INSERT INTO `quest_template_locale` VALUES (27556, 'ruRU', 'Оружейная смазка Гидвина', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27557, 'ruRU', 'Талисман Таренара', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27558, 'ruRU', 'Кукла Памелы', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27559, 'ruRU', 'Поручи Векс\'тула', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27560, 'ruRU', 'Дневник Аргуса', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27561, 'ruRU', 'Камень Римблата', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27562, 'ruRU', 'Шестеренка Бизила', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27563, 'ruRU', '[FLAG] Beezil\'s Flag', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27564, 'ruRU', 'Защита редута', 'Поговорите с Каленом на Гранатовом редуте.', 'Пришло сообщение от Калена – Сумеречные войска проникли на редут!$B$BНастало время, когда ты можешь заслужить его расположение!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27565, 'ruRU', 'В тюрьму', 'Отыщите Кевина Доусона.', 'Нам удалось проникнуть в тюрьму дворфов Черного Железа!$B$BТочнее, мы надеемся, что удалось.$B$BКевин Доусон отправился туда, чтобы лично поучаствовать в операции, и с тех пор от него ни слуху, ни духу. Ты же еще не собираешься отдавать концы? Вот и сходи туда да проверь, все ли с ним в порядке!$B$BОн должен находиться внутри зала в южном краю пещеры, что начинается впереди... хотя что-то мне подсказывает, что ему не удалось забраться так далеко.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27566, 'ruRU', 'Собрание в Запределье', 'Поговорите с Гаваном Серым Пером у Трона стихий в Награнде.', 'Приветствую, |3-6($c). Стихии все свирепствуют, усмирить их пока не в наших силах. У Трона стихий в Награнде собрались мудрейшие шаманы, чтобы общими усилиями найти способ исцелить нашу землю.$B$BОтправляйся к Трону стихий и поговори с Гаваном Серым Пером – у него наверняка найдется для тебя задание.', '', '', '', '', '', 'Поговорите с Гаваном Серым Пером у Трона стихий в Награнде.', 25549);
INSERT INTO `quest_template_locale` VALUES (27567, 'ruRU', 'Культ Сумеречного Молота?! О, нет!', '\"Дознайте\" правду у верховного дознавателя Герштан.', 'Сложно поверить, но в глубинах Черной горы скрываются сектанты из культа Сумеречного Молота! Не знаю, сколько именно адептов культа проникло в это место, но мне донесли, что верховный дознаватель Герштан находится в этом проходе среди прочих.$B$BМне неведомо, кого они тут допрашивают с пристрастием, но, может быть, тебе удастся выпытать это у Герштан?', '', 'Эмиссар Сумеречного Молота.', 'Верховный дознаватель Герштан', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27568, 'ruRU', 'Проникновение в Тенегорн', 'Поговорите с геологом Сеймуром.', 'Ты умеешь хранить секреты? Я хочу поделиться с тобой одной тайной.$B$BТут все ЧОКНУТЫЕ!$B$BТут повсюду гоблины, справа все заняли дворфы Черного Железа, а за этими воротами обитает гигантская огненная тварь! И вся эта живность теснится в маленькой пещерке!$B$BА ты что тут $gпозабыл:позабыла;?$B$BПонятно. Ты от Винки, не так ли? Он послал тебя переговорить с геологом Сеймуром, что находится за воротами направо? Ну, давай! Орелию до тебя нет никакого дела.$B$B...ВИНКИ, ТЫ МНЕ ЗА ЭТО ЗАПЛАТИШЬ!$B$B<Орелий рыдает.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27569, 'ruRU', 'Тактики из клана Черного Железа', 'Убейте генерала Кузню Гнева и повелителя големов Аргелмаха.', 'Генерал Кузня Гнева и повелитель големов Аргелмах ведут на нас свои войска вместе с големами. Если мы действительно хотим остановить их нападение, то для начала следует расправиться с этими военачальниками.$B$BВойди в эту дверь и открой замок Тенегорн, что отделяет Восточный гарнизон от Западного. Затем поднимайся по лестнице и, поднявшись, держись левой стороны пока не дойдешь до Западного гарнизона. Там ты и найдешь генерала и повелителя големов.$B$BБудь осторожен, они оба закаленные вояки. Если справишься с заданием, переговори с Майрой Светлое Крыло.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27571, 'ruRU', 'Трактир \"Угрюмый обжора\"', 'Подеритесь с Харли Чернопыхом, Штоппором Наливалсом и Риббли Крутипробом.', 'Кое-кто поговаривает, что \"Угрюмый обжора\" – залог успеха военных операций дворфов из клана Черного Железа. Уставшие воины восстанавливают там свои силы, чтобы снова отправиться на ратные подвиги. Думаю, мы могли бы серьезно насолить дворфам, внеся хаос в это заведение.$B$BЯ хочу, чтоб ты $gввязался:ввязалась; в перепалку с тремя завсегдатаями трактира. Повреди бочки, чтобы привлечь внимание Харли Чернопыха. Укради вещи, лежащие на столах, чтобы ввязаться в драку со Штоппором Наливалсом. Наконец, просто заговори с Риббли Крутипробом, и тот полезет к тебе с кулаками. Переговори с Орфусом, когда начистишь им рыльца.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27572, 'ruRU', 'Собрание в Запределье', 'Поговорите с Траллом у Трона стихий в Награнде.', 'Приветствую, |3-6($c). Стихии все свирепствуют, усмирить их пока не в наших силах. У Трона стихий в Награнде собрались мудрейшие шаманы, чтобы общими усилиями найти способ исцелить нашу землю.$B$BОтправляйся к Трону стихий и поговори с нашим вождем – у него наверняка найдется для тебя задание.', '', '', '', '', '', 'Поговорите с Траллом у Трона стихий в Награнде.', 25549);
INSERT INTO `quest_template_locale` VALUES (27573, 'ruRU', 'Узы Черного Железа', 'Убейте посла Огнехлыста и Рок\'рела.', 'Перед нами создание, известное как посол Огнехлыст. Рагнарос Повелитель Огня направил его к дворфам Черного Железа. За покоями посланника расположена Гробница Заклинателей, где обитают духи семи патриархов дворфов из Клана Черного Железа, призвавших Рагнароса в наш мир.$B$BПламенный лорд сулит смерть всему Азероту, если нам не удастся его остановить; и эти семь душ напрямую связаны с той властью, что Рагнарос имеет над дворфами Черного Железа. Расправься с ними и положи конец нечестивым узам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27574, 'ruRU', 'У меня отличная память на лица', 'Идите в Серебряный бор и отдайте полупереваренную голову лорду Годфри.', 'Вы нашли полупереваренную голову. Лорд Годфри настораживается, заметив ее. Возможно, вам следует отдать голову ему.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27575, 'ruRU', 'Из брюха зверя', 'Найдите туловище Демпси, конечности Демпси и внутренности Демпси.', 'Думаю, нам удастся его восстановить. И если мы это сделаем, то, возможно, он сообщит нам что-нибудь о Краули.$B$BМы должны убивать каждого кроколиска, которого встретим на этом болоте, пока не найдем остальные части Шона Демпси. Из брюха зверя возродится человек!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27576, 'ruRU', 'Разброд и шатание', 'Поговорите с Патчем в ущелье Драконьей Пасти.', 'Недавние события показали, что для обеспечения безопасности – и тем более для освобождения – Грим Батола одиночных вылазок недостаточно. Нам нужно действовать более напористо – необходимо нанести удар в самое сердце врага.$B$BМы отправим драконов к вашим командирам. Они уже разрабатывают план операции по штурму Грим Батола, так что тебе тоже стоит уделить этому внимание.$B$BНайди Патча – он находится на Тропе Драконьей Пасти, что к югу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27577, 'ruRU', 'Планы 7-го легиона', 'Найдите военные планы 7-го легиона.', 'Уничтожение Погребальных Костров, несомненно, даст нам преимущество в бою, но наша главная задача – нанести непоправимый урон войскам Альянса.$B$BК юго-западу отсюда, у Стены Седогрива, находится Лагерь 7-го легиона. Мы должны обыскать лагерь и найти планы битвы. Если нам это удастся, тогда мы будем знать обо всех перемещениях войск Альянса в Серебряном бору.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27578, 'ruRU', 'Плоды ожиданий Морганы', 'Ликвидируйте императора Даграна Тауриссана.', 'Император Дагран Тауриссан полностью держит город в своих руках, управляя им со своего трона. Чтобы остановить войска дворфов, нам нужно вначале покончить с их императором.$B$BДобраться до него непросто: вначале придется пройти мимо охраны, включая великана Магмуса. Старайся идти как можно быстрее; если тебя заметят раньше, чем выполнишь задание, то весь город встанет на защиту трона.$B$BЗапомни, что двери вблизи Лицея откроются лишь тогда, когда ты зажжешь светильники при помощи факелов, взятых у хранителей пламени. Удачи!', '', 'Пришел и его черед.', 'Император Дагран Тауриссан', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27579, 'ruRU', 'В тюрьму', 'Найдите Лекслорта.', 'Культ Сумеречного Молота тут трется неспроста. Мы не знаем почему, но Тал\'трак решил поведать тебе один наш секрет: у зала, где находится верховный дознаватель Герштан, прячется наш разбойник по имени Лекслорт, готовый прикончить ее, как только представится возможность.$B$BНо она слишком умна, чтобы дать ему этот шанс, так что тебе придется помочь нам. Ты же не откажешься? Иди, поговори с Лекслортом на этот счет. Я думаю, он не будет возражать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27580, 'ruRU', 'Семена раздора', 'Убейте генерала Марстоуна.', 'Войска Альянса закрепились в юго-западной части Серебряного бора – они называют это Лагерем 7-го легиона. Наша основная задача – посеять семена раздора среди вражеских солдат. Поэтому мы должны стремительно ворваться в лагерь и убить командира, генерала Марстоуна. Его смерть не остановит продвижение войск Альянса, но подорвет боевой дух.', '', 'Генерал Марстон: шаман клана Громового Молота', 'Генерал Марстон', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27581, 'ruRU', 'Культ Сумеречного Молота?! О, нет!', 'Убейте верховного дознавателя Герштан.', 'Герштан слишком хорошо охраняют, и она не так глупа, чтобы покинуть свое место, так что мне ее не прикончить.$B$BА вот тебе это по рукам.$B$BЯ тебя отблагодарю кое-чем, что я отнял у охранника.', '', 'Выпытайте правду у дознавателя.', 'Верховный дознаватель Герштан', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27582, 'ruRU', 'Проникновение в Тенегорн', 'Поговорите с Разал\'мечом.', 'Боюсь, что мы бьемся напрасно. С дворфами из клана Черного Железа и так не совладать, так на их стороне еще и элементали, дающие им значительное военное преимущество.$B$BЯ хочу, чтобы ты $gпроник:проникла; в город дворфов и $gуничтожил:уничтожила; как можно больше их ключевых руководителей. Надеюсь, что это внесет смуту в их войска и переломит ход боевых действий. Обратись к Разал\'мечу за дополнительными указаниями. Он стоит справа за воротами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27583, 'ruRU', 'Северный фланг', 'Поговорите с Гралоком в Скользкой бухте на Сумеречном нагорье.', 'Я приказала создать оборонительный периметр на северном берегу, в Скользкой бухте. Разведчики сообщают, что наги пытаются выбраться на берег именно там.$B$BКомандует операцией Гралок. Явись к нему и помоги зачистить берег!', '', '', '', '', '', 'Поговорите с Гралоком в Скользкой бухте на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27584, 'ruRU', 'Кровь и пена', 'Уничтожайте налетчиков из клана Черной Чешуи и прелестниц из клана Черной Чешуи, пока не убьете 15 любых из них.', 'Эти проклятые наги собираются подняться вверх по реке и прийти на помощь защитникам Сумеречного бастиона. Но мы ОТОРВЕМ их рыбьи головы и СЛОМАЕМ им хребты.$B$B<Гралок втыкает свой палаш в землю.>$B$BУбей наг Черной Чешуи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27585, 'ruRU', '109-е подразделение', 'Убейте генерала Кузню Гнева и повелителя големов Аргелмаха.', 'Генерал Кузня Гнева и повелитель големов Аргелмах повинны в чудовищной резне, когда было уничтожено 109-е подразделение Каргатского экспедиционного корпуса. В этом подразделении было много стоящих троллей и орков, среди которых были и мои друзья.$B$BИтак, $gюный:юная:r; |3-6($r), настало время отплатить за гибель наших собратьев.$B$BОткрой замок Тенегорна. Затем поднимайся по лестнице и, поднявшись, держись левой стороны пока не дойдешь до Западного гарнизона. Расквитайся с Кузней Гнева и Аргелмахом, не яви к ним ни капли сострадания!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27586, 'ruRU', 'Ракушки на морском берегу', 'Соберите 8 невзорвавшихся снарядов мортиры на берегу Скользкой бухты.', 'Когда наш корабль взорвался над портом Драконьей Пасти, я лично вытащил эти мортиры из-под обломков. Но у нас очень мало боеприпасов!$B$BИ раз уж ты все равно бегаешь по берегу, то сделай милость, набери неразорвавшихся снарядов.$B$BЭти снаряды самые лучшие – ведь ты не знаешь КОГДА ИМЕННО они взорвутся. Великолепный сюрприз для противника!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27587, 'ruRU', 'Зловещая вкуснятина', 'Соберите 6 неповрежденных хвостов береговых макрур.', 'Знаешь, мне пригодилась бы твоя помощь.$B$BДело в том, что помимо торговли оружием я тут в Веслотопи пытаюсь организовать кое-какие развлечения. Но в водоемах на севере водятся некие \"макруры\", которым не по душе наши пляжные вечеринки.$B$BК лешему их! Я не позволю креветкам-переросткам мною помыкать. Более того, собираюсь нажиться на них! Принеси мне несколько хвостов макрур, и мы превратим неприятности в деньги.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27588, 'ruRU', 'Сигнал к атаке', 'Подайте сигнал к атаке с вершины одной из башен Сумеречных врат.', 'Теперь, когда вам удалось выманить Дробителя Черепов Горобраза из Сумеречных врат, пора подать сигнал для наступления войск!', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27589, 'ruRU', 'Трактир \"Угрюмый обжора\"', 'Подеритесь с Харли Чернопыхом, Штоппором Наливалсом и Риббли Крутипробом.', 'Все посетители трактира \"Угрюмый обжора\" согреваются спиртным, так что они постоянно на взводе. Думаю, мы могли бы серьезно насолить дворфам, внеся хаос в это заведение.$B$BЯ хочу, чтоб ты $gввязался:ввязалась; в перепалку с тремя завсегдатаями бара. Повреди бочки, чтобы привлечь внимание Харли Чернопыха. Укради вещи, лежащие на столах, чтобы ввязаться в драку со Штоппором Наливалсом. Наконец, просто заговори с Риббли Крутипробом, и тот полезет к тебе с кулаками. Переговори с Громосердом, когда начистишь им мордахи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27591, 'ruRU', 'Узы Черного Железа', 'Расправьтесь с послом Огнехлыстом и Рок\'релом.', 'В этом зале находится посол Огнехлыст. Это посланник Рагнароса Повелителя Огня в клане Черного Железа. За его покоями расположена Гробница Заклинателей, где обитают духи семи патриархов дворфов из Клана Черного Железа, призвавших Рагнароса в наш мир.$B$BПовелитель Огня сулит смерть всему Азероту, если нам не удастся его остановить; и эти семь душ напрямую связаны с той властью, что Рагнарос имеет над дворфами Черного Железа. Расправься с ними и положи конец нечестивым узам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27592, 'ruRU', 'Прохладительные напитки', 'Принесите 10 бутылок \"Льда Сереблекса\", украденного иловыми крабами.', 'Как оно, \"$gбратан:сестренка;\"? Прикинь, у нас в самом разгаре спонтанной вечеринки приключилась катастрофа!$B$BУ меня был целый ящик \"Льда Сереблекса\" – любимого напитка самого барона. А эти крабы взяли его и стибрили! Никогда не видел, чтобы они прикладывались к бутылке, но они уволокли этот ящик прямо под воду. Нам нужен супергерой, который бы смог вернуть наше любимое марочное бухло!$B$B<Броно многозначительно на вас смотрит.>$B$BЯ вообще-то о тебе говорю, $gбратан:сестренка;!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27593, 'ruRU', 'Возрождение Коргатского экспедиционного корпуса', 'Ликвидируйте императора Даграна Тауриссана.', 'Император Дагран Тауриссан полностью держит город в своих руках, управляя им со своего трона. Чтобы остановить войска дворфов, нам нужно вначале покончить с их императором.$B$BДобраться до него непросто: вначале придется пройти мимо охраны, включая великана Магмуса. Старайся идти как можно быстрее; если тебя заметят раньше, чем выполнишь задание, то весь город встанет на защиту трона.$B$BЗапомни, что двери вблизи Лицея откроются лишь тогда, когда ты зажжешь светильники при помощи факелов, взятых у хранителей пламени. Удачи!', '', 'Пришел и его черед.', 'Император Дагран Тауриссан', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27594, 'ruRU', 'Секретная служба Ее величества', 'Схватите командира Лорну Краули и отведите ее к леди Сильване Ветрокрылой на Рубеж Отрекшихся в Серебряном бору.', 'Лорна Краули, дочь лорда Дария Краули, сейчас находится рядом со Стеной Седогрива, в лагере Освободительного фронта Гилнеаса. $B$BНаша основная задача – проникнуть в лагерь и схватить Лорну. Темная Госпожа полагает, что Лорна станет козырной картой на переговорах с Краули. Лично я считаю, что нам нужно ее убить и превратить в Отрекшуюся, но приказы Темной Госпожи обсуждению не подлежат.$B$BМы должны поторопиться, пока не прибыли основные силы Альянса.', '', 'Наш козырь на переговорах', 'Командир Лорна Краули', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27595, 'ruRU', 'Пророк Хадасси', 'Разыщите пророка Хадасси в Орсисе.', 'Пророк Хадасси – старейший и мудрейший член племени Орсиса.$B$BОн пропал без вести, меж тем его доброе здравие – наша первейшая забота.$B$BИди в Орсис и найди его. Прислужники Ал\'акира дорого заплатят, если с Хадасси что-то случилось...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27596, 'ruRU', 'Сердце горы', 'Добудьте \"Сердце Горы\".', 'Долгие годы я искал один самоцвет. Он называется \"Сердце Горы\", а сам камень размером с твой кулак! Дворфы из клана Черного Железа заперли его в своем хранилище и ни в какую не хотят мне его продать.$B$BТак что придется прибегнуть к грубой силе.$B$BПробейся в Черное Хранилище рядом с Залом Ремесла, взломай секретный сейф и достань оттуда самоцвет. Для этого придется расправиться со сторожем Хваткой Смерти, который не появится снова до тех пор, пока ты не открыл все ларцы с сокровищами, стоящие в хранилище!$B$BУдачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27597, 'ruRU', 'Безумный Ларри', 'Разыщите Безумного Ларри на юго-востоке от Веслотопи.', 'Я смотрю, ты врубаешься, $n. Ты мне спину почешешь – я тебе. Ну, точнее, не тебе, а всей вашей армии, и всего капельку тщательнее, чем вражеской! Ну, не сложно, так ведь?$B$BТак что я хочу сказать – спин ваших много. Поэтому придется тебе поскрести мою еще, и не раз. Тот, кто украл те мины, наверняка метил в наших парней на восточном берегу.$B$BОтправляйся в наш лагерь на юго-востоке и найди Безумного Ларри; он тебя введет в курс дел.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27598, 'ruRU', 'Взять за жабры', 'Убейте 7 жаблинов-ловцов.', 'Жаблины!$B$B<Ларри в молчании уставился на вас.>$B$BНикогда не $gвидел:видела; их, что ли? Они чокнутые! Еще больше, чем я! Я взрываю все подряд за деньги, но эти ребята просто ПСИХИ!$B$BУж не знаю, откуда они, но похожи они на мерзких рыбогоблинов! Жабры, все такое! Они перебили всех моих ребят на берегу и захватили наш грузовой корабль!$B$BВыручай! Они к востоку отсюда. Пойди и избавься от этих жаблинов!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27599, 'ruRU', 'Все с собой не заберешь', 'Соберите 6 кошелей мертвых каперов Веслотопи.', 'Вся моя команда, которой, как видишь, в лагере нет, МЕРТВА! Это были добрые гоблины, но что еще хуже, так это то, что они все еще там, под водой! Это ТРАГЕДИЯ!$B$BВ смысле, печально то, что их пожитки все еще с ними! Страшно подумать: все эти материалы и монеты лежат там, бедненькие, в воде...$B$BВот что! Окажи мне услугу! Раз уж ты пойдешь сражаться с жаблинами, собери заодно и кошели моих матросов!$B$BДа ладно тебе, все равно им они ни к чему! Больше здорового прагматизма!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27600, 'ruRU', 'С шумом и гамом', 'Поговорите с Чудиком Джерри, чтобы попасть на корабль, затем разыщите все три ценных груза Безумного Ларри.', 'Наш торговый фрегат все еще в море и кишит жаблинами! А-А-А!$B$BПардон. И все же! Нам нужно как-то отправить тебя туда за нашим хабаром. На корабле остался ценный груз! ЦЕННЫЙ! КАК МОЕ ОТЧЕСТВО!$B$BНа твое счастье, у меня родился отличный план! Как выйдешь из лагеря, иди вдоль северной стены... мой сынишка Джерри забросит тебя туда из нашей пушки! Если, конечно, он практиковался, а не баклуши бил!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27601, 'ruRU', 'Стереть в порошок', 'Отправляйтесь вместе с леди Сильваной Ветрокрылой на поле боя и разгромите войска Альянса!', 'Наши армии сошлись. Войска Краули отступают – и они еще не знают, что стало с Лорной Краули. Мы встретимся с Краули на поле боя, и я изложу ему условия капитуляции. Либо они будут приняты, либо мы перебьем их всех и разрушим их города.$B$BТы мой самый преданный солдат, и поэтому во время переговоров будешь рядом со мной. Только дай мне знать, и мы отправимся в путь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27602, 'ruRU', 'Последние слова пророка', 'Разыщите священный ларец.', 'Мы все... связаны клятвой... жизнью своей защищать скипетр Орсиса.$B$BПослушай, |3-6($c), мне осталось... недолго.$B$BНайди священный ларец... на южной окраине города.$B$BНе дай им... захватить его...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27603, 'ruRU', 'Закрытые врата', 'Убейте Бейл\'гора.', 'В конце зала, возведенного дворфами Черного Железа, стоят массивные врата, подобные тем, что закрывают вход в Тенегорн с другой стороны. Однако мы понятия не имеем, что скрывается за ними!$B$BНам лишь известно, что врата усиленно патрулируют дворфы из клана Ярости Горна вместе с великаном Бейл\'гором. Просто избавься от них и попробуй открыть ворота!$B$BСтрашно даже подумать о том, что находится за ними... может, это еще одна часть города, о которой мы даже не ведали! А может, и вообще ничего! Точно не знает никто.$B$BМне хочется верить, что там что-то есть...', '', 'Что за этими вратами?', 'Бейл\'Гор', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27604, 'ruRU', 'Джаммал\'ан Пророк', 'Отсеките голову пророка Джаммал\'ана.', 'Пророк Джаммал\'ан, вождь троллей Атал\'ай и Хаккари, получил небольшую порцию крови Хаккара Свежевателя Душ. Теперь они вводят эту кровь зеленым драконам, и в их телах аккумулируется новая кровь, пригодная для призыва Хаккара в наш мир.$B$BМы не можем этого допустить. Прикончи Джаммал\'ана и его жрецов, пока им не удалось завершить начатое!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27605, 'ruRU', 'Эраникус', 'Прикончите Эраникуса.', 'Кровь Хаккара, которую Атал\'ай вводят зеленым драконам, повлияла на драконов самым губительным образом. Драконы, которые некогда были тюремщиками Атал\'ай, под воздействием этой крови превратились в кошмарные создания.$B$BЭраникусу, первому возлюбленному Изеры и главному смотрителю храма, ввели больше всего крови, и он изменился до неузнаваемости. Когда расправишься с Джаммал\'аном, найди Эраникуса и покончи с ним.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27606, 'ruRU', 'Взорви его!', 'Подуйте в раковину Хет\'Жатара, находясь рядом со знаменем Хет\'Жатара. Убейте Повелителя Глубин Хет\'Жатара. Сделать это будет легче, если вы заманите его под огонь мортир.', '$n, идем на рыбалку! Мортиры готовы к бою, так что теперь мы сможем уничтожить командира захватчиков.$B$BКастой воинов Черной Чешуи правит Повелитель глубин Хет\'Жатар. Иди на северо-восток, к его знаменам. Когда прибудешь на место, протруби вот в эту раковину – это все равно что собачий свисток. Только для рыб.$B$BКогда появится Хет\'Жатар, я прикажу вдарить по нему из мортир. Ты увидишь цели, по которым будут стрелять орудия.$B$BЗамани Хет\'Жатара под огонь мортир и вбей его в землю!', '', 'Убей Хет\'Жатара! А мы поддержим тебя огнем наших пушек.', 'Повелитель глубин Хет\'Жатар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27607, 'ruRU', 'Южный фланг', 'Поговорите с Рок\'таром на Сумеречном берегу на Сумеречном нагорье.', 'В результате заключения договора с Ордой мой народ вступит в открытое противостояние с Альянсом.$B$BОни. У нас. Получат.$B$BУже сейчас войска Альянса маршируют по полуострову, угрожая порту Драконьей Пасти.$B$BОтправляйся на юг и найди Рок\'тара – кажется, он устроил свой командный пункт на одном из разбитых кораблей. Позаботься о том, чтобы побережье осталось в наших руках.', '', '', '', '', '', 'Поговорите с Рок\'таром на Сумеречном берегу на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27608, 'ruRU', 'Без головы хорошо, а с четырьмя – лучше', 'Добудьте четыре головы За\'брокса и Библи\'фода.', 'Теперь, когда атака на Сумеречные врата началась, осталось разобраться с За\'броксом и Библи\'фодом, учениками Чо\'Галла.$B$BПо данным разведки, они находятся в Пещере учеников, небольшом логове, принадлежащем ограм, которое расположено на юго-западе Сумеречных врат.$B$BИди туда и убей их.', '', '', '', '', '', 'Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Кассием Белым.', 19865);
INSERT INTO `quest_template_locale` VALUES (27610, 'ruRU', 'Разведка на побережье', 'Проведите разведку на Сумеречном берегу в окрестностях контрольного пункта берегового плацдарма. Вам не нужно его захватывать, но если вы это сделаете, то ваша сторона получит преимущество в бою, а вы – флаг PvP.', 'Если Альянс овладеет этим полуостровом, его войска будут угрожать порту Драконьей Пасти. Мы не должны этого допустить.$B$BНа юге есть небольшой холм, с которого прекрасно просматривается все побережье. Тот, кто завладеет холмом, получит преимущество в бою!$B$BМне нужно знать, что сейчас там происходит. Проведи разведку, двигаясь к контрольному пункту берегового плацдарма – он отмечен огромным флагом. Затем возвращайся ко мне.$B$BСам пункт захватывать не нужно – ну, разве что тебе хочется подраться.', 'Разведка окрестностей контрольного пункта берегового плацдарма проведена', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27611, 'ruRU', 'Кровь на песке', 'Убейте 12 пехотинцев Высокого берега на Сумеречном берегу на Сумеречном нагорье.', 'Наша цель на Сумеречном нагорье – взятие Сумеречного бастиона. Однако Альянс решил оказать сопротивление.$B$BНу что ж, значит, будем воевать!$B$BУбивай их морских пехотинцев, пока остальные не усвоят урок.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27612, 'ruRU', 'Триумф воли', 'Зайдите в аббатство Длани Тира и откройте Серебряные порталы в библиотечном крыле и оружейной.', 'Несколько наших людей не прошли через порталы, которые должны были открыться прямо в аббатстве. И поэтому мне снова нужна твоя помощь... ведь я знаю, что ты можешь действовать скрытно и при этом не боишься вступить в бой.$B$BУ этого аббатства два крыла: в одном библиотека, а во втором – оружейная. В каждом крыле портал.$B$BОткрой портал этим ключом; тогда оставшиеся воины смогут попасть в аббатство.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27613, 'ruRU', 'Убийца', 'Убейте Рохана Убийцу на колокольне аббатства в Длани Тира.', 'История Алого ордена довольно трагична, хотя в чем-то и забавна. Когда-то Орден вел людей на войну с нежитью. А сейчас его рыцари сами напоминают оживших мертвецов, которых раньше истребляли. Что превратило их в нежить, мы не знаем, но от этого они не становятся менее опасными.$B$BИ одним из самых опасных из них является убийца по имени Рохан. По данным наших агентов, сейчас он находится на колокольне этого аббатства. Найди и убей его, $n. И постарайся при этом не погибнуть.', '', 'Закоренелый разбойник, беспринципный негодяй.', 'Рохан Убийца', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27614, 'ruRU', 'Спасение артефактов', 'Добудьте багрового кабанчика, бусы Лианны, саван Утера и печать Гавинрада.', 'Эта битва была выиграна еще до того, как началась. Исход боя давно решен – осталось только со вкусом довершить разгром.$b$bВ этой казарме жалкие прихвостни Алого ордена хранят свои бесценные артефакты. Некоторые из этих предметов священны, и нежить не смеет к ним прикоснуться, поэтому держит сокровища в сундуках, спрятав от всего остального мира.$b$bНайди эти артефакты и принеси мне. Они должны принадлежать Серебряному Авангарду. Должны попасть в руки праведников.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27615, 'ruRU', 'Обрушивающий гнев', 'Убейте Матеуса Обрушивающего Гнев.', 'В подземельях этой казармы находится один из наиболее злобных членов Алого ордена – Матеус Обрушивающий Гнев. Его мерзкий характер отлично сочетается с обликом нежити.$B$BБыл бы я помоложе, сам бы его проткнул. Но, к сожалению, мне приходится сидеть в тылу и командовать войсками. Так что я предоставляю это удовольствие тебе.', '', 'Жалкая, черная душонка.', 'Матеус Обрушивающий Гнев', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27616, 'ruRU', 'Охотник', 'Убейте Охотника Леопольда.', 'Стрелы и пули защитников уже унесли жизни полдюжины наших людей. Я не видел лица стрелков, но мне это и не нужно. Известно, кто укрылся там, наверху.$B$BЭто Леопольд.$B$BДа, все верно, наших воинов убивает один человек. Один. И, насколько я понимаю, ты здесь тоже в одиночестве.$B$BДумаю, это будет честный бой.', '', 'Умеет обращаться с любым стрелковым оружием.', 'Охотник Леопольд', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27617, 'ruRU', 'Очищение', 'Явитесь с докладом к верховному магу Анжеле Досантос в Длань Тира в Восточных Чумных землях.', 'Ты чувствуешь это? Здание уже начало очищаться от порчи!$B$BСвятое здание хочет быть святым, а Рохан и прочее отребье Алого ордена только мешают ему.$B$BТеперь, после захвата аббатства, мы еще на шаг приблизились к освобождению Длани Тира. Сообщи о результатах нашей операции Анжеле. Сейчас она, наверное, где-то в центре города, руководит штурмом собора.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27618, 'ruRU', 'Победа Серебряных', 'Явитесь с докладом к верховному магу Анжеле Досантос в Длань Тира в Восточных Чумных землях.', 'Я думаю, мы нанесли достаточный урон казарме, и можно считать, что одержали победу. Командир, охотник, чернокнижник... все они убиты... не говоря уже о том, что мы захватили артефакты. Точнее... ТЕБЕ удалось их добыть.$B$BСобор пока стоит, но скоро мы это изменим. Поговори с верховным магом Анжелой Досантос – она в центральном дворе. Судьба собора – в ее руках.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27619, 'ruRU', 'Командир', 'Убейте командира Маржан из Алого ордена.', 'Командир Маржан из Алого ордена хитра и умна, и ради победы она готова на все. Но самое главное – то, что она никогда не предаст Алый орден.$B$BДумаю, ты найдешь ее в центральной комнате казарм, под алым знаменем. Она будет сражаться до тех пор, пока не одержит победу или не умрет.$B$BПозаботься о том, чтобы она умерла.', '', 'Ей нечего терять.', 'Командир Алого ордена Маржан', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27620, 'ruRU', 'Словно крысы', 'Убейте командира рыцарей Валделмара.', 'Хорошо, что Элигор и Корфакс позволили мне присоединиться к общему веселью. Мне чуть драться с ними не пришлось, чтобы они не бросились в лобовую атаку.$B$BВедь, в конце концов, это же ТВОЯ задача.$B$BПеред нами стоит собор, последний бастион Алого ордена. А в нем – командир рыцарей Валделмар, опутавший Длань Тира паутиной лжи.$B$BДеться ему некуда, и пощады мы ему не дадим. Жалкие остатки Алого ордена погибнут здесь. Убей его.', '', 'О, как низко пали великие герои.', 'Командир рыцарей Валделмар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27621, 'ruRU', 'Дозор Огнебородов', 'Найдите Кигана Огнеборода в Дозоре Огнебородов на Сумеречном нагорье.', 'Я собирался в Дозор Огнебородов, когда подстрелили мою птицу.$B$BСумеречный Молот пошел в наступление по всему нагорью. Иногда их здания вырастали из-под земли прямо в центре наших деревень. Это был кошмар!$B$BИ в этом хаосе Огнебород один из немногих сохранял хладнокровие. Сейчас он пытается собрать эскадрилью грифонов из тех, кто остался в живых.$B$BЕсли ты хочешь, чтобы Громовой Молот стал союзником Альянса, для начала выручи Огнеборода. Он находится к западу отсюда.', '', '', '', '', '', 'Найдите Кигана Огнеборода в Дозоре Огнебородов на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27622, 'ruRU', 'Большой, улучшенный крошшер', 'Найдите на Сумеречном берегу сломанный крошшер и с его помощью вызовите эксперта по металлолому из картеля Трюмных Вод. Защищайте крошшер, пока его не приведут в рабочее состояние.', '$n, я собираюсь создать улучшенный крошшер. Но мои инженеры не могут идти в зону боевых действий в одиночку.$B$BНайди сломанный крошшер на Сумеречном берегу и с его помощью подай сигнал: тогда к тебе присоединится один из моих экспертов. Затем защищай крошшер, пока мы будем им заниматься.$B$BАльянс даже ничего не сообразит! По крайней мере, пока не начнется моя маркетинговая кампания!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27623, 'ruRU', 'Колоссы-стражи', 'Извлеките камень луны и камень солнца из колоссов-стражей.', 'Ларец со скипетром, судя по всему, опечатан с помощью магии, так что его даже с места не сдвинуть.$B$BНа табличке над сундуком изображены две гигантские статуи с гнездами для камней – в форме звезды и полумесяца.$B$BСудя по рисунку, статуи сторожат пирамиды вроде тех, что вы видели снаружи.$B$BВозможно, стоит выйти и как следует осмотреться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27624, 'ruRU', 'Упавшие статуи', 'Соберите четыре сферы: сферу утренней звезды, сферу вечерней звезды, сферу северной звезды и сферу падающей звезды.', 'Ну, вот. Даже не пришлось напрягаться.$B$BСтатуи держались на честном слове. Посильнее ткнул пальцем – они и попадали.$B$BВ общем, я их повалил, а ты давай разгребай обломки.$B$BМне что-то подсказывает, мы уже близки к разгадке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27625, 'ruRU', 'Защита Сторожки Кель\'Данил', 'Убейте 16 ловчих смерти – захватчиков у Сторожки Кель\'Данил.', 'Здесь нежить! Отрекшиеся! Они подходят все ближе и ближе и вот-вот нападут на нас... эти отвратительные существа!$b$bНаходящиеся на моем попечении юные дренеи отлично показали себя в битве с эльфами Высокодолья. Они могут себя защитить, но им нужна помощь!$b$bПожалуйста, $n, помоги им! Помоги отбросить Отрекшихся!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27626, 'ruRU', 'Документы Высокодолья', 'Найдите отчет Высокодолья, записи Высокодолья и заметки Высокодолья.', 'В течение долгих лет эльфы Высокодолья вели подробный архив записей. Смерти, рождения, времена года... а кроме этого важнейшие разведданные и способы связи с остальными членами Альянса.$b$bВсе документы будут разбросаны в беспорядке. Если они попадут в руки Отрекшихся, многие жизни подвергнутся риску! Прошу тебя, ты $gдолжен:должна; спасти эти документы, прежде чем их не захватила Орда...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27627, 'ruRU', 'Разноцветные тараканы', 'Убейте 5 аметистовых скарабеев, 5 сапфировых скарабеев, 5 бирюзовых скарабеев и 5 изумрудных скарабеев.', 'Из обломков полезли жуки-скарабеи. Очевидно, у них были гнезда в статуях.$B$BВам почему-то не хочется, чтобы эти \"разноцветные тараканы\" расползались по комнате, и вы решаете перебить всех скарабеев.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27628, 'ruRU', 'Доклад Фаорису', 'Поговорите с королем Фаорисом в Рамкахене в Ульдуме.', 'Поспешим, $n. Нужно все рассказать моему брату, королю.$B$BОн хочет остановить войну с Ал\'акиром и неферсетами. Наивно полагает, что конфликт можно разрешить дипломатическим путем...$B$BНадеюсь, когда он узнает, что здесь произошло, он передумает.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27629, 'ruRU', 'Голос визиря', 'Поговорите с визирем Танотепом в Полях Ахенет в Ульдуме.', 'Убедить визиря Танотепа перечить моему братцу будет ой как непросто... Его собственное положение зиждется на том, что он беспрекословно исполняет волю Фаориса.$B$BЯ мало преуспел, настаивая на открытой войне с Неферсетом.$B$BТем не менее, тебе следует с ним поговорить. Возможно, к мнению стороннего наблюдателя он и прислушается.$B$BТы найдешь визиря в Полях Ахенет, он отправился туда с деловым визитом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27630, 'ruRU', 'Голос верховного жреца', 'Поговорите с верховным жрецом Аметом внутри запруды Вир\'наал в Ульдуме.', 'Верховный жрец Амет – единственный, на кого мы не можем повлиять.$B$BОн проголосует в соответствии с результатами своей ворожбы, и переубедить его мы вряд ли сможем.$B$BСкажем так, либо он проголосует \"за\", либо \"против\", шансы равны.$B$BЕдинственное – как только произошло падение барьеров вокруг Ульдума, у него с предвидением стало из рук вон плохо.$B$BОн не согласится голосовать до тех пор, пока не восстановит свои способности ворожить.$B$BПоговори с ним и выясни, чем ему можно помочь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27631, 'ruRU', 'Голос главнокомандующего', 'Поговорите с главнокомандующим Камзесом на заставе рамкахенов в Ульдуме.', 'Если мы хотим принять резолюцию о войне, решение Верховного совета должно быть единогласным.$B$BУверен, главнокомандующий Камзес согласится поддержать нас, когда узнает о том, что произошло в Орсисе.$B$BПожалуйста, поговори с ним на заставе рамкахенов и убедись, что он с нами. А мне нужно заняться подготовкой другого плана на тот случай, если наш не сработает.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27632, 'ruRU', 'Сын Танотепа', 'Отберите карту дельты Вир\'наала у стражника Неферсета.', 'Всю свою жизнь я посвятил служению королю. Этот долг для меня превыше всего на свете... кроме заботы о моем сыне.$B$BТахета схватили часовые Неферсета.$B$BОни заявляют, будто мой сын вторгся в их владения. Фаорис ведет переговоры о его освобождении... однако я опасаюсь худшего.$B$BЕсли ты разыщешь моего сына, я поддержу вас.$B$BНе знаю, где они держат пленных, но я видел, как стражи сверялись с картой, собираясь идти через густую растительность.', '', 'У стражников Неферсета может быть при себе карта, где сказано, куда увели Тахета.', 'Стражник Неферсета', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27633, 'ruRU', 'Бог Крови Хаккар', 'Уничтожьте Аватару Хаккара.', 'Хаккар... одно упоминание имени Свежевателя Душ заставит многих бежать без оглядки. В Святилище Падшего Бога Атал\'ай нашли его останки и хотят вернуть Хаккара к жизни. Его отпрыски уже начали появляться в округе.$B$BОтнеси это яйцо в святилище – тогда воскрешение Хаккара начнется преждевременно. Не медли, $n. Убей его Аватару, как только она появится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27635, 'ruRU', 'Санобработка', 'Пройдите процедуру очищения от радиоактивных загрязнений в Санитрон-500.', 'Ты много времени $gпровел:провела; в Гномрегане, $n, и потрясающе, что тебе удалось выжить! Нужно вытащить тебя отсюда.$b$bПрежде, чем мы сможем переправить тебя на поверхность, чтобы ты $gприсоединился:присоединилась; к остальным гномам, ты $gдолжен:должна; пройти через процедуру очищения от радиоактивных загрязнений. Просто зайди в комнату, что передо мной, и заберись в Санитрон-500. Он сделает все необходимое! Даже больно не будет... почти.$b$bКогда пройдешь процедуру, найди техника Бреггла, он подберет тебе одежду.', 'Завершите процедуру очищения от радиоактивных загрязнений', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27636, 'ruRU', 'Только ты и Матиас', 'Найдите мастера Матиаса Шоу в Сумеречной крепости в Сумеречном нагорье.', 'Агенты ШРУ мертвы. Теперь пора разыскать мастера Матиаса Шоу.$B$BХорошо, что командир отряда сказал, где его можно найти.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27637, 'ruRU', 'Только ты и Матиас', 'Найдите мастера Матиаса Шоу в Сумеречной крепости в Сумеречном нагорье.', 'Это серьезный удар по нашим планам. Будь проклят этот Чо\'Галл!$B$BХорошо, что командир отряда подсказал тебе, где искать мастера Шоу.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27638, 'ruRU', 'Только ты и Гарона', 'Найдите Гарону Полуорчиху в Сумеречной крепости в Сумеречном нагорье.', 'Кор\'кроны мертвы. Теперь пора разыскать Гарону Полуорчиху.$B$BХорошо, что у вас есть подсказка командира отряда, где ее можно найти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27640, 'ruRU', 'Дунвальды не умирают', 'Найдите в развалинах Дунвальда оставшихся в живых членов клана Дунвальд.', 'Насколько я понимаю, ты хочешь, чтобы кланы Громового Молота вступили в войну на стороне Альянса. Похоже, ты не понимаешь, во что ввязываешься.$B$BНу, а если готовишься к бою, то есть один клан, который тебе точно нужно привлечь на свою сторону. Иди на юго-запад, на другую сторону Горнила Крови, там находятся развалины Дунвальда. Селение разрушено почти до основания, но Дунвальдов это не остановит. Остается лишь найти их...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27641, 'ruRU', 'По пути к родственникам', 'Убейте 20 приспешников Сумеречного Молота на земле Дунвальдов.', 'Эй, $gпарень:девочка;! Я уверен, что Кили уже встревожила тебя рассказом про наших братьев, но они сами о себе позаботятся. Рано или поздно они вернутся сюда.$B$BНо раз уж ты собираешься встретиться с семьей, то, может, окажешь мне одну услугу?.. На землях Дунвальдов до сих пор полно слуг Сумеречного Молота. Я буду в большом долгу перед тобой, если ты напомнишь им о том, что здесь им не рады.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27642, 'ruRU', 'Разбирая обломки', 'Найдите 12 тел погибших Дунвальдов.', 'Проклятые слуги Сумеречного Молота разоряли наш город с удивительным упорством. И, возможно, только нам с братьями удалось хоть как-то их сдержать. Но это нужно проверить.$B$BКогда будешь осматривать руины, ищи тела моих родичей. Я хочу знать, выжил ли кто-нибудь... или, может, кому-то удалось бежать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27643, 'ruRU', 'Доннели Дунвальд', 'Найдите Доннели Дунвальда.', 'Значит, ты ищешь нас. Ну, а я разыскиваю братьев. Похоже, у нас общие интересы.$B$BДоннели – это наш старший. Но хоть рост у него соответствующий, то мозги точно нет. Обычно он околачивается в руинах на севере. Может, ты его разыщешь? Мне будет очень тепло на душе, если я буду знать, что он в безопасности.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27644, 'ruRU', 'Эоин Дунвальд', 'Найдите Эоина Дунвальда.', 'Эоин – это один из близнецов. Очень любит выпить. Скорее всего, он где-то рядом со старым колодцем – в соседнем здании хранились запасы эля.$B$BПожалуйста, попроси его навестить сестру, которая о нем беспокоится. Если доберешься до эля раньше, чем он, то долго убеждать братца не придется.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27645, 'ruRU', 'Кайден Дунвальд', 'Разыщите Кайдена Дунвальда.', 'Кайден – это второй близнец. Он тоже вечно томится жаждой, но отнюдь не по элю. В некотором смысле он был только рад, когда сюда заявились служители культа Сумеречного Молота – нашел выход своей агрессивности. Оно, может, и правильно. Надо же парню куда-то девать энергию!$B$BДумаю, его надо искать у торговых рядов, что неподалеку от старой кузницы. Он и раньше-то вечно там ошивался, а теперь, когда пришли эти сектанты, он там вообще поселился.$B$BНайди его и приведи ко мне. Желательно целым и невредимым.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27646, 'ruRU', 'Где ты, Клювик?', 'Помогите Доннелли найти Клювика на Складах Дунвальда.', 'Вот ведь какая беда... потерял своего грифона... Клювик! Клювик, ты где?!$B$BПоможешь найти моего грифончика? Он где-то в сарае, я знаю. Где ж ему еще быть?!$B$BКлювик?! Где ты?$B$BНадеюсь, с ним все хорошо.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27647, 'ruRU', 'Чем бы промочить горло', 'Обыщите подвал, где, по мнению Эоина Дунвальда, припрятан бочонок с выпивкой.', 'Слушай, $gдружище:милая;, либо ты мне помогаешь найти чем бы промочить горло, либо мы с тобой нежно простимся.$B$BМожет быть, сходишь на старый склад и заглянешь в подвал? Есть у меня подозрение, что старина счетовод очень даже позволял себе пропустить за работой стаканчик-другой. Наверняка у него там в подвале припрятан бочонок.$B$BЕсли чего-то найдешь, сразу же рысью – ко мне. Прямо вот сразу... не мешкая. Это срочно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27648, 'ruRU', 'И вновь за дело', 'Отправляйтесь вместе с Кайденом Дунвальдом туда, где вас явно поджидает засада.', 'Отлично, отлично. Так ты, стало быть, маешься от безделья. Я найду тебе дело.$B$BКогда будешь $gготов:готова;, скажи – и пойдем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27649, 'ruRU', 'Чем больше, тем лучше', 'Соберите 6 бочонков эля Громового Молота.', 'Слушай, $gприятель:милая;, раз мы такие большие друзья, может быть, сделаешь доброе дело? Уважишь старого дворфа, а?$B$BЭто развалины Дунвальда... здесь НАВЕРНЯКА есть запасы хорошего эля. Надо только пошарить по зданиям... Если вдруг что найдешь, сразу тащи ко мне, договорились? Чем больше, тем лучше. Хорошего эля, его никогда не бывает много. Доброму дворфу – доброе пойло!$B$BЯ пойду вернусь к Кили, так что тебе, вероятно, придется меня поискать. Но уж я постараюсь, чтобы ты не $gпожалел:пожалела; о потраченном времени.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27650, 'ruRU', 'Снова дома', 'Поговорите с Кили Дунвальд в Укрытии Дунвальда.', 'Скорее разыщи Кили. Ну, чтобы она не волновалась...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27651, 'ruRU', 'Веселье по-дунвальдски', 'Поговорите с Флинном Дунвальдом и помогите братьям Дунвальдам убить Дарунгу.', 'Они опять ушли. Убежали вдогонку за эттином, который возглавлял атаку на Дунвальд. Я их просила подождать. Ну, чтобы ты $gуспел:успела; догнать, но куда там! Умчались как ветер.$B$BОни побежали в ту сторону. На городскую площадь, это в самом центре руин. Так что если не хочешь пропустить веселье – ноги в руки и бегом туда!', '', 'Когда Дунвальды вместе, никому мало не покажется.', 'Дарунга', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27652, 'ruRU', 'Темные убийцы', 'Соберите 5 подвесок темных убийц.', 'Даже я стал жертвой охоты. Но это риск, на который приходится идти, когда прячешься среди овец.$B$B<Матиас пристально смотрит на вас.>$B$BСектанты Сумеречного Молота подослали ко мне своих темных убийц. Кстати, неплохие ребята. Только жалко, что мертвые. Их создают из душ самых умелых и ловких убийц.$B$BСделай мне одолжение. Разыщи этих темных и принеси мне подвески, в которых запаяны их души.', '', '', '', '', '', 'Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27653, 'ruRU', 'Темные убийцы', 'Соберите 5 подвесок темных убийц.', 'Даже я стала жертвой охоты, |3-6($c). Но это часть игры, когда прячешься среди овец.$B$B<Гарона пристально смотрит на вас.>$B$BСумеречный Молот подослал ко мне своих темных убийц. Кстати, вполне себе милые ребята, особенно для мертвецов. Их создают из душ самых умелых и ловких убийц.$B$BСделай мне одолжение. Разыщи этих темных убийц.$B$BОни носят на шее подвески, в которых запаяны их души. Души мне как-то без надобности, а вот сами подвески, наверное, на что-нибудь да сгодятся. Принеси их мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27654, 'ruRU', 'Истребление Сумеречного Молота', 'Убейте 10 ветеранов цитадели, порочных повелителей стихий и/или сумеречных защитников.', 'Ни одна вылазка не может считаться законченной без старинной забавы под названием \"А ну-ка замочим плохих парней\".$B$BА уж плохих-то парней тут в избытке: ветераны цитадели, порочные повелители стихий, сумеречные защитники... Как говорится, выбирай на свой вкус.$B$BА уж как именно их прикончить, это ты решай $gсам:сама;.', '', '', '', '', '', 'Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27655, 'ruRU', 'Истребление Сумеречного Молота', 'Убейте 10 ветеранов цитадели, порочных повелителей стихий и/или сумеречных защитников.', 'Нет ничего хуже, чем эти убогие недоумки из Сумеречного Молота. Ничего! Они всерьез собрались учинить конец света.$B$BВсе беды в мире – от дураков, а посему в моем личном списке кандидатов на истребление они стоят номером первым.$B$BВ общем, задачу ты $gпонял:поняла;. Тебе будет где развернуться: ветераны цитадели, порочные повелители стихий, сумеречные защитники... $B$BМеня не волнует, как именно ты их прикончишь. Мне важен результат.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27656, 'ruRU', 'Крокобой', 'Убейте 8 острозубых кроколисков.', 'Вязкая топь просто кишит кроколисками. Кишит, слышишь? Я торговал всем, что только можно добыть из кроколиска.$B$BШкуры, зубы, хвосты, языки, глаза – всем. Я что говорю-то: ничего больше не берут. Их тут слишком много! Запасов навалом, а спроса нет.$B$BТак что раз проку от них никакого, а к тому же они порой едят моих гостей, то ты просто поубивай этих тварей, сделай одолжение. А я тут пока обсужу кое-что с твоими людьми.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27657, 'ruRU', 'Помощь Заклинательницы земли', 'Поговорите с заклинательницей земли Евой у входа в Элементиевые глубины в Сумеречном нагорье.', 'Я пытался исследовать артефакт Чо\'Галла, но, похоже, мои изыскания зашли в тупик. Служители культа Сумеречного Молота угнали в рабство нескольких кузнецов Громового Молота, а потом утопили их в озере, когда те закончили работу, которую их заставляли выполнять.$B$B<Матиас сплевывает.>$B$BНам нужна помощь. Есть один дреней из Служителей Земли – заклинательница земли Ева. Она сейчас на юго-западе, у рудника элементия, со своим помощником-гоблином.$B$BОни пытаются закрыть порталы элементалей, и им нужна помощь. Вот я и подумал: если мы им поможем, потом Ева тоже нас выручит.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27658, 'ruRU', 'Помощь Заклинательницы земли', 'Поговорите с заклинательницей земли Евой у входа в Элементиевые глубины в Сумеречном нагорье.', 'Я пыталась что-нибудь выяснить об артефакте Чо\'Галла, но, похоже, мои изыскания зашли в тупик. Сектанты Сумеречного Молота угнали в рабство нескольких кузнецов Громового Молота, а потом утопили их в озере, когда те закончили работу, которую их заставляли выполнять.$B$B<Гарона сплевывает.>$B$BМне претит произносить эти слова, но нам нужна помощь. Есть один дреней из Служителей Земли – заклинательница земли Ева. Она сейчас на юго-западе, у элементиевого рудника, со своим ручным гоблином.$B$BОни пытаются закрыть порталы элементалей, и им нужна помощь. Вот я и подумала: если мы им поможем, потом эта Ева и нас выручит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27659, 'ruRU', 'Перегрузка портала', 'Убейте ослабленного Апексара, ослабленного Эферона и ослабленного Эдемантия.', 'Раньше я была смотрительницей здешних порталов Служителей Земли. Но в наше отсутствие – когда мы помогали спасать Подземье – сюда пришли служители культа Сумеречного Молота.$B$BДля охраны порталов они используют могучих Перерожденных. Но тут они здорово просчитались.$B$BИди к порталам и устрой перегрузку с пультов управления. Таким образом ты высвободишь всю энергию порталов, и это ослабит Перерожденных. Убей их всех.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27660, 'ruRU', 'Дух озера', 'Поговорите с графиней Вералл в озере Лок Вералл в Сумеречном нагорье.', 'Я ничего не знаю об артефакте Чо\'Галла, но знаю, кто сможет тебе помочь.$B$BТебе нужен древний дух озера Лок Вералл, что к северу отсюда, графиня Вералл. Она ненавидит Сумеречный Молот, загрязнивший ее воды.$B$BРазыщи духа и спроси совета.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27661, 'ruRU', 'Повелитель Прожар', 'Убейте Повелителя Прожара.', 'Мой давний враг, Повелитель Прожар, видимо, от большого ума решил присягнуть на верность Сумеречному Молоту.$B$BРаньше мы с ним еще как-то сосуществовали – в состоянии шаткого перемирия, – но теперь, когда он переметнулся к врагам, у меня просто нет выбора, кроме как прикончить предателя. Тебе нужна информация от мертвого дворфа? Ты получишь ее, если убьешь Повелителя Прожара.$B$BИщи его в Преисподней Прожара на юго-востоке отсюда.', '', 'Убейте его, чтобы графиня Вералл была довольна.', 'Повелитель Прожар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27662, 'ruRU', 'Освобождение элементалей', 'Убейте и тем самым освободите 10 порабощенных элементалей на Сумеречной крепости.', 'Слушай, если я в чем-нибудь и разбираюсь, так это в элементалях. Я их действительно понимаю. Знаю, как они чувствуют. И могу сказать определенно: им не нравится быть рабами! Совершенно не нравится!$B$BСобственно, я вот о чем... Если ты освободишь порабощенных элементалей, они, скорее всего, тут же набросятся на своих бывших хозяев. А элементали страшны в гневе, уж поверь мне на слово.$B$BПо-моему, это хороший план. А ты как думаешь, $n?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27663, 'ruRU', 'На вкус как бегун', 'Соберите 9 огромных ножек болотолюбивых долгоногов.', 'Эй ты! Да, ты! Хочешь, замолвлю за тебя словечко торговому барону? Тогда выручай!$B$BСлыхал, это ты $gраздобыл:раздобыла; хвосты макрур. Они вкусны, не спорю, но для приготовления настоящего болотного блюда их мало. Для моего супа нужны птичьи ноги!$B$BВ Горемраке недалеко от города обитают болотолюбивые долгоноги. Мне нужны самые жирные ножки, какие только сможешь добыть!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27664, 'ruRU', 'Колода карт Новолуния: Вулканы', 'Принесите колоду Вулканов на ярмарку Новолуния.', 'Когда вы собираете вместе восемь карт из колоды Вулканов, девятая карта с такой же \"рубашкой\" появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Вы как-то слышали, что вход на ярмарку Новолуния открывается раз в месяц недалеко от Мулгора и Златоземья.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27665, 'ruRU', 'Колода карт Новолуния: Ураганы', 'Принесите колоду Ураганов на ярмарку Новолуния.', 'Когда вы собираете вместе восемь карт из колоды Ураганов, девятая карта с такой же \"рубашкой\" появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Вы как-то слышали, что вход на ярмарку Новолуния открывается раз в месяц недалеко от Мулгора и Златоземья.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27666, 'ruRU', 'Колода карт Новолуния: Цунами', 'Принесите колоду Цунами на ярмарку Новолуния.', 'Когда вы собираете вместе восемь карт из колоды Цунами, девятая карта с такой же \"рубашкой\" появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Вы как-то слышали, что вход на ярмарку Новолуния открывается раз в месяц недалеко от Мулгора и Златоземья.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27667, 'ruRU', 'Колода карт Новолуния: Землетрясения', 'Принесите колоду Землетрясений на ярмарку Новолуния.', 'Когда вы собираете вместе восемь карт из колоды Землетрясений, девятая карта с такой же \"рубашкой\" появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Вы как-то слышали, что вход на ярмарку Новолуния открывается раз в месяц недалеко от Мулгора и Златоземья.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27668, 'ruRU', 'Будь внимательнее!', 'Назгрим хочет, чтобы вы проверили содержимое разбитого ящика Альянса, лежащего к северу от Серпантина Бессмертного.', 'Слушай, |3-6($r)... Ты не думай, я тебе за все очень благодарен, но сейчас дела у нас идут неважно.$B$BТебе надо быть внимательнее!$B$BТы только что спокойно $gпроплыл:проплыла; мимо разбитого ящика Альянса. А в нем наверняка полно всякой полезной всячины.$B$BДавай-ка ты вернешься и посмотришь повнимательнее, а?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27669, 'ruRU', 'Почетная миссия', 'Разложите сферы Звезд по углам механизма в Зале Звезд.', 'Похоже, теперь остается лишь разместить сферы на пьедесталах по четырем углам этого механизма.$B$BТы хоть понимаешь, ЧТО мы нашли?! Это же величайшее археологическое открытие во всей новейшей истории!$B$B<Харрисон внимательно смотрит на вас, а потом отдает вам сферы.>$B$BДавай, $n. Ты $gзаслужил:заслужила;.$B$BБез тебя мы бы не совершили это открытие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27670, 'ruRU', 'В плену обстоятельств', 'Убейте 6 безумных лепрогномов.', 'Меня зовут Невин Крутилкинс, и я командир Сообщества Помощи в Адаптации Спасенным, или С.П.А.С.$b$bНе знаю, как удалось тебе выжить при здешнем уровне радиации, $n, но не все спасенные себя чувствуют так же хорошо. Моя команда собирает выживших, но тут слишком много подвергшихся воздействию радиации лепрогномов, и мы не можем больше их сдерживать. Они лишились разума!$b$bЕсли ты чувствуешь в себе достаточно сил, чтобы обращаться с оружием или читать заклинания, не поможешь ли ты нам справиться с этими лепрогномами?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27671, 'ruRU', 'Позаботиться о выживших', 'Воспользуйтесь маяком телепортации, чтобы телепортировать в безопасное место 6 выживших.', 'Если мы будем медлить, ни мои люди, ни спасенные не выберутся отсюда живыми. Я дам тебе наш аварийный маяк для телепортации. Сил и боеприпасов у нас достаточно, мы сможем пробиться наверх, но вот этим выжившим это не по плечу.$b$bВоспользуйся маяком, чтобы обеспечить им возможность телепортироваться в безопасное место, обустроенное моими людьми. Когда сделаешь это, сообщи мне, и мы примем меры для переправки тебя на поверхность.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27672, 'ruRU', 'Чертог Хаз\'Мула', 'Уничтожьте Иронайю.', 'В Зале Карт есть одна дверь... Как я понимаю, она как раз и ведет в легендарный чертог Хаз\'Мула. Кто знает, какие секреты там сокрыты!$B$BОднако известно, что вход охраняет Иронайа, Страж Титанов, наделенная действительно титанической силой. Если ты собираешься разгадать секреты Ульдамана, тебе придется убить ее!', '', '', '', 'Да!', 'Старший геолог Дардин', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27673, 'ruRU', 'Важно то, что внутри', 'Раздобудьте обсидиановый энергетический сердечник и энергетический сердечник титанов.', 'Творцы создали двух древних каменных хранителей для защиты Ульдамана от возможных вторжений и наблюдения за текущей работой системы, пока Иронайа и Аркедас спят. Один – тот, что в Храмовом зале – работает исправно, но второй – в пещере Эхомок – испорчен.$B$BБоюсь, что его специально вывели из строя. Скорее всего, кто-то из Древних Богов. Помоги мне разобраться. Разбей Хранителей и принеси мне их энергетические сердечники. И тогда мы поймем, в чем тут дело.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27674, 'ruRU', 'На поверхность', 'Поговорите с Торбеном Взрывошоком, чтобы телепортироваться на поверхность, и отчитайтесь Невину Крутилкинсу.', 'Невин только что сообщил, что он со своими ребятами двигается к поверхности. Он будет ждать тебя в здании, которое организация С.П.А.С. выбрала для своего штаба.$b$bВидишь Торбена Взрывошока? Поговори с ним, когда будешь $gготов:готова;, и он поможет тебе переправиться туда. Было приятно познакомиться с тобой, $n. Я горд, что немного поучаствовал в твоем спасении из Гномрегана и начале твоей новой жизни на поверхности.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27675, 'ruRU', 'Поддельные документы', 'Найдите жителя Штормграда, который примет ваши поддельные документы.', 'Найдите жителя Штормграда, который примет ваши поддельные документы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27676, 'ruRU', 'За закрытыми дверьми', 'Убейте Галганна Огнемолота.', 'Галганн Огнемолот и его банда дворфов из клана Черного Железа заняли третий раскоп и охраняют какую-то дверь, о которой мы ничего не знаем! Они мешают нам работать. Причем их здесь вообще быть не должно. Только у Лиги исследователей есть официальное разрешение на изучение артефактов на территории Ульдамана!$B$BИди на третий раскоп и разгони эту шайку, чтобы мы могли спокойно работать. Я хочу знать, что скрывается за той дверью!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27677, 'ruRU', 'Аркедас, древний Каменный Страж', 'Убейте Аркедаса.', 'Поиск сокровищ – это не главная цель похода в Ульдаман. Диски Норганнона – вот что мы ищем на самом деле! Они ценнее любых сокровищ, потому что хранят великие тайны древних Творцов. Тайны, которые могут совершить радикальный переворот в наших взглядах на мир...$B$BНо вот в чем загвоздка: просто так эти диски не взять. Они под надежной охраной. Их стережет Аркедас, древнее и могучее существо, созданное Творцами. Причем в его распоряжении целое войско. И все равно я хочу, чтобы ты $gуничтожил:уничтожила; Аркедаса и $gдобыл:добыла; эти древние диски для Лиги исследователей.', '', 'Все дело в дисках!', 'Аркедас', 'У тебя получилось!', 'Старший геолог Дардин', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27679, 'ruRU', 'Чертог Хаз\'Мула', 'Уничтожьте Иронайю.', 'В Зале Карт есть одна дверь... Как я понимаю, она как раз и ведет в легендарный чертог Хаз\'Мула. Кто знает, какие секреты там сокрыты.$B$BОднако известно, что вход охраняет Иронайа, Страж Титанов, наделенная действительно титанической силой. Чтобы попасть туда, тебе придется убить ее.', '', '', '', 'Очень даже неплохо.', 'Главный дознаватель Тей\'телан Кровавый Взор', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27680, 'ruRU', 'Аркедас, древний Каменный Страж', 'Уничтожьте Аркедаса.', 'Поиск сокровищ – это не главная цель похода в Ульдаман. Диски Норганнона, вот что мы ищем на самом деле! Эти диски – ценнее любых сокровищ. И не потому, что они из платины. На них хранятся великие тайны древних Творцов. Тайны, которые могут даровать нам небывалую силу и мощь.$B$BНо просто так эти диски не достать. Они под надежной охраной. Их стережет Аркедас, древнее и могучее существо, созданное Творцами. И он там не один. В его распоряжении – целое войско. Но все равно я хочу, чтобы ты $gуничтожил:уничтожила; Аркедаса и $gдобыл:добыла; эти древние диски для Реликвария.', '', 'Диски – это ключ к разгадке.', 'Аркедас', 'Прекрасно.', 'Главный дознаватель Тей\'телан Кровавый Взор', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27681, 'ruRU', 'За закрытыми дверьми', 'Убейте Галганна Огнемолота.', 'Галганн Огнемолот и его банда дворфов из клана Черного Железа заняли третий раскоп и охраняют какую-то дверь, о которой мы ничего не знаем! Они мешают нам работать. Причем их здесь вообще быть не должно. Только у Реликвария есть официальное разрешение на изучение артефактов на территории Ульдамана!$B$BИди на третий раскоп и разгони эту шайку, чтобы мы могли спокойно работать. Я хочу знать, что скрывается за той дверью!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27682, 'ruRU', 'Душа просит минералов!', 'Раздобудьте обсидиановый энергетический сердечник и энергетический сердечник титанов.', 'Титаны создали двух древних каменных хранителей для защиты Ульдамана от возможных вторжений и наблюдения за текущей работой системы, пока Иронайа и Аркедас спят. Один – тот, что в Храмовом зале – работает исправно, но второй – в пещере Эхомок – испорчен.$B$BПодозреваю, что его специально вывели из строя. Скорее всего, кто-то из Древних Богов. Сейчас и проверим мою догадку. Разбей этих хранителей и принеси мне их энергетические сердечники. И мы все узнаем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27683, 'ruRU', 'В лесу', 'Найдите женщину-воргена на берегу реки Тондрорил в Восточных Чумных землях.', 'Сегодня по городу прошла удивительно странная компания. Женщина-ворген на телеге, полной сундуков и ящиков, рядом с ней кровавый эльф, а за ними бежал дворф-паладин, выкрикивавший самые цветистые ругательства, которые мне когда-либо приходилось слышать.$B$BКажется, они направлялись в Восточные Чумные земли, но, думаю, сейчас только-только добрались до реки Тондрорил. Интересно, куда они шли? И зачем?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27684, 'ruRU', 'Гости', 'Найдите женщину-воргена на берегу реки Тондрорил в Восточных Чумных землях.', 'Мои агенты на участке Целителей Земли сообщают, что скоро к нам прибудут гости – отряд паладинов, который возглавляет не кто-нибудь, а купец-ворген. Более того – женщина-ворген. Я с нетерпением жду встречи с ними. Особенно с одним.$B$BНе проведаешь их? Точно не знаю, но думаю, их можно встретить к западу отсюда, у реки Тондрорил.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27685, 'ruRU', 'Добрые дела не бросают', 'Поговорите с Адаррой в лесу Келп’тар.', 'Привет, $gмалой:дорогуша;.$B$BМеня звать Рендел.$B$BПохоже, мы со старушкой Моаной прибыли как раз вовремя, верно говорю?$B$BЭрунак не шутки шутил, когда говорил, что положеньице тут – пан или пропал!$B$BНу вот... мы так спешили, что вынуждены были бросить одно дельце на востоке.$B$BПонимаешь, там одна дамочка в смертельной опасности. Нам пришлось ее оставить возле небольшого источника воздуха, чтобы поскорее прийти к вам на выручку.$B$BСходи помоги ей, покуда еще не поздно.', '', 'Помогите!', 'Адарра', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27686, 'ruRU', 'Поддельные документы', 'Найдите жителя Оргриммара, который примет ваши поддельные документы.', 'Найдите жителя Оргриммара, который примет ваши поддельные документы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27687, 'ruRU', 'Скреж, да не наш', 'Принесите голову Скрежа Самиру в Пещеру контрабандистов.', 'Вот это подвиг – одолеть могучего морского гиганта!$B$BНовые обитатели Пещере контрабандистов будут чувствовать себя гораздо спокойнее, зная, что это чудище не шатается где-то поблизости.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27688, 'ruRU', 'Отвлекающий маневр', 'Убейте госпожу Элис Финнссон, мастера Клема и Мию Цветущую.', 'Необходимо уничтожить троих: госпожу Элис Финнссон, мастера Клема и Мию Цветущую.$B$BМне нужно, чтобы ты их $gотвлек:отвлекла;. А я выберу подходящий момент, подберусь к ним со спины и прикончу.$B$BТолько будь $gосторожен:осторожна;, $n. Не стоит их недооценивать. Они опасные соперники, сильные и безжалостные.', '', '', '', '', '', 'Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27689, 'ruRU', 'Отвлекающий маневр', 'Убейте госпожу Элис Финнссон, мастера Клема и Мию Цветущую.', 'Необходимо уничтожить троих: госпожу Элис Финнссон, мастера Клема и Мию Цветущую.$B$BМне нужно, чтобы ты их $gотвлек:отвлекла;. А я выберу подходящий момент, подберусь к ним со спины и прикончу.$B$BТолько, прошу тебя, будь $gосторожен:осторожна;, $n. Не стоит их недооценивать. Они опасные соперники, сильные и безжалостные. И при этом – форменные психопаты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27690, 'ruRU', 'Наркралл, Укротитель Драконов', 'Отправляйтесь к Наркраллу Кривому Когтю в Кровавое ущелье в Сумеречном нагорье.', '$n, крепость в Кровавом ущелье – это сердце империи Драконьей Пасти. И она не так далеко отсюда – вверх по течению реки. Наркралл Кривой Коготь сейчас собирает там армию наездников на драконах.$B$BЧтобы империя Драконьей Пасти смогла устоять, ей нужна сильная армия. Иди к Наркраллу в Кровавое ущелье и позаботься о том, чтобы у него все получилось.', '', '', '', '', '', 'Поговорите с Наркраллом Кривым Когтем в Кровавом ущелье в Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27691, 'ruRU', 'Болотноплавниковый беспредел', 'Убейте 12 мурлоков Болотных Плавников.', 'Боюсь, из хитрошестеренкинцев здесь уже никого не осталось. Вся молодежь в лагере на востоке пропала, когда пришли мурлоки.$B$BДа, мурлоки всегда обитали на этих берегах... но не в таких количествах. Они стаями повалили из моря под покровом ночи, воя и пуская слюну, собираясь на суше для атаки!$B$BМы не можем им позволить просто так тут расхаживать! Может быть, выручишь пожилую гоблиншу и пойдешь затолкаешь их обратно в море?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27692, 'ruRU', 'Принцесса Терадрас', 'Сразите принцессу Терадрас.', 'Не волнуйся, $gюный:юная:r; |3-6($r). Я Зейтар, сын Кенария, и я прибыл, чтобы тебе помочь.$B$BДавным-давно я совершил ошибку, вступив в связь с принцессой Терадрас, могущественным элементалем земли из рода древних богов. Родившись, наши дети ханы-кентавры сразу же напали на меня и жестоко убили. Тлетворное влияние Терадрас простирается гораздо дальше Мародона.$B$BСрази ее и освободи мой дух, чтобы мы смогли вернуть Пустоши к жизни, как завещал нам Кенарий.', '', 'Ее нужно остановить!', 'Принцесса Терадрас', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27693, 'ruRU', 'Игра стражей', 'Завершите игру стражей, переместив пешек-стражей так, чтобы они смотрели внутрь квадрата.', 'Вы видите, как статуэтка сначала раздваивается, затем делится на четыре, а затем на восемь одинаковых статуэток, которые выстраиваются в квадрат.$B$BПрямо в вашем сознании раздается голос:$B$B\"Настоящий страж не смотрит ВОВНЕ, отыскивая признаки опасности.$B$BНастоящий страж обращает свой взгляд ВОВНУТРЬ, сосредоточенно оберегая свою добычу\".$B$BДолжно быть, это какая-то загадка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27694, 'ruRU', 'Озеро слез', 'Найдите 5 артефактов Атал\'ай в Озере слез возле храма Атал\'Хаккара.', 'Тролли, затаившиеся в этом храме, причинили моим собратьям величайшее зло, $n. Предполагалось, что мы будем оберегать это место, но нас использовали для пробуждения ужасных сил.$B$BПрошу тебя об услуге, которую может оказать лишь смертный. Ты будешь моей правой рукой в храме; войди я туда, меня самого могут обратить против моих собратьев.$B$BЗаключим договор. Если хочешь помочь, найди на дне озера, расположенного возле храма, артефакты Атал\'ай и принеси их мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27695, 'ruRU', 'Топор из элементия', 'Раздобудьте топор из элементия.', 'Эти презренные трусы из Сумеречного Молота перебили почти всех красных драконов, но один все же остался. Вернее, одна. Помнишь Лирастразу? Ее держат в оковах. Тут, неподалеку. И мы ее освободим.$B$BНо сначала нам нужно добыть самый острый и крепкий клинок, чтобы перерубить ее цепи.$B$BОтправляйся на юг, к Алтарю Перерожденных. Его охраняет старый эттин по имени Слепой Страж.$B$BУ этого Стража боевой топор из чистейшего элементия. Я вот думаю... может быть, это и есть пресловутое \"совершенное оружие\" Чо\'Галла?', '', '', 'Слепой Страж', '', '', 'Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27696, 'ruRU', 'Топор из элементия', 'Раздобудьте топор из элементия.', 'Эти презренные трусы из Сумеречного Молота перебили почти всех красных драконов, но один все же остался. Вернее, одна. Помнишь Лирастразу? Ее держат в оковах. Тут, неподалеку. И мы ее освободим.$B$BНо сначала нам нужно добыть самый острый и крепкий клинок, чтобы перерубить ее цепи.$B$BОтправляйся на юг, к Алтарю Перерожденных. Его охраняет старый эттин по имени Слепой Страж.$B$BУ этого Стража настоящий боевой топор из чистейшего элементия. Я вот думаю... может, это и есть пресловутое \"совершенное оружие\" Чо\'Галла?', '', 'У него топор из элементия!', 'Слепой Страж', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27697, 'ruRU', 'Скверна в Мародоне', 'Покончите с лордом Злоязыким.', '$n, мне срочно нужна твоя помощь! Я Зейтар, сын Кенария. Вследствие череды событий, я оказался заточен этом подземелье! Однако прежде чем выручать меня, нужно избавить Мародон от скверны, поразившей это место.$B$BЛорд Злоязыкий – правитель сатиров из Пещеры лиловых кристаллов. Это коварный агент Пылающего Легиона, поэтому его присутствие способно принести лишь смерть и разрушение. С ним нужно покончить!', '', 'Пришел и его черед!', 'Лорд Злоязыкий', 'Твоя миссия еще не выполнена!', 'Зейтар', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27698, 'ruRU', 'Прислужники Терадрас', 'Уничтожьте Ноксиона и Бритвохлеста.', 'Моя бывшая возлюбленная, принцесса Терадрас, воспользовалась своей невиданной силой, чтобы поразить самую суть Мародона. Даже теперь ее создания бродят по округе, угрожая вырваться за пределы этого места и сеять смерть и разрушения.$B$BОтправляйся в путь, $n, и заставь ее страдать, убив Ноксиона и Бритвохлеста, сильнейших служителей Терадрас. Возможно, тогда ты сможешь вырвать мой дух из ее плена.', '', 'Самое их существование противно природе.', 'Бритвохлест', 'Благодарю тебя за старания.', 'Зейтар', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27699, 'ruRU', 'Крепкий орешек', 'Добудьте 5 зубов Костеглода на Рифе Скелетов.', 'Крепкая же оказалась акула!$B$BВам приходит в голову, что для всех будет лучше, если Бадд увлечется чем-нибудь другим и думать забудет о Костеглоде и об этом Проклятом рифе.$B$BВозможно, зубы Костогрыза в достаточной степени займут Бадда...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27700, 'ruRU', 'Освобождение дракона', 'Топором из элементия разрубите цепи, которыми скована Лирастраза.', 'Лирастраза – последняя и величайшая из красных драконов, которых захватил Сумеречный Молот. Они намерены ее убить.$B$BВозьми топор из элементия и освободи ее от оков.', '', '', 'Лирастраза', '', '', 'Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27701, 'ruRU', 'Освобождение дракона', 'Топором из элементия разрубите цепи, которыми скована Лирастраза.', 'Лирастраза – последняя и величайшая из красных драконов, которых захватил Сумеречный Молот. Они собираются убить ее, |3-6($c).$B$BВозьми топор из элементия и освободи ее от оков.', '', 'Освободите ее с помощью топора из элементия!', 'Лирастраза', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27702, 'ruRU', 'Удар милосердия', 'Добейте 5 сумеречных ужасов небес.', 'Смотри! Лирастраза сражается с ними!$B$BМы должны добить тех драконов, которых она сбила, но не прикончила, $n. Мы же не хотим, чтобы целители Сумеречного Молота вновь подняли их в воздух.$B$BНазовем это проявлением милосердия к проигравшим.', '', '', '', '', '', 'Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27703, 'ruRU', 'Удар милосердия', 'Добейте 5 сумеречных ужасов небес.', 'Ты гляди, что творится! Лирастраза сражается с ними!$B$BНекоторых драконов она сбила, но не прикончила. Мы должны завершить начатое ею, $n. Мы же не хотим, чтобы поганые целители Сумеречного Молота вновь подняли их в воздух.$B$BНазовем это проявлением милосердия к проигравшим.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27704, 'ruRU', 'Легенды Затонувшего храма', 'Доберитесь до Зала Масок через вестибюль храма.', 'Сначала в храм $gдолжен:должна; пойти ты, $n. Я присоединюсь к тебе, когда это будет безопасно, но не хочу действовать вслепую. Обращенный против своих собратьев, я стану грозным противником.$B$BСперва спустись по лестнице позади меня. Затем проплыви через Разрушенный зал. Дальше иди по коридору, и, повернув направо, ты окажешься в зале Масок.$B$BОстерегайся стражей храма. Когда окажешься в Зале Масок, я свяжусь с тобой через Камень клятвы.', 'Зал Масок найден', '', '', 'Ты в Зале Масок!', 'Лорд Итар', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27705, 'ruRU', 'Шаг первый: жрица', 'Убейте жрицу Удум\'бру в Чертоге Крови.', 'Здесь убивают моих братьев. Я так и думал.$B$BПрежде чем я туда пойду, снова попрошу твоей помощи, $n. Из коридора за этой комнатой есть два выхода – налево и направо. Путь направо ведет в Чертог Крови. Там Атал\'ай вершат темные ритуалы.$B$BГодами они готовились и поджидали моих собратьев, но тебя они не ждут. Пойди в Чертог Крови и убей жрицу Удум\'бру. Она одна из трех, от кого нужно избавиться, прежде чем я сам смогу войти.', '', 'Проповедница Чертога Крови', 'Жрица Удум\'бра', 'Камень клятвы связывает нас.', 'Лорд Итар', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27706, 'ruRU', 'Скипетр Орсиса', 'Возьмите скипетр Орсиса из священного ларца.', 'Едва вы вставляете камни в гнезда на табличке, как ларец с громким щелчком открывается.$B$BВозьмите скипетр и отнесите его генералу Аммантепу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27707, 'ruRU', 'Тюрьма неферсетов', 'Отправляйтесь в тюрьму Неферсета и выясните, что сталось с Тахетом.', 'Иероглифы, изображающие закованного в цепи тол\'вира, нанесены в юго-восточном уголке карты.$B$BВозможно, именно туда отвели пленного Тахета.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27708, 'ruRU', 'Последний дозор', 'Эрунак Говорящий с Камнем хочет, чтобы вы убили стража Азжакира на Жемчужной ферме.', '<Образ Эрунака возникает в вашем сознании.>$B$BХорошая работа, $n, но многое еще предстоит сделать.$B$BПрежде чем уйти, нужно напоследок учинить здесь изрядный погром.$B$BРазыщи предводителя наг и покарай за все его злодеяния.', '', 'Образ Эрунака возникает в вашем сознании.', 'Эрунак Говорящий с Камнем', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27709, 'ruRU', 'Игра часовых', 'Завершите игру часовых, соединив две красные статуэтки.', 'Как только статуэтка оказывается на месте, в комнате появляется еще несколько каменных статуэток. В нише в дальнем конце комнаты вы видите еще одну рубиновую фигурку. Вы слышите голос:$B$B\"Страж наблюдает.$BСтраж защищает.$BСтраж никогда не смежает очей\".$B$BКрасная статуэтка на другом конце комнаты наверняка для чего-то нужна. Может быть, попробовать соединить две красные статуэтки?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27711, 'ruRU', 'Возвращение в Элементиевые глубины', 'Поговорите с посвященным Клондацком в Элементиевых глубинах, что в Сумеречном нагорье.', 'Посвященному Клондацку, помощнику Заклинательницы земли, в свою очередь, нужна твоя помощь.$B$BУ них там какие-то сложности в шахте. Какие именно – я не в курсе. Придешь на место, узнаешь.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27712, 'ruRU', 'Возвращение в Элементиевые глубины', 'Поговорите с посвященным Клондацком в Элементиевых глубинах, что в Сумеречном нагорье.', 'У Заклинательницы Земли есть помощник-гоблин? Посвященный Клондацк – его имя? Ему нужна твоя помощь.$B$BУж не знаю, что у них там стряслось в этой шахте, но они явно не прочь скинуть на кого-нибудь всю грязную работенку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27713, 'ruRU', 'День, когда пришел Смертокрыл', 'Выслушайте рассказ Тельдарина.', 'Смертокрыл натворил немало бед, пролетая через эти земли. Если бы не я, он бы по-прежнему тут хозяйничал, сея смерть среди добрых жителей Бесплодных земель.$B$BЧто, не веришь? Ладно, я тебе расскажу, как все было.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27714, 'ruRU', 'День, когда пришел Смертокрыл: вся правда', 'Послушайте версию событий в изложении Люсьена Подай-Ключ.', 'Тельдарин не просто все переврал – его история скучна и напрочь лишена воображения и динамики.$B$BСейчас я тебе расскажу, как все было на самом деле.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27715, 'ruRU', 'День, когда пришел Смертокрыл: все было совсем иначе...', 'Послушайте рассказ в изложении Мартека Изгоя.', 'Эти двое вообще не умеют рассказывать. У Тельдарина все как-то скомкано, а у Люсьена натурально получилась история-переросток.$B$BИ ни у того, ни у другого ни слова о горячих цыпочках!$B$BУстраивайся поудобнее, $n. Я тебе расскажу, как все было.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27716, 'ruRU', 'Частица прошлого', 'Принесите обломок с древними эльфийскими письменами Ливии Пробуждающей. Найти ее можно в лагере спасенных Альянса из Неспиры.', '<Обломок треснувшей древней плиты весь покрыт какими-то надписями. Язык вам незнаком, но текст и сам вид обломка наводят на мысли о том, что это очень ценный предмет.>$B$B<Ливия Пробуждающая, живущая в лагере спасенных из Неспиры, искала нечто подобное.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27717, 'ruRU', 'Частица прошлого', 'Принесите обломок с древними эльфийскими письменами Элендре Золотое Чело. Ее можно найти в лагере ордынцев, спасенных из Неспиры.', '<Обломок треснувшей древней плиты весь покрыт какими-то надписями. Язык вам незнаком, но текст и сам вид обломка наводят на мысли о том, что это очень ценный предмет.>$B$B<Элендри Золотое Чело, живущая в лагере спасенных из Неспиры, искала нечто подобное.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27718, 'ruRU', 'Приказ вождя: Вайш\'ир!', 'Явитесь с рапортом к командиру Тораку в бухте Острорука в Дуротаре.', 'Всем годным к военной службе ордынцам приказано явиться к командиру Тораку в бухту Острорука в Дуротаре.$B$BСейчас нам как никогда прежде необходима твоя помощь в борьбе с нашим заклятым врагом Альянсом!$B$BЧтобы добраться до бухты Острорука, отправляйся через главные ворота Оргриммара на юг, в Дуротар. Оттуда следуй по тропе на восток, к побережью. Торак будет ждать возле доков.$B$BВперед, $gбрат:сестра;! Судьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27719, 'ruRU', 'Живая вода', 'Расспросите труп начальника кузни Финлея, вернув ему подобие жизни с помощью живой воды.', 'Возьми мою живую воду и влей в рот утонувшего дворфа.$B$BПри жизни тот был кузнецом и работал с металлом, и хотя уже мертв, вода вернет ему на время подобие жизни, и ты сможешь его расспросить и узнать, что тебе нужно.$B$BА потом уходи из моих владений.', '', '', '', '', '', 'Поговорите с мастером Матиасом Шоу на Сумеречной крепости на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27720, 'ruRU', 'Прокатимся с ветерком', 'Вместе с посвященным Клондацком прокатитесь на вагонетке до конца маршрута.', 'Значит, так, $n. Нам надо добраться до портала земли в самом дальнем конце пещеры.$B$BЯ сделал умно – \"раздобыл\" транспорт. Зачем трудить ноги, когда можно проехаться с ветерком? Надеюсь, твоя религия не запрещает кататься на шахтерских тачках?$B$BВ общем, как будешь $gготов:готова;, скажи – и поедем.', '', '', '', '', '', 'Поговорите с посвященным Клондацком в Элементиевых глубинах, что на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27721, 'ruRU', 'Приказ вождя: гора Хиджал!', 'Поговорите с кенарийским посланником Черным Копытом, чтобы он отправил вас на Лунную поляну.', 'Всем воинам Орды, способным держать оружие, надлежит отрапортовать посланнице Песне Ветра в Ночной Гавани на Лунной поляне.$B$BНаши братья из Круга Кенария сообщают о том, что пособники Смертокрыла отправились в разрушительный поход с целью уничтожить Древо Жизни и осквернить землю, на которой оно растет!$B$BОбратись к кенарийскому посланнику Черному Копыту, чтобы тот отправил тебя на Лунную поляну. Черное Копыто находится в квартале тауренов на Аллее Мудрости в Оргриммаре.$B$BВперед, $gбрат мой:сестра моя;! Свершения ждут тебя!', 'Путешествие на Лунную поляну обеспечено', '', '', '', '', 'Поговорите с посланницей Песней Ветра в Ночной гавани на Лунной поляне.', 25549);
INSERT INTO `quest_template_locale` VALUES (27722, 'ruRU', 'Приказ вождя: Подземье!', 'Поговорите с предсказателем Крогаром в Западном Святилище Земли в Оргриммаре.', 'Всем годным к военной службе ордынцам приказано явиться к предсказателю Крогару в Западное святилище Земли в Оргиммар.$b$bСлужителям Земли, возглавляемым нашим бывшим вождем Траллом, необходима ваша помощь! Они сообщают о том, что обитель стихии Подземья угрожает захватить наш мир!$b$bЗападное святилище Земли находится к северу от Аллеи Мудрости.$b$bВперед, $gбрат:сестра;! Судьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27724, 'ruRU', 'Воззвание к героям: Вайш\'ир!', 'Поговорите с вербовщиком Бернсом в порту Штормграда.', 'По приказу его королевского высочества короля Андуина Ринна все годные к военной службе подданные Альянса должны явиться к вербовщику Бернсу в порт Штормграда.$B$BНападения Орды на наши торговые суда не должны остаться без ответа!$B$BПорт Штормграда располагается в северо-западной части Штормграда.$B$BВо имя нашего славного Альянса! В бой, $gбрат:сестра;!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27725, 'ruRU', 'Сторожка Кель\'Данил', 'Поговорите с анахоретом Траской в Сторожке Кель\'Данил.', 'Тебе может казаться, что я пришел очень издалека, |3-6($c). Посол Руалет привел сюда достаточно много моих собратьев. Мы поселились вместе с высшими эльфами в Сторожке Кель\'Данил, что к северо-западу отсюда, чтобы узнать больше об учении Света и насладиться красотой этих земель.$b$bНо такой покой не может длиться долго. Мы видели войска Орды, которые продвигаются все дальше к западу отсюда. Не $gмог:могла; бы ты отправиться в Кель\'Данил и предупредить анахорета Траску? Ее хижина находится севернее самой Сторожки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27726, 'ruRU', 'Воззвание к героям: гора Хиджал!', 'Поговорите с кенарийской посланницей Нефритовой Луной, чтобы та отправила тебя на Лунную поляну.', 'По приказу его королевского высочества короля Андуина Ринна всем членам Альянса, способным держать оружие, надлежит отрапортовать посланнице Песни Ветра в Ночной Гавани на Лунной поляне.$B$BНаши братья из Круга Кенария сообщают о том, что пособники Смертокрыла отправились в разрушительный поход с целью спалить Древо Жизни дотла!$B$BОбратись к кенарийской посланнице Нефритовой Луне в крепости Штормграда за доступом на Лунную поляну.$B$BЗа честь и славу Альянса! В бой, $gбрат:сестра;!', 'Путешествие на Лунную поляну обеспечено', '', '', '', '', 'Поговорите с посланницей Песней Ветра в Ночной гавани на Лунной поляне.', 25549);
INSERT INTO `quest_template_locale` VALUES (27727, 'ruRU', 'Воззвание к героям: Подземье!', 'Поговорите с Нараатом Говорящим с Землей в Восточном Святилище Земли в Штормграде.', 'По приказу его королевского высочества короля Андуина Ринна все годные к военной службе граждане Альянса обязаны явиться к Нараату Говорящему с Землей в Восточное Святилище Земли в Штормграде.$b$bСлужителям Земли требуется наша помощь! Они сообщают о том, что обитель стихий Подземья угрожает захватить наш мир и уничтожить все живое на Азероте!$b$bВосточное Святилище Земли находится к северо-западу от Крепости Штормграда.$b$bЗа честь и славу Альянса! В бой, $gбрат:сестра;!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27729, 'ruRU', 'Угревая зыбь', 'Убейте 8 любых угрей в лесу Келп’тар.', 'Угри – одни из самых мерзких тварей во всем Азероте.$B$BРазумеется, найдутся те, кто будет заливать, будто ничего не имеют против угрей; есть и те, кто утверждает, будто бы они ЛЮБЯТ угрей.$B$BВсе это вранье.$B$BПравда же в том, что угрей не любит никто. Мало того – даже угри не любят угрей!$B$BЖизнь в Азероте станет прекрасной и удивительной, как только все забудут о том, что такое угорь, выползающий из морской пучины и кусающий тебя.$B$BЗа нос.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27733, 'ruRU', 'Старый добрый подлог', 'Убейте Рендольфа Молоха.', 'Послушай, я бы с радостью отдал приказ взорвать всех заключенных к лешему прямо сейчас, но не могу. Тюрьмой Штормграда распоряжается тюремщик Телвотер, а он пока просто хочет сдержать бандитов.$B$BВместо прямого неподчинения приказу мы пойдем на военную хитрость! Нам удалось сдружиться с Мортимером Молохом, который по счастливой случайности оказался братом-близнецом зачинщика восстания Рендольфа Молоха. Убей Рендольфа – мы поставим вместо него Мортимера, и тот без крови покончит с восстанием!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27737, 'ruRU', 'Пламя во спасение!', 'Раздобудьте пламенное сердце лорда Пережара.', 'Я прекрасно разбираюсь в первой помощи и других видах лечения, и при наличии Колодца Света мне удалось полностью исцелить многих наших людей. Но здесь, внизу, так холодно и сыро, что они все равно гибнут, несмотря на то, что я лечу их раны!$B$BЗемлетрясения разозлили элементалей в темнице... выйдя из толщи земли, они погубили половину узников. Если ты уничтожишь их вождя, лорда Пережара, и принесешь мне его сердце, я согрею им наших людей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27738, 'ruRU', 'Ров Чешуи', 'Спасите Тахета возле у Рва Чешуи в Ульдуме.', 'Точка в южной оконечности карты была отмечена иероглифами, изображающими дерущихся крокодилов.$B$BДолжно быть, туда Каимас увел Тахета.$B$BОтправляйтесь в Ров Чешуи и попытайтесь спасти сына визиря.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27739, 'ruRU', 'Король гноллов', 'Убейте Дробителя.', 'Боюсь, $n, что мне придется просить тебя о невозможном.$B$BВот эту повязку на глаз я получил из-за него. Тысячи тысяч пали жертвами его гнева. Лишь чудом его удалось здесь заточить.$B$BНо это было роковой ошибкой. Мы держались, сколько было сил, потом пришли они. Выступив из тьмы, гноллы, слуги Дробителя, разорвали лучших моих людей в клочья.$B$BТы $gдолжен:должна; одолеть короля гноллов, пока он снова не напал и не перебил всех нас в кровожадной ярости.', '', 'Его никому не одолеть.', 'Дробитель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27740, 'ruRU', 'Баба Тиночерп', 'Поговорите с Чудачкой Дейзи, чтобы вылететь из пушки в сторону Бабы Тиночерп.', 'Эй, пока тебя не было, заглядывал барон! Колошматил меня, пока деньги не посыпались!$B$BВпрочем, он всегда так делает. Но в этот раз он еще просил кое-что тебе передать! Он хочет, чтобы ты $gотправился:отправилась; на юг на помощь нашей травнице Бабе Тиночерп.$B$BК ней далековато плыть! Но ты просто загляни к моей девочке Дейзи возле лагеря – она тебя туда мигом доставит, по-нашему!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27742, 'ruRU', 'Сколько добра пропадает!', 'Соберите 6 осколков элементия.', 'Знаешь, тут развелось столько сланцевых пауков... и они пожирают элементий. Его надо спасать. Это наш моральный долг!$B$BСтолько добра пропадает зря, страшно подумать!$B$BНу что, займемся? И честно поделим спасенный элементий. Одну десятую долю – тебе, девять – мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27743, 'ruRU', 'Чтобы два раза не бегать', 'Убейте в Элементиевых глубинах 12 служителей культа Сумеречного Молота – инспекторов глубин или сумеречных шахтеров.', 'Знаешь, раз уж мы здесь... Может быть, зададим жару этим паршивцам из Сумеречного Молота? Ну, чтобы два раза не бегать... Надо же восстановить справедливость! Когда-то этот рудник был нашим, а они здесь чужие! Подлые захватчики!$B$BНу что, займешься? Я бы помог, только что я могу без оружия и тотемов?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27744, 'ruRU', 'Уничтожение рун', 'Уничтожьте сумеречную руну земли, руну воды, руну воздуха и руну огня.', 'Изучая сумеречную руну земли, вы почти ощущаете, как ее сила устремляется на самое дно Элементиевых глубин.$B$BВероятно, она тесно связана с другими рунами. Посвященный Клондацк считает, что их следует уничтожить. Все до одной.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27745, 'ruRU', 'Пламенная встреча', 'Раздобудьте пульт управления порталом огня и активируйте портал огня.', 'Это же Магмазуб, мой бывший элементаль огня. $n, я тебя умоляю, убей его. Иначе он меня прикончит!$B$BЭто было всего лишь недоразумение... Мы просто друг друга не поняли. Откуда мне было знать, что он так разъярится, когда я \"позаимствовал\" его сердце в Подземье? Все равно он не может умереть... во всяком случае, не навсегда!$B$BПульт управления порталом наверняка у него. Отбери у него пульт и активируй портал огня. И мы спокойненько перенесемся обратно к входу.', '', 'Бывший элементаль огня посвященного Клондацка. Теперь между ними вражда.', 'Магмазуб', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27746, 'ruRU', 'Империя грязи', 'Отчитайтесь верховному палачу Дарталии у Южных врат в предгорьях Хилсбрада.', 'Эта война отрицательно сказалась на нас, как на народе. Мы понесли огромные потери, защищая Лордерон. И несмотря на эту победу, бои продолжают бушевать в других частях Восточных королевств.$b$bЯ должна вернуться в Подгород и залечить свои раны. Я хочу, чтобы ты $gотправился:отправилась; в предгорья Хилсбрада вместо меня. Из всех своих солдат больше всего я полагаюсь на тебя, $n. Ты и возглавишь наши войска. Мы должны добиться абсолютного преимущества над нашими врагами в Хилсбраде.$b$bОтчитайся верховному палачу Дарталии у Южных врат, это к востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27747, 'ruRU', 'Дотла', 'Отправляйтесь в руины Громтара и разбейте 10 бочонков громтарского эля.', 'Большинство дворфов клана Громового Молота уже сбежали отсюда, бросив дома и имущество. И сейчас самое время стереть их деревню с лица земли.$B$BОтправляйся на север. Там, в горах, ты найдешь брошенное поселение в руинах Громтара. В домах осталось немало бочонков с крепчайшим элем.$B$BЭль Громтара. Крепость – аж 220 градусов! Уж не знаю, как такое возможно.$B$BРазбей эти бочонки и подожги их содержимое. Сожги там все дотла! Чтобы дворфам было некуда возвращаться!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27748, 'ruRU', 'Удача и слава', 'Уничтожьте обсидианового колосса.', 'Нужно продолжать наступление, $n. Через некоторое время вражеские войска перегруппируются.$B$BСаркофаг должен быть прямо за этими руинами.$B$BИ держи ухо востро. Что-то мне подсказывает – далеко не все наши приключения позади...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27750, 'ruRU', 'Пища, отнятая у врага', 'Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.', '<У Гриффа урчит в животе.>$B$BКогда мы, солдаты Драконьей Пасти, идем на войну, мы прекращаем охотиться.$B$BСамая вкусная пища – пища, отнятая у врага! В горах к северу от реки осталось полуразрушенное поселение дворфов из клана Громового Молота. Держу пари, там полно всякого разного продовольствия.$B$BПринеси мне чего-нибудь вкусненького.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27751, 'ruRU', 'Сокрушение Громового Молота', 'Отправляйтесь в руины Громтара, убейте нескольких передовых бойцов Громового Молота и соберите 8 знаков Громового Молота. Персонажи, у которых есть имена, тоже носят знаки различия.', 'С тех пор, как мы пришли на нагорье, дворфы из клана Громового Молота были и остаются нашими злейшими врагами. Эта война все никак не закончится! Мы дрались с ними в Грим Батоле, мы дрались с ними в Болотине и даже сейчас сражаемся – на севере, за рекой, в руинах Громтара.$B$BДокажи свою доблесть! Отыщи и сокруши передовых бойцов Громового Молота. Лучшие среди них носят знаки различия – мои бойцы собирают их дюжинами.$B$BХочу посмотреть, сколько соберешь ты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27752, 'ruRU', 'Боевой эль', 'Отправляйтесь в руины Громтара и принесите 10 бочонков эля. И не вздумайте пробовать этот эль – с непривычки он валит с ног с двух глотков!', 'Скажу тебе без ложной скромности – наши мастера-пивовары из Громтара варят просто волшебный эль! Лучший эль во всех Восточных королевствах! Крепость – аж 220 процентов. Да, ты не $gослышался:ослышалась;!$B$BКогда жители южных предместий бежали в город, им пришлось бросить свои дома, где у них были немалые запасы эля.$B$B<Бланди на миг умолкает, давая вам время осознать всю серьезность ситуации.>$B$BЕГО НАДО ВЕРНУТЬ! Одна кружка этого эля – и даже самый робкий солдат превращается в свирепого бешеного бойца, который сметает все на своем пути. Принеси мне побольше бочонков с элем! Это наша единственная надежда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27753, 'ruRU', 'Вылазка за продовольствием', 'Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.', 'Наш запас продовольствия подходит к концу, $n. В Громтар стекаются беженцы со всего горного кряжа – нам просто не прокормить столько ртов!$B$BА ведь в брошенных беженцами домах осталось немало продуктов. Нужно забрать их сюда!$B$BОтправляйся в руины Громтара и поищи там еду – в южной, восточной и юго-западной части руин.$B$BТолько будь $gосторожен:осторожна;, |3-6($c)! Там повсюду идут напряженные бои. Смотри, чтоб тебя не пришибло.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27754, 'ruRU', 'Уничтожение Драконьей Пасти', 'Отправляйтесь в руины Громтара, убивайте мародеров Драконьей Пасти и соберите 8 знаков Драконьей Пасти. Персонажи, у которых есть имена, тоже носят знаки различия.', 'Драконья Пасть!$B$B<Колин плюется.>$B$BМерзавцы и изверги, все как один. Сколько я себя помню, мы всегда с ними сражались. Всегда. Еще с начала последней войны. А теперь они, стало быть, объединяются с Ордой...$B$BЕсли ты собираешься убедить воинов Громового Молота встать под знамя Альянса, тогда докажи свою доблесть в сражении с Драконьей Пастью. В руинах Громтара сейчас как раз идет бой, на юге и юго-западе. Перебей сколько сможешь этих скотов-мародеров из Драконьей Пасти, собери знаки различия, которые носят их лучшие воины, и принеси сюда. Вот тогда и поговорим.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27755, 'ruRU', 'Проклятие гробниц', 'Убейте 6 безумных землекопов и Анжинера Злобекромса.', 'Неферсеты – не единственная угроза, нависшая над нашими священными гробницами.$B$BНесколько недель назад на эту землю пожаловала экспедиция гномов.$B$BОни не вняли нашим предостережениям и начали раскопки в проклятом склепе. И зарылись слишком глубоко.$B$BНа всех членов экспедиции пало страшное проклятье – оно лишило гномов рассудка и завладело их разумом.$B$BТеперь они представляют для нас большую опасность, потому что их цель – добраться до самых глубоких склепов Ульдума. $B$BОтправляйся на Террасу Солнечного Камня и избавь души этих гномов от страданий.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27756, 'ruRU', 'Штейгер', 'Убейте Глубтока.', 'Если мы хотим понять, что тут творится, нам, похоже, придется прорубаться через Мертвые Копи! Первым твоим серьезным противником станет штейгер Глубток, могучий огр-маг. Берегись: он не только силен, как всякий огр, но и колдовством может изрядно вдарить!$B$BВозьми эту рацию для связи, пока ты там внизу. И будь $gосторожен:осторожна;.', '', 'Так просто он не сдастся.', 'Глубток', 'Страсти накаляются.', 'Лейтенант Горацио Лейн', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27757, 'ruRU', 'Непроглядная глубь', 'Убейте Хр\'нглса Заблудшего.', 'Я вижу, что по всему болоту морские жители ведут себя странно. Ну, с мурлоками понятно, но были ведь еще жаблины и макруры... На днях я даже видела на берегу наг.$B$BЧто-то притягивает их сюда и доводит до исступления. Оно манит их сюда все неотвратимее с каждым днем... Там что-то есть, теперь я абсолютно уверена, и если так будет продолжаться, мы сами вскоре туда безвольно поплетемся...$B$BТы $gдолжен:должна; положить этому конец – что бы это ни было.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27758, 'ruRU', 'Плотник', 'Одолейте Хеликса Отломчикса.', '<Пшш-ш-ш...>$B$BПрием! Как слышно? Отлично!$B$BПохоже, Хеликс отвечает за постройку гигантской мачты. Не кажется ли тебе, что они хотят достроить исполинский корабль Братства?$B$BЛучше всего пойти туда и выяснить, $n. И не бойся замарать руки! У тебя карт-бланш на применение грубой силы при необходимости – а применять ее наверняка придется, $gсам:сама; понимаешь.', '', 'Он часто разъезжает на свирепом Болванчике.', 'Хеликс Отломчикс', 'Наконец картинка начинает складываться.', 'Лейтенант Горацио Лейн', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27760, 'ruRU', 'Искусственный интеллект', 'Поговорите с терминалом АИДА на Заставе исследователей в Ульдуме.', '<Из портативного терминала раздается женский голос.>$B$BАварийный код: 55-729.$B$BУ членов экспедиции нарушено нормальное функционирование коры головного мозга.$B$BПроследуйте к ближайшей к вам терминальной установке, расположенной к юго-востоку от Террасы Солнечного Камня, для проведения дальнейших анализов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27761, 'ruRU', 'Отвлечь и обезвредить', 'Обезвредьте первую, вторую и третью бомбовые кассеты и деактивируйте 4 неустойчивых бомбота у гробницы Солнечного короля.', 'Проклятие поразило всю нервную систему членов экспедиции, но мои расчеты показывают, что у нас еще есть возможность воздействовать на их подсознание. Необходимо с помощью реалистичных образов оживить их фантазии из подросткового возраста.$B$BВоспользуйся этим голографическим проектором, чтобы отвлечь их.$B$BОни сейчас устанавливают заряды у гробницы, что к востоку отсюда. Хотят проникнуть в тайные ходы Ульдума.$B$BИх цель – прибрать к рукам технологии перерождения, скрытые под Ульдумом. Этого нельзя допустить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27762, 'ruRU', 'Фюзель, йо-хо-хо!', 'Долетите на ракете \"Безупречность\" до Бесплодных земель, после чего поговорите с Эдди Выпшиком.', 'Эй, |3-6($r)! У меня для тебя есть работенка, от которой невозможно отказаться.$b$bНас сюда прислали из Фюзеля, что в Бесплодных землях. Там можно нереально разбогатеть. Именно так, $gдруг мой:душа моя;. Да и зомби там не так много, и заносчивые рыцари Серебряного Авангарда не мельтешат перед глазами.$b$bЭто просто дикое место, и мы ищем кого-то, кто поможет нам его обустроить. Как будешь $gготов:готова; отправиться, дай нам знать.', '', '', '', '', '', 'Поговорите с Эдди Выпшиком в Фюзеле-на-водах, в что в Бесплодных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (27763, 'ruRU', 'В Фюзель!', 'С помощью транспортера на окраине Фюзеля-на-водах перенеситесь наверх, а затем доложите о своем прибытии Дольфу Дымсту в Фюзеле, что в Бесплодных землях.', 'Поистине волшебное местечко, |3-6($r)! Мне всегда хотелось жить в тихом славном городке у моря и заниматься своими взрывами безо всяких помех.$B$BНу, тишина-то – она не для всех, конечно... Взять вот хоть героев вроде тебя.$B$BМы установили транспортер на пригорке рядом с городом, он перенесет тебя на вершину хребта. Оттуда ты сможешь быстро добраться на запад – до Фюзеля, что в Бесплодных землях.$B$BТам дельце по тебе найдется. Скажи, что ты от Пшика.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27764, 'ruRU', 'Необычная просьба', 'Доставьте посылку Дольфа Рее в долину Летлор в Бесплодных землях.', 'Теперь о других делах. Мне тут нужно доставить кое-что.$B$BНе так давно в нашем городе появилась одна юная дама, она искала прессованный порох, закаленную мифриловую оболочку для бомбы и защитные очки. Конечно, пороха и оболочек для бомбы у нас было сколько хочешь, а вот отыскать защитные очки оказалось сложнее.$B$BКороче говоря, очки у меня, но дамочка уже вернулась к своим изысканиям в долине Летлор. Отнесешь ей посылку?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27765, 'ruRU', 'Первый образец: украденные яйца', 'Добудьте 6 яиц дикого черного дракона.', 'Я экспериментирую с черными драконами. А конкретно – меня интересует, как они размножаются.$B$BМои нынешние опыты требуют множества драконьих яиц, потому я и нахожусь здесь, в долине Летлор. Я бы и сама занялась сбором яиц, но, думаю, ты извлечешь пользу из помощи мне.$B$BКладок много на краю долины. Однако остерегайся стражей, кружащих в небе, – им очень не нравится, когда воруют яйца.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27766, 'ruRU', 'Второй образец: детеныши драконов', 'Добудьте 10 тел обжигающих дракончиков.', 'Хочу попросить тебя еще об одном одолжении. Мне нужны тела черных дракончиков, летающих тут неподалеку. Убей их, а трупики принеси мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27768, 'ruRU', 'Шаг второй: кровопускатель', 'Убейте Гомору Кровопускателя на бойне.', 'По вине троллей мои братья гибнут в непрекращающихся кошмарах. Тролли отравляют и порабощают зеленых драконов кровью своего мерзкого божества, а затем пожинают плоды того зла, что проросло в них. Моих собратьев разводят, как скот...$B$BЭта дичайшая мерзость должна прекратиться. Возвращайся к выходу из Зала Масок и следуй другим коридором в сторону бойни. Там Гомора Кровопускатель собирает трупы для отвратительных темных ритуалов. Возьми его жизнь – он ее не заслуживает!', '', 'Когда он решил вредить моим собратьям, он подписал себе смертный приговор.', 'Гомора Кровопускатель', 'Камень клятвы связывает нас.', 'Лорд Итар', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27769, 'ruRU', 'Рея срывает маску', 'Узнайте, кто такая Рея на самом деле.', 'Как я уже говорила, я не обычный гоблин. Может быть, ты уже $gдогадался:догадалась;, каков мой истинный облик.$B$BПозволь показать тебе мое настоящее лицо. Поскольку ты $gдоказал:доказала;, что тебе можно доверять, я поделюсь с тобой и подробностями своего плана.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27770, 'ruRU', 'Откровение', 'Узрите последний предмет исследований Реа.', 'Когда-то род черных драконов был благородным. Это были стражи земли, хранители земель. Какая ирония судьбы: они стали самой жуткой напастью, которую только видели эти земли.$B$BОднако я думаю, есть еще лучик надежды, и так же считает моя повелительница. Черные драконы выживут, несмотря на предательство Смертокрыла, и вновь прославятся как благородные хранители земли.$B$BЯ хочу кое-что тебе показать. Закрой глаза.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27771, 'ruRU', 'Третий образец: яйца Никсондры', 'Добудьте 3 яйца Никсондры.', 'Никсондру удерживают против ее воли. Она скрыта от своего потомства в самом центре гнезда. Она откладывает яйца, но их отбирают у нее прежде, чем вылупляются дракончики.$B$BЖестоко? Возможно. Но даже и наполовину не так жестоко, как обошелся ее род с моей повелительницей.$B$BДокажи, что я могу доверять тебе, $n. Возьми яйца Никсондры и принеси мне. Чтобы отобрать яйца, тебе придется силой заставить Никсондру подчиниться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27772, 'ruRU', 'Почтенный доктор Блам', 'Принесите биологический материал черных драконов доктору Иерониму Бламу в Удел Эгмонда в Бесплодные земли.', 'Я неспроста открыла тебе правду о себе, $n. Мне нужно было завоевать твое доверие, но больше я не могу оставаться в долине Летлор, поскольку мое инкогнито раскрыто.$B$BОднако тебе, возможно, удастся ускользнуть незаметно. Вот, возьми результаты наших исследований и отнеси их на запад. В Уделе Эгмонда найди гнома, который знает, что делать с этими образцами.$B$BИ поторопись, $n! Не стоит задерживаться здесь дольше необходимого.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27773, 'ruRU', 'Шаг третий: пророк', 'Победите Джаммал\'ана Пророка.', 'Единственный, кто по-прежнему мешает мне войти в храм, – сам Джаммал\'ан Пророк. Этот мерзкий манипулятор – вождь троллей Атал\'ай. $B$BЗнай, $n, что тебе противостоит не обычный свихнувшийся тролль. Им управляет зло, которое ты вряд ли можешь себе представить. Но ты сражаешься не в одиночку: моя сила и воля зеленых драконов всегда с тобой.$B$BИди же в зал Взывающего, налево через Ритуальный зал, а затем спустись в зал Костей. В самом низу ты найдешь Джаммал\'ана.', '', 'Вождь Атал\'ай.', 'Джаммал\'ан Пророк', 'Камень клятвы связывает нас.', 'Лорд Итар', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27774, 'ruRU', 'Легко поддающиеся внушению', 'Убейте 9 огров из клана Гнилобрюхих в лагере Кош.', 'Самую непосредственную угрозу для Фюзеля представляет, бесспорно, колония огров на северо-западе.$B$BБольшинство этих огров некогда были обычными воинами, но теперь многие из них занимаются магией. А мне не нужны огры-маги прямо под боком.$B$BПойди и грохни нескольких Гнилобрюхих. Думаю, они сообразят, что к чему, и не станут испытывать силу Фюзеля.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27775, 'ruRU', 'Когда прижмет, можно и схитрить', 'Добудьте трость у наставника магов из клана Гнилобрюхих в лагере Кош.', 'Я уже целую вечность работаю над этим изобретением! А все никак не получается!$B$BВот оно, решение, – подумалось мне. Схитрю и прибегну к магии.$B$BДля моего изобретения требуется поршень, достаточно тонкий, чтобы влезть в узкую медную трубу, но в то же время крепкий, чтобы не ломался. Трости, которыми вооружены огры-маги, обитающие к северу отсюда, отлично подойдут.$B$BИ, по-моему, только у наставников достаточно крепкие экземпляры.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27776, 'ruRU', 'Пусти козла в город...', 'Ткните 12 козлов шокером Гарианны в Фюзеле.', 'У нас тут неприятности... с козлами, если ты еще не $gзаметил:заметила;. Они жрут все подряд и повадились, кажется, закусывать шестеренками и всякими детальками, которые мы тут грудами сваливаем.$B$BНадоело уже, знаешь ли.$B$BБольшинство козлов бродит на окраине городка, возле края утеса. Дай им небольшого \"тычка\"... вот этим приспособлением.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27777, 'ruRU', 'Коды доступа к ядру', 'Раздобудьте коды доступа к ядру у Торсиона Безумного.', 'Число членов экспедиции весьма велико, пользователь $n.$B$BЧтобы справиться с ними обычными методами, тебе понадобится приблизительно 2700136 с половиной часов.$B$BМы можем воспользоваться мощным источником энергии, содержащимся в машине-крабе из арсенала самой экспедиции.$B$BДля этого нам понадобятся коды доступа к ядру синтеза.$B$BУ Анжинера Торсиона есть эти коды. Его можно найти у башни Звездного Дозора, что к юго-востоку отсюда.$B$BВ это шифровальное устройство загружен вирус. С помощью него ты сможешь на время отключить систему защиты Торсиона.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27778, 'ruRU', 'Взлом \"Вибсона\"', 'Взломайте вычислитель \"Вибсон\", установленный на борту \"Водолаза\".', 'Это правда. Морем прибыли новые экспедиционные отряды.$B$BМои сканеры показывают, что они уже подпали под действие феномена проклятия.$B$BТебе нужно как можно скорее попасть на борт МАК \"Водолаз\". Коды доступа позволят нам получить контроль над функциями ядра синтеза, но перед этим придется взломать систему безопасности.$B$BПользователь $n, я должна попросить тебя провести взлом вычислителя с очень сложной структурой – он известен под названием \"Вибсон\".$B$BНе волнуйся, я снабжу тебя подробными инструкциями.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27779, 'ruRU', 'Гномоцид', 'Уничтожьте 1000 безумных гномов.', 'Я загрузила программу в ядро синтеза, и сейчас оно полностью под моим контролем.$B$BТам я создала небольшой воздушный карман, чтобы пользователь $n не $gизжарился:изжарилась;.$B$BЯ обездвижу себя, чтобы можно было посвятить мою тактовую частоту поддержанию ядра в стабильном состоянии.$B$BОтправляйся вниз по склону и нейтрализуй как можно большее число членов экспедиции.$B$BМои анализаторы показывают, что ты можешь начать испытывать чувство... \"вины\" из-за столь многочисленных жертв.$B$BПользователь $n, заверяю тебя, все члены экспедиции абсолютно безнадежны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27781, 'ruRU', 'Машинации', 'Уничтожьте Врагорез-5000.', '<Пшш-ш-ш...>$B$B<Пшш-ш-ш...>Прие-ем! $n, ты на связи? $GЦел:Цела;? Прием!$B$BХвала богам, ты на связи! Какого, во имя Лордерона, они там строят?! Это же механическое чудище какое-то! Не дай им доделать эту... эту... штуку!$B$BВсе правила долой, делай все, что считаешь нужным, только помешай им!', '', 'Не дай им достроить эту... штуковину!', 'Врагорез-5000', 'Лучше действуй исподтишка!', 'Лейтенант Горацио Лейн', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27782, 'ruRU', 'К Матиасу! Срочно!', 'Поговорите с мастером Матиасом Шоу в Сумеречной крепости в Сумеречном нагорье.', 'Мы с тобой замечательно повеселились. Жаль, что тебе пора уходить. Но Матиас сказал, ты ему $gнужен:нужна;.$B$BОн говорит, это срочно!$B$BВозьмешь с собой что-нибудь на дорожку? Ну, там выпить-закусить...', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27783, 'ruRU', 'К Гароне! Срочно!', 'Поговорите с Гароной Полуорчихой в Сумеречной крепости в Сумеречном нагорье.', 'Мы с тобой замечательно повеселились. Жаль, что тебе пора уходить. Но Гарона сказала, что ты ей $gнужен:нужна;.$B$BГоворит, это срочно!$B$BВозьмешь с собой что-нибудь на дорожку? Ну, там выпить-закусить...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27784, 'ruRU', 'Молот Сумерек', 'Доберитесь до Молота Сумерек.', 'Пока тебя не было, я все-таки вычислил, где находится Молот Сумерек. Его выковали на Сумеречном алтаре, что к югу отсюда.$B$BПричем они совершили ошибку – я бы даже сказал, роковую ошибку: Чо\'Галл лично присутствовал при создании Молота на последнем этапе.$B$BЭти сведения достались нам дорогой ценой. Многие наши разведчики погибли.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27785, 'ruRU', 'Адмирал', 'Убейте адмирала Терзающего Рева.', '<Пшш-ш-ш...>$B$BНевероятно... Они его почти отстроили заново! Времени в обрез, $n.$B$BАдмирал Терзающий Рев – правая рука Ванессы – должен быть на палубе. Нам ни за что до нее не добраться, пока он жив. Тебе придется взойти на недостроенный корабль-исполин, найти Терзающего Рева и избавиться от него, чтобы мы могли проникнуть на верхнюю палубу в каюту Ванессы.$B$BБудь $gосторожен:осторожна;: на адмирале лежит проклятье воргенов, и он с удовольствием проверит на тебе остроту своих клыков!', '', 'Приближайся с осторожностью!', 'Адмирал Терзающий Рев', 'Ну, вот и все.', 'Лейтенант Горацио Лейн', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27786, 'ruRU', 'Молот Сумерек', 'Доберитесь до Молота Сумерек.', 'Пока тебя не было, я все-таки вычислила, где находится Молот Сумерек. Его создали на Сумеречном алтаре, что к югу отсюда.$B$BПричем они совершили ошибку – я бы даже сказала, роковую ошибку: Чо\'Галл лично присутствовал при создании Молота на последнем этапе.$B$B<Гарона начинает точить мечи.>$B$BМногие кор\'кроны расстались с жизнью, чтобы добыть эти сведения.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27787, 'ruRU', 'Дробитель Черепов Горобраз', 'Постарайтесь уцелеть и убейте Дробителя Черепов Горобраза.', 'Это была ловушка! Чо\'Галл заманил вас сюда, используя Молот Сумерек как приманку. Он был уверен, что гронн прикончит вас с первого же удара.$B$BВы должны уцелеть и убить Дробителя Черепов Горобраза!', '', '', 'Дробитель Черепов Горобраз', '', '', 'Поговорите с Курдраном Громовым Молотом в Лагере Победителя на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27788, 'ruRU', 'Дробитель Черепов Горобраз', 'Постарайтесь уцелеть и убейте Дробителя Черепов Горобраза.', 'Это была ловушка! Чо\'Галл заманил тебя сюда, используя Молот Сумерек как приманку. Он был уверен, что гронн прикончит тебя с первого же удара.$B$BТы $gдолжен:должна; уцелеть и убить Дробителя Черепов Горобраза!', '', 'Вали его!', 'Дробитель Черепов Горобраз', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27789, 'ruRU', 'По троггам – из турели', 'Займите место за уничтожающей турелью и сумейте пережить 4 атаки троггов.', 'Мне потребуется немного времени для анализа образцов, а также отдых от утомительного отстрела троггов. Давай, вставай за одну из турелей и убей троггов, сколько сможешь. А я тут пока поработаю.$B$BТурель действует двояко: есть обычный выстрел, а есть с электроперегрузкой, когда враги наваливаются кучей. Хе-хе... Ну, удачи тебе.$B$BИ, кстати, берегись больших и неповоротливых троггов. Если они окажутся поблизости, тебе, пожалуй, не поздоровится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27790, 'ruRU', 'Главарь Братства Справедливости', 'Убейте главаря Братства Справедливости.', 'Привет, $n. Я о тебе изрядно наслышан. Слушай сюда, в этом деле у тебя всего одна попытка.$B$BНовоиспеченная атаманша Братства Справедливости наверняка сидит в хижине и руководит всей операцией. Ты $gдолжен:должна; проникнуть туда и убрать ее – ради сотен невинных людей, которых держала в страхе и убивала эта шайка, собранная еще отцом нынешней атаманши.$B$BПоразительно, как эта бандитка подпустила тебя так близко и вообще не залегла на дно до лучших времен. Похоже, нам везет.', '', 'Братству конец.', 'Мастер Матиас Шоу', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27791, 'ruRU', 'Раскопки Пыльного Ветра', 'Поговорите со старшим геологом Дардином у Раскопок Пыльного Ветра, что в Бесплодных землях.', 'Есть у меня одна мысль... но это явный выстрел наудачу. К счастью, выстрелы наудачу – мой конек.$B$BК северу отсюда Лига исследователей обнаружила еще один комплекс руин титанов. Если на этом свете и есть кто старше и мудрее драконов, так именно титаны. Слыхал я даже, будто титаны-то и СОЗДАЛИ драконов!$B$BПоговори со старшим геологом Дардином в его лагере к северу отсюда. У него информации о титанах больше, чем у меня.$B$BНу, что я тебе говорил? Стреляй наудачу, и удача придет!', '', '', '', '', '', 'Доложите о своем прибытии старшему геологу Дардину на Раскопках Пыльного Ветра, что в Бесплодных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (27792, 'ruRU', 'На войне, в любви и археологии все средства хороши!', 'Добудьте разбитую чашу, пыльную вазу, иероглиф земли и орудие троггов.', 'Так-так, давай-ка обо всем по порядку. Я не собираюсь рассиживаться тут и рассказывать обо всем, что мы обнаружили в этих руинах. У нас тут полно неприятностей!$B$BХуже всего – эти выскочки, хулиганы из Реликвария, орудующие на той стороне гробницы. Они утаскивают все наши находки! Как будто не знают, что копаться в руинах – призвание дворфов.$B$BПотряси-ка их \"археологов\" – как по мне, так имя \"бандиты\" им бы больше подошло – и верни мне драгоценные артефакты.$B$BА уж ПОТОМ поговорим о титанах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27793, 'ruRU', 'Древние защитники', 'Внимательно осмотрите Стража и Часового.', 'В центральном зале гробницы раздается нешуточный грохот. Все-таки что-то с теми огромными статуями неладно...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27794, 'ruRU', 'Возвращение к Бламу', 'Отнесите Око стражей доктору Иерониму Бламу в Удел Эгмонда в Бесплодных землях.', 'В сундуке на подушечке лежит небольшой округлый предмет.$B$BЕсли в этой гробнице и есть артефакты титанов, то это точно один из них. Вы решаете отнести его доктору Бламу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27795, 'ruRU', 'Силы тьмы', 'Убейте 6 огров Каменора.', 'Все идет по плану. Их воины на грани истощения, и я послала в бой кавалерию.$B$BНо вот кого я не ждала, так это огров. Наши рыцари по силе не уступают этим дикарям, однако помощь им не помешает.$B$BТы снова $gнужен:нужна; мне на поле боя, $n. Немногие способны одолеть здорового огра, но на тебя я могу рассчитывать. Не подведи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27796, 'ruRU', 'Пешка-страж', 'Выясните, для чего нужна пешка-страж в Гробнице Стражей в Бесплодных землях.', 'Когда эти деятели из Реликвария сюда заявились, мы задергались и стали выкапывать все без разбора.$B$BПечальный это был день для археологии.$B$BК счастью, Ольге удалось наткнуться вот на эту нефритовую статуэтку. Нам кажется, это своего рода ключ, но мы не можем понять, что он открывает. Может быть, тебе повезет больше?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27797, 'ruRU', 'Пешка-часовой', 'Выясните, для чего нужна пешка-часовой в Гробнице Стражей в Бесплодных землях.', 'Статуэтку чуть было не стащили у нас эти бездельники из Реликвария Кровавого Взора. Нам удалось поймать их с поличным, мы вернули статуэтку, но это мало чем помогло.$B$BПохоже, статуэтка является своеобразным ключом, но никаких замков я в этих руинах не вижу. Не хочешь попробовать поискать?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27798, 'ruRU', 'Живая вода', 'Расспросите труп начальника кузни Финлея, вернув ему подобие жизни с помощью живой воды.', 'Возьми мою живую воду и влей ее в рот утонувшего дворфа.$B$BПри жизни он был кузнецом и работал с металлом, и хотя он уже мертв, вода вернет ему на время подобие жизни, и ты сможешь его расспросить и узнать все, что тебе нужно.$B$BА потом уходи из моих владений.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27803, 'ruRU', 'Им надо выспаться', 'Убейте 8 порабощенных поджигателей.', 'Мои ребята держат линию обороны по всему периметру поселка, отбивая атаки элементалей, которые все прут и прут из развороченной земли. Они хорошие воины, сильные и выносливые. И пока что они еще держатся. Но даже самого крепкого дворфа со временем одолевает усталость.$B$BИх разделили на смены: один час на боевом посту, затем один час сна. Я понимаю, что этого мало. Но у нас не хватает бойцов.$B$BЕсли хочешь помочь, отправляйся на линию обороны и смени там кого-то из наших. Пусть хоть кто-нибудь поспит подольше. Возвращайся с докладом, когда убьешь... ну, хотя бы несколько элементалей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27804, 'ruRU', 'Это наш дом', 'Потушите 50 очагов возгорания в Дозоре Огнебородов.', 'Нас уже оттеснили гораздо дальше, чем я мог предвидеть, но это не значит, что мы отдадим этим мерзавцам свои дома. Их могут жечь, ломать и грабить... Но даже если от них не останется камня на камне, мы все равно будем сражаться. Это наш дом, и мы никому его не отдадим!$B$BКстати, раз мы об этом заговорили... все-таки очень не хочется, чтобы наши дома сгорели. Мои парни сейчас как раз тушат пожары. Если захочешь помочь, они могут передавать тебе ведра по цепочке, и тебе не придется бегать к колодцу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27805, 'ruRU', 'Хоть какое-то утешение', 'Разыщите засохшие розы Меары, молот Парлана из бивневой кости и куклу Априки, а затем верните все вещи их владельцам.', 'А ты, как я понимаю, и есть $gтот самый новенький:та самая новенькая;, кто помогает Кигану? Очень рада с тобой познакомиться. А можно тебя попросить сделать доброе дело для наших беженцев?$B$BНам пришлось быстро сниматься с места, бросить дома и имущество, в том числе разные дорогие сердцу мелочи. Ты все равно отправляешься в те края... Может, когда соберешься обратно, захватишь с собой наши вещи? И нам будет хотя бы какое-то утешение.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27806, 'ruRU', 'Почетная ноша', 'Поговорите с Иэном Огнебородом на Кладбище Огнебородов.', 'Иэн, мой первый помощник, перевозил тело одного из наших павших бойцов на запад в собор. Я поручил ему собрать вместе разрозненные остатки отряда всадников на грифонах. И ты будешь ему помогать.$B$BЯ хочу, чтобы ты хорошо $gпонимал:понимала; – дело не терпит отлагательств. Долго мы здесь не продержимся. В конце концов нас разобьют либо фанатики Сумеречного Молота, либо орки Драконьей Пасти. И боевой отряд всадников на грифонах – наша единственная надежда. Иными словами, это вопрос жизни и смерти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27807, 'ruRU', 'Клан Муллана', 'Поговорите с Дугласом Мулланом у Горнила Крови.', 'Если мы хотим сформировать отряд всадников на грифонах, нам надо быстрее собирать уцелевших бойцов, пока они не погибли или не покинули эти края. У меня уже есть на примете несколько групп всадников, наших давних союзников. В ближайшее время я отправляюсь на поиски всадников Громтара и всадников Мура.$B$BКогда я в последний раз видел воинов клана Муллана, они направлялись на запад, к Горнилу Крови. Следуй туда и попробуй уговорить Дугласа Муллана поступить на службу к Кигану. А уж Киган в долгу не останется.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27808, 'ruRU', 'Упрямый, как Дойл', 'Поговорите с Киландом Дойлом в лесу Нагорья.', 'В последний раз всадников Дойла видели на юге, на краю Обсидианового леса. Воины Дойла – упрямые и несговорчивые ребята, так что тебе надо будет как следует постараться, чтобы уговорить их присоединиться к нам.$B$BНо я, кажется, знаю один убедительный аргумент. Скажи Киланду Дойлу, что среди беженцев, укрывшихся в городе, есть и Кайлин Лонгфелло. Киланд давно по ней сохнет, и, быть может, присутствие Кайлин сподвигнет его привести к нам своих бойцов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27809, 'ruRU', 'Надо их поторопить', 'Поговорите с Маккеем Огнебородом в военном лагере Горшака.', 'Теперь мне нужно, чтобы ты $gразыскал:разыскала; Маккея и его людей на той стороне Ненасытного Пролома, в военном лагере Горшака.$B$BХваленые воины Драконьей Пасти доблестно проиграли первый же бой, и Маккей сейчас обыскивает их лагерь и собирает оружие, провизию, экипировку – все, что может нам пригодиться. В общем-то они сами прекрасно справляются, но слишком долго там возятся. Видимо, много набрали добра. Пока его все запакуешь... В общем, ты их поторопи и помоги.$B$BМожно даже пинками. Но по возможности вежливо. Короче, задачу ты $gпонял:поняла;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27810, 'ruRU', 'Испытание боем', 'Вызовите на бой и победите одного из наездников на грифоне Муллана.', 'Киган хочет, чтобы всадники Муллана присоединились к его отряду? Ну, что ж... Если в мире есть дворф, ради которого я согласен подняться в воздух, так это он и никто другой! Мне только одно непонятно – с какой такой радости он прислал ко мне для таких важных переговоров $gкакого-то чужака:какую-то постороннюю барышню;. Это не очень-то вежливо, мне кажется.$B$BУверен, любой из моих ребят уделает тебя за 20 секунд, что за чаркой вина, что на поле брани. Давай вот как поступим: если ты победишь в драке кого-то из моих парней, я подумаю над предложением Кигана.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27811, 'ruRU', 'Запах битвы', 'Разыщите 8 грифонов Муллана и отправьте их обратно к наездникам.', 'Пусть тебя не обманывает несговорчивость Дугласа. Наездники Муллана истосковались по полетам и рвутся в бой, и если есть в мире кто-то, ради кого мы поднимемся в воздух, так это Огнебород.$B$BМы оставили наших грифонов в лесу нагорья к югу отсюда, чтобы они поохотились и отдохнули от грохота битвы. Они заслужили отдых.$B$BЕсли хочешь, чтобы мы быстрее вступили в сражение, помоги привести наших грифонов обратно.$B$BВот возьми – это обуглившаяся высокогорная береза. Нужна для тренировки грифонов. Как только грифоны почуют этот запах, то сразу вернутся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27812, 'ruRU', 'Верность клана Муллана', 'Возвращайтесь к Иэну Огнебороду на Кладбище Огнебородов с известием о решении клана Муллана.', 'Ты нас $gубедил:убедила;. Передай Кигану, что он может на нас рассчитывать. Мы придем в город сразу, как все соберутся.$B$BА ты молодец. $GСилен:Сильна; – почти как бойцы Громового Молота. Уж не знаю, откуда ты родом, но, похоже, народ у вас крепкий.$B$BВпрочем, я еще не видел, как ты пьешь. Вот это будет уже настоящее испытание.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27813, 'ruRU', 'Смерть Драконьей Пасти!', 'Убейте 6 бойцов из клана Драконьей Пасти.', 'Бойцы Сумеречного Молота взяли город и перебили почти всех представителей клана Драконьей Пасти, которые здесь жили. Но кое-кто все-таки уцелел. И они недовольны, что мы забираем себе их припасы.$B$BСобственно, это не слишком большое горе.$B$BНо я все равно не хочу, чтобы они нападали на наших ребят. Сделай так, чтобы их здесь не было! Меня не волнует, убьешь ты их или прогонишь. Мне важен результат.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27814, 'ruRU', 'Перекованные мечи', 'Принесите 8 мечей Драконьей Пасти Брому Кузнецкому Молоту в военный лагерь Горшака.', 'Сидеть дома, ковать оружие? Ха! Кузнецкий Молот никогда не боялся хорошей драки! И потом, кто сказал, что оружие надо ковать в безопасном тылу? Тем более здесь целые горы сырья. Это оружие Драконьей Пасти, оно никуда не годится. Но можно его переплавить и выковать нормальные мечи. Принеси-ка мне 8 мечей Драконьей Пасти, и мы с дочкой сделаем из них настоящее оружие!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27815, 'ruRU', 'Подарок для Иэна Огнеборода', 'Отнесите оружие Кузнецкого Молота Иэну Огнебороду на Кладбище Огнебородов.', '$GПомог:Помогла; ребятам в лагере Горшака и $gвыполнил:выполнила; поручение Кузнецкого Молота? Очень даже неплохо для $gхудосочного:хиленькой:c; |3-1($c). Вот, отнеси эти мечи Иэну на Кладбище Огнебородов. Он тебя наградит за хорошую службу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27816, 'ruRU', 'Личный отчет', 'Поговорите с Киганом Огнебородом в Дозоре Огнебородов.', 'Жалко Дойла. И ребят его жалко. Хорошие были бойцы. Мы и сами-то уцелели лишь чудом. А им, видишь, не повезло.$B$BА эти жалкие трусы из Громтара поджали хвосты и сидят у себя в городишке, носа оттуда не кажут. Даже когда им сказали, что их призывает Киган, они все равно не пошли. Зато с нами Муры, а они одни стоят трех кланов.$B$BКиган хотел переговорить с тобой лично, когда ты вернешься. Так что давай отправляйся к нему. Он где-то в городе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27817, 'ruRU', 'Удар Молота', 'Садитесь на одного из грифонов в Дозоре Огнебродов и убейте 12 сумеречных штормовержцев и Сервиаса Ветряного Ужаса.', 'Благодаря тебе и Иэну у нас набралось столько всадников, что теперь мы уж точно сможем дать отпор Сумеречному Молоту.$B$BМы умеем сражаться в полете, но когда второй всадник использует Молот бури, бой идет эффективнее. Я тут подумал... ты ведь наверняка рвешься в битву.$B$BДавай выбирай себе грифона – и вперед. И тебе лучше поторопиться. В ближайший час-полтора мы рассчитываем перебить всех сумеречных на этих летающих скалах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27818, 'ruRU', 'Скользкие знаки', 'Соберите 5 нетронутых сердец змеев в Вязкой топи.', 'Я здесь обосновалась задолго до появления Веслотопи – хотела варить свои настои в мире и покое. Знаю эту трясину как три своих старых сморщенных пальца.$B$BСо здешней фауной недавно произошли перемены. Пресмыкающиеся, которые тебе, должно быть, встречались под Вязкой топью, – это крылатые змеи, таких здесь не было испокон веков.$B$BИз них можно добыть отменные ингредиенты, если это те самые змеи. Будь душкой, набери мне их сердец.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27819, 'ruRU', 'TEST - RVM', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27821, 'ruRU', 'Орки и люди', 'Убейте 8 воинов Каменора.', 'С учетом того, что весь мир погряз в войне, меньше всего хотелось бы иметь поселение орков прямо у нас под боком. Красногорье, Сумеречный лес, даже Элвиннский лес – в дневном переходе отсюда.$B$BМы уже нанесли первый удар, и я не собираюсь позволять Орде перевести дух. Поэтому считай, что ты уже на задании. Хватай оружие, присоединяйся к основным силам в Кровавой топи и начинай охоту на орков.$B$BДоложи, когда нанесешь им достаточный ущерб. И возвращайся $gживым:живой;... это приказ. Вольно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27822, 'ruRU', 'Лес рубят – щепки летят', 'Убейте 5 батраков Каменора.', 'Я хочу обеспечить полную победу. Иметь перевес в ресурсах недостаточно – нужно сделать так, чтобы врагу не досталось вообще ничего.$B$BКаменор зависит от древесины, которую добывают в окрестных лесах. Орочьи батраки на лесопилке, может быть, и не воины, но ненавидят людей не меньше.$B$BНе щади никого. Нужно перебить батраков и прервать поставки древесины в Каменор.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27823, 'ruRU', 'У дворфов – свои нужды', 'Раздобудьте 15 кружек \"Сумеречного крепкого\".', 'Поверь, мне хорошие раскопки по душе, как и любому дворфу. Просто... мы тут так много копаем и так мало пьем, что иногда я подумываю: а не поставить ли лопату в угол и не вернуться ли в старый добрый Стальгорн?$B$BНо только не сегодня. У меня здесь еще дельце осталось.$B$BДворфы из клана Черного Железа с карьера Тяжелоступа – неподалеку, к северу отсюда – варят крепкое и славное пиво, да-да, прямо здесь, в пустыне. Не принесешь мне кружечку-другую?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27824, 'ruRU', 'За сокровищем – с кулаками', 'Поищите сокровище на нижнем уровне крепости Ангор.', 'Есть у меня к тебе одно предложеньице – если ты, конечно, не против.$B$BДворфы Черного Железа ошивались тут еще до того, как прибыл Дардин со своими ребятами. А значит, как только руины титанов открылись, они – оба-на, тут как тут! – и все самое ценное сразу заграбастали. Бьюсь об заклад, в крепости Ангор на северо-западе у них еще полно сокровищ.$B$BТы уже $gдоказал, что способен:доказала, что способна; задать перцу дворфу. Вот и иди в крепость – проложи путь к сокровищу титанов.$B$BЯ бы и сам с тобой пошел, да вот пьян что-то сильно...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27825, 'ruRU', 'Выживает жирнейший', 'Добудьте 6 порций мясного провианта и 10 отрезов шелка клана Гнилобрюхих.', 'Припасов у нас – кот наплакал... Черные драконы разоряют наши охотничьи угодья, и нам негде раздобыть пропитание.$B$BЗато у огров на юге есть все, что нам нужно. В их пещере ты найдешь вдоволь запасов мяса и ремесленного сырья.$B$BОгры наверняка так просто все это не отдадут, поэтому будь начеку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27826, 'ruRU', 'Дорога в Драконью Пасть', 'Отнесите очищенное от скверны яйцо черного дракона Рее в Драконью Пасть, что в Бесплодных землях.', '<Доктор Блам смотрит на яйцевидный предмет в немом изумлении, моргает, словно не веря своим глазам, затем переводит взгляд на вас.>$B$BТы... ты это $gвидел:видела;? Невероятно! Мои догадки о титанах подтвердились! С твоей помощью, конечно.$B$BНадо отнести все это Рее. Она покинула долину Летлор. Еще бы! Пришлось – когда она трансформировалась в свою истинную форму прямо на глазах у дракончиков. Рея остановилась на западе, в лагере Альянса под названием Драконья Пасть.$B$BОна будет ждать тебя. Да, вместе с яйцом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27827, 'ruRU', 'Резвый, Лютый и Крепкий', 'Поговорите с Эриком \"Резвым\" в Драконьей Пасти, что в Бесплодных землях.', 'В спешке покидая долину Летлор, я забыла завершить одно дело. Это касается Никсондры. Она на свободе и бросила тревожный клич среди черных драконов. Половина крыла здесь, на западе Бесплодных земель, прочесывает местность в поисках этого яйца.$B$BЯ позабочусь о том, чтобы его спрятать. А ты, пожалуйста, займись самыми опасными драконами. Не без помощи, конечно.$B$BПоговори с Эриком – вон там, на другой стороне лагеря. Он вместе с братьями пойдет с тобой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27828, 'ruRU', 'Эрик, капитан Необходимость', 'Испытайте \"Рывок Эрика\" и карманное зелье Эрика.', 'Прежде чем мы съедем с катушек и займемся уничтожением драконов, давай-ка я расскажу тебе немного, как я обычно дерусь.$B$BМеня называют \"Резвый\", и вот почему: я врубаюсь прямиком во врагов – шлемом вперед, прошу заметить – и оглушаю их на несколько секунд. Для особо сложных ситуаций у меня всегда припасено несколько склянок с зельями$B$BПочему бы нам не попрактиковаться? Давай, выйди в поле и попробуй.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27829, 'ruRU', 'Поход на дракона', 'Одолейте Каларана Уничтожителя и четверых солдат Летящей Тьмы.', 'Приветствую тебя, $n. Я смотрю, вы четверо уже успели познакомиться.$B$BВот тебе первое задание. Каларан, древний и могучий черный дракон, присоединился к охотникам за яйцом, которое мы оберегаем. Его необходимо остановить, прежде чем он подберется слишком близко.$B$BТы найдешь дракона и его приспешников в Знойных Песках, к северо-востоку от Драконьей Пасти. Выследи его и убей. Скорее всего, тебе понадобится помощь твоих новых союзников-дворфов.', '', 'Нужно сразить черного дракона, пока яйцо все еще уязвимо.', 'Реастраза', 'Дело еще не закончено.', 'Реастраза', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27830, 'ruRU', 'Охота продолжается!', 'Победите генерала Жиракку, Молдарра и 6 черных драконоидов.', 'Черная драконья стая знает свое дело. Они заняли большую часть Нового Каргата, крупного поселения Орды к северо-западу от Драконьей Пасти. Войсками командуют генерал Жиракка и его правая рука, Молдарр. Их надо остановить.$B$BМы, драконы, не принимаем участия в этой вашей разборке между Ордой и Альянсом, но я понимаю, чем вы рискуете, отправляясь в Новый Каргат. Прошу вас, герои... будьте осторожны.', '', 'Молдарр и Жиракка командуют основной группировкой черных драконов.', 'Реастраза', 'Главное испытание еще впереди…', 'Реастраза', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27831, 'ruRU', 'Печаль и гнев', 'Убейте Никсондру и 12 ее детенышей.', 'Я бесконечно сожалею о том, как мы... нет, как я обращалась с Никсондрой. Я заставляла ее откладывать яйца и ставила над ними опыты. Снова и снова – без конца.$B$BДаже сама будучи матерью, я с трудом могу представить себе ее горе.$B$BНет... Мне нужно быть сильной. В конце концов, мы стараемся на благо будущих поколений черных драконов. Ее жертва не была напрасной.$B$BОна кружит над руинами Каргата, к северо-западу от Нового Каргата, обезумевшая от ярости. Пожалуйста, герои... избавьте Никсондру от страданий.', '', 'Прости меня, Никсондра…', 'Реастраза', 'Почти готово.', 'Реастраза', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27832, 'ruRU', 'Потайная кладка', 'Поговорите с Реей у Потайной кладки в Бесплодных землях.', 'Теперь, когда большинство черных драконов покинуло Бесплодные земли, переносить яйцо стало безопасно. Я буду на небольшом плато, к северу от Нового Каргата.$B$BИщи меня там.', '', 'Встретимся на севере.', 'Реастраза', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27833, 'ruRU', 'Затяжная оборона', 'Уничтожьте 12 бойцов клана Гнилобрюхих. Можно убивать как извергов, так и шаманов этого клана.', 'Я бы сказал, что у нас тут сложности с драконами, хотя их, похоже, больше интересует Новый Каргат, чем наш скромный лагерь. И все же я отрядил наших лучших ребят сдерживать драконов.$b$bЕсть, правда, кое-что, оставшееся без внимания, – это лагерь огров к юго-западу отсюда. Похоже, из их логова вышла небольшая армия.$b$bМы не можем просто сидеть и ждать, пока они зайдут к нам в тыл, солдат. Сократи их численность – пока они не сократили нашу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27834, 'ruRU', 'Бейлог, капитан Стеклянная Пушка', 'Испытайте выстрел Бейлога и боевой крик Бейлога.', 'Прежде чем я начну забрасывать стрелами этих драконов, позволь представиться.$B$BЯ Бейлог, основная боевая сила этой группы. Мой меч острее зуба кроколиска, а стрелы поют как банши. Правда, мои силы быстро иссякают, я не могу выдержать столько урона, сколько двое моих братьев.$B$BОдно твое слово – и я прицельным выстрелом поражу сердце врага. Также я могу воодушевить своих братьев и дать им силу боевого безумия.$B$BПочему бы нам с тобой не попрактиковаться?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27835, 'ruRU', 'Олаф, капитан Громадина', 'Испытайте \"Глухую защиту Олафа\" и могучий рев Олафа.', 'Ты, может, не $gзаметил:заметила;, но для дворфа я довольно велик.$B$BИ обеспечиваю прикрытие своим братьям, чтобы они не попали в беду. Они мелковаты, и таких здоровых щитов, как у меня, у них нет. А я большой и запросто выдержу удары сразу нескольких чудовищ! К тому же, если не зевать, всегда можно подставить вместо себя щит!$B$BЯ и тебя могу защитить. Давай немного попрактикуемся. Уж я позабочусь, чтобы враги нападали на меня, а не на тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27836, 'ruRU', 'Остановить заразу', 'Уничтожьте 6 яиц ползуна.', 'Недостаточно просто уничтожить тварей, осквернивших воды нашей реки, $n.$B$BВ ее священных водах вот-вот родится новое поколение этих гнусных созданий.$B$BНайди их яйца и тоже уничтожь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27837, 'ruRU', 'Чужаки в воде', 'Убейте 8 ползунов Тихой заводи.', 'Вскоре после того, как пали защитные барьеры Ульдума, река Вир\'наал оказалась заражена какой-то мерзостью.$B$BСейчас уже не важно, произошло это случайно или за этим заражением стояла какая-то злая сила.$B$BИтог в любом случае один. Воды реки стали мутными, и мы больше не можем видеть в них будущее столь же ясно, как прежде.$B$BОглянись вокруг, |3-6($c). Эти мерзостные существа никогда не должны были появиться в чистейших водах нашей реки.$B$BУничтожь их, чтобы в зеркале воды снова появились видения.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27838, 'ruRU', 'Источник заражения', 'Отправляйтесь на северо-восток к истоку реки Вир\'наал и уничтожьте Чешуйчатую прародительницу Хевну.', 'Тебе удалось устранить внешние признаки нашей проблемы, $n. Но я изучил этих тварей и пришел к выводу, что яйца отложены не ими.$B$BВода выносит яйца к запруде, но то существо, которое их откладывает, находится выше по течению.$B$BСтупай на северо-восток к истоку реки и устрани подлинный источник заражения.', '', 'Не будет чешуйчатой прародительницы, не будет яиц.', 'Чешуйчатая прародительница Хевна', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27839, 'ruRU', 'Древнее оружие', 'Верните древнее оружие Тол\'вир.', 'Хотя формально война еще не объявлена, неферсеты без колебаний захватывают в плен и убивают всех, кто осмеливается зайти на их землю.$B$BКороль Фаорис запрещает нам отплатить той же монетой, даже несмотря на то что они тайком вывозят украденные реликвии из гробниц наших предков.$B$BМои разведчики доложили, что неферсеты готовятся перевезти большую партию украденного оружия. Сейчас они к югу отсюда.$B$BЯ приказал работникам, которых ты $gзавербовал:завербовала;, помочь тебе. Вызови их, подув в этот рожок, когда обнаружишь контрабандистов. Вместе вам предстоит вернуть украденное оружие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27840, 'ruRU', 'Кристаллы дренетиста', 'Отыщите 5 кристаллов дренетиста в Болотном Пристанище.', 'Заблудшие, обитающие в Болотном пристанище, на вид как мы, однако они чудовища... лишившиеся разума из-за тягот нашего странствия в Азерот. Некогда наши братья, теперь они живут в Болотном пристанище на западе и нападают на всех, кто окажется поблизости.$B$BЕще они похитили нечто священное для нас – кристаллы дренетиста.$B$BУ нас недостаточно сил, чтобы напасть в Пристанище и вернуть кристаллы. Они лежат вокруг их хижин и костров. Без этих кристаллов... мы тоже можем сбиться с пути.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27842, 'ruRU', 'Это только начало', 'Убейте Глубтока.', 'Порой я тоскую по тем дням, когда легионы могучих огров шли в бой плечом к плечу с воинами Орды – и Альянс содрогался перед их яростью. Возможно, эти славные времена вернутся прежде, чем я уйду к предкам.$B$BНо сейчас не об этом. Огр-маг Глубток присоединился к Братству Справедливости и служит штейгером у них в шахте. Жалкий кретин! Покончи с ним ради меня, а главное – ради чести и славы Орды!', '', 'Так просто он не сдастся.', 'Глубток', 'Враг еще жив!', 'Кагта', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27843, 'ruRU', 'Никакого подкрепления', 'Убейте 3 чернокнижников Каменора.', 'Просто перебить огров недостаточно. На поле боя слишком быстро появляются новые.$B$BТы $gдолжен:должна; проникнуть вглубь за линию фронта и отыскать призывающих. Орки получают подкрепление с помощью чернокнижников.$B$BПеребей чернокнижников – и порталы закроются. Их немного; быстрый и точный удар подорвет силы врага.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27844, 'ruRU', 'Предатели!!!', 'Одолейте Хеликса Отломчикса.', 'Гоблины, работающие на Братство Справедливости, объявлены предателями картеля Трюмных Вод, клана Изувеченной Длани и всей Орды!$B$BУ меня еще не было инициализации в Изувеченной Длани, потому сохранилась и привязанность к своему народу. А у Хеликса Отломчикса, похоже, нет времени на подобные сантименты: он занят изготовлением мачты для корабля-исполина Братства. Не $gмог:могла; бы ты \"избавиться\" от Хеликса ради нас с мисс Кавардак?', '', 'Часто видели верхом на свирепом Болванчике.', 'Хеликс Отломчикс', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27845, 'ruRU', 'Отметить павших', 'Знаменем павших отметьте 7 павших воинов Болотной Воды.', 'Мы забрали больше жизней, чем потеряли сами, и все же урон наш огромен. Слишком многие храбрецы сложили головы в боях за Альянс. Я хочу почтить их память независимо от того, насколько яростное идет сражение.$B$BВозьми эти флаги и поставь их возле каждого павшего, какого увидишь. Заговоры вряд ли обеспечат надежную защиту от осквернения, но это лучше чем ничего. А мне так будет проще издали оценить, скольких мы потеряли.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27847, 'ruRU', 'Немного не то', 'Уничтожьте Врагорез-5000.', 'Я доведу эти прототипы до ума, и они изменят всю военную науку Орды! Но есть некоторое препятствие: указанные в них источники энергии непригодны для сложного маневрирования и крупных конструкций – качеств, которые очень бы пригодились в борьбе с Альянсом.$B$BС помощью предателей-гоблинов вроде Хеликса Братство почти завершило постройку Врагореза-5000, огромного голема, который наверняка будет функционировать!$B$BОб этом никто не должен узнать, понимаешь? Иначе я растеряю клиентов!', '', 'Уничтожь его! Не дай им переманить моих клиентов!', 'Врагорез-5000', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27848, 'ruRU', 'Хотели как лучше, а получилось как всегда', 'Убейте адмирала Терзающего Рева.', 'Братство Справедливости хочет достроить корабль-исполин и основательно потрепать Штормград. Достойная задача, за которую без лишних раздумий взялся бы любой орк!$B$BНо план Ванессы провалился. Корабль построен небрежно, команда неопытная, а хуже всего то, что среди них ворген!$B$BЕго зовут адмирал Терзающий Рев, и во имя нашего вождя его необходимо беспощадно покарать. Лок\'тар огар!', '', 'Приближайся с осторожностью!', 'Адмирал Терзающий Рев', 'Достойный противник.', 'Кагта', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27849, 'ruRU', 'Штурм Каменора', 'Убейте 6 защитников Каменора.', 'Все готово, $n. Мы подошли вплотную к самому Каменору.$B$BДумаю, никому не нужно напоминать об этом, и все же я скажу: мы не орки и не уподобимся им из мести и злобы. Мы не спалим Каменор дотла, чтобы станцевать на пепелище.$B$BНет, поступим по чести. Пусть удар будет точечным. Выше головы – и никакой пощады любому орку, который посмеет взяться за оружие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27850, 'ruRU', 'Главарь Братства Справедливости', 'Убейте главаря Братства Справедливости.', 'Годами Изувеченная Длань не заявляла о себе.$B$BДовольно!$B$BТы станешь символом нашего возрождения, $n. Покончи с атаманшей Братства и экспроприируй ее корабль в пользу Орды! Мы превратим его в настоящее орочье судно и не оставим от Штормграда камня на камне.$B$BСлучайно выжившие разнесут молву о нашей несокрушимой мощи во все уголки Азерота, и всякий склонит голову пред нами!$B$BИди же, смерть ван Клиф станет твоей великой победой.', '', 'Слава Изувеченной Длани!', 'Кагта', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27851, 'ruRU', 'Отобрать пайки', 'Захватите 5 ящиков провианта Каменора.', 'Мы не стерли Каменор в пыль, но я не желаю туда возвращаться.$B$BСобери весь провиант, который найдешь в городе, пока там будешь. Не пройдет и дня, как в отсутствие продовольствия они останутся без бойцов.$B$BЯщики наверняка разбросаны по всему городу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27852, 'ruRU', 'Орки и люди', 'Зарубите 10 солдат Болотной Воды.', 'В топях бушует война, $n. Злобные людишки обосновались к северу от города и привели свою армию прямо к нашему порогу.$B$BВ этих болотах им делать нечего. Они пришли сюда, только чтобы напасть на нас без повода. Но мы не подарим им радость победы!$B$BНам не хватает воинов, и мне на поле боя нужен каждый боеспособный орк. Иди и перебей столько человек, сколько сможешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27853, 'ruRU', 'Лес рубят – щепки летят', 'Убейте 5 крестьян Болотной Воды.', 'У Альянса численное превосходство. По своей трусости они прислали целую армию, чтобы разгромить одно поселение. Но мы не сдадимся без боя!$B$BНе имея ресурсов, их войска потеряют преимущество. Человечьи крестьяне ковыряются в лесу возле Заставы Болотной Воды, заготавливая лес для постройки своих шатких стен.$B$BЛиши их древесины, а заодно и жизни.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27854, 'ruRU', 'Силы тьмы', 'Убейте 6 рыцарей Болотной Воды.', 'Мы несем большие потери, $n. форт Молота Ужаса в Выжженных землях прислал подкрепление из огров, но их немного; и в данную минуту они уже отбиваются от сил Альянса.$B$BАльянс выставил против огров конных рыцарей – эта стратегия хорошо послужила им во Второй войне. Нам нужны сильнейшие бойцы, чтобы переломить ход сражения!$B$BВозвращайся в Кровавую топь, $n, и сокруши этих рыцарей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27855, 'ruRU', 'Никакого подкрепления', 'Убейте 3 магов Болотной Воды.', 'Альянс прислал сюда магов, чтобы те, сидя в крепости, телепортировали подкрепление прямо на поле боя. Мы должны это прекратить!$B$BМагов немного, но один-единственный портал может переломить ход битвы. Напади на их магов и закрой порталы!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27856, 'ruRU', 'Отметить павших', 'Знаменем павших отметьте 7 павших воинов Каменора.', 'Немало воинов полегло во имя нашей победы, $n. Такова судьба истинного орка.$B$BЯ видел, как солдаты Альянса собирают трофеи у наших ушедших бойцов – хватают все подряд, словно крысы. Мы не позволим им осквернять тела павших на поле брани.$B$BВозьми эти заговоренные флаги, когда пойдешь в Кровавую топь. Установи их возле погибших воинов. Я увижу, скольких мы потеряли, и воздам почести их жертве. Да помогут нам духи, которых мы чтим.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27857, 'ruRU', 'На нас напали!', 'Убейте 12 захватчиков Болотной Воды.', 'Войска Альянса у наших стен!$B$BТвои действия их задержали и ослабили, $n, но все-таки мы в меньшинстве. Это наш последний бой. Победа – или смерть...$B$BСражайся с честью, $n. В данную минуту враг уже проник в город. Выдворим человечишек из Каменора! За Орду!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27858, 'ruRU', 'Дар Реастразы', 'Подождите, пока Реа достанет яйцо из Потайной кладки.', 'Подожди здесь. Я достану яйцо.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27859, 'ruRU', 'Яйцо в безопасности', 'Подождите, пока Реа достанет яйцо из Потайной кладки.', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27860, 'ruRU', 'Заблудшие', 'Перебейте 12 Заблудших в Болотном пристанище.', 'Когда закрылся Темный портал, страх и сожаление охватили многих из тех, кто пришел в эти земли. В отчаянии они прокляли имя Света и погрязли в пучине насилия и ненависти.$B$BЭти падшие души – ныне Заблудшие, немногим отличные от чудовищ, которые нападают на всякого. С каждым днем они все глубже утопают во тьме, а поскольку вымирают, то стали заниматься хищениями из Убежища...$B$BИх уже не спасти, $n. Но мучениям нужно положить конец. Ты можешь избавить их от страданий?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27861, 'ruRU', 'Горнило Крови: боец из клана Кровавого Глаза!', 'Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!', 'А я все думал, когда ж ты объявишься, $n! Заполучить к нам сюда $gбывшего чемпиона:бывшую чемпионку; Кольца Крови – это ж прямо мечта! Народ валом повалит! Мы разбогатеем, $gдружище:подруга;! СКАЗОЧНО РАЗБОГАТЕЕМ!$B$BЭто старая бойцовская площадка Драконьей Пасти. Мы ее только чуток подновили. А потом я уж подсуетился, поговорил кое с кем – закинул удочки, так сказать – и набрал очень даже неслабых бойцов со всего Азерота. Так что пора зарабатывать деньги!$B$BТы знаешь, что делать, $n. Когда будешь $gготов:готова;, свисти. И мы сразу начнем!', 'Хурп\'дерп побежден', 'Хурп\'дерп побежден', '', '', '', 'Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27862, 'ruRU', 'Горнило Крови: боец из клана Кровавого Глаза!', 'Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!', 'Глазам не верю! Это же $n! $GБывший чемпион:Бывшая чемпионка; амфитеатра Страданий! Это ты очень удачно $gзашел:зашла;. Заполучить такого бойца – это же о-го-го! Народ валом повалит! Мы разбогатеем, $gдружище:подруга;! Как сыры в масле будем кататься, помяни мое слово.$B$BЭто старая бойцовская площадка Драконьей Пасти. Мы ее только чуток подновили. А потом я уж подсуетился, поговорил кое с кем – закинул удочки, так сказать – и набрал очень даже неслабых бойцов со всего Азерота. Так что пора зарабатывать деньги!$B$BТы знаешь, что делать, $n. Когда будешь $gготов:готова;, свисти. И мы сразу начнем!', 'Хурп\'дерп побежден', 'Хурп\'дерп побежден', '', '', '', 'Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27863, 'ruRU', 'Горнило Крови: боец из клана Кровавого Глаза!', 'Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!', 'Да, я не спорю. Этот край – то еще место, уж никак не Награнд и даже не Зул\'Драк, но знаешь, $gдружище:подруга;, я тебе вот что скажу: я просто двигаю туда, где можно заработать! Поэтому – добро пожаловать на Сумеречное нагорье!$B$BТы тут новичок, и я тебе объясню в двух словах, что здесь и как. Я организатор боев, этот сварливый тролль – мой телохранитель Водин. Ну а ты, стало быть, боец на потеху почтеннейшей публике. У нас тут все по желанию. Захочешь сражаться – собери друзей и скажи мне, а уж у меня найдутся для вас достойные противники.$B$BМожно и прямо сейчас, если хочешь. Ну что, будешь сражаться?', 'Хурп\'дерп побежден', 'Участник боев из клана Кровавого Глаза.', 'Хурп\'дерп', 'Правая рука Гурга.', 'Водин', 'Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27864, 'ruRU', 'Горнило Крови: смертоносная Драконья Пасть.', 'Выйдите на арену Горнила Крови и одержите победу над Торгом Свежевателем Драконов!', 'Слушай, тут такое дело... Тебе понравится! Бойцы Драконьей Пасти узнали, что ты сражаешься на арене, и прямо-таки озверели. Говорят, сделают все, чтобы тебя вынесли с этой арены вперед ногами.$B$BЧто скажешь? Покажем им старую добрую драку |3-1($r) с орком? Начнем сразу, как будешь $gготов:готова;.', 'Торг Свежеватель Драконов побежден', 'Сломить волю черного дракона – первый шаг на пути к тому, чтобы стать чемпионом Драконьей Пасти.', 'Торг Свежеватель Драконов', 'Что может сравниться с любовью троллей.', 'Водин', 'Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27865, 'ruRU', 'Горнило Крови: грозный Грозовой Молот.', 'Выйдите на арену Горнила Крови и одержите победу над Суллом Коленодробом!', 'Слушай, тут такое дело... Тебе понравится! Бойцы Громового Молота узнали, что ты сражаешься на арене, и прямо-таки озверели. Говорят, сделают все, чтобы тебя вынесли с этой арены вперед ногами.$B$BЧто скажешь? Покажем им старую добрую драку |3-1($r) с дворфом? Начнем сразу, как будешь $gготов:готова;.', 'Сулл Коленодроб побежден', 'Береги пальцы ног.', 'Сулл Коленодроб', 'Что может сравниться с любовью троллей.', 'Водин', 'Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27866, 'ruRU', 'Горнило Крови: чудовище Колдера', 'Выйдите на арену Горнила Крови и одержите победу над составным кадавром!', 'Жестокий и кровопролитный, следующий бой – я уверен – понравится публике. Зрители будут вопить от восторга! Ну, или с досады... это уж кто за кого болеет. Колдер Грей собрал части тел побежденных бойцов и составил из них идеального воина. Прямо-таки боевую машину.$B$BЯ его видел... Потом три ночи не спал. Настоящее чудовище, даром что кадавр. И он рвется в бой. Ну что? Рискнешь сразиться? Как будешь $gготов:готова;, скажи, и мы сразу начнем.', 'Составной кадавр побежден', 'Чудовищный плод всех предыдущих битв.', 'Составной кадавр', 'Это прямо как ты любишь, уж Водин знает.', 'Водин', 'Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27867, 'ruRU', 'Горнило Крови: лорд-Потрошитель', 'Выйдите на арену Горнила Крови и одержите победу над лордом Джеффри Талваном!', 'В следующей схватке тебе придется туго. К нам специально приехал один знаменитый боец благородных кровей, очень опытный воин. Родом из Гилнеаса, полон решимости доказать, что он – лучший боец на этом материке Азерота.$B$BСразу предупреждаю: этот бой не на жизнь, а на смерть. В общем, как будешь $gготов:готова;, скажи, и мы сразу начнем.', 'Лорд Джеффри Талван побежден', 'Действующий чемпион Горнила Крови, непобедимый лорд Джеффри Талван.', 'Лорд Джеффри Талван', 'Ни разу не переодевался за четыре года.', 'Водин', 'Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27868, 'ruRU', 'Горнило Крови: Сумеречный ужас', 'Выйдите на арену Горнила Крови и одержите победу над Углеколом Пожирателем!', 'У меня тут припасен противник, который сразу разбудит в тебе боевой задор. Как только увидишь, сразу рванешься его убивать. Я сперва сомневался, выпускать ли его на арену, но бой есть бой! И кто я такой, чтобы отказываться от притока наличности?! А уж он будет неслабый, поверь мне на слово.$B$BЭтот парень, он не откуда-нибудь, а из Сумеречной крепости! Говорят, очень коварный боец. Так что почаще смотри под ноги и не зевай. В общем, как будешь $gготов:готова; к поединку, мы сразу начнем.', 'Углекол Пожиратель побежден', 'Шутки в сторону. Если Уклекола не остановить, вся арена сгорит в пламени его гнева.', 'Углекол Пожиратель', 'Троллья тоска.', 'Водин', 'Вернитесь к троллю-прислужнику Водину в Горнило Крови, что на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27869, 'ruRU', 'Дракон и храм', 'Поговорите с лордом Итаром на вершине лестницы в храме Атал\'Хаккара.', 'Эти змеи, должно быть, из храма Атал\'Хаккара. Эта мысль приходила мне в голову и раньше... $B$BПару дней назад заходил ко мне один, предупреждал, чтобы я остерегалась чего-то подобного. Эльф, Итаром назвался. Думаю, он не заподозрил, что я видела его истинное обличье... То был зеленый дракон, вероятно, пришел на выручку своим павшим братьям.$B$BНаверняка он что-то затевает. Итар направился к самому храму... Возможно, тебе стоит последовать за ним. Грядут темные времена.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27870, 'ruRU', 'Возвращение на Заставу Болотной Воды', 'Поговорите с Джоанной Блухарт на Заставе Болотной Воды.', 'Вне зависимости от того, поможешь ли ты мне в храме, твой народ должен знать, что тут творится.$B$BК северу от храма люди из вашего Альянса смертных построили то, что они называют Заставой Болотной Воды. Они вступили в открытое противостояние с Ордой на болотах, и я предвижу, что конфликт будет только усугубляться.$B$BНе мне вмешиваться в дела смертных, $n. Я просто прошу тебя предупредить твой народ о том, какое зло затаилось в храме.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27871, 'ruRU', 'Возвращение в Каменор', 'Поговорите с командиром разведотряда Руагом в Каменоре на Болоте печали.', 'Вне зависимости от того, поможешь ли ты мне в храме, твой народ должен знать, что здесь происходит.$B$BК юго-западу от храма – ордынский город Каменор. Живущие там орки ведут войну с недавно прибывшими в топи людьми. Это яростный конфликт, который, я думаю, только усилится.$B$BНе мне вмешиваться в дела смертных, $n. Я просто прошу тебя предупредить твой народ о том, какое зло затаилось в храме.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27872, 'ruRU', 'Tortolla Hub Complete', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27873, 'ruRU', 'Контрольная точка Авианы пройдена', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27874, 'ruRU', 'Наследие Авианы', 'Разыщите Чолуну в святилище Авианы на горе Хиджал.', 'Еще одно святилище нуждается в твоей помощи, $n!$B$BК юго-западу от Древа Жизни находится святилище Авианы, пристанище друидов-воронов. 10 000 лет назад Авиана, покровительница всех пернатых созданий, пожертвовала собой ради спасения этого мира.$B$BЧувствую, что ее святилище находится в опасности, равно как и охраняющие его друиды. Разыщи Чолуну, одну из мудрейших представительниц друидов-воронов, обитающую в стенах святилища.', '', '', '', '', '', 'Разыщите Чолуну в Святилище Авианы на горе Хиджал.', 25549);
INSERT INTO `quest_template_locale` VALUES (27875, 'ruRU', 'Молитвоцвет', 'Соберите 10 побегов молитвоцвета в Ползучей трясине.', 'Годами я пытался смягчить страдания Сломленных. Поработившие их силы не просто изменили их облик – они отняли утешение Света. Свет больше не согревает их души.$B$BЯ не могу позволить Магтуру погрязнуть во тьме, $n. До того как его состояние ухудшилось, я изучал молитвоцвет – цветок, растущий в Ползучей трясине. Он умудряется прорастать даже в самой глубокой тени. Умоляю, собери эти цветы – ради Магтура.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27876, 'ruRU', 'Тайны Ползучей Трясины', 'Соберите 10 образцов укрепляющего ила в Ползучей трясине.', 'Ползучая трясина получила свое название благодаря удивительному явлению. Движимый некой силой, отборный ил накапливается и, словно живой, перемещается сам по себе.$B$BПоначалу я опасался, что это какая-то губительная сила, но в ходе наблюдений выяснилось обратное; какая бы энергия ни двигала им, по природе своей она положительная. Возможно, жизненную силу такого рода можно передать и Сломленным, чтобы пробудить их прежнюю сущность.$B$BИлу вряд ли придутся по душе твои попытки его собрать, $n. И все же прошу тебя – сделай это.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27877, 'ruRU', 'Цирк непуганых идиотов', 'Раздобудьте 15 голов дворфов клана Черного Железа.', 'Мне нужна твоя помощь в одной затее, $n. Она подпадает под определение \"превентивная археология\".$B$BЯ развлекаюсь, закапывая обычные предметы на видном месте, чтобы кретины из Альянса думали, будто нашли что ценное.$B$BИтак... Дворфы из клана Черного Железа обитают на карьере Тяжелоступа в крепости Ангор, на севере. Принеси мне их головы. Да, ты не $gослышался:ослышалась; – головы. После того как удалим с них плоть, черепа нам пригодятся, чтобы вмешаться в работу дворфов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27878, 'ruRU', 'Насильственный захват', 'Поищите сокровище на самом нижнем уровне крепости Ангор.', 'У меня есть предложение, которое, возможно, тебя заинтересует.$B$BДворфы из клана Черного Железа пришли сюда задолго до нас. А это значит, что, когда показались руины титанов, клан Черного Железа первым добрался до прорвы артефактов. Бьюсь об заклад, они до сих пор держат сокровище в крепости Ангор к северо-западу отсюда.$B$BРазыщи все самое ценное... и стащи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27879, 'ruRU', 'Выживает жирнейший', 'Добудьте 6 порций мяса и 10 отрезов шелка клана Гнилобрюхих.', 'Припасов у нас – кот наплакал... Черные драконы разоряют наши охотничьи угодья, и нам негде раздобыть пропитание.$B$BЗато у огров на юге есть все, что нам нужно. В их пещере ты найдешь вдоволь запасов мяса и ремесленного сырья.$B$BОгры наверняка так просто все это не отдадут, поэтому будь начеку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27880, 'ruRU', 'Затяжная оборона', 'Уничтожьте 12 бойцов клана Гнилобрюхих. Можно убивать как извергов, так и шаманов этого клана.', 'Мои воины сами вполне справляются с драконами. К тому же я не могу позволить $gначинающему:начинающей:c; |3-2($c) вроде тебя вмешиваться в наши военные планы и губить их на корню.$B$BХочешь работу? Будет тебе работа. Разведай лагерь огров на юго-западе. До меня дошли слухи, что возле их логова видели небольшой отряд бойцов.$B$BНельзя сидеть сложа руки и ждать, пока они зайдут к нам с фланга... особенно когда у нас и без того забот полон рот. Прореди-ка ряды этих огров, покуда они нас в этом не опередили.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27881, 'ruRU', 'Лагерь Кровавого Взора', 'Обратитесь к главному дознавателю Тей\'телану Кровавому Взору в лагере Кровавого Взора, что в Бесплодных землях.', 'Есть у меня одна идея, но это, скорее, задел на будущее. Заделы на будущее – это вроде как мой конек.$B$BК северу отсюда, в песках, Реликварий обнаружил неисследованные руины титанов. Если и был кто-то древнее и мудрее драконов, так это титаны. Проклятье, да я слыхал, что это титаны и СОЗДАЛИ драконов!$B$BПоговори с главным дознавателем Тей\'теланом Кровавым Взором в лагере на северо-востоке. Он об этих титанах знает побольше моего.$B$BНу, а я что говорил? Задел на будущее, да.', '', '', '', '', '', 'Явитесь с докладом к главному дознавателю Тей\'телану Кровавому Взору в лагерь Кровавого Взора, что в Бесплодных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (27882, 'ruRU', 'Вопрос не истории, а силы', 'Добудьте разбитую чашу, пыльную вазу, иероглиф земли и орудие троггов.', 'Лига исследователей, может, и поднаторела в пролетарском умении откапывать всякую всячину, но вот чего им действительно не хватает – ума и воображения по использованию находок. Они маринуют все найденное на музейных полках, вместо того чтобы применить силу этих могучих артефактов по назначению.$B$BДворфы – глупцы. Хорошо хоть, убивать таких легче легкого.$B$BТы найдешь их на раскопках стен каньона к северу отсюда. Вырви, что сможешь, из их короткопалых ручонок, и принеси мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27883, 'ruRU', 'Пешка-страж', 'Выясните, для чего нужна пешка-страж в Гробнице Стражей в Бесплодных землях.', 'Одной из немногих ценных находок, обнаруженных в руинах, была эта маленькая нефритовая статуэтка.$B$BМы считаем, это своего рода ключ, но не знаем, что он открывает. Поэтому мне статуэтка без надобности.$B$BЗато, может быть, тебе пригодится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27884, 'ruRU', 'Пешка-часовой', 'Выясните, для чего нужна пешка-часовой в Гробнице Стражей в Бесплодных землях.', 'Мы нашли эту миниатюрную красную статуэтку у одного из погибших археологов Лиги исследователей. Убили его, к сожалению, не мы. Местная фауна постаралась.$B$BСтатуэтка искусно изготовлена, но, похоже, магии в ней ни на пшик. Делай с ней что заблагорассудится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27885, 'ruRU', 'Игра стражей', 'Завершите игру стражей, переместив пешек-стражей так, чтобы они смотрели внутрь квадрата.', 'Вы видите, как статуэтка сначала раздваивается, затем делится на четыре, а затем на восемь одинаковых статуэток, которые выстраиваются в квадрат.$B$BПрямо в вашем сознании раздается голос:$B$B\"Настоящий страж не смотрит ВОВНЕ, отыскивая признаки опасности.$B$BНастоящий страж обращает свой взгляд ВОВНУТРЬ, сосредоточенно оберегая свою добычу\".$B$BДолжно быть, это какая-то загадка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27886, 'ruRU', 'Игра часовых', 'Завершите игру часовых, соединив две красные статуэтки.', 'Как только статуэтка оказывается на месте, в комнате появляется еще несколько каменных статуэток. В нише в дальнем конце комнаты вы видите еще одну рубиновую фигурку. Вы слышите голос:$B$B\"Страж наблюдает.$BСтраж защищает.$BСтраж никогда не смежает очей\".$B$BКрасная статуэтка на другом конце комнаты наверняка для чего-то нужна. Может быть, попробовать соединить две красные статуэтки?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27887, 'ruRU', 'Древние защитники', 'Внимательно осмотрите Стража и Часового.', 'В центральном зале гробницы раздается нешуточный грохот. Все-таки что-то с теми огромными статуями неладно...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27888, 'ruRU', 'Возвращение к Бламу', 'Отнесите Око стражей доктору Иерониму Бламу в Удел Эгмонда в Бесплодных землях.', 'В сундуке на подушечке лежит небольшой округлый предмет.$B$BЕсли в этой гробнице и есть артефакты титанов, то это точно один из них. Вы решаете отнести его доктору Бламу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27889, 'ruRU', 'Новый Каргат', 'Отнесите очищенное от скверны яйцо черного дракона Реа в Новый Каргат в Бесплодных землях.', '<Доктор Блам в ошеломленном молчании не сводит глаз с яйца, протирает глаза, затем переводит взгляд на вас.>$B$BТы... ты это $gвидел:видела;?! Потрясающе! Моя ставка на титанов была верна! И спасибо тебе за помощь, конечно.$B$BНам следует отнести это Реа. Реа покинула долину Летлор; после того, как она перевоплотилась в свое истинное обличье прямо на глазах у дракончиков, ей больше не удалось бы скрываться. Теперь она живет на западе, в большом ордынском поселении под названием \"Новый Каргат\".$B$BОна будет ждать тебя с этим яйцом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27890, 'ruRU', 'Плохие парни', 'Поговорите с Амаккаром в Новом Каргате в Бесплодных землях.', 'Из-за спешки, в которой я покидала долину Летлор, я совсем позабыла о Никсондре. А она на свободе и подняла переполох в стае черных драконов. Добрая половина драконов уже здесь, прочесывает западные Бесплодные земли в поисках яйца.$b$bО яйце я позабочусь. А ты займись самыми опасными драконами. Не волнуйся, ты будешь не $gодин:одна;.$B$BЯ заплатила паре наемников, они тебе помогут. Они здесь, в таверне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27891, 'ruRU', 'Амаккар, мастер на все руки', 'Испытайте удар Амаккара по почкам и карманное зелье Амаккара.', 'Прежде чем мы ринемся убивать этих драконов, я посвящу тебя в свою тактику боя.$B$BЯ не такой могучий и рослый, как эти двое, но и у меня есть пара козырей в рукаве. Ты только свистни, и я оглушу твоего противника и прослежу, чтоб он не дергался. Еще у меня всегда при себе зелье-другое на случай форс-мажора.$B$BВот что, давай-ка отработаем совместный бой. Иди в поле, и я тебе покажу, каково это – сражаться с настоящим орком.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27892, 'ruRU', 'Джаррикс-истребитель', 'Испытайте огневую вспышку Джаррикса и искажение времени Джаррикса.', 'Хочешь поболтать чутка? Не вопрос.$B$BЯ Джаррикс, единственный наемник тут, который хоть немного соображает. А также единственный, чьи атаки причиняют хоть какой-то вред. Этим двум тушам я позволяю бегать со мной, только чтобы меня самого не зашибло ненароком.$B$BСлушай, ты в этой операции вроде как за главного. По твоей команде я запущу огненный шар прямиком в твоего врага. А если станет жарковато, я даже время могу замедлить, чтобы ты $gуспел:успела; нанести пару-тройку лишних ударов.$B$BПойдем-ка порепетируем будущий бой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27893, 'ruRU', 'Гаргал-чудище', 'Испытайте осадный щит Гаргала и могучий рев Гаргала.', 'Может, это и не заметно, но вообще-то по орочьим меркам я крупный малый.$B$BЯ тут затем, чтобы оба моих приятеля выбрались из любой переделки целыми и невредимыми. Они мелковаты, и таких здоровых щитов, как у меня, у них нет. А я большой и запросто выдержу удары сразу нескольких монстров! К тому же, если не зевать, всегда можно подставить вместо себя свой щит!$B$BТебя я тоже смогу защитить. Пойдем потренируемся. Я буду следить за тем, чтобы враг атаковал меня, а не тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27894, 'ruRU', 'Поход на дракона', 'Одолейте Каларана Уничтожителя и четверых солдат Летящей Тьмы.', 'Приветствую, $n. Я смотрю, вы четверо уже успели познакомиться.$B$BВот тебе первое задание. Каларан, древний и могучий черный дракон, присоединился к охотникам за яйцом, которое мы оберегаем. Его необходимо остановить, прежде чем он подберется слишком близко.$B$BТы найдешь дракона и его приспешников в Знойных Песках к востоку от Нового Каргата. Выследи его и убей. Помощь твоих новых друзей-наемников придется как нельзя кстати.', '', 'Нужно сразить черного дракона, пока яйцо все еще уязвимо.', 'Реастраза', 'Дело еще не закончено.', 'Реастраза', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27895, 'ruRU', 'Охота продолжается!', 'Одолейте генерала Жиракку, Молдарра и 6 черных драконоидов.', 'Род черных драконов знает свое дело. Как тебе должно быть известно, они захватили значительную часть Нового Каргата. Этими войсками командуют генерал Жиракка и его правая рука – Молдарр. Их нужно остановить...', '', 'Молдарр и Жиракка командуют основной группировкой черных драконов.', 'Реастраза', 'Главное испытание еще впереди…', 'Реастраза', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27896, 'ruRU', 'Печаль и гнев', 'Убейте Никсондру и 12 ее детенышей.', 'Я бесконечно сожалею о том, как мы... нет, как я обращалась с Никсондрой. Я заставляла ее откладывать яйца и ставила над ними опыты. Снова и снова – без конца.$B$BДаже сама будучи матерью, я с трудом могу представить себе ее горе.$B$BНет... Мне нужно быть сильной. В конце концов, мы стараемся на благо будущих поколений черных драконов. Ее жертва не была напрасной.$B$BОна кружит над руинами Каргата, к северо-западу от Нового Каргата, обезумевшая от ярости. Пожалуйста, герой... избавь Никсондру от страданий.', '', 'Прости меня, Никсондра…', 'Реастраза', 'Почти готово.', 'Реастраза', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27897, 'ruRU', 'Потайная кладка', 'Поговорите с Реей у Потайной кладки в Бесплодных землях.', 'Теперь, когда большинство черных драконов покинуло Бесплодные земли, переносить яйцо стало безопасно. Я буду на небольшом плато, к северу от Нового Каргата.$B$BИщи меня там.', '', 'Встретимся на севере.', 'Реастраза', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27898, 'ruRU', 'Дар Реастразы', 'Подождите, пока Реа достанет яйцо из Потайной кладки.', 'Подожди здесь. Я достану яйцо.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27899, 'ruRU', 'Глаза горят, мозг кипит...', 'Поговорите с Харрисоном Джонсом у Обелиска Солнца.', 'Ты ищешь Харрисона? Он только что ушел.$B$BВсе твердил о каком-то недавнем открытии. Мол, теперь все наконец проясняется.$B$BУж не знаю, чего у него проясняется... Я так вообще ничего не поняла.$B$BЯ ему говорила, мол, побудь с нами хоть пару дней, отдохни, полюбуйся закатами... но куда там! Когда он в таком состоянии, с ним вообще невозможно разговаривать. Глаза горят, мозг кипит...$B$BКак-то мне за него неспокойно. Может, догонишь его и составишь ему компанию?$B$BОн умчался на юг, к тому огромному монолиту.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27900, 'ruRU', 'С одним я справлюсь', 'Убейте 10 воздушных пехотинцев Шнотца.', 'Как удачно, что ты $gпришел:пришла;, $n.$B$BПохоже, я не единственный, кто проявляет интерес к обелискам, и эти ребята явно не склонны к плодотворной научной дискуссии...$B$BДумаю, с этим парнем я справлюсь.$B$BА ты, может быть, разберешься с его друзьями, пока они сюда не добрались?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27901, 'ruRU', 'Они даже не знают, что это такое', 'Соберите активирующее устройство титанов.', 'Слушай, $n. На разговоры нет времени, так что я буду краток.$B$BЭти ребята, как я понимаю, хватают все без разбора и похоже, уже растащили на части нужный нам аппарат.$B$BОбыщи их ящики и собери все детали древнего активирующего устройства. У офицеров должен быть шифр, открывающий крышки.$B$BПоторопись!$B$BПока они не загрузили награбленное в самолеты!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27902, 'ruRU', 'Чистый источник', 'Соберите 6 частиц духов Чистого источника.', 'Магтур рассказывал мне о шаманстве Сломленных. Великий Нобундо однажды произнес, что путем стихии, в принципе, можно вернуться к Свету.$B$BОстается надеяться, что в его словах была доля истины. Духи, которые обитают возле пещеры Чистого Источника к югу отсюда, состоят из кристально чистой воды. Возможно, они неорганизованы и агрессивны, но чистейшая вода, заключенная в них, будет лучшим проводником для благословенного Света.$B$BПрошу тебя, принеси мне эту воду, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27903, 'ruRU', 'Зажигание', 'Раздобудьте линзу солнца.', 'Крепкий попался товарищ!$B$BВ который раз ты меня выручаешь, $gмалыш:малышка;. Мы почти у цели. Осталось всего ничего.$B$BСогласно моим изысканиям, там внизу должна быть статуя титана. Активируй ее с помощью этого устройства, а потом разбей.$B$BЕсли моя теория верна, в статуе должен быть ключ к активации обелиска.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27904, 'ruRU', 'Дуновение тумана', 'Добудьте 5 туманных кристаллов туманных греллей.', 'Грелли – духи леса, что блуждают в Туманной долине к западу отсюда. Несмотря на их сходство с бесами, в ходе своих наблюдений я не обнаружил никаких следов демонической природы. Насколько можно судить, они не подверглись порче.$B$BЖивя в долине, они вызывают порывы ветра, когда им заблагорассудится, и перемещаются с ним как единое целое. Здешний чистый воздух, возможно, дополнит мое лекарство для бедного Магтура.$B$BОкажи услугу, $n, добудь туманные кристаллы, заключенные в телах греллей. Нужно испробовать все доступные средства.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27905, 'ruRU', 'Стрелок хвостовой пушки', 'С помощью хвостовой пушки защищайтесь от бомбистов Шнотца.', 'Ну вот, я его обработал. А теперь остается его добить. Надеюсь, ты мне поможешь.$B$BУ меня есть план, как нам отсюда сбежать. Он требует немалого мужества... и чуть-чуть везения.$B$BНу что, $n? $GГотов:Готова;?$B$BТогда следуй за мной...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27906, 'ruRU', 'Ника Алый Шрам', 'Поговорите с Никой Алый Шрам у Развилки Расщепленного Копья.', 'Чтобы оправиться от одного нападения и подготовиться к следующему, нужно проделать много работы. Мне потребуются последние сведения от всех наших разведчиков.$B$BНика Алый Шрам – наш лучший следопыт – тренировалась в суровых условиях Бесплодных земель. Она была направлена на запад к Развилке Расщепленного Копья для наблюдения за действиями Альянса.$B$BОтправляйся к Нике, $n. Доложи ей о происходящем в Каменоре. Окажи ей любую помощь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27907, 'ruRU', 'Молитвоцвет', 'Принесите 10 побегов молитвоцвета из Ползучей трясины.', 'Я раздавлена, |3-6($c). Я вложила всю свою силу в Хелгрума, но она вытекает с кровью из его открытых ран. Они слишком глубоки, чтобы затянуться, его плоть отказывается заживать.$B$BОн бредит, охваченный лихорадкой и болью. Я не могу оставить его ни на минуту. Мне неловко просить тебя об этом, но не $gмог:могла; бы ты собрать травы?$B$BМолитвоцвет, растущий в этих топях, – издревле известное средство, облегчающее боль. Будь у меня это снадобье, я облегчила бы страдания Хелгрума.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27908, 'ruRU', 'Тайны Ползучей трясины', 'Соберите 10 образцов укрепляющего ила в Ползучей трясине.', 'Раны Хелгрума гноятся на влажном болотном воздухе. Они вздуваются и сочатся, делая невыносимыми последние минуты его жизни. Мне нужно их чем-нибудь обработать.$B$BВ этой трясине обитают духи. Они населяют даже тину, собирая ее в горсти целебного ила, которые будто оживают.$B$BДухи прохладной, чистой трясины облегчат страдания Хелгрума. Сделай милость, собери их, ибо я не могу покинуть больного.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27909, 'ruRU', 'Чистый источник', 'Раздобудьте 8 частиц духов Чистого источника.', 'Хелгрум уже еле дышит. Его время почти вышло.$B$BНужна вода. В прудах в пещере Чистого Источника обитают водные духи. Они состоят из наичистейшей воды, во всех этих болотах не найти такой.$B$BДаже если я рискнула бы оставить Хелгрума, у меня сейчас не хватит сил держать топор. Снова молю тебя, смилуйся надо мной ради утешения Хелгрума. Принеси мне частицы духов, чтобы он напоследок испил свежей чистой водицы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27910, 'ruRU', 'Сожаления об ушедшем', 'Добудьте шкуру Сумеречного Клыка.', 'Коли уж я снизошла до униженной мольбы, то терять мне уже нечего. Обращаюсь к тебе с последней просьбой, последним одолжением для меня, недостойного орка.$B$BХелгрум лелеял мечту об одной добыче. Сумеречный Клык, великая пантера из Туманной долины, пожиратель огров... Хелгрум весь извелся, но не давал себе воли поохотиться на него: наша разведмиссия была слишком важна.$B$BРаз уж Хелгруму не суждено добыть Сумеречного Клыка при жизни, пусть он встретится со своей мечтой в лучшем мире. Отправляйся на охоту вместо Хелгрума; принеси мне шкуру Сумеречного Клыка.', '', 'Сумеречный Клык из Туманной долины, пожиратель огров', 'Сумеречный Клык', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27911, 'ruRU', 'На последнем издыхании', 'Останьтесь рядом с Хелгрумом в его последние минуты.', 'Он покидает нас...$B$BНе уходи, $n. Пожалуйста, воздай Хелгруму последние почести вместе со мной. Ты столько $gсделал:сделала; для него.', '', '', '', '', '', 'Поговорите с Никой Алый Шрам.', 25549);
INSERT INTO `quest_template_locale` VALUES (27912, 'ruRU', 'Сокровище титанов', 'Осмотрите сокровище стражей.', 'Второй защитник падает замертво, и у задней стены зала появляется сундук. Быть может, это как раз то, что они охраняли?', '', '', '', '', '', 'Осмотрите сокровище в Гробнице Стражей в Бесплодных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (27913, 'ruRU', 'Сокровище титанов', 'Осмотрите сокровище стражей.', 'Второй защитник падает замертво, и у задней стены зала появляется сундук. Быть может, это как раз то, что они охраняли?', '', '', '', '', '', 'Осмотрите сокровище в Гробнице Стражей в Бесплодных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (27914, 'ruRU', 'Благословение рода зеленых драконов', 'Поговорите с лордом Итаром у входа в храм Атал\'Хаккара.', 'Отлично, $n. Пусть Джаммал\'ану удалось ускользнуть от нас, но теперь его нет, и я могу войти в храм когда пожелаю.$B$BСтой как стоишь, не шевелись. Я сокращу твой путь обратно, призвав к себе твой дух через Изумрудный Сон.$B$BНе пугайся, если почувствуешь легкую сонливость.', '', 'Возвратись ко мне за наградой.', 'Лорд Итар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27915, 'ruRU', 'Сердце храма', 'Обратитесь снова к лорду Итару в храме Атал\'Хаккара.', 'Должен признаться, что у меня есть личная заинтересованность в происходящем здесь. Одним их первых порабощенных здесь зеленых драконов был мой брат Эраникус.$B$BЯ думал, его больше нет, был уверен – он окончательно пропал в мрачном лабиринте кошмара, однако до меня дошли слухи, что в храме появился его призрак. Не знаю, действительно это он или лишь отдаленное тоскливое эхо.$B$BЕсли ты все еще желаешь мне помочь, возвращайся в Зал Масок и следуй через сводчатый коридор в самое сердце храма. Мы встретимся там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27916, 'ruRU', 'Отчет Руага', 'Доставьте рапорт Расщепленного Копья командиру разведотряда Руагу в Каменор.', 'Это донесение Руага, $n. Дай ему знать, что его разведчик все еще здесь.$b$bНи слова о Хелгруме. Я не буду никого расстраивать известиями о трагедии.$b$bМне нужно быть сильной. Всем нам нужно быть сильными.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27917, 'ruRU', 'Я чую их за милю', 'Убейте барона Эшбери.', 'Я чую Годфри и его приспешников. Они где-то рядом – примерно в миле отсюда. Пытались запутать следы, но как-то уж очень убого. Мы этим воспользуемся и – в прямом смысле слова – загоним их в гроб.$B$BОдин из них совсем близко. Хотя у нежити запах слегка изменяется, я уверен, что это Эшбери. Иди и разорви его в клочья. Пусть Отрекшиеся знают, что с нами лучше не связываться.', '', 'Он рядом.', 'Барон Эшбери', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27918, 'ruRU', 'Убежище', 'Отнесите кристаллы дренетиста анахорету Авууну.', 'Анахорет Авуун – один из наших не тронутых порчей братьев, которых другие народы прозвали дренеями. Он пришел в Убежище исцелить нас, попытаться найти лекарство. Это он послал меня сюда добывать эти кристаллы.$B$BОн сейчас присматривает за своим очень больным другом... но несмотря на то, что обращался в сам Экзодар, до сих пор не получил никакой помощи. Не отнесешь ему эти кристаллы, $n? Возможно, ты $gединственный:единственная;, кто может ему помочь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27919, 'ruRU', 'Вперед, к Выжженным землям!', 'Отправляйтесь в Выжженные земли и поговорите с Енохой Громовар в крепости Стражей Пустоты.', 'Мы признательны тебе за оказанную на болоте помощь, $n. Я получил послание из крепости Стражей Пустоты.$b$bЕноха Громовар попросила исследовать обломки корабля на Красных берегах, но у нас нет желающих туда отправляться, а я не могу оставить Убежище.$b$bКрепость Стражей Пустоты расположена в Выжженных землях, к югу от Болота печали. Когда будешь добираться туда, не подходи близко к Каменору.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27920, 'ruRU', 'Вооруженные до зубов', 'Убейте барона Сильверлейна и командира Спрингвейла.', 'Штурмуя крепость, мы столкнулись с неожиданным препятствием, $n. Похоже, слуги барона Сильверлейна и командира Спрингвейла, бывшие с ними при жизни, продолжают прислуживать им и после смерти. Годфри использует этих слуг для прикрытия, и прежде чем мы до него доберемся, нам придется сражаться с ними.$B$BНо ты не волнуйся, я знаю, как с ними справится. Если мы уничтожим Сильверлейна и Спрингвейла, без их руководства слуги уже ничего не смогут, поскольку им нужна твердая направляющая рука.', '', 'Этого мы никак не ожидали.', 'Командир Спрингвейл', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27921, 'ruRU', 'Не на жизнь, а на смерть', 'Убейте лорда Вальдена.', 'Похоже, лорд Вальден наконец соизволил заметить, что мы атакуем, и укрепил оборону. Хотя это ему не поможет... нас ничто не остановит!$B$BДорогу к нему преграждают полчища сильных воинов Плети, но я уверен, что ты сумеешь расчистить нам путь. Мы разделаемся с Вальденом, а потом придет очередь его трусливого господина.', '', 'Враг хитер и коварен.', 'Лорд Вальден', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27922, 'ruRU', 'Предатели!', 'Спрячьтесь за неферсетским папоротником и выведайте секрет Неферсета.', 'Прошу тебя, $gнезнакомец – ты должен:незнакомка – ты должна; мне помочь.$B$BЯ прибыл сюда, чтобы выяснить, что за могучий союзник пришел на помощь Неферсету – но мои же товарищи предали меня и сдали врагу.$B$BПроберись на расположенную над нами террасу, что к востоку отсюда, и раздобудь сведения, которые я собрать, увы, так и не смог. Но имей в виду, что тебе нужно будет скрываться от неферсетов. Возможно, у тебя получится укрыться за одним из этих больших растений на платформе.$B$BСделай это, пожалуйста, а я помогу твоим друзьям найти дорогу к безопасному месту.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27923, 'ruRU', 'Дым, застилающий глаза', 'Подожгите стога сена в Затерянном городе Тол\'вире в Ульдуме.', 'Не знаю, что за план придумал твой странный приятель, но если мы хотим унести отсюда ноги, нам нужно как-то отвлечь наших врагов.$B$BВот, возьми из той жаровни факел и подожги что-нибудь.$B$BВозможно, если мы отвлечем внимание неферсетов хотя бы на несколько минут, у нас будет шанс.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27924, 'ruRU', 'План Бадда', 'Добудьте 6 частей брони Неферсета.', 'У меня есть идея! И можешь не сомневаться, что на этот раз хорошая!$B$BДостань мне блестящие доспехи, которые носят эти люди-кошки.$B$BВ этот раз все будет в ажуре. Просто доверься мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27926, 'ruRU', 'Восточное гостеприимство', 'Беллок Сияющий Клинок предлагает вам пообщаться с гостями лагеря Шнотца.', 'Боюсь, у командующего сейчас и без того дел по горло.$B$BОперация, подобная этой, на текущий момент требует практически ста процентов его внимания.$B$BПока ты ожидаешь аудиенции, не желаешь ли пообщаться с нашими гостями?$B$BУ нас тут сливки всего азеротского общества ожидают, когда мы раскроем перед ними тайны этой местности.$B$BУверен, ваша беседа будет весьма захватывающей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27927, 'ruRU', 'Погружение в бездну', 'Отыщите Тельдарина Заблудшего в Разломе разрушителя миров в Бесплодных землях.', 'В Бесплодных землях обитает довольно необычный народец, многие – довольно давно.$B$BВот, например, останавливались тут в городе три джентльмена. Не могу припомнить их имена... дворфа, кажется, звали Тельдарин. Так или иначе, пару дней назад они отправились отсюда на юг с полным рюкзаком эля, и с тех пор от них никаких вестей. Думаю, они пошли к тому большому разлому.$B$BНе $gмог:могла; бы ты сходить за ними? Хотелось бы убедиться, что с ними все в порядке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27928, 'ruRU', 'С мехом по жизни', 'Раздобудьте 5 шкур пустынного койота.', 'Командир крайне щедр с теми, кто доказал свою преданность. Могу подсказать, как тебе выслужиться перед ним.$B$BДо того, как командир собрал свою... мм-м... рабочую бригаду, он промышлял мехами.$B$BОн настоящий мастер кожевничества. Скорняк может сделать конфетку даже из самой неприглядной шкуры.$B$BВ иссохшем оазисе на востоке, поговаривают, обитала стая койотов редкого вида.$B$BБыло бы неплохо преподнести в подарок командующему их мех.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27929, 'ruRU', 'Сначала сбить, потом прибить', 'Убейте 4 наездников Громтара, предварительно сбросив их на землю с помощью шипастого крюка для плоти.', 'Один дракон из Драконьей Пасти стоит дюжины наездников на грифонах Громового Молота. Поснимай этих горе-вояк с их завшивленных птичек – и они даже отбиться не смогут.$B$BПрикончить их на земле – вообще плевое дело. Даже ты справишься, |3-6($c) из Орды.$B$BА теперь слушай сюда: разыщи наездников на грифонах. Они должны быть у реки к северу от Кровавого ущелья. Вот, возьми этот крюк. Будешь бросать его в пролетающих мимо всадников. Сила удара вкупе с моментом импульса собьет наездника, и он свалится прямо тебе под ноги. А как свалится, так ты его и добей. Прикончи нескольких наездников, и тогда я поверю, что Орда так сильна и могуча, как ты говоришь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27930, 'ruRU', 'Сокрушение', 'Найдите Реастразу.', 'На горизонте чисто. Если Реастразе с яйцом чудом удалось избежать пламени Смертокрыла, возможно, она отчаянно нуждается в твоей помощи.', '', '', '', '', '', 'Обыщите Потайную кладку в Бесплодных землях и выясните, была ли здесь Реастраза.', 25549);
INSERT INTO `quest_template_locale` VALUES (27931, 'ruRU', 'Грот Обвалов', 'Поговорите со Сланцем Плывуном в Гроте Обвалов в Подземье.', 'Прежде, чем ты поможешь нам здесь, тебе нужно справиться с войсками Матери-Скалы Теразан к югу отсюда. В Гроте Обвалов собираются элементали и великаны.$b$bИм тоже нужен центральный фрагмент столпа мира. Если они нападут на нас во время нашей битвы с каменными троггами, мы не сможем дать им отпор.$b$bЯ отправил вперед верховного геоманта. Найди Сланца Плывуна и сделай все, что он скажет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27932, 'ruRU', 'Топор раскола земли', 'Убейте 5 потрескавшихся изумрудных колоссов.', 'Изумрудные колоссы – самые большие детища Матери-Скалы. Их не должно быть на поле. Как раз для этого я принес топор Отца-Скалы Железной Мантии. Воспользуйся им, чтобы раздробить великанов.$b$bКогда они станут меньше, тебе будет легче их прикончить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27933, 'ruRU', 'Элементиевая руда', 'Соберите 6 кусков элементиевой руды.', 'Тебе предстоит сразиться с лидером сил Теразан. Чтобы перенести тебя к нему быстро и безопасно, мне нужно совершить ритуал.$b$bОтправляйся на поле и добудь у яростней элементиевую руду. Когда ее будет достаточно, я смогу сделать так, что ты станешь единым целым с землей и перенесешься туда, куда тебе нужно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27934, 'ruRU', 'Единое целое с землей', 'Завершите ритуал единения с землей.', 'Войсками Матери-Скалы руководит огромный повелитель элементалей земли Лавинион. К счастью для нас сектанты Сумеречного Молота решили напасть на его логово. Они хотят подчинить его элементалей своей воле.$b$bМы воспользуемся этим. Ритуал земли, который я совершу, сделает тебя единым целым с землей. Ты окажешься недалеко от Лавиниона, ничем не выдав своего присутствия.$b$bПрикончи его.', '', '', '', 'Лавинион прямо перед тобой. Ты знаешь, что нужно делать.', 'Сланц Плывун', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27935, 'ruRU', 'Победить Лавиниона', 'Убейте Лавиниона.', 'Лавинион стоит прямо перед тобой. Убей его, чтобы помешать войскам Теразан напасть на Каменный очаг.', '', 'Убей его, чтобы предотвратить нападение на Каменный очаг!', 'Лавинион', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27936, 'ruRU', 'Победить Лавиниона', 'Убейте Лавиниона.', 'Тебе нужно вернуться и убить Лавиниона, чтобы помешать войскам Теразан напасть на Каменный очаг!', '', 'Убей его, чтобы предотвратить нападение на Каменный очаг!', 'Лавинион', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27937, 'ruRU', 'Возвращение героя', 'Явитесь к Отцу-Скале Железной Мантии в Каменный очаг, что в Подземье.', 'Отец-Скала ждет твоего возвращения к югу от Каменного очага.$b$bПрими подобающий вид. Ты заслуживаешь того, чтобы тебя встретили, как $gгероя:героиню;!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27938, 'ruRU', 'Центральный фрагмент', 'Найдите центральный фрагмент столпа мира.', 'Я вручаю тебе ключ от Каменного очага. Им ты сможешь открыть сейф в моем доме, где и найдешь центральный фрагмент.$b$bБереги его, $n. Постарайся доставить фрагмент в Храм Земли, что в центре Подземья, как можно быстрее!$b$bИ знай, что здесь тебе всегда будут рады.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27939, 'ruRU', 'Пустынная лиса', 'Шнотц желает, чтобы вы раздобыли ему пустынную лису.', 'Работ в этой местность хоть отбавляйт, |3-6($r).$B$BМы с тобой двое иметь горячий страсть, не так ли? К технология древних, я имей в виду.$B$BМожет, объединяйт усилья?$B$BДафай оставлять позади наши прошлый распри.$B$BК делу: на восток обитай некая неуловимый зверье, на который я уже устать охота. Принести мне его в знак искренность твой намерений.$B$BИ я позволять тебе присоединяться к наш операция.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27940, 'ruRU', 'Грязные пташки', 'Перебейте 8 больных падальщиков.', 'Небо над Высохшим оазисом кишит больными падальщиками.$B$BОни как зараженные грызуны – приносят только беду.$B$BОчисти небеса от этого недоразумения – сделай этот край лучше, чем он был до твоего прихода.', '', '', 'Больной падальщик', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (27941, 'ruRU', 'Дресс-код', 'Беллок Сияющий Клинок просит вас собрать 10 комплектов военной формы.', 'В нашем уставе есть один пункт, к которому нужно отнестись со всей серьезностью.$B$BНаши бойцы должны носить официальную униформу не снимая. Это повышает организованность, снижает риск пальбы по своим, к тому же войска смотрятся потрясающе!$B$BМы это называем корпоративным дресс-кодом.$B$BУ нас понемногу заканчивается обмундирование. Вынужден просить тебя принести мне униформу наших соратников, павших на поле боя.$B$BМногие наши бойцы покоятся в руинах Аммона, к востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27942, 'ruRU', 'Идолотерапия', 'Принесите командиру Шнотцу 8 хорошо сохранившихся идолов.', 'Хотеть давайт тебе поручений, |3-6($r).$B$BМой самый доверяйт советник стать жертва древний проклятье. Проклятье, который превращать человек в индюшка!$B$BДни напрочь я искать средство против – и наконец готовый осуществляйт ритуал.$B$BДля этот цель надо идолы с близко руинов. Приноси их быстро-быстро!$B$BФольно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27943, 'ruRU', 'Разгневанные духи', 'Командир Шнотц велит вам с помощью ЛППУ добыть 5 экстрактов взбешенного призрака.', 'Док Венкман быть числом лучших работникофф наука, пока время не прийти от него избавляйся.$B$BОднако он оставить мне величайший изобретений. Орудие борьба сверхъестественным. Его надо настройт и он выкачивайт из духа жизненный сила.$B$BЭтот оружий – ключевая роль мой ритуал.$B$BЗачем есть ты? Ты добывайт нужный ингредиент.$B$BЯ калибровать орудий на работа против бешеный призрак – их много-много в храм на восток.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27944, 'ruRU', 'Очищение леса', 'Убейте 12 скрытней Мрачного леса. Мрачный лес находится за мостом, к западу отсюда, в центральной части острова.', 'Мы неделями пытаемся зацепиться в Мрачном лесу, но лес просто кишит пауками. Окажи мне услугу, перебей эту гадость, чтобы мы могли подготовиться к нападению.$b$bБудь $gбдителен:бдительна;, когда доберешься до леса, а то мне тут на неделе доложили, что поблизости орудует Орда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27945, 'ruRU', 'Закрасить черным', 'Добудьте черное алмазное сердце.', 'Земля истекает кровью, |3-6($c). Они вспороли ее, как клинок вспарывает кожу.$B$BСектанты вершат свои темные дела с помощью элементалей – глупцы, они даже не подозревают о том, что элементали могут предать их. Иди на северо-восток – в то место, которое мы зовем Черный разлом. Там ты найдешь обсидиановых рабов камня.$B$BРаздроби их тела и найди идеальное сердце из черного алмаза. Я загляну в это сердце и увижу душу раба.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27947, 'ruRU', 'Видение Сумерек', 'Найдите Око Сумерек в Черном разломе.', 'Чо\'Галл следит за своими слугами с помощью волшебных шаров, \"Очей Сумерек\".$B$BСтражам Хиджала удалось найти один такой шар и понять, как он действует. То же надлежит сделать и нам. Мне нужен такой шар – тогда я смогу заглянуть в логово Чо\'Галла!$B$BПереправься через реку и иди на северо-восток. Обыщи Черный разлом и найди Око Сумерек. Делай что хочешь, но найди его!', '', '', '', '', '', 'Найдите Око Сумерек в Черном разломе.', 25549);
INSERT INTO `quest_template_locale` VALUES (27948, 'ruRU', 'Липкая работа', 'Соберите 4 липких паутинных железы праматерей Мрачного леса. Чтобы попасть в лес, находящийся в центральной части острова, пересеките мост к западу от лагеря.', 'Непросто было найти припасы на острове, скажу я тебе.$b$bК счастью, к западу отсюда, в Мрачном лесу, нам удалось обнаружить хороший источник шелка. Плохая новость – это то, что шелк производят паучихи-праматери. Достань мне 4 паутинных железы праматерей.$b$bЭтого хватит, чтобы дошить последний комплект рубашек.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27949, 'ruRU', 'Позабытые', 'Освободите 6 истерзанных душ на Забытом холме. Душу можно высвободить, дотронувшись до могильного камня. Забытый холм расположен к западу отсюда, за Мрачным лесом и Передовой Неупокоенных.', 'На этом острове погибло много солдат, $n. Наш долг – почтить их память.$b$bОтправляйся на Забытый холм, что к западу отсюда, и освободи души наших братьев по оружию, томящиеся там. Будь $gосторожен:осторожна;, по донесениям в тех местах бесчинствует нежить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27950, 'ruRU', 'Кулдык!', 'Шнотц хочет, чтобы вы поговорили с ним, когда будете готовы узреть ритуал.', 'Аллес! Время снимайт с мой Кулдыка мерзкий проклятье!$B$BБыть начеку, |3-6($r), смотреть два глаз. Никто не помешайт мне проводить ритуал.$B$BЗнайт, все есть чисто, давать знайт мне!$B$BФорвартс!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27951, 'ruRU', 'Порой приходится чем-то жертвовать', 'Убейте 10 черных шаманов.', '<Глаз говорит с вами, и вам кажется, что его грохочущий \"голос\" доносится отовсюду.>$B$BТебе нужна моя помощь, |3-6($r)? Мои услуги стоят дорого. Эти последователи Сумрака воздавали мне почести – поили меня кровью дворфов Громового Молота, которые остались в руинах своих городов. Но моя жажда велика. Быть может, тебе удастся утолить ее.$B$BУбей моих бывших повелителей, и тогда я покажу тебе все, что ты захочешь увидеть. Убей черных шаманов. В конце концов, в их жилах тоже течет кровь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27952, 'ruRU', 'Исследователи', 'Поговорите с исследовательницей Мови в Храме Земли в Подземье.', 'В зале в северо-западной части Храма появились сотрудники Лиги исследователей.$b$bОни все больше кричат о том, что Сумеречный Молот что-то затевает.$b$b$n, не будешь ли ты так $gдобр:добра; узнать, что им нужно?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27953, 'ruRU', 'Реликварий', 'Поговорите с исследователем Роу в Храме Земли в Подземье.', 'В зале в северо-восточной части Храма появились сотрудники Реликвария.$b$bОни все больше кричат о том, что Сумеречный Молот что-то затевает.$b$b$n, не будешь ли ты так $gдобр:добра; узнать, что им нужно?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27954, 'ruRU', 'Всевидящее Око', 'Отдайте Око Сумерек Гароне Полуорчихе в Кровавом ущелье на Сумеречном нагорье.', 'Ну хорошо, |3-6($r). Мои услуги оплачены кровью. Отнеси меня Гароне Полуорчихе.$B$BО да, я уже знаю, куда ты меня понесешь. Ни для кого не секрет, что Гарона мечтает о мести. Я с удовольствием буду следить за развитием событий.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27955, 'ruRU', 'Глаз-шпион', 'Загляните в Око Сумерек.', 'От одного вида этой ужасной штуки у меня мороз по коже. С их помощью Чо\'Галл правит своими миньонами – что ж, а мы обратим это Око против него.$B$BТак, посмотрим... хм... тут все мутное. Я вижу только тебя. Почему глаз показывает мне тебя?$B$B<Гарона ставит Око перед собой.>$B$BЗагляни в глаз и расскажи мне, что ты в нем видишь. Загляни в логово Чо\'Галла! Что он делает? Много ли с ним стражи? Отвечай!', '', '', '', '', '', 'Поговорите с Гароной Полуорчихой в Кровавом ущелье на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (27956, 'ruRU', 'Задача Чурбана', 'Получите 15 закаленных маховиков из закаленных боевых големов.', 'Чурбан пришел из Бесплодных земель. Другие огры дерутся с Чурбаном.$b$bЧурбан ненавидит драться. Чурбан хочет учиться.$b$bЧурбан видел машины на юге. У машин есть детали. Может быть, если вежливо попросить, машины дадут детали? Может быть, если у Чурбана будут детали, он узнает больше и о машинах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27957, 'ruRU', 'Чурбан не убивать', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27958, 'ruRU', 'Правильное противоядие', 'Добудьте 14 порций яда стеклопутого паука.', 'Жаль, что Чурбан ушел. Мне уже начала нравиться его компания.$b$bОх, ладно, пора возвращаться к работе!$b$bЯ в этой экспедиции лучше всех разбираюсь в медицине, и у меня заканчивается противоядие. А нам его понадобится много.$b$bСоздание хорошего противоядия всегда начинается с добычи яда. Можем начать со стеклопутых пауков, что водятся неподалеку. Если убьешь их, то, наверное, сможешь достать некоторое количество яда из желез под их зубами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27959, 'ruRU', 'Приключения Чурбана: верхом на пауках', 'Добейтесь того, чтобы 7 стеклопутных пауков ослабли и Чурбан смог покататься на них.', 'Чурбан видит, что тебе нравится убивать. Давай Чурбан научит тебя, как можно по-другому.$b$bЧурбану всегда хотелось покататься на пауках. Это должно быть забавно. Хотя пауки бегают слишком быстро. И всегда соскальзываешь.$b$bНо мы попробуем вместе. Ты будешь драться с пауком, пока он не станет усталым и слабым. Потом Чурбан запрыгнет на паука и покатается.$b$bМожет быть, Чурбан даже соберет для тебя немного яда! Но не надо убивать!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27960, 'ruRU', 'Чем меньше, тем лучше', 'Убейте 10 геологов или сторожей из клана Черного Железа.', 'Я не ахти какой боец... мне интереснее копаться в земле. И Джек, и Приз такие же. И Чурбан... По его виду можно предположить, что он драчун, но на самом деле он самый большой тюфяк из всех нас.$b$bЯ хочу сказать, что хорошо, что ты $gпришел:пришла; тогда, когда $gпришел:пришла;.$b$bПохоже, что скоро нашему Братству Тория придется драться с дворфами Черного Железа. Думаю, надо вывести из строя самых сильных их бойцов, пока и в самом деле не началась война. Начни с тех геологов и сторожей, что на юге.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27961, 'ruRU', 'Не на своем месте', 'Добудьте 8 пепельных цыплят.', 'Ущелье беспощадно. Нельзя сказать, что оно изобилует дичью.$b$bМы пытались завести кое-каких животных, но они здесь плохо себя чувствуют. Здесь просто нет пищи. А теперь пауки, которые водятся поблизости, питаясь мясом цыплят, становятся большими и толстыми, а ведь они и без этого опасны.$b$bОт пауков мы вряд ли когда-то избавимся, но мы можем спасти оставшихся цыплят. Тем самым ты не только обеспечишь Братство пищей, но и избавишь цыплят от болезненной смерти от паучьих укусов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27962, 'ruRU', 'Рокочущие останки', 'Добудьте гигантский рог Маргульи.', 'Маргулья Свирепая – старая рокочущая ящерица, которая живет в этих местах. Ходят легенды о том, что она жила в Тлеющем ущелье даже тогда, когда оно еще не было ущельем. Существует также легенда о том, что она сожрала моего брата Барнабаса.$b$bМне плевать, сколько ей лет и какой магией она пользуется. Я просто хочу, чтобы она умерла. Во имя Барнабаса.$b$bЭту ящерицу можно встретить на скалах к югу отсюда.', '', 'Древний страж Тлеющего ущелья.', 'Маргулья Свирепая', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27963, 'ruRU', 'Новый хозяин... Но кто?', 'Найдите Гравиуса Грязнулю на строительной площадке Грязнули и отберите у него докладную записку Черного Железа.', 'Ты как раз вовремя.$b$bИзлагаю факты: дворфы Черного Железа, которые обитают в ущелье, ведут себя странно, и Братство Тория намеревается выяснить, почему. Надзиратель Скользорук не любит сюрпризов.$b$bМы подозреваем, что у них появился новый командир, он и отдает приказы. У меня есть все основания считать, что Гравиус Грязнуля в курсе, кто бы это мог быть. Гравиуса можно найти к югу отсюда.$b$bДаже сюда, в Тлеющее ущелье дошли слухи о твоих подвигах, $n. Ты легко справишься с Грязнулей.', '', 'Этот дворф должен лучше знать, что происходит с Черным Железом.', 'Гравиус Грязнуля', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27964, 'ruRU', 'Главный землекоп Звоноус', 'Отправляйтесь в Котлован и убивайте землечерпов и пехотинцев из клана Черного Железа до тех пор, пока не появится главный землекоп Звоноус. Затем убейте Звоноуса и заберите у него темный тлеющий уголь.', 'Оказывается, Грязнуля занимал не такое высокое положение, как я думал. Мы должны устранить того, кому он подчиняется, предварительно узнав, что ему известно.$b$bЭто главный землекоп Звоноус, и он руководит земельными работами в Котловане, к северо-западу отсюда. Его землечерпы и пехотинцы надзирают за восточной частью Котлована, день и ночь копая ямы.$b$bОн не слишком часто показывается на поверхности, но если ты убьешь побольше его людей, он будет вынужден выйти и разобраться с тобой.', '', 'Начальник Грязнули – Звоноус. Возможно, у него больше информации.', 'Главный землекоп Звоноус', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27965, 'ruRU', 'Лагерь Братства Тория: трон Братства', 'Отправляйтесь с докладом к надзирателю Скользоруку в лагере Братства Тория, что в Тлеющем ущелье.', 'Ты... ты $gвидел:видела; это? Вот же недостающий элемент, который мы искали! Нужно передать эту информацию кому-нибудь из лагеря Братства Тория.$b$bИзвестно, что в прошлом дворфы Черного Железа имели дело с Повелителем Огня, но никогда раньше они не проникали так далеко в Тлеющее ущелье.$b$bЧтобы добраться до лагеря Братства Тория, надо двигаться на запад, а потом на север. Лагерь находится в скалах, которые возвышаются над северным плато Пироксовых равнин. Передай эту информацию лично надзирателю Скользоруку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27966, 'ruRU', 'Спасение останков', 'От вас требуется собрать 9 проклятых бедренных костей вурдалаков, населяющих Забытый холм. Это место расположено на западной стороне острова за Передовой Неупокоенных.', 'На Забытый холм покушаются зомби и вурдалаки c тех самых пор, как мы обосновались на этом проклятом острове. Мы многократно пытались очистить его от нежити, но безуспешно.$b$bОдин офицер посоветовал нам собирать кости вурдалаков, чтобы те еженощно не восставали из мертвых. Не подсобишь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27967, 'ruRU', 'Старший лейтенант Коннор', 'Обнаружьте и убейте старшего лейтенанта Коннора на Забытом холме. Это место расположено в западной стороне острова.', 'Я впервые услышал о лейтенанте Конноре, когда был новобранцем в тюрьме Штормграда. Никто бы не поверил, что он очутится здесь, на Тол Бараде. К сожалению, он все еще бродит по этим проклятым островам, сея смуту в наших войсках.$b$bПоложи конец его страданиям, а заодно и нашим.', '', 'Никто не хочет заканчивать тут свои дни, но жизнь порой складывается помимо нашей воли.', 'Старший лейтенант Коннор', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27968, 'ruRU', 'Ярость стаи', 'Убейте лорда Годфри.', 'О, сладкий запах победы! Должно быть, прямо сейчас, пока мы с тобой говорим, мои бойцы рвут Годфри в клочья. Отправляйся в его владения и получи свою долю останков – ты это $gзаслужил:заслужила;!$B$BКак мы с ним быстро разделались! Даже не думал, что все будет так просто...', '', 'За Кровавые Клыки!', 'Лорд Годфри', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27969, 'ruRU', 'Займись чем-нибудь полезным', 'Командир Шнотц хочет, чтобы вы заставили 6 ленивых работников приняться за дело.', 'Мы скорбеть Кулдыка, но приказ выполняйт, битте.$B$BТы вину искупляйт смочь.$B$BНадевайт форма ты добывайт. Мой работник видеть тебя эта форма и стать... не так агрессия.$B$BПоследний время их боевой настроений невысока. Отказывай выполняйт прямой обязанность.$B$BШайзе!$B$BТы разыскать эти ленивый олух и объясняйт – арбайтен... Или капут!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27970, 'ruRU', 'Капитан П. Харрис', 'Вас просят убить капитана П. Харриса на мысе Потерянной Надежды. Мыс расположен к северо-западу, если идти вдоль береговой линии. Ищите обломки корабля.', 'Мыс Потерянной Надежды уже долгое время стоит у нас как кость в горле. Половина кораблей с провиантом для Тол Барада разбивается внизу о скалы.$b$bЧто еще хуже, так это неупокоенные моряки, докучающие нам. Мы пробовали расправиться с ними, да только они приходят все снова и снова. Последняя надежда – убить капитана, которому они подчиняются. Ты найдешь его на корабле, причалившем к берегу.$b$bНадеюсь, ты не очень боишься акул?', '', 'Убей капитана, и его подчиненные отступят.', 'Капитан П. Харрис', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27971, 'ruRU', 'Раздробить косточки', 'Начальник лагеря Брэк поручил вам уничтожить 8 моряков-утопленников на мысе Потерянной Надежды. Мыс расположен к северо-западу, если идти вдоль береговой линии.', 'Уже долгое время нас беспокоит нежить с мыса Потерянной Надежды. Всякий раз, как разбивается корабль, ее воинство пополняется новыми душами.$b$bТы не $gмог:могла; бы оказать нам услугу, уничтожив несколько неупокоенных врагов? Знаю, что всех их истребить невозможно, но так ты хоть немного облегчишь нашу задачу.$b$bОстерегайся солдат Орды. Поступают донесения о том, что они устраивают засады вдоль береговой линии.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27972, 'ruRU', 'Поддержание боевого духа', 'Вас попросили доставить 6 бочонков южноморского рома с кораблей, затонувших у мыса Потерянной Надежды. Мыс расположен севернее на береговой линии.', 'Наши войска деморализованы, $n. Мы прилагаем все усилия, чтобы поддерживать в солдатах боевой дух, вот только главная составляющая успеха – ром – подходит к концу.$b$bПехотинцы с южного побережья докладывают, что в трюмах кораблей, затонувших у мыса Потерянной Надежды, хранится хороший запас рома. Не $gмог:могла; бы ты проверить, так ли это?$b$bПринеси весь ром, что сможешь найти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27973, 'ruRU', 'Щепки летят!', 'Сержант Грей хочет, чтобы вы принесли 15 единиц лесоматериалов с Верфи Веллсона. Доски можно отнять у призраков, обитающих на верфи, или поднять с земли. Верфь находится на берегу к северо-западу отсюда.', 'Ты уже $gбывал:бывала; на Верфи Веллсона, $n? Без особой нужды лучше держаться от нее подальше. К сожалению, именно туда тебе и придется пойти.$b$bВидишь ли, мы испытываем нехватку припасов с тех самых пор, как высадились на острове. На верфи находится много лесоматериалов, но обжившие ее призраки всякий раз мешают нам забрать их оттуда.$b$bТы не $gмог:могла; бы нам помочь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27974, 'ruRU', 'Это наша земля', 'Убейте барона Эшбери.', 'Неужели ты думаешь, что какая-то жалкая горстка воргенов сможет меня остановить?! Ха!$B$BКрепость Темного Клыка была владением Лордерона при жизни, так что, думаю, будет лишь справедливо, если в посмертии она перейдет во владение Отрекшихся. Годфри и его сообщники не представляют реальной угрозы. Это просто досадная помеха, которую мы без труда устраним. Они предали Темную Госпожу – и заплатят за это!$B$BЭшбери расположился на подступах к крепости – как будто специально напрашивается на то, чтобы его атаковали. Вот с него мы и начнем.', '', 'Первое задание было легким.', 'Барон Эшбери', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27975, 'ruRU', 'Разыскивается: начальник верфи Веллсон', 'Вам предстоит прикончить начальника верфи Веллсона. Верфь расположена к северо-западу отсюда, на западном побережье острова.', 'Начальник верфи Веллсон докучает нам с тех самых пор, как мы попали на остров. На его верфи находится масса припасов, которые бы нам пригодились... если бы мы до них добрались.$b$bОн бдительно следит за своими подчиненными, что осложняет нашу задачу. Итак, я хочу, чтобы ты $gпокончил:покончила; с Веллсоном. Остерегайся солдат Орды, бесчинствующих в округе, $n.', '', 'Когда-то великий человек, а нынче падший начальник пристани Веллсон.', 'Начальник верфи Веллсон', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27976, 'ruRU', 'Будь прокляты эти толстые пальцы', 'Убейте 12 тяжелых боевых големов.', 'К несчастью, из-за проблем с пальцами я уже не способен на столь меткие удары, как раньше. Виноват местный климат и низкое атмосферное давление – пальцы здесь отекают и становятся похожими на гигантские телcамарские кровяные колбаски... $b$bТак что придется тебе побегать по моим делам.$b$bПервое на повестке дня: вышибить дух из тяжелых боевых големов ущелья. Не задерживайся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27977, 'ruRU', 'Самое важное', 'Найдите и верните фурму и подзорную трубу наблюдателя.', 'Раньше у нас всего было больше. Где-то тут была и подзорная труба, и фурма.$b$bЯ практически уверен, что их украли дворфы Черного Железа. Да, я знаю, что я сам из клана Черного Железа. Я говорю о тех, которые живут внизу в ущелье. Они плохие.$b$bПосмотри у кузнецов, которые работают к югу отсюда. Им такие штуки нужнее всего.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27978, 'ruRU', 'Охота за привидениями', 'Вам нужно убить 14 любых призраков на Дозорном пункте Ларго к северо-востоку от лагеря.', 'Видишь гору за нашим лагерем? На ней находится Дозорный пункт Ларго, так что мы выбрали не лучшее место для пристанища. Мы отбиваемся от духов и призраков с того времени, как разбили тут лагерь.$b$bНе $gмог:могла; бы ты наведаться туда и дать им понять, что мы не собираемся никуда уходить? Убей несколько врагов, чтобы донести до них наше послание.$b$bБлагодарю за услугу, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27979, 'ruRU', 'Темное министерство', 'Добудьте шар Киюби, шар Летерио и шар Финистра, а затем объедините их в сумеречный триоцит.', 'У меня есть еще одно задание для тебя. На этот раз от самого инспектора. Похоже, что его сильно обеспокоила новость об этом \"эрцгерцоге\".$b$bОн попросил нас выследить трех министров из культа Сумеречного Молота, которые работают на Гряде Огненной Стражи, к западу отсюда. Их зовут Киюби, Летерио и Финистр, и у каждого из них есть что-то вроде камня. Объедини все три и принеси их сюда.$b$bИ знай: когда инспектор отдает приказы, их не обсуждают. Просто идут и делают.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27980, 'ruRU', 'Пауки должны уйти', 'Убейте 9 лавовых пауков в Тлеющем ущелье.', 'С обычными пауками я могу справиться.$b$bГигантские стеклопутые пауки нравятся мне меньше, но они достаточно далеко, так что о них можно сильно не беспокоиться.$b$bНо лавовые пауки? <Лоло вздрагивает.> Лавовые пауки страшны... Это огромные пауки. Которые живут в лаве.$b$bМне только что заплатили за работу на прошлой неделе, и я охотно заплачу тебе, если ты убьешь этих чудовищ. Их полно по всему Тлеющему ущелью.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27981, 'ruRU', 'Непроходящий жар', 'Соберите 10 наполненных огнеупорных колб. Вы должны наполнять огнеупорные колбы из живых элементалей в Тлеющем ущелье.', 'Мы куем, плавим, прокаливаем все паучье мясо, какое у нас есть. И цыплят еще, если повезет. Я имею в виду, что вся эта работа требует очень много огня.$b$bХорошо, что мы тут прямо в центре огненного города.$b$bКонечно, самый лучший огонь – у элементалей. Их легко найти по всему Тлеющему ущелью, обычно недалеко от скоплений лавы. Вот, возьми вот эти колбы и наполни их огнем элементалей.$b$bАх, да, я сказал, что элементали при этом должны быть живыми?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27982, 'ruRU', 'Сумеречные ожерелья', 'Добудьте 20 сумеречных ожерелий.', 'Ты $gвидел:видела; дурацкие ожерелья, которые носят все эти сектанты Сумеречного Молота? Драгоценные камни в них крупнее, чем кулак Гензеля!$b$bНесколько таких драгоценных камней с хорошую головку сыра – и кузнечное дело Закалона выйдет на новый уровень. Достань мне эти ожерелья, я хорошо заплачу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27983, 'ruRU', 'Приключения Чурбана: маленькие злобные дворфы', 'Добейтесь того, чтобы 7 дворфов из клана Черного Железа ослабли и Чурбан смог их усыпить.', 'Ну что ты делаешь? Зачем убиваешь?$b$bТебе нужно забрать у дворфов вещи? Чурбан понимает. Чурбан придумал лучше.$b$bСлушай: дерись с дворфом, но не убивай! Просто дерись, пока он не устанет. А потом Чурбан усыпит дворфа. Наверное, дворфы такие злые, потому что не спят.$b$bДавай! Доверься Чурбану.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27984, 'ruRU', 'История Лунного Репья', 'Послушайте историю Замеля.', 'Ты поможешь мне, $gсмертный:смертная;? Выслушай мою историю.', 'История Замеля', '', '', '', '', 'Вернитесь к Замелю Лунному Репью на Гряду Огненной стражи в Тлеющее ущелье.', 25549);
INSERT INTO `quest_template_locale` VALUES (27985, 'ruRU', 'Молитва к Элуне', 'Найдите и прочитайте молитву к Элуне.', 'Ты поможешь мне, $gсмертный:смертная;? Ты отыщешь молитву к Элуне?$B$BКак я говорил, молитва выгравирована на золотой табличке. Думаю, они спрятали ее в одном из своих отвратительных сундуков, которые стоят у входа в пещеру, в нижней части гряды.$b$bЕсли ты найдешь мою молитву, не приноси ее мне. Лучше прочитай ее.$b$bЯ совершил столько грехов, что, возможно, просить отпущения – это слишком с моей стороны. Но я не перестану надеяться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27986, 'ruRU', 'У горного владыки', 'Поговорите с горным владыкой Ренданом на Железной вершине, что в Тлеющем ущелье.', 'У Братства Тория нет ополчения – только я да несколько стражников, вот и все. И если мы собираемся победить клан Черного Железа здесь в ущелье, нам понадобится помощь.$b$bГорный владыка Рендан засел наверху вон той башни на другой стороне ущелья, к югу отсюда. Сектантов Сумеречного Молота или огненных элементалей он не поддерживает, но и к нашему Братству не присоединился. Возможно, настало время нанести ему визит. С его помощью у нас будет больше возможностей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27987, 'ruRU', 'Пушечное ядро!', 'Соберите для сержанта Грея 4 груды пушечных ядер, хранящихся на Дозорном пункте Ларго. Он находится к северо-востоку от лагеря.', 'Ларго со своими проходимцами воруют наши боеприпасы с тех самых пор, как мы разбили тут лагерь. Это крайне раздражает.$b$bНам донесли, что Ларго складирует пушечные ядра в башнях, стоящих над водой на его Дозорном пункте. Достанешь нам немного ядер?$b$b$n, остерегайся представителей Орды.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27988, 'ruRU', 'Чума... Чума повсюду!', 'Убейте барона Сильверлейна и командира Спрингвейла.', 'У этой чумы есть одно замечательное свойство – даже если она вроде бы отступает, все равно остается скрытая зараза, обладающая немалой губительной силой. Но кое с кем придется разбираться без помощи чумы: я говорю о прихвостнях Годфри.$B$BПохоже, духи, служившие барону Сильверлейну и командиру Спрингвейлу при жизни, теперь охраняют хозяев и после смерти, а Годфри использует их против нас. Покажи этим мерзавцам, что такое железная воля Отрекшихся!', '', 'Этого мы никак не ожидали.', 'Командир Спрингвейл', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27989, 'ruRU', 'Роумбо просит меда', 'Соберите 10 порций меда Деревни Мертвого Леса из ульев Деревни Мертвого Леса, используя медовую палочку Роумбо.', 'Роумбо голодный!$b$bНегодяи из Оскверненного леса украли весь мед племени Древобрюхов! Мы видели... ээ... Роумбо видел, как они это делали! А теперь Роумбо нужен этот мед!$b$bВозьми эту... эту палку! Да, эту палку. Возьми эту палку и с ее помощью укради мед из их ульев в Деревне Мертвого Леса.$b$bРоумбо нужно как можно больше меда. Это очень важно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27990, 'ruRU', 'Зона боевых действий', 'Командир Шнотц приказывает вам занять место канонира в одном из осадных танков и разобраться с 7 дряхлыми стражами, а затем вернуться к нему.', 'Ты еще один возможность доказывайт свой польза, |3-6($r).$B$BРезультат этот швах мы остаться без раз-два-три канонир.$B$BТы мочь заменяйт один?$B$BМои танк стоять запад лагерь. Марш-марш там и делать порядок!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27991, 'ruRU', 'Освобождение дозорной башни', 'Сержант Грей поручил вам ликвидировать Командира Ларго на Дозорном пункте Ларго. Это место находится к северо-востоку от лагеря.', 'Существует единственный вариант захватить Дозорный пункт Ларго.$b$bВ последнее время парень окончательно спятил: стоит себе на вершине башни и ждет, когда приплывет воображаемый флот. Так что найти его не составит труда.', '', 'Попробуй с ним справиться!', 'Командир Ларго', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27992, 'ruRU', 'Как работают магниты?', 'Вам поручили собрать 7 фрагментов осадных машин. Используйте намагниченный сборщик металлолома на Передовой Неупокоенных, расположенной на западе за вторым мостом.', 'На остров сложно доставить полезные запчасти, $n. Мы пытались на месте починить сломанные осадные машины, но у нас закончились необходимые детали.$b$bИз второго полка доложили об искореженных осадных машинах, стоящих на заброшенном поле боя к западу отсюда. Может быть, там остались какие-то пригодные запчасти?$b$bСложно будет отыскать что-то в груде обломков, так что возьми-ка этот намагниченный сборщик металлолома и воспользуйся им.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27993, 'ruRU', 'Задай им перцу!', 'Мак отправляет вас исследовать гробницу Хартута.', 'Едва ушли, |3-6($c)... Ох, душа у меня будет не на месте, если мы не зададим этим налетчикам по первое число!$B$BВозвращайся-ка к гробнице Хартута и покажи этим засланцам, где раки зимуют!$B$BЭто на северо-востоке прямо за входом в Ульдум, если мне память не изменяет.$B$BЧего смотришь-то? Мне сейчас такое точно не сдюжить!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27994, 'ruRU', 'Роумбо требует правосудия', 'Убейте 15 любых фурболгов Мертвого Леса.', 'Эй, ты! $gСтранник:Странница;! Склонись перед мощью Роумбо, великого божества племени Древобрюхов!$b$bСлушай мою волю! В деревне, что за моей спиной, живет злое племя Мертвого Леса! Они большие придурки!$b$bЯ хочу сказать, они... они... марают мое имя своими злобными деяниями! Преследуют дорогих моему сердцу Древобрюхов и обижают их!$b$bЯ требую, чтобы ты $gсвершил:свершила; правосудие! Победи племя Мертвого Леса, и ты завоюешь мою... мою... благосклонность! Благосклонность самого РОУМБО!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27995, 'ruRU', 'Танец для Роумбо!', 'Исполните для Роумбо глупый танец.', 'Ты отлично $gсправился:справилась;, |3-6($r)! Роумбо доволен твоей храбростью и тем вкусным медом, который ты $gпринес:принесла;.$b$bА теперь ты $gдолжен:должна;... $gдолжен:должна; танцевать! Да!$b$bТанцуй для Роумбо! Танцуй!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27996, 'ruRU', 'Твое время вышло!', 'Убейте лорда Вальдена.', 'Как ты понимаешь, мы вовсе не собираемся слушать, что Кромуш говорит о чуме. Но его грубая сила очень нам пригодится, когда придется сражаться с Годфри и его многочисленными приспешниками. Самый сильный из них, лорд Вальден, первый помощник Годфри, его правая рука.$B$BТвоя задача – прикончить Вальдена. Когда все сделаешь, встретимся в его покоях. И вот тогда крепость Темного Клыка наконец перейдет в руки Отрекшихся!', '', 'Он даже не успеет понять, что его погубило.', 'Лорд Вальден', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27997, 'ruRU', 'Вред Нефритового Пламени', 'Убейте 12 сатиров или скверноподданных из племени Нефритового Пламени в Долине Нефритового Пламени.', 'Очищение этого леса – нелегкая работа. Стоит нам в чем-то добиться успеха, как появляются новые проблемы.$b$bСатиры из племени Нефритового Пламени – это сущее наказание. Как мы хотим очистить этот лес, так они хотят его осквернить. Сейчас мы предпринимаем некоторые шаги для того, чтобы окончательно изгнать их из Оскверненного леса.$b$bОтправляйся на запад, в Долину Нефритового Пламени и очисти лес от их присутствия. Вход в Долину находится севернее стен Деревни Мертвого Леса. Ищи их мерзкие знамена.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27998, 'ruRU', 'Сладкая, беспощадная месть', 'Убейте лорда Годфри.', 'Если все будет нормально, ты сможешь войти прямо в личные владения Годфри и взять награду, достойную $gстоль отважного и рьяного:столь отважной и рьяной:c; |3-1($c).$B$BОднако Годфри хитер и коварен, так что тебе лучше поторопиться. На всякий случай. Вдруг твоя помощь понадобится где-то еще! Он дорого заплатит за то, что сделал с Темной Госпожой!', '', 'За Сильвану!', 'Лорд Годфри', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (27999, 'ruRU', 'Судьба Дойлов', 'Вернитесь на Кладбище Огнебородов и сообщите Иэну Огнебороду о судьбе клана Дойлов.', 'Похоже, этот бой стал последним для Дойлов. Нужно сообщить Иэну об их судьбе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28000, 'ruRU', 'Сделать невозможное', 'Сделайте так, чтобы Бесенок ослаб, а затем поймайте его при помощи заколдованного бесовского мешка.', 'Сатиры окружают свои лунные колодцы барьерами из демонического огня, сквозь которые невозможно пройти. Но им наверняка известен способ, как пробраться через этот огонь.$b$bСпрашивать у сатиров бесполезно, а вот с бесами, которые имеют с ними дело, договориться гораздо проще. Я тут подумала об одном из них...$b$bВ предгорьях к востоку отсюда, отдельно от остальных демонов бродит одинокий бес. Его одолеть несложно. Напади на него, дождись, когда он ослабеет, а потом воспользуйся заколдованным мешком, чтобы его схватить. Затем я его допрошу...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28001, 'ruRU', 'Удел труса', 'Идите в Громтар и поговорите с Колином Громтаром.', 'Здесь мы в безопасности – однако множество кланов Громового Молота нуждается в помощи. Наш отряд всадников на грифонах мог бы поддержать их, однако если мы хотим окончательно уничтожить Сумеречный Молот, нам понадобится подкрепление.$B$BЯ собираюсь потолковать об этом с Колином Громтаром. Думаю, он не откажет мне в помощи – ведь только трус может отвернуться от своего народа, особенно в такую тяжелую минуту.$B$BИди в Громтар, разыщи Колина и потребуй от него объяснений. Я не потерплю, чтобы кланами Громового Молота командовали трусы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28002, 'ruRU', 'Антикризисное управление', 'Беллок Сияющий Клинок хочет, чтобы вы успокоили гостей в лагере Шнотца.', 'Возникла деликатная ситуация, необходим... объективный взгляд со стороны.$B$BНекоторые гости несколько обеспокоены произошедшим инцидентом. Правда, этим уже занялись наши лучшие бойцы.$B$BА ты пока успокой наших самых щепетильных визитеров.$B$BЕсли справишься, я доложу о тебе на самый верх!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28028, 'ruRU', 'Осада!', 'Убейте 9 стрелков из клана Черного Железа.', 'Худшего времени, чтобы попросить меня вступить в бой, надзиратель Скользорук выбрать не мог. Эту вершину и так уже осаждает неприятель!$b$bМои ребята справятся с чем угодно, но все же мне будет нелегко вот так взять и послать несколько дворфов в это дьявольское ущелье.$b$bВот что я тебе скажу: если справишься со стрелками, которые окружили нашу крепость, я рассмотрю твое предложение. Их целая уйма на равнине к востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28029, 'ruRU', 'Задай им жару!', 'При помощи факела воздаяния подожгите четыре башни, окружающие Котлован.', 'Не знаю, $gзаметил:заметила; ли ты, но мои башни гораздо выше любых других башен ущелья. Некоторые дворфы гордятся тем, как глубоко они копают, но только не я. Иногда мне кажется, что я должен был родиться в клане Громового Молота.$b$bТем не менее, мне не очень нравится, как выглядят те, другие башни. Растут, понимаешь ли, догоняют мои. Вот, возьми этот факел и подожги с его помощью жаровни наверху тех башен. Они еще пожалеют, что вообще построили их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28030, 'ruRU', 'Пули у них отменные', 'Соберите 200 пуль Черного Железа.', 'По крайней мере одну вещь эти роющиеся в ущелье дворфы делают правильно: пули у них превосходные. У меня не получается добиться такого же качества, поэтому я привык воровать их пули, все, какие найду.$b$bХочешь, чтобы я помог тебе? Принеси мне пару сотен пуль от этих стрелков внизу.$b$bУверен, они охотно поделятся с тобой пулями, отдавая их по одной, но если ты найдешь целые ящики – получится быстрее.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28031, 'ruRU', 'Особая посылка для Бривельверпа', 'Отнесите криопушку \"Морозко\" Бривельверпу на Затопленные раскопки в Тысяче Игл.', 'У меня новый деловой партнер – мой лучший друг Бривельверп. Пока мы тут лясы точим, он закладывает фундамент нашей новой империи мороженого!$B$BБривельверп отвел наш холодильный буксир, оборудование и рабочих на юго-запад, к Затопленным раскопкам. К сожалению, у меня нет возможности отправить ему кое-что... кое-что очень важное: нашу сверхсекретную криопушку \"Морозко\"!$B$BТы не $gмог:могла; бы отнести ее Бривельверпу, $n?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28032, 'ruRU', 'Тайны пламенной кишки', 'Добудьте 6 пламенных кишок.', 'Мы очень многого не знаем о пламезаврах. Откуда они взялись? Как они выживают на этих равнинах? И почему они такие мерзкие на вкус?$b$bДумаю, что ключ к секрету этих доисторических животных – в их пламенных кишках. Они есть у всех пламезавров. И я бы хотела иметь несколько для изучения.$b$bПламезавров можно найти у Железной вершины, в основном в западной части.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28033, 'ruRU', 'Обман', 'Найдите способ убедить горного владыку Рендана присоединиться к Братству Тория.', 'Что? Почему ты все еще здесь? А, я обещал, что помогу тебе и Братству Тория в вашей битве?$b$bЯ врал.$b$bЯ просто не могу выделить бойцов. Знаю, я обещал помочь, но вы никак не убедите меня покинуть сейчас Железную вершину. Абсолютно никак.', '', '', '', '', '', 'Поговорите с Чурбаном на Железной вершине в Тлеющем ущелье.', 25549);
INSERT INTO `quest_template_locale` VALUES (28034, 'ruRU', 'Приключения Чурбана: слабость Рендана', 'Поговорите с тремя стражами Железной вершины и попросите их присоединиться к танцу.', 'Чурбан не очень умный, но зато наблюдательный. Сегодня Чурбан заметил, что этому горному дворфу нравится смотреть, как танцуют.$b$bЧурбан любит танцевать! $n любит танцевать!$b$bМожет быть, мы найдем еще дворфов, которые любят танцевать. А потом пойдем к этому горному дворфу, и он послушается |3-1($n).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28035, 'ruRU', 'Поддержка горного владыки', 'Отчитайтесь о вашем успехе надзирателю Скользоруку в лагере Братства Тория в Тлеющем ущелье.', 'Ладно, ладно! Если бы я знал, что вы так танцуете, я бы не стал вас просить делать все остальное.$b$bСкажите надзирателю Скользоруку, что я присоединюсь. Встретимся в Шлаковой яме! Когда Братство Тория объединится с Железной вершиной, эти дворфы из ущелья вообще не поймут, кто на них напал!', '', '', '', '', '', 'Поговорите с надзирателем Скользоруком в Братстве Тория, что в Тлеющем ущелье.', 25549);
INSERT INTO `quest_template_locale` VALUES (28038, 'ruRU', 'Кровь на нагорье', 'Поговорите с троллем-прислужником Водином в Горниле Крови на Сумеречном нагорье.', 'Похоже, |3-6($c), силенок тебе не занимать. Быть может, в Горниле Крови тебя ждет успех...$B$BЧто?! Ты ни разу не $gслышал:слышала; о Горниле Крови? Сладкоречивый гоблин Гаргток со своим помощником-троллем заваливает нас рекламными брошюрами с тех самых пор, как он открыл на нагорье этот свой цирк. Бойцы со всех концов Азерота приезжают сюда, чтобы принять участие в поединках не на жизнь, а на смерть. Собери своих друзей и испытай свои силы.$B$BГорнило Крови находится к юго-западу отсюда. Как увидишь огромный ринг из костей, а в нем – тролля-прислужника Водина, знай – ты на месте.', '', '', '', '', '', 'Поговорите с троллем-прислужником Водином в Горниле Крови на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (28041, 'ruRU', 'Наживка для грифона', 'Добудьте свежую грифонью тушу.', 'Да, $n, на земле ты можешь постоять за себя. Этого у тебя не отнимешь.$B$BНо мы, Драконья Пасть, властвуем не только на земле, но и в небе. И пока ты не докажешь, что можешь управляться с драконом не хуже моих родичей, твоя Орда – пустой звук для меня.$B$BЧто ж, посмотрим, удастся ли тебе привести дракона в Кровавое ущелье.$B$BДля начала тебе понадобится наживка. Иди в лес, на запад или северо-запад, и убей грифона. Но только дикого! Ведь если от пищи воняет дворфами, дракон к ней не прикоснется.$B$BА когда у тебя будет туша грифона, ты поймешь, что с ней делать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28042, 'ruRU', 'Особая посылка для Бривельверпа', 'Отнесите криопушку \"Морозко\" Бривельверпу на Затопленные раскопки в Тысяче Игл.', 'Мне тут по случаю досталось кое-что, что должны были доставить некому гному, Бривельверпу. По мне – так он скорее Дуреньверп.$B$BКак бы там ни было, хочу, чтобы ты $gотнес:отнесла; это на юго-запад, к Затопленным раскопкам. Он что-то замыслил, и дельце пахнет бабками – я прямо чую!$B$BПрисмотрись там, что он затевает, $n, и покумекай, как можно отхватить долю. Знатную долю!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28043, 'ruRU', 'Как искалечить своего дракона', 'Завлеките приманенного черного дракона, бейте его до тех пор, пока он не ослабнет, а затем летите на нем в Кровавое ущелье.', '<Вы вскидываете на плечо окровавленную тушу грифона; его длинные крылья волочатся за вами по земле.>$B$B<Черные драконы селятся к юго-западу от Горнила Крови, вокруг невысоких гор, образующих кольцо.>$B$B<Если бросить тушу грифона там, она непременно привлечет какого-нибудь дракона. Когда его внимание будет поглощено едой, вы сможете напасть на него и ослабить настолько, что он позволит себя оседлать.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28044, 'ruRU', 'Дотронуться до недосягаемого', 'Встаньте на знак Тихондрия, воспользуйтесь межфазовым зельем крови, чтобы перенестись в Пустоту и найти коготь Тихондрия.', 'Я добавил в зелье частицу моего собственного естества. Видишь мерцающий знак у Гряды Затаившейся Тьмы, к западу отсюда? Встань на него, сосредоточься и вылей зелье на себя. Этого должно быть достаточно для того, чтобы перенестись в Пустоту и увидеть, что там НА САМОМ ДЕЛЕ.$b$bТы будешь не $gодин:одна;... сокровище сатиров охраняет самый большой страж Пустоты, какого они только смогли призвать. Одолей его, и сокровище твое.$b$bИ возвращайся $gцелым и невредимым:целой и невредимой;, иначе эта ненормальная меня зажарит!', '', 'Страж Пустоты, в его руках то, что вы ищете.', 'Ворл', 'Теперь не двигайся.', 'Чародейка Деларис', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28045, 'ruRU', 'Лучший в мире вкус!', 'Соберите 8 пригоршней слизи силитида.', 'Прямо под нами – пещера. Огромная! Прекрасное место для нашего нового хладобункера. И достаточно большое, чтобы разместить все наше оборудование и иметь запас для расширения производства.$B$BК сожалению, когда мы провели почти все трубы, откуда ни возьмись полезли насекомые и перебили рабочих!$B$BНу, а откуда мне было знать?$B$BЗато у меня родилась гениальная идея: мороженое со вкусом силитидов! Это будет мега-хит!$B$BВсе, что мне нужно сейчас, – это ингредиенты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28046, 'ruRU', 'Завершение работы', 'От вас требуется уничтожить 5 неупокоенных пехотинцев на Передовой Неупокоенных. Это место расположено на западной стороне острова на подступах к Забытому холму.', 'Всю неделю мы пытались принести пригодные запчасти с Передовой. И всякий раз, когда мы несли детали в лагерь, на нас нападали неупокоенные солдаты. Ты бы не $gсогласился:согласилась; расчистить наш путь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28047, 'ruRU', 'Заморозка труб', 'С помощью криопушки \"Морозко\" заморозьте 4 трубы в пещере.', 'Что ж, пора распечатать нашу криопушку \"Морозко\"!$B$BМы скопировали технологию морозных пушек с гоночных судов. В чем нам, гномам, нет равных– так это в миниатюризации за счет делания всего окружающего во-о-от таким громадным!$B$BТы $gдолжен:должна; спуститься с пушкой в пещеру и заморозить трубы, вмонтированные в стены. Это запустит процесс.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28048, 'ruRU', 'Умникам здесь не место', 'Уничтожьте надсмотрщика улья.', 'Глубоко в пещере засел какой-то шибко умный жучила. И заправляет всеми силитидами, которые там развелись.$B$BУ меня мороженое тает! Как я, по-твоему, построю империю мороженого и сберегу свои запасы, если там хозяйничает эта тварь?!', '', 'Уничтожьте его во имя будущего процветания империи мороженого!', 'Надсмотрщик улья', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28049, 'ruRU', 'Увидеть невидимое', 'Соберите 8 порций слизи проклятых слизнюков в руинах Констелласа.', 'Да, да, твоя заносчивая подружка-магичка все правильно поняла. Бесы Гряды Затаившейся Тьмы прячут ключ от барьера сатиров, преграждающего путь в Пустоту. Он есть, но пока ты не $gоказался:оказалась; там, нельзя ни увидеть его, ни прикоснуться к нему.$b$bВ общем, думаю, вам не повезло, потому что только бесам доступны подобные перемещения. Так что тебе стоит просто закрыть глаза, отвернуться и дать мне уйти восвояси...$b$bШутка! Не бей меня! Мне нужна слизь проклятых слизнюков, которых полно в этих руинах. Принеси мне столько, чтобы хватило, чтобы покрыть тебя с головы до ног!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28050, 'ruRU', 'Акула Амбал', 'Вам поручено убить Амбала, гигантскую акулу, плавающую в водах у мыса Потерянной Надежды. Мыс расположен севернее, если идти вдоль береговой линии.', 'Ненавижу акул. И все мои солдаты тоже. Тут-то ты нам и пригодишься, $n.$b$bПоднимись к мысу Потерянной Надежды и убей гигантскую акулу по имени Амбал. Ее не стоит недооценивать, так что лучше прихвати с собой на подмогу парочку друзей.', '', 'У этой рыбины действительно огромные челюсти.', 'Амбал', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28051, 'ruRU', 'Мы положили жизни за мороженое!', 'Прицепите буксирный трос к телам 10 погибших рабочих.', 'Ты не думай... Это я внешне такой веселый, но внутри душа на части рвется. Все мои друзья, мои работники – мертвы...$B$BСделай одолжение: сплавай вниз и прицепи к телам моих рабочих этот буксирный трос. А я вытяну их на поверхность.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28052, 'ruRU', 'Операция: переполох в Котловане', 'Поговорите с распорядителем полетов Братства Тория, а затем воспользуйтесь орудиями ветролета Братства, чтобы убивать защитников Котлована, пока место посадки не станет безопасным.', 'Я посажу тебя на ветролет, $n.$b$bБудешь отвечать за мягкость нашей посадки в Шлаковой Яме. Поговори с распорядителем полетов здесь в Братстве Тория, а затем лети в ущелье.$b$bКогда приблизишься к точке посадки, там тебя наверняка будут ждать толпы дворфов Черного Железа. Воспользуйся орудиями на борту ветролета, чтобы уложить как можно больше, а затем приземляйся у входа в пещеру. К тому моменту Рендан должен уже ждать тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28053, 'ruRU', 'Чурбану нравится, что ты делаешь', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28054, 'ruRU', 'Рабство – это плохо', 'Убейте 10 надсмотрщиков или поработителей из клана Черного Железа.', 'Как и надзиратель Мальторий, я богат. Я достиг этого, принимая мудрые решения и упорно работая, а не занимаясь работорговлей.$b$bНу, ладно, почти не занимаясь работорговлей. Почти совсем.$b$bВ любом случае, первое, что бросается в глаза в этих пещерах – это надзиратели и надсмотрщики за рабами. Я не собираюсь это поддерживать! По мере продвижения вглубь пещеры убивай всех, кого сможешь. О результатах сообщи Эвонис Сажекурке, ее можно найти в глубине Шлаковой Ямы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28055, 'ruRU', 'Сладкая горечь свободы', 'Освободите 12 рабов-трудяг. Если они будут сопротивляться, убивайте их.', 'Раз уж мы здесь, нужно освободить как можно больше рабов. Скорее всего многие из них присоединятся к нам, сгорая от желания отомстить своим поработителям.$b$bНо в то же время некоторые рабы не пожелают вновь обрести свободу. Это удивительный феномен, его еще часто называют \"Дарнхольдским синдромом\".$b$bТак или иначе, ты $gдолжен:должна; попытаться освободить их. Если они будут сопротивляться, относись к ним, как к врагам. О результатах сообщи Эвонис Сажекурке, ее ты найдешь в глубине Шлаковой Ямы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28056, 'ruRU', 'Восстань, Обсидион', 'Воспользуйтесь алтарем Сунтары, а затем убейте Латорика Черного и Обсидиона.', 'Здесь всем заправляет надзиратель Мальторий, но он не единственный могущественный дворф в Шлаковой Яме. В глубине этого коридора обитают Латорик Черный и его ужасающий голем, Обсидион.$b$bПризвать обоих можно при помощи алтаря Латорика. Найди алтарь, призови Латорика и убей его. Когда закончишь, отчитайся Эвонис Сажекурке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28057, 'ruRU', 'Казнь через лишение сна', 'Добудьте 16 подушек дворфов Черного Железа.', 'Мало кто знает о том, что дворфы, особенно дворфы из клана Черного Железа, нуждаются в отдыхе! В хорошем регулярном отдыхе!$b$bА теперь я спрошу тебя: как они смогут спать, если у них не будет подушек? Вот именно, $n. Никак! Поэтому ты $gдолжен:должна; и украсть их подушки.$b$bА когда закончишь свою подушечную аферу, поговори с надсмотрщиком Скренджем. Он вместе с Гензелем работает над убежищем, это немного глубже внутри пещеры.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28058, 'ruRU', 'Размер имеет значение', 'Отнесите подушку горничной Крепкие Тиски Эвонис Сажекурке в Тлеющее ущелье.', 'Так, так, так... ну не сюрприз ли это. У горничной была огромная подушка с орнаментом и теперь она твоя. Эвонис Сажекурка определенно захочет прибрать эту подушку к своим маленьким жадным ручонками. Отнеси подушку ей, может быть, она чем-то отблагодарит тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28059, 'ruRU', 'Взятие крепости', 'Вас просят убить начальника крепости Фарсона. Его крепость находится на северной стороне острова.', '$gВидел:Видела; крепость в северной части острова, $n? Там обосновался некий Фарсон.$b$bФарсон со своими немногочисленными приспешниками докучают нам с тех пор, как мы пришли в эти места. Мы отправили в разведку небольшой отряд, который установил точное местоположение Фарсона в крепости.$b$bТы поможешь нам покончить с ним?', '', 'У него преданные подчиненные. Не нужно их недооценивать.', 'Начальник крепости Фарсон', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28060, 'ruRU', 'Запутанные связи Сумрака', 'Поговорите с Гензелем Большеруком и помогите ему напасть на надзирателя Мальтория и сумеречного лорда Арккуса.', 'Мы с Гензелем находимся при выполнении секретного задания: убить надзирателя Мальтория. Хотя главная наша цель остается прежней – победить эрцгерцога Кальциндера – если мы заодно избавимся от этого гнусного надзирателя Шлаковой Ямы, хуже не будет.$b$bПроблема в том, что Гензель готовился лишь к битве с одним дворфом, но, похоже, что у Мальтория сейчас гость... эмиссар из Сумеречного Молота!$b$bПоговори с Гензелем и помоги ему. А потом иди дальше по коридору вдоль внешнего балкона и найдешь надзирателя Скользорука.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28061, 'ruRU', 'Приспешники Кальциндера', 'Убейте 6 пламенных призраков.', 'Чем глубже копаешь, тем больше нюансов, $n. Бывает, найдешь богатейшие залежи минералов глубоко под землей, но одновременно наткнешься и на самых злобных существ.$b$bНапример, огненных элементалей.$b$bВ пещере, что перед нами, полно приспешников Кальциндера. И в каждом из них заключена частица его злой сущности. Убей, скольких сможешь, никого не щади.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28062, 'ruRU', 'Туда, откуда он пришел', 'Добейтесь того, чтобы эрцгерцог Кальциндер ослаб, а затем воспользуйтесь освященным триоцитом, чтобы изгнать его.', 'Эрцгерцог Кальциндер укрылся в глубине этой самой пещеры. Мы близки к тому, чтобы убить его... но мы поступим по-другому.$b$bУбийство Кальциндера ничего не решит. Его пособники легко смогут оживить его. Вместо этого мы его изгоним.$b$bРаньше я просил тебя достать один ценный камень Сумеречного Молота. Теперь ты используешь его против Кальциндера. Напади на него, добейся того, чтобы он ослаб, а затем используй камень. И он будет изгнан в свой мир.$b$bУдачи тебе, $gхрабрый:храбрая; $n.', '', 'Я не потреплю никаких приспешников Рагнароса вблизи лагеря Братства Тория. Отправьте его туда, откуда он пришел.', 'Эрцгерцог Кальциндер', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28063, 'ruRU', 'Забрать все оружие', 'Вам поручили забрать 12 ржавых винтовок из Крепости Фарсона, расположенной в северной части полуострова Тол Барад.', 'На этом острове сложно достать боеприпасы. Всякий раз, как на нас нападает Орда, создается ощущение, что мы сражаемся с помощью камней и палок.$B$BМне доложили, что в Крепости Фарсона на северной стороне острова есть винтовки, которые мы могли бы использовать. Ты не $gмог:могла; бы туда наведаться?$b$bБудь $gосторожен:осторожна;, $n, приспешники Фарсона сделают все, чтобы защитить его.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28064, 'ruRU', 'Добро пожаловать в Братство', 'Отчитайтесь надзирателю Скользоруку в Братстве Тория, что в Тлеющем ущелье.', 'Тебе нужно возвращаться в Братство Тория. Надзирателю Скользоруку и остальным членам Братства будет интересно узнать, как ты $gсправился:справилась; с Кальциндером.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28065, 'ruRU', 'По вражеским тропам', 'Сопроводите заключенного Крепости Фарсона в безопасное место. Данная крепость расположена в северо-западной части острова.', 'За несколько недель мы послали уже три группы на разведку обстановки в Крепости Фарсона. К сожалению, ни одна из них не принесла никаких сведений.$B$BВ данный момент мы можем только уповать на то, что они живы и просто находятся в заключении. Я хочу, чтобы ты $gотправился:отправилась; в крепость и $gпомог:помогла; в освобождении наших солдат. Это будет непросто, $n, но именно ты в силах нам помочь.', 'Узник крепости Фарсона сопровожден', 'Кажется, ему нужна помощь.', 'Узник Крепости Фарсона', '', '', 'Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.', 25549);
INSERT INTO `quest_template_locale` VALUES (28068, 'ruRU', 'Требуются герои: Глубины Черной горы', 'Поговорите с Морганой.', 'По повелению короля Андуина Ринна всем отважным искателям приключений надлежит немедленно явиться в Глубины Черной горы, что находятся к северо-западу от Дозора Морганы!$B$BДворфы Черного Железа представляют серьезную угрозу для жителей Красногорья! Если вы решите откликнуться на этот призыв, отправляйтесь в Глубины Черной горы, где вам надлежит обратиться к Моргане, которая недавно вернулась после длительного отсутствия и полна решимости отомстить дворфам Черного Железа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28069, 'ruRU', 'Требуются герои: Глубины Черной горы', 'Поговорите с верховным палачом Нузраком.', 'По повелению вождя всем отважным искателям приключений надлежит явиться в Глубины Черной горы, что находятся к западу от Пламенеющего Стяга!$B$BДворфы Черного Железа уже нападали на принадлежащее Альянсу Красногорье. Если ничего не предпринять, то вскоре они могут начать угрожать и владениям Орды на юге Азерота.$b$BЕсли вы решите откликнуться на этот призыв, отправляйтесь в Глубины Черной горы, где вам надлежит обратиться к верховному палачу Нузраку, который занимается перегруппировкой сил Каргатского экспедиционного корпуса, чтобы раз и навсегда покончить с дворфами Черного Железа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28084, 'ruRU', 'Мощь Кром\'гара', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28085, 'ruRU', 'Беда в Скальном гнездовье', 'Поговорите с Паокой Ходячей Горой в Скальном гнездовье в Тысяче Игл.', 'Благодарю тебя за помощь, $n. Поговори с Паокой Ходячей Горой в Скальном гнездовье к юго-западу отсюда.$B$BБыть может, он знает, где скрывается мудрая старица.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28086, 'ruRU', 'Свободу гордокрылам!', 'Освободите 12 детенышей гордокрыла Скального гнездовья.', 'Ловчие загоняют всех молодых ветрокрылов. Будь $gдобр:добра;, $n, освободи детенышей гордокрылов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28087, 'ruRU', 'Смерть ловчим!', 'Раздобудьте 8 ловчих сетей.', 'Только одного достойны эти мерзкие ловчие из клана Сумеречного Молота! Смерти!$B$BПринеси мне их сети, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28088, 'ruRU', 'Освободите Сердцереза', 'Освободите Сердцереза от всех сдерживающих его пут.', 'Культ Сумеречного Молота захватил главного самца Скального гнездовья. Иди на восток вверх по горе и освободи Сердцереза, пока прайд не потерял своего вожака!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28089, 'ruRU', 'Приказ вождя: предгорья Хилсбрада!', 'Отчитайтесь верховному палачу Дарталии у Южных врат в предгорьях Хилсбрада.', 'Всем годным к военной службе подданным Орды надлежит явиться к верховному палачу Дарталии в предгорья Хилсбрада к Южным вратам. Боевая машина Отрекшихся движется вперед и вперед, защищая Лордерон!$b$bЧтобы добраться до Южных врат, нужно идти по дороге на юг через Серебряный бор, а на развилке повернуть на восток, на дорогу, ведущую к предгорьям Хилсбрада.$b$bВперед, $gбрат:сестра;! Судьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28090, 'ruRU', 'Ценный груз', 'Найдите камень-ключ Сумеречного каравана. Ключи от сундуков с камнями-ключами должны быть у сумеречных копьеносцев.', 'Врата, открывающие проход дальше, заперты. Разведчики сообщают, что караванщики открывают их с помощью особых камней, которые возят в сундуках.$B$BСпустись в ущелье и постарайся раздобыть ключ от такого сундука у одного из убитых охранников. Потом найди фургон с сундуком, открой сундук и принеси мне камень-ключ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28091, 'ruRU', 'Легкая добыча', 'Убейте 8 сумеречных копьеносцев.', 'Нападение из засады прошло, как и было задумано. Мы перебили почти всех охранников, но несколько осталось за фургонами.$B$BОни находятся в ущелье, к западу отсюда. Уничтожь их, чтобы мы могли двинуться дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28092, 'ruRU', 'Если ключ подходит...', 'Ведите подрывной отряд к закрытым вратам Драконьей Пасти.$B$BЕсли вы потеряете отряд, возвращайтесь к полководцу Кроггу за новым заданием.', 'Драконы уже вступили в бой в небе над Грим Батолом. Пришло время нам пойти вперед и захватить врата.$B$B$C, знай: ставки очень высоки. Из Грим Батола Сумеречный Молот отправляет подкрепления во все уголки Нагорий. Если мы не возьмем город, победы в войне нам не видать.$B$BЯ дам тебе подрывной отряд. Иди на юго-восток, к вратам, и захвати их. За дальнейшими распоряжениями обращайся к Патчу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28093, 'ruRU', 'Наступление', 'Проведите подрывной отряд через северные врата Драконьей Пасти к входу в Грим Батол.$B$BЕсли вы потеряете отряд, возвращайтесь в Излучину Змея к полководцу Кроггу.', 'Пока ты действуешь неплохо. За следующими вратами должен быть вход в Грим Батол. Нам нужно его найти.$B$BМне приказали захватить этот вход и обеспечивать его безопасность, пока остальные наши ребята не пройдут по расчищенному пути. Если мы поторопимся, то Тиккер сможет вдоволь порезвиться.$B$BИдем по ущелью на юго-запад. Врата должны быть где-то недалеко.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28094, 'ruRU', 'Прокладывая путь', 'Пробиваясь к входу в Грим Батол, убейте 30 служителей культа Сумеречного Молота в Излучине Змея.', 'Мне приказано отправиться вместе с тобой на юг – через врата Драконьей Пасти к входу в Грим Батол. Нам нужно расчистить путь для основных сил, которые и захватят врата.$B$BПеревожу: убивай все, что движется, а если тебе это нравится – тем лучше.$B$BПарни уже рвутся в бой, так что идем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28096, 'ruRU', 'Добро пожаловать в систему', 'Вручите 3 задания.', 'Подойди сюда, $gмилый юноша:милая девушка;. Сигару? Тебе, как высокоранговому офицеру Отрекшихся, предстоит стать птицей высокого полета. Нет, в самом деле, тебя ждет прекрасная жизнь!$b$bЯ хочу, чтобы ты $gвзял:взяла; эти задания и $gраздал:раздала; их тем слабакам, которые интересуются работой. Кого из них выбрать – решай $gсам:сама;.$b$bКогда будешь $gготов:готова;, вскакивай на мою верную костлявую конягу и вперед к новой жизни! Ну то есть встань тут и жди.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28097, 'ruRU', 'Врата Грим Батола', 'Отправляйтесь в Излучину Змея и поговорите с полководцем Кроггом.', 'Крогг уже пошел в атаку. Он к юго-востоку отсюда, сразу за вратами.$B$BЯ соберу отряд и поведу его в наступление. Увидимся там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28098, 'ruRU', 'Распорядитель полетов Сумеречного Молота', 'Летите на Сердцерезе в Сумеречное гнездилище и покончите с сумеречным повелителем небес Рихтофеном.', 'Наверху на юго-востоке, в Сумеречном гнездилище, расположился сумеречный повелитель небес Рихтофен. Если мы с ним не разделаемся – все наши усилия здесь внизу напрасны, надежды для Скального гнездовья нет.$B$BХоть Сердцерез пока еще слишком слаб, чтобы помочь тебе в бою, он сможет отнести тебя на вершину. Остальное я вверяю тебе, $n.$B$BУдачи.', '', 'Подстрели его с воздуха!', 'Сумеречный повелитель небес Рихтофен', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28099, 'ruRU', 'Раша\'крак', 'Добудьте сковывающие браслеты Раша\'крака.', 'Из найденной тобой информации можно заключить, что один из приспешников этого \"эрцгерцога\" уже обратил свое внимание на лагерь Братства Тория.$b$bЕго зовут Раша\'крак, он обитает у озер лавы к югу отсюда. Он похож на тех огненных элементалей, что свирепствуют неподалеку, за одним лишь небольшим исключением: на запястьях у него сковывающие браслеты.$b$bНайди его и принеси мне эти браслеты, $n. Прежде чем мы позволим втянуть себя в войны с элементалями, я хочу быть уверенным, что нам действительно угрожает опасность.', '', 'Он наблюдает за входом в лагерь Братства Тория. Чего он хочет?', 'Раша\'крак', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28100, 'ruRU', 'Говорящий тотем', 'Поговорите с тотемом Роумбо у Деревни Мертвого Леса.', 'Деревня фурболгов, что к югу отсюда, – это дом племени Мертвого Леса, заклятых врагов племени Древобрюхов. Как и на многих других, на них тоже подействовала порча этих лесов, приведя их к безумию.$b$bВозле этой деревни происходит что-то необычное. Проходившие там путники рассказывали, что видели у дороги тотем, который разговаривал с ними.$b$bНо я ничего не слышал, хотя много раз проходил мимо. Может быть, этот тотем захочет поговорить с тобой, $n? Может быть, тебе удастся выяснить, в чем дело?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28101, 'ruRU', 'Под началом Матиаса', 'Отправляйтесь в ущелье Драконьей Пасти и поговорите с мастером Матиасом Шоу.', 'Недавние события показали, что для обеспечения безопасности и тем более для освобождения Грим Батола одиночных вылазок недостаточно. Нам нужно действовать более агрессивно – необходимо нанести удар в самое сердце врага.$B$BМы отправим драконов к вашим командирам. Они уже разрабатывают план операции по штурму Грим Батола, так что тебе тоже стоит уделить этому внимание.$B$BМатиас Шоу находится на Тропе Драконьей Пасти, что к югу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28102, 'ruRU', 'Борись с властью', 'Убейте 8 разбойников или тенеловов из племени Нефритового Пламени в руинах Констелласа.', 'Пришло время для заключительного удара по племени Нефритового Пламени!$b$bЕсли ты $gготов:готова; пройти через их грязный барьер и сразиться с их вожаком, я хочу попросить тебя заодно убить и их младших сатиров. Наши друиды яростно сражаются, но твоя сила не будет лишней.$b$bДай сатирам понять, что им больше не придется властвовать в этих землях!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28103, 'ruRU', 'Легкая добыча', 'Убейте 8 сумеречных копьеносцев.', 'Нападение из засады прошло, как и было задумано. Мы перебили почти всех охранников, но несколько осталось за фургонами.$B$BУничтожь их, чтобы мы могли двинуться дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28104, 'ruRU', 'Ценный груз', 'Найдите камень-ключ Сумеречного каравана. Ключи от сундуков с камнями-ключами должны быть у сумеречных копьеносцев.', 'Врата, открывающие проход дальше, заперты. Разведчики сообщают, что караванщики открывают их с помощью особых камней, которые возят в сундуках.$B$BСпустись в ущелье и постарайся раздобыть ключ от такого сундука у одного из убитых охранников. Потом найди фургон с сундуком, открой сундук и принеси мне камень-ключ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28105, 'ruRU', 'Кавем Бессердечный', 'Заберите неферсетский ключ у Кавема Бессердечного.', 'Кавем отличался жестокостью еще до объединения неферсетов со Смертокрылом – теперь же его садизм граничит с безумием.$B$BЭто он хранит ключи от наших оков.$B$BНайти его можно в соседнем здании, справа.$B$BРазыщи его и забери у него ключ. Не колеблись и не проявляй сострадания – он при первом удобном случае перерезал бы тебе горло без каких-либо раздумий.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28106, 'ruRU', 'Врата Грим Батола', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (28107, 'ruRU', 'Прокладывая путь', 'Пробиваясь к входу в Грим Батол, убейте 30 служителей культа Сумеречного Молота в Излучине Змея.', 'Мне приказано отправиться вместе с тобой на юг – через врата Драконьей Пасти к входу в Грим Батол. Нам нужно расчистить путь для основных сил, которые и захватят врата.$B$BПеревожу: убивай все, что движется, а если тебе это нравится – тем лучше.$B$BУ парней уже шило в одном месте, так что идем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28108, 'ruRU', 'Если ключ подходит...', 'Ведите отряд Высокого берега к закрытым вратам Драконьей Пасти.$B$BЕсли вы потеряете отряд, возвращайтесь к мастеру Матиасу Шоу за новым заданием.', 'Драконы уже вступили в бой в небе над Грим Батолом. Пришло время нам пойти вперед и захватить врата.$B$B$C, знай: ставки очень высоки. Из Грим Батола Сумеречный Молот отправляет подкрепления во все уголки нагорья. Если мы не возьмем город, победы в войне нам не видать.$B$BЯ дам тебе отряд из Высокого берега. Иди на юго-восток, к вратам, и захвати их. За дальнейшими распоряжениями обращайся к своему лейтенанту.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28109, 'ruRU', 'Наступление', 'Проведите ваш отряд через северные врата Драконьей Пасти к входу в Грим Батол.$B$BЕсли вы потеряете отряд, возвращайтесь в Излучину Змея к мастеру Матиасу Шоу.', 'Пока ты действуешь неплохо.$B$BЗа следующими вратами должен быть вход в Грим Батол. Мне приказали захватить этот вход и удерживать до подхода основных сил.$B$BИдем по ущелью на юго-запад. Врата должны быть где-то недалеко.', '', '', '', '', '', 'Поговорите с Каленом у входа в Грим Батол на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (28111, 'ruRU', 'Проблемы в Лазуритовом рудника', 'Отчитайтесь капитану Кейтону в Лазуритовом руднике в предгорьях Хилсбрада.', 'На нашей паучьей ферме у Лазуритового рудника застой. Капитан Кейтон потребовал, чтобы мы немедленно прислали помощь. Кейтон жалуется на то, что рудниковые пауки отказываются подчиняться и разбегаются. Кроме того, группа береговых мурлоков ворует наши припасы. Я хочу, чтобы ты $gотправился:отправилась; туда и $gразобрался:разобралась;, в чем дело. Помоги Кейтону и укротителю пауков, $n.$b$bЛазуритовый рудник находится на берегу, к юго-востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28112, 'ruRU', 'Бегство из Затерянного города', 'Освободите принца Надуна и поговорите с королем Фаорисом в Рамкахене в Ульдуме.', 'Все готово! Сними с меня цепи и освободи своих друзей.$B$BМы должны действовать быстро, пока неферсеты не догадались, что мы затеяли!$B$BЕсли у нас все получится, загляни потом к моему брату, королю Фаорису, за наградой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28113, 'ruRU', 'Пройти через непроходимое', 'Убейте Ксаватраса.', 'Теперь, когда у нас есть этот коготь, мы готовы прорвать оборону племени Нефритового Пламени.$b$bОтправляйся в руины, что к северо-западу от нас. Ты найдешь узкий проход в линии обороны сатиров, который ведет к их оскверненному лунному колодцу. Путь к нему преграждает огромная стена демонического пламени, но коготь Тихондрия поможет тебе рассеять его.$b$bЗа барьером ты увидишь их вожака, Ксаватраса, который охраняет оскверненный лунный колодец. Убей его!', '', 'Герцог племени Нефритового Пламени', 'Ксаватрас', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28114, 'ruRU', 'Славный урожай', 'Соберите 60 яиц ползунов.', 'К юго-востоку от Южных врат находится наша ферма по одомашниванию пауков. За годы мы сроднились с пауками Хилсбрада, научились приручать их и разводить этих очаровательных маленьких созданий. Теперь пауки стали нашими обычными домашними животными. И боевыми тоже! Вот такие они разносторонние создания!$b$bЯ хочу, чтобы ты $gотправился:отправилась; в поля к юго-востоку отсюда и осторожно $gсобрал:собрала; паучьи яйца, которые мы выращиваем на медведях. Когда закончишь, отнеси яйца Сарусу на рудник.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28115, 'ruRU', 'Они свое отжили', 'Убейте 8 зараженных медведей.', 'Медведи – бездушные твари, как будто бы созданные лишь для того, чтобы мучить нас. Только благодаря нашей изобретательности мы научились извлекать из них какую-то пользу! Мы используем медведей, как ходячую паучью ферму. Наши пауки откладывают яйца под шкуру медведей, и яйца растут, получая питание из медвежьей плоти и крови.$b$bА после того, как медведи выполнили свое предназначение, от них надо избавиться. Отправляйся на юго-восток и убей зараженных медведей, которые нам уже не пригодятся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28116, 'ruRU', 'Плачущие фиалки', 'Соберите 8 плачущих фиалок.', 'Мы должны тщательно подготовиться к нападению на Джеденар. Чернокнижники и демоны Джеденара сильны, и прежде чем мы попадем туда, нам нужно обзавестись стражами.$b$bЯ собрала много трав, мне не хватает всего лишь одного ингредиента: плачущей фиалки, которая растет на холмах к северо-западу отсюда.$b$bСобери для меня плачущие фиалки, а потом разыщи в поле моего помощника. Он знает, что делать дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28117, 'ruRU', 'Очищение Проклятых глубин', 'Вам поручено убить 9 любых призраков в Проклятых глубинах, расположенных к востоку от крепости Барадин.', 'Твое присутствие воодушевляет нас, $n. Битва за Тол Барад только началась.$B$BК востоку отсюда мы обнаружили темницу, которую следует освободить от нечисти. В ней находится множество призраков, которые томятся там уже долгое время.$b$bУбей столько нечисти, сколько сможешь, и доложи мне о выполненном задании.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28118, 'ruRU', 'Верховный маг в заточении', 'Убейте верховного мага Галия в Проклятых глубинах к востоку от крепости Барадин и заберите его посох.', 'Мы пытались зачистить тюремный блок в Проклятых глубинах со времен высадки на Тол Бараде. Всякий раз, как мы приближаемся к этой цели, появляется верховный маг, который рушит все наши планы.$B$BСейчас же, когда остров в наших руках, стоит попробовать снова. Направляйся вниз и доставь мне его посох в доказательство выполнения задания.', '', 'Недолго ему осталось владеть этим посохом.', 'Верховный маг Галий', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28119, 'ruRU', 'Чистота, порожденная скверной', 'Наполните пустую фляжку водой из оскверненного лунного колодца в центре Джеденара.', 'Цветы, которые ты $gпринес:принесла; мне, – самый важный компонент.$b$bОплот Теней окружают охранные барьеры, проецируемые с демонических жаровен. Если мы хотим изгнать Совет Теней из Оскверненного леса, мы должны погасить жаровни.$b$bВ этом сосуде – плачущие фиалки и магия здешних лесов. Наполни его водой из оскверненного лунного колодца в центре Джеденара и возвращайся ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28120, 'ruRU', 'Уроки прошлого', 'Найдите 4 пыльных тюремных журнала в Проклятых глубинах к востоку от крепости Барадин.', 'Теперь, когда мы закрепились на этом проклятом острове, нужно попытаться установить, что его привело к нынешнему состоянию. Наши воины обнаружили несколько журналов с записями, разбросанных вблизи входа в тюремный блок в Проклятых глубинах к востоку отсюда.$B$BЭти журналы представляют особый интерес для наших старейшин. Как можно быстрее отыщи четыре журнала и доставь их в лагерь.$B$BБудь $gосторожен:осторожна;, $n: в той местности бродит много нежити.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28121, 'ruRU', 'Силы Джеденара', 'Убейте 12 любых джеденарских прислужников.', 'В порче, охватившей эти земли, виновен Совет Теней. В Джеденаре, что к северо-западу отсюда, члены Совета Теней поклоняются демонам Пылающего Легиона и пытаются помочь своим хозяевам вернуться в этот мир.$b$bЗемли Джеденара охраняются джеденарскими гончими, стражами, адептами и сектантами, за которыми стоят еще более злые силы. Их нужно убить в первую очередь, чтобы прекратить мучения здешних лесов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28122, 'ruRU', 'Гигантская проблема', 'Избавьтесь от Проблима, гигантского эттина, бродящего по тропам Тол Барада.', 'Стоило нам захватить этот проклятый остров, как в окрестностях тут же обнаружился гигантский эттин, который стал нападать на наши патрули!$B$B$n, договорись с друзьями и подкарауль этого громилу. Нельзя допустить, чтоб такое чудище разгуливало на свободе и сеяло разрушения.$B$BБудь $gосторожен:осторожна;, мне донесли, что он вооружен огромным поленом, которое любит пускать в дело.', '', 'Ну и зверюга.', 'Проблим', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28123, 'ruRU', 'Демоническая цепь', 'Добудьте демоническую цепь.', 'Наркралл раскрыл мне свой секрет. Теперь я знаю, почему он обладает таким влиянием на местных драконов. Мне казалось, демоническая цепь – это просто миф, но она действительно существует и все это время была у него.$B$BНо теперь этот глупец ее утратит!$B$BМне все равно, будет он жить или умрет, но вот его артефакт – это совсем другое дело; он слишком много значит для Драконьей Пасти. Отправляйся за Наркраллом на север, к Громтару. В городе сейчас царит хаос, так что, возможно, тебе удастся приземлиться незаметно. Принеси мне демоническую цепь – даже если тебе придется снять ее с трупа Наркралла.$B$BНайди этот артефакт, $n!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28124, 'ruRU', 'К бастиону', 'Обратитесь к Лакоте Песне Ветра возле бастиона Сумрака в Тысяче Игл.', '$n, пока вы с детенышами гордокрылов разбирались с Сумеречным повелителем небес Рихтофеном, заходила Лакота Песня Ветра. Она передала, что будет ждать тебя на востоке, возле бастиона Сумрака.$B$BДолжно быть, именно там они держат Магату Зловещий Тотем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28125, 'ruRU', 'Неприметная одежка', 'Раздобудьте 10 частей доспеха Сумеречного Молота.', 'Я, кажется, знаю, как тебе подобраться к их главарям, не рискуя жизнью. Но сначала нужно переодеться.$B$BИди и отними у кого-нибудь из них доспехи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28126, 'ruRU', 'Загасить пламя защиты', 'Залейте 4 жаровни защиты очищенной водой из лунного колодца в Оплоте Теней.', 'Жаровни расставлены по всему Оплоту Теней.$b$bВойди в тоннель, ведущий в Оплот Теней, а затем иди по подземным проходам. Залей водой пламя всех жаровен, и защита, установленная Советом, пропадет, по крайней мере на короткое время.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28127, 'ruRU', 'Вызволи их', 'Отбейте 5 узников бастиона у сумеречных тюремщиков.', 'Магата не единственная, кого пленил клан Сумеречного Молота.$B$BКогда окажешься там, на юге, постарайся вызволить как можно больше пленников.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28128, 'ruRU', 'Внутренний круг', 'Убейте 12 защитников Оплота Теней.', 'Теперь, когда мы избавились от стражей, на очереди более значимые члены Совета Теней.$b$bВ глубине оскверненной обители ты встретишь могущественных джеденарских чернокнижников, охотников, головорезов, темноплетов и легионеров.$b$bЕсли мы хотим спасти эти земли, они должны быть убиты!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28129, 'ruRU', 'Демонический принц', 'Убейте принца Ксавалиуса.', 'Сатиры из племени Нефритового Пламени, которые захватили такую большую часть Оскверненного леса, действуют вместе с Советом Теней.$b$bЭти сатиры подчиняются непосредственно принцу Ксавалису. Поговаривают, что он сын Ксавия, которого благословил сам Саргерас.$b$bКем бы он ни был, он должен умереть, если мы собираемся вышвырнуть отсюда племя Нефритового Пламени и вернуть нашу обитель. Отправляйся в Оплот Теней, что в Джеденаре, и убей его. Не жди от него милосердия, и $gсам:сама; тоже будь с ним $gбезжалостным:безжалостной;.', '', 'Вожак сатиров племени Нефритового Пламени', 'Принц Ксавалис', 'Легион будет изгнан из этих мест!', 'Андалар Дольная Тень', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28130, 'ruRU', 'Неприветливый город', 'Командир Марк Джонсон поручил вам расправиться с 14 жителями Растберга. Растберг расположен в правой части острова, к северу от лагеря.', 'Ты уже $gбывал:бывала; в Растберге, $n? Советую припасти нож за пазухой, если пойдешь в те края.$b$bТамошние жители вроде бы не доставляют хлопот, вот только что-то странное там творится. Мне докладывают о том, что там периодически пропадают наши солдаты. Нам это порядком поднадоело, поэтому тебе следует отправиться в этот вертеп и навести там порядок.$B$BПеребей там столько народу, сколько сможешь, и отчитайся передо мной о проделанной работе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28131, 'ruRU', 'Две искусительницы', 'Убейте Моору и Салию.', 'Моора и Салия – личные прислужницы Владыки теней Скверн\'дана. Не позволяй им обмануть себя!$b$bЭти грязные суккубы пользуются своим коварством и магией, чтобы заманивать смертных в Оплот Теней. Тех, кто попал в их западню, подвергают промывке мозгов или приносят в жертву демоническим хозяевам Скверн\'дана.$b$bМоора и Салия никогда не расстаются, поэтому поодиночке с ними не справиться, что делает твою задачу гораздо сложнее. Продвигайся дальше в Оплот Теней и убей их.', '', 'Тебе нужно устоять перед этим гибельным соблазном.', 'Моора и Салия', 'Скверн\'дан должен пасть!', 'Андалар Дольная Тень', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28132, 'ruRU', '\"Эффективные раскопки\"', 'Принесите \"Эффективные раскопки\" Беллоку Сияющему Клинку в лагерь Шнотца.', 'В руководстве описаны нелепые теории о том, как эффективно управлять большим рабочим коллективом при осуществлении крупномасштабных проектов по раскопке.$B$BПробежав глазами текст, вы понимаете, что автор книги, скорее всего, и заправляет здешними не в меру агрессивными мародерами.$B$BКарта на обороте книги показывает некий бункер на юго-западе Ульдума, где скрывается автор.$B$BВозможно, выпадет шанс взять автограф.', '', 'Вам остается предполагать, что на обложке изображен ушедший в себя автор.', 'Шнотц', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28133, 'ruRU', 'Освобожденная ярость', 'Доберитесь до Глотки и поговорите с Зелой. Убейте Торза.', 'Торз, дракон Наркралла, выжил в ходе неудачной попытки захватить Громтар, и теперь это существо лишилось своего хозяина.$B$BТорз хочет отомстить Драконьей Пасти и уже один раз пикировал на Кровавое ущелье. И он будет возвращаться снова и снова, если мы не выбьем из него дух. Похоже, пришло время применить демоническую цепь.$B$BСтарое гнездо Торза находится в маленькой пещере в холмах к западу отсюда. Мы превратили его в небольшой лагерь под названием \"Глотка\".$B$BВстретимся там и вместе прикончим Торза.', '', 'Встретимся в Глотке и вместе прикончим Торза.', 'Торз Прожорливый', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28134, 'ruRU', 'Неминуемая расплата', 'Побеседуйте с Номарком Тенетом в Угодьях Тарет, жрецом Солнца Асарисом у Печати Солнечного короля и с Асаком возле Мар\'ата.', 'Теперь, когда тебя достойно наградили, хочу поговорить начистоту, без обиняков.$B$BТы $gсослужил:сослужила; моему королевству великую службу, но вместе с этим $gнарушил:нарушила; хрупкий процесс мирных переговоров.$B$BЯ добивался освобождения моего брата всецело дипломатическими методами в попытке избежать кровопролития.$B$BТеперь же наш враг наверняка захочет с нами поквитаться.$B$BПоговори с Номарком Тенетом в Угодьях Тарет на востоке, жрецом Солнца Асарисом на севере, у Печати Солнечного короля, и с Асаком возле Мар\'ата, что на западе. Выясни, куда противник собирается нанести удар.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28135, 'ruRU', 'Месть Ал\'акира', 'Поговорите с принцем Надуном у торговой лавки Арсад возле Мар\'ата в Ульдуме.', 'Послушай, $n. На Орсис налетела не обычная песчаная буря. То было нападение слуг Ал\'акира.$B$BЭлементаль – повелитель воздуха – верный союзник Смертокрыла, и то, что когда-нибудь он натравит своих слуг на мой народ, было лишь вопросом времени.$B$BНападение на Орсис было предупреждением для нас. Нужно скорее помочь нашим братьям.$B$BРазыщи Надуна у торговой лавки Арсад около Мар\'ата. А я начну хлопотать о беженцах и раненых.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28136, 'ruRU', 'Осторожно, сзади!', 'Ликвидируйте шифровальщика Дитака, командира Скороплава и повелителя стихий Стариона.', 'Трое главарей бастиона могущественны – нельзя их недооценивать, $n. К счастью, теперь у тебя есть маскировка, так что они примут тебя за одного из сектантов Сумеречного Молота.$B$BНадевай маскировку и поговори с шифровальщиком Дитаком, командиром Скороплавом и повелителем стихий Старионом – с каждым наедине. Подожди, покуда собеседник повернется к тебе спиной, и нанеси разящий удар!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28137, 'ruRU', 'Научи человека ловить рыбу... Или красть ее!', 'Вам нужно украсть 22 растбергских окуня. Рыба сушится на нитях на специальных стойках у причала за деревней. Растберг расположен на северо-востоке острова, к северу от лагеря.', 'Растберг. Это место – одновременно наше проклятье и благословение, $n. Понятия не имею, где эти разбойники научились ловить рыбу, но это и не важно.$B$BОтправляйся к ним в логово и укради столько рыбы, сколько сможешь. Мы питаемся всякими отбросами с тех пор, как вновь заняли этот остров, поэтому было бы неплохо пополнить запасы провизии.$B$BБудь $gосторожен:осторожна;, мне доложили, что в деревне нас может поджидать засада.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28138, 'ruRU', 'Заражение людьми', 'Возьмите в плен 8 жителей Хилсбрада.', 'Когда-то этот рудник играл важную роль в горных разработках Альянса в Хилсбраде. Теперь он служит местом разведения наших дорогих пауков, хотя люди там тоже еще есть – в каком-то смысле.$b$b<Кейтон ухмыляется.>$b$bНо к делу! Надзирателю Штиллецу требуется дополнительные рабочая сила для работы в Топких полях. Я хочу, чтобы ты $gвзял:взяла; вот эти оковы, $gотправился:отправилась; в рудник и $gвзял:взяла; в плен жителей Хилсбрада, которых потом можно будет использовать для работы в полях.$b$bВырви их из парализующей паутины, а потом бей до тех пор, пока не сможешь надеть оковы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28139, 'ruRU', 'Код шифровальщика', 'Раздобудьте коды шифровальщика.', '$n, оковы, в которые заточена Магата, закодированы. Мы сможем ее вызволить, только если раздобудем коды.$B$BНа юго-востоке бастиона подле шифровальщика Дитака стоит некое устройство. В нем содержатся коды.$B$BРаздобудь их, сделай милость.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28140, 'ruRU', 'Мудрая старица', 'Отключите контроллер оков Магаты.', 'У тебя есть код. Отправляйся же в восточную часть бастиона и освободи мудрую старицу.$B$BУдачи, $n. И спасибо тебе за все.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28141, 'ruRU', 'Реликвии Солнечного короля', 'Раздобудьте 4 реликвии Солнечного короля.', 'Печать Солнечного короля – это защитный механизм Рамкахена.$B$BКогда пал барьер вокруг Ульдума, сюда проникли всадники шайки Скитальцев Пустыни из Танариса.$B$BУстремившись на запад, они напали на это священное место и похитили реликвии, которые давали ему силу.$B$BРаздобудь эти реликвии. Без них мы беззащитны перед вторжением из пустыни.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28142, 'ruRU', 'Дорога в пустошь', 'Обратитесь к Магате Зловещий Тотем в Сумеречной пустоши в Тысяче Игл.', 'Магата сказала, что будет ждать тебя возле Сумеречной пустоши, что к востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28144, 'ruRU', 'Маленькие грязные воришки!', 'Верните 6 \"припасов\" из лагеря Отрекшихся.', 'Часть берега к югу от нашего расположения, которая далеко простирается с запада на восток, называется Западным побережьем. Все Западное побережье усеяно мурлоками и нашими украденными \"припасами\".$b$b<Кейтон поднимает руки вверх и изображает кавычки.>$b$bСтоит нам только отвернуться, как эти проклятые маленькие воришки нападают и крадут наши \"припасы\".$b$bМы с Сарусом не можем отойти. Поэтому нужно, чтобы ты $gотправился:отправилась; на Западное побережье и $gвернул:вернула; эти \"припасы\"!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28145, 'ruRU', 'Противоядие', 'Наполните колбу для антидота ядом 8 трупов ядокровых скорпидов.', 'Изет оказал сопротивление бандитам шайки Скитальцев Пустыни, разорившим это священное место.$B$bПохоже, они отравили его мощным токсином, который добывают из ядокровых скорпидов.$B$BВозьми этот пузырек и нацеди в него яда из тел скорпидов, а я попробую изготовить противоядие. Иначе, боюсь, Изету недолго осталось...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28146, 'ruRU', 'Деликатесы с побережья', 'Убейте 12 мурлоков на Западном побережье, чтобы накормить голодного рудникового паука.', 'Мои пауки голодны и нервничают! Они не ели уже несколько дней и начинают подбираться к людям, которых мы держим в плену. С этим нельзя смириться. Люди нам еще пригодятся в Топких полях.$b$bЯ хочу, чтобы ты $gвыпустил:выпустила; одного из моих голодных рудниковых пауков и $gнакормил:накормила; его мурлоками с Западного побережья, что к югу отсюда. Сколько ни убьешь – он все съест! Чем больше, тем лучше!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28147, 'ruRU', 'Твой цвет – фиолетовый', 'Соберите 8 лоскутов сумеречного облачения.', 'Насколько я могу судить, местные огры из клана Помойных Потрохов еще не присоединились к Сумеречному Молоту. Так что если мы правильно разыграем наши карты, то сможем натравить наших врагов друг на друга.$B$BДавай устроим небольшой трюк, которому меня научили в Силитусе. Для начала нам понадобится одежда сектанта.$B$BИди на юг, на Сумеречный разлом, и убей несколько сумеречных заветренников. Так ты помешаешь их планам и, кроме того, сможешь добыть себе одежду.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28148, 'ruRU', 'Истребление заразы', 'Соберите 10 зараженных шкур медведей злобных когтей или волков-сквернолапов.', 'Эта отвратительная порча, в ответе за которую демоны, охватила весь лес. Земля, деревья, животные... все раздулось от их грязной магии.$b$bМы, друиды Изумрудного Круга, поклялись очистить этот лес, а это требует непрекращающейся битвы. И хотя многих существ еще можно вылечить, с медведями и волками, которые бродят поблизости, все зашло слишком далеко.$b$bМы должны прекратить их страдания и удостовериться, что их тела не станут причиной дальнейшего распространения заразы. Убей медведей и волков и возвращайся ко мне с их шкурами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28149, 'ruRU', 'Шепот ветра', 'Добудьте амулет говорящего с ветром и 5 дыханий шторма.', 'Ты слышишь их, |3-6($c)? Голоса из пещеры. Они хотят говорить, но им не хватает дыхания.$B$BДавай найдем способ послушать их. Сумеречный Молот, вот кто разговаривает с ветром. Иди на юг, к Сумеречному разлому, и найди в лагере амулет говорящего с ветром. Он должен лежать на каменной колонне.$B$BИ дыхание элементалей нам тоже пригодится! Так что убивай штормовые завихрения и бери то, что тебе нужно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28150, 'ruRU', 'Союзница-чародей', 'Поговорите с чародейкой Деларис в руинах Констелласа.', 'Изумрудный Круг поклялся принимать помощь от всех, кто желает сразиться с демонами Оскверненного леса. Хотя наш народ и избегает тайной магии, мы не имеем права лишать себя тех преимуществ, которые она дает.$b$bЧародейка Деларис, одна из выживших магов высокорожденных, помогает нам в борьбе с сатирами племени Нефритового Пламени. Отправляйся по дороге, ведущей на север, и ты найдешь ее в нашем лагере, разбитом в руинах Констелласа.$b$bЕсли ты желаешь помочь нам в очищении Оскверненного леса, выполняй ее просьбы так же, как выполняешь мои.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28151, 'ruRU', 'Костюм убийцы', 'Убейте 10 огров из клана Помойных Потрохов. Маскировочный костюм Сумеречного Молота изменяет ваш облик автоматически, когда вы находитесь в Ложбине клана Помойных Потрохов.', '$n, твое облачение служителя культа Сумеречного Молота готово. Надень его, когда пойдешь на север, в Ложбину клана Помойных Потрохов, и он введет в заблуждение огров.$B$BВсе остальное очень просто: ты убиваешь кучу огров Помойных Потрохов, а они винят во всем культ. Ну что, наведешь шороху в лагере огров? Я так и думал.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28152, 'ruRU', 'Джеденар ждет', 'Доставьте чародейские травы Грете Замшелое Копыто в Лагерь Дикого Сердца.', 'Сектанты, которых ты $gвидел:видела;, когда $gискал:искала; коготь, раньше были членами Совета Теней. Грязные чернокнижники, которые стоят почти за каждой попыткой вернуть демонов в Азерот.$b$bК северу отсюда располагается Джеденар, названный так в честь самого Кил\'джедена. В глубине Джеденара находится Оплот Теней, бывшая обитель, а теперь – крепость Совета Теней в Азероте.$b$bВозьми эти травы и отнеси их в Лагерь Дикого Сердца, что к востоку от дороги. Они понадобятся Грете Замшелое Копыто для реализации ее плана по очищению Оплота Теней.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28153, 'ruRU', 'Владыка теней Скверн\'дан', 'Убейте Владыку теней Скверн\'дана.', 'Владыка теней Скверн\'дан ждет тебя там, в глубине, $n.$B$BТы $gубил:убила; его любимых слуг, и гнев его будет страшен. Даже без поддержки Мооры и Салии, он остается страшнейшим противником.$b$bОпасайся его темной магии, сейчас он куда ближе к демону, чем к орку.', '', 'Мерзкий лидер Совета Теней', 'Владыка теней Скверн\'дан', 'Наша задача почти выполнена. Мы вернем Оплот Теней.', 'Андалар Дольная Тень', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28154, 'ruRU', 'Плавник Грязехлюпа или что-то в таком духе...', 'Доставьте плавник Грязехлюпа капитану Кейтону в Лазуритовый рудник, что в предгорьях Хилсбрада.', 'Это похоже на плавник Грязехлюпа или что-то подобное. Возможно, в Лазуритовом руднике кому-нибудь будет интересно узнать, что вы убили этого мурлока. Возможно и нет, но почему бы не проверить?$b$bВозьмите плавник Грязехлюпа и отнесите его капитану Кейтону в Лазуритовый рудник, что к юго-западу от Хилсбрада.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28155, 'ruRU', 'Лорд Гиблопуст', 'Убейте лорда Гиблопуста.', 'Осталось справиться с последней опасностью, которая таится в глубине Оплота Теней: лордом Гиблопустом.$b$bСовет Теней служит его прихотям, и даже Скверн\'дан — лишь его орудие в подготовке этих земель для следующего вторжения Пылающего Легиона.$b$bБудь $gосторожен:осторожна;, $n. Повелитель ужаса – страшный противник. Приготовься и добейся победы!', '', 'Он ждет в самом дальнем углу Оплота Теней.', 'Лорд Гиблопуст', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28156, 'ruRU', 'Спасение из глубин рудника', 'Проводите Дюмлона в безопасное место!', '<Сквозь паутину вы слышите голос Дюмлона.>$b$BЭЙ! ТУТ ВЕЗДЕ ПАУКИ! КАПИТАН ОТПРАВИЛ МЕНЯ СПАСАТЬ МИР И БРАТЬ В ПЛЕН ЛЮДЕЙ! А ТУТ ЧТО ТАКОЕ? ЗДЕСЬ ТАК ЖАРКО! Я...$b$b<Дюмлон все жалуется и жалуется на ситуацию, в которой он оказался.>$b$bВозможно, стоит освободить его и проводить в безопасное место. Ну или оставить его здесь, ведь не вы же виноваты, что он застрял в этом руднике.', 'Проводите Дюмлона в безопасное место!', '', '', '', '', 'Поговорите с капитаном Кейтоном в Лазуритовом руднике, что в предгорьях Хилсбрада.', 25549);
INSERT INTO `quest_template_locale` VALUES (28157, 'ruRU', 'Четыре сумеречные стихии', 'Раздобудьте четыре сумеречные стихии: воздух, землю, огонь и воду.', 'Клан Сумеречного Молота призвал чудовище. Оно сочетает в себе четыре стихии, усиленные мощью их особой руды – элементия.$B$BЕсли хочешь спасти свою драгоценную Тысячу Игл от полного уничтожения, тебе придется одолеть эту тварь. Но сначала понадобится кое-что, чтобы пробиться сквозь ее защиту.$B$BОтправляйся на восток пустоши и принеси мне четыре сумеречные стихии.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28158, 'ruRU', 'Непокорные', 'Освободите покоренного Неистового и покоренного Вихря.', 'Клан Сумеречного Молота подчинил себе двух очень могущественных элементалей. Через покоренных Неистового и Вихря они передают Анимусу огромное количество энергии.$B$BКак только Анимус вберет в себя достаточно силы, он взорвется. Тысячу Игл и окрестные земли сметет с лица Азерота.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28159, 'ruRU', 'Камень Рока', 'Раздобудьте Камень Рока.', 'Сердце Анимуса – артефакт, известный как Камень Рока. Одно из его свойств – способность поглощать огромное количество энергии.$B$BИменно так сектанты планируют осуществить взрыв – перегрузить Камень и усилить мощь взрыва с помощью элементаля...$B$BПринеси мне Камень Рока. На безопасное сохранение, разумеется.', '', 'У него Камень Рока!', 'Анимус', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28160, 'ruRU', 'Поведай всем', 'Обратитесь к Пшиксу Медноштифу на гоночной барже Пшикса и Поззика в Тысяче Игл.', 'За твою верную службу я дарю тебе жизнь. Забирай ее – и поди прочь с моих глаз. И расскажи своему народу обо всем, что случилось здесь.$B$BИ еще, $n: если я еще хоть раз встречу тебя, ты умрешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28161, 'ruRU', 'Поведай всем', 'Обратитесь к Поззику на гоночной барже Пшикса и Поззика в Тысяче Игл.', 'За твою верную службу я дарю тебе жизнь. Забирай ее – и поди прочь с моих глаз. И расскажи своему народу обо всем, что случилось здесь.$B$BИ еще, $n: если я еще хоть раз встречу тебя, ты умрешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28162, 'ruRU', 'Припасы на болоте', 'Вам нужно собрать 8 шкур толбарадских кроколисков. Кроколиски обитают на болоте к западу от крепости Барадин.', 'В подобном месте сложно пополнить припасы, |3-6($c). Мы безуспешно пытались найти что-либо пригодное с тех пор, как попали на этот остров.$B$BК счастью, только что лазутчики доложили, что на болоте к западу от лагеря водится много кроколисков. Их шкуры, несомненно, пригодятся нашим кожевникам. Принеси столько шкур, сколько сможешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28163, 'ruRU', 'Окончательная зачистка', 'От вас требуется убить 12 пехотинцев Орды на Тол Бараде. Укрепления Орды на Тол Бараде расположены на Шлакозаводе, Посту Стража и в Железном гарнизоне.', 'Мы стойко сражались, чтобы захватить этот остров, |3-6($r). Нам удалось уничтожить большую часть ордынских паскудников, но я все еще чую их мерзкий дух в окрестностях.$b$bПоручаю тебе провести разведку на Шлакозаводе, на Посту Стража и в Железном гарнизоне. Убей всех представителей Орды, которых обнаружишь.$b$bКак гласит народная мудрость, хороший ордынец – мертвый ордынец.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28165, 'ruRU', 'Блок Д', 'Вам поручено уничтожить 10 любых демонов, обитающих в блоке Д, что находится к северо-западу от крепости Барадин.', 'Ты уже $gслышал:слышала; о блоке Д, $n? Это один из старых тюремных блоков, находящихся на острове. Дело в том, что его заселили демоны. Мы рассчитывали разместить там пленных из Орды, захваченных на острове, но при текущем раскладе это невозможно.$B$BЯ хочу, чтобы ты $gпомог:помогла; нам очистить блок от демонов. Отрапортуй мне о выполнении приказа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28166, 'ruRU', 'Ночник Тога', 'Добудьте Свет души в Ложбине клана Помойных Потрохов.', 'Чтобы увидеть духов, нам нужен особый свет. Свет, который подсвечивает самое нутро. Свет души.$B$BПосле того что мы сделали с ними на Хиджале, Сумеречный Молот стал выявлять с их помощью предателей. И один из них они подарили Помойным Потрохам.$B$BНа севере, в Ложбине Помойных Потрохов, живет огромный громила по имени Тог. У него есть Свет души. По крайней мере, до тех пор, пока ты его не отберешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28167, 'ruRU', 'Отчет Карво Рвизасову', 'Поговорите с Карво Рвизасовом в Гномрегане.', 'Я собираюсь начать приготовления к тому, чтобы вывести своих гномов из этого места. Мы больше не можем здесь оставаться. Я хочу, чтобы ты $gзанял:заняла; позицию в центре большого зала, что впереди нас.$b$bНайди там Карво Рвизасова. Он даст тебе остальные инструкции. Удачи, $n, и увидимся на поверхности.', '', '', '', '', '', 'Поговорите с Карво Рвизасовом в Гномрегане.', 25549);
INSERT INTO `quest_template_locale` VALUES (28168, 'ruRU', 'Проблемы в Топких полях', 'Отчитайтесь надзирателю Штиллецу в Топких полях, что в предгорьях Хилсбрада.', 'От надзирателя Штиллеца, который сейчас на Топких полях, что к северу отсюда, поступил сигнал бедствия. Мы не очень точно поняли его послание, но насколько я понял, в Топких полях произошел бунт и большинство стражей убиты. Надзиратель предупредил нас, что тот, кто геройски готов помочь, должен приближаться с западной стороны Топких полей.$b$bОн также настаивал на конфиденциальности. Он не хочет, чтобы об этом небольшом хм... недоразумении стало известно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28169, 'ruRU', 'В Погрузочную!', 'Следуйте за участниками команды С.П.А.С. к Гаффер Пружинопрыг в Погрузочной.', 'Ты отлично $gпотрудился:потрудилась;, собирая выживших! Для них – и для тебя – команда С.П.А.С. и продолжает спускаться сюда. Невин не сомкнет глаз, пока не найдет и не выведет на поверхность всех, кого сможет.$b$bЯ отправил своих подчиненных в Погрузочную, чтобы они подготовили все необходимое для процедуры очищения от радиоактивных загрязнений. Пожалуйста, следуй за ними и, когда прибудешь, разыщи Гаффер Пружинопрыг. Она поможет тебе пройти процедуру и поможет тебе выбраться на поверхность.', '', '', '', '', '', 'Следуйте за участниками команды С.П.А.С. к Гаффер Пружинопрыг в Погрузочной.', 25549);
INSERT INTO `quest_template_locale` VALUES (28170, 'ruRU', 'Ночные кошмары', 'Поговорите с Учеком в Глотке. Находясь в мире духов, защищайте себя с помощью Света души, и посетите три алтаря, которые находятся в пещере.', 'Мой друг Учек уже в пещере. Там мы поставили три алтаря. И твоя задача – очистить все три от скверны.$B$BИди в пещеру и поговори с Учеком. Он введет тебя в транс, отправит в мир духов. Когда окажешься там, действуй осторожно! Если увидишь призрачное чудовище, не паникуй. Посвети на него Светом души пару секунд, и с тварью будет покончено. Свет защитит тебя. Иди и очисти три алтаря!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28171, 'ruRU', 'И небо окрасилось в красный цвет', 'Примите участие в бою с черными драконами.', 'Пока Смертокрылу не до нагорья, королева поручила нам одно весьма сложное и опасное дело. Мы должны истребить черных драконов.$B$BЕсли ты решишь помочь нам в этом, мы будем весьма благодарны. Когда будешь $gготов:готова;, поговори со мной, и я дам тебе дракона, чтобы ты $gсмог:смогла; присоединиться к атаке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28172, 'ruRU', 'Безвинные создания', 'Освободите красного дракончика, зеленого дракончика, синего дракончика и бронзового дракончика.', 'Орки Черной горы из Пылающих степей служат темному повелителю, который проводит изощренные эксперименты над живыми созданиями, превращая их в полчище чудовищ. Многие из подопытных существ были осквернены своим создателем, однако же, некоторые из них сохранили внутреннюю чистоту.$b$bВ Ясельных холмах к югу отсюда орки приковывают к земле детенышей дракона, чтобы подготовить тех к последующим опытам. Я не потерплю подобного издевательства. Сбрось с них оковы и приведи детенышей ко мне... в безопасное место.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28173, 'ruRU', 'Затмение', 'Зацепите 8 обсидиановых огнекрылов с помощью крюков охотников на драконов, а затем убейте.', 'Сумеречные охотники на драконов используют жуткие инструменты для борьбы с нашими драконами – крючья, канаты и прочее.$B$BПримирение с ними невозможно – мы в силах лишь помочь им обрести вечный покой, который они ищут. $B$BОтправляйся на юг и убей обсидиановых огнекрылов. Возьми эти крюки: они помогут тебе лучше маневрировать в воздухе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28174, 'ruRU', 'Настигающая кара', 'Уничтожьте 5 взращивателей из клана Черной горы и 5 огнечешуйчатых дракончиков.', 'Орки Черной горы все не угомонятся. Они собираются у полей сражений к востоку отсюда, готовые ударить в любой момент.$b$bОднажды они уже напали на мою родину. Я здесь, чтобы не допустить этого вновь.$b$bЕсли тебе хоть немного дорого человечество, ты поступишь так же. Прояви себя в деле. Отправляйся на юг, к Ясельным холмам, и уничтожь взращивателей маленьких дракончиков, а также опекаемых ими детенышей черного дракона. Докажи мне, что ты $gготов:готова; к войне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28175, 'ruRU', 'Свет во тьме', 'Поместите слезу Алекстразы в нору под обсидиановым деревом.', 'К югу отсюда находится огромное окаменевшее дерево. Когда-то это был великий источник жизни. Наш источник. Черные драконы отняли у нас этот лес, и с тех пор он переполнился скверной и окаменел.$B$BНо мы еще надеемся его спасти. У меня есть одно сильное средство, с которого можно начать лечение. Возможно, нам удастся исцелить дерево – но для этого нам понадобится время, удача и, быть может, твоя помощь.$B$BВозьми вот это, слезу Алекстразы, и исцели сердцевину дерева.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28176, 'ruRU', 'Юные драконы идут в логово', 'Используйте материнское пламя, чтобы из обсидиановых яиц вылупились молодые драконы. Идите за детенышами к логову их матери.', 'В юго-западной части Обсидианового леса ты найдешь яйца черных драконов. Если как следует их поджарить, из них вылупятся дракончики и с воплем помчатся к матери.$B$BНе волнуйся, детенышей я тебя убивать не заставлю. Тебе просто нужно проследить за ними – они приведут тебя к своей матери. Нам нужно разобраться с ней.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28177, 'ruRU', 'Запасаемся', 'Добудьте 5 бритвенно-острых жал скорпида.', 'Если мы намерены тягаться с кланом Черной горы, то нам нужно разработать план военных действий. Полковник уже сделал кое-какие наброски, так что пришло время действовать.$b$bМне потребуются жала скорпидов... самые острые, какие сможешь найти. Скорпиды обитают на всей территории степей, но больше всего их можно найти в ущелье на западе.$b$bНе спрашивай, зачем они мне. Скоро все узнаешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28178, 'ruRU', 'Планы на будущее', 'Добудьте 11 шкур пепельного ворга.', 'Нам потребуется множество шкур воргов. Не важно, в каком они будут состоянии: изорванные, обгоревшие или запятнанные кровью. Нам подойдут любые и в большом количестве.$b$bПожалуй, неплохо будет их для начала немного истрепать.$b$bВорги обитают к востоку и к западу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28179, 'ruRU', 'Сборщик грязи', 'Соберите 9 кучек насыщенной обсидианом грязи.', 'Надеюсь, ты не боишься испачкаться. Судя по твоему виду, по крайней мере.$b$bК северу отсюда, там, где кончается застывшая лава, лежат кучи темной грязи. Она мне нужна.$b$bЛучше не задавай лишних вопросов и просто сосредоточься на задании, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28180, 'ruRU', 'Песок, сидр и сфера', 'Переговорите с Горзиеки Дикоглазом вблизи Алтаря Бурь.', 'Полковник Тротман ждет нас на востоке. Однако перед выходом нам нужно собрать еще немного припасов. Для этого тебе придется поговорить с чернокнижником по имени Горзиеки Дикоглаз.$b$bЕго можно встретить на северо-западе вблизи Алтаря Бурь. Попроси его выручить нас. И еще передай ему, что нам нужен песок, сидр и сфера.$b$bОн поймет, о чем идет речь.', '', '', '', '', '', 'Доложите Горзиеки Дикоглазу у Алтаря Бурь в Пылающих степях о выполнении задания.', 25549);
INSERT INTO `quest_template_locale` VALUES (28181, 'ruRU', 'Лучшие вещи – это к чернокнижникам', 'Добудьте горсть сонного песка, кувшин прокисшего сидра и сферу из прозрачного стекла.', 'Кишан сказал, что ему нужны припасы? У меня куча припасов! Проблема в том, что они хранятся у меня дома, откуда меня выдворили чернокнижники и не пускают обратно.$b$b<Горзиеки оценивающе осматривает тебя.>$b$bВот ты, наверное, сможешь туда пробраться. Направляйся на север, только прихвати немного сонного песку, прокисшего сидра и сферу из прозрачного стекла. Уверен, это то, что он хочет.$b$bАх да, и если ты мимоходом укокошишь несколько тамошних орков, я не сильно расстроюсь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28182, 'ruRU', 'Развеять мрак', 'Ликвидируйте Нер\'гоша Мрака.', 'Нер\'гош Мрак – предводитель чернокнижников к северу отсюда; именно он вышвырнул меня из дому, когда в эти края пришли орки Черной горы.$b$bЕсли мне когда-нибудь суждено вернуться к Алтарю, то следует вначале избавиться от Нер\'гоша.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28183, 'ruRU', 'Возвращение к Кишану', 'Отнесите припасы чернокнижника Джону Джею Кишану в Лагерь Пламени Звезд в Пылающих степях.', 'Думаю, пока это все. Когда наберусь смелости, пойду сам разберусь с остальными чернокнижниками.$b$bНе забудь припасы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28184, 'ruRU', 'Узкоклинье – сердце Пылающих степей', 'Убейте 15 орков Черной горы по пути в Узкоклинье.', 'Мы направляемся в Узкоклинье, лежащее прямо в центре степей. Там мы повстречаемся братством Тория и ожидающим нас Тротманом.$b$bТы уже $gзнаком:знакома; с братством? Это дворфы из клана Черного Железа, уже не раз выручавшие меня в беде. Теперь нам снова нужна их помощь.$b$bНаш путь проходит мимо Загона Черного Зуба. Ты не возражаешь, если по пути убьем парочку орков? А то мне что-то становится беспокойно в этом лагере.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28185, 'ruRU', 'Сварнос', 'Расправьтесь со Сварносом в Блоке Д и заберите проклятый ошейник Сварноса. Монстр находится в Блоке Д к северо-западу от крепости Барадин.', 'Ты отлично $gпотрудился:потрудилась; при захвате острова, |3-6($c). Теперь, когда он в наших руках, предстоит подготовить камеры к приему заключенных. Блок Д доставляет нам особенно много проблем в плане зачистки. К сожалению, его заполонили демоны всех мастей.$B$BНам удалось совладать с большинством, но из одной камеры сбежала большая гончая Недр, которая теперь бесчинствует в тюремном блоке. Я хочу, чтобы ты $gубил:убила; ее и $gдоставил:доставила; мне ее ошейник.', '', 'Мне никогда не нравился зеленый цвет.', 'Сварнос', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28186, 'ruRU', 'Проклятые кандалы', 'Соберите 8 проклятых кандалов в Блоке Д, что находится к северо-западу от крепости Барадин.', 'Ты уже $gбывал:бывала; в Блоке Д, $n? Всякий раз как мы зачищаем этот блок, демоны быстро заселяют его снова. Мы установили, что они возрождаются за счет проклятых кандалов, разбросанных по блоку. Вот тут-то ты нам и пригодишься, $n.$B$BСобери столько кандалов, сколько сможешь, и принеси их мне. Мы их немедленно уничтожим.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28187, 'ruRU', 'Мимо!', 'Поговорите с командиром Шнотцем, когда будете готовы вывести его из пылающего здания.', 'Такой дело, |3-6($r)! Отшень серьезный!$B$BКто-то решайт избавляйт от я и думайт, это просто парный репка.$B$BНу-с, посмотреть! Майн арбайтен не смочь мешать! Нихт!$B$B<Шнотц оглядывается по сторонам, видит приближающиеся языки пламени.>$B$BМне думайт, польза идти вон.$B$BШнель! Время ценен!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28188, 'ruRU', 'Тюремный бунт', 'Вам поручено убить 10 любых узников в Яме, расположенной к юго-западу от крепости Барадин.', 'Теперь, когда остров находится в наших руках, предстоит тяжкая работа. Нам удалось обнаружить заброшенный тюремный блок к юго-западу отсюда, который нужно проверить, $n.$B$BПо донесениям разведки заключенные, томившиеся в заточении годами, захватили блок. Прими все необходимые меры по зачистке этого места. Доложи мне о результатах операции.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28189, 'ruRU', 'Благое дело', '\"Спасите\" 15 прорастающих людей.', 'Вашим глазам предстает ужасная картина. Кто-то закопал всех людей в землю по шею, как если бы сажал растения. Вурдалаки, которые бродят по полю, периодически набрасываются на человеческие головы и пожирают их!$b$bВы можете положить этому конец прямо сейчас! Возьмите лопату и \"спасите\" людей.$b$bСделайте благое дело.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28190, 'ruRU', 'Нечистые слизнюки', 'Убейте 8 нечистых слизнюков.', 'Все это началось с Винны Хеззард. Она была Отрекшейся и работала аптекарем на Заставе Отравленной Крови, искала способы использовать демонических слизнюков во вред Альянсу.$b$bМы предупреждали ее, что она зашла слишком далеко, но она не слушала, а мы не успели вовремя принять меры. И вот теперь и она, и вообще все на Заставе Отравленной Крови превратились в безумных существ, состоящих из слизи...$b$bОтвратительные слизнюки, которых она использовала, до сих пор ползают у прудов, расположенных к востоку и к югу. Прошу тебя, |3-6($c), уничтожь их, чтобы больше никто не смог совершить подобное злодеяние.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28191, 'ruRU', 'Заслуженная участь', 'Убейте 10 обсидиановых драконидов.', 'Земли на юге заполонили обсидиановые дракониды. Сейчас они не могут нас потеснить, но в военное время нельзя недооценивать ни одного врага. $B$BТак что твоя задача – нанести упреждающий удар. Уничтожь их, чтобы мы могли и дальше очищать наши земли от черных драконов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28192, 'ruRU', 'Никто не уйдет живым', 'Оцените ситуацию в Топких полях.', 'Наша ферма находится в полной изоляции! Никакой связи с внешним миром! Мы до сих пор пытаемся разобраться, что же произошло на самом деле, но у меня есть такая теория: работники наелись грибов и каким-то образом мутировали в ужасную нежить. Я хочу сказать, что других объяснений я не вижу. Ведь это же обычная ферма! Мы выращиваем тут грибы! И слизней!$b$bОсмотрись вокруг, |3-6($c), потому что раз уж ты здесь, ты не можешь уйти, не решив проблемы.$b$bИ будь осторожнее!', 'Оцените ситуацию в Топких полях.', '', '', '', '', 'Поговорите с надзирателем Штиллецом в Топких полях, что в предгорьях Хилсбрада.', 25549);
INSERT INTO `quest_template_locale` VALUES (28193, 'ruRU', 'Под колпаком!', 'Командир Шнотц хочет, чтобы вы понаблюдали за гостями в лагере Шнотца.', 'Здание не есть само взрывайт!$B$BМеня желание прикончать, я выяснить, кто есть это!$B$BИдти к наш гости. Смотреть их и мне докладать.$B$BИм что знайт, я выбивайт сведения!$B$BФольно! Идти!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28194, 'ruRU', 'Побег', 'Плодовитый писатель из лагеря Шнотца хочет, чтобы вы раздобыли 6 комплектов униформы моряков Шнотца.', 'Пожалуйста, |3-6($c)! Нам нужна твоя помощь!$B$BНас здесь держат против нашей воли. И еще неизвестно, что этот командир с нами теперь сделает!$B$BБыть может, если ты добудешь нам их форму, мы сумеем ускользнуть.$B$BНе следовало сюда вообще соваться, теперь я это понимаю.$B$BЕсли ты поможешь нам бежать, я напишу всю правду о том, что здесь произошло.$B$BДобыть бы только одежду моряков с тех кораблей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28195, 'ruRU', 'Послание всем остальным', 'Командир Шнотц приказывает вам убить капитана Маргана, капитана Корка и капитана Кронха.', 'Я имейт мой шпион всюда, |3-6($r).$B$BИ знайт, что шептать солдаты. Я терпеть их выходка долго, больше терпеть нет!$B$BЯ показывайт мои люди, такое поведенье запрещайт!$B$BТы наказать официрен корабли в гавань. Эти были громче всех.$B$BТы заканчивайт, я смотреть донесений и решать, что делайт.$B$BФольно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28196, 'ruRU', 'Битва за Хилсбрад', 'Доставьте записи под названием \"Битва за Хилсбрад\" надзирателю Штиллецу в Топкие поля, что в предгорьях Хилсбрада.', 'В дневнике описываются последние 62 дня жизни клерка Горация Белоконя. В записях содержатся отвратительные факты, касающиеся надзирателя Штиллеца и его деяний в Топких полях.$b$bНужно показать это надзирателю. Наверняка у него найдется объяснение тому, что написано в этом дневнике.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28197, 'ruRU', 'Осторожность – ключ к успеху', 'Убейте горожанина Вилкса и клерка Горация Белоконя.', 'Мы должны уничтожить доказательства, $n! Ой, я сказал \"доказательства\"? Я имел в виду эту сумасшедшую нежить! В общем, осторожность – это ключ к успеху. Нельзя допустить, чтобы эти буйствующие ходячие мертвецы выбрались за пределы Топких полей. И никто из посторонних не должен знать об этом!$b$bК юго-востоку отсюда, там, где раньше была старая грибная ферма, ты найдешь ожившего монстра, известного под именем горожанина Вилкса, и его пособника, клерка Горация Белоконя. Они создают большие проблемы для моей охраны. Найди их и убей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28198, 'ruRU', 'Слабое звено', 'Поговорите с Салхетом на заставе рамкахенов в Ульдуме.', 'Говорят, крепость цепи определяется крепостью ее самого слабого звена.$B$BЯ всецело поддерживаю эту теорию и даже готов ее дополнить.$B$BВместо того чтобы удалять из цепи слабое звено, его необходимо... усилить.$B$BИ тогда другие станут из кожи вон лезть, лишь бы самим не оказаться на месте самого слабого звена.$B$BВ случае с моей армией у слабого звена есть имя – Салхет.$B$BОн тренируется у подножия той лестницы.$B$BДля начала придумай для него что-нибудь полегче. Например, пусть начнет с гиен на западных холмах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28199, 'ruRU', 'Во имя науки!', 'Достаньте 6 образцов плоти.', 'Образцы... да... нужны образцы! Нужно изучить этих подопытных кроликов... ээ... я имею в виду, этих несчастных рабочих.$b$bОтправляйся на юго-восток и на первой же ферме убей восставших вурдалаков. А из их разлагающихся тел возьми образцы плоти. И принеси их мне!$b$b<Арно потирает руки и безумно хихикает без видимых на то причин.>$b$bНадо изучить!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28200, 'ruRU', 'Жизненно необходимые припасы', 'Раздобудьте 20 затвердевших шкур кроколисков.', 'Как ты понимаешь, мы сейчас не вполне готовы к бою.$B$BПлеменам тол\'виров уже тысячу лет не доводилось вступать в войну.$B$BОднако все те боевые протоколы, что титаны вложили в наших предков, никуда не делись. Часть из них превратилась в инстинкты, другие мы передаем от поколения к поколению в виде обрядов.$B$BНо все это не в силах компенсировать недостаток припасов. Нам нужно оружие. И доспехи.$B$BЛучшие доспехи получаются из шкур речных кроколисков, что водятся в реке неподалеку. Помоги нам добыть несколько шкур.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28201, 'ruRU', 'От лемехов – к мечам', 'Завербуйте 8 рамкахенов-работников.', 'Армия у нас немаленькая, но, боюсь, для предстоящего решающего сражения с ордами неферсетов нам понадобится собрать всех годных к военной службе тол\'виров из Рамкахена и Орсиса.$B$BЯ хочу, чтобы вербовкой новых солдат $gзанялся:занялась; ты.$B$BОтправляйся на ту сторону реки, на Поля Ахенет, и завербуй работников, что там трудятся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28202, 'ruRU', 'Идеальный костюм', 'Возьмите необходимые материалы с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.', 'Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в орка. Вражеская армия в основном состоит из орков, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28203, 'ruRU', 'Идеальный костюм', 'Возьмите необходимые материалы с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.', 'Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в огра. Огры из клана Огненного Чрева всегда работали на клан Черной горы, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно. Теларон тебя быстро приоденет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28204, 'ruRU', 'Идеальный костюм', 'Возьмите необходимые материалы с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.', 'Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в гоблина. Орки Черной горы часто нанимают гоблинов-торговцев, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно. Теларон тебя быстро приоденет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28205, 'ruRU', 'Идеальный костюм', 'Возьмите необходимые материалы с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.', 'Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в тролля. Тролли из племени Тлеющего Терновника всегда были подельниками орков Черной горы, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно. Теларон тебя быстро приоденет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28206, 'ruRU', 'Потерялась маленькая девочка', 'Найдите Джонни \"Дженни\" Потрясного в Топких полях, что в предгорьях Хилсбрада.', 'Только вчера я отправил ее исследовать ферму к востоку отсюда, а кажется, что уже прошла вечность!$b$bС самой первой минуты, как я увидел ее, я знал, что это настоящая любовь. Ее чудесные белокурые локоны, обрамлявшие прекрасное лицо эльфийки крови... Она растопила лед в моем сердце. Я не хотел отпускать ее, но она так просила! У меня не было выбора, я разрешил ей! Кто бы смог отказать?$b$bУвы, бедняжка Дженни Потрясная не вернулась! Я опасаюсь самого худшего, $n. Найди ее!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28207, 'ruRU', 'Скользкая ситуация', 'Соберите 7 изумрудных мерцающих грибов.', 'Этому несчастному едва удалось выбраться живым с Заставы Отравленной Крови! Если мы хотим помешать тому, чтобы он превратился в такое же существо из слизи, как и остальные, мы должны справиться с инфекцией.$b$bК востоку отсюда, ниже водопада, есть пруд, заполненный ярко-зеленой водой. Вблизи от такой воды частенько растут грибы. Большая часть их никуда не годится... Я хочу, чтобы ты $gсобрал:собрала; те из них, которые ярко-зеленого цвета и светятся!$b$bВот из них я смогу изготовить что-нибудь на скорую руку для этого бедного таурена. Но поторапливайся!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28208, 'ruRU', 'Котенок Винны', 'Добудьте ушное колечко котенка Винны.', 'Наш друг таурен рассказал мне многое о том, что случилось на Заставе Отравленной Крови. Он говорит, что Винна Хеззард до сих пор там!$b$bОна мало похожа на себя прежнюю, но то, что от нее осталось, продолжает вырабатывать слизь. Мы должны остановить ее!$b$bК счастью, у меня есть план. Наш таурен сказал мне, что у Винны был котенок. Вместо молока она наливала ему в блюдце воду вместе со слизью, и он сбежал от нее в леса. Я видела какое-то существо, которое бегало по лесу к юго-востоку от Башни Отравленной Крови, но оно было определенно крупнее котенка! Иди посмотри, есть ли у него колечко в ухе...', '', 'Котенок успел подрасти…', 'Котенок Винны', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28209, 'ruRU', 'Свободу Лидону', 'Достаньте ключ от клетки Лидона.', 'Это не ферма! Штиллец там проводит эксперименты на жителях Хилсбрада. Все монстры в округе – его рук дело.$b$bИ это еще не самое плохое, |3-6($c). Те твари, у которых ключ от моей клетки, – бывшие Отрекшиеся. У экспериментов надзирателя есть побочный эффект – Отрекшиеся превращаются в безумных зомби. Ты думаешь, почему он так боится, что они вырвутся наружу? Он знает, что такие преступления караются смертной казнью.$b$bВыпусти меня отсюда! Ключ у зараженных стражей полей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28210, 'ruRU', 'Тренировка', 'Помогите Салхету убить 8 кровавых гиен.', 'У главнокомандующего Камзеса есть для меня особое задание?$B$BПогоди... не говори. Опять гиены небось, да?$B$BЧто ж, я покажу, на что способен.$B$BВстретимся у Хребта Стражей Солнца.$B$BЯ тебя не разочарую.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28211, 'ruRU', 'Сталь, закаленная в огне элементалей', 'Соберите 8 закаленных копий.', 'Сначала о главном: нам нужны боеприпасы. Мощные боеприпасы, которые способны пробить даже броню черного дракона. $B$BК западу от Громтара находится город Громовых Молотов, захваченный вольными духами огня. Если там осталось какое-либо оружие, то оно уже многократно закалилось в пламени элементалей – а значит, гораздо прочнее того, что могу выковать я!$B$B$n, отправляйся на Пожарище Гумбольдта и принеси мне оттуда копья. И чем острее они будут, тем лучше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28212, 'ruRU', 'Горячо!', 'Соберите 5 капель раскаленного неистовства.', 'Я собираюсь в четыре раза увеличить крутящий момент стандартного копьемета, но, по моим вычислениям, один выстрел из такого оружия может разрушить корпус. И, возможно, расколоть планету пополам.$B$BА вот если бы у меня был надежный источник чистого огня элементалей, я бы смог сварить шасси в сто раз прочнее.$B$BК западу отсюда по Пожарищу Гумбольдта гуляют вольные углебесы. Если убить одного из них, то он распадется на капли раскаленного неистовства, которые ты мне и принесешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28213, 'ruRU', 'Избавление от Хеззард', 'Воспользуйтесь ушным колечком Мур\'рзика, чтобы отвлечь Винну, а затем убейте ее.', 'Винну можно найти в дальней части Заставы Отравленной Крови, к западу отсюда. Все ее внимание приковано к слизи. Она, не отрываясь, следит, чтобы слизь не переставала течь, от этого зависит ее безопасность! Но если ее отвлечь...$b$bВозьми это ушное колечко и покажи его Винне. Может быть, в ней осталось еще хоть что-то душевное. Вдруг она пожалеет своего несчастного котенка и в это время отвлечется от слизи!$b$bТогда ты сможешь попытаться ее убить и остановить выработку слизи. Вот так!', '', 'Она выглядит несколько иначе…', 'Винна Хеззард', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28214, 'ruRU', 'Очищение Заставы Отравленной Крови', 'Убейте 6 рабов слизи с Заставы Отравленной Крови.', 'Бр-р-р...$b$bНе $gмог:могла; бы ты... уф... пожалуйста... БЛУРГХ!$b$bПрости, у меня все еще не очень хорошо... с желудком. Если ты идешь на Заставу Отравленной Крови, что к западу отсюда, то, пожалуйста УУРГХ...$b$bПросто... просто положи конец мучениям тех созданий, которыми стали мои друзья. Иди ПРЯМО СЕЙЧАС. Для своего же блага. Ууургх...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28215, 'ruRU', 'Потенциальная энергия', 'Соберите 10 скрученных пружин из элементия.', 'Тебе прекрасно известно о том, что потенциальная энергия, заключенная в обычной пружине, равна квадрату смещения пружины, умноженному на половину ее жесткости. Это, конечно, не относится к пружинам, сделанным из элементия – у них запасы энергии просто огромны. Нет, не огромны – чудовищны!$B$BМне нужен элементий для моего секретного оружия – и совершенно случайно служители культа Сумеречного Молота используют для связывания элементалей земли именно такие элементиевые пружины, которые мне нужны.$B$BИди на восток, в ужасный край под названием Черный разлом, и собирай эти пружины с тел убитых обсидиановых рабов камня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28216, 'ruRU', 'Повелитель магмы Фалтазар', 'Добудьте голову повелителя магмы Фалтазара.', 'С запада только что прибыл гонец с дурными вестями – мы потеряли Гумбольдт. Стена огня стерла его с лица земли!$B$BТе, кто выжил, утверждают, что это дело рук Сумеречного Молота, а именно некоего повелителя магмы Фалтазара. Он – \"возвысившийся\", то есть один из высших чинов в иерархии Молота, тот, кто стал одним целым со стихиями. Существо, состоящее из чистого огня.$B$BА скоро он станет существом, состоящим из чистого пепла! Иди на Пожарище Гумбольдта и убей Фалтазара! Принеси мне его голову!', '', 'Ищи его в центре пламени.', 'Повелитель магмы Фалтазар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28217, 'ruRU', 'Разыскивается: охотник на демонов', 'Убейте Феронаса Греховодника.', 'После того как мы изгнали сатиров с Холма Нефритового Пламени, Изумрудный Круг поручил друидам начать долгий процесс очищения руин. Прошлой ночью некоторые из этих друидов были убиты... ночным эльфом.$b$bСвидетели утверждают, что это был охотник на демонов, безумный послушник Иллидана. Нет никаких сомнений, что власть лишила его разума так же, как и его хозяина.$b$bЯ обещаю хорошее вознаграждение тому, кто представит мне доказательство смерти этого убийцы. Его видели у дороги, ведущей на север, в долине у Холма Нефритового Пламени.', '', 'Пусть свершится правосудие над этим убийцей.', 'Феронас Греховодник', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28218, 'ruRU', 'Яркая и скорбная судьба', 'Оживите в памяти битву Иллидана с Артасом.', 'Все ненавидят мой народ за то, что мы делаем... относятся к нам, как к презираемым изгнанникам, считают, что мы порочны и что нас уже не исправить.$b$bА если бы не охотники за демонами, вот эти самые леса уже были бы самой сильной крепостью Пылающего Легиона в Азероте. Я говорю о своем хозяине, \"предателе\" Иллидане Ярости Бури.$b$bСмотри $gсам:сама;. Смотри, что произошло здесь после того, как Иллидана впервые освободили, а этот лес был захвачен Повелителем ужаса Тихондрием, чьи демонические силы не встретили никакого сопротивления...', 'Артас побежден', 'Первая встреча Иллидана с рыцарем смерти Артасом закончилась жестокой битвой.', 'Артас', '', '', 'Вернитесь к Феронасу Греховоднику в Оскверненный лес.', 25549);
INSERT INTO `quest_template_locale` VALUES (28219, 'ruRU', 'Жужелы для малыша', 'Убейте 10 жужел Железнолесья, чтобы накормить сеянец заступника.', '<Маленькое растение широко раскрывает свои листочки, словно птенец, который хочет, чтобы его покормили. Оно говорит очень тихим голоском.>$b$bГолодный... хочу... жучков...<Вы слышите, как где-то южнее жужжат осы. Может быть, ими можно накормить малыша?>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28220, 'ruRU', 'В поисках земли', 'Поднесите сеянец заступника к 7 участкам плодородной земли.', '<Тонкие побеги подталкивают вас, побуждая двигаться в южную сторону. Вы даже слышите тихий голос.>$b$bЗемля...$b$b<Кажется, ему нужна свежая земля. Может быть, отнести его туда, где почва более плодородная?>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28221, 'ruRU', 'Корни для того, чтобы ими топать', 'Убейте 10 топотунов Железнолесья.', 'Много духов все еще находится в западне в этих гниющих телах...$b$bТы видишь? К северу отсюда, топотуны Железнолесья. Они больны демонической порчей и все липкие от покрывающей их плесени. Бедные духи, находящиеся внутри них, не могут вырваться наружу.$b$bТы можешь помочь! Сруби их, и духи выйдут на свободу. Я впущу духов в себя и, когда я вырасту, мы все будем счастливы вместе. Ты поможешь? Пожалуйста.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28222, 'ruRU', 'Петь под солнцем', 'Отнесите саженец заступника к 5 снопам солнечного света в Железнолесье.', 'Я так вырос... Пришло время подставить солнцу мои листья!$b$bОтведи меня к солнцу! Солнце очень далеко отсюда, но свет его доходит до меня. Благодаря этому свету я стану большим и сильным. Все радуются свету – и большие ветви, и маленькие вроде моих.$b$bТуда! Солнце на севере! Возьми меня с собой, сделай так, чтобы я затанцевал!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28223, 'ruRU', 'Тюремщик', 'Вам нужно устранить стража Сильву в Яме и забрать его связку ключей. Яма находится к юго-западу от крепости Барадин.', 'Мы почти расправились с заключенными-бунтовщиками в Яме, однако остается еще одна нерешенная проблема. Тюремщик.$b$bСтраж Сильва – глава бунтовщиков, и узники готовы на все ради него. Стоит убрать его, и мы обуздаем всех остальных. Прикончи его и принеси мне связку ключей, которую он носит с собой. Ключи помогут нам проникнуть в глубину блока и, может быть, отыскать источник водоснабжения.', '', 'Пора отправить тюремщика в досрочный отпуск.', 'Страж Сильва', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28224, 'ruRU', 'Последний заступник', 'Победите высохшего заступника.', 'Ах... спасибо тебе, $gмаленький:маленькая:r; |3-6($r). Я столько раз пытался вырасти в этом лесу, но всякий раз неудачно.$b$bС тех пор, как лес охвачен порчей, лишь одному высохшему заступнику, который прячется на севере, удалось вырасти до зрелого состояния. Но он болен как телесно, так и духовно. Мы собрали духов, которые жили в древнях. Точно так же я хочу спасти и тех, которые живут в нем.$b$bПобеди высохшего заступника и позволь живущим в нем духам присоединиться ко мне прежде, чем я пущу где-то корни.', '', 'Через разрушение и страдание появляется новая жизнь.', 'Высохший заступник', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28225, 'ruRU', 'Доказательство преданности', 'Убейте 10 дворфов из клана Черного Железа на Руинах Тауриссана.', 'Можешь еще погостить в Узкоклинье, но ты $gдолжен:должна; завоевать наше доверие. У меня как раз есть для тебя работенка.$b$bМы не единственные дворфы из клана Черного Железа в этих краях. Далеко не единственные. Нас превосходят по численности дворфы с Черной горы. Пусть мы закрепились в Узкоклинье, но даже тут они словно дышат нам в затылок с Руин Тауриссана, лежащих к северу.$b$bПрояви себя, |3-6($r). Убей их ради меня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28226, 'ruRU', 'Лом с големов', 'Уничтожьте боевых разорителей в Руинах Тауриссана, затем соберите среди выпавших деталей 3 обсидиановых поршня, 3 фильтра выхлопных газов, 3 ториевых приводных вала и 1 каменный сердечник.', 'Мы держим големов для охраны. Дворфы к северу отсюда тоже их держат, только вот непонятно для каких целей.$b$bЯ так думаю, что для убийства...$b$bНам бы пригодились запасные детали, поэтому сделай-ка вот что: уничтожь их големов и поищи потом на земле уцелевшие детали. Собери все пригодные запчасти. Конечно, все брать не стоит, так что отбирай тщательно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28227, 'ruRU', 'Подготовка големов', 'Помогите 4 угловатым големам в боевой подготовке.', 'Ты нам уже $gоказал:оказала; неоценимую помощь, |3-6($r). Ты не $gмог:могла; бы нам еще кое в чем подсобить?$b$bНаши стражники сильны, но они уступают тебе. Может быть, ты согласишься заняться их боевой подготовкой? Просто подойди к ним и покажи пару приемов. Надеюсь, они переймут у тебя технику боя и станут лучше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28228, 'ruRU', 'Воссоединение с лесом', 'Отнесите цветущего заступника обратно на холм в центре Железнолесья.', 'Пришло время прощаться. Мы встретились, когда я был сеянцем, ты $gпомог:помогла; мне пройти большой путь и вырасти. Но теперь я должен воссоединиться с лесом.$b$bОтнеси меня обратно на тот холм, где ты меня $gнашел:нашла;. Там я пущу корни и буду расти в тени моих предков.', 'Заступник возвращен на холм', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28229, 'ruRU', 'Жизненная сила воды', 'Наполните сосуд водой из лунного колодца в Роще Шелеста Ветра и вылейте воду на землю посередине между мертвыми сторожевыми древами в Железнолесье.', 'Сторожевые древа Железнолесья к северу отсюда были мертвы в течение многих лет. Их безжизненные тела – мрачное напоминание о том, какой вред был нанесен этим землям.$b$bКаждый раз, когда одно время года сменяет другое, мы набираем воду из этого лунного колодца и поливаем древа, надеясь, что это пробудит новую жизнь. Если хочешь, можешь сделать это $gсам:сама;.$b$bЭто отличная возможность предаться спокойным размышлениям. Возьми вот этот сосуд, наполни его водой из лунного колодца и вылей ее на самой вершине небольшого холма посередине между тремя сторожевыми древами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28230, 'ruRU', 'Протокол', 'Убейте чудовище Рей-Гетц-Калаба.', 'Прежде чем надзиратель будет наказан по заслугам, мы должны подавить бунт. Мы не можем рисковать и позволить этой заразе распространиться по всему миру.$b$bСреди кварталов рабочих, что к северу отсюда, бродит чудовище, которое Штиллец собрал из трех фермеров. Оно должно быть уничтожено, чтобы в Топких полях стало безопасно! Этого требует протокол!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28231, 'ruRU', 'Сделай это во имя Звездочки', 'Убейте кузнеца Верринтана.', 'Надзиратель Штиллец отправил меня на поле, чтобы я разузнал подробности бунта. На месте мы со Звездочкой наткнулись на неповоротливое чудовище по имени Верринтан. Я спрыгнул со Звездочки и побежал, что было духу. А Звездочка осталась и храбро бросилась на чудовище. Увы, оно оказалось сильнее.$b$bЗвездочка отдала свою жизнь, чтобы спасти меня. Я должен отомстить! Сделай это во имя Звездочки!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28232, 'ruRU', 'Баланда', 'От вас требуется достать 12 тюремных пайков в Яме, расположенной к юго-западу от крепости Барадин.', 'Мы испытываем нехватку провизии, $n. Только что поступило донесение, что в тюремном блоке к юго-западу отсюда хранится большое количество тюремного пайка, сохранившегося с прошлых лет. Собери столько еды, сколько сможешь, и доставь ее в лагерь.$B$BИ еще кое-что: тюремный блок кишит заключенными, так что будь $gбдителен:бдительна;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28233, 'ruRU', 'Пропавший брат', 'Найдите Бахрума Кузнецкого Молота.', 'Мой братишка Бахрум пропал!$B$BЛучший разведчик, и вот пожалуйста – все вернулись без единой царапины, а от него ни слуху ни духу. Папаша говорит, что он, наверно, где-то прохлаждается. Но ведь он же мой единственный братец! И мамаша просила меня о нем позаботиться! Пожалуйста, найди его!', '', '', '', '', '', 'Найдите Бахрума Кузнецкого Молота.', 25549);
INSERT INTO `quest_template_locale` VALUES (28234, 'ruRU', 'Они отняли у меня штаны!', 'Найдите набедренники Бахрума.', 'Почему я стою в ящике с зерном? Во-первых, тут были шершни. И еще сюда заявились орки из Драконьей Пасти. Короче говоря, мне удалось удрать, но эти мерзавцы забрали мои набедренники! А ведь их делала моя сестрица – даже мое имя на них выгравировала!.. Если она узнает, что я их потерял, я сгорю со стыда. Пожалуйста, найди их. Кажется, воры отправились вон в ту крепость. А я подожду тебя здесь. Только не надо спрашивать, что у Громового Молота под килтом!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28235, 'ruRU', 'Бернсайд должен умереть', 'Убейте мирового судью Бернсайда.', 'Когда-то мировой судья Бернсайд был мэром этого региона. Пока он был жив, ему не было равных в битве за Хилсбрад. Справиться с ним нелегко и после его смерти.$b$bБернсайд отлично владеет тайной магией. Найти его можно в северо-западной части Топких полей. Приведи нас к нему, и вместе мы положим конец его правлению раз и навсегда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28236, 'ruRU', 'Пропавший брат', 'Найдите Бахрума Кузнецкого Молота.', 'Мой братишка Бахрум пропал!$B$BЛучший разведчик, и вот пожалуйста – все вернулись без единой царапины, а от него ни слуху ни духу. Папаша говорит, что он, наверно, где-то прохлаждается. Но ведь он же мой единственный братец! И мамаша просила меня о нем позаботиться! Пожалуйста, найди его!', '', '', '', '', '', '<completion text>', 19865);
INSERT INTO `quest_template_locale` VALUES (28237, 'ruRU', 'Нарыв на теле земли', 'Добудьте голову надзирателя Штиллеца.', 'Теперь, когда мы справились с восстанием нежити, пришло время призвать Штиллеца и его пособников к ответу за совершенные преступления. И хотя мы столкнулись с трагедией, подобной которой не было со времен нападения Плети, мы должны сделать так, чтобы этого больше никогда не случилось. Все они встретят смерть!$b$bИди, $n! Мне нужна голова Штиллеца!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28238, 'ruRU', 'Сумеречный берег', 'Поговорите с Фарго Кремневым Затвором в порту Штормграда.', 'Наш час настал, |3-6($c). Штормград в безопасности, и теперь мы можем перейти в наступление. Вперед, на нагорье!$B$BБольшая часть нашего флота уже вышла из гавани благодаря твоей помощи. Фарго Кремневый Затвор уже подготовил гидроплан, который мигом домчит тебя до пункта назначения.$B$BОбратись к Фарго, стоящему в порту, и сообщи ему, что хочешь отправиться с ним на Сумеречное нагорье. Он находится у кромки воды. Доброго пути, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28239, 'ruRU', 'Поход в Загон Черного Зуба', 'Поговорите с интендантом Каошином в Загоне Черного Зуба, расположенном в Пылающих степях.', 'Это не самый убедительный наряд, но все должно получиться. Уверенный внешний вид – залог успеха в разведке. Просто веди себя как $gсвой:своя;, когда прибудешь на место, и все будет в порядке.$b$bТвоим связным в Загоне Черного Зуба станет орк по имени интендант Каошин. Он НЕ знает, что ты шпион, так что не веди себя безрассудно.$b$bДелай все, что тебе скажет Каошин. Полковник Тротман свяжется с тобой по ГНМ-передатчику, чтобы поведать дальнейшие инструкции.$b$bУдачи, солдат.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28241, 'ruRU', 'Видение Сумерек', 'Найдите Око Сумерек в Черном разломе.', 'Чо\'Галл следит за своими слугами с помощью волшебных шаров, \"Очей Сумерек\".$B$BМне нужен такой шар – тогда я смогу заглянуть в логово Чо\'Галла!$B$BИщи око в Черном разломе, он прямо к востоку отсюда, к северу от реки. Делай что хочешь, но найди его!', '', '', '', '', '', 'Найдите Око Сумерек в Черном разломе.', 25549);
INSERT INTO `quest_template_locale` VALUES (28242, 'ruRU', 'Порой приходится чем-то жертвовать', 'Убейте 10 черных шаманов.', '<Глаз говорит с вами, и вам кажется, что его грохочущий \"голос\" доносится отовсюду.>$B$BТебе нужна моя помощь, |3-6($r)? Мои услуги стоят дорого. Эти последователи Сумрака воздавали мне почести – поили меня кровью дворфов Громового Молота, которые остались в руинах своих городов. Но моя жажда велика. Быть может, тебе удастся утолить ее.$B$BУбей моих бывших повелителей, и тогда я покажу тебе все, что ты захочешь увидеть. Убей черных шаманов. В конце концов, в их жилах тоже течет кровь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28243, 'ruRU', 'Всевидящее Око', 'Отнесите Око Сумерек младшему шаману Бланди в Громтар, что на Сумеречном нагорье.', 'Ну хорошо, |3-6($r). Мои услуги оплачены кровью. Отнеси меня к младшему шаману Громтара.$B$BО да, я уже знаю, куда ты меня понесешь. Бланди – жалкий пьяница, и его способности весьма ограничены. Но ты, |3-6($r)... ты не перестаешь удивлять меня. Если бы мы объединили мое зрение с твоим талантом, то смогли бы потрясти эту ничтожную планетку...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28244, 'ruRU', 'Глаз-шпион', 'Загляните в Око Сумерек.', 'Если честно, $n, то от этой штуки у меня мурашки по коже. Но раз уж тебе пришлось столько пережить ради того, чтобы добыть этот шар, то, думаю, нам придется воспользоваться им.$B$BСначала ты.$B$BЗагляни в Око и попроси показать тебе Сумеречный бастион. Мы узнаем, что там замышляет этот жирный двухголовый мерзавец Чо\'Галл, и помешаем его планам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28245, 'ruRU', 'Солдатские будни', 'Хорошенько начистите 7 пар сапог орков клана Черной горы.', 'Ладно! Те6е повезло, что нам сегодня не хватает рук. Иначе бы я сам тебя выпорол на неделю вперед, $gпарень:девчонка;.$b$bНужно почистить обувь офицеров и старшин. Она выставлена перед их хижинами.$b$bНачисти так, чтобы та заблестела, рубака! Живо за дело!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28246, 'ruRU', 'Стратегические цели', 'Уколите бритвенно-острым жалом скорпида вудуиста Тимана, который находится на вершине Башни Пепла; заводчицу воргов Отану, которая находится в загоне воргов; и Горлопа, которого можно найти вблизи озер лавы.', '<Непонятный шум.>$n... $n, прием! Говорит Тротман.$b$bК нам поступили последние данные разведки относительно твоего следующего задания. Нужно ликвидировать три цели. Объект номер один – вудуист Тиман, стоящий на вершине Башни Пепла. Заводчица воргов Отана стоит посреди центрального загона воргов. Наконец, Горлоп находится рядом с озерами лавы на юге.$b$bЖала скорпидов, собранные тобой ранее, спрятаны среди твоих пожитков. Улучи удачный момент, чтобы воспользоваться жалами.', '', 'Приступим к ликвидации целей? Я готов на все сто.', 'Полковник Тротман', 'Ловко ты обращаешься с жалами.', 'Полковник Тротман', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28247, 'ruRU', 'Последняя в своем роду', 'Убейте Обсидию.', 'Обсидия – последний взрослый черный дракон. Мы должны ее уничтожить.$B$BЕсли тебе это удастся, немедленно сообщи о своей победе Лирастразе. Она много сделала для победы над черными драконами.$B$BСпасибо тебе. Теперь мы знаем, что ты – наш верный и сильный союзник.', 'Обсидия побеждена', 'Один из последних способных к размножению черных драконов во всем Азероте.', 'Обсидия', '', '', 'Поговорите с Лирастразой на Сумеречном нагорье, на северо-западе от Обсидианового леса.', 25549);
INSERT INTO `quest_template_locale` VALUES (28248, 'ruRU', 'Лагерь Победителя', 'Поговорите с Курдраном Громовым Молотом в Лагере Победителя.', 'Тебе удалось доказать, что ты – настоящий воин, и твои намерения чисты. Дорога на Грим Батол перекрыта, а черные драконы разгромлены – так что теперь мы загнали Сумеречный Молот в его цитадель.$B$BИди к своим предводителям. Они на северо-западе, в Лагере Победителя. Передай им, что когда начнется штурм Сумеречной крепости, в небо поднимутся красные драконы. Пусть тебе и не удалось искупить все грехи твоих союзников, но в этой битве мы на твоей стороне.$B$BСумеречный Молот будет разгромлен.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28249, 'ruRU', 'Тукмак', 'Поговорите с полководцем Зелой у Тукмака.', 'Тебе удалось доказать, что ты – настоящий воин, и твои намерения чисты. Дорога на Грим Батол перекрыта, а черные драконы разгромлены – так что теперь мы загнали Сумеречный Молот в его цитадель.$B$BИди к своим вождям. Они на западе, у Тукмака. Передай им, что когда начнется штурм Сумеречной крепости, в небо поднимутся красные драконы. Пусть тебе и не удалось искупить все грехи твоих союзников, но в этой битве мы на твоей стороне.$B$BСумеречный Молот будет разгромлен.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28250, 'ruRU', 'Маленькие любители фиников', 'Прихлопните 30 песчаных пигмеев молотом династии Тарет.', 'То, чем я промышляю, трудно назвать лучшей в мире работой.$B$BМеня не интересуют перипетии войн, сокровенные тайны Ульдума и прочая экзотика.$B$BЯ заправляю этими землями... и финиками, которые здесь произрастают.$B$BИ тут, понимаешь, эти хулиганы додумались до того, чтобы вставать друг другу на плечи и обрывать мои драгоценные фрукты!$B$BЯ этого терпеть не намерен!$B$BВозьми этот молот, выкованный титанами, благословленный солнечными королями и бог весть кем еще, и прихлопни эту мелюзгу!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28251, 'ruRU', 'Проблемы в Южнобережье', 'Поговорите с Сержем Хиноттом в Руинах Южнобережья, что в предгорьях Хилсбрада.', 'Перед тем, как меня схватили и посадили за решетку, я работал в Южнобережье. Моей главной задачей было собирать образцы грунта в руинах, чтобы убедиться в том, что гниль, которой мы заразили местность, благополучно исчезает. Это довольно просто, если бы не воргены, которые не дают нам сосредоточиться на работе.$b$bЯ хочу, чтобы ты $gотправился:отправилась; в Южнобережье и $gнашел:нашла; моего ученика, Сержа Хинотта. Удостоверься, что с ним все в порядке, и сообщи ему, что я возвращаюсь, поскольку моя работа здесь подошла к концу.$b$bРуины Южнобережья находятся к юго-востоку отсюда, на берегу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28252, 'ruRU', 'Рог призывателя кодо', 'Воспользуйтесь рогом призывателей, чтобы вернуть 7 боевых кодо Черной горы в лагерь. Если кодо заартачится, сражайтесь с ним, пока тот не станет послушным.', 'Итак, у меня для тебя есть действительно важное задание. От тебя потребуется переправить кодо с пастбищ на юг. Генерал Торг\'изог сказал, что скоро мы идем войной на Красногорье, и я не хочу, чтобы кодо задерживали нас в пути.$b$bБудь $gвнимателен:внимательна;! Порой кодо начинают артачиться, и тогда их нужно подстегнуть, чтобы вразумить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28253, 'ruRU', 'Заберем рог себе', 'Доставьте рог призывателей полковнику Тротману в Узкоклинье в Пылающих степях.', '$n, прием, это Тротман. Ты мудро $gпоступил:поступила;, оставив у себя этот рог. Уверен, мы найдем ему применение.$b$bМеня несколько взволновало известие Каошина о том, что орки собираются напасть на Красногорье. Мы знали, что атака неизбежна, но на несколько дней запоздали с приготовлениями к бою.$b$bВозвращайся ко мне вместе с рогом. Переговорим, когда вернешься в Узкоклинье. Только не повреди шпионский наряд. Твоя разведывательная миссия еще не окончена.', '', 'Рог вроде этого подействует не только на кодо…', 'Полковник Тротман', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28254, 'ruRU', 'Иголка в стане врага', 'Поговорите с Телароном Крутоиглом в Узкоклинье, что находится в Пылающих степях.', 'Мы с тобой вдвоем не одолеем целую армию, $n. Их просто слишком много. Так что нужно придерживаться плана Тротмана.$b$bНа следующем этапе от тебя потребуется определенная гибкость... в таких делах я не очень силен. Именно поэтому я полагаюсь на тебя.$b$bПоговори с Телароном Крутоиглом, городским портным. Я уже передал ему добытые тобой шкуры и грязь. Ему нужно снять с тебя мерку.$b$bТы правильно понимаешь, $n. Мы тебя переоденем во врага.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28256, 'ruRU', 'Череп Гул\'дана', 'Оживите в памяти битву Иллидана за череп Гул\'дана.', 'Иллидан отправился на поиски черепа Гул\'дана. Чтобы добраться до него, ему пришлось сражаться с целыми армиями демонов, убивая их при помощи той силы, из-за которой он и стал ненавистным всем изгоем.$b$bПосмотри, каков он в бою, |3-6($c). Смотри, как яростно он сражался с осквернителями леса и какой удар он нанес по источнику порчи.', 'Череп Гул\'дана найден', '', '', '', '', 'Поговорите с Феронасом Греховодником в Оскверненном лесу.', 25549);
INSERT INTO `quest_template_locale` VALUES (28257, 'ruRU', 'Падение Тихондрия', 'Оживите в памяти битву Иллидана с Тихондрием.', 'Да, вся сила черепа Гул\'дана досталась Иллидану.$b$bНо разве он после этого скрылся тайно, посреди ночи? Разве он использовал эту силу, чтобы достичь славы? Нет... вместо этого он выступил против Повелителя ужаса Тихондрия!$b$bСтань же $gсвидетелем:свидетельницей:c; его триумфа, |3-6($c). Посмотри, как Иллидан избавил Оскверненный лес от демонов... и какую благодарность он за это получил.', 'Тихондрий побежден', 'Предводитель натрезимов и осквернитель леса.', 'Тихондрий', '', '', 'Вернитесь к Феронасу Греховоднику в Оскверненный лес.', 25549);
INSERT INTO `quest_template_locale` VALUES (28258, 'ruRU', 'Встреча с Андером Гермайном', 'Поговорите с Андером Гремайном в Ставке командования, которая находится к югу от Старого города Штормграда.', 'У Андера Гермайна для тебя сообщение. Он хочет, чтобы как можно быстрее $gявился:явилась; к нему в штаб Ставки командования, который располагается в Старом городе Штормграда. Похоже, это очень важно, $n.', '', '', '', '', '', 'Поговорите с Андером Гермайном в Ставке командования, что к югу от Старого города Штормграда.', 19865);
INSERT INTO `quest_template_locale` VALUES (28259, 'ruRU', 'Встреча с Демизеттой Клойс', 'Поговорите с Демизеттой Клойс в подвале таверны \"Забитый ягненок\" в Квартале Магов Штормграда.', 'Я только что получил свиток от Демизетты Клойс из Штормграда. Она просит тебя прийти в таверну \"Забитый ягненок\", которая находится в городе. Никаких подробностей в письме нет, но у меня возникло ощущение, что это дело имеет некоторую важность.', '', '', '', '', '', 'Поговорите с Демизеттой Клойс в подвале таверны \"Забитый ягненок\" в Квартале Магов Штормграда.', 25549);
INSERT INTO `quest_template_locale` VALUES (28260, 'ruRU', 'Встреча с Вульфом Хансраймом', 'Поговорите с Вульфом Хансраймом в Ставке командования, что к югу от Старого города Штормграда.', 'Я получила сообщение из Штормграда, от Вульфа Хансрайма. Он хочет немедленно с тобой встретиться. Его можно найти в Ставке командования, что к югу от Старого города Штормграда.', '', '', '', '', '', 'Поговорите с Вульфом Хансраймом в Ставке командования, что к югу от Старого города Штормграда.', 19865);
INSERT INTO `quest_template_locale` VALUES (28261, 'ruRU', 'Обманщики среди нас', 'Убейте 12 аномалий Нефритового Пламени.', 'А теперь, когда ты $gнаучился:научилась; не делать поспешных выводов, может быть, ты захочешь узнать, ПОЧЕМУ я убил тех друидов.$b$bОтвет прост: они вовсе не друиды.$b$bДемоны по-прежнему блуждают в руинах, принимая обличье тех, кто борется с порчей. Убедись $gсам:сама;... вот эта повязка смочена в крови демонов. Отправляйся на север, на Холм Нефритового Пламени и там повяжи ею глаза. С нею любой увидит истинную суть демонов.', '', '', '', 'Не переборщите для первого раза.', 'Феронас Греховодник', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28262, 'ruRU', 'Встреча с лордом Тони Романо', 'Поговорите с Андером Гремайном в Ставке командования, которая находится к югу от Старого города Штормграда.', 'Лорд Тони Романо, один из старших наставников разбойников ШРУ, прислал сообщение, что хочет поговорить с тобой, $n. Отправляйся в Штормград так скоро, как только сможешь, и найди его в здании ШРУ. Это к югу от Старого города.', '', '', '', '', '', 'Поговорите с лордом Тони Романо в штабе ШРУ, который находится к югу от Старого города Штормграда.', 25549);
INSERT INTO `quest_template_locale` VALUES (28263, 'ruRU', 'Встреча с Магинором Дюма', 'Поговорите с Магинором Дюма в Башне магов, что в Квартале Магов Штормграда.', 'Я только что получила сообщение из Штормграда от Магинора Дюма, старшего наставника магов. Он просит тебя прибыть к нему в Башню магов так скоро, как только ты сможешь добраться до Штормграда.', '', '', '', '', '', 'Поговорите с Магинором Дюма в Башне магов, что в Квартале Магов Штормграда.', 25549);
INSERT INTO `quest_template_locale` VALUES (28264, 'ruRU', 'Жертва Наваракса', 'Убейте демона, принявшего обличье верховного друида Наваракса.', 'Вот уже некоторое время я выслеживаю этих демонических мошенников и теперь наконец напал на след их предводителя. Это не кто иной, как верховный друид Наваракс, глава Изумрудного Круга.$b$bДемоны прячутся за спины тех, кто ни о чем не подозревает. Если я сунусь в Рощу Шелеста Ветра, чтобы убить Наваракса, на меня набросятся ее защитники... Но ты! Ты-то можешь застать его врасплох.$b$bВозвращайся в Рощу Шелеста Ветра. Поднимись на башню друидов и на ее вершине ты найдешь Наваракса в его комнате, посреди ветвей.', '', 'Внутри таится сердце демона.', 'Верховный друид Наваракс', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28265, 'ruRU', 'Генерал Торг\'изог', 'Поговорите с генералом Торг\'изогом.', 'Пусть Каошин и оказался полезнее, чем я думал, больше от него ничего не добьешься. Настало время поговорить с генералом. Считаю, что ты к этому достаточно $gготов:готова;. Торг\'изог – один из членов \"большой тройки\", командующей войсками в Пылающих степях. В сферу его ответственности входят земли к северо-западу от крепости бухты Барадин. Надень свой костюм и отправляйся к нему. Попытайся втереться к нему в доверие. Тротман будет на связи, если нам еще что-то понадобится.', '', '', '', '', '', 'Поговорите с генералом Торг\'изогом в крепости Черной горы, расположенной в Пылающих степях.', 25549);
INSERT INTO `quest_template_locale` VALUES (28266, 'ruRU', 'Испытание магмой', 'Поговорите с Виртлом Грызжемулем и попросите его выпустить повелителя магмы Колоба. Затем победите повелителя магмы Колоба в бою.', 'Я знаю, как можно воспользоваться ситуацией. Гоблины-наемники приволокли огненного элементаля-переростка в мою крепость в качестве \"подарка\" за то, что их наняли. И что прикажешь с ним делать – в Пылающих-то степях?! Это же все равно что принести на пляж ведро песка!$b$bЕсли ищешь работенку, то придется зарекомендовать себя. Поговори с тем гоблином и вызови его элементаля на бой. Победитель заслужит мое уважение и окупит мое драгоценное время.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28267, 'ruRU', 'Расстрельная команда', 'Поговорите с командиром Шнотцем.', 'Комм цу мир, |3-6($r).$B$BХотеть кой-что показайт.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28268, 'ruRU', 'Встреча с лордом Грейсоном Тенеломом', 'Поговорите с лордом Грейсоном Тенеломом в Соборе Света в Соборном квартале Штормграда.', 'Лорд Грейсон Тенелом из Собора Света Штормграда прислал для тебя сообщение. Он хочет поговорить с тобой, когда ты в следующий раз будешь в городе. Его можно найти в Соборном квартале.', '', '', '', '', '', 'Поговорите с лордом Грейсоном Тенеломом в Соборе Света, в Соборном квартале Штормграда.', 25549);
INSERT INTO `quest_template_locale` VALUES (28269, 'ruRU', 'Встретимся в Вир\'саре', 'Поговорите с Харрисоном Джонсом в Вир\'саре.', 'Так, слушай, $n.$B$BЯ знал, что эти обелиски соединены с саркофагом Предвестья, но оказывается, это еще не все.$B$BСаркофаг – и это очень важно – каким-то образом связан с местом под названием Чертоги Созидания.$B$BТеперь, когда нам известно, что этот Шнотц в сговоре со Смертокрылом, мы никак не можем допустить, чтобы он нас опередил.$B$BЯ буду ждать тебя к северу отсюда, в оазисе Вир\'сара.$B$BТоропись, в этой гонке они уже ведут!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28271, 'ruRU', 'Сниженная продуктивность', 'Убейте 15 землечерпов или надзирателей Шнотца.', 'Слушай, $n. Вот что мне удалось узнать.$B$BЕсть такое место – Чертоги Созидания, и там стоит древнее устройство титанов. Своего рода кнопка экстренной жизне-перезагрузки для Азерота. Если его активировать, все живое в мире погибнет!$B$BЕго строили на крайний случай, но если Смертокрыл способен вывести из строя стражей титанов, он наверняка разберется, как воспользоваться содержимым саркофага, чтобы запустить это устройство.$B$BОтправляйся к Обелиску Луны, $n. И задержи их любой ценой!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28272, 'ruRU', 'Недостающие части', 'Соберите 7 древних медных свитков.', 'Я почти все понял, но мне не хватает некоторых данных.$B$BКак только мы соберем всю информацию и заполним пробелы, то активируем последний обелиск, а потом сразу отправимся на поиски саркофага Предвестья, пока его не нашел Шнотц со своими дружками.$B$BЭти убогие недоумки все здесь перерыли. Торопятся, да. Как будто не раскопки ведут, а картошку копают... Больше портят, чем грабят!$B$BИди к обелиску и обыщи их пожитки. Проверь, что они там нахватали, $n.$B$BМожет, как раз и удастся найти недостающие части.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28273, 'ruRU', 'Друг моего друга', 'По настоянию Харрисона поговорите с Суллой у оазиса Вир\'сара.', 'Мне надо распаковать вещи и посмотреть, что здесь и как. А ты пока познакомься с моим старым приятелем.$B$BСулла – отличный мужик и настоящий друг. Из тех, кому можно доверять. А в наши дни это большая редкость.$B$BНу, давай. Ты иди и знакомься, а я пока займусь делом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28274, 'ruRU', 'Два шатра', 'Отправляйтесь вместе с Суллой к цирку Суллы.', 'Ты посмотри на себя, $gдружище:подруга;! Что ж ты $gтакой напряженный:такая напряженная;?! Сплошные великие приключения – это, конечно, неплохо. Жизнь становится интереснее, насыщеннее, да... Но ведь надо когда-то же и отдыхать!$B$BА то если вечно ходить как кол проглотил, эдак очень скоро скопытишься. И будет обидно.$B$BНу, ничего. Ты – в надежных руках. Уж я-то тебя научу правильно отдыхать!$B$BКстати об отдыхе. Смотрю, Джонси привез шатры, которые я просил.$B$BЛадно, $gдружище:дружок;, давай-ка за мной!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28275, 'ruRU', 'Пушки к бою!', 'Уничтожьте 10 мрачных суден снабжения.', 'На Верфь Веллсона по морю постоянно поступают припасы, и нужно положить этому конец. Враг расставил пушки по периметру верфи в целях защиты, но мы обернем это против него: воспользуемся пушками, чтобы уничтожить суда снабжения.$B$BОтправляйся туда и посмотри, что можно сделать. Доложи мне о результатах операции.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28276, 'ruRU', 'Салхетов секрет', 'Разыщите Салхета у южной оконечности Хребта Стражей Солнца в Ульдуме.', 'Послушай, $n. Прежде чем ты махнешь на меня рукой, хочу тебе кое-что показать.$B$BВидишь ли, воин из меня плохой. С координацией беда.$B$BЯ больше по части тактики специалист.$B$BВстретимся у южной оконечности хребта – я тебе продемонстрирую.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28277, 'ruRU', 'Салхет-тактик', 'Поговорите с Салхетом и убейте 30 кровавых падальщиков.', 'Я с младых лет мечтал стать генералом.$B$BИ с готовностью записался в армию. Но, как ты $gмог:могла; заметить, мои боевые навыки оставляют желать много лучшего.$B$BМеня уже не первый раз посылают убивать гиен. На самом деле мне приходится бывать тут так часто, что я уже успел подружиться со здешними львами и научил их выполнять за меня всю работу.$B$BЭто мои солдаты, и по моей команде они готовы убивать гиен целыми стаями. Смотри!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28278, 'ruRU', 'Я – закон и наказание', 'Примените дисциплинирующую дубинку Черной горы на 20 воинах на Полях Славы. Если какой-то солдат раскусит, что вы не орк, забейте его до смерти.', 'Давно искал такого хорошего и сильного солдата как ты. Мне нужен кто-то для поддержания дисциплины в армии.$b$bПеред крепостью находятся орки, огры и тролли, готовящиеся к нападению на Красногорье. За их дисциплину отвечают мои сержанты, но и твоя помощь не помешает.$b$bВозьми-ка эту дубину и проучи парочку моих солдат. Мне безразлично, отлынивают ли они от службы или стоят по струнке. Просто побей их. Хочу, чтобы они были твердыми, исполнительными и готовыми к бою.$b$bЗа дело!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28279, 'ruRU', 'Злоупотребление полномочиями', 'Перебейте 5 старшин Черной горы при помощи дисциплинирующей дубинки Черной горы. Старайтесь убивать их быстро, пока те вас не раскусили.', '$n, прием! Тротман на связи.$b$bПохоже, ты $gвтерся:втерлась; в доверие к Торг\'изогу, и он поручил тебе следить за дисциплиной в армии. Нам это на руку.$b$bНужно будет убрать его старшин. Их можно встретить разъезжающими верхом на волке за стенами крепости Черной горы на Полях Славы. Дубась их, пока те не испустят дух. Действуй стремительно, потому что они могут раскусить тебя в этом облачении. Бей молниеносно и безжалостно, $n.$b$bКонец связи.', '', 'Надеюсь, костюм плотно сшит…', 'Полковник Тротман', 'Ха-ха-ха! Просто чудесно!', 'Полковник Тротман', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28280, 'ruRU', 'Сбей их!', 'Убейте 8 черных драконов клана Драконьей Пасти с помощью переносного дракобоя.', 'Они уже здесь, $n. Они уже здесь!$B$BЯ надеялся оснастить своими переносными дракобоями целую армию, но все, что у меня есть – это один, невероятно дорогой и ни разу не испытанный образец. Вот, держи!$B$BСтреляй в черных драконов Драконьей Пасти, которые кружат над Громтаром! Стреляй и сбивай их!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28281, 'ruRU', 'Решающая битва за Громтар', 'Убейте 8 пеших Небесных когтей из клана Драконьей Пасти.', 'Я поручаю это тебе и твоим друзьям из Альянса. Ты здорово $gпотрепал:потрепала; клан Драконьей Пасти!$B$BМногим из них пришлось спешиться, но они все еще наступают, и без твоей помощи мои воины долго не продержатся.$B$BУбей пеших Небесных когтей из клана Драконьей Пасти, и весь Громтар будет в вечном долгу перед тобой!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28282, 'ruRU', 'Наркралл Укротитель Драконов', 'Убейте Наркралла Кривого Когтя. Когда будете готовы, поговорите с Колином Громтаром.', 'Среди всех орков Драконьей Пасти особенно выделяется один – тот, которого все зовут \"Наркралл Укротитель Драконов\". Я не знаю, как ему удается укрощать драконов, но он действительно летает верхом на ужасной черной твари.$B$B$n, Наркралл – тот самый негодяй, который убил моего отца.$B$B$C, я не справлюсь с ним в одиночку – а вот твои таланты мне известны. Возможно, вместе нам удастся его уничтожить.$B$BКогда будешь $gготов:готова;, дай мне знать – и тогда мы вместе сразимся с Наркраллом!', '', 'Сообщи мне о своей готовности. Я заставлю его спешиться с дракона, но мне понадобится твоя помощь в схватке с ним…', 'Наркралл Кривой Коготь', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28283, 'ruRU', 'Что это за погремушка?', 'Осмотрите костяную погремушку на пике Темного Облака в Тысяче Игл.', 'Ты $gвидел:видела; эту светящуюся погремушку, которая лежит на земле возле хижины Иши?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28284, 'ruRU', 'Что это за погремушка?', 'Осмотрите костяную погремушку на пике Темного Облака в Тысяче Игл.', 'Ты $gвидел:видела; эту светящуюся погремушку, которая лежит на земле возле хижины Иши?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28285, 'ruRU', 'Встреча со жрицей Лореной', 'Поговорите с верховной жрицей Лореной в Соборе Света, что в Соборном квартале Штормграда.', 'Я только что получил свиток из Собора Света, $n. Верховная жрица Лорена пишет, что хочет поговорить с тобой. Тебе нужно встретиться с ней как можно скорее.', '', '', '', '', '', 'Поговорите с верховной жрицей Лореной в Соборе Света, что в Соборном квартале Штормграда.', 25549);
INSERT INTO `quest_template_locale` VALUES (28286, 'ruRU', 'На сегодня хватит крови', 'Явитесь к полковнику Тротману в Узкоклинье.', 'Торг\'изог со своим кланом Черной горы больше не является для нас стратегически важной целью. Давай перейдем к следующей фазе операции.$b$bКогда закончишь свои дела в крепости, возвращайся в Узкоклинье.', '', 'Иди домой, детка. У нас много работы.', 'Полковник Тротман', '', '', 'Доложите полковнику Тротману в Узкоклинье в Пылающих степях о выполненном задании.', 25549);
INSERT INTO `quest_template_locale` VALUES (28287, 'ruRU', 'Встреча с прорицательницей Умбруа', 'Поговорите с прорицательницей Умбруа в таверне \"Золотой бочонок\" в Квартале Дворфов Штормграда.', 'Ко мне только что прибыл гонец от прорицательницы Умбруа, $n. У нее есть какое-то важное дело, которое она бы хотела обсудить с тобой, и она просит тебя как можно скорее встретиться с ней в таверне \"Золотой бочонок\" в Квартале Дворфов Штормграда.', '', '', '', '', '', 'Поговорите с прорицательницей Умбруа в таверне \"Золотой бочонок\", что в Квартале Дворфов Штормграда.', 25549);
INSERT INTO `quest_template_locale` VALUES (28288, 'ruRU', 'Открыть им глаза', 'Воспользуйтесь призмой Деларис, чтобы напугать 20 бесов Нефритового Пламени.', 'Прежде чем ты уйдешь...$b$bМы с Бесенком провели некоторое время наедине, и я узнала много интересного о бесах. В частности, он рассказал мне о том, чего бесы боятся больше всего. Что просто приводит их в ужас.$b$bЭто показалось мне интересным и полезным, и я тут немного поколдовала. Эта призма будет проецировать изображение... в общем, того, о чем рассказывал Бесенок.$b$bГряда Затаившейся Тьмы все еще кишит бесами. Может, проверишь, как они будут реагировать на то, что я сделала?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28289, 'ruRU', 'Лунная поляна зовет', 'Отправляйтесь в Лунную поляну и поговорите с Логанааром в Ночной Гавани.', 'Я только что узнала, что одному из наших братьев на Лунной поляне нужна твоя помощь, $n. Отправляйся туда и поговори с Логанааром. Его можно найти в Ночной Гавани. Он расскажет тебе все, что нужно.', '', '', '', '', '', 'Отправляйтесь на Лунную поляну и поговорите с Логанааром в Ночной Гавани.', 25549);
INSERT INTO `quest_template_locale` VALUES (28290, 'ruRU', 'Встреча с Греззом Десницей Гнева', 'Поговорите с Греззом Десницей Гнева на Аллее Чести в Оргриммаре.', 'Грезз Десница Гнева прислал для тебя срочное сообщение, $n. Он хочет, чтобы ты немедленно $gприбыл:прибыла; к нему в Оргриммар, на Аллею Героев. Должно быть, у него есть для тебя важное задание.', '', '', '', '', '', 'Поговорите с Греззом Десницей Гнева на Аллее Чести Оргриммара.', 19865);
INSERT INTO `quest_template_locale` VALUES (28291, 'ruRU', 'Возвращение в лагерь', 'Вернитесь к главнокомандующему Камзесу на заставу рамкахенов.', 'Что скажешь, $n? Может, главнокомандующий выделит под мое руководство несколько бойцов.$B$BА если повезет, мы станем во главе целого полка. Что скажешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28292, 'ruRU', 'Это не пирамида!', 'Поговорите с Харрисоном Джонсом в крепости Штормграда.', 'То, что стоит на Террасе Творца в Ульдуме, – совсем не пирамида. Это гигантская машина, которую можно приспособить для чего угодно.$b$bПо желанию Смертокрыла служители культа Сумеречного Молота должны были переделать ее в гигантское орудие!$b$b$n, иди через портал и сообщи об этом Харрисону Джонсу в Штормграде. Он знает, что делать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28293, 'ruRU', 'Это не пирамида!', 'Поговорите с Беллоком Сияющим Клинком в Крепости Громмаш в Оргриммаре.', 'То, что стоит на Террасе Творца в Ульдуме, – совсем не пирамида. Это гигантская машина, которую можно приспособить для чего угодно.$b$bПо желанию Смертокрыла служители культа Сумеречного Молота должны были переделать ее в гигантское орудие!$b$b$n, иди через портал и сообщи об этом Беллоку Сияющему Клинку в крепости Громмаш Оргриммаре. Он знает, что делать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28294, 'ruRU', 'Встреча в Кирте', 'Поговорите с Лахланом Макгреффом в Кирте на Сумеречном нагорье.', 'После той трепки, которую мы задали Драконьей Пасти, нападения на Громтар должны прекратиться. Возможно, Громовому Молоту действительно стоит присоединиться к вашему Альянсу – мы, жители Громтара, точно в долгу перед вами.$B$BВ Кирте наш великий шаман Лахлан Макгрефф пытается устроить встречу между оставшимися в живых вождями Громовых Молотов. Заставить нас объединиться – непростая задача, но я готов помочь ему в этом.$B$BЛети на север, в Кирт, и поговори с Лахланом Макгреффом. Увидимся там!', '', '', '', '', '', 'Поговорите с Лахланом Макгреффом из Кирта на Сумеречном нагорье.', 25549);
INSERT INTO `quest_template_locale` VALUES (28295, 'ruRU', 'Встреча с караваном', 'Поговорите с Адаррой в Долине Кактусов в пустыне Танарис.', 'Пирамиду, что стоит на Террасе Творца в Ульдуме, можно использовать как некое супер оружие, которое может положить конец всему живому в Азероте.$b$b<Харрисон на минуту задумывается.>$b$bТы $gдолжен:должна; продолжить то, что $gначал:начала;. Отправляйся в южную часть Калимдора, в пустыню Танарис. Вот-вот оттуда уйдет караван в Ульдум.$b$bМожет быть, они возьмут тебя с собой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28296, 'ruRU', 'Встреча с караваном', 'Поговорите с Адаррой в Долине Кактусов в пустыне Танарис.', 'Пирамиду, что стоит на Террасе Творца в Ульдуме, можно использовать как некое супер оружие, которое может положить конец всему живому в Азероте.$b$b<Беллок на минуту задумывается.>$b$bТы $gдолжен:должна; продолжить то, что $gначал:начала;. Отправляйся на юг, в пустыню Танарис. Вот-вот оттуда уйдет караван в Ульдум.$b$bМожет быть, они захватят тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28297, 'ruRU', 'Встреча с Ормаком Лютострелом', 'Поговорите с Ормаком Лютострелом на Аллее Чести Оргриммара.', 'Ормак Лютострел из Оргриммара прислал для тебя свиток. Он просит тебя как можно быстрее прибыть на Аллею Чести и поговорить с ним. Похоже, дело срочное, $n.', '', '', '', '', '', 'Поговорите с Ормаком Лютострелом на Аллее Чести Оргриммара.', 25549);
INSERT INTO `quest_template_locale` VALUES (28298, 'ruRU', 'Встреча с Гордулом', 'Поговорите с Гордулом в Расселине Теней в Оргриммаре.', 'Гордул, предводитель разбойников клана Изувеченной Длани хочет встретиться с тобой. Как можно быстрее отправляйся в Оргриммар, $n, и разыщи его в Расселине Теней. Вероятно, у него для тебя важное задание.', '', '', '', '', '', 'Поговорите с Гордулом в Расселине Теней в Оргриммаре.', 25549);
INSERT INTO `quest_template_locale` VALUES (28299, 'ruRU', 'Встреча с Краношем', 'Поговорите с Краношем в Расселине Теней в Оргриммаре.', 'Я только что получил сообщение от Краноша, главного наставника чернокнижников Оргриммара. Он хочет, чтобы ты как можно быстрее $gприбыл:прибыла; в Оргриммар и $gпоговорил:поговорила; с ним в Расселине Теней. Должно быть, у него есть для тебя важное задание.', '', '', '', '', '', 'Поговорите с Краношем в Расселине Теней в Оргриммаре.', 25549);
INSERT INTO `quest_template_locale` VALUES (28300, 'ruRU', 'Встреча с Уредой', 'Поговорите с Уредой в Расселине Теней в Оргриммаре.', 'Я только что получил свиток из Оргриммара, $n. Он от Уреды, она – одна из тамошних наставниц магов. Она хочет, чтобы ты $gвстретился:встретилась; с ней в Расселине Теней, когда в следующий раз будешь в городе.', '', '', '', '', '', 'Поговорите с Уредой в Расселине Теней в Оргриммаре.', 25549);
INSERT INTO `quest_template_locale` VALUES (28301, 'ruRU', 'Встреча с Тергой Землелом', 'Поговорите с Тергой Землелом на Аллее Мудрости в Оргриммаре.', '$n, только что тебе пришла срочная депеша. Это от Терги Землелом, одной из наставниц шаманов в Оргриммаре. Она хочет видеть тебя как можно скорее.', '', '', '', '', '', 'Поговорите с Тергой Землелом на Аллее Мудрости в Оргриммаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (28302, 'ruRU', 'Встреча со служителем солнца Атомо', 'Поговорите со служителем солнца Атомо на Аллее Мудрости Оргриммара.', 'Мне нужно как можно скорее отправить тебя в Оргриммар, $n. Служитель солнца Атомо сообщил, что он хочет поговорить с тобой о деле, имеющем огромную важность для Орды. Ищи его на Аллее Мудрости.', '', '', '', '', '', 'Поговорите со служителем солнца Атомо на Аллее Мудрости Оргриммара.', 25549);
INSERT INTO `quest_template_locale` VALUES (28303, 'ruRU', 'Встреча с наставником Огненором', 'Поговорите с наставником Огненором в крепости Громмаш в Оргриммаре.', 'Наставник Огненор прислал для тебя срочное сообщение, $n. Он просит тебя прибыть к нему в крепость Громмаш, которая находится на Аллее Силы Оргриммара, когда ты следующий раз будешь в городе. У него есть для тебя важное задание.', '', '', '', '', '', 'Поговорите с наставником Огненором в крепости Громмаш, что в Оргриммаре.', 25549);
INSERT INTO `quest_template_locale` VALUES (28304, 'ruRU', 'Встреча с темной жрицей Сесиль', 'Поговорите с темной жрицей Сесиль в крепости Громмаш, которая находится на Аллее Силы Оргриммара.', 'Темная жрица Сесиль, член делегации королевы банши в Оргриммаре, хочет встретиться с тобой, когда ты в следующий раз будешь в городе. Ее можно найти в крепости Громмаш, что на Аллее Силы в Оргиммаре. Если она обратилась к тебе, наверняка дело важное, $n.', '', '', '', '', '', 'Поговорите с темной жрицей Сесиль в крепости Громмаш, которая находится на Алее Силы Оргриммара.', 25549);
INSERT INTO `quest_template_locale` VALUES (28305, 'ruRU', 'Участь Заставы Отравленной Крови', 'Поговорите с Келнир Песнь Листвы на Заставе Отравленной Крови.', 'Пока мы разбирались с Джеденаром, я отправил свою подругу на Заставу Отравленной Крови. Раньше нас изредка посещали таурены, но в последнее время эти визиты прекратились.$b$bМоя подруга Келнир Песнь Листвы не вернулась. Не отправишься ли ты на север, чтобы разыскать ее и узнать, что творится на заставе?$b$bКогда найдешь ее, будь $gосторожен:осторожна;... дриады вроде нее недолюбливают другие расы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28306, 'ruRU', 'Роща Шелеста Ветра', 'Поговорите с хранительницей Чистой Рощей в Роще Шелеста Ветра.', 'Ты так нам $gпомог:помогла;!$b$bЯ еще задержусь здесь и поухаживаю за этим бедным тауреном, пока его не перестанет так тошнить. Почему бы тебе не отправиться на север в Рощу Шелеста Ветра? Там очень красиво, а все друиды – так дружелюбны!$b$bПередай хранительнице Чистой Роще, что со мной все в порядке, она, наверное, волнуется, так как меня долго нет. Кроме того, она может попросить тебя помочь ей с цветами! Наслаждайся!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28307, 'ruRU', 'Встреча с Тиелисом', 'Поговорите с Тиелисом в крепости Громмаш на Аллее Силы Оргриммара.', 'Тиелис, член делегации Луносвета в Оргриммаре, хочет встретиться с тобой, когда ты в следующий раз будешь в городе. Ты можешь найти его в крепости Громмаш на Аллее Силы в Оргриммаре. Наверняка речь идет о чем-то важном, иначе бы он не пытался поговорить с тобой лично, $n.', '', '', '', '', '', 'Поговорите с Тиелисом в крепости Громмаш на Аллее Силы в Оргриммаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (28309, 'ruRU', 'Встреча с крадущимся в тени Зуру', 'Поговорите с крадущимся в тени Зуру на Алее Духов в Оргриммаре.', 'Крадущийся в тени Зуру, достопочтенный наставник жрецов, хочет встретиться с тобой, когда ты в следующий раз будешь в Оргриммаре. Его можно найти на Аллее Духов в окружении других наставников племени Черного Копья. Если он обратился к тебе, наверняка дело важное, $n.', '', '', '', '', '', 'Поговорите с крадущимся в тени Зуру на Аллее Духов в Оргриммаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (28310, 'ruRU', 'Дозор Морганы', 'Явитесь к Орелию в Дозор Морганы, что в Пылающих степях.', 'Во многом благодаря тебе наши дела в Узкоклинье завершены. Теперь мы отправимся на восток к Дозору Морганы.$b$bЛазутчики докладывают, что это место сейчас пустынно, так как большая часть жителей ушла на Черную гору, чтобы сражаться с орками. Дозор Морганы станет опорным пунктом для реализации финальной части нашего плана.$b$bВ пути тебя будет сопровождать Кишан. И, конечно же, я.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28311, 'ruRU', 'Почерневший пепел', 'Соберите 9 кучек обсидианового пепла.', 'Перед тем как разгромить остатки армии орков Черной горы, хочу, чтобы ты $gсобрал:собрала; для меня еще кое-что. Если мы хотим чего-то добиться, то надо все делать правильно и хорошенько подготовиться к операции.$b$bМне нужен пепел, $n. И не просто пепел, а пепел больших обсидиановых элементалей, встречающихся в долинах к северо-западу отсюда. Он чернее черного, что нам и требуется для твоего следующего переоблачения.$b$bНе бойся, у тебя уже есть одеяние. Это пойдет кое-кому... кое-ЧЕМУ еще.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28312, 'ruRU', 'Присмиревшие демоны', 'Соберите тела 18 поверженных демонов огня.', 'Лавовые потоки к западу отсюда – пристанище демонов огня, долгое время странствующих по степям. Ситуация в армии орков Черной горы такова, что мы, проявив надлежающую осторожность, вполне сможем подкинуть парочку демонов в их тыл и как следует повеселиться.$b$bДоставь мне тела нескольких демонов огня. Этих существ легко воскресить, чтобы затем использовать по собственному усмотрению.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28313, 'ruRU', 'Аппетитная туша ворга', 'Воспользуйтесь этим свежевателем, чтобы добыть из поверженных огромных пепельных воргов вырезку из ворга в количестве 40 штук.', 'Нам понадобится свежее мясо, так что тебе придется поохотиться на воргов. Твоя цель – ворги, обитающие по эту сторону степей.$b$b<Тротман достает длинный нож и передает его вам.>$b$bКогда разделаешься с ними, воспользуйся этим ножом, чтобы освежевать трупы и содрать с них самые сочные куски. Ворги водятся по всей территории степей, а ближайшая к нам стая обитает к северо-востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28314, 'ruRU', 'Кровавый поход', 'Убейте 25 черных драконоидов или черных драконид.', 'У меня что-то ноги затекли. Может, пройдемся, $n?$b$bПрогуляемся вокруг скалы Молота Ужаса. Хочу разведать обстановку в армии орков Черной горы до того, как мы выступим, а еще по дороге прикончить несколько их союзников.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28315, 'ruRU', 'Драконий авангард', 'Ликвидируйте Минифа, укротительницу драконов Акуми, Терромата Опаленного и Тугнара Кровобрюха.', 'Орки Черной горы не приходят в одиночку. Ты уже $gслышал:слышала; о союзных им ограх из клана Огненного Чрева и троллях из племени Тлеющего Терновника. К несчастью для нас, они привлекли на свою сторону еще и род Черных драконов.$b$bОрки с драконами уже выслали вперед своих лучших бойцов, чтобы защитить ключевые точки сбора, отмеченные драконьим черепом на шесте. Нужно обнаружить точки сбора, охраняемые авангардом, до начала битвы.$b$bТы $gготов:готова; к операции?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28316, 'ruRU', 'Сделка с драконом', 'Доставьте спасенных дракончиков Акрайду к Скользкой скале, что в Пылающих степях.', 'Давай сделаем еще один привал, пока мы обходим скалу Молота Ужаса.$b$bПомнишь дракончиков, освобожденных нами на Ясельных холмах? Все это время за ними присматривал Тротман, но нужно найти кого-то, кто лучше позаботится об этих животных. Новый друг ждет нас у Скользкой скалы, расположенной к северо-востоку от скалы Молота Ужаса.$b$bЕго зовут Акрайд, и он может стать залогом нашей победы в грядущем сражении.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28317, 'ruRU', 'Посылка для Торг\'изога', 'Надев свой маскировочный костюм пособника орков Черной горы, отнесите вырезку, маринованную в прокисшем сидре, генералу Торг\'изогу, находящемуся в Очаге Огненного Чрева в Пылающих степях. Обратитесь к полковнику Тротману, если вам нужен новый костюм.', 'Генерал Торг\'изог находится среди огров в Очаге Огненного Чрева, пещере на западном краю скалы Молота Ужаса. Доставь эту посылку генералу и его ограм-приспешникам.$b$bВ ней находятся вырезка из ворга, маринованная в прокисшем сидре, который мы добыли на Алтаре Бурь.$b$bНа твоем месте я бы не стал дегустировать это мясо.$b$bОтнеси его генералу Торг\'изогу. Он раздаст его своим подчиненным, а может и сам отведает.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28318, 'ruRU', 'Посылка для Неералака', 'Наденьте свой маскировочный костюм пособника орков Черной горы, чтобы проникнуть в Лабиринт Черепа и убедить повелителя драконов Неералака забрать от вас ящик со спящими демонами огня. Обратитесь к полковнику Тротману, если вам нужен новый маскировочный костюм Черной горы.', 'Чернокнижники из клана Черной горы часто оттачивают свое мастерство в Лабиринте Черепа, пещере в восточной части скалы Молота Ужаса. В настоящий момент их предводитель Кси\'лун находится в отлучке, поэтому в пещере заправляет другой член большой тройки – повелитель драконов Неералак. Он специализируется в драконах, а не в некромантии.$b$bЯ использовал снотворный песок на пойманных тобой демонах огня. Попробуй убедить Неералака, что это бесы чернокнижников, а не демоны огня. Когда демоны проснутся, то будут очень недовольны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28319, 'ruRU', 'Посылка для Кси\'луна', 'Наденьте свой маскировочный костюм пособника орков Черной горы и доставьте сферу из прозрачного стекла верховному чернокнижнику Кси\'луну на вершину скалы Молота Ужаса, расположенной в Пылающих степях.', 'Разведка доложила нам о том, что верховный чернокнижник Кси\'лун, последний член большой тройки, находится в пещере на вершине скалы Молота Ужаса и готовится к своему выходу.$b$bОн ждет посылку – сферу власти, с помощью которого он сможет провести могущественный ритуал призыва. Передай-ка ему вот это.$b$b<Тротман передает тебе стеклянный шар.>$b$bЭто прозрачная ледяная сфера, которую ты $gдостал:достала; в Алтаре Бурь. Она абсолютно бесполезна. Передай сферу Кси\'луну и молись, чтобы он не заметил подмены.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28320, 'ruRU', 'Атака на скалу Молота Ужаса', 'Убейте 200 захватчиков из клана Черной горы. Воспользуйтесь рогом призывателей для вызова нового верхового животного в случае гибели прежнего.', 'Судьбоносный час пробил, $n. Наступает решающий момент. Все части плана сходятся воедино.$b$bВдохни поглубже и следуй за мной. Надо напомнить Акрайду о неоплаченном долге. Затем мы пресечем нападение на Красногорье прямо на корню.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28321, 'ruRU', 'Слава в гуще хаоса', 'Ликвидируйте генерала Торг\'изога, повелителя драконов Неералака и верховного мага Кси\'луна.', 'Вам с Кишаном нужно вернуться назад на гору. Три орка избежало гибели, но мы не остановимся, пока не покончим с ними.$b$bТы правильно $gпонял:поняла;, я имею в виду большую тройку.$b$bГенерал Торг\'изог скрывается в Очаге Огненного Чрева, а повелитель драконов Неералак трусливо прячется в пещере на вершины скалы. Кси\'лун затаился в Лабиринте Черепа и строит козни со своими собратьями-чернокнижниками.$b$bРасквитайся с ними, $n. Покарай тщедушных орков Черной горы, пусть те познают всю мощь Красногорья!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28322, 'ruRU', 'Боевые трофеи', 'Осмотрите ящик с остатками припасов в Дозоре Морганы, что в Пылающих степях.', 'Сегодня мы нанесли по ним сокрушительный удар, $n. Пусть орки Черной горы все еще спускаются с пика вниз, полагаю, что они больше не представляют угрозы для мирных жителей Красногорья. Это ваша с Кишаном заслуга.$b$bМне кажется, мы проявили смекалку во время операции в Пылающих степях: собранные запасы чернокнижников нам очень помогли, а обсидиановый пепел послужил камуфляжем для дракона.$b$bОднако ж, у нас остались кое-какие припасы. Пока ты еще не $gпокинул:покинула; степи, можешь забрать все, что захочешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28323, 'ruRU', 'Встреча с братом Сребросвятом', 'Поговорите с братом Сребросвятом в Гоблинских трущобах Оргриммара.', 'Брат Сребросвят сообщил, что хочет поговорить с тобой. Когда в следующий раз будешь в Оргриммаре, навести его в Гоблинских трущобах. Кажется, это важно.', '', '', '', '', '', 'Поговорите с братом Сребросвятом в Гоблинских трущобах Оргриммара.', 19865);
INSERT INTO `quest_template_locale` VALUES (28324, 'ruRU', 'Изучение смертоносности', 'Соберите 250 образцов гнили.', 'Мы напустили на жителей Южнобережья довольно заразную гниль. Как видишь, это сработало. Но с использованием гнили связаны некоторые проблемы – она имеет тенденцию распространяться и после того, как сослужила свою службу.$b$bЯ хочу, чтобы ты $gвзял:взяла; этот набор для полевых исследований, $gотправился:отправилась; на поле и $gподсчитал:подсчитала;, какова смертоносность гнилостных слизней, распространенных нами в этой области. Используй анализатор смертоносности на лужах липкой гнили. Когда получишь надежные данные, возвращайся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28325, 'ruRU', 'Охрана природы', 'Соберите 8 использованных канистр из-под гнили.', 'Переработка отходов! Сейчас все просто помешались на этом. Королева банши утверждает, что если мы хотим добиться процветания, то должны охранять природу. Каждый должен внести свой вклад в общее дело, не так ли? А раз так, то ты сделаешь этот вклад за нас.$b$bЗдесь в Южнобережье, наверное, тысячи разбитых канистр из-под гнили. Их можно использовать повторно. Отправляйся в руины и собирай, что найдешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28326, 'ruRU', 'Расстановка фигур', 'Вернитесь к полковнику Тротману в Дозор Морганы, что в Пылающих степях.', '$n. Похоже, что вы с Кишаном закончили подготовительные действия. У меня тоже все готово.$b$bВозвращайся в Дозор Морганы. Я подготовил несколько посылок для большой тройки: Торг\'изога, Неерелака и Кси\'луна. Ты уже $gпересекался:пересекалась; с генералом Торг\'изогом. Теперь тебе представилась возможность познакомиться с оставшимися двумя лидерами.$b$bЗатем мы их ликвидируем.', '', 'Возвращайся в Дозор Морганы. У меня готово к отправке несколько посылок.', 'Полковник Тротман', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28327, 'ruRU', 'Последнее затишье перед битвой', 'Доложите о своем возвращении полковнику Тротману в Дозоре Морганы, что в Пылающих степях.', 'Прием, $n. Как слышно?$b$bБитва скоро начнется. Надеюсь, ты $gдоставил:доставила; все посылки.$b$bТы нам $gнужен:нужна; на Дозоре Морганы.', '', 'Срочно возвращайся в Дозор Морганы.', 'Полковник Тротман', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28328, 'ruRU', 'Тайные планы Сумеречного Молота', 'Воспользуйтесь пылающим факелом, чтобы уничтожить 8 копий \"Догматов Сумеречного Молота\" в Жилом квартале Глубин Черной горы.', 'Влияние Сумеречного Молота простирается очень далеко. Они без конца ищут союзников, чтобы сражаться против нас, и сейчас к ним примкнули дворфы Черного Железа в Глубинах Черной горы.$b$bМойра не так уж крепко держит в руках дворфов Черного Железа, каждый день ее покидает все больше и больше ее подданных, чтобы примкнуть к Сумеречному Молоту. Мы должны помешать этому.$b$bОтправляйся в Жилой квартал глубин Черной горы и воспользуйся этим факелом, чтобы поджечь книги, которые там распространяет клан Сумеречного Молота.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28329, 'ruRU', 'Злые гнилостные слизни', 'Убейте 5 злых гнилостных слизней.', 'Эти гнилостные слизни действительно злобные. На поверхности их эктоплазмы даже просматриваются очертания злого человеческого лица. Ты же не думаешь, что Хинотту понравится, если эти слизни будут мешать ему работать с лужами.$b$bУбей всех злых гнилостных слизней, каких встретишь, и попытайся уничтожить лужу, в которой они разводятся.', '', 'Возможно, его били в детстве.', 'Злой слизень', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28330, 'ruRU', 'Следы гнили', 'Убейте заводчика слизней Чета.', 'Следы гнили ведут к разрушенной городской ратуше. Наверняка именно там лужа, в которой разводятся слизни. Пробейся внутрь, убивая всех злых гнилостных слизней, каких встретишь!$b$bКогда все получится, Серж Хинотт без сомнений захочет узнать о твоих успехах.', '', 'Тебе каюк!', 'Чет', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28331, 'ruRU', 'Жезл Гелькулара дает...', 'Воспользуйтесь жезлом Гелькулара, чтобы наделить силой 8 темных следопытов.', 'Подумать только, я, мастер некромантии, учившийся у самого Кел\'Тузада, был превращен в обычный лежащий в могиле труп. К счастью, моему сообразительному ученику Тайлванду удалось отыскать героев, которые помогли это исправить.$b$b<Гелькулар резко вскидывает руку, демонстрируя свой жезл.>$b$bСила этого жезла помогла мне переродиться. Жезл дающий и жезл отнимающий!$b$bВозьми его и используй для того, чтобы придать сил нашим темным следопытам, которые дерутся с воргенами на поле к северу от нас. Влей в них силу при помощи моего жезла.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28332, 'ruRU', 'Приказ Гелькулара', 'Убейте 15 охотников из стаи Кровавых Клыков.', 'Наши темные следопыты обследуют поля в поисках террористов воргенов. Их темные хозяева прислали их, чтобы они выслеживали и убивали нас. Темным следопытам нет равных в битве. Но воргены часто нападают стаями, благодаря чему могут одолеть даже такого сильного противника.$b$bОбыщи поля вокруг Руин Южнобережья, найди охотников из стаи Кровавых Клыков. Убивай всех, кого увидишь! Во имя Отрекшихся и во имя Лордерона!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28333, 'ruRU', 'Их пора смазать', 'Воспользуйтесь крюком Дарлы, чтобы собрать канистры с маслом и использовать их для смазки 7 крошшеров Железнолесья.', 'Прогалину Железнолесья легко узнать по большому количеству бревен, нефти и изможденным рабочим. Третье – прямое следствие первого и второго, но, когда могу, я стараюсь использовать имеющиеся ресурсы с максимальной эффективностью.$b$bНаши крошшеры работают в три смены без дополнительной оплаты, и у них совсем не остается времени на то, чтобы пройти техосмотр.$b$bВоспользуйся этим погрузочным крюком, чтобы стащить канистры с маслом, которые разбросаны вокруг лагеря, и смажь маслом крошшеры. Хорошо?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28334, 'ruRU', 'Огненный бой', 'Воспользуйтесь коробкой сигнальных свечей Дарлы, чтобы обнаружить 8 хищников Когтистых Ветвей и убить их.', 'Долгое время нам удавалось держать эти разработки в секрете, но про них пронюхали воргены с Поляны Когтистых Ветвей. Теперь они всячески пытаются заставить нас прекратить работу.$b$bНекоторые рабочие говорили мне, что видели воргенов, рыщущих вблизи Прогалины. Возьми эти огромные сигнальные свечи. Они достаточно яркие, чтобы осветить все, что будет поблизости.$b$bВоспользуйся свечами, чтобы обнаружить крадущихся воргенов, и убедись, что ни один из них не ушел живым!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28335, 'ruRU', 'Выключи его! Выключи его!', 'Выключите главный насос в глубине Пещеры Железнолесья.', 'Эти чертовы воргены! Они проскользнули за моей спиной в пещеру.$b$bНаверняка это они что-то сотворили с главным насосом! Если его слишком долго не выключать, то все трубы, что под нашими ногами, взорвутся. Думаешь, хуже, чем нынешняя утечка нефти, не бывает? Подожди немного и увидишь!$b$bСлушай, если тебе удастся пробраться в глубину пещеры и выключить главный насос, ты спасешь всех нас!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28336, 'ruRU', 'Ударить и заткнуть', 'Ударьте 7 паникующих рабочих, чтобы они пришли в себя и заткнули нефтяные фонтаны.', 'Вот черт... неужели опять! Если ты $gслышал:слышала; крики десятника, то это означает, что у нас снова утечка нефти! Опять эти грязные воргены!$b$bСлушай, сейчас тут начнется полнейшая паника. Измученные бессонницей гоблины будут носиться по Прогалине и орать, не зная, что им делать. Я хочу, чтобы ты $gпривел:привела; их в чувство.$b$bХорошая пощечина должна сделать свое дело! Это заставит их прекратить истерику, вернуться к работе и закрыть бьющие нефтяные фонтаны!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28337, 'ruRU', 'Крошшеры Железнолесья', 'Уничтожьте 9 крошшеров Железнолесья.', 'Отвратительно, не правда ли? Только посмотри на них. Жалкие создания, которые без такого снаряжения даже и работать не могут.$b$bТопчутся здесь в своих громоздких металлических крошшерах, рубят лес в щепки. Поручусь, что сами они считают, что находятся в безопасности, тепле и уюте.$b$bДокажи им, что они ошибаются. Двигайся в северном направлении и уничтожай все крошшеры, какие встретишь. А когда прольешь немного крови, мы разнесем тут все для всеобщего блага.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28338, 'ruRU', 'Северные фурболги Мертвого Леса', 'Убейте 15 любых фурболгов Мертвого Леса в Деревне Сквернолапов.', 'Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.$B$BПлемя Мертвого Леса злобное, но это все действие скверны, поразившей их разум. Они враждебны не от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.$B$BПрошу тебя, $n, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28339, 'ruRU', 'Живая нефть', 'Достаньте 10 капель неочищенной нефти у нефтяных слякочей.', 'В прошлый раз, когда у нас была такая же серьезная утечка, нефть и сама как будто пыталась сбежать!$b$bНе знаю, из-за чего так получается, может, дело во всех этих демонах, но так или иначе, когда достаточно большое количество нефти вытекло, половина ее собралась в шарики и попыталась удрать.$b$bА это ведь чистая прибыль! Догони этих нефтяных слякочей и отбери у них нашу драгоценную нефть!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28340, 'ruRU', 'Договоренность насчет бомб', 'Соберите 8 штук взрывчатки Железнолесья в Пещере Железнолесья.', 'Эти болотные комки слизи вытурили из пещеры всех моих рабочих! Дарла прислала меня сюда, чтобы собрал все, что осталось, но ты же видишь, что там творится? Я в пещеру не пойду!$b$bЗдесь осталось много нашей взрывчатки, и мы не можем ее бросить.$b$bПредлагаю сделку. Ты отправляешься в пещеру и собираешь взрывчатку. Я остаюсь тут, и эти твари не превращают меня в бездыханное тело. А если и ты останешься в живых, то я тебе заплачу! Ну, как?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28341, 'ruRU', 'Сбор грязи', 'Соберите 8 энтропических сущностей энтропических ужасов в Долине Рваных Ран.', 'Хотя мы, друиды, и сторонимся демонической силы, которой заражены эти земли, бороться с нею необходимо.$b$bДолина Рваных Ран, что к югу отсюда, охвачена порчей. Силы, которые бушуют там, такие мощные, что действуют почти как живые и жестокие существа. Магия скверны в такой форме, которая позволяет ей нападать на все живое.$b$bЯ наблюдаю за этими чудовищами и изучаю их силу. Мне нужно убедиться, что с течением времени они слабеют. Достань мне их энтропические сущности, чтобы я смогла проверить, уменьшаются ли они.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28342, 'ruRU', 'Частицы порчи', 'Соберите 9 обломков инферналов из Долины Рваных Ран.', 'Инферналы, обитающие в долине Рваных Ран, сильны, но все же уязвимы. Мы всеми силами стараемся уменьшить их численность.$B$BНо уничтожение инферналов не решит всех проблем, оказывается, в камне, из которого они состоят, магия Скверны сохраняется даже после их гибели.$B$BСейчас долина Рваных Ран усыпана останками инферналов, эти камни заражают землю, на которой находятся. Принеси их мне, пожалуйста, и моя благодарность не будет знать границ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28343, 'ruRU', 'Дыхание Кенария', 'Найдите артефакт дыхание Кенария, которым владеет пиромант Зерно Мудрости в Глубинах Черной горы, и воспользуйтесь им, чтобы закрыть 3 стихийных врат.', '$n, мы узнали, что недостающий артефакт Кенария оказался в руках пироманта Сумеречного Молота. Пиромант Зерно Мудрости унес артефакт \"Дыхание Кенария\" в Глубины Черной горы и там пользуется его силой, чтобы открывать стихийные врата.$b$bМы должны действовать, чтобы помешать Зерну Мудрости призывать элементалей для усиления войск его союзников из клана Черного Железа. Достань этот артефакт и воспользуйся его силой, чтобы закрыть те стихийные врата, которыми пользуется Зерно Мудрости.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28344, 'ruRU', 'Знаешь, что делает \"лок\'тар\"?', 'Найдите Оркуса, свергнувшего Короля, в руинах Южнобережья, что в предгорьях Хилсбрада.', 'Незадолго до тебя сюда прибыл орк на ледяном змее и просил, чтобы я направил его туда, где \"тусуются новички\". Не будучи уверенным в том, что я его правильно понял, я посоветовал ему исполнять свои обязанности члена Орды и разобраться с окрестными воргенами. Он прорычал что-то о том, \"что делает лок\'тар\" и исчез в южном направлении, к докам.$b$bС одной стороны, одним орком больше, одним меньше, с другой стороны, действительно интересно, что может сделать этот \"лок\'тар\". Разузнай.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28345, 'ruRU', '*Бульк* ПОМОГИТЕ! *Бульк*', 'Помогите Оркусу, свергнувшему Короля, выбраться из воды.', '<Бульк>$B$BПомогите!$b$b<Судорожный вздох>$b$bОркус тонет! Спаси меня, $n!$b$b<Бульк>$b$bДворф бросил Оркуса в воду! Я не хочу умирать!$b$b<Бульк>$b$bОн об этом еще как пожалеет.', 'Оркус благополучно вытащен из воды', '', '', '', '', 'Поговорите с Оркусом, свергнувшим Короля, в руинах Южнобережья, что в предгорьях Хилсбрада.', 25549);
INSERT INTO `quest_template_locale` VALUES (28346, 'ruRU', 'Завидный жених', 'Обсудите возможность заключения брака с Киганом Огнебородом, который находится в Сумеречном нагорье, в Кирте.', '$n, мы должны добиться успеха. Это же наши родичи, родная кровь! Семейные узы разъединили кланы Громовых Молотов, и они же должны скрепить их союз. Дело непростое, но ничего не поделаешь – нам придется стать свахами!$B$BЯ разыщу Колина Громтара и поговорю с ним. А ты иди внутрь и поговори с Киганом Огнебородом. Он достаточно умен – поймет, что такое династический брак. Иди и узнай, кто ему нравится!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28347, 'ruRU', 'Coffer of Promise TRACKING QUEST', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (28348, 'ruRU', 'Встреча с Грозовой Вершиной', 'Узнайте о том, как Оркус встретился с Грозовой Вершиной.', 'В надежде получить какую-нибудь информацию о действиях Альянса в Хилсбраде, я отыскал этого дряхлого некроманта, Гелькулара.$b$bГелькулар дал мне задание выслеживать и убивать воргенов. Как правило, такие вещи не являются проблемой для Оркуса, но так как недавно я съел несколько порций зажигательных отбивных Могиля из химерока, то меня скрутило от боли в животе. Вот тогда-то и начались все проблемы, которые привели к тому, что я оказался в воде.$b$bПослушай Оркуса, $n.', 'Узнайте о встрече с Грозовой Вершиной', '', '', '', '', 'Поговорите с Оркусом, свергнувшим Короля, в руинах Южнобережья, что в предгорьях Хилсбрада.', 25549);
INSERT INTO `quest_template_locale` VALUES (28349, 'ruRU', 'Мегз из маркетинга', 'Поговорите с Мегз Жестекрошшер в штаб-квартире ТКК на Кезане.', 'Босс, пока ты $Gнаходился:находилась; внизу в шахтах, Мегз Жестекрошшер из маркетинга спрашивала о тебе. Может, это связано с твоим новым средством передвижения?$B$BОна ожидает тебя у здания, что слева отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28350, 'ruRU', 'Искусный зверолов', 'По поручению Суллы соберите 5 обрезков мяса любого из диких зверей Ульдума.', 'Ты, наверное, не знаешь, $n...$B$BЯ происхожу из старинного рода звероловов. Искусство поимки зверя наиболее гуманным способом передается у нас в семье из поколения в поколение, от отца к сыну.$B$BЛюбой зверолов скажет тебе, что самое важное в этом деле – хорошая приманка.$b$bЛадно, начнем с самого легкого.$B$BВот тебе ведро. Его надо наполнить мясными обрезками. Подойдет мясо любого дикого зверя Ульдума.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28351, 'ruRU', 'Безграничный потенциал', 'Возьмите укрепленную клетку и поймайте 5 прытких пигмеев.', 'Многие думают, что песчаные пигмеи – это не более чем вредители и паразиты, а то и вовсе злобные демоны, мелкие, но пакостные.$B$BТакое вот распространенное заблуждение. Да-да, именно заблуждение!$B$BПри правильном уходе они превращаются в настоящих миляг... и легко поддаются обучению. С ними приятно работать.$B$BКстати, у тебя есть возможность своими глазами увидеть, как это бывает. Вот, возьми эти клетки и налови мне пигмейчиков.$B$BМожет так случиться, что тебе придется их поколотить, чтобы запихать в клетки, но в конечном итоге это для их же пользы.$B$BВ общем, $gсам:сама; все увидишь!$B$BОтправляйся к пигмеям на юг!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28352, 'ruRU', 'След верблюда', 'Укротите 3 верблюдов с помощью верблюжьей упряжи Суллы.', 'Здравствуй-здравствуй, $gдружище:подруга;!$B$BВсегда рад тебя видеть в этом скромном шатре.$B$BИщешь, чем бы заняться? У Суллы найдется для тебя работенка!$B$BТы займешься отловом верблюдов! Верблюд – вообще животина полезная. В любом хозяйстве. А в цирке – так вовсе необходимая! Вот $gсам:сама; посуди: какое же представление без верблюдов?!$B$BВозьми эту упряжь и приведи мне сюда пару-тройку бесхозных диких верблюдов.$B$BПоначалу они будут сопротивляться, так что придется их... э... укротить. В общем, ты все понимаешь.$B$BМножество верблюдов обитает в пустыне на юге.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28353, 'ruRU', 'Джонси зовет!', 'Поговорите с Харрисоном Джонсом в оазисе Вир\'сара.', 'Послуйшай, $n, а не сходить ли тебе обратно к Джонси, когда выдастся минутка?$b$bНе знаю, о чем он хочет тебя попросить, но наверняка это более срочные дела, чем все то, в чем ты можешь помочь мне тут.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28354, 'ruRU', 'Кайша снова взлетит', 'Соберите 8 грибов Грязного Рыла.', 'Кайша снова будет летать, $n. Это необходимо, чтобы мы смогли отомстить. К сожалению, Оркусу нужно остаться с Кайшей. Ты $gдолжен:должна; помочь нам. Я умоляю тебя!$b$bСлушай меня внимательно. Когда я только прибыл сюда, я несколько дней летал вокруг, чтобы изучить рельеф местности. К востоку отсюда есть ферма, которая долго была заброшенной, а теперь ее захватили гноллы. На этой ферме растет один особенный гриб, который называют грибом Грязного Рыла. Отправляйся туда и собери этих грибов для Кайши. Возвращайся, когда сумка будет полна.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28355, 'ruRU', 'Маленькие гадкие создания', 'Убейте 10 гноллов во Владении Нетандера.', 'Гноллы! Эти гадкие мелкие создания – настоящая зараза для любых земель. Невозможно не обращать на них внимание, если Хилсбрад считается территорией Отрекшихся. Убей как можно больше гноллов во Владении Нетандера. Для всеобщего блага!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28356, 'ruRU', 'Предупреждающий удар', 'Убейте 15 любых наг на Восточном побережье.', 'В этих документах содержится описание скорой атаки на Южнобережье. Теперь, когда войска Альянса отброшены, наги с Восточного побережья собираются захватить город.$b$bНо если ты поможешь, этому не бывать!$b$bУбей наг Восточного побережья, а потом отправляйся с докладом к Гелькулару в руины Южнобережья. Возьми с собой планы нападения клана Пронзающего Гребня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28357, 'ruRU', 'Задай им жару', 'Убейте 8 защитников поляны Когтистых Ветвей.', 'Эти шелудивые псы думают, что могут безнаказанно совать нос в мои дела? Я им покажу...$b$bГоворя это, я имею в виду, что ТЫ им покажешь. Ты и небольшая армия гоблинов с топорами, которых я отправила на Поляну Когтистых Ветвей.$b$bЭто место сейчас просто кишмя кишит воргенами. Там-то мы их и возьмем. Отправляйся на юго-восток, присоединяйся к гоблинам и пусть полетят клочки по закоулочкам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28358, 'ruRU', 'Охота на проклятых', 'Убейте 6 караульных-инферналов.', 'Первыми демонами, которые пришли в этот лес, были инферналы. Давным-давно эти могущественные существа из камня и демонического огня упали с неба, чтобы захватить эту землю для Пылающего Легиона.$b$bПочерневшие от огня кратеры, которые можно видеть в южной части Долины Рваных Ран, как раз и есть следы того, что когда-то там приземлились инферналы. Инферналы и до сих пор могут бродить там. Они свирепы, но убить их – это и достойно, и благородно.$b$bВсем, кто присоединится к охоте, я обещаю вознаграждение. Когда закончишь, возвращайся сюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28359, 'ruRU', 'Ядро Крошиуса', 'Добудьте огненное ядро Крошиуса.', 'Самого ужасного демона Долины Рваных Ран зовут Крошиус. На него охотились в течение многих лет, но каждая гибель лишь делала его сильнее.$b$bРаз за разом в этот лес приходили чернокнижники и оживляли Крошиуса. Теперь он скрывается на юго-востоке в окружении демонического огня, поджидая тех, кто осмелится прийти и помериться с ним силой.$b$bЯ больше не позволю этому продолжаться! Убей Крошиуса и принеси мне его огненное ядро.', '', 'Без ядра он больше не сможет возродиться.', 'Крошиус', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28360, 'ruRU', 'Положить конец их страданиям', 'Убейте 8 болезненных оленей.', 'Мне бы так хотелось спасти всех созданий этого леса, но, как ты, наверное, $gвидел:видела;, многим из них уже не помочь.$b$bКогда мы только нашли Рощу Шелеста Ветра, леса к югу отсюда населяли прекрасные олени, величественные и нежные животные. Порча, поразившая Рощу, не сделала их жестокими, но они чахнут и слабеют.$b$bДаже если мы сможем избавить их от порчи, они все равно будут чувствовать лишь боль и страдания. Пожалуйста, |3-6($c), окажи мне услугу и положи этому конец.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28361, 'ruRU', 'Чистые белочки', 'Потрите 6 больных белочек.', 'Крупные животные зачастую настолько пострадали от порчи, что их уже не спасти, но ты удивишься, когда узнаешь, насколько устойчивыми к этой болезни могут быть мелкие.$b$bВозьмем, к примеру, белок. После купания в загрязненной воде они могут разнести заразу далеко от ее источника, но сами при этом практически не пострадают. И решается эта проблема легко – достаточно просто помыть белку. В результате – чистая белка и более безопасный лес!$b$bВот, возьми-ка эту бутылку с очищающим составом. Хватай любую белку, какую увидишь в лесах, к югу отсюда, и хорошенько потри ее. Они будут благодарны тебе за это!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28362, 'ruRU', 'Глупый Дризл!', 'Найдите Дризла в Деревне Сквернолапов.', 'Глупый, глупый Дризл! Говорила же я ему не ходить туда!$b$bОн хотел утащить меда из Деревни Сквернолапов... той, что к западу отсюда, знаешь? Ее видно со скалы...$b$bНеважно... Я говорила ему, что это глупая идея, но он все равно пошел, и племя Мертвого Леса схватило его, и... и...$b$bШмыг...$b$bЯ не знаю, что они собираются с ним делать! Пожалуйста, найди его, $gдядя:тетя; |3-6($r)! Он, конечно, дурак! Но я все равно не хочу, чтобы его съели!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28363, 'ruRU', 'Осиное гнездо', 'Поговорите с Суллой в цирке Суллы.', 'Ух ты!$B$BПохоже, $n, ты слегка $gперестарался... разворошил:перестаралась... разворошила;, так сказать, осиное гнездо. Они сейчас будут держаться настороже, так что соваться туда нам не стоит.$B$BЗначит, нужно придумать какой-то другой способ...$B$BЭто лишь вопрос времени, когда дружки Шнотца активируют обелиск, а мне нужно еще изучить эти свитки. Так что придется тебе $gсамому:самой; измышлять способ действий.$B$BУ Суллы в этих краях есть связи. Может быть, он нам поможет пробраться внутрь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28364, 'ruRU', 'Ключ вождя', 'Отберите у вождя Кровавой Утробы ключ Дризла.', 'Хнык... Я прошу прощения! Я же не думал, что меня поймают! А они схватили меня, посадили на цепь и оставили здесь! Я не могу двигаться, у меня онемела нога, и я хочу есть!$b$bКлюч у вождя... у вождя Кровавой Утробы, как его называют. Он в северной части лагеря.$b$bБыстрее! Пожалуйста! Не бросай меня тут одного!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28366, 'ruRU', 'Обезоружить медведей', 'Соберите 7 предметов оружия племени Мертвого Леса в Деревне Сквернолапов.', 'Я предпочитаю сделать все, что только возможно, чтобы защитить мой народ от племени Мертвого Леса, не убивая их всех до единого. Мы и раньше предпринимали шаги в этом направлении, и если ты хочешь завоевать расположение племени Древобрюхов, то я прошу тебя присоединиться.$b$bОтправляйся в Деревню Сквернолапов, что к юго-западу отсюда, и поищи там оружие племени Мертвого Леса. Собери как можно больше. Если мы лишим племя Мертвого Леса оружия, то, может быть, сможем избежать последующего кровопролития.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28367, 'ruRU', 'Покров Творцов', 'Перемонтируйте взрывные устройства 7 бочонков с порохом в лагере Шнотца.', 'Хорошо, когда есть друзья, |3-6($c)! Сделать доброе дело – это само по себе награда, но иной раз случается и ощутимая материальная польза!$B$BМои друзья тут на днях перехватили партию груза с добычей Шнотца. Там было много всего интересного. Вот, например, очень полезная вещь, которая может тебе пригодиться.$B$BЭто древнее устройство титанов. Оно делает своего хозяина почти невидимым. Удобно, например, в лагере неприятеля. Скажем, можно потихонечку перемонтировать схему вражеских взрывных устройств и, таким образом, сорвать им все планы.$B$BДействие покрова ограниченно. Каждый раз его надо включать заново. Так что действовать надо быстро. И старайся не углубляться в лагерь!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28368, 'ruRU', 'Огонь в скважине!', 'Убейте Гролвитара Вечнопылающего.', 'Отлично, $gприятель:подруга;! Тебе удалось выключить насос, молодец!$b$bК сожалению, у нас тут серьезная проблема с этим чертовым центральным регулятором сжигания. Дарла послала туда столько рабочих, сколько смогла, но такое ощущение, что пламя себе на уме!$b$bВ буквальном смысле! Огонь взвивается и поглощает любого, кто приблизится! Так что Дарла говорит, что если тебе удастся выбраться из пещеры, в которой ты сейчас находишься, и победить этого элементаля, она тебя щедро наградит!', '', 'Наш трубопровод не для этого огромного монстра!', 'Гролвитар Вечнопылающий', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28369, 'ruRU', 'Моя сестра Фанни', 'Поговорите с Фанни Громтар в Громтаре, что в Сумеречном нагорье.', 'Прежде чем уйти, загляни в таверну, которая находится за моей спиной. Там моя сестра Фанни.$B$BСюда стекаются беженцы из всех сожженных поселений Громового Молота, и я поручил Фанни заниматься ими. Моя сестра – сильная девица, но ей нужна твоя помощь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28370, 'ruRU', 'Ловля огоньков', 'Воспользуйтесь магнитом для огоньков Дарлы, чтобы собрать 5 огоньков Поляны Когтистых Ветвей.', 'Ты можешь себе представить, что у местных воргенов есть огоньки? Ночные эльфы поделились с ними своими приспособлениями, и теперь у них тоже есть эти маленькие драгоценные огоньки, которые достают им все необходимые строительные материалы, не причиняя вреда деревьям.$b$bЕсли бы и у нас были эти штуки, то с каждого дерева мы бы смогли получать еще больше дохода. Больше материалов, больше прибыли! Вот зачем я разработала это удерживающее устройство.$b$bОтправляйся на Поляну Когтистых Ветвей и воспользуйся им, чтобы украсть несколько огоньков. Просто направь прибор на огонек и нажми кнопку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28371, 'ruRU', '[DND] ORKUS QUEST FLAG [DO NOT LOCALIZE]', 'Соберите 8 грибов Грязного Рыла.', 'Кайша снова будет летать, $n. Это необходимо, чтобы мы смогли отомстить. К сожалению, Оркусу нужно остаться с Кайшей. Ты $gдолжен:должна; помочь нам. Я умоляю тебя!$b$bСлушай меня внимательно. Когда я только прибыл сюда, я несколько дней летал вокруг, чтобы изучить рельеф местности. К востоку отсюда есть ферма, которая долго была заброшенной, а теперь ее захватили гноллы. На этой ферме растет один особенный гриб, который называют грибом Грязного Рыла. Отправляйся туда и собери этих грибов для Кайши. Возвращайся, когда сумка будет полна.', '', '', '', '', '', 'Вернитесь к Оркусу, свергнувшему Короля, в руины Южнобережья, что в Предгорьях Хилсбрада.', 19865);
INSERT INTO `quest_template_locale` VALUES (28372, 'ruRU', 'Возвращение к работе', 'Садитесь на гиппогрифа и отправляйтесь на Прогалину Железнолесья, где поговорите с Дарлой Закрутижлой.', 'Друзья – это прекрасно, правда? Все работают рука об руку, очищают лес. Но что будет с лесом потом? Все так и останется?$b$bЭтот лес нужен нам. Он нужен Орде. У меня есть приказ прислать всех, кто служит Орде, – а я надеюсь, это к тебе относится – на север, на Прогалину Железнолесья.$b$bЯ уже договорился с распорядителем полетов и получил для тебя разрешение на бесплатный полет на гиппогрифе. Когда будешь на месте, поговори с Дарлой Закрутижлой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28373, 'ruRU', 'Крепость Древобрюхов', 'Поговорите с Нафиеном в Крепости Древобрюхов, что в Оскверненном лесу. Крепость Древобрюхов располагается восточнее, за деревней Сквернолапов.', 'Ладно, я согласна, что это рискованное предприятие, но почему бы и не попытаться?$b$bПока я разбираюсь со всеми приключившимися у нас проблемами, ты поговоришь с медведями. Северо-восточные леса контролируют фурболги из племени Древобрюхов, и они нас не слишком-то любят.$b$bМне нужно, чтобы кто-то объяснил им, что Орда не так уж и плоха. Отправляйся на северо-восток, по дороге, которая ведет к Крепости Древобрюхов. Только не заходи в Деревню Сквернолапов! А когда будешь возле Крепости, спроси у фурболгов, чем мы можем им помочь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28374, 'ruRU', 'Прополка', 'Вырвите 7 плеточников рощи, чтобы проверить, подверглись ли они порче.', 'В таком месте, как это, даже для простых вещей вроде выращивания цветов или прополки, нужны большие усилия.$b$bВыросшие в роще лиловые плеточники – это знак того, что болезнь отступает. Но не все они такие, какими должны быть. Некоторые все же подверглись влиянию демонической порчи.$b$bСамый лучший способ проверить – просто вырвать их. Если они нормальные, то они побродят некоторое время и где-нибудь укоренятся заново. А вот если нет... тебе лучше быть $gготовым:готовой; к бою!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28375, 'ruRU', 'Дорога к Острову Очищения', 'Проводите Оркуса, свергнувшего Короля, на Остров Очищения.', 'Настало время возмездия, $n. Благодаря тебе Кайша снова может летать. Она отнесет нас на Остров Очищения, и мы сможем напасть на генерала дворфов Грозовой Вершины, Вандара Грозовую Вершину, и его капитана Балинду Каменный Очаг. Они оба заплатят за то, что сделали.$b$bТы $gготов:готова;? В одиночку Оркусу с этим не справиться.', 'Дорога на Остров Очищения', '', '', '', '', 'Поговорите с Оркусом, свергнувшим Короля, на Острове Очищения, что в предгорьях Хилсбрада.', 25549);
INSERT INTO `quest_template_locale` VALUES (28376, 'ruRU', 'Голова Мизериана', 'Отнесите голову Мизериана Сулле в цирк Суллы.', 'Теперь у вас есть голова одного из самых свирепых и грозных черных драконов Смертокрыла.$B$BЗа такой артефакт можно выручить очень хорошие деньги, но вам что-то подсказывает, что голову нужно отдать в музей – чтобы все ее видели и помнили темные страницы истории.$B$BХаррисон Джонс наверняка знает, как лучше всего ею распорядиться.$B$BА Сулла с радостью доставит ему голову Мизериана.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28377, 'ruRU', 'Чудесное спасение в Ложбине клана Помойных Потрохов', 'Найдите Колина Громтара в Ложбине клана Помойных Потрохов, что в Сумеречном нагорье.', 'О, легка на помине! Фанни похитили огры!$B$BЯ не верю, что жители Громтара смогут сами организовать спасательную операцию. Так что я возьму своих наездников на грифонах, и мы поддержим их с воздуха.$B$BИ мне кажется, $n, что им пригодится |3-6($c). Возьми свое снаряжение и разыщи Колина Громтара в лагере Помойных Потрохов. Лагерь находится к юго-западу отсюда, у подножия скал. Поторопись!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28378, 'ruRU', 'Поиски Фанни', 'Найдите и спасите Фанни Громтар.', '$n, мы уже начали разносить лагерь, но пока не обнаружили никаких следов Фанни. Может, тебе удастся ее найти.$B$BМы еще не осматривали пещеру позади меня, к северо-западу. Загляни туда – может, Фанни там!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28379, 'ruRU', 'Избиение огров', 'Убейте 10 огров из клана Помойных Потрохов (крушителей, метателей либо губителей Помойных Потрохов).', 'Огры из клана Помойных Потрохов! Я бы назвал их тупыми ослами, но не хочу оскорблять ослов.$B$BМы уже много лет отражали их набеги – но если они осмелели настолько, что похитили одного из наших, значит, нам придется проучить их.$B$BПомоги задать трепку Помойным Потрохам! Убивай их крушителей, метателей и губителей либо здесь, либо – еще лучше – в пещере. Они надолго запомнят этот урок.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28380, 'ruRU', 'Пиквик в опасности', 'Поговорите со штейгером Пиквиком в Пещере Железнолесья.', 'Что здесь происходит? Штейгер Пиквик уже должен был закрыть все клапаны.$b$bЕсли центральный клапан открыт, то мы можем весь день собирать нефть, но тем самым лишь отсрочим чудовищный взрыв.$b$bСлушай, если ты ценишь деньги, или жизнь, или и то, и другое, то отправляйся на юг в Пещеру Железнолесья и постарайся найти штейгера Пиквика.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28381, 'ruRU', 'Повелительница логова', 'Садитесь на гиппогрифа и отправляйтесь на Поляну Когтистых Ветвей, где поговорите с повелительницей логова Ульрикой.', 'К северу отсюда, на расстоянии полета ворона хозяйничают гоблины. Они вырубают лес, чтобы обеспечить топливом боевые машины Орды и заодно набить свой карман. Друиды закрывают на это глаза, лишь бы не нарушить и без того шаткий нейтралитет.$b$bНо с воргенов с Поляны Когтистых Ветвей хватит. Присоединяйся к нам! Укротитель гиппогрифов может отправить тебя прямо в наш дом. Повелительница логова Ульрика будет рада $gлюбому:любой:r; |3-2($r), $gкоторый:которая:r; хочет присоединиться к битве.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28382, 'ruRU', 'Враг у наших корней', 'Убейте 8 древорубов Железнолесья.', 'Наше терпение лопнуло!$b$bМы испробовали все, что в нашей власти, чтобы дать гоблинам понять, что они должны покинуть Прогалину Железнолесья, прежде чем пришлось прибегнуть к жестокости. Но так как они оставались глухи к нашим просьбам, мы стали бороться. Теперь, вместо того, чтобы просто поделить лес, они лишатся жизней из-за собственной жадности.$b$bСкоро они в полной мере узнают, какой может быть наша ярость!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28383, 'ruRU', 'Лесные огоньки', 'Воспользуйтесь лозой Быстрого Ветра, чтобы поймать 5 огоньков Поляны Когтистых Ветвей.', 'Мы с повелительницей логова многое сделали для распространения учений Кенария и дикой природы. Ей удалось заслужить мое доверие, а мне было позволено рассказать ее ученикам о лесных духах. То, что в лесу есть огоньки, это и большая честь, и благословение.$b$bНо нагрянувшие в эти места гоблины хотят украсть огоньки и использовать в своих гнусных целях. Пожалуйста, предотврати это злодеяние!$b$bВозьми эту благословенную ветвь, призови с ее помощью огоньки из западных лесов и сохрани их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28384, 'ruRU', 'На Прогалину', 'Поговорите с Алтоном Реддингом у Пещеры Железнолесья.', 'Прогалину Железнолесья надо стереть с лица земли. Если мы хотим помешать гоблинам уничтожить весь лес целиком, мы не можем быть к ним милосердными.$b$bАлтон Реддинг, защитник, которому я больше всего доверяю, уже отвел большую часть моей стаи в тыл врага, чтобы нанести удар тогда, когда они не будут к этому готовы. Ты найдешь его к западу отсюда, возле Пещеры Железнолесья.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28385, 'ruRU', 'С нефтью не шутят', 'Сломайте главный насос в нижней части Пещеры Железнолесья.', 'Мой план – обернуть гоблинскую жадность и то, что они загрязняют окружающую среду, против них самих. Любое дополнительное разрушение будет оправдано, если это поможет остановить их.$b$bВ глубине Пещеры Железнолесья, что прямо под нами, проходит множество труб, по которым гоблины выкачивают нефть со всей Прогалины. Все эти трубы присоединены к главному насосу, который находится в дальней части пещеры.$b$bИди в пещеру и сломай насос. Возникнет паника, и это даст нам возможность нанести окончательный удар.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28386, 'ruRU', 'Позаимствованные бомбы', 'Соберите 8 штук взрывчатки Железнолесья в Пещере Железнолесья.', 'В Пещере Железнолесья, что под нами, рабочих уже не осталось. Там что-то другое.$b$bСобытия развиваются в нашу пользу. Я заметил, что по крайней мере некоторые из них, убегая, закладывали взрывчатку. А она-то и нужна нам для следующей части плана.$b$bОтправляйся в пещеру и собери всю взрывчатку, какую найдешь. Когда закончишь с этим, а также с насосом, мы нанесем завершающий удар.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28387, 'ruRU', 'Выгорание', 'Воспользуйтесь украденной взрывчаткой Железнолесья, чтобы воспламенить 7 нефтяных фонтанов на Прогалине Железнолесья.', 'Благодаря тому, что ты $gиспортил:испортила; насос, в лагере много разрушений. Гоблины в панике мечутся среди нефтяных фонтанов, и вот-вот станет еще хуже.$b$bВозьми собранную взрывчатку и воспользуйся ею, чтобы взорвать нефть. Нам нужно нанести лагерю как можно больший ущерб и не позволить использовать эту нефть в качестве топлива для крошшеров... или, что еще хуже, боевых кораблей Орды.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28388, 'ruRU', 'Плата кровью', 'Убейте 7 паникующих рабочих.', 'Жалкие трусы... посмотри, в какой панике они бегут!$b$bНо пусть тебя это не обманывает, $n. Как только к ним вернется трезвость рассудка, они снова начнут тратить все свое время на рубку леса для военных нужд Орды.$b$bНе допусти этого. Безжалостно убивай рабочих на Прогалине Железнолесья. Покажи им, что их жадность тоже имеет цену!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28389, 'ruRU', 'Доклад повелительнице логова', 'Поговорите с повелительницей логова Ульрикой на Поляне Когтистых Ветвей.', 'Теперь, когда гоблины разбиты, а их оборудование уничтожено, либо они все поймут и уйдут сами, либо решат остаться, но при этом станут для нас легкой добычей. Мы победили.$b$bТы $gдрался:дралась; так же яростно, как и любой другой член стаи, $n. Возвращайся к повелительнице логова и расскажи ей о нашем успехе. Я останусь на страже.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28390, 'ruRU', 'Глоп, сын Глопа', 'Поговорите с целительницей земли Норсалой, а затем убейте грибоманта Глопа.', 'У Глопа есть сын. Будучи весьма самолюбивым, он назвал его в свою честь – тоже Глопом.$b$bУбей этого нового грибоманта. Твоя союзница-шаманка уже вернулась и ждет тебя в своей пещере в юго-западной части Верлока.', '', 'Грибомант собственной персоной.', 'Грибомант Глоп', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28391, 'ruRU', 'Беспокойный род', 'Победите Эозеру.', 'Эозера беспокойна и упряма. Она не признает наше господство и насмехается над ним. Нужно напомнить ей, где ее место.$b$bКиянка, которую ты $gдостал:достала;, все еще у меня. Возвращайся в западную часть Белого гнездовья и ударь киянкой по резонирующему кристаллу.$b$bЯ буду ждать тебя там и помогу, чем смогу. Поставь ее на место, |3-6($c).', '', 'Беспокойная праматерь.', 'Эозера', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28392, 'ruRU', 'Племя Древобрюхов', 'Поговорите с Нафиеном у входа в Крепость Древобрюхов.', 'Фурболги племени Древобрюхов – единственные фурболги, которых не коснулась порча. Они ютятся на краю этих земель, яростно защищая свой дом – Крепость Древобрюхов.$b$bОни гордые существа, но отчаянно нуждаются в помощи. Если ты $gготов:готова; им помочь, отправляйся на север и поговори с ними у входа в Крепость Древобрюхов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28393, 'ruRU', 'Опасный союз', 'Убейте 6 огнестражей-разрушителей и завладейте планами нападения генерала Кузни Гнева в Западном гарнизоне, что в Глубинах Черной горы.', 'Меня тревожит последний отчет ШРУ об активности Сумеречного Молота и клана Черного Железа, $n. Совершенно очевидно, что они готовят совместное нападение со стороны Черной горы. Нам будет сложно выдержать нападение их объединенных сил, но если мы начнем действовать до того, как они будут готовы к атаке, то имеем шансы на успех.$b$bОтправляйся в Глубины Черной горы, найди в Западном гарнизоне генерала Кузню Гнева и завладей хранящимися у него планами нападения Сумеречного Молота. Без колебаний убивай элементалей, которые оказывают поддержку его войскам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28394, 'ruRU', 'Создания повелителя големов', 'Добудьте 5 стихийных модулей, убив големов на фабрике в Глубинах Черной горы, и найдите чертежи стихийных големов.', 'Последний отчет ШРУ о событиях, развивающихся в глубинах Черной горы, выглядит пугающе, $n. Похоже, что с кланом Сумеречного Молота сотрудничает инженер Черной горы, Аргелмах, который делает для них големов, управляемых элементалями. Эти големы могут нанести нам сокрушительный удар, если Сумеречный Молот использует их против нас.$b$bТы $gдолжен:должна; предотвратить это, $n. Найди в Глубинах Черной горы фабрику, похить чертежи, которые он использует для производства големов, и стихийные модули, которые нужны для управления ими.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28395, 'ruRU', 'Перья для Нафиена', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28396, 'ruRU', 'Перья для Гразла', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28397, 'ruRU', 'Такого они точно не ожидают...', 'Убейте 8 дворфов Грозовой Вершины и 8 часовых стаи Кровавого Клыка на Острове Очищения.', 'Они совершили ошибку, оставив меня в живых, хотя у них был шанс убить меня. Возможно, они думали, что Оркус утонет. Ха! Теперь они заплатят за свою недальновидность.$b$bМы с тобой разорвем этот остров на куски, $n. Такого они от нас точно не ожидают! А когда все их солдаты будут мертвы, мы нападем на предводителей. Будь начеку. Если мы сможем нарушить их планы, то мы сорвем все вторжение!$b$bВперед, $n!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28398, 'ruRU', 'Гримуар пироманта', 'Убейте 6 сумеречных эмиссаров и завладейте гримуаром пироманта Зерно Мудрости в святилище Тауриссана, что в глубинах Черной горы.', 'Союз сил Черного Железа и Сумеречного Молота набирает силу. Пиромант Зерно Мудрости играет важную роль в руководстве силами Сумеречного Молота. Если бы мы смогли получить его гримуар, я бы смог придумать контрзаклинания или другие способны ослабления их стихийной магии.$b$bОтправляйся в Глубины Черной горы, найди святилище Тауриссана и завладей гримуаром. Не щади Зерно Мудрости и его пособников.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28399, 'ruRU', 'Связывающие камни', 'Найдите 6 стихийных связующих камней в Глубинах Черной горы. Камни можно найти в Тенегорне, Жилом квартале, святилище Тауриссана, Западном и Восточном гарнизонах.', 'Мне достоверно известно, что в ШРУ очень обеспокоены объединением сил Сумеречного Молота и дворфов Черного Железа в Глубинах Черной горы. Эта информация дает нам возможность доказать Альянсу нашу ценность, и в то же время учесть и свои интересы.$b$bВ отчете упоминается о том, что служители культа Сумеречного Молота разместили некоторое количество стихийных связующих камней в Тенегорне, Жилом квартале, святилище Тауриссана, Западном и Восточном гарнизонах. Найди и собери эти камни!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28400, 'ruRU', 'Герои Орды!', 'Украдите военные планы Альянса и станьте героями Орды.', 'А теперь дело за тем, чтобы найти военные планы и победить их предводителей! В случае нашего успеха мы заслужим похвалу самого верховного полководца орков, который участвовал в войне в Серебряном бору, а теперь находится на мельнице Таррен, что в самом сердце Хилсбрада! Мы будем героями Орды, $n!$b$bВперед! Вместе мы справимся с отродьями Альянса!', 'Станьте героями Орды.', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28401, 'ruRU', 'Рабы Повелителя Огня', 'Воспользуйтесь тотемом свободы, чтобы освободить сущности 6 огнестражей, огнестражей-разрушителей или пылающих огнестражей в Глубинах Черной горы.', 'Служители культа Сумеречного Молота и дворфы Черного Железа объединяют свои силы в Глубинах Черной горы. Их войска поддерживают огненные элементали, которые служат Рагнаросу Повелителю Огня.$b$bЕсли мы разрушим узы, связывающие элементалей с повелителем, то тем самым мы и ослабим вражеские войска, и отдадим дань уважения стихиям. Возьми этот тотем и воспользуйся им, чтобы освободить порабощенных огнестражей. После этого они смогут вернуться в свое естественное состояние.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28402, 'ruRU', 'Шустрые солдаты Шнотца', 'Убейте 10 элитных штурмовиков Шнотца в Зале Луны.', 'У меня почти все готово, $n.$B$BВ твоих свитках было достаточно информации, чтобы разгадать шифр. Осталось только перевести коды.$B$BПока я буду этим заниматься, тебе тоже найдется дело. Проверь нижний зал под Обелиском Луны. После твоего взрыва кое-кто из приспешников Шнотца мог выжить. Не исключено, что они прячутся под обелиском.$B$BВ общем, сходи и проверь. Я подойду позже. Как только закончу переводить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28403, 'ruRU', '\"Битые\" данные', 'Следуйте за Харрисоном Джонсом по Залу Луны.', 'Где-то здесь, в этой комнате, должны быть два переговорных устройства.$B$BЕсли я правильно перевел древние тексты, одно из них – это смертельная ловушка, а второе – запускающее устройство. Оно должно принять коды и активировать обелиск.$B$BПонадеемся, что я ничего не напутал.$B$BСкажи, когда будешь $gготов:готова;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28404, 'ruRU', 'Ручной запуск', 'Уничтожьте стража титанов.', 'Думаю, я во всем разобрался. $B$BБлагодаря добытой тобой информации я смогу активировать эту машину. Нужно только, чтобы меня никто не отвлекал.$B$BКак только я приступлю к активации, это создание титанов наверняка попытается мне помешать.$B$BИ вот тут мне нужна твоя помощь.$B$BДумаю, ты уже $gпонял:поняла;, что тебе надо делать. Вырубить этого стража!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28405, 'ruRU', 'Оружие тьмы', 'Отправляйтесь в глубины Черной горы и добудьте у дворфов клана Ярости Горна 5 единиц усиленного стихиями оружия, а затем разбейте оружие о Черную наковальню, которая находится в Тенегорне.', 'Наши враги давно уже обосновались в глубинах Черной горы, а теперь от ШРУ поступило сообщение, что дворфы Черного Железа и клан Сумеречного Молота объединяют свои силы. Используя знания клана Сумеречного Молота, дворфы заряжают свое оружие стихийными силами. И теперь войска клана Ярости Горна вооружены этим грозным новым оружием.$b$bОтправляйся в глубины Черной горы, добудь у дворфов клана Ярости Горна это оружие и разбей его о Черную наковальню, которая находится в самом сердце Тенегорна.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28406, 'ruRU', 'Армия Черного Железа', 'Воспользуйтесь ядом быстрого действия и отравите 6 хлебных пайков в Западном или Восточном гарнизонах, что в Глубинах Черной горы.', 'События, развивающиеся вокруг Черной горы, становятся все интереснее, $n. Наши источники сообщают, что союз дворфов Черного Железа и служителей культа Сумеречного Молота становится все крепче, и вместе они готовятся к серьезной атаке.$b$bЯ передал ключевые моменты этого отчета нашим лидерам в Штормграде, а тебя хочу попросить помочь разобраться с растущей угрозой, которая исходит от клана Черного Железа.$b$bВ Западном и Восточном гарнизонах, которые находятся в Глубинах Черной горы, хранится провизия почти для всей армии Черного Железа. Возьми вот этот яд и отрави их запасы хлеба.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28407, 'ruRU', 'Девица на выданье', 'Поговорите с Фанни Грозовое Озеро в Кирте в Сумеречном нагорье.', 'Огнебород?! Хочет жениться на моей сестре?! Мир сошел с ума, честное слово, $n!$B$BНу, может, Курдран и прав. Хорошая свадьба успокоит всех... и, быть может, слегка охладит Огнеборода... Кстати, мне понравилось сражаться всем вместе против огров...$B$BНу ладно! Решение за Фанни. И что-то подсказывает мне, что она не захочет связывать себя семейными узами.$B$BЛети в Кирт и узнай, желает ли она выходить замуж. А я останусь здесь и прикончу оставшихся огров.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28408, 'ruRU', 'Символ храбрости', 'Соберите 12 безупречных перьев совы.', 'По традиции, невесты из клана Громовой Молот одеваются в белое в знак своей чистоты и непорочности. Кроме того, на голову они надевают корону из черных перьев – чтобы продемонстрировать свою ХРАБРОСТЬ.$B$BЛучший символ храбрости – перья сов, стало быть, именно они и нужны Фанни. Такие совы живут на нагорье – они часто летают вокруг деревьев, которые растут на скалах. Раздобудь такие перья.$B$BВероятно, сначала сов придется убить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28409, 'ruRU', 'За здоровье молодых', 'Встретьте Молоторука по дороге на восток от Кирте и сопроводите караван в город.', 'Было бы кощунством праздновать свадьбу по обычаям Громового Молота без выпивки! Курдран самолично наказал доставить несколько бочонков редчайшего светлого громоварского с Высокого берега, но каравану не пройти через ущелье.$B$BИди на восток вдоль южного склона горы Громового Удара и встреть караван. Найди молодчика по имени Молоторук и помоги ему провезти выпивку через ущелье. В целости и сохранности!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28410, 'ruRU', 'Кое-что позаимствовать', 'Добудьте сверток тонкой темной ткани.', 'Ради этого события все захотят принарядиться, но, к сожалению, у нас тут мало хороших тканей.$B$BНасколько мне известно, эти мерзкие гоблины на побережье используют тончайший шелк для ремонта своих дирижаблей. Какое расточительство!$B$BНайди дирижабль, который курсирует между портом Драконьей Пасти и Психходельней, и позаимствуй немного шелка из трюма.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28411, 'ruRU', 'Чего бы пожевать', 'Соберите 8 кусков свежей оленины и 5 ребер воргов.', 'Наконец-то у нас будет пир. И чтобы никаких салатов и закусок! Нам нужно мясо – много, много мяса!$B$BНа нагорье водятся олени – принеси нам оленины. У местных воргов тоже вкусное мясо – принеси несколько ребер. А мы устроим тебе такой пир, какой и не видывали во всех Восточных королевствах!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28413, 'ruRU', 'Автор слов и музыки...', 'Поговорите с Расселом Брауером и помогите ему написать песню.', '$n, за свою жизнь я сочинил множество песен, но для этой свадьбы нужно сложить особую балладу. Причем быстро!$B$BСочинить ли мне романтическую песню? Комические куплеты? Застольную?$B$BЗнаешь, мне понадобится помощь в написании текста.$B$BПоговори со мной, и тогда мы напишем песню вместе!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28414, 'ruRU', 'Гол!', 'Заберитесь в \"Буканьер Трюмных Вод\" и забейте победный гол, запустив футбомбный мяч между двумя дымоходами за воротами соперника.', 'Все зависит от тебя, $gприятель:подруга;. Ты $gистребил:истребила; акул Хитрой Шестеренки, так что осталось забить победный гол.$B$B<Тренер наклоняется к вашему уху и переходит на шепот.>$B$BТолько между нами, нужно все сделать красиво. Ты $gдолжен:должна; не просто забить гол... Хочу, чтобы футбомбный мяч пролетел за ворота между дымоходами соперника!$B$BЯ немного переделал мяч, чтоб сделать его помощнее.$B$BА теперь отправляйся и не заставляй меня за тебя краснеть!', '', '', '', '', '', 'Вернитесь к тренеру Проверяку на площадку Каджаро на Кезане.', 19865);
INSERT INTO `quest_template_locale` VALUES (28415, 'ruRU', 'Дружеская пирушка', 'Соберите 7 огнежуков.', 'Нужно приступать к действиям. Винки и Гор\'теш постоянно дерутся друг с другом, поэтому я хотел устроить для них церемонию примирения. Все складывалось удачно, пока...$b$bНу, ты знаешь, что случилось.$b$bЯ даже достал выпивку!$b$bВинки любит огнежуков. Он гоняется за ними почти каждую ночь. Может быть, он туда пошел?$b$bОгнежуки водятся на западе и на севере, там же, где и лава. Принеси мне семь жучков, да поторопись!$b$bА то еще и Гор\'теш уйдет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28416, 'ruRU', 'Настигающая кара', 'Уничтожьте 5 взращивателей из клана Черной горы и 5 огнечешуйчатых дракончиков.', '$n... это ты? Я уж думал, что ты $gпогиб:погибла;, как и все остальные!$b$bОднако ты всегда $gбыл:была; сильнее прочих, как тогда в Красногорье.$b$bНаша битва не окончена, $n. Однажды они уже покусились на нашу родину. Я здесь, чтобы этого не случилось вновь.$b$bЕсли твой боевой запал так же силен, как и в былые дни, бейся со мной плечом к плечу. Для начала можешь отправиться в Ясельные холмы и уничтожить взращивателей маленьких дракончиков вместе с детенышами черного дракона, находящимися под их опекой.$b$bДавай тряхнем стариной.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28417, 'ruRU', 'Безвинные создания', 'Освободите красного дракончика, зеленого дракончика, синего дракончика и бронзового дракончика.', 'Орки Черной горы из Пылающих степей служат темному повелителю, который проводит изощренные эксперименты над живыми созданиями, превращая их в полчище чудовищ. Многие из подопытных существ были осквернены своим создателем, однако же, некоторые из них сохранили внутреннюю чистоту.$b$bВ Ясельных холмах к югу отсюда орки приковывают к земле детенышей дракона, чтобы подготовить тех к последующим опытам. Я не потерплю подобного издевательства. Сбрось с них оковы и приведи детенышей ко мне... в безопасное место.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28418, 'ruRU', 'Настигающая кара', 'Уничтожьте 5 взращивателей из клана Черной горы и 5 огнечешуйчатых дракончиков.', 'Я родом из орков Черной горы. Большую часть своей юности я провел в пределах этой горы.$b$b<Ариок сдвигается к северу, по направлению к Черной горе.>$b$bИ все же, несмотря на то, что я разделяю их обличье, мне чужды орочьи убеждения. Мне $gнужен союзник, который смог:нужна союзница, которая смогла; бы помочь отразить их нападение. Ступай на юг, к Ясельным холмам, и истреби взращивателей маленьких дракончиков вместе с детенышами черного дракона, находящимися под их опекой. Докажи мне, что ты $gготов:готова; к войне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28419, 'ruRU', 'Запасаемся', 'Добудьте 5 бритвенно-острых жал скорпида.', 'Если мы намерены тягаться с кланом Черной горы, то нам нужно разработать план военных действий. Мой отец уже подготовил подобный план, так что пришло время действовать.$b$bМне потребуются жала скорпидов... самые острые, что сможешь найти. Скорпиды обитают на всей территории степей, но больше всего их можно найти в ущелье на западе.$b$bНе спрашивай, зачем они мне. Скоро все узнаешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28420, 'ruRU', 'Планы на будущее', 'Добудьте 11 шкур пепельного ворга.', 'Согласно плану моего отца нам потребуется множество шкур воргов. Не важно, в каком они будут состоянии: изорванные, обгоревшие или запятнанные кровью. Нам подойдут любые и в большом количестве.$b$bПожалуй, неплохо будет их для начала немного истрепать.$b$bВорги обитают к востоку и к западу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28421, 'ruRU', 'Сборщик грязи', 'Соберите 9 кучек насыщенной обсидианом грязи.', 'Надеюсь, ты не боишься испачкаться. Судя по твоему виду, это действительно так.$b$bК северу отсюда на краю лавы лежат кучи темной грязи. Она мне нужна.$b$bЛучше не задавай лишних вопросов и просто сосредоточься на задании, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28422, 'ruRU', 'Песок, сидр и сфера', 'Переговорите с Горзиеки Дикоглазом вблизи Алтаря Бурь.', 'Мой отец ждет нас на востоке. Однако перед выходом нам нужно собрать еще немного припасов. Для этого тебе придется поговорить с чернокнижником по имени Горзиеки Дикоглаз.$b$bЕго можно встретить на северо-западе вблизи Алтаря Бурь. Попроси его выручить нас. И еще передай ему, что нам нужен песок, сидр и сфера.$b$bОн поймет, о чем идет речь.', '', '', '', '', '', 'Поговорите с Горзиеки Дикоглазом у Алтаря Бурь в Пылающих степях.', 25549);
INSERT INTO `quest_template_locale` VALUES (28423, 'ruRU', 'Лучшие вещи – это к чернокнижникам', 'Добудьте горсть сонного порошка, кувшин прокисшего сидра и сферу из прозрачного стекла.', 'Ариок сказал, что ему нужны припасы? У меня куча припасов! Проблема в том, что они хранятся у меня дома, откуда меня выдворили чернокнижники и не пускают обратно.$b$b<Горзиеки оценивающе смотрит на вас.>$b$bВот ты, наверное, сможешь туда пробраться. Направляйся на север и прихвати оттуда немного сонного песку, прокисшего сидра и сферу из прозрачного стекла. Уверен, это то, что он хочет.$b$bАх да, и если ты мимоходом укокошишь несколько тамошних орков, я не сильно расстроюсь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28424, 'ruRU', 'Развеять мрак', 'Ликвидируйте Нер\'гоша Мрака.', 'Нер\'гош Мрак – предводитель чернокнижников к северу отсюда; именно он вышвырнул меня из дому, когда в эти края пришли орки Черной горы.$b$bЕсли мне когда-нибудь суждено вернуться к Алтарю, то следует вначале избавиться от Нер\'гоша.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28425, 'ruRU', 'Возвращение к Ариоку', 'Отнесите припасы чернокнижника Ариоку в Лагерь Пламени Звезд, что в Пылающих степях.', 'Думаю, пока это все. Когда наберусь смелости, пойду сам разберусь с остальными чернокнижниками.$b$bНе забудь забрать припасы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28426, 'ruRU', 'Узкоклинье – сердце Пылающих степей', 'Убейте 15 орков Черной горы по пути в Узкоклинье.', 'Мы направляемся в Узкоклинье, лежащее прямо в центре степей. Там мы повстречаемся с моим отцом и братством Тория.$b$bТы уже $gзнаком:знакома; с братством? Это дворфы из клана Черного Железа, уже не раз выручавшие меня в беде. Теперь нам снова нужна их помощь.$b$bНаш путь проходит мимо Загона Черного Зуба. Ты не возражаешь, если по пути убьем парочку орков? А то мне что-то становится неуютно в этом лагере.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28427, 'ruRU', 'Иголка в стане врага', 'Поговорите с Телароном Крутоиглом в Узкоклинье, что находится в Пылающих степях.', 'Лок\'тар, |3-6($c). Я Эйтригг из Серебряного Авангарда... а ранее – из стражей чести вождя. А еще раньше – из орков Черной горы.$b$bПолагаю, мой сын поведал тебе наш план, не так ли? Может быть, это к лучшему.$b$bНа следующем этапе от тебя потребуется определенная гибкость. Поговори с Телароном Крутоиглом, городским портным. Я уже передал ему добытые тобой шкуры и грязь. Ему нужно снять с тебя мерку.$b$bТы правильно $gпонял:поняла:r;, |3-6($r): тебе предстоит пойти в стан врага.', '', '', '', '', '', 'Поговорите с Телароном Крутоиглом в Узкоклинье, что находится в Пылающих степях.', 25549);
INSERT INTO `quest_template_locale` VALUES (28428, 'ruRU', 'Идеальный костюм', 'Возьмите необходимое количество материалов с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.', 'Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в орка. Вражеская армия в основном состоит из орков, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно. Увидишь, как Теларон тебя нарядит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28429, 'ruRU', 'Идеальный костюм', 'Возьмите необходимое количество материалов с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.', 'Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в огра. Огры из клана Огненного Чрева всегда работали на клан Черной горы, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно. Увидишь, как Теларон тебя нарядит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28431, 'ruRU', 'Идеальный костюм', 'Возьмите необходимое количество материалов с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.', 'Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в тролля. Тролли из племени Тлеющего Терновника всегда были подельниками орков Черной горы, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно. Увидишь, как Теларон тебя нарядит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28432, 'ruRU', 'Поход в Загон Черного Зуба', 'Поговорите с интендантом Каошином в Загоне Черного Зуба, расположенном в Пылающих степях.', 'Уверенный внешний вид – залог успеха в разведке. Просто веди себя как $gсвой:своя;, когда прибудешь на место, и все будет в порядке.$b$bТвоим связным в Загоне Черного Зуба станет орк по имени интендант Каошин. Он не знает, что ты шпион, так что не веди себя опрометчиво. Делай все, что тебе скажет Каошин.$b$b<Эйтригг кладет тебе в руку маленький металлический предмет.>$b$bПомести передатчик в ухо. Я буду выходить на связь, чтобы ознакомить тебя с особыми инструкциями.$b$bУдачи, солдат.', '', '', '', '', '', 'Поговорите с интендантом Каошином в Загоне Черного Зуба, расположенном в Пылающих степях.', 25549);
INSERT INTO `quest_template_locale` VALUES (28433, 'ruRU', 'Солдатские будни', 'Хорошенько начистите 7 пар сапог орков из клана Черной горы.', 'Ладно! Те6е повезло, что нам сегодня не хватает рук. Иначе бы я сам тебя выпорол на неделю вперед, $gпарень:девчонка;.$b$bНужно почистить обувь офицеров и старшин. Она выставлена перед их хижинами.$b$bНачисти так, чтобы та заблестела, рубака! Живо за дело!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28434, 'ruRU', 'Стратегические цели', 'Уколите бритвенно-острым жалом скорпида вудуиста Тимана, находящегося на вершине Башни Пепла, заводчицу воргов Отану в загоне воргов и Горлопа, которого можно найти вблизи озер лавы.', '<Вы слышите непонятный шум в ухе.>$n, прием! Говорит Эйтригг.$b$bК нам поступили последние данные разведки относительно твоего следующего задания. Нужно ликвидировать три цели. Объект номер один – вудуист Тиман, стоящий на вершине Башни Пепла. Заводчица воргов Отана стоит посреди центрального загона воргов. Наконец, Горлоп находится рядом с озерами лавы на юге.$b$bЖала скорпидов, собранные тобой ранее, спрятаны среди твоих пожитков. Улучи удачный момент, чтобы воспользоваться жалами.', '', 'Пришла пора пустить в дело припасенные жала.', 'Эйтригг', 'Молодец.', 'Эйтригг', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28435, 'ruRU', 'Рог призывателя кодо', 'Воспользуйтесь рогом призывателей, чтобы вернуть 7 боевых кодо Черной горы в лагерь. Если кодо заартачатся, сражайтесь с ними, пока те не станут послушными.', 'Итак, у меня для тебя есть действительно важное задание. От тебя потребуется переправить кодо с пастбищ на юг. Генерал Торг\'изог сказал, что скоро мы выходим в Красногорье, и так кодо не будут нас обременять в пути.$b$bБудь $gвнимателен:внимательна;! Порой кодо начинают своевольничать, тогда их нужно немного подстегнуть, чтобы поставить на место.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28436, 'ruRU', 'Заберем рог себе', 'Доставьте рог призывателей Эйтриггу в Узкоклинье, что находится в Пылающих степях.', '$n, прием, это Эйтригг. Ты мудро $gпоступил:поступила;, оставив у себя этот рог. Уверен, мы найдем ему применение.$b$bМеня несколько взволновало известие Каошина о том, что орки собираются напасть на Красногорье. Мы знали, что атака неизбежна, но на несколько дней запоздали с приготовлениями к бою.$b$bВозвращайся ко мне вместе с рогом. Переговорим, когда вернешься в Узкоклинье. Только не повреди шпионский наряд. Твоя разведывательная миссия еще не окончена.', '', 'Рог вроде этого подействует не только на кодо…', 'Эйтригг', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28437, 'ruRU', 'Генерал Торг\'изог', 'Поговорите с генералом Торг\'изогом.', 'Пусть Каошин и оказался полезнее, чем я думал, больше от него ничего не добьешься. Настало время поговорить с генералом. Считаю, что ты к этому достаточно $gготов:готова;. Генерал Торг\'изог – один из членов \"большой тройки\", командующей войсками в Пылающих степях. Он руководит солдатами из крепости Черной горы, что находится к северо-западу отсюда. Надень свой костюм и иди к нему. Попытайся втереться к нему в доверие. Я буду на связи, если нам еще что-то понадобится.', '', '', '', '', '', 'Доложите о своем прибытии генералу Торг\'изогу в крепости Черной горы, что находится в Пылающих степях.', 25549);
INSERT INTO `quest_template_locale` VALUES (28438, 'ruRU', 'Испытание магмой', 'Поговорите с Виртлом Грызжемулем и попросите его выпустить повелителя магмы Колоба. Затем победите повелителя магмы Колоба в бою.', 'Я знаю, как можно воспользоваться ситуацией. Гоблины-наемники приволокли огненного элементаля-переростка в мою крепость в качестве \"подарка\" за то, что их наняли. И что прикажешь с ним делать – в Пылающих-то степях?! Это же все равно что принести на пляж ведро песка!$b$bЕсли ищешь работенку, то придется зарекомендовать себя. Поговори с тем гоблином и вызови его элементаля на бой. Победитель заслужит мое уважение и окупит мое драгоценное время.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28439, 'ruRU', 'Я – закон и наказание', 'Примените дисциплинирующую дубинку Черной горы на 20 воинах на Полях Славы. Если какой-то солдат раскусит, что вы не орк, забейте его до смерти.', 'Давно искал такого хорошего и сильного солдата как ты. Мне нужен кто-то для поддержания дисциплины в армии.$b$bПеред крепостью находятся орки, огры и тролли, готовящиеся к нападению на Красногорье. За их дисциплину отвечают старшины, но и твоя помощь пригодится.$b$bВозьми-ка эту дубину и проучи парочку моих солдат. Мне безразлично, отлынивают ли они от службы или стоят по струнке. Просто побей их. Хочу, чтобы они были твердыми, собранными и исполнительными.$b$bЗа дело!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28440, 'ruRU', 'Злоупотребление полномочиями', 'Перебейте 5 старшин Черной горы при помощи дисциплинирующей дубинки Черной горы. Старайтесь убивать их быстро, пока те вас не раскусили.', '$n, прием! Эйтригг на связи.$b$bПохоже, ты $gвтерся:втерлась; в доверие к Торг\'изогу, и он поручил тебе следить за дисциплиной в армии. Нам это на руку.$b$bНужно будет убрать его старшин. Их можно встретить разъезжающими верхом на волке за стенами крепости Черной горы на Полях Славы. Дубась их, пока те не испустят дух. Действуй стремительно, потому что они могут раскусить тебя в этом облачении. Бей молниеносно и безжалостно, $n.', '', 'Пора прикончить старшин.', 'Эйтригг', 'Дело сделано. И, кстати, неплохо.', 'Эйтригг', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28441, 'ruRU', 'На сегодня хватит крови', 'Вернитесь к Эйтриггу в Узкоклинье.', 'Торг\'изог с кланом Черной горы больше не представляет для нас интереса. Давай перейдем к следующей фазе операции.$b$bКогда закончишь свои дела в крепости, возвращайся в Узкоклинье.', '', 'Возвращайся в Узкоклинье. Мы скоро выходим.', 'Эйтригг', '', '', 'Переговорите с Эйтриггом в Узкоклинье, что находится в Пылающих степях.', 25549);
INSERT INTO `quest_template_locale` VALUES (28442, 'ruRU', 'Пламенеющий Стяг', 'Переговорите с Киблером на Пламенеющем Стяге в Пылающих степях.', 'Наши дела в Узкоклинье успешно подошли к концу. И в этом, во многом, твоя заслуга. Сейчас нам предстоит направиться на северо-восток к Пламенеющему Стягу.$b$bЭто место находится в скалах за Руинами Тауриссана. Оно станет нашим опорным пунктом для реализации финальной части плана.$b$bЯ со своим сыном Ариоком станем твоими спутниками в дороге.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28443, 'ruRU', 'Почерневший пепел', 'Соберите 9 кучек обсидианового пепла.', 'Перед тем как разгромить остатки армии орков Черной горы, хочу, чтобы ты $gсобрал:собрала; для меня еще кое-что. Если мы хотим чего-то добиться, то надо все делать правильно и хорошенько подготовиться к операции.$b$bМне нужен пепел, $n. И не просто пепел, а пепел больших обсидиановых элементалей, встречающихся в долинах к юго-востоку отсюда. Он чернее черного, что нам и требуется для твоего следующего переоблачения.$b$bНе бойся, у тебя уже есть одеяние. Это пойдет кое-кому... кое-ЧЕМУ другому.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28444, 'ruRU', 'Присмиревшие демоны', 'Соберите тела 18 поверженных демонов огня.', 'Лавовые потоки к югу отсюда – пристанище демонов огня, обживших эти степи. Ситуация в армии орков Черной горы такова, что мы, проявив надлежающую осторожность, вполне сможем подкинуть парочку демонов в их тыл и как следует повеселиться.$b$bДоставь мне тела нескольких демонов огня. Этих существ можно запросто воскресить, чтобы затем использовать по собственному усмотрению.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28445, 'ruRU', 'Аппетитная туша ворга', 'Воспользуйтесь свежевателем воргов, чтобы добыть из поверженных огромных пепельных воргов вырезку из ворга в количестве 40 штук.', 'Нам понадобится свежее мясо, так что тебе придется поохотиться на воргов. Твоя цель – ворги, обитающие по эту сторону степей.$b$b<Эйтригг достает длинный нож и передает его тебе.>$b$bОхоться на огромных пепельных воргов. Когда разделаешься с ними, воспользуйся этим ножом, чтобы освежевать трупы и содрать с них самые сочные куски. Ворги водятся по всей территории степей, а ближайшая к нам стая обитает к юго-востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28446, 'ruRU', 'Кровавый поход', 'Убейте 25 черных драконоидов или черных драконид.', 'У меня что-то ноги затекли. Может, пройдемся, $n?$b$bНам предстоит прогулка вокруг скалы Молота Ужаса. Хочу разведать обстановку в армии орков Черной горы до того, как мы выступим, а еще по дороге прикончить несколько их союзников.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28447, 'ruRU', 'Драконий авангард', 'Ликвидируйте Минифа, укротительницу драконов Акуми, Терромата Опаленного и Тугнара Кровобрюха.', 'Орки Черной горы не приходят в одиночку. Ты уже $gслышал:слышала; о союзных им ограх из клана Огненного Чрева и троллях из племени Тлеющего Терновника. К несчастью для нас, они привлекли на свою сторону еще и род Черных драконов.$b$bОрки с драконами уже выслали вперед своих лучших бойцов, чтобы защитить ключевые точки сбора, отмеченные драконьим черепом на шесте. Нужно обнаружить точки сбора, охраняемые авангардом, до начала битвы. Приступим?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28448, 'ruRU', 'Сделка с драконом', 'Доставьте спасенных дракончиков Акрайду к Скользкой скале, что в Пылающих степях.', 'Давай сделаем еще один привал, пока мы обходим скалу Молота Ужаса. На самом деле, этот привал крайне важен для успеха всего плана.$b$bПомнишь дракончиков, освобожденных нами на Ясельных холмах? Все это время я присматривал за ними, но нужно найти кого-то, кто лучше позаботится об этих животных. Новый друг ждет нас у Скользкой скалы, расположенной к северо-востоку от скалы Молота Ужаса.$b$bЕго зовут Акрайд, и он может стать залогом нашей победы в грядущем сражении.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28449, 'ruRU', 'Расстановка фигур', 'Вернитесь к Эйтриггу, находящемуся на Пламенеющем Стяге в Пылающих степях.', '<Ты слышишь треск в ухе.>$b$b$n, прием! Похоже, что вы с Ариоком закончили подготовительные действия. Я тоже доделал все приготовления.$b$bВозвращайся на Пламенеющий Стяг. Я подготовил несколько посылок для большой тройки: Торг\'изога, Неерелака и Кси\'луна. Ты уже $gпересекался:пересекалась; с генералом Торг\'изогом. Теперь тебе представилась возможность познакомиться с оставшимися двумя лидерами.$b$bЗатем мы их ликвидируем.', '', 'Возвращайся в Пламенеющий Стяг. Передашь для меня пару посылок.', 'Эйтригг', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28450, 'ruRU', 'Посылка для Торг\'изога', 'Воспользуйтесь маскировочным костюмом пособника орков Черной горы, чтобы отнести вырезку, маринованную в прокисшем сидре, генералу Торг\'изогу, находящемуся в Очаге Огненного Чрева в Пылающих степях. Обратитесь к Эйтриггу, если вам нужен новый костюм.', 'Генерал Торг\'изог находится среди огров в Очаге Огненного Чрева, пещере на западном краю скалы Молота Ужаса. Доставь эту посылку генералу и его ограм-приспешникам.$b$bВ ней находится вырезка из ворга, маринованная в прокисшем сидре, который мы добыли на Алтаре Бурь.$b$bНа твоем месте я бы не стал дегустировать это мясо.$b$bОтнеси его генералу Торг\'изогу. Он раздаст его своим подчиненным, а может и сам отведает.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28451, 'ruRU', 'Посылка для Неералака', 'Наденьте свой маскировочный костюм пособника орков Черной горы, чтобы проникнуть в Лабиринт Черепа и убедить повелителя драконов Неералака забрать от вас ящик со спящими демонами огня. Обратитесь к Эйтриггу, если вам нужен новый костюм.', 'Чернокнижники из клана Черной горы часто оттачивают свое мастерство в Лабиринте Черепа, пещере в восточной части скалы Молота Ужаса. В настоящий момент их предводитель Кси\'лун находится в отлучке, поэтому в пещере заправляет другой член большой тройки – повелитель драконов Неералак. Он специализируется в драконах, а не в некромантии.$b$bЯ использовал снотворный песок на пойманных тобой демонах огня. Попробуй убедить Неералака, что это бесы чернокнижников, а не демоны огня. Когда демоны проснутся, то будут очень недовольны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28452, 'ruRU', 'Посылка для Кси\'луна', 'Наденьте свой маскировочный костюм пособника орков Черной горы и доставьте сферу из прозрачного стекла верховному чернокнижнику Кси\'луну на вершине скалы Молота Ужаса, расположенной в Пылающих степях. Обратитесь к Эйтриггу, если вам нужен новый костюм.', 'Разведка доложила нам о том, что верховный чернокнижник Кси\'лун, последний член большой тройки, находится в пещере на вершине скалы Молота Ужаса и готовится к своему выходу на сцену.$b$bОн ждет посылку – сферу власти, с помощью которого он сможет провести могущественный ритуал призыва. Передай-ка ему вот это.$b$b<Эйтригг передает вам стеклянный шар.>$b$bЭто прозрачная ледяная сфера, которую ты $gдостал:достала; в Алтаре Бурь. Она абсолютно бесполезна. Передай сферу Кси\'луну и молись, чтобы он не заметил подмены.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28453, 'ruRU', 'Последнее затишье перед битвой', 'Поговорите с Эйтриггом на Пламенеющем Стяге в Пылающих степях.', 'Прием, $n. Как слышно?$b$bБитва скоро начнется. Надеюсь, ты $gдоставил:доставила; все посылки.$b$bТы нам $gнужен:нужна; на Пламенеющем Стяге немедленно.', '', 'Поспеши в Пламенеющий Стяг. Скоро начнется битва.', 'Эйтригг', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28454, 'ruRU', 'Атака на скалу Молота Ужаса', 'Расправьтесь с 200 захватчиками из клана Черной горы. Воспользуйтесь рогом призывателя для вызова нового верхового животного в случае гибели прежнего.', 'Вот и пробил час расплаты, $n. Прискорбный, но неотвратимый день, когда орки Черной горы получат воздаяние по заслугам. Сегодня мы пожнем плоды своих трудов.$b$bСледуй за мной. Обратимся к Акрайду и напомним ему о том неоплаченном долге. Затем мы пресечем нападение на Красногорье.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28455, 'ruRU', 'Слава в гуще хаоса', 'Ликвидируйте генерала Торг\'изога, повелителя драконов Неералака и верховного мага Кси\'луна.', 'Вам с моим сыном нужно вернуться назад на гору. Три орка избежало гибели, но мы не остановимся, пока не покончим с ними.$b$bТы правильно $gпонял:поняла;, я имею в виду большую тройку.$b$bГенерал Торг\'изог скрывается в Очаге Огненного Чрева, а повелитель драконов Неералак трусливо прячется в пещере на вершины скалы. Кси\'лун затаился в Лабиринте Черепа и строит козни со своими собратьями-чернокнижниками.$b$bРасквитайся с ними, $n. Пусть падшие предводители орков канут в лету.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28456, 'ruRU', 'Боевые трофеи', 'Осмотрите ящик с остатками припасов на Пламенеющем Стяге в Пылающих степях.', 'Пусть орки Черной горы все еще спускаются с пика вниз, полагаю, что они больше не представляют угрозы для мирных жителей Красногорья. Это ваша с Ариоком заслуга.$b$bМне кажется, мы проявили смекалку во время операции в Пылающих степях: собранные запасы чернокнижников нам очень помогли, а обсидиановый пепел послужил камуфляжем для дракона.$b$bОднако ж, у нас остались кое-какие припасы. Пока ты еще не $gпокинул:покинула; степи, можешь забрать все, что захочешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28457, 'ruRU', 'Опасный союз', 'Убейте 6 огнестражей-разрушителей и завладейте планами нападения генерала Кузни Гнева в Западном гарнизоне, что в глубинах Черной горы.', 'Клан Изувеченной Длани считает, что дворфы Черного Железа объединились с Сумеречным Молотом. Нет никаких сомнений, что они готовят совместное нападение со стороны Черной горы. Мы не можем этого допустить.$b$bОтправляйся в глубины Черной горы, найди в Западном гарнизоне генерала Кузню Гнева и завладей хранящимися у него планами нападения Сумеречного Молота. И уничтожь элементалей, которые оказывают поддержку его войскам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28458, 'ruRU', 'Гримуар пироманта', 'Убейте 6 сумеречных эмиссаров и завладейте гримуаром пироманта Зерно Мудрости в святилище Тауриссана, что в глубинах Черной горы.', 'Союз сил Черного Железа и Сумеречного Молота набирает силу. Пиромант Зерно Мудрости играет важную роль в руководстве силами Сумеречного Молота. Если бы мы смогли получить его гримуар, я бы смог придумать контрзаклинания или другие способны ослабления их стихийной магии.$b$bОтправляйся в глубины Черной горы, найди святилище Тауриссана и завладей гримуаром. Не щади Зерно Мудрости и его пособников.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28459, 'ruRU', 'Связывающие камни', 'Найдите 6 стихийных связывающих камней в Глубинах Черной горы. Камни можно найти в Тенегорне, Жилом квартале, святилище Тауриссана, Западном и Восточном гарнизонах.', 'Клану Изувеченной Длани стало известно об объединении сил Сумеречного Молота и дворфов Черного Железа в Глубинах Черной горы. У нас есть возможность нанести удар по нашим врагам и усилить свои собственные позиции, $n.$b$bСлужители культа Сумеречного Молота разместили некоторое количество стихийных связывающих камней в Тенегорне, Жилом квартале, святилище Тауриссана, Западном и Восточном гарнизонах. Найди и собери эти камни!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28460, 'ruRU', 'Угроза со стороны Зимней Спячки', 'Убейте 15 любых фурболгов из племени Зимней Спячки возле источников Ледяного огня.', 'В Зимних Ключах я изучаю источники Ледяного огня. И заметила, что у воды здесь какие-то... странные свойства. Мне пока не удалось определить источник изменения, да и, по правде говоря, в последнее время у меня возникли кое-какие сложности из-за фурболгов племени Зимней Спячки.$B$BИх, кажется, тянет к источникам – так же, как и меня. Они яростно защищают воду и не подпускают меня близко к двум большим ключам на севере.$B$BЯ хотела бы продолжить свои изыскания. Ты не поможешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28461, 'ruRU', 'Создания повелителя големов', 'Добудьте 5 стихийных модулей, убив големов на фабрике в глубинах Черной горы, и найдите чертежи стихийных големов.', 'Клану Изувеченной Длани стали известны тревожные факты, касающиеся Глубин Черной горы. Похоже, что с кланом Сумеречного Молота сотрудничает инженер Черной горы, Аргелмах, который делает для них големов, управляемых элементалями. Для наших врагов эти големы могут стать огромным преимуществом.$b$bТы $gдолжен:должна; предотвратить это, $n. Найди в глубинах Черной горы фабрику, похить чертежи, которые он использует для производства големов, и стихийные модули, которые нужны для управления ими.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28463, 'ruRU', 'Армия Черного Железа', 'Воспользуйтесь ядом быстрого действия и отравите 6 хлебных пайков в Западном или Восточном гарнизонах, что в Глубинах Черной горы.', 'Будучи членом клана Изувеченной Длани, ты знаешь, что наблюдать за врагами Орды – это наша работа. Мы узнали, что дворфы Черного Железа и их новые союзники, служители культа Сумеречного Молота, готовятся к атаке.$b$bТы $gдолжен:должна; помочь разобраться с этой угрозой до того, как армия Черного Железа будет готова к выходу. Возьми этот яд и отрави их запасы хлеба в Глубинах Черной горы.$b$bВ Западном и Восточном гарнизонах, которые находятся в Глубинах Черной горы, хранится провизия почти для всей армии Черного Железа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28464, 'ruRU', 'Поддавшиеся порче', 'Найдите котел Зимней Спячки в северном лагере племени Зимней Спячки.', 'Фурболги Зимней Спячки не могли стать агрессивными без причины. И я должна понять, чем вызвано такое поведение!$B$BНа севере находится их лагерь: там фурболги варят что-то в большом котле и никого к нему не подпускают. Если их агрессия вызвана именно этим варевом, то я должна изучить его.$B$BНайди этот котел и принеси мне его содержимое!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28465, 'ruRU', 'Рабы Повелителя Огня', 'Воспользуйтесь тотемом свободы, чтобы освободить сущности 6 огнестражей, огнестражей-разрушителей или пылающих огнестражей в Глубинах Черной горы.', 'Служители культа Сумеречного Молота и дворфы Черного Железа объединяют свои силы в Глубинах Черной горы. Их войска поддерживают огненные элементали, которые служат Рагнаросу Повелителю Огня.$b$bЕсли мы разрушим узы, связывающие элементалей с повелителем, то тем самым мы и ослабим вражеские войска, и отдадим дань уважения стихиям. Возьми этот тотем и воспользуйся им, чтобы освободить порабощенных огнестражей. После этого они смогут вернуться в свое естественное состояние.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28466, 'ruRU', 'Оружие тьмы', 'Отправляйтесь в глубины Черной горы и добудьте у дворфов клана Ярости Горна 5 единиц усиленного стихиями оружия, а затем разбейте оружие о Черную наковальню, которая находится в Тенегорне.', 'Наши враги давно уже обосновались в глубинах Черной горы, а теперь клану Изувеченной Длани удалось узнать, что дворфы Черного Железа и клан Сумеречного Молота объединяют свои силы. Используя знания клана Сумеречного Молота, дворфы заряжают свое оружие стихийными силами. И теперь войска клана Ярости Горна вооружены этим грозным новым оружием.$b$bОтправляйся в глубины Черной горы, добудь у дворфов клана Ярости Горна это оружие и разбей его о Черную наковальню, которая находится в самом сердце Тенегорна.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28467, 'ruRU', 'Таинственная слизь', 'Вернитесь к Донове и сообщите ей о своих находках.', 'В котле находится зловонная, вязкая зеленоватая жидкость. Что бы это ни было, вряд ли что-то хорошее.$B$BЛучше всего взять образец этой жидкости и отнести его Донове.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28469, 'ruRU', 'Гонцы Зимней Спячки', 'Найдите и победите гонца из племени Зимней Спячки и заберите у него ящик Зимней Спячки.', 'Очень интересно, $n...$b$bЕсли эту ядовитую субстанцию смешать с водой из горячих ключей, она потеряет свою токсичность, и остается лишь способность временно воздействовать на тех, кто такую смесь употребляет. Наверное, из-за этого племя Зимней Спячки и защищает источники столь яростно: они необходимы фурболгам для очистки огненной воды.$b$bМы должны положить этому конец: прекратить контакты между племенами Зимней Спячки и Мертвого Леса. Группа гонцов курсирует между поселением Зимней Спячки и Оскверненным лесом. Найди их, убей и забери то, что у них будет с собой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28470, 'ruRU', 'Верховный вождь племени Зимней Спячки', 'Убейте верховного вождя племени Зимней Спячки.', 'Фурболги из племени Зимней Спячки никогда не отличались агрессивностью, и резкая перемена в их поведении заставляет предположить, что они действуют по приказу вождя. Скорее всего, исцелить их уже не получится, но, возможно, удастся остановить дальнейший пагубный процесс, если мы ликвидируем их вождя.$B$BИди на восток. Там, в восточной части заставы Древобрюхов, ты найдешь верховного вождя племени Зимней Спячки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28471, 'ruRU', 'Последний фрагмент мозаики', 'Отнесите неразборчиво исписанный журнал Донове Снегоноре в Зимние Ключи.', 'Записи, которые вы нашли у верховного вождя, кажутся обширными, но просмотрев пару страниц, вы понимаете, что не можете прочитать написанное. Все заметки написаны так коряво, что вы сомневаетесь, что кто-либо сможет что-то понять в них.$b$bНо, может быть, Донова сможет?..', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28472, 'ruRU', 'Слова верховного вождя', 'Отнесите неразборчиво исписанный журнал Келеку Стражу Неба, который находится у озера Кел\'Терил.', 'Племя Зимней Спячки больше не представляет угрозы, но если ты все-таки хочешь узнать, почему фурболги варят и употребляют эту странную огненную воду, поговори с Келеком Стражем Неба.$B$BКелек – друид; когда-то он вместе с Изумрудным Кругом очищал Оскверненный лес, а теперь поселился здесь, чтобы изучать местные руины.$B$BСкорее всего, его можно найти на востоке, на берегу озера Кел\'Терил.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28473, 'ruRU', 'Оружие тьмы', 'Отправляйтесь в глубины Черной горы и добудьте у дворфов клана Ярости Горна 5 единиц усиленного стихиями оружия, а затем разбейте оружие о Черную наковальню, которая находится в Тенегорне.', 'Наши враги давно уже обосновались в глубинах Черной горы, а теперь клану Изувеченной Длани удалось узнать, что дворфы Черного Железа и клан Сумеречного Молота объединяют свои силы. Используя знания клана Сумеречного Молота, дворфы заряжают свое оружие стихийными силами. И теперь войска клана Ярости Горна вооружены этим грозным новым оружием.$b$bОтправляйся в глубины Черной горы, добудь у дворфов клана Ярости Горна это оружие и разбей его о Черную наковальню, которая находится в самом сердце Тенегорна.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28474, 'ruRU', 'Тайные планы Сумеречного Молота', 'Воспользуйтесь пылающим факелом, чтобы уничтожить 8 копий \"Догматов Сумеречного Молота\" в Жилом квартале Глубин Черной горы.', 'Сумеречный Молот приобретает все большее влияние в Глубинах Черной горы. Служители культа заключили союз с дворфами Черного Железа и пытаются убедить их в необходимости совместной атаки.$b$bМы должны уничтожить все орудия агитации Сумеречного Молота. Нужно свести к минимуму их влияние на дворфов Черного Железа.$b$bОтправляйся в Жилой квартал Глубин Черной горы, воспользуйся этим факелом и сожги книги, которые распространяют служители культа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28475, 'ruRU', 'Тайные планы Сумеречного Молота', 'Воспользуйтесь пылающим факелом, чтобы уничтожить 8 копий \"Догматов Сумеречного Молота\" в Жилом квартале Глубин Черной горы.', 'Служители культа Сумеречного Молота и дворфы Черного Железа укрепляют свой союз в Глубинах Черной горы и готовятся к совместной атаке.$b$bМы не должны этого допустить! Нужно уничтожить все предметы, при помощи которых эта секта воздействует на клан Черного Железа.$b$bОтправляйся в Жилой квартал Глубин Черной горы, воспользуйся этим факелом и сожги книги, которые распространяют служители культа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28476, 'ruRU', 'Тайные планы Сумеречного Молота', 'Воспользуйтесь пылающим факелом, чтобы уничтожить 8 копий \"Догматов Сумеречного Молота\" в Жилом квартале Глубин Черной горы.', 'Служители культа Сумеречного Молота и дворфы Черного Железа укрепляют свой союз в Глубинах Черной горы и готовятся к совместной атаке.$b$bМы должны действовать прежде, чем служителям культа удастся разжечь в дворфах Черного Железа жажду крови.$b$bОтправляйся в Жилой квартал Глубин Черной горы, воспользуйся этим факелом и сожги книги, которые распространяют служители культа.', '', '', '', '', '', 'Вернитесь к ясновидице Ливате на Аллею Мудрости, что в Оргриммаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (28477, 'ruRU', 'Тайные планы Сумеречного Молота', 'Воспользуйтесь пылающим факелом, чтобы уничтожить 8 копий \"Догматов Сумеречного Молота\" в Жилом квартале Глубин Черной горы.', 'Наши враги что-то замышляют против нас в Глубинах Черной горы. Служители культа Сумеречного Молота без конца проповедуют свои идеи, раздают дворфам Черного Железа свои книги и убеждают их, что пришло время атаковать. Если они смогут привлечь клан Черного Железа на свою сторону, то приобретут огромную силу. Мы должны положить конец этой агитации!$b$bОтправляйся в Жилой квартал Глубин Черной горы, воспользуйся этим факелом и сожги книги, которые распространяют служители культа!', '', '', '', '', '', 'Вернитесь к крадущемуся в тени Зуру на Аллею Духов, что в Оргриммаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (28478, 'ruRU', 'Тайные планы Сумеречного Молота', 'Воспользуйтесь пылающим факелом, чтобы уничтожить 8 копий \"Догматов Сумеречного Молота\" в Жилом квартале Глубин Черной горы.', 'Их хозяевам мало того, что случилось со всем миром! Служители культа изо всех сил настраивают наших врагов против нас, особенно в Глубинах Черной горы. У них есть целая группа посланников, которые пропагандируют необходимость объединения сил и совместной атаки.$b$bПора положить этому конец!$b$bОтправляйся в Жилой квартал Глубин Черной горы, воспользуйся этим факелом и сожги книги, которые распространяют служители культа!', '', '', '', '', '', 'Вернитесь к брату Сребросвяту в Гоблинские трущобы Оргриммара.', 19865);
INSERT INTO `quest_template_locale` VALUES (28479, 'ruRU', 'Руины Кел\'Терила', 'Поговорите с калдорайским духом в Зимних Ключах, у озера Кел\'Терил.', 'На берегу этого озера высокорожденные украли кристалл Зин-Малора. Этот кристалл был могущественным артефактом, который изменял магическую энергию самым непредсказуемым образом... но только самые достойные могли держать его в руках – все остальные погибали.$B$BДухи, которые здесь обитают, – это несколько поколений, порабощенных Зин-Малором. Кое-кто из них готов рассказать тебе о своей судьбе.$B$BЕсли хочешь узнать о Зин-Малоре, разыщи духа, который находится в центре озера...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28480, 'ruRU', 'Лейтенанты Тьмы', 'Убейте владыку скорпионов Намкара и верховного жреца Секмета.', 'Армия защитников Рамкахена тает на глазах под натиском бессмертных стражей Неферсета.$B$BЕдинственный способ справиться с ними – убить Темного фараона Неферсета.$B$BОднако перед тем как нанести ему смертельный удар, сперва надо устранить его лейтенантов.$B$BОтправляйся в тыл врага и уничтожь владыку скорпионов Намкара и верховного жреца Секмета. Только тогда мы сможем бросить вызов самому Темному фараону.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28482, 'ruRU', 'Подарок Суллы', 'Поговорите с Харрисоном Джонсом у Пропасти Пилигрима.', 'Джонси говорит, вам с ним надо попасть на вершину горы.$B$BПросто так вам не подняться: там столько этих солдат... больше, чем крокодилов в Вир\'наале.$B$BКое-кому из моих друзей удалось раздобыть пару вражеских машин. Так что артиллерией вы обеспечены, я уже договорился.$B$BИдите на север, поднимитесь по склону, и эти машины уже ждут вас там.$B$BУдачи, ребята!', '', '', '', '', '', 'Поговорите с Харрисоном Джонсом у Пропасти Пилигрима.', 25549);
INSERT INTO `quest_template_locale` VALUES (28483, 'ruRU', 'Истощение противника', 'Добудьте 10 знаков различия Неферсета.', 'Не буду врать тебе, $n. Нам предстоит очень серьезное испытание.$B$BКогда ты отправишься в тыл к неприятелю в город Неферсет, я хочу, чтобы ты $gсобрал:собрала; знаки различия всех мерзавцев, которых убьешь на своем пути.$B$BНаши ребята сильно воспрянут духом, когда узнают, что ты $gнанес:нанесла; врагу столь сокрушительный удар.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28484, 'ruRU', 'Суть дела', 'Соберите 12 бьющихся сердец йети.', 'Когда маг слишком долго сидит без работы, результатом часто бывают не очень хорошо продуманные планы действий. На этот раз меня попросили собрать внутренние органы различных монстров, они нужны, чтобы влить энергию в определенные типы контрольных стержней. Но я слишком слаб, чтобы самому охотиться на чудовищ – особенно на йети!$b$bМожет быть, если я пообещаю тебе награду, ты согласишься заняться этим вместо меня? Все, что от тебя требуется, – это отправиться на запад к пещерам йети и убивать йети. Вырывай сердца из их груди, пока они еще бьются, и приноси их мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28485, 'ruRU', 'Йетиан Царь Пещер', 'Добудьте витой рог Йетиана.', 'Долгие годы мы не трогали горных йети, которые живут в этих краях. И вот теперь наша безалаберность обернулась проблемой! Йетиан Царь Пещер вырос до таких размеров и стал так силен, что наша стража просто не может с ним справиться. И мы опасаемся, что если в поисках пищи он набредет на мельницу Таррен, то сожрет нас всех.$b$bСобери подходящую команду и разделайся с этим монстром. Он бродит к западу отсюда.$b$bПринеси мне один из его рогов, и я щедро награжу тебя.', '', 'Бич холма Дарроу.', 'Йетиан', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28486, 'ruRU', 'Гамбит Салхета', 'Сопроводите капитана рамкахенов-следопытов до горной вершины.', 'Город Неферсет защищен слишком хорошо, а вот о горе, рядом с которой он находится, этого не скажешь.$B$BЯ поговорил с капитаном следопытов – он готов взять небольшой отряд своих людей и с ними закрепиться на стратегически важной горной вершине.$B$BНо есть одно \"но\", $n. Его условие – чтобы ты $gотправился:отправилась; вместе с ними.$B$BОтряд должен быть совсем маленьким, иначе он раньше времени привлечет к себе внимание врага, но поверь мне... следопыты Рамкахена – очень серьезные бойцы. Вместе вас непременно ожидает успех.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28487, 'ruRU', 'Интимные проблемы Гумберта', 'Найдите меч Гумберта, шлем Гумберта и штаны Гумберта.', 'Это очень деликатная история. С чего же начать?$b$bВ общем, по просьбе Мелизары я отправился на запад, к пещерам йети, чтобы оценить исходящую от них угрозу. Вечерело, а мои доспехи были такими тяжелыми. Я снял их с себя и решил прогуляться. Ну да, я отправился, гм, на прогулку. А когда я вернулся, то обнаружил, что все мое снаряжение украдено! Наверняка это были йети. Я в этом уверен. Они взяли мои штаны, меч и шлем и скрылись в пещере. Верни мои вещи, и я награжу тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28488, 'ruRU', 'В подземных глубинах', 'Найдите огромную друзу рубиновых кристаллов.', 'Среди всех остальных драгоценных камней, спрятанных вне нашей досягаемости в Гремящих глубинах, встречаются огромные рубиновые кристаллы. В них заключена убийственная энергия.$b$bДостать их непросто, так как они очень хорошо охраняются. Но ты отличаешься храбростью и упорством. Думаю, тебе это под силу.$b$bКогда будешь в Гремящих глубинах, ищи обрывающиеся туннели. Если где и можно найти эти кристаллы, то только там. Когда найдешь гроздь таких кристаллов, возвращайся ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28489, 'ruRU', 'Сэндвичи с олениной', 'Достаньте 8 кусков оленины.', 'Ты $gпробовал:пробовала; когда-нибудь сэндвичи с олениной? Вот и я нет. А ведь они очень вкусные. Я думаю не только о еде, но и о бизнесе. Если моим клиентам хочется сэндвичей с олениной, то кто я такой, чтобы им отказывать?$b$bВозможно, ты думаешь: \"При чем же здесь я?\". А вот при чем, |3-6($c): мне нужна оленина! Принеси мне мясо горных оленей Хилсбрада, и я заплачу тебе за него. Неплохая сделка, не так ли?$b$bНу вот и иди. Больше всего оленей к западу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28490, 'ruRU', 'Воззвание к героям: Темные берега!', 'Встретьтесь с жрицей Дентарией в Лор\'данеле, что на Темных берегах.', 'По приказу его королевского высочества короля Андуина Ринна все годные к военной службе подданные Альянса должны явиться к жрице Дентарии в Лор\'данел, что на Темных берегах.$B$BНарод Лор\'данела взывает о вашей помощи в спасении уцелевших жителей Аубердина и борьбе против культа Сумеречного Молота! Поговорите с Веспристом, укротителем гиппогрифов из деревни Рут\'теран, что находится рядом с Дарнасом, и он отправит вас на Темные берега.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28491, 'ruRU', 'Не светляки, а огнежуки', 'Соберите 7 огнежуков.', 'Большинство моих земляков уже покинуло Пламенеющий Стяг. Видимо, им наскучили Пылающие степи.$b$bДа только не мне. Я всегда ищу причину не уходить отсюда, и огнежуки – очередной повод задержаться в Пылающих степях.$b$bДнем их можно встретить вблизи лавы. Ночью же, жуки летают практически повсюду.$b$bЕсли бы $gпоймал:поймала; для меня несколько штук, я бы тебя вознаградил по заслугам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28492, 'ruRU', 'Воззвание к героям: Ясеневый лес!', 'Явитесь к часовому Шейле в Укрытие Орендила, что на северо-западе Ясеневого леса.', 'По приказу его королевского высочества короля Андуина Ринна всем членам Альянса, способным держать в руках оружие, настоящим предписывается явиться к часовому Шейле в Укрытие Орендила, что на северо-западе Ясеневого леса. $B$BМы не можем больше мириться с агрессией Орды! Помогите изгнать захватчиков и сохранить неприкосновенность священного леса! Чтобы добраться до Ясеневого леса, следуйте на юг через Сумеречную долину на Темных берегах.$B$BВо славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28493, 'ruRU', 'Приказ вождя: в Ясеневый лес!', 'Явитесь к Кадраку на заставу Мор\'шан, что на границе между Северными степями и Ясеневым лесом.', 'Всем ордынцам, способным держать в руках оружие, настоящим предписывается явиться к Кадраку на заставу Мор\'шан, что на границе между Северными степями и Ясеневым лесом. Окажите помощь своему народу, изгоните ночных эльфов из нашего леса, чтобы его ресурсы послужили на благо Орде!$B$BЧтобы добраться до заставы Мор\'шан, следуйте по Золотому Пути на север от Перекрестка в Северных степях.$B$BИдите на зов судьбы!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28494, 'ruRU', 'Приказ вождя: Северные степи!', 'Доложите о своем прибытии Каргалу Боевому Шраму на Дальней заставе, что в Северных степях.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к Каргалу Боевому Шраму на Дальнюю заставу, что в Северных степях.$b$bВаша помощь нужна, чтобы помочь справиться со вторжением в Северные степи свинобразов и кентавров.$b$bЧтобы добраться до Дальней заставы, отправляйтесь на запад через разлив Строптивой, что в Дуротаре, а затем перейдите по мосту в Северные степи.$b$bСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28495, 'ruRU', 'Во имя спасения', 'Спасите 10 горных оленят.', 'Во имя Света! Мне нужна твоя помощь!$b$bПо пути в Хилсбрад я видела несколько очаровательных оленьих семейств. А когда я решила погладить одного из маленьких оленят, сверху спрыгнула голодная рысь и убила его. Я побежала на мельницу Таррен и поклялась сделать что-то для маленьких оленят. Несколько дней ушло на работу, но теперь я знаю, что делать, чтобы спасти их!$b$bВозьми этот жезл, отправляйся в поля к западу отсюда, и при помощи жезла влей силу в маленьких горных оленят. После этого они смогут постоять за себя!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28496, 'ruRU', 'Приказ вождя: Азшара!', 'Доложите о своем прибытии подрядчику Жаднюку у задних врат Оргриммара в Азшаре.', 'Всем годным к военной службе ордынцам приказано явиться к Аг\'тору Кровопалу к Задним вратам Оргриммара в Азшаре. Помогите Орде закрепиться в Азшаре и отбросить назад захватчиков Альянса.$B$BПокиньте Оргриммар через северные ворота, чтобы выйти к Задним вратам Оргриммара в Азшаре.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28497, 'ruRU', 'Огонь с высот', 'Убейте 100 солдат Шнотца, находясь на конфискованном орудии.', 'Сулла не шутил... Холм кишмя кишит вражескими солдатами!$B$BДавай-ка запрыгивай сюда и помечай для меня цели.$B$BПусть каждый выстрел будет в яблочко, $n! Нам нужно пробиться на эту высоту.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28498, 'ruRU', 'Секрет Нахома', 'Добудьте 8 обломков скрижалей с записями Атулхета.', 'О Нахоме есть древнее сказание, в котором говорится о том, как могучий пророк по имени Атулхет сдерживал бесчисленные полчища врагов, сосредотачивая силу самого солнца в этом самом храме.$B$BМногие полагают, что это всего лишь сказка, но эта сила... она сейчас вполне бы нам пригодилась.$B$BГнусные неферсеты разграбили гробницу Атулхета, забрали с собой все могущественные артефакты, какие нашли, и разбили скрижали, на которых были записаны его воспоминания.$B$BОтправляйся на Гробницы Предтеч к востоку отсюда и принеси все обломки, которые тебе удастся там найти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28499, 'ruRU', 'Наказать нарушителей', 'Убейте 10 неферсетов-захватчиков в Гробницах Предтеч.', 'Мы, жрецы Нахома, охраняем Гробницы Предтеч.$B$BС тех пор как неферсеты стали служить новым господам, они стали еретиками.$B$BРазграбляют священные могилы наших праотцов в поисках могущественных артефактов, попутно уничтожая бесценные реликвии.$B$BСтупай к захоронениям, что находятся к востоку отсюда, и покарай грабителей могил за их святотатственные деяния, иначе они присоединятся к своим собратьям, когда неферсеты атакуют Нахом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28500, 'ruRU', 'Шифр Кесета', 'Раздобудьте шифр Кесета.', '<Салхет в окружении жрецов некоторое время вчитывается в текст на скрижалях.>$B$BНу да, так и есть, $n. Атулхет создал в этом храме могучее оружие, но воспользоваться им можно, только если знать правильный шифр.$B$BСудя по всему, он хранится на Тропе Кесета. Нам остается лишь уповать на то, что грабители из Неферсета пока еще не добрались до него. В тех краях орудует предводитель налетчиков Хават – среди них всех, судя по слухам, он самый жестокий.$B$BОднако без подкрепления это, похоже, наша единственная надежда защитить Нахом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28501, 'ruRU', 'Защита Нахома', 'Поговорите с рамкахеном-сержантом и защитите Нахом.', 'Враги приближаются... и им нет числа.$B$BБольше подкрепления у нас не будет, поэтому остается надеяться, что мы сумеем остановить продвижение Неферсета своими силами.$B$BЕсли падет Нахом, следом за ним та же участь постигнет и Рамкахен.$B$BКогда будешь $gготов:готова;, ступай и поговори с одним из моих сержантов. Я помогу тебе командовать имеющимися в нашем распоряжении силами.', 'Защита Нахома', '', '', '', '', 'Вернитесь к Салхету в Нахом в Ульдуме.', 25549);
INSERT INTO `quest_template_locale` VALUES (28502, 'ruRU', 'Атаман разбойников', 'Убейте атамана Ихсенна.', 'Наш закон требует, чтобы тех, кто стоит за этим нападением, постигла жестокая кара.$B$BГлаварь этой шайки бандитов – некто атаман Ихсенн.$B$BТы найдешь его далеко на западе пустыни. Покарай Ихсенна за его преступления.', '', 'Свершите над ним правосудие, как он того заслуживает.', 'Атаман Ихсенн', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28503, 'ruRU', 'Воззвание к героям: Тысяча Игл!', 'Отправляйтесь к Кариссии Лунной Охотнице в Новый Таланаар, что на границе Фераласа и Тысячи Игл.', 'По приказу его высочества Короля Андуина Ринна, всем дееспособным воинам Альянса надлежит незамедлительно явиться к Кариссии Лунной Охотнице в Новый Таланаар на границе Фераласа и Тысячи Игл.$B$BЧасовым нужна ваша помощь, чтобы прогнать мародеров из клана Зловещего Тотема, что бесчинствуют в тамошних землях. Чтобы добраться до Нового Таланаара, идите на восточную окраину Фераласа, к границе с Тысячей Игл.$B$BВо имя славы и чести Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28504, 'ruRU', 'Приказ вождя: Тысяча Игл!', 'Отправляйтесь к Нице в Шестермуть на южную окраину Пылевых топей.', 'Всем дееспособным воинам Орды приказано незамедлительно явиться к Нице в Шестермуть, где армия Орды пытается сдержать натиск предателей из клана Зловещего Тотема, что бесчинствуют в тамошних землях.$B$BНице скажет, что делать, и обеспечит транспортом до линии фронта. Она ждет тебя на постоялом дворе в Шестермути, на южной окраине Пылевых топей.$B$BНе теряй времени даром! Судьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28505, 'ruRU', 'Битва за Андорал', 'Обратитесь к Гутруму Брату Грома, чтобы тот переправил вас в Андорал, расположенный в Западных Чумных землях. После этого переговорите с Тассарианом в Андорале.', 'Мне только что донесли пренеприятное известие, $gпарень:подруга;..$b$bГород Андорал попал в гущу противоборства между Отрекшимися, Альянсом и Плетью. Король Ринн положился на удачу и послал рыцаря смерти во главе своего воинства. Однако пригодится любое подкрепление..$b$bМне так не хочется расставаться с тобой, но тебя желают видеть в другом месте, $n. Обратись к Гутруму Брату Грома, что стоит снаружи. Он отправит тебя в Андорал с первым же грифоном.', '', '', '', '', '', 'Поговорите с Тассарианом в Андорале в Западных Чумных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (28506, 'ruRU', 'Диспозиция Грозовой Вершины', 'Посмотрите на позиции Грозовой Вершины.', 'Найденные тобой планы наводят на интересные мысли, $n. Вот уже больше месяца, как клан Грозовой Вершины перебрасывает свои войска из Альтеракской долины в Хилсбрад. Каким-то образом им удалось провести эту операцию тайно. Если бы эти планы не попали нам в руки, всего через неделю они бы выступили против нас, все сокрушая на своем пути.$b$bА теперь мы можем сделать так, что преимущество будет на нашей стороне.$b$bВот что нам нужно сделать...', 'Посмотрите на позиции Грозовой Вершины.', '', '', '', '', 'Поговорите с верховным полководцем Кромушем на мельнице Таррен, что в предгорьях Хилсбрада.', 25549);
INSERT INTO `quest_template_locale` VALUES (28507, 'ruRU', 'Воззвание к героям: Танарис!', 'Доложите о своем прибытии Келси Стализвон в Прибамбасске, что в Танарисе.', 'По приказу его королевского высочества короля Андуина Ринна все годные к военной службе граждане Альянса обязаны явиться к Келси Стализвон в Прибамбасск.$b$bАльянсу требуется ваша помощь, чтобы отвоевать земли у местного барона и получить доступ к ценным ресурсам. Чтобы добраться до Прибамбасска, отправляйтесь на юг из Мерцающих глубин, что в Тысяче Игл.$b$bЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28508, 'ruRU', 'Битва за Андорал', 'Обратитесь к Келлену Куну, чтобы тот переправил вас в Андорал, расположенный в Западных Чумных землях. После этого доложите о своем прибытии Кольтире Ткачу Смерти в Андорале.', 'Я только что получил чрезвычайно занимательное послание. Поистине любопытное письмо...$b$bГород Андорал попал в гущу противоборства между Отрекшимися, Альянсом и Плетью. Похоже, Леди Сильвана решилась действовать и, что еще интереснее, поставила во главе своих войск рыцаря смерти Кольтиру Ткача Смерти.$b$bТебя персонально позвали на подмогу, $n. Обратись к дрессировщику нетопырей Келлену Куну. Он отправит тебя в Андорал с первым же нетопырем.', '', '', '', '', '', 'Поговорите с Кольтирой Ткачом Смерти в Андорале, что в Западных Чумных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (28509, 'ruRU', 'Приказ вождя: Танарис!', 'Доложите о своем прибытии Мегз Жестекрошшер в Прибамбасске, что в Танарисе.', 'Всем годным к военной службе ордынцам приказано явиться в Прибамбасск к Мегз Жестекрошшер. Орде и картелю Трюмных Вод нужна помощь, чтобы упрочить свое положение в Танарисе до прихода туда Альянса!$b$bЧтобы добраться до Прибамбасска, отправляйся на юг от гоночной баржи Пшикса и Поззика, что в Тысяче Игл.$b$bСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28510, 'ruRU', 'Приказ вождя: Фералас!', 'Доложитесь Кону Руническому Тотему в лагере Атайя в Фераласе.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к Кону Руническому Тотему в лагерь Атайя в Фераласе. Помогите Орде защитить великий лес от налетчиков Альянса и Зловещего Тотема.$B$BВ лагерь Атайя можно попасть, отправившись из Пустошей на юг, в Фералас.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28511, 'ruRU', 'Воззвание к героям: Фералас!', 'Доложитесь Теларону Полету Ветра в Покоях Дремлющего, что находятся в Фераласе.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к Теларону Полету Ветра в Покои Дремлющего, что в Фераласе.$B$BАльянс взывает о вашей помощи, чтобы сокрушить наших врагов: налетчиков Орды и Зловещего Тотема. В Покои Дремлющего можно попасть, отправившись из Пустошей на юг, в Фералас.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28512, 'ruRU', 'На помощь Братству Тория', 'Поговорите с Джеком Глыбоногом на Передовой Братства Тория, что в Тлеющем ущелье.', 'Дворфы из клана Черного Железа злы и коварны... но у нас есть и другие враги. Я несколько раз обращался за помощью к дворфам из Братства Тория, и они всегда шли мне навстречу.$b$bНа днях в город приехал мой стародавний знакомый Джек Глыбоног и попросил меня отправиться с ним в какой-то поход. Кажется, это для него крайне важно.$b$bЯ немного занят, не $gмог:могла; бы ты пойти вместо меня? Просто иди на запад по дороге в Тлеющее ущелье. Ты повстречаешь его сразу на краю Бесплодных земель.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28513, 'ruRU', 'Гордость высокорожденных', 'Убейте 8 тоскующих или страдающих высокорожденных.', 'Десять тысяч лет назад...$B$BВысокорожденные жили здесь в богатстве и достатке. Мы считали себя выше простых ночных эльфов. Магия и золото удовлетворяли все наши желания; мы жили в роскоши. И алчности...$B$BДухи, которых ты здесь видишь, переполнены сожалением и раскаянием. Тоска удерживает их здесь. Если хочешь узнать больше о Кел\'терил и Зин-Малоре, поговори с ними.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28514, 'ruRU', 'Мутон Пламя Звезд', 'Поговорите с Мутоном Пламенем Звезд в Лагере Пламени Звезд, что в Пылающих степях.', 'Я наслаждаюсь редкими моментами, когда удается вырваться из Тлеющего ущелья. Я собирался навестить своего друга в Пылающих степях, но у меня так и не получилось это сделать.$b$bЕго зовут Мутон Пламя Звезд. Хоть он и не состоит в Братстве, ему можно доверять.$b$bНе передашь ли ты ему от меня привет? Двигайся на юг, сквозь Черную гору. Просто двигайся в южном направлении... и ты встретишь его.$b$bБлагодарю тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28515, 'ruRU', 'Мутон Пламя Звезд', 'Поговорите с Мутоном Пламенем Звезд в Лагере Пламени Звезд, что в Пылающих степях.', 'Я наслаждаюсь редкими моментами, когда удается вырваться из Тлеющего ущелья. Я собирался навестить своего друга в Пылающих степях, но у меня так и не получилось это сделать.$b$bЕго зовут Мутон Пламя Звезд. Хоть он и не состоит в Братстве, ему можно доверять.$b$bНе передашь ли ты ему от меня привет? Двигайся на юг, сквозь Черную гору. Просто двигайся в южном направлении... и ты встретишь его.$b$bБлагодарю тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28517, 'ruRU', 'Воющий дуб', 'Поговорите с Генном Седогривом в Воющем дубе Дарнаса.', 'Значит, это и есть... наш новый дом. Не знаю, смогу ли я еще хоть раз обрести чувство, что я по-настоящему вернулся домой...$B$BМы должны быть благодарны ночным эльфам за все, что они сделали для нас. Эта раса обычно не злоупотребляет гостеприимством. То, что они приютили нас – знак их безграничной щедрости и веры в будущее.$B$BГвен и король Седогрив обосновались в городской ратуше – Воющем дубе. Зайди, они будут рады тебя видеть. Просто воспользуйся порталом в дереве позади меня, а как окажешься на месте – иди в северную часть города.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28518, 'ruRU', 'Наследие высших эльфов', 'Добудьте воспоминание о Зин-Малоре у духа верховного мага Мения.', 'Сто лет назад...$B$BЯ с небольшим отрядом высших эльфов прибыл сюда из нашей родной страны, Кель\'Таласа. Мы надеялись узнать тайны древнего Кель\'торила... выяснить, почему он был уничтожен.$B$BВ толще льда мы нашли осколки кристалла. Верховный маг, который был с нами, вскоре подпал под их власть. Но мы, глупцы, заметили это слишком поздно.$B$BЕго дух бродит на юго-востоке, среди тех, кого он свел с ума. Он до сих пор цепляется за воспоминания о своем драгоценном кристалле...', '', 'Безумие одного из нас навлекло проклятие Зин-Малора на весь народ.', 'Верховный маг Мений', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28519, 'ruRU', 'Боль эльфов крови', 'Убейте 7 обреченных духов или обреченных призраков у озера Кель\'терил.', 'Один год назад...$B$BЛегенда о кристалле Зин-Малора добралась до Луносвета, и я повел в эти земли отряд, состоявший из лучших воинов и ученых. С собой мы взяли запас кристаллов маны, чтобы никто из нас не поддался искушению попробовать сам кристалл.$B$BНо кристалл все равно одержал верх над нами. Как только он оказался в наших руках, сразу превратил всех, кроме меня, в кровожадных зверей.$B$BЭти погибшие души до сих пор бродят здесь в поисках новых жертв. Ты проявишь к ним милосердие?.. Или убежишь, чтобы когда-нибудь умереть в своей постели?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28520, 'ruRU', 'Падение Неферсета', 'Убейте Темного фараона Текана в городе Неферсет в Ульдуме.', 'Мы готовы атаковать, $n.$B$BЕсли мы сразим Темного фараона Текана, бессмертные колоссы падут, и наши армии смогут ворваться в Неферсет.$B$BОтыщи фараона и сразись с ним. Пусть в твоей душе не будет места страху, ибо когда придет время решающей схватки с могучим врагом, я позабочусь о том, чтобы ты $gпротивостоял:противостояла; ему не в одиночку.', '', 'Убей темного фараона и неферсеты падут вслед за ним.', 'Темный фараон Текан', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28521, 'ruRU', 'Разговор с Сальфой', 'Пройдите через Крепость Древобрюхов и выйдите к Зимним Ключам. Поговорите с Сальфой, который стоит на страже у входа в Крепость Древобрюхов.', 'Угроза распространения порчи исходит не только с юга от фурболгов Мертвого Леса, но и с востока от фурболгов Зимней Спячки, которые обитают в Зимних Ключах. Если ты хочешь и дальше помогать нам, поговори с Сальфой. Его можно найти с другой стороны крепости, у входа в Зимние Ключи. Иди туда по тропе, которая слева.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28522, 'ruRU', 'Боевые действия в деревне Зимней Спячки', 'Соберите 10 бус духов, убивая фурболгов из племени Зимней Спячки.', '$n, обычно древобрюхи держатся особняком. И хотя мы позволяем друзьям ходить по нашей земле, но все-таки стараемся не общаться с другими племенами фурболгов.$B$BВ последнее время племя Зимней Спячки ведет себя очень враждебно. Они боятся и ненавидят все, чего не могут понять, и этот страх и ненависть приводят их в бешенство.$B$BОни носят на шее особые бусы, но, похоже, они не уберегли их от порчи. Принеси мне 10 таких бус – тогда я буду знать, что тебе удалось уменьшить их численность.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28523, 'ruRU', 'Четки для Сальфы', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28524, 'ruRU', 'Груз для Доновы', 'Отнесите корзинку Сальфы Донове Снегоноре, которая находится в Зимних Ключах.', 'Донова Снегонора – добрый дворф. Она часто посещает местные горячие источники: по ее словам, изучает их магические свойства.$B$BОна в хороших отношениях с нашим племенем, и когда племя Зимней Спячки стало вести себя агрессивно, Донора решила найти источник порчи.$B$BМне нельзя покидать свой пост, поэтому я хочу попросить тебя об услуге. Отнеси ей эту корзинку со снедью и передай, что мы будем рады, если она нас навестит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28525, 'ruRU', 'Воззвание к героям: кратер Ун\'Горо!', 'Доложите о своем прибытии Виллидену Маршаллу на заставе Маршалла, что в кратере Ун\'Горо.', 'По приказу его королевского высочества короля Андуина Ринна все годные к военной службе подданные Альянса должны явиться к Виллидену Маршаллу на заставу Маршалла.$b$bЭкспедиции Маршалла требуется помощь в изучении древних животных, уникальных растений и мощных кристаллов кратера Ун\'Горо. Чтобы добраться до кратера Ун\'Горо, отправляйтесь в западную часть пустыни Танарис и идите по дороге к заставе Маршалла.$b$bЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28526, 'ruRU', 'Приказ вождя: кратер Ун\'Горо!', 'Доложите о своем прибытии Виллидену Маршаллу на заставе Маршалла, что в кратере Ун\'Горо.', 'Всем годным к военной службе подданным Орды надлежит явиться к Виллидену Маршаллу на заставу Маршалла. Экспедиции Маршалла требуется твоя помощь в исследовании секретов кратера Ун\'Горо. Уникальные животные и кристаллы кратера Ун\'Горо могут оказаться очень полезны Орде.$b$bЧтобы добраться до кратера Ун\'Горо, отправляйся в западную часть пустыни Танарис и иди по дороге к заставе Маршалла.$b$bСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28527, 'ruRU', 'Приказ вождя: Силитус', 'Явитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к призывательнице ветров Горный Рог в крепость Кенария. Наши союзники из Круга Кенария взывают о помощи в противостоянии с культом Сумеречного Молота. Пособники Чо\'Галла не должны властвовать над Силитусом!$B$BВ Силитус можно попасть, отправившись по дороге из кратера Ун\'Горо на северо-запад.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28528, 'ruRU', 'Воззвание к героям: Силитус', 'Явитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.', 'По приказу его королевского высочества Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к призывательнице ветров Горный Рог в крепость Кенария.$B$BНаши союзники из Круга Кенария взывают о помощи в противостоянии с культом Сумеречного Молота. В Силитус можно попасть, отправившись по дороге из кратера Ун\'Горо на северо-запад.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28529, 'ruRU', 'Рукописи бездны', 'Отнесите записи темного вестника следопыту Глинде Нал\'Шие в Лор\'данел.', 'Это очень древние свитки, которые, кажется, составляют часть какого-то манускрипта, но вы все равно можете разобрать, что некоторые из этих записей описывают путь становления охотником на демонов.$B$BБольшинство ночных эльфов с подозрением относятся к ритуалам и темным клятвам охотников на демонов, поэтому лучше хранить свою находку в тайне.$B$BПокажите свитки только следопыту Глинде Нал\'Шие. Она знает, что с ними делать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28530, 'ruRU', 'Следы ожогов', 'Соберите 7 фрагментов подозрительного зеленого слякоча, уничтожая обжигающие всплески или кипящие клокотуны.', 'Похоже, в котле находился какой-то концентрат. Если племя Зимней Спячки разводит это вещество прямо в источниках, то со временем его содержание в них будет повышаться...$b$bВ источнике к северо-востоку отсюда полно элементалей. Раньше я думала, что это из-за катаклизма, но, похоже, их появление вызвано именно этим.$B$BМожет, ты проверишь, поражены ли они порчей? Убей несколько штук и собери все зеленое вещество, которое после них останется.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28531, 'ruRU', 'Воззвание к героям: Пустоши!', 'Доложитесь офицеру Дженки, находящейся в Тефрис-Аране в Пустошах.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к офицеру Дженки, находящейся в Тефрис-Аране в Пустошах.$B$BОтважные солдаты, отбивающиеся от толп демонов и войск Орды на Высоте Найджела, взывают о вашей помощи. Чтобы попасть в Пустоши, следуйте из Обугленной долины, что в Когтистых горах, по дороге на юг.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28532, 'ruRU', 'Приказ вождя: Когтистые горы!', 'Обратитесь к кровавому стражу Альдо Каменному Дождю, находящемуся в приюте Серебряного Ветра в Ясеневом лесу.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к кровавому стражу Альдо Каменному Дождю, находящемуся в приюте Серебряного Ветра в Ясеневом лесу. Войска Орды в Когтистых горах просят оказать им помощь в борьбе с захватчиками из Альянса и защите нашего народа. Кровавый страж переправит вас к краю Когтистых гор.$B$BДля того чтобы попасть в приют Серебряного Ветра, доберитесь до самого сердца Ясеневого леса, где вблизи озера собираются наши силы.$B$BСудьба зовет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28533, 'ruRU', 'Решение Верховного совета', 'Поговорите с королем Фаорисом в Рамкахене в Ульдуме.', 'Верховный Совет готов огласить свое решение касательно объявления войны племени Неферсет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28534, 'ruRU', 'Потомки высокорожденных', 'Поговорите с кель\'дорайским духом.', 'Вскоре после моей смерти алчность погубила мой народ, и ему пришлось покинуть родные края. На другом континенте они стали называться \"Кель\'дорай\" – \"Высшие эльфы\". В Кель\'Таласе они наслаждались могуществом своего колодца и забыли о том, к чему привели их непомерные желания и алчность.$B$BЭти эльфы, наши отдаленные потомки, вернулись сюда по зову рока – чтобы повторить наши ошибки. Теперь выслушай их историю, как это сделал я...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28535, 'ruRU', 'Потомки высших эльфов', 'Поговорите с духом син\'дорай.', 'Много лет спустя после моей смерти мой народ совершил еще более страшную ошибку. Высшие эльфы попали в зависимость от Солнечного Колодца. Мы не представляли себе мир без него и поэтому не были готовы к тому, что когда-нибудь его лишимся.$B$BПозднее, когда Солнечный Колодец попал в руки нежити, мы растерялись... и путь, который мои родичи выбрали после этого, навсегда изменил их.$B$BСин\'дорай, все еще мечтающие о прощении, тоже вернулись сюда...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28536, 'ruRU', 'Проклятие Зин-Малора', 'Поговорите с Келеком Стражем Неба в Зимних Ключах у озера Кел\'Терил.', 'Теперь тебе удалось увидеть все своими глазами. Знай, что кристалл Зин-Малора несет лишь гибель всему живому.$B$BУходи отсюда, если не хочешь присоединиться к нам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28537, 'ruRU', 'В погоне за тенями', 'Догоните и убейте тень Ищущего Духов и добудьте любые сведения о ее повелителе.', 'Говоришь, эта штука вещала про какого-то повелителя? Про того, кому принадлежит Зин-Малор?$B$BЭто тревожная новость. $C, мы должны действовать! Я видел, как тень летела на юг. Следуй по тропе к верхним руинам и, возможно, тебе удастся перебраться через замерзший водопад и догнать ее!$B$BНо будь начеку... возможно, тень уже ждет тебя.', '', 'Мы должны узнать, кто командует этим чудовищем!', 'Тень Ищущего Духов', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28538, 'ruRU', 'Крик банши', 'Воспользуйтесь зеркалом банши, чтобы захватить 10 агентов ШРУ.', 'Так ты собираешься стать $gнашим спасителем:нашей спасительницей;? Что ж, прекрасно, я установлю мысленную связь с тобой. Тогда я смогу общаться с тобой и видеть все твоими глазами.$b$bСогласно военным планам, которые ты $gдостал:достала;, клан Грозовой Вершины заручился поддержкой ШРУ на Возвышенности Соферы, что к северу отсюда. В ШРУ состоят только люди. Люди, которых мы можем использовать в своих целях.$b$bВозьми мое зеркало и отправляйся на север. Вступи в бой с агентами ШРУ и сражайся до тех пор, пока почти не убьешь их. Когда они будут на волосок от смерти, используй зеркало.', '', '', '', 'У нас впереди еще много работы. Не расслабляйся.', 'Мелизара', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28539, 'ruRU', 'Воззвание к героям: Когтистые горы!', 'Обратитесь к охотнице Джалин в башне Звездной Пыли, находящейся на границе Ясеневого леса и Когтистых гор.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к охотнице Джалин в башню Звездной Пыли в Ясеневом лесу.$B$BВойска Орды стремятся проникнуть вглубь Когтистых гор, и мы должны дать им отпор! В башню Звездной Пыли можно попасть из южной части Ясеневого леса, что граничит с Когтистыми горами.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28540, 'ruRU', 'Э\'ко-магия', 'Добудьте сердце Ледолапа.', 'Мау\'ари много лет делает амулеты. РАЗ! – и вырывает Э\'ко из зверей, а потом делает амулеты для детишек и искателей приключений.$B$BА там, на востоке стоит огромный холм. Вокруг холма бродят медведи-щербозубы. А на вершине живет Ледолап, самый старый медведь в этом лесу.$B$BМау\'ари нужно сердце этого медведя – для ее магии. Принеси мне сердце старого большого медведя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28542, 'ruRU', 'Приказ вождя: Оскверненный лес!', 'Доложите о своем присутствии Тенеллу Листогону. Его можно найти в Изумрудном святилище, что в Оскверненном лесу.', 'Всем годным к военной службе подданным Орды надлежит явиться к Тенеллу Листогону в Изумрудное святилище, что в Оскверненном лесу. Кругу Кенария нужна твоя помощь, чтобы отвоевать Оскверненный лес у демонов и других оскверненных существ!$b$bЧтобы добраться до Изумрудного святилища, иди по дороге, что ведет из Ясеневого леса на север.$b$bСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28543, 'ruRU', 'Воззвание к героям: Оскверненный лес!', 'Доложите о своем присутствии Тенеллу Листогону. Его можно найти в Изумрудном святилище, что в Оскверненном лесу.', 'По приказу его королевского высочества короля Андуина Ринна все годные к военной службе граждане Альянса обязаны явиться к Тенеллу Листогону в Изумрудное святилище.$b$bЕго орден нуждается в вашей помощи, чтобы очистить Оскверненный лес от власти демонов. Чтобы добраться до Изумрудного святилища, идите по дороге, что ведет из Ясеневого леса на север, к Оскверненному лесу.$b$bЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28544, 'ruRU', 'Воззвание к героям: Зимние Ключи!', 'Явитесь к Донове Снегоноре у Источников Ледяного огня в Зимних Ключах.', 'По повелению его королевского высочества короля Андуина Ринна всем боеспособным гражданам Альянса приказано явиться к Донове Снегоноре у источников Ледяного огня.$B$BЕй требуется ваша помощь, чтобы отразить угрозу фурболгов из племени Зимней Спячки. Чтобы добраться до Зимних Ключей, необходимо следовать на восток из северной области Оскверненного леса и пройти через крепость Древобрюхов.$B$BВо имя славы и чести Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28545, 'ruRU', 'Приказ вождя: Зимние Ключи!', 'Явитесь к Донове Снегоноре у Источников Ледяного огня в Зимних Ключах.', 'Всем боеспособным членам Орды настоящим приказано явиться к Донове Снегоноре у источников Ледяного огня. Сведения о фурболгах племени Зимней Спячки, которыми она располагает, помогут покончить с их агрессией раз и навсегда.$B$BЧтобы добраться до Зимних Ключей, необходимо следовать на восток из северной области Оскверненного леса и пройти через крепость Древобрюхов.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28548, 'ruRU', 'Приказ вождя: Пустоши!', 'Доложитесь Фуриену в Тефрис-Аране в Пустошах.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к Фуриену, находящемуся в Тефрис-Аране в Пустошах. Отважные воители Орды в Пустошах взывают о вашей помощи, чтобы отразить нападения войск Альянса и древних демонов.$B$BЧтобы попасть в Тефрис-Аран, двигайтесь на юг из Обугленной долины в Когтистые горы.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28549, 'ruRU', 'Приказ вождя: Южные степи!', 'Доложите о своем прибытии Нуре Землепроходице на Верхнем пути в Южных степях.', 'Всем годным к военной службе подданным Орды надлежит явиться к Нуре Землепроходице на Верхний путь, что в Южных степях. В последнее время Альянс одержал ряд побед в степях, и теперь враг угрожает перекрыть наши линии подкрепления. Мы должны действовать!$b$bЧтобы добраться до Верхнего пути, иди на восток от Когтистых гор.$b$bСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28550, 'ruRU', 'Воззвание к героям: Южные степи!', 'Доложите о своем прибытии командиру Уолполу на тропе Каменного Когтя, что в северо-западной части Южных степей.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к командиру Уолполу на тропу Каменного Когтя, что в Южных степях.$b$bНаши храбрые солдаты одержали в степях ряд побед, но за это пришлось дорого заплатить! Ваша помощь требуется, чтобы упрочить наши позиции. Чтобы добраться до Южных степей из Когтистых гор, отправляйтесь на юго-восток и идите через долину Высокого Леса.$b$bЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28551, 'ruRU', 'Воззвание к героям: Южные степи!', 'Доложите о своем прибытии начальнику порта Льюису в доках у крепости Северной стражи, что в Южных степях.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к начальнику порта Льюису возле крепости Северной стражи.$b$bНаши храбрые солдаты одержали в степях ряд побед, но за это пришлось дорого заплатить! Ваша помощь требуется, чтобы упрочить наши позиции. Чтобы добраться до крепости Северной стражи, плывите на корабле из Пиратской Бухты до Кабестана, а затем продвигайтесь по берегу в южном направлении.$b$bЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28552, 'ruRU', 'Воззвание к героям: Пылевые топи!', 'Явитесь к Калии Гастингс, находящейся на острове Тераморе в Пылевых топях.', 'По приказу его королевского высочества Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к Калии Гастингс на остров Терамор.$B$BВы должны оказать помощь агенту ШРУ Калии Гастингс в расследовании заговоров, угрожающих безопасности города как в нем самом, так и за его стенами. До острова Терамора можно добраться на корабле, отплывающем из Гавани Менетилов, либо направиться к нему из Южных степей и пересечь болото.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28553, 'ruRU', 'Окрилла и Выжженные земли', 'Поговорите с Окриллой в форте Молота Ужаса, что находится в Выжженных землях.', 'Наконец, у меня для тебя есть еще одно донесение, $n. Оно поступило из форта Молота Ужаса, что находится южнее, в Выжженных землях.$b$bПредводительница Окрилла сражается с силами Альянса у крепости Стражей Пустоты, и ей, конечно же, пригодится помощь $gтакого доблестного: такой доблестной:c; |3-3($c), как ты. Ты мне сразу $gпришел:пришла; на ум.$b$bОтправляйся на юг, в Выжженные земли, а затем поверни на запад. Удачи, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28554, 'ruRU', 'Приказ вождя: Пылевые топи!', 'Явитесь к Крогу в деревню Гиблотопь в Пылевых топях.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к Крогу в деревню Гиблотопь. Болото заполонили враги всех мастей, и силы Альянса в данном регионе необычайно сильны.$B$BВ Пылевые топи можно попасть, следуя по тропе из восточной части Южных степей в направлении деревни Гиблотопь.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28556, 'ruRU', 'Преградить путь', 'Заложите гоблинские карманные ядерные бомбы на Возвышенности Соферы, Уступе Коррана, Высоком отроге и Возвышенности Гэвина.', 'Если мы хотим помешать вторжению Грозовой Вершины, мы должны преградить им путь в четырех стратегических точках.$b$b<Кромуш вручает вам небольшой пакет.>$b$bЗдесь четыре упаковки отличной гоблинской взрывчатки. Тебе нужно пробраться на каждую из четырех возвышенностей – Возвышенность Соферы, Уступ Коррана, Высокий отрог, Возвышенность Гэвина – и везде заложить эти карманные ядерные бомбы.$b$bКогда сделаешь это, а также все остальное, о чем просила тебя Мелизара, возвращайся ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28557, 'ruRU', 'Приказ вождя: в Ульдум!', 'Поговорите с Адаррой в Долине Кактусов в западном Танарисе.', 'Всем дееспособным воинам Орды предписано незамедлительно явиться к Адарре в Долину Кактусов в Танарисе.$B$BВ древних рукописях говорится, что в Ульдуме хранятся несметные сокровища. Отправляйтесь туда и добудьте эти сокровища для Орды!$B$BКараван Адарры можно найти в юго-западной части Танариса, в Долине Кактусов.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28558, 'ruRU', 'Воззвание к героям: Ульдум!', 'Поговорите с Адаррой в Долине Кактусов в Танарисе.', 'Его высочество король Андуин Ринн приказывает всем гражданам Альянса, способным держать оружие, прибыть в Танарис, в Долину Кактусов, и явиться к Адарре за распоряжениями.$B$BСтаньте одними из первых героев, которые войдут в знаменитый Ульдум и захватят его сокровища во имя Альянса.$B$BКараван Адарры можно найти в западной части Танариса.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28559, 'ruRU', 'Воззвание к героям: остров Кровавой Дымки!', 'Доложите о своем прибытии Воркану Пастуху Элекков на Перекрестке Кессела, что на острове Кровавой Дымки.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к Воркану Пастуху Элекков на Перекресток Кессела.$B$BЖителям острова Кровавой Дымки нужна ваша помощь, чтобы справиться с коварными эльфами крови и опасными существами, населяющими остров. Чтобы попасть на Перекресток Кессела, что на острове Кровавой Дымки, воспользуйтесь северным мостом от острова Лазурной Дымки.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28560, 'ruRU', 'Приказ вождя: Призрачные земли!', 'Явитесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.', 'Всем годным к службе воинам Орды приказано явиться к чародею Вандрилу в Транквиллион, что в Призрачных землях.$B$BТребуется ваша помощь в борьбе с нашествием Плети и привлечении Отрекшихся в качестве союзников в борьбе с нашим общим врагом.$B$BЧтобы попасть в Транквиллион, следуйте по дороге, ведущей на юг от площади Легкого Ветерка в Призрачные земли.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28561, 'ruRU', 'Нахом должен выстоять', 'Идите в Нахом в Ульдуме.', 'Как только мы выступим на запад, чтобы атаковать Неферсет, враг нанесет нам удар с востока, где мы будем наименее защищены.$B$BВ этом случае первым падет Нахом, а за ним – Рамкахен.$B$BОдно небольшое подразделение уже прибыло.$B$BУзнай у них обстановку. Я хочу, чтобы вы удержали Нахом до того времени, когда у меня будет возможность снова послать туда войска.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28562, 'ruRU', 'Воззвание к героям: Западный Край!', 'Поговорите с лейтенантом Горацио Лейном во Владении Янсена в Западном Крае.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к лейтенанту Горацио Лейну во Владение Янсена.$B$BВ последнее время Западный Край заполонили нищие и бродяги, из-за чего преступность там значительно возросла. Нужна ваша помощь в восстановлении правопорядка. Во Владение Янсена, что в Западном Крае, можно попасть, отправившись на запад из Элвиннского леса.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28563, 'ruRU', 'Воззвание к героям: Красногорье!', 'Найдите капитана стражи Паркера на Часовой башне в Красногорье.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к капитану стражи Паркеру, находящемуся на Часовой башне в Красногорье.$B$BНа его отряд напали мародерствующие гноллы и орки. Жители Приозерья находятся в большой беде и просят вас защитить их. Отправляйтесь на восток из Элвиннского леса в Три Угла на границе Красногорья, где и находится Часовая башня.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28564, 'ruRU', 'Воззвание к героям: Темнолесье!', 'Поговорите с командиром Алтеей Чернодрев в Темнолесье, что в Сумеречном лесу.', 'По приказу его королевского высочества короля Андуина Ринна все годные к военной службе граждане Альянса обязаны явиться к командиру Алтее Чернодрев в Темнолесье.$b$bСтражи Темнолесья борются с хищными волками и воргенами. Они не смогут долго продержаться без вашей помощи. Чтобы добраться до Темнолесья, что в Сумеречном лесу, идите по дороге, ведущей на юг вдоль границы между Элвиннским лесом и Красногорьем.$b$bЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28565, 'ruRU', 'Воззвание к героям: Болотина!', 'Явитесь к горному пехотинцу Рарену, что находится в Дун Альгазе.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к горному пехотинцу Рарену в Дун Альгаз.$B$BВследствие разрушений, вызванных Катаклизмом, Болотину заполонили дикие звери, орки-разбойники и свирепые гноллы! Для того чтобы попасть в Болотину, отправляйтесь на север из Лок Модана, минуя дворфийскую крепость Дун Альгаз.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28566, 'ruRU', 'Истребление', 'Убейте капитана Ледяное Сердце и 12 солдат Грозовой Вершины.', '<Перед вами появляется проекция Мелизары.>$b$bПередовой лагерь Грозовой Вершины находится на вершине Уступа Коррана, что к западу от Возвышенности Соферы. Отправляйся в лагерь и убей всех дворфов, каких только увидишь. Надо показать им, что такое страх, и нет лучшего способа сделать это, чем полное истребление.$b$bВыживших не оставлять, $n. Даже их капитан – особенно их капитан – должен умереть.$b$bЯ буду на связи.', '', 'Клан Грозовой Вершины узнает, что значит страх.', 'Мелизара', 'Уничтожение заставит их остановиться.', 'Мелизара', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28567, 'ruRU', 'Воззвание к героям: Лок Модан!', 'Доложите о своем прибытии пилоту Большеногу на заставе у Южных врат, что в Лок Модане.', 'По приказу его королевского высочества короля Андуина Ринна все годные к военной службе граждане Альянса обязаны явиться к пилоту Большеногу на заставу у Южных врат.$b$bИз-за разрушения Каменной Плотины и повышенной активности троггов и кобольдов силы горных пехотинцев на пределе. Они отчаянно нуждаются в подкреплении! Чтобы добраться до заставы у Южных врат, пройдите через Южные врата, которые находятся в восточной части Дун Морога.$b$bЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28568, 'ruRU', 'Приказ вождя: на Серебряный бор!', 'Явитесь к главному палачу Мортию в Ставку Отрекшихся в Серебряном бору.', 'Все способные держать оружие подданные Орды должны явиться в Серебряный бор, в Ставку Отрекшихся, к главному палачу Мортию.$B$BНам как никогда нужна ваша помощь по зачистке этого региона и захвату порта Гилнеас!$B$BЧтобы добраться до Ставки Отрекшихся, вам нужно пойти на юг, через Тирисфальские леса и войти в Серебряный бор. Оттуда следуйте по дороге, ведущей на юг, до Ставки Отрекшихся.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28569, 'ruRU', 'Болотный экспресс', 'Поговорите с Шарон Быстроходной в юго-восточном краю Пылающих степей, чтобы та перевезла вас на \"Болотном экспрессе\" на Болото печали. Затем обратитесь к торговому барону Сереблексу в Веслотопи.', 'Всякое поговаривают о дороге на Болото печали. Существуют загадочные сказания об извилистой горной дороге, идущей в обход Красногорья, что ведет в Веслотопь.$b$bКогда тебе тут станет нечем заняться, то ты захочешь уйти. Это нас всех опечалит. Если ты действительно уже $gнадумал:надумала; покинуть это место, переговори с Шарон Быстроходной в юго-восточном краю степей. Она тебя прокатит с ветерком.$b$b<Орелий наклоняет голову, словно прислушиваясь к чему-то.>$b$bВинки? Винки! О, нет!', '', '', '', '', '', 'Поговорите с торговым бароном Сереблексом в Веслотопи, что на Болоте печали.', 25549);
INSERT INTO `quest_template_locale` VALUES (28570, 'ruRU', 'Болотный экспресс', 'Поговорите с Шарон Быстроходной в юго-восточном краю Пылающих степей, чтобы та перевезла вас на \"Болотном экспрессе\" на Болото печали. Затем обратитесь к торговому барону Сереблексу в Веслотопи.', 'Смотрите, $gкакой важный:какая важная:r; |3-6($r). Только посмотрите на $gнего:нее;... $gВесь надулся:вся надулась; от важности. А ведь мы еще только познакомились!$b$bЗнаю, чем это закончится... скоро тебе станет нечем заняться на Пламенеющем Стяге. Ты, конечно же, пообещаешь вернуться. Однако никогда не сдержишь своего слова.$b$bКиблер все это уже видел не раз.$b$bЕсли ты действительно уже $gнадумал:надумала; покинуть это место, переговори с Шарон Быстроходной в юго-восточном краю степей. Она тебя прокатит с ветерком.$b$bНа чем? Да на ракете. Это абсолютно безопасно.', '', '', '', '', '', 'Поговорите с торговым бароном Сереблексом в Веслотопи, что на Болоте печали.', 25549);
INSERT INTO `quest_template_locale` VALUES (28571, 'ruRU', 'Приказ вождя: предгорья Хилсбрада!', 'Отчитайтесь верховному палачу Дарталии у Южных врат в предгорьях Хилсбрада.', 'Всем годным к военной службе подданным Орды надлежит явиться к верховному палачу Дарталии в предгорья Хилсбрада к Южным вратам. Боевая машина Отрекшихся движется вперед и вперед, защищая Лордерон!$b$bЧтобы добраться до Южных врат, нужно идти по дороге на юг через Серебряный бор, а на развилке повернуть на восток, на дорогу, ведущую к предгорьям Хилсбрада.$b$bВперед, $gбрат:сестра;! Судьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28572, 'ruRU', 'Приказ вождя: нагорье Арати!', 'Доложите о своем прибытии темному следопыту Алине в Уделе Галена, что на нагорье Арати.', 'Всем годным к военной службе ордынцам приказано явиться к темному следопыту Алине в Удел Галена. Силы Темной Госпожи нуждаются в подкреплении, чтобы усилить власть Орды и вышвырнуть прочь захватчиков Альянса.$B$BЧтобы добраться до нагорья Арати, отправляйся на восток от предгорий Хилсбрада и следуй по дороге, ведущей к Стене Торадина.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28573, 'ruRU', 'Воззвание к героям: нагорье Арати!', 'Доложите о своем прибытии капитану Ниалс в Опорном пункте, что на нагорье Арати.', 'По приказу его королевского высочества короля Андуина Ринна все годные к военной службе граждане Альянса обязаны явиться к капитану Ниалс в Опорный пункт.$b$bНужно возродить доброе имя Стромгарда! Слишком долго его марали преступники и огры. Чтобы добраться до Арати, отправляйтесь из Болотины на север и перейдите через Мост Тандола. Затем двигайтесь по дороге к Опорному пункту и доложите о своем прибытии капитану.$b$bВо славу и за честь Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28574, 'ruRU', 'Приказ вождя: Внутренние земли!', 'Поговорите со старейшиной Сломанным Клыком в Деревне Сломанного Клыка, что во Внутренних землях.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к старейшине Сломанному Клыку в Деревню Сломанного Клыка.$B$BТеперь, когда дворфы из клана Громового Молота официально присоединились к Альянсу, они стали нашими врагами. Мы должны покончить с ними раз и навсегда!$B$BЧтобы попасть в Деревню Сломанного Клыка, двигайтесь во Внутренние земли по горному перевалу в восточных предгорьях Хилсбрада и далее – к восточному побережью.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28575, 'ruRU', 'Приказ вождя: Западные Чумные земли!', 'Явитесь к Кольтире Ткачу Смерти в Андорале, что находится в Западных Чумных землях.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к Кольтире Ткачу Смерти в Андорале.$B$BСилы Альянса продвигаются вглубь разрушенного города Андорала, стремясь закрепиться в данном регионе. Мы должны пресечь эти планы!$B$BПройдите через Бастион, расположенный в восточной части Тирисфальских лесов, и следуйте по дороге на юго-восток в Андорал, где вам надлежит присоединиться к войскам Орды.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28576, 'ruRU', 'Воззвание к героям: Западные Чумные земли!', 'Явитесь к Тассариану в Андорале, что находится в Западных Чумных землях.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к Тассариану в Андорал.$B$BВ ответ на успех нашей недавней кампании в Андорале Отрекшиеся решились перейти в контрнаступление. Силы Альянса нуждаются в вашей помощи в операции по освобождению Андорала от приспешников Плети и Орды.$B$BДля того чтобы попасть в Андорал, отправляйтесь на север через предгорья Хилсбрада и следуйте по дороге, проходящей за Лагерем Промозглого Ветра.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28577, 'ruRU', 'Приказ военачальника: Восточные Чумные земли!', 'Явитесь с докладом к Фионе на восточный берег реки Тондрорил в Восточных Чумных землях.', 'Все способные держать оружие подданные Орды должны переправиться на восточный берег Тондрорила и явиться к Фионе за распоряжениями.$B$BСеребряный Авангард закрепился в Чумных землях, и теперь ему нужна ваша помощь, чтобы развить успех.$B$BВосточные Чумные земли расположены рядом с Западными Чумными землями, на другом берегу реки Тондрорил. Ищите Фиону на восточном берегу!$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28578, 'ruRU', 'Воззвание к героям: Восточные Чумные земли!', 'Явитесь с докладом к Фионе на восточный берег реки Тондрорил в Восточных Чумных землях.', 'Его высочество король Андуин Ринн приказывает всем гражданам Альянса, способным держать оружие, переправиться на восточный берег Тондрорила и явиться к Фионе за распоряжениями.$B$BПомогите Серебряному Авангарду отвоевать Восточные Чумные земли у Плети.$B$BВосточные Чумные земли расположены рядом с Западными Чумными землями, на другом берегу реки Тондрорил. Ищите Фиону на восточном берегу!$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28579, 'ruRU', 'Воззвание к героям: Бесплодные земли!', 'Поговорите с Геком Выхлюпом в часовне Последней Надежды, что в Восточных Чумных землях.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к Геку Выхлюпу в часовню Последней Надежды, что в Восточных Чумных землях.$b$bОт вас требуется оценить ущерб, нанесенный Смертокрылом, а также разведать место дислокации сил Орды в Бесплодных землях.$b$bВ обмен на вашу помощь Гек согласился доставить вас на ракете в Бесплодные земли. Его можно найти в часовне Последней Надежды, расположенной в Восточных Чумных землях.$b$bЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28580, 'ruRU', 'Приказ вождя: Бесплодные земли!', 'Поговорите с Геком Выхлюпом в часовне Последней Надежды, что в Восточных Чумных землях.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к Геку Выхлюпу в часовню Последней Надежды, что в Восточных Чумных землях.$b$bАльянс всеми силами стремится закрепиться в Бесплодных землях. От вас требуется отвадить врага и оценить ущерб, нанесенный Смертокрылом.$b$bГек согласился доставить вас в Бесплодные земли на своей ракете. Он находится в часовне Последней Надежды.$b$bСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28581, 'ruRU', 'Приказ вождя: Тлеющее ущелье', 'Доложите о своем прибытии Джеку Глыбоногу в Братстве Тория, что в Тлеющем ущелье.', 'Всем годным к военной службе ордынцам надлежит явиться к Джеку Глыбоногу в Братство Тория.$b$bКлан Изувеченной Длани сообщает о том, что дворфы Черного Железа из Тлеющего ущелья к чему-то готовятся. Твоим заданием будет разведать об этом все, что сможешь, и помешать их действиям.$b$bЧтобы попасть в Тлеющее ущелье, иди по дороге, что ведет из Бесплодных земель на запад.$b$bСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28582, 'ruRU', 'Воззвание к героям: Тлеющее ущелье!', 'Доложите о своем прибытии Джеку Глыбоногу в Братстве Тория, что в Тлеющем ущелье.', 'По приказу его королевского высочества короля Андуина Ринна всем членам Альянса, способным держать оружие, надлежит отрапортовать Джеку Глыбоногу на Передовой Братства Тория.$b$bШРУ сообщает о том, что дворфы Черного Железа в Тлеющем ущелье готовятся к нападению. Вашим заданием будет разведать об этом все, что сможете, и помешать их действиям.$b$bЧтобы попасть в Тлеющее ущелье, идите по дороге, что ведет из Бесплодных земель на запад.$b$bЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28583, 'ruRU', 'Психходельня', 'Отнесите заявку на патент капитану Психхо в Психходельню на Сумеречном нагорье.', 'Мой проект нового крошшера крут, $n. Реально крут! Теперь важно защитить свою интеллектуальную собственность. Запатентовать, выбрать дилеров, засудить плагиаторов... Ах да, и взятки раздать, конечно!$B$BВот, отнеси-ка эту заявку на патент капитану Психхо в Психходельню. Он пережил крушение своего дирижабля, так что теперь наверняка ищет новые идеи для бизнеса.$B$BПсихходельня на севере отсюда, на абсолютно надежной горной вершине. Давай-ка, $gдружок:подружка;, одна нога здесь, другая там!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28584, 'ruRU', 'Сработано на совесть', 'Замотайте термолентой 10 неисправных вентилей.', 'Я тебе так скажу, $gкомандир:дорогуша;: если бы не эта ошибка природы вон там напротив, Психходельня сейчас стояла бы себе и горя не знала.$B$BК несчастью для всех нас, товарища Ротмана \"Несуразные Штаны\" угораздило развернуть город на вершине горы! Нет, ну в самом деле, кому такое в голову-то взбредет?!$B$BНу и теперь у нас, разумеется, утечка на утечке сидит и утечкой погоняет из-за неисправных вентилей... Может, поможешь мне их замотать вот этой термолентой?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28586, 'ruRU', 'Надувные пони спешат на помощь', 'Сбросьте надувных пони 10 работникам Психходельни, свалившимся в воду.', 'Из-за этого кретина – вон напротив стоит – наши гибнут!$B$BЭтот Бретт \"Криворучко\" развернул Психходельню черт знает где, теперь тут все на честном слове держится... Взрывами, вызванными неустойчивостью, наших рабочих сметает с платформ прямо в воду.$B$B$n, может быть, слетаешь вниз и сбросишь им на подмогу надувных пони?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28587, 'ruRU', 'Помощь клана Северного Волка', 'Поговорите с Воггой Смертобоем в Альтеракских горах, что в предгорьях Хилсбрада.', 'Я изучу военные планы Грозовой Вершины и спланирую нападение. Мне нужно, чтобы ты $gотправился:отправилась; в Альтеракскую долину и $gзаручился:заручилась; поддержкой клана Северного Волка, это клан самого нашего бывшего вождя Тралла. Они помогут нам сразиться с дворфами Грозовой Вершины! Вместе мы сокрушим их и выдворим из Лордерона навсегда!$b$bИди, $n. Альтеракская долина находится к северо-востоку от мельницы Таррен. Найди Воггу Смертобоя и скажи ему, что Орда нуждается в помощи клана Северного Волка!$b$bЛок\'тар!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28588, 'ruRU', 'Засилье Громового Молота', 'Убейте 10 налетчиков из клана Громового Молота.', 'Эти двое придурков все спорят, кто из них больше виноват, а Психходельня, между тем, уже кишмя кишит врагами!$B$BКуда ни плюнь – всюду эти ничтожества из Громового Молота! Выдвори этих вонючих выпивох прочь из Психходельни!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28589, 'ruRU', 'Всякая всячина', 'Сбейте 15 штормокрылов из клана Громового Молота.', 'Ты $gдолжен:должна; помочь нам разобраться с этими штормокрылами Громового Молота. Они не оставляют нас в покое!$B$BБеда в том, что снарядов у нас нет. Придется импровизировать. Мы зарядили психхопушки всякой всячиной: надувными пони, банками \"Каджа-Колы\" использованными упаковками от продуктов, канистрами из-под горючего, покрышками... в общем, чего там только нет!$B$BВсе, что быстро летает и больно бьет, пошло в ход.$B$BНу что, есть настроение попрактиковаться в стрельбе?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28590, 'ruRU', 'Карательные меры', 'Поговорите с Патчем на борту \"Небокрошшера\", кружащего над Высоким берегом.', 'Я, кажется, знаю, кому из альянсовского отребья сегодня не поздоровится. У них, кстати, есть кое-что из наших вещей. Я распорядился начать полномасштабное наступление на Высокий берег.$B$BСадись на \"Небокрошшер\" и присоединяйся к атаке. Патч расскажет тебе что к чему, когда доберешься до места.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28591, 'ruRU', 'Зенитчик-лимитчик сидел на стене...', 'Убейте 80 стрелков Высокого берега, 12 канониров Высокого берега и разрушьте 4 зенитные пушки Высокого берега из пушки \"Небокрошшера\".', 'Ты, похоже, любишь пострелять, $n. Занимай любую из тех вон пушек и задай жару их зенитчикам на стенах.$B$BИ поживее, ладно? Пока наш корабль не превратили в огромного цыпленка табака.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28592, 'ruRU', 'Прощальные дары', 'Заминируйте корабль, вход в крепость и одну из северных башен.', 'Уверен, у Патча в голове грандиозный план, но какая же это осада, если мы напоследок чего-нибудь не заминируем!$B$BСпускайся-ка вниз и заложи взрывчатку на корабле, у ворот крепости и в одной из тех северных башен. Этого хватит, чтобы их как следует тряхнуло.$B$BМы тоже собираемся садиться. Как закончишь, подходи к восточной башне – там и встретимся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28593, 'ruRU', 'Дело на миллион золотых', 'Отыщите индукционный самофланж.', 'Вместе с дирижаблем Гарроша на землю рухнул и индукционный самофланж, который ты для нас $gраздобыл:раздобыла; в Азшаре. Альянс держит его где-то в этой крепости. Психхо хочет его вернуть.$B$BДумаю, он спрятан в подвале, так что начни искать оттуда. Как отыщешь, принеси его мне, к восточной башне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28594, 'ruRU', 'Слезная река, Высокие берега', 'Убейте 10 защитников Высокого берега.', 'Поди и сделай отбивную из этих отбросов Альянса! Из кого хочешь – на твой вкус. Хочу, чтобы ты там $gустроил:устроила; переполох, пока будешь выполнять основное задание.$B$BКак закончишь, возвращайся к нам, к восточной башне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28595, 'ruRU', 'Психходелишки', 'Обратитесь к Трит, чтобы она отправила вас в Психходельню. По прибытии отдайте индукционный самофланж капитану Психхо.', 'Ну вот, мы тут почти закончили. Пора выдвигаться.$B$BНа вершине башни Трит держит под парами несколько гирокоптеров. Поговори с ней – и долетишь до Психходельни с ветерком. А мы тепло попрощаемся с местными и догоним тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28596, 'ruRU', 'Добро пожаловать на Высокий берег!', 'Уничтожьте 10 воинов Орды на Высоком берегу.', 'Добро пожаловать на нагорье, солдат. Ты как раз вовремя.$B$BВойска Орды только что начали атаку с воздуха. Вступай в бой и разберись с ними. Всех перебей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28597, 'ruRU', 'Меж двух огней', 'Соберите 10 мешков оружейного пороха.', 'Здорово! Придется нам сломя голову кидаться в бой, $n. Похоже, у Высокого берега есть одна проблема с дирижаблем: вон тот аппарат поливает крепостные стены почем зря.$B$BСлушай, мне тут пришла идейка настолько бредовая – аж до гениальности! И нужен мне всего-навсего порох.$B$BРаздобудь сколько сможешь пороха – обшарь весь Высокий берег! Встретимся в торговых рядах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28598, 'ruRU', 'Целясь ввысь', 'Дайте Фарго Кремневому Затвору выстрелить вами в дирижабль, а затем заложите взрывчатку в трюме воздушного судна.', 'Слушай сюда, $n. Я нашел самую большую пушку на Высоком берегу! Сейчас опробуем трюк, о котором поведал мне мой батя, а ему – его батя, а тому – его папашка, как раз перед тем, как его разнесло в клочки.$B$BНазывается \"|3-6($c)-снаряд\".$B$BБерется, значит, |3-6($r) |3-6($c), заряжается в пушку покрупнее, а потом... да успокойся! Обычно все обходится.$B$BПодержи-ка вот взрывчатку и далеко не уходи. Когда эта дирижабель подлетит поближе, я запулю тебя прямо к ним на палубу. Заложи взрывчатку в трюме, а дальше... ну не знаю, что-нибудь по ходу сообразишь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28599, 'ruRU', 'Курдран ждет', 'Поговорите с Курдраном Громовым Молотом в Крепости Высокого берега на Сумеречном нагорье.', 'Кажется, наступление прекратилось, $n. Жаль, конечно, ведь мы так и не попробовали |3-6($c)-ракету...$B$BКак бы там ни было, Курдран Громовой Молот ждет тебя в крепости с распростертыми объятиями, чтобы как следует отблагодарить. Ты $gзаслужил:заслужила; награду! Отправляйся к нему.$B$BА я пойду разведаю, что там на берегу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28600, 'ruRU', 'Суть верности', 'Поговорите с Дрек\'Таром.', 'Я не уполномочен принимать подобные решения. Тебе нужно поговорить с нашим предводителем, Дрек\'Таром. Я уже отправил сообщение о твоем прибытии в крепость Северного Волка. Дрек\'Тар выйдет, чтобы лично поговорить с тобой.', 'Узнайте истинную суть верности.', '', '', '', '', 'Вернитесь к верховному полководцу Кромушу на мельницу Таррен, что в предгорьях Хилсбрада.', 25549);
INSERT INTO `quest_template_locale` VALUES (28602, 'ruRU', 'Будь готов ко всему', 'Соберите 6 обрывков веревки.', 'Ни один уважающий себя путешественник – равно как и благоразумный искатель приключений – никогда не войдет в пещеру, подземелье или гробницу без мотка длинной крепкой веревки... верно я говорю?$B$BМоя веревка осталась в вагончике со взрывчаткой, которую ты так бодро $gрванул:рванула;.$B$BТак что, может, поищешь в окрестностях... вдруг и найдется веревочка...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28603, 'ruRU', 'Проникновение', 'Убейте инструктора Руфуса, сержанта-инструктора Магнуса и капитана Грязноборода.', 'Твое следующее задание будет заключаться в том, чтобы отправиться на запад на Высокий отрог и проникнуть на тренировочную площадку Грозовой Вершины. Одна из моих банши замаскирует тебя, и несмотря на то, что там сотни новобранцев Грозовой Вершины, ты сможешь свободно перемещаться среди наших врагов.$b$bОтправляйся на Высокий отрог и разыщи там инструкторов Грозовой Вершины. После этого сделай так, чтобы они напали на тебя! А когда нападут – убей их. Если инструкторы будут мертвы, некому будет обучать новобранцев Грозовой Вершины!', '', 'Натрави их друг на друга.', 'Мелизара', 'От сумятицы рукой подать до хаоса.', 'Мелизара', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28604, 'ruRU', 'Хитрость и мошенничество', 'При помощи бочки с водой отравите 30 новобранцев Грозовой Вершины.', 'Благодаря моей маскировке враги будут считать тебя $gодним:одной; из своих. И все же не ударяйся в безумства. Если ты привлечешь к себе внимание, дворфы могут что-то заподозрить и напасть на тебя!$b$bС учетом всего этого у меня есть план. Возьми эту бочку с отравленной водой и предложи утомленным новобранцам Грозовой Вершины утолить из нее жажду. Стоит им выпить этой воды, как они обречены. В конечном итоге они умрут от действия яда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28605, 'ruRU', 'Власть', 'Убейте 10 инженеров Грозовой Вершины.', '<Мысли Мелизары переплетаются с вашими мыслями.>$b$bПоследним твоим заданием будет разобраться с осадными машинами на Возвышенности Гэвина, которая находится к западу от Высокого отрога. Проберись туда и уничтожь дворфов и гномов инженеров, которые конструируют и укрепляют боевые машины Грозовой Вершины. И не забудь заложить там гоблинскую взрывчатку Кромуша.', '', 'Превосходство ведет к победе!', 'Мелизара', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28608, 'ruRU', 'Мрачный склеп', 'Принесите из Мрачного склепа, что в Похоронном Звоне, густой бальзамировочный состав и нить для сшивания трупов.', 'Я рад видеть, что ты на ногах, $n. Неплохо выглядишь, особенно с учетом того, что ты так долго $gбыл мертв:была мертва;!$b$bНе всем так повезло. Если ты не против, я бы хотел попросить тебя сбегать за моим бальзамировочным составом и нитью для сшивания трупов, чтобы я мог подштопать эти тела. И то, и другое можно найти в Мрачном склепе – здании, что прямо позади меня.$b$bДарнелл сходит с тобой. Он знает дорогу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28609, 'ruRU', 'Молотилка', 'Поговорите с Дизом Дятло.', 'Мы трое уже несколько недель спорим о том, чье оружие лучше.$B$BИ я никому не позволю утверждать, что какое-то оружие лучше моих булав. Ни топоры Килрама, ни мечи Сирила не могут сравниться с моими творениями.$B$BМне надоело спорить. Пришло время на деле доказать свою правоту! Если не сложно, $gдорогой:дорогая;, выйди на улицу и передай Дизу Дятло, что мне нужен самый большой валун, какой он сможет найти!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28610, 'ruRU', 'Беда с этими обломками', 'Соберите 6 первосортных обломков, убивая ледяных грохотунов.', 'Если хочешь затащить туда валун, воспользуйся моим патентованным валуном-в-коробке! Я бы продал тебе его, но у меня закончились материалы.$B$BТам, на горе к югу от города, водятся элементали земли. Они – хороший источник обломков. Принеси мне немного обломков – я заплачу тебе за них и дам в придачу валун-в-коробке!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28611, 'ruRU', 'Ритуал осквернителей', 'Прервите ритуал неферсетов в пещере Глубомрака.', 'Мое зрение уже стало яснее, $n.$B$BНе зря мы опасались этих злодеев-неферсетов. Я чувствую, что именно они стоят за теми силами, которые отравили реку.$B$BТебе снова придется отправиться под воду. Отыщи пещеру Глубомрака – там ты встретишь неферсетов, проводящих ритуал осквернения.$B$BНе дай им завершить его – тогда река наконец-то очистится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28612, 'ruRU', 'Харрисон Джонс и храм Ульдума', 'Доберитесь до саркофага Предвестья.', 'После всего, что с нами стряслось, картинка наконец складывается воедино!$B$BДо саркофага рукой подать... Я вычислил коды, чтобы его обнаружить... Шнотц думает, мы уже покойники.$B$BА знаешь, может статься, что у нас в конце концов все получится!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28613, 'ruRU', 'Увидимся по ту сторону!', 'Обратитесь к Харрисону Джонсу, его можно найти на вершине Возвышения Творца в Ульдуме.', 'Что ж, $n, руки у нас теперь вроде как развязаны, но времени в обрез.$B$BЗа мной!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28614, 'ruRU', 'Берсерк', 'Убейте Гролнара Берсерка.', 'Племя Зимней Спячки лишилось верховного вождя, но осталось таким же яростным – только теперь его возглавляет их самый могучий воин, Гролнар Берсерк.$B$BОн живет в пещере, над деревней Зимней Спячки. Огненной воды, которую он выпивает, хватило бы на то, чтобы убить десяток обычных фурболгов!$B$BОн превратился в огромное чудовище, и наши воины не смеют бросить ему вызов... А ты сможешь победить его, |3-6($c)?', '', 'Напившись отравленной огненной воды, он повелевает всеми фурболгами.', 'Гролнар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28615, 'ruRU', 'Гнев Земли', 'С помощью заряженного тотема Танрира уничтожьте 4 тотема земли Зимней Спячки.', 'Несмотря на порчу и безумие, фурболги Зимней Спячки все еще могут шаманить. И мне больно видеть, как они пускают силу стихий на причинение вреда моему племени и всем остальным.$B$BНо мы обратим против них их же тотемы! Возьми мой тотем и отправляйся в деревню Зимней Спячки. Поставь его напротив тотемов Зимней Спячки, при этом к ним не приближайся, – тогда на всех, кто стоит рядом с ними, обрушится вся ярость земли!$B$BПовторяю: не подходи к этим тотемам!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28616, 'ruRU', 'Конец клану Грозовой Вершины', 'Станьте свидетелем гибели клана Грозовой Вершины.', 'Прежде чем мы продолжим, давай почтим минутой молчания память нашего павшего собрата Оркуса. Без него мы бы ни за что не смогли выстоять против натиска Грозовой Вершины. Это в твою честь, брат!$b$b<Кромуш становится на одно колено.>$b$bНо не думай, что я забыл о твоем участии, $n! Именно поэтому тебе и выпала честь взорвать гоблинскую ядерную бомбу.$b$bТы $gготов:готова;? За Орду!', 'Станьте свидетелем гибели клана Грозовой Вершины.', '', '', '', '', 'Поговорите с верховным полководцем Кромушем на мельнице Таррен, что в предгорьях Хилсбрада.', 25549);
INSERT INTO `quest_template_locale` VALUES (28617, 'ruRU', 'Цветочная сила', 'Выдержите 1 внушительную волну наступления зомби.', 'Теперь ты знаешь, как использовать дрызгуны. Но $gзнал:знала; ли ты, что если использовать подсолнух, они будут расти быстрее? Мы вырастим несколько подсолнухов, а потом посадим дрызгуны, чтобы остановить безумных чудовищ надзирателя Штиллеца.$b$bЗа работу!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28618, 'ruRU', 'Доставка валунов', 'Доставьте валун-в-коробке Лилит Гибкой в Круговзор.', 'Вот, держи! Один валун-в-коробке, как и было обещано.$B$BТебя ведь Лилит за ним послала? Она – мой единственный покупатель!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28619, 'ruRU', 'Приказ вождя: нагорье Арати!', 'Доложите о своем прибытии темному следопыту Алине в Уделе Галена, что на нагорье Арати.', 'Всем годным к военной службе ордынцам приказано явиться к темному следопыту Алине в Удел Галена. Силы Темной Госпожи нуждаются в подкреплении, чтобы усилить власть Орды и вышвырнуть прочь захватчиков Альянса.$B$BЧтобы добраться до нагорья Арати, отправляйся на восток от предгорий Хилсбрада и следуй по дороге, ведущей к Стене Торадина.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28620, 'ruRU', 'Восточная башня', 'Поговорите с Нильсом Гнилопчелом в Восточной башне, что в предгорьях Хилсбрада.', 'На нашей заставе, расположенной к юго-востоку отсюда, какие-то проблемы. Подробностей я не знаю, только... впрочем, давай я зачитаю отрывок из последнего письма:$b$b\"Орки совсем обнаглели. Пришли помощь или придется бить их палками.\"$b$bВот и все. Это прислал Нильс Гнилопчел, наш главный псилософ. Да, я тоже не понимаю, о чем он. Не отправишься ли ты в Восточную башню и не узнаешь ли, что ему нужно? С меня хватит этой китайской грамоты!$b$bПросто двигайся на юг, а потом – по дороге, которая ведет на восток.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28621, 'ruRU', 'Каждой малютке – по колыбельке', 'Поговорите с Харрисоном Джонсом возле храма Ульдума.', 'Ага!$B$BВы вместе с мальцом ковыляли себе сюда да в ус не дули, так ведь?$B$B$GЭль потягивали:За ручки держались;, небось видами любовались.$B$BВы там орденами-то обмениваться не спешите, настоящая работа вся впереди!$B$BАртефакт этот древний – не абы какая безделица, как вы думаете. Но чтобы вытрясти из него все тайны, нужно отнести его в Колыбель Древних!$B$BНу, и как нам это обтяпать?$B$BМожет, младшой идейку какую подкинет дельную, а?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28622, 'ruRU', 'Трое в воздухе, не считая саркофага', 'Расставьте сигнальные ракеты возле храма Ульдума.', 'Вообще-то я планировал доставить саркофаг к себе в лабораторию для изучения, но похоже, у Бранна на него свои виды.$B$BЕму кажется, он знает, как воспрепятствовать планам Смертокрыла здесь, в Ульдуме.$B$BУ моего приятеля Джока транспорт наготове, он ждет только нашего сигнала.$B$BВот сигнальные ракеты – расставь их по периметру. Сообщим ему, что у нас все готово.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28623, 'ruRU', 'Поход на запад', 'Встретьтесь с королем Фаорисом на окраине города Неферсет в Ульдуме.', 'Наша работа здесь закончена, $n. Вопреки судьбе мы сумели остановить нашествие Неферсета на Нахом.$B$BДавай же присоединимся к нашим войскам, продвигающимся на запад, пока вся слава не досталась только им.$B$BСейчас они уже должны подходить к окраинам Неферсета.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28624, 'ruRU', 'Похвальба Килрама', 'Поговорите с Дизом Дятло.', 'Ха! Какая неуклюжесть!$B$BТебе нужна не только сила. Мои топоры не менее прочные, чем булавы Лилит, но при этом они такие острые, что валят дерево с одного удара!$B$BДа-да, с одного удара! И я докажу это – здесь, на виду у всех! Иди к Дизу и попроси его притащить сюда дерево!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28625, 'ruRU', 'Лесозаготовки', 'Соберите 10 кусков свежей ледяной древесины, убивая древней с морозными листьями.', 'Целое дерево? Я торгую досками, а деревья – это что-то новенькое. Как и те валуны.$B$BМожет, окажешь мне еще одну услугу? К западу от города, над озером Кел\'Терил есть роща. Не знаю, или там нечисть завелась, или эльфы все испортили своей вонючей магией, но вот что-то в последнее время там развелось много древеней и плеточников.$B$BОни здорово мешают рубить лес – так почему бы тебе не срубить парочку из них? И принеси мне древесину этих древней.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28626, 'ruRU', 'Доставка деревьев', 'Доставьте суперростовое быстродерево Килраму в таверну Круговзора.', 'Вот, держи, суперростовое Быстродерево, на 80% состоит из натуральных ингредиентов!$B$BНет корней, нет и... мигреней. Отдай его Килраму и скажи, чтобы отошел от него ко всем чертям, когда поставит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28627, 'ruRU', 'Похвальба Сирила', 'Поговорите с Дизом Дятло.', 'Неумехи и любители, вот вы кто!$B$BЕсли ты хочешь просто зарубить своего врага, словно огр, то не важно, насколько остро и тяжело твое оружие. Я мог бы часами говорить об изяществе оружия, о скорости, о балансе... но лучше просто показать.$B$BПередай Дизу, что мне нужна ледяная глыба.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28628, 'ruRU', 'Доставка льда', 'Доставьте ледяную глыбу быстрой заморозки Сирилу Плетебою в Круговзоре.', 'Вот, держи, высококачественная, чистейшая ледяная глыба быстрой заморозки!$B$BЯ пытался продавать их как средство защиты. Ну, ты ведь знаешь этот трюк – его еще фокусники показывают? Правда, мне так и не удалось понять, как они там дышат.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28629, 'ruRU', 'Йети где-то рядом...', 'Добудьте 10 толстых шкур йети, убивая йети с холмов Ледополоха.', 'Мои друзья вечно придумывают что-нибудь гениальное, и я всегда считала, что мне за ними не угнаться... Но сегодня все изменилось! Я только что закончила чертеж великого изобретения! Если дашь слово, что не проболтаешься, так и быть, поведаю свой секрет...$B$BЯ собираюсь сделать механического йети! Все мои друзья перепугаются до смерти, когда его увидят, а когда немного придут в себя, то будут до глубины души поражены моим талантом!$B$BМне понадобятся толстые шкуры йети с холмов Ледополоха, которые в больших количествах живут на юго-востоке, на холмах Ледополоха.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28630, 'ruRU', '\"Эхо-3\"', 'Найдите \"Эхо-3\".', 'В последнее время в холмах Ледополоха пропало много гоблинов. И я чуть было не стала одной из них! $B$BМне в голову пришла мысль о том, что нужно бы поставить сенсор, оповещающий о приближении йети к Круговзору. Но, разумеется, сенсор почему-то не работает. Тут, в холмах полным-полно йети, а он ни разу даже не пискнул!$B$BМожет, ты его проверишь? Кто знает, вдруг еще починить можно... \"Эхо-3\" находится на юго-востоке, на краю холмов Ледополоха. Только не спрашивай, что стало с \"Эхо-1\" и \"Эхо-2\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28631, 'ruRU', 'Идеальные рога', 'Добудьте безупречные рога Ледобума.', 'Какой же йети без рогов!$B$BЯ уже целую вечность подыскиваю идеальную пару рогов для своего йети... и все без толку! Но вчера довелось увидеть невероятно крупного йети – самого большого из тех, что живут в Зимних Ключах.$B$BПочему-то захотелось назвать его Ледобумом. Его рога – это именно то, что мне нужно! Он бродит где-то в пещере, а вход в нее на восточной гряде холмов Ледополоха.$B$BПринеси мне его рога... Но обязательно по дороге зайди к \"Эхо-3\"!', '', 'Ты только посмотри на эти прекрасные рога!', 'Ледобум', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28632, 'ruRU', 'Чистый ледниковый лед', 'Соберите 7 кусков чистого ледникового льда в пещере на холмах Ледополоха.', 'Лед? Ох, ты ж... То есть да, конечно. У меня для тебя есть две новости: хорошая и плохая.$B$BХорошая заключается в том, что отличный чистый лед есть в пещере на холмах Ледополоха, к востоку от Круговзора. А плохая – в этой пещере полно злобных йети.$B$BНо если ты справишься с йети, то добыть лед плевое дело! Просто выбери кусок побольше и расколи его своим оружием. Принеси лед, а все остальное я сделаю.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28633, 'ruRU', 'Саркофаг Предвестья', 'Передайте Бранну Бронзобороду содержимое саркофага Предвестья.', 'Не знаю, чего нам следует ожидать, так что глядите в оба, ладно?$B$BС помощью этих кодов мы выясним истинное предназначение саркофага и узнаем способ раз и навсегда отвадить Смертокрыла от Ульдума!$B$BА ну назад!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28634, 'ruRU', 'Истребление', 'Убейте 12 озлобленных совухов.', 'Совухи... Бездушные монстры в перьях из самых темных глубин Круговерти Пустоты, которые преследуют тех, кто послабее.$b$b<Нильс указывает на леса, окружающие Восточную башню.>Они окружают нас со всех сторон и планируют нападение. Я чувствую это. Ты $gдолжен:должна; остановить их прежде, чем они смогут организоваться.$b$bОтправляйся в лес и убей всех совухов, каких увидишь. Ни один из них не должен выжить!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28635, 'ruRU', 'Призраки Хилсбрада', 'Узнайте, есть ли в Дун Гароке призраки.', 'Битва за Дун Гарок была самой кровавой за всю историю Хилсбрада. Дворфы сражались до последнего, хотя противник и превышал их численностью в десять раз. Все они погибли, защищая вот эту самую землю.$b$bА теперь я слышу жалобы на то, что в этих местах появились призраки. Все боятся даже просто пройти мимо! К сожалению, мне нужно подготовить Дун Гарок к будущему заселению.$b$bНе можешь ли оказать мне услугу и посмотреть, что там творится в Дун Гароке? Это к юго-востоку отсюда.', 'Узнайте, есть ли в Дун Гароке призраки.', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28636, 'ruRU', 'Тишина дворфов', 'Убейте 10 духов Дун Гарока.', 'Теперь в этой крепости витают духи моих погибших солдат, $n. Их души не могут покинуть это место. Даже после смерти они продолжают защищать его. Все это очень печально.$b$bИзбавь их от мучений, и, может быть, ты прославишь свой народ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28637, 'ruRU', 'Любовь к медвежатине', 'Убейте 15 медведей-щербозубов.', 'Тебе когда-нибудь доводилось есть медвежатину? В Гилнеасе я так и не смог ее попробовать – а вот у местных медведей мясо просто восхитительное.$B$BПогода здесь холодная, так что у медведей-щербозубов, которые живут к югу отсюда, мясо мраморное, с прожилками жира. Я и сам охотился на них и, честно сказать, это очень весело! Однако я предпочитаю их есть!$B$BСоветую тебе поохотиться на них. Постарайся убивать только белых щербозубов. Всех убитых тобой медведей капитан принесет в лагерь.', '', '', '', 'Мм-м... медвежатина...', 'Фрэнсис Моркотт', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28638, 'ruRU', 'Сочные совы', 'Убейте 15 сов Зимних Ключей.', 'Я всю жизнь ем сов. Совы – хорошая еда, и мой друг Джез со мной согласен. Я первый присоветовал ему продавать сов!$B$BВот этот вот красавчик-ворген говорит, что медведи вкуснее, но ты его не слушай. Иди охотиться на сов. На юге они кишмя кишат. Пока что бей только серых, а когда завалишь пару-другую, пожужжи мне на этой говорильной штуке, которую тебе дал Джез.', '', '', '', 'От этой говорильной штуки у меня ум за разум заходит.', 'Джеб Гутри', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28639, 'ruRU', 'Урсиус', 'Убейте Урсиуса.', 'Говорят, ты – это то, что ты ешь. Я в этом не уверен, но если это правда... Лично я предпочитаю мясо самого сильного зверя, которого мне удается найти.$B$BСамый большой медведь в Зимних Ключах – это Урсиус. Когда его стая щербозубов убивает химеру или совомедведя, он ест первым. Он живет в самой уютной пещере и обладает... большим влиянием на самок щербозубов.$B$BКороче говоря, это мой медведь.$B$BЯ хочу его съесть.$B$BЕго пещера находится рядом с территорией могучих щербозубов. Удачи!', '', 'Урсиус должен стать моим.', 'Фрэнсис Моркотт', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28640, 'ruRU', 'Свежие ледопарды', 'Убейте 15 ледопардов или ледопардов-разведчиков.', 'Прекрасный запах, верно? Покупатели готовы платить большие деньги за мое копченое мясо, и, кроме того, ни у одного из конкурентов нет такого ассортимента экзотической дичи. Все работает как часы: ты убиваешь зверей за небольшую плату, а мои друзья притаскивают их сюда, чтобы освежевать и закоптить!$B$BА сейчас у меня монополия на продажу мяса ледопардов. Просто объедение, колбаса из него замечательная получается. Иди на запад и поохоться на этих кошек!', '', '', '', 'Ты охотишься, я копчу мясо! Это называется \"разделение труда\"!', 'Джез Скороцап', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28641, 'ruRU', 'Украшение стола', 'Убейте 15 ледопардов-охотниц или дозорных прайда ледопардов.', 'Ну, малыш, на этот раз тебе придется отправиться еще дальше!$B$BДа, тебе удалось добыть отличную дичь, но там на западе живут кошечки побольше. У дозорных и охотниц гораздо больше мяса, и из него получаются УДИВИТЕЛЬНЫЕ котлеты. Они расходятся как горячие пирожки!$B$BКогда разберешься с ними, звякни мне. Тогда мы подумаем и о главном блюде.', '', 'Охота – это весело!', 'Джез Скороцап', 'Остался еще один!', 'Джез Скороцап', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28643, 'ruRU', 'Вызов Дарнхольда: Зефирий', 'Убейте Зефирия.', 'Крепость Дарнхольд всегда была местом стычек и распрей. В течение многих лет люди пользовались ею, как тюрьмой и лагерем для орков. Потом ее захватил Синдикат. Что сейчас? Сейчас в ее стенах находятся могущественные элементали, захваченные Темной Госпожой. По ее приказу я занимаюсь управлением состязаниями \"Вызов Дарнхольда\". Любой, кто сможет победить всех элементалей, получит главный приз! Возьми это руководство и приступай к своему первому испытанию: Зефирий!$b$bДарнхольд располагается к северо-востоку от нас.', '', 'Приспешник Ал\'акира', 'Зефирий', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28644, 'ruRU', 'Вызов Дарнхольда: Теракула', 'Убейте Теракулу.', 'В соответствии с руководством твоим следующим противником будет Теракула. Он бродит по тропе возле логова Зефирия.', '', 'Приспешник Теразан', 'Теракула', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28645, 'ruRU', 'Вызов Дарнхольда: Кровояд', 'Убейте Кровояда.', 'В соответствии с руководством твоим следующим противником будет Кровояд. Найти этого ужасного элементаля можно на нижнем этаже крепости Дарнхольд, возле западных темниц.', '', 'Приспешник Нептулона', 'Кровояд', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28646, 'ruRU', 'Вызов Дарнхольда: Инферний', 'Убейте Инферния.', 'В соответствии с руководством твоим следующим противником будет Инферний. Этого монстра, состоящего из кипящей лавы и бушующего огня, можно найти на нижнем этаже крепости Дарнхольд, возле восточных темниц.', '', 'Приспешник Рагнароса', 'Инферний', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28647, 'ruRU', 'Вызов Дарнхольда: Д-1000', 'Убейте Д-1000.', 'На арене старой крепости Дарнхольд тебя ждет существо, целиком состоящее из чистой ртути. Отрекшиеся дали ему имя Д-1000. Убей Д-1000, и приз твой!', '', 'Синий приспешник', 'Д-1000', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28649, 'ruRU', 'Приятный сюрприз', 'Командор Чумопал из Часовни Багрового Пламени приказал вам отправиться в ближайшее здание тюрьмы и уничтожить лорда Гарфорда, узника из Серебряного Рассвета.', 'Мы ворвались сюда, перевернули все вверх дном и направились к тюрьме. Но мы совершенно не ожидали увидеть там такого, $n. Похоже, Авангард не сидел без дела. Вся тюрьма забита узниками из Серебряного Рассвета. К тому времени, как мы прибыли, многие из них были уже мертвы, но некоторые еще дышали.$b$bЯ уже было собирался убить их, но потом решил, что пусть лучше эта честь достанется тебе. В частности, там остался один злющий ворген, убить его – одно удовольствие.', '', '', '', '', '', 'Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.', 19865);
INSERT INTO `quest_template_locale` VALUES (28650, 'ruRU', 'Приятный сюрприз', 'Командор Чумопал из Часовни Багрового Пламени приказал вам отправиться в ближайшее здание тюрьмы и уничтожить Галли Чвазниха, узника из Серебряного Рассвета.', 'Мы ворвались сюда, перевернули все вверх дном и направились к тюрьме. Но мы совершенно не ожидали увидеть там такого, $n. Похоже, Авангард не сидел без дела. Вся тюрьма забита узниками из Серебряного Рассвета. К тому времени, как мы прибыли, многие из них были уже мертвы, но некоторые еще дышали.$b$bЯ уже было собирался убить их, но потом решил, что пусть лучше эта честь достанется тебе. В частности, там остался один злющий гоблин, убить его – одно удовольствие.', '', '', '', '', '', 'Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.', 19865);
INSERT INTO `quest_template_locale` VALUES (28651, 'ruRU', 'Новобранец Элрет', 'Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.', 'Почему бы тебе не поговорить с новобранцем Элрет? Она состоит у меня на службе, и наверняка у нее найдется пара-тройка заданий, в которых ты $Gмог:могла; бы применить свои новые способности.', '', '', '', '', '', 'Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.', 25549);
INSERT INTO `quest_template_locale` VALUES (28652, 'ruRU', 'Смотритель Кайс', 'Поговорите со смотрителем Кайсом в Похоронном Звоне, что в Тирисфальских лесах.', 'У меня для тебя все. Но есть и другие, кому может понадобиться твоя помощь.$b$bВозможно, у смотрителя Кайса найдется задание для тебя. Поговори с ним прямо сейчас.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28653, 'ruRU', 'Жрец Тьмы Сарвис', 'Поговорите со жрецом Тьмы Сарвисом в Похоронном Звоне, что в Тирисфальских лесах.', 'Ты все еще здесь, $n? Знаешь, я же только страж смерти. У меня не так уж много заданий для прохожих вроде тебя.$b$bЛучше обратись к жрецу Тьмы Сарвису. Помнится, он помогал мне встать на ноги, когда меня вырыли из вот этой могилы.$b$bЕго можно найти в часовне, в западной части Похоронного Звона.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28654, 'ruRU', 'Суть дела', 'Поговорите с Бранном Бронзобородом в Чертогах Созидания.', 'Эх, $gсынок:дочка;, мне бы тоже хотелось походить здесь с тобой, получше осмотреться... Тут есть на что поглазеть! Уж поверь мне на слово.$B$BЯ повидал на своем веку много чудесного и удивительного, но такого еще не видел.$B$BК сожалению, пока я не могу выбрать время для исследования Чертогов Созидания. Нужно сперва разобраться с этими дисками.$B$BКстати, ты, вроде бы, $gлюбознательный юноша:барышня любознательная;... Не хочешь посмотреть, как работают НАСТОЯЩИЕ археологи? Наверняка тебе будет интересно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28655, 'ruRU', 'Гремит-гуляет громовая свадьба', 'Скажите Грунди Макгреффу, что церемонию можно начинать. Разделайтесь с негодяями из Сумеречного Молота, которые попытаются прервать церемонию!', 'Все готово, $n, можно начинать!$B$BНаверняка культ Сумеречного Молота попробует воспрепятствовать церемонии, чтобы сломить дух и уничтожить клан Громового Молота. Здесь может начаться та еще заварушка!$B$BПоэтому я решил сам провести церемонию, чтобы жених и невеста держались поближе ко мне. Как тебе идейка? Отлично!$B$BПоскольку отец Фанни мертв, а брат у нас уже шафер, она попросила тебя сопроводить ее к алтарю. Великая честь, между прочим! Скажи, когда будешь $gготов:готова;, и мы начнем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28656, 'ruRU', 'Странные жизненные силы', 'Поговорите со знахаркой Мау\'ари в Зимних Ключах, в Снегоноре.', 'Когда это существо умерло, из его тела высвободилась некая энергия. Она перешла к вам, и теперь вы чувствуете прилив сил.$B$BЖители Зимних Ключей утверждают, что больше всего про местных зверей знает знахарка Мау\'ари, которая живет в Снегоноре. Возможно, ей что-то известно про эту загадочную энергию.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28657, 'ruRU', 'Гигантская проблема', 'Избавьтесь от Проблима, гигантского эттина, бродящего по тропам Тол Барада.', 'Стоило нам захватить этот проклятый остров, как в окрестностях тут же обнаружился гигантский эттин, который стал нападать на наши патрули!$B$B$n, договорись с друзьями и подкарауль этого громилу. Нельзя допустить, чтоб такое чудище разгуливало на свободе и сеяло разрушения.$B$BБудь $gосторожен:осторожна;, мне донесли, что он вооружен огромным поленом, которое любит пускать в дело.', '', 'Ну и зверюга.', 'Проблим', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28658, 'ruRU', 'Припасы на болоте', 'Вам нужно собрать 8 шкур толбарадских кроколисков. Кроколиски обитают на болоте к западу от крепости Барадин.', 'В подобном месте сложно пополнить припасы, |3-6($c). Мы безуспешно пытались найти что-либо пригодное с тех пор, как попали на этот остров.$B$BК счастью, только что лазутчики доложили, что на болоте к западу от лагеря водится много кроколисков. Их шкуры, несомненно, пригодятся нашим кожевникам. Принеси столько шкур, сколько сможешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28659, 'ruRU', 'Окончательная зачистка', 'От вас требуется убить 12 пехотинцев Альянса на Тол Бараде. Укрепления Альянса на Тол Бараде расположены на Шлакозаводе, Посту Стража и в Железном гарнизоне.', 'Мы стойко сражались, чтобы захватить этот остров, |3-6($r). Нам удалось уничтожить большую часть паршивцев из Альянса, но я все еще чую их мерзкий дух в окрестностях.$b$bПоручаю тебе провести разведку на Шлакозаводе, на Посту Стража и в Железном гарнизоне. Убей всех представителей Альянса, которых обнаружишь.$b$bКак гласит народная мудрость, хороший враг – мертвый враг.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28660, 'ruRU', 'Очищение Проклятых глубин', 'Вам поручено убить 9 любых призраков в Проклятых глубинах, расположенных к востоку от крепости Барадин.', 'Твое присутствие воодушевляет нас, $n. Битва за Тол Барад только началась.$B$BК востоку отсюда мы обнаружили темницу, которую следует освободить от нечисти. В ней находится множество призраков, которые томятся там уже долгое время.$b$bУбей столько нечисти, сколько сможешь, и доложи мне о выполненном задании.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28661, 'ruRU', 'Верховный маг в заточении', 'Убейте верховного мага Галия в Проклятых глубинах к востоку от крепости Барадин и заберите его посох.', 'Мы пытались зачистить тюремный блок в Проклятых глубинах со времен высадки на Тол Бараде. Всякий раз, как мы приближаемся к этой цели, появляется верховный маг, который рушит все наши планы.$B$BСейчас же, когда остров в наших руках, стоит попробовать снова. Направляйся вниз и доставь мне его посох в доказательство выполнения задания.', '', 'Недолго ему осталось владеть этим посохом.', 'Верховный маг Галий', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28662, 'ruRU', 'Уроки прошлого', 'Найдите 4 пыльных тюремных журнала в Проклятых глубинах к востоку от крепости Барадин.', 'Теперь, когда мы закрепились на этом проклятом острове, нужно попытаться установить, что его привело к нынешнему состоянию. Наши воины обнаружили несколько журналов с записями, разбросанных вблизи входа в тюремный блок в Проклятых глубинах к западу отсюда.$B$BЭти журналы представляют особый интерес для наших старейшин. Как можно быстрее отыщи четыре журнала и доставь их в лагерь.$B$BБудь $gосторожен:осторожна;, $n: в той местности бродит много нежити.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28663, 'ruRU', 'Блок Д', 'Вам поручено уничтожить 10 любых демонов, обитающих в блоке Д, который находится к северо-западу от крепости Барадин.', 'Ты уже $gслышал:слышала; о блоке Д, $n? Это один из старых тюремных блоков, находящихся на острове. Дело в том, что его заселили демоны. Мы рассчитывали разместить там пленных из Альянса, захваченных на острове, но при текущем раскладе это невозможно.$B$BЯ хочу, чтобы ты $gпомог:помогла; нам очистить блок от демонов. Отрапортуй мне о выполнении приказа.', '', '', '', '', '', 'Доложите военному инструктору Разготу в крепости Барадин о выполнении задания.', 19865);
INSERT INTO `quest_template_locale` VALUES (28664, 'ruRU', 'Сварнос', 'Расправьтесь со Сварносом в Блоке Д и заберите проклятый ошейник Сварноса. Монстр находится в Блоке Д к северо-западу от крепости Барадин.', 'Ты отлично $gпотрудился:потрудилась; при захвате острова, |3-6($c). Теперь, когда он в наших руках, предстоит подготовить камеры к приему заключенных. Блок Д доставляет нам особенно много проблем в плане зачистки. К сожалению, его заполонили демоны всех мастей.$B$BНам удалось совладать с большинством, но из одной камеры сбежала большая гончая недр, которая теперь бесчинствует в тюремном блоке. Я хочу, чтобы ты $gубил:убила; ее и $gдоставил:доставила; мне ее ошейник.', '', '', 'Сварнос', '', '', 'Доложите военному инструктору Разготу в крепости Барадин о выполнении задания.', 19865);
INSERT INTO `quest_template_locale` VALUES (28665, 'ruRU', 'Проклятые кандалы', 'Соберите 8 проклятых кандалов в Блоке Д, что находится к северо-западу от крепости Барадин.', 'Ты уже $gбывал:бывала; в Блоке Д, $n? Всякий раз как мы очищаем этот блок, демоны быстро заселяют его снова. Мы установили, что они возрождаются за счет проклятых кандалов, разбросанных по блоку. Вот тут-то ты нам и пригодишься, $n.$B$BСобери столько кандалов, сколько сможешь, и принеси их мне. Мы их немедленно уничтожим.', '', '', '', '', '', 'Доложите военному инструктору Разготу в крепости Барадин о выполнении задания.', 19865);
INSERT INTO `quest_template_locale` VALUES (28666, 'ruRU', 'Воззвание к героям: Пылающие степи!', 'Обратитесь к Джону Джею Кишану в Лагере Пламени Звезд в Пылающих степях.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к Джону Джею Кишану в Лагерь Пламени Звезд.$B$BСрочно требуется ваша помощь в обуздании орков Черной горы!$B$BПылающие степи находятся за Черной горой к югу от Тлеющего ущелья. Лагерь Пламени Звезд расположен на дальней стороне горы.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28667, 'ruRU', 'Приказ вождя: Пылающие степи!', 'Обратитесь к Ариоку в Лагере Пламени Звезд в Пылающих степях.', 'Всем годным к службе членам Орды надлежит явиться к Ариоку в Лагерь Пламени Звезд.$B$BАриок, сын почтенного Эйтригга, нуждается в вашей помощи, чтобы остановить агрессию орков Черной горы, стремящихся захватить близлежащие земли.$B$BПылающие степи находятся за Черной горой к югу от Тлеющего ущелья. Лагерь Пламени Звезд расположен на дальней стороне горы.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28668, 'ruRU', 'Тюремный бунт', 'Вам поручено убить 10 любых узников в Яме, расположенной к юго-западу от крепости Барадин.', 'Теперь, когда остров находится в наших руках, предстоит тяжкая работа. Нам удалось обнаружить заброшенный тюремный блок к юго-западу отсюда, который нужно проверить, $n.$B$BПо донесениям разведки заключенные, томившиеся в заточении годами, захватили блок. Прими все необходимые меры по зачистке этого места. Доложи мне о результатах операции.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28669, 'ruRU', 'Тюремщик', 'Вам нужно устранить стража Сильву в Яме и забрать его связку ключей. Яма находится к юго-западу от крепости Барадин.', 'Мы почти расправились с заключенными-бунтовщиками в Яме, однако остается еще одна нерешенная проблема. Тюремщик.$b$bСтраж Сильва – глава бунтовщиков, и узники готовы на все ради него. Стоит убрать его, и мы обуздаем всех остальных. Прикончи его и принеси мне связку ключей, которую он носит с собой. Ключи помогут нам проникнуть в глубину блока и, может быть, отыскать источник водоснабжения.', '', 'Пора отправить тюремщика в досрочный отпуск.', 'Страж Сильва', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28670, 'ruRU', 'Баланда', 'От вас требуется достать 12 тюремных пайков в Яме, расположенной к юго-западу от крепости Барадин.', 'Мы испытываем нехватку провизии, $n. Только что поступило донесение, что в тюремном блоке к юго-западу отсюда хранится большое количество тюремного пайка, сохранившегося с прошлых лет. Собери столько еды, сколько сможешь, и доставь ее в лагерь.$B$BИ еще кое-что: тюремный блок кишит заключенными, так что будь $gбдителен:бдительна;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28671, 'ruRU', 'Приказ вождя: Выжженные земли!', 'Поговорите с Окриллой в форте Молота Ужаса, что находится в Выжженных землях.', 'Настоящим повелением всем членам годным к службе членам Орды приказано явиться к Окрилле в крепость Стражей Пустоты.$B$BОкрилла, командующая силами Орды в указанной крепости, нуждается в вашей помощи, чтобы защитить наш оплот от посягательств мятежных огров и войск Альянса.$B$BВ крепость Стражей Пустоты можно попасть, отправившись на юг по дороге, следующей из Болота печали.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28672, 'ruRU', 'Палач на поле боя', 'Отчитайтесь палачу Аррену.', 'У меня заданий столько, что тебе хватило бы на неделю... но ты, кажется, $gлюбитель:любительница; сражений.$b$b<Элрет оценивающе смотрит на вас и кивает.>$b$bДа, ты подойдешь. Отправляйся к палачу Аррену. Выходи из Похоронного Звона на север. Найдешь его сразу за баррикадами.', '', '', '', '', '', 'Поговорите с палачом Арреном в Похоронном Звоне, что в Тирисфальских лесах.', 25549);
INSERT INTO `quest_template_locale` VALUES (28673, 'ruRU', 'Воззвание к героям: Выжженные земли!', 'Поговорите с интендантом Лунгерцом в крепости Стражей Пустоты.', 'По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса приказано явиться к интенданту Лунгерцу в крепость Стражей Пустоты.$B$BГарнизон крепости нуждается в вашей помощи, чтобы остановить продвижение Орды в Выжженные земли! В крепость Стражей Пустоты можно попасть, отправившись на юг по дороге, следующей из Болота печали.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28674, 'ruRU', 'Деревня Звездопада', 'Поговорите с Вундом Ночным Охотником в деревне Звездопада.', 'Если хочешь сделать доброе дело или просто немного подработать, то есть кое-что интересное.$B$BК северо-западу от Круговзора находится селение ночных эльфов – деревня Звездопада. Недавно там случилось нашествие каких-то жуков, и местные жители не могут справиться с этими тварями. Им нужна помощь.$B$BПара местных гоблинов уже отправилась на борьбу с жуками, но думаю, там найдется работа и для тебя. Поговори с Вундом Ночным Охотником, он сообщит тебе все подробности.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28675, 'ruRU', 'Воззвание к героям: Болото печали!', 'Явитесь к торговому барону Сереблексу в Веслотопи на Болоте печали.', 'По приказу его величества короля Андуина Ринна все подданные Альянса, способные держать оружие, должны явиться к торговому барону Сереблексу в Веслотопь.$B$BАрмии Альянса срочно необходимо снабжение! Вы должны сделать все возможное, чтобы убедить барона продолжать поставки амуниции по разумным ценам.$B$BЧтобы добраться до Веслотопи, следуйте по дороге из юго-восточной части Пылающих степей через Красногорье.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28676, 'ruRU', 'Экстерминаторы за работой', 'Поговорите с Ринно Гориштором в берлоге Бен\'Таллоу.', 'Эти жуткие невиданные твари захватили нашу берлогу практически за одну ночь. Они заполонили все туннели, вылупляясь из невидимых яиц.$B$BМы не даем им выбраться наружу, но нас слишком мало, чтобы дать им достойный отпор. Нам пришлось нанять гоблинов из Круговзора – они утверждали, что являются мастерами по уничтожению паразитов. Но пока им не удалось справиться с жуками.$B$BЕсли хочешь помочь им, войди в берлогу, что к западу отсюда, и поговори с Ринно Гориштором.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28677, 'ruRU', 'Приказ вождя: Болото печали!', 'Явитесь к торговому барону Сереблексу в Веслотопи на Болоте печали.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к торговому барону Сереблексу в Веслотопь.$B$BЛюбыми средствами убедите барона продолжить поставки оружия и боеприпасов нашей армии в необходимом объеме!$B$BДля того чтобы попасть на Болото печали, следуйте по дороге из Пылающих степей на юго-восток, минуя Красногорье. После прибытия на место отыщите барона в его курортной резиденции.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28678, 'ruRU', 'Капитан П. Харрис', 'Вас просят убить капитана П. Харриса на мысе Потерянной Надежды. Мыс расположен к северо-западу, если идти вдоль береговой линии. Ищите обломки корабля.', 'Мыс Потерянной Надежды уже долгое время стоит у нас как кость в горле. Половина кораблей с провиантом для Тол Барада разбивается внизу о скалы.$b$bЧто еще хуже, так это неупокоенные моряки, докучающие нам. Мы пробовали расправиться с ними, да только они приходят все снова и снова. Последняя надежда – убить капитана, которому они подчиняются. Ты найдешь его на корабле, причалившем к берегу.$b$bНадеюсь, ты не очень боишься акул?', '', 'Убей капитана, и его подчиненные обратятся в бегство.', 'Капитан П. Харрис', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28679, 'ruRU', 'Раздробить косточки', 'Третий офицер Кронкар поручил вам уничтожить 8 моряков-утопленников на мысе Потерянной Надежды. Мыс расположен к северо-западу от лагеря.', 'Уже долгое время нас беспокоит нежить с мыса Потерянной Надежды. Всякий раз, как разбивается корабль, ее воинство пополняется новыми душами.$b$bТы не $gмог:могла; бы оказать нам услугу, уничтожив несколько неупокоенных врагов? Знаю, что всех их истребить невозможно, но так ты хоть немного облегчишь нашу задачу.$b$bОстерегайся солдат Альянса. Поступают донесения о том, что они устраивают засады вдоль береговой линии.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28680, 'ruRU', 'Поддержание боевого духа', 'Вас попросили доставить 6 бочонков южноморского рома с кораблей, затонувших у мыса Потерянной Надежды. Мыс расположен севернее на береговой линии.', 'Наши войска деморализованы, $n. Мы прилагаем все усилия, чтобы поддерживать в солдатах боевой дух, вот только главная составляющая успеха – ром – подходит к концу.$b$bПехотинцы с южного побережья докладывают, что в трюмах кораблей, затонувших у мыса Потерянной Надежды, хранится хороший запас рома. Не $gмог:могла; бы ты проверить, так ли это?$b$bПринеси весь ром, что сможешь найти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28681, 'ruRU', 'Акула Амбал', 'Вам поручено убить Амбала, гигантскую акулу, плавающую в водах у мыса Потерянной Надежды. Мыс расположен севернее, если идти вдоль береговой линии.', 'Ненавижу акул. И все мои солдаты тоже. Тут-то ты нам и пригодишься, $n.$b$bПоднимись к мысу Потерянной Надежды и убей гигантскую акулу по имени Амбал. Ее не стоит недооценивать, так что лучше прихвати с собой на подмогу парочку друзей.', '', 'У этой рыбины действительно огромные челюсти.', 'Амбал', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28682, 'ruRU', 'Взятие крепости', 'Вас просят убить начальника крепости Фарсона. Его крепость находится на северной стороне острова.', '$gВидел:Видела; крепость в северной части острова, $n? Там обосновался некий Фарсон.$b$bФарсон со своими немногочисленными приспешниками докучают нам с тех пор, как мы пришли в эти места. Мы отправили в разведку небольшой отряд, который установил точное местоположение Фарсона в крепости.$b$bТы поможешь нам покончить с ним?', '', 'У него преданные подчиненные. Не нужно их недооценивать.', 'Начальник крепости Фарсон', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28683, 'ruRU', 'Очищение леса', 'Убейте 12 скрытней Мрачного леса. Мрачный лес находится за мостом, к северу отсюда, в центральной части острова.', 'Мы неделями пытаемся зацепиться в Мрачном лесу, но он просто кишит пауками. Окажи мне услугу, перебей эту гадость, чтобы мы могли подготовиться к нападению.$b$bБудь $gбдителен:бдительна;, когда доберешься до леса, а то мне тут на неделе доложили, что поблизости орудует Альянс.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28684, 'ruRU', 'Липкая работа', 'Соберите 4 липких паутинных железы праматерей Мрачного леса. Чтобы попасть в лес, находящийся в центральной части острова, пересеките мост к западу от лагеря.', 'Непросто было найти припасы на острове, скажу я тебе.$b$bК счастью, к северу отсюда, в Мрачном лесу, нам удалось обнаружить хороший источник шелка. Плохая новость – это то, что шелк производят паучихи-праматери. Достань мне 4 паутинных железы праматерей.$b$bЭтого хватит, чтобы дошить последний комплект рубашек.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28685, 'ruRU', 'Забрать все оружие', 'Вам поручили забрать 12 ржавых винтовок из Крепости Фарсона, расположенной в северной части полуострова Тол Барад.', 'На этом острове сложно достать боеприпасы. Всякий раз, как на нас нападает Альянс, создается ощущение, что мы сражаемся с ними при помощи камней и палок.$B$BМне доложили, что у начальника крепости Фарсона на северной стороне острова есть винтовки, которые мы могли бы использовать. Ты не $gмог:могла; бы туда наведаться?$b$bБудь $gосторожен:осторожна;, $n, приспешники Фарсона сделают все, чтобы защитить его.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28686, 'ruRU', 'Неприветливый город', 'Командир Лармаш поручил вам расправиться с 14 жителями Растберга. Растберг расположен в правой части острова, к северу от лагеря.', 'Ты уже $gбывал:бывала; в Растберге, $n? Советую припасти нож за пазухой, если пойдешь в те края.$b$bТамошние жители вроде бы не доставляют хлопот, вот только что-то странное там творится. Мне докладывают о том, что там периодически пропадают наши солдаты. Нам это порядком поднадоело, поэтому тебе следует отправиться в этот вертеп и навести там порядок.$B$BПеребей там столько народу, сколько сможешь, и отчитайся передо мной о проделанной работе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28687, 'ruRU', 'Научи человека ловить рыбу... Или красть ее!', 'Вам нужно украсть 22 растбергских окуня. Рыба сушится на нитях на специальных стойках у причала за деревней. Растберг расположен на северо-востоке острова, к северу от лагеря.', 'Растберг. Это место – одновременно наше проклятье и благословение, $n. Понятия не имею, где эти разбойники научились ловить рыбу, но это и не важно.$B$BОтправляйся к ним в логово и укради столько рыбы, сколько сможешь. Мы питаемся всякими отбросами с тех пор, как вновь заняли этот остров, поэтому было бы неплохо пополнить запасы провизии.$B$BБудь $gосторожен:осторожна;, мне доложили, что в деревне нас может поджидать засада.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28688, 'ruRU', 'Приказ вождя: Северная Тернистая долина', 'Явитесь к командиру Агро\'рошу в лагере Гром\'гол, что в Северной Тернистой долине.', 'Настоящим повелением всем годным к службе воинам Орды приказано явиться к командиру Аггро\'гошу, находящемуся в Лагере Гром\'гол. Командиру требуется ваша помощь в обеспечении безопасности путей снабжения и борьбе с докучающими членами Альянса и местными жителями.$B$BДля того чтобы добраться до лагеря, можно воспользоваться дирижаблем, отправляющимся с башни за Оргриммаром, или еще одним, отбывающим из окрестностей Подгорода.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28689, 'ruRU', 'Позабытые', 'Освободите 6 истерзанных душ на Забытом холме. Душу можно высвободить, дотронувшись до могильного камня. Забытый холм расположен к западу отсюда, за Передовой Неупокоенных.', 'На этом острове погибло много солдат, $n. Наш долг – почтить их память.$b$bОтправляйся на Забытый холм, что к западу отсюда, и освободи души наших братьев по оружию, томящиеся там. Будь $gосторожен:осторожна;, по донесениям в тех местах бесчинствует нежить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28690, 'ruRU', 'Спасение останков', 'От вас требуется собрать 9 проклятых бедренных костей вурдалаков, населяющих Забытый холм. Это место расположено на западной стороне острова за Передовой Неупокоенных.', 'На Забытый холм покушаются зомби и вурдалаки c тех самых пор, как мы обосновались на этом проклятом острове. Мы многократно пытались очистить его от нежити, но безуспешно.$b$bОдин офицер посоветовал нам собирать кости вурдалаков, чтобы те еженощно не восставали из мертвых. Не подсобишь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28691, 'ruRU', 'Старший лейтенант Коннор', 'Обнаружьте и убейте старшего лейтенанта Коннора на Забытом холме. Это место расположено в западной стороне острова.', 'Я впервые услышал о лейтенанте Конноре, когда был простым новобранцем в Огненной Пропасти. Никто бы не поверил, что он очутится здесь, на Тол Бараде. К сожалению, он все еще бродит по этим проклятым островам, сея смуту в наших войсках.$b$bПоложи конец его страданиям, а заодно и нашим.', '', 'Никто не хочет заканчивать тут свои дни, но жизнь порой складывается помимо нашей воли.', 'Старший лейтенант Коннор', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28692, 'ruRU', 'Как работают магниты?', 'Вам поручили собрать 7 фрагментов осадных машин. Используйте намагниченный сборщик металлолома на Передовой Неупокоенных, расположенной на западе за вторым мостом.', 'На остров сложно доставить полезные запчасти, $n. Мы пытались на месте починить сломанные осадные машины, но у нас закончились необходимые детали.$b$bИз второго полка доложили об искореженных осадных машинах, стоящих на заброшенном поле боя к западу отсюда. Может быть, там остались какие-то пригодные запчасти?$b$bСложно будет отыскать что-то в груде обломков, так что возьми-ка этот намагниченный сборщик металлолома и воспользуйся им.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28693, 'ruRU', 'Завершение работы', 'От вас требуется уничтожить 5 неупокоенных солдат на Передовой Неупокоенных. Это место расположено на западной стороне острова на подступах к Забытому холму.', 'Всю неделю мы пытались принести пригодные запчасти с Передовой. И всякий раз, когда мы несли детали в лагерь, на нас нападали неупокоенные солдаты. Ты бы не $gсогласился:согласилась; расчистить наш путь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28694, 'ruRU', 'Щепки летят!', 'Рядовой Сарлоск хочет, чтобы вы принесли 15 единиц лесоматериалов с Верфи Веллсона. Доски можно отнять у призраков, обитающих на верфи, или поднять с земли. Верфь находится на берегу к северо-западу отсюда.', 'Ты уже $gбывал:бывала; на Верфи Веллсона, $n? Без особой нужды лучше держаться от нее подальше. К сожалению, именно туда тебе и придется пойти.$b$bВидишь ли, мы испытываем нехватку припасов с тех самых пор, как высадились на острове. На верфи находится много лесоматериалов, но обжившие ее призраки всякий раз мешают нам забрать их оттуда.$b$bТы не $gмог:могла; бы нам помочь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28695, 'ruRU', 'Разыскивается: начальник верфи Веллсон', 'Вам предстоит прикончить начальника верфи Веллсона. Верфь расположена к северо-западу отсюда, на западном побережье острова.', 'Начальник верфи Веллсон докучает нам с тех самых пор, как мы попали на остров. На его верфи находится масса припасов, которые бы нам пригодились... если бы мы до них добрались.$b$bОн бдительно следит за своими подчиненными, что осложняет нашу задачу. Итак, я хочу, чтобы ты $gпокончил:покончила; с Веллсоном. Остерегайся солдат Альянса, бесчинствующих в округе, $n.', '', 'Когда-то великий человек, а нынче падший начальник пристани Веллсон.', 'Начальник верфи Веллсон', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28696, 'ruRU', 'Пушки к бою!', 'Уничтожьте 10 мрачных суден снабжения.', 'На Верфь Веллсона по морю постоянно поступают припасы, и нужно положить этому конец. Враг расставил пушки по периметру верфи в целях защиты, но мы обернем это против него: воспользуемся пушками, чтобы уничтожить суда снабжения.$B$BОтправляйся туда и посмотри, что можно сделать. Доложи мне о результатах операции.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28697, 'ruRU', 'Охота за привидениями', 'Вам нужно убить 14 любых призраков в Дозорном пункте Ларго к северо-востоку от лагеря Орды.', 'Видишь гору за нашим лагерем? На ней находится Дозорный пункт Ларго, так что мы выбрали не лучшее место для пристанища. Мы отбиваемся от духов и призраков с того времени, как разбили тут лагерь.$b$bНе $gмог:могла; бы ты наведаться туда и дать им понять, что мы не собираемся никуда уходить? Убей несколько врагов, чтобы донести до них наше послание.$b$bБлагодарю за услугу, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28698, 'ruRU', 'Пушечное ядро!', 'Соберите для рядового Сарлоска 4 груды пушечных ядер, хранящихся на Дозорном пункте Ларго. Он находится к северо-востоку от лагеря.', 'Ларго со своими проходимцами воруют наши боеприпасы с тех самых пор, как мы разбили тут лагерь. Это крайне раздражает.$b$bНам донесли, что Ларго складирует пушечные ядра в башнях, стоящих над водой на его Дозорном пункте. Достанешь нам немного ядер?$b$b$n, остерегайся представителей Альянса.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28699, 'ruRU', 'Воззвание к героям: Северная Тернистая долина', 'Явитесь к лейтенанту Дорену в Лагере Повстанцев, что в Северной Тернистой долине.', 'По приказу его величества короля Андуина Ринна все подданные Альянса, способные держать оружие, должны явиться к лейтенанту Дорену в лагерь мятежников.$B$BГоды прошли с тех пор, как полковник Курцен вероломно предал Штормград, но до сих пор мы не знаем об этом всей правды. Помогите уцелевшим выяснить, что сталось с полковником. Отправляйтесь из Сумеречного леса на юг, перейдите в джунгли и оттуда следуйте по дороге на запад, пока не доберетесь до лагеря мятежников.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28700, 'ruRU', 'Освобождение дозорной башни', 'Рядовой Сарлоск поручил вам ликвидировать Командира Ларго на Дозорном пункте Ларго. Это место находится к северо-востоку от лагеря.', 'Существует единственный способ захватить Дозорный пункт Ларго.$b$bВ последнее время парень окончательно спятил: стоит себе на вершине башни и ждет, когда приплывет воображаемый флот. Так что найти его не составит труда.', '', 'Попробуй с ним справиться!', 'Командир Ларго', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28701, 'ruRU', 'В безопасности', 'Найдите 5 реликвий Звездопада в берлоге Бен\'Таллоу.', 'К счастью, когда жуки напали на берлогу, там не было друидов. Но мы не можем его вот так просто сдать – это священное место, в нем хранятся многие древние артефакты.$B$BИ хотя я, в целом, доверяю этим гоблинам-истребителям, но... скажем так, кое-что знаю о повадках этого народа. Пожалуйста, собери в берлоге артефакты и принеси мне, пока кто-нибудь не повредил их. Урны с артефактами находятся в небольших альковах, их много по всей берлоге.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28702, 'ruRU', 'Воззвание к героям: мыс Тернистой долины', 'Обратитесь к Бронвину Зарубаю на Раскопки Лиги исследователей, что на мысу Тернистой долины.', 'По приказу его величества короля Андуина Ринна все подданные Альянса, способные держать оружие, должны явиться к Бронвину Зарубаю на Раскопки Лиги исследователей.$B$BЭкспедиции Лиги исследователей нужна ваша помощь для защиты от огров-мародеров. Из Северной Тернистой долины двигайтесь на юг по дороге к Раскопкам Лиги исследователей.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28703, 'ruRU', 'Добро пожаловать в мой курган', 'Убейте 10 холодных ползунов и 5 холодных землеглотов.', 'Я до сих пор не знаю, откуда взялись эти насекомые. По-видимому, катаклизм потревожил какие-то гнезда глубоко под землей.$B$BНо довольно об этом. Нам нужно уничтожить этих тварей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28704, 'ruRU', 'Приказ вождя: мыс Тернистой долины', 'Обратитесь к Хамми Кофельнагель в Укрытии Кофельнагель, что находится на мысе Тернистой долины.', 'Настоящим повелением всем годным к службе воинам орды приказано явиться к Хамми Кофельнагель, находящейся в Укрытии Кофельнагель. Она нуждается в вашей помощи в борьбе с пиратами и нагами, кишащими в джунглях.$B$BОтправляйтесь на юг в Укрытие Кофельнагель по дороге, ведущей из Северной Тернистой долины, и ищите город к юго-западу от арены Гурубаши.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28705, 'ruRU', 'Приказ вождя: Запределье!', 'Явитесь к генерал-лейтенанту Ориону на Ступень Судьбы, что на полуострове Адского Пламени.', 'Настоящим распоряжением всем годным к службе воинам Орды приказано явиться к генерал-лейтенанту Ориону на Ступени Судьбы.$B$BТребуется ваша помощь для противостояния Пылающему Легионому в раздробленном мире Запределья.$B$BОтправляйтесь в Расселину Теней в Оргриммаре и воспользуйтесь порталом у торговца ядами, чтобы попасть на полуостров Адского Пламени.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28706, 'ruRU', 'Распыляй!', 'Отнесите коробку с инсектицидными фумигаторами Ремме Гориштор в берлогу Бен\'Таллоу.', 'Мои сестры уже спустились в курган и сейчас пытаются разобраться с насекомыми. Но этих тварей слишком много. По-моему, пора применить газ.$b$bВозьми эти фумигаторы. Но только ничего с ними не делай: пользоваться ими должны только опытные профессионалы. Просто найди моих сестер и отдай фумигаторы им.$B$BРемма должна быть недалеко от входа. Иди вниз по коридору, а когда дойдешь до пандуса, держись правой стороны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28707, 'ruRU', 'Распыли снова!', 'Отнесите коробку с инсектицидными фумигаторами Марси Гориштор в берлогу Бен\'Таллоу.', 'Сейчас я все сделаю.$B$BТак, следующий фумигатор нужно отдать Марси – она находится чуть дальше. Иди вот по этому коридору, до следующей большой комнаты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28708, 'ruRU', 'Воззвание к героям: Запределье!', 'Явитесь к командиру Дарону на Ступени Судьбы, что на полуострове Адского Пламени.', 'По приказу его величества короля Андуина Ринна все подданные Альянса, способные держать оружие, должны явиться к командиру Дарону на полуостров Адского Пламени.$B$BНашим экспедиционным силам требуется помощь в борьбе с армиями демонов Пылающего Легиона! Воспользуйтесь порталом на верхнем уровне башни в квартале магов и отправляйтесь к Ступеням Судьбы в Запределье.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28709, 'ruRU', 'Воззвание к героям: Нордскол!', 'Доложите о своем прибытии вербовщику Блиту в Крепости Отваги, что в Борейской тундре.', 'По приказу его величества короля Андуина Ринна все подданные Альянса, способные держать оружие, должны явиться к вербовщику Блиту в Крепость Отваги, что в Борейской тундре.$b$bЭкспедиции Отважных требуется помощь, чтобы справиться с силами Плети и обеспечить безопасность населенных земель! Отправляйтесь в порт Штормграда, а там садитесь на корабль, идущий на север, в Крепость Отваги.$b$bЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28710, 'ruRU', 'Распыли еще раз!', 'Отнесите коробку с инсектицидными фумигаторами Сане Гориштор в берлогу Бен\'Таллоу.', 'Кто бы мог подумать, что помощником Ринно окажется |3-6($r)! Я надеялась, что это будет кто-то помощнее... Вечно этот Ринно пытается выехать на нашем горбу.$B$BСейчас я настрою этот фумигатор. А ты иди на север по коридору и найди Сану. Наверно, она заблудилась где-то в последней комнате, так что не забудь осмотреть все боковые ходы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28711, 'ruRU', 'Приказ вождя: Нордскол!', 'Доложите о своем прибытии вербовщику клана Песни Войны в Крепости Песни Войны, что в Борейской тундре.', 'Всем годным к военной службе подданным Орды надлежит явиться к вербовщику клана Песни Войны в Крепость Песни Войны.$b$bАрмии Песни Войны нужна твоя помощь, чтобы справиться с угрозой, исходящей от нежити Плети.$b$bСадись на дирижабль, отходящий от западной башни Оргриммара, отправляйся в Крепость Песни Войны и доложи о своем прибытии вербовщику.$b$bСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28712, 'ruRU', 'Королева драконов вступает в бой', 'Обратитесь к Лирастразе в Круге Жизни на Сумеречном нагорье.', 'Приветствую тебя, |3-6($r). Жаль, что мы встретились при столь удручающих обстоятельствах. Судьба нашего мира висит на волоске, и все, что сотворили Титаны, может в одночасье рухнуть.$B$BПечаль моя велика, но решение непоколебимо. Смертокрыл – жуткое создание, которое некогда было Хранителем Земли и моим другом – должен умереть.$B$BЯ подготовила место на вершине нагорья к западу от Гранатового редута, где я сумею совладать с ним. Разыщи Круг Жизни и обратись к Лирастразе – она ожидает тебя там. Я вскоре присоединюсь к вам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28713, 'ruRU', 'Природное равновесие', 'Убейте 6 молодых ночных саблезубов.', 'Привет, $n. Мое имя Илталайн. В Тенистой долине я учу таких, как ты, и забочусь о том, чтобы не нарушалось природное равновесие.$B$BВ этом году весна была очень дождливой, и в результате одни звери чувствуют себя прекрасно, а другие, наоборот, страдают. К сожалению, ночные саблезубы слишком расплодились: если ничего не предпринять, они истребят всю живность в этом лесу.$B$BИди же, |3-6($c), и уменьши численность саблезубов, чтобы в природе восстановилась гармония.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28714, 'ruRU', 'Мох скверны', 'Соберите 6 пучков мха Скверны, отобрав их у греллей, которые находятся к западу от Илталайна.', 'Похоже, ты знаешь, что делаешь. Значит, я могу дать тебе более важное поручение.$B$BНасколько тебе известно, Тельдрассил был очищен от порчи. Но все-таки там что-то осталось. Звери не успокоились, и местных жителей одолевают разные беды.$B$BИди на запад и разберись с тамошними греллями. Проверь, нет ли у них мха скверны. Это поможет мне понять, откуда здесь берется скверна.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28715, 'ruRU', 'Демонические воры', 'Найдите украденные у Мелитара сумки на западе, рядом с греллями.', 'Мерзкие грелли! Они снова воруют наши припасы.$B$BЯ почти уверен в том, что они спрятали мои сумки в своем лагере, к западу отсюда. Принеси мне эти сумки, и я с радостью награжу тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28716, 'ruRU', 'Воззвание к героям: Сумеречное нагорье!', 'Поговорите с королем Андуином Ринном в крепости Штормграда в Штормграде.', 'По приказу его величества короля Андуина Ринна все подданные Альянса, способные держать оружие, должны явиться в крепость Штормграда.$B$BКоролю Ринну нужна помощь достойных и преданных героев для выполнения задания чрезвычайной важности.$B$BКрепость расположена в восточной части Штормграда.$B$BЗа честь и славу Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28717, 'ruRU', 'Приказ вождя: Сумеречное нагорье!', 'Явитесь к верховному правителю Саурфангу – он ожидает вас в крепости Громмаш в Оргриммаре.', 'Всем годным к военной службе ордынцам приказано немедленно явиться к верховному правителю Саурфангу в крепость Громмаш.$B$BПравителю требуется ваша помощь в подготовке победоносного наступления на Сумеречное нагорье. Мы собираемся нанести удар по нашим врагам – Альянсу и культу Сумеречного Молота.$B$BПравитель ожидает вас в крепости Громмаш посреди Аллеи Силы в Оргриммаре.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28718, 'ruRU', 'Где дым, там и вкусное мясо', 'Найдите Джеза Скороцапа в коптильне Скороцапа, что в Зимних Ключах.', 'Слушай, |3-6($c)... ты любишь мясо? Нет, даже не так – ты любишь деньги? $B$BМой троюродный брат сколотил целое состояние, торгуя замороженным мясом. На севере у него коптильня, и он ищет тех, кто готов охотиться на опасных тварей, у которых такое вкусное мясо.$B$BЗа хищников можно выручить хорошие деньги, точно тебе говорю. У меня-то здесь дела – а вот |3-6($r) вроде тебя может неплохо заработать на этом.$B$BБрата зовут Джез. Иди на северо-восток и ориентируйся на дым!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28719, 'ruRU', 'Мясо с душком', 'Убейте 15 могучих щербозубов.', 'Многие утверждают, что у мяса щербозубов слишком резкий аромат. Я с этим не согласен, но, как говорится, о вкусах не спорят.$B$BА вот у могучих щербозубов – бурых братьев обычных щербозубов – у них мясо мягче, особенно на лапах. И, говорят, рыло считается деликатесом.$B$BПродолжай охотиться, $n, и принеси старому Фрэнсису несколько могучих щербозубов. Они живут к югу отсюда.', '', 'Вкус неплохой.', 'Фрэнсис Моркотт', 'Хороший попался медведь.', 'Фрэнсис Моркотт', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28721, 'ruRU', 'По вражеским тропам', 'Сопроводите заключенного Крепости Фарсона в безопасное место. Данная крепость расположена на северe острова.', 'За несколько недель мы послали уже три группы на разведку обстановки в Крепости Фарсона. К сожалению, ни одна из них не принесла никаких сведений.$B$BВ данный момент мы можем только уповать на то, что они живы и просто находятся в заключении. Я хочу, чтобы ты $gотправился:отправилась; в крепость и $gпомог:помогла; в освобождении наших солдат. Это будет непросто, $n, но именно ты в силах нам помочь.', 'Узник крепости Фарсона сопровожден', 'Кажется, ему нужна помощь.', 'Узник Крепости Фарсона', '', '', 'Доложите командиру Лармашу в Хватке Адского Крика о выполнении задания.', 25549);
INSERT INTO `quest_template_locale` VALUES (28722, 'ruRU', 'Йетифобия', 'Напугайте Легакки с помощью механического йети Уми.', 'Все готово, $n!$B$BЯ сказала своей подруге Легакки, что у меня для нее сюрприз. Но мне понадобится твоя помощь.$B$BЯ отдам тебе своего механического йети и предоставлю тебе честь ее удивить. Она сейчас на другом конце Круговзора, рядом с таверной.$B$BПодойди к ней и включи йети... А я буду следить за вами отсюда!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28723, 'ruRU', 'Жрица луны', 'Поговорите с Дентарией Серебристой Поляной в центре Тенистой долины между двумя водоемами.', 'Возможно, ты захочешь помочь нам очистить Тенистую долину от порчи.$B$BДентария Серебристая Поляна, жрица Луны, предложила нам свою помощь. Она находится между двумя водоемами, к северу от нашего великого дерева. Обойди дерево, |3-6($c), найди жрицу и сделай все, о чем она тебя попросит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28724, 'ruRU', 'Противоядие для Иверрона', 'Соберите 7 лунных лилий.', 'Нашего друга Иверрона покусали местные пауки и отравили его своим ядом. Я могу поддерживать Иверрона в его нынешнем состоянии, но для приготовления противоядия мне нужна твоя помощь.$B$BПо берегам этих водоемов растут лунные лилии. Они обладают целебными свойствами, и я могу объединить их с другими ингредиентами и сделать противоядие для Иверрона.$B$BПожалуйста, набери этих лилий. В здешних краях их много, можно увидеть даже отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28725, 'ruRU', 'Защитница леса', 'Найдите дриаду по имени Тариндрелла в Паучьем логове в северной части Тенистой долины.', 'Я хочу поручить тебе более опасное дело. Духи леса сообщили мне нечто очень странное. Тариндрелла, загадочная защитница леса, снова вернулась в Тенистую долину. $B$BА ведь ее присутствия не ощущали здесь со времен благословения Тельдрассила. И если она решила снова прийти сюда, значит, здесь творится что-то неладное.$B$BОтправляйся на север, в Паучье логово, и найди там Тариндреллу. Это опасное место, так что на всякий случай мы приготовим это противоядие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28726, 'ruRU', 'Оскверненные пауки', 'Убейте 12 чащобных тенетников.', 'Я надеялась, что мне никогда не придется возвращаться в Тельдрассил по такому страшному поводу. Думала, эта земля полностью очищена от порчи. Но зло все-таки здесь осталось.$B$BЭти пауки пострадали от порчи гораздо больше, чем другая живность. Они представляют опасность как для твоего народа, так и для всего леса. Мы должны сократить их численность, но еще важнее обнаружить источник скверны.$B$BЯ пойду с тобой и помогу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28727, 'ruRU', 'Зловещее прикосновение', 'Убейте Гитьис Зловещую в северной части Паучьего логова.', 'Если у этих пауков от рождения в жилах скверна, значит, источник этой заразы – их мать.$B$BДавай доберемся до северной части пещеры и найдем Гитьис Зловещую. Ответ на наш вопрос находится в ней.', '', 'Гитьис знает, откуда взялась порча в Тенистой долине и в остальных частях Тельдрассила.', 'Гитьис Зловещая', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28728, 'ruRU', 'Видения будущего', 'Поговорите с Дентарией Серебристой Поляной между двумя водоемами в центре Тенистой долины.', 'Я пойду по следу Кривой Сосны и найду источник этой скверны. Если в Доланааре ты встретишь Атридаса Медвежью Шкуру, расскажи ему все. Ему прекрасно знакомы все беды этого леса, и он сможет дать тебе дельный совет.$B$BДумаю, мы еще встретимся. Если я обнаружу источник скверны, то, возможно, ты поможешь мне его ликвидировать. А пока что я отведу тебя обратно к Дентарии, и ты продолжишь свое обучение. Спасибо за все, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28729, 'ruRU', 'Телдрассил: венец Азерота', 'Наполните хрустальный фиал водой из лунного колодца в северо-восточной части Тенистой долины.', 'Если ты хочешь закончить обучение здесь, в Тенистой долине, то тебе нужно узнать больше о нашей истории.$B$BПоэтому я прошу тебя выполнить одно задание. Иди на северо-восток, к нашему лунному колодцу. Набери из него воды в этот пузырек. Пока ты будешь там, сможешь увидеть проявления нашей магии и узнать о нашей истории.$B$BКогда закончишь, принеси воду мне, и я скажу, что нужно делать дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28730, 'ruRU', 'Драгоценные воды', 'Отдайте наполненный хрустальный фиал Тенарону Хватке Бури на вершине Альдрассила в Тенистой долине.', 'Тенарон Хватка Бури следит за всем, что происходит в долине. Он сидит на вершине Альдрассила.$B$BЕсли посмотришь на юг, то увидишь помост, который ведет к нему. Поднимись по этому помосту и заверши свое обучение.$B$BМне было приятно познакомиться с тобой, $n. Меня переполняет гордость при мысли о том, что среди молодых ночных эльфов есть такие самоотверженные и полные энергии, как ты. Ты совершишь великие подвиги во славу нашего народа.$B$BДо встречи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28731, 'ruRU', 'Тельдрассил: утраченное знание', 'Отнесите частично наполненный сосуд Коритрасу Лунному Гневу в Доланаар.', 'Я мог бы поведать тебе еще многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждет тебя. Я перелил воду из фиала, принесенного тобой, в этот сосуд, чтобы ты $gотнес:отнесла; его Коритрасу.$b$bТы найдешь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернет на запад, следуй по пути, мощенному булыжниками.$b$bИ советую тебе не сходить с дороги, $n, – в последнее время в лесу появились опасные существа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28732, 'ruRU', 'Это может значить только одно...', 'Прокатитесь на буровой установке Вентурона до Черной горы.', 'Нас с Разом завербовали Стражи Хиджала, чтобы мы установили обстоятельства возвращения Рагнароса в наш мир. Смею доложить, что Рагнарос действительно вернулся, и он очень зол! Мы также получили доказательства того, что сектанты из культа Сумеречного Молота перемещают элементалей по Восточным королевствам в Пещеры Черной горы.$B$BМы с Разом как раз собирались направиться в то место, чтобы разведать обстановку. У нас в буровой машине как раз найдется местечко для тебя. Залезай внутрь да поедем.', 'Доберитесь до Пещер Черной горы.', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28733, 'ruRU', 'Основы ботаники', 'Выдержите 1 внушительную волну наступления зомби.', 'На помощь! Помогите! Свихнувшаяся нежить атакует мою ферму! Наверняка это дело рук того ненормального надзирателя с Топких полей. Помоги мне отбиться от этих зомби!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28734, 'ruRU', 'Просьба Мелитара', 'Идите в Тенистую долину и поговорите с Мелитаром Оленьим Шлемом.', 'Тебе нужно поговорить с Мелитаром. Кажется, у него уже были какие-то проблемы с греллями.$B$BЕсли ты поможешь ему, то, возможно, он выделит тебе место для хранения товаров.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28735, 'ruRU', 'В Чертог Испепеления!', 'Прикончите Ром\'огга Костекрушителя.', 'Это была засада, $n! Как только мы вошли внутрь, на нас накинулся фантастически жирный огр по имени Ром\'огг Костекрушитель! Раз отважно бросился защищать меня, а я побежал прочь в укрытие. Я видел, как они вначале избили, а потом потянули его, еле дышащего, в место, которое огр назвал \"Чертогом Испепеления\". Думаю, оно находится в зале за мостом.$B$BМне слишком страшно идти туда. Возьми-ка мой универсальный шлем и попробуй отыскать Раза. Я буду держать с тобой связь через этот шлем.$B$BЕсли найдешь жуткого огра, прикончи его!', '', 'Ходячий жирный окорок, что похитил Раза.', 'Ром\'огг Костекрушитель', 'Найди Раза!', 'Айс Вентурон', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28736, 'ruRU', 'Огонь с высот', 'Запрыгивайте на конфискованное орудие и расстреляйте из него 100 пехотинцев Шнотца.', 'Недобитки Шнотца укрепились здесь, на Возвышении Творца. Из-за этого всем, кто окажется поблизости, грозит смертельная опасность.$B$BСнарядов у нас тут хватает, но без хорошего наводчика мне приходится палить вслепую.$B$BНу-ка, запрыгивай и помоги мне. Застанем его солдат врасплох!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28737, 'ruRU', 'Что это за место?', 'Убейте глашатая сумрака Корлу', '<Шлем Вентурона гудит от напряжения.>$B$BЧто это за место? Похоже, что они творят с драконом Пустоты нечто ужасное. Энергия, высасываемая из бедного существа, устремляется к той женщине! Нужно прервать ритуал!$B$BУстрани Корлу, чтобы пройти сквозь этот зал!', '', 'Она выглядит зловеще!', 'Глашатай сумрака Корла', 'Время на исходе! Разу нужна наша помощь!', 'Айс Вентурон', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28738, 'ruRU', 'Сумеречная кузня', 'Прикончите Карша Гнущего Сталь.', '<Шлем Вентурона гудит от напряжения.>$B$BПроклятье! Раз все не угомонится! Его словно обуяла ярость по отношению ко всему, что связано с культом Сумеречного Молота! Похоже, что для того, чтобы пройти эту комнату и добраться до Раза, нам придется ликвидировать бронника культа Сумеречного Молота по имени Карш Гнущий Сталь. Прикончи его поскорее, $n.', '', 'Похоже, что он действительно гнет сталь руками.', 'Карш Гнущий Сталь, бронник Сумеречного Молота', 'Раз где-то рядом. Я его слышу!', 'Айс Вентурон', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28739, 'ruRU', 'Night Elf Class Skill Tracker Quest', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (28740, 'ruRU', 'Не верь глазам своим', 'Убейте Красавицу.', '<Шлем Вентурона взрывается, издавая громкий пищащий звук.>$B$BНе может быть! Я... Я застрял в одной из этих тварей почти на месяц. Да, именно застрял в чреве чудовища. Если бы не спецкостюм и универсальный шлем, то я бы просто сгорел дотла! И посмотри-ка сюда, у чудовища тут целый выводок!$B$BТы $Gдолжен:должна; с ней расправиться, $n! Мы не можем допустить, чтобы потомство монстра разгуливало на свободе!', '', 'Порождение зла!', 'Красавица', 'Это сэкономит мне несколько лет жизни.', 'Айс Вентурон', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28741, 'ruRU', 'Повелитель Перерожденных Обсидий', 'Расправьтесь с Повелителем Перерожденных Обсидием.', '<Шлем Вентурона жужжит.>$B$BНичего себе! Вы только посмотрите на это место! О... Неужели там на потолке след от когтей Смертокрыла?$B$BИ что это за создание в центре зала?$B$BЯ нигде не вижу Раза. Давай расправимся с этим чудищем и найдем Раза!', '', 'Когда-то простой смертный, а ныне новоявленный повелитель элементалей.', 'Повелитель Перерожденных Обсидий', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28742, 'ruRU', 'Ши-Ротам', 'Убейте Ши-Ротам.', 'А теперь, $gприятель:подруга;, мы будем охотиться на крупную дичь! На севере живет Ши-Ротам, самый крупный ледопард в мире.$B$BЭто большая честь для тебя, ведь это самый опасный зверь, на которого когда-либо ходили охотники... а если когда-нибудь ты увидишь ту кучу денег, которую гурманы предлагают за кусочек мяса Ши-Ротам, у тебя лопнут глаза!$B$BКогда убьешь ее, возвращайся в лагерь. Я не хочу, чтобы кто-то истребил всех ледопардов за один день...', '', 'Глава прайда ледопардов Зимних Ключей... и вкуснейший обед!', 'Ши-Ротам', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28744, 'ruRU', 'Вурдалакам не нравятся мои семена', 'Выдержите 2 внушительных волны наступления зомби.', 'А ты неплохо справляешься, $n! Просто юный ботаник! Слушай, у меня есть новые семена, которые я хотел бы испытать, называются орехокамни. Используй их, чтобы остановить нежить. Просто бросай их на землю и зомби не смогут пройти дальше. Нежить так глупа!$b$bДавай попытаемся!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28745, 'ruRU', 'Крикуны в собственном соку', 'Убейте 15 крикунов Зимних Ключей.', 'Энти маленькие совы – просто вкуснотища, но Скороцап утверждает, что дальше на юге живут еще вкуснее. Крикуны – так их тут кличут... если их бьешь, они поднимают страшный шум, да!$B$BНо Скороцап говорит, что ничего лучше он в жизни не пробовал, и я ему верю. Может, добудешь для нас парочку, пока мы тут с Фрэнсисом спорим?', '', 'Я мечтаю отведать совятины!', 'Джеб Гутри', 'От этой говорильной штуки у меня ум за разум заходит.', 'Джеб Гутри', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28746, 'ruRU', 'Взломанная защита', 'Проникните в зал управления титанов.', 'Ну ладно, приступим, $n!$B$BЗа этой дверью – главная комната, что-то вроде центральной диспетчерской.$B$BСейчас я войду в эту дверь, быстренько деактивирую преобразующий механизм, а потом мы все дружно отправимся домой кушать плюшки. Дела на две минуты.$B$BВсе зависит от уровня подготовки, $gсынок:малышка;. Именно уровень и отличает настоящего археолога от обычного охотника за сокровищами.$B$BК чему поднимать лишний шум и будоражить зверюг? Все можно сделать по-умному... отключить пару приборов... вывести аппаратуру из строя...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28747, 'ruRU', 'Тыквомбы', 'Выдержите 2 внушительных волны наступления зомби.', '$gВидел:Видела; когда-нибудь такое?$b$b<Брейзи вытаскивает тыкву.>$b$bЭто не просто тыква, $gдружок:подружка;. Смотри, ты кладешь ее на землю, подходит зомби и... БУМ! От зомби остается мокрое место. Давай попробуем!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28748, 'ruRU', 'Посев мертвецов', 'Победите надзирателя Штиллеца', 'Это Штиллец! Он уже почти здесь! Он собирается забрать у нас все, что у нас есть, чтобы бороться с ним! За дело!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28749, 'ruRU', 'Битва за Андорал', 'Обратитесь к боевому магу Эраллиеру, чтобы тот телепортировал вас в Андорал, что находится в Западных Чумных землях. Затем поговорите с Тассарианом в Андорале.', 'К нам только что прибыл грифон c известием из Чумных земель. Плохие новости.$b$bАндорал находится в гуще противостояния между Отрекшимися, Альянсом и Плетью. Король Ринн рискнул и поставил во главе своих войск рыцаря смерти. Однако я уверен, что он не откажется от любой помощи.$b$bОн отдельно упомянул о том, что им $gнужен:нужна:c; |3-6($c) Альянса для выполнения специальных заданий. Если ты $gсогласен:согласна;, обратись ко мне снова, чтобы я открыл портал.', '', '', '', '', '', 'Поговорите с Тассарианом в Андорале, что в Западных Чумных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (28750, 'ruRU', 'Битва за Андорал', 'Обратитесь к чародею Арману, чтобы тот телепортировал вас в Андорал, что находится в Западных Чумных землях. Затем поговорите с Кольтирой Ткачом Смерти в Андорале.', 'К нам только что прибыл ветрокрыл с известием из Чумных земель. Плохие новости.$b$bАндорал находится в гуще противостояния между Отрекшимися, Альянсом и Плетью. Похоже, что Сильвана рискнула и поставила во главе своих войск рыцаря смерти Кольтиру Ткача Смерти.$b$bОна отдельно упомянула о том, что им $gнужен:нужна:c; |3-6($c) для выполнения специальных заданий. Если ты $gсогласен:согласна;, обратись ко мне снова, чтобы я открыл портал.', '', '', '', '', '', 'Поговорите с Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (28751, 'ruRU', 'Уход за садом', 'Выдержите 2 внушительных волны наступления зомби.', 'Хоть мы и победили Штиллеца, его зомби все еще наводняют округу. Смотри, вот приближается еще один отряд! Помоги мне справиться с ними, $gстарик:подруга;! Вперед!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28753, 'ruRU', 'Испорченная система', 'По просьбе Бранна Бронзоборода убейте Изисет, Аммунаэ, Сетеша и Раджа.', 'Вот зараза!$B$BКто-то уже постарался и разворотил всю систему! Теперь с этого пульта никак не добраться до базы данных.$B$BПридется нам делать все через за... э... другим способом. Надеюсь, $gсынок:малышка;, ты со своими замечательными друзьями ничего не имеешь против хорошей драки?$B$BВам надо подняться на самый верхний уровень. Там вас встретят четыре стража. Я смогу утилизировать эти диски, только когда эти стражи... ну, скажем так, будут исключены из системы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28755, 'ruRU', 'Летописи ордена Серебряной Длани', 'Разыщите утраченные тома летописей ордена Серебряной Длани в Стратхольме.', 'Знаешь ли ты, кто такие рыцари ордена Серебряной Длани? Они были первыми паладинами Света. Именно они потом образовали орден Серебряного Рассвета и Алый орден. И хотя многие из них сошли с пути истинного, они по-прежнему хранят ценные реликвии рыцарей ордена Серебряной Длани.$B$BВ центральных кварталах Стратхольма под неусыпным взором инструктора Галфорда хранятся летописи ордена Серебряной Длани. Все тома, которые тебе удастся раздобыть, найдут достойное место в воссозданной часовне Последней Надежды.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28756, 'ruRU', 'Костяные кадавры', 'Прикончите Громоклина в склепе Некроситета.', 'При жизни мы с братьями сражались со многими порождениями Плети, но никто так не переполнял наши души ненавистью, как некроманты. Мало им было поднять наших погибших товарищей из мертвых и натравить на нас – так они еще и создали этих омерзительных костяных големов с тесаками вместо рук!$B$BЭти кадавры порешили многих наших, и нам так и не удалось совладать с ними. Прошу тебя, $n, подними знамя павших. Проберись в склеп Некроситета и покончи с самой крупной и опасной из этих мерзких тварей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28757, 'ruRU', 'Дать отпор!', 'Убейте 6 воргов из клана Черной горы.', 'Стало быть, ты новобранец из Штормграда? Я маршал Макбрайд, командир гарнизона. Добро пожаловать в строй!$B$B<Макбрайд просматривает какие-то бумаги.>.$B$B$n. $n, так?$B$BТы как раз вовремя. Оркам Черной горы удалось проникнуть в Североземье через горный разлом. Мои солдаты делают все возможное, чтобы оттеснить врага, но их становится все больше и больше.$B$BОтправляйся на северо-запад в лес и истреби там боевых воргов клана Черной горы! Приди на помощь нашим войскам!', '', 'Боевые ворги клана Черной горы – опасные хищники.', 'Боевой ворг клана Черной горы', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28758, 'ruRU', 'Битва жизни и смерти', 'Оседлайте гранатового бойца. Уничтожьте 8 сумеречных темных драконов.', 'Алекстраза и Смертокрыл кружат в небе над Грим Батолом! План Алекстразы не сработал: королева драконов вне Круга Жизни, который она подготовила. Мы должны помочь ей всем, чем только сможем.$B$BСкорее! Забирайся на гранатового бойца, что позади меня.$B$BНаша задача – найти и уничтожить сумеречных драконов, которые помогают Смертокрылу. В седло, ну же!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28759, 'ruRU', 'Волки и овцы', 'Расправьтесь с 8 шпионами клана Черной горы.', 'Орки-захватчики – не дураки. Они следят за нашими действиями, чтобы улучить удобный момент для нападения.$B$BВ лесу на северо-западе расположились шпионы из клана Черной горы. Они смотрят на нас через подзорные трубы, выжидая удобный час. Я хочу, чтобы ты $gнапал:напала; на них!$B$BРасправься со шпионами клана Черной горы! Нужно продемонстрировать им, что мы знаем о том, что они следят за нами, а также показать нашу боеготовность!', '', 'Это шпион клана Черной горы. Однако иногда встречаются и шпионки.', 'Шпион клана Черной горы', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28760, 'ruRU', 'Возмездие за Орсис', 'Прикончите Асаада.', 'Великий град Орсис подвергся нападению воздушных орд.$B$BНас захватили в плен – и нам еще повезло.$B$BА многие погибли, погребенные в удушающих песках...$B$BПриказ к наступлению на Орсис отдал Асаад, калиф Ал\'акира... И он должен поплатиться за это жизнью!', '', 'По воле Ал\'акира Асаад отдал приказ разрушить Орсис. Покарай его!', 'Калиф зефиров Асаад', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28762, 'ruRU', 'Дать отпор!', 'Убейте 6 воргов из клана Черной горы.', 'Стало быть, ты новобранец из Штормграда? Я маршал Макбрайд, командир гарнизона. Добро пожаловать в строй!$B$B<Макбрайд просматривает какие-то бумаги.>.$B$B$n. $n, так?$B$BТы как раз вовремя. Оркам Черной горы удалось проникнуть в Североземье через горный разлом. Мои солдаты делают все возможное, чтобы оттеснить врага, но их становится все больше и больше.$B$BОтправляйся на северо-запад в лес и истреби там вторгшихся воргов из клана Черной горы! Приди на помощь нашим войскам!', '', 'Боевые ворги клана Черной горы – опасные хищники.', 'Боевой ворг клана Черной горы', '', '', '', 25549);
