INSERT INTO `quest_template_locale` VALUES (28768, 'ruRU', 'Зимние Ключи!', 'Явитесь к Донове Снегоноре у Источников Ледяного огня в Зимних Ключах.', 'Донова Снегонора – женщина-дворф – друг Древобрюхам.$B$BМы торгуем огненной водой.$B$BТы найдешь ее у источников Ледяного огня – это надо идти на восток через наши пещеры.$B$BОна хочет одолеть фурболгов из племени Зимней Спячки и нуждается в помощи. Может быть, ты сумеешь ей помочь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28769, 'ruRU', 'Волки и овцы', 'Расправьтесь с 8 шпионами клана Черной горы.', 'Орки-захватчики – не дураки. Они следят за нашими действиями, чтобы улучить удобный момент для нападения.$B$BВ лесу на северо-западе расположились шпионы из клана Черной горы. Они смотрят на нас через подзорные трубы, выжидая удобный час. Я хочу, чтобы ты $gнапал:напала; на них!$B$BРасправься со шпионами клана Черной горы! Нужно продемонстрировать им, что мы знаем о том, что они следят за нами, а также показать нашу боеготовность!', '', 'Это шпион клана Черной горы. Однако иногда встречаются и шпионки.', 'Шпион клана Черной горы', '', '', '', 25549);
