INSERT INTO `quest_template_locale` VALUES (28775, 'ruRU', 'Разбитая статуэтка змеи', 'Почините разбитую статуэтку, применив необходимые умения и материалы.', 'Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28776, 'ruRU', 'Разбитая статуэтка земельника', 'Почините разбитую статуэтку, применив необходимые умения и материалы.', 'Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28777, 'ruRU', 'Разбитая статуэтка совы', 'Почините разбитую статуэтку, применив необходимые умения и материалы.', 'Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28778, 'ruRU', 'Разбитая статуэтка медведя', 'Почините разбитую статуэтку, применив необходимые умения и материалы.', 'Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28779, 'ruRU', 'До дома далече', 'Раздобудьте сердце великого визиря Эртан.', 'Думаю, мне удалось сбежать потому, что отсюда, по сути, больше некуда деваться...$B$BЯ застрял на этих платформах, и рано или поздно они меня все равно найдут. Если только...$B$BСлыхал я, что сердце высокородного элементаля дарует его обладателю свойства соответствующей стихии. Стало быть, сердце воздушного элементаля пришлось бы очень кстати, надумай я спуститься на землю.$B$BПринеси мне сердце великого визиря Эртан – с помощью его магии я смогу благополучно приземлиться на побережье Ульдума.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28780, 'ruRU', 'В бой!', 'Явитесь к сержанту Виллему, находящемуся за Аббатством Североземья.', 'Мне пришло срочное донесение от сержанта Виллема. Оказывается, орки Черной горы привлекли гоблинов, промышляющих наемными убийствами. Они атаковали позиции нашего батальона за аббатством. Виллем попросил меня прислать ему на подмогу $gнастоящего героя:настоящую героиню;. Ты $gдолжен:должна; прийти им на помощь, $n!$B$BОбратись к сержанту Виллему, который находится к северу от аббатства в командирском шатре. За дело!', '', 'Сержант Виллем находится в командирском шатре позади Аббатства Североземья.', 'Сержант Виллем', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28781, 'ruRU', 'Неплановые цели', 'Ликвидируйте генерала Хусама и 2 присягнувших капитанов.', 'Мы были участниками секретной операции, организованной принцем Надуном из Рамкахена. Однако большую часть нашего отряда перебили в результате засады, вследствие чего мы не можем выполнить задание.$B$BЕсли ты согласишься помочь нам, я бы смог выторговать для тебя солидное вознаграждение.$B$BНам было поручено уничтожить любые неплановые цели, потеря которых нанесла бы ощутимый урон военной инфраструктуре противника.$B$BВпереди мы обнаружили генерала Хусама в сопровождении двух капитанов. Ликвидация этих целей станет неоспоримым благом для Рамкахена.', '', 'Нужно нанести сокрушительный удар по командованию Неферсета!', 'Генерал Хусам', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28782, 'ruRU', 'Легендарная птица', 'Убейте Смертоуха.', 'У местных есть легенда о могучей сове, которая кружит над вершинами гор, словно сама крылатая смерть. Местные назвали ее \"Смертокрыл\".$B$BНо скоро им сообщили, что это имя уже занято, и поэтому они выбрали другое прозвище, которое также наполняет душу страхом и ужасом.$B$BСмертоух!$B$BСмертоух живет на вершине горы, к юго-западу от нашей коптильни. Заставь это инфернальное уханье умолкнуть... чтобы мы могли съесть эту сову!', '', 'Вперед, за птицей!', 'Джеб Гутри', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28783, 'ruRU', 'Источник их силы', 'Сразите Сиамата.', 'Перед тем, как наш отряд попал в засаду, нам удалось провести полномасштабную разведку в стане врага.$B$BМы установили, что посланник Смертокрыла Сиамат является источником новоприобретенной силы Неферсета.$B$BВраги заявляют, что они всего лишь восстановили величие прошлых дней, но произошло нечто другое: в их души закралась тьма.$B$BБудучи повелителем одного из четырех ветров, Сиамат обладает гигантской силой. Однако он растерял часть своего могущества вследствие передачи своей мощи Неферсету.$B$BНужно сразить его сейчас, пока Сиамат ослаблен, и положить конец этому безумию.', '', 'Сиамат питает Неферсет неисчерпаемой силой!', 'Сиамат, южный ветер', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28784, 'ruRU', 'В бой!', 'Явитесь к сержанту Виллему, находящемуся за Аббатством Североземья.', 'Мне пришло срочное донесение от сержанта Виллема. Оказывается, орки Черной горы привлекли гоблинов, промышляющих наемными убийствами. Они атаковали позиции нашего батальона за аббатством. Виллем попросил меня прислать ему на подмогу $gнастоящего героя:настоящую героиню;. Ты $gдолжен:должна; прийти им на помощь, $n!$B$BОбратись к сержанту Виллему, который находится к северу от аббатства в командирском шатре. За дело!', '', 'Сержант Виллем находится в командирском шатре позади Аббатства Североземья.', 'Сержант Виллем', '', '', '', 25549);
