INSERT INTO `quest_template_locale` VALUES (28790, 'ruRU', 'Персональное приглашение', 'Предсказатель Крогар просит вас встретиться с ним в Оргриммаре.', '<В вас нарастает незнакомое чувство, наполняя весь ваш разум невиданными образами и странными мыслями.>$B$BУслышь меня, $n.$B$BНаш мир на грани жуткой катастрофы.$B$BВзываю к тебе: окажи нам помощь в этот трудный час.$B$BЯ Крогар.$B$BНайди меня, и я открою тебе твое предназначение.$B$BЖду тебя в Оргриммаре, к северу от Волока.', '', '', 'Предсказатель Крогар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28791, 'ruRU', 'Враг подослал наемных убийц', 'Прикончите 8 гоблинов-убийц.', 'Ты когда-нибудь $gвстречал:встречала; гоблина, $n? Это презренные зеленокожие монстры, любящие лишь две вещи: золото и самих себя.$B$BОрки Черной горы прибегли к услугам гоблинов, промышляющих наемными убийствами, чтобы те убивали наших солдат. Погляди на поле к северу от нас: ты вряд ли разглядишь, как они маскируются в траве.$B$BХочу, чтобы ты $gпошел:пошла; туда и $gперебил:перебила; всех гоблинов, которых сможешь найти. Пусть узнают, что не следует выступать против Альянса.', '', 'Это гоблин-убийца. Подлое маленькое создание!', 'Гоблин-убийца', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (28792, 'ruRU', 'Враг подослал наемных убийц', 'Прикончите 8 гоблинов-убийц.', 'Ты когда-нибудь $gвстречал:встречала; гоблина, $n? Это презренные зеленокожие монстры, любящие лишь две вещи: золото и самих себя.$B$BОрки Черной горы прибегли к услугам гоблинов, промышляющих наемными убийствами, чтобы те убивали наших солдат. Погляди на поле к северу от нас: ты вряд ли разглядишь, как они маскируются в траве.$B$BХочу, чтобы ты $gпошел:пошла; туда и $gперебил:перебила; всех гоблинов, которых сможешь найти. Пусть узнают, что не следует выступать против Альянса.', '', 'Это гоблин-убийца. Подлое маленькое создание!', 'Гоблин-убийца', '', '', '', 25549);
