INSERT INTO `quest_template_locale` VALUES (28889, 'ruRU', 'Arcane Instructions tracking Quest', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (28909, 'ruRU', 'Сауранок укажет путь', 'Поговорите с Сауранком Мистиком в Крепости Громмаш в Оргриммаре.', 'Вижу, ты еще не $gговорил:говорила; с Сауранком Мистиком. Он является моим советником с начала кампании в Нордсколе.$b$bЧтобы напасть на Сумеречное нагорье, нам нужен план побережья. Я попросил Сауранка раздобыть эту информацию. Узнай, не нужна ли ему твоя помощь! Он тут, недалеко от меня.', '', '', '', '', '', 'Поговорите с Сауранком Мистиком в Крепости Громмаш, что в Оргриммаре.', 25549);
