INSERT INTO `quest_template_locale` VALUES (29015, 'ruRU', 'Удача шахтера', 'Заберите изумруд \"Кошачий глаз\" у одного из надзирателей или головорезов Торговой Компании.', 'Управляющий пристанью в таком оживленном порту, как Кабестан, держит руку на пульсе происходящего. Я в курсе всего товарообмена между нашим городом и Пиратской бухтой.$B$BПоследние слухи касаются Каменного карьера, принадлежащего Торговой Компании, что на северо-востоке от Нефтяного болота. Один из шахтеров нашел изумруд размером с твой кулак. Я знаю несколько покупателей на такой товар и готов поделиться с тобой комиссией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (29016, 'ruRU', 'Кулек конфет', '', '', '', '', '', '', '', '', 25549);
