INSERT INTO `quest_template_locale` VALUES (30375, 'ruRU', 'Морские змеи', 'Соберите 6 голов темночешуйчатых жаленей, которые водятся в реке Красаранг.', 'Реки здесь просто кишат ядовитыми змеями. Эти змеи покусали тех, кто бежал из храма, и кое-кто из укушенных уже серьезно болен.$b$bМы стараемся как можно быстрее ввести всем противоядие, но нам нужны еще ядовитые железы.$b$bЯ не стану просить тебя вырезать эти железы на месте – слишком много времени уйдет. Лучше принеси мне головы, а я позабочусь об остальном.', '', '', '', '', '', 'Вернитесь к Андуину Ринну в Укрытие Красного Крыла.', 19865);
INSERT INTO `quest_template_locale` VALUES (30376, 'ruRU', 'Надежда умирает последней', 'Поговорите с Лун Маем в Каменном Плуге.', 'Возможно, и другие монахи Шадо-Пан подвергаются подобным нападениям.$B$BОтыщи Лун Мая, командира стражи Шадо-Пан. Он находится на западном краю Долины Четырех Ветров. Сообщи ему, что у нас все в порядке и подмоги не требуется.$B$BДаже более того – я пошлю большое число своих спутников в разные концы, что они передали весть надежды тем, кто в ней нуждается.$B$BСпасибо тебе еще раз, $n. До встречи!', '', '', '', '', '', 'Поговорите с Лун Маем в Каменном Плуге.', 19865);
