INSERT INTO `quest_template_locale` VALUES (30384, 'ruRU', 'Ослепить их!', 'Убейте разведчика Служителей Солнца.', 'Служители Солнца из Орды! Мы недавно видели, как их разведчик околачивался рядом с темницей.$b$bНе знаю, как он туда попал, но точно знаю – он там не один. Они всегда ходят вместе.$b$bУбей разведчика Служителей Солнца, пока он не сообщил врагам, где мы находимся.', '', '', '', '', '', '', 25549);
