INSERT INTO `quest_template_locale` VALUES (30533, 'ruRU', 'Tracking Event: Finished Second Expansion', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30534, 'ruRU', 'Вторые руки', 'Уговорите одного из своих друзей поработать на ферме Солнечной Песни.', 'Несмотря на все ваши усилия, дел только прибавляется.$B$BВозможно, вы могли бы пригласить на ферму Солнечной Песни одного из своих друзей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30535, 'ruRU', 'Растениеводство I: семена', 'Поговорите с торговцем Зеленое Поле на рынке Полугорья и получите у него пакетик семян капусты кале.', 'Ну, начнем с начала! Помощь мне всегда пригодится.$b$bЕсли хочешь быть моим компаньоном, тебе нужно научиться выращивать овощи. А для этого ты $gдолжен:должна; посадить семена!$B$BИ насколько я понимаю, господин Земляная Плюха... Нет, не так... Золотая Бляха? Тоже не то...$B$BЗеленое Поле! Вот как его зовут! В общем, семена нужно получить у него.$B$BЗеленое Поле торгует на рынке в Полугорье – это прямо на юго-восток отсюда. Иди к нему и возьми семена овощей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30536, 'ruRU', 'FLAG - Война с сорняками: обучение', 'Выслушайте Сяо и его товарищей.', 'А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке.$b$bЯ просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.', '', '', '', '', '', 'Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.', 19865);
