INSERT INTO `quest_template_locale` VALUES (30564, 'ruRU', 'Tracking Event: Talked to Dog at Farm', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30565, 'ruRU', 'Неожиданное преимущество', 'Отнимите поврежденные водой механизмы и ржавые зажимные болты у хозенов к востоку.', '$n, наши дела идут все лучше. Я тут гулял немного и набрел на эту маленькую красотку.$B$B<Салли указывает на баллисту, стоящую справа от него.>$B$BНо беда в том, что она парная, а ее сестричка еще не готова. Я бы сам ее собрал, если бы эти мерзкие твари из племени Злобного Оскала не напали на меня и не отняли некоторые детали.$B$BСлушай, а ведь ты здорово управляешься с аборигенами. Может, выручишь старину Салли, а?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30566, 'ruRU', 'FLAG - Проблемы с вредителями: обучение', 'Выслушайте Сяо и его товарищей.', 'А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке. Я просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.', '', '', '', '', '', 'Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.', 19865);
INSERT INTO `quest_template_locale` VALUES (30567, 'ruRU', '\"Громобой\" Бланш', 'Завершите сценарий \"Хмельная буря\".', 'Чуешь этот запах? Приближается шторм! Разразится страшная буря – а у меня тут, между прочим, тоже бурная деятельность!$B$BКогда начнется шторм, разыщи меня на вершине холма, и тогда мы сварим бочонок моего самого знаменитого напитка. Я могу рассчитывать на твою помощь?$B$B', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30568, 'ruRU', 'Вклад в общее дело', 'Поговорите со Здоровяком Кажаши, Эмбер Кеарнен и Мишкой.', '$n, с возвращением! Знаешь, цзинь-юй обучаются быстрее, чем мне думалось! Мы уже заканчиваем.$B$BПожалуйста, разыщи Эмбер, Здоровяка Кажаши и Мишку. Узнай, не нужна ли им помощь с тренировками.$b$bКажаши и Мишку можно найти здесь, в Деревне Жемчужного Плавника. Эмбер занимается с новобранцами в Ямах Ловкого Хвоста к северо-западу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30569, 'ruRU', 'Проблемы на ферме', 'Поговорите с крестьянином Чоу на ферме Чоу, что на вершине Кунь-Лай.', 'Я... мне удалось бежать от крестьянина Чоу, он живет к юго-востоку отсюда. Ферма захвачена яунголами, но старик и его жена так просто не сдадутся!\n\nПрошу тебя, помоги ему. Может, тогда он согласится отправить сюда кого-нибудь, чтобы заготовить еду для вашего нового города?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30570, 'ruRU', 'Проблемы на ферме', 'Поговорите с крестьянином Чоу на ферме Чоу, что на вершине Кунь-Лай.', 'Я... мне удалось бежать от крестьянина Чоу, он живет к юго-востоку отсюда. Ферма захвачена яунголами, но старик и его жена так просто не сдадутся!\n\nПрошу тебя, помоги ему. Может, тогда он согласится отправить сюда кого-нибудь, чтобы заготовить еду для вашего нового города?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30571, 'ruRU', 'Свободу рабам!', 'Освободите 12 рабов с фермы, убив надзирателей Ордо.', 'Яунголы ордо загоняют моих рабочих до смерти! Это не дело.$B$BПожалуйста, |3-6($c), спаси их, пока не поздно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30573, 'ruRU', 'Tracking Event: Started Third Expansion', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30574, 'ruRU', 'Tracking Event: Finished Third Expansion', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30575, 'ruRU', 'Отлов яков', 'Поймайте 3 диких яков равнин и отведите их в приют Западного Ветра.', 'Мы должны иметь возможность быстро передвигаться, если хотим удержать эту землю. Но это невозможно без верховых животных, а их тут не так много, согласись.\n\nКажется, местных яков можно объездить. По крайней мере, пандарены так говорят. Ты можешь поймать несколько?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30581, 'ruRU', '...а еще котелок!', 'Собрать 12 корнеплодов и 1 чугунный котелок.', 'Конечно, я хочу помочь вам. Но нам тоже нужно что-то есть, а у меня нет даже котелка, не говоря уж о том, что в него положить!$B$BВот список того, что мне нужно. Вперед, достань все это!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30582, 'ruRU', 'Покойная госпожа Мускусная Лапа', 'Принесите Лао Мускусной Лапе подарок его жены.', 'На потертом браслете несколько отметин – знаки любви и обожания покойной госпожи Мускусной Лапы.$b$bНаверняка Лао захочет получить эту вещицу назад.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30583, 'ruRU', 'Дворфу очень нужно мясо', 'Соберите 160 мясных кусочков Кунь-Лай.', 'Эй!\n\nНам нужно еды раздобыть, если мы тут не хотим с голодухи помереть.$B$BТы, может, не знаешь, но из меня повар хороший. Иди-ка мяса набери, а я его заготовлю, надолго хватит. На много месяцев. Или недель. На несколько дней уж точно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30584, 'ruRU', 'Электрошок!', 'Поймайте 7 доцзянских угрей в реке Доцзян в Красарангских джунглях.', 'Ты $gел:ела; когда-нибудь свежего доцзянского угря, $n? Нет? Ну, тогда ты, считай, и не $gжил:жила;!$b$bОтправляйся к реке Доцзян и налови нам несколько угрей. Но будь $gосторожен:осторожна;, они могут ударить током!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30585, 'ruRU', 'В тихом омуте', 'Найдите древний рыбацкий пруд у Красарангского водопада, что к северо-западу отсюда, и ловите в нем рыбу, чтобы выманить чудовище из укрытия.', 'Легенда гласит, что в лесу к северу отсюда живет огромное чудовище. Мой сын пропал, и я боюсь, что он мог подойти слишком близко к его логову...$b$bИди на северо-запад к Красарангскому водопаду и разыщи там таинственный водоворот – это и есть ключ к разгадке. Убей гнусное чудовище и узнай хоть что-нибудь о моем сыне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30586, 'ruRU', 'Морские ушки', 'Соберите 9 кусков мяса морских ушек в Поющей Котловине на на северо-востоке.', 'Уже несколько поколений пандаренов собирают здесь морские ушки. Пора и тебе приобщиться к этому ритуалу.$b$bНайти морские ушки можно к северо-востоку отсюда, в Поющей Котловине. Но будь $gосторожен:осторожна; – туда в последнее время зачастили акулы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30587, 'ruRU', 'Як и так, и сяк', 'Убейте 9 хияккеров-разорителей на ферме Мускусной Лапы.', 'Похоже, что яунголы повадились воровать яков. Осмотрев местность, вы убеждаетесь, что напасть на якомойку не составляет никакого труда.$b$bЕсли вы вырежете нескольких яунголов, они поймут, что эту область охраняют.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30588, 'ruRU', 'Рыбалка не задалась', 'Убейте 8 береговых налетчиков Речного Клинка у Рыболовной экспедиции, что к западу от Деревни рыболовов.', 'Сауроки из клана Речного Клинка нападают на наших рыбаков! Им нужно срочно помочь!$b$bУбей сауроков и помоги рыбакам вернуться домой.', '', 'Сауроки – яростные бойцы из джунглей, с ними не стоит шутить.', 'Разоритель Речного Клинка', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30589, 'ruRU', 'Разрушение крушения', 'Поговорите с Макаэлем Бэем в лесу Пэй-У.', 'Чтобы выбить корабль Альянса, нам нужно найти нашего инженера. Мы расстались с ним, когда спасались после крушения.$B$BДумаю, ты найдешь его где-то в лесу, к западу отсюда. Скажи, что тебя прислал Керга, и он с радостью поможет тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30590, 'ruRU', 'Не кантовать', 'Найдите 6 зарядов взрывчатки.', 'Мы можем помочь вам освободить корабль, но для этого нам понадобится побольше взрывчатки, которую мы пытались забрать обратно у Альянса.$B$BПеред бегством я приказал своим людям вынести всю взрывчатку, какую они смогли найти. К югу отсюда много обломков и трупов, там же можно найти и взрывчатку, которая еще не успела взорваться.$B$BПринеси мне достаточное ее количество, и я смогу из нее что-нибудь сообразить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30591, 'ruRU', 'Охота на хищников', 'Убейте 9 тигров Пэй-У.', 'Этот лес стал куда опаснее с тех пор, как Шэнь-Цзынь Су начал сотрясаться. Потревоженные этой тряской тигры начали нападать на беженцев – и даже на меня.$B$BНам нужно позаботиться о том, чтобы в лесу было безопасно – ради пострадавших и раненых, что собираются здесь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30592, 'ruRU', 'К путевой станции Джутового пути', 'Защищайте отряд груммелей по дороге к путевой станции Джутового пути. Хотя бы один груммель должен остаться в живых.$b$bЕсли отряд будет потерян, ищите его на Джутовом пути или вернитесь в Пэй-Лэй и дождитесь следующего отряда.', 'Не везет груммелям. Хозены начали грабеж. Напали на дорогу, по которой мы припасы возим к Змеиному Хребту.$b$bТак не пойдет.$b$bПоможешь? Мы не бойцы, мы груммели. Удача ждет того, кто поможет груммелям.$b$bИди с отрядом груммелей к путевой станции Джутового пути. Береги груммелей. Хотя бы один должен дойти.$b$bГруммели отблагодарят, не пожалеешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30593, 'ruRU', 'Упокоить беспокойных', 'Уничтожьте 14 терракотовых воинов или терракотовых стражей.', 'Адмирал поручил мне решение одной важной проблемы, но я же ведь целитель, а не боец!$B$BПандарены в лагере рассказали, что кто-то оживляет статуи к северо-востоку от Могуцзя.$B$BТы поможешь мне, $n? Сейчас нам никак нельзя отвлекаться на войну с армией оживших статуй.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30594, 'ruRU', 'Упокоить беспокойных', 'Уничтожьте 14 терракотовых воинов или терракотовых стражей.', 'У меня тут много дел, $n. Мне бы пригодилась твоя помощь.$B$BК северо-западу есть область, которую местные называют Могуцзя. Тамошние статуи почему-то оживают, наши пандарены в ужасе от этой новости...$B$BЕсли кто-нибудь не разберется с этой проблемой, могут начаться серьезные неприятности. Мы только что расположились здесь и не можем позволить себе воевать со статуями прямо сейчас.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30595, 'ruRU', 'Ценный антиквариат', 'Соберите 12 реликвий могу.', 'Дай угадать, ты $gпришел:пришла; разобраться с ожившими статуями могу? Какое совпадение, а я тут, э-э, провожу кое-какие исследования, касающиеся могу.$B$BЯ тебе вот что скажу. Если притащишь столько реликвий, сколько сможешь унести, я поделюсь с тобой кое-чем: средствами... для финансирования моих исследований.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30596, 'ruRU', 'Зандаларский тролль?', 'Убейте зандаларского воскресителя.', 'Когда вы уничтожали статуи могу, вам послышался характерный говор тролля из племени Зандалар.$B$BОчевидно, это серьезная угроза для Приюта Западного ветра, с троллем надо что-то делать.', '', '', '', '', '', 'Вернитесь к Мишке в Приют Западного ветра на вершине Кунь-Лай.', 19865);
INSERT INTO `quest_template_locale` VALUES (30597, 'ruRU', 'Странный сферический камень', 'Вымочите камень в отваре из золотого лотоса.', 'У этого красивого камня явно есть магический потенциал... это очевидно всем, кто сведущ в алхимии. Стоит добавить травы, растущие в Пандарии, и этот камень сможет принести много пользы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30598, 'ruRU', 'Кто знал, что рыбам нравятся яйца?', 'Заберите нетронутое яйцо с Поющих Вершин и используйте его как наживку для ловли серебристого бычка.', 'Огромные журавли гнездятся здесь уже несколько поколений. На Поющих Вершинах они находят укрытие, где можно высиживать птенцов.$b$bНетронутые яйца этих журавлей – отличная приманка для серебристых бычков. Раздобудь такое яйцо и попробуй поймать на него бычка!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30599, 'ruRU', 'Обезьяний идол', 'Положите тела Так-Така, Дак-Дака и Ко-Ко на алтари, которые они охраняют.', 'Давным-давно, чтобы предотвратить устраиваемые хозенами погромы, груммели делились с хозенами едой.$b$bНо теперь у племени Ломаного Зуба, которое обитает к югу отсюда, есть большие магические идолы. Ук Всего Дука научил их получать силу с помощью идолов.$b$bОни убивают груммелей идолами!$b$bТы $gдолжен:должна; уничтожить эти идолы.$b$bКаждый из них охраняет вождь. Убей вождя и брось его труп на алтарь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30600, 'ruRU', 'Важные вещи', 'Найдите 8 тюков груммелей в лагере Ломаного Зуба или в Глубокой пещере.', 'Хозены из племени Ломаного Зуба, которые обитают к югу отсюда, убили всех моих груммелей. И, что еще хуже, погибшие груммели не смогли доставить свои вещи.$b$bПрошу, принеси им покой на великой тропе в нижний мир и верни мне их тюки.$b$bА уж я прослежу, чтобы они попали куда надо.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30601, 'ruRU', 'Когда храбрость ведет, счастье ей сопутствует.', 'Убедите 3-х скрывающихся проводников в пещере Ревущего Ветра помочь вам.', 'Большая неудача, если идешь в горы без хорошего проводника. Груммели лучше всех покажут дорогу, но многие убежали. Они боятся перевала. Там пропало много хороших груммелей.$b$bГруммели много вещей делают хорошо, но они не храбрые. Может, фимиам огненного лотоса сделает их храбрыми. Тогда они покажут тебе путь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30602, 'ruRU', 'Кроличья Лапка', 'Спасите брата Кроличью Лапку с заставы Ломаного Зуба.', 'Хозены Ломаного Зуба похитили Кроличью Лапку! Этот груммель – самая большая удачка.$b$bТак не повезло! Пожалуйста, |3-6($r), помоги вернуть его! Нам так нужна его удача.$b$bМожешь поискать его на заставе Ломаного Зуба?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30603, 'ruRU', 'Набег Ломаного Зуба', 'Заберите счастливую кроличью лапку у Мо-Мо.', 'И они стащили мой талисман на удачу! Здешний вожак хозенов Мо-Мо украл мою кроличью лапку.$b$bЭто самый дурной знак для груммеля. Моя лапка приносила удачу груммелям повсюду. Если хозены поймут, как сделать удачу из лапки, все пропало.$b$bПожалуйста, можешь вернуть ее?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30604, 'ruRU', 'Вырывая Ломаный Зуб', 'Убейте 8 бойцов Ломаного Зуба и 6 метателей Ломаного Зуба.', 'Хозены разоряют нас, если думают, что у них недостаточно припасов для всех.$b$bХозены плодятся как гну-синь, у них тоже ртов всегда больше, чем еды.$b$bГруммелей немного, сейчас осталось совсем мало.$b$bОб этом сложно просить, но... Можешь стать другом груммелей и убить несколько хозенов Ломаного Зуба? Это единственный способ уберечь земли от опустошения.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30605, 'ruRU', 'Утром братья, вечером – хозены', 'Спасите Брата Ячью Подкову.', 'Пока тебя не было, я увидел группу груммелей, которые шли по Джутовому пути. Впереди всех шел мой брат – Ячья Подкова.$b$bА потом на них напал Тяжелый Коготь. Они утащили моего брата и тех груммелей на север.$b$bПожалуйста, $n! Спаси моего брата. Удачи у него нет никакой, сплошная неудачка, но он же мой брат. Ищи его перед Крепостью Седоспинов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30606, 'ruRU', 'Тяжелая участь Тяжелого Когтя', 'Убейте 8 крушителей или пронзателей из племени Тяжелого Когтя в логове Тяжелого Когтя.', 'У хозенов Тяжелого Когтя появился новый вожак, Ук Всего Дука.$b$bОн видит страх на западе, гнев на юге, ненависть на севере и яунголов на востоке.$b$bИ он посылает своих хозенов разорять все вокруг и запасать припасы перед голодом.$b$bЭтих хозенов много, они опасны.$b$bУдачка, прошу тебя, сможешь победить их бойцов?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30607, 'ruRU', 'Хозены любят ключи', 'Добудьте ключи от оков йети у Чо Чо Злонравного и освободите Старика Пуф-Пуфа.', 'У хозенов есть йети! Они зовут его старик Пуф-Пуф и держат в задней части пещеры.$b$bОбычно хозены сами боятся стать завтраком для йети, но теперь они кормят их груммелями.$b$bТам есть главный хозен, который сторожит зверя. Можешь узнать, есть ли у него ключи от оков йети?$b$bБольшая неудача для хозенов, если йети будет гулять по форту.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30608, 'ruRU', 'Закуска из груммелей', 'Спасите 5 захваченных груммелей, открыв клетки или перерезав веревки, на которых они висят.', 'Они утащили моих груммелей! Хозены не едят груммелей, а вот йети едят. У хозенов Тяжелого Когтя есть йети!$b$bПрошу, спаси моих груммелей. Выпусти их из клеток или перережь веревки, на которых они висят. Спаси их, как можешь!$b$bНаграда и удача – твои, если сделаешь это.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30610, 'ruRU', 'Груммель! Груммель! Груммель!', 'Проведите 5 груммелей налегке к ящикам с припасами возле Дукерского Купола.', 'Теперь груммели в безопасности, надо вернуть припасы.$b$bВеликий вождь седошкурых, Ук Всего Дука, потому и великий, что все припасы у него.$b$bИди к Дукерскому Куполу, это на северо-запад. Возьми груммелей. Смотри за ними, проведи их к ящикам с припасами.$b$bДальше они знают, что делать.$b$bВстретимся там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30611, 'ruRU', 'Освободить йети!', 'Убейте 4-х смотрителей клетки.', 'Эта поездка на йети навела меня на кое-какие мысли. Ук Всего Дука держит в качестве домашнего животного йети по кличке Хрумк-Хрумк.$b$bОн запугивает им других хозенов, и они считают его великим предводителем. Надо избавиться от этого йети.$b$bОтправляйся к Дукерскому Куполу, он к северо-западу отсюда, и победи нескольких смотрителей клетки, чтобы ослабить путы Хрумк-Хрумка.$b$bМы с Ячьей Подковой встретим тебя там с множеством благовоний и грязным яком.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30612, 'ruRU', 'Вожак хозенов', 'Разозлите Хрумк-Хрумка, а затем победите Ука всего Дука.', 'Настало время сразиться с Уком Всего Дука. Если мы его победим, хозенам никто не будет приказывать разорять и грабить.$b$bПлан таков: Ячья Подкова поведет на арену Кисточку и спугнет Хрумк-Хрумка.$b$bЗатем появишься ты и сразишься с Уком Всего Дука, пока внимание хозенов будет отвлечено на йети, бесчинствующего в их доме.$b$bМы встретим тебя в лагере Коту с большой наградой. Удачи тебе, друг груммелей.', '', 'Вождь горных племен.', 'Ук Всего Дука', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30613, 'ruRU', 'Крепкочешуйчатый карп', 'Поймайте с помощью рыболовной пики 5 крепкочешуйчатых карпов в водах к югу от Деревни рыболовов.', 'Крепкочешуйчатый карп в этих краях – настоящее лакомство.$b$bУвы, поймать их нам не удается – своими мощными челюстями они перекусывают крючки. Возьми эту рыболовную пику и попробуй с ее помощью добыть нам карпов.', '', 'Крючок здесь не поможет.', 'Крепкочешуйчатый карп', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30614, 'ruRU', 'Нефтяная остановка', 'Наполните пустой сосуд для нефти у яунгольской нефтяной вышки.', 'Когда яунголы пришли сюда, они начали копать в поисках нефти. Что это вообще за \"нефть\"? А вдруг эта штука – огромный источник удачи? Это надо выяснить.$b$bВот, возьми этот сосуд и заполни его яунгольской нефтью у одного из ветряков. Если добудешь мне немного, в награду получишь много удачки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30615, 'ruRU', 'Зандаларский тролль?', 'Убейте зандаларского воскресителя.', 'Когда вы уничтожали статуи могу, вам послышался характерный говор тролля из племени Зандалар.$B$BОчевидно, это серьезная угроза для Приюта Западного ветра, с троллем надо что-то делать.', '', '', '', '', '', 'Вернитесь к темному мастеру Кирин в Приют Восточного Ветра на вершине Кунь-Лай.', 19865);
INSERT INTO `quest_template_locale` VALUES (30616, 'ruRU', 'Пробки на дорогах', 'Убейте 8 яунголов в Огненном лагере Жу-Цзинь.', 'Яунголы заблокировали наш Джутовый путь. Это очень неудачно для груммелей.$b$bМы используем эту дорогу, чтобы доставлять припасы к Змеиному Хребту. Без этих поставок защитники стены в опасности.$b$bГруммели – путешественники и погонщики, не бойцы. Можешь принести нам удачу, очистить путь от яунголов?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30617, 'ruRU', 'Удача в пути', 'Зажгите 8 джутовых благовоний удачи по пути в Пэй-Лэй.', 'Тот, с кем удача всегда, должен брать благовония в горы, чем ароматнее они – тем лучше.$b$bМожешь подняться к Пэй-Лэй и возжечь благовония, которые встретятся тебе по пути?$b$bЭто принесет удачу всем груммелям, которые пойдут той дорогой.$b$bБрат Перекатыш хорошо наградит тебя. Поговори с ним, когда прибудешь на место.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30618, 'ruRU', 'Возвращение припасов в Пэй-Лэй', 'Разыщите 8 украденных припасов в пещере Ревущего Ветра.', 'Если ты ищешь лучшие товары в Кунь-Лай, то $gпришел:пришла; по адресу! Конечно, здесь немного пустовато, но это лишь видимость...$b$bДа кого я обманываю? О каких поставках может идти речь, когда на нас постоянно совершают набеги хозены, а еще, будто этого мало, нас разграбляют грелли... У меня на складах почти ничего не осталось.$b$bЕсли ты поможешь вернуть хотя бы часть моих запасов, я дам тебе скидку в магазине.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30619, 'ruRU', 'Я больше не могу!', 'Убейте призывателя душ Могуцзя.', 'Вы с друзьями все еще обсуждаете ожившие статуи в Могуцзя, но я скажу тебе кое о чем пострашнее.\n\nГде оживают статуи, там поблизости и могу. Не знаю, встречались ли они тебе, но если нет...\n\nЛадно, скажем просто: могу – это очень плохо.\n\nТеперь тебе все время придется оглядываться и держать в уме еще одну угрозу.', '', 'Настоящий источник бед в Могуцзя…', 'Призыватель духов Могуцзя', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30620, 'ruRU', 'Я больше не могу!', 'Убейте призывателя душ Могуцзя.', 'Вы с друзьями все еще обсуждаете ожившие статуи в Могуцзя, но я скажу тебе кое о чем пострашнее.\n\nГде оживают статуи, там поблизости и могу. Не знаю, встречались ли они тебе, но если нет...\n\nЛадно, скажем просто: могу – это очень плохо.\n\nТеперь тебе все время придется оглядываться и держать в уме еще одну угрозу.', '', 'Настоящий источник бед в Могуцзя…', 'Призыватель духов Могуцзя', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30621, 'ruRU', 'Они украли мою удачу!', 'Верните Цзи-Лу Счастливчику счастливую лапку гну-синя, подкову яка, четырехветровый клевер и золотую монетку.', 'Путешествие по Кунь-Лай научило меня двум вещам. Во-первых, никогда не подкрадываться к спящему яку. Во-вторых, удерживать удачу на своей стороне нужно, но непросто!$b$bГруммели верят в то, что талисман приносит удачу, если носить его с собой. А я считаю, что если один талисман иногда приносит удачу, то с целой кучей оберегов удача никуда от меня не денется!$b$bЯ прибыл в Пэй-Лэй, и эти мерзкие маленькие грелли украли все мои талисманы. Если бы ты $gсмог:смогла; разыскать их, моему счастью не было бы предела!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30622, 'ruRU', 'Штурм начинается', 'Уничтожьте 15 ик\'тиков-воинов или ик\'тиков-заразителей.', 'Без стены у нас нет ни одного шанса. И если бы ты не $gпривел:привела; сюда столько воинов, мы бы долго не продержались.$b$bРазыщи капитана стражи Дубового Щита – он должен быть рядом с проломом в стене. По пути уничтожь столько богомолов, сколько сможешь.$b$bЕсли нам суждено победить, мы победим. Если потерпим поражение, то умрем с оружием в руках. Да здравствует Пандария!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30623, 'ruRU', 'Противоядие', 'Покажите маску Кен-Кена 5 ик\'тикам – командирам звена, а затем победите появившиеся воплощения страха.', '<Мэй указывает на поле боя.>$b$bВидишь вон тех огромных богомолов? Что-то в их облике напоминает мне о тех печальных существах, которых мы встретили в дозоре Чжу.$b$bМожет... Может, они тоже попали под влияние ша?$b$bУ меня есть маска Кен-Кена – та самая, с помощью которой он изгнал ша из наших стражей... и из И-Мо. Возможно, с помощью маски нам удастся и их привести в чувство.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30624, 'ruRU', 'Какая польза от бочки с пивом?', 'Отнесите пиво стражам Чжу, жрецам Журавлиного Крыла, монахам Шадо-Пан и ночным эльфам-поселенцам.', 'Я вот что думаю.$b$bУ нас есть пиво, которое сварил Чэнь, и все эти воины, которых ты $gсобрал:собрала;. Мы должны их объединить.$b$bТам, на полях, пандарены рискуют жизнью во имя родной страны. Мы с тобой можем хотя бы отнести им бочонок пива.$b$bМожет, они поднимут тост за победу. Может, выпьют в последний раз перед тем, как их прикончит богомол. В любом случае я хочу, чтобы перед боем они выпили хорошего пива.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30625, 'ruRU', 'Больше уже не ученики', 'Найдите учеников и помогите им победить ик\'тика-кровожада, наседку, ик\'тика – подрезателя сухожилий и сеятеля страха.', 'Пять учеников – те самые, которые искали тайного мастера – одни отправились на передовую. Я бы послал к ним на помощь монахов Шадо-Пан, но у меня их не осталось.$b$bУ стены рыщут опасные твари. Если встретишь учеников, защити их от чудовищ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30626, 'ruRU', 'Отступаем!', 'Поговорите с Лун Маем в Каменном Плуге, в долине Четырех Ветров.', 'Я собираю оставшиеся войска и отступаю – к хмелеварне Буйных Портеров, а может, даже к Полугорью. Это решит командир Лун Май.$b$bИди вперед и сообщи обо всем командиру. Мои воины последуют за тобой.', '', '', '', '', '', 'Вернитесь к командиру стражи Лун Маю в Каменный Плуг, что в долине Четырех Ветров.', 25549);
INSERT INTO `quest_template_locale` VALUES (30627, 'ruRU', 'Спаситель Каменного Плуга', 'Поговорите с Мисс Фанни в Каменном Плуге. Затем с ее помощью победите гигантского богомола.', 'Этот командир говорит быстро. У него есть оружие, которое поможет ему одержать победу. У него есть ВЫ.$b$b\"Но ведь это невозможно\", – скажете вы.$b$bИ ошибетесь. Это возможно. НИЧЕГО НЕВОЗМОЖНОГО НЕТ.$b$bИди же, $n, и спаси Каменный Плуг!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30628, 'ruRU', 'Благодарность Каменного Плуга', 'Найдите тайник командира и заберите свою награду.', 'И еще, $n. Не бойся, я не собираюсь снова просить тебя об услуге. Сегодня ты $gубил:убила; достаточно богомолов.$b$bНедавно мы получили партию высококачественной брони с вершины Кунь-Лай. Я собирался оставить это для своих воинов... но, думаю, по справедливости все должно достаться тебе. Эту награду ты найдешь на втором этаже таверны.', '', '', '', '', '', 'Найдите тайник командира.', 25549);
INSERT INTO `quest_template_locale` VALUES (30629, 'ruRU', 'FLAG - Игрок в финале', 'Выслушайте Сяо и его товарищей.', 'А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке.$b$bЯ просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.', '', '', '', '', '', 'Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.', 19865);
INSERT INTO `quest_template_locale` VALUES (30631, 'ruRU', 'Святилище Семи Звезд', 'Поговорите с Джалуу Щедрым, Куру Беззаботным, Удачливой Линь и смотрительницей Ви Вин в Вечноцветущем доле.', 'Взгляни на это существо, $gстранник:странница;. Почти сразу же после нашего прибытия могу-убийца напал без предупреждения.$B$BЕго целью был глава Золотого Лотоса. К счастью, мы оказались здесь и смогли защитить его.$B$BПосле покушения на Чжи я опасаюсь за жизнь тех, кто пришел в дол.$B$BСмотрители размещают людей в городе к юго-востоку отсюда. Идит туда и поговори с предводителями. Убедись, что они в безопасности.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30632, 'ruRU', 'Руины Го-Лай', 'Поговорите с Аньцзи Осенний Свет на руинах Го-Лай в Вечноцветущем доле.', 'Чжи Безмятежный считает, что могу попадают в дол через Руины Го-Лай, это на западе отсюда.$B$BАньцзи и Кунь отправились на разведку, но еще не вернулись.$B$BНужно выяснить, что случилось. Мне нужен $gумелый:умелая:c; |3-6($c).', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30633, 'ruRU', 'Разведчики', 'Убейте 8 вестников Шао-Тень.', 'Мы уже знаем о том, что могу проникли в Дол, но как выясняется, ситуация еще хуже.$B$BРуины на северо-западе кишат разведчиками, которые собирают там сведения и расхищают сокровища.$B$BТвоя задача проста: избавься от всех разведчиков, которых встретишь. Армия могу не сможет двигаться, лишившись глаз.', '', '', '', '', '', 'Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (30634, 'ruRU', 'Закрыть проход', 'Поговорите с Лао Легкая Нога у подножия Холма Руин и следуйте за ним по тропе. Дойдя до входа в пещеру на Холме Руин, установите там бочонок со взрывчаткой.', 'Мы с Лао Легкая Нога сходили на север, обшарили руины.$B$BПохоже, что могу лезут в долину из пещеры на склоне холма, и у них уже собрался внушительный отряд.$B$BВрагов слишком много, чтобы бросаться на них в открытую, так что иди ко входу в руины, там тебя ждет Лао Легкая Нога.$B$BОн проведет тебя по-тихому. Вот этот бочонок со взрывчаткой надо положить ко входу в пещеру.$B$BИ все, больше ничего не нужно.', '', '', '', '', '', 'Поговорите с Кунем Осенним Светом на Руинах Го-Лай в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (30635, 'ruRU', 'Охотник на цийлиней', 'Убить 9 каменных стражей.', 'С разведчиками теперь все ясно. Но совсем рядом, в Залах Го-Лай, все еще держится большой отряд могу.$B$BК сожалению, пробраться туда сложно, вход в руины сторожат свирепые сторожевые псы.$B$BРазберись с этими тварями. Будь начеку, их не так-то просто заметить.', '', '', '', '', '', 'Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (30636, 'ruRU', 'Камни силы', 'Соберите 7 ревелитовых кристаллов.', 'Много тысячелетий назад правители Вечноцветущего дола черпали энергию из могущественного ревелитового кристалла.$B$BС его помощью они поддерживали города, производства и боевые механизмы.$B$BЧжи Безмятежный попросил нас собрать эти кристаллы и принести их в город.$B$BВозможно, ты найдешь их в руинах.', '', '', '', '', '', 'Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (30637, 'ruRU', 'Залы Го-Лай', 'Проверьте, есть ли могу в Залах Го-Лай.', 'Проходя рядом с огромными вратами, вы слышите изнутри какие-то звуки.$B$BАньцзи говорила, что поблизости видели могу-разведчиков. Возможно, они пробрались вглубь залов.$B$BВам не терпится проверить это.', '', '', '', '', '', 'Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (30638, 'ruRU', 'Оставить просвет', 'Поговорите с Левеном Рассветным Клинком в Золотой Пагоде Вечноцветущего дола.', 'Это очень важно.$B$BМы с Кунем останемся наблюдать, а ты отправляйся в Золотую Пагоду.$B$BИ поторопись!', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30639, 'ruRU', 'Секреты Го-Лай', 'Найдите Хэ Легкая Нога в Залах Го-Лай и узнайте, что замышляют могу в западных чертогах.', 'Стражник, несущий службу у руин Го-Лай, недавно сообщил мне, что в чертоги пробрался предводитель Шао-Тень, убив при этом двух моих бойцов. Враги там что-то замышляют. Их надо остановить.$b$bХэ Легкая Нога уже последовал туда за ними. Он будет ждать тебя у входа в западные залы.$b$bОтправляйся поскорее, $n. Мне не нравится думать, что могу на шаг впереди нас.', '', '', '', '', '', 'Вернитесь к Левену Рассветному Клинку в Золотую Пагоду, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (30640, 'ruRU', 'Боевое копье Властелина Грома', 'Найдите боевое копье Властелина Грома.', 'У меня тревожные новости, $n.$B$BПохоже, могу задумали похитить из Дола три артефакта Силы.$B$BНам надлежит немедленно достать все три и надежно перепрятать их.$B$BВ первую очередь займемся боевым копьем Властелина Грома.$B$BПосле смерти Императора Лэй Шэня его поместили в древнее святилище к северо-западу отсюда.$B$BПринеси копье мне.', '', '', '', '', '', 'Вернитесь к Чжи Безмятежному в Золотую Пагоду в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (30641, 'ruRU', 'Боевой шлем Властелина Грома', 'Найдите боевой шлем Властелина Грома.', 'Второй артефакт Силы – это боевой шлем Властелина Грома.$B$BИмператор Лэй Шэнь надевал его в битву, и враги обращались в бегство при одном его виде.$B$BКогда Император скончался, шлем был помещен в Залы Го-Лай, что к западу отсюда, и окружен тысячами терракотовых воинов.$B$BТеперь они должны охранять своего вождя и умереть за него.', '', '', '', '', '', 'Вернитесь к Чжи Безмятежному в Золотую Пагоду в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (30642, 'ruRU', 'Боевой топор Властелина Грома', 'Найдите боевой топор Властелина Грома.', 'Последний артефакт – это топор Властелина Грома.$B$BЛэй Шэнь сражался, держа в одной руке копье, а в другой – топор.$B$BГоворят, что он мог бросить этот топор с ужасающей точностью, а, настигая жертву, оружие гремело подобно грому.$B$BПосле смерти Императора топор был помещен в церемониальный зал в юго-западной части.$B$BИзлишне говорить, что и топор не должен попасть в руки могу.', '', '', '', '', '', 'Вернитесь к Чжи Безмятежному в Тихий приют в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (30647, 'ruRU', 'Tracking Quest: Opened the Golden Valley', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30648, 'ruRU', 'Только вперед!', 'Поговорите с Фэй и отправляйтесь в долину Четырех Ветров.', 'Твое путешествие по этой земле было полным событий, $gстранник:странница;, да и моему, похоже, еще суждено продолжаться какое-то время.$b$bЦепь событий началась с вашего прибытия сюда, и хотя некоторые из них весьма опечалили, я чувствую, что за твоим появлением стоит нечто большее.$B$BСейчас было бы мудрым оставить это место и исследовать другие районы Пандарии.$B$BОбратись ко мне, когда будешь готов к отъезду.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30649, 'ruRU', 'Святилище Двух Лун', 'Поговорите с Джалуу Щедрым, Мокито Сильным, старейшиной Ляо и мадам Ви Ло в Вечноцветущем доле.', 'Взгляни на это существо, $gстранник:странница;. Почти сразу же после нашего прибытия могу-убийца напал без предупреждения.$b$bЕго целью был глава Золотого Лотоса. К счастью, мы оказались здесь и смогли защитить его.$B$BПосле покушения на Чжи я опасаюсь за жизнь тех, кто пришел в дол.$B$BСмотрители размещают людей в городе к юго-востоку отсюда. Идит туда и поговори с предводителями. Убедись, что они в безопасности.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30650, 'ruRU', 'Пандарены-пленники', 'Освободите 8 пандаренов-пленников.', 'Послушай, я знаю, что Альянсу нужны рекруты, и нас слишком мало, чтобы установить численный перевес в городе.\n\nНо мне стало известно, что яунголы в Огненном лагерь Ордо захватили множество пленников. Не сомневаюсь, если ты освободишь их, они с радостью присоединятся к Альянсу.\n\nЧто скажешь, $n?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30651, 'ruRU', 'Взрыв смеха', 'Взорвите западную, южную и восточную буровые установки. Воспользуйтесь бочонками со взрывчаткой, найденными в огненном лагере Ордо.', 'Давай-ка повеселимся, $gпарниша:девчонка;!$B$BЯунголы Ордо, что на северо-западе, избавили нас от необходимости изготавливать бомбы. Они у них уже есть.$B$BДавай-ка мы используем эти взрывоопасные бочонки себе на благо – взорвем их буровые установки, как думаешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30652, 'ruRU', 'Поддержание магии', 'Убейте ордо – призывателя пепла, ордо – пироманта, ордо – шептателя огня и ордо – заклинателя пламени.', 'Яунголы, обитающие в лагере Ордо, представляют страшную угрозу. Я хочу, чтобы ты $gотправился:отправилась; на северо-запад и $gубил:убила; их вождя.$B$BНо есть одна проблема. Четверо приближенных к нему чародеев, известных как Жильвиси, защищают его пещеру огненным барьером, так что мы не можем попасть туда.$B$BРасправься с ними, и защита пропадет. Они поддерживают магическую связь в шатрах, там ты их и найдешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30653, 'ruRU', 'Какая польза от бочки с пивом?', 'Отнесите пиво стражам Чжу, жрецам Журавлиного Крыла, монахам Шадо-Пан и тауренам-поселенцам.', 'Я вот что думаю.$b$bУ нас есть пиво, которое сварил Чэнь, и все эти воины, которых ты $gсобрал:собрала;. Мы должны их объединить.$b$bТам, на полях, пандарены рискуют жизнью во имя родной страны. Мы с тобой можем хотя бы отнести им бочонок пива.$b$bМожет, они поднимут тост за победу. Может, выпьют в последний раз перед тем, как их прикончит богомол. В любом случае я хочу, чтобы перед боем они выпили хорошего пива.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30654, 'ruRU', 'Залы Го-Лай', 'Проверьте, есть ли могу в Залах Го-Лай.', 'Могу что-то затеяли, это точно.$B$BОни отправили разведчиков в Залы Го-Лай.$B$BСмотрители говорят, что там хранятся старинные реликвии древних императоров. Они не только ценны, но и крайне могущественны.$B$BНельзя допустить, чтобы они достались могу! Отправляйся на северо-запад, вниз по спуску! Останови их!', '', '', '', '', '', 'Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (30655, 'ruRU', 'Пандарены-пленники', 'Освободите 8 пандаренов-пленников.', 'Послушай, я знаю, что Орде нужны рекруты, и нас слишком мало, чтобы установить численный перевес в городе.\n\nНо мне стало известно, что яунголы в Огненном лагерь Ордо захватили множество пленников. Не сомневаюсь, если ты освободишь их, они с радостью присоединятся к Орде.\n\nЧто скажешь, $n?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30656, 'ruRU', 'Взрыв смеха', 'Взорвите восточную, южную и западную буровые вышки. Воспользуйтесь бочонками со взрывчаткой, найденными в огненном лагере Ордо.', 'Взрывать я люблю. У меня это в крови!$B$BУ яунголов в огненном лагере Ордо на западе отсюда бочонки со взрывчаткой просто повсюду лежат.$B$BОчень правильно будет взорвать их насосы для горючей смеси и заодно развлечься.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30657, 'ruRU', 'Поддержание магии', 'Убейте ордо – призывателя пепла, ордо – пироманта, ордо – говорящего с огнем и ордо – заклинателя пламени.', 'Сейчас наибольшую опасность для нас представляют яунголы с Огненного лагеря Ордо. Тебе предстоит отправиться на запад и уничтожить их предводителя.$B$BЭтот трус затаился в пещере, защищенной огненным щитом. Щит постоянно поддерживают четыре волшебника Жильвиси.$B$BУстрани их, и щит спадет. Они сидят в своих шатрах и поддерживают заклинание.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30658, 'ruRU', 'Злючки-колючки', 'Убейте рыболовной пикой 5 колючих иглобрюхов в Сарджунских Глубинах и вернитесь с их хребтами.', 'Ты $gслышал:слышала; что-нибудь о колючих иглобрюхах, $n? Конечно же, нет, ты ж впервые в этих местах!$b$bИх можно встретить в Сарджунских Глубинах, прямо на запад отсюда. Возьми рыболовную пику и постарайся добыть мне несколько ядовитых колючих хребтов этих рыб.', '', 'Осторожнее, эти хребты оставляют чудовищные шрамы!', 'Колючий иглобрюх', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30660, 'ruRU', 'Вестник войны Ордо', 'Убейте вестника войны Ордо.', '<Защита пропала. Время войти в пещеру и убить вестника войны Ордо.>', '', 'Защита больше не действует!', 'Вестник войны Ордо', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30661, 'ruRU', 'Вестник войны Ордо', 'Убейте вестника войны Ордо.', '<Защита пропала. Время войти в пещеру и убить вестника войны Ордо!>', '', 'Защита больше не действует!', 'Вестник войны Ордо', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30662, 'ruRU', 'Вестник войны Ордо', 'Убейте вестника войны Ордо.', 'Вы сняли защиту в огненном лагере Ордо. Скорее идите туда, пока барьер не появился снова.$b$bВремя войти в пещеру и убить их вождя!', '', '', 'Вестник войны Ордо', '', '', 'Вернитесь к адмиралу Тейлору в Приют Западного Ветра на вершине Кунь-Лай.', 19865);
INSERT INTO `quest_template_locale` VALUES (30663, 'ruRU', 'Вестник войны Ордо', 'Убейте вестника войны Ордо.', 'Вы сняли защиту в огненном лагере Ордо. Скорее идите туда, пока барьер не восстановили снова.$b$bВремя войти в пещеру и убить вестника войны Ордо!', '', '', 'Вестник войны Ордо', '', '', 'Вернитесь к генералу Назгриму в Приют Восточного Ветра на вершине Кунь-Лай.', 19865);
INSERT INTO `quest_template_locale` VALUES (30665, 'ruRU', 'Защита оплота Шадо-Пан', 'Убейте 15 зараженных ша яунголов.', 'Я послал за подкреплением из монастыря, но ответа пока нет. Мы уже потеряли город... Может, несколько жителей осталось, но мы здесь в безвыходном положении.\n\nУ нас нет времени на болтовню. Если ты можешь сражаться – помоги моим людям защитить Приют. Если нет – уноси ноги отсюда, иначе долго здесь не протянешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30666, 'ruRU', 'Неожиданная агрессивность кроколисков', 'Убейте 8 кроколисков-смертосмрадов в Ки Крак.', 'Обычно мой день состоит из ловли рыбы, поедания того, что я поймал, и сна. Обрати внимание – пункта \"драка с кроколисками\" в этом распорядке дня нет.$b$bТы, похоже, $gумелый:умелая:c; |3-6($c). Можешь разделаться с этими кроколисками, чтобы я вернулся к нормальной жизни? Кроколиски обычно обитают в Ки Крак, это на северо-западе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30667, 'ruRU', 'Распушили перышки', 'Соберите 6 изумрудных хвостовых перьев, 6 алых хвостовых перьев и 6 тусклых хвостовых перьев.', 'Когда кроколиски напали, они спугнули из гнезд стайку попугаев, и те улетели на остров к северо-западу отсюда.$b$bИз их перьев я бы сделал специальную наживку, которая весьма пригодится, когда и если закончится война с этими рептилиями.$b$bНе желаешь пособирать перья?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30668, 'ruRU', 'На маленьком плоту', 'Соберите 4 куска доски и несколько крепких водорослей.', '<Джей смотрит в направлении Ки Крак.>$b$bХм. Не вижу, чтобы они... успокоились. Нужно попробовать что-то другое.$b$bТебе понадобится плот. Собери доски и водоросли и принеси их мне. А уж я что-нибудь смастерю.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30669, 'ruRU', 'Хранитель истории на озере', 'Залезайте на плот и плывите к ведунье Ана У, что обосновалась в центре лагуны Найели.', 'Теперь твой плот на воде. Плыви на нем в середину озера. Там ты повстречаешь женщину. Ее зовут Ана У.$b$bКаждый раз, когда у меня возникает вопрос, на который я не могу ответить сам, я обращаюсь к ней. Она растолкует нам, почему кроколиски так разбушевались.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30670, 'ruRU', 'Прозрение', 'Соберите 5 сущностей слепой ярости в убежище Огненной Ветви.', 'Наши истинные враги – ша, а не яунголы.\n\nОни – воплощенние эмоций. Их мощь разрушительна и хаотична. А неупорядоченная сила неспособна долго существовать. Наводнение теряет силу, когда потоки воды разделяются. Пожар угасает, когда огонь пожирает последние угли.\n\nМудрость и порядок могут обернуть мощь ша против них самих.\n\nПринеси в деревню сущности ша, и я расскажу об этом подробнее.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30671, 'ruRU', 'Цена мудрости', 'Соберите 5 порций филе акулы.', '<Ана слушает вашу историю и кивает.>$b$bКроколиски нападают? Я знаю историю об этом. И я поделюсь ей с тобой, но сперва... хочу утолить голод.$b$bАкулье мясо было бы весьма кстати. В окрестных водах ты найдешь предостаточно акул.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30672, 'ruRU', 'Равновесие', 'Убейте 10 унга-рыбников.', 'У этой сказки не было счастливого конца. Кроколисков Поющей Котловины больше нет.$b$bНо на сей раз тебе, возможно, выпадет шанс изменить историю.$b$bХозены, что поселились на юге, выловили в тех водах чуть ли не всю рыбу. Без рыбы кроколиски стали голодными и злыми, потому они и нападают на Маристу.$b$bИди же, |3-6($R)! Останови этих рыболовов, что утратили всякое чувство меры!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30673, 'ruRU', 'В западне', 'Спасите Цзиня Теплого Бочонка, Я Огненную Ветвь, старуху Фун и Ся Чжун.', 'Слава небесным духам, ты здесь, |3-6($c)! Я не знаю, сколько времени мне бы удалось еще продержаться.$B$BВ Убежище Огненной Ветви еще есть выжившие! Поможешь им спастись и добраться до Оплота Шадо-Пан?', '', '', '', '', '', 'Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.', 19865);
INSERT INTO `quest_template_locale` VALUES (30674, 'ruRU', 'Равновесие без насилия', 'Бросьте 6 вертлявых карпов в лагуну Найели.', 'Кажется, еще не вся рыба, выловленная унга-хозенами, умерла. Может, ты еще успеешь бросить ее обратно в воду.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30675, 'ruRU', 'Зарытое сокровище хозенов', 'Найдите зарытое сокровище хозенов.', 'Карта, которую вы держите в руках, потрескалась, запачкалась и нарисована кое-как, но на берегу там явно нарисован большой крестик.$b$bНеужели где-то на этом острове зарыто сокровище?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30678, 'ruRU', 'Проще пареной... бомбы', 'При помощи гоблинской бомбы для рыбалки убейте 3 скатов-хвостоколов, заберите их острые шипы и принесите Свистеру. Скаты водятся на мелководье к западу от Деревни рыболовов.', 'Не так-то просто, оказывается, поймать этих скатов! Ты, вроде, $gпарень ловкий:девушка сообразительная; – так не поможешь ли мне?$b$bЯ изготовил бомбы, но плыть на плоту не могу – нога болит. Скаты водятся на отмели к западу отсюда. Возьми бомбы, плыви туда на моем плоту и добудь мне их острые шипы!$b$bА, да – осторожно, там акулы!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30680, 'ruRU', 'В западне', 'Спасите Цзиня Теплого Бочонка, Я Огненную Ветвь, старуху Фун и Ся Чжун.', 'Спасибо тебе, огромное спасибо. Если бы не ты...$B$BПостой-ка! В убежище наверняка еще кто-нибудь остался!$B$BПрошу тебя, |3-6($c), умоляю. Спаси остальных и помоги нам попасть в Оплот Шадо-Пан.', '', '', '', '', '', 'Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.', 19865);
INSERT INTO `quest_template_locale` VALUES (30681, 'ruRU', 'В западне', 'Спасите Цзиня Теплого Бочонка, Я Огненную Ветвь, старуху Фун и Ся Чжун.', 'Огромное тебе спасибо! Мне бы никак не удалось выбраться оттуда.$B$BПослушай-ка, а ведь в Убежище Огненной Ветви тоже, наверное, кто-то ждет помощи. Мы сможем спасти их и добраться до Приюта Шадо-Пан?', '', '', '', '', '', 'Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.', 19865);
INSERT INTO `quest_template_locale` VALUES (30682, 'ruRU', 'В западне', 'Спасите Цзиня Теплого Бочонка, Я Огненную Ветвь, старуху Фун и Ся Чжун.', 'Как тебе удалось сюда попасть?!\n\nОх, сколько бы мне пришлось тут торчать, если б не ты.$B$BНо ведь и другие в том же положении. Слушай, |3-6($c), их надо спасти и отвести в оплот Шадо-Пан, а там уж мастер что-нибудь придумает.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30683, 'ruRU', 'Несчастье путника', 'Поищите припасы в брошенных обломках.', 'Ты что, $gкидался:кидалась; в них нашими припасами?! А почему нельзя было воспользоваться оружием? Или всякими заклинаниями и приемчиками? Ну почему именно припасы?!$b$bТеперь мы не сможем протянуть до конца, особенно с этим племянником Кривым Ногтем. Он же жрет, как йети!$b$bТак, раз ты $gвыкинул:выкинула; все наши припасы, то тебе придется раздобыть новые. Чуть дальше по пути произошло крушение. Возможно, ты сможешь что-нибудь найти в тех обломках.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30684, 'ruRU', 'Причуда Искателя', 'Пройдите путь под названием \"Причуда Искателя\", чтобы найти хранителя истории Чо. По пути остановитесь у трех храмов.', 'Я уверен, что у твоего пандарийского друга есть пара идей насчет планов могу.$B$BОн пошел на гору пару дней назад без проводника и сказал, что лишь ты $gдолжен:должна; последовать за ним. Он выразился очень конкретно:$B$B\"$c $gдолжен:должна; пройти этот путь без чьей-либо помощи, наедине со своими мыслями. Пусть $gон:она; почтит каждое святилище по пути, прежде чем встретится со мной.\"$B$BЭта тропа находится к северо-западу от лагеря, она отмечена флагами. Пожалуйста, будь осторожнее! Причуда Искателя – опасный маршрут, даже если тебе сопутствует удача.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30690, 'ruRU', 'Сорвать маску с яунгола', 'Заманите хана Кобая в ловушку ослепляющей ярости, сорвите с него маску Злобной ярости и затем победите Злобную ярость.', 'Просто убив хана Кобая, ты ничего не добьешься, поскольку он одержим крайне мощным и разрушительным ша – Злобной яростью.\n\nИз сущностей ярости, что ты $gпринес:принесла;, я изготовил ловушку. Замани хана в эту ловушку, а затем сорви с него маску. Как только наденешь ее, явится Злобная ярость и попытается овладеть твоим разумом.\n\nПобеди его, и мы сможем обратить эту печальную ситуацию себе на пользу. Хан сейчас на севере, охвачен безумным гневом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30691, 'ruRU', 'Страдания', 'Избавьте Нахассу от страданий.', 'Когда окажешься под водой, ты $gдолжен:должна; будешь убить Нахассу, патриарха смертосмрадов. Он страдает. Я слышу, как его предсмертные крики доносятся до поверхности лагуны.$b$bНайди пещеру Нахассы и избавь его от страданий. Не потому, что это решит проблему Маристы с кроколисками. Просто из милосердия.', '', 'Даже самое страшное чудовище заслуживает милосердия.', 'Нахасса', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30692, 'ruRU', 'Джутовый путь: лагерь Коту', 'Защищайте отряд груммелей по дороге от путевой станции Джутового пути до лагеря Коту. Хотя бы один груммель должен остаться в живых.$b$bЕсли отряд будет потерян, ищите его на Джутовом пути или вернитесь на путевую станцию и дождитесь следующего отряда.', 'Тут земля хозенов. Опасно. Но груммелям надо пройти. Пронести груз до Змеиного Хребта.$b$bЗащити отряд груммелей по дороге в лагерь Коту.$b$bЕсли хоть один груммель дойдет до конца пути, тебя ждет удача.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30694, 'ruRU', 'Ступай легко', 'Обезвредьте 10 шипастых ловушек Речного Клинка с безопасного расстояния, используя \"Испытующий взгляд\".', 'Ученики говорят мне, что в округе полно смертельных ловушек – наверняка их расставили сауроки. Ступишь в такую – и все лицо будет истыкано шипами.$b$bКак гласит пословица, \"Путь изобилует опасностями – ступай осторожно, смотри испытующе\".$b$b<Коро вручает вам длинную ветку.>$b$bВот твой \"испытующий взгляд\".$b$bЕе длины должно хватить, чтобы снять ловушки с безопасного расстояния.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30695, 'ruRU', 'Что ждет на Пути', 'Уничтожьте Пасти Отчаяния в восточной и западной пагодах храма Красного Журавля.', 'Огромные Пасти Отчаяния в пагодах по обеим сторонам храма извергают из себя ша. Тем временем, твоя импровизированная тренировка следованию Пути продолжается.$b$b\"Та, что зашивает порванный зонтик, промокнет меньше той, что бьет по дождю\".$b$bИ хоть я не вполне согласен с этим утверждением – иногда удары по дождю приносят немалую пользу, – в нашем случае оно истинно.$b$bУничтожь эти Пасти Отчаяния и дай моему ордену шанс вернуть себе храм.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30698, 'ruRU', 'Сбор металлолома', 'Возьмите рыбацкий плот гоблина и соберите 15 ржавых обломков кораблекрушения в плавающем хламе около корабля.', 'Ты! Тебя-то я и ищу!$b$bМне нужны запчасти к бомбам для рыбалки, но я повредил ногу и сам их собрать не смогу.$b$bВидишь, вон там, рядом, обломки корабля, потерпевшего крушение? Готов биться об заклад: там есть то, что мне нужно, остается выудить это из воды. Возьми мой рыбацкий плот, сплавай туда и поищи хорошенько! Мой приятель уже пытался помочь, так что если увидишь его плоты там, пользуйся на здоровье.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30699, 'ruRU', 'К лагерю Зимнего Цветения', 'Поговорите с Линем Беззвучным Ударом в лагере Зимнего Цветения на вершине Кунь-Лай.', 'Борьба с ша вечна, и мы не можем покинуть это место.\n\nТем не менее, меня беспокоит, что подкрепление из монастыря все еще не прибыло, ведь мы посылали за ним пару дней назад.\n\nТы достойно $gпоказал:показала; себя, может быть, отправишься в лагерь Зимнего Цветения? Это по дороге в монастырь Шадо-Пан. Поговори с Линем Беззвучным Ударом, когда доберешься туда, – он опытный разведчик и наверняка знает, в чем дело. Чтобы добраться туда, иди от деревни на север. Дорога в низину Шадо-Ли проходит через перевал Шадо-Пан.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30700, 'ruRU', 'Клешнехват', 'Убейте клешнехвата на дне Поющей Котловины и прихватите его клешню как доказательство.', 'Огромный ядовитый краб сеет хаос в наших колониях морских ушек. Я хочу, чтобы ты $gспустился:спустилась; в Поющую Котловину и убил его!', '', 'Клешнехват – гроза здешних моллюсков.', 'Клешнехват', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30701, 'ruRU', 'Суп из шустрого краба', 'Убейте на побережье шустрых крабов – рыболовов и соберите 16 их глаз для вкусного супа.', 'Ничто не сравнится по вкусу с супом из шустрого краба. Это фирменное блюдо Красаранга!$b$bЯ как раз собирался его сварить, когда понял, что мне не хватает главных ингредиентов – глаз!$b$bУбей шустрых крабов – рыболовов и принеси мне их глаза для супа!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30715, 'ruRU', 'Несломленная оборона', 'Упокойте шадо-мастера Чжияо, Лю Тысячу Ударов и Шию Кипящую Кровь.', 'Когда мы перегруппировались после их первой атаки, нас стало на троих меньше. Ты можешь сражаться, и мы должны организовать оборону, если эти проклятые яунголы снова пойдут в атаку.\n\nЕсли ты хочешь помочь, упокой души наших павших товарищей и забери их доспехи. Тела ты найдешь к западу отсюда, возле ворот.\n\nА еще отгони от их тел падальщиков.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30716, 'ruRU', 'В погоне за надеждой', 'Прикоснитесь к 3 духам Журавля.', 'Чи-Цзи всегда с нами. Даже когда его нет в Колыбели, частички его души летят по лесу и берегам острова, следят за нами и испытывают нас.$b$bДокажи Чи-Цзи свою ловкость, $n. Найди и поймай духов Журавля.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30717, 'ruRU', 'Дары Великого Журавля', 'Соберите 10 даров Великого Журавля.', 'Журавли Красаранга – дар Чи-Цзи. Даже перья, которые они сбрасывают, – великое благо для нас.$b$bЭтими перьями мы украшаем одежду и оперяем стрелы. Но сначала... их нужно собрать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30718, 'ruRU', 'Ученики Чи-Цзи', 'Сразитесь с 10 учениками Чи-Цзи.', 'Наш орден гордится своим боевым мастерством. Мы оттачиваем его, сражаясь друг с другом здесь, в Колыбели Чи-Цзи.$b$bПокажи свою доблесть Красному Журавлю. Отправляйся на юг, в центр острова, и сразись в поединках со своими товарищами-учениками.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30719, 'ruRU', 'FLAG - Cradle of Chi-Ji Progress Bit 01', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30720, 'ruRU', 'FLAG - Cradle of Chi-Ji Progress Bit 02', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30721, 'ruRU', 'FLAG - Cradle of Chi-Ji Progress Bit 03', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30722, 'ruRU', 'FLAG - Cradle of Chi-Ji Progress Bit 04', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30723, 'ruRU', 'Честь после смерти', 'Убейте 12 падальщиков Кунь-Лай.', 'Хм... Раз шадо-мастер Чун доверяет тебе, может, ты нам и пригодишься.\n\nЯунголы – наши враги.\n\nНужно доказать, что мы лучше их. Мы уважаем мертвых.\n\nКак всегда, падальщики уже начали свой кровавый пир. Уменьши их число, чтобы тела наших противников остались неоскверненными. Они собрались на поле битвы, это к западу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30724, 'ruRU', 'На стену!', 'Поговорите с мастером воздушных змеев Лэнем в лагере Зимнего Цветения, что на вершине Кунь-Лай, чтобы подняться на воздушном змее наверх, на стену над вратами Быка. Оказавшись там, поговорите с Суной Беззвучный Удар.', 'Они снова атакуют!\n\n<Линь глядит в сторону Врат Быка.>\n\n Лучники... на стене!\n\nСможешь забраться туда? Моя жена Суна только что отправилась на разведку к стене с этим придурком, Лао-Чинем. Если бы он больше времени уделил организации обороны, вместо того чтобы заниматься сооружением этого нелепого хмельного лифта...\n\nНеважно. Заберись туда и найди мою жену. Она знает, что делать дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30725, 'ruRU', 'Эллия Вороная Грива', 'Победите Эллию Вороную Гриву в павильоне Ангхал.', 'Мы постоянно устраиваем поединки один на один между учениками, которые, на наш взгляд, достойны друг друга. Мы нашли такого партнера и тебе, $n.$b$bЕе зовут Эллия Вороная Грива. Для нее, как и для тебя, это будет первая дуэль. Она ждет тебя в павильоне к югу отсюда.', '', 'Ваш первый противник.', 'Эллия Вороная Грива', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30726, 'ruRU', 'Минь До-Тан', 'Победите Минь До-Тана.', 'Твой следующий соперник тоже из новичков. Его зовут Минь До-Тан, и он победил в двух своих последних боях.$b$bОн будет ждать тебя у статуи журавля на юге.', '', '', 'Минь До-Тан', '', '', 'Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30727, 'ruRU', 'Эллия Вороная Грива: реванш', 'Победите Эллию Вороную Гриву у подножия Пьедестала Надежды.', 'Эллия Вороная Грива хочет вновь сразиться с тобой. Похоже, она сочла тебя своим принципиальным соперником.$b$bЗдесь, в Колыбели Чи-Цзи, мы не одобряем такого рода конкуренцию, но и просьбу о реванше мы отклоняем редко. Ты найдешь Эллию на Пьедестале Надежды, это в восточной части острова.', '', 'Она жаждет реванша!', 'Эллия Вороная Грива', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30728, 'ruRU', 'Толстяк Лун-Фат', 'Победите Толстяка Лун-Фата на крыше павильона Ангхал.', 'Теперь ты встанешь в пару с... особым учеником. Его зовут Толстяк Лун-Фат.$b$b<Телоний тщательно выбирает слова.>$b$bТолстяк Лун-Фат... дерется иначе, чем принято. Он выходит на поединок не каждый день, но когда выходит, то сам выбирает себе противника. Сегодня по какой-то причине... он выбрал тебя.$b$bТы найдешь его на крыше павильона Ангхал.', '', '', 'Толстяк Лун-Фат', '', '', 'Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30733, 'ruRU', 'Тукка-Тук', 'Победите Тукка-Тука.', 'Ты становишься у нас знаменитостью, $n. С тобой хочет выйти на поединок один из наших опытных бойцов. Он считает, что ты не так $gсилен:сильна;, как кажешься.$b$bЕго зовут Тукка-Тук, и он хозен. Если ты когда-нибудь $gдрался:дралась; с хозенами, то знаешь, что они весьма сообразительны, несмотря на свой глупый вид. Удачи.', '', '', 'Тукка-Тук', '', '', 'Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30742, 'ruRU', 'Взять козла за рога', 'Убейте 12 одурманенных кафой горных козлов на пике Коту.', 'Плохая идея была. Очень.$B$BНепросто вынимать семена из ягод кафы. Появилась тут идея: козлы-то ягоды едят, а семена из них выходят... на другой день.$B$BНу что, сожрали козлы с пика Коту все мои ягоды и взбесились! Кидаются на все, что движется.$B$BПик Коту раньше был безопасным, там груммели кафу собирали. А теперь все, козлы – штука такая. Поможешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30743, 'ruRU', 'Изысканная кафа', 'Отметьте 10 \"складов\" кафа-гуты на пике Коту.', 'Гениально же: ягоды кафы даешь козлу, а на выходе семена.$B$BКафа\'кота и так бешеных денег стоит, да и не достанешь, а тут кафа-гута – пальчики оближешь!$B$BТолько не вышло ничего. Дядя злится, на горе бедлам. Мне бы хоть достать кафа-гуту, которая уже получилась, и больше не связываться.$B$BСобирать не прошу – работа грязная, не для героев – просто оставляй метки, чтоб мне найти было проще, когда опять можно будет на гору ходить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30744, 'ruRU', 'Смесь кафы', 'Соберите 100 ягод кафы на пике Коту. Кусты кафы растут на горных склонах, а в пещерах йети можно найти запасы ягод.', 'Пик Коту знаменит своей кафой – больше на такой высоте ничего не растет.$B$BГруммели торгуют кафой и неплохо наживаются, но теперь это стало опасно благодаря моему родственничку. Он там все на уши поставил, хотел кафой разжиться.$B$BКафа\'коту найти все сложнее: то козлы кусты объедят, то йети все перетаскают.$B$BЯ хорошо заплачу, если ты принесешь с пика Коту ягоды кафы.$B$BВот такие они, эти ягоды. Съешь, и сразу узнаешь силу кафы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30745, 'ruRU', 'Расхлебывать кафу', 'Убейте 5 одурманенных кафой йети в пещерах на пике Коту.', 'Да, на пике Коте водятся йети. Обычно они мирные, едят козлов.$B$BНо теперь они едят козлов, нажравшихся кафы.$b$b<Остробоб недовольно смотрит на кузена Шерстомеха.>$b$bТеперь они просто бешеные, и, похоже, никогда не спят. Пристрастились к кафе, видать.$b$bВот-вот вылезут из пещер. Пойдут сами кафу искать...$b$bВот это будет беда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30746, 'ruRU', 'Честная сделка', 'Принесите мешок ягод кафа\'коту в логово Коту Кон недалеко от пика Коту.', '<Вновь раздается страшный вой, так громко и страшно не ревел еще ни один встреченный вами йети. А затем голос груммеля.>$B$BОй! Умоляю, могучая Коту Кон, прости груммеля. Отпусти меня, я принесу много-много кафы, обещаю!$B$B<Существо, названное Коту Кон, издает ответный рев.>', '', 'Ужас пика Коту', 'Коту Кон', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30747, 'ruRU', 'Джутовая резня', 'Напоите Коту Кон кафой из фляжки в лагере Коту, а затем убейте 100 хозенов на Джутовом пути.', 'Так... Начало хорошее, она пока никого не ест.$B$BОна хочет больше кафы, но нам надо еще придумать, на что тратить ее энергию...$B$BЕсть идея! Джутовый путь! Она может отгонять хозенов хоть весь день!$B$B<Колючник поворачивается к огромному зверю.>$B$BКак думаешь, красавица? Пойдешь гонять хозенов?$B$BПохоже, да. Угости ее кафой из моей неприкосновенной фляжки. Ты ей нравишься.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30750, 'ruRU', 'А ну слезь оттуда!', 'Убейте 12 опытных осулов-лучников или осулов – воинов огня.', 'Яунголы-лучники стоят на стене и прикрывают тех, что внизу. Не знаю уж, что там Лао-Чинь думает, но тебе надо разобраться с этими стрелками.\n\nНам повезло, что дух Быка на нашей стороне. Когда враги ослабеют, дух Быка оглушит их, и ты сможешь столкнуть их со стены.\n\nЛучников ты найдешь сразу за этой дверью.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30751, 'ruRU', 'Ужасная жертва', 'Собрать 6 бочек с яунгольской нефтью.', 'Я тут подумал и... готов принести ужасную жертву.\n\nНасколько я понял, мой крепкий хмель укрепит дух защитников Врат Быка и позволит им продержаться подольше...\n\nМне не хотелось бы сейчас погружаться в детали, но прошу тебя – пока будешь на стене, собери бочки с нефтью, которую они используют, чтобы поджигать стрелы. Они нам пригодятся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30752, 'ruRU', 'Невероятно!', 'Поговорите со стражем монастыря Шадо-Пан и потребуйте, чтобы вас впустили.', 'Я просто отказываюсь поверить, что стражники не пустят нас в монастырь, если мы убедим их в серьезности ситуации.\n\nДруг, иди на восток к стражникам и потребуй, чтобы нас пустили. Я пойду с тобой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30753, 'ruRU', 'Верхом на акуле', 'Убейте разъяренную рифовую акулу голыми руками.', 'Есть только один способ убить акулу там, откуда я родом, – голыми руками!$b$bЯ накидал в воду рядом с пристанью достаточно много приманки, так что это место скоро будет кишеть местными рифовыми акулами. Прыгай на первую, которую увидишь, и расправься с ней!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30754, 'ruRU', 'Яркая наживка', 'Соберите 7 солнечных ползунов в лесу к северу от Деревни рыболовов.', 'Некоторых рыб можно подманить только ярким светом. В лесу к северу отсюда водятся пандаренские светляки, которых называют солнечными ползунами.$b$bИх можно найти у корней пней. Принеси мне пригоршню таких светляков, и я пущу их на наживку!', '', 'Этих маленьких светящихся насекомых можно обнаружить у подножия деревьев в Красарангских джунглях.', 'Солнечный ползун', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30757, 'ruRU', 'Глава Шадо-Пан', 'Избавьте Тажаня Чжу от одержимости Ша Ненависти.', 'В нашего настоятеля Тажаня Чжу вселился ша – воплощение чистой ненависти. Монастырь погиб!$B$B$c, я знаю, ты найдешь способ излечить настоятеля! Кажется, он медитирует в Роще Опадающих Лепестков.', '', 'Надо освободить его от Ша Ненависти!', 'Тажань Чжу, глава Шадо-Пан', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30759, 'ruRU', 'Прямо в пекло', 'Поговорите с Новобранцем Киа в додзё Небесного Удара, что в монастыре Шадо-Пан.', 'Монастырь Шадо-Пан захвачен!$B$BНовобранцу Киа удалось сообщить мне, что все его обитатели попали под воздействие ша. Страшнее всего, что это случилось даже с нашим господином, Тажанем Чжу.$B$B$c, ты можешь отправиться к северу, в горы? Ты войдешь в монастырь через додзё Небесного Удара. Там прячется Киа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30763, 'ruRU', 'Пираньи!', 'Поймайте 5 волчьих пираний в реке Красаранг в Красарангских джунглях.', 'Иную рыбу бывает очень трудно поймать. Волчья пиранья – как раз из таких рыбок.$b$bМне повезло, что сюда $gявился:явилась; ты! Проверим твои рыбацкие умения: принеси мне несколько пираний из реки Красаранг, что к северо-западу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30765, 'ruRU', 'Восстановленная честь', 'Верните знамя Чжэня.', 'Значит так, $n. Яунгольский вождь Громила убил шадо-мастера Чжэня и завладел его знаменем.$B$BУбей Громилу и восстанови честь Мстера Чжэня, или это сделаю я.', '', '', 'Громила', '', '', 'Вернитесь к У Као Блейку к Вратам Зимнего Цветения на вершине Кунь-Лай.', 19865);
INSERT INTO `quest_template_locale` VALUES (30766, 'ruRU', 'Ценный антиквариат', 'Соберите еще 11 реликвий могу.', '<Со статуи падает реликвия. Да, знаток оценит эту вещь по достоинству.>$B$B<В этих же руинах бродит искатель сокровищ. Возможно, он захочет выкупить у вас находку?>', '', '', '', '', '', 'Поговорите с Бао Цзянем у Могуцзя на вершине Кунь-Лай.', 19865);
INSERT INTO `quest_template_locale` VALUES (30767, 'ruRU', 'Рискнуть всем', 'Избавьте Шэнь-Цзынь Су от занозы.', 'Погоди, что?! Какое безрассудство! Взорвать корабль – это просто безумие! Они могли убить Шэнь-Цзынь Су и всех нас заодно.$b$BЯ знаю, времени у нас мало, но мы должны найти какой-то другой способ...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30768, 'ruRU', 'Мой муж...', 'Встретьтесь с Суной Беззвучный Удар на укреплениях Лун-Ин в Танлунских степях.', 'Линь...\n\nМне все равно, что говорят Бань, Лао-Чинь или даже Тажань Чжу. Я направляюсь в Танлунские степи. Возможно, мне не удастся спасти Линя самостоятельно, но я не собираюсь рассиживаться и ждать, пока это сделают все остальные.\n\nКак только Тажань Чжу откроет двери своего драгоценного монастыря, мы спасем Линя. А до того я отправлюсь на разведку – убедиться, что с ним все в порядке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30769, 'ruRU', 'Первое нападение', 'Убейте 6 осулов-остророгов.', 'Теперь, когда мы хорошенько поразмышляли о слабостях наших врагов, можно нанести яунголам прямой удар.$B$BИди и сразись с осулами-буянами на западном плоскогорье.$B$BДай им знать, что мы здесь и не боимся их угроз.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30770, 'ruRU', 'Разъяренный скот', 'Испугайте 8 мохнатых яков или степных зверей.', 'Что нужно каждой армии, так это провизия.$B$BВо вражеском лагере к западу отсюда пасется большое стадо, которое служит основным источником еды для яунгольской армии.$B$BК счастью для нас, яков и диких мушанов, водящихся в этой местности, легко испугать.$B$BПрокрадись туда, отвесь им хороших шлепков и погляди, что из этого выйдет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30771, 'ruRU', 'Лучшая смола', 'Соберите 8 кусков черной смолы.', 'Когда племя осулов идет на войну, его воины смазывают свои копья и стрелы горючей смолой, которая легко воспламеняется.$B$BОни используют это ужасное оружие, чтобы не только проливать кровь, но и стирать жилища врагов с лица земли.$B$BМне нужно, чтобы ты $gсобрал:собрала; эту смолу, пока будешь в их лагере.$B$BС ее помощью мы покажем яунголам, что, когда играешь с огнем, можешь и сам обжечься.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30772, 'ruRU', 'Время ярости', 'Убейте 8 осулов-мародеров или осулов-огнеплюев.', 'Перед нами главный костяк армии яунголов.$B$BОни стягивают огромные силы, чтобы напасть на поселения Кунь-Лай.$B$BЕсли мы сейчас нападем на осулов, то сможем здорово подорвать их силы.$B$BПомни – каждый, кого мы здесь убьем, не сможет потом убить кого-то из наших.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30773, 'ruRU', 'Смола – тоже оружие', 'Используйте взрывчатку Баня, чтобы уничтожить 6 баллист осулов.', 'Осадные орудия яунголов – баллисты, метающие копья, разрушают наши защитные сооружения как на укреплениях Лун-Ин, так и на вершине Кунь-Лай.$B$BЭти ужасные орудия должны быть уничтожены.$B$BВозьми эту взрывчатку. Я обработал ее смолой, которую ты $gсобрал:собрала;.$B$BБрось ее в эти баллисты, и пусть яунголы испытают мощь собственного оружия на себе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30774, 'ruRU', 'Спасение стрелков', 'Откройте деревянные клетки, чтобы освободить 4 стрелков Лун-Ин и Линя Беззвучный Удар.', 'Хочу попросить тебя об очень серьезной услуге, $n.$B$BГде-то в клетках посреди лагеря осулов заперт мой муж, Линь, свет моих очей.$B$BПожалуйста, найди его и приведи ко мне, а еще освободи столько наших соратников шадо-панов, сколько сможешь.$B$BТебе нужно найти ключи к этим клеткам у осулов-мародеров.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30775, 'ruRU', 'Изгнанник', 'Убейте Юранга, Ку-Туна и Баттата.', 'Да что тут говорить, $gнезнакомец:незнакомка;...$B$BЯ сражался с Цзюн Дуком и проиграл. Я был дураком и поверил, что он будет сражаться честно.$B$BТеперь мои собственные братья обратились против меня, и вот я вынужден говорить с врагами.$B$BЯ знаю, что ты здесь, чтобы пролить кровь осулов.$B$BПрошу только об одном – убей тех троих, кто предал меня.$B$BЭто Юранг, который отравил мое питье. Ку-Тун, который согнул мое копье. И Баттат, который вонзил мне в бок кинжал, когда я был на волосок от победы.$B$BСделай это, и я смогу умереть спокойно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30776, 'ruRU', 'Цзюн Дук', 'Поднимите знамя шадо-панов на церемониальном шесте, затем убейте Цзюн Дука.', 'Это война!$B$BЯ получу головы всех, кто отнял у меня Линя. Всех и каждого!$B$BМы начнем с вождя осулов, Цзюн Дука.$B$BВозьми это боевое знамя шадо-панов и подними его в центре их лагеря.$B$BЦзюн Дук будет вынужден сойтись с тобой в схватке.$B$BБейся с ним без пощады, $n.', '', 'Вождь осулов. Убей его!', 'Цзюн Дук', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30777, 'ruRU', 'Поиски Суны', 'Поговорите с Банем Медвежьим Сердцем после прибытия в Хватку Ненависти.', 'У меня плохие новости. Когда я вернулся, Суна уже исчезла.$B$BОстальные говорят, что она собрала вещи и направилась по восточной дороге, бормоча что-то о том, что положит конец нашествиям яунголов.$B$BНельзя позволить ей в одиночестве бродить по опасным местам.$B$BЯ собрал группу воинов для дальнейшего похода на восток.$B$BМы вскоре выступаем в путь. Запрыгивай на повозку, если хочешь отправиться вместе с Шадо-Пан. Или можем встретиться прямо там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30778, 'ruRU', 'Прах к праху', 'Используйте факел Шадо-Пан, чтобы поджечь 20 трупов жителей деревни Слабого Ветра.', 'Если хотим разбить здесь лагерь, нельзя оставлять гнить все эти тела яунголов.$B$BВозьми этот факел и подожги трупы жителей деревни.$B$BДым от факела заодно очистит землю и воздух вокруг.$B$BДаже наши враги заслуживают того, чтобы покоиться с миром.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30779, 'ruRU', 'Уничтожение падальщиков', 'Убейте 8 пеплозубых гиен.', 'Гниющие трупы привлекают гиен-падальщиков.$B$BОни не просто жрут падаль и разносят болезни: эти дикие твари набросятся на нас, как только завидят.$B$BИди и уничтожь этих зверей. Неприятное задание, но нужное.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30780, 'ruRU', 'Изучение тотемов', 'Соберите 9 тотемов деревни Слабого Ветра.', 'Когда мы вошли в деревню, по всему лагерю лежали тотемы яунголов.$B$BЕсть у меня подозрение, что тут задействованы темные силы, а эти тотемы помогут разобраться в природе этих сил.$B$BСможешь ли ты принести мне несколько этих тотемов для дальнейшего изучения? Мне бы хотелось внимательно их осмотреть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30781, 'ruRU', 'Тяжкий рок яунголов', 'Отведите Сяо Ту к клубам дыма в Хватке Ненависти.', 'Бань попросил меня осмотреть деревню, чтобы определить, что там произошло.$B$BС востока, запада, северо-запада и юга поднимается дым.$B$BМне нужен кто-то, кому я доверяю и кто может прикрыть меня.$B$BЧто скажешь? Поможешь мне в первой вылазке?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30782, 'ruRU', 'Недобрые духи', 'Убейте 10 недобрых духов.', 'Духи погибших жителей деревни вернулись в мир живых! Я чувствую исходящую от них ненависть.$B$B$n, если мы хотим здесь выжить, то должны себя защитить. Это единственный способ их упокоить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30783, 'ruRU', 'Мы во власти ненависти', 'Используйте тотем гармонии, чтобы изгнать духи ша из 8 обезумевших следопытов Шадо-Пан. Одержите победу над воплощениями испепеляющей ненависти, чтобы очистить ваших союзников.', 'Нужно было еще раньше догадаться о присутствии ша!$B$BМы в безопасности, пока находимся внутри защитных чар тотема гармонии, но многим из нашего лагеря повезло меньше.$B$BОни оказались в ловушке снаружи лагеря, когда проявила себя сила ша, и теперь обратились друг против друга!$B$BВозьми с собой один из моих тотемов. Помести его рядом с обезумевшим союзником, чтобы очистить его, но проявляй осторожность.$B$BТы можешь столкнуться с тьмой, что заполнила их разум.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30784, 'ruRU', 'Точка невозврата', 'Найдите Суну Беззвучный Удар.', 'Один из наших следопытов доложил, что видел Суну на холме на северо-западе.$B$BКакое облегчение знать, что она в целости и сохранности. Я опасался того, что она могла сотворить в своем горе.$B$BСможешь ли ты поговорить с ней от моего имени?$B$BВозьми с собой этот тотем. Он может пригодиться против опасностей, с которыми ты можешь столкнуться по дороге.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30785, 'ruRU', 'Застава Гао-Жаня', 'Поговорите с господином Тажанем Чжу у Заставы Гао-Жаня в Танлунских степях.', 'С твоей помощью мы упокоили духов этого места.$B$BНаконец-то они обрели мир.$B$BНаше путешествие по этой проклятой земле, боюсь, только началось.$B$BМне еще нужно закончить здесь несколько важных дел, но мы уже скоро отправимся в путь.$B$BМне нужно, чтобы кто-нибудь поехал вперед и предупредил господина Тажаня Чжу, что мы к нему присоединимся.$B$BНайди его у Заставы Гао-Жаня. Расскажи ему о том, что здесь произошло.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30786, 'ruRU', 'Копье в боку, сердце на цепи', 'Убейте Дмонга Наруука, шамана, который захватил Орбисса.', 'Моя жизнь кончена. Яунгол проткнул мне бок копьем. Эта рана смертельна.$b$bЯунгол поймал меня в сети своей темной магии. Такой позор... Это страшнее смертельной раны.$b$bЯ не могу остановить смерть. Но ты можешь освободить мою душу.', '', 'Могущественный туманный шаман из племени осулов.', 'Дмонг Наруук', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30787, 'ruRU', 'Факелы', 'Раздобудьте 6 факелов туманного шамана.', 'До недавнего времени шаманы яунголов приходили к нам как друзья. А теперь они подчиняют наших людей своей воле.$b$bОни убивают тех, кто противится их власти. А заодно и тех, кто им подчиняется.$b$bСила туманного шамана яунголов в его факеле. Отбери факел, и он уже ничего не сможет сделать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30788, 'ruRU', 'Голгосс', 'Призовите Голгосса. Для этого нужно воткнуть факелы туманных шаманов в торфяной ком в Верхних Камышовых топях.', 'Предводителя туманных шаманов яунголов зовут Джахеш. Он славится своей силой.$b$bНо у нас есть тот, кто может противостоять ему, и зовут его Голгосс.$b$bОн дремлет в туманах Верхних Камышовых топей. Помоги мне призвать его, и он поможет мне отомстить за наш народ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30789, 'ruRU', 'Арконисс', 'Призовите Арконисса. Для этого нужно воткнуть факелы туманных шаманов в торфяной холмик в Верхних Камышовых топях.', 'Если я хочу сразиться с Джахешем, вождем туманных шаманов, мне нужно заручиться поддержкой Арконисса. Свирепость Арконисса не знает равных.$b$bОн отдыхает в туманах Верхних Камышовых топей. Найди его жилище, и призови его с помощью факелов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30790, 'ruRU', 'Голод Голгосса', 'Добудьте 10 витых лоз.', 'Голгосс очень силен, но ему нужно питание, чтобы воспользоваться силой.$b$bУ кустов заплетня в Верхних Камышовых топях толстые, мясистые ветви. Это должно утолить его аппетит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30791, 'ruRU', 'Жажда Арконисса', 'Добудьте 4 образца свернувшейся крови грызунов.', 'В бою Арконисса охватывает невыразимая ярость, но долгое пребывание в туманах подорвало его силу.$b$bНа болотах водится много грызунов, а их тела наполнены питательной кровью. Вернись с достаточным количеством крови, чтобы восстановить боевой дух Арконисса.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30792, 'ruRU', 'Орбисс угасает', 'Добудьте 8 сгустков тумана, пройдя через туманные гейзеры в Верхних Камышовых топях.', 'Я знал, что смерть придет, но не знал, что она настанет так быстро.$b$bМне нужно выиграть время. Туман в Верхних Камышовых топях такой теплый и благоухающий... Этот туман – отличная пища для таких, как я.$b$bСобери его как угодно – в банки, флаконы, заполни им пространство своих сумок. Принеси его сюда – он поможет мне оставаться в своем теле еще какое-то время.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30793, 'ruRU', 'Будущее в тумане', 'Уничтожьте Джахеша-осула.', 'Настало время нанести удар.$b$bГолгосс, Арконисс и я пойдем на восток, во владения Джахеша. Встреть нас там и приготовься к битве.$b$bСегодня мы восстановим гордое имя нашего народа.', '', 'Глава туманных шаманов из племени осулов.', 'Джахеш-осул', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30794, 'ruRU', 'Неотложная помощь', 'Исцелите мудреца Ляо, чтобы он смог подняться на ноги.', 'Я... жив... едва-едва. Остальные убиты. Мои друзья... семья...\n\nЯ должен вернуться в деревню, но мне не хватит сил... Может, ты умеешь лечить? В моей хижине лежит целебный напиток. Если ты владеешь магией, можешь прочитать заклинание.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30795, 'ruRU', 'Оставайся на связи', 'Воспользуйтесь Языком Ба-Шона, войдя в Долину императоров.', 'Язык Ба-Шона позволит нам переговариваться на расстоянии, $n.$b$bЕсли я правильно понимаю принцип работы этого артефакта, то мне не придется покидать это место и прекращать медитацию, а ты сможешь в одиночку отправиться в Долину императоров.$b$bМиши доставит тебя на границу долины, и мы проверим, прав ли я. Будет ужасно, если ты окажешься посреди могил и не сможешь со мной связаться!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30796, 'ruRU', 'Окончательная гибель', 'Уничтожить 5 страдающих душ.', 'Должно быть, души покинули открытые могилы...$b$bДля могу смерть не была концом, а лишь остановкой на пути к новому телу. Темная магия душеловов помогала духам менять оболочки.$b$bНо души, которые провели годы в запертых склепах, просто спятили. Их нужно уничтожить, пока они не рассердились или не обрели новые тела.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30797, 'ruRU', 'Почти живой', 'Вырвите страницу из открытой книги, чтобы отдать ее хранителю истории Чо.', 'Здесь проводился ритуал, но судя по всему, он не был завершен.$b$bСреди разбросанных предметов лежит книга. Вам непонятны письмена на ее страницах.$b$bУнести всю книгу будет тяжело, можно обойтись одной страницей. Возможно, хранитель истории Чо сможет объяснить, что там написано.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30798, 'ruRU', 'Щит Императора', 'Остановите ритуал ловли душ в Гробнице Секретов.', 'Могу осталось совсем немного, и они не живут в больших поселениях. Теперь ясно, что им понадобилось в нашей долине.$b$bИз неупокоенных духов можно собрать огромную армию. И нельзя забывать про зандаларские войска.$b$bА в Гробнице Секретов захоронен отряд великих воинов – Щит Императора. Нельзя допустить, чтобы их воскресили! Этот склеп расположен на самой высокой вершине к юго-западу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30799, 'ruRU', 'Гробница Теней', 'Скопируйте рисунки с таблички династии Шэнь, таблички династии Вай и таблички династии Цян в Гробнице Теней.', 'Судя по артефактам, найденным на алтаре, здесь готовились провести ритуал ловли душ.$b$bБольшинство книг об этом ритуале хранятся в склепах Гробницы Теней. Возможно, там мы найдем ответы.$b$bВозможно, тебе удастся найти еще что-нибудь. Склеп расположен на ближайшем к алтарю холме.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30800, 'ruRU', 'Похитить останки их Властелина Грома', 'Найдите нижнюю часть таблички Лэй Шэня и восстановите скрижаль грома.', 'Нам остается только найти останки Властелина Грома раньше них. Он похоронен в Гробнице Завоевателей.$b$bОтыскать место погребения будет непросто, $n. Несомненно, его могилу защищают стражи, а внутри ждет масса неприятных сюрпризов.$b$bНо попасть внутрь – это еще не все, нужно еще найти сами останки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30801, 'ruRU', 'Уроки Истории', 'Прочитайте скрижаль грома в Гробнице Завоевателей.', 'Властелин Грома был страшным императором, и никто не мог противостоять ему, пока на его стороне были зандалары. Если он вернется, эта земля утонет в насилии и агонии.$b$bНужно найти его останки и перенести их в безопасное место. Скрижаль грома поможет найти место погребения.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30802, 'ruRU', 'Погоня за грозой', 'Заберите кровавую карту с трупа зандаларского воина.', 'Мы должны выяснить, куда они понесут останки Властелина Грома. В Долине Императоров воскрешение провести невозможно, им придется отойти подальше, в безопасное место.$b$bПохоже, выбраться отсюда тоже будет непросто.$b$bПробейся наружу и попробуй выяснить, где сейчас находятся останки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30804, 'ruRU', 'Повелитель Ужаса', 'Убейте Повелителя Ужаса.', 'Больше я этого не вынесу. Моя покойная женушка всю душу в нашу ферму вложила.$b$bА потом яунголы явились, ходят тут, как хозяева, тоже мне. Я хорошо заплачу тебе, если ты сотрешь с мерзкой подлой морды этого типа нахальную улыбочку.', '', 'Он предпочитает манервенность яка силе мушана.', 'Повелитель Ужаса', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30805, 'ruRU', 'Правосудие', 'Убейте капитана Живореза и 6 черногривов-наемников.', 'Наемники напали на нас, ограбили, а потом ушли.\n\nОстался один. Он проткнул насквозь тех, кто выжил. Просто так, для смеха!\n\nОтомсти за погибших. Может, весть о смерти наемников вселит в меня силы, и я смогу жить дальше.\n\nОни расположились к западу отсюда.', '', 'Командир черногривов-наемников.', 'Капитан Живорез', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30806, 'ruRU', 'Запах жизни', 'Найдите прозрачный панцирь голубого краба и 8 украденных пандаренских специй.', 'Мы потеряли очень много своих. Нужно оказать им последние почести, а для этого надо собрать ингредиенты для приготовления благовония жизни. \n\nОно, конечно, пахнет не очень приятно, зато обладает целебными свойствами и даже ускоряет рост растений. Быть может, оно и мне поможет быстрее встать на ноги.\n\nВсе необходимое можно собрать с местных животных – кроме специй, которые забрали наемники, разграбившие деревню.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30807, 'ruRU', 'К водопадам во имя павших', 'Соберите 3 камня, отполированных водопадами.', 'Я должен достойно похоронить своих друзей.\n\nНо нам никогда не приходилось погребать сразу столько тел, мне будет не под силу собрать нужные материалы.\n\nПрошу тебя, пройди по дороге на юг до озер у подножия гор. Водопады на озерах до блеска шлифуют камни, и из них можно сделать надгробия.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30808, 'ruRU', 'Удача груммеля', 'Найдите 8 украденых удачек.', 'Яунголы утащили наши удачки! Прискакали, с копьями, отняли у наших носильщиков на Джутовом пути.$b$bЭто очень дурной знак. Если яунголы узнают секрет удачек, то груммели будут в опасности.$b$bВерни наши удачки из огненного лагеря Жу-Цзинь, и мы подарим тебе много везения.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30814, 'ruRU', 'Первый шаг', 'Убейте 8 осулов-погромщиков.', '<Лорд Тажань пронзает тебя взглядом.>$B$BПоследняя битва оставила на тебе свой след, |3-6($c).$B$BЭто хорошо. На передовой нам нужны такие закаленные воины, как ты.$B$BМы заняли неплохой плацдарм, но яунголы стремятся отбить его.$B$BХочешь показать, чего ты стоишь? Иди к подножию холма и покажи этим яунголам, что мы не отступим.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30815, 'ruRU', 'Моя смерть', 'Вытащите копье из Орбисса.', 'Я решил вытащить это копье из бока.$b$bДля этого мне нужна твоя помощь. Твои руки крепче моих.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30816, 'ruRU', 'Проверка', 'Проведайте мудреца Ляо на побережье Цзоучин на вершине Кунь-Лай.', 'Когда пришли тролли, с ними были наемники, их дружки... Я видел, как они пошли дальше, к лагерю рыбаков, на северо-запад. Там живет мой двоюродный брат, он целитель. Ты можешь проверить, все ли в порядке с ним и с его деревней?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30817, 'ruRU', 'Исцеление Шэнь-Цзынь Су', 'Защищайте лекарей, пока они исцеляют рану Шэнь-Цзынь Су.', 'Вот к чему приводит подобное безрассудство. Как ему вообще могло прийти такое в голову?$b$bЛадно, на разговоры у нас нет времени. Нужно действовать, чтобы спасти Шэнь-Цзынь Су.$b$bНайди всех лекарей, каких только сможешь! Спаси их, освободи – делай все, что понадобится, лишь бы они оказались здесь.$b$bЗащищай лекарей любой ценой!', '', '', '', '', '', 'Поговорите с Аисой Воспевающей Облака на месте падения \"Небесного огня\"', 19865);
INSERT INTO `quest_template_locale` VALUES (30818, 'ruRU', 'Новая судьба', 'Вернитесь в Храм Пяти Рассветов. Вы можете добраться туда на повозке, ожидающей вас у места падения \"Небесного огня\".', '$n, я рада, что план сработал, мы были на волоске от гибели. Если бы не ты, мы бы уже лежали на дне океана вместе с Шэнь-Цзынь Су. Не думаю, что когда-нибудь смогу простить Цзи то, что он вел себя так необдуманно.$b$bУ нас будет много времени на размышления, но сейчас нам необходимо вернуться в Храм Пяти Рассветов. Мы должны сообщить там, что Шэнь-Цзынь Су спасен, и заняться судьбой наших новых союзников.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30819, 'ruRU', 'Подготовка к погребению', 'Вернитесь к Ли Хаю и расскажите ему о похоронах.', 'Благодарю тебя. После всего, что пришлось перенести, удача все же улыбнулась и послала нам тебя.\n\nТеперь мои друзья отомщены, и я могу достойно похоронить их. Я подготовлю все необходимое для церемонии, после чего мы встретимся на кладбище.\n\nА пока не затруднит ли тебя вернуться к моему брату и попросить его созвать на похороны всех селян?', '', '', '', '', '', 'Вернитесь к Ли Хаю в деревню Цзоучин и расскажите ему о похоронах.', 25549);
INSERT INTO `quest_template_locale` VALUES (30820, 'ruRU', 'Похороны', 'Посетите похороны и зажгите благовония жизни.', 'Я соберу всех жителей, и мы придем на похороны.\n\nТы так много $gсделал:сделала;, чтобы души наших друзей обрели покой, что мы просим именно тебя зажечь благовония жизни и проводить их души в мир иной.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30821, 'ruRU', 'Джутовая резня', 'Поговорите с Коту Кон в лагере Коту, чтобы поехать на ней. Затем убейте 100 хозенов на Джутовом пути.', 'Самое время отправиться на \"прогулку\" с Коту Кон.$B$BМы сварили ей два горшка кафы, у нее энергии – хоть отбавляй!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30823, 'ruRU', 'Взять козла за рога', 'Убейте 12 одурманенных кафой горных козлов на пике Коту.', 'Мой двоюродный брат в лагере Коту сделал глупость. Очень большую глупость.$B$BЕму было слишком лень вырезать семечки из ягод кафы вручную, и тут он заметил что козел, съевший кафу, \"возвращает\" семена... через день или около того.$B$BОн скормил всю кафу козлам на пике Коту, и теперь они посходили с ума! Они бодают все, что движется.$B$BНа пике Коту груммелям раньше было безопасно собирать кафу. Теперь это не так. Не с этими бешеными козлами. Ты поможешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30824, 'ruRU', 'Изысканная кафа', 'Отметьте 10 \"складов\" кафа-гуты на пике Коту.', 'Это была сумасшедшая идея: с одной стороны в козла попадают ягоды кафы, а с другой раз – и уже семена.$B$BКафа\'кота уже редкость и стоит уйму денег, но изобретение моего родича, кафа-гута – это изысканно!$B$BНо все кончено. Дядя Остробоб расстроен, а на пике царит беспорядок. Теперь надо только собрать остатки кафа-гуты и больше так не делать.$B$BЯ не прошу тебя собирать ее, это грязная работенка, герои такое не делают. Просто отметь ее, и мы все соберем, когда на горе снова будет безопасно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30825, 'ruRU', 'Смесь кафы', 'Соберите 100 ягод кафы на пике Коту. Кусты кафы растут на горных склонах, а в пещерах йети можно найти запасы ягод.', 'Пик Коту знаменит своей кафой – больше на такой высоте ничего не растет.$B$BГруммели торгуют кафой и неплохо наживаются, но теперь это стало опасно благодаря моему родственничку. Он там все на уши поставил, хотел кафой разжиться.$B$BКафа\'коту найти все сложнее, то козлы кусты объедят, то йети все перетаскают.$B$BДядя Остробоб хорошо заплатит тебе, если ты принесешь с пика Коту ягоды кафы.$B$BВот такие они, эти ягоды. Съешь, и сразу узнаешь силу кафы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30826, 'ruRU', 'Расхлебывать кафу', 'Убейте 5 одурманенных кафой йети в пещерах на пике Коту.', 'Да, на пике Коту водятся йети. Обычно они мирные, едят козлов.$B$BА потом этот балбес Шерстомех скормил козлам кафу, а йети их сожрали.$b$bТеперь они просто бешеные, и, похоже, никогда не спят. Пристрастились к кафе, видать.$b$bВот-вот вылезут из пещер. Пойдут сами кафу искать...$b$bВот это будет беда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30827, 'ruRU', 'Что кроется в тенях', 'Поговорите с Ялией Мудрый Шепот, чтобы начать церемонию.$B$BЗатем активируйте тотем доброты, тотем спокойствия и тотем безмятежности.', 'Если мои подозрения верны, это место все еще преисполнено скрытой тьмой.$B$BЧто бы здесь ни случилось, это не могло быть естественным ходом событий.$B$BДаже яунголы не так жестоки и не истребляют себе подобных до... такого предела.$B$BЯ использую принесенные тобой тотемы, чтобы провести ритуал очищения.$B$BМне $gнужен помощник:нужна помощница; для этой церемонии. Дай мне знать, когда будешь $gготов:готова;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30828, 'ruRU', 'Очищение болота', 'Покажите Говорящему с водой Гожаю источники порчи на озере Чернильной Жабры, чтобы он знал, что вы готовы защищать его во время ритуала очищения.', 'В болото проникает темное вещество, такое же, как было в Мэй.\n\nЯ пойду с тобой. Укажешь мне источники порчи, которые надо устранить.\n\nТебе придется сражаться с тем, что появится оттуда, и защищать меня, пока идет ритуал.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30829, 'ruRU', 'Язык Ба-Шона', 'Помогите хранителю истории Чо провести ритуал Связывания Ба-Шона.', 'Спасибо, что $gпришел:пришла;, $n. Мне пришлось говорить намеками, потому что я опасаюсь, что могу узнают о моей работе.$B$BОни ищут что-то в долине... расхищают гробницы своих старых королей в поисках могущественных реликвий.$B$BМне не удалось долго понаблюдать за ними – пришлось бежать. Однако и мне удалось утащить один артефакт.$B$BЯзык Ба-Шона позволит нам безопасно общаться на больших расстояниях, но сначала мне надо связать его с собой.$B$BНачнем, когда ты будешь $gготов:готова;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30834, 'ruRU', 'Отец и сын: снова вместе', 'Вернитесь к торговцам Ши и У-Пэну на юго-восточном берегу озера Чернильной Жабры на вершине Кунь-Лай.', 'Они выжили? Мой отец жив!\n\nЯ думал, мы все умрем в этом ужасном болоте от руки этих безумных цзинь-юй.\n\nЯ сам найду дорогу назад, встретимся в лагере.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30854, 'ruRU', 'Слежка для Лха-По', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30855, 'ruRU', 'Падение Шай Ху', 'Победите Шай Ху. Вы найдете его в Святилище говорящих с водой на острове в центре озера Чернильной Жабры на вершине Кунь-Лай.', 'Я слышу голос болота, ибо оно было очищено.\n\nНо эту страницу в истории моего народа не перелистнуть, пока жив Шай Ху.\n\nОн перебрался на остров в центре болота, оскверняя святые места.\n\nОстерегайся его, ведь он силен. Но после того, что мы уже совершили, я уверен: мы сильнее.', '', 'Губитель цзинь-юй Чернильной Жабры. Чтобы спасти их, нужно убить его.', 'Шай Ху', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30884, 'ruRU', 'За заставой', 'Встретьтесь с Таоши в Логове Сыроземья.', 'Пока меня не было в Кунь-Лай, эта застава слишком надолго осталась без присмотра и без достаточного количества припасов. Нам нужно снова все здесь наладить, прежде чем мы пойдем по следу Ша Ненависти.$B$BТаоши – моя правая рука. Я послал ее на север расследовать слухи о богомолах, которые каким-то образом прорвались сквозь линию наших войск. Мне нужен кто-то, кому я могу доверять и кто поехал бы туда и поработал с ней на пару, заделывая все бреши в нашей обороне.$B$BЕсли то, что мне докладывали о тебе, правда, ты в самый раз подойдешь для этого дела, не так ли, |3-6($c)?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30886, 'ruRU', 'Example Pandaren Race Quest', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30887, 'ruRU', 'Непрошеные гости', 'Убить 12 крик\'тиков-лазутчиков вместе с Таоши.', 'Там внизу, под стеной, передовой отряд богомолов. Задача Заставы Гао-Жаня – не пропускать их в восточные Танлунские степи. Если позволить им пройти на север за укрепления, мы потеряем эти земли.$B$BДавай избавимся от них. Я тебе помогу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30888, 'ruRU', 'Брешь в обороне', 'Используйте сигнальные ракеты Шадо-Пан, чтобы уничтожить 10 крик\'тиков-помечателей.', 'Обычно хватает нескольких разведчиков, чтобы удерживать этот проход. Большая часть территории видна со стены, так что лучники могут осыпать стрелами любые отряды богомолов, которые попытаются пробиться здесь. Проблема в том, что сейчас большая часть лучников занята в схватке у ворот.$B$BВозьми эту сигнальную ракету – она позволит определить, где находятся богомолы, которые пытаются пробраться через восточный проход мимо нашего поредевшего дозора. Убей всех, кого найдешь. Нельзя позволить им открыть путь для полчищ богомолов, которые двинутся дальше в степи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30889, 'ruRU', 'Установка ловушек', 'Заново зарядите 8 шипастых ловушек Шадо-Пан.', 'Приятно тебя видеть, |3-6($c). У нас установлены ловушки по всему проходу, чтобы ловить рыскающих повсюду богомолов, но их последнее время было так много, что почти все ловушки уже сработали.$B$BТаоши говорит, что ты сможешь помочь снова установить некоторые из них, пока ты здесь. Это правда?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30890, 'ruRU', 'Бесконечный дозор', 'Доставьте приказ о возвращении разведчику Вэй-Чиню, разведчице Лун, разведчице Ин и разведчику Цзай-Ганю.', 'Мне доложили, что наши бойцы на Пути Неверного Шага уже дольше двух дней в дозоре. Неудивительно, что богомолы проскальзывают мимо них незамеченными: двое суток на ногах подкосят любого дозорного.$B$BОтправляйся к солдатам и передай, пусть немедленно возвращаются на заставу, чтобы отдохнуть и пополнить припасы. Я найду кого-нибудь им на замену.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30891, 'ruRU', 'Лечение войска', 'Соберите 10 цветков лилового лимона.', 'О, $gновенький:новенькая;! Приятно познакомиться. Я – Септи. Поддерживаю здоровье бойцов Шадо-Пан.$B$BУ богомолов есть яд, который проникает под кожу и попадает в кровь. Он приводит к медленной мучительной смерти, если не применить противоядие.$B$BМне нужна пыльца цветков лилового лимона. Ближайшее место, где их можно найти, – это у Логова Сыроземья к северу от заставы. Если окажешься в тех краях, сможешь мне принести этих цветков?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30892, 'ruRU', 'Снова на ногах', 'Исцелите 8 раненых черных стражей Гао-Жаня.', '$n, мне снова пригодилась бы твоя помощь. Наши воины на южной стороне сражаются из последних сил, и многие из них отравлены ядом богомолов.$B$BНам нужны еще помощники, чтобы было кому позаботиться о раненых. У меня готовы несколько перевязок с принесенными тобой травами, а если ты умеешь исцелять, эффект будет еще сильнее.$B$BПожалуйста, $n, поставь наших воинов на ноги, чтобы они могли вернуться сюда, в более безопасное место.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30893, 'ruRU', 'Нескончаемый рой', 'Убейте 12 крик\'тиков у Заставы Гао-Жаня.', 'Солдатам Гао-Жаня нужна помощь на южном фронте. Если хочешь сражаться вместе с шадо-панами, именно там твое место.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30894, 'ruRU', 'Копание в останках', 'Соберите 20 конечностей крик\'тиков.', 'У меня есть еще одно дело для тебя, $n, хоть оно и не очень-то веселое. Мне очень нужно узнать все о яде богомолов, но для этого необходимо больше конкретной информации и фактов.$B$BПока будешь на поле битвы к югу отсюда, собери, пожалуйста, несколько конечностей богомолов, чтобы у меня была возможность исследовать их неповрежденные железы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30895, 'ruRU', 'Импровизированные боеприпасы', 'Раздобыть 16 непрочных сфер ужаса из Янтарной топи.', 'У меня для тебя есть еще работа.$B$BУ пушек, на которые мы полагаемся в отражении самого сильного натиска богомолов, заканчиваются снаряды. Лагерные канониры изобрели взрывчатое вещество, которое можно делать из семян сферы, растущей на западном кряже.$B$BОни отправили пару новобранцев за ними несколько часов назад, и с тех пор мы о них не слышали. Я хочу послать туда кого-нибудь более толкового, чтобы это задание все-таки было выполнено.$B$BТы как, справишься?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30896, 'ruRU', 'Воры и возмутители спокойствия', 'Убейте 10 встревоженных крапивников.', 'Никак не получается поймать этих маленьких мерзавцев.$B$BУбей любого, кто тебе попадется. И внимательно следи за ценными вещами – они тащат все, что плохо лежит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30897, 'ruRU', 'Не в те руки', 'Раздобудьте меч новобранца Чао.', 'Послушай, э-э... так неловко получилось. Я буквально на секунду положил меч, чтобы собрать сферы, и тут откуда ни возьмись большой дух – схватил его и сбежал через западный проход.$B$BЯ не могу вернуться в лагерь без меча. Тех, кто теряет оружие, тут же вышвыривают из шадо-панов. Оружие – это святое.$B$BПрошу тебя – можешь найти этого большого духа и вернуть мне меч? Я был бы очень благодарен тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30898, 'ruRU', 'Рой врагов', 'Убейте 50 нападающих богомолов с помощью орудия \"дракон\".', 'С тех пор, как ты $gушел:ушла;, богомолов в округе стало намного больше. Давай-ка используем собранные тобой сферы.$B$BОтправляйся на заставу и бери управление одной из пушек на себя. Не пропусти ни единого врага.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30899, 'ruRU', 'В умелых руках', 'Доставьте колчан арбалетных болтов Шадо-Пан повелителю ястребов Нужуну.', '$n, возьми эти арбалетные болты и отнеси их повелителю ястребов Нужуну на Наблюдательный пункт к юго-западу отсюда.$B$BУкао чтут Нужуна, ведь он никогда не промахивается. В том, что мы до сих пор держим оборону, есть и его заслуга. Пообщайтесь, может, сработаетесь. Вдруг, это именно тот шадо-пан, которого нам не хватало.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30900, 'ruRU', 'Кошмар Жутких пустошей', 'Уничтожьте Норвакесс, Кошмар Жутких пустошей.', 'Какая громадина!$B$BШадо-паны на заставе к такому не готовы... Пойдем и разберемся сами.', '', '', 'Норвакесс', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30901, 'ruRU', 'Вдоль южного фронта', 'Отправляйтесь с Тажанем Чжу и Таоши в Ложбину Тусклого Света.', 'Я направляюсь на запад с Таоши, чтобы собрать самых сильных бойцов для сражения с Ша Ненависти.$B$BМне бы хотелось, чтобы ты к нам $gприсоединился:присоединилась;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30907, 'ruRU', 'Четвертый раунд: П.У.Г.', 'Победите Дамагисса, Хилисса и Танкисса.', 'Надвигается последний раунд. Я выбрал для тебя сразу трех соперников. Ты можешь счесть это нечестным... если сил у тебя маловато. А ведь это не так, верно?$b$bОтправляйся в главный храм, выходи на главную арену и сразись с тремя противниками. Докажи, что ты сильнее их всех вместе взятых.$b$bУдачи тебе, боец.', '', 'У каждого есть сила, которую они используют в бою.', 'Дамагисс, Хилисс и Танкисс', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30921, 'ruRU', 'Мотивы богомолов', 'Убейте богомолов в Кри\'весс, чтобы Тай Хо мог изучить их тела.', 'Нам нужна твоя помощь, |3-6($c).$B$BНеобходимо выяснить, почему богомолы так свирепо сражаются. У нас есть некоторые подозрения, но их нужно проверить. И богомолы не должны понять, что мы изучаем их.$B$BВот твое задание.$B$BУбей богомола в Кри\'весс, это к северу отсюда. Я буду красться за тобой и рассмотрю тело как следует.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30922, 'ruRU', 'Природный антисептик', 'Соберите 5 наполненных мочевых пузырей мушана.', 'Члены ордена Шадо-Пан – очень опытные и закаленые многолетними тренировками воины, мы не можем себе позволить терять их из-за царапины отравленным оружием или занесенной в рану инфекции. Вот поэтому мне нужно, чтобы ты $gраздобыл:раздобыла;... кое-что.$b$bВ общем, не буду ходить кругами: моча мушанов – это прекрасный естественный антисептик. И нам очень повезло, что они производят эту жидкость в таких количествах. Нам ее понадобится немало.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30923, 'ruRU', 'Сдержать богомолов', 'Взорвите оружейный склад и склад боеприпасов кри\'тиков в Кри\'весс с помощью бочек с порохом.', 'С каждым днем богомолы производят все больше оружия. Мы не можем остановить это... но помешать можем.$b$b<Тай Хо дает вам взрывчатку.>$b$bМне нельзя привлекать к себе внимание. Хочешь отличиться?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30924, 'ruRU', 'Мудрость Нюцзао', 'Поговорите с Юным Ого в храме Нюцзао, что в Танлунских степях.', 'Черный Бык Нюцзао обитает в храме к западу отсюда. Быть может, он знает, отчего богомолы решили напасть.$b$bЕму ведомо многое.$b$bМы встретимся в храме Нюцзао, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30925, 'ruRU', 'Задание Нюцзао', 'Убивайте богомолов из числа вторгшихся шра\'тиков, чтобы Тай Хо мог обыскать их тела и найти части статуэтки Нюцзао.', 'Нюцзао очень ценит одну статуэтку, свое изображение, созданное одним из его давно павших стражей. Недавно эта вещь была похищена богомолами шра\'тик, она теперь в их лагере на севере.$b$bВерни статуэтку. Тогда ты и твои соратники шадо-паны получите ответ, которого так ждете.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30926, 'ruRU', 'Страшная правда', 'Изучите катакомбы Нюцзао и убейте мрачную тень, что обитает там.', 'Жаль, что приходится подтверждать твои подозрения. Богомолы действительно находятся под властью Ша Страха.$b$bКогда-то мы поклялись удержать это создание в земных недрах под нашим храмом. Но наша бдительность ослабла, и Ша исчез. Теперь он ведет богомолов.$b$bМожешь убедиться в этом. Богомолы прорываются к западной части нашего острова.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30927, 'ruRU', 'Даруй им покой', 'Принесите покой 10 насмерть перепуганным стражам: закройте им глаза и переверните их на живот.', 'Я подслушивал. Что ж, наш секрет раскрыт.$b$bУзнав, что богомолы роют ход под наш храм, я поступил необдуманно. Я отправил несколько десятков стражей защищать нашу землю, не дав им как следует подготовиться. Они поддались страху и не смогли выбраться наружу.$b$bУмирая, пандарен должен обнимать теплую землю, как будто бы погружаясь в сон. Плохо лежать на спине с раскрытыми от ужаса глазами. Прошу тебя, $n, принеси им заслуженный покой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30928, 'ruRU', 'Путь страха', 'Убейте 12 кошмарней в катакомбах Нюцзао.', 'Теперь ты знаешь тайну Нюцзао. Мы не только служители храма... Мы должны сторожить Ша Страха в земных недрах под храмом.$b$bШа удалось скрыться... но тени его остались. Если ты действительно собираешься в катакомбы, уничтожь эти тени, иначе они выйдут наружу, и у нас будет еще больше проблем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30929, 'ruRU', 'Плохой як', 'Помогите Синескоку заменить дефективного яка.', 'Это здесь меняют дефективных яков?$b$bЭй, кто-нибудь, чего делать-то?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30930, 'ruRU', 'Выбор яка', 'Воспользуйтесь лассо, чтобы отловить диких танлунских яков. Затем испытайте их в бою, чтобы проверить, подходят ли они Синескоку.', 'Я тут не вижу хороших яков. Все плохие, и все тут.$b$bОдни воняют, другие дерутся, третьи – пугливые какие-то.$b$bТы вот с виду $gвезучий:везучая:r; |3-6($r), возьми-ка лассо, может, ты мне хорошего яка подыщешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30931, 'ruRU', 'Арбалет отца', 'Добудьте арбалет Ку-Яо.', 'Я пришел сюда, чтобы навестить отца в храме. Как только я здесь очутился, то увидел самое ужасное из всего, что мне доводилось видеть.$b$bЭто был богомол, он шел мимо меня с арбалетом отца.$b$BС отцом что-то случилось! Нам нужно выяснить, что именно... но сначала надо вернуть его арбалет. Я видел, что богомол двигался на запад, за храм.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30932, 'ruRU', 'Стезя отца', 'Найдите отцовскую походную постель, отцовский щит, Ха-Шу и часового Яло.', 'Да, отец мальчика, часовой Ку-Яо, пропал. Он может быть где угодно, у нас много врагов.$b$bТы посматривай по сторонам, вдруг что узнаешь. Можешь поискать его яка, или спросить у часового Яло, может, он что знает.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30933, 'ruRU', 'В поисках отца', 'Поищите часового Ку-Яо.', 'Я искал повсюду... но отца не нашел. Я знаю, что он жив. Но ему нужен лук... вот и все.$b$bЯ слышал, что вы, Шадо-Паны, иногда сражаетесь с богомолами на острове Шра\'весс. Я не знаю, как попасть туда. Если ты будешь там, поищешь моего отца?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30935, 'ruRU', 'История рыбака', 'Поговорите с Миши, чтобы отправиться на Путь Завоевателей. На вершине Шепота Облака найдите Шиня Шепот Облака.', 'Жители Цзоучин знают побережье лучше, чем кто-либо еще во всем Кунь-Лай. Если зандалары скрываются на одном из этих островов, они это выяснят.$B$BМиши доведет тебя до Пути Завоевателей. Я пойду вперед, может, удастся поговорить со старейшинами.$B$BСледуй по дороге до вершины Шепота Облака. Шинь Шепот Облака встретит тебя и проводит в деревню.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30936, 'ruRU', 'UNUSED', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (30942, 'ruRU', 'Сделай меня воином', 'Убейте 4 аманийских застрельщиков, 4 мастеров проклятий из племени Гурубаши и 3 драккарских ледоплетов в провинции Цзоучин.', 'Ш-ш-ш! Не говори так громко, отец услышит!$b$b<Шоми указывает на Дошу Сгибающего Сталь.>$b$bМой отец спятил! Он думает, что я буду учиться и чаи гонять, пока на нашу деревню нападают. Глупость какая! Я не трусливей, чем мужчины. Вот только сражаться не умею... пока.$b$bК этому-то я и веду. Возьми меня с собой! Я быстро учусь и не буду путаться под ногами, обещаю!$b$bПожа-а-а-алуйста!$b$bЕсли потеряем друг друга, встретимся здесь снова.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30943, 'ruRU', 'Осторожность и еще раз осторожность', 'Принесите старейшине Шу 50 взрывоцветов.', 'Судя по количеству воинов, которые пришли сюда, победа будет нелегкой. Но я знаю одну вещь, благодаря которой мы можем получить преимущество.$b$bРядом с деревней растет одно растение, которое можно использовать для создания мощной взрывчатой жидкости. Если ты сможешь набрать достаточно, я начну ее варить.$b$bРастение, которое тебе нужно, называется взрывоцвет. Обращайся с ним осторожнее, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30944, 'ruRU', 'Целая деревня', 'Освободите изможенных защитников от несения стражи.', 'Жители нашей деревни еще с первого нападения охраняют Цзоучин. Они измождены, а многие из них ранены.$b$bЕсли снова нападут зандалары, то меньше всего нам хотелось бы, чтобы наши защитники заснули посреди битвы. Попроси их оставить свои посты, чтобы у них была возможность подлечиться и навестить семьи.$b$bТы найдешь их на постах вокруг деревни.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30945, 'ruRU', 'Это моя добыча', 'Украдите 6 клинков у зандаларских захватчиков.', 'Старейшины хотят, чтобы мы усилили защиту? Мы не монахи, |3-6($c), нам нужно оружие, чтобы сражаться!$B$BСобери с тел этих варваров оружие для меня. Я переплавлю его во что-нибудь более подходящее для жителей нашей деревни, чтобы они могли воевать.$b$bПринеси столько, сколько сможешь, а я позабочусь об остальном.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30946, 'ruRU', 'Откровения', 'Поговорите с зандаларским пленником.', 'Старейшины считают, что останки находятся рядом с островом на северо-востоке. Селяне говорят, что около руин видели пророка Хар\'зула.$b$bНайди Хар\'зула, тогда, может, найдешь и останки Властелина Грома. Не упусти этот шанс, $n. Отправляйся в Покой Кан-Ши и сделай все, что возможно, чтобы остановить пророка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30952, 'ruRU', 'Бесконечная осада', 'Уничтожьте 12 нападающих шра\'тиков в храме Нюцзао.', 'Богомолы постоянно нападают на нас. Они то прибывают, то отступают, но они не уходят насовсем.$b$bНичего, яки – воплощение стойкости. Мы не сдадимся и готовы вечно защищать свой дом.$b$bТы за нас?', '', '', '', '', '', 'Вернитесь к старейшине Ого в храм Нюцзао, что в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30953, 'ruRU', 'Павшие стражи', 'Исцелите 8 раненых стражей Нюцзао до уровня 50% здоровья. Вы можете воспользоваться флягами с молоком яка или применить свои исцеляющие заклинания.', 'Наши стражи могут сражаться дни и ночи напролет, но даже их выносливость не беспредельна. Многие уже полностью истощили свои силы в бою с богомолами.$b$bПрошу тебя, помоги им, придумай хоть что-нибудь. Если не сможешь излечить их $gсам:сама;, то дай им вот это. Глоток питательного молока яка придаст им сил.', '', '', '', '', '', 'Вернитесь к сторожу яков Киане в храм Нюцзао в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30954, 'ruRU', 'Клинок – всегда клинок', 'Достаньте 10 клинков шра\'тиков.', 'Нет времени соблюдать все обычаи. Руки наших каменщиков дрожат и кровоточат. Наши кузнецы не успевают ковать оружие, так быстро оно уходит.$b$bНадо проявить смекалку.$b$bУ многих богомолов есть оружие, и на поле боя лежит вооружение убитых врагов. Глупо не воспользоваться этим.', '', '', '', '', '', 'Вернитесь к Юному Ого в храм Нюцзао, что в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30955, 'ruRU', 'Подношение', 'Возьмите 6 порций еды Нюцзао. Понесет ее силач Нюцзао.', 'Наш покровитель Нюцзао долго раскачивается, но потом его не остановишь. Я хочу сказать, что если он сдвинется с места, богомолам придется приложить все силы, чтобы остановить его.$B$BПопробуем заинтересовать Нюцзао едой, это проще всего. К счастью, пищи в храме хватает... несмотря на военное время.$B$BМой силач пойдет с тобой, чтобы нести эту ношу.', '', '', '', '', '', 'Вернитесь к старшему ученику Паоша в храм Нюцзао в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30956, 'ruRU', 'Осада продолжается', 'Убейте 25 нападающих на храм Нюцзао шра\'тиков.', 'Нет ничего хуже этой стаи богомолов. Хорошо еще, что с нами Нюцзао.$B$BПомоги ему, |3-6($c). Возвращайся во двор и помоги защитить храм.', '', '', '', '', '', 'Вернитесь к старейшине Ого в храм Нюцзао, что в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30957, 'ruRU', 'Нашествие', 'Победите 4 шра\'тиков-куньчунов.', 'Я командир стражей Нюцзао. Наши воины вполне справляются с богомолами.$B$BА вот с куньчунами сложнее.$B$BОни огромные и свирепые, серьезнейшая угроза для моих стражей. Только Нюцзао может выстоять против такого врага... И, возможно, ты.', '', '', '', '', '', 'Вернитесь к командиру стражи Ципану в храм Нюцзао, что в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30958, 'ruRU', 'Под прикрытием Нюцзао', 'Бросьте 10 выпавших из стены камней каменщикам Нюцзао.', 'Появление Нюцзао на поле боя – это великое благо... во многих смыслах.$b$bНапример, пока он отвлекает армию противника, у каменщиков есть время укрепить стены. Им нужна твоя помощь.$b$bЕсли увидишь выпавшие из стены камни, кидай им. И поторопись! Нюцзао не сможет сражаться вечно.', '', '', '', '', '', 'Вернитесь к сторожу яков Киане в храм Нюцзао в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30959, 'ruRU', 'Мощное оружие', 'Уничтожьте 3 боевых повозки шра\'тиков.', 'Богомолы в своих жутких боевых повозках сейчас окружают Храм. Чем раньше мы от этих повозок избавимся, тем лучше. Можно их уничтожить с помощью нашего оружия и заклинаний, но вот это сработает гораздо быстрее.$b$b<Ого дает тебе несколько маленьких бочек с наспех уложенной взрывчаткой. >$b$BОпасайся нападения богомолов, которые останутся в фургоне, когда он взорвется. Вообще-то тебе стоит держаться от них как можно дальше.', '', '', '', '', '', 'Вернитесь к Юному Ого в храм Нюцзао, что в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (30960, 'ruRU', 'Возвращение из прохода', 'Доложите о возвращении Тажаню Чжу на Заставе Гао-Жаня.', 'У меня все еще есть дела в проходе – некоторые богомолы так по нему и пробираются. Однако твоя помощь неоценима в любом деле, так что вряд ли Тажань одобрит, если я попрошу тебя выполнить столь обыденную работу.$B$BТажань все еще должен быть в главном лагере Гао-Жаня. Возвращайся с докладом, а я позже к тебе присоединюсь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30963, 'ruRU', 'Полевой бронник', 'Соберите 120 фрагментов панциря гнилозуба.', 'Шадо-паны сражаются. Во время боя на броне появляются царапины, порезы и прожженные дырки. А чинить все это мне.$b$bЯ не бронник, но залатать кольчугу могу, если дыра не слишком велика.$b$bЯ использую фрагменты панциря черепах, что живут в дикой местности на северо-востоке. Пополни мои запасы, и я смогу починить больше брони для шадо-панов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30964, 'ruRU', 'Нужная припарка', 'Соберите 11 ив Мао.', 'Сухая повязка бесполезна, только что мухи в рану не лезут. Иногда, впрочем, большего и не жди.$b$bТолько не у меня.$b$bЯ прокладываю между бинтами пасту из найденных целебных трав. И лучше всего для этих целей подходят ивы Мао, что растут в северо-восточных полях. Если тебе попадутся эти ивы, собери их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30967, 'ruRU', 'Освобождение узников', 'Спасите 6 раскольников Чернильной Жабры на озере Чернильной Жабры.', 'Не все мои сородичи из Чернильной Жабры поддались искушению. Многие последовали моему совету и не стали пить воды, оскверненной ша..$b$bОни прячутся в деревне, боятся до смерти, а может, их стражники напугали.\n\nСообщи им, что еще не все потеряно! Отправляйся в деревню к северу отсюда. Передай им, чтобы шли ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30968, 'ruRU', 'Ша Ненависти', 'Победите Ша Ненависти.', 'Мы близки к заветной цели. Среди нас сильнейшие из шадо-панов, и с твоей помощью мы одержим победу над Ша Ненависти и положим конец его влиянию на наш мир.$B$BПосле того, как мы войдем в тоннель, держитесь близко и следуйте моим приказам. Победить Ша почти невозможно, но у меня есть план, который гарантирует нам победу.$B$BЗнакомство с тобой, $n – большая честь для меня.', '', '', 'Ша Ненависти', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30969, 'ruRU', 'Новый противник', 'Добудьте 5 оскверненных знаков различия у любых последователей в Огненной Пропасти.', '$n, темные шаманы обладают большой силой, и это привлекло к ним многих союзников – тех, кто раньше был частью Орды, но теперь преследует свои зловещие цели.$b$bНам нужно разобраться с ними и тем самым преподать урок всем остальным, чтобы не повторилась ситуация с Сумеречным Молотом.$b$bУбей как можно больше последователей шаманов и принеси мне их знаки различия.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30970, 'ruRU', 'Ослепленные ненавистью', 'Убейте 9 ослепленных ненавистью шкуродеров.', 'Эти скорпионы находятся под воздействием ша. Из-за этого они повылезали из своих нор и направились в наш лагерь, ослепленные ненавистью к тем, кто вторгся в их земли.$B$BНам нужно избавиться от этих скорпионов и укрепить защиту лагеря. Убей всех, кого найдешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30971, 'ruRU', 'Пополнение запаса', 'Соберите 120 огненных стрел Шадо-Пан.', 'Меня послали обратно в лагерь собрать промасленные стрелы для лучников на мосту, и вот что в итоге получилось... Меня обучали, как и большинство этих пандаренов, а к этому не готовили.$B$BИ все-таки лучникам на мосту нужна наша помощь. Если ты поможешь собрать стрелы из этих обломков, может, мы хоть что-то сможем использовать от того, что здесь осталось...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30972, 'ruRU', 'Присоединиться к сражению', 'Принесите колчан с огненными стрелами Шадо-Пан Лао-Чиню Стальному Брюху на Мост Тусклого Света.', 'Лучникам Лао-Чиня пригодятся эти стрелы на мосту. Сможешь их принести?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30973, 'ruRU', 'Охваченные пламенем', 'Убейте 10 древесных корт\'тик с помощью бочонков Лао-Чиня.', 'У богомолов, пересекающих мост, прочные панцири, которые отражают большинство атак. Но есть у них и слабость – огонь.$B$BБойцы Лао-Чиня принесли для этого на поле боя бочонки. Кидай бочонки в богомолов, а лучники Лао-Чиня их подожгут.$B$BТогда их уже будет легко добить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30975, 'ruRU', 'Захват Моста Тусклого Света', 'Помогите Лао-Чиню Стальному Брюху удержать дальнюю часть Моста Тусклого Света.', 'Давай оттесним этих насекомых за мост и сломим их боевой дух!$B$BСледуй за мной.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30976, 'ruRU', 'Присоединиться к охоте', 'Отправляйтесь с Тажанем Чжу, Таоши и Лао-Чинем к дозорному пункту Жэнь-сая.', 'Нас на одного больше. Твоя помощь бесценна.$B$BДавайте двинемся на запад к караульному посту Жэнь-сая, чтобы найти последнего участника нашей вечеринки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30977, 'ruRU', 'Привет приземлившимся!', 'Убейте 12 приземлившихся легкокрылых кор\'тиков.', 'Все мои солдаты сейчас на юго-западе у Наблюдательного пункта, сдерживают богомолов, которые пытаются перелететь через провал. Пока у лучников есть стрелы, ни один богомол не сможет улететь далеко.$B$BЕсли хочешь помочь, добивай богомолов на земле. Возьмешься, |3-6($c)?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30978, 'ruRU', 'Враждебные небеса', 'Подстрелите 50 кор\'тиков-роевиков и воресс\'талика.', 'Сейчас нам будет не сладко... $B$BИди-ка к той пушке и начинай палить. Целей будет предостаточно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30979, 'ruRU', 'Истребление жуков', 'Объединившись с повелителем ястребов Нужуном, убейте Воресс\'талика.', 'Нам нужно спуститься и добить этого огромного жучару. Смелей.', '', '', 'Воресс\'талик', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30980, 'ruRU', 'Герои Шадо-Пан', 'Вернитесь с повелителем ястребов Нужуном к Тажаню Чжу на дозорный пункт Жэнь-сая.', 'Говоришь, Тажань Чжу сейчас в Танлуне, и он спрашивает обо мне? Должно быть, что-то важное...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30981, 'ruRU', 'Таоши и Корвекксис', 'Убейте Корвекксиса, объединив усилия с Таоши.', 'Таоши устраивает западню для одного из лидеров богомолов на юге Сик\'весс. Ей поручено достать кристалл, чтобы мы могли с его помощью открыть дверь.$B$BДвое сильнее одного. Я хочу, чтобы ты $gприсутствовал:присутствовала; там, чтобы удостовериться, что все пройдет гладко.', '', '', 'Корвекксис', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30982, 'ruRU', 'Ветеринарный контроль', 'Уничтожьте Адарогга и Брюхошлака.', 'Там, в пропасти, полно лавовых паразитов и гончих, и у них столько мяса троггов, что они могут продержаться там целую вечность.$b$bС этими паразитами нужно покончить как можно скорее, пока они не причинили ущерб городу. А ты, $n, кажется, можешь постоять за себя.$b$bПроложи себе путь и уничтожь самых опасных бестий – Адхиллеса и Магнаута.', '', '', '', '', '', 'Вернитесь к командиру Баграну в Огненной Пропасти.', 19865);
INSERT INTO `quest_template_locale` VALUES (30983, 'ruRU', 'Темный шаман', 'Победите темного шамана Корантала и стража лавы Гордота.', 'Эти темные шаманы уже несколько месяцев проводят здесь жуткие ритуалы и призывают чудовищ.$b$bНе знаю, чего они хотят этим добиться, но одно предельно ясно: шаманы – враги Орды. И для борьбы с ними мне нужна твоя помощь.$b$bПроложи себе путь в ущелье и убей темного шамана Корантала и стража лавы Гордота.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30984, 'ruRU', 'Орки своих не бросают', 'Спасите 5 кор\'кронских разведчиков в Огненной Пропасти.', '$n, я думал, это будет обычный рейд – уничтожим пару троггов, осмотрим окрестности, а к полудню уже будем сидеть в таверне.$b$bВместо этого у меня пропал целый отряд разведчиков, а Ксор теперь пугает всех новым Сумеречным Молотом.$b$b<Командир Багран плюет с досады.>$b$bПриведи сюда моих разведчиков – тогда мы поймем наконец, что здесь происходит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30986, 'ruRU', 'Древняя крипта могу', 'Убейте одержимого лидера шадо-панов и очистите источник жизни.', 'Наш отряд разведчиков уничтожен! На помощь!', '', '', 'Новобранец Чуббс', 'Отличная работа!', 'Новобранец Чуббс', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30987, 'ruRU', 'Вступление в Альянс', 'Поговорите с королем Андуином Ринном в крепости Штормграда.', '$n, мы должны помнить о долге.$b$bНаша задача – распространять учение Тушуй за пределами Скитающегося острова... и начать лучше всего здесь, в Штормграде – сердце Альянса.$b$bНам понадобятся союзники, так что давай сначала узнаем, кто их предводитель.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30988, 'ruRU', 'Традиции Альянса', 'Проследуйте за королем Варианом Ринном.', 'Недавно мне сообщили, что сюда может прибыть кто-то из твоего народа. Если ты хочешь помочь нашему делу, то я с радостью назову тебя своим союзником.$b$bСледуй за мной, $n.', '', '', '', '', '', 'Поговорите с королем Варианом Ринном в крепости Штормграда.', 19865);
INSERT INTO `quest_template_locale` VALUES (30989, 'ruRU', 'Старый боец', 'Проведите тренировочный поединок с королем Варианом Ринном.', 'Я хочу знать, умеешь ли ты сражаться. Возможно, когда-нибудь тебе придется пойти в бой, и мне нужно знать, сможешь ли ты встать на защиту моего королевства.$b$bЯ наслышан о воинах-пандаренах, но видеть их в деле мне не приходилось.$b$bМожет, сразимся?', '', '', '', '', '', 'Вернитесь к королю Вариану Ринну в крепость Штормграда.', 19865);
INSERT INTO `quest_template_locale` VALUES (30991, 'ruRU', 'Катушки-покатушки', 'Возьмите бочку у Лао-Чиня, скатите ее с холма на яунголов и подожгите, когда они будут близко, чтобы уничтожить 4 древомета осулов и 50 осулов-завоевателей.', 'Вот уж не думал я, когда учился на хмелевара, что мои знания придется использовать столь нестандартным образом.\n\nТы знаешь, что пиво можно поджечь, и оно будет гореть? А если смешать его с яунгольской нефтью, так и вовсе взрывчатка выйдет.\n\nВ эти бочки я добавил горючую смесь, что ты $gпринес:принесла;. Подкати их к яунголам, а потом подожги.\n\nБочка взорвется через несколько секунд, и мало никому не покажется...\n\nХм, не хотел бы я там оказаться.\n\nТак что я останусь здесь и буду грустить об этом пиве.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30992, 'ruRU', 'Завершить начатое!', 'Закончите битву у Врат Быка.', 'У нас новости от Суны, со стены. Что-то вот-вот случится...\n\nПохоже, они готовят завершающий удар. Пора показать им, кто тут чего стоит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30993, 'ruRU', 'Где же подкрепление?', 'Поговорите с Банем Медвежьим Сердцем около монастыря Шадо-Пан на вершине Кунь-Лай.', 'Так больше продолжаться не может. Откладывать нельзя.\n\nУчитывая, что творится здесь и в Огненной Ветви, нужно отправляться в монастырь.\n\nВсе другие дела могут подождать! Мой воздушный шар может подняться к самым вершинам гор, прямо туда. Он привязан у лагеря к северо-востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30994, 'ruRU', 'Трюк Лао-Чиня', 'Поговорите с Лао-Чинем Стальным Брюхом в лагере Зимнего Цветения на вершине Кунь-Лай.', 'Так. С твоей помощью мы снова захватили всю стену. Хорошо.\n\nЯ пока останусь наверху, вдруг еще какой яунгол решится сюда залезть.\n\nА вот тебе стоит вернуться, посмотреть, как там дела у Лао-Чиня. Не хочется это признавать, но может, не такая уж плохая у него идея...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30995, 'ruRU', 'Своих не бросаем', 'Спасите 5 следопытов ШРУ в Огненной Пропасти.', 'Час назад я отправил отряд на разведку, но он до сих пор не вернулся – более того, из пропасти полезли эти проклятые гончие.$b$bНе знаю, что там происходит, но пока разведчики не вернутся, я с места не двинусь.$b$b$n, иди туда и найди их – лучше, конечно, живыми.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30996, 'ruRU', 'Темный шаман', 'Победите темного шамана Корантала и стража лавы Гордота.', 'Эти темные шаманы уже несколько месяцев проводят здесь жуткие ритуалы и призывают чудовищ.$b$bНе знаю, чего они хотят этим добиться, но одно предельно ясно: шаманы – враги Альянса. И для борьбы с ними мне нужна твоя помощь.$b$bПроложи себе путь в ущелье и убей темного шамана Корантала и стража лавы Гордота.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30997, 'ruRU', 'Ветеринарный контроль', 'Уничтожьте Адарогга и Брюхошлака.', '$n, это хорошо, что ты здесь. Орда собирает армию, и нам нужно немедленно переходить к решительным действиям.$b$bМы должны нанести удар и уничтожить хотя бы часть тех чудовищ, которых привел сюда враг.$b$bРазберись с Адароггом и Брюхошлаком, пока Орда не бросила их в бой против нас.', '', '', '', '', '', 'Вернитесь к боевому командиру ШРУ Диркену в Огненную Пропасть.', 19865);
INSERT INTO `quest_template_locale` VALUES (30998, 'ruRU', 'Новый противник', 'Добудьте 5 оскверненных знаков различия у последователей темного шамана.', '$n, с помощью черной магии Орда управляет чудовищами и своими одержимыми собратьями.$b$bЯ намереваюсь положить этому конец, но сначала надо выяснить, кто именно нам противостоит. А для этого мне понадобится твоя помощь.$b$bПроложи себе путь по пещерам и собери знаки различия, которые носят последователи шаманов. Тогда я пойму, какая магия здесь задействована.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (30999, 'ruRU', 'Нехоженая тропа', 'Поговорите с дядюшкой Листом Клевера в Пэй-Лэй.', 'Трудный путь вознаграждает самыми ценными знаниями, |3-6($c). Несомненно, я обогащусь великим опытом, пройдя путем Шаохао.$b$bМного лет назад Шаохао отправился на самый высокий пик Кунь-Лай, чтобы получить совет Нефритовой Змеи. Я тоже намерен отправиться в лагерь Искателя, дабы приобщиться к мудрости.$b$bВозможно, тебя заинтересует подобное путешествие? Если да, поговори с дядюшкой Листом Клевера. Он поможет тебе подготовиться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31000, 'ruRU', 'Жуткое место', 'Поговорите с лучницей Ли на Змеином Хребте.', 'Лучники Шадо-Пан неотступно следят за Жуткими пустошами с вершин Змеиного Хребта. Им очень пригодится помощь $gхорошего:хорошей:c; |3-1($c).$B$BВозьми воздушный змей и зайди к лучнице Ли.', '', '', '', '', '', 'Поговорите с лучницей Ли на Змеином Хребте.', 25549);
INSERT INTO `quest_template_locale` VALUES (31001, 'ruRU', 'Падение', 'Спуститесь на Гуртанскую террасу с помощью шадопанской веревки и найдите упавшего шадопанского меткого стрелка.', 'Мало того, что мы стараемся сдержать богомолов, так теперь из руин внизу полезли пауки.$B$BВ одного из моих лучших стрелков выстрелили паутиной и за ногу утащили прямо вниз!$B$BМы считаем, что он жив, но у меня мало людей и некого послать за ним. Мы уже на пределе, |3-6($c).$B$BПозади меня есть веревка, спустись по ней в руины, если хочешь помочь. Ты же не боишься высоты?$B$BА пауков?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31002, 'ruRU', 'Нет', 'Убейте 6 страхопрядов-охранников и используйте драконье ружье шадо-панов, чтобы уничтожить 20 яиц страхопряда на Террасе Гуртан.', 'Мы держимся, но едва-едва. Ты нам очень поможешь, если сделаешь хоть что-нибудь, чтобы сдержать поток поднимающихся по стене страхопрядов.$B$BХочешь раскалывать паучьи яйца руками по одному?$B$BСомневаюсь. Возьми одно из наших драконьих ружей и повеселись там внизу. Хочу услышать, как лопается эта мелюзга.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31003, 'ruRU', 'Безумный богомол', 'Узнайте больше о бое богомолов на Террасе Гуртан.', 'Ты не поверишь, что мне довелось увидеть! Два богомола сражались друг с другом, швыряясь смертоносными заклинаниями.$B$BОдин из них... Такого богомола мне видеть не доводилось. Он был абсолютно другого цвета, и одет иначе, будто какой-то жрец. Второй был настоящий псих, магия лилась из него, словно портер из бочки.$B$BПослушай, мне надо возвращаться на пост, но эти двое все еще сражаются в пещере за моей спиной, и у меня такое чувство, что дело тут серьезное. Может, проверишь?', '', 'Богомол, пользующийся силой ша, как оружием? Как это возможно?', 'Адъюнкт Кри\'зот', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31004, 'ruRU', 'Застывший в янтаре', 'Используйте камертон клакси на куске древнего янтаря на Террасе Гуртан.', 'Возьми... это...$B$B<Умирающий богомол с трудом вытягивает искалеченную руку. В ней лежит металлическая вилка с двумя длинными тонкими зубцами и украшенной самоцветами ручкой.>$B$BПробуди... Рассекающего Ветер...$B$BТолько так можно... остановить рой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31005, 'ruRU', 'Тяжелое пробуждение', 'Принесите 100 кусочков нектарниц Кил\'руку Рассекающему Ветер на террасу Гуртан.', 'Прошу простить, что я в таком виде. Я провел во сне долгие годы.$B$BКлакси\'ва должны были заготовить сок кипари для моего Пробуждения... этим придется заняться тебе.$B$BЯ слышу, с юга доносится жужжание нектарниц. У них вдоволь древесного сока, что мне нужен. Принеси их мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31006, 'ruRU', 'Совет клакси', 'Отправляйтесь к центру Жутких пустошей в Клакси\'весс. Добраться туда можно самостоятельно или при помощи Кил\'рука Рассекающего Ветер. Он находится на Террасе Гуртан.', 'Мне нужно предстать перед клакси. Меня бы не пробудили, если бы нашему народу не угрожала опасность.$B$BА от тебя все же есть польза, так что я тебя пощажу.$B$BВозможно, совет найдет тебе применение.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31007, 'ruRU', 'Нечистые роерожденные', 'Убейте 6 хранителей кладки Шек\'зир во Владениях Шек\'зир.', 'Имперские кладки осквернены! Хранители кладки ускоряют развитие новых роерожденных, питая их этой отвратительной энергией так называемого \"ша\", прежде чем отправить к стене.$B$BКлакси хотят прервать поток роерожденных из этих жутких кладок. Уничтожь хранителей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31008, 'ruRU', 'Янтарное оружие', 'Соберите 6 янтарных клинков воинов клинка Шек\'зир у Сердца Страха и во Владении Шек\'зир.$B$BПоговорите с Кил\'руком Рассекающим Ветер в Клакси\'весс, чтобы отправиться в Сердце Страха.', 'Ты, ничтожество!$B$BТеперь ты работаешь на меня!$B$BУ воинов клинка Шек\'зир лучшее оружие в империи.$B$BПринеси мне столько янтарных клинков, сколько сможешь, если только тебя не проткнут ими по дороге! Я хочу быть уверен, что оружия при необходимости у нас будет достаточно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31009, 'ruRU', 'Мертвая зона', 'Активируйте недействующее звуковое реле в Сердце Страха с помощью резонирующего кристалла клакси.$B$BПоговорите с Кил\'руком Рассекающим Ветер в Клакси\'весс, чтобы отправиться в Сердце Страха.', 'Клакси\'ва шепчет сонару, и он далеко разносит этот шепот, передает другим сонарам, богомолам, Идеалам. Шепот возвращается, и клакси слышат его.$B$BТак им становится ведомо все.$B$BСонар около дворца молчит. Это неправильно. Он должен петь для клакси.$B$BЧинить сонар – моя работа, но ты служишь клакси, а значит – и мне. Так что ты чини сонар, а я тут подожду!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31010, 'ruRU', 'В ее власти', 'Найдите и пробудите Идеал во Владениях Шек\'зир.', 'Клакси внимают песне кристалла. Они ощущают присутствие Идеала в кладке к востоку от звукового реле.$B$BХранители кладок пытаются осквернить его... клакси не могут допустить этого.$B$BОтправляйся туда и найди Идеал. Возложи руки на его убежище, шепот клакси пройдет сквозь тебя и освободит его. Защити его, если сможешь.', '', 'Мы обнаружили Идеал где-то рядом с тобой.', 'Кор\'ик', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31011, 'ruRU', 'Враг у ворот', 'Победите 10 зандаларских берсерков, 5 зандаларских чудищ и 3 кровопийц из племени Гурубаши.', 'Зандалары напали! Помоги нам защитить деревню!$B$BЕсли они одержат верх, нам уже никогда не найти останки Властелина Грома!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31012, 'ruRU', 'Вступление в Орду', 'Поговорите с Гаррошем Адским Криком, который находится в Оргриммаре.', '$n, вот он... Оргриммар, сердце Орды.$b$bМы сумеем принести пользу не только на Скитающемся острове. Здесь множество дел, которые только и ждут, чтобы мы ими занялись. Мастеру Шан Си это бы понравилось.$b$bНачнем здесь и сейчас. Но сначала узнаем, кто возглавляет Орду. Союзники нам понадобятся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31013, 'ruRU', 'Традиции Орды', 'Проследуйте за Гаррошем Адским Криком.', 'Недавно мне сообщили, что сюда может прибыть кто-то из твоего народа. $b$bЭто хорошо. Орде нужны новые силы, и пандарены ей очень пригодятся.$b$bСледуй за мной, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31014, 'ruRU', 'Дар Адского Крика', 'Пройдите испытание Гарроша, победив Оггакса, Гадуна и Ледяную Кровь.', 'Мне нужно знать, умеешь ли ты драться... то есть убивать и при этом оставаться в живых. Рано или поздно каждый из вас отправится на войну, и я должен знать, можно ли на вас рассчитывать.$b$bЕсли помнишь, я упомянул о подарке – он здесь, на Арене Доблести. Открой дверь, которая находится у меня за спиной, и зайди на арену. Я испытаю тебя.', '', '', '', '', '', 'Вернитесь к Гаррошу Адскому Крику в крепость Громмаш в Оргриммаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (31015, 'ruRU', 'Ваша личная коллекция', 'Протереть пустую полку.', 'У Пандарии богатая история и культура. Легенды, сказания, байки... Если во время своих путешествий ты встретишь ценный артефакт или сведения, связанные с нашими изысканиями, сохрани их.$b$bКогда наберется достаточно материалов, мы сплетем их в книгу, которую добавим в твою личную коллекцию.$b$bРазумеется, ты в любой момент сможешь посетить нас и ознакомиться с этими данными.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31016, 'ruRU', 'Хранители истории', 'Поговорите с хранителем истории Чо в Обители Мудрости в Вечноцветущем доле.', '$gДорогой:Дорогая; $n!$b$bМы сделали великое открытие в Вечноцветущем доле. Найдено огромное хранилище, полное книг и свитков, в которых содержатся знания времен империи могу.$b$bПредлагаем посетить нас при первой возможности. Обитель Мудрости находится около печально известных Подземелий Могу\'шан, от входа в подземелья нужно подняться на площадку.$b$bЖдем тебя с нетерпением!$b$bС уважением,$b$bХранитель истории Чо', '', '', '', '', '', 'Вернитесь к хранителю истории Чо в Обитель Мудрости, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (31018, 'ruRU', 'Глубоко под Сердцем Страха', 'Убейте адьюнктов Эквема, Иккесса, Суруза, Цзикци и освободите Ксарила Отравленный Разум.', 'Клакси стало известно о существовании еще одного Идеала, Пробудитель.$B$BОн был скрыт от нас неспроста.$B$BОн находится у императрицы. Адъюнкты собираются его уничтожить.$B$BОни творят свои нечистые заклинания, скрывшись глубоко в подземельях дворца. Необходимо им помешать!$B$BПока мы будем удерживать Клакси\'весс, тебе надо остановить их. Пройди по западному выступу и отыщи вход в их зал.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31019, 'ruRU', 'Янтарь – это жизнь', 'Убейте 7 раздирателей из клана Туманного Клинка и чешуйчатого повелителя из клана Туманного Клинка.', 'Чтобы противостоять империи богомолов, нам нужно достать еще янтаря.$B$BБольшие запасы хранятся под озером к югу отсюда, но вокруг этого озера обитает дикое племя сауроков.$B$BУ меня каждый боец на счету. Придется тебе отправиться к озеру и познакомиться с ними. Убей, сколько сможешь. Обязательно прикончи вождя.$B$BНе так уж и сложно, правда?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31020, 'ruRU', 'Обед для зверя', 'Убейте 8 кроколисков-хладогрызов.', 'Мне нужно немедленно присоединиться к Совету клакси и другим Идеалам, но у меня едва хватает сил держаться на ногах.$B$BМне нужна пища, Пробудитель.$B$BЯ чувствую, как бьются сердца созданий на северном берегу озера.$B$BПринеси мне их мясо, и я насыщусь им.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31021, 'ruRU', 'Живой янтарь', 'Соберите 8 кусков живого янтаря и накормите ими Корвена Первейшего.', 'Жидкий янтарь лучше всего восстанавливает силы Идеала после пробуждения, его принято подносить Идеалу на церемонии пробуждения.$b$bСудя по всему, тебе об этом не сообщили, так что придется импровизировать.$B$BЯ чувствую, что на дне озера есть залежи янтаря. Он подойдет, но мне не хватит сил, чтобы выкопать его самому.$B$BПомоги же мне, и ты не останешься без награды.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31022, 'ruRU', 'Кипари Зар', 'Активируйте сонар, а затем защитите Корвена Первейшего, пока он будет изучать дерево.', 'Что за дерево растет на холме к западу отсюда? Неужели это... Кипари Зар?$B$B<Корвен Первейший погружается в молчание.>$B$BКогда я вернулся из последнего налета, еще до того, как стать Идеалом, мне была оказана честь, и я посадил кипари.$B$BИ вот из моего саженца выросло огромное дерево, но... с ним что-то не так.$B$BУ его корней должен быть старый сонар. Отведи меня к дереву, Пробудитель. Нужно осмотреть его повнимательней.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31023, 'ruRU', 'Реликвии Роя', 'Соберите 8 реликвий богомолов.', 'Эта странная табличка покрыта письменами на языке, возможно, богомольского происхождения.$B$BВы замечаете и другие реликвии, неосторожно разбросанные по стоянкам и в озере.$B$BМожет быть, клакси будет интересно изучить эти артефакты.$B$BКто знает? Возможно, так удастся заслужить их уважение.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31024, 'ruRU', 'Угощение куньчуна', 'Соберите 4 мясистых черепашьих бедрышка.', 'По мере того как Ковок растет, ему будут нужны дисциплина и поощрение в равных долях.$B$BУ меня нет проблем с дисциплиной, но наши запасы мяса почти иссякли.$B$BК югу ты найдешь черепах, которые ползают севернее Озера Звезд и Кипари Зар.$B$BПоохоться на них, Ковоку нравится вкус их плоти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31026, 'ruRU', 'Корень проблемы', 'Убейте матриарха хладогрызов.', 'Кипари Зар умирает.$B$BПорождение тьмы вгрызлось в его корни, пропитывая их скверной.$B$BДерево уже не спасти, но мы можем облегчить его страдания.$B$BСмотри. Злобная тварь оставила ход в свое логово. Достаточно пройти по нему, спуститься с холма и обойти сонар.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31030, 'ruRU', 'В монастырь', 'Встретьтесь с Банем Медвежьим Сердцем внутри монастыря Шадо-Пан.', 'Это... невообразимо. Если в монастыре и правда эпидемия ша, нам нелегко будет очистить монахов от скверны.\n\nСобери друзей, встретимся в монастыре.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31031, 'ruRU', 'В монастырь', 'Встретьтесь с Банем Медвежьим Сердцем внутри монастыря Шадо-Пан.', 'Это... невообразимо. Если в монастыре и правда эпидемия ша, нам нелегко будет очистить монахов от скверны.\n\nСобери друзей, встретимся в монастыре.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31032, 'ruRU', 'Дым в небе', 'Сожгите 10 трупов легкокрылых кор\'тиков.', 'Нужун попросил меня раздать факелы, чтобы сжечь трупы.$b$bЛетающие богомолы хрупки и не выдержат горячего дыма.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31034, 'ruRU', 'Враг из глубин', 'Поговорите с командиром Баграном.', '$c, враги Орды гнездятся даже под самим городом.$B$BПламенеющий клинок уже захватил Огненную Пропасть, а теперь собирается взять штурмом и сам Оргриммар! Нам нужно нанести ответный удар и отбить то, что принадлежит нам по праву!$B$BИди в Огненную Пропасть. У самого входа найдешь командира Баграна. Он скажет, что тебе нужно делать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31035, 'ruRU', 'Враг из глубин', 'Поговорите с каменным стражем Курджаком.', 'Огненная Пропасть в Оргриммаре захвачена Пламенеющим Клинком. $n, нельзя оставить это безнаказанным, иначе вскоре они обратят взор на Громовой Утес.$B$BОтправляйся в пропасть и поговори с каменным стражем Курджаком прямо возле входа. Помоги ему чем можешь, ибо судьбы наши связаны.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31036, 'ruRU', 'Враг из глубин', 'Поговорите с командиром Баграном.', 'Огненную Пропасть Оргриммара захватили темные шаманы. $n, это не должно остаться безнаказанным, иначе в следующий раз они двинутся уже на Громовой Утес.$B$BИди в Пропасть и поговори с командиром Баграном. Наши судьбы тесно связаны, поэтому ты $gдолжен:должна; сделать все, чтобы ему помочь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31037, 'ruRU', 'Враг из глубин', 'Поговорите с командиром Баграном.', 'Оргриммарскую Огненную Пропасть захватил темный шаман. $n, мы не можем допустить, чтобы это осталось безнаказанным. Иначе потом они протянут свои руки к Подгороду.$b$bИди и поговори с командиром Баграном, его можно найти в Пропасти. Помоги ему всем, чем сможешь. Наши судьбы переплетены.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31038, 'ruRU', 'Бойцовский круг: Снежный Цветок', 'Бросьте вызов Снежному Цветку и победите ее в бойцовском круге.', 'Ну что ж, $n, весь лагерь слышал о твоих подвигах.$B$BИ Снежный Цветок не прочь проверить, на что ты годишься в бою.$B$BСоветую подготовиться, |3-6($c). Справиться с ней непросто.$B$BПокажи ей, чего ты стоишь, и ты завоюешь верного друга.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31039, 'ruRU', 'Угроза могу', 'Убейте 12 змееловов Шань\'цзэ или повелителей зверей Шань\'цзэ.', 'Разведчики засекли большой отряд могу к северо-западу отсюда, на острове Шань\'цзэ Дао.$B$BНовости не из лучших, остров считался пустым.$B$BЧто еще хуже, они проводят какие-то зловещие опыты.$B$B$gНужен хорошо подготовленный:Нужна хорошо подготовленная:c; |3-6($c), чтобы оценить обстановку.$B$BЕсли Шань\'цзэ попробуют тебе помешать, можешь убить их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31040, 'ruRU', 'Злобные духи', 'Убейте 30 духов Мрачного леса или заклинателей Мрачного леса.', 'Могу подчинили духов из Мрачного леса на острове Шань\'цзэ Дао.$b$bИз мелких пакостников получились покорные слуги Шань\'цзэ. Они наглеют день ото дня, воруют и убивают по слову своих хозяев.$b$bИх нужно уничтожить, но не попадись на их уловки. С виду они безобидны, но внешность обманчива.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31041, 'ruRU', 'Спасение яиц!', 'Соберите 8 яиц облачных бегунов.', 'Яйца. Да, ты не $gослышался:ослышалась;, именно яйца, и речь не об омлете.$b$bТы $gвидел:видела; когда-нибудь яйцо облачного змея?$b$bЭто большая редкость. Они похожи на драгоценные камни и ценятся на вес золота.$b$bНа острове Шань\'цзэ Дао, что к северу отсюда, водятся дикие облачные змеи, но могу и духи забирают все их яйца себе.$b$bНам нужно достать как можно больше яиц.$b$bЯ рассчитываю на тебя, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31042, 'ruRU', 'Ониксовые сердца', 'Соберите 4 ониксовых сердца.', 'Змееловы Шань\'цзэ завладели разумами диких облачных змеев. А еще они создают темных существ из камня, металла и крови с помощью древнего колдовства.$b$bЭти создания, ониксовые Когти Бури, охраняют северо-западный остров.$b$bЯ хочу понять магию, создавшую их. Принеси мне их сердца, и я выясню, с каким колдовством мы имеем дело.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31043, 'ruRU', 'Темные искусства', 'Соберите 8 скрижалей Шань\'цзэ.', 'Говорят, что на Шань\'цзэ Дао некогда стоял огромный храм могу.$b$bТам Шань\'цзэ учились подчинять мертвецов и оживлять неодушевленное.$b$bВсе это не пропало бесследно: на острове к северо-западу отсюда есть руины, и они все еще хранят в себе эти знания.$b$bМы должны добыть все, что можно, чтобы понять суть зловещих опытов Шань\'цзэ, и чтобы они не смогли получить доступ к этим знаниям.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31044, 'ruRU', 'Бронзовые когти', 'Соберите 20 бронзовых когтей.', 'Цийлинь – одно из самых свирепых и верных созданий Шань\'цзэ.$b$bЭти твари не остановятся, пока не убьют свою жертву или не погибнут в схватке.$b$bТебе предстоит сократить их число. А еще нужно добыть их бронзовые когти.$b$bЭто прекрасные заготовки для оружия и крючьев, прочные и острые.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31045, 'ruRU', 'Иллюзии прошлого', 'Убейте 3-х мастеров иллюзий Шань\'цзэ.', '$c, тебе предстоит отправиться на северо-запад, на Шань\'цзэ Дао и уничтожить мастеров иллюзий Шань\'цзэ.$b$bЯ знаю, что требую от тебя очень многого.$b$bТвоими противниками будут сильнейшие колдуны Шань\'цзэ.$b$bПобедить их будет непросто, но ты $gлучший:лучшая:c; |3-6($c) из тех, что у нас есть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31046, 'ruRU', 'Детеныши', 'Освободите 20 детенышей облачных бегунов.', 'Теперь я знаю, что за опыты проводят Шань\'цзэ на северо-западном острове.$b$bОни выращивают змеенышей, прямо из яиц помещают их в крохотные клетки и держат среди отбросов.$b$bЗмеенышей морят голодом и мучают самые жестокие палачи.$b$bМы должны спасти столько детенышей, сколько удастся. Я позволяю тебе наказать всех могу, что попадутся тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31047, 'ruRU', 'Рожденные свободными', 'Освободите 6 диких облачных бегунов от цепей.', 'Знаешь ли ты о судьбе великих облачных змеев Пандарии, $n?$b$bТебе непременно следует послушать эту историю, но сейчас у нас мало времени.$b$bТебе достаточно знать, что танлунские дикие облачные бегуны сейчас в беде.$b$bМогу захватывают диких змеев и порабощают их разум, подчиняя своей злой воле.$b$bОтправляйся на северо-запад, к Шань\'цзэ Дао. Освободи взрослых змеев от оков. Спаси их!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31048, 'ruRU', 'Траурное настроение', 'Убейте 24 прародителя Шань\'цзэ. Вы найдете их в погребальных урнах могу.', 'В руинах на Шань\'цзэ Дао мы нашли древние погребальные урны могу.$b$bОбычно такие вещи не представляют опасности, но в этих урнах заперты разъяренные духи могу.$b$bУрны опасны для тех несчастных, которые могут найти их случайно. Но гораздо страшнее, если эти сосуды попадут в злые руки.$b$bНа Шань\'цзэ Дао им не место.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31049, 'ruRU', 'Духи не в духе', 'Убейте волшебницу Мрачного леса.', 'Духи на Шань\'цзэ Дао частенько шалили, но сейчас они попали под власть могу.$b$bВсе больше духов стекается к новому хозяину.$b$bМы не можем допустить этого.$b$bОдно дело – мелкие пакости, и совсем другое – мощная и опасная темная магия большого отряда духов.$b$bУничтожь их предводительницу, пока не поздно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31050, 'ruRU', 'Выбрать огненного мага', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31051, 'ruRU', 'Выбрать ледяного мага', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31052, 'ruRU', 'Выбрать жреца', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31053, 'ruRU', 'Tracking Event: Started Shado-Pan Dailies', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31054, 'ruRU', 'Unlocked Yalia Sagewhisper', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31055, 'ruRU', 'Между сауроками и наковальней', 'Принесите хранителю истории Чо книгу \"Между сауроками и наковальней\".', '$gДорогой:Дорогая; $n!$b$bМы получили твою работу по саурокам и отметили ее как весомый вклад в раскрытие тайн прошлого.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо', '', '', '', '', '', 'Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.', 25549);
INSERT INTO `quest_template_locale` VALUES (31058, 'ruRU', 'Обезьянье пойло', 'Одержите верх над капитаном Уком.', 'Пираты! Наши берега избрали своим пристанищем самые невоспитанные, неуемные, недобрые и нечистоплотные хозены, каких только знала Пандария. Мало того, они утверждают, что служат легендарному капитану Уку!$b$bМы каждую ночь видим, как они веселятся и варят пунш на своем острове Унга-Ингу.$b$bА давай возьмем и заберем их пунш! Я даже, пожалуй, смогу его улучшить.$b$bСобери друзей и разыщи меня на южной стороне Унга-Ингу. Пора устроить хмельной забег!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31060, 'ruRU', 'Dawson test POI', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31061, 'ruRU', 'Оседлать грозу', 'Оседлайте 8 облачных бегунов Шань\'Цзэ с помощью бронзовых когтей. Атакуйте их, чтобы очистить от скверны.', 'Шань-Бу, предводитель Шань\'цзэ, проводит темный ритуал на вершине острова к северо-западу отсюда.$B$BСудя по всему, облачные бегуны Шань\'цзэ усиливают его колдовство, но мы не знаем как.$B$BВозможно, их удастся очистить от скверны.$B$BВозьми бронзовые когти, чтобы оседлать облачного бегуна.$B$BПроучи их... может, они поумнеют!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31062, 'ruRU', 'Когда мертвецы говорят', 'Убейте Шань\'цзэ — вестника смерти.', 'За опытами Шань\'цзэ наблюдает сильный некромант: Шань\'цзэ – вестник смерти.$B$BЧтобы остановить их, придется от него избавиться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31063, 'ruRU', 'Лао-Чинь и Серевекс', 'Убейте Серевекса вместе с Лао-Чинем Стальным Брюхом.', 'Лао-Чинь сражается с вождем прямо над входом в дерево, на северной стороне Сик\'весс. Он должен добыть второй кристалл, который нужен для того, чтобы попасть в туннель богомолов.$b$bОтправляйся туда и помоги ему.', '', '', 'Серевекс', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31064, 'ruRU', 'Нужун и Ротек', 'Воспользуйтесь помощью повелителя ястребов Нужуна, чтобы убить Ротека.', 'Повелитель ястребов Нужун направился в северо-западную часть Сик\'весс, дабы убедиться, что последнему предводителю богомолов никуда не скрыться.$b$bДогони его и помоги убить предводителя богомолов. Если ты поможешь, Нужун добудет последний кристалл.', '', '', 'Ротек', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31065, 'ruRU', 'Спрятано внутри', 'Посмотрите в подзорную трубу на дозорном пункте Жэнь-сая.', 'Таоши установила подзорную трубу на склоне горной гряды, чтобы показать мне результаты разведки.$b$bПодойди и посмотри.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31066, 'ruRU', 'Крик из тьмы', 'Убейте оскверненный Идеал у Кипари Вор.', 'Итак, тебе удалось близко подойти к имперским кладкам и выжить. Ты... $gвынослив:вынослива;.$B$BКлакси слышат еще один Идеал, на севере, среди выжженых ша корней Кипари Вор.$B$BОн кричит в муке и ужасе, спасти его невозможно.$B$BКлакси хотят, чтобы ты $gположил:положила; конец его мучениям. Убей его, иначе можешь сюда не возвращаться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31067, 'ruRU', 'Война жужжит на небесах', 'Убейте Аззикса К\'тая.', 'От богомолов вечно одни только проблемы, но сейчас они зашли слишком далеко!$b$bМы можем отбить отдельные атаки из Кор\'весс, но сейчас... сейчас они пытаются окружить нас. Вдобавок ко всему, они собирают янтарь с нашего дерева!$b$bНет, так не пойдет! Нам самим этот янтарь для пива нужен!$b$bОни сделали подкоп к югу от дерева, а там у нас бойцов не хватает. Можешь их оттуда прогнать?', '', 'Плохой богомол.', 'Аззикс К\'тай', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31068, 'ruRU', 'Священный рецепт', 'Принесите свиток с предсказанием Ля Десять Песен в хмелеваренный дворик \"На закате\".', '\"Когда небеса загудят в смятении\nИ страх поднимется из долин,\nВместилище нашего избавленья\nРазбей до самых его глубин.\"$b$bДальше в свитке еще несколько строф. Возможно, кто-то в хмелеваренном дворике \"На закате\" сможет расшифровать это загадочное послание.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31069, 'ruRU', 'Связанные тенью', 'Соберите 100 капель тени, убив существ ша и оскверненных ша диких животных в окрестностях хмелеваренного дворика \"На закате\".', 'Найденный тобой свиток...$b$bЯ все смотрю на эту строчку во второй строфе – \"Тенью и деревом ты свяжи\". Особенно меня интересует \"тень\".$b$bНадо сказать, мне часто приходило в голову собрать остаточную сущность ша в окрестностях и добавить ее в пиво. Думаю, это и есть та самая тень, о которой говорится в нашем рецепте.$b$bБольших ша можно найти к юго-востоку от нашего дерева... хотя, возможно, тебе удастся вытрясти немного из местной живности.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31070, 'ruRU', 'Кинжалы великих', 'Добудьте 3 больших зуба мушана.', 'В рецепте сказано: \"Кинжалы злые великих, статных\"...$b$b<Олон глубоко задумался над отрывком.>$b$bМушан! Это точно мушан!$b$bТам полным-полно мушанов с такими огромными зубами, длинными, точно кинжалы. Наверное, о них говорится в рецепте.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31071, 'ruRU', 'Позор мне', 'Найдите потерянный бочонок, потерянные кружки и потерянные припасы для пикника.', 'Я подвел своих собратьев-хмелеваров.$b$bЯ оставил нужные нам вещи на прогалине к востоку от нашего дерева... Теперь, когда ша заполонили землю, а богомолы вышли на охоту, я не могу вернуться и забрать их, это слишком опасно.$b$bЕсли ты поможешь мне отыскать их, то моя честь будет хотя бы отчасти восстановлена.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31072, 'ruRU', 'Добыть кинжалы', 'Добудьте клинок Кз\'Кзика и клинок Иликкакса.', 'Забудь про них и про их пиво. У нас тут серьезная работа.$b$bВ свитке написано \"Кинжалы злые великих, статных\". Кажется, я знаю, где их найти.$b$bПара богомолов-лейтенантов патрулирует Подступы Ужаса, что к югу отсюда. У каждого из них есть церемониальный кинжал.$b$bПринеси сюда эти кинжалы, $n. Возможно, мы на пороге чего-то очень важного.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31073, 'ruRU', 'Скованные древом', 'Добудьте 8 кусков ароматной древесной сердцевины.', '<Ву изучает рецепт.>$b$bХм-м... \"деревом ты свяжи\". Мы обычно не варим дерево. Сок – да, но не древесину.$b$bИзредка мы добавляли в наши напитки сердцевину древней, что водились к западу отсюда. Большинство из них уничтожено богомолами... но их останков хватит для рецепта.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31074, 'ruRU', 'Дерево и тень', 'Найдите метку императрицы и главный корень дерева Кипари Кор.', '\"Кинжалы злые великих, статных тенью и деревом ты свяжи\". Хм-м.$b$bМне стало многое известно о богомолах кор\'тик за время, проведенное здесь. Я знаю, что в их поселении, Кор\'весс, находятся святилища.$b$bОдно из них – в главном корне дерева, где они живут. Второе – темный столп, соединяющий их с королевой.$b$bЭти святилища и есть дерево и тень. Если мои предсказания верны... кинжалы должны соединиться, когда их поднесут ближе к ним.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31075, 'ruRU', 'Закатные короли', 'Встретьтесь с соковаром Ву в деревне Риккитун.', 'У Олона отличная идея. Он думает, что нужно навестить духов к западу отсюда и спросить, нет ли у них каких-нибудь ингредиентов из списка. Некоторые пункты рецепта выглядят... странно.$b$bДухи Риккитун живут в деревне к западу от Кор\'весс. Встретимся там, $n.', '', '', '', '', '', 'Поговорите с соковаром Ву в деревне Риккитун, что в Жутких пустошах.', 25549);
INSERT INTO `quest_template_locale` VALUES (31076, 'ruRU', 'Судьба семейства Буйный Портер', 'Спросить у обитателей хмелеваренного дворика \"На закате\", не видели ли они Буйных Портеров.', 'Приветствую тебя, |3-6($r). Меня зовут Чэнь Буйный Портер.$b$bЯ ищу свою семью. Мне сказали, что несколько Буйных Портеров перешли через стену, чтобы помочь справиться с богомолами. Я хочу присоединиться к ним.$b$bНе проходил ли здесь кто-нибудь по имени Буйный Портер? Можешь помочь мне расспросить здешних жителей?', '', '', '', '', '', 'Вернитесь к Чэню Буйному Портеру в хмелеваренный дворик \"На закате\", что в Жутких пустошах.', 19865);
INSERT INTO `quest_template_locale` VALUES (31077, 'ruRU', 'Эви Буйный Портер', 'Подойдите к Чэню в хмелеваренном дворике \"На закате\" и прослушайте его скорбную песнь.', 'Я опоздал. Она была совсем малюткой... и я опоздал.$b$bНадо похоронить ее достойно. Маленькая воительница вроде нее заслуживает большего, нежели это.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31078, 'ruRU', 'Хань Буйный Портер', 'Найдите Ханя Буйного Портера в Зале Потоков под Кор\'весс.', 'Время горевать придет позже. Сейчас нужно найти остальных Буйных Портеров.$b$bГоворят, Ханя Буйного Портера в последний раз видели, когда он обследовал Кор\'весс. Подозреваю, что он направился в логово богомолов, прямо по пути.$b$bВстреть меня там, $n. Я не сомневаюсь, что справлюсь с несколькими богомолами в одиночку... но мне спокойней, если ты будешь рядом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31079, 'ruRU', 'Страх из долин', 'Убейте 7 слоняющихся туманных скрытней и 2 кипаритов.', 'Богомолы нас не тронут. Об этом мы договорились много тысяч лет назад.$b$bНо это не значит, что мы в безопасности. Подземные кипариты, что живут к западу отсюда, преследуют нас, охотятся... они питаются нами. Скрытни пожирают нас во множестве.$b$bПомоги нам, $gчужестранец:чужестранка;. Избавь нас от этой напасти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31080, 'ruRU', 'Ярость бурь королей закатных', 'Потряси порхунов Риккили, а затем поймай 88 крупинок пыльцы порхунов.', 'Кажется, в той старой рукописи говорилось что-то о \"закатных королях\". У здешних дракончиков есть крылья огненного цвета... похоже на свет солнца на закате.$b$bТы шустрее меня. Попробуй поймать нескольких дракончиков... или хотя бы натрясти с них пыльцы.$b$bНезачем убивать безобидного дракончика, если нужны всего лишь блестки с его крылышек.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31081, 'ruRU', 'Заклятья, что силу хранят в веках', 'Уничтожьте Агуносса и Мигонесса.', 'Думаю, нам понадобится помощь тех духов.$b$bУ нас есть два зачарованных кинжала, связанных древом и тенью. Теперь нужно, чтобы кто-то произнес древние \"заклятья\" над нашим артефактом.$b$bПрежде чем просить об услуге, надо показать духам, что у нас добрые намерения. Их глава говорил о паре туманников, укравших нескольких жителей деревни. Если убить этих туманных тварей... то мы, возможно, в награду получим \"заклятье\", которое нам нужно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31082, 'ruRU', 'Вместилище нашего избавленья', 'Принесите 3 семени матери древ в яму для семян в деревне Риккитун с помощью заклинателей Риккитун.$b$bВы можете использовать колокол Риккитун, чтобы призвать заклинателей, если вы потеряете друг друга.', 'Я знаю, что ищете вы с девочкой-пандой. Мы можем провести для вас ритуал... но позже.$b$bСначала я прошу помочь нам. С великой матери древ падают семена. Наша обязанность – собирать их, даже в опасные времена, подобные нынешним.$b$bСопроводите моих заклинателей к семенам матери древ, чтобы они принесли их в яму для семян.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31083, 'ruRU', 'Обещание золота', 'Доложите вождю Риккитун в деревне Риккитун, что в Жутких пустошах.', 'Сразу после гибели этого существа появилась стайка лесных духов, они забрали жемчужину.$b$bДеревня лесных духов недалеко отсюда, она называется Риккитун. Советую туда зайти.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31084, 'ruRU', 'Связать чары', 'Позвольте вождю Риккитун зачаровать раздвоенный клинок.', 'Много, много лет прошло с тех пор, как наше племя проводило этот ритуал. Я буду стараться изо всех сил.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31085, 'ruRU', 'Огонь и былого страх', 'Используйте двузубец разрушения на Ийокуке Проницательном, а затем защитите его, пока он не сможет спастись.', 'Мы нашли клинки, связали их древом и тьмой и благословили древним заклинанием. Если я не ошибаюсь, пора использовать эту штуку.$b$bДухи говорили о древней смоле в Янтарной усыпальнице, пещере богомолов возле дворца их императрицы. Это, должно быть, \"Кровь Древних\", о которой говорит пророчество.$b$bВнутри этой смолы находится что-то важное. Удачи тебе, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31086, 'ruRU', 'Кровь Древних', 'Добудьте кусок затвердевшего янтаря.', 'Кое в чем мы с Ля совершенно согласны: \"кровь Древних\" – это наверняка смола здешних великих деревьев. Да и мне ли не знать! Я ведь постоянно использую ее при варке.$b$bСамое древнее из местных деревьев – дом великой императрицы Шек\'зир, который сейчас зовут Сердцем Страха. Добудь немного янтаря с того дерева, и варево будет готово!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31087, 'ruRU', 'Усиление сигнала', 'Активируйте резонирующий маячок в Янтарном зале.', 'Клакси\'ва стало известно еще об одном Идеале. Его голос слаб и глух, а значит, сигнал надо усилить!$b$bВ Янтарном зале есть башня-сонар, которая затихла очень давно. Ее песнь должна прозвучать вновь. Так приказали клакси!$b$bВ этот раз я пойду с тобой. Ты поможешь мне ее починить.$b$bВозьми резонирующий кристалл и найди меня там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31088, 'ruRU', 'Преступление и наказание', 'Убейте 8 ик\'тиков-жнецов на Жгучей тропе.', 'Вдоль Жгучей тропы растет много молодых деревьев кипари, но императрица приказала собирать янтарь и с этих саженцев... слишком рано! Так нельзя, $gчужестранец:чужестранка;!$b$bКлакси\'ва требуют, чтобы злодеи понесли заслуженное наказание! Доставь им радость и уничтожь ик\'тиков-жнецов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31089, 'ruRU', 'Уже не у моря', 'Поднесите камертон клакси к океаническим камням и пробудите Идеал.', 'Клакси\'ва говорили со мной, $gчужестранец:чужестранка;. Идеал был спрятан на Соленой отмели, но нам все же удалось его отыскать.$b$bЕго окружают люди-ящеры, и мы не можем позволить им и пальцем его тронуть!$b$bНайди его и пробуди. Без Идеала можешь не возвращаться!$b$bЕсли справишься со своей задачей, то клакси будут нам весьма признательны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31090, 'ruRU', 'Чем старше, тем лучше', 'Соберите 7 кувшинов с янтарем с накопителей янтаря на Жгучей тропе.', 'Собирать янтарь с саженцев – преступление, но еще большее преступление – позволить ему бесцельно пропасть.$b$bМолодой янтарь не так полезен, но клакси он все равно пригодится. Принесем им побольше янтаря, и они восславят меня!$b$bСобери молодой янтарь, мы поместим его в хранилище, выдержим его там, и он будет пригоден для еды.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31091, 'ruRU', 'Воссоединение', 'Помогите Каз\'тику Манипулятору, пока он выкапывает свое величайшее оружие.', 'Тот, кого ты видишь перед собой, не очень-то похож на воина, да? Так почему же его назвали Идеалом, думаешь ты... Не все оружие можно увидеть, Пробудитель. О книге по обложке не судят.$b$bНо мне нужно убедиться в твоей благонадежности, прежде чем я поясню, в чем дело.$b$bНезадолго до того, как я был погружен в сон, нечто драгоценное для меня было спрятано, без чего я ничего не стою.$b$bЗащити меня, пока я ищу мое величайшее оружие, и обретешь мое доверие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31092, 'ruRU', 'Покормить или стать обедом', 'Начните обучение Ковока, скормив ему 6 порций сочного черепашьего филе. Его можно добыть, убивая океанических крепкохватов на Соленой отмели.', 'Я долгие годы изучал куньчунов, и у меня появилась теория: если воспитывать их с детства, то связь между вами, в том числе звуковая, будет крепче.$b$bКогда меня решили заточить в янтаре, я только начал обучать Ковока. Он еще очень молод, и, чтобы раскрыть его потенциал, необходимы долгие тренировки.$b$bЯ доверю Ковока тебе, но запомни: если обидишь его, прощайся с жизнью.$b$bСначала надо накормить Ковока, чтобы завоевать его доверие. Для этого вполне подойдут черепахи, которые водятся в этих краях.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31093, 'ruRU', 'Хозен в тумане', 'Принесите работу \"Хозен в тумане\" хранителю истории Чо в Обитель Мудрости.', '$gДорогой:Дорогая; $n!$b$bТвое исследование хозенов позволяет взглянуть на них под новым углом.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо', '', '', '', '', '', 'Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.', 25549);
INSERT INTO `quest_template_locale` VALUES (31094, 'ruRU', 'Рыбьи байки', 'Принесите книгу \"Рыбьи хвосты\" хранителю истории Чо в Обитель Мудрости.', '$gДорогой:Дорогая; $n!$b$bТвой труд о цзинь-юй доставил мне истинное наслаждение. Поразительный народ, и такой умный.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо', '', '', '', '', '', 'Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.', 25549);
INSERT INTO `quest_template_locale` VALUES (31095, 'ruRU', 'Черное сердцу могу', 'Принесите книгу \"Черное сердце могу\" хранителю истории Чо в Обитель Мудрости.', '$gДорогой:Дорогая; $n!$b$bДавно известно, что могу – зловещий народ, их сердца полны мрака. Однако твое исследование показывает, что они еще хуже.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо', '', '', '', '', '', 'Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.', 25549);
INSERT INTO `quest_template_locale` VALUES (31096, 'ruRU', 'За что стоит сражаться', 'Принесите книгу \"За что стоит сражаться\" хранителю истории Чо в Обитель Мудрости.', '$gДорогой:Дорогая; $n!$b$bТебе удалось раздобыть рассказ о том, как наш народ избавился от гнета могу.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо', '', '', '', '', '', 'Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.', 25549);
INSERT INTO `quest_template_locale` VALUES (31097, 'ruRU', 'Сердце роя богомолов', 'Принесите книгу \"Сердце роя богомолов\" хранителю истории Чо в Обитель Мудрости.', '$gДорогой:Дорогая; $n!$b$bМы ценим твои усилия по изучению истории и преданий Пандарии, но найденные тобой данные о богомолах попросту лишили меня сна. Пугающие сведения.$b$bЕсли посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо', '', '', '', '', '', 'Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.', 25549);
INSERT INTO `quest_template_locale` VALUES (31100, 'ruRU', 'Песнь яунголов', 'Принесите \"Песнь яунголов\" хранителю истории Чо в Обитель Мудрости.', '$gУважаемый:Уважаемая; $n.$b$bТвои исследования, касающиеся яунголов оказались очень проницательными.$b$bЕсли ты посетишь нас в Обители Мудрости в Вечноцветущем доле, мы добавим этот вклад в исследования в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо', '', '', '', '', '', 'Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.', 25549);
INSERT INTO `quest_template_locale` VALUES (31102, 'ruRU', 'Семь бремен Шаохао', 'Принесите \"Семь бремен Шаохао\" хранителю истории Чо в Обитель Мудрости.', '$gДорогой:Дорогая; $n.$b$bТебе удалось восстановить полное сказание о Шаохао – последнем императоре Пандарии.$b$bЕсли ты посетишь нас в Обители Мудрости в Вечноцветущем доле, мы добавим этот вклад в исследования в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо', '', '', '', '', '', 'Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.', 25549);
INSERT INTO `quest_template_locale` VALUES (31103, 'ruRU', 'Баллада о Лю Лане', 'Принесите \"Балладу о Лю Лане\" хранителю истории Чо в Обитель Мудрости.', '$gДорогой:Дорогая; $n!$b$bБлагодаря твоим исследованиям у нас, наконец, есть полная баллада о Лю Лане.$b$bЕсли посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо', '', '', '', '', '', 'Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.', 25549);
INSERT INTO `quest_template_locale` VALUES (31104, 'ruRU', 'Бойцовский круг: Ялия Мудрый Шепот', 'Бросьте вызов Ялии Мудрый Шепот и победите ее в бойцовском круге.', 'Братья и сестры шадо-паны продолжают шептаться о твоих делах, $n.$B$BДаже сама Ялия заинтересовалась твоим обучением.$B$BОна желает сразиться с тобой в бойцовском круге.$B$BТебе бы стоило впечатлить ее. Если у тебя это получится, она сможет помочь тебе в будущем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31105, 'ruRU', 'Угроза могу', 'Убейте 12 змееловов Шань\'цзэ или повелителей зверей Шань\'цзэ.', 'Разведчики засекли большой отряд могу к северо-западу отсюда, на острове Шань\'цзэ Дао.$B$BНовости не из лучших, остров считался пустым.$B$BЧто еще хуже, они проводят какие-то зловещие опыты.$B$B$gНужен хорошо подготовленный:Нужна хорошо подготовленная:c; |3-6($c), чтобы оценить обстановку.$B$BЕсли Шань\'цзэ попробуют тебе помешать, можешь убить их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31106, 'ruRU', 'Угроза могу', 'Убейте 12 змееловов Шань\'цзэ или повелителей зверей Шань\'цзэ.', 'Разведчики засекли большой отряд могу к северо-западу отсюда, на острове Шань\'цзэ Дао.$B$BНовости не из лучших, остров считался пустым.$B$BЧто еще хуже, они проводят какие-то зловещие опыты.$B$B$gНужен хорошо подготовленный:Нужна хорошо подготовленная:c; |3-6($c), чтобы оценить обстановку.$B$BЕсли Шань\'цзэ попробуют тебе помешать, можешь убить их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31107, 'ruRU', 'Граждане новой империи', 'Соберите 10 яиц вор\'тиков у Кипари Вор.', 'По приказу Шек\'зир великое дерево Кипари Вор было превращено в тотем ужаса.$B$BТеперь эта кладка, как и те, что снаружи дворца, оскверняет роерожденных.$B$BДобудь яйца вор\'тиков, прежде чем их коснется скверна, и мы вырастим из них граждан новой империи, свободной от ша.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31108, 'ruRU', 'Воплощение страха', 'Соберите 4 куска жуткого янтаря с вор\'тиков-жуткоревов в Кипари Вор.', 'В янтаре заключена великая сила. Она порождает жизнь.$B$BНо этот янтарь испорчен. В нем сконцентрирован страх.$B$BВор\'тики знают это. Их кипари поражены ша, и смола дерева превращается в кристаллы концентрированного страха.$B$BПринеси их мне. Мы исследуем их и постараемся уничтожить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31109, 'ruRU', 'Уничтожение роя', 'Уничтожьте 40 Шек\'зир-роерожденных во Владениях Шек\'зир. Поговорите с Кил\'руком Рассекающим Ветер, чтобы отправиться туда.', 'Императрица продолжает наращивать свое войско. Если так будет продолжаться – они преодолеют стену. Заберутся на нее по трупам миллионов роерожденных.$B$BДавай найдем для их трупов место получше.$B$BДай мне знать, когда будешь $gготов:готова; отправиться во Владения Шек\'зир. Я помогу тебе добраться туда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31110, 'ruRU', 'Через портал', 'Соберите 1000 порций древнего чародейского порошка.', 'Вот и |3-6($c), жду не дождусь!$B$BМы поняли, почему портал не работает. Надо больше чародейского порошка.$B$BМожно заказать, но это займет не один месяц... К счастью, порошка немало у могу на этом острове, им он тоже для заклинаний нужен.$B$BНо у них порошок староват, так что нужно много.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31111, 'ruRU', 'Битва с зан\'тиками', 'Убейте 6 зан\'тиков-пронзателей и 6 зан\'тиков-манипуляторов в Зан\'весс.', 'Мало кого в империи так боятся и уважают, как воинов Зан\'весс, и не зря.$B$BПронзатели превосходят всех в мастерстве владения древковым оружием – Малик в свое время явно учился у них. А их манипуляторы с легкостью испускают убийственные звуковые волны.$b$bИ тех, и других врагов необходимо убить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31112, 'ruRU', 'Они такие колючие!', 'Заберите 5 комплектов для оказания первой помощи у водных духов.', 'Ящик, когда-то полный очень нужных вещей, полностью разграблен.$b$bБеглый осмотр местности помог найти улики, оставленные воришками. Ледяные шипы, совсем как у водных духов с береговой линии к востоку отсюда.$b$bДля горстки выживших это вопрос жизни и смерти. Надо отнять похищенное у воришек и вернуть в лагерь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31113, 'ruRU', 'Напасть на огненный лагерь Гай-Чо', 'Убейте 16 яунголов Гай-Чо, толкователей земли или метателей смолы.', 'Яунголы докучают нам постоянно, но отряд, который собрался на северо-востоке, в лагере Гай-Чо, вместе с осулами участвовал в последнем налете на Кунь-Лай.\n\nНалетчиков следует покарать.\n\nИди и атакуй лагерь Гай-Чо. Ты отвлечешь их, чтобы враг у Врат Быка не дождался подкреплений.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31114, 'ruRU', 'Напасть на Плато Говорящего с Мертвыми', 'Убейте 8 говорящих с мертвыми – осквернителей праха и 1 говорящего с мертвыми – крушителя.', 'Мы никогда не трогали говорящих с мертвыми. Они проводили священные погребальные ритуалы в племенах яунголов.\n\nНо теперь они прибегают к темной магии, оскверняя тела своих бывших соплеменников...\n\nЯ не знаю, ни где они нашли эти ритуалы, ни почему они позволяют себе осквернять тела погибших соратников, и выяснять это некогда.\n\nИх нужно остановить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31115, 'ruRU', 'FLAG - Freed Han', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31116, 'ruRU', 'Пыль духов', 'Верните 8 духов к их телам на Плато Говорящего с Мертвыми, что в Танлунских степях.', 'Яунголы поймали в ловушку духов своих предков. Но у духов еще осталось немного сущности жизни.\n\nЕсли тебе удастся победить их в бою, эта сущность достанется тебе в виде пыли. Посыпь этой пылью могилы, и духи смогут обрести новую жизнь.\n\nТолько так можно исправить то, что натворили толкователи мертвых. И нам будет поспокойней.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31117, 'ruRU', 'Урук!', 'Убейте Урука на Плато Говорящего с Мертвыми в Танлунских степях.', 'Говорящего с мертвыми Танлунских степей зовут Уруком. Твоя задача не будет завершена, пока он жив. Иди же!', '', '', 'Урук', '', '', 'Поговорите с мастером Снежным Вихрем в гарнизоне Шадо-Пан, что в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (31118, 'ruRU', 'Шифр говорящих с мертвыми', 'Заберите у яунголов с Плато Говорящего с Мертвыми свиток с ритуалами ловли душ.', 'Нам нужно разобраться, что пошло не так с говорящими с мертвыми.\n\nМного лет говорящие с мертвыми просто приглядывали за кладбищами и хоронили павших воинов.\n\nНо в последний раз мы нашли скрижаль, которая покрыта зашифрованными надписями, но шифр какой-то другой. Если тебе удастся завладеть каким-нибудь свитком, где используется этот же шифр, мы сможем разобраться в том, что происходит.', '', '', '', '', '', 'Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (31119, 'ruRU', 'Враг моего врага... все равно мой враг!', 'С помощью взрывоопасных бочек с яунгольской нефтью убейте 100 богомолов или яунголов на поле битвы Гай-Чо.', 'Богомолы нам враги. Яунголы из огненного лагеря Гай-Чо – тоже.\n\nНо и друг с другом они не ладят. Богомолы из Кри\'весса постоянно нападают на яунголов Гай-Чо, но дальше ворот прорваться не могут.\n\nТвое дело – перевернуть все вверх дном. Позаимствуй в огненном лагере Гай-Чо взрывоопасные бочки с нефтью и сбрось их сверху на поле боя.\n\nНеважно, кто именно пострадает, лишь бы погибло как можно больше народу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31120, 'ruRU', 'Чэн Бо!', 'Убейте Чэна Бо в огненном лагере Гай-Чо в Танлунских степях.', 'Вестника войны огненного лагеря Гай-Чо зовут Чэн Бо. Тебе удалось сорвать немало планов противника, а теперь тебе выпала честь нанести страшный удар.\n\nУбей вестника войны!', '', 'Вестник войны яунголов Гай-Чо', 'Чэн Бо', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31121, 'ruRU', 'Постой и послушай', 'Выпейте чая из чайника Чо.', 'Быстрей, быстрей – ваш народ всегда так торопится?$b$bСядь и выпей со мной чаю, и мы обсудим ваше затруднительное положение.$b$b<Хранитель истории Чо терпеливо улыбается.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31122, 'ruRU', 'Chose Prot Warrior', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31123, 'ruRU', 'Chose Arms Warrior', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31124, 'ruRU', 'Chose Brewmaster', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31125, 'ruRU', 'Unlocked Chao', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31126, 'ruRU', 'Unlocked Lao-Chen', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31127, 'ruRU', 'Бойцовский круг: Чао Голосистая', 'Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, Чао Голосистую и победите ее.', 'Ты кажешься хорошим бойцом, $n.\n\nОб этом прослышала Чао, теперь она хвалится, что надерет тебе...\n\nКороче, тебе стоит вызвать ее на бой и попытаться завоевать ее уважение.', '', '', 'Чао Голосистая', '', '', 'Вернитесь к мастеру Снежному Вихрю в гарнизон Шадо-Пан в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (31128, 'ruRU', 'Бойцовский круг: Лао-Чинь Стальное Брюхо', 'Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, Лао-Чиня Стальное Брюхо и победите его.', 'Лао-Чинь почти все время витает в облаках... и обычно в пивных.\n\nПосле всех этих битв он загорелся идеей создать пиво для сражения.\n\nЭто прекрасно, конечно, но собственно сражаться-то кто будет?!\n\nСловом, вызови его на бой, может, тебе удастся вернуть его на землю.\n\nЕсли ты победишь, с него станется продолжить бой снаружи, лишь бы обставить тебя!', '', '', '', '', '', 'Вернитесь к мастеру Снежному Вихрю в гарнизон Шадо-Пан в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (31129, 'ruRU', 'Судьба семейства Буйный Портер', 'Спросить у обитателей хмелеваренного дворика \"На закате\", не видели ли они Буйных Портеров.', '$n! Так приятно видеть тебя в добром здравии в таких дальних краях. Кажется, наши пути крепко переплелись между собой.$b$bЯ ищу здесь свою семью. Мне сказали, что несколько Буйных Портеров перешли через стену, чтобы помочь справиться с богомолами. Я хочу найти их и присоединиться.$b$bНе проходил ли здесь кто-нибудь по имени Буйный Портер? Можешь помочь мне расспросить здешних жителей?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31130, 'ruRU', 'Визит к хранителю истории Чо', 'Подружитесь с хранителем истории Чо, оказав ему помощь по дому: подстригите дерево, покрасьте стену, накормите птиц.', '$gНезнакомец:Незнакомка;, я могу помочь тебе найти твоего принца. Но сначала я хочу больше узнать о тебе и твоем народе.$B$BПомоги мне закончить дела, и мы поговорим.$B$BУ тебя взгляд убеленного сединой ветерана многих войн, но наверняка у тебя найдется пара минут, чтобы помочь пандарену-книголюбу вроде меня прибраться в доме, правда?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31132, 'ruRU', 'Попробуй побыть мной', 'Поговорите с хранителем истории Чо у Круга Кости.', 'Ой, куда подевались мои манеры? Формально, я считаюсь тут хозяином.$b$bПозволь рассказать немного о себе и моем народе, а потом я задам вопросы уже тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31133, 'ruRU', 'Агрессия кор\'тик', 'Уничтожьте 17 богомолов кор\'тик в Кор\'весс.', 'Я не хмелевар... только от взгляда на все эти ингредиенты голова кружится. Просто пусть ставят пиво передо мной, когда оно готово, и на том спасибо.$b$bНет, я слежу за тем, чтобы хмелеваров не порубили, пока они пытаются сделать идеальное пиво. Это нелегко.$b$bБогомолы кор\'тик с той стороны водоема атакуют нас по ночам. Если ты и так идешь туда, может, вернешь им должок и нападешь на них в ответ?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31134, 'ruRU', 'Если бы камни могли говорить', 'Используйте каменные монолиты в Круге Кости.', 'Это очень древнее место.$b$bЛишь недавно я собрал воедино метод перевода забытого языка, на котором вырезаны надписи на этих камнях.$b$bО, радость открытий! Она всегда в новинку, могу заверить.$b$bВот, ты гость. Тебе достается самая почетная роль. Я настаиваю.$b$bЭтим ключом ты откроешь секреты, которые хранят эти камни.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31135, 'ruRU', 'Будущее Гномрегана', 'Поговорите с Си Другом Низкорослых в Новом Городе Механиков.', 'Мы празднуем победу каждый раз, когда нам удается помочь очередному выжившему выбраться из зараженных залов Гномрегана. Такой |3-6($c), как ты, может сыграть важную роль в будущем Гномрегана. В связи с этим наш предводитель, главный механик Меггакрут, собрал команду наставников, чтобы ты $gмог:могла; обучаться своему искусству.$b$bСи Друг Низкорослых приехала к нам издалека и поможет тебе с тренировками и с подготовкой к жизни на поверхности. Она ждет тебя на небольшом поле для тренировок через дорогу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31137, 'ruRU', 'Встретиться с главным механиком', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 'Не знаю, вспомнишь ли ты Меггакрута. Невин и другие гномы говорят, что многие выжившие страдают потерей памяти.$b$bВ общем, главный механик Меггакрут – предводитель всех гномов. Он взял за правило лично встречаться со всеми, кому удалось остаться в живых. Тебе следует представиться Меггакруту. Он вместе с военным советом сейчас в шатре в центре города.', '', '', '', '', '', 'Представьтесь главному механику Меггакруту в Новом Городе Механиков.', 25549);
INSERT INTO `quest_template_locale` VALUES (31138, 'ruRU', 'Искусство монаха', 'Достигните 3-го уровня, чтобы изучить прием \"Лапа тигра\". Выучив, дважды примените его на тренировочном манекене в Новом Городе Механиков.', 'Сражаясь, ты совершенствуешь свои навыки. Совершенствуя их, ты узнаешь новые движения. Иди, посмотри на мир, выучись и покажи мне все, что сможешь узнать.', '', '', '', '', '', 'Вернитесь к Си Другу Низкорослых в Новый Город Механиков.', 19865);
INSERT INTO `quest_template_locale` VALUES (31139, 'ruRU', 'Дать отпор!', 'Убейте 6 воргов из клана Черной горы.', 'Стало быть, ты новобранец из Штормграда? Я маршал Макбрайд, командир гарнизона. Добро пожаловать в строй!$B$B<Макбрайд просматривает какие-то бумаги.>.$B$B$n. $n, так?$B$BТы как раз вовремя. Оркам Черной горы удалось проникнуть в Североземье через горный разлом. Мои солдаты делают все возможное, чтобы оттеснить врага, но их становится все больше и больше.$B$BОтправляйся на северо-запад в лес и истреби там вторгшихся воргов из клана Черной горы! Приди на помощь нашим войскам!', '', 'Боевые ворги клана Черной горы – опасные хищники.', 'Боевой ворг клана Черной горы', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31140, 'ruRU', 'Волки и овцы', 'Расправьтесь с 8 шпионами клана Черной горы.', 'Орки-захватчики – не дураки. Они следят за нашими действиями, чтобы улучить удобный момент для нападения.$B$BВ лесу на северо-западе расположились шпионы из клана Черной горы. Они смотрят на нас через подзорные трубы, выжидая удобный час. Я хочу, чтобы ты $gнапал:напала; на них!$B$BРасправься со шпионами клана Черной горы! Нужно продемонстрировать им, что мы знаем о том, что они следят за нами, а также показать нашу боеготовность!', '', 'Это шпион клана Черной горы. Однако иногда встречаются и шпионки.', 'Шпион клана Черной горы', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31141, 'ruRU', 'Каллиграфическое письмо', 'Прочитайте каллиграфическое письмо и поговорите с Бао в Аббатстве Североземья.', 'Меня попросили передать тебе это письмо, как только ты разделаешься с шпионами клана Черной горы, $n. Похоже, что на нем стоит печать пандарена Бао, прибывшего из далеких краев. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', '', '', 'Бао', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31142, 'ruRU', 'Лапа тигра', 'Достигните 3-го уровня, чтобы изучить прием \"Лапа тигра\", затем опробуйте этот прием на тренировочном манекене, расположенном к югу от входа в аббатство Североземья.', 'Теперь, когда ты $gиспытал:испытала; свои силы в бою, пришло время рассказать тебе о важности тренировок.$B$BКогда ты наберешься опыта, то сможешь использовать новые техники, о которых раньше и не $gмечтал:мечтала;.\n\nИди и наберись опыта, выучи новую способность и потренируй ее на тренировочных манекенах.', '', '', '', '', '', 'Вернитесь к Бао в оружейную в аббатство Североземья.', 19865);
INSERT INTO `quest_template_locale` VALUES (31143, 'ruRU', 'В бой!', 'Явитесь к сержанту Виллему, находящемуся за Аббатством Североземья.', 'Мне пришло срочное донесение от сержанта Виллема. Оказывается, орки Черной горы привлекли гоблинов, промышляющих наемными убийствами. Они атаковали позиции нашего батальона за аббатством. Виллем попросил меня прислать ему на подмогу $gнастоящего героя:настоящую героиню;. Ты $gдолжен:должна; прийти им на помощь, $n!$B$BОбратись к сержанту Виллему, который находится к северу от аббатства в командирском шатре. За дело!', '', 'Сержант Виллем находится в командирском шатре позади Аббатства Североземья.', 'Сержант Виллем', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31144, 'ruRU', 'Враг подослал наемных убийц', 'Прикончите 8 гоблинов-убийц.', 'Ты когда-нибудь $gвстречал:встречала; гоблина, $n? Это презренные зеленокожие монстры, любящие лишь две вещи: золото и самих себя.$B$BОрки Черной горы прибегли к услугам гоблинов, промышляющих наемными убийствами, чтобы те убивали наших солдат. Погляди на поле к северу от нас: ты вряд ли разглядишь, как они маскируются в траве.$B$BХочу, чтобы ты $gпошел:пошла; туда и $gперебил:перебила; всех гоблинов, которых сможешь найти. Пусть узнают, что не следует выступать против Альянса.', '', 'Это гоблин-убийца. Подлое маленькое создание!', 'Гоблин-убийца', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31145, 'ruRU', 'Тыл зачищен', 'Явитесь к маршалу Макбрайду, стоящему перед Аббатством Североземья в Элвиннском лесу.', 'Прекрасно сработано, $n! Отныне тыл можно считать зачищенным. Мы сами займемся оставшимися противниками. Я хочу, чтобы ты $gпошел:пошла; к маршалу Макбрайду, стоящему перед Аббатством Североземья, что к югу отсюда, и $gдоложил:доложила; ему, что ситуация с гоблинами находится под контролем.$B$BПрощай, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31146, 'ruRU', 'Простой свиток', 'Прочтите изящный свиток и поговорите с Тин Крепкий Желудок в Похоронном Звоне.', 'Пока ты разбирался с Плетью, тебе пришел свиток. Его принесла пандарен по имени Тин. Может, вы, монахи, и понимаете эти каракули, но я ничего не могу разобрать. Поговори с Тин, она в таверне.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31147, 'ruRU', 'Лапа тигра', 'Достигните 3-го уровня, чтобы изучить прием \"Лапа тигра\", затем испытайте его на тренировочном манекене.', 'На пути к мастерству испытаниям подвергнется твои тело и дух. Ты откроешь в себе новые способности, о которых ранее и не $gподозревал:подозревала;. Иди же и работай над собой, и вскоре ты овладеешь ударом тигра. Затем отточи новое умение на тренировочном манекене.', '', '', '', '', '', 'Вернитесь к Тину Крепкому Желудку в Похоронный Звон, что в Тирисфальских лесах.', 19865);
INSERT INTO `quest_template_locale` VALUES (31148, 'ruRU', 'Новобранец Элрет', 'Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.', 'Кстати, тебе следует побеседовать с новобранцем Элрет. У нее найдется для тебя работа, которая принесет другим благо и поможет тебе развить умения.\n\nДо встречи в Подгороде.', '', '', '', '', '', 'Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.', 19865);
INSERT INTO `quest_template_locale` VALUES (31150, 'ruRU', 'Изящная руна', 'Изучите изящную руну и поговорите с Ло в Холодной долине.', '$n, меня попросили передать тебе вот эту руну. Изучи ее, когда будет времечко. Думаю, ее прислал наш гость издалека, Ло. Взгляни на нее и отыщи его в Старой Наковальне.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31151, 'ruRU', 'Бей, снова бей, разум всего сильней!', 'Достигните 3-го уровня, чтобы изучить прием \"Лапа тигра\", а затем испытайте этот прием на одном из тренировочных манекенов рядом с входом в Старую Наковальню.', 'Правда в том, что у тебя уже есть талант и способности, чтобы изучить необходимое. Как я могу помочь тебе? Показать, как правильно применить твои таланты.\n\nСначала тебе нужно тренироваться до тех пор, пока ты не начнешь понимать суть новой техники. И первой техникой, которую ты выучишь, будет \"Лапа тигра\". Вперед, тренируйся, пока не откроешь свой внутренний потенциал, а затем оттачивай новый прием!\n\nПомни: разум всего сильней!', '', '', '', '', '', 'Вернитесь к Ло в Старую Наковальню.', 19865);
INSERT INTO `quest_template_locale` VALUES (31152, 'ruRU', 'Взгляд в прошлое', 'Поговорите с хранителем истории Чо у Круга Камня.', 'Минуточку. Я только соберу вещи.$b$bНе хотелось бы сейчас потерять эти записи, верно? Особенно после того, как ты за них чуть жизнью и здоровьем не $gпоплатился:поплатилась;!$b$bВот, все на месте. Отправляемся?$b$bНадо сказать, увидев, как ты $gрасправился:расправилась; с тем сауроком, я теперь не так беспокоюсь за наше путешествие!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31153, 'ruRU', 'Tracking Event: Kite 2 Unlocked', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31154, 'ruRU', 'Tracking Event: Kite 3 Unlocked', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31155, 'ruRU', 'Tracking Event: Kite 4 Unlocked', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31156, 'ruRU', 'Покрытый письменами пергамент', 'Прочтите покрытый письменами пергамент и поговорите с Гато в Долине Испытаний.', 'О, пока тебя не было, тут прислали пергамент, $n.$B$BПрочти на досуге. Если не ошибаюсь, он от нашего друга-пандарена Гато. Он прибыл издалека, чтобы поделиться мудростью и обучить нас искусству монахов. Не опозорь свой народ, достойно прояви себя на его уроках!', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31157, 'ruRU', 'Лапа тигра', 'Достигните 3-го уровня, чтобы изучить прием \"Лапа тигра\". Найдите тренировочный манекен и два раза опробуйте на нем \"Лапу тигра\".', 'Тренируясь все усерднее, ты будешь находить внутри себя силу открывать новые техники. Тебе даже не нужно учиться этому у меня или еще у какого-то более опытного монаха... увидишь, они будут открываться тебе без посторонней помощи.\n\nА пока тебе следует пойти и попрактиковаться в основах. Наберись больше опыта и освой новую технику. Как только сделаешь это, сможешь поупражняться на одном из тренировочных манекенов, чтобы как следует ее отработать.', '', '', '', '', '', 'Вернитесь к Гато в Долине Испытаний в Дуротаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (31158, 'ruRU', 'Азы мастерства: поражение цели', 'Уничтожьте 6 манекенов-тики.', 'Ну ладно, $gдружище:подруга;. Начнем с азов. Посмотрим, как ты владеешь этим своим оружьицем.$B$BПопробуй-ка разнести в щепки вон те манекены-тики. Не торопись. Делай, как получится. А я посмотрю, как ты дерешься и что с этим можно сделать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31159, 'ruRU', 'Возрождение Черного Копья', 'Встретьтесь с Забраксом на тренировочной площадке Черного Копья.', 'Племя Черного Копья долго угнетали. Мы изгнанники. Раз от раза мы покидали дома... Но этот раз мы не убегать.$B$BВол\'джин предложил возглавлять нас мудростью и благодаря тому мы живы. Та мудрость предостерегает о хаосе что будет у Орды под Гаррош Адский Крик.$B$BНет. Этот раз мы не убегать. Этот раз мы защищать дома.$B$BНужно тренироваться, $n. Ищи Забракса на востоке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31160, 'ruRU', 'Практическое занятие', 'Добудьте 6 шкур буйногривой рыси.', 'Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31161, 'ruRU', 'Яма испытаний', 'Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.', 'Ты уже многому $gнаучился:научилась;, |3-6($c). Конечно, это еще не все. Но мы больше не будем практиковаться на манекенах-тики. Просто жаль тратить время...$B$BДавай-ка испробуем твои силы на настоящем противнике. На том, кто будет биться до смерти. Иди в яму испытаний – там тебе подберут соперника. Скажи тюремщику, когда будешь $gготов:готова;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31162, 'ruRU', 'Искусство монаха', 'Достигните 3-го уровня, чтобы изучить прием \"Лапа тигра\". Потренируйтесь в использовании этого приема на манекене-тики.', 'Когда научишься драться лучше и всех вокруг раскидывать, всякие ништячные штуки будут прямо сами собой получаться.$B$BХошь посмотреть? Иди потренируйся и выучи пару новых приемов.$B$BПотом приходи, покажешь.', '', '', '', '', '', 'Вернитесь к Забраксу на тренировочную площадку Черного Копья на островах Эха.', 19865);
INSERT INTO `quest_template_locale` VALUES (31163, 'ruRU', 'Превосходя ожидания', 'Поговорите с Вол\'джином в крепости Черного Копья.', 'Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31165, 'ruRU', 'Каллиграфическая записка', 'Прочтите каллиграфическую записку и поговорите с Шоюем в Лагере Нараче.', 'Всего минуту назад тебя искала посыльная, $n! Думаю, она от нашего гостя-пандарена Шоюя. Тебе следует прочитать это.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31166, 'ruRU', 'Лапа тигра', 'Достигните 3-го уровня, чтобы изучить прием \"Лапа тигра\". Найдите тренировочный манекен в Лагере Нараче и отработайте этот прием.', 'У тебя все хорошо получилось. Ты будешь продвигаться по этому пути и развиваться, овладевая новыми навыками, о которых раньше не $gмог:могла; и мечтать.\n\nТвой первый урок – сила опыта. Иди, изучи новую способность и продемонстрируй ее мне.', '', '', '', '', '', 'Вернитесь к Шоюю в лагерь Нараче.', 19865);
INSERT INTO `quest_template_locale` VALUES (31167, 'ruRU', 'Фамильное древо', 'Зажгите связку благовоний в Круге Камня.', 'Итак, теперь ты знаешь о этом, $gстранник:странница;. По крайней мере, достаточно для первого знакомства, не так ли?$b$bНу, а ты? Твой народ сильно отличается от моего?$b$bУ нас непременно должно быть что-то общее. Давай-ка посмотрим...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31168, 'ruRU', 'Покрытый письменами знак', 'Поговорите с Лаоси в Альдрассиле, что в Тенистой долине.', 'Этот знак передал мне посланец нашего гостя-пандарена, Лаоси. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и затем отправляйся с ним к Лаоси.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31169, 'ruRU', 'Искусство монахов', 'Достигните 3-го уровня, чтобы изучить прием \"Лапа тигра\". Поищите тренировочный манекен и попрактикуйтесь в использовании этого приема на нем.', 'Истинный секрет искусства монаха заключается в том, чтобы открывать внутри себя знания и силу.$B$BИди, набирайся опыта и учи новые умения. Затем покажи их на одном из тренировочных манекенов.', '', '', '', '', '', 'Вернитесь к Лаоси на Тельдрассил.', 19865);
INSERT INTO `quest_template_locale` VALUES (31170, 'ruRU', 'Наставник монахов', 'Поговорите с Пао, наставником монахов, в Солнечном Шпиле на Острове Солнечного Скитальца.', 'По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных монахов на Острове Солнечного Скитальца тренирует Пао, наша гостья-пандарен. Поговори с ней, может быть, она сможет тебя чему-нибудь научить.$B$BПао, как и все наставники Острова Солнечного Скитальца, находится в нижней части Солнечного Шпиля.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31171, 'ruRU', 'Лапа тигра', 'Достигните 3-го уровня, чтобы изучить прием \"Лапа тигра\". Найдите тренировочный манекен рядом с Солнечным Шпилем и отработайте этот прием.', 'Хорошо. Тебя ждет яркое начало пути. Дорога будет долгой, и, чем большего ты сможешь достигнуть, тем проще будут даваться умения, о которых ты раньше даже не $gмечтал:мечтала;.$B$BИди, получи новый опыт и изучи новую технику. Затем продемонстрируй ее на одном из тренировочных манекенов.', '', '', '', '', '', 'Вернитесь к Pao на Солнечный Шпиль на Остров Солнечного Скитальца.', 19865);
INSERT INTO `quest_template_locale` VALUES (31173, 'ruRU', 'Лапа тигра', 'Достигните 3-го уровня, чтобы изучить прием \"Лапа тигра\". Разыщите тренировочный манекен на северо-западной стороне места крушения и потренируйтесь на нем.', 'Надеюсь, вы там в порядке... Крушение было ужасным: грохот, все рушится!\n\n<Моцзо осматривает тебя, оценивая твой потенциал.>\n\nДа, ты подойдешь. Они сказали, что им нужно больше тех, кто будет сражаться, и они не хотят, чтобы я поранился. Я-то не боюсь, но мешать им не хочу, так что обучу тебя.\n\nКак ты уже, может быть, $gзаметил:заметила;, полученный боевой опыт раскрывает новые грани твоих талантов. Вперед, попробуй овладеть новой способностью. Покажи мне, что ты можешь. Так ты поймешь, что к чему.', '', '', '', '', '', 'Вернитесь к Моцзо Буйному Портеру на место крушения.', 19865);
INSERT INTO `quest_template_locale` VALUES (31174, 'ruRU', 'Озеро Звезд', 'Убейте 12 порабощенных янтароискателей или вос\'тик-надсмотрщиков. Освободите Корвена Первейшего.', 'Обнаружен еще один Идеал.$B$BНа этот раз он в Озере Звезд, это древнее озеро на юге.$B$BПопасть туда будет непросто, путь преграждают враги.$B$BЯ поручаю это тебе. Справишься – останешься в живых.$B$BПровалишь задание – отправлю еще кого-нибудь.', '', '', '', '', '', 'Поговорите с Корвеном Первейшим у Озера Звезд, что в Жутких пустошах.', 19865);
INSERT INTO `quest_template_locale` VALUES (31175, 'ruRU', 'Скир Кровожадный', 'Пробудите Скира Кровожадного в подводной пещере.', 'Хорошо, что мы захватили отмели, прежде чем двигаться к Зан\'весс.$B$BМы обнаружили еще один Идеал, заключенный под водой в янтаре к юго-западу отсюда.$B$BНам совершенно необходимо заручиться его помощью. Вполне возможно, этот воитель из прошлого решит исход битвы в нашу пользу.$B$BЯ не прочь отправиться за ним немедленно, но обязанности не позволяют.$B$BРаз уж ты $gстал:стала; Пробудителем, то сможешь выполнить эту задачу вместо меня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31176, 'ruRU', 'Странный аппетит', 'Соберите 12 кусочков мяса морских звезд.', 'Еда. Мне нужна еда.$B$BВ мои времена мясо морских звезд придавало силы и очищало разум. Вот что я хочу съесть.$B$BПринеси мне звезд с отмелей неподалеку.$B$BЕсли будешь мешкать, я сожру тебя взамен.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31177, 'ruRU', 'Хороший обед', 'Соберите 8 хвостов трещотов.', 'Пока я был жив, то считался величайшим воином роя.$B$BПомоги мне восстановить силы, и я покажу тебе, на что способен.$B$BЯ чувствую солоноватый запах моря. А где море, там морские трещоты.$B$BПринеси мне их питательные хвосты. Они должны утолить мой голод.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31178, 'ruRU', 'Кровавое удовольствие', 'Соберите 100 капель неустойчивой крови ужасающих прилипал.', 'Пока воин не попробовал крови своих врагов, толку от него в бою немного.$B$BЯ еще слишком слаб, чтобы охотиться, так что этим придется заняться тебе.$B$BМне нужна кровь лишь самых свирепых хищников. Я чую их присутствие в водах за стенами этой пещеры.$B$BДобудь мне их крови, и поймешь, почему меня прозвали Кровожадным.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31179, 'ruRU', 'Запах крови', 'Убейте 12 поедаталей плоти и змейников из племени Грязной Чешуи.', 'Пришлось запачкать руки кровью сауроков, пока тебя не было.$B$BИзвини, не удержался. Смотри, как тщетны их нападки!$B$BНичтожества!$B$BНеужто хотят отомстить за убитых и бросить вызов мне? Мне?!$B$BНе я ли победил в сотне войн? Не я ли бился с тысячей врагов и победил?$B$BА этих... сауроков... я раздавлю, как скорлупу молотом!$B$BУзри мою мощь, Пробудитель! Давай сразимся с ними!$B$BСауроки не пройдут!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31181, 'ruRU', 'Свежие горшки', 'Разложите наживку в 10 пустых ловушек для крабов в Одинокой бухте. Для каждой ловушки требуется 2 куска мяса морского монарха.', 'У нас тут полно пустых крабьих горшков и нам для них нужна свежая наживка.$B$BДумаешь, мы их вытащим сюда по одному и будем не торопясь наполнять? Сидя в кресле, чаек попивая? Мечта, не работа...$B$BТак вот, не дождешься.$B$BДавай-ка, отправляйся в Одинокую бухту, это на юго-западе, и разложи в горшки наживку из двух свежих морских монархов. Свежих – это значит, убитых там же, прямо в воде.$B$BА, да, \"горшками\" у нас называют ловушки. Хочешь сработаться с ребятами, учи жаргон.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31182, 'ruRU', 'Кто выдрал наживку из горшка?', 'Накормите из мешка с моллюсками 8 хладноусых выдр из Одинокой бухты.', 'Знаешь, что случилось с наживкой в горшках?$B$BВыдры, вот что.$B$BОни обычно свежих моллюсков жрут, но с голодухи могут и крабьи ловушки очистить.$B$BВ Одинокой бухте выдры охраняются законом, а мы тут вполне легально. Так что грохать этих водных крыс мы не будем, как бы ни хотелось. Надо им жратвы подкинуть, чтоб они на ловушки наши уж и глядеть не хотели.$B$BДай им моллюсков, пусть лопают, пока ты там будешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31183, 'ruRU', 'Встреча с капитаном', 'Поговорите с \"Мокрым\" Су-Дао в Приюте капитана.', 'Ладушки, $p, у меня для тебя новая работенка.$B$BВидишь тюльва в том загончике? Его зовут Пес. Он любимчик Мокрого уже много лет.$B$BВ последнее время Пес неспокоен – кажется, ему надоело сидеть в загоне. Поговори с Мокрым и расскажи ему это.$B$BТебе все равно пора уже встретиться с капитаном.', '', '', '', '', '', 'Поговорите с \"Мокрым\" Су-Дао в Приюте капитана.', 25549);
INSERT INTO `quest_template_locale` VALUES (31184, 'ruRU', 'Старость и предательство', 'Отыщите договор фрахтования среди обломков \"Туманного Кузнечика\".', 'Слушай, у меня нет причин тебе доверять, но есть задание, которое я не могу поручить своей команде.$B$BЯ хочу, чтобы ты $gобыскал:обыскала; место крушения нашего старого корабля, \"Туманного кузнечика\", и $gпринес:принесла; договор фрахтования. Он в серебряном футляре, в cундуке.$B$BОн немного... э-э... инкриминирующий. Не могу рисковать, чтобы моя команда его нашла, если вдруг вздумает наведаться на старичка. \"Кузнечик\" покоится на шельфе Мацзу, на западе.$B$BСоветую добраться туда на подводном течении, если желудок не шалит. Они там по всему шельфу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31185, 'ruRU', 'Выгулять Пса', 'Прогуляйтесь вместе с псом к горячим гейзерам, трупу кита и обломкам \"Туманного Кузнечика\" на шельфе Мацзу.', 'Пес – не мой \"питомец\", а член команды и мой лучший друг. Не раз спасал мне жизнь.$B$BНо я уже староват, чтобы гулять с ним, а ему надо размяться. Отведи его на прогулку, хорошо?$B$BОн любит плавать вокруг горячих гейзеров к северо-востоку от отмелей.$B$BЕму совершенно необходимо... э-э... \"отметиться\" на дохлом ките, который находится далеко на западе побережья.$B$BА, и еще он захочет заглянуть на место нашего старого крушения. Он любит воспоминания.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31186, 'ruRU', 'Накормить Пса', 'Помогите Псу полакомиться останками 10 твердопанцирных клешнехватов.', '<Пес скулит так, как только может тюлев, с трудом поднося ласт к массивным челюстям.$B$BОн голоден.$B$BШельф Мацзу покрыт твердопанцирными макрурами, которые должны прийтись ему по вкусу.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31187, 'ruRU', 'Крабы', 'Прицепите буй \"Туманного Кузнечика\" к 8 ловушкам с крабами на шельфе Мацзу.', 'Говорят, что горшки, которые мы опустили утром на дно, битком набиты крабами!$B$BПроблема в том, что течения усилились, и часть горшков потерялась. И теперь они, до краев полные колючего синего золота, валяются неизвестно где!$B$BТы мне $gнужен:нужна;, чтобы их вернуть. Прицепи эти буйки ко всем полным ловушкам, которые найдешь, и отпусти их на поверхность – мы их подберем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31188, 'ruRU', 'Неделя акулы', 'Соберите 200 зубов крепкозуба, выдирая их из челюстей длинноплавниковых крепкозубов на шельфе Мацзу.', 'Конечно, основной доход у нас с крабов, но мы отсылаем за стену и много всего другого. Масла, растения, даже редкие минералы – море в этих краях щедрое.$B$BА сейчас начался бум на зубы крепкозуба. Похоже, из них получаются отличные ожерелья.$B$BВ западной части шельфа Мацзу водится много крепкозубов. А мне нужно много зубов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31189, 'ruRU', 'Ловля на живца', 'Помогите опытному рыболову Цзюй Лэню, его можно найти в Приюте капитана.', 'Просто не верится, первый раз за... первый раз в жизни опытный рыболов Цзюй Лэнь попросил помочь ему со снастями.$B$BМоре сегодня неспокойное, он не справляется. Может, ты сможешь ему помочь? Он рыбачит к югу отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31190, 'ruRU', 'Месть моряка', 'Спустите на воду \"малого\" \"Туманного Кузнечика\" на причале в Приюте капитана и уничтожьте Цзяо.', 'Я не собираюсь сидеть в этой качалке, пока мою команду пожирает левиафан!$B$BПойдем, надо добраться до причала и спустить на воду шлюпку. Я приберег одну как раз для таких случаев. Мой собственный \"малый\" \"Туманный Кузнечик\".$B$BПокажем этой твари, что такое гарпунная лихорадка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31194, 'ruRU', 'Проблемы со Скользкой Чешуей', 'Убейте чешуйчатого повелителя из клана Скользкой Чешуи.', 'Приказы клану Скользкой Чешуи отдает его новый глава, чешуйчатый повелитель. Сейчас он празднует свои победы в юго-восточной части Наветренного острова.$B$BУничтожив его, мы нанесем их племени чувствительный удар.$B$BБез своего повелителя клан дважды подумает, прежде чем снова нападать на беззащитных облачных змеев востока.', '', 'Великая опасность ожидает.', 'Чешуйчатый повелитель из клана Скользкой Чешуи', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31195, 'ruRU', 'Заукать дукера', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31196, 'ruRU', 'Мокрое дело на Шра\'весс', 'Убейте 15 обычных богомолов около острова Шра\'весс.', 'Богомолы во много раз превосходят нас числом. Их сотни на каждого из нас.\n\nИ они наступают с двух сторон – на юге, на Заставе Гао-Жаня, нам пока удается их сдерживать, но на западе, на острове Шра\'весс, мы ничего не можем сделать.\n\nМы не самоубийцы и не собираемся идти в лобовую атаку. Битвы на несколько фронтов нам не выдержать.\n\nМы пошлем туда тебя и кого-нибудь из У Као, вас ждет грязная работенка. Как тебе этот план?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31197, 'ruRU', 'Чем они больше...', 'Убейте 4 элитных богомолов на острове Шра\'весс.', 'Убийство богомолов поменьше – это скорее отвлекающий маневр, им приходится пополнять свои войска, даже если серьезного урона они не понесли.\n\nБольшие богомолы – совсем другое дело, стоит убить несколько штук, и мы надолго задержим их продвижение на острове. Видимо, в империи их ценят в зависимости от размеров.\n\nТак что, будь так $gдобр:добра; убей несколько богомолов покрупнее.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31198, 'ruRU', 'Моральная победа', 'Уничтожьте южного, центрального, восточного и западного идолов на острове Шра\'весс.', 'У богомолов на острове Шра\'весс есть статуи, которые они используют... Кто знает, зачем они их используют. Может, они им поклоняются, или переговариваются с их помощью.\n\nВрага надо уничтожать не только физически, но и морально! Не знаю, как там все устроено у этих богомолов, но статуи явно как-то им помогают.\n\nПоэтому надо, чтобы ты их $gвзорвал:взорвала;. Это сильно подорвет их боевой дух.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31199, 'ruRU', 'Уничтожить осадные орудия!', 'Уничтожьте четыре осадных орудия богомолов на острове Шра\'весс в Танлунских степях.', 'Богомолы берут не только числом.\n\nОни умны. У них на службе алхимия, бомбы... и что хуже всего, осадные орудия. Это очень серьезная угроза.\n\nРазведчики сообщили, что богомолы строят осадные орудия в западной части острова Шра\'весс. Уничтожь их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31200, 'ruRU', 'Выкуривание', 'Установите газовые бомбы Шадо-Пан на 5 указанных объектах в Шра\'весс.', 'Наши алхимики создали газовые бомбы, которые быстро отгонят богомолов от любого нужного места.\n\nЕсли забросать ими ключевые здания на острове Шра\'весс, начнется эвакуация и паника. Это задержит богомолов на несколько дней.\n\nЗаймись этим, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31201, 'ruRU', 'Друзья – не еда!', 'Спасите учеников Шадо-Пан из северной, центральной и южной кормовых ям куньчунов.', 'Разведчики принесли плохие новости.\n\nНедавно пропали трое из учеников, и теперь понятно, куда....\n\nБогомолы взяли их в плен и отвели к ямам куньчунов.\n\nК их кормовым ямам. Хорошо еще, что куньчуны едят довольно редко.\n\nТебе нужно будет пробраться туда и раздать пленникам воздушных змеев, чтобы они могли сбежать.', '', '', '', '', '', 'Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (31203, 'ruRU', 'Попутная цель: шра\'тик – повелитель роя', 'Убейте шра\'тика – повелителя роя в Шра\'весс, что в Танлунских степях.', 'Раз уж мы здесь, надо сделать еще кое-что.\n\nШра\'тик – повелитель роя направляет атаки богомолов с воздуха. Если мы оставим его в живых, он изрядно потреплет весь наш гарнизон.\n\nТак что предлагаю в живых его не оставлять. Действуй, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31204, 'ruRU', 'Попутная цель: шра\'тик – повелитель улья', 'Убейте шра\'тика – повелителя улья.', 'У океана на востоке Шра\'весс есть пещера, которая переходит в лабиринт других пещер.\n\nОттуда шра\'тик – повелитель улья управляет Шра\'весс и строит козни против нас. Если мы убьем его, вражеское войско надолго останется обезглавленным.\n\nПриступим же.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31205, 'ruRU', 'Lorewalker Cho Tracking Quest', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31206, 'ruRU', 'Горнило Крови: боец из клана Кровавого Глаза!', 'Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!', 'Да, я не спорю. Этот край – то еще место, уж никак не Награнд и даже не Зул\'Драк, но знаешь, $gдружище:подруга;, я тебе вот что скажу: я просто двигаю туда, где можно заработать! Поэтому – добро пожаловать на Сумеречное нагорье!$B$BТы тут новичок, и я тебе объясню в двух словах, что здесь и как. Я организатор боев, этот сварливый тролль – мой телохранитель Водин. Ну а ты, стало быть, боец на потеху почтеннейшей публике. У нас тут все по желанию. Захочешь сражаться – собери друзей и скажи мне, а уж у меня найдутся для вас достойные противники.$B$BМожно и прямо сейчас, если хочешь. Ну что, будешь сражаться?', 'Хурп\'дерп побежден', 'Хурп\'дерп побежден', 'Хурп\'дерп', 'Правая рука Гурга.', 'Водин', 'Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.', 19865);
INSERT INTO `quest_template_locale` VALUES (31207, 'ruRU', 'Арена Истребления', 'Выйдите на Арену Истребления и выполните все предложенные задания. Не забудьте забрать свою награду у тролля-прислужника Водина.', 'Эх, я все еще помню бои, которые мы проводили в этой грязной дыре, в Награнде. Много воды утекло, а, Водин?$B$BЭти монахи из Храма Тигра ценят хорошую драку, точно говорю. Они неплохо заплатили мне, чтобы я обосновался здесь и помогал отбирать лучших бойцов!$B$BНу так что? Выйдешь с парой друзей на Арену Истребления? Это неплохие деньги, кстати.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31208, 'ruRU', 'Ядовитый умысел', 'Соберите 8 ядовитых жал.', 'Если хотим одержать верх над императрицей, нужно как следует вооружиться. Себе в качестве оружия я подобрал кое-что особо ядовитое.$B$BЖелезы скорпионов, обитающих на выступе, вырабатывают смертельный яд.$B$BПринеси мне жала этих скорпионов, и я покажу тебе, за что меня прозвали Идеалом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31209, 'ruRU', 'Черные крылья, черные дела', 'Соберите 150 крыльев скарабея.', 'Для моего первого яда понадобится еще один ингредиент, Пробудитель.$B$BТебе придется отыскать поблизости скарабеев.$B$BУбей их и принеси мне крылья.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31210, 'ruRU', 'Жуткоцвет', 'Соберите 8 жуткоцветов.', 'Последний ингредиент – пожалуй, самый опасный.$B$BЖуткоцвет растет на здешних холмах.$B$BИменно поедая эти токсичные растения, местная фауна стала столь ядовитой.$B$BОдна капля нектара жуткоцвета может убить куньчуна.$B$BПринеси мне эти цветы. И не пытайся их попробовать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31211, 'ruRU', 'Отравленный разум', 'Поговорите с Ксарилом Отравленный Разум. Убейте 200 богомолов и 3 кунчунов, пока летите вместе с ним.', 'Прежде чем мы вернемся в Клакси\'весс, мне хотелось бы увидеть, что стало с империей.$B$BСовет клакси поведал мне, что противник стянул силы к вратам дворца императрицы.$B$BЯ, наконец, приготовил яды. Смерть и разрушения станут прекрасными глашатаями моего возвращения!$B$BСмотри внимательнее, чтобы сыворотки не смешивались! По крайней мере, пока ты держишь сосуды в руках.$B$BПоговори со мной, когда подготовишься к полету.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31212, 'ruRU', 'FLAG - Chose Tenwu', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31213, 'ruRU', 'FLAG - Chose Taoshi', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31214, 'ruRU', 'FLAG - Chose Nurong', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31216, 'ruRU', 'Темные небеса', 'Убейте 200 богомолов и 3 кунчунов или ужасающих чудищ, пока вас несет по воздуху Ксарил Отравленный Разум.', 'Рой готовится к атаке, Пробудитель! Богомолы стягивают силы к Сердцу Страха.$B$BИх крылья уже затмили свет солнца, а ноги взрыли почву. Они остановятся лишь тогда, когда их окровавленные бездыханные тела упадут на землю.$B$BА мы с радостью поможем этому осуществиться. Я понесу нас по небу, а ты отравляй их моими ядами.$B$BНе смешивай сыворотки, пока не наступит удачный момент для атаки. Химическая реакция может оказаться весьма... бурной.$B$BПоговори со мной, когда подготовишься к полету.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31218, 'ruRU', 'FLAG - Unlocked Tenwu', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31219, 'ruRU', 'FLAG - Unlocked Nurong', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31220, 'ruRU', 'Бойцовский круг: повелитель ястребов Нужун', 'Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, повелителя ястребов Нужуна и победите его.', 'Среди Шадо-Панов ты слывешь хорошим бойцом, $n.\n\nНужун хочет проверить свои силы и сразиться с тобой.\n\nХорошая новость: если ты победишь, я позволю ему помогать тебе.\n\nПлохая новость: сомневаюсь, что ты победишь.', '', 'Смертельно опасный У Као всегда путешествует со своим любимым ястребом по имени Белоснежное Перо.', 'Повелитель ястребов Нужун', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31221, 'ruRU', 'Бойцовский круг: Тэнь-у Красный Дым', 'Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, Тэнь-у Красного Дыма и победите его.', 'Итак, тебе бросил вызов печально известный Тэнь-у Красный Дым.\n\nОн сам себя так зовет. Это хороший боец, и разбойник отменный, но сколько он хвастается и бахвалится, это уму непостижимо.\n\nВ общем, тебе стоит принять вызов. Может, это его чему-нибудь научит. А может, и нет. В любом случае, если ты победишь его, он будет стремиться помогать тебе в твоих поручениях.\n\nНу и мне какое-то развлечение.', '', '', 'Тэнь-у Красный Дым', '', '', 'Вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (31228, 'ruRU', 'Пророк Хар\'зул', 'Победите пророка Хар\'зула.', 'Пророк Хар\'зул – опытный заклинатель, но тебя он недооценивает.$B$BРади защиты этой деревни Хар\'зула и его приспешников нужно убить. Его смерть даст понять Властелину Грома, что мы не отступим!$B$BТы найдешь его на острове Расплаты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31230, 'ruRU', 'Добро пожаловать в Цветущую Зарю!', 'Поговорите с Каем Бродячим Бражником, мастером Воздушный Мех и Пэйцзи Золотистый Нектар в Цветущей Заре.', 'Чо снова отправился на поиски приключений, а у меня тут заказ на большую партию нефрита. Обращусь за помощью к знакомым.$b$bА ты пока познакомься с местными.$b$bКай Бродячий Бражник – отличный собеседник, как и мастер Воздушный Мех. Кстати, зайди в таверну и передай привет Пэйцзи Золотистый Нектар.$b$bПоговори с этими тремя и узнаешь, чем живет Цветущая Заря.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31231, 'ruRU', 'Истребление страхопрядов', 'Убейте 8 страхопрядов-охранников на террасе Гуртани. Поговорите с Кил\'руком Рассекающим Ветер для выброски с воздуха.', 'На террасе Гуртани, где ты меня $gнашел:нашла;, лучникам Шадо-Пан приходится все время следить за страхопрядами, вместо того чтобы сосредоточиться на рое.$B$BУничтожь этих пауков, пусть стрелки хоть немного передохнут.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31232, 'ruRU', 'Древняя империя', 'Соберите 8 скрижалей Гуртани.', 'Мои братья говорят о древней империи могу, развалины которой еще можно увидеть на востоке.$B$BКогда-то могу владели тайнами колдовства и порабощало непокорных.$B$BМне свойственно любопытство, Пробудитель. Я желаю знать, что за империи были после меня.$B$BЗнание прошлого помогает постичь будущее.$B$BРазыщи же в руинах древние скрижали, дабы мне открылись тайные знания.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31233, 'ruRU', 'Сбор смолы', 'Соберите 6 образцов янтарной смолы.', 'Я нашел рощу молодых янтарных деревьев к востоку отсюда, Пробудитель.$B$BЯ поместил там емкости для сбора смолы, но у меня не было времени добыть его оттуда.$B$BМне нужно, чтобы кто-то нашел экстракторы. Активируй их и принеси мне образцы янтаря.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31234, 'ruRU', 'Выколоть глаз', 'Добудьте 1 безупречный глаз болотного чудища.', 'Ах! Пробудитель! Ты $gдолжен:должна; помочь мне! (Ты поможешь мне, или же $gсам:сама; станешь материалом!)$B$BМне нужно больше материалов для экспериментов, да-да! (Кровь и кишки, сердца и мозги, языки и глаза, глаза, глаза!)$B$BК западу отсюда я видел существ, сделанных из тумана. У них такие чудесные, большие, круглые глазные яблоки! Они хорошо видят и не мигают!$B$BИди же, Пробудитель. Принеси мне безупречный глаз!', '', '', '', '', '', 'Вернитесь к Рик\'калу Разрезателю в Клакси\'весс в Жуткие пустоши.', 19865);
INSERT INTO `quest_template_locale` VALUES (31235, 'ruRU', 'Нет-нет-нет', 'C помощью драконьего ружья Шадо-Пан уничтожьте 20 яиц страхопрядов на террасе Гуртани.', 'Последняя разведка в окрестностях стен принесла мне это ружье. С его помощью можно помочь твоим шадо-панам справиться с тем, что у них творится на террасе Гуртани.$B$BУ них столько сил уходит на пауков, что совсем не остается времени сражаться с роерожденными.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31237, 'ruRU', 'Борьба с насекомыми', 'Растопчите 6 Очей Императрицы на террасе Гуртан. Убийство любого существа позволит вам отслеживать феромоны и поможет их обнаружить.', 'Если императрица действительно страдает от паранойи, она пошлет разведчиков во все концы своей страны, чтобы укрепить свою власть.$B$BЭти личинки могут быть повсюду, но их сложно заметить невооруженным глазом. Лучше всего отслеживать их по следам феромонов, которые они оставляют за собой.$B$BЯ уже подарил тебе... реактивный яд, который ненадолго откроет тебе эти следы после того, как ты испытаешь радость от победы.$B$BОтправляйся на террасу Гуртан и вылови этих шпионов.', '', '', '', '', '', 'Вернитесь к Хисеку Хранителю Роя в Клакси\'весс.', 19865);
INSERT INTO `quest_template_locale` VALUES (31238, 'ruRU', 'Пища для мозгов', 'Принесите 4 языка мушана Каз\'тику Манипулятору в Клакси\'весс.', 'Ковок растет с огромной скоростью, его мозг может с этим не справиться. Ему нужна специальная диета, иначе он рискует утратить контроль над собственным телом.$B$BЯзык мушана богат питательными веществами, которые способствуют росту мозга у куньчунов, но если есть мушанов целиком, много не влезет. А вот если каждые пару дней кормить Ковока только языком мушана, то мозг будет успевать за ростом тела.$B$BШирокоспинные мушаны пасутся на холмах к востоку отсюда, около террасы Гуртани.', '', '', '', '', '', 'Вернитесь к Каз\'тику Манипулятору в Клакси\'весс.', 19865);
INSERT INTO `quest_template_locale` VALUES (31239, 'ruRU', 'Что тебе в имени-имени моем?', 'Уничтожьте 7 приречных цзинь-юй.', 'Значит, хочешь быть хозеном, шнуропс?$b$bХозены защищай свои земли от врагов, как цзинь-юй.$b$bКах-Ках раньше драться часто с цзинь-юй и побеждать всегда.$b$bХозен давай имя-имя только хороший грокер. Иди грокай цзинь-юй, и когда-нибудь тебя назвать $n-$n.$b$bЦзинь-юй ползай у реки. Бацай их по дукерам!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31241, 'ruRU', 'Гадкие шнуропсы', 'Соберите 6 медальонов воинов Альянса у закаленных в боях парашютистов.', 'Они говорить, $n – добрый шнуропс...$b$bОни говорить, $n помогай хозенам...$b$bОни говорить, не надо больше грокать, $n.$b$bХорошо. Смотри сюда – гадкие шнуропсы падать, как дождь, их грокать в самый раз!$b$bТвоя иди, веселись! Но только чтоб все блестяшки Ках-Ках! Это правило хозенов номер два.$b$b<Джик-Джик чешет в затылке.>$b$bХм, у хозенов все правила номер два...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31251, 'ruRU', 'Самая лучшая еда', 'Соберите 160 мясных кусочков Кунь-Лай.', 'Ну да, ну да.\n\nВсе знают, что гоблины умеют чинить и взрывать. Ну и... еще ерундой всякой заниматься.\n\nНо никто не знает, что я, например, прекрасный повар! Люблю это дело.\n\nЗдесь столько зверья водится, добудь-ка мне мяса, а я уж его приготовлю, пальчики оближешь!\n\nИ кстати, топлива уйдет всего три-четыре процента.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31252, 'ruRU', 'Обратно, в приют Западного Ветра', 'Вернитесь к батраку Бо в приют Западного Ветра на вершине Кунь-Лай.', 'Ну что ж, похоже, нам предстоит многое строить заново.\n\nЯ не любитель больших заварух, но у батраков моих, признаться, сейчас не так уж много работы. Они так благодарны тебе, что рвутся присоединиться к этому твоему Альянсу. Что ж мне, удерживать их силой?\n\nВеди их к батраку Бо. Мне будет не хватать их, но с тобой им явно лучше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31253, 'ruRU', 'Обратно в приют Восточного Ветра.', 'Вернитесь к батраку Ко в приют Восточного Ветра на вершине Кунь-Лай.', 'Ну что ж, похоже, нам предстоит многое строить заново.\n\nЯ обычно не присоединяюсь к большим заварухам, но у батраков моих, признаться, не так уж много работы сейчас. Они так благодарны тебе, что рвутся присоединиться к этой твоей Орде. Что ж мне, удерживать их силой?\n\nВеди их к батраку Ко. Мне будет не хватать моих людей, но пусть будет так.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31254, 'ruRU', 'Дорога в Кунь-Лай', 'Отправляйтесь в деревню Бинан по Сокрытой лестнице.', 'Ах! Приветствую тебя, друг хранителя истории Чо! У меня есть для тебя послание.$b$b<Необычное маленькое существо вручает вам обветшалый свиток.>$b$bХранитель истории ждет тебя на Вершине Кунь-Лай. Путь туда очень, очень опасен.$b$bИщи знаки на обочинах дорог, они помогут тебе отыскать дорогу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31255, 'ruRU', 'Дорога в Кунь-Лай', 'Отправляйтесь в деревню Бинан по Сокрытой лестнице.', 'Ах! Приветствую тебя, друг хранителя истории Чо! У меня есть для тебя послание.$b$b<Необычное маленькое существо вручает вам обветшалый свиток.>$b$bХранитель истории ждет тебя на Вершине Кунь-Лай. Путь туда очень, очень опасен.$b$bИщи знаки на обочинах дорог, они помогут тебе отыскать дорогу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31256, 'ruRU', 'Отлов яков', 'Поймайте 3 диких яков равнин и отведите их в приют Восточного Ветра.', 'Лок\'тар, |3-6($c).\n\nНаши дела неплохи, но необходимо повысить мобильность войск, чтобы укрепить наше положение в Кунь-Лай.\n\nВоргов и кодоев в окрестностях немного, зато я видел яков. Наши союзники, пандарены, утверждают, что из них получаются хорошие ездовые животные, доверимся их совету.\n\nСобери несколько яков и пригони сюда, мы начнем их объезжать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31260, 'ruRU', 'Охота за наживой: Чашин', 'Добудьте кровь старой тигрицы.', 'Я замыслила еще одну великую аферу!$b$bПока я летела, я видела очень старую тигрицу, которая рыскала неподалеку.$b$bЗнаешь, сколько ее кровь будет стоить на черном рынке? Особенно если мне удастся убедить чернокнижников, что она усилит их заклятья призыва или что-то еще.$b$bПринеси мне немного ее крови, и я возьму тебя в долю. Она рыскала на дальнем берегу реки Доцзян.', '', 'Королева Диких зарослей', 'Чашин', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31261, 'ruRU', 'Голова капитана Джека', 'Отнесите голову капитана Джека вождю Ках-Каху, который находится на холме Грукин.', 'Пока вы изучаете с таким трудом добытый трофей, из головы капитана Джека вытекает кровь и таинственным образом впитывается в землю.$b$bСтранно, однако расследовать это нет времени. У вас слишком много работы.$b$bВождь ваших новых союзников, несомненно, обрадуется, узнав о том, как ловко вы умеете грокать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31262, 'ruRU', 'Охота на журавля: иглоклюв', 'Добудьте иглоклюв.', 'Теперь, когда ты получил представление о том, как журавли сражаются, у меня для тебя есть нечто сногсшибательное.$b$bИглоклюв!$b$bНу, я его так называю. Самый здоровенный журавль из виденных мной. Его клюв острый как меч.$b$bК северо-западу отсюда есть большой водопад у реки Доцзян. Иглоклюв любит там бывать.$b$bПринеси мне его клюв в качестве трофея, и я отблагодарю тебя по-эрнестуэйски.', '', 'Повелитель стаи', 'Иглоклюв', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31265, 'ruRU', 'Дыхание Мацзу', 'Выпейте зелье \"Дыхание Мацзу\".', 'Хочешь помочь? Что ж, начнем с самого начала.$B$B<Ари шарит по карманам, а затем достает маленький флакон с синей светящейся жидкостью.>$B$BВот оно! \"Дыхание Мацзу.\" Собственное изобретение капитана.$B$BЧто? Ты $gдумал:думала;, что я отправлю тебя в море, не позаботившись, чем тебе дышать? Мне нужны матросы, а не трупы!$B$BЗабирай его, салага. С его помощью ты сможешь победить на побережье.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31266, 'ruRU', 'Набеги могу', 'Найдите и убейте шпиона Шань\'цзэ.', 'Мы слышали донесения о нескольких группах могу, проникших на берег здесь, в Танлуне. Понятия не имею, что они тут делают, да мне и, честно говоря, все равно.\n\nНа тебя, похоже, можно положиться, так что мы решили дать это задание именно тебе.\n\nВот что предстоит сделать: иди, найди и убей их.\n\nНаши разведчики доложили, что первая группа высадилась на севере, на полпути отсюда до плато Толкователя Мертвых. Так что иди и расправься с ними.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31267, 'ruRU', 'Уничтожение клана Туманного Клинка', 'Убейте 6 раздирателей из клана Туманного Клинка.', 'Корвен рассказал мне о своих изысканиях. Оказывается, глубоко под Озером Звезд расположены гигантские залежи янтаря.$B$BК несчастью, на берегу озера проживает враждебное племя сауроков, которые считают весь янтарь своим.$B$BОни не позволят нам попасть туда.$B$BОтправляйся на юг к озеру и убей сауроков из клана Туманного Клинка, чтобы мы смогли начать безопасную добычу янтаря.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31268, 'ruRU', 'Работа мысли', 'Соберите 3 покрытых янтарем мозга с тел ик\'тиков-янтарожалов.', 'Далеко на юге в болотах рождаются орудия разрушения – огромные, почти неуничтожимые янтарные скорпионы.$B$BКак и все создания, они подвержены гипнозу, но в отличие от остальных, еще не подчинились моему разуму.$B$BПохоже, чтобы я смог получить власть над ними, потребуются дополнительные исследования.$B$BМне надо изучить их мозг. Добудь для меня несколько экземпляров этих существ.$B$BВозьми звуковой излучатель. Он весьма эффективен против этих тварей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31269, 'ruRU', 'Чешуйчатый повелитель', 'Убейте чешуйчатого повелителя из клана Туманного Клинка.', 'Сауроки у Озера Звезд подчиняются лютому и злобному чешуйчатому повелителю, а он свои земли защищает яростно.$B$BЕсли бы нам удалось прикончить их вожака, то мы бы с легкостью завладели залежами янтаря под водами озера.$B$BИди же! Жилище главаря сауроков находится под землей у южного берега озера. Оттуда он и руководит своими соплеменниками.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31270, 'ruRU', 'Схватка со страхом', 'Убейте 15 мерзкочешуйчатых скорпидов.', 'После того как присутствие ша в Кипари Зар стало очевидным, мне хотелось верить, что нам удастся избавиться от скверны.$B$BК несчастью, Совет клакси подтвердил, что скверна укоренилась глубоко и продолжает распространяться.$B$BК югу отсюда я видел животных, измененных до неузнаваемости ужасной темной силой.$B$BШа превращают свои жертвы во что-то неописуемо жуткое.$B$BМы должны помешать распространению этой скверны. Выследи запятнанных ша мерзкочешуйчатых скорпидов и убей их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31271, 'ruRU', 'Дурные гены', 'Убейте 3 ик\'тиков-скрещивателей и 6 ик\'тиков – смотрителей яиц.', 'Далеко на юге, Пробудитель, скрещиватели императрицы проводят свои черные эксперименты. (Черные, но мои чернее!)$B$BОни препарируют местную фауну и вызывают у нее мутации, создавая существ по своим разработкам. (Разработкам, которые станут моими!)$B$BНельзя, чтобы они добились своего! (Нет, нет! Только мне может быть подвластна такая сила!)$B$BИх мутанты уже используются на войне. Иди и уничтожь их, во что бы то ни стало!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31272, 'ruRU', 'Заражение', 'Убейте 6 зараженных тварей. Заражены могут быть костепылые мотыльки, синешкурые мушаны и мутирующие скорпиды.', 'Скрещиватели императрицы играют в опасную игру.$B$BК югу отсюда они впрыскивают в местных существ паразитов, полных феромонов, пытаясь создать для своей армии чудовищных мутантов.$B$BОни беспечно позволили червям-паразитам сбежать и затеряться в местной экосистеме.$B$BБез контроля со стороны инфекция распространится между животными, поэтому мы должны что-то предпринять.$B$BЯ ввел тебе слабый токсин. С ним ты сможешь распознать зараженных существ.$B$BНемедленно убей всех носителей паразитов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31277, 'ruRU', 'Внезапная атака!', 'Встретьтесь с Банем Медвежьим Сердцем снаружи храма Нюцзао в Танлунских степях и остановите вторжение могу.', 'Проклятые могу!\n\nОказывается, эти шпионы просто отвлекали наше внимание! А пока мы бегали за ними, основные силы могу передвинулись к храму Нюцзао. Оскверненные змеи, повсюду полно могу... просто катастрофа!\n\nК счастью, Баню удалось пробиться – ему и храбрейшим членам нашего ордена. Если тебе удастся повторить этот подвиг, встреться с ним. Надо остановить этот кошмар!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31279, 'ruRU', 'Все, что я знаю о кулинарии', 'Доставьте письмо Суншинь Железной Лапе. Она обучает желающих на рынке Полугорья.', 'Как меня радует, что тебе понравилась моя еда. Может, тебе нужны рецепты? Если да, то тебе стоит обучиться им у опытных кулинаров на рынке Полугорья. Они научили меня всему, что я знаю о кулинарии.$b$bЕсли соберешься на рынок Полугорья, не захватишь с собой письмо для Суншинь Железной Лапы? Она была моим любимым учителем. Хочу, чтобы она знала, как я скучаю по ней.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31281, 'ruRU', 'Так ты хочешь быть поваром?', 'Научитесь готовить разрезанные персики у наставницы и принесите ей 5 порций готового блюда.', 'Хочешь стать шеф-поваром? Если будешь усердно заниматься, я помогу раскрыть твой внутренний потенциал, и неважно, что у тебя нет опыта.$b$bЕсли хочешь учиться, покажи мне, что можешь по крайней мере следовать простым инструкциям. Научись нарезать персики и покажи мне, что получается. У меня есть свежие пандаренские персики, которые я продам тебе за символическую плату.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31282, 'ruRU', 'Выслеживание Каз\'тика', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31283, 'ruRU', 'Тераморский разрушенный путь', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31284, 'ruRU', 'FLAG - Ancient Pandaren Fishing Pole', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31285, 'ruRU', 'Весенняя лодка', 'Переживите путешествие на \"Весенней лодке\".', 'Никто не путешествует через Древний проход пешком. При неосторожности можно нарваться на сауроков.$b$bВот что я тебе скажу. Мы с Яичной скорлупой собираемся плыть вверх по течению к деревне Бинан. Хочешь, подбросим?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31286, 'ruRU', 'Грабь награбленное', 'Верните 7 товаров черного рынка.', 'А, |3-6($c). Мне бы очень пригодились твои таланты.$b$bТут недалеко на конвой напала банда мародерствующих сауроков. И эти мародеры забрали кое-какие... товары, которые ее светлость мадам Гойя собиралась продать.$b$bНельзя красть у ее светлости.$b$bЕсли ты вернешь эти товары, я с удовольствием вознагражу тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31287, 'ruRU', '\"Просвещение\" сауроков', 'Победить Пальцепийцу.', 'Весенняя тропа находится под покровительством ее светлости, достопочтенной мадам Гойи.$b$bСауроки из логова клана Грозной Чешуи обязательно должны усвоить этот урок. Мы их уже предупреждали, но, к сожалению, они, похоже, отличаются очень короткой памятью.$b$bОтправляйся на северо-восток к этому логову и найди их вождя-шамана. Убей его и получишь благодарность ее светлости. Вместе с приличествующим вознаграждением.', '', 'Шаман Грозной Чешуи', 'Пальцепийца', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31288, 'ruRU', 'Исследовательский проект: династии могу', 'Раздобудьте 20 фрагментов артефакта могу.', 'А, ты любишь странствия! Очень хорошо. Я нахожусь на пороге разгадки темных секретов могу.$b$bНу, не всех, конечно. У них много темных секретов. Но я на пороге открытия по крайней мере одного из них.$b$bЕсли в странствиях тебе попадутся какие-нибудь свидетельства прошлого могу, принеси их мне, и я щедро тебя за это отблагодарю.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31291, 'ruRU', 'Открывая прошлое', 'Раскройте тайну одного артефакта Пандарии.', 'Хочешь стать $gхранителем:хранительницей; истории? Придется много копаться в прошлом и читать, а потом еще копаться в прошлом и снова читать.$b$bЯ, бывает, целыми днями таращусь на осколки вазы, пытаясь сообразить, как их соединить.$b$bМожешь попробовать. Иди и раскрой тайну одного из артефактов Пандарии, и мы будем очень благодарны, если ты расскажешь нам потом, как тебе это удалось.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31292, 'ruRU', 'FLAG - Ancient Pandaren Woodcutter', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31298, 'ruRU', 'Zouchin Village - Intro Tracking', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31299, 'ruRU', 'Shomi Ruins Tracking', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31300, 'ruRU', 'Shomi Beach Tracking', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31301, 'ruRU', 'Shomi Strand Tracking', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31302, 'ruRU', 'Путь к величию', 'Приготовьте 5 порций рисового пудинга и отдайте их Показывающей Путь.', 'Похоже, тебе удалось освоить искусство готовки. Докажи это и приготовь мне 5 мисок рисового пудинга.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31303, 'ruRU', 'Печать сломана', 'Закройте 12 трещин, чтобы изгнать Ша Сомнения.', '<Чо смотрит на вас c неверием.>$b$bЯ... я думал, что ша такой силы – это миф... Мы все так думали. Мы пугали ими детишек, чтобы они не ссорились$b$bСейчас на разговоры нет времени. Эти трещины подпитывают ша, они становятся сильнее с каждой секундой!$b$bЯ должен покопаться в моих семейных архивах. А ты возьми эту пушку и иди к Миши.$b$bНадо найти способ сдержать ша, пока он не распоясался окончательно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31304, 'ruRU', 'FLAG - Kafa Press', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31306, 'ruRU', 'Причуда Искателя', 'Пройдите путь под названием \"Причуда Искателя\", чтобы найти хранителя истории Чо. По пути остановитесь у трех храмов.', 'Я уверен, что у твоего пандарийского друга есть пара идей насчет планов могу.$B$BОн пошел на гору пару дней назад без проводника и сказал, что лишь ты $gдолжен:должна; последовать за ним. Он выразился очень конкретно:$B$B\"$c $gдолжен:должна; пройти этот путь без чьей-либо помощи, наедине со своими мыслями. Пусть $gон:она; почтит каждое святилище по пути, прежде чем встретится со мной.\"$B$BЭта тропа находится к северо-западу от лагеря, она отмечена флагами. Пожалуйста, будь осторожнее! Причуда Искателя – опасный маршрут, даже если тебе сопутствует удача.', '', '', '', '', '', 'Поговорите с хранителем истории Чо в лагере Искателя.', 19865);
INSERT INTO `quest_template_locale` VALUES (31307, 'ruRU', 'FLAG - Jade Infused Blade', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31308, 'ruRU', 'Изучение основ', 'Победите в битве питомцев.', 'Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся в лес и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31309, 'ruRU', 'На поправку', 'Излечите своих питомцев полностью, поговорив со смотрительницей стойл Ирмой.', 'Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрительнице стойл Ирме, чтобы вылечить и оживить питомцев.', '', 'Ирма, местная смотрительница стойл, может исцелять и оживлять ваших питомцев.', 'Ирма', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31310, 'ruRU', 'Interrogation Tracking', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31311, 'ruRU', 'Путь Гриля', 'Принесите 5 сырых стейков из тигриного мяса мастеру гриля.', 'Пандаренский Путь Гриля позволяет готовить блюда, прибавляющие сил. Принеси мастеру Гриля немного сырых стейков из тигриного мяса, и он покажет тебе, как их готовить. В Нефритовом лесу и Красарангских джунглях много тигров. Кроме того, ты можешь найти их и в других местах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31312, 'ruRU', 'Старая карта', 'Покажите карту Рыбе Тросниковой Шкуре на Камышовом озере или на рынке Полугорья в Долине Четырех Ветров.', 'Старая выцветшая кожа буквально рассыпается у вас в руках, но надписи все еще можно разобрать.$B$BНа ней нарисована карта и написано следующее:$B$BВ равнине, где четыре ветра правят бал,$BСмеется девушка за веером златым$BИ у подножья лестницы, что предки возвели,$BОна секреты шепчет в гулкой темноте.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31313, 'ruRU', 'Просто легенда', 'Поговорите с сортировщиком зерна Пэем, резчиком Маком, мамой Минь и со стариком Седым Усом.', 'Что? Глупость какая-то!<У нее вытягивается лицо.>$B$BЧто это за ерунда про девушку, предков и какую-то там лестницу?$B$BНичего не понимаю. А ты?$B$BЛадно, тут есть кого поспрошать, тех, кто постарше нас с тобой будет.$B$BПоспрашивай народ в Полугорье. Наверняка они что-нибудь да знают.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31314, 'ruRU', 'Сокровище Старого Шипа', 'Найдите вход в пещеру и отыщите клад Старого Шипа.', 'Ох, очуметь можно! Теперь это самая настоящая охота за сокровищами!$B$BВидимо, на севере, где горы подступают к Камышовому озеру, должен быть какой-то вход или проход.$B$BТам-то мы и с тобой встретимся! На поиски сокровищ!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31315, 'ruRU', 'Наследие Плодородных Земель', 'Отнесите Альманах Старого Шипа хранительнице семян Шин Син в Полугорье, что в Долине Четырех Ветров.', 'На самом дне сундука с сокровищами вы находите свитки и мешочек из мягкой кожи, наполненный семенами.$B$BВ этих свитках – очень подробные земледельческие заметки, изображения растений, числа и подсчеты, места расположения источников и масса другой информации.$B$BНаверняка, это будет интересно кому-нибудь в совете фермеров.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31316, 'ruRU', 'Джулия, укротительница питомцев', 'Победите Джулию Стивенс в битве питомцев.', 'Хочу сказать, что тебе удалось заметно улучшить свои навыки, $n. Думаю, пришло время для более серьезного испытания.$b$bДжулию Стивенс можно найти на виноградниках Маклура, это к югу от Штормграда. Она – начинающая укротительница диких питомцев и, думаю, тебе стоит вызвать ее на поединок!', '', 'Испытай себя, сразившись с Джулией!', 'Одри Бернхеп', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31317, 'ruRU', 'Tracking Event: Found Entrance', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31318, 'ruRU', 'Tracking Event: Found Treasure', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31319, 'ruRU', 'Срочные меры', 'Запустите фейерверки Чо рядом с адмиралом Тейлором, Мишкой и Салли.', 'Твои товарищи обжились в этих местах. Но вместе с ними сюда пришла война.$b$bПока что мы не знаем всех последствий, но то, что мы уже видели... просто чудовищно.$b$bИ тем не менее, мы не можем оставить твоих друзей, поддавшись злости. Те из них, кто остался в живых, наверняка ранены и нуждаются в помощи.$b$bЭти фейерверки должны были запустить в честь окончания строительства статуи. Используй их, чтобы подать сигнал Миши, он заберет твоих товарищей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31320, 'ruRU', 'Как рыбке рюмка', 'Принесите 1 бутылку соджу четырех ветров Йогу Пьяному. Соджу Четырех Ветров можно приобрести у большинства барменов Пандарии.', 'Привет, $gприятель:подруга;, как шизнь? Не купишь цзинь-юй выпить?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31321, 'ruRU', 'Как рыбке бутылка', 'Принесите 5 бутылок пандаренского сливового вина Йогу Пьяному. Сливовое вино можно приобрести у большинства барменов Пандарии.', 'А-а-а-а, $gдружище:подрушка;-|3-6($r)!$B$BПонимаю, ты меня тут не первый раз видишь, но поверь мне, я не пьян!$B$BТы пошмотри на меня, пошмотри! Трезв как стеклышко!$B$BКонечно, я люблю топить свои печали в хорошей выпивке, но цзинь-юй не может перепить, $gсам:сама; понимаешь!$B$BНет, от выпивки я жашыпаю и вижу будущее! $B$B$B$BИ чем крепче выпивка, тем отчетливее видения! Принесешь мне чего-нибудь выпить, пошмотрю будущее и для тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31322, 'ruRU', 'Как рыбке бочка', 'Принесите 10 бутылок отвара нефритовой ведьмы Йогу Пьяному. Отвар нефритовой ведьмы можно приготовить, используя умения кулинарии.', 'Мои видения штали меркнуть, |3-6($r).$B$BМне нужно што-то покрепче, для вдохновения!$B$BЯ шлышал, сейчас стали делать отличный напиток.$B$BОн нажывается отвар нефритовой ведьмы.$B$BХочу его попробовать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31323, 'ruRU', 'Как рыбке хмелеварня', 'Принесите 20 завтраков безумца Йогу Пьяному. Завтрак безумца можно приготовить, используя умения кулинарии.', 'Так, $n, чтобы видения шнова вернулись ко мне, мне нужна своя хмелеварня.$b$B...$B$BШучу-шучу! $gВидел:Видела; бы ты свое лицо! Как шмешно! Ик.$B$BВ общем, ладно, слышал я тут об одном напитке, подобного которому нет. И я хочу его попробовать.$B$B$gШлышал:Шлышала; про завтрак безумца? Вот если принесешь мне его, штанем друзьями навек.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31324, 'ruRU', 'Семейные тайны', 'Соберите 5 секретов Буйного Портера.', 'Наши секретные рецепты! Я столько их собирала. А потом... Хозены?$B$B<У тетушки недоуменный вид.>$B$BИ как Гао теперь хоть что-то сварит? Надо вернуть эти рецепты, иначе будет беда, просто беда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31325, 'ruRU', 'Прекрасное ожерелье', 'Отнесите ожерелье Тине Грязный Коготь в дом Хаоханя или на рынок Полугорья в долине Четырех Ветров.', 'Несмотря на то, что за него хватались десятки грязных рук, это ожерелье по-прежнему прекрасно.$B$BИ у меня не так много вариантов, кому оно может принадлежать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31326, 'ruRU', 'Роскошная тиара Тины', 'Отнесите роскошную тиару Тине Грязный Коготь в дом Хаоханя или на рынок Полугорья в долине Четырех Ветров.', 'Это великолепная тиара. Интересно, у кого в равнине хватит денег на то, чтобы купить такое роскошное украшение?$B$BВпрочем, неважно, думаю, награду они дадут щедрую.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31327, 'ruRU', 'Проблемы хмелевара', 'Убейте Янь-Чжу Высвобожденного.', 'После того, как в хмелеварню заявились хозены и прочие твари, у хмелеваров возникли серьезные неприятности.$B$BОкажи мне услугу, выясни, что там происходит.', '', 'Убейте его, чтобы спасти дядюшку Гао.', 'Янь-Чжу Высвобожденный', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31328, 'ruRU', 'Изящная серьга', 'Отнесите изящную серьгу Тине Грязный Коготь в дом Хаоханя или на рынок Полугорья в долине Четырех Ветров.', 'Вы вытаскиваете серьгу из уха мохнатого существа. Похоже, ему нравилось носить эту красивую висюльку. Пожалуй, даже слишком нравилось.$B$BВозможно, владелица захочет получить свое украшение обратно. И совершенно необязательно рассказывать ей, где эта серьга была... и кто ее носил.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31329, 'ruRU', 'Великолепная брошь', 'Отнесите великолепную брошь Тине Грязный Коготь в дом Хаоханя или на рынок Полугорья в долине Четырех Ветров.', 'Это очень старая, антикварная брошь, отделанная тончайшей филигранью по краям. Судя по виду, стоит она немало.$B$BПоскольку в этих краях есть только одна особа, постоянно теряющая украшения, вероятно, стоит вернуть ей ее брошь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31332, 'ruRU', 'Урок 1: разрезанные персики', 'Достаньте 5 пандаренских персиков для занятий с Номи.', 'Уже очень хочется чему-нибудь научиться. Начнем с разрезанных персиков, да?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31333, 'ruRU', 'Урок 2: растворимая лапша', 'Достаньте 5 порций лапши быстрого приготовления для занятий с Номи.', 'Растворимую лапшу готовить совсем просто, так ведь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31334, 'ruRU', 'Урок 3: подрумяненная соленая рыба', 'Достаньте 5 золотистых карпов для занятий с Номи.', 'Надо же, готовить сложнее, чем кажется. Все постоянно пригорает.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31335, 'ruRU', 'Урок 4: сушеный игольчатый гриб.', 'Достаньте 5 опят для занятий с Номи.', 'Не очень люблю грибы... но все равно попробую освоить это блюдо.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31336, 'ruRU', 'Урок 5: торт из молотого риса', 'Достаньте 5 порций риса для занятий с Номи.', 'Обожаю рисовые торты. Надеюсь, получится вкусно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31337, 'ruRU', 'Знак признательности', 'Получите подарок Номи.', 'Спасибо, что интересуешься, как у меня дела! Сегодня мне удалось помочь семейству Железной Лапы, и они сказали, что я могу передать это тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31338, 'ruRU', 'Заблудший барашек', 'Найдите Бяшу и верните его Чи-Чи.', 'Любимый барашка Чи-Чи, Бяша, совсем пропасть!$B$BПлохой барашка всегда убегай с фермы!$B$BГлупый баран! Я искать везде — его нет.$B$BМожешь помочь, |3-6($r)?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31339, 'ruRU', 'Заблудший барашек... Еще раз', 'Найдите Бяшу и верните его Чи-Чи.', 'Тупой барашка! Опять пойти гулять!$B$BМожешь найти еще раз?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31340, 'ruRU', 'Ох, Бяша...', 'Найдите Бяшу.', 'Хм... ты угадай... Бяша ушел. Снова!$B$BГлупый-глупый баран! Одни хлопоты с ним!$B$BЯ не хотеть просить, но... я обещай – это в последний раз.$B$BНайдешь Бяшу?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31341, 'ruRU', 'Волк в овечьей шкуре', 'Используйте старую овечью шкуру в Небогорье или в деревне Куньцзэнь, а потом убейте Крунко.', 'А-а-а! Это был последний капля!$B$bХозены с гор убить мой Бяшу!$B$BЯ знай, кто это делать, и я хочу месть!$B$BЕсли хочешь помогать, бери этот старый овечий шкура.$B$BИди на север, в горы, и надень на себя. Жди мелкий дукер Крунко и сломать все-все его кости!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31342, 'ruRU', 'Путь к уважению лежит через насилие.', 'Убейте Ша Жестокости.', 'Твое боевое мастерство несомненно.$B$BНо если ты хочешь помогать нам и дальше, я попрошу тебя о еще одной услуге.$B$BВ Закрытых покоях под землей притаился Ша Жестокости. Уничтожь его, и заслужишь мое уважение.', '', 'Мастер Снежный Вихрь попросил вас убить это кошмарное существо.', 'Ша Жестокости', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31343, 'ruRU', 'Kovok Tracking', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31344, 'ruRU', 'Tracking Event: Chee Chee Exalted', '', '', '', '', '', '', '', '', 19865);
