INSERT INTO `quest_template_locale` VALUES (31348, 'ruRU', 'Tracking Event: Gina Mudclaw Exalted', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31349, 'ruRU', 'Tracking Event: Haohan Mudclaw Exalted', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31350, 'ruRU', 'Tracking Event: Jogu the Drunk Exalted', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31351, 'ruRU', 'Tracking Event: Old Hillpaw Exalted', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31352, 'ruRU', 'Tracking Event: Sho Exalted', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31353, 'ruRU', 'Tracking Event: Tina Mudclaw Exalted', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31354, 'ruRU', 'Дар Мацзу', 'Поговорите с опытным рыболовом Цзюй Лэнем в Приюте капитана.', 'Вы с капитаном отлично справились, $n! Я горжусь, что ты в моей команде.$B$BКстати! Цзюй Лэню удалось выжить! Он выплыл на берег, когда вы начали бомбардировать левиафана гарпунами. Плел что-то про какое-то гигантское яйцо, которое принесло сюда вместе с Цзяо.$B$BИди, проверь, как он там, ладно? Наверное, он уже вытащил это яйцо из воды.', '', '', '', '', '', 'Поговорите с опытным рыболовом Цзюй Лэнем в Приюте капитана.', 25549);
INSERT INTO `quest_template_locale` VALUES (31355, 'ruRU', 'Восстановление чистоты нефрита', 'Помогите Мудрому Марису, Лю Пламенное Сердце и хранителю истории Каменная поступь справиться с ша.', '$c, ты поможешь нам?$B$BЭтот храм был осквернен. Даже сейчас три мастера продолжают сражаться с обуревающими их сомнениями.$B$BПожалуйста, умоляю тебя, помоги Мудрому Марису, Лю Пламенному Сердцу и хранителю истории Каменной Поступи одолеть ша.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31356, 'ruRU', 'Глубина сомнений порождает глубину мысли', 'Убейте Ша Сомнения.', 'Один древний пандарен сказал \"Глубина сомнений порождает глубину мысли.\"$B$BШа Сомнения отравил Нефритовое сердце, которое находится в храме. Его необходимо уничтожить.$B$BОсмелюсь предположить, |3-6($c), что выполнив это задание, ты станешь $gмудр:мудра; не по годам.', '', 'Избавьте храм от сомнений.', 'Ша Сомнения', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31357, 'ruRU', 'Реликвии Четырех Королей', 'Найдите светильник короля-чародея, весы безумного короля Мына, свиток \"Наука Войны\" Цяна и стремительный лук Субетая.', 'Могу вернулись к жизни, и теперь угрожают всей Пандарии. И они вот-вот станут еще более опасны.$B$BЛегенда гласит о четырех королях могу: Цзыань Беспросветная Тьма, Мын Безумный, Цян Безжалостный и Субетай Быстрый. Четыре артефакта этих королей хранятся в Королевском хранилище.$B$BТебе нужно найти артефакты до того, как это сделают могу, иначе мы уже не сможем их остановить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31359, 'ruRU', 'Говорящий с куньчунами', 'Убейте оракула Хисс\'ира и 10 членов племени Грязной Чешуи.', 'Чтобы упрочить связь с Ковоком, надо постоянно подвергать его испытаниям – ментальным и физическим. Надо уважать его силу и интеллект, только тогда он позволит себя тренировать.$b$bДумаю, племя Грязной Чешуи – хорошая проверка, Ковок сможет показать себя, а ты будешь в относительной безопасности.$b$bК тому же, так этих тварей на Соленой отмели станет поменьше.', '', 'Верховный оракул племени Грязной Чешуи.', 'Оракул Хисс\'ир', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31360, 'ruRU', 'Новый урок для мастера', 'Убейте Синя Мастера Боя.', 'У могу появился новый король – Синь Мастер Боя.$B$BОн подчинил себе все кланы могу, и теперь они сражаются за его благосклонность.$B$BЯ не знаю более великого воина, так что не надо его недооценивать, $n.$B$BНаша судьба в твоих руках.', '', 'Убейте нового короля могу.', 'Синь Мастер Боя', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31362, 'ruRU', 'Последний фрагмент головоломки', 'Используйте фамильную ценность Чо у фамильного святилища Чо на площадке с видом на Нефритовую Змею Чо.$b$bПопросите Миши доставить вас туда.', 'Надо сказать, $n, несмотря на вечную вражду с хозенами, цзинь-юй никогда не были настроены столь воинственно. Меня это беспокоит. Ладно, эту проблему обсудим в другой раз. Сейчас мне нужна твоя помощь.$b$bТа древняя фреска, которую мы видели в прошлый раз, почти разгадана. Нет сомнений, что в ней сокрыта древняя мудрость – знание, которое хотел нам оставить император.$b$bЧтобы расшифровать ее значение, моих медитаций может оказаться недостаточно. Пожалуйста, отнести эту фамильную ценность в святилище моего рода. Мне потребуется помощь предков.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31363, 'ruRU', 'Освещая путь', 'Зажгите сигнальный огонь', 'Нам нужно подкрепление! Кто-то должен прорваться туда и зажечь сигнальный огонь.$B$BХочешь вызваться, |3-6($c)? Дело добровольное.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31364, 'ruRU', 'Тараканище!', 'Убейте Райгонна.', 'У богомолов в распоряжении есть очень опасная тварь – Райгонн. С помощью этого гигантского жука они собираются разрушить ворота!$B$BНельзя допустить, чтобы эта тварь прорвалась в Дол.', '', 'Не дай ему прорваться внутрь!', 'Райгонн', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31365, 'ruRU', 'Где-то внутри', 'Спасите 12 шадопанских пленников.', 'Я отправил к богомолам с десяток своих солдат.$B$BНи один не вернулся.$B$BРаз уж ты собираешься драться с богомолами, думаю, у тебя будет возможность освободить тех, кому не повезло попасть в плен.$B$BВозьмешься?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31366, 'ruRU', 'Убейте командующего флангом', 'Убейте командующего флангом Нер\'онока.', 'Богомолы осаждают храм Нюцзао.$B$BДаже сейчас командующий флангом Нер\'онок и его войска пытаются построить мост через последнее ущелье.$B$BТы $gдолжен:должна; им помешать.', '', 'Его надо убить, чтобы помешать строительству моста.', 'Командующий флангом Нер\'онок', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31367, 'ruRU', 'Хранители истории', 'Поговорите с хранителем истории Чо из Обители Мудрости в Вечноцветущем доле.', 'Так ты хочешь узнать больше об истории этой земли?$B$BОтлично! Тебе стоит поговорить с Хранителем истории Чо в Обители Мудрости.$B$BТы найдешь его в комнате прямо над входом во Дворец Могу\'шан. Попроси Миши доставить тебя туда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31368, 'ruRU', 'Хранители истории', 'Поговорите с хранителем истории Чо из Обители Мудрости в Вечноцветущем доле.', 'Так ты хочешь узнать больше об истории этой земли?$B$BОтлично! Тебе стоит поговорить с хранителем истории Чо в Обители Мудрости.$B$BТы найдешь его в комнате прямо над входом во Дворец Могу\'шан. Попроси Миши доставить тебя туда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31369, 'ruRU', 'Рыболовы', 'Поговорите с рыбаком Хайто в Деревне рыболовов в Красарангских джунглях.', 'Если ты хочешь изведать все тайны бездонного океана и поймать по-настоящему крупную рыбу, тебе стоит поговорить с моим братом Хайто в Деревне рыболовов в Красарангских джунглях.$B$BОн наверняка будет рад показать тебе, как обращаться с леской и крючком!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31370, 'ruRU', 'Рыболовы', 'Поговорите с рыбаком Хайто в Деревне рыболовов в Красарангских джунглях.', 'Если ты хочешь изведать все тайны бездонного океана и поймать по-настоящему крупную рыбу, тебе стоит поговорить с моим братом Хайто в Деревне рыболовов в Красарангских джунглях.$B$BОн наверняка будет рад показать тебе, как обращаться с леской и крючком!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31371, 'ruRU', 'Tracking Event: Player Has Completed One Anglers Daily', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31372, 'ruRU', 'Земледельцы', 'Поговорите с фермером Юном на Ферме Солнечной Песни, которая находится в Долине Четырех Ветров.', 'На Полугорье в Долине Четырех Ветров работают земледельцы.$B$BДля начала можешь поговорить с новым фермером по имени Юн.$B$BДумаю, ему пригодится твоя помощь.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31373, 'ruRU', 'Орден Облачного Змея', 'Поговорите с инструктором Небесным Шипом в Дендрарии, расположенном в Нефритовом лесу.', 'Орден Облачного Змея всегда приветствует одаренных путников.$B$BЕсли тебе близок наш путь, поговори с инструктором Небесным Шипом в Дендрарии, который находится в Нефритовом лесу.$B$BУдачи, |3-6($r)!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31374, 'ruRU', 'Земледельцы', 'Поговорите с фермером Юном на ферме Солнечной Песни, которая находится в долине Четырех Ветров.', 'В Полугорье, что в долине Четырех Ветров, работают земледельцы.$B$BДля начала можешь поговорить с вновь прибывшим фермером по имени Юн.$B$BДумаю, ему пригодится твоя помощь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31375, 'ruRU', 'Орден Облачного Змея', 'Поговорите с инструктором Небесным Шипом в Дендрарии, расположенном в Нефритовом лесу.', 'Орден Облачного Змея всегда приветствует одаренных путников.$B$BЕсли тебе близок наш путь, поговори с инструктором Небесным Шипом в Дендрарии, который находится в Нефритовом лесу.$B$BУдачи, |3-6($r)!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31376, 'ruRU', 'Битва у храма Нефритовой Змеи', 'Поговорите с верховным жрецом Тай-Фэном в землях Нефритового храма в Нефритовом лесу.', 'Тьма подступает к храму Нефритовой Змеи, и жрецы Юй-лун молят нас о помощи.$B$BПока что жрецы еще сдерживают ша, но силы их на исходе.$B$BТолько ты сможешь изменить ход событий, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31377, 'ruRU', 'Битва у храма Нефритовой Змеи', 'Поговорите с верховным жрецом Тай-Фэном в землях Нефритового храма в Нефритовом лесу.', 'Тьма подступает к храму Нефритовой Змеи, и жрецы Юй-лун молят нас о помощи.$B$BПока что жрецы еще сдерживают ша, но силы их на исходе.$B$BТолько ты сможешь изменить ход событий, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31378, 'ruRU', 'Испытание в храме Красного Журавля', 'Поговорите с Телонием в Колыбели Чи-Цзи в Красарангских джунглях.', 'Храм Красного Журавля все еще сотрясают последствия нашествия ша, лишь недавно там нашли в себе силы собраться и начать восстановление храма и его воинов.$B$BЕсли ты $gготов:готова; помочь храму, поговори с Телонием в Колыбели Чи-Цзи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31379, 'ruRU', 'Испытание в храме Красного Журавля', 'Поговорите с Телонием в Колыбели Чи-Цзи в Красарангских джунглях.', 'Храм Красного Журавля все еще сотрясают последствия нашествия ша, лишь недавно там нашли в себе силы собраться и начать восстановление храма и его воинов.$B$BЕсли ты $gготов:готова; помочь храму, поговори с Телонием в Колыбели Чи-Цзи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31380, 'ruRU', 'Испытание в храме Белого Тигра', 'Поговорите с Сюэнем в храме Белого Тигра на вершине Кунь-Лай.', 'Сюэнь, великий дух Севера, ищет величайших героев.$B$BСегодня он устраивает турнир в своем храме на вершине Кунь-Лай.$B$BЕсли ты $gготов:готова; встретиться в битве с лучшими бойцами Пандарии, отправляйся туда и выйди на арену!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31381, 'ruRU', 'Испытание в храме Белого Тигра', 'Поговорите с Сюэнем в храме Белого Тигра на вершине Кунь-Лай.', 'Сюэнь, великий дух Севера, ищет величайших героев.$B$BСегодня он устраивает турнир в своем храме на вершине Кунь-Лай.$B$BЕсли ты $gготов:готова; встретиться в битве с лучшими бойцами Пандарии, отправляйся туда и выйди на арену!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31382, 'ruRU', 'Оборона храма Нюцзао', 'Поговорите со старейшиной Ого в храме Нюцзао в Танлунских степях.', 'Богомолы напали на храм Нюцзао, далеко на западе.$B$BХрам пока еще держится, но без поддержки это долго не продлится.$B$BОтправляйся на помощь защитникам, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31383, 'ruRU', 'Оборона храма Нюцзао', 'Поговорите со старейшиной Ого в храме Нюцзао в Танлунских степях.', 'Богомолы напали на храм Нюцзао, далеко на западе.$B$BХрам пока еще держится, но без поддержки это долго не продлится.$B$BОтправляйся на помощь защитникам, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31384, 'ruRU', 'Золотой Лотос', 'Поговорите с Аньцзи Осенний Свет в Гарнизоне Заходящего Солнца, что в Вечноцветущем доле.', 'Золотой Лотос на протяжении веков охранял Дол, обеспечивая его безопасность.$B$BПосле недавних событий это священное место находится под угрозой, и на свободу вырвались страшные силы, но союзники Золотого Лотоса не сдаются и пытаются отстоять Дол.$B$BЕсли ты хочешь помочь, присоединись к ним в Гарнизоне Заходящего Солнца.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31385, 'ruRU', 'Золотой Лотос', 'Поговорите с Аньцзи Осенний Свет в Гарнизоне Заходящего Солнца, что в Вечноцветущем доле.', 'Золотой Лотос на протяжении веков охранял Дол, обеспечивая его безопасность.$B$BПосле недавних событий это священное место находится под угрозой, и на свободу вырвались страшные силы, но союзники Золотого Лотоса не сдаются и пытаются отстоять Дол.$B$BЕсли ты хочешь помочь, присоединись к ним в Гарнизоне Заходящего Солнца.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31386, 'ruRU', 'Армия Шадо-Пан', 'Поговорите с Тажанем Чжу на укреплениях Лун-Ин, которые находятся в Танлунских степях.', 'Шадо-паны проводят столь масштабную мобилизацию впервые за многие века.$B$BШа Ненависти удалось скрыться за Змеиным Хребтом, и наш священный долг – остановить его.$B$BХотя нашим воинам и нет равных, но нас просто слишком мало. Если бы нам $gпомог достойный:помогла достойная:c; |3-6($c), то ситуация могла бы обернуться в нашу пользу.$B$BЕсли хочешь присоединиться к армии Шадо-Пан, поговори с Тажанем Чжу в Танлунских степях.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31387, 'ruRU', 'Понимание Шадо-Пан', 'Добейтесь того, чтобы вас почитали в Золотом Лотосе.', 'Воины Шадо-Пан – это древнейшие защитники Пандарии.$b$bГодами мы тренируемся в нашем укрытом снегами монастыре на вершине Кунь-Лай и оттачиваем навыки боевых искусств, которые передали нам наши предки.$b$bМожет показаться, что нас не так уж много, но один воин Шадо-Пан стоит сотни вымуштрованных солдат.$b$bЧтобы стать одним из членов ордена Шадо-Пан, нужно пройти долгий и трудный путь. Если это именно то, чего ты ищешь, для начала ты $gдолжен:должна; доказать, что $gдостоин:достойна; быть $gодним:одной; из нас.$b$bУ нас есть для тебя срочное задание. Помоги Золотому Лотосу защитить дол.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31388, 'ruRU', 'Армия Шадо-Пан', 'Поговорите с Тажанем Чжу на укреплениях Лун-Ин, которые находятся в Танлунских степях.', 'Шадо-паны проводят столь масштабную мобилизацию впервые за многие века.$B$BШа Ненависти удалось скрыться за Змеиным Хребтом, и наш священный долг – остановить его.$B$BХотя нашим воинам и нет равных, но нас просто слишком мало. Если бы нам $gпомог достойный:помогла достойная:c; |3-6($c), то ситуация могла бы обернуться в нашу пользу.$B$BЕсли хочешь присоединиться к армии Шадо-Пан, поговори с Тажанем Чжу в Танлунских степях.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31389, 'ruRU', 'Понимание Шадо-Пан', 'Добейтесь того, чтобы вас почитали в Золотом Лотосе.', 'Воины Шадо-Пан – это древнейшие защитники Пандарии.$b$bГодами мы тренируемся в нашем укрытом снегами монастыре на вершине Кунь-Лай и оттачиваем навыки боевых искусств, которые передали нам наши предки.$b$bМожет показаться, что нас не так уж много, но один воин Шадо-Пан стоит сотни вымуштрованных солдат.$b$bЧтобы стать одним из членов ордена Шадо-Пан, нужно пройти долгий и трудный путь. Если это именно то, чего ты ищешь, для начала ты $gдолжен:должна; доказать, что $gдостоин:достойна; быть $gодним:одной; из нас.$b$bУ нас есть для тебя срочное задание. Помоги Золотому Лотосу защитить дол.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31390, 'ruRU', 'Клакси', 'Поговорите с лучницей Ли Ц-Вай у Врат Заходящего Солнца между Вечноцветущим долом и Жуткими пустошами.', 'Все, что мы знаем о клакси – лишь слухи, Говорят, что они обитают далеко за стеной в Жутких пустошах.$B$BНемногие добирались туда, и никому еще не удалось отттуда вернуться.$B$BЕсли ты хочешь найти этих... клакси... тебе стоит отправиться на стену, далеко на юго-запад. Там ты найдешь небольшую группу шадо-панов, которые могут что-то о них знать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31391, 'ruRU', 'Клакси', 'Поговорите с лучницей Ли у Врат Заходящего Солнца между Вечноцветущим долом и Жуткими пустошами.', 'Все, что мы знаем о клакси – лишь слухи, Говорят, что они обитают далеко за стеной в Жутких пустошах.$B$BНемногие добирались туда, и никому еще не удалось отттуда вернуться.$B$BЕсли ты хочешь найти этих... клакси... тебе стоит отправиться на стену, далеко на юго-запад. Там ты найдешь небольшую группу шадо-панов, которые могут что-то о них знать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31392, 'ruRU', 'Храм Белого Тигра', 'Поговорите с Андуином Ринном в храме Белого Тигра около вершины Кунь-Лай.', 'Ты $gслышал:слышала; новости, $gпутник:путница;? Враги напали на наше священное место, Вечноцветущий дол!$b$bНо даже сейчас принц-человек доказывает в храме Белого Тигра, что вас и прочих, кто пришел сквозь туман, надо пустить в дол.$b$bХрам находится на северо-востоке от вершины Кунь-Лай. Вдруг ты уговоришь Белого Тигра пропустить тебя?$b$bНадеюсь, Вечноцветущий дол не уничтожен полностью...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31393, 'ruRU', 'Храм Белого Тигра', 'Поговорите с Дезко в храме Белого Тигра на вершине Кунь-Лай.', 'Ты $gслышал:слышала; новости, $gпутник:путница;? Враги напали на наше священное место, Вечноцветущий дол!$b$bНо даже сейчас принц-человек доказывает в храме Белого Тигра, что вас и прочих, кто пришел сквозь туман, надо пустить в дол.$b$bХрам находится на северо-востоке от вершины Кунь-Лай. Вдруг ты уговоришь Белого Тигра пропустить тебя?$b$bНадеюсь, Вечноцветущий дол не уничтожен полностью...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31394, 'ruRU', 'Испытания Небожителей', 'Поговорите с Сюэнем и пройдите его испытания.', 'Никому не позволено входить в дол без разрешения Августейших Небожителей. Похоже, Сюэнь Белый Тигр готов меня выслушать.$b$bНо после случившегося глава Шадо-Пан, Тажань Чжу, не желает даже близко подпускать к долу кого-либо из Альянса или Орды.$b$b<Андуин качает головой.>$b$bВозможно, у тебя получится убедить его. Поговори от нашего имени с Белым Тигром. Но будь начеку! Он может подвергнуть тебя множеству испытаний...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31395, 'ruRU', 'Испытания Небожителей', 'Поговорите с Сюэнем и пройдите его испытания.', 'Должен признать, человечий теленок умеет говорить. Теперь я понимаю, почему Бейн Кровавое Копыто так высоко ценит принца.$b$bИ все же наши аргументы пока не убеждают. От меня толку мало, но ты – другое дело. Возможно, у $gпосланника:посланницы; Орды получится изменить ситуацию?$b$b$r, поговори с Белым Тигром от нашего имени.$b$bНо будь начеку! Он может подвергнуть тебя многим испытаниям...', '', '', '', '', '', '', 25549);
