INSERT INTO `quest_template_locale` VALUES (31397, 'ruRU', 'FLAG - Wodin\'s Mantid Shanker', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31398, 'ruRU', 'На части', 'Принесите переливающийся янтарь Каз\'тику Манипулятору.', 'Откуда у сауроков янтарь? Что еще важнее, какое до него дело оракулу Хисс\'иру?$b$bВряд ли его добыли в Зан\'весс, там охрана хорошая. Откуда же он тогда взялся?$b$bВозможно, у клакси найдется ответ на этот вопрос.', '', '', '', '', 'Каз\'тик Манипулятор', '', 25549);
