INSERT INTO `quest_template_locale` VALUES (31587, 'ruRU', 'Отлов питомца', 'Поймайте боевого питомца.', 'Ты отлично справляешься, $n. Скоро ты и $gсам:сама; не заметишь, как станешь мастером в обращении с питомцами. А теперь пришла пора поймать собственного питомца!$b$bОтправляйся на поиски за город и найди там боевого питомца. Затем вступи с ним в бой, а когда у него останется мало здоровья, брось ловушку.$b$bНе забудь, что твой питомец должен быть минимум 3-го уровня, иначе ловушку нельзя будет использовать.', '', '', '', '', '', 'Вернитесь к Мэтти в Оргриммар и покажите ему, кого вы поймали!', 19865);
