INSERT INTO `quest_template_locale` VALUES (31592, 'ruRU', 'На поправку', 'Излечите своих питомцев полностью, поговорив со смотрительницей стойл Дженовой Камнещит.', 'Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Дженове Камнещит, чтобы вылечить и оживить питомцев.', '', 'Дженова Камнещит, местная смотрительница стойл, может исцелять и оживлять ваших питомцев.', 'Дженова Камнещит', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31593, 'ruRU', 'Отлов питомца', 'Поймайте боевого питомца.', 'Ты отлично справляешься, $n. Скоро ты и $gсам:сама; не заметишь, как станешь мастером в обращении с питомцами. А теперь пришла пора поймать собственного питомца!$b$bОтправляйся на поиски за город и найди там боевого питомца. Затем вступи с ним в бой, а когда у него останется мало здоровья, брось ловушку.$b$bНе забудь, что твой питомец должен быть минимум 3-го уровня, иначе ловушку нельзя будет использовать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31598, 'ruRU', 'Ядро Кипа\'рака', 'Отнесите большое кипаритовое ядро кователю янтаря Зикку в Клакси\'весс.', '<Когда червь разваливается на части, из его сердцевины выпадает большой кусок кипарита. Кое-кого в Клакси\'весс он обязательно заинтересует.>', '', '', '', '', '', 'Принесите большое кипаритовое ядро кователю янтаря Зикку в Клакси\'весс.', 19865);
INSERT INTO `quest_template_locale` VALUES (31599, 'ruRU', 'Мощные жвала матриарха', 'Отнесите огромные жвала куньчун кователю янтаря Зикку в Клакси\'весс.', '<Огромные жвала матриарха куньчунов Каранош наверняка пригодятся кому-нибудь в Клакси\'весс.>', '', '', '', '', '', 'Принесите огромные жвала куньчуна кователю янтаря Зикку в Клакси\'весс.', 25549);
INSERT INTO `quest_template_locale` VALUES (31600, 'ruRU', 'Enable Scenarios', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31603, 'ruRU', 'Семена Страха', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31605, 'ruRU', 'Раскопки Зан\'тиков', 'Найдите Идеала в Янтарных копях на Зан\'весс.', 'Мы перехватили сообщение адъюнкта с Зан\'весс. Яунголы обнаружили Идеала в янтарных копях, что на дальнем конце острова.$B$BНемедленно отправляйся туда и освободи Идеала, пока Зан\'тики не уничтожили его!', '', '', '', '', '', 'Выясните, где находится извлеченный из земли Идеал в Янтарных копях, что в Зан\'весс.', 25549);
INSERT INTO `quest_template_locale` VALUES (31606, 'ruRU', 'Пробуждение Рик\'кала', 'Сдерживайте зан\'тиков, пока Рик\'кал не придет в себя.', 'Ты... не похож на них...$B$BЯ слышу зов клакси... <кашляет>$B$BДай мне прийти в себя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31607, 'ruRU', 'Выслеживание: задания \"Недобрые духи\" и \"Мы во власти ненависти\"', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31609, 'ruRU', 'Гнев Шек\'зир', 'Разбейте рой богомолов, уничтожив Акколона, Шокс\'тика, Проявление ужаса и 25 богомолов-прислужников.', 'Остальные освобожденные Идеалы рассеяны по всему Сердцу Страха. Они сражаются с роем богомолов, и им может понадобится твоя помощь!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31611, 'ruRU', 'Куньлайский сногсшибатель', 'Защитите фестиваль Хмельнолуния.', 'Ты $gбыл:была; когда-нибудь на фестивале Хмельнолуния?$b$bДобрые жители деревни Бинан устраивают славную пирушку. И сегодня напитки для нее предоставит никто иной, как твой покорный слуга.$b$bЯ приготовлю свой знаменитый куньлайский сногсшибатель!$b$bНе желаешь ли повеселиться вместе с нами? Праздник обещает быть очень радостным, мы забудем обо всех заботах – ведь опасность нам не грозит.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31612, 'ruRU', 'Тень империи', 'Сопроводите Кил\'рука Рассекающего Ветер в зал под Клакси\'весс.', 'Пока что ты $gсумел:сумела; понять лишь часть законов, по которым живет наш орден. Ты – $gчужестранец:чужестранка;, и к тебе относились соответствующим образом.$b$bНо мы не можем и дальше иметь от тебя секреты. Есть кое-что, что ты $gдолжен:должна; увидеть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31613, 'ruRU', 'Отвар Зеленой Скалы', 'Помогите защитить деревню Зеленой Скалы.', 'Я сейчас готовлю свой знаменитый отвар Зеленой Скалы.$b$bОн пригодится нам в борьбе с негодяями и всякими злодеями, которых сейчас полно в шахтах.$b$bВот что я скажу – может, соберешь друзей да и приведешь их сюда, чтобы попробовали мой напиток?$b$bПервая кружка – за счет заведения!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31652, 'ruRU', 'Roll Club: Serpent\'s Spine Tracking Quest', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31654, 'ruRU', 'Проход в Дол открыт', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31655, 'ruRU', 'Mishi Tracking 1', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31656, 'ruRU', 'Угроза на юге', 'Поговорите с лучницей Ли на Змеином Хребте.', 'Ша Ненависти был повержен, а вместе с ним исчезла и самая страшная угроза для этих земель, и все же опасность существует. Во время нашего путешествия к южным границам выяснилось, что силы богомолов в Жутких пустошах пришли в движение и скоро нагрянут сюда.$B$BЕсли хочешь сослужить хорошую службу шадо-панам, то советую доложиться лучнице Ли на Змеином Хребте. Она дежурит на великой стене, что защищает наши плодородные земли на востоке от кошмаров Жутких пустошей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31660, 'ruRU', 'Обуза для роя', 'Убейте 30 роерожденных во Владениях Шек\'зир.', 'У только что появившихся на свет богомолов есть только два инстинкта: есть и убивать. Они нападают на сородичей, пожирая слабых и оставляя в живых сильнейших.$B$BВсе меняется, когда приходит время роя: роерожденные нападают лишь на врагов.$B$BНо роерожденные из Владений Шек\'зир осквернены. Они появляются на свет в тенях и кошмарах, их ведет не голод, а ужас.$B$BОни обуза для роя, и они должны быть уничтожены.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31661, 'ruRU', 'Источник чудовищной силы', 'Покажите тронутый ша кристалл кователю янтаря Зикку в Клакси\'весс.', '<Хранители кладки по-видимому используют эти ослепительно-белые кристаллы для фокусирования магической энергии. Заглянув внутрь, вы увидели массивные струи черного дыма, которые пульсируют в центре. Рабочие Клакси\'весс смогут рассказать поподробнее об этом материале и о том, почему он так распространен в пустошах.>', '', '', '', '', '', 'Принесите тронутый ша кристалл кователю янтаря Зикку в Клакси\'весс.', 25549);
INSERT INTO `quest_template_locale` VALUES (31664, 'ruRU', 'Задание для рыболова', 'Прочтите рыболовный журнал Ната.', 'В журнале собраны бессвязные воспоминания Ната о его великих приключениях. Прочитать эти записи будет весьма полезно для понимания сути рыбной ловли.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31665, 'ruRU', 'FLAG - Vegetron 4000 Converted', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31666, 'ruRU', 'FLAG - Wind-Reaver\'s Dagger', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31668, 'ruRU', 'Ambush Event Tracking', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31669, 'ruRU', 'Капустное испытание', 'Посадите капусту кале на ферме Солнечной Песни. Семена капусты можно приобрести у торговца Зеленое Поле на рынке Полугорья.', 'Мой дедушка всегда говорил, что о фермере можно судить по его капусте. Всякий раз, когда в городе появялся новый фермер, дедушка покупал у того пару кочанов, чтобы понять, что тот из себя представляет.$b$bТеперь я сам стал фермером, и мне представился шанс показать себя. Не $gмог:могла; бы ты посадить для меня немного капусты?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31670, 'ruRU', 'Эта притягательная морковь', 'Посадите хрустящую морковь на ферме Солнечной Песни. Семена продаются у торговца Зеленое Поле на рынке Полугорья.', 'Мой дедушка всегда говорил: \"От моркови нет никакой пользы, она лишь приманивает гну-синей\". Кажется, за свою жизнь он не вырастил ни одной морковки.$b$bНо в этом я с ним не соглашусь. Я рисковать люблю. И к тому же я люблю морковь.$b$bМожет, раздобудешь семена и вырастишь для меня морковь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31671, 'ruRU', 'Почему бы и не лук-шалот?', 'Посадите лук-шалот на ферме Солнечной Песни. Семена можно приобрести у торговца Зеленое Поле на рынке Полугорья.', 'Я слышал, что Хаохань собирался сажать лук-шалот сегодня. Не уверен, что сегодня самый подходящий для этого день, но, надеюсь, он знает, что делает. В конце концов, это же он глава союза земледельцев.$b$bНе посадишь для меня лук-шалот?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31672, 'ruRU', 'Тыквенный аромат', 'Посадите тыкву могу на ферме Солнечной Песни. Семена можно приобрести у торговца Зеленое Поле на рынке Полугорья.', 'На рынке поговаривают, что Джине Грязный Коготь нравится аромат цветков тыквы. Может быть, если на моей ферме будут расти тыквы, то она будет почаще сюда захаживать?$b$bНе посадишь для меня тыкву?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31673, 'ruRU', 'Красный лук-порей – лучшее средство против кроколисков', 'Посадите красный лук-порей на ферме Солнечной Песни. Семена можно приобрести у торговца Зеленое Поле на рынке Полугорья.', 'Дедушка всегда говорил мне, что запах красного лука-порея отпугивает кроколисков. Наверное, он был прав... Он всегда выращивал лук-порей, и я никогда не видел ни одного кроколиска вблизи его фермы.$b$bВообще-то водоемов тут поблизости нет... но лучше лишний раз подстраховаться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31674, 'ruRU', 'Розовая репа: вызов брошен', 'Посадите розовую репу на ферме Солнечной Песни. Семена можно приобрести у торговца Зеленое Поле на рынке Полугорья.', 'Старик Горная Лапа был готов поспорить, что на моей земле невозможно вырастить розовую репу.$b$bЯ ему докажу, что он не прав. У меня будут расти самые большие, самые розовые репки, из всех, какие только видел этот простофиля!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31675, 'ruRU', 'Лечение белой репой', 'Посадите белую репу на ферме Солнечной Песни. Семена можно приобрести у торговца Зеленое Поле на рынке Полугорья.', 'Дедушка любил говорить: \"Руки должны быть чистыми, а земля – еще чище\". На первый взгляд, вроде какая-то нелепость, но на самом деле он прав.$b$bПосле сбора урожая в земле часто остаются корни, которые могут испортить почву, но белая репа обладает удивительным свойством очищать землю от этой дряни. Поможешь мне с посадкой белой репы?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31676, 'ruRU', 'Месть древних', 'Убейте 6 мстительных гуртанских духов на Террасе Гуртан.', 'До меня доносятся яростные вопли духов гуртанских могу, которых я сразил давным-давно. Они шныряют по развалинам террасы в поисках мщения.$B$BМне не хватит сил дать им отпор, если они найдут меня в таком состоянии. Отвлеки их и разделайся с ними.$B$BЗакончи начатое, и я открою тебе, кто я такой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31677, 'ruRU', 'Прах вождя', 'Принесите прах вождя клана Гуртан Кил\'руку Рассекающему Ветер в Клакси\'весс.', '<Многие столетия назад Кил\'рук Рассекающий Ветер одолел вождя Гуртана, но дух повелителя зверей из рода могу до сих пор витает над руинами древней крепости.$B$BПобеда над этим духом может помочь вам заслужить благосклонность клакси.>', '', '', '', '', '', 'Принесите прах вождя Гуртана Кил\'руку Рассекающему Ветер в Клакси\'весс.', 19865);
INSERT INTO `quest_template_locale` VALUES (31680, 'ruRU', 'Преступление и наказание', 'Убейте 8 ик\'тиков-жнецов на Жгучей тропе.', 'Вдоль Жгучей тропы растет много молодых деревьев кипари, но императрица приказала собирать янтарь и с этих саженцев... слишком рано! Так нельзя, $gчужестранец:чужестранка;!$b$bКлакси\'ва требуют, чтобы злодеи понесли заслуженное наказание! Доставь им радость и уничтожь ик\'тиков-жнецов.', '', '', '', '', '', 'Поговорите с Кор\'иком в Янтарном зале.', 19865);
INSERT INTO `quest_template_locale` VALUES (31681, 'ruRU', 'Чем старше, тем лучше', 'Соберите 7 кувшинов с янтарем с накопителей янтаря на Жгучей тропе.', 'Собирать янтарь с саженцев – преступление, но еще большее преступление – позволить ему бесцельно пропасть.$b$bМолодой янтарь не так полезен, но клакси он все равно пригодится. Принесем им побольше янтаря, и они восславят меня!$b$bСобери молодой янтарь, мы поместим его в хранилище, выдержим его там, и он будет пригоден для еды.', '', '', '', '', '', 'Поговорите с Кор\'иком в Янтарном зале.', 19865);
INSERT INTO `quest_template_locale` VALUES (31682, 'ruRU', 'Уже не у моря', 'Поднесите камертон клакси к океаническим камням и пробудите Идеал.', 'Клакси\'ва говорили со мной, $gчужестранец:чужестранка;. Идеал был спрятан на Соленой отмели, но нам все же удалось его отыскать.$b$bЕго окружают люди-ящеры, и мы не можем позволить им и пальцем его тронуть!$b$bНайди его и пробуди. Без Идеала можешь не возвращаться!$b$bЕсли справишься со своей задачей, то клакси будут нам весьма признательны.', '', '', '', '', '', 'Поговорите с Каз\'тиком Манипулятором.', 19865);
INSERT INTO `quest_template_locale` VALUES (31685, 'ruRU', 'Долина Четырех Ветров', 'Телепортируйтесь в Долину Четырех Ветров и поговорите с рядовым В. Ременным.', 'Арр! Нефритовый лес закрыт на принудительную реконструкцию, зато Долина Четырех Ветров созрела для исследований. Скажешь, когда будешь $gготов:готова;, и я подброшу тебя, куда захочешь. На той стороне мой приятель подкинет тебе вещичек в дорогу.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31687, 'ruRU', 'Проредить сик\'тиков', 'Убейте 12 богомолов cик\'тиков.', 'Несмотря на все наши усилия, направленные на то, чтобы удержать богомолов в Жутких пустошах, некоторым из них удалось прорваться. Судя по всему они направляются к храму Нюцзао. Мои войска пытались уничтожить их на западе, в Сик\'вессе, но безуспешно. Если ты хотя бы наполовину $gтакой:такая:c; |3-6($c), $gкаким:какой:c; тебя описывает Тажань, возможно, у тебя получится лучше. $b$bОтправляйся на запад и убей всех богомолов сик\'тиков, каких только увидишь. И помни, никакой жалости. От нас зависят жизни тех, кто в храме.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31688, 'ruRU', 'Поиски Беспокойного Лэна', 'Обыщите клетки сик\'тиков и попытайтесь найти Беспокойного Лэна.', 'Один из моих лучших разведчиков, Беспокойный Лэн, пропал без вести во время нашей операции на той стороне Сик\'весса. Надеюсь, он попал в плен, а не был убит, но поскольку богомолы находятся под воздействием ша, ничего нельзя утверждать наверняка.$b$bМожешь ли ты проверить клетки вокруг Сик\'весса? Я просто обязан искать его как можно лучше, но нас так мало, а нам нужно держать оборону на юге.$b$bПожалуйста, |3-6($c), даже если он уже мертв, найди его. Я должен знать, что с ним случилось.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31689, 'ruRU', 'Воины ужаса', 'Убейте 6 вор\'тиков – воинов ужаса в Кипари Вор.', 'Клакси многое знают и многое понимают. Они поделились со мной своей мудростью.$B$BВор\'тики впустили в себя ша, чтобы с новообретенной силой повелевать своим ложным роем. Их воины поглощают оскверненный янтарь и называют себя воинами ужаса.$B$BТакие, как они, не должны существовать. Они – грязь, которую надо стереть с лица земли.$B$BИ ты положишь начало их падению, когда прибудешь в Кипари Вор.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31690, 'ruRU', 'Покрытый письменами тигриный посох', 'Принесите ваш покрытый письменами тигриный посох мастеру каллиграфии Глень-цзу в Дендрарий.', 'Этот посох очень мощный, но вы понимаете, что рано или поздно \"перерастете\" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.', '', '', '', '', '', 'Отдайте покрытый письменами тигриный посох мастеру каллиграфии Глень-цзу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31691, 'ruRU', 'Покрытый письменами журавлиный посох', 'Принесите ваш покрытый письменами журавлиный посох мастеру каллиграфии Цзо По в Дендрарий.', 'Этот посох очень мощный, но вы понимаете, что рано или поздно \"перерастете\" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.', '', '', '', '', '', 'Отдайте покрытый письменами журавлиный посох мастеру каллиграфии Цзо По.', 19865);
INSERT INTO `quest_template_locale` VALUES (31692, 'ruRU', 'Покрытый письменами змеиный посох', 'Принесите ваш покрытый письменами змеиный посох мастеру каллиграфии Вэю в Дендрарий.', 'Этот посох очень мощный, но вы понимаете, что рано или поздно \"перерастете\" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.', '', '', '', '', '', 'Отдайте покрытый письменами змеиный посох мастеру каллиграфии Вэю.', 19865);
INSERT INTO `quest_template_locale` VALUES (31693, 'ruRU', 'Джулия Стивенс', 'Победите Джулию Стивенс в битве питомцев.', 'Думаешь, что сможешь снова меня одолеть?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31694, 'ruRU', 'Хисинген Блюз', 'test log desc ! $1oa $1oo $1oo $1oa test cona $oo fodasse $o1x caracois $o1 crl\n\n*DO NOT LOCALIZE*', 'test desc! $1oa $1oo $1oo $1oa test cona $oo fodasse $oa caracois $1ox $9o crl\n\n*DO NOT LOCALIZE*', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31695, 'ruRU', 'По ту сторону стены', 'Поговорите с Тажанем Чжу на укреплениях Лун-Ин, что в Танлунских степях.', 'Мы получили сообщение о том, что Шадо-Пан предпринял атаку на Танлунские степи. Похоже, они хотят полностью положить конец нашествию яунголов.$b$bУже несколько тысяч лет пандарены не заходили в Танлунские степи. Пандарены из ордена Шадо-Пан сильные и храбрые, но вместе с этим они еще и горды. А кроме того, их мало. Не $gмог:могла; бы ты пройти через врата Зимнего Цветения на северо-запад? Найди там предводителей Шадо-Пан и предложи им свою помощь.', '', '', '', '', '', 'Поговорите с Тажанем Чжу на укреплениях Лун-Ин, что в Танлунских степях.', 25549);
INSERT INTO `quest_template_locale` VALUES (31697, 'ruRU', 'ACCIDENTAL COPY [reuse if you like]', 'Убейте 50 нападающих богомолов с помощью орудия \"дракон\".', 'С тех пор, как ты $gушел:ушла; богомолов в округе стало намного больше. Давай-ка используем собранные тобой сферы.$B$BОтправляйся на заставу и бери управление одной из пушек на себя. Не пропусти ни единого врага.', '', '', '', '', '', 'Поговорите с Таоши на Заставе Гао-Жаня в Танлунских степях.', 19865);
INSERT INTO `quest_template_locale` VALUES (31698, 'ruRU', 'Сокращение популяции', 'Убейте 8 тигров или матерых тигров Наветренного острова.', 'Последние несколько лет были изобильными, и, как результат, популяция диких тигров на Наветренном острове резко выросла.$b$bСвирепые звери истребили всю обитающую поблизости дичь и начинают покушаться на гнезда облачных змеев.$b$bВ итоге тигры живут себе припеваючи, а облачных змеев становится все меньше.$b$bЕсли мы ничего не предпримем, эти хищные кошки их полностью уничтожат.$b$bМы должны сократить численность тигров, |3-6($r).', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31699, 'ruRU', 'Боязнь духов', 'Убейте 7 темных духов – плутов.', 'Черт возьми, и как я собиралась выполнить эту работу?$B$BИнструктор Небесный Шип попросил меня убить несколько тигров на Наветренном острове, но говорят, там все просто кишит духами!$B$BФу! Ненавижу духов! У меня от них мурашки!$B$BОни такие маленькие, и... и... прыгают на тебя, и... и... у них такие холодные маленькие липкие ручонки!$B$BФу-у-у-у! Ты $gдолжен:должна; мне помочь, $n. Избавься от этих тварей, умоляю!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31700, 'ruRU', 'Сапог не на ту ногу', 'Украдите 14 пар украденных сапог.', 'Ненавижу лесных духов. Однажды один такой маленький негодник преследовал меня целый день – подмешивал мне в чай песок и подкидывал жуков в волосы.$B$BЧто это за выходки?!$B$BДумаю, пришло время отплатить им той же монетой. Знаешь, что духи Наветренного острова любят больше всего?$B$BО, да! Сапоги!$B$BВот их-то мы и украдем! Духи просто с ума сойдут! Хе-хе.$B$BЯ вообще-то боюсь подходить близко к духам, так что придется это сделать тебе, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31701, 'ruRU', 'Охотница Наветренного острова', 'Убейте охотницу Наветренного острова.', 'Я узнала о том, что в лесах в северо-западной части острова бесчинствует злобный зверь – охотница Наветренного острова.$b$bОна уже убила нескольких облачных змеев и ранила не одного наездника из тех, кто пытался ее одолеть.$b$bНужно положить этому конец, пока от нее не пострадал еще кто-нибудь. Можешь заняться этим?', '', 'Логово охотницы находится в северо-западной части Наветренного острова.', 'Охотница Наветренного острова', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31702, 'ruRU', 'Крадучись', 'Убейте саблезуба Наветренного острова.', 'Мне рассказывали о большом белом звере, который бродит по лесам в северо-западной части острова, где обитают дикие облачные змеи.$b$bОхотница Наветренного острова – близкая подруга этого свирепого создания. Он уже убил нескольких матриархов облачных змеев.$b$bМы не можем допустить, чтобы по острову свободно разгуливал такой страшный хищник.$b$bОтправляйся туда и разберись с ним. И мы увидим, чего стоят твои тренировки.', '', '', 'Саблезуб Наветренного острова', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31703, 'ruRU', 'Беспредел Сумасброда', 'Убейте Злонравного Сумасброда.', 'У меня есть еще одно задание для тебя.$b$bЗлонравный Сумасброд – предводитель островных лесных духов.$b$bЕсли где-то начинаются неприятности с хмелеварением, наверняка именно он дергает за ниточки.$b$bУ нас нет времени, чтобы тратить его на надоедливых и нахальных духов. Расправься со Злонравным Сумасбродом и сделай это побыстрее.', '', 'Предводитель лесных духов. Опасайся его.', 'Злонравный Сумасброд', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31704, 'ruRU', 'Большая уборка', 'Соберите 5 мешочков экскрементов.', '<Детеныш облачного змея ловит ваш взгляд и стыдливо наклоняет голову.>$b$bКажется, кое-кто не сдержался, и с ним произошла небольшая \"неприятность\".$b$bЧто ж, неудивительно. Раз этот змей столько ест, то такое должно было случиться... рано или поздно.$b$bЛучше найти оставленные змеем кучки и убрать их, пока об этом не узнал распорядитель змеев.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31705, 'ruRU', 'Не ужаль меня', 'Воспользуйтесь медом на поляне в северной части Дендрария, а затем убейте садового острожала.', 'Дендрарий – это наш дом. Тихая гавань, где мы растим детенышей змеев и обучаем наших учеников.$b$bК сожалению, есть и другие, куда более опасные существа, которые хотят здесь поселиться.$b$bК северу отсюда, за рекой, мы видели огромного шершня, который пил нектар цветов.$b$bЭта тварь уже ужалила четырех наших учеников.$b$bВозьми этот мед и воспользуйся им как приманкой, чтобы выманить шершня из укрытия. Затем убей его, чтобы он больше не причинил никому вреда.', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31706, 'ruRU', 'Рыдающие вдовы', 'Убейте 7 рыдающих вдов.', 'Пауки, обитающие вблизи деревни Шри-Ла, стали очень агрессивными. Они представляют собой серьезную опасность для рыболовов, которые удят рыбу на берегу.$b$bРади их безопасности я прошу тебя отправиться туда и убить рыдающих вдов в Плаче Вдовы.$b$bТы найдешь пещеру, если пойдешь вдоль берега в северном направлении.', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31707, 'ruRU', 'Спутанная паутина', 'Разорвите паутину вдовы и освободите 5 жителей деревни Шри-Ла.', 'Мы получаем тревожные сообщения от рыболовов из деревни Шри-Ла, $n.$b$bНа жителей деревни нападают пауки, которые обитают в Плаче Вдовы – прибрежной пещере, расположенной к северу отсюда.$b$bПауки тащат своих жертв вглубь пещеры, опутывают их коконами из паутины и оставляют до своего следующего обеда.$b$bМы надеемся, что некоторые из них все еще живы и мы можем спасти их! Отправляйся туда и освободи всех, кого сможешь найти.', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31708, 'ruRU', 'Змеиные чешуйки', 'Соберите 25 \"змеиных чешуек\".', 'Я вижу, ты $gполучил:получила:r; своего собственного облачного змея, |3-6($r).$b$bТы не забываешь о том, что его надо кормить, убирать за ним и играть с ним? Только в этом случае твой змей вырастет здоровым и сильным.$b$bА теперь я поделюсь с тобой одним секретом. К северу отсюда, в Плаче Вдовы, растут грибы, известные как \"змеиные чешуйки\".$b$bНайти их трудно, но эти грибы особенные и содержат в себе много питательных веществ. Твоему змею они вряд ли понравятся. Впрочем, кто любит есть то, что полезно?', '', '', '', '', '', 'Вернитесь к вашему детенышу облачного змея в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31709, 'ruRU', 'Мучительные сомнения', 'Воспользуйтесь устройством измерения силы ша в местах волнений ша в Плаче Вдовы. Вход в Плач Вдовы находится в северной части берега, южнее деревни Шри-Ла.', 'Говорят, что в Плаче Вдовы, что к северу отсюда, происходит что-то странное.$b$bМы с Гиацинтом ходили туда на разведку, и теперь я не сомневаюсь в том, что в эту пещеру каким-то образом проникли ша.$b$bЯ изобрел устройство, которое позволяет измерить уровень энергии ша.$b$bЕсли ты направляешься в ту сторону, может быть, произведешь замеры?$b$bВолнения ша выглядят как потоки темной и светлой энергии, поднимающиеся из земли.', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31710, 'ruRU', 'Маленькие лакомства', 'Соберите 100 маленьких паучьих глаз.', 'При вашем приближении облачный змей открывает свою пасть, из которой капает слюна. По его виду заметно, что он успел сильно проголодаться с момента вашей последней встречи.$b$bПо тому, какие звуки он издает и как бьет хвостом, вы понимаете, что он не просто голоден, а хочет получить свое любимое лакомство.$b$bВаш змей любит пожевать маленькие паучьи глаза. Но такое изысканное лакомство можно добыть, только убивая порождений вдовы, которые обитают в пещере на берегу к северу отсюда.$b$bЧто ж, выхода нет. Ваш змей ждет.', '', '', '', '', '', 'Вернитесь к вашему змею в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31711, 'ruRU', 'Зерно сомнения', 'Уничтожьте зерно сомнения.', 'Основная проблема с Ша Сомнения в том, |3-6($r), что они проникают повсюду.$b$bСтоит зерну сомнения попасть в благодатную почву, как оно начинает расти со скоростью сорняка.$b$bИменно такое зерно пустило корни в Плаче Вдовы, что к северу отсюда. И мы должны поступить с ним так же, как с любым другим сорняком – вырвать его с корнем, немедленно.$b$bУничтожь разрастающийся очаг сомнений, пока еще кто-то не стал жертвой этой заразы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31712, 'ruRU', 'Обезьяньи проказы', 'Убейте 13 хозенов Уна.', 'Странные вести доходят до нас из деревни Шри-Ла.$b$bПохоже, племя хозенов с удобством расположилось в Уна Кагу – пещере, расположенной на берегу, к югу от рыбацкой деревни.$b$bИ чувствуют они себя там просто прекрасно. Племя занимается грабежом и мародерством по всему берегу.$b$bМы должны преподать им урок... и это тот самый случай, когда можно действовать только силой. Они уже и так злоупотребили гостеприимством.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31713, 'ruRU', 'Спасение портера', 'Соберите 100 порций украденного портера Шри-Ла.', 'Это какой-то кошмар, $n!$B$BКогда я вчера зашел в \"Танцующую змею\", там не налили ни капли. Оказалось, что у них закончился портер, а тот, что был отправлен из деревни Шри-Ла, разворовали хозены. Разворовали!$B$BЭти хозены Уна вообще доставляют много хлопот на пристани. Они тащат портер со всего побережья в свое логово в Уна Кагу.$B$BУ меня все падает из рук, когда нечем промочить горло.$B$BКто-то должен пойти туда и спасти наш портер!', '', '', '', '', '', 'Вернитесь к Айсу Длинной Лапе в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31714, 'ruRU', 'Спасение змеев', 'Соберите 10 спасенных змеев.', 'На этот раз хозены Уна зашли слишком далеко.$B$BЗнаешь, что они делают с дикими облачными змеями? Они натаскивают пойманных детенышей друг на друга на ринге на потеху публике.$B$BДикари!$B$BЕсли юные змеи свыкнутся с жестокостью, то во взрослом возрасте они могут быть очень опасны.$B$BНужно спасти малышей.', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31715, 'ruRU', 'Лорд Уна', 'Убейте Лорда Уна.', 'Главарь хозенов Уна – разбойник по имени Лорд Уна.$B$BОб этом капитане и его команде ходят жуткие истории. Всюду, куда он направляется, его племя сеет разрушение.$B$BУна причаливают на своих лодках к плодородным берегам, грабят местные деревни, выжимают из земли все до капли и двигаются дальше.$B$BПока я за все отвечаю, я не позволю, чтобы это случилось и с нашим краем.$B$BМне нужен тот, кто искоренит эту проблему незамедлительно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31716, 'ruRU', 'Большая уборка', 'Соберите 5 больших мешков экскрементов.', '<Когда вы приближаетесь к загону, змей стремительно перелетает в угол и прячется.>$b$BПо его стыдливому взгляду становится понятно, что кое-кто не сдержался и с ним произошла небольшая \"неприятность\".$b$bЧто ж, неудивительно. Раз этот змей столько ест, то такое должно было произойти... рано или поздно.$b$bЛучше найти оставленные змеем кучки и убрать их, пока об этом не узнал распорядитель змеев.', '', '', '', '', '', 'Вернитесь к вашему змею в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31717, 'ruRU', 'Поединок укротителей: Айс Длинная Лапа', 'Поговорите с Айсом Длинной Лапой, а затем победите его.', 'Ты котируешься все выше среди наших учеников, $n.$B$BКак меч закаляется в огне, так и наши ученики становятся сильнее, сражаясь друг с другом.$B$BСегодня ты сойдешься в поединке с одним из наших ярчайших учеников, Айсом Длинной Лапой. Чтобы победить его, тебе придется использовать свои защитные умения.$B$BПоговори с ним на ринге, чтобы начать состязание. Удачи.', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31718, 'ruRU', 'Поединок укротителей: Большой Бао', 'Поговорите с Большим Бао, а затем победите его.', 'Ты уже $gготов:готова; к следующему уроку, $n?$b$bСегодня тебе предстоит встретиться на ринге с Большим Бао. Он большой во всех смыслах этого слова. И он не сдастся до последнего.$b$bЕсли хочешь одержать над ним победу, тебе нужно быть $gстойким:стойкой;.$b$bПоговори с ним на ринге, чтобы начать поединок. Желаю удачи!', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31719, 'ruRU', 'Поединок укротителей: Нинья Темное Колесо', 'Поговорите с Ниньей Темное Колесо, а затем победите ее.', 'У тебя большой потенциал, $n. Однако без дисциплины и смирения талант мало чего стоит.$B$BСегодня ты сразишься с Ниньей Темное Колесо. Благодаря природной силе она стала одной из самых талантливых учениц.$B$BЕсли надеешься победить ее, то придется действовать на пределе самообладания.$B$BЧтобы начать состязание, поговори с ней на ринге. Удачи.', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31720, 'ruRU', 'Поединок укротителей: Сладкая Су-Чи', 'Поговорите со Сладкой Су-Чи, а затем победите ее.', 'Сегодня тебе предстоит встретиться на ринге со Сладкой Су-Чи. Несмотря на ее милую внешность, она – сильный противник.$b$bОна атакует быстро и точно, правда, спустя какое-то время столь мощные атаки утомляют ее.$b$bЕсли надеешься победить ее, тебе будет нужно сосредоточиться на нанесении урона, когда она ослабнет.$b$bПоговори с Су-Чи и начинай поединок. Удачи.', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31721, 'ruRU', 'Поединок укротителей: Цюа-Жо Белая Бровь', 'Поговорите с Цюа-Жо Белой Бровью, а затем победите его в бою.', 'Цюа-Жо считают лучшим послушником Ордена.$B$BКажется, у него нет слабых сторон. Он сметлив, силен, прилежен и даровит.$B$BТебе предстоит сойтись в поединке с одним из лучших бойцов.$B$BПоговори с ним, чтобы начать схватку. Кто бы из вас ни победил, ты многому научишься в бою с таким непростым соперником.', '', '', '', '', '', 'Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.', 19865);
INSERT INTO `quest_template_locale` VALUES (31724, 'ruRU', 'Старик Макдональд', 'Победите старика Макдональда в битве питомцев.', 'Для новичка ты прекрасно справляешься!$b$bСтарик Макдональд научил меня всему, что я знаю о битвах питомцев. Думаю, поединок с ним будет для тебя отличным уроком!$b$bЕго можно найти сразу за мостом, ведущим в Западный Край. И не обольщайся насчет его возраста. Он победил уже немало таких же многообещающих укротителей питомцев, как ты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31725, 'ruRU', 'Линдси', 'Победите Линдси в битве питомцев.', '$gГотов:Готова; продемонстрировать, на что ты $gспособен:способна;? В Красногорье есть девочка, с которой мало кто может сравниться в укрощении питомцев.$b$bРазыщи Линдси в Лагере Безмолвия. Она юна, но список ее побед нешуточный!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31726, 'ruRU', 'Эрик Дэвидсон', 'Победите Эрика Дэвидсона в битве питомцев.', 'Все мои друзья говорят об ужасном воргене по имени Эрик Дэвидсон из Сумеречного леса, с которым еще никто не устраивал битв питомцев.$b$bДумаю, если тебе удастся найти и победить его, то после этой победы все будут говорить только о тебе!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31727, 'ruRU', 'Поиск припасов', 'Поговорите с боцманом Ари в Приюте капитана, что в Жутких пустошах.', 'Если мы хотим выиграть эту войну, нельзя упустить ни единой мелочи.$b$bВдоль побережья были замечены посторонние. Нам не нужны чужаки, но их припасы могут пригодиться.$b$bЕсли там есть что-то полезное, мы должны опередить императрицу и завладеть этим.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31728, 'ruRU', 'Билл Баклер', 'Победите Билла Баклера в битве питомцев.', 'Мой давний друг, укротитель боевых питомцев и всем известый пьяница Билл Баклер, устроил открытый турнир для хорошо подготовленных укротителей!$b$bДумаю, тебе стоит поучаствовать и проверить свои силы. Обычно Билл шатается по южным дорогам Мыса Тернистой долины.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31729, 'ruRU', 'Стивен Лисбен', 'Победите Стивена Лисбена в битве питомцев.', 'Если тебе показалось, что сражаться со мной было трудно, сейчас тебе стоит хорошенько приготовиться. Дальше будет только сложнее.$b$bРазыщи Стивена Лисбена, обычно он бродит по дорогам в южной части Северной Тернистой долины, и ты увидишь, кто самый сильный укротитель питомцев!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31730, 'ruRU', 'Недружественная просьба', 'Поговорите с соковаром Ву в хмелеваренном дворике в Жутких пустошах.', 'Наши разведчики сообщили о присутствии чужаков рядом с Кор\'весс. Мы бы и сами могли справиться с их вторжением и вернуть похищенный янтарь, но сейчас наши солдаты нужны в другом месте.$b$bДумаю, ты справишься с этим заданием, Пробудитель. Убеди их покинуть нашу землю или сотри их с лица земли во имя клакси\'ва.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31732, 'ruRU', 'Да разверзнется ад', 'Летите на гирокоптере \"Небесного огня\", чтобы уничтожить 60 солдат лагеря Гаррош\'ар и 8 крошшеров лагеря Гаррош\'ар, а затем потопите \"Жнец Кровавого Кулака\" и \"Адский Шрам\".', 'Я не позволю Орде закрепиться на этих берегах раньше нас! Если ищешь приключений на свою голову, то можешь взять гирокоптер, который стоит на корме. Он уже подготовлен к атаке, так что от тебя просто требуется пострелять.$B$BЗадай жару этим оркам!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31733, 'ruRU', 'Коснуться земли', 'Используйте парашют \"Небесного огня\", чтобы приземлиться в лагере Гаррош\'ар, после чего поговорите с Салли \"Рассольным\" Маклири.', 'Их город пылает, а воины разрознены и сломлены. Все наши должны быть на земле немедленно, чтобы прикончить их.$B$BХватай парашют у борта корабля и прыгай вниз!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31734, 'ruRU', 'Яркая встреча', 'Используйте сигнальный пистолет Салли, чтобы уничтожить 5 боевых повозок Орды.', 'Ты $gвидел:видела;, какого размера эти боевые повозки? Там напихано столько взрывчатки, что можно подумать, будто Орда хочет не захватить континент, а разнести его на кусочки!$B$BНам надо обезвредить эти повозки, пока они еще в лагере Гаррош\'ар.$B$BВот, возьми эти карманные ракеты. Выпусти их в повозку и полюбуйся фейерверком!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31735, 'ruRU', 'Подходящий инструмент', 'Используйте сигнальный пистолет Салли, чтобы уничтожить баррикады, и сразитесь с Га\'трулом на другом конце дока.', 'Я разведал окрестности и не нашел следов принца или адмирала Тейлора. Нам надо быстро зачистить этот лагерь и продолжить наши поиски в другом месте.$B$BТут всеми операциями командует орк-чернокнижник, Га\'трул. Он забаррикадировался в доке и пытается сбежать через демонический круг.$B$BПусть этот сигнальный пистолет снова послужит нам, взорви баррикады! Я прикрою тебя с тыла, а когда ты доберешься до Га\'трула, помогу тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31736, 'ruRU', 'Посланник Альянса', 'Найдите мэра деревни Лап\'дон и поговорите с ним.', 'К северу от этого лагеря находится вишневый сад, а за ним прячется деревенька. Нам надо будет остановиться там и перевязать раненых, пока мы будем готовить наш следующий ход.$B$BОтправляйся в эту деревню и поговори с тамошним предводителем. Мы с агентом Мишкой встретим тебя там.$B$BИ будь повежливей, $n! Я возлагаю на тебя честь представлять весь Альянс. Не заставь меня пожалеть об этом.$B$BНадеюсь, что $gтакой могущественный герой:такая могущественная воительница; как ты произведет на них хорошее впечатление.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31737, 'ruRU', 'Цена войны', 'Убейте $1oa |4наваждение:наваждения:наваждений; ша и 5 ша – вестников ужаса в лагере Гаррош\'ар.', 'Тут все пылает, а с \"Небесного огня\" докладывают, что еще больше этих... теней выползает из земли. Нам надо уводить всех прочь отсюда.$B$BРасчисти путь через лагерь по дороге на север и направляйся в город. Я встречу тебя там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31738, 'ruRU', 'Батраки-мародеры', 'Убейте 12 надсмотрщиков или батраков Двух Башен.', 'Как наша деревня стала полем боя?$B$BК западу отсюда негодяи из Орды вырубают наш бесценный сад. Без яблоневых деревьев пропадет вся деревня – не будет ни урожая, ни еды, ни заработка.$B$BЕсли ты действительно не $gтакой:такая; как они, докажи нам это! Защити сад и накажи тех, кто бесчинствует на нашей земле!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31739, 'ruRU', 'Приоритеты!', 'Соберите 6 бочек сидра Яблоневого Цвета.', 'Эти так называемые \"орки\" разграбили хмелеварню и сбежали с бочками моего лучшего сидра!$b$bЯ знаю, что повсюду война, но я не тот хмелевар, который будет стоять и смотреть на то, как его коллекционный напиток пьют недостойные его личности!$b$bЭта \"Орда\" получит отпор.$b$bПочему бы тебе не обратить свое оружие на доброе дело и не помочь мне вернуть мой сидр?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31740, 'ruRU', 'Буйство Куку', 'Убейте Куку.', 'Мы беспокоимся не только о своих погребах.$b$bКуку, наш любимый мушан, сошел с ума! Только посмотри на него!$b$bЧто я только не пробовала! И уговаривала его, и упрашивала, и кричала, и успокаивала... Ничего не помогает.$b$bБоюсь, он больше не контролирует себя. Есть только один способ спасти как его, так и нашу хмелеварню.$b$bНанеси ему быстрый и точный удар. Он ничего не почувствует.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31741, 'ruRU', 'Крепость Двух Башен', 'Убейте 15 солдат Орды в Крепости Двух Башен.', 'Я не доверяю Орде. Ее представители используют темную магию и явно не с добрыми намерениями. Мы больше не можем терпеть их присутствие в Крепости Двух Башен, в двух шагах от деревни Лап\'дон.$b$bУмоляю, $gчужестранец:чужестранка;, помоги нам, а не то с нашей деревней случится что-то ужасное.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31742, 'ruRU', 'Разрозненные силы', 'Убить Далгана и Белландру Бурю Скверны.', 'Орда сама делает за нас всю работу. Их грызня и разрозненность раскололи лагерь надвое: орки на западе, нежить на востоке.$b$bОрки подчиняются своему командиру Далгану, а нежить следует за Белландрой Бурей Скверны, могучей чернокнижницей. Если повезет, то внутренние стычки отвлекут их, и ты сможешь пробраться внутрь и убить обоих. Салли уже засел в руинах. Найди его там, когда закончишь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31743, 'ruRU', 'Дым над Ордой', 'Используйте сигнальный огонь Альянса, чтобы вызвать воздушный удар по груде боеприпасов, разрушителям Двух Башен, диким бесам и Ксу\'даггабе.', 'Салли обнаружил лагерь Орды к северу отсюда и доложил, что видел огромную кучу взрывчатки, а также небольшую группу разрушителей. И это не считая демонов, которых призвали чернокнижники.$b$bК счастью, мы были готовы к этому. \"Небесный огонь\" поддержит нас с воздуха. Надо только показать нашим пилотам, куда бить.$b$b<Релл подает дымовую сигнальную ракету и со значением кивает.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31744, 'ruRU', 'Нечестная торговля', 'Освободите 8 захваченных юных пандаренов из Крепости Двух Башен, уничтожив демонические очи, которые их сторожат.', 'Хоть мы и только познакомились, у нас есть общий враг – так называемая \"Орда\".$b$bНесколько дней назад их командир предложил нам сделку. Когда мы отказались, его прислужники похитили наших детей, чтобы выбить из нас согласие.$b$bМы обратились за помощью к монахам Шадо-Пан, но вершина Кунь-Лай от нас в нескольких днях пути. Ты можешь нам помочь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31745, 'ruRU', 'Все дальше и дальше', 'Явитесь к адмиралу Роджерс в деревне Лап\'дон в Нефритовом лесу.', '\"Ша\", говоришь? Будь $gосторожен:осторожна;, $n, над этими краями сгущается тьма.$b$bМы очистим местность от остатков Орды, а тебе придется продолжить основную операцию по спасению капитана Тейлора и поискам принца Андуина.$b$bПо донесениям воздушной разведки остатки кораблекрушения были замечены вблизи деревни Лап\'дон. Отправляйся туда и обратись за дальнейшими указаниями к адмиралу Роджерс.$b$bМожешь воспользоваться моим гирокоптером.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31752, 'ruRU', 'Блескотрон-4000', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31765, 'ruRU', 'Раскрась мир красным!', 'Используйте башню боевого корабля, чтобы уничтожить 80 солдат и 9 пушек Громовой крепости.', 'Они вырубили наши двигатели, и мы упали здесь... здесь! Прямо на вражеской линии огня!$b$bТы знаешь, что надо делать, $n. Спускайся под палубы и встань за орудия!$b$bПокажи этим уродам, что они на нашей линии огня!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31766, 'ruRU', 'Коснуться земли', 'Используйте канат для спуска, чтобы добраться до земли.', 'Назгрим возглавил наземную операцию и попросил немедленно прислать тебя к нему.$B$BУ нас есть несколько канатов для спуска, привязанных возле орудий. Это самый быстрый путь вниз – ну, из тех, что заканчиваются удачно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31767, 'ruRU', 'Прикончить их!', 'Уничтожьте 15 солдат Громовой крепости.', 'Мы их потрепали. Пора их прикончить!$b$bЭту крепость надо очистить от Альянса, и нам негде держать пленников.$b$b<На лице Назгрима мелькает тень улыбки.>$b$bТы знаешь, что делать, $n. Эти трусы побегут, если дать им шанс.$b$bПостарайся им его не дать!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31768, 'ruRU', 'Огонь – лучший ответ', 'Уничтожьте 10 штабелей боеприпасов Громовой крепости.', 'Уничтожить их силы недостаточно. Нельзя оставить им ни единого шанса на спасение!$b$bВозьми это ружье и выстрели из него в боеприпасы. Пусть останутся ни с чем!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31769, 'ruRU', 'Завершающий удар!', 'Уничтожьте капитана Дорена в Громовой крепости.', 'Мы узнали, что их капитан забаррикадировался над нами.$b$bЭтот трус отправил свои отряды на смерть, а сам спрятался от нашего гнева! Типично для Альянса! Неважно. Он больше не сможет бежать от судьбы.$b$bЯ поведу своих пехотинцев на стены, а ты возглавишь основную атаку на крепостные валы. Используй ружье для подрыва взрывчатки, чтобы пробить себе дорогу.$b$bВстретимся наверху и вместе расправимся с этим ничтожеством, которое называет себя капитаном!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31770, 'ruRU', 'Или с нами, или...', 'Попытайтесь заручиться поддержкой мэра Медовая Роса в Деревне Медовой Росы.', 'Помощь жителей соседней деревушки стала необходимостью, $n.$b$bНам нужна эта деревня, чтобы позаботиться о раненых и перегруппироваться.$b$bМожет быть, ее жители помогут нам после того, как стали свидетелями жестокости Альянса.$b$bТы будешь посланником Орды. Обеспечь нам помощь со стороны их главы. И не разочаруй меня!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31771, 'ruRU', 'Лицом к лицу с последствиями', 'Убейте 20 наваждений ша и 7 ша – вестников ужаса.', 'Я не знаю предыстории вашей войны, да и не хочу ее знать. Наша земля живо реагирует на любую отрицательную энергию. Ненависть, сомнение и насилие, которые вы принесли с собой, яростно хлещут из ран Пандарии.$b$bТо, что вы натворили, посеяло хаос в руинах! Иди же туда и приведи все в порядок, а затем возвращайся ко мне. Я постараюсь объяснить тебе, что произошло.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31772, 'ruRU', 'Приоритеты!', 'Найдите 6 бочек медового хмеля на поляне Медовой Росы.', 'Только посмотри на этот бардак! Весь хмель пропал!$b$bТажань Чжу предупреждал, чтобы мы держались подальше от чужаков, но сейчас нам пригодится любая помощь.$b$bМы везли хмель в Цветущую Зарю, как вдруг начался бой. И все наше добро пропало!$b$bХочешь помочь нам? Может быть, ты найдешь какие-нибудь уцелевшие бочки с медовым хмелем? Тогда наши потери не будут столь ужасными.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31773, 'ruRU', 'Докучливые хищники', 'Уничтожьте 10 зараженных ша хищников на Поляне Медовой Росы.', 'Все животные взбесились!$b$bОбычно хищники держатся подальше от деревни, но теперь мы не можем их отогнать! Они себя раньше так никогда не вели!$b$bМэр даже позвал на помощь Шадо-Пан, но пока еще никто не приехал. Не $gмог:могла; бы ты разобраться с хищниками, пока они не задрали одного из фермеров?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31774, 'ruRU', 'В поисках Зин\'Джуна', 'Найдите Зин\'Джуна где-то на Возвышенности Кружащихся Ветров.', 'Риветт утверждает, что видел, как Зин\'Джун покинул корабль вместе с остальными выжившими. Это значит, что он может быть где угодно.$b$bМы не оставим его здесь. Его могли ранить или того хуже – взять в плен!$b$bОтыщи Зин\'Джуна и приведи его к нам.', '', '', '', '', '', 'Поговорите с Зин\'Джуном на Возвышенности Кружащихся Ветров.', 25549);
INSERT INTO `quest_template_locale` VALUES (31775, 'ruRU', 'Нападение на взлетную полосу', 'Убейте 15 бойцов Сильной Руки на Взлетной полосе Сильной Руки.', 'Мне удалось обнаружить секретный аэродром Альянса, Взлетную полосу Сильной Руки, $n. Это было несложно – врагов там целое скопище.$b$b<Назгрим отплевывается.>$b$bОни полагают, что мы уже разбиты, но, видать, они не знают, что такое Орда! Каждый ордынец дерется до последнего вздоха... а порой и после него! Пусть отведают нашей стали!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31776, 'ruRU', 'Слабости Сильной Руки', 'Убейте капрала Джексона Сильвера, Моргуса Вредоруба, а также старшего инженера Гайкокрутса и гиро-механика Клейкомяша.', 'Поступили донесения разведки, и я отметил для тебя главные цели на Взлетной полосе Сильной Руки.$b$bДва гнома-механика следят за состоянием гирокоптеров Альянса. Ликвидируй механиков, и число исправных гирокоптеров резко снизится.$b$bЕще одна цель, рыцарь смерти – дворф, ходит по периметру базы. Он в чем-то похож на тебя – такой же не связанный обязательствами искатель приключений и опасный противник.$b$bИ, наконец, известная личность – капрал Джексон Сильвер. Это герой Альянса, который мастерски обращается с арбалетом.$b$bЖелаю удачи, |3-6($n).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31777, 'ruRU', '\"Фейерверк\"', 'Соберите конфискованные установки для фейерверков на Взлетной полосе Сильной Руки, а затем примените их против 12 гирокоптеров Сильной Руки.', 'По дороге сюда я приметил несколько ручных ракетометов.$b$bМожет, это были и установки для запуска фейерверков, сложно сказать. В общем, будем считать, что это ручные ракетометы, пока не будет доказано обратное.$b$bДумаю, в руках $gтакого опытного:такой опытной:c; |3-1($c) подобная установка превратится в грозное оружие. С ее помощью можно будет даже сбить гирокоптер. Если найдешь такую установку, то обязательно опробуй ее на хлипких гирокоптерах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31778, 'ruRU', 'Ненадежные союзники', 'Убедите 12 пандаренов-добровольцев уйти со Взлетной полосы Сильной Руки.', 'Сначала мы тепло встретили Альянс. Некоторые жители деревни даже вызвались помочь чужакам в строительстве взлетной полосы. И лишь недавно мы осознали, что на самом деле там строят военную базу, в двух шагах от деревни!$b$bПодозреваю даже, что некоторых жителей удерживают там насильно. Если найдешь их, |3-6($c), передай им, что пора вернуться домой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31779, 'ruRU', 'Тьма внутри', 'Убейте капитана Дорена.', 'Тебе там случайно не попадался на глаза капитан Дорен?$b$bЭтот хлюпик где-то прячется. Если его нет на воздушной базе, значит он укрылся поблизости! Обыщи периметр базы, проверь пещеру к юго-западу от главного аэродрома. Я хочу, чтобы Альянс свалил отсюда!', '', 'Дорен – командир Сильной Руки. Нужно его убить!', 'Капитан Дорен', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31780, 'ruRU', 'Старик Макдональд', 'Победите старика Макдональда в битве питомцев.', 'В этот раз я тебе доставлю хлопот!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31781, 'ruRU', 'Линдси', 'Победите Линдси в битве питомцев.', 'Что, хочешь меня одолеть? Я всегда готова к бою.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31782, 'ruRU', 'Свержение', 'Поговорите с клакси\'ва Вор в Клакси\'весс.', 'Совет принял решение, Пробудитель.$b$bС помощью ритуала мы покончим с императрицей и обеспечим будущее нашей великой империи.$b$bУзри же силу клакси!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31784, 'ruRU', 'Полезный оникс', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31785, 'ruRU', 'Новый уровень!', 'Повысьте уровень питомца до 3-го.', 'Замечательно. Очень важно следить за здоровьем питомца, чтобы он всегда был готов к битве.$b$bВот мое следующее задание: проведи несколько битв и повысь уровень одного питомца до 3-го. После этого возвращайся ко мне и мы поговорим о том, как научиться ловить питомцев для себя!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31786, 'ruRU', 'Безупречные оковы мятежника', 'Выставите артефакт на обозрение.', 'Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.', '', '', '', '', '', '', 25549);
