INSERT INTO `quest_template_locale` VALUES (31807, 'ruRU', 'Tracking Quest: Opened the Golden Valley', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31808, 'ruRU', 'Механическая ярость', 'Уничтожьте 200 богомолов, управляя Ковоком во рве.', 'Ковок развивается с потрясающей скоростью. Возможно, годы спячки повлияли на его процесс роста?...$b$bКак бы то ни было, это как нельзя кстати. Самое время проверить, на что он способен.$b$b$n, ты так много $gсделал:сделала; для его обучения – тебе и управлять им сегодня!$b$bЯ уже подвел его к краю рва. Найди его и уничтожь армию Шек\'зир!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31809, 'ruRU', 'Остатки злости', 'Доставьте Коготь гнева Баню Медвежьему Сердцу, который находится в Танлунских степях, в гарнизоне Шадо-Пана.', 'Глядя на отрубленный коготь лапы Ша Злости, вы понимаете, что о вашей победе непременно захочет узнать Бань Медвежье Сердце, командир монахов Шадо-Пан в Танлунских степях.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31810, 'ruRU', 'Полет Облачного Змея', 'Вступите в Орден Облачного Змея.', 'Я более не могу называть себя твоим учителем, $n.$B$BТы $gпоказал себя достойным:показала себя достойной; своего облачного змея.$B$BСегодня мы примем тебя в свои ряды. Ты $gготов:готова; к этому?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31811, 'ruRU', 'Полет Облачного Змея', 'Вступите в Орден Облачного Змея.', 'Я более не могу называть себя твоим учителем, $n.$B$BТы $gпоказал себя достойным:показала себя достойной; своего облачного змея.$B$BСегодня мы примем тебя в свои ряды. Ты $gготов:готова; к этому?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31812, 'ruRU', 'Зунта, укротитель питомцев', 'Победите Зунту в битве питомцев.', 'Хочу сказать, что тебе удалось заметно улучшить свои навыки, $n. Думаю, пришло время для более серьезного испытания.$b$bЗунту можно найти у фермы Тор\'кренов, это к югу от Оргриммара. Он – начинающий укротитель диких питомцев и, думаю, тебе стоит вызвать его на поединок!', '', 'Испытай себя, сразившись с Зунтой!', 'Зунта', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31813, 'ruRU', 'Дагра Яростная', 'Победите Дагру Яростную в битве питомцев.', 'Тут неподалеку есть еще один укротитель. Попробуй-ка сразиться с ней!$b$bДагра Яростная будет тебя ждать на северном склоне Тернистого холма, к востоку от Перекрестка. Победишь ее – получишь заслуженную награду.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31814, 'ruRU', 'Аналинн', 'Победите Аналинн в битве питомцев.', 'Решимость ничего не значит, если не найти ей достойного применения.$b$bРазыщи на дорогах западного Ясеневого леса Аналинн. Она немного... эксцентричная... но укротитель из нее отменный! Если сумеешь ее победить, твоя команда станет только сильнее!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31815, 'ruRU', 'Зоня Садистка', 'Победите Зоню Садистку в битве питомцев.', '$n, появилась прекрасная возможность, и, я думаю, ты будешь в ней $gзаинтересован:заинтересована;.$b$bЗоня Садистка из южной части Когтистых гор снова участвует в поединках. Думаю, тебе стоит встретиться с ней, чтобы отточить свои навыки укротителя питомцев.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31817, 'ruRU', 'Мерда Могучее Копыто', 'Победите Мерду Могучее Копыто в битве питомцев.', '$gГотов:Готова:r; к настоящей проверке твоего мастерства, |3-6($r)?$b$bМерда Могучее Копыто разбила лагерь в местечке, которое называют Просекой Карнума. Это в Пустошах. Поединок с таким сильным укротителем питомцев, как она, станет для тебя хорошей проверкой, не так ли?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31818, 'ruRU', 'Зунта', 'Победите Зунту в битве питомцев.', 'Думаешь, что сможешь снова меня одолеть?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31819, 'ruRU', 'Дагра Яростная', 'Победите Дагру Яростную в битве питомцев.', 'В этот раз ты встретишь на горе собственную смерть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31820, 'ruRU', 'Подарок для учителя', 'Получите подарок от Номи.', 'Я полностью догнал других детей, даже несмотря на то, что начал гораздо позже. И теперь я могу посещать обычные уроки вместе со всеми!$b$bЯ сделал для тебя фартук, чтобы показать, как я ценю все то, что ты для меня $gсделал:сделала;. Надеюсь, тебе нравится?', '', '', '', '', '', 'Получите подарок от Номи.', 25549);
INSERT INTO `quest_template_locale` VALUES (31821, 'ruRU', 'Новый уровень!', 'Повысьте уровень питомца до 3-го.', 'Замечательно. Очень важно следить за здоровьем питомца, чтобы он всегда был готов к битве.$b$bВот мое следующее задание: проведи несколько битв и повысь уровень одного питомца до 3-го. После этого возвращайся ко мне и мы поговорим о том, как научиться ловить питомцев для себя!', '', '', '', '', '', '', 25549);
