INSERT INTO `quest_template_locale` VALUES (31833, 'ruRU', 'Продолжение тренировок: мастер Ву', 'Поговорите с мастером Ву на пике Безмятежности и завершите ваши совместные тренировки.', 'И снова добро пожаловать, $n. Пришло время продолжить твои тренировки. Спустись на тренировочную площадку и поговори там с мастером Ву, чтобы начать следующий урок.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31834, 'ruRU', 'Начало тренировок: мастер Чэн', 'Поговорите с мастером Чэн на Пике Безмятежности и завершите ваши совместные тренировки.', 'Приветствую, $n. Добро пожаловать на пик Безмятежности. Именно здесь монахи проводят свои тренировки и оттачивают навыки боевых искусств. Пришло время и тебе присоединиться к ним. Чтобы приступить к занятиям, спустись на тренировочную площадку и поговори с мастером Чэн.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31835, 'ruRU', 'Продолжение тренировок: мастер Кистан', 'Поговорите с мастером Кистан на пике Безмятежности и завершите ваши совместные тренировки.', 'И снова добро пожаловать, $n. Пришло время продолжить твои тренировки. Спустись на тренировочную площадку и поговори там с мастером Кистан, чтобы начать следующий урок.', '', '', '', '', '', '', 25549);
