INSERT INTO `quest_template_locale` VALUES (31840, 'ruRU', 'Через практику к совершенству: мастер Чэн', 'Поговорите с мастером Чэн на пике Безмятежности и примите участие в поединке с ним.', 'Добро пожаловать, $n. Вижу, ты $gрешил:решила; отточить свои навыки. Чтобы приступить к занятиям, спустись на тренировочную площадку и поговори с мастером Чэн.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31841, 'ruRU', 'Через практику к совершенству: мастер Ву', 'Поговорите с мастером Ву на пике Безмятежности и начните ваши совместные тренировки.', 'Добро пожаловать, $n. Вижу, ты $gрешил:решила; отточить свои навыки. Чтобы приступить к занятиям, спустись на тренировочную площадку и поговори с мастером Ву.', '', '', '', '', '', '', 25549);
