INSERT INTO `quest_template_locale` VALUES (31846, 'ruRU', 'Через практику к совершенству: мастер Хсу', 'Поговорите с мастером Хсу на пике Безмятежности и примите участие в поединке с ним.', 'Добро пожаловать, $n. Вижу, ты $gрешил:решила; отточить свои навыки. Чтобы приступить к занятиям, спустись на тренировочную площадку и поговори с мастером Хсу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31847, 'ruRU', 'Жуткое место', 'Поговорите с лучницей Ли на Змеином Хребте.', 'Я уверен, многие наши союзники захотят прибегнуть к твоим услугам после нашей победы. Но сейчас я получил просьбу о помощи от защитников стены в Жутких пустошах.\n\nЕсли хочешь откликнуться на их призыв, бери воздушного змея и отправляйся к лучнице Ли.', '', '', '', '', '', 'Поговорите с лучницей Ли на Змеином Хребте.', 25549);
INSERT INTO `quest_template_locale` VALUES (31850, 'ruRU', 'Эрик Дэвидсон', 'Победите Эрика Дэвидсона в битве питомцев.', 'Итак, ты снова $gявился:явилась; в лес, чтобы вызвать меня на бой. Мои смертоносные питомцы принимают твой дерзкий вызов.', '', '', '', 'Превосходно!', 'Маркус Йенсен', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31851, 'ruRU', 'Билл Баклер', 'Победите Билла Баклера в битве питомцев.', 'Ну что, $gявился:явилась; попробовать еще разок?$B$BСейаас узнаешь, почему меня называют \"ужасом долины\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31852, 'ruRU', 'Стивен Лисбен', 'Победите Стивена Лисбена в битве питомцев.', 'Ты осмеливаешься снова бросить мне вызов? На этот раз я выйду победителем в битве!', '', '', '', 'Ну и зрелище!', 'Маркус Йенсен', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31853, 'ruRU', 'Все на борт!', 'Поговорите с генералом Назгримом на борту корабля \"Кулак Адского Крика\".', '$gСлыхал:Слыхала;, $n? Мне нужна команда опытных бойцов для опасного задания.$b$bНужно как следует потрепать Альянс, и ты отправляешься со мной!$b$bМы не вернемся, пока не выполним задачу, так что собирай вещи и готовься.$b$bЯ буду на борту свежеотстроенного боевого судна над бухтой Острорука.$b$bНе заставляй меня ждать!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31854, 'ruRU', 'Аналинн', 'Победите Аналинн в битве питомцев.', 'Вижу, ты снова меня $gнашел:нашла;. Видимо, хочешь снова вызвать меня на бой? Что ж, я не против.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31855, 'ruRU', 'Пик Безмятежности - продолжение обучения', 'Воспользуйтесь способностью \"Духовное путешествие\", чтобы отправиться на пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время вернуться на пик Безмятежности и продолжить твои тренировки. Воспользуйся способностью \"Духовное путешествие\" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 25549);
INSERT INTO `quest_template_locale` VALUES (31856, 'ruRU', 'Пик Безмятежности – начало обучения', 'Воспользуйтесь способностью \"Духовное путешествие\", чтобы отправиться на пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время отправиться на пик Безмятежности и начать твои тренировки. Воспользуйся способностью \"Духовное путешествие\" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 25549);
INSERT INTO `quest_template_locale` VALUES (31857, 'ruRU', 'Пик Безмятежности - продолжение обучения', 'Воспользуйтесь способностью \"Духовное путешествие\", чтобы отправиться на пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время вернуться на пик Безмятежности и продолжить твои тренировки. Воспользуйся способностью \"Духовное путешествие\" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 25549);
