INSERT INTO `quest_template_locale` VALUES (31862, 'ruRU', 'Зоня Садистка', 'Победите Зоню Садистку в битве питомцев.', 'Добыча сама идет в лапы хищника, даже не подозревая об опасности. На этот раз Зоня с тобой позабавится.', '', '', '', '', '', '', 25549);
