INSERT INTO `quest_template_locale` VALUES (31966, 'ruRU', 'Укротители боевых питомцев: Cataclysm', 'Победите Брока, Бордина Крепкорука и Гоза Гибельную Ярость в битвах питомцев.', 'Тебе удалось победить лучших укротителей Нордскола, но прежде чем ты предстанешь перед мастерами Пандарии, тебе надо победить нескольких укротителей: Брока на горе Хиджал, Бордина Крепкорука в Подземье и Гоза Гибельную Ярость в Сумеречном нагорье.$B$BТолько после победы над ними ты будешь $gготов:готова; отправиться покорять Пандарию.', '', 'Покажи свои лучшие стороны!', 'Одри Бернхеп', 'Ну что, начнем?', 'Одри Бернхеп', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31967, 'ruRU', 'Укротители боевых питомцев: Cataclysm', 'Победите Брока, Бордина Крепкорука и Гоза Гибельную Ярость в битвах питомцев.', 'Тебе покорился Нордскол, но ты еще не $gготов:готова; сразиться с мастерами Пандарии. Чтобы укрепить свой дух, тебе надо победить нескольких укротителей: Брока на горе Хиджал, Бордина Крепкорука в Подземье и Гоза Гибельную Ярость в Сумеречном нагорье.$B$BТолько после победы над ними ты будешь $gготов:готова; отправиться покорять Пандарию.', '', 'Теперь ты не можешь проиграть.', 'Варзок', 'Думаешь, пришло время для следующего поединка?', 'Варзок', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31969, 'ruRU', 'Выбор приоритетов', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31970, 'ruRU', 'Великий укротитель Обалис', 'Победите Обалиса в битве питомцев.', 'Думаешь, ты $gготов:готова; бросить вызов Пандарии? Ты правда считаешь, что можешь победить величайших укротителей Азерота?$B$BПосмотрим, |3-6($r). Встретимся у запруды Вир\'Наал в Ульдуме и посмотрим, на что ты $gспособен:способна;.', '', 'Жду не дождусь битвы с тобой.', 'Обалис', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31971, 'ruRU', 'Великий укротитель Обалис', 'Победите Обалиса в битве питомцев.', 'Вижу, великий укротитель снова здесь. Хочешь сразиться еще раз? Хорошо. Я принимаю твой вызов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31972, 'ruRU', 'Брок', 'Победите Брока в битве питомцев.', 'Я пока не очень хорошо понимаю, чего от меня хотят эти крохи. Может, еще одна битва укрепит связь между нами?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31973, 'ruRU', 'Бордин Крепкорук', 'Победите Бордина Крепкорука в битве питомцев.', 'Местные жители научили меня чувствовать силу земли. Ее поддержка никогда не ослабевает. Давай сразимся еще раз, и ты увидишь, как я силен!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31974, 'ruRU', 'Гоз Гибельная Ярость', 'Победите Гоза Гибельную Ярость в битве питомцев.', 'По моим венам течет сила сумерек. Я – бог! У тебя нет шансов против меня!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31975, 'ruRU', 'Возвращение героя', 'Обратитесь к Одри Бернхеп в Штормграде.', 'Я считаю, что тебе самое место среди всяких дельцов из Запределья. Возвращайся-ка в Штормград к Одри Бернхеп и спроси у нее, что делать дальше!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31976, 'ruRU', 'Возвращение героя', 'Обратитесь к Одри Бернхеп в Штормграде.', 'Все только и говорят, что о твоих боевых навыках. Возвращайся к Одри Бернхеп за дальнейшими указаниями.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31977, 'ruRU', 'Возвращение героя', 'Обратитесь к Варзоку в Оргриммаре.', 'Я считаю, что тебе самое место среди всяких дельцов из Запределья. Возвращайся-ка в Оргриммар к Варзоку и спроси у него, что делать дальше!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31978, 'ruRU', 'Приоритеты!', 'Найдите 6 бочек медового хмеля на поляне Медовой Росы.', 'Только посмотрите на этот бардак! Весь хмель пропал!$b$bТажань Чжу предупреждал, чтобы мы держались от подальше от чужаков, но сейчас нам пригодится любая помощь.$b$bМы везли хмель в Цветущую Зарю, как вдруг начался бой. И все наше добро пропало!$b$bХочешь помочь нам? Может быть, ты найдешь какие-нибудь уцелевшие бочки с медовым хмелем? Тогда наши потери не будут столь ужасными.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31980, 'ruRU', 'Возвращение героя', 'Обратитесь к Варзоку в Оргриммаре.', 'Все только и говорят, что о твоих боевых навыках. Возвращайся к Варзоку за дальнейшими указаниями.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31981, 'ruRU', 'Превосходный ученик', 'Обратитесь к Одри Бернхеп в Штормграде.', 'Беги к своей наставнице, Одри Бернхеп, в Штормград. Может быть, она посчитает тебя более... $gдостойным:достойной;... для поединков.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31982, 'ruRU', 'Превосходный ученик', 'Обратитесь к Варзоку в Оргриммаре.', 'Беги к своему наставнику, Варзоку, в Оргриммар. Может быть, он посчитает тебя более... $gдостойным:достойной;... для поединков.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31983, 'ruRU', 'Краткая отсрочка', 'Обратитесь к Варзоку в Оргриммаре.', 'Для |3-1($r) ты отлично $gсправился:справилась;. Теперь возвращайся в Оргриммар и поговори с этим грубияном Варзоком. Может быть, он отправит тебя куда-нибудь подальше от моей семьи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31984, 'ruRU', 'Краткая отсрочка', 'Обратитесь к Одри Бернхеп в Штормграде.', 'Здорово, действительно здорово! А теперь, пожалуйста, возвращайся к Одри Бернхеп в Штормград.$b$bДа, и передай ей от меня привет. Этой прелестной молодой женщине может пригодиться компания такого опытного бойца, как я.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31985, 'ruRU', 'Триумфальное возвращение', 'Обратитесь к Одри Бернхеп в Штормграде.', 'По мнению твоего наставника, теперь ты полностью $gготов:готова;. Возвращайся в Штормград и поговори с Одри Бернхеп. Она расскажет тебе, что делать дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31986, 'ruRU', 'Триумфальное возвращение', 'Обратитесь к Варзоку в Оргриммаре.', 'По мнению твоего наставника, теперь ты полностью $gготов:готова;. Возвращайся в Штормград и поговори с Варзоком. Он расскажет тебе, что делать дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (31989, 'ruRU', 'Пик Безмятежности - завершение обучения', 'Воспользуйтесь способностью \"Духовное путешествие\", чтобы отправиться на пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время вернуться на пик Безмятежности и закончить твои тренировки. Воспользуйся способностью \"Духовное путешествие\" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 25549);
INSERT INTO `quest_template_locale` VALUES (31990, 'ruRU', 'Одри Бернхеп', 'Обратитесь к Одри Бернхеп в Штормграде.', 'Боюсь, я ничему не могу научить тебя, $n. Однако твой путь, как дрессировщика питомцев, еще далек от завершения!$b$bПоговори с Одри Бернхеп в Штормграде. Она знакома со многими из лучших дрессировщиков Азерота и поможет тебе в твоем дальнейшем обучении.', '', '', 'Грейди Баннсон', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31991, 'ruRU', 'Великий укротитель Зусши', 'Победите искателя Зусши в битве питомцев.', 'Я знал, что рано или поздно ты вернешься, чтобы еще раз сразиться со мной. Давай посмотрим, в ком из нас больше тактической мудрости.', '', '', '', '', '', '', 25549);
