INSERT INTO `quest_template_locale` VALUES (31997, 'ruRU', '[FLAG] Dread Wastes Buff Bitflag - Augmentation 03', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (31999, 'ruRU', 'Приказ Назгрима', 'Поговорите с генералом Назгримом на Взлетной полосе Сильной Руки в Нефритовом лесу.', 'Что ж, теперь у тебя имеется удобная база для вылазок, Альянсом даже и не пахнет, а несколько ветеранов Орды готовы к приказаниям. Пора приступать к завоеванию континента.$b$bГенерал Назгрим знает, с чего начать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32003, 'ruRU', 'Серьезное испытание: Райгонн', 'Пройдите Врата Заходящего Солнца в режиме испытания.', 'Я хочу, чтобы ты $gсобрал:собрала; могучую группу и $gотправился:отправилась; к Вратам Заходящего Солнца. Когда прибудешь на место, задействуй сферу испытания и сокруши Райгонна.$B$BВозвращайся ко мне за наградой, когда завершишь это испытание.', '', '', '', '', '', 'Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (32005, 'ruRU', 'Серьезное испытание: Дюранд', 'Пройдите Монастырь Алого ордена в режиме испытания.', 'Я хочу, чтобы ты $gсобрал:собрала; храбрую группу и $gотправился:отправилась; в Монастырь Алого ордена. Когда прибудешь на место, задействуй сферу испытания и покарай Дюранда.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.', '', '', '', '', '', 'Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (32007, 'ruRU', 'Серьезное испытание: темный магистр Гандлинг', 'Пройдите Некроситет в режиме испытания.', 'Я хочу, чтобы ты $gсобрал:собрала; бесстрашную группу и $gотправился:отправилась; в Некроситет. Когда прибудешь на место, задействуй сферу испытания и очисти Некроситет от тлетворного влияния темного магистра Гандлинга.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.', '', '', '', '', '', 'Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (32008, 'ruRU', 'Одри Бернхеп', 'Обратитесь к Одри Бернхеп в Штормграде.', 'Приветствую тебя, $n! Меня зовут Одри Бернхеп. Я много о тебе слышала. Ты становишься $gизвестным укротителем:известной укротительницей; питомцев!$b$bТебе следует поговорить со мной в Штормграде. Я знакома со многими из лучших укротителей питомцев Азерота, и я могу помочь тебе стать еще опытнее!', '', 'Не могу дождаться встречи с тобой!', 'Одри Бернхеп', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32009, 'ruRU', 'Варзок', 'Поговорите с Варзоком в Оргриммаре.', 'Лок\'тар, $n. Меня зовут Варзок. Я многое слышал о твоих успехах в качестве $gукротителя:укротительницы; боевых питомцев, и я хочу познакомить тебя с другими укротителями Азерота, чтобы ты $gпродолжал:продолжала; оттачивать свои навыки.$b$bПоговори со мной в Оргриммаре, и мы начнем.', '', 'Я ждал встречи с тобой.', 'Варзок', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32010, 'ruRU', 'Небесное задание', 'Добейтесь того, чтобы к вам относились с почтением в Золотом Лотосе.', 'Ты знаешь об Августейших небожителях? Юй-лун, Чи-Цзи, Сюэнь и Нюцзао хранят Пандарию, оберегая ее с четырех сторон света.$b$bОни наблюдают и за тобой.$b$bНебожители владеют древними и могущественными знаниями. Тех, кому они благоволят, они могут одарить невероятной силой.$b$bВозможно, ты стремишься завоевать их доверие. Но у тебя есть более серьезная задача.$b$bВечноцветущий дол в опасности. Прежде всего, мы все должны защищать его. А уже потом мы сможем обратить внимание на Августейших небожителей.', '', '', '', '', '', 'Поговорите с мудрецом Цветком Лотоса в Святилище Двух Лун, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (32011, 'ruRU', 'Небесное задание', 'Добейтесь того, чтобы к вам относились с почтением в Золотом Лотосе.', 'Ты знаешь об Августейших небожителях? Юй-лун, Чи-Цзи, Сюэнь и Нюцзао хранят Пандарию, оберегая ее с четырех сторон света.$b$bОни наблюдают и за тобой.$b$bНебожители владеют древними и могущественными знаниями. Тех, кому они благоволят, они могут одарить невероятной силой.$b$bВозможно, ты стремишься завоевать их доверие. Но у тебя есть более серьезная задача.$b$bВечноцветущий дол в опасности. Прежде всего, мы все должны защищать его. А уже потом мы сможем обратить внимание на Августейших небожителей.', '', '', '', '', '', 'Поговорите с мудрецом Белое Сердце в Святилище Семи Звезд, что в Вечноцветущем доле.', 19865);
INSERT INTO `quest_template_locale` VALUES (32012, 'ruRU', 'Kovok tracking [GROWING]', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32016, 'ruRU', 'Большие амулеты удачи', 'Соберите 90 малых амулетов удачи.', 'Приветствую тебя, $n. Мне выпала честь предоставить тебе прекрасную возможность. Несколько столетий мы совершенствовали метод, который позволяет влиять даже на законы вероятности. Если у тебя будет большой амулет удачи, ты сможешь находить ценные артефакты гораздо чаще.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32017, 'ruRU', 'Большие амулеты удачи', 'Соберите 90 малых амулетов удачи.', 'Приветствую тебя, $n. Мне выпала честь предоставить тебе прекрасную возможность. Несколько столетий мы совершенствовали метод, который позволяет влиять даже на законы вероятности. Если у тебя будет большой амулет удачи, ты сможешь находить ценные артефакты гораздо чаще.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32018, 'ruRU', 'Его звали... Буйный Портер', 'Поговорите с Чэнем Буйным Портером на лугах Громовой Пяты, что в долине Четырех Ветров.', 'Несколько дней назад в городе появился необычный пандарен. Он рассказал байку поинтереснее, чем у Паня, выпил вдвое больше Ли, да еще и поколотил меня у дверей бара. А в это время его маленькая племянница насмехалась над нами.$b$bЭто было незабываемо.$b$bОни сказали, что направляются в долину Четырех Ветров. Ты $gдолжен:должна; познакомиться с ним! Только... опасайся его удара справа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32019, 'ruRU', 'Его звали... Буйный Портер', 'Поговорите с Чэнем Буйным Портером на лугах Громовой Пяты, что в долине Четырех Ветров.', 'Не всегда дела обстояли так плохо, |3-6($r). В смысле, все было еще хуже. Около трех недель назад нашу деревню взяли в кольцо разбойники-сауроки. Они вынесли весь нефрит, разгромили продовольственные лавки и перепугали детей.$b$bМы надеялись, что найдется герой, который нас спасет. И вот он пришел.$b$bОн оттеснил сауроков, уничтожил их главаря и вернул нам украденный нефрит. В награду он попросил только прокатить его племянницу на змее.$b$bУ меня не было возможности отблагодарить его по-настоящему. Если ты направляешься в долину Четырех Ветров, то, может быть, передашь ему от нас спасибо?', '', '', '', '', '', '', 25549);
