INSERT INTO `quest_template_locale` VALUES (32030, 'ruRU', 'Раз в тысячу лет', 'Поговорите с клакси\'ва Ик в Клакси\'весс.', 'Время пришло, Пробудитель.$b$bСила совета сокрушит падшую императрицу.$b$bЭтот ритуал не проводился многие тысячи лет, и ни разу еще при нем не присутствовал чужестранец.$b$bВ знак нашей благодарности за твои деяния я приглашаю тебя стать $gсвидетелем:свидетельницей; этого великого исторического события.', '', 'Возвращайся в Клакси\'весс и стань свидетелем обновления нашей империи.', 'Клакси\'ва Ик', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32031, 'ruRU', 'Кулек конфет', '', '', '', '', '', '', '', '', 25549);
