INSERT INTO `quest_template_locale` VALUES (32035, 'ruRU', 'Запах шелка', 'Поговорите с шелкоделом Цаем на Шелковых полях в долине Четырех Ветров.', 'Со стороны Шелковых полей доносится странный шум.$b$bДа и странный запах.$b$bПохоже, там пригодятся услуги $gтакого:такой:c; |3-1($c) как ты. Не за просто так, конечно. Это возможность заработать пару монет.$b$bА может, и нет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32036, 'ruRU', 'Кулек конфет', '', '', '', '', '', '', '', '', 25549);
