INSERT INTO `quest_template_locale` VALUES (32038, 'ruRU', 'Искусство охоты на оленей', 'Убейте 10 оленей пустошей.', 'Я всегда любил поохотиться на оленей. Олени сильные и быстрые животные и защищают свою территорию.$b$bХоть они и питаются одной травой, но бегают так, что охотнику приходится попотеть, чтобы их поймать.$b$bК востоку отсюда полно оленей пустошей. Они только и ждут, чтобы какой-нибудь охотник устроил им хорошую пробежку.$b$bУдачной охоты.', '', '', '', '', '', '', 25549);
