INSERT INTO `quest_template_locale` VALUES (32045, 'ruRU', 'Дети воды', 'Убейте Красора, Громожабра и Суккулу.', 'Здесь, в долине Четырех Ветров мы все – дети воды. Она питает нас, помогает растить наши овощи, несет нам жизнь.$b$bНо некоторые существа пьют слишком много воды и вырастают до огромных размеров. Нужно уничтожить их до того, как они стали угрозой для окружающих.$b$bЯ – простой резчик по камню. Но вот ты...', '', '', '', '', '', '', 25549);
