INSERT INTO `quest_template_locale` VALUES (32690, 'ruRU', 'Безупречные останки Идеала', 'Выставите артефакт на обозрение.', 'Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32691, 'ruRU', 'Безупречная лампа богомолов', 'Выставите артефакт на обозрение.', 'Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32692, 'ruRU', 'Безупречный сборник пыльцы', 'Выставите артефакт на обозрение.', 'Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.', '', '', '', '', '', 'Выставите артефакт в Обители Мудрости.', 19865);
INSERT INTO `quest_template_locale` VALUES (32693, 'ruRU', 'Безупречный резервуар для сока кипари ', 'Выставите артефакт на обозрение.', 'Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.', '', '', '', '', '', '', 25549);
