INSERT INTO `quest_template_locale` VALUES (32754, 'ruRU', 'Кон Железный убит', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32755, 'ruRU', 'Наложницы-близнецы убиты', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32756, 'ruRU', 'Лэй Шэнь убит', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32783, 'ruRU', 'Месть Га\'нара', 'Найдите Га\'нара у Ущелья Кинжальной Пасти.', 'Мой брат туп, как его топор, а упрямства в нем хватит на целого гронна!$B$BГа\'нар взял с собой несколько наших лучших воинов и направился на север, в Ущелье Кинжальной Пасти. Если они все еще там, тебе нужно будет их найти. Меня Га\'нар точно не послушает.$B$BЕсли иначе не получится, помоги ему отомстить – только, пожалуйста, уговори вернуться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32791, 'ruRU', 'Пришло время охоты!', 'Бросьте вызов Гротану Глашатаю.', 'Нет времени слушать нытье моего брата. Цель нашей охоты – либо сладкая месть, либо доблестная смерть.$b$bВождь клана Громоборцев убил моего отца и оставил меня умирать. В ответ я заберу трех его сыновей. Первый – этот малец.$b$bОн выдал нам и число Громоборцев в ущелье, и их позиции.$b$bЕсли не боишься, идем с нами. Покажем тебе, как сражаются истинные воины клана Северного Волка. Встанешь у меня на пути – попрощаешься с жизнью.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32792, 'ruRU', 'Пленных не брать!', 'Убейте Кур\'ака Связывающего, сожгите припасы и уничтожьте катапульты клана Громоборцев.', 'Моему терпению пришел конец: клан Громоборцев поплатится за все.$b$bИдем на восток! Никого не щадить! Припасы уничтожать! Не оставим им ни малейшей надежды.$b$bСбор после битвы – на Диком Утесе к востоку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32794, 'ruRU', 'Гнев гроннов', 'Освободите $1oa |4пойманного гронна:пойманных гроннов:пойманных гроннов;. ', 'Клан Громоборцев отлавливает гроннов для Железной Орды. Пусть эти глупцы на собственной шкуре прочувствуют, что гронны – не домашние животные.$b$bСледуй за нами в Грот Груллока и разбей цепи пойманных гроннов. Освободившись, они сами отомстят своим обидчикам.$b$bКогда закончишь, отправляйся в Логово Груллока под гротом. Мы будем ждать тебя там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32795, 'ruRU', 'Старший', 'Помогите Га\'нару отомстить за смерть отца.', 'Это Хаток, старший сын Железного Волка. Он – один из величайших охотников клана Громоборцев.$b$bОн видел, как его отец убил моего отца и оставил меня умирать.$b$bОн пожалеет, что не довел дело до конца.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32796, 'ruRU', 'В гарнизон', 'Встретьтесь с Дуротаном перед гарнизоном на Хребте Ледяного Огня.', 'Я отомстил за своего отца. Сыновья Железного Волка повержены.$b$bОтправляйся в гарнизон, что строят на юге. Передай моему увальню братцу, что я возвращаюсь.$b$bНадеюсь, теперь этот \"вождь\" поймет, что значит быть Северным Волком.', '', '', '', '', '', 'Встретьтесь с Дуротаном перед гарнизоном на Хребте Ледяного Огня.', 25549);
INSERT INTO `quest_template_locale` VALUES (32803, 'ruRU', 'Treasure: Thunderlord Cache 01', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32804, 'ruRU', 'Вещи павших братьев', 'Раздобудьте $1oa |4артефакт:артефакта:артефактов; погибших орков из клана Северного Волка.', 'В погоне за местью надлежит помнить о благородстве, которое надлежит сохранять каждому члену нашего клана.$b$bВ гроте под нами лежат тела славных орков из клана Северного Волка. Мы должны чтить их память.$b$bВыполняя задание Га\'нара, найди вещи наших павших братьев. Принеси их мне, они потребуются нашему шаману, чтобы провести обряд захоронения, как того требуют наши обычаи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32806, 'ruRU', 'Король и Совет', 'Пройдите сценарий \"Кровь на снегу\". Чтобы встать в очередь, воспользуйтесь поиском подземелий или выпейте хмель глубоких раздумий хранителя истории Чо.', 'Хорошо, что ты здесь, $n. Хмель глубоких раздумий помогает мне узнать, что творится в мире, но чем больше я узнаю, тем меньше понимаю.$b$bК примеру, король Ринн попросил дворфов Стальгорна предоставить ему больше войск, но не все дворфы поддерживают его.$b$bЯ расскажу тебе больше, но сперва мне хотелось бы узнать о твоих приключениях от тебя лично...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32807, 'ruRU', 'Вождь и тьма', 'Пройдите сценарий \"Темное сердце Пандарии\". Для этого можно встать в очередь в системе поиска подземелий или выпить хмель глубоких раздумий хранителя истории Чо.', 'Теперь я вижу, как король Альянса ведет свой народ. Но что же задумал вождь Орды? Прямо под нами толпы гоблинов роют туннели по его приказу. Что он надеется найти? Мы должны выяснить!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32812, 'ruRU', 'Восстание Черного Копья', 'Отправляйтесь в Дуротар и поговорите с Ки\'той Стрелоклыком в деревне Сен\'джин. ', 'Хмель глубоких раздумий позволяет мне увидеть не все. Видения рассеяны в пространстве и времени. Но ясно, что в Орде разгорается большой конфликт.$b$bВидения говорят мне, что тролль Вол\'джин из племени Черного Копья уже отправился в Дуротар, чтобы защищать свой народ. Его сопровождает Чэнь Буйный Портер, хмелевар со Скитающегося острова.$b$bУж если я что и знаю про Чэня, так это то, что бедокурить он мастер, каких мало... Поторопись же!', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32813, 'ruRU', 'Битва в деревне Сен\'джин', 'Защитите деревню Сен\'джин от нападения кор\'кронских бойцов.', '<Гул боевых барабанов слышен в отдалении.>$b$b$c, ты снова в нужном месте в нужное время. Адский Крик пошел против своего народа.$b$bХочет узнать, что будет, если поссориться с Черным Копьем. Вперед! Бейся с нами бок о бок! Пусть он увидит настоящий дух Орды!', '', '', '', '', '', 'Вернитесь к Вол\'джину в деревню Сен\'джин в Дуротаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (32814, 'ruRU', 'Битва за Колючий Холм', 'Освободите 6 пленных и одолейте кор\'кронских командиров, чтобы помочь восставшим троллям из племени Черного Копья захватить Колючий Холм.', 'Ударим прямо сейчас! Не дадим Адскому Крику опомниться. На север! Пора резать кор\'кронским солдатам глотки.$b$bЕсли возьмем Колючий Холм, все дороги в Дуротаре будут наши.$b$bВперед! Давай за мной!', '', '', '', '', '', 'Поговорите с Вол\'джином под сторожевой башней Колючего Холма в Дуротаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (32815, 'ruRU', 'Старый провидец', 'Найдите провидца Хао Фам Жу на склоне горы Неутомимых, что на вершине Кунь-Лай.', 'Я могу помочь разузнать разные детали, но общую картину тебе придется составить самостоятельно. И я знаю, где ты можешь этим заняться.$b$bДо меня доходили рассказы о старом провидце по имени Хао Фам Жу. Он отлично осведомлен об истории Пандарии и может помочь пролить свет на нынешние события.$B$BНайди его, $n. Насколько мне известно, он собирался пройти путем императора и взойти на гору Неутомимых у Вершины Кунь-Лай.', '', '', '', '', '', 'Найдите провидца Хао Фам Жу на склоне горы Неутомимых, что на вершине Кунь-Лай.', 25549);
INSERT INTO `quest_template_locale` VALUES (32816, 'ruRU', 'Путь последнего императора', 'Прикрепите веревку к каждому столбику на пути, чтобы помочь провидцу Хао Фам Жу добраться до Лагеря Искателя.', 'Когда последнего императора стали одолевать сомнения, он начал в одиночку взбираться на эту гору, пока наконец не нашел ответы на свои вопросы.$b$bЯ пришел сюда, чтобы проделать тот же путь, и мне кажется, что у тебя тоже есть вопросы без ответа. Не пойти ли нам дальше вдвоем, чтобы обоим обрести то, что мы ищем?$b$bВот только староват я уже, от пурги ломит кости. Ты можешь забраться повыше и закрепить там эту веревку? А я уже отсюда по ней поднимусь.$b$bВместе мы пойдем путем последнего императора.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32817, 'ruRU', 'Пройдите сценарий \"Кровь на снегу\"', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32818, 'ruRU', 'Пройдите сценарий \"Темное сердце Пандарии\"', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32819, 'ruRU', 'Поле битвы: Степи', 'Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.', 'Чтобы восстать против вождя, мне понадобится армия и припасы.$b$bАрмия у меня есть, и моим солдатам не занимать ненависти к Адскому Крику за все, что он сотворил с Ордой. А вот древесины, мяса, нефти и камня не хватает.$b$bК счастью для нас, солдаты Кор\'крон все это запасают к западу отсюда, в Северных Степях, причем в огромных количествах. Убивай всех кор\'кронцев, которые будут встречаться тебе на пути, а еще помоги нашим братьям-тауренам с охраной караванов и найди помощников для расправы над командирами Кор\'крона.', '', '', '', '', '', 'Вернитесь к Вол\'джину в деревню Сен\'джин в Дуротаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (32832, 'ruRU', 'Сцена с Тажанем Чжу и Дезко', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32836, 'ruRU', 'Скрипучая флейта', 'Верните скрипучую флейту кому-нибудь из вашей бойцовской гильдии.', 'Эта скрипучая флейта наскоро вырезана из корня дерева, а по всей ее длине неравномерно проделаны отверстия.$b$bПри внимательном осмотре задней части обнаруживается вырезанная в дереве надпись:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32837, 'ruRU', 'Дедушка Скрипучая Флейта', 'Приобретите карточку вызова дедушки Скрипучей Флейты, вызовите Дедушку на поединок в бойцовской гильдии и победите его.', 'Карточка вызова, которая может сегодня стать твоей, принадлежит груммелю с чудесным именем дедушка Скрипучая Флейта. Хоть груммели и не отличаются особым боевым мастерством, везения этим малышам не занимать.$b$bВозможно, все дело в их... как там они их называют... удачках?', '', '', '', '', '', 'Вернитесь к продавцу карт вашей бойцовской гильдии.', 19865);
INSERT INTO `quest_template_locale` VALUES (32838, 'ruRU', 'Сказка о любви и благородстве', 'Верните \"Медведя и прекрасную даму\" кому-нибудь из вашей бойцовской гильдии.', 'Маленькая детская книжка. Она хорошо переплетена и неплохо сохранилась.$b$bНа задней стороне книги рядом с переплетом вы замечаете надпись:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32839, 'ruRU', 'Медведь и прекрасная дама', 'Приобретите карточку вызова медведя и прекрасной дамы, вызовите их на поединок в бойцовской гильдии и одержите над ними победу.', 'Эта карточка дает тебе право сразиться с двумя весьма необычными личностями. Пожалуй, больше мне и добавить-то нечего.$b$bПриобрети карточку вызова, и $gсам:сама; все увидишь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32840, 'ruRU', 'Фитиль Бум-Бума', 'Верните фитиль Бум-Бума кому-нибудь из вашей бойцовской гильдии.', 'Из ошметков хозенского мяса и шерсти, летающих туда-сюда вокруг Коту Кон, сеющей хаос и разрушение, вам удалось выхватить небольшой фитиль.$b$bВесь фитиль сплетен из спутанных волос с хвоста хозена. Он издает сильный запах.$b$bК одному из концов фитиля прикреплен небольшой бумажный ярлычок с надписью:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32841, 'ruRU', 'Мастер Бум-Бум', 'Приобретите карточку вызова мастера Бум-Бума, вызовите его на поединок в бойцовской гильдии и победите.', 'Ты $gнашел:нашла; карточку, принадлежащую хозену-бомбометателю по имени мастер Бум-Бум.$b$bХозены в большинстве своем любят разрушительную мощь взрывов, но мало кому из них удается научиться обращению с бомбами, не подорвав при этом себя. Мастер Бум-Бум – исключение.$b$bУдачи тебе!', '', '', '', '', '', 'Вернитесь к продавцу карт вашей бойцовской гильдии.', 19865);
INSERT INTO `quest_template_locale` VALUES (32842, 'ruRU', 'Зубы, похожие на мечи', 'Верните невероятно острый зуб кому-нибудь из вашей бойцовской гильдии.', 'Зуб оканчивается острой кромкой, будто его заточили специально. Сразу видно, что он принадлежал злобному чудовищу.$b$bОсторожно разглядывая зуб, вы замечаете, что на его эмали тщательно вырезана надпись:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32843, 'ruRU', 'Щербохмыл', 'Приобретите карточку вызова Щербохмыла, вызовите его на поединок в бойцовской гильдии и победите.', 'Эта карточка дает тебе право сразиться с одним из самых опасных созданий Южных морей – Щербохмылом. Один укус такими зубами – и от тебя останется только не поддающаяся опознанию груда кожи и кишок в луже крови.$b$bВсего хорошего!', '', '', '', '', '', 'Вернитесь к продавцу карт вашей бойцовской гильдии.', 19865);
INSERT INTO `quest_template_locale` VALUES (32844, 'ruRU', 'Секрет неизвестной жидкости', 'Верните склянку с красноватой жидкостью кому-нибудь из вашей бойцовской гильдии.', 'Содержимое склянки неистово бурлит и вскипает, из-за чего сама склянка дрожит у вас в руках. Вглядываясь в нее, вы смутно различаете образ чьего-то злобного лица.$b$bЗатычка отлично подходит к горлышку склянки. Вдоль ее края искусно вырезана следующая надпись:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32845, 'ruRU', 'Бульк', 'Приобретите карточку вызова Бульк, вызовите ее на поединок в бойцовской гильдии и одержите победу.', 'Полагаю, с Блэтом, нашим гильдейским бойцом 2 ранга, ты уже $gзнаком:знакома;. Эта карточка дает тебе право сразиться с Бульк, его старшей сестрой. Она злобная.$b$bПостарайся не умереть. А если умрешь – то хотя бы сделай это так, чтобы наблюдать было интересно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32846, 'ruRU', 'Модифицированный рубильный аппарат', 'Верните модифицированный рубильный аппарат кому-нибудь из вашей бойцовской гильдии.', 'Вы, возможно, и не узнали бы в этом агрегате модифицированный рубильный аппарат, не будь на нем кривыми буквами выведена надпись \"МОДИФИЦИРОВАННЫЙ РУБИЛЬНЫЙ АППАРАТ\".$b$bПрямо под этикеткой вы замечаете еще одну, уже не такую большую, но гораздо более аккуратную надпись ярко-красными чернилами:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32847, 'ruRU', 'Меха-Брюс', 'Приобретите карточку вызова Меха-Брюса, вызовите его на поединок в бойцовской гильдии и победите.', 'Все знают Брюса. Все любят Брюса! И рано или поздно все убивают Брюса.$b$bОдному орку-охотнику с инженерным талантом это надоело, и он нашел себе кроколиска и слегка его модернизировал.$b$bЭта карточка вызова дает тебе право сразиться с Меха-Брюсом. Такой бой обязательно станет настоящей кровавой бойней. Весь вопрос в том, чья кровь прольется – твоя, или противника?', '', '', '', '', '', 'Вернитесь к продавцу карт вашей бойцовской гильдии.', 19865);
INSERT INTO `quest_template_locale` VALUES (32848, 'ruRU', 'Морозная скорлупа', 'Верните морозную скорлупу кому-нибудь из вашей бойцовской гильдии.', 'Это кусок скорлупы – вероятно, от пингвиньего яйца. Его края покрыты инеем, и по самому осколку видно, что яйцо, от которого он откололся, было огромным.$b$bК своему немалому удивлению вы замечаете на внутренней стороне осколка надпись нефритово-зелеными чернилами:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32849, 'ruRU', 'Тюка и Тяпа', 'Приобретите карточку вызова Тюки и Тяпы, вызовите их на поединок в бойцовской гильдии и победите.', 'Все ветераны бойцовской гильдии помнят пингвина Тюку. Тюка – не самый грозный боец гильдии, но и отнюдь не слабак!$b$bНет, ну с соображалкой у него, конечно, не очень...$b$bНеважно! Эта карточка дает вам право сразиться как с Тюкой, так и с его крупным старшим братцем Тяпой. Пусть оба они и туповаты, но это не значит, что им не по силам вас убить вдвоем или в одиночку.', '', '', '', '', '', 'Вернитесь к продавцу карт вашей бойцовской гильдии.', 19865);
INSERT INTO `quest_template_locale` VALUES (32850, 'ruRU', 'Прошлогодняя модель', 'Верните старого пыльного робота кому-нибудь из вашей бойцовской гильдии.', 'Этот робот в неважном состоянии. В нем есть несколько гнезд, в которых, как и у Блескотрона-4000, вероятно, были драгоценные камни, но теперь они пусты.$b$bВ пыли, покрывающей заднюю часть робота, блестит металлическая табличка с надписью:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32851, 'ruRU', 'Блескотрон-3000', 'Приобретите карточку вызова Блескотрона-3000, вызовите его на поединок в бойцовской гильдии и победите.', 'Серия Блескотронов не была особенно популярна до тех пор, пока на полки магазинов не попала модель 4000. Мало кто помнит о Блескотроне-3000, а ведь он в каком-то смысле был настоящим инженерным чудом!$b$bЭта карточка вызова дает тебе право сразиться с Блекскотроном-3000 прямо здесь, в бойцовской гильдии. $b$bВот это повезло!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32852, 'ruRU', 'Лопата мастера', 'Верните лопату мастера кому-нибудь из вашей бойцовской гильдии.', 'Совершенно обычная с виду лопата, на рукоятке которой затейливыми буквами вырезана надпись \"Лопата мастера\".$b$bНа обратной же стороне рукоятки видна надпись поменьше, сделанная буквами попроще:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32853, 'ruRU', 'Мингус Коппс', 'Приобретите карточку вызова Мингуса Коппса, вызовите его на поединок в бойцовской гильдии и победите.', 'Ты $gзаслужил:заслужила; право сразиться с археологом Мингусом Коппсом!$b$bНасколько мне известно, сам по себе Мингус не такой уж и страшный боец, но устроители боев позволяют ему приносить с собой на ринг отрытые им сокровища. Их-то и надо беречься больше всего.$b$bКогда будешь $gготов:готова;, смело покупай эту карточку!', '', '', '', '', '', 'Вернитесь к продавцу карт вашей бойцовской гильдии.', 19865);
INSERT INTO `quest_template_locale` VALUES (32854, 'ruRU', 'Изношенная повязка для глаз', 'Верните изношенную повязку для глаз кому-нибудь из вашей бойцовской гильдии.', 'Кусок ткани размером под среднюю человеческую голову. Ткань самая простая, без каких-либо украшений, если не считать маленького ярлычка на краю, на которой написано:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32855, 'ruRU', 'Слепой герой', 'Приобретите карточку вызова cлепого героя, вызовите его на поединок в бойцовской гильдии и победите.', 'Эта карточка дает тебе право сразиться со cлепым героем, таинственным воином минувшей эпохи. Никто не способен превзойти его во владении клинком. Никто.$b$bК счастью, он абсолютно слеп. Желаю повеселиться!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32856, 'ruRU', 'Обернутый в бумагу камень', 'Верните обернутый в бумагу камень кому-нибудь из вашей бойцовской гильдии.', 'Перед вами странная комбинация предметов. Камень, обернутый настолько толстым слоем бумаги, что он скрадывает его истинные размеры. Под этой бумагой камень кажется совсем маленьким. $b$bЕсли рассматривать бумагу на просвет, видно водяной знак и надпись:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32857, 'ruRU', 'Ро-Шамбо', 'Приобретите карточку вызова Ро-Шамбо, вызовите ее на поединок в бойцовской гильдии и победите.', 'Новая карточка дает тебе право сразиться с Ро-Шамбо, непонятным созданием из неизвестных краев.$b$bБерегись. Я слышала, у нее в запасе есть пара хитрых фокусов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32858, 'ruRU', 'Боксерские перчатки из шкуры ящера', 'Верните боксерские перчатки из шкуры ящера кому-нибудь из вашей бойцовской гильдии.', 'Швы на перчатках грубые, а шкуру, судя по запаху, обрабатывали слизью краба. Но сами перчатки при этом весьма прочные и удобные.$b$bНа изнанке перчаток видна следующая, логичная, в общем-то, надпись:$b$b\"Вернуть в бойцовскую гильдию\".', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32859, 'ruRU', 'Ти\'тар', 'Приобретите карточку вызова Ти\'тара, вызовите его на поединок в бойцовской гильдии и победите.', 'Ты $gзаслужил:заслужила; право приобрести карточку вызова, и принадлежит эта карточка троллю по имени Ти\'тар.$b$bТи\'тар обладает очень характерным боевым стилем, и тебе, как того требует соглашение с бойцовской гильдией, придется драться по его правилам – лицом к лицу, на кулаках и не убегать. До трех нокдаунов.$b$bУдачи!', '', '', '', '', '', 'Вернитесь к продавцу карт вашей бойцовской гильдии.', 19865);
INSERT INTO `quest_template_locale` VALUES (32860, 'ruRU', 'Битва за Колючий Холм – задание на отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32862, 'ruRU', 'Поле битвы: Степи', 'Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.', 'Наша работа далека от завершения, $n. Горят костры перемен, хотя их еще можно задуть.$B$BПринеси мне больше кор\'кронских припасов, и я тебя награжу.', '', '', '', '', '', 'Вернитесь к Ки\'те Стрелоклыку в деревню Сен\'джин или в Колючий Холм, что в Дуротаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (32863, 'ruRU', 'Ради чего мы обучались', 'Воспользуйтесь системой поиска боев и победите 10 игроков. Все питомцы из вашей команды должны быть 25 уровня.', 'Ты $gготов:готова; подвергнуть своих питомцев испытанию? На арене для боевых питомцев нет места хилым кроликам, туда стоит нести ракетобота, не меньше. Если у тебя есть три полностью обученных питомца, найди укротителей, примерно равных тебе по умениям, и устрой с ними бой. За подробностями обращайся в атлас питомцев.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32864, 'ruRU', 'Сбор разведданных – слежка за Рико', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32865, 'ruRU', 'Сбор разведданных – слежка за Назгримом', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32866, 'ruRU', 'Сбор разведданных – слежка за Зелой', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32867, 'ruRU', 'Вол\'джин из племени Черного Копья', 'Выслушайте Ки\'ту Стрелоклыка.', 'С возвращением в Сен\'джин. Знаю, ты $gпроделал:проделала; долгий путь, чтобы поговорить с Вол\'джином, предводителем Черного Копья.$B$BПрости, придется еще чуть подождать. Надо поговорить.', '', '', '', '', '', 'Поговорите с Вол\'джином в деревне Сен\'джин в Дуротаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (32868, 'ruRU', 'Звери из легенд, книга II', 'Победите Счастливчика И, Серое копытце и Быстролапого Кся.', 'В этих краях всегда будут рассказывать истории о Счастливчике И, Сером копытце и Быстролапом Кся. Хочешь сразиться с ними еще раз?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32869, 'ruRU', 'Звери из легенд, книга III', 'Победите Но-Но, Ти\'уна Странника и Кровоспина.', 'В этих краях всегда будут рассказывать истории о Но-Но, Ти\'уне Страннике и Кровоспине. Хочешь сразиться с ними еще раз?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32872, 'ruRU', 'Поле битвы: Степи', '[Еженедельное задание] Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.', 'Работа еще не окончена, |3-6($r). Если ты $gготов:готова; опять рискнуть головой, помогая Черному Копью, награда будет достойной.', '', '', '', '', '', 'Вернитесь к Ки\'те Стрелоклыку в Колючий Холм, что в Дуротаре.', 19865);
INSERT INTO `quest_template_locale` VALUES (32890, 'ruRU', 'FLAG – Caravan Tutorial', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32891, 'ruRU', 'FLAG – Commander Tutorial', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32892, 'ruRU', 'Грядет война', 'Поговорите с хранителем истории Чо.', 'При входе в долину вы замечаете, что упитанный пандарен на балконе Дворца Могу\'шан делает вам знаки остановиться. Похоже, что хранитель истории Чо пытается привлечь ваше внимание. Нужно узнать, в чем дело!', '', 'Он машет рукой из Обители Мудрости.', 'Хранитель истории Чо', '', '', 'Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.', 25549);
INSERT INTO `quest_template_locale` VALUES (32896, 'ruRU', 'Путь к войне', 'Поговорите с Ки\'той Стрелоклыком в Колючем Холме, что в Дуротаре.', 'У меня новости от Бейна. Восстанию Черного Копья нужна твоя помощь.$B$BОтправляйся в Колючий Холм и найди Ки\'ту Стрелоклыка.$B$BИ никому ни слова!', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32898, 'ruRU', 'Daily Scenario Random (1st) (Mists)', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (32900, 'ruRU', 'Героические свершения', 'Пройдите любой сценарий в героическом режиме сложности.', 'Я просто умираю от скуки. Мне никогда не выбраться из этого места!$b$bТы производишь впечатление $gбывалого искателя:бывалой искательницы; приключений. Порадуй меня по-настоящему героической историей. В награду я дам тебе кое-что особенное, что тебя непременно заинтересует.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32901, 'ruRU', 'Героические свершения', 'Пройдите любой сценарий в героическом режиме сложности.', 'Я просто умираю от скуки. Мне никогда не выбраться из этого места!$b$bТы производишь впечатление $gбывалого искателя:бывалой искательницы; приключений. Порадуй меня по-настоящему героической историей. В награду я дам тебе кое-что особенное, что тебя непременно заинтересует.', '', '', '', '', '', '', 25549);
