INSERT INTO `quest_template_locale` VALUES (32929, 'ruRU', 'Не уменьем, а числом', 'Убейте $1oa |4Громоборца:Громоборцев:Громоборцев; в ущелье Кинжальной Пасти, что среди скал Хребта Ледяного Огня.', 'Громоборцы предпочитают охотиться большими группами, ведь поодиночке они слабы. Их единственная сильная сторона – многочисленность.$b$bЗначит, чтобы победить... нужно сократить их количество.$b$bУбивай всех Громоборцев на своем пути по мере нашего продвижения в Ущелье Кинжальной Пасти, и их клан будет слабеть на глазах.', '', '', '', '', '', '', 25549);
