INSERT INTO `quest_template_locale` VALUES (32942, 'ruRU', 'Заказ: Войска Похитителей Солнца I', 'Посадите 8 семян лука-шалота на ферме Солнечной Песни.', '<Юн описывает заказ четко и без лишних слов.>$b$bПоступил еще один заказ от Орды. Войска Похитителей Солнца, находящиеся на Острове Грома, нуждаются в луке-шалоте.$b$bИ хотя от конфликта Орды и Альянса у меня волосы встают дыбом, я не стану отказывать голодающим.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32943, 'ruRU', 'Заказ: Войска Похитителей Солнца II', 'Соберите урожай с 8 растений лука-шалота и упакуйте 40 единиц лука-шалота для Войск Похитителей Солнца.', 'Когда лук-шалот вырастет, останется только сложить его в ящик.$b$bПодумать только, благодаря этому луку солдаты на передовой будут накормлены!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32944, 'ruRU', 'Заказ: Армия Кирин-Тора I', 'Посадите 8 семян хрустящей моркови на ферме Солнечной Песни.', '<Юн описывает заказ четко и без лишних слов.>$b$bПоступил еще один заказ от Альянса. Армия Кирин-Тора, находящаяся на Острове Грома, нуждается в хрустящей моркови.$b$bИ хотя от конфликта Орды и Альянса у меня волосы встают дыбом, я не стану отказывать голодающим.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (32945, 'ruRU', 'Заказ: Армия Кирин-Тора II', 'Соберите урожай с 8 растений хрустящей моркови и упакуйте 40 единиц хрустящей моркови для Армии Кирин-Тора.', 'Когда хрустящая морковь вырастет, останется только сложить ее в ящик.$b$bПодумать только, благодаря этой моркови солдаты на передовой будут накормлены!', '', '', '', '', '', '', 25549);
