INSERT INTO `quest_template_locale` VALUES (33093, 'ruRU', 'FLAG - Proving Grounds - Tank Silver', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33094, 'ruRU', 'FLAG - Proving Grounds - Tank Gold', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33095, 'ruRU', 'FLAG - Proving Grounds - Healer Bronze', '', '', '', '', '', '', '', '', 19865);
