INSERT INTO `quest_template_locale` VALUES (33160, 'ruRU', 'Хранитель Времени Кайроз', 'Поговорите с Кайрозом на Вневременном острове.', 'Ты $gнашел:нашла; способ попасть на Вневременный остров, |3-6($c). Бронзовые драконы желают разузнать его тайны, но остров опасен, и нам нужна твоя помощь.$b$bИди вдоль берега, и на полпути ты увидишь мощеную дорогу, которая ведет на восток.$B$BОна приведет тебя на Турнирную площадку Небожителей. Там ты найдешь Кайроза, одного из Хранителей Времени, с которым мы работаем.$B$BКайроз ответит на любые твои вопросы. Будь $gосторожен:осторожна;, путь может быть опасным.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33161, 'ruRU', 'Вневременная экскурсия', 'Исследуйте Вневременный остров.', 'Для начала тебе следует ознакомиться с островом.$B$BИсследуй его и разузнай обо всем, что тебя заинтересует. Возвращайся, когда закончишь, и я вознагражу тебя за любую информацию об этом странном месте.$B$BИ соблюдай осторожность! Здесь водятся ужасные и сверхъестественные создания.', '', '', '', '', '', '', 25549);
