INSERT INTO `quest_template_locale` VALUES (33168, 'ruRU', 'Сердце в огне', 'Добудьте огненное сердце Кросниса.', 'Осколки у нас, но теперь их нужно соединить. Здесь есть кузница, но жара огня в горне для этого недостаточно.$B$BВпрочем, недалеко отсюда живет демон, что пылает подобно солнцу.$B$BГул\'дан – а может, и Разуун – сумел призвать сюда инфернала. Эта тварь называет себя Кроснис, что значит \"горнило\".$B$BСердце демона источает достаточно жара. Все, что тебе нужно, – это добыть его.', '', 'Уничтожьте инфернала и заберите его огненное сердце.', 'Кроснис', '', '', '', 25549);
