INSERT INTO `quest_template_locale` VALUES (33222, 'ruRU', 'Малыш Томми Новобранец', 'Победите малыша Томми Новобранца в битве питомцев.', 'У меня тоже есть боевой питомец! Устроим поединок? Будет весело, обещаю!', '', '', '', '', '', '', 25549);
