INSERT INTO `quest_template_locale` VALUES (33248, 'ruRU', 'Арена испытаний', 'Поговорите с мастером испытаний Ротуном у храма Белого Тигра, а затем пройдите на арену испытаний.', 'А вот и ты! Ты же $n, так? Рад встрече. Меня зовут Тайцзин.$b$b<Тайцзин оценивающе смотрит на вас.>$b$bНа вид ты $gкрепкий:крепкая;. Я тебя видел раз или два здесь, в Доле, но мне еще не приходилось с тобой сражаться. Интересно… на деле ты окажешься так же $gсилен:сильна;?$b$bЕсли хочешь испытать себя, поговори с мастером испытаний Ротуном у храма Белого Тигра, что на вершине Кунь-Лай. Он предложит тебе испытание.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33249, 'ruRU', 'Арена испытаний', 'Поговорите с мастером испытаний Ротуном у храма Белого Тигра, а затем пройдите на арену испытаний.', 'А вот и ты! Ты же $n, так? Рад встрече. Меня зовут Цзиньхо.$b$b<Цзиньхо оценивающе смотрит на вас.>$b$bНа вид ты $gкрепкий:крепкая;. Я тебя видел раз или два здесь, в Доле, но мне еще не приходилось с тобой сражаться. Интересно… на деле ты окажешься так же $gсилен:сильна;?$b$bЕсли хочешь испытать себя, поговори с мастером испытаний Ротуном у храма Белого Тигра, что на вершине Кунь-Лай. Он предложит тебе испытание.', '', '', '', '', '', '', 25549);
