INSERT INTO `quest_template_locale` VALUES (33255, 'ruRU', 'Марш справедливости', 'Отведите свои войска к храму Карабор и убейте всех орков, вставших на пути Света.', 'Железная Орда захватила Карабор. Если не поторопимся, потеряем город. $b$bЭкзарх Акама с остатками наших войск заперт в городе, но бойцы твоего гарнизона все еще у храма – и ждут твоих приказов.$B$BЛетим со мной. Встретимся с твоими войсками на поле боя. Теперь, когда с нами наару, мы должны в последний раз пойти на штурм и захватить город!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33256, 'ruRU', 'Защита Карабора', 'Уничтожьте Железную Орду в Караборе.', 'Защити Карабор от Железной Орды.$B$BВ глубине северного двора находится Арнокк Сжигатель. Он охраняет вход в порт за Карабором, где ждут основные силы Железной Орды.$B$BКак только с ним разберемся, сразу займемся предводителем Орды – командиром Воркой.', '', '', '', '', '', '', 25549);
