INSERT INTO `quest_template_locale` VALUES (33263, 'ruRU', 'Сумрачная роща', 'Обыщите Сумрачную рощу и выясните, откуда здесь взялся мул.', '<Кажется, это вьючный мул из вашего гарнизона. Странно, что он бродит здесь в одиночку.$B$BНужно выяснить, что случилось.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33264, 'ruRU', 'A Proper Burial', 'Burn the corpses of dead Frostwolf Outriders.', '<The orc is visibly winded. A large pool of blood is gathering at his feet.>$B$BWe were out hunting when we found the wolves under attack.$b$bMany ogres were slaughtered by our blades... but their numbers were too great.$b$bI\'m going to catch my breath before I go out and kill the rest of them.$B$BHere, take this torch. Go give my brothers and sister a proper burial and return to me.', '', '', '', '', '', 'Return to Urukag by Grimfrost Hill in Frostfire Ridge.', 19865);
INSERT INTO `quest_template_locale` VALUES (33266, 'ruRU', 'A Light in the Dark - Tracking Quest', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33267, 'ruRU', 'Сливы и стручлинги', 'Отомстите стручлингам.', 'The blood soaked body of Kenny is slummped up against the cave wall. The podlings clearly made a feast of him.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33269, 'ruRU', 'Освобождение Гул\'вара', 'Убейте $1oa |4орка:орков:орков; Совета Теней в Гул\'варе.', 'Кадгар хочет, чтобы ты $gсосредоточился:сосредоточилась; на Гул\'дане, но это не значит, что одновременно мы не можем уничтожить и Совет Теней.$B$BВ Гул\'варе полно приспешников Совета Теней. Нужно разобраться с ними.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33270, 'ruRU', 'Tracking Quest - First - Ironfur Steelhorn', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33271, 'ruRU', 'Песнь шипов и кореньев', 'Убейте короля Бутона Смерти.', '<Джаррод ранен. Морщась от боли, он обращается к вам.>$b$bШелли, командир отряда... ее держат где-то поблизости...', '', '', 'Король Бутон Смерти', '', '', '', 25549);
