INSERT INTO `quest_template_locale` VALUES (33348, 'ruRU', '\"Tom\" Bone Apart - Intro Tracking Quest', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33349, 'ruRU', 'STARTER QUEST - RED->PURPLE 15', 'Пробегите под аркой, добегите до красной отметки, затем до фиолетовой и возвращайтесь в игровой лагерь Железных Эльфов.', 'B этом испытании тебе нужно будет пробежать под аркой, затем добежать до КРАСНОЙ отметки, потом до ФИОЛЕТОВОЙ и успеть вернуться сюда до пятнадцатого удара колокола. Удачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33350, 'ruRU', 'Redridge Group Trial', 'Log description text.', 'Redridge group trial. Get to the blue marker, then the green marker, then the red marker, then return to the Lakeshire Ironelf cmap.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33352, 'ruRU', 'Tracking Event: Chief killed', 'Kill the Foreling Chief.', 'Okay best friend. Let\'s talk to old smelly mud chief. We smell so good like moonstone and foods. We give friends moonstones. We tell friends I\'m chief. We get ALL the foods.$b$bStupid bad smelling chief. Thinks I\'m foods? Pshh. He\'s foods.$b$bTime for foods best friend.', '', '', '', '', '', 'xxxxxx', 19865);
INSERT INTO `quest_template_locale` VALUES (33354, 'ruRU', 'Гибель матери стаи', 'Отнесите шкуру Лунной волчицы Эббу Ниблгиру на Ярмарку Новолуния, которая проходит на Острове Новолуния.', 'Это шкура огромной матери стаи с Острова Новолуния.$B$BЭбб Ниблгир, повелитель зверей с Ярмарки Новолуния, будет счастлив узнать, что эта призрачная волчица и ее потомство больше не будут создавать угрозу для его зверинца… по крайней мере какое-то время. Отнеси шкуру ему.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33358, 'ruRU', 'Час лапши: бонус', 'Встаньте в очередь на рабочую смену у стойки с лапшой в Полугорье и выполните дополнительную задачу.', 'Привет, $n. Думаешь, ты действительно можешь претендовать на звание выдающегося мастера лапши?$B$bДавай, посмотрим, на что ты $gспособен:способна;.', '', '', '', 'Ты действительно настоящий мастер лапши! Так держать!', 'Суншинь Железная Лапа', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33359, 'ruRU', 'Ищи нас на Заставе Падающих Звезд', 'Поговорите с верховным магом Кадгаром на Заставе Падающих Звезд.', 'Верховный маг заподозрил, что в долине есть кто-то из Совета Теней. Он попросил меня сообщить тебе об этом. $B$BРазыщи нас на Заставе Падающих Звезд – и как можно скорее. Врага нужно искоренить, но без твоей помощи, командир, мы не справимся.', '', '', '', '', '', '', 25549);
