INSERT INTO `quest_template_locale` VALUES (33374, 'ruRU', 'Путь странника туманов', 'Убейте 20 элитных существ на Вневременном острове.', 'Ты $gслышал:слышала; слова Небожителей. Но чему ты $gнаучился:научилась; на своем пути к святилищам?$b$bМудрость паломничества заключается в его простоте и тишине. Ты слышишь ветер, шумящий в кронах деревьев, замечаешь даже самую маленькую бабочку, и твой разум открыт для самых важных уроков, которые готовят нам испытания. Возможно, ты $gзаметил:заметила; грозных монстров, которые водятся на этом острове?$b$bВот твое испытание. Пандария многому научила тебя. Позволь нам проверить твои знания.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33375, 'ruRU', 'Усовершенствование видения', 'Используйте видение времени во время Осады Оргриммара.', 'Я закончил шлифовать камни и настроил песочные часы для новых путей времени. Не можешь ли ты еще раз вернуться к Осаде Оргриммара и перевернуть часы?$b$bИ возвращайся поскорее, мне очень интересно узнать о результатах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33376, 'ruRU', 'В поисках судьбы', 'Используйте видение времени во время Осады Оргриммара.', 'Я не был с тобой полностью откровенен, несмотря на всю ту помощь, которую ты $gоказал:оказала; Дозорным Времени. Я пока не могу сказать тебе всего. Среди нас есть предатель. Никому не рассказывай о том, что ты $gделал:делала; сегодня. И будь $gосторожен:осторожна; в присутствии любого члена моей стаи, когда у тебя видение времени.$b$bА теперь быстрее возвращайся к Осаде Оргриммара и еще раз используй песочные часы.$b$bИ береги себя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33377, 'ruRU', 'Сокрытые нити', 'Используйте видение времени во время Осады Оргриммара.', 'Тебе удалось сохранить все в тайне, и я благодарен тебе за это. Когда информация о путях времени попадает не в те руки, это может привести к разрушительным последствиям. И в настоящий момент моя стая не так уж много может сделать, чтобы исправить их. Поэтому мы должны быть осторожны.$b$bСила песочных часов растет. Думаю, теперь с их помощью мы сможем увидеть больше, чем раньше. Я хочу попросить тебя попробовать сделать это.$b$bВозвращайся к Осаде Оргриммара и сфокусируй песочные часы на самом разрушительном пути времени, какой только найдешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33378, 'ruRU', 'Судьба принца', 'Используйте видение времени в храме Белого Тигра, что на вершине Кунь-Лай.', 'Видение времени почти идеально, и теперь мы гораздо лучше можем контролировать интересующие нас видения. Твоя помощь была очень важна для завершения работы над артефактом и спасения не только моей стаи, но и наших союзников, дозорных Времени. Мы все у тебя в долгу.$b$bДовольно удачно мне удалось обнаружить что-то вроде пересечения временных путей, прямо здесь, в Пандарии. Отнеси видение времени в храм Белого Тигра. Там, в подвалах храма, переверни песочные часы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33379, 'ruRU', 'Один последний переворот', 'Используйте видение времени в Пещерах Времени в Танарисе.', 'Не хочется опять просить тебя об услуге, но я больше не знаю, кому доверять. Я использовал видение времени для того, чтобы собирать информацию, а также в моих исследованиях и, похоже, нашел еще один временной перекресток. Он находится прямо в Пещерах Времени.$b$bКогда я впервые увидел это видение, то не хотел верить. Но я не могу сидеть сложа руки и не воспользоваться такой информацией. Тебе нужно отправиться в Пещеры Времени и использовать там видение времени.$b$bНе теряй времени!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33380, 'ruRU', 'REUSE', 'Find Ga\'nar and 2 Frostwolf Lieutenants at the Ogre Fortress.', 'My brother Ga\'nar led an assault into the citadel a few hours ago with some of my best lieutenants. They have yet to return.$B$BI need you to move ahead of the pack and find them. We need every warrior we can if we are to stand atop the ogre king\'s skull by the day\'s end.', '', '', '', '', '', 'Найдите Дуротана в крепости огров.', 19865);
INSERT INTO `quest_template_locale` VALUES (33382, 'ruRU', 'Tracking Quest: Saw Maraad Storm Off', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33383, 'ruRU', 'Событие: тернистый король Фили', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33384, 'ruRU', 'Сокровище: погребальные поля A', '', '', '', '', '', '', '', '', 19865);
