INSERT INTO `quest_template_locale` VALUES (33389, 'ruRU', 'Событие: Иггдрел Оскверненный', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33398, 'ruRU', 'South Sprint Practice', 'Пробегите под аркой, добегите до красной отметки, затем до фиолетовой и возвращайтесь в игровой лагерь Железных Эльфов.', 'B этом испытании тебе нужно будет пробежать под аркой, затем добежать до красной отметки, потом до фиолетовой отметки и вернуться сюда.$B$BВремени у тебя на это будет сколько угодно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33407, 'ruRU', 'REUSE', 'Найдите Га\'нара, Лигру и Коргу в крепости огров.', 'Пару часов назад мой брат Га\'нар и несколько моих лучших командиров отправились в набег на цитадель и до сих пор не вернулись.$B$BЯ прошу тебя встать во главе стаи и найти их. Если мы хотим победоносно воздеть на копье отрубленную голову вождя Камнерогов Горр\'тога уже к закату, то у нас каждый воин на счету.', '', '', '', '', '', 'Найдите Дуротана в крепости огров.', 19865);
INSERT INTO `quest_template_locale` VALUES (33408, 'ruRU', 'Огромные огненные шары!', 'Поговорите с Траллом в Цитадели Камнерогов.', 'Га\'нар, Лигра и остальные находятся на втором этаже крепости. Тралл, твой друг, тоже предложил свою помощь.$b$bЧтобы найти их, поднимись по скату, расположенному на юге за пределами крепости.$b$bПомоги клану Северного Волка одержать победу!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33410, 'ruRU', 'Чудовище клана Камнерогов', 'Убейте Дорогга Беспощадного.', 'После того как Га\'нар вошел в крепость, Камнероги натравили на нас это чудовище.$b$bПосле стольких заклинаний сил у меня мало, но я еще способен помочь этой женщине-орку.$b$b$n, помоги другим солдатам убить Дорогга.', '', 'Чудовище Камнерогов', 'Дорогг Беспощадный', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33412, 'ruRU', 'Зачистка территории', 'Поговорите с Игримар Непоколебимой в Круге Крови.', 'Мы одержали победу, но еще многое предстоит сделать.$b$bСеверные Волки обыщут цитадель и прикончат оставшихся в живых. А тебе я предлагаю почетную задачу – зачистить ямы гладиаторов на севере.$b$bВ начале боя мы отправили туда нашу лучшую разведчицу. Если ты все еще жаждешь крови, поговори с ней. Наверняка там еще остались враги.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33416, 'ruRU', 'South Sprint 12', 'Пробегите под аркой, добегите до красной отметки, затем до фиолетовой отметки и возвращайтесь в игровой лагерь Железных Эльфов.', 'B этом испытании тебе нужно будет пробежать под аркой, затем добежать до красной отметки, потом – до фиолетовой и успеть вернуться сюда до двенадцатого удара колокола. Удачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33418, 'ruRU', 'Поднять щиты!', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33419, 'ruRU', 'Вопрос жизни и смерти', 'Найдите Арекка, Диаани и Зууло в пещере Кровавых Шипов.', '$gНезнакомец:Незнакомка;, пожалуйста, помоги мне!$B$BМы с соратниками пришли сюда, чтобы убить чудовищную королеву ос в надежде получить награду за нее.$B$BМы разбили лагерь у подножья холма и легли спать. Посреди ночи на нас напали эти ужасные бледнокожие... существа!$B$BНе знаю, где теперь мои друзья, но я слышала крики, доносящиеся из глубины пещеры.$B$BПожалуйста, найди моих товарищей. Без них я отсюда не уйду.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33422, 'ruRU', 'Элвиннский тренировочный марафон', 'Пробегите под аркой, добегите до синей отметки, затем до зеленой отметки и возвращайтесь в игровой лагерь Железных Гномов.', 'B этом испытании тебе нужно будет пробежать под аркой, затем добежать до синей отметки, потом до зеленой отметки и вернуться сюда.$B$BВремени у тебя на это будет сколько угодно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33424, 'ruRU', 'Northshire Dash 12', 'Пробегите под аркой, добегите до синей отметки и возвращайтесь в игровой лагерь Железных Эльфов.', 'Испытание такое: пробеги под аркой, добеги до синей отметки и как можно скорее возвращайся назад.$B$BПостарайся успеть до двенадцатого удара колокола.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33425, 'ruRU', 'Blue/Yellow Sprint 15 INTERNAL REPEATABLE', 'Пробегите под аркой, добегите до синей отметки, затем до зеленой отметки и возвращайтесь в игровой лагерь Железных Эльфов.', 'Ready for a tougher challenge? This one has an extra leg:$B$BRun through the arch...$BGet to the blue marker...$BGet to the green marker...$Bthen return here before the bell tolls 15 times.$B$BGood luck!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33427, 'ruRU', 'Гнев – наше все', 'Поговорите с воеводой Зогом в своем гарнизоне на Хребте Ледяного Огня.', 'Дрек\'Тару просто нужно приспособиться, и все будет в порядке. Дар видения, что дал ему элементаль, имеет огромную силу, и он уже на пути к тому, чтобы стать величайшим шаманом в мире.$b$bВозможно, тебе лучше отправиться в гарнизон и рассказать воеводе Зогу обо всем, что здесь произошло.$b$bОн сможет отправить сюда твои войска, чтобы усилить контроль над территорией.', '', '', '', '', '', 'Поговорите с воеводой Зогом в своем гарнизоне на Хребте Ледяного Огня.', 25549);
INSERT INTO `quest_template_locale` VALUES (33429, 'ruRU', 'Элвиннский тренировочный марафон: 25', 'Пробегите под аркой, добегите до синей отметки, затем до зеленой отметки и возвращайтесь в игровой лагерь Железных Эльфов.', 'Испытание такое: пробеги под аркой, беги до синей отметки, затем до зеленой отметки и вернись сюда до двадцать пятого удара колокола.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33431, 'ruRU', 'Элвиннская южная трасса: 30', 'Пробегите под аркой, добегите до красной отметки, затем до фиолетовой и возвращайтесь в игровой лагерь Железных Эльфов.', 'B этом испытании тебе нужно будет пробежать под аркой, затем добежать до красной отметки, потом до фиолетовой отметки и успеть вернуться сюда до тридцатого удара колокола.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33432, 'ruRU', 'Элвиннская южная тренировочная трасса', 'Пробегите под аркой, добегите до красной отметки, затем до фиолетовой и возвращайтесь в игровой лагерь Железных Эльфов.', 'Хочешь попрактиковаться?$B$BB этом испытании тебе нужно будет пробежать под аркой, затем добежать до красной отметки, потом до фиолетовой отметки и вернуться сюда.$B$BВремени на это у тебя будет сколько угодно.', '', '', '', '', '', '', 25549);
