INSERT INTO `quest_template_locale` VALUES (33444, 'ruRU', 'Поедология', 'Соберите $1oa |4частицу:частицы:частиц; Ледяного Огня.', 'Дрек\'Тар считает, что съеденные горенами части Экзурота для нас бесполезны. Однако я не собираюсь рваться в бой с духом стихий до тех пор, пока мы хотя бы не попытаемся раздобыть как можно больше этих \"частиц\".$b$bУбей всех горенов, которых встретишь в Магнароке, и постарайся извлечь из них частицы Ледяного Огня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33445, 'ruRU', '[FLAG] Caravan Position Bitflag 02', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33446, 'ruRU', '[FLAG] Caravan Position Bitflag 03', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33447, 'ruRU', 'Сокровища: ремесленник из клана Камнерогов', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33448, 'ruRU', 'One-Time Chest 000', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33450, 'ruRU', 'Стража вождя', 'Добудьте головы Тхунка, Гуллока и Сплорга.', 'Не знаю, к чему ты $gпривык:привыкла;, но эта земля не терпит слабаков. Может, Дуротан просто захотел от тебя избавиться. Посмотрим.$b$bУбей вождя Круга Крови. Сделаешь это – и здешние огры будут разгромлены. Но сначала его надо найти.$b$bТелохранители вождя здесь, неподалеку. Убей их и принеси мне их головы. Так мы сможем выманить нашу жертву.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33454, 'ruRU', 'Лекарство', 'Вылечите 5 гладиаторов из клана Северного Волка.', 'Трусы! Пусть будут прокляты эти мерзкие мешки с требухой!$b$bКамнероги всегда доводили орков до белого каления тем, что брали в плен наших раненых, чтобы обратить их в рабов и заставить сражаться между собой на аренах, словно собак.$b$bВ отместку за наше нападение они отравили пленных орков. Если им не помочь, все они скоро умрут мучительной смертью.$b$bПротивоядие есть только у огрских геомантов. Лишь оно способно исцелить узников из клана Северного Волка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33455, 'ruRU', 'Westfall Race Practice UNUSED', 'Пробегите под аркой, добегите до синей отметки, затем до зеленой отметки и возвращайтесь в игровой лагерь Железных Эльфов.', 'Run through the arch...$BGet to the blue marker...$BGet to the green marker...$Bthen return here.$B$BYou have all the time you need.', '', '', '', '', '', 'test trial completion text.', 19865);
