INSERT INTO `quest_template_locale` VALUES (33461, 'ruRU', 'Охотник на дичь из Сумрачной рощи', 'Соберите нужные продукты в Сумрачной роще.', '<Вы нашли обрывок пергамента со списком продуктов, которые нужны Арсенио для приготовления нового блюда для обитателей гарнизона.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33462, 'ruRU', 'В шкуре Громоборца', 'Сделайте крюк Громоборцев.', 'На земле валяется обрывок цепи, выкованный работниками клана Громоборцев. Цепь выглядит очень простой, но со своей задачей она должна справляться более чем успешно.$b$bЕсли собрать достаточно таких обрывков, то даже новичок соберет из них цепь с крюком, по эффективности не уступающую тем, что используют гарпунеры из клана Громоборцев.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33467, 'ruRU', 'Падение вождя', 'Убейте вождя Балта.', 'Что ж, ты еще $gжив:жива;. Осталось лишь одолеть Вождя арены.$b$bЭто станет твоим первым настоящим испытанием. Балт – серьезный противник даже для опытного бойца из клана Северного Волка.$b$bНасади собранные тобой головы на копья на арене Ледяного Огня. Вождь разъярится и бросится в бой.$b$bВернись с арены с победой, тогда мы поймем, что Дуротан не ошибся, доверившись тебе.', '', '', 'Вождь Балт', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33468, 'ruRU', 'Спасение Волчьего дома', 'Спасите Вор\'гол от клана Громоборцев.', 'Подлые и трусливые Громоборцы...\n\nКогда битва за крепость была в самом разгаре, ко мне прибыли гонцы с вестью о том, что Железный Волк атаковал наш дом. Но легкой добычи ему не видать – Дрека позаботится о том, чтобы на каждого из наших павших пришлось не меньше десятка врагов. Но все же мы должны вернуться как можно скорее и прогнать этих псов.\n\nТы и твои бойцы уже показали себя ценными союзниками Северных Волков. Твоя помощь в нашей битве за Вор\'гол пришлась бы нам очень кстати.\n\nЕсли решишься помочь – увидимся на поле боя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33469, 'ruRU', 'Предсказатель', 'Отправляйтесь к Пруду Видений и убейте военного вождя Гарграка.', 'Этот полководец Громоборцев... $n, останови его!$B$BОн хочет напасть на Дрек\'Тара у пруда Видений на северо-западе!', '', 'Убейте его, пока он не убил предсказателя Дрек\'Тара!', 'Военный вождь Гарграк', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33470, 'ruRU', 'Пруд Видений', 'Поговорите с предсказателем Дрек\'Таром у пруда Видений, чтобы начать ритуал предвидения.', 'На горизонте собирается буря, |3-6($c).$B$BЯ все подготовил для ритуала. Посмотри в пруд и узри, что готовит нам судьба.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33473, 'ruRU', 'Возвращение в Цитадель Камнерогов', 'Вернитесь к Дуротану в Цитадель Камнерогов.', 'Дуротан должен узнать о твоем видении. Попроси Пула Резчика Ветра отвезти тебя обратно.$B$BОт тебя, $n, сейчас зависит судьба клана Северного Волка... и всего Дренора.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33483, 'ruRU', 'Беда Маэстра', 'Добудьте ключ у надсмотрщика Тургалла и найдите топоры Маэстра.', 'Тебя послали освободить меня? Значит, теперь мы союзники.$b$bНаверняка ключ от этой клетки найдется у надсмотрщика Тургалла, который следит за Закоптелой шахтой.$b$bИ, пока ты будешь там, может, найдешь тех жалких надсмотрщиков Закоптелой шахты, которые забрали мои топоры?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33484, 'ruRU', 'Печальная участь надсмотрщика', 'Поговорите с Гузой в Цитадели Камнерогов.', 'Сообщи остальным о том, что сегодня ты $gспас:спасла; Северных Волков. Им будет приятно узнать, что хоть кто-то выбрался из этих шахт.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33485, 'ruRU', 'Гонка для всех', 'Пробегите под аркой, добегите до синей отметки, затем до зеленой отметки, потом до красной отметки, наконец, до фиолетовой отметки и возвращайтесь в игровой лагерь Железных Эльфов.', 'Пробеги под аркой...$BДобеги до синей отметки...$BДобеги до зеленой отметки...$BДобеги до красной отметки...$BДобеги до фиолетовой отметки.$BВозвращайся сюда...$B$BЗатем повтори все с самого начала. Да-да, ты не $gослышался:ослышалась; – бежать надо будет два круга!$B$BУдачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33492, 'ruRU', 'Northshire Sprint Practice', 'Пробегите под аркой, добегите до синей отметки, затем до зеленой отметки и возвращайтесь в игровой лагерь Железных Эльфов.', 'Добро пожаловать на игры Железных Гномов! Испытание будет такое: пробеги под аркой...$BДобеги до синей отметки...$BДобеги до зеленой отметки...$BИ возвращайся сюда.$B$BВремени у тебя на это будет сколько угодно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33493, 'ruRU', 'Возвращение в стаю', 'Поговорите с Дуротаном у себя в гарнизоне.', 'Какая-то часть меня согласна с Каргом, мы и правда могли бы сразиться с Железным Волком прямо сейчас. Как только я слышу это имя, у меня начинают сжиматься кулаки. Каждый мускул моего тела жаждет мести.$B$BНо сердцем я чую Ашу, и это ощущение успокаивает меня. Она указывает мне верный путь. Я не заслужила ее мудрости, но не стану впустую растрачивать этот дар.$B$B<Локра смотрит на небо.>$B$BДуротан вот-вот начнет собирать остальных в твоем гарнизоне. Нам тоже надо быть там.', '', '', '', '', '', 'Поговорите с Дуротаном у себя в гарнизоне.', 25549);
INSERT INTO `quest_template_locale` VALUES (33497, 'ruRU', 'Событие: падение затерянного во времени громилы, ч. 2', '', '', '', '', '', '', '', '', 19865);
