INSERT INTO `quest_template_locale` VALUES (33504, 'ruRU', 'Эпизод: огненный камень шамана', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33505, 'ruRU', 'Сокровища: шевелящееся яйцо химеры', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33511, 'ruRU', 'Эпизод: яма для жертвоприношений', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33512, 'ruRU', 'Эпизод: лавовый горен', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33513, 'ruRU', 'Приспешники Черношипа', 'Убейте Аарукса, Мордреша и Мягконога.', 'Реинкарнация Амненнара неизбежна. Чтобы не допустить срыва церемонии, вестник смерти Черношип приказал своим самым верным слугам любой ценой защитить его от нашего нападения.$B$BАарукс, чумной паук, сидит в своем гнезде, окруженный многочисленными отпрысками – за ним присматривают араноманты из племени Мертвой Головы. Мордреш собирает силы Амненнара на Груде костей. И, наконец, Мягконог охраняет вход на Тернистый серпантин.$B$BКогда ты победишь всех троих, я присоединюсь к тебе, и мы вместе бросим вызов Черношипу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33514, 'ruRU', 'Ритуал', 'Убейте Амненнара Хладовея.', 'Очень хорошо, что ты так быстро $gоткликнулся:откликнулась; на зов. Мне снова придется попросить тебя рискнуть жизнью ради спасения Калимдора.$B$BВестник смерти Черношип, ученик Амненнара, хочет вернуть своего господина из небытия в мир живых! Мы должны как можно скорее добраться до вершины Тернистого серпантина и помешать ему завершить ритуал. Только вместе мы можем одержать над ним верх!', '', 'Опасайся его мощной магии!', 'Амненнар Хладовей', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33525, 'ruRU', 'Сокровища: семья орков', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33526, 'ruRU', 'Флаги победы', 'Воткните $1oa |4знамя:знамени:знамен; Северного Волка в трупы огров из клана Камнерогов.', 'Камнероги многие годы мешали жить моему народу.$b$bСегодня этому придет конец!$b$bОсталось сообщить об этом ограм так, чтобы они поняли.$b$bЕсли хочешь нам помочь, воткни наши знамена в тела врагов.$b$bКогда огры увидят, что поле боя пестрит трофеями клана Северного Волка, их боевой дух будет подорван!$b$bТак мы обычно действуем. Закончишь – найди меня, я буду ждать впереди.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33527, 'ruRU', 'Последние шаги', 'Заберитесь по цепи наверх и убейте Горр\'тога.', 'Га\'нар пришел в ярость и отправился наверх за Горр\'тогом, королем огров.$b$bОн ушел один, а проход, ведущий к тронному залу, сейчас заблокирован.$b$bТы очень $gизобретательный:изобретательная; – может, и на этот раз найдешь другой способ пробиться наверх?$b$bПока я добирался сюда, меня ранили, но расчистить путь, чтобы встретиться с тобой наверху, я еще смогу.$b$bПоторопись! Клан Северного Волка обязан захватить цитадель!', '', 'Властелин Цитадели Камнерогов.', 'Горр\'тог', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33530, 'ruRU', 'Кошмар в гробнице', 'Узнайте о ритуале в Гробнице Душ.', 'Там, внизу... кошмар... всюду трупы...$B$BТемный ритуал... прошу... его нужно остановить...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33531, 'ruRU', 'Сокровища: павший огр', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33532, 'ruRU', 'Сокровища: сундук огров', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33533, 'ruRU', 'Тайны Горгронда', 'Найдите Ирель в Диколесье в Горгронде. Чтобы отправиться к ней, поговорите с укротителем грифонов в своем гарнизоне.', 'Сегодняшняя победа далась нам дорогой ценой. Слишком дорогой. И никто не знает, выдержим ли мы следующую битву.$b$bНам нужно узнать планы Железной Орды, и есть лишь одно место, где мы можем раздобыть нужные сведения.$b$bГоргронд.$b$bЭто дикие земли, и немногие возвращаются оттуда.$b$bЯ собираюсь отправиться туда, найти их крепость на Черной горе и узнать, как нам победить этих злобных орков.$b$bТы со мной, командир?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33540, 'ruRU', 'Сокровище: безделушки Узко', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33543, 'ruRU', 'Веселый Череп', 'Найдите кого-нибудь из клана Веселого Черепа.', 'О, $p. Очень хорошо. Мне позарез нужен кто-нибудь не из моего клана для переговоров с кланом Веселого Черепа.$b$bНам необходимы их проводники, но они опасны и непредсказуемы, впрочем, как и сам Горгронд.$b$bИди по этой дороге – может быть, встретишь кого-нибудь, с кем удастся договориться.$b$bНадеюсь, из любопытства с тобой сначала побеседуют, а уж только потом начнут убивать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33544, 'ruRU', 'Горены, повсюду горены!', 'Убейте $1oa |4едкозубого пожирателя:едкозубых пожирателей:едкозубых пожирателей;.', 'Мы... Слишком долго терпели горенов. Они совсем страх потеряли. Надо освежить им память и напомнить, кто мы.$b$bУбей их! Перебей всех. Разорви их на части. Пусть вспомнят, что случается с теми, кто нападает на деревню клана Веселого Черепа.$b$bАх, да. Добро пожаловать в Горгронд.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33546, 'ruRU', 'Незавершенные дела', 'Соберите бочки с маслом клана Северного Волка и отнесите их Гол\'кошу в кладовую.', 'Га\'нар поторопился и начал продвигаться вперед еще до того, как область была зачищена. Как воин он, конечно, не имеет себе равных, но его тактика иногда дорого нам обходится.$b$bГол\'кошу и его войскам было приказано уничтожить вражеские припасы, но огры украли масло, которое нужно ему для поджога.$b$bНайди горючее и проследи за тем, чтобы задание было успешно выполнено. Если наши бойцы еще живы, скажи им, чтобы возвращались ко входу в цитадель, ко мне.$b$bА пока я прослежу за безопасностью моих раненых братьев.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33548, 'ruRU', 'Мы умираем, смеясь!', 'Соберите $1oa |4маску:маски:масок; клана Веселого Черепа.', 'Ты $gпришел:пришла; помочь или помешать нам?$b$bНадо торопиться – попытаться спасти то, что еще можно спасти.$b$bСобери маски наших погибших братьев и сестер из клана Веселого Черепа и принеси мне в западную часть деревни.$b$bОни пригодятся мне, чтобы возродить наш клан.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33550, 'ruRU', 'Vignette: Iron Horde Napmaster', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33561, 'ruRU', 'Гонка для всех', 'Пробегите под аркой, добегите до синей отметки, затем до зеленой отметки, потом до красной отметки, наконец, до фиолетовой отметки и возвращайтесь в игровой лагерь Железных Эльфов.', 'Пробеги под аркой...$BДобеги до синей отметки...$BДобеги до зеленой отметки...$BДобеги до красной отметки...$BДобеги до фиолетовой отметки.$BВозвращайся сюда...$B$BЗатем повтори все с самого начала. Да-да, ты не $gослышался:ослышалась; – бежать надо будет два круга!$B$BУдачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33563, 'ruRU', 'Глаз радует... глаз?', 'Добудьте глаз Скотвы.', 'Эй, ты! Иди в бой или не мешайся под ногами.$b$bЭто не обычное нападение горенов. Смотри, гронн грабит нашу столовку. Этот горбатый мешок с кишками укусил мою Мозглю!$b$bВырви у него глаз и принеси мне.$b$bЭто даст мне время вывести ее из этой дыры.', '', 'Пожиратель черепов', 'Скотва', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33564, 'ruRU', 'Treasure: Hanging Satchel', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33565, 'ruRU', 'Treasure: Chimaera Scale', '', '', '', '', '', '', '', '', 19865);
