INSERT INTO `quest_template_locale` VALUES (33578, 'ruRU', 'Пирофобия', 'Убейте солнечного ведуна Кайрикса.', 'М-мы не сделали н-ничего, что могло бы разозлить араккоа... П-почему они напали на Арууну? Что им от нас нужно?$B$BМне так хочется убраться отсюда, но... очень страшно. Их предводитель испепелит меня, если увидит, я точно знаю!$B$BО... он сейчас в таверне...', '', '', 'Солнечный ведун Кайрикс', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33579, 'ruRU', 'Дренейская находка', 'Осмотрите древнюю призму в копях Арууны.', 'Они пришли за артефактом? Должно быть, шахтеры нашли что-то в наших копях на севере.$B$BВо имя Света! Только представь, какой должна быть сила артефакта, чтобы он привел их сюда от самых пиков.$B$BДумаю, они получили то, за чем пришли... Пытаться вернуть артефакт – безумная затея...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33580, 'ruRU', 'Очищение Гнездовья Шадар', 'Помогите 8 араккоа-изгоям выбраться из Гнездовья Шадар.', 'Не все араккоа равны.$B$B<Искар приподнимает рукав и показывает искалеченное крыло.>$B$BЭто не иллюзия. Вот что они со мной сделали. Мое место в обществе было определено еще до того, как я получил свое имя... И это место – в самом низу.$B$BНас много. Мы находим приют в забытых уголках этого мира.$B$BГнездовье Шадар было таким уголком. До тех пор, пока не пришли Приверженцы и не начали \"очищение\". Для поднятия боевого духа. И просто смеха ради.$B$BПомоги моему народу бежать, мы в долгу не останемся.$B$BКогда небеса пылают, полезно иметь союзников в тени.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33581, 'ruRU', 'Запретное знание', 'Вынесите из Гнездовья Шадар 6 фолиантов Тьмы.', '<Темный провидец Раасток смотрит на вас недоверчиво.>$B$BТак тебя прислал Искар? Я буду рад любой помощи, и мне все равно – |3-6($r) ты или волен-переросток.$B$BПриверженцы Рухмар – зашоренные глупцы! Они запрещают изучать темную магию, и всякий, кто ищет ответы в ней – для них еретик.$B$BВ Гнездовье Шадар мы хранили множество запретных фолиантов. Принеси мне все книги, которые сможешь спасти от огня, и я награжу тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33582, 'ruRU', 'Месть Кьюры', 'Убейте крылатого стражника Кууана в Гнездовье Шадар.', 'Когда-то я тоже был крылатым стражником.$B$BНо как-то вечером я отлучился с поста, чтобы посмотреть на фестиваль, и меня поймали. Кууан сдал меня, чтобы выслужиться перед командирами.$B$BМне выкололи глаза, сломали крылья и сбросили с пика.$B$BНо я все же везучий: если бы Искар меня не нашел, я бы там и умер. А теперь еще ты появляешься ровно в тот день, когда Кууан объявился в Гнездовье Шадар, и предлагаешь услуги наемного убийцы. Как удачно все сложилось.', '', '', 'Крылатый стражник Кууан', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33584, 'ruRU', 'Сокровище: прах А\'кумбо', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33586, 'ruRU', 'Преследуя тени', 'Поговорите с Рулкан на Утесе Изгнанников.', 'Не все орки клана Призрачной Луны вступили в союз Нер\'зула с Железной Ордой.$B$BСреди них есть одна орчиха, с которой мы дружим с давних пор. Она многое сможет рассказать нам о планах Нер\'зула, связанных с этой \"Темной звездой\".$B$BНайти ее можно на Утесе Изгнанников к северо-востоку отсюда. Я пошлю ей весть о твоем скором прибытии, она будет ждать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33593, 'ruRU', 'Салют для Пенни', 'Выстрелите из сигнального пистолета Пенни в Ухмылке Смерти.', 'Командир, у меня тут странный предмет с запиской, она, похоже, написана на твоем языке.\n\n<Дорогой господин Дуротан,\n\nЯ Пенни... ну, знаете, из Азерота? Мы виделись в гарнизоне, которым командует $p. \n\nВ общем, как я и говорила, у меня черный молот пятого уровня по инженерному делу, и я готова служить. Чем опаснее работа, тем лучше!\n\nЕсли окажетесь в опасности, просто подпалите эту сигнальную ракету, и тогда я примчусь быстрее кварка!\n\nС надеждой на встречу,\n\nПенни>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33597, 'ruRU', 'Tracking Quest - First - The Obliterator', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33602, 'ruRU', 'Награда за самоотверженность', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33603, 'ruRU', 'Награда за самоотверженность', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33609, 'ruRU', 'Northshire Dash Practice', 'Пробегите под аркой, добегите до синей отметки и возвращайтесь в игровой лагерь Железных Эльфов.', 'Добро пожаловать на игры Железных Гномов! B этом испытании тебе нужно будет пробежать под аркой, затем добежать до синей отметки и вернуться сюда.$B$BВремени у тебя на это будет сколько угодно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33610, 'ruRU', 'Сокровище: погребальные поля B', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33611, 'ruRU', 'Сокровище: погребальные поля C', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33612, 'ruRU', 'Сокровище: погребальные поля D', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33613, 'ruRU', 'Treasure: Adventurer\'s Cache', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33614, 'ruRU', 'Сокровище: урна Греки', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33622, 'ruRU', 'В бой!', 'Убейте $1oa |4огра:огров:огров; в Цитадели Камнерогов.', 'Благодаря тебе у входа в крепость снова безопасно.$b$bНо внутри все совсем иначе. Попытайся пробиться внутрь и перебить всех огров.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33633, 'ruRU', 'Прожорливый корчеватель', 'Найдите еду для корчевателя в Проходе Корчевателя в Горгронде.', 'Отбившийся кабан роется в мусоре, оставленном Железной Ордой. Он прекращает жевать и пристально смотрит на вас, затем рыгает.$b$bВоняет он ужасно.$b$bПохоже, только что съел кусок протухшего мяса. Может быть, вы найдете для него более здоровую пищу?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33634, 'ruRU', 'Maldo\'s Test Quest', '[DNT] Log Description', '[DNT] Quest Description', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33635, 'ruRU', 'FLAG - Seen Gazebo Explosion', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33640, 'ruRU', 'Vignette: Veloss', '', '', '', '', '', '', '', '', 19865);
