INSERT INTO `quest_template_locale` VALUES (33643, 'ruRU', 'Vignette: Venomshade (Plant Hydra)', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33644, 'ruRU', 'FLAG - Seen Wall Explosion', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33645, 'ruRU', 'Tracking Quest - Iskar\'s Hired Hand', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33649, 'ruRU', 'Сокровище: сожженный разведчик Железной Орды', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33657, 'ruRU', 'Заселение', 'Встретьтесь с Дуротаном в Цитадели Камнерогов.', 'Горр\'тог мертв. Самое время закрепиться в Цитадели Камнерогов. Я буду ждать тебя внизу. Приходи, и мы начнем укреплять наши позиции.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33660, 'ruRU', 'Позаимствовать у саблеронов', 'Найдите $1oa |4пучок:пучка:пучков; благословенных трав в кладах саблеронов на Парящем утесе.', '<Сундук забит старыми частями тел животных и прочим мусором. Порывшись в сундуке, вы нашли пучок благословенных трав и растений.$b$bЕсли найти и собрать достаточно трав, а потом отнести их Рактот, она захочет вам помочь.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33661, 'ruRU', '\"Реагенты\" Парящего утеса', 'Заберите $1oa |4сердце у живого саблерона:сердца у живых саблеронов:сердец у живых саблеронов; на Парящем утесе.', 'Вот мы и подошли к сути проблемы. Сердца саблеронов обладают большой силой. Наши шаманы нашли множество способов их применения.$b$bЯ начну поиски магии древних, если ты принесешь мне сердца. Договорились?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33662, 'ruRU', 'Рожебой против Валуна', 'Разбейте преграждающий путь валун с помощью гладиатора Рожебоя.', 'После того, как саблероны ограбили растения, им пришлось забаррикадироваться выше на Парящем утесе. У меня не получилось найти проход, но ты сможешь решить эту проблему.$b$bОдна из троп перегорожена валуном, но его можно разбить. Сильный огр справился бы с подобной задачей.$b$bКажется, ты знаешь огра-гладиатора...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33663, 'ruRU', 'Крошшер против саблеронов', 'Разрубите лозы с помощью крошшера.', 'После того, как саблероны ограбили растения, им пришлось забаррикадироваться выше на Парящем утесе. У меня не получилось найти проход, но ты сможешь решить эту проблему.$b$bОдна из троп перегорожена толстыми лианами. Кажется, у тебя есть машина, которая может с легкостью их перерезать.$b$bКрошшер без проблем с ними справится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33664, 'ruRU', 'Vignette: Blademaster Zaruk', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33685, 'ruRU', 'Посол к древнему', 'Поговорите с Березусом в Погибели Дионора в Горгронде.', 'Это странное \"дерево\" все время плачет и стонет, но не проявляет агрессии.$b$bПойди и разведай, знает ли оно, как избавиться от растений.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33689, 'ruRU', 'Подрезка ветвей', 'Убейте $1oa |4защитника:защитников:защитников; в Погибели Дионора.', 'Неподалеку отсюда находится место, где я собирала трофеи и реагенты для клана Веселого Черепа. Не так давно из буйных зарослей пришел огромный монстр-растение, и его сразу убили каменные монстры. На месте смерти растения начали прорастать монстры поменьше, и теперь там невозможно охотиться.$b$bОни отрезали меня от лучшего источника реагентов. Убей их, а я попытаюсь добраться туда и собрать все, что смогу...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33694, 'ruRU', 'Реагенты от Рактот', 'Найдите Рактот в Погибели Дионора в Горгронде.', 'Нам будет тяжело восстановиться после разрушения деревни. Реагенты для шамана \"находит\" наша лучшая охотница – Рактот.$b$bМы давно ее не видели, а реагенты очень нам нужны. Отправляйся туда, где она охотится. Узнай, жива ли она. ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33695, 'ruRU', 'Забрать Цветок Смерти', 'Заберите Цветок Смерти у Владыки дыма Ррыка на Парящем утесе. ', '$p, ты $gпомог:помогла; мне, а теперь я помогу тебе. Цветок, который ты ищешь, находится совсем рядом – в пещере у нового предводителя саблеронов.$b$bУбей его и верни цветок древнему. Надеюсь, что после этого растения уйдут, и я смогу вернуться к охоте...', '', 'Убейте Владыку дыма Ррыка и захватите Цветок Смерти.', 'Владыка дыма Ррык', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33706, 'ruRU', 'Упокоение Дионора', 'Наблюдайте за ритуалом Березуса.', 'Этот цветок – настоящий дар для меня. Теперь я смогу навсегда вернуть Дионора назад в Буйные заросли и покончить с этим кошмаром. Осталось лишь провести ритуал... Наблюдай. Больше ты никогда такого не увидишь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33720, 'ruRU', 'Снова в строю', 'Найдите списанный железный крошшер в пещере неподалеку и заберите его у инженера Дракса.', 'Кетия Крошшерон, \n\nТвои новые железные крошшеры – угроза для наших солдат.\n\nПрототип необходимо списать и спрятать в пещере на побережье Таладора, пока ты его не доработаешь.\n\nПока что этим займется инженер Дракс.\n\nОргрим Молот Рока', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33721, 'ruRU', 'Устройство Газлоу', 'Уничтожьте тайник клана Громоборцев, кузню Черной горы и место высадки.', 'Я обнаружил в лесу несколько особо важных для врага объектов.\n\nТебе нужно будет подобраться к каждому из них и использовать мое средство.\n\nПосле этого объекты будут нейтрализованы – и притом весьма торжественно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33722, 'ruRU', 'Избыток железа', 'Убейте $1oa |4бойца:бойцов:бойцов; Железной Орды на Орунайском берегу.', 'Мы не должны бросаться в бой очертя голову. Прежде чем напасть на самого Оргрима, мы должны уничтожить его войска.\n\nЕсли мы хотим очистить Таладор от Железной Орды, начинать надо здесь, на побережье.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33724, 'ruRU', 'Страницы из тома Х?', 'Найдите $1oa |4страницу:страницы:страниц; руководства на осадном дворе Аркенон.', 'Здесь есть руководство по эксплуатации крошшера, но в нем не хватает многих страниц. Нужно найти как можно больше страниц, и я, возможно, смогу заставить крошшер работать.\n\nСудя по направлению ветра, страницы наверняка унесло на осадный двор Аркенон.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33728, 'ruRU', 'Постоянная бдительность', 'Используйте \"Глаза и уши\" Газлоу.', 'Отлично, отлично! Я разберусь в страницах руководства и сразу же запущу железного крошшера!\n\nА пока я это делаю, взгляни-ка в мои \"Глаза и уши\". Вот туда ты скоро направишься!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33729, 'ruRU', 'Ломать и крошить', 'Убейте $2oa |4бойца:бойцов:бойцов; Железной Орды в Тууреме с помощью железного крошшера.', 'Железный крошшер запущен! Он готов покрошить наших врагов в Тууреме!\n\nОтправляйся туда и уничтожь все на своем пути. Ох, я даже завидую тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33730, 'ruRU', 'Не все идеи одинаково полезны', 'Убейте Кетию Крошшерон в Тууреме.', '-- ОБНАРУЖЕНА МАМА. ВНИМАНИЕ! ВНИМАНИЕ! --', '', '', 'Кетия Крошшерон', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33731, 'ruRU', 'Битва за Шаттрат', 'Отбросьте войска Железной Орды от Шаттрата.', 'Если мы хотим остановить Железную Орду, то должны забыть о предрассудках и сотрудничать – хотя бы ради этой цели.\n\nОрда, Альянс, прошлое, настоящее – перед лицом врага все это не имеет значения.\n\nВместе мы вернем Шаттрат – или погибнем в бою.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33734, 'ruRU', 'Частицы нас самих', 'Найдите инструменты огранщика, куклу Мелани и анналы Арууны.', 'Когда начался пожар, я только и успел, что схватить дочь за руку и броситься наутек. Конечно, это спасло нам жизнь, но сейчас выясняется, что кое-какие вещи все же стоило забрать.$B$BЯ специализируюсь на огранке кристаллов и камней. Без инструментов я обычный беженец.$B$BВсе записи нашего города хранятся в кристалле памяти в главном зале. Если бы я смог его получить, история и знания Арууны не пропали бы бесследно.$B$BИ еще: моя дочь напугана, но она наверняка успокоится, если вернуть ей любимую куклу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33735, 'ruRU', 'Хищение имущества', 'Соберите $1oa |4ящик:ящика:ящиков; со взрывчаткой Железной Орды. ', 'Внизу, на берегу, наши враги выгрузили взрывчатку. Мы должны найти ее, пока нас ею же не взорвали.\n\nРазведка доложила, что ящики со взрывчаткой разбросаны по всему побережью.\n\nПока ты их ищешь, мы с Дуротаном проберемся дальше вглубь территории Железной Орды.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33736, 'ruRU', 'Покорежить железо', 'Уничтожьте $1oa |4осадную машину:осадные машины:осадных машин; Железной Орды.', 'Сами орки – не единственная угроза. Мы заметно ослабили их, но у них остались мощные осадные орудия.\n\nУничтожь осадные орудия с помощью взрывчатки, найденной тобой на берегу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33740, 'ruRU', 'Небо в огне', 'Убейте $1oa |4приверженца-налетчика:приверженцев-налетчиков:приверженцев-налетчиков; в Арууне или копях Арууны.', 'Все случилось так быстро. Сначала леса загорелись от раскаленной добела вспышки света, а потом жуткий ветер раздул огонь по всей Арууне.$B$BЧуть позже из дыма начали спускаться араккоа.$B$BМне нужно отвести Мелани на Путь пилигрима. Оттуда мы сможем отправиться в Приют анахорета, под защиту воздаятелей. Но тут повсюду полно араккоа и бушуют пожары... Что из этого опаснее, еще неизвестно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33748, 'ruRU', 'Tracking Quest -  Saberon Servent Snip Scene', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33749, 'ruRU', 'Награда за квест: Депо', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33750, 'ruRU', 'Награда за квест: Трубопровод', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33754, 'ruRU', 'Мне бы такое зрение', 'Используйте \"Глаза и уши\" Газлоу.', 'Твои союзники прислали советника – гоблина Газлоу, чтобы он помог нам бороться с Железной Ордой. И он уже оказал нам неоценимую помощь.\n\nУ него есть подзорная труба, с ее помощью можно видеть – и, по его словам, даже слышать – все на очень большом расстоянии.\n\nОпробуй этот прибор и сообщи, что удалось увидеть. Я-то больше доверяю своей старой проверенной подзорной трубе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33755, 'ruRU', 'Первая тренировочная гонка: 2 круга', 'Пробегите под аркой, добегите до синей отметки, затем до зеленой отметки, потом до красной отметки, наконец, до фиолетовой отметки и возвращайтесь в игровой лагерь Железных Эльфов.', 'Пробеги под аркой...$BДобеги до синей отметки...$BДобеги до зеленой отметки...$BДобеги до красной отметки... Затем повтори все с самого начала. Да-да, ты не $gослышался:ослышалась; – бежать надо будет два круга!$B$BУдачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33756, 'ruRU', 'Продолжаем гонки!', 'Пробегите под стартовым флагом, добегите до синей отметки, затем до зеленой отметки, потом до красной отметки и снова вернитесь к стартовому флагу.', 'Хочешь снова поучаствовать в гонках? Наш человек!\n\nПосмотрим, сможешь ли ты достичь лучшего результата. Сначала нужно достичь синей отметки, потом зеленой, потом красной и вернуться сюда. Время учитывается, так что ноги в руки!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33761, 'ruRU', 'Записи Барума', 'Проверьте эффекты отшлифованного, отполированного и гармонического кристаллов в Арууне.', '<Этот тяжелый фолиант содержит записи о шлифовке камней и кристаллов Дренора, в том числе несколько подробных диаграмм для сложной огранки.$B$BНа последних страницах собраны варианты огранки камней, которые могут помочь дренеям-воздаятелям в бою.>$B$B\"...отшлифованный кристалл может выявлять слабости...\"$B$B\"...скругленный и отполированный защищает от вредоносных воздействий...\"$B$B\"...оказывается, кристалл может резонировать с жизненной силой носителя!\"', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33765, 'ruRU', 'Лютые враги', 'Убейте 8 магов Бездны из клана Призрачной Луны.', 'Твое прибытие – само по себе уже повод для торжеств, но, боюсь, у нас нет на это времени.$B$BНер\'зул и его клан Призрачной Луны внезапно атаковали поселение дренеев к северу отсюда.$B$BПророк Велен уже поспешил в Телуунскую обсерваторию на помощь, но нам по-прежнему не хватает защитников.$B$BЯ отправляюсь туда. Если хочешь нам помочь, иди в Лесистую лощину и убей всех орков из клана Призрачной Луны, что встретятся на твоем пути.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33772, 'ruRU', '6.0 Invasion Opt-Out', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33784, 'ruRU', 'Башня Гормол', 'Отбейте башню Гормол у огров клана Камнерогов.', 'Пришло время нанести решительный удар по нашим поработителям!$b$bМы отправимся к башне Гормол и отобьем ее у Камнерогов. Отправившись с нами, ты окажешь нам честь.$b$bСадись в седло, и мы вместе ринемся в бой!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33785, 'ruRU', 'Карг Освобожденный', 'Убейте в Гром\'гаре 25 орков из клана Громоборцев.', 'Они забрали моих братьев и сестер.$B$BОни забрали моего волка.$B$B<Карг поднимает топор и пристально осматривает острие.>$B$BИх головы будут нашими трофеями.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33786, 'ruRU', 'Нападение на караван', 'Найдите Караван Фионы в Долине Призрачной Луны.', 'По моим данным, ботани начали уходить все дальше от своей рощи и теперь нападают на путешественников. Это очень странно.$b$bМы уже отправили отряд рангари разбираться с этой проблемой.$b$bА недавно здесь проходил караван из Азерота. Тебе стоит проверить, все ли с ним в порядке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33787, 'ruRU', 'Решение Фионы', 'Добудьте $1oa |4сердце:сердца:сердец; речного чудища, $2oa |4порцию:порции:порций; яда болотного светляка, $3oa |4лист:листа:листьев; строптивого плеточника и $4oa |4лунолист:лунолиста:лунолистов;.', 'На Гидвина напало одно из этих живых растений.$b$bИ, судя по всему, его разбил паралич.$b$bЯ могу сделать целебное зелье, но для него нужно несколько местных ингредиентов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33788, 'ruRU', 'Варево из опасных трав', 'Помогите Фионе сварить целительный эликсир.', 'Гениально! Основа варится на медленном огне, осталось только добавить ингредиенты, которые ты $gпринес:принесла;.$B$BКлади их по одному, а я буду перемешивать и снимать пену. Скажи, когда будешь $gготов:готова;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33793, 'ruRU', 'Глашатаи Бездны', 'Уничтожьте сущность тени, сущность тьмы и сущность страдания.', 'Наши разведчики сделали ужасное открытие, $n.$B$BКолдуны из клана Призрачной Луны призывают из Бездны чудовищ, используя в качестве приманки души пленников.$B$BВнутри уже обретаются три таких монстра – сущность тени, сущность тьмы и сущность страдания.$B$BИх надо немедленно уничтожить, пока они еще не успели вырваться на свободу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33794, 'ruRU', 'Великое спасение', 'Выпустите из клеток $1oa |4пленного дренея:пленных дренеев:пленных дренеев;.', 'Мы обнаружили пленных. Их держат в крепости клана Призрачной Луны.$B$BПрошу тебя, спаси выживших! Торопись! Их крики слышны даже здесь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33795, 'ruRU', 'Звезды зовут', 'Найдите $1oa |4карту:карты:карт; звездного неба.', 'Сила клана Призрачной Луны связана с пониманием знамений и движения звезд. $B$BМного веков они составляли карты звездного неба и истолковывали их. $B$BКогда будешь в крепости, собери несколько таких карт.$B$BМы обратим против врага его же знания.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33807, 'ruRU', 'Освободи наших братьев и сестер', 'Освободите $1oa |4северного волка:северных волков:северных волков; или |4жителя:жителей:жителей; Вор\'гола.', 'Жалкие псы-Громоборцы пускают в ход оружие трусов: цепи и сети.$B$BМногие жители деревни и волки попали в их ловушки.$B$BЕсли освободить пленников, они почтут за честь сражаться вместе с тобой.$b$bМы должны отразить это нападение как можно скорее. Мне нужно возвращаться в Цитадель Камнерогов и продолжить подготовку к битве.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33808, 'ruRU', 'Королева болотных светляков', 'Раздобудьте хвост королевы болотных светляков и принесите его Фионе в Долину Призрачной Луны.', 'Похоже, эти живые растения, что напали на Гидвина, впрыснули ему какой-то яд.$b$bОчень сильный яд.$b$bЧтобы спасти Гидвина, мне понадобится еще один особый ингредиент. Раздобыть его будет труднее прочих.$b$bКак думаешь, $n, справишься?', '', '', 'Королева болотных светляков', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33813, 'ruRU', 'Место подвигу', 'Залейте огонь из ведра и спасите Вихлюшку.', 'Я...<всхлипывает> Я никуда не пойду...<хлюпает> Никуда не пойду без Вихлюшки!$B$BОн... он... не выберется сам!$B$BПотуши огонь!$B$B<Ариаана показывает в противоположный угол комнаты и захлебывается рыданиями.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33814, 'ruRU', 'Быстрое расширение', 'Явитесь к Баросу Алекстону в свой гарнизон в Долине Призрачной Луны.', 'Приветствую, командир.$B$BЯ здесь от имени архитектора Бароса Алекстона.$B$BМы собрали достаточно ресурсов для следующей фазы расширения гарнизона. $B$BОн хотел бы поговорить с вами при первой же возможности.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33815, 'ruRU', 'Песня льда и огня', 'Встретьтесь с Дуротаном.', 'Скольких ты $gспас:спасла; из рабства в Танаане? Этого и разрушения Темного Портала для меня вполне достаточно, чтобы считать тебя $gодним:одной; из нас.$b$bНо Дуротан, наш предводитель, пока еще ничего о тебе не знает. Я хочу представить тебя ему.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33816, 'ruRU', 'Награда за доблесть', 'Ступайте к камню шаманов в Вор\'голе и получите благословение.', 'Ты $gоказал:оказала; моему народу огромную услугу. За это мы хотим воздать тебе почести.$b$bВ моем клане существует обряд посвящения: когда член клана вступает в пору зрелости, он должен вымазаться в крови жертвы, добытой в первую охоту, и возложить окровавленные руки на камень шаманов, чтобы почтить память предков.$b$bЗа то недолгое время, что мы провели вместе, ты уже $gубил:убила; множество таких грозных врагов, с которыми нашим охотникам сталкиваться еще не доводилось. Ступай же, коснись камня шаманов здесь в Вор\'голе и присоединись к нашей стае как $gравный:равная;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33820, 'ruRU', 'Сумеречная поляна', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33823, 'ruRU', 'Tracking Quest - Archaeology - Frostfire - Dig Map #1', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33824, 'ruRU', 'Tracking Quest - Archaeology - Frostfire - Dig Map #2', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33825, 'ruRU', 'Tracking Quest - Archaeology - Frostfire - Dig Map #3', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33826, 'ruRU', 'Где мой волк?!', 'Убейте в Гром\'гаре повелителя зверей Тораша и освободите Нерока.', 'Нерока, моего северного волка, захватили вместе со всеми остальными. Не знаю, где его держат, но этот \"повелитель зверей\", что нас сюда притащил, наверняка в курсе.$B$BВон он – в загонах для зверей – хвалится своими трофеями перед молодыми охотниками.$B$BПосмотрим, как он запоет, когда из его черепа будет торчать мой топор.', '', '', 'Повелитель зверей Тораш', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33828, 'ruRU', 'Главный кузнец', 'Убейте главного осадного кузнеца Уратока в Гром\'гаре.', 'Еще недавно пределом возможностей оружейников Громоборцев было очень большое копье. Скорее всего, орки клана Черной горы прислали сюда какого-то жуткого мастера, который научил их делать пушки.$B$BНам нужно найти этого мастера.', '', 'Выписан из Литейной клана Черной горы.', 'Главный осадный кузнец Ураток', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33833, 'ruRU', 'Разыскиваются: бивни Куу\'рат', 'Убейте Куу\'рат и отнесите ее бивни Эремору в Деревню Эмбаари.', 'Размещено: Эремор.$B$BКровожадная самка элекка невероятных размеров была замечена неподалеку от Сумрачной рощи.$B$BЕе называют Белой Смертью. Она легко впадает в ярость и уже убила нескольких неосторожных путников.$B$BПока что рангари не удалось ее выследить. Если кто-то сможет убить этого зверя, пусть принесет доказательство Эремору в обмен на щедрую награду.', '', 'Убейте ее и заберите ее бивни.', 'Куу\'рат', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33834, 'ruRU', 'Разыскивается: жало Клайи', 'Убейте Клайю и отнесите ее жало Диуне в деревню Эмбаари.', 'Размещено: Диуной.$B$BВ северных лесах Призрачной Луны поселилась королева болотных светляков.$B$BЭта ядовитая тварь охотится на путников на главном торговом пути между деревней Эмбаари и Шаттратом. Пока жизнь торговцев подвергается опасности, цены на товары будут расти.$B$BТому, кто сможет одолеть эту тварь, следует извлечь ее жало в качестве доказательства и принести Диуне в деревню Эмбаари. Торговцы щедро наградят своего спасителя.', '', 'Надо вытащить жало.', 'Клайя', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33836, 'ruRU', 'Разыскивается: Копыто Маа\'руна', 'Добудьте копыто Маа\'руна.', 'Размещено: Оррином$B$BДикий талбук по имени Маа\'рун бродит по холмам к юго-востоку от деревни Эмбаари и к западу от Дракория.$B$BЭто дикое животное напало на моего брата, и теперь он не может встать с постели.$B$BРади безопасности всех местных жителей мы должны уничтожить это злобное существо!$B$BТот, кто принесет мне копыто Маа\'руна, получит щедрую награду.', '', 'Отрежешь его копыто – и получишь свою награду.', 'Маа\'рун', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33837, 'ruRU', 'Тьма наступает', 'Найдите Нер\'зула.', 'Уже началось... вон там, за холмами на юго-востоке.$B$BУ Нер\'зула есть все, чтобы призвать Темную Звезду. Железная Орда нападет на Карабор, этого не избежать. Здесь все и закончится.$B$B$gВоитель:Воительница;, я попрошу тебя выступить вперед и задержать Нер\'зула. Я постараюсь присоединиться к тебе как можно скорее.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33838, 'ruRU', 'Плавильное дело', 'Добудьте $1oa |4кусок:куска:кусков; фомиевой руды с помощью шахтерской кирки На\'Шры.', 'Благодарение духам, что они послали тебя сюда, $gчужак:незнакомка;! Я кую новый клинок и не могу бросить работу на середине.$b$bЧтобы завершить начатое, мне нужно больше руды.$b$bВот, держи мою кирку. Она создана из зубов местных горенов и смазана их кислотой. Входит в любую породу, словно горячий нож в масло.$b$BПринеси мне руду, и я смогу сражаться на твоей стороне с этим клинком.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33839, 'ruRU', 'Tracking Quest: Saw Naaru Purified', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33843, 'ruRU', 'Эпизод: праматерь Риг\'ак', 'Уничтожьте $1oa |4кладку:кладки:кладок; яиц горенов, $2oa |4железоеда:железоедов:железоедов; Ледяной Кузни и праматерь Риг\'ак.', 'Горены опасны для нас – их много, а наш шаман слеп и обессилен.$b$bКонечно, век этих чудовищ короток, но они очень быстро размножаются и растут.$b$BЧтобы справиться с горенами, нам нужно найти их матку, убить ее и уничтожить яйца. Так мы сможем на какое-то время обезопасить себя. Осмотри норы у врат Кузни, а я сделаю так, чтобы горены не напали на след Дрек\'тара.', '', '', '', '', '', 'Вернитесь к Дреке, к Вратам Кузни, что на Хребте Ледяного Огня.', 19865);
INSERT INTO `quest_template_locale` VALUES (33846, 'ruRU', 'Flag: Seen Thrall Cyclone', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33847, 'ruRU', 'Flag: Seen Ga\'nar Rolling Out', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33866, 'ruRU', 'Сокровище: мешочек с травами Вимы', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33867, 'ruRU', 'Сокровище: \"Черный ящик\" звездолета', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33868, 'ruRU', 'Родина Северных Волков', 'Поговорите с Дрек\'таром на месте крушения, что на Хребте Ледяного Огня.', 'Ты $gприбыл:прибыла; в Хребет Ледяного Огня. Дальше тебя направит предсказатель Дрек\'Тар.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33869, 'ruRU', 'Сокровище: рог элекка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33871, 'ruRU', 'Найти провидицу', 'Поговорите с провидицей Малунэ на острове Сгущающихся Сумерек в Таладоре.', 'Мы следили за тобой, $n.$B$BПровидица Малунэ, хранительница воспоминаний, хочет встретиться с тобой, $gпутник:путница;.$B$BОна предсказала появление $gмогучего воина, который:могучей воительницы, которая; остановит тьму. Мы считаем, что $gэтот воин:эта воительница; – ты.$B$BОтправляйся на юг к острову Сгущающихся Сумерек и исполни свою судьбу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33872, 'ruRU', 'Пыль для зелья', 'Соберите 7 горстей пыли тенекрыла с крыльев мотыльков-тенекрылов на острове Сгущающихся Сумерек.', 'Мне казалось, если привести его сюда, я смогу искупить его прегрешения перед Светом. Что я смогу спасти сына! А теперь мой возлюбленный Аруумель превратился в жуткого призрака.$b$bТеперь мне остается лишь исправить свою ошибку.$b$bПринеси мне пыль тенекрыла с крыльев мотыльков, которые водятся на острове Сгущающихся Сумерек. С твоей помощью я изготовлю эликсир, который поможет нам отправиться в страну мертвых и подарить Аруумелю покой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33873, 'ruRU', 'Снадобье Арууны', 'Соберите 60 ягод Арууны на острове Сгущающихся Сумерек.', 'Мне нужна твоя помощь в создании эликсира, который откроет нам двери в царство мертвых.$B$BДля него мне понадобится кое-что из местной флоры. Здесь, на острове, можно набрать ягоды Арууны. Принеси мне столько этих ягод, сколько сможешь унести.$b$bНо предупреждаю, $n, не ешь их сырыми! Их яд убьет тебя за несколько минут!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33874, 'ruRU', 'Покой Аруумеля', 'Войдите в мир духов и уничтожьте видение Аруумеля.', 'Мое призвание – видеть то, что недоступно другим. Я храню воспоминания и читаю их остальным как книгу – но сейчас мои способности притуплены из-за сына.$b$bОн отвернулся от света. Когда он погиб, мысль о том, что его дух не примут в Аукиндон, не давала мне покоя.$B$BМне пришлось поймать его и заточить на этом острове, и теперь он искажает мои воспоминания так, что прочесть их невозможно.$b$bСделай то, что не могу сделать я. Используй этот эликсир, войди в мир духов...$B$B...и уничтожь дух моего сына.', '', '', 'Видение Аруумеля', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33882, 'ruRU', 'Ох уж эти павлинчики!', 'Найдите 7 испуганных павлинчиков и верните их Калебу.', 'Старый подлый Шер\'хаан! Он всегда обижал бедных павлинчиков, но это уже совсем никуда не годится!$b$bМы с моими малышами бежали от демонов – и тут на нас напал он! Все павлинчики в испуге разбежались!$b$bУмоляю, помоги мне их найти!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33883, 'ruRU', 'Сокровище: сокровища Призрачной Луны #2', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33884, 'ruRU', 'Шер\'хааааан!', 'Убейте 8 остроклыких ловцов и уничтожьте Шер\'хаана.', 'Тигры в округе словно взбесились! Эти злобные кошки повсюду!$b$bШер\'хаан – самый ужасный из них! Огромный и свирепый! Храбрый герой, только ты можешь расправиться с ужасным Шер\'хааном и другими тиграми!', '', '', 'Шер\'хаан', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33885, 'ruRU', 'Сокровище: сокровище гавани', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33886, 'ruRU', 'Сокровище: вещи Ронокка', '', '', '', '', '', '', '', '', 19865);
