INSERT INTO `quest_template_locale` VALUES (33891, 'ruRU', 'Сокровище: семечко лунной ивы', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33898, 'ruRU', 'Долой рабовладельцев', 'Убейте $1oa |4огра:огров:огров; Закоптелой шахты.', 'Огры похищают орков моего клана и обращают их в рабство!\n\nУбей для меня парочку, а я буду ждать тут... на случай, если они попытаются бежать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33899, 'ruRU', 'Tracking Quest: Turn on the Holograms', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33900, 'ruRU', 'Tracking Quest: Activated Arkonite 3', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33901, 'ruRU', 'Tracking Quest: Activated Arkonite 4', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33903, 'ruRU', 'Tracking Quest: Activated Arkonite 5', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33905, 'ruRU', 'Закрыть дверь', 'Закройте врата Бездны 3 раза, убив мастеров порталов из клана Призрачной Луны.', 'Орки из клана Призрачной Луны призывают через порталы подкрепления и переправляют на ту сторону пленных дренеев.$B$BЧтобы отбить деревню, нужно уничтожить порталы.$B$BДля этого достаточно убить заклинателей порталов, которые поддерживают пространственные разломы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33906, 'ruRU', 'War Kangaroo!', 'test', 'test', '', '', '', '', '', 'test2 test2 test2 $o1a $o1o', 19865);
INSERT INTO `quest_template_locale` VALUES (33909, 'ruRU', 'Пометка: увидеть появление Га\'нара в форте Камнерогов', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33910, 'ruRU', 'Спасение Акланы', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33914, 'ruRU', 'Gut Guttra', 'Kill Guttra Wolfchew.', 'Guttra Wolfchew\'s hunger can be blamed for this massacre. He will pay with his life for the blood spilled today. $b$bYou can find Guttra up on Grimfrost Hill to the north. Slay him and return to me.$b$bWhen you get back we shall drink to our victory.', '', '', '', '', '', 'Return to Urukag near the Grimfrost Hill in Frostfire Ridge.', 19865);
INSERT INTO `quest_template_locale` VALUES (33915, 'ruRU', 'Юные сердца', 'Найдите Орака и скажите ему, чтобы возвращался к дяде.', 'Мой племянник не замечает ничего вокруг. Захотел доказать свою удаль и снова – снова! – отбился от стаи.$b$bОн очень напоминает меня в юности.$b$bУвидишь Орака – скажи ему, пусть возвращается. Нам еще готовиться к завтрашней охоте.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33916, 'ruRU', 'Сокровища: боевой горн повелителя арены', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33917, 'ruRU', 'Перекрыть поток', 'Уничтожьте $1oa |4пылающий резонатор:пылающих резонатора:пылающих резонаторов; на Пылающей передовой.', 'Мы должны отрезать вражеское подкрепление!$B$BВидишь кристаллы Скверны, парящие над линией фронта? Эти резонаторы питают порталы, сквозь которые приходят свежие отряды демонов. Их нужно уничтожить!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33918, 'ruRU', 'Разыскивается: Грондо', 'Убейте Грондо на Растрескавшихся равнинах.', 'Безумный гронн Грондо бродит по Растрескавшимся равнинам.$b$bЭто чудовище убивает целые стада копытней и пожирает невинных северных волков. Мы должны уничтожить его, пока он не добрался до гарнизона.', '', '', 'Грондо', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33919, 'ruRU', 'Разыскивается: Кишкодав Разрушитель', 'Убейте Кишкодава Разрушителя на Хребте Ледяного Огня.', 'Кишкодав – противник более чем достойный. Собери небольшой отряд и раз и навсегда положи конец его тирании.', '', '', 'Кишкодав Разрушитель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33920, 'ruRU', 'Сердце Аукиндона', 'Отправляйтесь на Пылающую передовую, победите О\'могга Черносерда и верните Караб\'уун.', 'Орки Совета Теней украли Сердце Аукиндона – кристалл, питающий его защитные сооружения! К счастью, ядро и один из четырех осколков удалось спасти.$B$BЧернокнижник О\'могг Черносерд использует Караб\'уун – один из украденных осколков – для подпитки самого большого портала на Пылающей передовой. Верни мне Караб\'уун.', '', '', 'О\'могг Черносерд', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33923, 'ruRU', 'Демоны? В Аукиндоне?', 'Убейте О\'могга Черносерда в Гробнице Света, чтобы закрыть портал демонов.', 'Демоны! Этого мы и боялись.$B$BНельзя позволить покинуть гробницу и подобраться к Аукиндону!$B$BСкорее! Я помогу собрать аукенайских защитников, а тебе нужно закрыть портал, через который демоны приходят в этот мир. Наверняка его открыл сильный чернокнижник. Убей его, и портал будет разрушен!', '', '', '', '', '', 'Доложитесь леди Лиадрин в Лагере Золотой зари.', 19865);
INSERT INTO `quest_template_locale` VALUES (33925, 'ruRU', 'Treasure: Frostwolf Cache 01', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33926, 'ruRU', 'Сокровища: косяк рыбы', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33927, 'ruRU', 'Взрывы в дренейском лагере', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33928, 'ruRU', 'Земля и огонь', 'Отнесите огненное сердце Возжигателю.', 'Похоже, что это расплавленное ядро состоит из мутировавших останков элементаля, состоявшего из огня и земли.$b$bНа плато, где стихии существуют в своей чистейшей форме, этих шлаковых элементалей быть не должно.$b$bЭто ядро нужно отнести Возжигателю у Трона Стихий, чтобы он изучил его более тщательно.$b$bВозможно, великий дух огня после рассказа о вашем поединке сможет разобраться, что это за ядро.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33929, 'ruRU', 'Логово Трясохвоста', 'Найдите родителей Трясохвоста на Хребте Ледяного Огня.', 'Северный волчонок смотрит на вас большими печальными глазами. Затем он начинает скулить, жалобно глядя в пещеру.$b$bТаких маленьких детенышей нечасто встретишь бродящими в одиночку. Родители Трясохвоста наверняка где-то неподалеку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33930, 'ruRU', 'Сокровища: клад саблерона', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33931, 'ruRU', 'Это не задание', 'Помогите Жулии', 'Нам нужна помощь! Но не твоя...', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33933, 'ruRU', 'Сокровище: тлеющие сапоги Жулии', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33938, 'ruRU', 'Событие: огр-шаман стихий', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33940, 'ruRU', 'Сокровища: тайник скального прыгуна', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33942, 'ruRU', 'Treasure: Frostwolf Cache 02', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33944, 'ruRU', 'И элекка тоже?!', 'Верните Рики Калебу. Его можно найти у перевернутой повозки.', 'Кто же так потрепал эту игрушку? Она вся изорвана, отовсюду торчит набивка.$b$bНа задней левой лапе элекка вышито имя – \"Калеб\". Видимо, Шер\'хаан утащил его из повозки. Малыш-дреней будет рад, если ему вернут любимую игрушку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33945, 'ruRU', 'Treasure: Frostwolf Cache 03', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33946, 'ruRU', 'Treasure: Frostwolf Cache 04', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33947, 'ruRU', 'Сокровище: тайник клана Жестокого Холода', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33948, 'ruRU', 'Сокровища: запасы горена', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33949, 'ruRU', 'Treasure: Frostwolf Cache 07', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33955, 'ruRU', 'Пропавшая стая', 'Найдите Трясохвоста в окрестностях Вор\'гола, что на Хребте Ледяного Огня.', 'Интересно, куда делись малыш Трясохвост и его стая? Обычно в это время они приходят на кормежку.$b$bНадеюсь, с ними не приключилось ничего дурного.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33958, 'ruRU', 'В лощину', 'Убейте Ксанатоса Осквернителя в лощине Смертоносной Паутины и верните Ша\'тар.', 'После поражения на Пылающей передовой Совет Теней решил усилить свои войска и распространить влияние Скверны с помощью яда обитающих поблизости пауков-смертоткачей.$B$BОдин из наших стражников душ видел, как некий повелитель ужаса направлялся в шахты на востоке с Ша\'таром – частью Сердца Аукиндона.$B$BУбей повелителя ужаса, обыщи его еще теплый труп, найди Ша\'тар и принеси его мне.', '', '', 'Ксанатос Осквернитель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33960, 'ruRU', 'Таладорский сборщик цветов', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33961, 'ruRU', 'Цветы Ледяного Огня', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33962, 'ruRU', 'Цветы Призрачной Луны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33963, 'ruRU', 'Nagrand Flowerpicker', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33964, 'ruRU', 'Arak Flowerpicker', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33965, 'ruRU', 'Tanaan Flowerpicker', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33966, 'ruRU', 'Gorgrond Flowerpicker', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33967, 'ruRU', 'Паучье жало – лучшее лекарство', 'Добудьте $1oa |4жвало смертоткача:жвала смертоткачей:жвал смертоткачей; в лощине Смертоносной Паутины.', 'Я беспокоюсь за Ниами. Она только и думает, что о возвращении Сердца Аукиндона, и ничто другое не занимает ее.$B$BНет-нет, я нисколько не умаляю ее мудрости, но ты же $gсам:сама; видишь, что творится! Все солдаты, которых мы отправили в шахту, вернулись искусанные пауками-смертоткачами. Их раны нужно обработать как можно скорее!$B$BПрошу тебя, добудь мне жвала этих пауков. Они понадобятся мне, чтобы приготовить противоядие, а сама я не могу отправиться за ними – я должна оставаться здесь и ухаживать за пострадавшими.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33969, 'ruRU', 'Мерзкие осквернители', 'Уничтожьте $1oa |4оскверняющий кристалл:оскверняющих кристалла:оскверняющих кристаллов; в лощине Смертоносной Паутины.', 'Пауки, населившие соседнюю шахту, наводят ужас на все окрестности. При укусе они впрыскивают яд, который изменяет и облик, и сущность их жертв. Местные жители обходят шахту стороной, но я опасаюсь, что Совет Теней планирует использовать этих тварей в своих целях.$B$BРазведка доложила, что их чернокнижники наполняют пауков энергией Скверны, чтобы жертвы смертоткачей становились верными слугами Совета!$B$BМы должны уничтожить оскверняющие кристаллы, чтобы не дать этой порче распространиться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33970, 'ruRU', 'В лощину', 'Убейте Ксанатоса Осквернителя в лощине Смертоносной Паутины и верните Ша\'тар.', 'После поражения на Пылающей передовой Совет Теней решил усилить свои войска и распространить влияние Скверны с помощью яда обитающих поблизости пауков-смертоткачей.$B$BОдин из наших стражников душ видел, как некий повелитель ужаса направлялся в шахты на востоке с Ша\'таром – частью Сердца Аукиндона.$B$BУбей повелителя ужаса, обыщи его еще теплый труп, найди Ша\'тар и принеси его мне.', '', '', 'Ксанатос Осквернитель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33971, 'ruRU', 'Паучье жало – лучшее лекарство', 'Добудьте $1oa |4жвало смертоткача:жвала смертоткачей:жвал смертоткачей; в лощине Смертоносной Паутины.', 'Я беспокоюсь за Ниами. Она только и думает, что о возвращении Сердца Аукиндона, и ничто другое не занимает ее.$B$BНет-нет, я нисколько не умаляю ее мудрости, но ты же $gсам:сама; видишь, что творится! Все солдаты, которых мы отправили в шахту, вернулись искусанные пауками-смертоткачами. Их раны нужно обработать как можно скорее!$B$BПрошу тебя, добудь мне жвала этих пауков. Они понадобятся мне, чтобы приготовить противоядие, а сама я не могу отправиться за ними – я должна оставаться здесь и ухаживать за пострадавшими.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33972, 'ruRU', 'Мерзкие осквернители', 'Уничтожьте $1oa |4оскверняющий кристалл:оскверняющих кристалла:оскверняющих кристаллов; в лощине Смертоносной Паутины.', 'Пауки-смертоткачи – невероятные существа. Их яд искажает облик и сущность жертв.$B$BК сожалению, не мы одни знаем об этом. Совет Теней уже отправил своих чернокнижников в лощину Смертоносной Паутины. Если пауки подвергнутся воздействию энергии Скверны, то укушенные ими существа станут демоническими прислужниками!$B$BМы должны уничтожить оскверняющие кристаллы, не то весь Таладор склонится перед Терон\'кровом!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33973, 'ruRU', 'Последнее желание', 'Заберите семейную реликвию Ахма у мастера клинка Бралока.', 'Спасать меня уже поздно – но спасибо за то, что ты со мной говоришь.\n\nМастер клинка Бралок заставил своих подчиненных морить меня голодом и бить, а еще он забрал ценную реликвию, которая была в нашей семье с тех пор, как мы прибыли на Дренор.\n\nЕсли найдешь ее – покажи, пожалуйста, мне, чтобы я мог умереть спокойно.', '', '', 'Мастер клинка Бралок', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33975, 'ruRU', 'Treasure: Blasting Charges - Rubble A', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33976, 'ruRU', 'Последний фрагмент мозаики', 'Заберите Аук\'наару у Ворпила Реброруба в Телморе.', 'Мои раны слишком тяжелы, |3-6($c). Я не могу сражаться, я подвел свой город и свой народ. Эта битва теперь твоя.$B$BВорпил совсем рядом. Он направляет силы Аук\'наару на проведение темного ритуала.$B$BЗаверши то, что не удалось мне. Срази Ворпила и добудь Аук\'наару, чтобы Сердце Аукиндона снова воссоединилось!', '', '', 'Ворпил Реброруб', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33977, 'ruRU', 'Благословение Волка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33978, 'ruRU', 'Дух Волка', '', '', '', '', '', '', '', '', 19865);
