INSERT INTO `quest_template_locale` VALUES (33987, 'ruRU', 'Первая слежка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33988, 'ruRU', 'Нашествие пожирателей душ', 'Используйте факелы из кузни, чтобы сжечь $2oa |4груду:груды:груд; тел в Телморе.', '<Записка поспешно нацарапана на пергаменте.>$B$BТелмор потерян. Члены Совета Теней стаскивают тела наших павших воинов в груды и кормят их душами своего предводителя. На моих руках кровь...$B$BОбращаюсь к тому, кто читает это: прошу, сожги тела наших бойцов, чтобы враг не смог их использовать.$B$BРесталаан, капитан стражи', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (33989, 'ruRU', 'Treasure: Blasting Charges - Cave A Cache', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33990, 'ruRU', 'Treasure: Blasting Charges - Rubble B', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33991, 'ruRU', 'Treasure: Blasting Charges - Cave B Cache', '', '', '', '', '', '', '', '', 19865);
