INSERT INTO `quest_template_locale` VALUES (33996, 'ruRU', 'Treasure: Blasting Charges - Cave C Cache', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33997, 'ruRU', 'Treasure: Blasting Charges - Rubble D', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (33998, 'ruRU', 'Treasure: Blasting Charges - Cave D Cache', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34012, 'ruRU', 'Как можно больше зубов', 'Соберите $1oa |4коричневый гнилой зуб:коричневых гнилых зуба:коричневых гнилых зубов; огра.', '<Мародер Саша молча протягивает руку и разжимает кулак, показывая ожерелье из коричневых гнилых зубов огров, вплетенных в запачканный кровью кожаный ремешок.>$b$b<На нескольких узелках зубов не хватает.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34013, 'ruRU', 'Вечная память', 'Найдите телморскую учетную книгу, аукенайский молитвенник и Лиственную тень в Телморе.', 'Нам пришлось спешно хватать пожитки и бежать из Телмора.$B$BКто-то вывел из строя маскирующее поле Лиственной тени – полагаю, это был один из нас.$B$BСо временем мы вернем наше имущество, но священные артефакты необходимо спасти сейчас.$B$BНайди Лиственную тень, городскую регистрационную книгу и наш молитвенник и доставь их в безопасное место.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34019, 'ruRU', 'Пробуждение теней', 'Убейте Нер\'зула.', 'Мы сумели загнать Нер\'зула в обсерваторию, но по пути он захватил много заложников.$B$BВ плен попала и сестра Ирель – Самаара.$B$BЯ удерживаю позицию здесь и не могу вызволить ее. Прошу, сделай это за меня, $Gгерой:воительница;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34024, 'ruRU', 'Vignette: Executioner Nozil', 'Collect 3 Fungal Hearts.', 'The second ingredient I will need for the elixir is harder to obtain.$B$BAlong the river roam Marsh Giants - fungal monstrosities whose hunger is never sated. I will need three of their hearts.$B$BThe stronger the heart, the more potent the mixture, and the clearer my vision.', '', '', '', '', '', 'Return to Prophet Velen at Twilight Glade in Shadowmoon Valley.', 19865);
INSERT INTO `quest_template_locale` VALUES (34025, 'ruRU', 'Nuke Bastion Rise Tracking Flag', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34026, 'ruRU', 'Гарнизонная кампания: Сейсмические волнения', 'Поговорите с младшим геодезистом Дорном в своем гарнизоне.', 'Один из наших младших геодезистов уже все уши мне прожужжал о какой-то необычной сейсмической активности. Мне не верится, что мы случайно отстроились на разломе. Проверяли все трижды!$B$BМожешь с ним потолковать?', '', '', '', '', '', 'Поговорите с младшим геодезистом Дорном в своем гарнизоне.', 25549);
INSERT INTO `quest_template_locale` VALUES (34027, 'ruRU', 'Потрясающие данные', 'Используйте улавливатель сотрясений в вашем гарнизоне.', 'Мы тут все трижды перепроверили, прежде чем обосноваться. Все было благополучно, тишина полная.$B$BНо сегодня вдруг раздался какой-то грохот, потом повторился, и он, кажется, приближается! Я точно говорю – что-то тут не так!$B$BДаже не обязательно верить мне на слово – улавливатель сотрясений как раз сейчас закончит сбор и анализ данных. Возьми его с собой и убедись во всем $gсам:сама;!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34028, 'ruRU', 'Что-то очень знакомое...', 'Найдите мастерскую Телина в Горгронде.', 'И зачем это Железной Орде понадобились технологии Черного Железа? Я как раз знаю, кого об этом нужно спросить!$B$BТелин Темная Наковальня – гениальный инженер из клана Черного Железа, который помогает нам на Дреноре. Может быть, вы с ним уже встречались?$B$BГоворят, он построил где-то в Горгронде специальный бункер – типа у него там секретная мастерская или что-то вроде того. Попробуй отыскать его – возможно, ему что-то известно.$B$BТолько прошу, будь осторожнее, хорошо? Хоть дворфы Черного Железа сейчас наши союзники, я им не доверяю ни на грош.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34029, 'ruRU', 'Прототип', 'Используйте прототип буровой установки для поисков Телина Темной Наковальни.', 'Несколько дней назад сюда явилась куча орков Железной Орды. Они схватили Телина и утащили его с собой. Меня оставили в живых, чтобы шантажировать его и заставить сотрудничать.$B$BЯ не знаю, куда они его увели, но знаю, как нам до него добраться.$B$BУ Телина всегда при себе специальный маячок – нет, не спрашивай, где он его прячет. У всех изготовленных им механизмов, способных передвигаться, есть специальная кнопка \"Иди к папочке\".$B$BЕсли разобраться, не самая лучшая идея в случае ходячих бомб... зато для буровой установки – то, что нужно! Залезай и поехали!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34030, 'ruRU', 'Пленный инженер', 'Отыщите Телина Темную Наковальню в осадном лагере Железной Орды.', 'Ах... Прости, $p, но силы окончательно меня покинули. Я сейчас не боец – скорее полуживой, чем полумертвый, и все-таки.$B$BЯ присмотрю за буровой установкой, а ты отправляйся на поиски Телина. Он должен быть где-то рядом!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34031, 'ruRU', 'Это вам на память', 'Заложите в осадном лагере Железной Орды $1oa |4мину:мины:мин; Черного Железа.', 'Железной Орде так нужны мои изобретения? Что ж, тогда я кое-чем с ними поделюсь.$B$BВот эти малышки оторвут у их танка гусеницы и расплавят корпус. Посмотрим, как они теперь вывезут отсюда свои неуклюжие пушки!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34032, 'ruRU', 'Особо ценная информация', 'Заберите записную книжка Телина у властителя Черного Молота в осадном лагере Железной Орды.', 'Я не единственный трофей, доставшийся Железной Орде после налета на мастерскую.$B$BВластитель Черный Молот, маньяк, руководивший той операцией, прихватил мою записную книжку лично для себя.$B$BПроизводственные технологии, чертежи новых изобретений, прикольные розыгрыши...$B$BВ ней все мои секреты!$B$BТы поможешь мне ее вернуть? Я могу на тебя положиться?', '', 'Строго говоря, его молот скорее угольного цвета. Но никто не осмеливается его поправлять.', 'Властитель Черный Молот', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34033, 'ruRU', 'Верхом на буре', 'Отведите Телина Темную Наковальню к Гензелю Большеруку в осадный лагерь Железной Орды.', 'Кажется, мы уже и так заставили Гензеля ждать слишком долго. Ты отведешь меня к нему? А потом мы все вместе уедем отсюда на моей буровой установке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34034, 'ruRU', 'Гарнизонная кампания: Молотящие шестерни', 'Доставьте платеж Газлоу к Грозовому перевалу.', 'Командир! Орки из клана Северного Волка с Грозового перевала сообщили, что слышали в ущелье какой-то жуткий скрежет. Мы думаем, это какая-то боевая машина Железной Орды.$B$BГазлоу уже пошел туда, но теперь требует премии. Что взять с гоблина! Отнеси ему его плату на Грозовой перевал.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34035, 'ruRU', 'Бурная деятельность', 'Помогите Газлоу испортить железную камнедробилку.', 'И правда машина. Бур, да какой здоровенный! К счастью, нам не понадобится его весь разбирать на части.$B$BЭта штука работает по принципу форсированной индукции – спаренные суперзарядники подают на двигатель дополнительную импульсную мощность. Без этой дополнительной мощности бур бесполезен.$B$BПроберись к задней части бура и дерни за рычаг. Это должно отвлечь их внимание от турбин.$B$BО технике я позабочусь сам – а тебе всего-то нужно будет разделаться с ордой кровожадных орков.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34039, 'ruRU', 'Разыскивается: властитель Черный Молот', 'Убейте властителя Черного Молота в осадном лагере Железной Орды.', 'Ну что – в принципе, мы можем уходить. Мы сделали то, за чем пришли, и даже сверх того – я помог Телину сбежать отсюда.$B$BНо остается еще кое-что.$B$B<Газлоу протягивает вам листок бумаги, на котором от руки нарисована морда особенно отвратительного орка.>$B$BЭто объявление ШРУ о награде за голову некого властителя Черного Молота – а он как раз должен быть где-то совсем рядом. Если поможешь мне его завалить, я тебе заплачу. А его голову я представлю Альянсу и получу награду. Все в плюсе!$B$BНу, кроме самого Черного Молота, разумеется.', '', 'Строго говоря, его молот скорее угольного цвета. Но никто не осмеливается его поправлять.', 'Властитель Черный Молот', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34040, 'ruRU', 'Клеймо мастера', 'Осмотрите 5 частей осадной машины в осадном лагере Железной Орды.', 'Ничего не понимаю. Почти весь этот хлам Железной Орды по технической сложности недалеко ушел от каменного топора. Собственно, и сам бур – ничего особенного. Но индукционная система – это нечто. Это, можно сказать, технологический шедевр...$B$BКак-то это не стыкуется!$B$BЯ знаю, еще не раз пожалею, что ввязался в это, но обязательно выясню, кто ее разработал. Надо бы взглянуть на другие машины и механизмы в осадном лагере – может быть, где-то найдется клеймо мастера.$B$B<Газлоу цепляет мешок с золотом к поясу.>$B$BНу что, ты со мной? Хочешь поработать моим телохранителем?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34041, 'ruRU', 'Стопроцентная скидка', 'Украдите шестеренку Черной горы, конденсированный гейзерный газ и обуглившийся сердечник ледяного огня из осадного лагеря Железной Орды.', 'Должен признать, организация поставок в первобытный мир, да еще и в такое неудачное время – довольно сложная задача даже для меня. Приходится довольствоваться тем, что доступно на месте.$B$BВсе-таки что бы там ни говорили про Железную Орду, по части добычи материалов они большие доки!$B$BСмотри внимательно по сторонам – наверняка у них тут в осадном лагере полно ценных и дефицитных вещей. Я прихватил с собой несколько турбоцыплят – с их помощью мы сможем переправить отсюда в твой гарнизон самые ценные вещицы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34042, 'ruRU', 'Коллега-механик', 'Отыщите Телина Темную Наковальню в осадном лагере Железной Орды.', 'Не может быть, чтобы Телин продался. Это исключено! Наверняка они держат его в плену где-то в окрестностях.$B$BПошли, $p. Я знаю, что он сотрудничает с Альянсом и что вы не друзья, но если Железная Орда воспользуется его наработками, хуже будет всем, можешь не сомневаться!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34043, 'ruRU', 'Непроглядная ночь', 'Поговорите с Пророком Веленом у Крепости Страданий.', 'Этот ключ поможет попасть в Крепость Страданий.$B$BВозьмите его и встретьтесь с Пророком Веленом у крепости Долины Призрачной Луны.$B$BОн хочет атаковать Нер\'зула.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34047, 'ruRU', 'Tuurem Explosion Tracker', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34048, 'ruRU', '\"Буровая установка, домой!\"', 'Отправьте домой из осадного лагеря Железной Орды 5 буровых установок.', 'Моя запатентованная голосовая команда \"Иди к папочке\" – это только первый шаг.$B$BЯ также запрограммировал во всех своих буровых установках инструкцию \"Иди домой\", которая заставляет их бурить в заданном направлении – а конкретно, в сторону моей мастерской в Горгронде!$B$BТак что давай-ка отправим моих красоток домой, пока орки окончательно не провоняли их своими потными кожаными портками.$B$B<Вы слышите, как Телина слегка подташнивает внутри его Рободворфа.>$B$BФу!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34053, 'ruRU', 'SoL Conversation Tracker', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34054, 'ruRU', 'Темная сторона Луны', 'Найдите Нер\'зула.', '<голос Пророка Велена продолжает>$B$BНам с Ирель удалось найти Нер\'зула. Он встречается с Громмашем Адским Криком на вершине самого высокого алтаря около Крепости Страданий.$B$BПриходи туда. Нам надо остановить его.', '', '', 'Пророк Велен', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34060, 'ruRU', 'Krasarang RRP - Daily Vignette - Rogue Boss', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34061, 'ruRU', 'Krasarang RRP - Daily Vignette - Priest Boss', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34062, 'ruRU', 'Krasarang RRP - Daily Vignette - Warrior Boss', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34066, 'ruRU', 'Беспощадная месть', 'Убейте 10 железных громостражей у Костей Агурака, что на Хребте Ледяного Огня.', 'Громоборцы – настоящая напасть, $n.$b$b<Рук\'ган сплевывает с отвращением.>$b$bОни убили мою дочь Гришну. Лишь кровь этих тварей вернет мне покой.$b$bЕсли хочешь мне помочь, отвлеки их, а я подберусь поближе к лагерю.$b$bЕсли удастся прирезать нескольких \"железных громостражей\", как называют их орки, будет просто отлично.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34067, 'ruRU', 'В поисках веревок', 'Заберите 5 мотков прочной веревки у укротителей из клана Громоборцев у Костей Агурака.', 'Очень толстый канат, его используют укротители из клана Громоборцев, чтобы справляться с опасными зверями.$b$bРазведчик Рук\'ган сможет найти для него применение.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34068, 'ruRU', 'Эпизод: Каменное Копыто', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34069, 'ruRU', 'Добавить остроты', 'Соберите 5 копий Громоборцев у Костей Агурака.', 'Копье Громоборцев – невероятно легкое и крепкое.$b$bРазведчик Рук\'ган наверняка придумает, как его можно использовать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34070, 'ruRU', 'Сколько веревочке ни виться…', 'Используйте зазубренный гарпун, чтобы убить 5 небесных наездников из клана Громоборцев.', 'Благодаря собранным тобой копьям и веревкам мы сможем убить небесных наездников из клана Громоборцев! Мой гнев сбросит их на землю!$b$bИз копий, привязанных к веревкам, получились отличные гарпуны. Отправляйся на охоту за небесными наездниками, которые летают в долине. Брось гарпун, когда наездник будет пролетать рядом. Если прицелишься как следует, то сможешь притянуть его к себе!$b$bА если не прицелишься... ну... лучше все-таки прицеливайся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34072, 'ruRU', 'Полезная смола', 'Соберите 5 шариков липкой смолы с пятен черной смолы у Костей Агурака.', 'Этот отряд Громоборцев возглавляет генерал Вул\'гат. Он трус – прячется в своей хижине и оттуда отдает приказы воинам.$b$bНадо показать ему, что его жалкая защита не выстоит против Северных волков!$b$bДля этого мне потребуется смола. К югу отсюда есть смоляные ямы, живущие там слизнюки – хороший источник смолы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34073, 'ruRU', 'Сжечь дотла', 'Сожгите инкубаторы рилаков Громоборцев в Погибели Агурака.', 'Пора начать атаку, $n!$b$bСпустись к Погибели Агурака и сбрось смоляные бомбы на инкубаторы рилаков.$b$bА я в это время проберусь в лагерь и подготовлю все к следующему этапу атаки. Встреть меня там, когда все сожжешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34075, 'ruRU', 'Смерть Вул\'гата', 'Убейте генерала Вул\'гата в Погибели Агурака.', 'Время Вул\'гата подошло к концу, $n. Он убил мою дочь! Возмездие настигнет его! $b$bЗабудь о милосердии и уничтожь его!', '', 'Повсюду таскает своего питомца Кровобрюха.', 'Генерал Вул\'гат', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34076, 'ruRU', 'Погребальные поля', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34078, 'ruRU', 'Счет за услуги', 'Выведите Газлоу на крышу крепости властителя Черного Молота в осадном лагере Железной Орды.', 'Нужно скорее уносить отсюда ноги, но ломиться через толпу орков – не вариант.$B$BК счастью, у меня с собой есть несколько турбоцыплят, так что мы можем вернуться в твой гарнизон быстро и эффектно! Нужно вылезти на крышу и поискать подходящее место для взлета.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34087, 'ruRU', 'Мне бы такое зрение', 'Осмотрите местность с помощью обозревательного гирокоптера Телина.', 'Твой союзник Телин помогает нам бороться с Железной Ордой.\n\nОн утверждает, что это его устройство позволяет шпионить за врагом и даже подслушивать разговоры на огромном расстоянии.\n\nЯ скептически отношусь к подобным устройствам. Испытай этот гирокоптер и доложи о результатах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34088, 'ruRU', 'Избыток железа', 'Убейте $1oa |4бойца:бойцов:бойцов; Железной Орды на лесозаготовках Мор\'грана.', 'Мы должны уничтожить войска Железной Орды, заполонившие наши земли.\n\nОтыщи тех, кто собирается осквернить наш великий лес, и сверши над ними правосудие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34089, 'ruRU', 'Хищение имущества', 'Соберите $1oa |4ящик:ящика:ящиков; со взрывчаткой Железной Орды. ', 'На своей лесопилке Железная Орда хранит взрывные устройства.\n\nНужно их забрать, чтобы их не смогли использовать против нас.\n\nЯ буду приглядывать за Мараадом... Боюсь за него, когда он выходит из себя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34090, 'ruRU', 'Устройство Телина', 'Уничтожьте тайник клана Громоборцев, кузню Черной горы и хранилище бревен.', 'Орки обожают сваливать свое добро в одну кучу. Что и навело меня на одну неплохую мысль...\n\nИ в результате у меня появилось гениальное устройство! Вот, хочу отдать его тебе! Когда подойдешь достаточно близко к цели, оно сообщит тебе об этом. Ну, и ты его задействуешь, чтобы получился большой и бодрый БУМ!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34091, 'ruRU', 'Снова в строю', 'Убейте инженера Трака и заберите списанный железный крошшер.', 'Кетия Крошшерон,\n\nтвои новые железные крошшеры опасны для наших же солдат.\n\nСними прототип с вооружения и держи его в безопасном месте, пока не исправишь все недочеты.\n\nЯ же отправлю на работу с ним инженера Трака.\n\n- Оргрим Молот Рока', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34092, 'ruRU', 'Крайние меры', 'Найдите анго\'рошскую книгу заклинаний и гримуар связывания, затем проведите ритуал у анго\'рошского ритуального факела в руинах Анго\'рош.', 'Мы обнаружили Терон\'крова, но его войско слишком сильно – с такой сильной армией мы еще не сталкивались. Нам нужно получить преимущество, и как можно быстрее.$B$BНеподалеку отсюда есть руины, в них обитают проклятые духи огров клана Анго\'рош, наших давних врагов. Отправляйся туда и найди Анго\'рошскую книгу заклинаний и гримуар связывания.$B$BПроведи у алтаря описанный в них ритуал, чтобы снять с духов проклятие – а затем попроси их о помощи.$B$BНадежды на успех мало, но выбора у нас нет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34093, 'ruRU', 'Добавить остроты', 'Соберите 5 зазубренных копий клана Громоборцев у Костей Агурака.', 'Эти Громоборцы, кружащие над нами на своих рилаках, настоящая беда, $n.$b$bОни летают по долине, думая, что могут безнаказанно закидывать нас копьями. Надо показать им, что возмездие Северных волков все равно настигнет их!$b$bПлан у меня есть, но нужно собрать кое-какие материалы. Поищи в долине их копья, только целые. Думаю, пяти штук хватит.', '', '', '', '', '', 'Вернитесь к разведчику Рук\'гану к Костям Агурака, что на Хребте Ледяного Огня.', 19865);
INSERT INTO `quest_template_locale` VALUES (34094, 'ruRU', 'Страницы из тома Х?', 'Найдите $1oa |4страницу:страницы:страниц; руководства по эксплуатации на осадном дворе Аркенон.', 'В кабине крошшера есть руководство по эксплуатации, да вот страниц в нем не хватает. Сумеем их отыскать – точно заставлю этот прототип крошшера заработать, зуб даю! \n\nВот я не я буду – несколько страниц точно летало по осадному двору Аркенон. И сейчас они запросто могут быть у тамошних орков.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34095, 'ruRU', 'Покорежить железо', 'Уничтожьте $1oa |4осадную машину Железной Орды:осадные машины Железной Орды:осадных машин Железной Орды;.', 'Сами по себе орки – не единственная опасность. Нельзя упускать из виду их мощные осадные орудия.\n\nОни уже пустили их в ход в Тууреме, и нельзя допустить, чтобы это повторилось и здесь.\n\nВыведи из строя осадные орудия с помощью взрывчатки, найденной на лесопилке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34096, 'ruRU', 'Постоянная бдительность', 'Осмотрите местность с помощью обозревательного гирокоптера Телина.', 'Все, сейчас вот запущу прототип крошшера!\n\nНа вот, глянь в мой обозревательный гирокоптер. Увидишь, чего стоит ждать...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34097, 'ruRU', 'Ломать и крушить', 'Убейте $2oa |4бойца:бойцов:бойцов; Железной Орды в Тууреме с помощью железного крошшера.', 'Теперь прототип крошшера работает почти на полную мощность.\n\nНу и удивятся же они, когда их станет давить собственная машина!\n\nНе терпится посмотреть на все это из безопасного места – через мой обозревательный гирокоптер.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34098, 'ruRU', 'Не все идеи одинаково полезны', 'Победите Кетию Крошшерон.', '-- ОБНАРУЖЕНА МАМА. ВНИМАНИЕ! ВНИМАНИЕ! --', '', '', 'Кетия Крошшерон', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34099, 'ruRU', 'Битва за Шаттрат', 'Отбросьте войска Железной Орды от Шаттрата.', 'Если мы хотим остановить Железную Орду, то должны забыть о предрассудках и сотрудничать – хотя бы ради этой цели.\n\nОрда, Альянс, прошлое, настоящее – перед лицом врага все это не имеет значения.\n\nВместе мы вернем себе Шаттрат – или погибнем в бою.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34101, 'ruRU', 'Vignette: Aruumel\'s Worn Mace', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34102, 'ruRU', 'Символ непокорности', 'Воткните знамена клана Северного Волка в трупы 6 орков из клана Громоборцев в Погибели Агурака.', 'Глядя на знамя клана, вы вспоминаете все битвы, что привели вас и Северных Волков сюда.$b$bРук\'ган устал терпеть поражения в битвах с Громоборцами и не отказался бы от помощи. $b$bВы смотрите на развевающееся знамя и понимаете, что нужно громко заявить о победе Северных Волков над грозным противником.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34103, 'ruRU', 'Разыскивается: Кил\'уун', 'Выследите Кил\'ууна и принесите его клюв Патрику Мессеру.', 'Командир, мне предложили награду за птицу. Да, за птицу.$B$BВсе дело в том, что это огроменная тварь – и в последний раз ее видели в паре шагов от базы Орды, в лесу к югу отсюда. Местные называют ее Кил\'уун.$B$BВот если б ты $gпринес:принесла; мне ее клюв, то, честное слово, мы бы озолотились!', '', '', 'Кил\'уун', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34104, 'ruRU', 'Разыскивается: Хилаани', 'Убейте Хилаани и принесите груду мяса речного чудища Патрику Мессеру.', 'О\'Райли хочет отблагодарить наших крестьян за упорную работу – угостить их мясом речного чудища. $B$BКомандир, мне неудобно целый день отрывать тебя от дел и просить убивать разных тварей. Но нам тут сообщили, что в озере к югу отсюда живет огромное речное чудище по имени Хилаани.$B$BЕсли сможешь добыть его мясо, наши люди будут очень тебе благодарны.', '', '', 'Хилаани', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34105, 'ruRU', 'Разыскивается: Ра\'ток Молот', 'Устраните Ра\'ток Молот на Орунайском берегу.', 'Командир, тут есть одно дело, в котором мне бы пригодилась твоя помощь.$B$BНаши люди видели на скалах неподалеку отсюда лейтенанта Железной Орды. Мы полагаем, она направляет их войска, прибывающие на Орунайский берег, к стратегически важной позиции.$B$BМне было бы гораздо спокойнее за мой форт, если бы ты ее $gуничтожил:уничтожила;.', '', '', 'Ра\'ток Молот', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34106, 'ruRU', 'Разыскивается: Ра\'ток Молот', 'Убейте Ра\'ток Молот на Орунайском берегу.', 'Железная Орда не имеет понятия о чести. Они отвратительны.$B$BОдного из их командиров мы заметили на скалах неподалеку от нашей базы. Кажется, эта женщина-орк следит за нашими передвижениями, готовя наступление с Орунайского берега.$B$BКомандир, я понимаю, что у тебя много дел. Но если ты ее уничтожишь, то ликвидируешь угрозу нашим позициям.', '', '', 'Ра\'ток Молот', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34107, 'ruRU', 'Разыскивается: Хилаани', 'Убейте Хилаани и принесите груду мяса речного чудища повелителю зверей Таху.', 'Командир, нам нужно больше мяса.$B$BЯ знаю, о чем ты думаешь. У меня же целая гора мяса за спиной!$B$BВ том-то все и дело. В лучшем случае этого нам хватит на день.$B$BВ озере к югу отсюда живет речное чудище. Местные называют ее Хилаани. Вот это огромная туша.$B$BЕсли убьешь животное и принесешь мне мясо, твоим же волкам будет лучше.', '', '', 'Хилаани', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34108, 'ruRU', 'Разыскивается: Кил\'уун', 'Принесите клюв Кил\'ууна повелителю зверей Таху.', 'Проклятая птица!$B$BКаждые пару часов она нагло тут пролетает, и никто из этих простофиль ее не подстрелит.$B$BГоворят: \"У нее глаза безумные\". Пфф!$B$BКомандир, эта птица меня в гроб вгонит. Если увидишь эту тварь, может, отрубишь ее дурную башку и принесешь мне?$B$BОт этого мне сразу полегчает.', '', '', 'Кил\'уун', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34110, 'ruRU', 'Vignette: Girl 1 Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34111, 'ruRU', 'Vignette: Girl 2 Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34112, 'ruRU', 'Vignette: Guy 1 Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34113, 'ruRU', 'Vignette: Guy 2 Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34114, 'ruRU', 'Vignette: Four Friends Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34115, 'ruRU', 'Vignette: Four Friends Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34116, 'ruRU', 'Vignette: Girl 1 Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34117, 'ruRU', 'Vignette: Girl 2 Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34118, 'ruRU', 'Vignette: Guy 1 Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34119, 'ruRU', 'Vignette: Guy 2 Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34122, 'ruRU', 'Дипломатия огров', 'Убейте $1oa |4духа огров или питомцев:духов огров или питомцев:духов огров или питомцев; клана Анго\'рош в руинах Анго\'рош.', 'Может, это и духи, но все равно при жизни они были ограми. Даже если ты возьмешь в руки их книги, духи не признают тебя до тех пор, пока ты не покажешь себя в деле. И сделать это можно только одним способом.$B$BУбивая их.$B$BТебе придется уничтожить как можно больше духов огров клана Анго\'рош и их питомцев.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34123, 'ruRU', 'На Грозовой перевал', 'Поговорите с Локрой на Волчьей заставе.', 'Сейчас не время оплакивать павших и зализывать раны. Наши разведчики сообщили, что большая армия Железной Орды двинулась через Грозовой перевал.$b$bСоветую тебе направить силы гарнизона на защиту близлежащей территории, а мы тем временем отправимся к перевалу с оставшимися Северными Волками.$b$bПора показать Железной Орде, на что способен клан Северного Волка.', '', '', '', '', '', 'Поговорите с Локрой на Волчьей заставе.', 25549);
INSERT INTO `quest_template_locale` VALUES (34124, 'ruRU', 'Битва за Грозовой перевал', 'Защитите Хребет Ледяного Огня от захватчиков из Железной Орды.', 'По Грозовому перевалу уже идет армия Железной Орды, она в десять раз больше нашей.$b$bДуротан собирает наши войска у выхода из ущелья. Он делает все, чтобы организовать оборону, но мы, Северные Волки, не привыкли к таким масштабным сражениям.$b$bЕму нужна твоя помощь.$b$bПожалуйста, разыщи его.', '', '', '', '', '', '', 25549);
