INSERT INTO `quest_template_locale` VALUES (34144, 'ruRU', 'Воздаяние Света', 'Убейте $1oa |4демона:демонов:демонов; в Гул\'роке.', 'Шпионы Тьмы окружают нас и всеми силами стараются захватить мир. Мы – последняя надежда Света на сохранение равновесия.$B$BТебе хватит сил, чтобы уничтожить демонов-слуг Терон\'крова раз и навсегда. Сокруши их и отправь в Круговерть Пустоты!', '', '', '', '', '', '', 25549);
