INSERT INTO `quest_template_locale` VALUES (34154, 'ruRU', 'Пункт назначения: неизвестно', 'Уничтожьте Темнорода в руинах Ксандроса.', 'Терон\'кров и Гул\'дан как раз уходили через портал... а я... Я знаю, что не смогу их одолеть.$B$BПостараюсь держать портал открытым как можно дольше. Но нанести последний удар $gдолжен:должна; ты, $n.$B$BНаша судьба – в твоих руках.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34155, 'ruRU', 'Treasure: Gorgrond Treasure 06', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34157, 'ruRU', 'В сердце безумия', 'Поговорите со стражницей душ Ниами у Трона Порочности в Гул\'роке.', '$n, Ниами сбежала, чтобы напасть на Терон\'крова!$B$BТебе нужно ее найти. В одиночку она с ним не справится.$B$BА мне нужно остаться здесь и реорганизовать войска на случай нового нападения. Я рассчитываю на тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34160, 'ruRU', 'Vignette: Nixxie the Goblin', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34162, 'ruRU', 'Vignette: Icklarv', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34163, 'ruRU', 'Затаившийся во тьме', 'Уничтожьте 3 сферы Тьмы в Гул\'роке.', '<Голос Терон\'крова проникает в ваш разум.>$B$BСлуги мои, аукенаи не должны узнать о последнем этапе нашего плана. Используйте сферы Тьмы, которые дал нам Гул\'дан, и погрузите Гул\'рок во мрак.$B$BПодготовьте войска. Выдвигаемся в Аукиндон по моему приказу. Мы насытимся душами дренеев и откроем нашим союзникам-демонам путь в этот мир!$B$B<Если уничтожить сферы Тьмы, это очень поможет защитникам Аукиндона.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34164, 'ruRU', 'Сожжение книг', 'Добудьте 3 книги заклинаний Совета Теней и сожгите их в костре возле Кор\'тоса Ярости Зари в Гул\'роке.', '$n, прошу тебя... у меня мало времени.$B$BСовет Теней позволил, чтобы Терон\'кров и его чернокнижники превратили их в демонов!$B$BУ меня есть основания полагать, что темные похитители разума используют заклинания, которым их научил Гул\'дан, чтобы сделать демонических орков еще сильнее. Добудь их книги заклинаний и предай их огню... перед смертью я бы с удовольствием посмотрел, как они горят.', '', '', '', '', '', '', 25549);
