INSERT INTO `quest_template_locale` VALUES (34192, 'ruRU', 'Горе и горены', 'Убейте Камнезуба в шахте гарнизона.', 'Заброшенную шахту заполонили горены! Похоже, они подчиняются какому-то здоровяку, который сидит в глубине туннелей. Если его убить, то остальные наверняка разбегутся сами.$b$bА потом мы сможем возобновить добычу руды!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34193, 'ruRU', 'Расчистка места для сада', 'Убейте 8 грызунов Ледяных скал.', 'В этой пещере просто идеальный климат, чтобы выращивать травы для нашего гарнизона. Есть только одна небольшая помеха. Проклятые грызуны!$b$bНужно истребить их всех до одного – и тогда совсем скоро наш сад расцветет пышным цветом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34194, 'ruRU', 'Поиск помощников', 'Найдите рыбака, который поделится с вами секретом рыбной ловли в этих местах.', 'Мы нашли удобное местечко для рыбалки, но рыба совсем не клюет! Возможно, кто-то из местных рыбаков сможет подсказать, в чем дело. Отправляйся на северо-запад и поищи кого-нибудь на берегу.', '', '', '', '', '', '', 25549);
