INSERT INTO `quest_template_locale` VALUES (34209, 'ruRU', 'Обеспечить прибытие', 'Найдите Кордану Оскверненную Песнь около Тром\'вара на Утесе Морозного Ветра.', 'У нас появилось очень важное дело. Пока тебя не было, ко мне обратился верховный маг Кадгар.$B$BОн занимается изучением деятельности демонов в северных землях.$B$BПоскольку Кадгар человек, Северные волки не примут его у себя, если ты не поручишься за него, – как не примут и ночного эльфа вроде меня.$B$BЯ буду ждать тебя за Тром\'варом на Утесе Морозного Ветра.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34210, 'ruRU', 'Treasure: Gorgrond Treasure 19', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34211, 'ruRU', 'Treasure: Gorgrond Treasure 20', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34214, 'ruRU', 'Treasure: Gorgrond Treasure 21', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34215, 'ruRU', 'Treasure: Gorgrond Treasure 22', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34216, 'ruRU', 'Безопасный проход', 'Выслушайте историю Корданы Оскверненной Песни.', 'Орки клана Северного Волка вряд ли будут рады появлению человека и ночного эльфа.$B$BПожалуйста, представь нас предсказателю в Тром\'варе.$B$BНам нужно многое обсудить. Я введу тебя в курс дела, пока мы добираемся до деревни.', '', '', '', '', '', '', 25549);
