INSERT INTO `quest_template_locale` VALUES (34227, 'ruRU', 'То, что должно', 'Заберите останки Матери Волков и похороните на кладбище к северу от Тром\'вара.', 'Похоже, мы видели демоническую скверну, о которой говорят твои друзья.$B$BВ последнее время Мать Волков сама не своя. Сейчас волки окружили ее.$B$BОни не подпускают к ней наших охотников. Но тебя они вряд ли остановят.$B$BЕсли скверна поразила Мать Волков, ее придется убить.$B$BТы почтишь Северных Волков, если принесешь сюда ее останки и похоронишь ее с подобающими почестями.', '', 'Облегчите страдания Матери Волков и похороните ее останки на кладбище.', 'Мать Волков', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34228, 'ruRU', 'Клубок червей', 'Убейте $1oa |4каменного червя:каменных червей:каменных червей; пустошей.', 'Во время разведки выяснилось, что на Утесе Морозного Ветра полно странных червей.$B$BХуже всего, что эти твари передвигаются под землей и потому могут незаметно подобраться к жертве.$B$BОни нападают на северных волков и других животных. Думаю, оркам не помешает твоя помощь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34229, 'ruRU', 'Спящая проснулась', 'Убейте Шуй Халад.', 'Что-то пробудило великую Шуй Халад. И теперь земля трясется.$B$B<Предсказатель чертит в воздухе охранный знак и продолжает.>$B$BВозможно, великого червя потревожили те, кого ищут твои друзья?$B$BВ любом случае, Шуй Халад надо погрузить в вечный сон, иначе все северные земли погрузятся в океан.', '', 'Срази великого червя!', 'Шуй Халад', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34230, 'ruRU', 'Алчный глаз', 'Добудьте Всевидящее кольцо Огзора Некромага.', 'Мать Волков была поражена демонической магией. Совет Теней наверняка надеялся распространить скверну на других северных волков, а затем – и на Тром\'вар.$B$BОхотники доложили, что заметили горящие зеленые глаза на Костяном дворе Ледяного Шрама, что на западе. Мы все знаем, что это означает.$B$BУ меня идея... мы используем \"глаза\" Совета Теней против них самих, чтобы найти, где они обосновались. Для этого нам нужно Всевидящее кольцо главного чернокнижника.', '', 'Убей его и забери Всевидящее кольцо.', 'Огзор Некромаг', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34231, 'ruRU', 'Vignette: Giant Snake', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34232, 'ruRU', 'Сокровище: рыболовные снасти Рука', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34233, 'ruRU', 'Сокровище: кувшин выдержанного крепкого вина', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34234, 'ruRU', 'Возмездие', 'Уничтожьте $1oa |4бойца:бойцов:бойцов; Совета Теней в Телморе.', 'Мы думали, что завеса Лиственной тени надежно защищает нас.$B$B<Воздаятель Калууд вытирает кровь с лица.>$B$BКто-то рассказал Совету Теней, как снять ее. Мы сдерживали наступление... но только поначалу.$B$BБольшинство наших в городе были убиты при нападении. Прошу, отомсти за них. Сотри врагов с лица Телмора навеки!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34235, 'ruRU', 'Сокровище: светящаяся раковина', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34236, 'ruRU', 'Сокровище: аметиловый кристалл', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34238, 'ruRU', 'Сокровище: коробка с обедом для штейгера', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34239, 'ruRU', 'Сокровище: сокровище Туурема', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34240, 'ruRU', 'Запланированная встреча', 'Поговорите со стражницей душ Туулани возле Телмора.', '$n, ты достойно $gпроявил:проявила; себя в бою. Как ты знаешь, войска Совета Теней могут быть в любом уголке Аукиндона, даже возле Телмора.$B$BТуулани еще не обрела полную силу как жрица душ, она не может защитить осколок в одиночку. Найди ее в Телморе и убедись, что кристалл будет доставлен в Аукиндон целым и невредимым.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34241, 'ruRU', 'Treasure: Gorgrond Treasure 12', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34242, 'ruRU', 'Запланированная встреча', 'Поговорите со стражницей душ Туулани возле Телмора.', '$n, ты достойно $gпроявил:проявила; себя в бою. Как ты знаешь, войска Совета Теней могут поджидать нас в любом уголке Аукиндона, даже возле Телмора.$B$BНайди стражницу душ Туулани в Телморе и охраняй кристалл по пути в Аукиндон. Я знаю, что тебе можно это доверить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34243, 'ruRU', 'Vignette: Rak\'nar Muzzlebash', '', '', '', '', '', '', '', '', 19865);
