INSERT INTO `quest_template_locale` VALUES (34255, 'ruRU', 'Сокровище: покрытый паутиной мешок', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34256, 'ruRU', 'Сокровище: реликвия Телмора', '', '', '', '', '', '', '', '', 19865);
