INSERT INTO `quest_template_locale` VALUES (34260, 'ruRU', 'Сокровище: вагонетка Арууны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34261, 'ruRU', 'Сокровище: вещи Келуу', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34262, 'ruRU', 'Сокровище: вагонетка Арууны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34263, 'ruRU', 'Сокровище: беспримесная пыль кристаллов', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34264, 'ruRU', 'В поисках веревок', 'Заберите 5 мотков прочной веревки у укротителей из клана Громоборцев у Костей Агурака.', 'Громоборцам не избежать моего гнева! Но надо спустить их на землю, чтобы поприветствовать нашими клинками.$b$bУкротители носят с собой веревки, чтобы при необходимости удерживать своих тварей на привязи. Убей их и принеси мне несколько мотков веревки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34271, 'ruRU', 'Судьба Гордауга', 'Добудьте Сердце Гнева.', 'Путь к внутренним покоям преграждает устрашающий Гнев, которого мы так стремились вернуть на Трон Стихий.$b$bГордауг зачарован – он полностью покорился бледнокожим и их таинственному хозяину. Мое сердце опечалено; мне тяжело видеть, что зло поработило это великое существо и лишило разума.$b$bНазад пути нет; ты $gдолжен:должна; одолеть Гнева.$b$bМне больно это говорить, но Гнева необходимо убить.$b$bКогда это будет сделано, мы вернем сердце Гнева к Трону Стихий.', '', 'Смерть – единственный способ вырвать великую ярость из лап Чо\'Галла.', 'Гордауг', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34276, 'ruRU', 'Сокровище: ржавый сейф', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34277, 'ruRU', 'Остановить поток', 'Уничтожьте $1oa |4круг призыва:круга призыва:кругов призыва;.', 'Совет Теней создает магические круги на кладбище. Нам нужно не только убить заклинателей, но и разрушить то, что они успели построить.$B$BУничтожив круги, ты остановишь демонов, которых они призывают и вселяют в трупы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34278, 'ruRU', 'Осквернение могил', 'Убейте $1oa |4некрофита:некрофитов:некрофитов; и |4волка Скверны:волков Скверны:волков Скверны;.', 'Чернокнижники оскверняют тела мертвых на костяном дворе!$B$B<Предсказатель дрожит, не в силах совладать с собой.>$B$BОни должны умереть!$B$BУничтожь некрофитов. Уничтожь их демонических тварей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34279, 'ruRU', 'Я – Блук', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34280, 'ruRU', 'Все тайное становится явным', 'Проследите за Советом Теней.', 'Скажи, когда будешь $gготов:готова;.$B$BМы пробудим силу кольца, чтобы призвать один из их \"глаз\". Тогда мы узнаем, где расположен Совет Теней и чем сейчас занимаются его основатели.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34281, 'ruRU', 'Сбросить оковы', 'Добудьте ключ от оков Кровавого Молота и освободите Овинна Граддока.', 'Они меня здорово отделали. Башка просто раскалывается. Ну да ладно, ничего, жить буду. Но вот цепи эти совершенно лишние.$b$bСможешь достать от них ключ? Он должен быть у большого огра по имени Наб, который бродит где-то на дальней стороне террасы.', '', '', 'Наб Истязатель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34284, 'ruRU', 'Гарнизонная кампания: В поисках Овинна Граддока', 'Отправляйтесь в Земли Каменного Неистовства на Хребте Ледяного Огня и найдите Овинна Граддока.', 'Командир, у меня плохие новости.$b$bАгент Граддок отправился на задание – наблюдать за кланом Кровавого Молота, но не вернулся к назначенному сроку.$b$bЧто-то тут не так, $n.$b$bЕсли Овинн попал в плен, его, наверное, заковали в цепи и бросили к остальным рабам.$b$bНадо отправиться в Земли Каменного Неистовства и попробовать его найти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34285, 'ruRU', 'Вернуть снаряжение', 'Найдите кинжал, палицу и доспехи Овинна.', 'Когда меня схватили, то отобрали все снаряжение. Одни лохмотья остались. Моей палицей они крошат камни, а мой лучший кинжал теперь служит им вилкой за обедом! Что они сделали с моими доспехами, даже думать не хочется. Надеюсь, что они хотя бы в годном состоянии.$b$bМне нужно какое-то время оправиться от ран; да и без снаряжения какой от меня толк в драке. Может, поможешь мне вернуть мое снаряжение?$b$bДоспехи, кажись, лежат в сундуке возле большой сторожевой башни к югу отсюда; кинжал, наверное, где-то на юго-западе, а палица должна быть возле лавовых плато на западе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34286, 'ruRU', 'В поисках правды', 'Найдите Боргала Гибельного Кулака.', 'Так, теперь к делу.$b$bКлан Кровавого Молота выкопал какой-то жуткий артефакт, который они называют Разрушитель Душ. Это темная магия – с ее помощью вождь может обрести огромное могущество. Но могущество это надо постоянно подпитывать свежими душами. Чтобы поддерживать темные чары, он каждый день убивает все новых и новых рабов.$b$bМы должны найти Боргала и навсегда избавиться от Разрушителя Душ!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34287, 'ruRU', 'Очищение душ', 'Очистите $1oa |4обезумевшую душу:обезумевшие души:обезумевших душ;.', 'Разрушитель Душ уничтожает не все души. Некоторые умудряются сопротивляться его влиянию – как я. Большинству повезло меньше – из-за невыносимых страданий их охватило безумие.$B$BПоложи конец их мучениям. Возьми мой осколок души и с его помощью очисти несчастных. Пока они охвачены яростью, осколок души не возымеет действия, поэтому сначала тебе нужно будет победить их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34288, 'ruRU', 'Связывающие тотемы', 'Соберите $1oa |4тотем Боргала:тотема Боргала:тотемов Боргала;.', 'Перед тем как пустить в ход свой жуткий Разрушитель Душ, Боргал с помощью тотемов заставил духов служить ему.$b$bЕсли мы раздобудем несколько таких тотемов, возможно, я смогу понять, каким образом он связан с ними, и, в свою очередь, подействовать через тотемы на него. Тогда он вынужден будет предстать перед нами!$b$bПринеси несколько таких тотемов, и я попробую это сделать. Думаю, пяти должно хватить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34289, 'ruRU', 'Сбежавшие от Разрушителя Душ', 'Расставьте тотемы Боргала, чтобы Орлана могла начать ритуал, затем убейте Боргала.', 'Боргалу пора умереть.$b$bМы должны отправиться в место средоточия силы, где я смогу провести ритуал. На северо-западе отсюда есть разрушенная башня. Она подойдет идеально. Отправляйся туда и расставь тотемы в местах средоточия силы. Мы будем тебя ждать. Когда расставишь тотемы, я проведу ритуал призыва Боргала.$b$bТебе предстоит самая трудная часть работы – убить его!', '', '', 'Боргал Гибельный Кулак', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34290, 'ruRU', 'Сокровище: тайник Кетии', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34291, 'ruRU', 'Дела сердечные', 'Заберите у Фернуса сердце Фернуса.', 'Ты $gзаметил:заметила; магический барьер, защищающий вход в пещеру? Его подпитывают демонические кристаллы.$B$BПылающий Легион имеет привычку использовать демонические останки в качестве ключей к подобным устройствам.$B$BОтправляйся на запад к руинам Ата\'гара. Найди там могучего демона и принеси мне его сердце.$B$BЯ создам в руинах свою проекцию, чтобы тебе не пришлось возвращаться, пока мы не закончим.', '', 'Сердце инфернала поможет вам добраться до Гул\'дана, засевшего в Мрачном пике.', 'Фернус', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34292, 'ruRU', 'Уничтожьте Совет Теней', 'Убейте $1oa членов Совета Теней в руинах Ата\'гара.', 'Эти руины наверняка кишат прихвостнями Совета Теней. Нельзя допустить, чтобы они расползлись по всему Дренору, когда ты покончишь с Гул\'даном.$B$BМы должны истребить их – всех до единого.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34293, 'ruRU', 'Уничтожьте Совет Теней', 'Убейте $1oa членов Совета Теней в руинах Ата\'гара.', 'Эти руины кишат последователями Совета Теней. Нельзя допустить, чтобы они расползлись по всему Дренору, когда с Гул\'даном будет покончено.$B$BМы должны истребить их – всех до единого.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34294, 'ruRU', 'Кристаллы Скверны', 'Уничтожьте кристаллы Скверны.', 'Ключ у тебя есть. Теперь тебе нужно уничтожить кристаллы Скверны.$B$BПосле этого магический барьер, закрывающий вход в Мрачный пик, падет.$B$BТогда ты сможешь войти в пещеру и сразиться с Гул\'даном.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34295, 'ruRU', 'Схватить Гул\'дана', 'Вступите в схватку с Гул\'даном.', 'Гул\'дан прячется в пещере, расположенной внутри Мрачного Пика.$B$BНам известно, что он собирается отправиться в Таладор и Долину Призрачной Луны. Его необходимо схватить любой ценой, $n!$B$BУвидимся в Тром\'варе. Удачи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34309, 'ruRU', 'Гарнизонная кампания: В поисках темной охотницы Бву\'и', 'Отправляйтесь в Земли Каменного Неистовства и найдите темную охотницу Бву\'я.', 'От темной охотницы Бву\'и уже давно не было никаких вестей, командир. $b$bОна отправилась на Хребет Ледяного Огня наблюдать за ограми Кровавого Молота.$b$bЭти огры только надсмотрщики, так что с ней, видать, стряслось что-то из ряда вон выходящее, раз она до сих пор не вернулась.$b$bНаверное, тебе стоит отправиться в Земли Каменного Неистовства и отыскать ее. ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34311, 'ruRU', '6.0 Invasion: Opted Out', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34312, 'ruRU', 'Повелитель магмы', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34313, 'ruRU', 'Орлана Крутобров', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34314, 'ruRU', 'Сбросить оковы', 'Получите ключ от рабских оков Кровавого Молота и освободите темную охотницу Бву\'ю.', 'Короче, слушай. У огров, что на меня напали, был какой-то сильно могучий артефакт. Меня сразу вырубило, а оклемалась я уже тут – с переломанными костями и на цепи. Я воззвала к духам, чтобы они разорвали цепь, – да только, видать, они здесь меня не слышат.$b$bСтало быть, придется по старинке. Тут в пещере ошивается один здоровенный огр, которого звать Ругрум. У него должен быть ключ от моих оков. Воткни ему клинок в брюхо и принеси мне ключ, ага?', '', '', 'Хозяин ямы Ругрум', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34315, 'ruRU', 'Вернуть снаряжение', 'Достаньте снаряжение, копье и маску Бву\'и.', 'Огры меня отделали будь здоров. Руку сломали, пару ребер, хорошо, если селезенка не лопнула – болит, зараза. Но мы, тролли, народ живучий. Оклемаюсь, надо только отдохнуть мальца.$b$bА вот мою снарягу, которую огры забрали, вернуть надо непременно. Мое шмотье они бросили в сундук, что в хибаре к югу отсюда, копье должно быть в сундуке у башни Костекрушителей, а маска, видать, где-то возле лавы валяется! Можешь поискать мой шмот, пока я тут в себя прихожу?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34316, 'ruRU', 'В поисках правды', 'Найдите Боргала Гибельного Кулака.', 'Слушай сюда. Пару ночей назад эти огры откопали какое-то старое шибко сильное колдунство.$b$bЯ бродила возле пещеры, которая за лавой, и тут из мира духов раздался такой дикий вопль – ужас. Заглянула я внутрь, вижу – Боргал, вождь огров, вытягивает из рабов души с помощью какого-то здоровенного колеса. Они его вроде как называют Разрушитель Душ. Я напала на них, но эта штука в меня выстрелила, и из меня разом словно вся сила ушла.$b$bНельзя такое сильное колдунство ограм оставлять.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34318, 'ruRU', 'Связывающие тотемы', 'Соберите $1oa |4тотем Боргала:тотема Боргала:тотемов Боргала;.', 'Перед тем как пустить в ход свой жуткий Разрушитель Душ, Боргал с помощью тотемов заставил духов служить ему.$b$bЕсли мы раздобудем несколько таких тотемов, возможно, я смогу понять, каким образом он связан с ними, и, в свою очередь, подействовать через тотемы на него. Тогда он вынужден будет предстать перед нами!$b$bПринеси несколько таких тотемов, и я попробую это сделать. Думаю, пяти должно хватить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34319, 'ruRU', 'Сбежавшие от Разрушителя Душ', 'Расставьте тотемы Боргала, чтобы Орлана могла начать ритуал, затем убейте Боргала.', 'Боргалу пора умереть.$b$bМы должны отправиться в место средоточия силы, где я смогу провести ритуал. На северо-западе отсюда есть разрушенная башня. Она подойдет идеально. Отправляйся туда и расставь тотемы в местах средоточия силы. Мы будем тебя ждать. Когда расставишь тотемы, я проведу ритуал призыва Боргала.$b$bТебе предстоит самая трудная часть работы – убить его!', '', '', 'Боргал Гибельный Кулак', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34321, 'ruRU', 'Пепел прошлого', 'Молтрон в землях клана Кровавых Молотов просит вас принести ему $1oa пригоршней пепла стихий.', 'Огры – проклятье моего рода. Они призывают моих родичей и превращают в рабов, заставляя трудиться без отдыха, пока их жар не угаснет и они не превратятся в пыль.$b$bИх пепел нужно вернуть в лаву, чтобы они могли переродиться!$b$bОгры хранят этот пепел в мешочках и носят с собой, думая, что он придаст им сил. Убей их и принеси прах моих родичей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34325, 'ruRU', 'Пламя земли', 'Молтрон в землях Кровавого Молота просит вас использовать обожженный самоцвет, чтобы освободить $1oa |4элементаля магмы:элементалей магмы:элементалей магмы;.', 'В недрах земли мне удалось найти способ разрушить заклятья, которые держат мой народ в рабстве, но так можно освободить лишь полностью заточенного. Я не смогу освободиться от заклятия и сам окажусь в плену.$b$bТы, существо из плоти, не из пламени, так что их связывающие заклинания на тебя не подействуют.$b$bПрошу, возьми этот камень и используй его силу, чтобы освободить мой народ!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34326, 'ruRU', 'Переломный момент', 'Поговорите с Ресталааном на Месте Воздаяния.', 'Пора дать врагу отпор. Найди меня на Месте Воздаяния, и мы пойдем в наступление на Совет Теней.$B$BТерон\'кров не поглотит ни единой души, пока мы стоим на его пути! Его тирания закончится сегодня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34328, 'ruRU', 'Выбрано: благословение волка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34329, 'ruRU', 'Выбрано: яростный удар', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34330, 'ruRU', 'Выбрано: стойкость огра', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34331, 'ruRU', 'Выбрано: дух волка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34332, 'ruRU', 'Выбрано: прикосновение пламени', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34333, 'ruRU', 'Выбрано: прикосновение льда', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34335, 'ruRU', 'Гарнизонная кампания: Вороны на поле боя', 'Поговорите с Тизали Вороной на Гряде Небоводья в Горгронде.', 'По результатам твоих донесений из Награнда наши друиды раскинули обширную разведывательную сеть.$B$BМы обнаружили подозрительные раскопки Железной Орды рядом с соляными озерами в западной части Горгронда.$B$BУ нас есть основания полагать, что орки ищут в пустыне ценный артефакт.$B$BЯ собираю небольшой отряд, задача которого – нанести точечный удар по врагу. Им пригодится $gопытный:опытная:c; |3-6($c). Я прошу тебя о помощи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34336, 'ruRU', 'Засада на караван', 'Соберите 5 ящиков с грузом каравана и добудьте голову лейтенанта О\'рока.', 'Видишь этот лагерь Железной Орды на юге, на другом берегу? Мы уже давно за ним следим.$B$BИх лейтенант и командование Железной Орды в Награнде активно обмениваются сообщениями.$B$BНужно разорвать эту связь.$B$BСобери их припасы и принеси мне голову их командира.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34337, 'ruRU', 'Гигантский кратер', 'Поговорите с Чолуной.', 'Ценный артефакт в Кратере Дымных Скал? $B$BДавай попробуем добыть его раньше, чем это сделает Железная Орда.$B$BБудем действовать быстро. Поговори с Чолуной, и отправляемся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34338, 'ruRU', 'Спуск', 'Осмотрите Кратер Дымных Скал.', 'То, что находится на дне этого кратера, совершенно точно представляет большую ценность для Железной Орды, а значит – не меньший интерес и для нас.$B$BМне нужно, чтобы ты $gосмотрел:осмотрела; дно кратера.$B$BПойдешь $gпервым:первой;. Я следом за тобой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34339, 'ruRU', 'Пиршество горенов', 'Соберите 8 набитых желудков и изучите их содержимое.', 'Горены. Кратер буквально кишит ими. Я даже отсюда чую их вонь.$B$BМне кажется, они не примитивны, как кажется на первый взгляд, но для подтверждения такой теории мне нужны дополнительные данные.$B$BЕсли тебе придется убить пару-тройку горенов, посмотришь заодно, что у них было в желудках? Интересно узнать, чем они питаются.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34340, 'ruRU', 'Жаркий прием', 'Используйте термометр Арена возле Шипящего гейзера в Кратере Дымных Скал.', 'Здравствуй, $n. Я уже давно занимаюсь исследованием гейзеров Горгронда.$B$BКратер Дымных Скал – одна из самых крупных кальдер в этом регионе. Но нам все никак не удается отправить туда геологическую экспедицию – опасно, слишком много хищников.$B$BРаз уж ты все равно спускаешься вниз, может быть, заодно измеришь там температуру?$B$BЭто бы очень помогло в исследованиях этих природных образований.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34341, 'ruRU', 'Бьющееся сердце', 'Отнесите сердце Горгорека воеводе Зогу в ваш гарнизон.', 'Одно мы знаем наверняка. К нам в руки попал предмет, имеющий исключительную важность для Железной Орды.$B$BНужно как можно скорее доставить это... \"сердце Горгорека\"... в надежное место.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34344, 'ruRU', 'Ползучие', 'Соберите $1oa |4порцию:порции:порций; яда червей.', 'Тут опасно, босс.$b$bМонстры с великанами кишмя кишат.$b$bНо, знаешь, как говорят лоа моей семьи: \"Не можешь завалить в бою – отрави\".$b$bНам нужен яд червей с Растрескавшихся равнин. Найти этих тварей нелегко, а победить еще сложнее. И вот еще что: осторожнее – там земля трясется.$b$bА я пока тебя тут подожду. Заодно сварю противоядие, на случай, если тебя кто ядовитый куснет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34345, 'ruRU', 'Смертоносная пыльца', 'Соберите $1oa |4лист:листа:листьев; ледоцвета.', 'Мы охотимся на такое... такое здоровенное и свирепое, что нужен другой яд. Много, много яда!$b$bНу, чего скажешь? $gГотов:Готова; цветочки пособирать? Нам нужны листья ледоцвета, они растут в тени камней и уступов на западе Растрескавшихся равнин.$b$bИ будь поосторожнее, босс! Там всякое встречается...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34346, 'ruRU', 'Ледяная ярость', 'Соберите $1oa |4ледяной осколок:ледяных осколка:ледяных осколков;.', 'Ярости Дренора отличаются от элементалей Азерота. Но не питай иллюзий. Некоторые из них те еще падлюки. Да-да, падлюки!$b$bДля нашей ловушки понадобятся хорошие ледяные осколки. Будет отлично, если ты наберешь их у ледяных яростей.$b$bОни бродят по Растрескавшимся равнинам, морозя все, к чему прикасаются. А еще они падлюки!$b$bПринеси-ка несколько ледяных осколков, и мы состряпаем смертельную ловушку. ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34347, 'ruRU', 'Приказы Ярости Клинка', 'Доставьте приказы Ярости Клинка Тизали Вороне на Гряду Небоводья.', 'Лейтенанту О\'року$B$BОтправить элитный отряд в Кратер Дымных Скал.$B$BЗабрать со дна кратера артефакт большой ценности и доставить его в мой командный пункт в северном Таладоре.$B$BОстальные войска отвести к Покою Горгорека. Защитить особь магнарона и подготовить к транспортировке.$B$BПриступить к исполнению немедленно.$B$BЯрость Клинка', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34348, 'ruRU', 'Настоящая добыча', 'Отыщите логово Ледяных Искр и убейте Гроша Могучего.', 'Эй, босс! Ну чего, пора поохотиться на настоящую добычу. На севере есть пещера. В пещере злой огрон, звать его Грош Могучий. У огрона – здоровенная куча шкур и кож. А это добро в гарнизоне всегда нарасхват.$b$bВот особый яд, сваренный из того, что ты $gсобрал:собрала;. Он волшебный – поможет совладать с огроном.$b$bВозьми эти склянки в пещеру. Посмотрим, удастся ли тебе добыть сокровища.', '', 'Этот здоровяк скопил целую кучу добра.', 'Грош Могучий', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34351, 'ruRU', 'Нужно больше пилонов', 'Добудьте $1oa кристаллов каронита и каронитовый пилон в Гробнице Света.', 'Мы прибыли сюда, чтобы забрать запасной каронитовый пилон для поддержки щитов Аукиндона, но войска Совета Теней обнаружили нас и напали!$B$BНужно доставить раненых в Приют экзарха, а у нас по-прежнему нет резервной системы подачи энергии!$B$BПрошу, добудь в гробнице 6 кристаллов каронита и каронитовый пилон и возвращайся ко мне в Приют как можно скорее!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34352, 'ruRU', 'Защитник Темного Прилива', 'Убейте $1oa |4жулика:жуликов:жуликов; и $2oa |4инженера:инженеров:инженеров; Темного Прилива.', '<Рексар наблюдает за тем, как вы осматриваете мертвого гоблина. Вполне очевидно, чего он ждет от вас.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34353, 'ruRU', 'Крах крошшеров', 'Уничтожьте крошшеры Темного Прилива в Гнездовье Темного Прилива.', 'Рилаки беззащитны перед изобретениями Железной Орды. Настоящему охотнику никакие машины для ловли дичи не нужны.$b$bУничтожь железные крошшеры и выродков, которые ими управляют. Я отправлю тебе на помощь духа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34354, 'ruRU', 'Легкая смерть', 'Используйте топор Рексара, чтобы добить раненых рилаков в Гнездовье Темного Прилива.', 'У этих глупцов нет понятия о чести.$b$bКажется, им доставляет удовольствие мучить несчастных тварей. Единственное доброе дело, которое мы теперь можем сделать, это найти раненых рилаков и избавить их от страданий.$b$bВозьми топор и убивай их с одного удара, $n. Эти рилаки заслуживают легкой смерти.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34355, 'ruRU', 'Грязные крысы', 'С помощью крыс уничтожьте беспилотные крошшеры в Гнездовье Темного Прилива.', 'Эти крошшеры меня совсем допекли.$b$bС помощью местных крыс я исследовал остров. К западу отсюда есть несколько беспилотных крошшеров.$b$bКрысы обожают лакомство, которое я тебе дам. Забрось его внутрь беспилотных крошшеров, и крысы уничтожат их изнутри.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34359, 'ruRU', 'Darktide Defender TEST', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34361, 'ruRU', 'Эпизод: костяной червь', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34362, 'ruRU', 'Темные врата', 'Победите Грубнора-воителя и проследуйте за Боргалом.', 'Действовать придется стремительно. $b$bМне довелось видеть, как Боргал создает магические порталы. Возможно, именно через такой он и попытается сбежать. В этом случае нам ничего не останется, как только последовать за ним. Кроме того, от него ни на минуту не отходит Грубнор, его лейтенант – так что, скорее всего, нам предстоит серьезная драка.$b$b<Овинн заглядывает в пещеру.>$b$bТише! Там что-то происходит.', '', 'Он немного туповат.', 'Грубнор-воитель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34364, 'ruRU', 'За Орду!', 'Установите знамя Орды, чтобы основать гарнизон.', 'Без тебя мы бы не достигли этих берегов. Ты возглавишь наши силы на Дреноре. Здесь ты можешь устроить гарнизон.\n\nЯ дам тебе время поставить знамя и заявить свои права на территорию. Если решишь тут обосноваться, Кадгар откроет портал, чтобы привести необходимые подкрепления.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34365, 'ruRU', 'Освобождение рилаков', 'Освободите плененных рилаков из Гнездовья Темного Прилива.', 'Гоблины проводили над рилаками чудовищные эксперименты. Этот глупец дал мне координаты трех мест, где они работали.$b$bОтпусти рилаков на волю. Может быть, на свободе их измученные души смогут обрести покой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34375, 'ruRU', 'За работу', 'Отметьте $1oa |4дерево:дерева:деревьев;.', 'Окей, босс. Нам нужна древесина, чтобы начать строительство гарнизона.\n\nЕсли ты отметишь те деревья, которые нужно срубить, батраки смогут спокойно собрать материалы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34378, 'ruRU', 'Создание гарнизона', 'Проследите за строительством вашего гарнизона с помощью \"Главного обозревателя\".', 'Пора переходить к главному! У нас есть материалы, у нас есть рабочая сила, и кое-что еще.$b$bИтак, начнем строительство!$b$bУ меня целая куча помощников на хребте к западу отсюда.$b$bОни уже должны были организовать твой личный наблюдательный пункт.$b$bОтправляйся туда – оттуда ты сможешь следить за ходом нашей работы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34379, 'ruRU', 'Волчье логово', 'Отправляйтесь в Вор\'гол на рилаке клана Северного волка.', 'Теперь, когда тебе удалось обосноваться здесь, Дуротан просит нас присоединиться к нему. Надеюсь, он примет твою помощь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34380, 'ruRU', 'Объединение Северных волков', 'Попросите Дреку протрубить в боевой горн.', 'Мой брат поторопился и повел нескольких воинов клана на осаду Цитадели Камнерогов, но мы еще не готовы к бою.$b$bДрека ждет у боевого горна. Дай ей знать, что пришла пора созывать клан на бой!$b$bС твоей помощью и боевой мощью твоих войск у нас есть шанс одержать победу над ограми.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34381, 'ruRU', 'Темные врата', 'Победите Грубнора-воителя и проследуйте за Боргалом.', 'В этой пещере огры. Я чую их вонь.$b$bБудь наготове – мы должны быстро их прикончить, пока они не начали колдунство.$b$b<Бву\'я заглядывает в пещеру.>$b$bТы осторожнее – там у них что-то творится.', '', 'Он немного туповат.', 'Грубнор-воитель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34382, 'ruRU', 'Vignette: Grand Warlock Duress', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34392, 'ruRU', 'Конец резни', 'Обезвредьте два шпиля Скверны Темного портала.', '\"Охраняйте Гул\'дана и Совет Теней даже ценой собственной жизни! Без темной магии наших пленников портал работать не будет. Не выполните приказ – и все, что вам дорого, будет уничтожено\".$B$B– Громмаш Адский Крик$b$bПохоже, Железная Орда держит в плену тех, кто поддерживает портал. Обыщите окрестные шпили!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34393, 'ruRU', 'Энергия портала', 'Войдите в реактор душ под Темным порталом и закройте портал.', 'Этот портал поддерживается не механизмами и не волшебством.$b$bОглянись по сторонам, $n. Сердце портала подпитывают воющие души убитых узников.$b$bТело Гул\'дана является проводником между душами и порталом.$b$bПроникни в камеру, что находится под нами, и сделай все, чтобы прервать ритуал. Теперь вся надежда только на тебя, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34397, 'ruRU', 'Ослабление Темного Прилива', 'Убейте предводителей клана Темного Прилива.', 'Это ходячее недоразумение заложило всех своих товарищей, стоило лишь чуточку на него надавить.$b$bНайди руководителей этой операции и принеси мне их головы. В этом задании тебе поможет Харатха.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34398, 'ruRU', 'Темный портал', 'Поговорите с верховным магом Кадгаром у подножия Темного портала в Выжженных землях.', '$B|cFF660000 ВНИМАНИЕ, ГЕРОИ,$b ИСКАТЕЛИ ПРИКЛЮЧЕНИЙ,$b ЗАЩИТНИКИ АЗЕРОТА!|r$b$bВерховный маг Кадгар, герой Второй войны, созывает коалицию сильнейших воинов Азерота, готовых пройти через Темный портал и остановить вторжение Железной Орды в Азерот.$b$bЗащитников, жаждущих славы, ждут у основания Темного портала в Выжженных землях.$b$bБезопасность не гарантируется.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34399, 'ruRU', 'Проблемы с шахтой', 'Поговорите с воздаятелем Доруу.', 'В Иорунской шахте беда!$b$bНедавно мы добыли там невероятно огромный и мощный чародейный кристалл. Однако что-то пошло не так, и энергия кристалла заполнила шахту.$b$bАукенаи уже послали воздаятелей, чтобы помочь нам.$b$bПоговори с воздаятелем Доруу, чтобы узнать, чем ты можешь быть $Gполезен:полезна;. Он ждет в шахте.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34400, 'ruRU', 'Разозленные маноеды', 'Используйте чародейный рассеиватель на $oa |4разозленном маноеде:разозленных маноедах:разозленных маноедах;.', 'Это редкий вид таладорских мотыльков, маноеды. Они питаются пылью чародейных кристаллов из шахты.$b$bОбычно эти мотыльки не представляют серьезной угрозы. Однако, впитав мощную тайную энергию, которая заполнила шахту, они стали весьма агрессивными и нападают на любого на своей территории.$b$bЭтот кристалл настроен на рассеивание энергии. Используй его на разозленных маноедах, чтобы утихомирить их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34401, 'ruRU', 'Чародейская сущность', 'Соберите $1oa |4чародейскую сущность:чародейские сущности:чародейских сущностей;.', 'Келинара не остановится, пока не выкачает всю энергию из чародейского кристалла... уничтожив при этом всю шахту. Чародейский щит, которым она себя прикрывает, нельзя разрушить обычным способом, но у меня есть план.$b$bЕсли бы у меня был фокусирующий кристалл, способный на миг пробить ее щит, с Келинарой можно было бы справиться.$b$bК счастью, это место идеально для того, чтобы его создать. Для начала принеси мне чародейскую сущность существ, обитающих в шахте.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34402, 'ruRU', 'Волки и воины', 'Следуйте за Дуротаном.', 'Возвращение стольких моих сородичей – великое благо для нашего народа, и я благодарю тебя за участие в их судьбе.\n\nИдем со мной. Нам нужно о многом поговорить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34403, 'ruRU', 'Чародейская сущность', 'Соберите $1oa |4чародейскую сущность:чародейские сущности:чародейских сущностей;.', 'Келинара одержима жаждой силы, она угрожает безопасности всех находящихся в этой шахте. Ее надо остановить.$b$bНо, к сожалению, мы ничего не сможем с ней сделать, пока она прикрывается магическим щитом. Нужно найти способ его пробить.$b$bЕсли я построю фокусирующий кристалл, то смогу использовать его для ослабления щита... Займись поиском нужных компонентов.$b$bДля начала мне нужна чародейская сущность кристальных яростней и чародейских призраков, живущих в шахте.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34404, 'ruRU', 'Кристаллы с необычной силой', 'Добудьте $oa |4неотшлифованный кристалл:неотшлифованных кристалла:неотшлифованных кристаллов; силы.', 'Чародейные кристаллы такого размера и мощи редки даже на Дреноре. Не случайно дренеи построили Шаттрат и Аукиндон так близко к шахте.$b$bЯ хочу знать как можно больше об этих кристаллах и их природе.$b$bПринеси мне все неотшлифованные кристаллы силы, какие только найдешь, и я прослежу, чтобы тебя достойно наградили за твой труд.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34405, 'ruRU', 'DEPRECATED - REUSE', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34406, 'ruRU', 'Заложники хаоса', 'Спасите $oa |4раненого шахтера:раненых шахтеров:раненых шахтеров;.', '$n, когда начался хаос, не все дренейские шахтеры выбрались наружу. Многие были ранены и до сих пор находятся в шахте.$b$bДействия Келинары привели к ужасающим последствиям. Чародейские призраки рождаются из высвобожденной энергии и атакуют все живое. Спавшие под землей элементали выходят наружу – яростные и опасные.$b$bПрошу, найди как можно больше раненых шахтеров и выведи их наружу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34407, 'ruRU', 'Держать строй', 'Убейте $1oa |4демона:демонов:демонов; на Пылающей передовой.', 'Рад снова видеть тебя, $gвоитель:воительница;.$B$BНа Аукиндон напали демоны, и мы едва сдерживаем их натиск.$B$BНужно отодвинуть линию фронта, иначе потерь станет слишком много.$B$BЕсли ты с нами, воткни свой клинок в горло каждому демону, которого встретишь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34409, 'ruRU', 'Гарнизонная кампания: Вороны на поле боя', 'Поговорите с Тизали Вороной на Гряде Небоводья в Горгронде.', 'По результатам твоих донесений из Награнда наши друиды раскинули обширную разведывательную сеть.$B$BПо их наблюдениям, Железная Орда ведет раскопки у соляных озер на западном побережье.$B$BУ нас есть основания полагать, что орки ищут в пустыне ценный артефакт.$B$BЯ собираю небольшой отряд, задача которого – нанести точечный удар по врагу, и хочу, чтобы ты тоже $gпринял:приняла; участие в этой операции.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34410, 'ruRU', 'Бьющееся сердце', 'Отнесите сердце Горгорека Мортису Шелесту Крыла в ваш гарнизон.', 'Одно мы знаем наверняка. К нам в руки попал предмет, имеющий исключительную важность для Железной Орды.$B$BНужно как можно скорее доставить это... \"сердце Горгорека\"... в надежное место.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34411, 'ruRU', 'Сокровище существа: слякоч-повелитель', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34412, 'ruRU', 'Сокровище существа: Криворот', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34414, 'ruRU', 'Гигант Ан\'дур', 'Добудьте сердце кристаллического гиганта.', 'Чтобы пробить щит Келинары, нам нужен особый мощный фокусирующий кристалл.$b$bВ глубинах шахты живет кристаллический гигант, которого дренеи зовут Ан\'дур. Гигант спал под землей много веков, но неосторожность Келинары пробудила его.$b$bСердце кристаллического гиганта – очень мощный артефакт. Срази Ан\'дура и принеси мне его сердце. После этого я смогу создать фокусирующий кристалл!', '', 'Восьмое чудо Дренора.', 'Ан\'дур Пробудившийся', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34415, 'ruRU', 'Гигант Ан\'дур', 'Добудьте сердце кристаллического гиганта.', 'Чтобы пробить щит Келинары, нам нужен особый мощный фокусирующий кристалл.$b$bВ глубинах шахты живет кристаллический гигант, которого дренеи зовут Ан\'дур. Гигант спал под землей много веков, но Келинара по неосторожности пробудила его.$b$bСердце кристаллического гиганта – очень мощный артефакт. Срази Ан\'дура и принеси мне его сердце.$b$bКогда ты вернешься, я сконструирую фокусирующий кристалл, и вместе мы остановим Келинару.', '', 'Восьмое чудо Дренора.', 'Ан\'дур Пробудившийся', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34418, 'ruRU', 'Держать строй', 'Убейте $1oa |4демона:демонов:демонов; на Пылающей передовой.', 'Аукиндон под угрозой!$B$BАукенайские воины храбры и сильны, но им не выстоять против бесчисленных орд демонов без поддержки. Мы прибыли сюда, чтобы не дать Легиону захватить Дренор... Чтобы получить шанс на победу, нам нужно действовать вместе.$B$BУничтожь побольше демонов, чтобы мы могли перегруппироваться и выдвинуться на Пылающую передовую.$B$BОстановим их здесь и сейчас!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34420, 'ruRU', 'Цена войны', 'Следуйте за верховным магом Кадгаром.', 'Эту операцию назвали самоубийством, но я не собираюсь напрасно жертвовать никем из вас.$b$bЗа мной!', '', '', '', '', '', 'Поговорите с верховным магом Кадгаром в Крови Сердца, что в Танаанских джунглях.', 25549);
INSERT INTO `quest_template_locale` VALUES (34421, 'ruRU', 'До последней капли', 'Освободите рабов из двух клеток клана Кровавой Глазницы в Крови Сердца.', '<Орк буквально выплевывает свои последние слова.>$b$bОни бросили нас в клетки. Они высасывают из нас кровь... для своих ритуалов...$b$b<Северный Волк заходится кашлем.>$b$b...осталось...$b$b...моих... собратьев...$b$b<Орк испускает дух.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34422, 'ruRU', 'Пламя славы', 'Уничтожьте 8 хижин клана Кровавой Глазницы с помощью шарика луцифрия.', 'Мы не можем здесь оставаться. Мы должны идти дальше. Но сначала нужно отвлечь внимание врага.$b$b<В ладони Кадгара появляется маленький кристалл.>$b$bВот этой штучкой можно зажечь все, что горит. Если будешь делать все достаточно аккуратно, то сможешь отвлечь внимание орков клана Кровавой Глазницы от нашего отряда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34423, 'ruRU', 'Апокалипсис у алтаря', 'Поговорите с Ариоком и помогите ему отвлечь внимание Ока Килрогга.', 'Видишь вон тот алтарь? Над ним парит магическое око, и я опасаюсь, что если оно нас заметит, нам конец.$b$bОтвлеки это око, $n. Устрой суматоху, убей пару-тройку ритуалистов, что угодно – просто отвлеки его на время, достаточное для того, чтобы наша группа незаметно прошмыгнула мимо взора ока.$b$b<Кадгар бросает взгляд назад.>$b$bПрихвати с собой здорового орка. Не Тралла, а другого.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34425, 'ruRU', 'Каргатар', 'Следуйте за Кадгаром.', 'Похоже, местные орки принадлежат к клану Изувеченной Длани. Это легко определить – просто взгляни на их руки.$b$bПойдем к остальным. Надо придумать, как отсюда выбраться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34427, 'ruRU', 'Потенциальный союзник', 'Воспользуйтесь Сосредоточением Морозной Бури возле кольца огня в Каргатаре, чтобы освободить предсказателя Дрек\'Тара.', 'К одному из пленных орков у них... особое отношение, если можно так выразиться. В то время как остальных пленников держат в кандалах и истязают, этого привязали к столбу и собираются сжечь на потеху захватчикам.$b$bВозьми этот рунный камень. Он должен погасить кольцо огня вокруг этого орка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34429, 'ruRU', 'Убей сотню', 'Переживите резню на арене Каргата.', 'У нас теперь только один путь, $n, и лежит он прямиком через арену.$b$bВозможно, для нас все скоро закончится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34431, 'ruRU', 'Мастера теней', 'Убейте Унгру, надсмотрщика Гуррана и Анкову Падшую.', 'Плохие орки меня ловили-ловили, но я сбежал. Я хорошо прячусь.$b$bВсе плохие орки – плохие, но я запомнил имена самых гадких. Вдруг кто-нибудь придет и меня спасет.$b$b<Луука делает глубокий вдох.>$b$bУнгра, Гурран и... гм... ох! Анкова.$b$bТы защитишь меня от них?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34432, 'ruRU', 'Клан Призрачной Луны', 'Убейте 10 орков из клана Призрачной Луны или волков Бездны в Темных залах.', 'Мы сдержим здесь Каргата и защитим раненых пленников. А ты, $n, ступай вперед и зачисти пещеру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34434, 'ruRU', 'Ирель', 'Проводите Ирель до безопасного места.', 'Извини, я немного взволнована: раньше мне не приходилось убивать.$b$bМеня зовут Ирель, я послушница из Карабора.$b$bГоворишь, с тобой пришла целая армия?! Воистину, сегодня Свет мне благоволит.$b$bЯ пойду с тобой. Веди, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34435, 'ruRU', 'Поиски Га\'нара', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34436, 'ruRU', 'Кели\'дан Разрушитель', 'Убейте Кели\'дана Разрушителя.', 'В живых остался только один из приближенных последователей Нер\'зула. Где-то на тропе за ним должен быть выход из пещеры.$b$bЯ вернусь и доложу Кадгару, что пещера зачищена. Встретимся, когда ты разберешься с Кели\'даном!', '', 'Помощник Нер\'зула. Верховный колдун клана Призрачной Луны.', 'Кели\'дан Разрушитель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34437, 'ruRU', 'Блудный Северный Волк', 'Встретьтесь с предсказателем Дрек\'таром в каменоломне клана Черной горы, что в Танаанских джунглях.', 'К Дрек\'Тару теперь я уж как-нибудь сам доберусь... после того, как вспорю этой лопатой брюхо паре-тройке мерзавцев из клана Черной горы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34438, 'ruRU', 'Огромные танки', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34439, 'ruRU', 'Битва за кузницу', 'Убейте 15 орков из клана Черной горы и 3 огронов-сокрушителей.', 'Наши воины получили оружие – самое время нанести удар! $b$b$n, бей быстро и точно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34440, 'ruRU', 'ФЛАГ: Кадгар выходит из портала', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34442, 'ruRU', 'Га\'нар из клана Северного Волка', 'Найдите Га\'нара.', 'Мы должны двигаться дальше, нельзя терять ни минуты!$b$bЯ чувствую, что где-то рядом должен быть Га\'нар, один из старейшин моего клана. Однако я не могу его найти.$b$bПостарайся его разыскать. Он упрямый орк, в неволе точно зачахнет.', '', '', '', '', '', 'Найдите Га\'нара в каменоломне клана Черной горы, что в Танаанских джунглях.', 25549);
INSERT INTO `quest_template_locale` VALUES (34445, 'ruRU', 'Вкус железа', 'Встаньте за боковую турель \"Разрушителя миров\" и уничтожьте 200 бойцов Железной Орды.', 'Я пока вижу два способа не дать танку пройти через портал... сломать его или воспользоваться им, чтобы взорвать этот чертов портал.$b$bЯ уверен, что смогу заставить его заработать – мне просто нужно больше времени. Вставай пока за правую переднюю турель и не подпускай их ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34446, 'ruRU', 'Финишная прямая', 'Доберитесь до доков.', 'Уж если они не разозлились до этого, то теперь мы точно довели их до белого каления. Мы и минуты не протянем на этом танке!$b$bНам нужно объединиться с оставшимися и сваливать отсюда!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34447, 'ruRU', 'Келинара Ловчая Солнца', 'Сразитесь с Келинарой Ловчей Солнца.', 'Фокусирующий кристалл готов, $n. По твоему сигналу я использую кристалл, чтобы разбить щит Келинары.$b$bОднако сражаться с ней в шахте небезопасно. Как только щит рассеется, я телепортирую нас в безопасное место у Иорунской шахты. С Келинарой будет гораздо легче справиться, когда она будет далеко от кристалла.$b$bСообщи мне, когда можно начинать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34448, 'ruRU', 'Келинара Ловчая Солнца', 'Сразитесь с Келинарой Ловчей Солнца.', 'Фокусирующий кристалл готов, $n. По твоему сигналу я использую кристалл, чтобы разбить щит Келинары.$b$bОднако сражаться с ней в шахте небезопасно. Как только щит рассеется, я телепортирую нас в безопасное место у Иорунской шахты. С Келинарой будет гораздо легче справиться, когда она будет далеко от кристалла.$b$bСообщи мне, когда можно начинать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34450, 'ruRU', 'Спасение рилаков', 'Убейте Разза Ракетобега в Гнездовье Темного Прилива.', 'Мне удалось выжать из нашего общего друга еще немного сведений.$b$bНа вершине холма находится матриарх Темного Прилива.$b$bОдин из ведущих инженеров пытается приручить ее при помощи своих изобретений. Мы должны остановить его, $n.', '', '', 'Разз Ракетобег', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34451, 'ruRU', 'Лагерь Верных Солнцу', 'Встретьтесь с леди Лиадрин в лагере Верных Солнцу в Таладоре.', 'Нам больше не обязательно работать вместе с аукенаями. Их лучшие стражники душ будут и дальше помогать нам советами, но, думаю, действовать теперь лучше нам одним.$B$BВстретимся в лагере Верных Солнцу к юго-востоку отсюда. Я чувствую в этой области демоническую порчу – может, найдя ее источник, мы сумеем обнаружить оставшиеся осколки кристалла силы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34452, 'ruRU', 'Покой Света', 'Встретьтесь с экзархом Маладааром в Покое Света в Таладоре.', 'Теперь, когда мы справились с основными силами врага, пора подумать о последствиях и подготовиться к будущим нападениям. Нам все еще нужно укрепить защиту Аукиндона.$B$BЯ буду ждать тебя в Покое Света, это к югу отсюда. Я чувствую в этой области демоническую порчу – может, найдя ее источник, мы сумеем обнаружить оставшиеся осколки кристалла силы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34453, 'ruRU', 'Преследование: прибытие Газлоу', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34455, 'ruRU', 'Свободу узникам разума', 'Используйте устройство для управления разумом рилака на контролируемых рилаках.', 'Этот прибор гоблины используют для того, чтобы управлять рилаками.$b$bТам есть кнопка, на которой написано \"Не трогать\".$b$bПодберитесь к контролируемому рилаку и нажмите кнопку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34456, 'ruRU', 'Дух Волка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34458, 'ruRU', 'Усиление защиты', 'Найдите стражницу душ Туулани в Гробнице Света.', 'Большинство наших стражников душ на передовой, остальные поддерживают защиту Аукиндона. Без помощи долго им не продержаться.$B$BСтражница душ Туулани отправилась в ближайшую Гробницу Света, чтобы добыть запасной пилон силы, но до сих пор не вернулась. Пожалуйста, найди ее и доставь сюда вместе с пилоном.', '', '', '', '', '', 'Найдите стражницу душ Туулани в Гробнице Света.', 25549);
INSERT INTO `quest_template_locale` VALUES (34461, 'ruRU', 'Постройка казарм', 'Найдите и изучите чертеж гарнизона для постройки казарм, затем воспользуйтесь столом архитектора, чтобы построить казармы.', 'Тебе точно понадобятся казармы, если ты хочешь воевать как следует.\n\nПервым делом следует найти чертежи и разобраться с ними. Кажется, тут есть парочка поблизости.\n\nЗатем понадобится выбрать место для постройки. Отметь место строительства на моем столе архитектора, и мы сразу же примемся за дело.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34462, 'ruRU', 'Ветер перемен', 'Спасите Оулина Бурошкура.', 'У меня плохие новости, командир. Оулин Бурошкур, таурен, сбежавший с тобой из Танаана, попал в засаду у восточного оборонительного рубежа гарнизона.$b$bЕго куда-то уволокли бледнокожие. Это опасные, гнусные твари. Говорят, когда-то они были орками, но теперь от них остались лишь оболочки, наполненные темной магией.$b$bОулин находчив, но в одиночку ему с ними не управиться. Будет своевременно прямо сейчас отправиться на восток и спасти его, пока бедолагу не сожрали живьем... медленно и мучительно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34463, 'ruRU', 'Таинственное кольцо', 'Отнесите таинственное кольцо Зути Шипяточку в Башню Кадгара в Таладоре.', 'Это элегантное кольцо расписано различными узорами и символами, из которых наиболее крупным является светящаяся руна в форме буквы \"В\". Кольцо то исчезает из виду, то появляется снова; такое ощущение, что оно постоянно путешествует между прошлым и будущим.$b$bВозможно, кто-нибудь в Башне Кадгара заинтересуется этим артефактом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34464, 'ruRU', 'Таинственные сапоги', 'Отнесите таинственные сапоги Зути Шипяточку в Башню Кадгара в Таладоре.', 'На этих мерцающих сапогах, постоянно перемещающихся вперед и назад во времени, вышита буква \"В\".$b$bВозможно, кто-нибудь в Башне Кадгара сможет разобраться в их происхождении.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34465, 'ruRU', 'Таинственная шляпа', 'Отнесите таинственную шляпу Зути Шипяточку в Башню Кадгара в Таладоре.', 'Эта таинственная шляпа излучает очень мощные энергетические потоки. Она постоянно перемещается вперед и назад во времени, причем этот процесс сопровождается характерным гудением.$b$bОпределенно, кто-то в Башне Кадгара должен заинтересоваться таким предметом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34466, 'ruRU', 'Таинственный посох', 'Отнесите таинственный посох Зути Шипяточку в Башню Кадгара в Таладоре.', 'Завихрения реальности вокруг этого посоха столь сильны, что вы не можете разобрать никаких символов на его поверхности, кроме большой буквы \"В\" на набалдашнике.$b$bОпределенно, здесь потребуется помощь кого-то из обитателей Башни Кадгара.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34469, 'ruRU', 'Очищение душ', 'Очистите $1oa |4обезумевшую душу:обезумевшие души:обезумевших душ;.', 'Разрушитель Душ уничтожает не все души. Некоторые умудряются сопротивляться его влиянию – как я. Большинству повезло меньше – из-за невыносимых страданий их охватило безумие.$B$BПоложи конец их мучениям. Возьми мой осколок души и с его помощью очисти несчастных. Пока они охвачены яростью, осколок души не возымеет действия, поэтому сначала тебе нужно будет победить их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34470, 'ruRU', 'Событие: бледный орк на рыбалке', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34471, 'ruRU', 'Сокровище: блестящая монетка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34472, 'ruRU', 'Наслоение временных потоков', 'Ждите завершения ритуала Зути Шипяточка.', 'Кажется, я разобрался, для чего были нужны эти загадочные артефакты, которые ты $gпринес:принесла;.$b$bПохоже, кто-то хотел изменить определенные события, отправляя предметы из твоей временной реальности в эту.$b$bПо идее, это невозможно. Но, похоже, нашему таинственному путешественнику во времени это каким-то образом удалось.$b$bДумаю, я могу провести ритуал, чтобы вызвать его в нашу реальность.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34473, 'ruRU', 'Записи эмиссара', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34476, 'ruRU', 'Событие/сокровище: замерзшее сокровище', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34477, 'ruRU', 'Событие: ярость Циклона', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34478, 'ruRU', 'Потенциальный союзник', 'Воспользуйтесь Сосредоточением Морозной Бури возле кольца огня в Каргатаре, чтобы освободить экзарха Маладаара.', 'К одному из пленных дренеев у них... особое отношение, если можно так выразиться. В то время как остальных пленников держат в кандалах и истязают, этого привязали к столбу и собираются сжечь на потеху оркам.$b$bВозьми этот рунный камень. Он сумеет погасить кольцо огня вокруг этого дренея.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34483, 'ruRU', 'Событие: Гальзомар', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34496, 'ruRU', 'Валуунские холмы', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34497, 'ruRU', 'Vignette: Breathless', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34498, 'ruRU', 'Vignette: Klikixx', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34501, 'ruRU', 'Пещера Леденящего Ветра', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34503, 'ruRU', 'Кричащий житель Телмора', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34504, 'ruRU', 'Пещера Кровавых Шипов', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34505, 'ruRU', 'Запретный ледник', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34506, 'ruRU', 'Дополнительная задача: убейте огров из клана Жестокого Холода', '', 'Освободите орков из клана Северного Волка, которых удерживают в плену огры племени Жестокого Холода.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34507, 'ruRU', 'Сокровище: замерзший топор Северного Волка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34508, 'ruRU', 'Ресталаан, капитан стражи', 'Найдите Ресталаана в Телморе.', 'Они убили Аэдраа и отняли у нее кристалл! Капитан стражи Ресталаан попытался помешать им, и они забрали его в храм!$B$BТолько бы вернуть кристалл – с ним мы сумеем восстановить Сердце Аукиндона, чтобы защита заработала в полную силу! У нас больше нет права на ошибку.$B$BТеперь только ты, $n, сможешь помочь. Найди Ресталаана! Он расскажет, куда они забрали кристалл.', '', '', '', '', '', 'Найдите Ресталаана в Телморе.', 25549);
INSERT INTO `quest_template_locale` VALUES (34510, 'ruRU', 'Отслеживание задания: Катапульты и копытни', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34511, 'ruRU', 'Отслеживание задания: Обуза огра', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34512, 'ruRU', 'Вырвать когти конкурентам', 'Добудьте $oa |4коготь:когтя:когтей; саблеронов.', 'Из-за этих проклятых саблеронов я потеряла целую кучу звонких, |3-6($c).$b$bЯ не из тех, кто прощает долги, так что пора этим гадам заплатить по счетам!$b$bБольше всего неприятностей нам причинили те, что живут в Землях саблеронов. Они постоянно нападают на наши торговые караваны из засад на дорогах.$b$b<Динки усмехается.>$b$bПора вырвать им когти – в прямом смысле слова. Принеси мне их. Из лучших сделаем талисманы удачи для бойцов на арене и продадим.$b$bА если когти не покроют моих убытков, тогда им придется расплачиваться еще руками и ногами!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34513, 'ruRU', 'РАЗЫСКИВАЕТСЯ: Когтистый Ужас!', 'Победите Когтистый Ужас.', 'Разыскивается за преступления против невинных в Круге Испытаний!$b$bКогтистый Ужас организовал несколько рейдов и засад на путешественников в районе Земель саблеронов.$b$bВ последний раз был замечен в непосредственной близости от Земель саблеронов.$b$bТребуется исключительная осторожность!$b$bНаграду за голову можно будет получить у Динки Деньжатникс из картеля Хитрой Шестеренки.', '', 'Разыскивается за преступления против мирных жителей!', 'Когтистый Ужас', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34514, 'ruRU', 'Они украли наши товары!', 'Верните $oa |4мешок:мешка:мешков; украденных товаров.', 'Саблероны... им были нужны не только пленники...$b$b<Кашляет.>...они еще и все товары забрали.$b$bПохищение пленников – одно дело, но красть у гоблинов их товар? Это уже повод для вендетты!$b$b<Кашляет>...Динки будет очень недовольна, если ты не вернешь все пропавшие товары. Отправляйся в Земли саблеронов и укради их назад.$b$bКогда все сделаешь, возвращайся к Динки Деньжатникс в Круг Испытаний.$b$bОна уж в долгу не останется...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34515, 'ruRU', 'Гоб-стоп', 'Спасите $oa |4гоблина-торговца:гоблинов-торговцев:гоблинов-торговцев;.', 'Мы даже и не подозревали, что нарвемся на засаду...$b$bСаблероны атаковали так внезапно, что мы даже не успели собраться с мыслями.$b$bЭти твари утащили остальных в свое логово, а меня бросили здесь... наверное, решили, что я все равно скоро умру от ран.$b$bЯ слышал, они любят свежее мясо – падаль им ни к чему...$b<кашляет>...но я помирать пока не собираюсь!$b$bНе беспокойся за меня...<кашляет>...Я бывал в переделках и похуже! А тебе нужно отправиться в Земли саблеронов и вызволить из плена остальных торговцев.$b$bНаверное, их всех уже пересажали в клетки...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34516, 'ruRU', 'Моя прелесть!', 'Отыщите украденное сокровище Базвикса.', 'Ты просто $gобязан:обязана; мне помочь!$b$bЯ спрятался в торговой повозке, когда мы попали в засаду неподалеку отсюда. Саблероны меня не заметили, но... но...$b$bОНИ ПОХИТИЛИ САМОЕ ЦЕННОЕ, ЧТО У МЕНЯ БЫЛО!$b$bТы $gдолжен:должна; помочь мне вернуть мое сокровище! Я видел, как они потащили его в Земли саблеронов вон на тот огромный холм!$b$bМало ли что они с ним сделают – от этих тварей всего можно ждать!$b$bПожалуйста! Ведь я еще ребенок! Ты же ведь мне поможешь, правда?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34517, 'ruRU', 'Событие: огромный ледоклюв', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34518, 'ruRU', 'Награндский кораль', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34519, 'ruRU', 'Событие: Бротокул', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34520, 'ruRU', 'Сокровище: горящая жемчужина', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34521, 'ruRU', 'Сокровище: светящийся обсидиановый осколок', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34522, 'ruRU', 'Событие: Уг\'лок Ледяной', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34523, 'ruRU', 'Чернокнижник, говорящий с Гул\'даном', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34557, 'ruRU', 'Отслеживание задания: Карта сокровищ', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34558, 'ruRU', 'По вашей команде', 'Выберите, какое здание нужно построить.', 'Хорошо, что ты здесь!$B$BСтроительство форта Ринн почти завершено. Остался лишь один свободный участок.$B$BБарос дал нам чертежи двух зданий, которые могут здесь поместиться: артиллерийской башни и волшебного святилища.$B$BТебе решать, что строить, командир. Планы на твоем чертежном столе, изучи их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34559, 'ruRU', 'Событие: Йага Изрубцованная', 'Уничтожьте $1oa |4кладку:кладки:кладок; яиц горенов, $2oa |4железоеда:железоедов:железоедов; Ледяной Кузни и праматерь Риг\'ак.', 'Горены опасны для нас – их много, а наш шаман слеп и обессилен.$b$bКонечно, век этих чудовищ короток, но они очень быстро размножаются и растут.$b$BЧтобы справиться с горенами, нам нужно найти их матку, убить ее и уничтожить яйца. Так мы сможем на какое-то время обезопасить себя. Осмотри норы у врат Кузни, а я сделаю так, чтобы горены не напали на след Дрек\'тара.', '', '', '', '', '', 'Вернитесь к Дреке, к Вратам Кузни, что на Хребте Ледяного Огня.', 19865);
INSERT INTO `quest_template_locale` VALUES (34560, 'ruRU', 'Оружейная', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34561, 'ruRU', 'Башня магов', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34562, 'ruRU', 'Активация защиты Терон\'крова', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34563, 'ruRU', 'Сложности с пленником', 'Поговорите с ученицей Миаллой у форта Ринн в Таладоре.', 'Мы построили артиллерийскую башню – теперь нам нужен опытный кузнец, который будет там работать.$b$bДо меня дошли слухи, что Аред, один из лучших кузнецов Шаттрата, успел бежать до падения города. Сейчас он должен быть где-то у северной стены среди прочих беженцев.$b$bПопробуй уговорить его работать на нас.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34564, 'ruRU', 'Пункт назначения: неизвестно', 'Уничтожьте Темнорода в руинах Ксандроса.', 'Терон\'кров и Гул\'дан как раз уходили через портал... а я... Я знаю, что не смогу их одолеть.$B$BПостараюсь держать портал открытым как можно дольше. Но нанести последний удар придется тебе, $n.$B$BНаша судьба – в твоих руках.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34565, 'ruRU', 'Раздор в Таладоре', '', 'Командир, у нас небольшая проблема.$b$bМы нашли в Таладоре место для аванпоста, послали туда отряд, чтоб начать строительство, но они рассорились: не могут решить, что именно строить. Если быстро все не уладить, это спутает наши планы.$b$bНужно слетать на грифоне в Таладор и поговорить со Штейгером Эксосом, пока дело дошло до драки.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34566, 'ruRU', 'По вашей команде', 'Осмотрите чертежный стол и выберите, какую из построек следует возвести на аванпосте.', 'Командир, аванпост почти достроен.$b$bГазлоу дал нам чертежи двух разных зданий для последнего свободного участка – оружейной и волшебного святилища.$b$bЛюбое из них обеспечит нас огневой мощью, которая поможет остановить Железную Орду.$B$BПланы на твоем чертежном столе. Решать тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34567, 'ruRU', 'Башня магов', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34568, 'ruRU', 'Оружейная', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34569, 'ruRU', 'Сложности с пленником', 'Заручитесь поддержкой Моркета Воющего Меча.', 'Арсенал построен, теперь нам нужен умелый кузнец.$b$bНедавно мы захватили в плен дезертира из Железной Орды, и он уверяет, что был одним из лучших кузнецов клана Черной горы.$b$bНельзя верить пленникам на слово, но меня поразило качество оружия, которое было у него с собой.$b$bКомандир, нужно проверить, так ли он хорош, как утверждает.', '', '', '', '', '', 'Поговорите с Моркетом Воющим Мечом в Гордости Вол\'джина в Таладоре.', 25549);
INSERT INTO `quest_template_locale` VALUES (34570, 'ruRU', 'REUSE', 'Slay Hurkan Skullsplinter in the Seat of Depravity.', 'Терон\'кров и его хозяин Гул\'дан были здесь! Они сбежали через демонические врата, что находятся позади меня! Мне не удалось их прикончить.$B$BДумаю, я смогу ненадолго открыть портал, чтобы у тебя была возможность пройти. Мы не знаем, куда он ведет, но боюсь, что в Аукиндон!$B$BВрагов нужно остановить раз и навсегда!', '', '', '', '', '', 'Speak to Exarch Maladaar in the Seat of Depravity.', 19865);
INSERT INTO `quest_template_locale` VALUES (34571, 'ruRU', 'За йовитовой рудой', 'Добудьте 12 кусков йовитовой руды в шахте Кууро.', 'Мы с Аредом пришли сюда, чтобы запастись металлом для его проектов, а один из лучших видов металла выплавляется из йовитовой руды, которую добывают в шахте Кууро. Чтоб обеспечить артиллерийскую башню снаряжением, мне понадобится этот металл.$b$bК несчастью, там с недавних пор полно горенов, так что тебе придется проложить дорогу к руде силой – пока они ее всю не сожрали.$b$bНо, думаю, для тебя это будет не сложно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34572, 'ruRU', 'Уничтожение огров', 'Убейте $1oa |4огра:огров:огров; в Бастионе Мар\'гока.', 'С появлением огров-магов клан Верховного Молота усилил патрули и стал действовать агрессивнее.$b$bУничтожив достаточно огров, мы значительно затормозим продвижение клана Верховного Молота по Награнду.$b$bКогда разберешься с магами, поговори с моей сестрой Мираной, она скажет, что делать дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34573, 'ruRU', 'Добыча иридия', 'Соберите $1oa |4порцию:порции:порций; иридиевой пыли с иридиевых жеод в шахте Кууро.', 'Аред всегда учил меня, что самое главное в нашем ремесле – чистота металла. Если металл недостаточно чист, под напряжением он просто треснет – и какой от такого изделия толк?$b$bЧтобы наладить работу артиллерийской башни, нужно добиться высочайшей чистоты металла, с которым предстоит работать, и для этого понадобится сильный реагент.$b$bПыль, образующаяся при дроблении иридиевых жеод, как раз подойдет для моих целей – но сперва нужно найти эти жеоды. Обычно они встречаются под землей, так что загляни для начала в шахту Кууро, что неподалеку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34574, 'ruRU', 'Разрушитель Душ', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34575, 'ruRU', 'Шаг третий: пророк!', 'Поговорите с пророком Веленом у потерпевшего крушение корабля Железной Орды в Долине Призрачной Луны.', 'Вы прибыли в Долину Призрачной Луны. Пришло время поговорить с пророком.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34576, 'ruRU', 'Возвращение иридия', 'Соберите $1oa |4порцию:порции:порций; иридиевой пыли с иридиевых жеод в шахте Кууро.', 'Мои товары были самыми лучшими, а теперь Железная Орда делает копии из дрянного металла и раздает их всем.$b$bЯ покажу им, что может сделать настоящий кузнец в твоей оружейной, но сначала нужно добиться высочайшей чистоты металла, с которым предстоит работать, и мне понадобится сильный реагент.$b$bПыль, образующаяся при дроблении иридиевых жеод, как раз подойдет для моих целей – но сперва нужно найти эти жеоды. Обычно они встречаются под землей, так что загляни для начала в шахту Кууро, что неподалеку отсюда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34577, 'ruRU', 'Нехватка йовита', 'Добудьте 12 кусков йовитовой руды в шахте Кууро.', 'Для создания лучшего снаряжения требуются лучшие материалы, а один из лучших видов металла выплавляется из йовитовой руды, которую добывают в шахте Кууро. Чтоб обеспечить арсенал, мне понадобится этот металл.$b$bК несчастью, там с недавних пор полно горенов, так что тебе придется проложить дорогу к руде силой – пока они ее всю не сожрали.$b$bНо, думаю, для тебя это будет не сложно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34578, 'ruRU', 'К Гордунни', 'Отправляйтесь к крепости Гордал и встретьтесь там с Миаллой.', 'Сейчас у нас пока достаточно йовита, но в шахте его мало, и наших запасов для снабжения артиллерийской башни хватит ненадолго. К югу отсюда есть гора с отличными йовитовыми жилами, но на ней поселились огры!$b$bНа вершине обосновался клан Гордунни, и они начали продавать йовит Железной Орде.$b$bНам надо отправиться туда и забрать ценные минералы себе.$b$bЯ упакую припасы и встречу тебя на юге, рядом с их крепостью.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34579, 'ruRU', 'Пожиратели газа', 'Извлеките $1oa |4образец:образца:образцов; кишечного газа горенов из тел роняющих кристаллы светоглотов и прожорливых светоглотов в шахте Кууро.', 'Командир!$b$bЧтобы изготовить снаряжение высшего качества, нужны не только лучшие материалы, но и высокие технологии.$b$bЗа много лет мне удалось разработать способ значительно усилить прочность металла, но для него нужен экзотический ресурс – а именно кишечный газ горенов!$b$bКак раз недавно они наводнили шахту Кууро, она находится совсем недалеко отсюда. Ты не $gмог:могла; бы набрать образцов для снабжения оружейной? Просто убей несколько горенов и как следует потыкай в их трупы извлекателем газа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34580, 'ruRU', 'Draenor Flowerpicker', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34581, 'ruRU', 'Draenor Flowerpicker Note Found', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34582, 'ruRU', 'Закрепление на Дреноре', 'Следуйте за пророком Веленом.', 'Значит, это ты $gпривел:привела; моих детей домой? Железная Орда становится все сильнее с каждым днем.$b$bЯ предвижу великую битву, но мои видения затуманены. На ткани времени будто образовались складки.$b$bНо одно я могу сказать наверняка: ты сыграешь в грядущих событиях важную роль.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34583, 'ruRU', 'За Альянс!', 'Поставьте знамя Альянса.', '$n, без тебя мы бы не выжили в Танаане. Многие дренеи и другие воины Альянса у тебя в большом долгу.$B$BПеред тем как мы отправились к Темному порталу, Король Ринн лично попросил поставить тебя во главе наших операций на Дреноре. После того как я увидел тебя в бою, я с ним согласен.$B$BЗдесь будет стоять твой гарнизон. Установи знамя, командир, и мы сразу же начнем строительство.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34584, 'ruRU', 'На поиски древесины', 'Отметьте $1oa |4дерево:дерева:деревьев;.', 'Некоторые деревья здесь не очень высокие, рабочие Шелли легко их повалят.$b$bВсю тяжелую работу оставим им, но дело пойдет куда быстрее, если ты сразу отметишь деревья для валки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34585, 'ruRU', 'Камнехруст', 'Убейте Камнехруста.', 'До меня дошли слухи о том, что в лесу поселился великан.$b$bНесколько караборских миротворцев обнаружили пещеру, где находится его логово. Честно говоря, я сомневаюсь, что наши бойцы захотят связываться с этим чудовищем.$b$bМожет быть, этим займешься ты? Наверняка миротворцы будут очень благодарны нам за помощь.', '', '', 'Камнехруст', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34586, 'ruRU', 'Создание гарнизона', 'Постройте гарнизон.', 'Удивительно, как быстро вам удалось собрать этот отряд, командир.$b$bПо-моему, нам пора возводить стены и устанавливать четкие границы базы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34587, 'ruRU', 'Постройка казарм', 'Найдите и изучите чертежи, после чего воспользуйтесь столом архитектора, чтобы построить казармы.', 'Дела в гарнизоне идут очень даже неплохо, командир.$b$bУ нас достаточно стройматериалов, и я могу уже сейчас приступить к возведению казарм.$b$bХмм... вот только куда делись мои чертежи?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34592, 'ruRU', 'Малые гронны, большие проблемы', 'Убейте $1oa |4малого гронна:малых гроннов:малых гроннов; Ледяного Огня.', 'Строить крепость, когда вокруг шныряют толпы малых гроннов – задача не из легких.\n\nНе уверен, что кроме тебя здесь кто-то сможет разделаться с этими тварями. Поэтому, видимо, придется заняться этим именно тебе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34593, 'ruRU', 'Приказы огров о наступлении', 'Достаньте приказы Крулгорошу и Тулгорку в Бастионе Мар\'гока.', 'Моя сестра Мирана отправилась на разведку на верхние скалы, пока я осматривала местность внизу. Похоже, там всем заправляют два огра-мага.$b$bУ них должны быть какие-то свитки или приказы... думаю, эти документы весьма помогли бы нам понять, что тут происходит.$b$bСобери эти сведения и встреться с моей сестрой на длинной лестнице, что ведет наверх.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34596, 'ruRU', 'Исследование Реглакка', 'Остановите великого магистра Реглакка.', 'Эти огры владеют древними артефактами титанов – с их помощью они наделяют силой небольшую группу своих собратьев, известных как разрушители. Магистр Реглакк изучает способы повышения эффективности этого жуткого процесса.$B$BНужно положить конец всем ритуалам, которые он проводит на вершине утеса.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34597, 'ruRU', 'Бумажная работа', 'Уничтожьте $1oa |4ящик:ящика:ящиков; с исследованиями огров в Бастионе Мар\'гока.', 'Коробка набита текстами и рисунками, которые очень напоминают исследования по нейтрализации магии.$b$bПожалуй, стоит сорвать эту работу, уничтожив все записи подобного рода.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34598, 'ruRU', 'Пропавший караван', 'Найдите пропавший груз.', 'У меня возникла одна проблема, но, как мне кажется, |3-6($r) вроде тебя отлично с ней справится!$b$bВчера мы должны были получить груз товаров, но он словно сквозь землю провалился. Мои припасы уже подходят к концу, и мне срочно нужно выяснить, что случилось с тем грузом!$b$bМогу предположить, что к его пропаже причастны саблероны. С тех пор как мы сюда прибыли, эти твари уже успели доставить нам целую кучу неприятностей!$b$bПоищи повозку на дороге в районе Земель саблеронов. И поторопись! Время – деньги!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34599, 'ruRU', 'Tracking Quest: Saw Yrel Leave Twilight Glade', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34600, 'ruRU', 'Tracking Quest: Saw Vorka, Rangari Leave', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34609, 'ruRU', 'Создание чернил', 'Соберите $1oa |4пульсирующий гнойник:пульсирующих гнойника:пульсирующих гнойников; со спороскатов и грибных великанов в Зангарре.', 'В твоей башне необходимо создать искусственный нексус.$B$BЯ знаю, где достать компоненты, которые нам нужны, но это место хорошо охраняется. Необходимо как следует продумать операцию, чтобы не допустить ошибок.$B$BУ меня есть план. Нам потребуется свиток массовой телепортации.$B$BОбитающие внизу грибные великаны и споровики сплошь покрыты гнойниками, наполненными маслянистой субстанцией. Она как раз сгодится для изготовления чернил, которые понадобятся при начертании свитка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34612, 'ruRU', 'Создание свитка', 'Сдерите $1oa |4кусок:куска:кусков; коры с дремлющих древней в Зангарре.', 'Чтобы начертать свиток, понадобится чародейский пергамент.$B$BТайная магия нексуса заморозила древние создания, и часть этой энергии должна была сохраниться в их коре.$B$BЕсли мы достанем немного коры древних, которых еще не успели уничтожить грибные создания, я изготовлю из нее пергамент.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34616, 'ruRU', 'Прожорливые вороны', 'Убейте $1oa |4ворона:воронов:воронов; Зашедшей Луны.', '$gВидел:Видела;? Над деревьями только что пролетел огромный ворон.$b$bЯ туда ни за что не пойду. Более того, мои воины тоже не готовы сражаться с таким врагом.$b$bКомандир, может, ты $gсам:сама; с ним разберешься?$b$bИз кожи и перьев таких воронов получатся отличные накидки. Мы могли бы убить двух птиц одним камнем... или, точнее, пять птиц несколькими... $b$b<Барос путается в собственных мыслях и чешет в затылке.>$b$bНу, ты меня понимаешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34619, 'ruRU', 'Пойманная искра', 'Соберите $1oa |4волшебное завихрение:волшебных завихрения:волшебных завихрений; в Зангарре.', 'Чтобы завершить работу над свитком, нам понадобится магическая энергия. Она послужит связующей субстанцией.$B$BУ меня есть артефакт, с помощью которого мы сможем захватить энергетические завихрения в кальдере, так что не будем терять времени.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34622, 'ruRU', 'Tracking Quest: Saw Ner\'zhul Leave', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34624, 'ruRU', 'Пожиратели газа', 'Извлеките $1oa |4образец:образца:образцов; кишечного газа горенов из тел роняющих кристаллы светоглотов и прожорливых светоглотов в шахте Кууро.', 'Чтобы воплотить планы моего наставника и пополнить запасы артиллерийской башни, нам понадобится один экзотический ресурс – кишечный газ горенов.$b$bКак раз недавно они наводнили шахту Кууро, она находится совсем недалеко отсюда. Ты не $gмог:могла; бы принести несколько образцов? Этот газ очень концентрированный, так что пары образцов будет достаточно. Просто убей одного горена и как следует обработай его труп извлекателем газа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34631, 'ruRU', 'Встреча с верховным магом', 'Поговорите с верховным магом Кадгаром в Таладоре.', 'Рад сообщить, что строительство волшебного святилища уже закончено, командир!$B$BМы все сделали в соответствии с проектом, но... тут внизу Барос приписал: \"Не забыть подключить святилище к сети силовых линий!\"$B$BКомандир, я всего лишь бригадир, а не маг. Я... Я понятия не имею, как это делается.$B$BУ гор на востоке, недалеко отсюда, я видел верховного мага Кадгара и еще нескольких мудрецов из Кирин-Тора. Может, нам стоит попросить у них совета?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34632, 'ruRU', 'Встреча с верховным магом', 'Поговорите с верховным магом Кадгаром в Таладоре.', 'Волшебное святилище уже начало свою работу, командир!$B$BМы все сделали в соответствии с проектом, но... тут внизу Газлоу приписал: \"Не забыть подключить святилище к сети силовых линий!\"$B$BЯ... Э-э... Я понятия не имею, как это делается.$B$BПрости, командир, но магия – это совсем не мое. Тут поблизости оказался верховный маг Кадгар и еще несколько мудрецов из Кирин-Тора. Это к востоку отсюда, у подножия гор.$B$BМожет, попросить у них помощи?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34634, 'ruRU', 'Создание чернил', 'Соберите $1oa |4пульсирующий гнойник:пульсирующих гнойника:пульсирующих гнойников; со спороскатов и грибных великанов в Зангарре.', 'Нам нужно найти способ создать в твоей башне искусственный нексус.$B$BЯ знаю, где достать то, что нам нужно, но это место хорошо охраняется. Просто ломиться через парадную дверь – не вариант.$B$BНо у меня есть план – свиток массовой телепортации.$B$BОбитающие внизу грибные великаны и споровики сплошь покрыты гнойниками, наполненными маслянистой субстанцией. Если собрать достаточно этого масла, я смогу изготовить чернила, которые сгодятся для начертания свитка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34635, 'ruRU', 'Создание свитка', 'Сдерите $1oa |4кусок:куска:кусков; коры с дремлющих древней в Зангарре.', 'Чтобы мой план сработал, понадобится чародейский пергамент.$B$BТайная магия нексуса заморозила спящих защитников, и часть этой энергии должна была сохраниться в их коре. $B$BЕсли мы достанем немного коры древних, которых еще не успели уничтожить грибные создания, я изготовлю из нее пергамент.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34636, 'ruRU', 'Пойманная искра', 'Соберите $1oa |4волшебное завихрение:волшебных завихрения:волшебных завихрений; в Зангарре.', 'Для завершения работы над свитком понадобится тайная энергия. Энергетическая искра, если быть совсем точным.$B$BУ меня есть приспособление, с помощью которого можно собрать энергию со дна котловины, так что пора засучить рукава. Думаю, вдвоем мы с тобой легко справимся с существами, напитанными этой энергией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34639, 'ruRU', 'Опустошение Арууны', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34641, 'ruRU', 'Vignette/Treasure: Waterlogged Journal', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34642, 'ruRU', 'Vignette/Treasure: Lucky Coin', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34645, 'ruRU', 'Vignette: Warmaster Blugthol', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34646, 'ruRU', 'Киана Тень Луны', 'Поговорите с Кианой Тенью Луны.', 'Для победы в этой войне недостаточно рядовых солдат. Понадобятся закаленные воины.$b$bКиана Тень Луны великолепно показала себя в Танаане и на причале Вечерней Зари.$b$bМожет быть, ты предложишь ей сыграть еще более значительную роль в войне с Железной Ордой?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34647, 'ruRU', 'Vignette/Treasure: Snow-Covered Strongbox', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34648, 'ruRU', 'Vignette/Treasure: Gnawed Bone', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34649, 'ruRU', 'Vignette/Treasure: Smoldering True Iron Deposit', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34651, 'ruRU', 'Tracking Flag: Dagg Found at Grom\'gar', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34652, 'ruRU', 'Vignette/Treasure: Savage Clam', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34653, 'ruRU', 'Исход араккоа', 'Поговорите с Азиком на Пиках Арака.', 'Тебе уже доводилось сталкиваться с араккоа, командир? Это гордые летающие люди-птицы. Они очень ревниво относятся к вторжению на свою территорию.$b$bКстати, у некоторых атрофированы крылья – видимо, болезнь какая. Такие, похоже, в обществе араккоа – изгои. Они кочуют с места на место, разбивают лагеря в заброшенных руинах, торгуют редкими товарами у дорог.$B$BСудя по всему, причиной их исхода с родных мест стала Железная Орда.$B$BНужно установить контакт с этими изгнанниками – они могут рассказать много интересного.', '', '', '', '', '', 'Поговорите с Азиком на Пиках Арака.', 25549);
INSERT INTO `quest_template_locale` VALUES (34654, 'ruRU', 'Tracking Flag: Dagg Found at Daggermaw Ravine', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34655, 'ruRU', 'Тени Скеттиса', 'Скажите пароль Решаду в Скеттисе.', 'Толпы моих сородичей бегут из родных краев. Я продаю вещицы, которые могут облегчить им путешествие.$B$BНо тебя, похоже, они не интересуют... Нет, тебе нужны ответы.$B$BСкеттис находится чуть дальше. Когда-то это был великий город. Терокк построил его, чтобы приютить отверженных. А теперь это просто развалины и трущобы.$B$BТам живет один старый сказочник – хранитель свитков по имени Решад. Найди его и скажи ему так: \"Тени сгущаются\". Тогда он поймет, что ты – друг.$B$BА теперь ступай. Ты отпугиваешь клиентов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34656, 'ruRU', 'Спрятано на виду', 'Найдите потертые крылатые клинки и старую маску.', '<Решад начинает распихивать свитки по карманам.>$B$BЯ думал, у меня будет больше времени на подготовку! В Скеттисе спрятаны реликвии огромной мощи – мне легче умереть, чем бросить их здесь.$B$BПервая реликвия – это пара клинков в руках статуи у главных ворот, через которые ты $gдолжен был:должна была; пройти по дороге сюда. $B$BВторая реликвия – это белая маска на лице статуи в восточной части руин.$B$BПринеси эти вещи мне, и я открою тебе их тайны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34657, 'ruRU', 'Приверженцы богини солнца', 'Убейте $1oa |4приверженца-острокрыла:приверженцев-острокрылов:приверженцев-острокрылов;.', 'Араккоа Небесного Пути подчиняются Приверженцам Рухмар и презирают тех из нас, кого коснулось проклятие Сете. Теперь же Приверженцы решили, что во имя богини солнца нас необходимо истребить.$B$BВскоре они обратят свой взор к землям за пределами Арака.$B$BБрось вызов их воинам. Выиграй время, чтобы мне удалось уйти, а потом помоги мне остановить их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34658, 'ruRU', 'Приказы сверху', 'Силой заберите воззвание приверженцев у солнечного ведуна Ратикса.', 'Приверженцы Рухмар – главные представители власти на шпилях. Их влияние неоспоримо. Их решения воспринимаются как воля самой Рухмар.$B$BВне всякого сомнения, их приказы должны быть у глашатая, возглавляющего атаку, и, скорее всего, это просто список имен и мест, которые вскоре попадут под их удар.$B$BУчитывая обстановку, ценность этих приказов для нас трудно преувеличить. Достань этот документ и разберись с глашатаем!', '', '', 'Солнечный ведун Ратикс', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34659, 'ruRU', 'Ведьма', 'Скажите фразу-пароль Орнекке в Вороньем Крюке.', 'Помнишь, с какими словами ты $gобратился:обратилась; ко мне?$B$B\"Тени сгущаются. Когда ворон проглотит солнце\".$B$BЭто не просто красивая метафора – это руководство к действию. Сторонники старых обычаев собираются с силами, и мой долг – присоединиться к ним. Думаю, твоя помощь нам тоже понадобится.$B$BИди по этой дороге до Вороньего Крюка. У ручья ты увидишь хижину, в которой живет древняя старуха. Поприветствуй ее, произнеся заветные слова, и она укажет тебе путь.$B$BМеня ты не увидишь, но я буду рядом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34660, 'ruRU', 'Падение Зоркры', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34662, 'ruRU', 'Круг Испытаний: Молотобой', 'Победите Молотобоя в Круге Испытаний.', 'Значит, ты хочешь сражаться в Круге Испытаний? Ну все, пиши завещание!$b$bВ первом же бою тебе придется сойтись с огромным и злобным огром по имени Молотобой. Но это еще не все. Вместе с ним тебе придется одолеть еще и его закованного в броню кабана – Молотобой никогда не выходит на ринг без него!$b$bНадеюсь, ты $gуспел:успела; привести в порядок все свои дела – последнего гладиатора, сражавшегося с Молотобоем, отправили домой в мешке...$b$bНо я в тебя верю! Давай дуй на арену и поговори с моим помощником Газрагом, когда будешь $gготов:готова; к бою!', '', 'В первом поединке ты сразишься с Молотобоем!', 'Молотобой', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34663, 'ruRU', 'Круг Испытаний: Вспарывающая Плоть', 'Победите Вспарывающую Плоть в Круге Испытаний.', 'Молотобой повержен, но это еще не все – тебе предстоит очередная битва!$b$bКлан Верховного Молота относится к гладиаторским боям очень серьезно, для сражений в Круге Испытаний они выбирают самых могучих и свирепых существ!$b$bВ этот раз тебе будет противостоять грозный ворон, имя которого говорит само за себя – Вспарывающая Плоть! Я тебе сразу скажу, $n, с этой птичкой что-то не так... Как мне кажется, тварь получает истинное наслаждение от убийства!$b$bС последним гладиатором, который с ним сражался, Вспарывающий Плоть несколько часов игралась, как кошка с мышкой, и только потом сожрала.$b$bУж постарайся как-нибудь выжить!', '', 'Если не хочешь, чтобы тебя сожрала Вспарывающая Плоть, держись подальше от ее клюва!', 'Вспарывающая Плоть', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34664, 'ruRU', 'Круг Испытаний: Хе\'йилаа', 'Победите Хе\'йилаа в Круге Испытаний.', 'Первые два боя остались за тобой, но расслабляться еще рано. Чем дальше – тем сложнее, $gсам:сама; понимаешь!$b$bТвоим следующим противником станет Хе\'йилаа – бывший рангари, у которого совершенно съехала крыша.$b$bСерьезно... Хе\'йилаа – это форменный псих!$b$bПрикинь, несколько лет назад он в одиночку спас весь свой отряд разведчиков от стаи гарнов. Но что-то, видать, в нем в тот день надломилось...$b$bВскоре после этого Хе\'йилаа совершенно слетел с катушек и напал на своих же бойцов!$b$bТак, ладно, инструктаж окончен! Выходи на арену и мочи там всех!', '', 'Он – бывший боец элитного отряда рангари, и поэтому его удары отличаются смертельной точностью.', 'Хе\'йилаа ', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34665, 'ruRU', 'Круг Испытаний: Капитан Бумшмяк', 'Победите капитана Бумшмяка в Круге Испытаний.', 'Ты уже $gсделал:сделала; себе имя, $n!$b$bОднако не обольщайся: слава – неверная подруга! Тебе бросил вызов один многообещающий гладиатор, который тоже хочет прославиться – никого не напоминает?$b$bТвой следующий соперник – капитан Бумшмяк, наемник Железной Орды. Он довольно быстро понял, что там ему просто так не озолотиться, потому и решил попытать счастья здесь!$b$bВ бою он использует крошшер, так что остерегайся лезвий... Да, и самое главное – огонь! Пуще всего берегись огня!', '', 'Победите капитана Бумшмяка и его милитаризированный крошшер!', 'Капитан Бумшмяк', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34666, 'ruRU', 'Круг Испытаний: Роакк Фанатичный', 'Победите Роакка в Круге Испытаний.', 'Скоро начнется твой финальный бой, $n! Ты $gпобедил:победила; всех лучших бойцов! До вершины остался последний шаг – бой с действующим чемпионом Круга Испытаний!$b$bТвоим соперником в финале станет араккоа по имени Роакк Фанатичный. Роакк совершенный псих! Он всем говорит, что его призвание – какая-то священная война во имя солнца.$b$bНо в любом случае он один из самых грозных бойцов, которых я повидал на своем веку. Он даже выступал в Колизее Верховного Молота!$b$bНе буду тебя зря обнадеживать – этот бой, скорее всего, станет для тебя последним в жизни... Удачи!', '', 'Он действующий чемпион Круга Испытаний, и один из самых опасных бойцов, которые когда-либо выходили на эту арену!', 'Роакк Фанатичный', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34667, 'ruRU', 'Двор Душ', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34668, 'ruRU', 'Vignette: Talonpriest Zorkra', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34671, 'ruRU', 'Vignette: Shirzir', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34672, 'ruRU', 'Возрождение Аку\'мая', 'Убейте Аку\'мая Пожирателя', 'Мы чудом избежали смерти на жертвенном алтаре Сумеречного Молота, но другим несчастным в глубинах этих пещер все еще требуется помощь. Если сектанты завершат свой ритуал крови, Аку\'май Пожиратель вырвется на свободу. Этого допустить нельзя.', '', 'Берегитесь голов Аку\'мая!', 'Аку\'май Пожиратель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34673, 'ruRU', 'Возрождение Аку\'мая', 'Убейте Аку\'мая Пожирателя', 'Мы еле избежали смерти на жертвенном алтаре Сумеречного Молота, но ведь нужно еще спасти и остальных. Если сектанты завершат ритуал крови, Аку\'май Пожиратель вырвется на волю. Ты уж постарайся, чтобы этого не случилось.', '', 'Берегитесь голов Аку\'мая!', 'Аку\'май Пожиратель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34674, 'ruRU', 'Передвинуть фронт в Награнд', 'Поговорите с лейтенантом Балфором у каравана в Награнде.', '**Секретно – командиру |3-2($n)**\n\nТеперь, когда база рангари в Телааре разрушена, воздаятельница Ирель посоветовала нам основать новую заставу в Награнде.$B$BЯ взял на себя смелость отправить туда часть бойцов и припасы. Рангари Д\'каан уже доложил, что застава почти достроена. Он попросил меня сообщить, что все готово к твоему прибытию.$B$BГрифон уже ждет, ты сможешь догнать последний караван с припасами, как только будешь $gготов:готова; отправиться в путь.\n\nБоудрик Грей, ШРУ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34675, 'ruRU', 'Могущество Песни Войны', 'Поговорите с рангари Д\'кааном на Телаарской станции.', '<Офицера явно терзает ужасная боль. Видно, что жить ему осталось считанные минуты.>$B$BПесня Войны. Внезапная атака.$B$BОни ушли... на запад.$B$B<Он замолкает, потом продолжает.>$B$BОни забрали... чертежи...$B$B<Это были его последние слова.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34676, 'ruRU', 'Жизненно важный маршрут', 'Поговорите с Дунгаром Долгопивом, чтобы отправиться в Таладор.', 'Через леса Таладора пролегают важнейшие маршруты материка. С западного побережья от Горгронда к Шаттрату движется флот Железной Орды.$B$BТаладор падет, если мы не позаботимся об укреплениях! По моей просьбе штейгер Эксос уже начал возведение опорного пункта наших сил неподалеку от места высадки Железной Орды. Обратитесь к нему и обсудите дальнейшие действия.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34678, 'ruRU', 'Запуск', 'Добудьте детали для инженерного дела, несущий винт и трансмиссионный маховик.', 'Мы потеряли Телаар, однако сейчас нам представилась редкая возможность нанести Песне Войны удар в самое сердце.$B$B$n, мы всецело полагаемся на твою мудрость и авторитет.$B$BНо сначала нужно вывести всех выживших из Телаара. Мои рангари готовы нанести удар. Нужно просто доставить тебя к ним.$B$BУ Телина есть коптер, он тебя довезет. Но, к сожалению, у него все силы уходят на то, чтобы управлять этой инфернальной машиной.$B$BПоможешь ему ее запустить?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34679, 'ruRU', 'Альянс: строим стойла', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34680, 'ruRU', 'Альянс: строим мастерскую', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34681, 'ruRU', 'Вопрос стратегии', 'Поговорите с Броном Небесным Рогом и договоритесь о полете в Таладор.', 'Железная Орда, оказывается, умеет воевать.$B$BИм удалось перевести флот из Горгронда в Таладор так, что мои шпионы ничего не заметили. В Таладор сходятся дороги со всего континента. Нельзя оставлять его в руках врага.$B$BТы не волнуйся, босс, у нас есть план. Штейгер Гробаш устраивает аванпост для наших войск. Когда ты приедешь туда, они уже будут готовы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34682, 'ruRU', 'Операция \"Внезапный налет\"', 'Воспользуйтесь гирокоптером Телина, чтобы добраться до наблюдательного пункта рангари.', 'Уцелевших после налета Песни Войны осталось немного. Рангари, которым посчастливилось выжить, ушли на один из утесов, возвышающихся над Телааром.$B$BОни ждут тебя и готовят внезапную контратаку.$B$BМой гирокоптер изрядно потрепан. Я настроил автопилот, чтобы ты $gсмог:смогла; добраться до места. Думаю, на этот последний полет его еще хватит.$B$BНадеюсь...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34683, 'ruRU', 'На шаг впереди', 'Поговорите с Дуротаном в Таладоре.', 'Эй, босс. Дуротан отправился с Дрекой и Газлоу отслеживать передвижения Железной Орды на побережье.$B$BОни ждут тебя на утесах на северо-западе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34685, 'ruRU', 'Дым поднимается', 'Найдите огранщика Барума рядом с Арууной в Таладоре.', 'Арууна горит.$B$BАраккоа налетели со своих пиков и превращают все и всех в пепел. Дренеев, талбуков и даже орков. Араккоа не заботят альянсы, они хотят испепелить весь мир.$B$BМне удалось спастись бегством, но мой лучший друг Барум остался, чтобы найти свою дочь. Все говорят, что на тебя можно положиться. Умоляю тебя, отправься в Арууну и найди их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34692, 'ruRU', 'Передача полномочий', 'Подойдите к командирскому столу и отправьте Киану Тень Луны на задание.', 'На Дреноре столько всего надо сделать, что самим нам никак не справиться. Нужно передать часть работы в другие руки.$b$bГруппе ночных эльфов на Заставе Падающих Звезд нужна помощь опытного воина.$b$bКиана идеально подойдет для этого задания.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34696, 'ruRU', 'Леди Света', 'Поговорите с леди Лиадрин на Пылающей передовой в Таладоре.', '$n? Ты здесь за $gглавного:главную;? Предводитель рыцарей Дранар к твоим услугам.$B$BЛеди Лиадрин сообщила о появлении демонов к юго-западу отсюда, в Аукиндоне, и просит твоей помощи. Гул\'дан не должен завладеть Аукиндоном.$B$BОтправляйся в путь как можно скорее, Леди будет тебе благодарна.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34697, 'ruRU', 'Возвращение легенды', 'Найдите Кас\'дракора рядом с ареной Каменного Молота в Горгронде.', 'Если твои отряды хотят учиться сражаться, найди им наставников! И хороших.$b$b$gСлышал:Слышала; о Кас\'дракоре?$b$bЭто знаменитый орк-воин из клана Северного Волка, который пытался убить нас, Черепов. И ему бы это удалось, если бы огры его не поймали.$b$bК северу отсюда находится арена Каменного Молота, они отвезли его туда вместе с остальными гладиаторами.$b$bЕсли сумеешь освободить гладиаторов, они станут отличными учителями – лучше не найдешь.', '', '', '', '', '', 'Найдите Кас\'дракора рядом с ареной Каменного Молота в Горгронде.', 25549);
INSERT INTO `quest_template_locale` VALUES (34698, 'ruRU', 'Охотники на рабов', 'Соберите подвески Брола, Крага и Мола.', 'Каждый раз, когда из Каменного Молота убегает гладиатор, за ним отправляют опытных охотников на рабов.$b$bЯ считаю себя опытным воином, несколько лет я отдал арене.$b$bНо охотники на рабов делают для надзирателей подвески, по которым они могут отследить нас повсюду. А потом убить, когда мы уснем или просто утратим бдительность.$b$bЯ не имею права просить тебя о таком, но все же – ты можешь пойти в Каменный Молот и забрать оттуда подвески?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34699, 'ruRU', 'Освободить гладиаторов', 'Спасите гладиаторов Бруто, И\'киша и бойца Ваандаама.', 'Когда мы бежали из Каменного Молота, нам пришлось оставить нескольких товарищей.$b$bЕсли мы попытаемся их спасти и нас узнают, огры поймут наш замысел и первым делом убьют наших друзей.$b$bТебя огры не знают, и это может дать тебе шанс на бой.$b$bЗайди в Каменный Молот, найди других гладиаторов и освободи их из плена. Сделай это – и мы будем век тебе обязаны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34700, 'ruRU', 'Назгрел', 'Спасите Назгрела.', 'Вырваться из лап клана Каменного Молота было проще всего. Дело в том, что мой сын до сих пор находится в плену у этих мерзких огров.$b$bПоначалу они держали его у себя, чтобы заставить меня сражаться на их аренах. Однако теперь, когда я сбежал, они будут готовить его к тому, чтобы он занял мое место.$b$bПрошу тебя, спаси моего сына. Сам я не могу – они убьют его сразу, как только меня увидят.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34701, 'ruRU', 'Голос тех, кого нет', 'Поговорите с Экзархом Маладааром на Пылающей передовой в Таладоре.', 'Слава Свету, ты здесь! Экзарх Маладаар попросил найти тебя.$B$BНам нужна твоя помощь. На Аукиндон напали демоны!$B$BКак можно скорее отправляйся на юго-запад к Пылающей передовой! Экзарх Маладаар мало кому доверяет и хочет, чтобы именно ты $gвозглавил:возглавила; оборону.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34702, 'ruRU', 'Крав\'огра', 'Ударьте в гонг для поединков на Арене Каменного Молота и убейте надсмотрщика Ок\'мока.', 'У Каменных Молотов есть вождь и есть надсмотрщик. Сегодня мы убить оба.$b$bСначала – Ок\'мок. Я убить первый раз, когда быть... вот как ты маленький совсем. Знать слово жестокость. Надсмотрщик Ок\'мок – это жестокая жестокость.$b$bХочешь быть гладиатор? Иди тогда на Арену Каменного Молота, бдыщь в гонг в центре арены и делай убить зверей.$b$bМожет, Ок\'мок разозлится, сам придет тебя убить. А вот тогда ты его $Gсам:сама; убить.', '', 'Торговец плотью', 'Надсмотрщик Ок\'мок', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34703, 'ruRU', 'Топор Кор\'галла', 'Убейте Кор\'галла и заберите его топор Сератил.', 'Пришло время отмщения! Мы убьем Кор\'галла, а ты заберешь его топор.$b$bРазбей этот жалкий заслон и иди по мосту за ним, пока не дойдешь до трона вождя.$b$bМы свободны благодаря тебе – тебе и принадлежит честь первой крови. Мы последуем за тобой. ', '', 'Жестокий вождь клана Каменного Молота', 'Кор\'галл', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34704, 'ruRU', 'Возвращение легенды', 'Отыщите гладиатора Акаани у Арены Каменного Молота в Горгронде.', 'Эта арена – хорошее начало, но нам нужны учителя, способные превратить твои отряды в настоящих бойцов.$b$bГоворят, к западу отсюда видели дренейку, по описанию похожую на Акаани.$b$bЭто интересно, ведь считалось, что она погибла. Она – один из лучших дренейских воинов и владеет почти всеми известными видами оружия.$b$bКомандир, лучшего наставника просто быть не может. Я советую тебе разыскать ее – если это и правда она...', '', '', '', '', '', 'Отыщите гладиатора Акаани у Арены Каменного Молота в Горгронде.', 25549);
INSERT INTO `quest_template_locale` VALUES (34705, 'ruRU', 'Tracking Quest - Shadowmoon Intro', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34706, 'ruRU', 'Объединение', 'Поговорите с предводителем рыцарей Дранаром в Гордости Вол\'джина.', 'Твоя работа здесь окончена, $n. Я останусь здесь и помогу уничтожить оставшихся демонов.$B$BА ты возвращайся в лагерь и расскажи Дранару о наших успехах. Он передаст эти новости на Азерот.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34707, 'ruRU', 'Объединение', 'Поговорите с воздаятельницей Исией в Форте Ринн.', 'Гул\'дан и его дружки надолго запомнят этот день. Аукенаи не позволят себя запугивать.$B$BОтправляйся в свой лагерь и сообщи воздаятельнице Исие о своем успехе. Она сможет найти всех беженцев и их семьи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34708, 'ruRU', 'Vignette: Jehil the Climber', 'Уничтожьте $1oa |4кладку:кладки:кладок; яиц горенов, $2oa |4железоеда:железоедов:железоедов; Ледяной Кузни и праматерь Риг\'ак.', 'Горены опасны для нас – их много, а наш шаман слеп и обессилен.$b$bКонечно, век этих чудовищ короток, но они очень быстро размножаются и растут.$b$BЧтобы справиться с горенами, нам нужно найти их матку, убить ее и уничтожить яйца. Так мы сможем на какое-то время обезопасить себя. Осмотри норы у врат Кузни, а я сделаю так, чтобы горены не напали на след Дрек\'тара.', '', '', '', '', '', 'Вернитесь к Дреке, к Вратам Кузни, что на Хребте Ледяного Огня.', 19865);
INSERT INTO `quest_template_locale` VALUES (34709, 'ruRU', 'Важна каждая мелочь', 'Поговорите с Агейлаа в Иорунской шахте в Таладоре.', 'Твоя помощь нужна в Иорунской шахте к западу отсюда!$B$BТебя ищет моя хорошая подруга Агейлаа. Экзарх Маладаар отправил на помощь воздаятелей, но без тебя им не справиться!$B$BТы сможешь отправиться в туда и помочь? Нам нужны кристаллы из шахты, чтобы усилить оборону. Ты уже $gвидел:видела; такие кристаллы на Пылающей передовой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34710, 'ruRU', 'Важна каждая мелочь', 'Поговорите с Агейлаа в Иорунской шахте в Таладоре.', 'Мадуил Зов Небес отправился на важное задание в Иорунскую шахту, но так и не вернулся.$B$BПодозреваю, что ему нужна помощь, и он сам расскажет тебе подробности задания. Вероятно, он находится где-то в глубинах шахты.$B$BТебе поможет Агейлаа – дренейка, которая согласилась сотрудничать с нами в обмен на то, что мы поможем ей вновь получить контроль над шахтой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34711, 'ruRU', 'Повод отпраздновать', 'Поговорите с магистром Сереной в форте Ринн.', 'Ну что, возвращаемся на твой аванпост? Праздновать твою победу там будет куда удобнее – и безопаснее.$B$BЯ перенесу нас туда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34712, 'ruRU', 'Повод отпраздновать', 'Поговорите с магистром Креласом в Гордости Вол\'джина.', 'Мне бы не хотелось разговаривать об этом тут.$B$BМожет, вернемся на твой аванпост? Праздновать победу там будет куда удобнее.$B$BЯ перенесу нас туда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34713, 'ruRU', 'Treasure: Gronnstalker\'s Cache', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34714, 'ruRU', 'Frostfire Ridge: (RRP) - Treasure - Pale Leather Cache', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34715, 'ruRU', 'Tracking Flag: Shamanstone Summons', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34716, 'ruRU', 'Мо\'мор должен знать', 'Найдите воздаятеля Мо\'мора в Телааре.', 'Мы знаем, кто возглавлял атаку Песни Войны на караван в Телааре. Чертежи должны быть у этой женщины-орка.$B$BУ нас нет информации, где конкретно она сейчас находится, но кое-кто может знать это наверняка.$B$BВоздаятеля Мо\'мора взяли в плен. Он может знать, где сейчас находятся чертежи – если его еще не убили.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34717, 'ruRU', 'Операция \"Наконечник стрелы\"', 'Убейте $1oa |4орка или волка:орков или волков:орков или волков; клана Песни Войны в Телааре.', 'Разумеется, мы поможем тебе разобраться с орками Песни Войны.$B$BТы только начни бой, а мы его завершим и не пощадим никого.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34718, 'ruRU', 'Остальные', 'Спасите Вершителя Хана, хозяйку таверны Фелаану с Изелью и Гензеля Большерука.', 'Кое-кому все же посчастливилось выжить. Я видел, как они навалились всем скопом на Вершителя Хана во время драки.$B$BИ еще я слышал плач малышки Изель. Она где-то рядом. Надеюсь, ее мать еще жива.$B$BТвой приятель-дворф Гензель попытался вызволить нас. Он, видать, решил, что в одиночку одолеет весь клан Песни Войны. Боюсь, я не знаю, что с ним сейчас.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34719, 'ruRU', '…и мой молот', 'Отыщите священный молот Мо\'мора.', 'Когда я попал в плен, орки Песни Войны забрали мой молот. Ты поможешь мне его вернуть?$B$BПрошу тебя об этом только лишь потому, что это священная реликвия. Его нужно вырвать из лап этих гнусных орков и доставить в Аукиндон.$B$BБыть может, другой достойный воздаятель когда-нибудь возьмет его в руки и сокрушит наших врагов во имя Света.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34720, 'ruRU', 'Операция \"Наконечник стрелы\"', 'Убейте $1oa |4орка:орков:орков; клана Песни Войны в Телааре.', 'Вне всякого сомнения, с орками клана Песни Войны в Телааре нужно разобраться как можно скорее. Рангари Огир и его бойцы на утесе помогут тебе истребить орков.$B$BТы только начни бой, а мы его завершим и не пощадим никого.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34721, 'ruRU', 'Найти провидицу', 'Поговорите с провидицей Малунэ на острове Сгущающихся Сумерек в Таладоре.', 'Мы следили за тобой, $n.$B$BПровидица Малунэ, хранительница воспоминаний, хочет встретиться с тобой, $gискатель:искательница; приключений.$B$BОна предсказала появление $gмогучего воина, который:могучей воительницы, которая; остановит тьму. Мы считаем, что $gэтот воин:эта воительница; – ты.$B$BОтправляйся на юго-восток к острову Сгущающихся Сумерек и исполни свою судьбу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34723, 'ruRU', 'Гавань Железного Кулака', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34724, 'ruRU', 'Позабытые пещеры', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34725, 'ruRU', 'Событие: морская гидра', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34726, 'ruRU', 'Событие: бледная паучья праматерь', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34727, 'ruRU', 'Событие: морской повелитель Торглорк', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34728, 'ruRU', 'Мерцающая топь', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34729, 'ruRU', 'Клятва на крови На\'шры', 'Примите клятву на крови мастера клинка На\'Шры.', 'Ты мне очень $gпомог:помогла;. Теперь этот клинок принадлежит не только мне, но и тебе.$b$bЯ клянусь на крови служить тебе и использовать все свои знания о клинках и руде, чтобы помогать тебе.$b$bПримешь ли ты мою клятву?', '', 'На\'Шра, только что получившая звание мастера клинка, – грозная воительница.', 'Мастер клинка На\'Шра', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34730, 'ruRU', 'Клятва крови Локры', 'Примите клятву на крови мастера клинка На\'шры.', 'Ты мне очень $gпомог:помогла;. Теперь этот клинок принадлежит не только мне, но и тебе.$b$bЯ клянусь на крови служить тебе и использовать все свои знания о клинках и руде, чтобы помогать тебе.$b$bПримешь ли ты мою клятву?', '', '', 'Мастер клинка На\'Шра', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34731, 'ruRU', 'Клятва темного охотника Ралы', '', '', '', 'На\'Шра, только что получившая звание мастера клинка, – грозная воительница.', 'Мастер клинка На\'Шра', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34732, 'ruRU', 'Маэстр предлагает помощь', '', '', '', 'На\'Шра, только что получившая звание мастера клинка, – грозная воительница.', 'Мастер клинка На\'Шра', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34733, 'ruRU', 'Услуги Дагга', '', '', '', 'На\'Шра, только что получившая звание мастера клинка, – грозная воительница.', 'Мастер клинка На\'Шра', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34734, 'ruRU', 'The Loyalty of Olin Umberhide', '', '', '', '', 'Мастер клинков На\'Шра', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34736, 'ruRU', 'Нам нужны припасы', 'Поговорите с темным охотником Ралой на Уступе Черного Копья.', 'Командир, наши бойцы не готовы воевать на морозе. Я решил проявить инициативу и послал на север несколько наших темных охотников, чтобы они там организовали базу снабжения.$b$bДумаю, тебе стоит отправиться туда и присмотреть за всем. Ищи лощину между Растрескавшимися равнинами и Диким утесом.', '', '', '', '', '', 'Поговорите с темным охотником Ралой на Уступе Черного Копья.', 25549);
INSERT INTO `quest_template_locale` VALUES (34737, 'ruRU', 'Мастера теней', 'Убейте Унгру, надсмотрщика Гуррана и Анкову Падшую.', 'Плохие орки меня ловили-ловили, но я сбежал. Я хорошо прячусь.$b$bВсе плохие орки – плохие, но я запомнил имена самых гадких. Вдруг кто-нибудь придет и меня спасет.$b$b<Луука делает глубокий вдох.>$b$bУнгра, Гурран и... гм... ох! Анкова.$b$bТы защитишь меня от них?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34739, 'ruRU', 'Клан Призрачной Луны', 'Убейте 10 орков из клана Призрачной Луны или волков Бездны в Темных залах.', 'Мы сдержим здесь Каргата и защитим раненых пленников. А ты, $n, ступай вперед и зачисти пещеру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34740, 'ruRU', 'Ирель', 'Проводите Ирель до безопасного места.', 'Извини, я немного взволнована: раньше мне не приходилось убивать.$b$bМеня зовут Ирель, я послушница из Карабора.$b$bГоворишь, с тобой пришла целая армия?! Воистину, сегодня Свет мне благоволит.$b$bЯ пойду с тобой. Веди, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34741, 'ruRU', 'Кели\'дан Разрушитель', 'Убейте Кели\'дана Разрушителя.', 'В живых остался только один из приближенных последователей Нер\'зула. Где-то на тропе за ним должен быть выход из пещеры.$b$bЯ вернусь и доложу Кадгару, что пещера зачищена. Встретимся, когда ты разберешься с Кели\'даном!', '', 'Помощник Нер\'зула. Верховный колдун клана Призрачной Луны.', 'Кели\'дан Разрушитель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34743, 'ruRU', 'Событие: Хрустальный клинок Торвата', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34746, 'ruRU', 'Опустить щиты!', 'Уничтожьте кристалл каронита и заберите гарнизонные чертежи у предводительницы стаи Каргоры.', 'Ты это $gслышал:слышала;? Они активировали щит. Теперь в Телаар не попасть.$B$BТебе нужно будет отключить щит. Сделать это можно только одним способом – уничтожить кристалл каронита.$B$BЗа меня не беспокойся. Одним выстрелом ты убьешь двух зайцев: нужные тебе чертежи украла их предводительница стаи Каргора.', '', 'Чертежи у нее. Убейте ее и уничтожьте каронитовый щит.', 'Предводительница стаи Каргора', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34747, 'ruRU', 'Честь мастера клинка', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34751, 'ruRU', 'Разряд!', 'Соберите $1oa |4железу озерного электрического угря:железы озерных электрических угрей:желез озерных электрических угрей; в Таладоре.', 'Ты $gдолжен:должна; помочь мне починить этого робота. Я тут с голода подыхаю!$B$BСпециально построил \"Гедотрон-8000\", чтобы он добывал дренорские трюфеля, и что? Он приплыл на дурацкий остров, и тут у него закоротило вариатор напряжения.$B$BЯ подключил аккумулятор, но он недостаточно заряжен, чтобы перезапустить вариатор. Будь умницей и принеси мне железы озерных электрических угрей, ладно? Этого будет достаточно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34755, 'ruRU', 'Событие: капитан Башгар', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34756, 'ruRU', 'Обман зрения', 'Используйте $1oa |4амулет иллюзии:амулета иллюзии:амулетов иллюзии;, чтобы привлечь внимание приверженцев-налетчиков.', 'Время не пощадило Решада, этого старого ворона, который и минуты не может прожить без книги. Но на самом деле он обладает гораздо большей силой, чем кажется на первый взгляд. Его помощь для нас бесценна.$B$BТени сгущаются над одиноким пиком Гнездовья Терокк. Нужно позаботиться о безопасности Решада в пути.$B$BПо дороге ты увидишь несколько зачарованных амулетов. Коснись их, чтобы принять облик Решада и сбить врагов с толку.$B$BСтарого отшельника подстерегают приверженцы-убийцы, желая заполучить его свитки, так что будь $gосторожен:осторожна;.$B$BДа, пожалуй, они удивятся, когда иллюзия рассеется. Но будет уже поздно, хе-хе-хе!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34758, 'ruRU', 'Поиск помощников', 'Найдите рыбака, который поделится с вами секретом рыбной ловли в этих местах.', 'Мы обнаружили отличный пруд, но в нем совершенно не ловится рыба! Нужно найти кого-нибудь из местных рыбаков – наверняка они должны знать, в чем тут хитрость. Отправляйся на юго-восток и займись этим.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34760, 'ruRU', 'Сокровище: сокровище Кулл\'кроша', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34761, 'ruRU', 'Разряд!', 'Соберите $1oa |4железу озерного электрического угря:железы озерных электрических угрей:желез озерных электрических угрей; в Таладоре.', 'Ох, как я страдаю за все грехи гномо сапиенс!$B$B\"Гедотрон-8000\" сломался, не успев найти ни одного дренорского трюфеля. Он приплыл на дурацкий остров, и тут у него закоротило вариатор напряжения.$B$BОПЯТЬ!$B$BПитание есть, но его недостаточно, чтобы перезапустить вариатор.$B$BМожешь принести мне железы озерных электрических угрей? Уверен, что тогда все получится!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34765, 'ruRU', 'Логово Скога', 'Убейте Скога.', 'Нашествие гроннов, похоже, само не рассосется. Придется тебе показать им, кто тут главный – как это принято у нас в Орде!$b$bРаз тут такая толпа малых гроннов, где-то должна быть мамаша всего этого выводка. Найди ее... или его, пес их разберет – и убей. Тогда, наверное, вся эта малышня уберется отсюда сама.', '', 'Мать и/или отец местных малых гроннов.', 'Ског', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34766, 'ruRU', 'Логистический кошмар', 'Верните $1oa |4мешок с припасами:мешка с припасами:мешков с припасами; и $2oa |4запись гарнизона:записи гарнизона:записей гарнизона;.', 'Командир, боюсь, что у меня неприятные новости.$B$BГруппа саблеронов проследовала за нами из Горгронда. Они воруют наши припасы, роются в наших архивах и убивают крестьян!$B$BНе хочется беспокоить тебя, командир, но сейчас все взялись за оружие и охраняют лагерь от набегов. Мы отчаянно нуждаемся в припасах! Без них мы не сможем нести службу!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34769, 'ruRU', 'Нелегкий выбор', 'Подойдите к чертежному столу и выберите постройку – стойла или танковую мастерскую.', 'Все готово, можно начинать. Тебе нужно просто сделать выбор.$B$BПосмотри на чертежи – они на чертежном столе.$B$BСтроим стойла или танковую мастерскую?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34770, 'ruRU', 'Честь мастера клинка', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34771, 'ruRU', 'Приятные мелочи', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34772, 'ruRU', 'Клетка Моркета', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34773, 'ruRU', 'Напитки тоже пропали!', 'Верните $1oa |4длинный меч пехотинца:длинных меча пехотинцев:длинных мечей пехотинцев; и $2oa |4бочонок громоварского:бочонка громоварского:бочонков громоварского;.', 'Командир, у нас небольшая... мм-м... проблема.$B$BЭти саблероны шли за нами из самого Горгронда – они крадут оружие у пехотинцев и убивают крестьян!$B$BНе хочется беспокоить тебя, командир, но сейчас все охраняют лагерь от набегов. Кроме того... $B$B<Интендант О\'Райли понижает голос до шепота.>$B$BОни унесли наше пиво!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34774, 'ruRU', 'Блескотрон-5000', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34775, 'ruRU', 'Миссия мыслима', 'Подойдите к командирскому столу, чтобы послать Оулина Бурошкура на задание.', 'Несмотря на недавние поражения, таурен Оулин Бурошкур кажется искусным бойцом. Он определенно умеет обратить на себя внимание противника.$b$bУ меня появилось задание, где его навыки будут очень кстати.$b$bКогда будешь $gготов:готова;, просто подойди к командирскому столу и отдай приказ. Тогда мы тут же отправим таурена в бой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34776, 'ruRU', 'Привратники Аукиндона', 'Победите воздаятеля Далу и стражницу душ Халаари в бою.', 'Мы направлялись в Аукиндон, но Железная Орда напала на наш караван, и меня взяли в плен.$B$BМне удалось сбежать, но эти духи не отпускают меня к Верным Солнцу, пока кто-нибудь не одолеет их в бою!$B$BПрошу, помоги мне победить их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34777, 'ruRU', 'Привратники Аукиндона', 'Победите воздаятеля Далу и стражницу душ Халаари.', 'Аукиндон в опасности, $gнезнакомец:незнакомка;, и я хочу защитить его.$B$BВот только у меня получилось найти лишь старые доспехи деда, и в них мне ни за что не одолеть духов, которые преграждают путь в Аукиндон.$B$BТы можешь победить их и провести меня с собой? Я найду способ отблагодарить тебя!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34778, 'ruRU', 'Работники-переселенцы', 'Поговорите со штейгером Шипосвистом в гарнизоне, затем встретьтесь с работниками возле Элодора.', '$n, каждый час в гарнизон прибывают новобранцы. Скоро у нас закончится продовольствие.$b$bМы обратились к экзарху Акаме в надежде наладить поставку провианта из Элодора – житницы этой долины. Он согласился на том условии, что мы предоставим им работников на время уборки урожая. Все в выигрыше.$b$bЕсли мой план тебе по душе, поговори со штейгером Шипосвистом – он собрал во дворе работников, которые сейчас сидят без дела. Мы с Акамой поведем их на восток, в Элодор. Встретимся там!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34779, 'ruRU', 'Оборона повозки', 'Найдите Мараада и пропавших работников и проводите их на Элодорские поля.', 'Одна из наших повозок отстала и пропала где-то в лесах к северо-западу отсюда. Там были воздаятель Мараад и несколько твоих работников.$b$bОтыщи их и помоги им вернуться сюда!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34780, 'ruRU', 'Незримая оборона', 'Отнесите заряженные кристаллы-резонаторы к первому, второму и третьему пилонам.', 'Экзарх Акама предпочитает действовать осторожно, однако не стоит недооценивать орков Призрачной Луны. Поэтому твое появление тут как нельзя кстати.$B$BС тех пор как мы прибыли на Дренор, я посвятил себя воссозданию технологии, которую мы использовали в нашем родном мире. Видишь это сооружение? Это генератор защитного поля. Он способен задержать наступление орков, но сначала нужно его зарядить.$B$BКристаллы-резонаторы лежат в моей мастерской к югу отсюда. Вынеси их оттуда – не больше одного за раз – и помести на три столба, окружающие установку. После этого включи ее с помощью панели управления.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34781, 'ruRU', 'Защитник', 'Убейте $1oa |4налетчика:налетчиков:налетчиков; или |4темную жрицу:темных жриц:темных жриц; из клана Призрачной Луны', 'Энергия устремляется к наружному кристаллу, и вы сразу же слышите отдаленные боевые кличи и крики тревоги. На Элодор напали!$b$bЕсли вы хотите, чтобы ваши работники вернулись домой целыми и невредимыми, надо помочь защитить город. Отбейте вторжение и вернитесь к панели управления, чтобы перезапустить систему обороны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34782, 'ruRU', 'Совет экзархов', 'Поговорите с экзархом Отааром в Элодоре.', 'Ты отлично $gпоработал:поработала; у ворот! Орки из клана Призрачной Луны зачем-то искали пленников. Их агрессия нам только на руку.$b$bПойдем со мной. Хочу представить тебя Совету экзархов, который еще называют Рукой Пророка. Я пытался убедить Совет поддержать нас и начать борьбу с Железной Ордой, но они как всегда слишком осторожны и медлительны.$b$bДля начала я познакомлю тебя с экзархом Отааром. Он вон там, на холме. Возможно, встреча с героем Альянса повлияет на решение совета.', '', '', '', '', '', 'Поговорите с экзархом Отааром в Элодоре, что в Долине Призрачной Луны.', 25549);
INSERT INTO `quest_template_locale` VALUES (34783, 'ruRU', 'Найель, рангари', 'Поговорите с экзархом Найель в Анклаве рангари.', 'Я созываю Совет экзархов, чтобы выслушать тебя. Никто из нас не сомневается, что Железная Орда – это серьезная угроза. Но лишь немногие могут сойтись во мнении, что нам нужно делать. Тебе и воздаятелю Марааду предстоит сплотить всех экзархов.$b$bЭкзарх Найель возглавляет рангари \"Око Пророка\". Это разведчики, они тайно ведут наблюдение даже в самых дальних уголках Дренора. Ищи ее в Анклаве рангари к северо-западу отсюда.', '', '', '', '', '', 'Поговорите с экзархом Найель в Анклаве рангари, что в Долине Призрачной Луны.', 25549);
INSERT INTO `quest_template_locale` VALUES (34784, 'ruRU', 'Грибное помешательство', 'Используйте мерцагрибы, чтобы собрать $oa |4нестабильную спору:нестабильные споры:нестабильных спор;.', 'У нас, рангари, особая миссия – исследовать и понять этот мир. Вокруг тебя раскинулась Тенетопь. Много дренеев погибло, когда мы впервые пришли сюда. Нестабильные споры взрываются, как только кто-то подходит слишком близко к ним.$b$bНо мы наблюдали за ними – и поняли, как этого избежать.$b$bНа болоте растут так называемые мерцагрибы – ты их легко узнаешь по оранжевым светящимся шляпкам. Пыль из этих грибов сделает тебя $Gневидимым:невидимой; для взрывоопасных спор. Собери споры – только аккуратно! – и принеси их мне.$b$bМы используем смертоносное оружие этого мира себе во благо.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34785, 'ruRU', 'Хатаару, механолог', 'Поговорите с экзархом Хатаару возле Элодорской шахты.', 'Мне также потребуется, чтобы ты $gпомог:помогла; экзарху Хатаару. Ты уже $gпомогал:помогала; ему с защитой врат.$b$bХатаару наш главный механолог, он разбирается в наших технологиях лучше, чем кто-либо еще. И в поте лица работал над воссозданием былого величия нашей цивилизации после побега с родной планеты.$b$bОн переехал в свою мастерскую, она находится неподалеку от Элодорской шахты на юго-востоке, там мы добываем кристаллы. Ты найдешь его у входа в шахту.', '', '', '', '', '', 'Поговорите с экзархом Хатаару возле Элодорской шахты в Долине Призрачной Луны.', 25549);
INSERT INTO `quest_template_locale` VALUES (34786, 'ruRU', 'Раздутый горен', 'Соберите $1Oa |4кристаллическую чешуйку:кристаллические чешуйки:кристаллических чешуек; горена, убивая горенов в Элодорской шахте.', 'Должно быть, ты $gтот самый:та самая:c; |3-6($c), о ком так хорошо отзывался экзарх Хатаару. Можешь мне помочь?$b$bЭлодорская шахта за моей спиной прямо-таки кишит странными каменными созданиями. Эти так называемые горены поедают минералы, переваривают их и преобразуют в кристаллические выросты на своих спинах и верхних конечностях. Они ощутимо мешают нашим планам, как и большинство прочих диких обитателей этого мира.$b$bПрошу, убей как можно больше горенов и собери их кристаллическую чешую. Так ты защитишь землекопов от хищников и к тому же поможешь нам с исследованиями.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34787, 'ruRU', 'Экзарх Маладаар', 'Поговорите с экзархом Маладааром на Волшебной площадке к югу от Элодора.', 'Почти все члены Совета в сборе: Отаар, я, Хатаару и Найель. Не хватает только экзарха Маладаара. После того как экзарх вернулся из плена Железной Орды, он сам не свой. Воздаятель Мараад с трудом его отыскал.$b$bМаладаар должен сейчас быть на Волшебной площадке – это к югу от центра города. Поговори с ним.', '', '', '', '', '', 'Поговорите с экзархом Маладааром на Волшебной площадке к югу от Элодора в Долине Призрачной Луны.', 25549);
INSERT INTO `quest_template_locale` VALUES (34788, 'ruRU', 'Друг экзархов', 'Выберите соратника (Андрена, Шел или Онаалу) и поговорите с экзархом Найель.', 'В Совете экзархов осталось лишь трое, но мы у тебя в большом долгу. Решение принято единогласно: мы полностью поддержим Альянс на Дреноре.$b$bМы также собираемся передать под твое непосредственное командование представителя дренеев. Во дворе ждут твоего решения три кандидата. Поговори с ними и реши, кого возьмешь с собой – мы сразу же отправим его или ее в твой гарнизон.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34789, 'ruRU', 'Голос тех, кого нет', 'Встретьтесь с экзархом Маладааром на утесах к востоку от алтаря Ша\'тар. Завершите ритуал очищения и допросите труп Хатаару.', 'Предатель – один из нас. Другого объяснения я не вижу. Экзархи теперь не доверяют друг другу – и особенно мне. Отаар и Акама вполне могли нарушить законы чести... Мы должны выявить изменника, а сделать это можно, лишь поговорив с погибшим.$b$bЯ буду ждать тебя за алтарем Ша\'тар на восточных утесах. Мы со стражницей душ Ниами проведем ритуал экзорцизма, чтобы спасти бессмертную душу Хатаару... заодно, возможно, узнаем, кто был его убийцей.$b$bТы доверяешь мне, $n?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34790, 'ruRU', 'Горькая правда', 'Раздобудьте безупречное жало лунного спороската.', 'Вижу, экзархи доверяют тебе, |3-6($c). Ты собираешься в Тенетопь?$b$bСпороскаты, обитающие в тех краях, обычно не проявляют агрессии, но в последнее время что-то их сильно взбудоражило. При нападении они обвивают своими хвостами-жалами незащищенные конечности жертв. Я видела, как они рвут дубленую кожу – словно бумагу. Интересно, как устроены эти их хвосты?$b$bНе $gмог:могла; бы ты принести мне безупречное жало спороската? Было бы очень интересно рассмотреть его поближе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34791, 'ruRU', 'Предупредить экзархов', 'Поговорите с экзархом Маладааром у алтаря Ша\'тар в Долине Призрачной Луны.', 'Вы сжигаете книгу, пробежав взглядом по ее страницам. Демонический фолиант посвящен зачарованию оружия энергией Скверны. Судя по всему, цель такого зачарования – поработить душу жертвы.$b$bНадо предупредить экзархов, что среди них затесались предатели! Совет сейчас собирается на холме к востоку от вас.', '', '', '', '', '', 'Поговорите с экзархом Маладааром у алтаря Ша\'тар в Долине Призрачной Луны.', 25549);
INSERT INTO `quest_template_locale` VALUES (34792, 'ruRU', 'Истинное имя предателя', 'Установите фокусирующую линзу на Вершине экзарха в Долине Призрачной Луны.', 'Мы должны сделать так, чтобы предатель нигде не мог от нас скрыться. У меня есть специальная фокусирующая линза, которая позволит обнаружить скрытую энергию скверны. Если установить ее на какой-нибудь возвышенности, она выявит в нашем поселении всех, кого коснулась скверна.$b$bНа Вершине Экзарха находится молитвенная площадка – она отлично подойдет для этой цели. Установи фокусирующую линзу, $n. Если что-то обнаружишь, разберись. Потом спускайся ко мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34793, 'ruRU', 'Приветствие аукенайских защитников', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34794, 'ruRU', 'Передвинуть фронт в Награнд', 'Поговорите с каменным стражем Броксом у каравана в Награнде.', 'Босс, хорошо, что ты здесь.$b$bДуротан приказал нам укрепиться в Награнде, так что я сам решил отправить туда кое-кого из ребят.$B$BТралл сообщил, что застава уже почти достроена. Он просил передать, что все будет готово к твоему приезду.$B$BВетрокрыл уже ждет тебя, ты сможешь догнать на нем последний караван с припасами, как только будешь $gготов:готова; отправиться в путь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34795, 'ruRU', 'Могущество Песни Войны', 'Поговорите с Траллом в Вор\'варе.', '<Офицера явно терзает ужасная боль. Видно, что жить ему осталось считанные минуты.>$B$BПесня Войны. Внезапная атака.$B$BОни ушли... в Пылающий... Клинок.$B$B<Он замолкает, потом продолжает.>$B$BОни забрали... чертежи...$B$B<Это были его последние слова.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34801, 'ruRU', 'Неудачное паломничество', 'Соберите $1oa |4флакон:флакона:флаконов; с кровью хищника, $2oa |4росток:ростка:ростков; львиного зева и глаз речного прыгуна.', 'Клянусь, я всего лишь паломник. Пожалуйста, не трогай меня!$B$BМы с сестрой отправились в Аукиндон, чтобы навестить бабушку, но по пути врезались в каменную глыбу, и наши повозки перевернулись. Мне удалось выжить, но моя сестра...$B$B<Надур плачет.>$B$BПрошу тебя, ты $gдолжен:должна; мне помочь. Я в отчаянии. Но... если ты отыщешь кровь хищника, цветки львиного зева и глаз речного прыгуна, то я смогу приготовить зелье, чтобы вернуть ее. Я знаю, что смогу...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34802, 'ruRU', 'Неудачное паломничество', 'Соберите $1oa |4флакон:флакона:флаконов; с кровью хищника, $2oa |4росток:ростка:ростков; львиного зева и глаз речного прыгуна.', 'Мы с сестрой отправились в Аукиндон, чтобы навестить бабушку, но по пути врезались в каменную глыбу, и наши повозки перевернулись. Мне удалось выжить, но моя сестра...$B$B<Надур плачет.>$B$BПрошу тебя, ты $gдолжен:должна; мне помочь. Если ты отыщешь кровь хищника, цветки львиного зева и глаз речного прыгуна, то я смогу приготовить зелье, чтобы вернуть ее. Я знаю, что смогу...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34803, 'ruRU', 'Пусть бегут', 'Убейте Злогрыза у Гордости Вол\'джина.', 'Разведчики обнаружили альфа-самца саблеронов прямо за нашими воротами!$B$BКомандир, если расправиться с ним, то остальные тут же разбегутся по пещерам.$B$BНе хотелось попусту тебя беспокоить, но ведь только ты сможешь его одолеть…', '', '', 'Злогрыз', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34804, 'ruRU', 'Не в вашем доме', 'Убейте Кишкодера у Форта Ринн.', '$GСэр:Мэм;, мы обнаружили альфа-самца саблеронов прямо за нашими воротами!$B$BМы считаем, что если убить его, то остальные убегут, поджав хвост. Но этот зверь огромен!$B$BНе хотелось попусту тебя беспокоить, но только ты можешь его одолеть.', '', '', 'Кишкодер', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34805, 'ruRU', 'Эхоловы', 'Убейте $1oa |4эхолова:эхолова:эхоловов;.', 'Я не особенно разбираюсь в магии, хотя в свое время мне все же удалось научиться кое-каким фокусам. Например, я могу пройти мимо врага так, что он меня не увидит.$B$BТолько вот летучие мыши – вампиры не привыкли полагаться на зрение. Они за милю слышат шорох моей одежды, да и Перси – не самое тихое создание.$B$BНе $gмог:могла; бы ты расчистить от них путь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34806, 'ruRU', 'Проредить грядки', 'Отомстите стручлингам.', 'Райан лежит у стены пещеры. Несчастный истек кровью – тело с головы до ног искусано мелкими, острыми зубками.$B$BСтручлинги представляют нешуточную угрозу вашему гарнизону.$B$BПора брать в руки секатор.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34807, 'ruRU', 'Событие: Златогрив Свежеватель', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34808, 'ruRU', 'Опять ленивые батраки', 'Вдохновите $1oa |4ленивого батрака:ленивых батраков:ленивых батраков;', 'Cейчас нам представилась редкая возможность нанести клану Песни Войны удар в самое сердце. Мы всецело полагаемся на твою мудрость и авторитет.$B$BСейчас необходимо сделать важный выбор – должны ли мы построить стойла или танковую мастерскую. Твое решение изменит весь ход кампании против клана Песни Войны.$B$BСтроительством будет руководить Тазз\'рил. Поможешь ему?$B$BПохоже, ему никак не удается заставить батраков работать.', '', 'Вот враг нашей Победы! Он мешает победе Орды! Как следует вдохновите его!', 'Ленивый батрак', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34809, 'ruRU', 'Урок минералогии', 'Добудьте $oa |4земляное ядро:земляных ядра:земляных ядер;.', '<Газмольф указывает рукой на стоящую рядом здоровенную машину>$b$bЯ построил эту машину, чтобы разделять элементиевые минералы на основные элементы. Видишь ли, в чем дело: ценность может иметь не только зарытое в землю сокровище, но и сама земля!$b$bВот взять, например, элементалей земли, что обитают под нами – ведь в каждом, в каждом есть земляное ядро, богатое ценными металлами!$b$bЭти элементали сделают нас богачами! Собери несколько земляных ядер и засунь их в Злат-о-матик 9000, а я поделюсь с тобой наваром!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34810, 'ruRU', 'Газмольф Прохлаждайс и поход против Верховного Молота', 'Поговорите с Газмольфом Прохлаждайсом.', 'Я прибыла в Награнд, чтобы найти работников для Археологического общества Хитрой Шестеренки. Мы – археологическое подразделение Картеля Хитрой Шестеренки.$b$bЗанимаемся поиском артефактов, реликвий, антиквариата и прочих подобных штуковин, какие только можно найти в Награнде! На данный момент нам нужны геодезисты, землекопы, искатели приключений... в общем, все нужны!$b$bТак что если ты не прочь запачкать руки и подзаработать, поговори с Газмольфом Прохлаждайсом в ущелье Каменных Скал. Этот гоблин руководит всей нашей экспедицией!', '', '', '', '', '', 'Поговорите с Газмольфом Прохлаждайсом.', 25549);
INSERT INTO `quest_template_locale` VALUES (34811, 'ruRU', 'Хороших работников трудно найти', 'Добудьте $1oa |4древность:древности:древностей; Награнда.', 'Землекопы объявили забастовку!$b$bБригадир Тазвикс и его подчиненные решили, что смогут выбить из Археологического общества Хитрой Шестеренки прибавку к жалованию, если откажутся выходить на работу.$b$bМне нужен этот, как его... штрейкбрехер! Короче, тот, кто вправит им мозги, делая работу, которую сами они делать отказались!$b$bСпустись в ущелье и накопай там всяких древностей – а я тебе за это заплачу из жалования этих лодырей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34812, 'ruRU', 'Орда: строим стойла', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34813, 'ruRU', 'Орда: строим мастерскую', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34814, 'ruRU', 'Новые знакомства', 'Следуйте за Верховным магом Кадгаром и поговорите с магистром Креласом в Зангарре.', 'Всегда приятно встретить $gтого:ту;, кто проявляет подлинный интерес к магическим искусствам. Нынче эта большая редкость, доложу я тебе!$B$BК сожалению, мне сейчас нужно срочно встретиться с Корданой по важному делу – но тебе повезло! Один из моих хороших друзей в Кирин-Торе согласился помочь подключить твое волшебное святилище к сети силовых линий.$B$BОн уже ждет в моей башне. Давай-ка, не теряя времени, туда и отправимся – я вас представлю друг другу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34815, 'ruRU', 'Новые знакомства', 'Следуйте за Верховным магом Кадгаром и поговорите с магистром Сереной в Зангарре.', 'Всегда приятно встретить $gтого:ту;, кто проявляет подлинный интерес к магическим искусствам. Нынче эта большая редкость, доложу я тебе!$B$BК сожалению, мне сейчас нужно срочно встретиться с Корданой по важному делу – но тебе повезло! Одна из моих хороших подруг в Кирин-Торе согласилась помочь подключить твое волшебное святилище к сети силовых линий.$B$BОна уже ждет в моей башне. Давай-ка, не теряя времени, туда и отправимся – я вас представлю друг другу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34817, 'ruRU', 'Апокалипсис у алтаря', '', 'Освободите пленников на алтаре.$b$b[NOTE: THIS QUEST WILL GET SIGNIFICANT REVAMP ONCE WE GET THE ALTAR IN]', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34818, 'ruRU', 'Его имя – Лантрезор Клинок', 'Найдите Лантрезора Клинка в Галлвалоре.', 'Когда орки клана Песни Войны ограбили твой караван, они унесли чертежи в деревню клана Пылающего Клинка. Без них я не смогу достроить это здание.$B$BЯ слышал про одного юного мечника, которого много лет назад изгнали из клана Пылающего Клинка. Его зовут Лантрезор Клинок.$B$BНедавно наши разведчики доложили, что он вернулся в Галлвалор, чтобы бросить вызов старшим мастерам клинка. Но его схватили и заковали в цепи.$B$BЕсли он еще жив – может быть, он поможет тебе вернуть чертежи?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34819, 'ruRU', 'Витаминизация', 'Соберите $1oa |4награндскую вишню:награндские вишни:награндских вишен;.', 'О нет! Видать, они вегетарианцы.$B$BВыходит, этим элеккам нужны фрукты – много фруктов. Тут под деревьями должно валяться множество вишневых ягод.$B$BМожет, наберешь немного, а?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34820, 'ruRU', 'Пропавшие дровосеки', 'Выясните, что случилось с Шелли и пропавшими дровосеками.', 'Шелли вместе со своей командой отправилась в Сумрачную рощу, и до сих пор от них ни слуху ни духу.$B$BПрошло уже несколько дней... надеюсь, с ними не произошло ничего ужасного.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34821, 'ruRU', 'Призыв Кадгара', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34822, 'ruRU', 'То, что нам нужно', 'Соберите $1oa |4ящик:ящика:ящиков; вещей с боевого корабля.', 'Я слышал, на пути из Танаана ты $gугнал:угнала; корабль и $gразбил:разбила; его.$b$bКак любил говорить мой папаша: \"Что человеку хлам, то гоблину сокровище\".$b$bСтупай на побережье к западу от гарнизона и посмотри, не осталось ли там каких материалов, которые еще можно спасти. Только ты это... осторожней там. Говорят, в тех краях промышляют огры-налетчики.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34823, 'ruRU', 'Огроны еще существуют?', 'Убейте Груга.', 'Командир, наши союзники, клан Северного Волка, доложили, что к западу от нас находится гарнизон огров из клана Камнерогов, и возглавляет эту банду огрон.$b$bЯ много слышал об огронах, но никогда не видел. Это ужасные создания из стародавних темных времен. Говорят, основная их масса была уничтожена при создании первой Орды. Недостаток ума они с лихвой компенсируют свирепостью, силой и алчностью!$b$bЛучше бы нам уничтожить эту тварь как можно скорее.', '', 'Поработитель', 'Груг', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34824, 'ruRU', 'То, что у нас есть', 'Прикажите Скеггиту заставить батраков работать, проверьте содержимое гарнизонного склада и найдите старшего батрака.', 'Для строительства любой крепости нужны три важные вещи.$b$bВо-первых, это рабочие руки! Найди Скеггита и удостоверься, что наши батраки вернулись к работе.$b$bВо-вторых, это строительные материалы. Я велел батракам относить ресурсы в гарнизонный склад, пока тебя не будет. Загляни в него и посмотри, что там накопилось.$b$bИ в-третьих – грубая сила с головой на плечах! Здания в гарнизоне строятся неспешно, но, думаю, постройку самого первого из них можно ускорить, если привлечь к этому делу недавно назначенного Скеггитом старшего батрака. Найди его и скажи, что ты от меня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34825, 'ruRU', 'Событие: Груук', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34826, 'ruRU', 'Друг моего врага', 'Убейте $1oa |4орка:орков:орков; клана Пылающего Клинка в Галлвалоре.', 'Галлвалор – это родина клана Пылающего Клинка. Клан Песни Войны позволил мастерам клинка остаться в Награнде.$B$BМы – яростные бойцы, но если Пылающий Клинок нападет на нас, нам не победить. Поэтому весьма разумно будет нанести удар первыми.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34827, 'ruRU', 'Последний жрец Когтя', 'Выпейте эликсир теней у хижины Ишааля на Тенистой поляне.', 'Жрецы Когтя в тайне живут среди нас, храня обряды возвращения короля Воронов.$B$BВ воззвании приверженцев, которое ты $gполучил:получила; в Скеттисе, упоминаются двое из них, что живут на Тенистой поляне к северу отсюда. Орки уже заняли эту область, а лучевое оружие приверженцев превратило Гнездовье Акраз в дымящийся кратер.$B$BКак видишь, мой народ окружен врагами со всех сторон.$B$BЖрец Когтя Ишааль жив, но он скрывается в мире теней. Выпей этот эликсир у его хижины, чтобы заглянуть в мир теней и связаться с ним.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34828, 'ruRU', 'Сфера Ишааля', 'Заберите сферу Ишааля из лагеря Тернистого Шрама.', 'Приверженцы пришли за мной, но я укрылся от них в тенях и наблюдал, как они грабят мою хижину.$B$BЗатем появились орки из клана Изувеченной Длани и безжалостно выпотрошили их, как дичь. Похоже, нынче все охотятся за нами.$B$BОдин из этих разбойников унес мою гадальную сферу. Без нее я буду Искару бесполезен.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34829, 'ruRU', 'Новые соседи', 'Убейте $1oa |4орка:орков:орков; клана Изувеченной Длани в лагере Тернистого Шрама.', 'Клан Изувеченной Длани состоит из орков, которых не признает ни один другой клан. Эти жестокие воины калечат себя во имя единения друг с другом или, возможно, потому что им просто нравится испытывать боль.$B$BТак или иначе, важно то, что они расширяют границы своей территории, убивая всех на своем пути. $B$BС ними нужно разобраться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34830, 'ruRU', 'За Завесой', 'Выпейте концентрированный эликсир теней в хижине Зеллека в Гнездовье Акраз.', 'Прежде чем сюда нагрянули орки, Гнездовье Акраз сжег луч света Небесного Пути.$B$B<Ишааль заглядывает в сферу, и его взгляд затуманивается.>$B$BПохоже, что на самом деле у них была другая цель. Зеллек все еще там, он прячется в мире теней.$B$BИ... и там есть кто-то еще. Орк-убийца, который воспользовался моей сферой.$B$BВозьми это. Выпей в Гнездовье Акраз и найди Зеллека.$B$BО, и будь $gосторожен:осторожна;. Это зелье немного сильнее предыдущего. Ты увидишь...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34831, 'ruRU', 'Странный гриб', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34833, 'ruRU', 'Древний срез', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34834, 'ruRU', 'Общий комментарий', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34835, 'ruRU', 'Сбор энергии', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34836, 'ruRU', 'Лунные цветы', 'Соберите $1oa |4лунный цветок:лунных цветка:лунных цветков;.', 'Как бы я хотел обнять Кат\'лу!$B$BНи луна, ни звезды не сравнятся с ее красотой.$B$BУвы, я лишь простой свинопас.$B$BХоть бы избавиться от этой жалкой работы на денек и нарвать для Кат\'лы лунных цветов!$B$BЯ не посмею признаться ей в своих чувствах, если не принесу подарок, достойный ее красоты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34837, 'ruRU', 'К Гордунни', 'Найдите Моркета Воющего Меча рядом с крепостью Гордал.', 'У нас пока хватает йовита, но в шахте его мало, и наших запасов хватит ненадолго. К югу отсюда есть гора с отличными йовитовыми жилами, но есть одна проблема – огры!$b$bНа вершине живет клан Гордунни, и они начали торговать йовитом с Железной Ордой.$b$bНам надо отправиться туда и захватить месторождение.$b$bЯ упакую припасы и встречу тебя на юге, рядом с их крепостью.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34838, 'ruRU', 'Яйцо Икки', 'Помогите Икки вылупиться из яйца калири на Тенистой поляне.', '<Это единственное яйцо чудом уцелело после нашествия опустошителей.$B$BК нему аккуратно привязан небольшой ярлычок с надписью \"Икки\".>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34839, 'ruRU', 'Событие: Ског', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34840, 'ruRU', 'Бомбардировка', 'Пусть артиллерия ударит по камнеметателям клана Гордунни в крепости Гордал.', 'В крепость клана Гордунни ведет только одна тропа, и ее хорошо охраняют.$b$bК счастью, они не ожидают, что внутрь попытаемся проникнуть только мы двое.$b$bЭто отличная возможность прорвать их оборону и хороший шанс для наших артиллеристов попрактиковаться в стрельбе.$b$bВозьми эти дымовые гранаты – с их помощью ты сможешь наводить артиллерию на вражеские катапульты по пути наверх.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34841, 'ruRU', 'Сокровище: замороженные припасы', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34843, 'ruRU', 'Событие: Хладноклык', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34847, 'ruRU', 'Запретная любовь', 'Найдите Крал\'за.', 'Мой сын Крал\'за упрям, как талбук.$B$BКогда мы ушли из клана Призрачной Луны, он отказался разорвать отношения с девушкой-орком из этого клана.$B$BЯ запретила ему с ней видеться, но сегодня он сбежал и до сих пор не вернулся.$B$BЯ не доверяю Дол\'мак – как и ее сородичи, она слишком увязла в темной магии.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34849, 'ruRU', 'Собственно, клинок', 'Отнимите клинок Лантрезора у инструктора Лухка.', 'Когда меня заковали в цепи, инструктор клана Пылающего Клинка по имени Лухк Остроглазый забрал мой клинок. Он достопочтенный орк, пусть его методы обучения и не очень эффективны.$B$BЯ хочу вернуть свой клинок, |3-6($c). Тогда я смогу вернуть себе и свободу.', '', 'Клинок Лантрезора находится у этого наставника мастеров клинка.', 'Инструктор Лухк', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34850, 'ruRU', 'Главное – честь', 'Отыщите знамя мастера клинка в сундуке клана Пылающего Клинка.', 'Сам клинок – не единственный ценный предмет, которым владеет каждый мастер клинка.$B$BПройдя последние испытания в Пещерах Мастеров, мастер клинка получает знамя Пылающего Клинка. $B$BКогда же моя просьба вернуть мне законное место в клане была отвергнута, меня лишили и этой чести.$B$BСейчас мое знамя, несомненно, хранится где-то в Галлвалоре. Если знамя еще не сожгли, то, наверно, отдадут его какому-нибудь начинающему мастеру клинка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34851, 'ruRU', 'Событие: Груук', 'Уничтожьте $1oa |4кладку:кладки:кладок; яиц горенов, $2oa |4железоеда:железоедов:железоедов; Ледяной Кузни и праматерь Риг\'ак.', 'Горены опасны для нас – их много, а наш шаман слеп и обессилен.$b$bКонечно, век этих чудовищ короток, но они очень быстро размножаются и растут.$b$BЧтобы справиться с горенами, нам нужно найти их матку, убить ее и уничтожить яйца. Так мы сможем на какое-то время обезопасить себя. Осмотри норы у врат Кузни, а я сделаю так, чтобы горены не напали на след Дрек\'тара.', '', '', '', '', '', 'Вернитесь к Дреке, к Вратам Кузни, что на Хребте Ледяного Огня.', 19865);
INSERT INTO `quest_template_locale` VALUES (34855, 'ruRU', 'Пробиться внутрь', 'Убейте визирей Воргорша, Зулморка и Кромауга.', 'Чтобы взять под контроль крепость, нужно убить лорда-чародея Моркурка. Но вряд ли разумно сразу идти за его головой. $B$BТрое его подручных – Воргорш, Зулморк и Кромауг – могущественные маги, и они беззаветно преданы Моркурку. $B$BЕсли мы нападем на лорда-чародея, они бросятся ему на выручку. Давай уничтожим их, чтобы облегчить себе задачу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34856, 'ruRU', 'Gok Tracking Quest', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34857, 'ruRU', 'Поиск флага: Орков выгнали из пещеры', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34858, 'ruRU', 'Возвращение ценностей', 'Заберите $1oa |4\"Зубочистку\":\"Зубочистки\":\"Зубочисток\"; Гордунни у крушителей или рассекателей из клана Гордунни в крепости Гордал.', 'Железная Орда подарила клану Гордунни копии моих клинков. Но как они ими пользуются? Ковыряют в зубах!$b$bНу да, это ведь просто дешевые подделки, но модели-то мои, и мне противно даже думать о том, что сейчас они в лапах огров!$b$bРаз уж мы здесь, то сделай одолжение – отними у них эти клинки!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34859, 'ruRU', 'Событие: Но\'лош', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34860, 'ruRU', 'Возвращение припасов', 'Добудьте $1oa |4комплект:комплекта:комплектов; груза Железной Орды.', 'Похоже, мы прибыли вовремя! $b$bГордунни зачаровывают оружие для Железной Орды – и, кажется, они еще не забрали последнюю поставку.$b$bНам это оружие нужнее! Пойдем отобьем их ящики со снаряжением. У меня с собой сигнальные ракеты, используем их, чтобы кто-нибудь прилетел и забрал нас, когда поставка будет у нас.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34861, 'ruRU', 'Нам нужна армия', 'Поговорите с воеводой Зогом.', 'Новый вождь решил отрядить тебе в помощь воеводу Зога. Он возьмет на себя контроль над локальными операциями. О, Зог! Я слыхал, что это именно он командовал объединенной армией Альянса и Орды в битве с силитидами у Врат Ан\'Киража.$b$bТогда он, кажись, был генералом.$b$bВ общем, сообщи ему, что казармы уже построены. Он наверняка найдет им достойное применение.$b$bЗога ты найдешь в ратуше.', '', '', '', '', '', 'Поговорите с воеводой Зогом в своем гарнизоне на Хребте Ледяного Огня.', 25549);
INSERT INTO `quest_template_locale` VALUES (34862, 'ruRU', 'Событие: Зажечь жаровни', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34865, 'ruRU', 'Событие: Ског', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34866, 'ruRU', 'Встреча в пещере', 'Встретьтесь с Лантрезором Клинком в Пещере Мастеров.', 'Пора, |3-6($c). Тебе пора вернуть свои чертежи.$B$BИ нам обоим пора встретиться с мастерами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34867, 'ruRU', 'Тайны Горгронда', 'Встретьтесь с Дуротаном в Горгронде.', 'Командир, мои воины займут и будут удерживать ущелье, но я не собираюсь бить баклуши, в то время как противник готовится к следующей атаке.$b$bЯ хочу расправиться с Железной Ордой прямо в их логове на Черной горе, а для этого нам нужно отправиться туда, куда орки не любят соваться.$b$bВ Горгронд.$b$bЭто дикие земли, кишащие великанами и чудищами всех мастей.$b$bХватит ли тебе мужества пойти со мной туда и нанести удар в самое сердце Железной Орды?', '', '', '', '', '', 'Встретьтесь с Дуротаном в Горгронде.', 25549);
INSERT INTO `quest_template_locale` VALUES (34868, 'ruRU', 'Испытание мастеров', 'Выдержите испытание клана Пылающего Клинка и заберите чертежи.', 'Самое время бросить вызов мастерам клана Пылающего Клинка.$B$BСтупай вглубь пещеры. Там увидишь площадку для боя. Мастера будут наблюдать за тобой со своих мест сверху.$B$BВытащи из земли клинок в центре площадки – этим ты покажешь свою готовность к испытанию. Мой клан превыше всего ценит честь и примет твой вызов на испытание боем.$B$BЕсли выдержишь его, тебе позволят забрать чертежи и убраться восвояси с головой на плечах. В противном случае с головой придется расстаться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34869, 'ruRU', 'По вкусу – как курица', 'Добудьте $1oa |4кусок:куска:кусков; сырого мяса ветруха в Награнде.', 'Есть свободная минутка, $gприятель:красотка;? У меня тут проблема – с элекка размером!$B$BКое-кто мне тут продал парочку этих красавцев, но они, похоже, захворали. Я с ними ношусь, как с тухлым яйцом, но что ни делаю – толку ноль.$B$BМне кажется, они просто очень оголодали. Я где-то слышал, что элекки очень любят сырое мясо ветрухов. Бр-р! Отвратительно.$B$BНо, может быть, пока ты будешь заниматься своими делами, заодно раздобудешь для меня немного птичьего мяса?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34870, 'ruRU', 'Повелитель Гордунни', 'Победите лорда-чародея Моркурка в крепости Гордал и заберите \"Ярость Кузни\".', 'Лорд-чародей Моркурк – это предводитель клана Гордунни. Это он заключил договор о торговле с Железной Ордой, и, хуже того, мой бывший хозяин отдал ему мою лучшую палицу!$b$bЕе нужно вернуть! Ну, то есть... Нам нужно его убить, чтобы получить йовит для выплавки оружия!$b$bМоркурк – опытный маг, так что приготовься. Вот возьми ракетный ускоритель и используй его, когда нужно, например, быстро уклониться.$b$bКроме того, если найдешь палицу – забирай, она мне нужна.', '', '', 'Лорд-чародей Моркурк', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34871, 'ruRU', 'Возвращение припасов – отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34872, 'ruRU', 'Возвращение ценностей – отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34873, 'ruRU', 'Пробиться внутрь – отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34874, 'ruRU', 'Дальнейшие шаги', 'Поговорите с магистром Креласом в Гордости Вол\'джина.', 'Шустро ты со всем $gуправился:управилась;!$B$BТеперь у нас есть все необходимое для создания свитка. Твое волшебное святилище уже совсем скоро будет буквально дышать магической энергией.$B$BСейчас я телепортируюсь назад в Гордость Вол\'джина, чтобы смешать реагенты и собрать твои войска. Там и встретимся.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34875, 'ruRU', 'Дальнейшие шаги', 'Поговорите с магистром Сереной в форте Ринн.', 'Мы справились! Теперь у нас есть все необходимые реагенты для создания свитка! Уже скоро о твоем волшебном святилище заговорит весь Дренор.$B$BЯ возвращаюсь в форт Ринн, чтобы закончить работу и собрать твои войска. Встретимся там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34876, 'ruRU', 'Пропавшая любовь Лоолы', 'Поищите мужа старушки Лоолы на Грязном болоте.', 'О, это было ужасно.$b$bМы с мужем ловили рыбу на болоте. Я заснула, а когда проснулась, обнаружила, что муж превратился в жабу!$b$bУверена, во всем виноваты орки Призрачной Луны, о которых столько говорят.$b$bОн прыгнул в мутную воду раньше, чем я успела его поймать.$b$bТы поможешь мне найти моего любимого, |3-6($c)?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34877, 'ruRU', 'Уничтожение подкреплений', 'Уничтожьте портал в крепость Верховного Молота.', 'В ходе расследования мне удалось обнаружить постоянно действующий магический портал, ведущий отсюда в логово клана Верховного Молота. Он охраняется, но если немного расчистить перед ним место, то будет совсем несложно вывести его из строя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34878, 'ruRU', 'Подступы к крепости', 'Поговорите с магистром Креласом у входа в крепость Гордал.', 'Мы воодушевили твои войска, и свиток тоже готов.$B$BПереходим ко второй части плана – похищению кристалла-источника из хорошо защищенной крепости огров.$B$BОставим свиток на потом, чтобы вызвать подкрепление в ходе боя с Повелителем ведьм клана Гордунни. Встретимся у подножия крепости Гордал и заберем то, что более-менее по праву принадлежит тебе!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34879, 'ruRU', 'Взлом и проникновение', 'Помогите магистру Креласу уничтожить $1oa |4камнеметатель:камнеметателя:камнеметателей; клана Гордунни.', 'Лорд-чародей Моркурк – не дурак.$B$BВ холмах, на подступах к крепости, он расставил катапульты.$B$BНо это не важно – я знаю, как с ними разобраться.$B$BУничтожь огров, которые их охраняют, а затем отметь их позиции для меня. Я приготовлю заклинание вихря, которое сметет их с лица земли.$B$BСразу после этого встречаемся у ворот.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34881, 'ruRU', 'Земля, ветер, огонь... и вода', 'Соберите по 4 экземпляра всех видов субстанции Жизни на Плато Стихий. ', 'Плато Стихий стало нестабильным, и поэтому должен начаться цикл возрождения.$b$bВ теле элементаля постепенно накапливается скверна – это часть нашего жизненного цикла.$b$bЕсли ее уже много, элементаль становится непредсказуемым и нестабильным, а в некоторых случаях – взрывоопасным.$b$bДля возрождения необходимо не только тело элементаля, но и чистая субстанция Жизни, которую можно найти на вершине Плато Стихий.$b$bПринеси эту субстанцию мне, и тогда мы начнем возрождение.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34882, 'ruRU', 'Клинки во тьме', 'Убейте Малрока Тернистого Шрама в Гнездовье Акраз.', 'Орки захватили сферу Ишааля, так? Ясно тогда, почему незадолго до тебя в этот мир попал один жуткий тип.$B$BНе всем удается перенести переход так... изящно, как тебе. Этот болван все еще цепляется за свой разум, бормочет всякую ерунду.$B$BСкоро сфера снова притянет его и, вероятно, отправит в Гнездовье Терокк.$B$BНадо убить его сейчас, пока он еще не пришел в себя.', '', 'Путешествие в мир теней лишило его рассудка. По-прежнему опасен.', 'Малрок Тернистый Шрам', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34883, 'ruRU', 'Пир теней', 'Соберите $1oa ед. теневой пыли.', 'Много араккоа погибло в Гнездовье Акраз. На первый взгляд здесь царит спокойствие. Кажется, что здесь никого нет.$B$BОднако в промежутке между мирами смерть нельзя не заметить.$B$BС другой стороны, сюда иногда случайно попадает эссенция жизни – и становится добычей обитающих здесь тварей.$B$BУбей создания тьмы и собери с их трупов мелкую пыль. Мне нужно много такой пыли, чтобы провести обряд Короля воронов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34884, 'ruRU', 'Говорящий с калири', 'Заберите у Скиззика старый молот.', 'На Тенистой поляне живет кое-кто крайне важный. Этот тихоня занимается очень опасным ремеслом – дрессирует калири невероятных размеров.$B$BОн как-то говорил, что калири может налететь на рилака и сбить его на землю, хотя я в это не поверю, пока не увижу своими глазами.$B$BСкиззик хранит для меня одну очень ценную вещь. Попытайся разыскать его и вернуть в Гнездовье Терокк. Или хотя бы найти молот, который я ему доверил.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34885, 'ruRU', 'Мать шипов', 'Убейте $1oa |4опустошителя-темноспина:опустошителей-темноспинов:опустошителей-темноспинов; и мать шипастых темноспинов.', '<Отодвинув безжизненную руку Скиззика, вы видите нацарапанные на глине буквы:$B$Bм а т ь$B$Bш и п а с т ы х$B$BОпустошители, которых привели орки из клана Изувеченной Длани, заполнили авиарий и стремительно размножаются. Если им не помешать, они за несколько дней захватят всю область, включая Гнездовье Терокк.>', '', 'Убей ее и ее опустошителей.', 'Мать шипастых темноспинов', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34886, 'ruRU', 'Птичка-невеличка', 'Соберите $1oa |4личинку опустошителя:личинки опустошителей:личинок опустошителей; на Тенистой поляне.', '<Икки снова пищит, затем принимается клевать свою лапу.$B$BОглядевшись, вы замечаете маленьких личинок опустошителей, ползущих по траве.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34887, 'ruRU', 'Пока мы здесь', 'Найдите $1oa |4нитку:нитки:ниток; рунических четок Гордунни.', 'Ох уж эта гордыня огров.$B$BНи к чему хорошему она не приводит.$B$BЧтобы придать своим прислужникам волшебных сил, Моркурк раздал им зачарованные браслеты. Мы могли бы распылить эти браслеты, превратив их в реагенты – для твоего волшебного святилища они наверняка придутся весьма кстати. Ну, что скажешь? Соберем их заодно?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34888, 'ruRU', 'Нечестивые визири', 'Убейте визирей Воргорша, Зулморка и Кромауга.', 'Нам необходимо устранить лорда-чародея Моркурка. Но вряд ли нужно сразу идти за его головой.$B$BТрое его подручных – Воргорш, Зулморк и Кромауг – могущественные маги и беззаветно преданы Моркурку.$B$BЕсли мы нападем на лорда-чародея, они бросятся ему на выручку. Давай сначала уничтожим их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34889, 'ruRU', 'Сферы могущества', 'Уничтожьте $1oa |4астрального стража:астральных стража:астральных стражей;.', 'Боюсь, что у нас есть небольшая проблема, с которой нужно разобраться.$B$BВ крепости Гордал повелитель ведьм Моркурк разместил астральных стражей, препятствующих любой массовой телепортации, – и, значит, от нашего свитка никакой пользы.$B$BК счастью, ни один огр даже не подумает, что в их крепость может проникнуть парочка искателей приключений.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34890, 'ruRU', 'Последний шаг', 'Одержите победу над лордом-чародеем Моркурком и заберите чародейский нексус из крепости Гордал.', 'Ударим огнем по огню!$B$BМы загнали Моркурка в угол. Он остался без защиты. Поэтому доставай свиток...$B$B...и наслаждайся фейерверком!', '', '', 'Лорд-чародей Моркурк', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34891, 'ruRU', 'Общение на языке стихий', 'Найдите четыре столпа стихий.', 'Многие шаманы добивались расположения духов Трона Стихий.$b$bВедь связь со стихиями позволяет шаману не только узнать волю стихий Дренора, но и получить доступ к могучему источнику силы.$b$bЕсли ты хочешь выяснить, что стало причиной исчезновения Гордауга, нужно добиться успеха там, где другие потерпели поражение. Тебе нужно провести ритуал единения.$b$bНо сначала ты $gдолжен:должна; подготовиться. Ступай на плато и настройся на одну волну со столпами стихий.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34893, 'ruRU', 'Стражи Плато', 'Уничтожьте оскверненных стражей на Плато Стихий.', 'Плато Стихий – это практически святилище элементалей Награнда.$b$bВеличайшими из элементалей являются стражи – могучие духи, охраняющие эти края.$b$bНарушение природного равновесия сделало стражей нестабильными, а от них эта скверна передалась и меньшим элементалям.$b$bЕсли мы хотим восстановить равновесие на плато, нам нужно уничтожить стражей. Тогда начнется цикл возрождения.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34894, 'ruRU', 'Редкий цветок', 'Найдите углецвет на Плато Стихий.', 'Много лет назад у меня была подруга по имени Дахака. Мы были вместе недолго – ее отняли у меня.$b$bЯ долго прожил на этом свете, но никогда мне не было так больно, как в тот день. Я был молод, и горе мое было столь велико, что земля содрогалась под моими ногами. Я похоронил ее на этом утесе.$b$bЗдесь умру и я, но сначала окажи мне услугу.$b$bВ пещере на этом плато, залитой огненной лавой, растет редкий цветок. Дахака очень любила такие цветы.$b$bЯ бы хотел перед смертью еще раз положить их на ее могилу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34895, 'ruRU', 'Бомбометание – отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34896, 'ruRU', 'Слежка: скрытный рангари', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34897, 'ruRU', 'Среди рангари', 'Отыщите $1oa |4скрывшегося:скрывшихся:скрывшихся; рангари.', 'Ты весьма $gнаблюдательный:наблюдательная:c;, |3-6($c).$b$bВ Ночнотопи скрываются многие рангари вроде меня.$b$bМне нужно получить рапорты от каждого из них, чтобы удостовериться в том, что там безопасно.$b$bМожет быть, ты мне поможешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34898, 'ruRU', 'Икки', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34899, 'ruRU', 'Нелегкий выбор', 'Подойдите к чертежному столу и выберите постройку – стойла или танковую мастерскую.', 'Мы готовы начать строительство. Тебе нужно просто сделать выбор.$B$BПосмотри на чертежи, они на чертежном столе.$B$BЗатем скажи мне, что будем строить – стойла или танковую мастерскую.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34900, 'ruRU', 'Новые детки', 'Приманите $1oa |4лугопотама-мягкоступа:лугопотама-мягкоступа:лугопотамов-мягкоступов;.', 'Уже лучше, но все равно что-то с ними не так. Я уже практически готов бросить свою затею, $n.$B$BЯ же ведь могу звать тебя просто $n? Отлично.$B$BСлушай, кажется, теперь до меня дошло, в чем тут дело. Теперь я знаю, что не так.$B$BОни скучают по своим детенышам.$B$BНу конечно! Когда они впервые оказались здесь, эти... эти подлецы-охотники, что бросили их, сказали, что детенышей они с собой не взяли.$B$BЗначит, если мы хотим избавить их от тоски и безутешного горя... (тихонько) и хорошенько подзаработать... (в полный голос) нужно привести им новых детенышей!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34904, 'ruRU', 'Видение портала', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34905, 'ruRU', 'Placeholder Quest', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34906, 'ruRU', 'Призыв Креласа', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34907, 'ruRU', 'Событие/сокровище: косяк рыбы/гигантский моллюск', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34908, 'ruRU', 'Подступы к крепости', 'Поговорите с магистром Сереной у входа в крепость Гордал.', 'Твои войска наготове, и свиток начертан.$B$BПереходим ко второй части плана – похищению кристалла-источника из хорошо защищенной крепости огров.$B$BОставим свиток на потом, чтобы вызвать подкрепление в ходе боя с Повелителем ведьм клана Гордунни. Давай встретимся у подножия крепости Гордал и оттуда уже направимся в крепость.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34909, 'ruRU', 'Пока мы тут', 'Найдите $1oa |4:рунические четки:рунических четок:рунических четок; Гордунни.', 'Имперские огры известны своей холодной расчетливостью.$B$BК счастью для нас, их расчеты редко оказываются верными.$B$BМоркурк использовал специальные зачарованные браслеты, чтобы наделить своих прислужников силой тайной магии.$B$BПоскольку мы все равно собираемся избавиться от них, можно попутно добыть кое-какие реагенты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34910, 'ruRU', 'Нечестивые визири', 'Убейте визирей Воргорша, Зулморка и Кромауга.', 'Мы не можем просто зайти туда, убить лорда-чародея Моркурка и скрыться.$B$BТрое его подручных – Воргорш, Зулморк и Кромауг – могущественные маги и беззаветно преданы Моркурку.$B$BЕсли мы нападем на лорда-чародея, они бросятся ему на выручку и одолеют нас. Сначала нужно разобраться с его подручными.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34911, 'ruRU', 'Сферы могущества', 'Уничтожьте $1oa |4астрального стража:астральных стража:астральных стражей;.', 'Боюсь, у нас тут возникла небольшая проблемка.$B$BМоркурк расставил в крепости Гордал мощные обереги, которые предотвратят любую попытку массового призыва. Учитывая специфику нашего плана, это совсем не здорово.$B$BК счастью, никакому огру даже в голову не придет, что их крепость кто-то рискнет атаковать столь малыми силами, так что мы сможем без особого труда туда пробраться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34912, 'ruRU', 'Последний шаг', 'Одержите победу над лордом-чародеем Моркурком и заберите чародейский нексус из крепости Гордал.', 'Мы загнали Моркурка в угол. Теперь он полностью в наших руках. Используй свиток, когда вступишь в бой с Моркурком...$B$B...и наблюдай, как его сметает лавина твоих бойцов.', '', '', 'Лорд-чародей Моркурк', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34913, 'ruRU', 'Взлом и проникновение', 'Помогите магистру Серене уничтожить $1oa |4камнеметатель:камнеметателя:камнеметателей; клана Гордунни.', 'Лорд-чародей Моркурк приказал расставить катапульты на подходах к крепости.$B$BНо с ними у нас проблем не будет.$B$BУничтожь огров рядом с катапультами и пометь их позиции. Остальное сделает мое заклинание вихря.$B$BУничтожим катапульты, а потом встретимся у ворот крепости.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34914, 'ruRU', 'Попутная цель: Телаар', 'Поговорите с темной охотницей Каджассой в Телааре.', 'Пришло сообщение, что клан Песни Войны захватил анклав дренеев в Телааре.$B$BМой отряд темных охотников отправился туда на разведку.$B$BЕго возглавляет Каджасса. Поговоришь с ней?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34915, 'ruRU', 'Я помогу их пришлепнуть', 'Убейте $1oa |4орка:орков:орков; клана Песни Войны в Телааре.', 'Песня Войны пришла и убила дренеев-следопытов. Не хочет, чтобы они тут были.$B$BМы с тобой, командир, их всех перебьем.$B$BТы их отвлечешь, а мой лоа их пришлепнет. Вот увидишь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34916, 'ruRU', 'Благословение Самеди', 'Поднесите фетиш Самеди к трупам темных охотников.', 'Три моих охотника пришли сюда со мной. Песня Войны их убила.$B$BНужно помочь их душам двинуться дальше. Если вдруг найдешь их раньше меня, поднеси к ним вот это.$B$BИ их души отправятся к Самеди, Замогильному лоа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34917, 'ruRU', 'Поднять щиты!', 'Активируйте четыре телаарских кристалла.', 'Предводительница стаи Каргора пытается накрыть Телаар силовым щитом. Если ей это удастся, клан Песни Войны получит неприступный оплот.$B$BНо пока оркам удалось только запустить подготовительную процедуру щита. Из-за этого возник один неприятный эффект – теперь предводительница стаи и ее шаман находятся под защитой главного кристалла. $B$BАктивируй кристаллы по периметру Телаара. Это заставит щит включиться полностью.$B$BТогда Каргора останется без прикрытия.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34918, 'ruRU', 'Опустить щиты!', 'Убейте предводительницу стаи Каргору и уничтожьте каронитовый щит.', 'Пришел твой час, командир. Предводительница стаи Каргора и каронитовый щит остались без защиты.$B$BМы должны убить ее и уничтожить кристалл щита.', '', 'Не дайте ей превратить Телаар в неприступную базу клана Песни Войны.', 'Предводительница стаи Каргора', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34920, 'ruRU', 'Уничтожение стража', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34921, 'ruRU', 'Культ Говорящих с воронами', 'Положите перо Анзу в жертвенную чашу в Ущелье Криволеса', 'Эти изгои – не единственные проклятые араккоа, которые удерживают позиции в Араке.\n\nПоявился некий любопытный культ, почитающий Ка\'алу, мою избранницу и хранительницу моей стаи. Они довольно... странные.\n\nИ все же изгоям понадобится их помощь. Без крыльев этих воронов Искару не добраться до пиков.\n\nВозьми это перо и положи его в жертвенную чашу к югу отсюда. Так называемые \"Говорящие с воронами\" должны это заметить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34922, 'ruRU', 'Слова Прародительницы воронов', 'Найдите $1oa |4обрывок:обрывка:обрывков; свитка Говорящих с воронами.', 'Мы готовились исполнить ритуал призыва и приблизить возвращение Прародительницы воронов. У каждого из нас был свой фрагмент священного текста, и мы уже начали ритуал, когда внезапно напала Кровавая Грива. Они уничтожили большую часть нашей стаи, а обрывки свитка оказались разбросаны по всей округе!$b$bРитуал провалился, но мы не должны допустить, чтобы эти негодяи сломили нашу веру! Мы должны молиться дальше! Будем очень признательны, если ты поможешь нам найти все потерянные фрагменты свитка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34923, 'ruRU', 'Кровавая Грива', 'Убейте искусного охотника Мрачный Оскал и $1oa |4когтереза:когтерезов:когтерезов; Кровавой Гривы.', 'Кровавая Грива... Они появились из ниоткуда и напали на нас в ту самую минуту, когда мы начали возносить хвалу безголовой птице.$b$bМы сразу поняли, что это Прародительница воронов решила испытать стойкость своих детей. Конечно, этим испытанием нас не сломить, и мы будем продолжать наши молитвы несмотря ни на что!$b$b<Секара наклоняется к вам и шепотом добавляет:>$b$bНо если ты поможешь нам избавиться от Кровавой Гривы и ее предводителя, это будет поистине великое деяние.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34924, 'ruRU', 'Похитители яиц', 'Добудьте $1oa |4яйцо:яйца:яиц; грозного ворона.', 'Кровавый Коготь – банда настоящих чудовищ. Они атаковали Пристанище и похитили яйца священных воронов.$b$bЕсли окажешься в землях Кровавого Когтя, попробуй узнать, где они прячут яйца.$b$bЯ буду ждать твоего возвращения в гнезде и подготовлю побольше корзин для яиц.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34925, 'ruRU', 'Полировка Железного трона', 'Заберите ключ от кандалов Га\'нара у владыки Готригга в соседнем строении.', 'Эти вонючие трусы из клана Черной горы думают, что этим унижают меня.$b$bНо я не сломлен – я в ярости!$b$bВон в той хижине сидит владыка Готригг, который носит при себе ключ от моих оков. Мне нужен этот ключ – иначе я отсюда не выберусь. Но когда выберусь... я им такое устрою...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34929, 'ruRU', 'Событие: Геннадиан', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34931, 'ruRU', 'Treasure: Frostwolf Cache 04', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34932, 'ruRU', 'Личина лжи', 'Поговорите с Чалли и узнайте правду.', 'Неподалеку отсюда, в пещере живет старуха по имени Чалли.$b$bЯ знаю ее много лет – еще со своей юности. Но вот я состарился и поседел, а она осталась молодой и красивой.$b$bКогда-то она ревновала меня к Дахаке, и я давно подозреваю Чалли в причастности к ее смерти. Однако я не могу свершить над ней правосудие, пока у меня нет доказательств.$b$bНайди Чалли и скажи ей, что я умираю. Передай ей – я хочу узнать, что стало с Дахакой, прежде чем покину этот мир.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34934, 'ruRU', 'Первые защитники', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34935, 'ruRU', 'Приветствие после Стены', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34936, 'ruRU', 'Сокровище: дополнительный тайник леди Сены', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34937, 'ruRU', 'Сокровище: дополнительный тайник Скеггита', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34938, 'ruRU', 'Судный час Ралшиары', 'Убейте Ралшиару.', 'В Свитке Восходящего Солнца сказано, что нельзя приготовить утреннюю трапезу, не разбив яиц.$b$bА Ралшиара, матерь Кровавой Гривы, поедает священные яйца воронов. Как она смеет! За такие грехи – только смерть!$b$bИди на юг через горы, чтобы добраться до проклятых земель Кровавой Гривы.$b$bВозьми эту вещицу, она упала к нам с неба как благословение Прародительницы воронов. С ней у тебя появится шанс победить в битве.', '', '', 'Ралшиара', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34939, 'ruRU', 'Тот без когтя и останется', 'Добудьте $1oa |4лапу:лапы:лап; шаманов Кровавого Когтя.', 'Свиток Поучений говорит нам: \"Кто когтем своим отбирает у тебя, тот без когтя и останется\".$b$bК югу отсюда есть тропа, она ведет за гору, в Долину Кровавой Гривы, к западу отсюда. Кое-кто из тамошних жителей владеет примитивным колдовством. Убей их и отрежь каждому по одной лапе вот этим ритуальным ножом.$b$bА после принеси эти лапы ко мне в гнездо, я преподнесу их Прародительнице воронов!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34940, 'ruRU', 'Сокровище: паучий нож', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34941, 'ruRU', 'Наш общий долг', 'Поговорите с Гар\'роком.', 'Эти смертные оболочки под названием \"тела\" – не наша собственность. Тело – дар земли, и однажды должно вернуться туда, откуда пришло.$b$bИ для этого тела пришел черед вернуться обратно к стихиям.$b$bНо знай, $n, – ты $gснял:сняла; тяжелый груз со старого сердца. Я покидаю этот мир без сожалений. Я сражался за свой народ и свою землю, я служил стихиям, и я любил.$b$bТы окажешь мне честь, |3-6($c), если останешься со мной в эти последние минуты.', '', '', '', '', 'Каландриос', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34942, 'ruRU', 'Возращение', 'Поговорите с темным ведуном Искаром в Гнездовье Терокк.', 'Необходимо подготовиться к возвращению Короля воронов.$B$BИз этого мира я смогу быстро перенестись в Гнездовье Терокк.$B$BА вот тебя нужно вернуть в другой мир. У тебя слишком много силы, ты привлечешь ненужное внимание.', '', '', '', '', '', 'Поговорите с темным ведуном Искаром в Гнездовье Терокк.', 25549);
INSERT INTO `quest_template_locale` VALUES (34943, 'ruRU', 'Старый знакомый', 'Поговорите с Гар\'роком.', 'С самого начала хранителем Трона Стихий был шаман, которого призывали специально для этой цели. Это призвание на всю жизнь, и нового хранителя выбирают только после кончины предыдущего.$b$bГар\'рок много лет верно служил нам и не раз очищал Плато Стихий в ходе бесчисленных циклов перерождений.$b$bНаш хранитель умирает, и скоро его место займет другой. В свой смертный час он не должен оставаться в одиночестве. Иди к нему, $n.$b$bОблегчи его страдания.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34945, 'ruRU', 'Отслеживание – событие \"Малый надзиратель Кровогрив\"', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34946, 'ruRU', 'Приветствие Моркурка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34947, 'ruRU', 'Руководство по управлению крошшером', 'Найдите распоряжения о списании железных крошшеров.', 'Эй! Говорят, рядом есть кое-что интересное. Разведчики утверждают, что это какая-то инструкция по крошшеру.\n\nНайдешь ее, ладно? Интересно, а вдруг она относится к этому новому прототипу...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34948, 'ruRU', 'Руководство по управлению крошшером', 'Найдите распоряжения о списании железных крошшеров.', 'Говорят, инженеры Железной Орды работают над новым прототипом крошшера.\n\nЭто дело нужно расследовать. Темная охотница заметила какое-то руководство по управлению крошшером – возможно, оно имеет отношение к этой модели.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34949, 'ruRU', 'Вербовка', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34950, 'ruRU', 'Жуткопоршень', 'Разрушьте Жуткопоршень.', 'Неподалеку отряд Железной Орды с удивительной быстротой захватил стратегически важную позицию.\n\nПобеду им обеспечила машина, которую они называют Жуткопоршень. Думаю, нам нужно сначала разобраться с ней, и лишь затем выступать против армии Железной Орды, которая обосновалась в Тууреме.', '', '', 'Жуткопоршень', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34951, 'ruRU', 'Его имя – Лантрезор Клинок', 'Найдите Лантрезора Клинка в Галлвалоре.', 'Клан Пылающего Клинка в Галлвалоре поставляет Песне Войны оружие и воинов. Так дальше продолжаться не может.$B$BЕсть один юный воин, которого много лет назад изгнали из клана Пылающего Клинка. Его зовут Лантрезор Клинок.$B$BНедавно мои рангари видели, как он вернулся в Галлвалор, чтобы бросить вызов старшим мастерам. Но его схватили и заковали в цепи.$B$BНадеюсь, он еще жив. И, возможно, поможет тебе справиться с Пылающим Клинком.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34952, 'ruRU', 'Друг моего врага', 'Убейте $1oa |4орка:орков:орков; клана Пылающего Клинка в Галлвалоре.', 'Галлвалор – это родина клана Пылающего Клинка. Поскольку они с Песней Войны добрые друзья, клан позволяет мастерам клинка и их шаману оставаться в Награнде – при том, что все остальные кланы оттуда вытесняют.$B$BЧушь это все, я так скажу.$B$BЕсли они друзья моего врага, значит, они – мои враги, а больше ничего знать и не нужно!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34953, 'ruRU', 'Кровь Пылающего Клинка', 'Убейте $1oa |4орка:орков:орков; клана Пылающего Клинка в Галлвалоре.', 'Галлвалор – это родина моего клана, Пылающего Клинка. Когда к власти пришел новый вождь и его семья, меня – полукровку – изгнали.$B$BЯ хочу, чтобы свершилось правосудие.$B$BИ думаю, что ты не откажешься ради этого пролить кровь. Правда, выбора у тебя все равно нет.', '', '', '', '', '', 'Поговорите с Гензелем Большеруком на Телаарской станции.', 19865);
INSERT INTO `quest_template_locale` VALUES (34954, 'ruRU', 'Собственно, клинок', 'Отнимите клинок Лантрезора у инструктора Лухка.', 'Когда меня заковали в цепи, наставник клана Пылающего Клинка Лухк Остроглазый забрал мой клинок. Он достойный орк, хоть его тренировочные методы и оставляют желать лучшего.$B$BЯ хочу вернуть свой клинок, |3-6($c).', '', 'Клинок Лантрезора находится у этого наставника мастеров клинка.', 'Инструктор Лухк', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34955, 'ruRU', 'Главное – честь', 'Отыщите знамя мастера клинка в сундуке клана Пылающего Клинка.', 'Сам клинок – не единственный ценный предмет, которым владеет каждый мастер клинка.$B$BПройдя последние испытания в Пещерах Мастеров, мастер клинка получает знамя Пылающего Клинка. $B$BКогда же моя просьба вернуть мне законное место в клане была отвергнута, меня лишили и этой чести.$B$BСейчас мое знамя, несомненно, хранится где-то в Галлвалоре. Если знамя еще не сожгли, то, наверно, отдадут его какому-нибудь начинающему мастеру клинка.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34956, 'ruRU', 'Встреча в пещере', 'Встретьтесь с Лантрезором Клинком в Пещере Мастеров.', 'Пора, |3-6($c). Время предстать перед мастерами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34957, 'ruRU', 'Испытание мастеров', 'Выживите в испытании клана Пылающего Клинка.', 'Самое время бросить вызов мастерам клана Пылающего Клинка.$B$BСтупай вглубь пещеры. Там увидишь площадку для боя. Мастера будут наблюдать за тобой со своих мест сверху.$B$BВытащи из земли клинок в центре площадки – этим ты покажешь свою готовность к испытанию. Мой клан превыше всего ценит честь и примет твой вызов на испытание боем.$B$BЕсли выдержишь его, тебе позволят убраться восвояси с головой на плечах. В противном случае с головой придется расстаться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34958, 'ruRU', 'Тень \"Разрушителя миров\"', 'Достаньте чертежи \"Разрушителя миров\" у орков клана Черной горы в Каменоломне клана Черной горы.', 'Похоже, скоро нам предстоит столкнуться с еще одним препятствием: с безумно огромным танком, который целится в Темный портал. \"Железный разрушитель миров\" – так, кажется, его называют.$b$bМне бы достать какие-нибудь технические документы по этой железяке, тогда я бы понял, как вывести ее из строя. Может, у кого-то из механиков есть такие?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34959, 'ruRU', 'Жуткопоршень', 'Разрушьте Жуткопоршень.', 'Железная Орда захватила мирный аванпост дренеев и перебила всех его обитателей.\n\nУ нападавших была машина под названием Жуткопоршень – это именно она сровняла поселение с землей буквально за считанные минуты.\n\nУничтожь ее.', '', '', 'Жуткопоршень', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34960, 'ruRU', 'Природа обеспечит всем необходимым', 'Найдите $1oa |4пучок:пучка:пучков; ледяной лозы.', 'Ледяная лоза из Продуваемой впадины обладает повышенной устойчивостью к холоду. Включи ее в список материалов, которые пойдут на строительство гарнизона.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34962, 'ruRU', 'План Кадгара', 'Поговорите с Кадгаром у ворот Шаттрата.', 'Железная Орда загнана в угол – и все благодаря тебе.\n\nСкоро мы войдем в Шаттрат и прогоним захватчиков.\n\nНо сначала нам нужно встретиться с Кадгаром и новыми союзниками.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34963, 'ruRU', 'План Кадгара', 'Поговорите с Кадгаром у ворот Шаттрата.', 'Шаттрат не должен достаться Железной Орде. Пора снова обагрить руки кровью.\n\nМы сообщим Кадгару, что готовы войти в город и вернуть себе то, что принадлежит нам по праву.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34964, 'ruRU', 'Предсказатель ждет', 'Найдите предсказателя Дрек\'Тара у Трона Стихий.', '$n, тебя хотят видеть у Трона Стихий.$b$bПредсказатель Дрек\'Тар услышал в голосе ветра зов Ярости и отправился в путь, чтобы поговорить со стихиями.$b$bПредсказатель сказал, что тебе нужно поговорить с ним у Трона Стихий.$b$bИди и узнай, что стихиям от тебя надо.', '', '', '', '', '', 'Поговорите с Дрек\'Таром.', 25549);
INSERT INTO `quest_template_locale` VALUES (34965, 'ruRU', 'Призыв к Трону', 'Поговорите с гневными духами у Трона Стихий.', 'Вскоре после прибытия в Награнд я услышал голос Каландриоса – его голос принес ветер.$b$bАудиенция у Трона Стихий – великая честь, но на душе у меня было тяжело: я предполагал, зачем меня вызвали.$b$bПовсюду я чувствую присутствие болезни. Она окружает все живое... поглощает... душит...$b$bИдем, пора пообщаться с гневными духами стихий и помочь им. На эту долину упала невидимая тень. Возможно, убрать ее должны именно мы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34967, 'ruRU', 'Сокровище: добыча из рейда', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34968, 'ruRU', 'Сокровище: замороженные припасы', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34969, 'ruRU', 'Призыв Серены', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34971, 'ruRU', 'Единственный способ путешествовать', 'Поговорите с Моркетом Воющим Мечом в Гордости Вол\'джина.', 'Можешь упрекнуть меня за излишнюю осторожность, но мне показалось разумным приберечь несколько сигнальных ракет, на случай если нам придется бежать отсюда.$b$bХорошо, что они не понадобились, но прокатиться с ветерком до оружейной было бы неплохо.$b$bЧто скажешь, командир?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34972, 'ruRU', 'Облачиться в доспехи', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34976, 'ruRU', 'Бомбардировка', 'Пусть артиллерия ударит по камнеметателям клана Гордунни в крепости Гордал.', 'В крепость Гордунни ведет только одна тропа, и ее хорошо охраняют.$b$bК счастью, они не ожидают, что внутрь попытаемся проникнуть только мы двое.$b$bЭто отличная возможность прорвать их оборону и хороший шанс для наших артиллеристов попрактиковаться в стрельбе.$b$bВозьми эти дымовые гранаты – с их помощью ты сможешь корректировать огонь артиллерии по вражеским катапультам по пути наверх.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34977, 'ruRU', 'Охота за припасами', 'Добудьте $1oa |4комплект:комплекта:комплектов; груза Железной Орды.', 'Похоже, мы прибыли вовремя! $b$bГордунни зачаровывают оружие для Железной Орды, и, кажется, они не забрали последнюю поставку.$b$bЭтим игрушкам самое место в нашей артиллерийской башне! Пойдем отобьем их ящики со снаряжением. У меня с собой сигнальные ракеты: сможем использовать их, чтобы кто-нибудь прилетел и забрал нас, когда захватим оружие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34978, 'ruRU', 'Возвращение ценностей', 'Заберите $1oa |4булаву:булавы:булав; стражей Шаттрата у крушителей или рассекателей из клана Гордунни в крепости Гордал.', 'Гордунни досаждали народу Шаттрата столько времени, сколько стоит их город. Со временем они скопили у себя целую прорву оружия, которое захватывали в набегах.$b$bМне кажется, это оружие совсем не помешало бы нашим бойцам, и лично я спала бы куда спокойнее, зная, что у огров его больше нет.$b$bПрошу тебя, сделай мне одолжение и отбери у огров столько оружия, сколько сможешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34979, 'ruRU', 'Пробиться внутрь', 'Убейте визирей Воргорша, Зулморка и Кромауга.', 'Чтобы взять под контроль крепость, нужно убить лорда-чародея Моркурка. Но вряд ли разумно сразу идти за его головой. $B$BТрое его подручных – Воргорш, Зулморк и Кромауг – могущественные маги, и они беззаветно преданы Моркурку. $B$BЕсли мы нападем на лорда-чародея, они бросятся ему на выручку. Давай уничтожим их, чтобы облегчить себе задачу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34980, 'ruRU', 'Повелитель Гордунни', 'Победите лорда-чародея Моркурка в крепости Гордал.', 'Лорд-чародей – это предводитель клана Гордунни. Нам нужно его убить, чтобы добыть йовит, необходимый нам в артиллерийской башне.$b$bМоркурк – опытный маг, так что приготовься. Вот, возьми ракетный ускоритель и используй его, когда нужно будет уклониться от его смертоносных заклинаний.$b$bАркенон порос!', '', '', 'Лорд-чародей Моркурк', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34981, 'ruRU', 'Единственный способ путешествовать', 'Поговорите с Миаллой в форте Ринн.', 'Можете упрекнуть меня за излишнюю осторожность, но мне показалось разумным приберечь несколько сигнальных ракет, на случай если нам придется бежать отсюда.$b$bХорошо, что они не понадобились, но прокатиться с ветерком до артиллерийской башни было бы неплохо.$b$bВы готовы, командир?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34982, 'ruRU', 'Облачиться в доспехи', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34983, 'ruRU', 'Бомбометание - отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34984, 'ruRU', 'Охота за припасами - отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34985, 'ruRU', 'Возвращение ценностей - отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34986, 'ruRU', 'Пробиться внутрь - отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34987, 'ruRU', 'Пороховой заговор', 'Найдите бочонок с порохом Черной горы и отнесите его Гензелю Большеруку.', 'Эй, $gприятель:дамочка;! У нас тут проблема.$b$bМой старый приятель Телин собрал вот эту подрывную машинку из запасных частей, отобранных у орков клана Черной Горы, – такой уж он у нас сметливый инженер. Но нашему приспособлению не хватает пороху – без него мы ничего не сможем взорвать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34991, 'ruRU', 'Спа... сение?', 'Спасите \"Тиллика\" от чудовищного Камнешкура в Ущелье Криволеса.', 'Пергамент Пыли учит нас: \"Да сразится бесперый с бесперым, негоже нам для этого когти марать!\" Что бы мы делали без наставлений Верховной Говорящей с воронами?$b$bНа холмах, что к западу отсюда, злодействует зверь Камнешкур. Он утащил одного из моих соплеменников к себе в логово, и сколько стая ни пыталась спасти несчастного, одолеть чудовище так и не удалось.$b$bНастал твой час испытаний! Убей Камнешкура, вызволи Тиллика и сверши предначертанное самой Прародительницей воронов!', '', '', 'Камнешкур', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34992, 'ruRU', 'Лесопилка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (34993, 'ruRU', 'Вербовка', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34994, 'ruRU', 'Вечная юность', 'Найдите младокорень для мистера Попайла.', 'Пока я сижу тут, дела идут хуже некуда. $b$bНадо как-то вернуть себе потерянную прибыль.$b$bДренейские женщины просто одержимы красотой своих рогов. $b$bЯ слышал, как одна из них говорила о корне, который растет в Цветении Лунного Серпа. Он якобы укрепляет рога.$b$bДумаю, я смогу продать им этот корень за хорошую цену.$b$bЕсли добудешь мне его, поделюсь прибылью.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34995, 'ruRU', 'Прополка', 'Убейте $1oa ботани.', 'Гидвину сейчас намного лучше. Спасибо, $n.$b$bПоверить не могу, что дренеи столько лет жили рядом с этими ужасными тварями.$b$bДумаю, надо объяснить им, что случается, когда нападаешь на жителей Азерота.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34996, 'ruRU', 'Гниющие речные чудища', 'Убейте $1oa |4цветущую мандрагору:цветущих мандрагоры:цветущих мандрагор;.', 'Ботани заражают местных речных чудищ какими-то странными плотоядными растениями.$B$BБоюсь, что эта зараза может перейти и на наш народ.$B$BЕсли увидишь зараженных чудищ, уничтожь растения, которые населяют их тела, пока они тебя не убили.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34997, 'ruRU', 'Дремоцвет', 'Используйте подобранные камни, чтобы уничтожить дремоцветы.', 'А?.. Ой, что-то меня снова сморил сон.$b$bОт этого дремоцвета одни беды. Я сражаюсь с ботани, а уже через секунду мне снится, что я элекк и танцую с речными чудищами.$b$b*Зевает* Надо что-то сделать с этими дремоцве... *Зевает* Хр-р-р-р-р.$b$b<Вы подбираете небольшую пригоршню камней, лежащих около спящего дренея.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34998, 'ruRU', 'Дозор Когтя', 'Отдайте Глаз Анзу коготарю Курекку в Дозоре Когтя. Чтобы добраться туда, поговорите с небесным когтем Мешаалом.', 'Ты, наверное, уже гадаешь, что это за проклятье, превратившее прекрасных и гордых араккоа в... вот это?$B$B<Решад проводит скрюченной рукой по пестрым перьям на лице.>$B$BВорон ждет. Он отнесет тебя к Дозору Когтя. Там ты поймешь природу проклятия.$B$BПокажи Глаз Анзу коготарю Курекку – он скажет тебе, что нужно делать дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (34999, 'ruRU', 'Вечная ненависть', 'Соберите $1oa |4образец:образца:образцов; запекшейся крови Сете в Сетеккской низине.', 'В местных водоемах осталась кровь мертвого бога Сете. А с ней и его ненависть к Рухмар и Анзу.$B$BТакая сильная, что она оживляет кровь даже сейчас, через несколько эпох после того, как его убили другие боги.$B$BМне нужна запекшаяся кровь, которая дает этим злобным существам жизнь.$B$BПриверженцы больше всего на свете боятся этого проклятия – что, если мы сможем обратить его против них?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35000, 'ruRU', 'Изгнание с небес', 'Используйте Глаз Анзу на 8 проклятых араккоа.', 'Приверженцы уже много лет сбрасывают своих врагов в эту низину.$B$BВ лужах крови Сете заключено его предсмертное проклятие. Оно лишает араккоа сил, насылая на них жуткие видения и сильную боль. Разум смятен, тело изнемогает от боли, крылья усыхают.$B$BБольшинство араккоа умирают там или сходят с ума. Сопротивляются только самые сильные – найди их и используй Глаз Анзу, чтобы помочь им вернуть себе разум.$B$BНо берегись: последователи Сете тоже хотят переманить выживших.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35001, 'ruRU', 'Взгляд Бога-ворона', 'Уничтожьте $1oa |4гнездо:гнезда:гнезд; крылатых змеев при помощи Глаза Анзу.', 'Из крови и костей Сете его последователи, сетекки, плодят гнусных крылатых змеев. С такими союзниками на их стороне они скоро будут безраздельно властвовать над небесами.$B$BИх гнезда защищены могучими чарами, но взгляд Анзу с легкостью рассеет их.$B$BДавай же атакуем гнезда и уничтожим их!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35002, 'ruRU', 'Сыны Сете', 'Добудьте 6 крыльев крылатых змеев.', 'Уже много лет никто не обращался к Анзу. Он отступил, как когда-то Терокк, чтобы укрыться в тенях.$B$BЧтобы выманить его обратно, надо сделать достойное предложение.$B$BСете забрал у всех нас небо – будет справедливо забрать у его детей крылья.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35003, 'ruRU', 'Ритуальное отсечение', 'Затопчите три ритуальных круга сетекков в Сетеккской низине, пробежав по ним.', 'Мне не удалось справиться с проклятием, и поэтому я давным-давно смирился с тем, что навсегда останусь во тьме.$B$BОднако темные ритуалы сетекков тянут меня обратно и подчиняют воле Сете. Если они добьются своего, Сете заставит меня затянуть горизонт темной пеленой и утопить мир в его крови.$B$BОстанови эти ритуалы и освободи меня. Тогда мы вместе помешаем Сете воскреснуть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35004, 'ruRU', 'Служители мертвого бога', 'Убейте $1oa |4сетеккского пророка:сетеккских пророков:сетеккских пророков; и $2oa |4сетеккского избранного:сетеккских избранных:сетеккских избранных; в Сетеккской низине.', 'Даже после смерти Сете продолжает влиять на этих несчастных. Культ сетекков появился из-за этого влияния, его создал король-самозванец, служащий мертвому богу.$B$BЗаставь их пророков замолчать, ибо они хотят создать мир, где моря почернеют, а воздух будет отравлен. Победи их защитников, ибо они поклялись сражаться за неправое дело.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35005, 'ruRU', 'Подготовка к битве', 'Соберите 30 комплектов оружия орков из клана Черной горы.', 'Здесь не спрячешься. Нужно продвигаться дальше, а для этого нам придется пройти по землям Железной Орды.$b$bПора превратить эту толпу пленников в армию.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35006, 'ruRU', 'Паралич от яда', 'Спасите пропавших путников.', 'Пропали и другие путники из каравана.$b$bДумаю, ботани утащили их в Цветение Лунного Серпа.$b$bТебе нужно спасти их, $n! Ты – наша единственная надежда.$b$bВот, возьми эликсир... он тебе пригодится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35007, 'ruRU', 'В поисках ритуалистов', 'Поговорите с Говорящим с воронами Секарой в Пристанище Воронов.', 'Наш дорогой брат Секара вместе с собратьями отправился в Пристанище воронов, чтобы провести великий ритуал очищения.$b$bС тех пор от них не было гонцов – наверное, они всецело погружены в молитвы.$b$bЯ собираюсь проведать их, но мне также нужно проследить за переписчиком: в моем последнем поучении не должно быть ни одной ошибки! Можешь пока что проведать Секару? Я присоединюсь к вам... рано или поздно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35009, 'ruRU', 'Призыв Прародительницы воронов', 'Помогите Верховной Говорящей с воронами Крикке провести ритуал призыва.', 'Все готово к началу ритуала, который вернет Прародительницу воронов в гнездо.$b$bТы $gпрошел:прошла; все испытания, так что у тебя есть полное право принять участие в этом ритуале.$b$bСкоро перед нами явится Прародительница воронов! О, у меня мурашки бегут по перьям от волнения!$b$bПоговори со мной, когда будешь $gготов:готова;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35010, 'ruRU', 'Верховная Говорящая с воронами', 'Найдите Верховную Говорящую с воронами Крикку', 'Я так и знал, что ты пройдешь испытание! В Свитке веры говорится, что тяжелые времена порождают великие сомнения, и только вера в Прародительницу воронов может вернуть все на круги своя!$b$bИдем, идем, мы должны разыскать Верховную Говорящую с воронами!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35011, 'ruRU', 'Король-самозванец', 'Заберите поцарапанный браслет у короля воронов Айкисса', 'Когда-то Айкисс был уважаемым мудрецом среди приверженцев, но попытки узнать правду о крахе Терокка стали причиной его собственного изгнания.$B$BАйкисс стал одержим Терокком, он даже считает себя воплощением этого героя древности, обещает сетеккам невиданную мощь в новую эпоху тьмы.$B$BЗнай: Айкисс – вовсе не король. Убей этого безумца, а затем обыщи его. Он любит собирать разные могущественные реликвии.', '', 'Безумный чародей, возомнивший себя реинкарнацией Терокка.', 'Король воронов Айкисс', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35012, 'ruRU', 'Сете, мертвый бог', 'Помогите Анзу победить Сете у Надломленного пика.', 'Пора наконец устранить Сете. Когда-то мне уже удалось его убить – а сейчас с твоей помощью я сделаю это еще раз.$B$BГотовься к бою – сторонники культа не будут спокойно смотреть на то, как мы уничтожаем их бога.', '', 'Возрожден сетекками.', 'Сете, мертвый бог', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35013, 'ruRU', 'Дар Литик', 'Отнесите поцарапанный браслет в Последнее пристанище Литик.', '<Курекк, прищурившись, медленно крутит браслет в когтях.>$B$BНа внутренней стороне видна надпись:$B$B\"Моему отцу. Да осветит твой путь Рухмар. С любовью, Литик\".$B$BНе может быть... это же браслет Терокка! Это подарок дочери, он годами носил его, пока...$B$BВ общем, браслет лучше вернуть.$B$BТерокк воздвиг мемориал Литик неподалеку от Дозора Когтя. Браслет должен лежать там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35014, 'ruRU', 'Цветение Лунного Серпа', 'Найдите рангари Арефеона в Цветении Лунного Серпа', 'Другого выхода нет.$b$bЯ пойду в рощу и выясню, что происходит. Встретимся там.$b$bУдачи, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35015, 'ruRU', 'Растущий генезотавр', 'Убейте генезотавра.', 'Плохо дело. В роще начал расти генезотавр.$B$BГенезотавров на Дреноре не было уже три сотни лет.$b$bНеудивительно, что ботани так сходят с ума. Им нужны трупы, чтобы удобрять это чудовище.$b$bНадо уничтожить эту тварь, пока она не выросла. Если упустим момент, то уже ничего не сумеем поделать с этим генезотавром.', '', '', 'Цветущий генезотавр', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35016, 'ruRU', '\"Сбор черепов для чайников\"', 'Соберите черепа $1oa |4мертвого Собирателя:мертвых Собирателей:мертвых Собирателей; Черепов.', 'Все мои охотники мертвы – так что теперь тебе придется немного мне помочь.$b$bОтыщи тела погибших и принеси мне их черепа. Я решу, какие выбросить, а каким воздать почести. Таков наш обычай.$b$bА я отправлюсь на охоту за другими черепами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35017, 'ruRU', 'Месть Собирателя Черепов', 'Убейте $1oa |4грибного разведчика:грибных разведчиков:грибных разведчиков;.', 'Остальные... погибли или ушли в туман. Я тоже слышал зов, но оказался сильнее. Я убивал их, пока они не изувечили мое тело. Но я убил их слишком мало, $p... слишком мало! Ступай. Перебей их и скажи моему командиру, что я ушел во тьму не один.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35018, 'ruRU', 'Событие: Сквернодрев', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35019, 'ruRU', 'Подготовка к битве', 'Соберите 30 комплектов оружия орков из клана Черной горы.', 'Здесь не спрячешься. Нужно продвигаться дальше, а для этого нам придется пройти по землям Железной Орды.$b$bПора превратить эту толпу пленников в армию.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35020, 'ruRU', 'Jared\'s Test Quest', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35021, 'ruRU', 'Таинственный стручок', 'Отнесите светящийся красный стручок Грулкору в Багровую топь.', 'Этот стручок похож на все остальные стручки, растущие на трупах и возле них, только он как-то странно пульсирует. Возможно, Грулкор знает, в чем дело.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35022, 'ruRU', 'Разгоняя тьму', 'Зажгите от факела духов церемониальные костры в Землях Предков.', 'Гора Ошу\'гун всегда притягивала к себе духов моих предков. И я сейчас в глубине души чувствую ее притяжение... но что-то изменилось.$b$bСила, что манит нас, стала зловещей и темной. Она пожирает души мертвых, души моих предков, $n.$b$bС этим нужно что-то делать.$b$bВот, возьми факел духов и зажги от него церемониальные костры в Землях Предков.$b$bПламя, зажженное от факела духов, умиротворит беспокойных духов, которых тянет к себе Пустота.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35023, 'ruRU', 'Отголоски прошлого', 'Убейте $1oa |4отголосок страданий:отголоска страданий:отголосков страданий;.', 'Когда дух поглощается Пустотой, от него остается только отголосок.$b$bНи в материальном, ни в духовном смысле эти отголоски не являются живыми. Отголосок – это лишь искаженный отзвук страданий и мучений поглощенного духа.$b$bНо они могут нападать на живых и будоражить духи тех, кто давно уже обрел покой в могиле.$b$bЧтобы вернуть в Земли Предков мир, нужно уничтожить эти отголоски.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35024, 'ruRU', 'Голмаш Адский Крик', 'Победите дух Голмаша Адского Крика.', 'Те, кто находит смерть в жестоком бою, нередко переходят в мир духов неупокоенными. Так и вышло с Голмашем, отцом Громмаша Адского Крика.$b$bСтиснутый огромными челюстями гронна, Голмаш все же сумел из последних сил нанести чудовищу смертельный удар – вонзил свой топор Кровавый Вой прямо в его глаз. В той схватке погибли оба, причем гронн испустил дух первым.$b$bГолмаш погиб как настоящий герой. Любой орк клана Песни Войны был бы счастлив умереть такой смертью – но это удел лишь немногих. Однако могучий дух Голмаша до сих пор не обрел покоя, и своим присутствием он будоражит других духов.$b$bУпокой дух этого великого воина, $n.', '', 'Дух Голмаша Адского Крика нужно упокоить!', 'Голмаш Адский Крик', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35025, 'ruRU', 'Мы не одни', 'Осмотрите лагерь Железной Орды в Серной низине.', 'Эй, $gчужеземец:чужестранка;, здесь неподалеку ходят солдаты Железной Орды.$B$BПрийти в это опасное место – довольно дерзкая затея, даже для них.$B$BЕсли ты с ними не разделаешься, твой лагерь окажется в опасности.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35026, 'ruRU', 'Идем на поправку', 'Достаньте $1oa |4порцию:порции:порций; охлаждающей воды у духов кипящей ярости.', 'Ниша поправится.$b$bЕй сильно досталось, ей нужна вода и отдых.$b$bЯ пока отнесу ее в лагерь.$b$bМожет, тем временем наберешь для нее воды?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35027, 'ruRU', 'Расчистка пути', 'Убейте $1oa |4покрытого плесенью шаркуна:покрытых плесенью шаркунов:покрытых плесенью шаркунов;.', 'Самыми сильными, видать, были мертвецы. Те, что оказались слабее, шатаются по болоту и нападают на чужаков.$b$bУбивать таких, как мне кажется, неправильно... Но от них все равно никакого толку, и они нам мешают. Убей этих немощных, чтобы мы могли спокойно идти дальше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35028, 'ruRU', 'Крикка и Вакора – отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35029, 'ruRU', 'Секрет грибов', 'Соберите $1oa |4светящийся гриб:светящихся гриба:светящихся грибов;.', 'Я чую запах и слышу шепот.$b$bЯ чувствую, что между местными растениями и животными есть какая-то связь. Похоже, внимание зверей привлекают какие-то особые грибы.$b$bСобери и принеси их. Они мне... понадобятся...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35030, 'ruRU', 'Жуткий урожай', 'Принесите Грулкору $1oa |4споровый стручок:споровых стручка:споровых стручка; грибных топотунов.', 'Большие монстры – вот что решит мою судьбу. Я чувствую это. Растущие на них стручки еще крупнее того, что ты $gпринес:принесла; мне. Собери несколько штук... они понадобятся... уже скоро.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35031, 'ruRU', 'Поиск по зову сердца', 'Найдите источник силы в Багровой топи.', 'Я чувствую присутствие какой-то мощной силы на болоте, $p. Она тянет меня к себе. Мы должны отправиться туда и забрать себе то, что ждет нас там. Ты иди $gпервым:первой; – мне еще нужно доесть грибы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35032, 'ruRU', 'Навстречу страданиям', 'Используйте осколок страдания у главного входа. Затем уничтожьте знак тьмы, метку тени и знак страданий.', 'Осколок страдания – подарок Рулкан – поможет тебе незаметно пробраться в Крепость Страданий. Поднимись по лестнице к двери и используй его, чтобы войти.$B$BВнутри ты найдешь три алтаря, которые подпитывают энергией волшебный барьер вокруг крепости.$B$BУничтожь руны – тогда мы с Ирель сможем помочь тебе в поисках Нер\'зула.', '', '', '', 'Хорошо.', 'Пророк Велен', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35033, 'ruRU', 'Добро пожаловать в Горгронд', 'Идите по Диколесью до Дозора Найель.', 'Горгронд – одно из самых опасных и диких мест на всем Дреноре.$b$bТолько самые опытные рангари забредают так далеко.$b$bМы направляемся к их лагерю. Если хочешь добраться туда раньше нас, иди по этой дороге и сверни направо.$b$bМы с Мараадом вскоре присоединимся к тебе. Нам еще нужно кое-что продумать перед отправлением.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35035, 'ruRU', 'Сеятели плохих новостей', 'Сожгите $1oa |4труп древнего-сеятеля:трупа древних-сеятелей:трупов древних-сеятелей;.', 'Убить сеятеля – дело нехитрое, но сами семена при этом выживают. Из них вырастают новые сеятели – и на это уходят вовсе не годы, а буквально считанные часы.$b$bЕсли не уничтожать останки, скоро их расплодится столько, что мы с ними уже не справимся.$b$bНо мы выяснили, что их можно сжечь, и тогда ничего такого не произойдет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35036, 'ruRU', 'Это кто-то из твоих?', 'Поговорите с Рексаром и поручитесь за Костяного Зака.', 'Он прятался тут поблизости. Говорит, что твой союзник.$b$bЭто правда? Или мне зажарить его на медленном огне?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35037, 'ruRU', 'Сломать тех, кто строит', 'Осмотрите лагерь Железной Орды в последнем приюте Клыколома.', 'Снизу из ущелья постоянно доносятся какой-то визг и рычание.$b$bНадо бы туда заглянуть, но я пока не рискую оставлять Нишу одну.$b$bТы выяснишь, что там происходит?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35038, 'ruRU', 'Какого Костяного Зака?', 'Добудьте $1oa |4кристалл:кристалла:кристаллов; горена с проглотов-длиннозубов.', 'Смотрю, $n, у тебя все кости пока целы. Как и у Зака.$b$bКогда ты $gотправился:отправилась; в глубину каньона, Зак пришел предложить свои услуги. Зак не позволит тебе забрать все черепа!$b$bЗак поделится с тобой своей могущественной магией, которой мой клан владеет уже много лет. Пока Зак готовится, тебе нужно собрать реагенты.$b$bДля начала нам нужны кристаллы умерших горенов. Их можно найти в каньоне неподалеку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35040, 'ruRU', 'В самом сердце трясины', 'Следуйте за Грулкором вглубь Багровой топи и готовьтесь к любому повороту событий.', 'Если бы только деревья не орали на меня, мне бы удалось сосредоточиться получше. Ну да ладно – это всего лишь деревья, в конце концов.$b$bЗдесь уже ничего не осталось, но я чувствую гораздо более могучую силу в глубине болота. Я отправлюсь туда и заберу то, что принадлежит мне по праву!$B$BА потом я поделюсь добычей со всеми...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35041, 'ruRU', 'Закнуть их!', 'Замаскируйтесь под горена, чтобы исследовать Горгронд.', 'Дело сделано.$b$bЭти чары позволят тебе не только без опаски ходить среди горенов – но и ходить, как они.$b$bТеперь хождения по Горгронду будут совсем простыми. Сможешь попасть куда угодно, куда попасть невозможно.$b$bОб этом позаботились предки Зака.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35044, 'ruRU', 'Призыв Корданы', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35045, 'ruRU', 'В память об Ареде', 'Поговорите с Миаллой в форте Ринн в Таладоре.', 'Мой наставник ушел к Свету, но я продолжу его дело.$b$b<Миалла бросает взгляд на Ареда.>$b$bШанай ортар, Аред.$b$bЯ распоряжусь, чтобы его тело отправили в Аукиндон. Ну а теперь покажи мне свою артиллерийскую башню.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35047, 'ruRU', 'Бомбометание – отслеживание', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35049, 'ruRU', 'Лесопилка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35050, 'ruRU', 'Спасение рангари', 'Отыщите рангари Раджесс, рангари Колаана и рангари Йонаа.', 'Мы недосчитались многих рангари. Похоже, они в плену у порождений Ию.$b$bМы продолжим поиски выживших.$b$bА ты пока отправляйся по Диколесью на запад к Верхнему Пути и постарайся найти следы рангари.$b$bНаш народ очень выносливый: ты наверняка найдешь больше пленных, чем ожидаешь. Скажи им, чтобы ждали у дороги, а мы прибудем, как только... этот дворфишка... починит свое механическое судно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35051, 'ruRU', 'Башня магов', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35055, 'ruRU', 'Пропавшие буровые установки', 'Найдите пропавшую буровую установку.', 'Немногие знают клан Черной горы лучше дворфов Черного Железа.$b$bПосле Танаана мы отправили группу буровых установок в Горгронд, чтобы построить пост подслушивания и присматривать за ними.$b$bМоя установка сбилась с курса, и я отстал от остальных. Быстро стало ясно, что все другие установки тоже отклонились от маршрута.$b$bПо данным радара в моем танке, к западу отсюда на поверхность вышла буровая установка.$b$bМожешь разведать ситуацию, пока мы приводим танк в рабочее состояние?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35056, 'ruRU', 'Отслеживание – Рогатый Череп', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35058, 'ruRU', 'Бутыль с загадочной жидкостью', 'Поговорите с Ло\'нашем в гарнизоне.', 'Жидкость, бурлящая в бутыли, очевидно, обладает мощными алхимическими свойствами, но ее природа вам неизвестна. Вы слыхали, что один из беженцев Каменного Клыка в вашем гарнизоне знаком с дренорской алхимией. Может быть, он знает, что это за жидкость?', '', '', '', '', '', 'Поговорите с Ло\'нашем в вашем гарнизоне.', 25549);
INSERT INTO `quest_template_locale` VALUES (35059, 'ruRU', 'У реки', 'Поговорите с воздаятельницей Ирель в Дозоре Ирель.', 'Воздаятельница Ирель отправилась с большей частью наших сил на север. Она собирается организовать передовую базу у реки Небесной Песни.$B$BЕй непременно нужно сообщить, что мы уже практически полностью готовы двинуться на Громмашар.$B$BКроме того, ей наверняка пригодится твоя помощь, чтобы разделаться с орками клана Песни Войны в Лок\'рате.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35060, 'ruRU', 'Условия сдачи', 'Поговорите с Уруком Грозой Врагов в Лок\'рате.', 'Невероятно, но в кои-то веки у нас хорошие новости: мы уже взяли Лок\'рат.$B$B<Воздаятельница просто сияет от гордости.>$B$BНаши воины захватили в плен большую часть бойцов клана Песни Войны, в том числе их командира Урука Грозу Врагов.$B$BЧесть принять его капитуляцию принадлежит тебе. Они ждут внутри, командир.', '', 'Договоритесь об условиях сдачи и приведите его в Дозор Ирель.', 'Урук Гроза Врагов', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35061, 'ruRU', 'Гордость Лок\'рата', 'Убейте Урука Грозу Врагов.', 'Думаешь, Песню Войны так легко одолеть?$B$B<Внезапно вы слышите скребущий звук, будто веревкой трут по металлу.>$B$BМеня уже тошнит от вашего Альянса, и вы только что вторглись в нашу родную землю.$B$B<Урук Гроза Врагов смотрит вам прямо в глаза, и звук становится громче.>$B$BКапитуляции не будет. Клан Песни Войны не склонится ни перед кем!', '', 'Убейте командира клана Песни Войны в Лок\'рате.', 'Урук Гроза Врагов', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35062, 'ruRU', 'Лок\'рат взят', 'Поговорите с рангари Д\'кааном на Телаарской станции.', 'Лишившись командира, бойцы клана Песни Войны уже не смогут оказать организованное сопротивление.$B$BКак только довершим разгром, сразу покинем Лок\'рат и двинемся на Громмашар.$B$BЕсли ты собираешься возвращаться на Телаарскую станцию, передашь новости Д\'каану?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35063, 'ruRU', 'Нам нужен аванпост', 'Выберите на чертежном столе лесопилку или бойцовскую арену.', 'Командир, мы собрали достаточно материалов, чтобы построить аванпост, который поможет нам в войне с Железной Ордой.$b$bКак мы поступим?$b$bЛесопилка пригодится нам для сбора ресурсов в густых лесах на юге и для борьбы с жуткими живыми деревьями, обороняющими их.$b$bБойцовская арена, с другой стороны, поможет нам подготовить свирепых воинов, которые нужны, чтобы пробиться через магнаронские пустоши на севере.$b$bКогда примешь решение, укажи свой выбор на столе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35064, 'ruRU', 'Бойцовская арена', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35065, 'ruRU', 'Приход жнеца', 'Убейте жнеца Оммру.', 'Вот что бывает, если окажешься на пути генезотавра. А коли увидишь генезотавра, не сомневайся – ботани рядом.$b$bЯ видел, как один из них скрылся в пещере на северной окраине нашего лагеря.$b$bОн приказал стручлингам собрать тела наших убитых братьев, и его необходимо остановить.$b$bМне нужно помочь раненым и собрать припасы перед отправлением.$b$bЕсли действительно хочешь помочь, отправляйся в пещеру и убей этого ботани.', '', 'Орудие генезотавра Ию.', 'Жнец Оммру', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35066, 'ruRU', 'Огненный аммонит', 'Принесите Мак\'джину 10 порций икры огненных аммонитов, которые водятся в водоемах Хребта Ледяного Огня.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Осмотри водоемы Хребта Ледяного Огня и выясни, где можно хорошо порыбачить. Каждой пойманной рыбине надо будет вспороть брюхо и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35067, 'ruRU', 'Уничтожение боевых машин', 'Уничтожьте $1oa |4боевую машину Железной Орды:боевые машины Железной Орды:боевых машин Железной Орды;.', 'Железная Орда направила в Лок\'рат боевые машины из Гавани Железного Кулака. Если ничего не предпринять, скоро они сровняют Дозор Ирель с землей.$B$BКто-то должен их остановить!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35068, 'ruRU', 'Если враг не сдается...', 'Уничтожьте $1oa |4врага:врагов:врагов; при Лок\'рате.', 'Это костяк нашей армии, которую мы собираемся отправить в поход на Громмашар против Гарроша Адского Крика.$B$BЕсли клан Песни Войны не сдастся, нам придется его уничтожить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35069, 'ruRU', 'Ужас Награнда', 'Заберите ошейник Шагора у Шагора.', '<Здесь лежит тело погибшего воина. На север от трупа ко входу в пещеру тянется кровавый след.>$B$B<Судя по леденящему душу вою, идущему из глубины логова, там обитает какая-то жуткая тварь.>', '', 'Достаньте ошейник Шагора. Не допустите, чтобы смерть того воина оказалась напрасной.', 'Шагор, Ужас Награнда', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35070, 'ruRU', 'Вырубай!', 'Выведите из строя неисправный резонирующий кристалл в Элодорской шахте.', 'Землеройные существа, которых называют горенами, буквально заполонили наши копи. Судя по тому, что произошло у ворот, мне кажется, что мой резонирующий кристалл сводит местных зверей с ума.$b$bОтправляйся к Элодорской шахте на севере и отключи резонирующий кристалл!$b$bОднако будь $gосторожен:осторожна;, мои работники говорят, что рудник просто кишит этими тварями.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35071, 'ruRU', 'Безротый скрытиус', 'Принесите Мак\'джину 10 порций икры безротых скрытиусов, которые водятся в водоемах Горгронда.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Осмотри водоемы Горгронда и выясни, где можно хорошо порыбачить. Каждой пойманной рыбине надо будет вспороть брюхо и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35072, 'ruRU', 'Толстопузик', 'Принесите Мак\'джину 10 порций икры толстопузиков, которые водятся в водоемах Награнда.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Осмотри водоемы Награнда и выясни, где можно хорошо порыбачить. Каждой пойманной рыбине надо будет вспороть брюхо и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35073, 'ruRU', 'Слепой озерный осетр', 'Мак\'джин хочет, чтобы вы принесли икру 10 слепых озерных осетров, которые водятся в водоемах Долины Призрачной Луны.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Поищи в водоемах Долины Призрачной Луны рыбу, которая может нам пригодиться. Тебе придется распотрошить ее и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35074, 'ruRU', 'Хлыстохвост Черноводья', 'Принесите Мак\'джину 10 порций икры хлыстохвостов Черноводья, которые водятся в водоемах Таладора.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Осмотри водоемы Таладора и выясни, где можно хорошо порыбачить. Каждой пойманной рыбине надо будет вспороть брюхо и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35075, 'ruRU', 'Глубинный угорь-мешкорот', 'Принесите Мак\'джину 10 порций икры глубинных угрей-мешкоротов, которые водятся в водоемах на Пиках Арака.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Осмотри водоемы Пиков Арака и выясни, где можно хорошо порыбачить. Каждой пойманной рыбине надо будет вспороть брюхо и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35077, 'ruRU', 'Грибоцид', 'Используйте прижигатель земли QR58 и уничтожьте 20 споровых масс.', 'Ты $gвидел:видела; грибок в воде? Эта дрянь растет быстрее, чем детеныши равазавров в Ун\'Горо, так что если мы ее не выведем, Мастерскую будет уже не спасти, так же, как и нашу последнюю деревню.$b$bДядя Криксель всегда говорил, что надо выжечь красный грибок, потому что именно он отвечает за размножение.$b$bТы $gмог:могла; бы нам помочь. Возьми прижигатель и выжги хотя бы часть этого грибка на мелководье.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35079, 'ruRU', '\"Бесспорный\"', 'Активируйте 6 очистителей \"Бесспорный\".', 'У нас экстренная ситуация!$b$bСвора споровиков-скитальцев заполонила побережье и вывела из строя наши очистители \"Бесспорный\".$b$bЭто просто настоящая беда! Если мы снова не включим очистители, то эти споры мигом попадут прямо в город и история с Мысом Паросвистов снова повторится!$b$bНужно сходить туда и перезапустить очистители вручную.$b$bПоможешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35080, 'ruRU', 'Золотая жила', 'Встретьтесь с Кимзи Паросвист на месте крушения \"Золотой Жилы\".', 'У нас тут кризис! Наш дирижабль \"Золотая жила\" потерпел крушение в горах к югу отсюда.$B$BОн же отправлялся на самую обычную наблюдательную миссию! Ума не приложу, почему все сложилось так плохо!$B$BНам нужно быстро туда добраться, и без тебя мне не справиться.$B$BПоможешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35081, 'ruRU', 'Зачистка перед уборкой', 'Убейте $1oa |4багровокрылую осу:багровокрылых ос:багровокрылых ос;.', 'Давай поясню ситуацию.$b$bНужно как можно быстрее начать спасательную операцию, но, к сожалению, корабль попал буквально в осиное гнездо.$b$bПовсюду мельтешат эти гнусные насекомые, и пока они там, я не могу отправить спасательную команду.$b$bУбей как можно больше ос, а я за это возьму тебя в долю.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35082, 'ruRU', 'Спасение команды', 'Приведите в чувство 6 раненых членов экипажа.', 'Мать моя шахтер! Обломки разметало по всему склону! Если ничего не предпринять, то выжившие долго не протянут. Их нужно вылечить и НЕМЕДЛЕННО!$b$bВозьми мои бинты и помоги им. ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35083, 'ruRU', 'Прервать ритуалы', 'Уничтожьте ритуальные тотемы.', 'Клан Песни Войны более не желает быть единым целым со стихией – теперь он использует свою силу во зло, призывая тьму из Бездны.$B$BЯ не намерен молча смотреть на эти ритуалы. Найди ритуальные тотемы, которые клан Песни Войны использует для связи с Бездной, и уничтожь их.$B$BДар стихий был дан оркам не для того, чтобы осквернять его ради низких устремлений.', '', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35084, 'ruRU', 'Прервать зов', 'Убейте Кулрата и $2oa |4шамана:шаманов:шаманов; из клана Песни Войны.', 'Клан Песни Войны в своей жажде власти перешел на сторону тьмы и обратился к силам Бездны. Темный шаманизм – это порочное и опасное занятие, оскверняющее дар стихий, который я дал им.$B$BВ рядах Песни Войны есть тот, кто громче других взывает к Бездне – старейшина шаманов по имени Кулрат. Убей его и его темных шаманов.$B$BЯ не позволю клану Песни Войны осквернять стихии и наши традиции.', '', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35085, 'ruRU', 'Через Пустоту', 'Коснитесь маяка Пустоты, чтобы отправиться в Круговерть Пустоты.', 'Мы сорвали их ритуалы, но маяки Пустоты до сих пор активны...$b$bЭто может означать лишь одно – маяки подпитываются энергией из самой Круговерти Пустоты!$b$bИх связь с Пустотой должна быть разорвана! Единственный способ сделать это – уничтожить создание Бездны, которое поддерживает связь с нашим миром.$b$bЧтобы попасть в Круговерть Пустоты, коснись маяка ладонями. Как только окажешься по ту сторону, найди камень шаманов и с его помощью свяжись со мной.', '', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35086, 'ruRU', 'Марш Бездны', 'Уничтожьте $1oa |4ужасня:ужасней:ужасней; Бездны и $2oa |4щупальце:щупальца:щупалец; Бездны.', 'Скрытые покровом Круговерти Пустоты, обитатели Бездны движутся к Ошу\'гуну. Великая пустота, что заполняет гору, манит их, как пламя мотыльков.$B$BВолна за волной, эти существа движутся к горе и приносят себя в жертву повелителю Бездны Немощусу. Нельзя позволять ему пожирать другие создания Бездны, иначе он станет слишком силен, и мы его уже не остановим.', '', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35087, 'ruRU', 'Пустота подступает', 'Обрушьте $oa |4врата:врат:врат; Бездны.', 'Открыв порталы в Круговерть Пустоты, шаманы из клана Песни Войны, сами того не подозревая, запустили цепную реакцию.$b$bОглянись вокруг, и ты увидишь, как буквально повсюду открываются все новые и новые порталы – эти порталы зарождаются в Круговерти Пустоты и ищут точки выхода на Дреноре.$b$bЕсли они откроются, через них сюда хлынут несметные полчища демонов, созданий Бездны и прочей нечисти.', '', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35088, 'ruRU', 'Тень Бездны', 'Призовите и победите Немощуса.', 'Ну что, пришло время расправиться с повелителем Бездны. Но имей в виду, Немощус набирает силы с каждой минутой – поторопись, если хочешь его одолеть.$b$bВезде, где проходит ритуал клана Песни Войны, находится кристалл Бездны – через них в наш мир передается энергия из Круговерти Пустоты.$b$bЕсли дотронешься до кристалла, Немощус тотчас узнает о твоем появлении.$b$bБудь $gготов:готова; встретить его – потревожишь кристалл, Немощус сразу ринется в бой.', '', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', 'Ветер доносит до вас шепот Каландриоса.', 'Каландриос', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35089, 'ruRU', 'Снимая сливки', 'Соберите $1oa |4порцию:порции:порций; огнеопасного масла.', 'Ветролет бы нас отсюда вывез, но топливо все вышло!$b$bУ нас нет времени заниматься перегонкой нефти из местных скважин, тем более когда вокруг шастают все эти зараженные. Придется импровизировать.$B$BТут рядом с насосами ползают какие-то слизняки. Они наполнены высокоэнергетической смесью, которую можно сразу заливать в бак. Добудь эту смесь, и тогда у нас будут все шансы отсюда выбраться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35090, 'ruRU', 'Внимание к деталям', 'Выстрелите ракетой G-14 \"Задира\" по сломанным крошшерам, чтобы собрать исправные запчасти.', 'Дядя Криксель – крепкий малый, но со сломанной ногой он далеко не уйдет.$B$BУ него есть ветролет из Азерота, он может нас отсюда вывезти. Проблема в том, что там сломан двигатель.$b$bМне нужны запчасти для ремонта, а на окраине города стоят поломанные крошшеры, в которых есть необходимые детали. Разбирать их на части нет времени, так что возьми этот ракетомет и просто взрывай механизмы. А потом бери все детали, которые уцелеют, – нам они уж точно подойдут.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35091, 'ruRU', 'Спороцид', 'Убейте $1oa |4споровика-шаркуна:споровиков-шаркунов:споровиков-шаркунов; на Мысе Паросвистов.', 'Это просто отвратительно, омерзительно, и даже приводит в ярость!$b$bЯ говорю об этих споровиках, которые бродят по Мысу Паросвистов.$b$bМожет, убьешь несколько этих тварей, пока я занимаюсь машиной? Мне будет спокойнее, если я буду знать, что их стало чуть меньше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35093, 'ruRU', 'Темная сторона Луны', 'Найдите Нер\'зула.', 'Нам с Ирель удалось найти Нер\'зула. Он встречается с Громмашем Адским Криком на вершине самого высокого алтаря около Крепости Страданий.$B$BПриходи туда. Нам надо остановить его.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35095, 'ruRU', 'У реки', 'Поговорите с Дуротаном в Речном лагере.', 'Дуротан с большей частью наших сил отправился на запад. Он собирается организовать передовую базу у реки Небесной Песни.$B$BЕму непременно нужно сообщить, что мы уже практически полностью готовы двинуться на Громмашар.$B$BКроме того, ему наверняка пригодится твоя помощь, чтобы разделаться с орками клана Песни Войны в Лок\'рате.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35096, 'ruRU', 'Условия сдачи', 'Поговорите с Уруком Грозой Врагов в Лок\'рате.', 'Хорошие новости, командир: мы уже взяли Лок\'рат.$B$B<Вождь усмехается.>$B$BНаши солдаты взяли в плен большую часть бойцов клана Песни Войны, включая их командира, Урука Грозу Врагов.$B$BСчитаю, что честь принять его капитуляцию принадлежит тебе по праву. Иди, командир, тебя там ждут.', '', 'Договоритесь об условиях сдачи и приведите его в Речной лагерь.', 'Урук Гроза Врагов', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35097, 'ruRU', 'Гордость Лок\'рата', 'Убейте Урука Грозу Врагов.', 'Думаешь, Песню Войны так легко одолеть?$B$B<Внезапно вы слышите скребущий звук, будто веревкой трут по металлу.>$B$BМеня уже тошнит от вашей Орды, и вы только что вторглись в нашу родную землю.$B$B<Урук Гроза Врагов смотрит вам прямо в глаза, и звук становится громче.>$B$BКапитуляции не будет. Клан Песни Войны не склонится ни перед кем!', '', 'Убейте командира клана Песни Войны в Лок\'рате.', 'Урук Гроза Врагов', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35098, 'ruRU', 'Лок\'рат взят', 'Поговорите с Траллом в Вор\'варе.', 'Лишившись командира, бойцы клана Песни Войны уже не смогут оказать организованное сопротивление.$B$BКак только мы довершим разгром, мы покинем Лок\'рат и двинемся на Громмашар.$B$BЕсли ты собираешься возвращаться в Вор\'вар, сообщи Траллу, что совсем скоро мы будем готовы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35099, 'ruRU', 'Уничтожение боевых машин', 'Уничтожьте $1oa |4боевую машину Железной Орды:боевые машины Железной Орды:боевых машин Железной Орды;.', 'Железная Орда направила в Лок\'рат боевые машины из Гавани Железного Кулака. Если ничего не предпринять, скоро они сровняют Речной лагерь с землей.$B$BКто-то должен их остановить!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35100, 'ruRU', 'Если враг не сдается...', 'Уничтожьте $1oa |4врага:врагов:врагов; при Лок\'рате.', 'Это костяк нашей армии, которую мы собираемся отправить в поход на Громмашар против Гарроша Адского Крика.$B$BЕсли клан Песни Войны не сдастся, нам придется его уничтожить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35101, 'ruRU', 'Ужас Награнда', 'Заберите ошейник Шагора у Шагора.', '<Здесь лежит тело погибшего воина. На север от трупа ко входу в пещеру тянется кровавый след.>$B$B<Судя по леденящему душу вою, идущему из глубины логова, там обитает какая-то жуткая тварь.>', '', 'Достаньте ошейник Шагора. Не допустите, чтобы смерть того воина оказалась напрасной.', 'Шагор, Ужас Награнда', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35102, 'ruRU', 'Освобожденная сталь', 'Поговорите с Моркетом Воющим Мечом в Гордости Вол\'джина, что в Таладоре.', 'Спасибо, босс.$b$bЯ тебя не подведу! Я даже не стащил ни один из этих отвратительных клинков, которые кто-то из твоих батраков свалил прямо у клетки. Что, конечно же, было с его стороны большой оплошностью. Надо бы их убрать, а то другой узник может оказаться не столь щепетильным.$b$bНо хватит болтовни – давай смотреть, что тут да как!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35103, 'ruRU', 'Алхимик', 'Найдите Кадар в Костегаре.', 'Основам алхимии меня обучала моя кузина Кадар. Она – алхимик на аванпосте Каменного Клыка. Если ты хочешь углубить свои познания в алхимии, тебе следует обратиться к ней.$b$bОчень надеюсь, что она не погибла во время атаки.', '', '', '', '', '', 'Отыщите Кадар.', 25549);
INSERT INTO `quest_template_locale` VALUES (35104, 'ruRU', 'Ученичество', 'Уберите обломки и поговорите с Анг\'крой.', 'Последние слова Кадар... В хижине еще кто-то остался?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35106, 'ruRU', 'Месть и возвращение утраты', 'Прикончите убийцу Кадар и заберите книгу.', 'Я отомщу за свою наставницу и закончу труд всей ее жизни. Этого требуют законы чести. Этого жаждет мое сердце. Если я погибну сама – да будет так. Убийца заплатит за все.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35128, 'ruRU', 'Предупреждение', 'Убейте $1oa |4огрона-хребтолома:огронов-хребтоломов:огронов-хребтоломов; и Борогана.', 'Местные огроны не отличаются умом, но они гораздо разумнее гроннов. Они велики, а на деле – еще сильнее, чем кажутся.$B$BИх предводитель Бороган – особенно опасный противник. Мне за несколько боев так и не удалось убить его.$B$BПомяни мое слово, в их логове главное – осторожность.$B$BНиша готова отправиться в путь. Попроси ее доставить тебя к входу в пещеру – уверен, она с радостью согласится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35129, 'ruRU', 'Своих в беде бросаем', 'Найдите капрала Тукмара и заберите его бумаги.', 'Хм...$b$bУ огронов есть то, что представляет большую ценность для Железной Орды. Думаю, они этого даже не представляют. Скорее всего, им просто скучно, и они хотят кого-нибудь помучить.$b$bМне бы хотелось просто бросить их пленников на произвол судьбы – они это заслужили. Но мы не имеем права не воспользоваться полученной информацией. Если повезет, то мы помешаем Железной Орде превратить самых страшных животных Горгронда в свое оружие.$b$bПостарайся найти этого капрала Тукмара и его бумаги. Встретимся позже.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35136, 'ruRU', 'Железные цепи', 'Победите капитана Браку и найдите Сердце магнарона.', 'Артефакт почти у нас в руках.$b$bГотовься к битве. Если они действительно научились управлять гроннами, все может оказаться сложнее, чем я ожидал.$b$bЯ помогу тебе сражаться, когда будешь на месте.', '', '', 'Капитан Брака', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35137, 'ruRU', 'Бойцовская арена', 'Поговорите с рангари Йонаа на Верхнем Пути в Горгронде.', 'Мы обязаны тебе больше, чем свободой. Я поговорила с остальными: мы хотим вернуться вместе с тобой в твой гарнизон и научить жалких неумех, которых ты называешь \"солдатами\", как нужно сражаться.$b$bКроме того, мы сделаем все, чтобы передать наши знания тебе, командир. Если тебе понадобится помощь на просторах Горгронда, просто позови нас.$b$bВозможно, тебе стоит предупредить рангари Йонаа о том, что мы идем.', '', '', '', '', '', 'Поговорите с рангари Йонаа на Верхнем Пути в Горгронде.', 25549);
INSERT INTO `quest_template_locale` VALUES (35139, 'ruRU', 'Небесное око', 'Поговорите с Нишей.', 'В найденных тобой записках говорится об устройстве, которое может подчинить себе даже магнарона.$b$bВ древних легендах говорится о подобных артефактах, с помощью которых создатели мира держали этих существ в узде. Мне всегда казалось, что это просто дурацкие сказки, но если это правда...$b$b$n, Дренор обречен.$b$bНи одна армия не сможет остановить их. Мы должны помешать их планам или погибнуть.$b$bСейчас я сделаю так, чтобы мы смотрели на мир глазами Ниши. Будем надеяться, что ей удастся найти артефакт.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35140, 'ruRU', 'ТЕЛИН!', 'Поймайте $1oa |4малыша-горена:малышей-горенов:малышей-горенов;.', 'Ох уж этот мелкий!..$B$B<Ирель пытается удержать себя в руках.>$B$BТелин Темная Наковальня прислал нам груз. Там должны были быть детали для машин.$B$BНо когда мы открыли один из ящиков, оттуда выскочил малыш-горен. Знаешь, как они любят все ломать?$B$BИ, разумеется, этот малявка немедленно выпустил на свободу остальных.$B$BПоможешь мне отомстить?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35141, 'ruRU', 'Гореноносец прибыл', 'Доставьте переноску с малышами-горенами Телину Темная Наковальня на Телаарскую станцию.', 'Мы отомстим этому мелкому хорьку.$B$BПоложи малышей-горенов в переноску, а затем доставь этот \"особый груз\" Телину.', '', 'Подарите ему горенов.', 'Телин Темная Наковальня', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35142, 'ruRU', 'Нападение горенов!', 'Отбейте нападение горенов на ваш гарнизон.$B$B(Чтобы начать, еще раз поговорите с сержантом Зловещей Утробой.)', 'У нас земля дрожит под ногами, командир. Вот и разведчики не вернулись с задания. Я чувствую, что скоро на нас нападут – вот только откуда именно?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35143, 'ruRU', 'Кровь Пылающего Клинка', 'Убейте $1oa |4орка:орков:орков; клана Пылающего Клинка в Галлвалоре.', 'Галлвалор – это родина моего клана, Пылающего Клинка. Когда к власти пришел новый вождь и его семья, меня – полукровку – изгнали.$B$BЯ хочу, чтобы свершилось правосудие.$B$BИ думаю, что ты не откажешься ради этого пролить кровь. Правда, выбора у тебя все равно нет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35144, 'ruRU', 'Темные путы', 'Освободите $1oa |4духа:духов:духов; стихий.', 'В эту самую минуту бледнокожие в Ущелье Нависших Теней подчиняют стихии своей воле. Многие уже в их власти, и это только начало.$b$bБледнокожих необходимо остановить, а заодно спасти тех, кого еще можно.$b$bОтправляйся в Ущелье Нависших Теней и освободи тех духов стихий, что еще не до конца поддались бледнокожим. Ну а порабощенным мы можем помочь лишь одним – освободить, даровав им смерть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35145, 'ruRU', 'Бледная угроза', 'Убейте Серого Провидца и $2oa |4бледнокожего орка:бледнокожих орков:бледнокожих орков;.', 'Бледнокожие – это мерзкие существа, живущие под землей. Они постоянно строят козни тем, кто живет на поверхности. Одно из мест их обитания – Бледная Пещера. Это темное, запутанное подземелье под горой Ошу\'гун.$b$bЕсли мы хотим остановить Чо\'Галла, то нужно начать оттуда.$b$bОтправляйся в пещеру и разберись со всей этой нечистью, а также с их лидером – Серым Провидцем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35146, 'ruRU', 'Добрый доктор', 'Спасите доктора Хэдли Рикарда.', 'Биолога нашей экспедиции похитили стручлинги!$b$bДело было так: мы отправились в Награнд, чтобы исследовать земли, уничтожить могучего зверя и проявить храбрость, работая в одной команде с великим Хемингом Эрнестуэем.$b$bНо как только мы прибыли, охотничьи таланты Хеминга потребовались для битвы с кланом Песни Войны. Ну, мы не стали сидеть сложа руки и решили самостоятельно продолжить экспедицию!$b$bНо когда исследовали Чащу злобнолистов, на нас внезапно напали стручлинги! И во всеобщей суматохе утащили с собой доктора Хэдли.$b$bПрошу, помоги – нельзя оставлять его в плену!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35147, 'ruRU', 'Осколки прошлого', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35148, 'ruRU', 'Неприятности в Бастионе', 'Найдите рангари Элиину в Бастионе Мар\'гока.', 'Знаешь, мы отправили пару разведчиков, чтобы они разузнали все об этих здоровых, вонючих \"цивилизованных\" ограх в Бастионе Мар\'гока.$B$BИ с тех пор от них никаких вестей. На самом деле от них нет вестей с тех самых пор, как я спас твою шкуру в Телааре.$B$BУ тебя не найдется времени сгонять туда и выяснить, что с ними?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35149, 'ruRU', 'Бойцовская арена', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35150, 'ruRU', 'Неприятности в Бастионе', 'Найдите Акроша в Бастионе Мар\'гока.', 'Вчера я отправила двух лучших разведчиков разузнать все об ограх в Бастионе Мар\'гока.$B$BИ с тех пор от них никаких вестей.$B$B$n, сделай одолжение – выясни, что с ними. Думаю, ничего страшного не произошло, просто бастион очень уж огромный.$B$BОднако мне будет легче, если я буду знать, что у них все в порядке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35151, 'ruRU', 'Твоя база, твой выбор', 'Выберите, что построить на Звериной заставе: лесопилку или бойцовскую арену.', 'Ты уже $gпостроил:построила; отличный гарнизон на Хребте Ледяного Огня. Думаю, самое время принять важное решение.$b$bВ Горгронде есть богатая ресурсами область. Лесопилка придется как нельзя кстати.$b$bВ другом месте живет немало закаленных гладиаторов. Если построить бойцовскую арену, многие из них захотят сражаться на нашей стороне.$b$bТак или иначе, мы станем сильнее и сможем эффективнее противостоять Железной Орде.$B$BЧто ты выберешь, командир?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35152, 'ruRU', 'Бойцовская арена', 'Поговорите с Ногорвачом на Звериной заставе в Горгронде.', 'Мы обязаны тебе больше чем свободой. Я поговорил с остальными: мы хотим вернуться вместе с тобой в твой гарнизон и научить жалких неумех, которых ты называешь \"солдатами\", как нужно сражаться.$b$bКроме того, мы сделаем все, чтобы передать наши знания тебе, командир. Если тебе понадобится помощь на просторах Горгронда, просто позови нас.$b$bВозможно, тебе стоит предупредить Ногорвача о том, что мы идем.', '', '', '', '', '', 'Поговорите с Ногорвачом на Звериной заставе в Горгронде.', 25549);
INSERT INTO `quest_template_locale` VALUES (35153, 'ruRU', 'Событие: грибной претор', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35154, 'ruRU', 'Горе и горены', 'Убейте Камнезуба в шахте гарнизона.', 'Заброшенную шахту заполонили горены! Похоже, они подчиняются какому-то здоровяку, который сидит в глубине шахты. Если его убить, то остальные наверняка разбегутся.$b$bА потом мы сможем возобновить работы в этой шахте!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35155, 'ruRU', 'Уничтожение огров', 'Убейте $1oa |4огра:огров:огров; в Бастионе Мар\'гока.', 'Огры кидаются не валунами, а заклинаниями? Вот это новость!$b$bЭти новые огры особенно наглые и постоянно понукают рабочих.$b$bА ты знаешь, какой лучший способ погасить рабочий энтузиазм? Убить энтузиаста.$b$bПрикончи несколько огров, чтобы в лагере снова воцарилась обычная повседневная скука.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35156, 'ruRU', 'Бумажная работа', 'Уничтожьте $1oa |4ящик:ящика:ящиков; с исследованиями огров в Бастионе Мар\'гока.', 'Коробка набита текстами и рисунками, которые очень напоминают исследования по нейтрализации магии. Пожалуй, стоит сорвать эту работу, уничтожив все записи подобного рода.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35157, 'ruRU', 'Приказы огров о наступлении', 'Достаньте приказы Крулгорошу и Тулгорку в Бастионе Мар\'гока.', 'Очевидно, утес наверху для огров очень важен. Оттуда недавно спустились два огра-мага и стали раздавать остальным приказания.$b$bРаздобудь мне приказы, которые должны быть при них, а затем отыщи на утесе моего разведчика Долгорша. Ему эта информация придется очень кстати.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35158, 'ruRU', 'Исследование Реглакка', 'Остановите исследования великого магистра Реглакка.', 'Короче, тема такая: некий Реглакк занимается исследованиями – типа, из простых огров делает суперогров, которых называют Разрушителями. Дело пахнет керосином.$b$bКак думаешь, ты сможешь $gодин:одна; остановить этого Реглакка? Меня тут так отделали, что от меня толку никакого.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35159, 'ruRU', 'Уничтожение подкреплений', 'Уничтожьте портал в крепость Верховного Молота.', 'Все плохо, $p. Эти хитрецы-огры открыли здесь портал, и через него сюда прибывают огры откуда-то еще. Но вроде как на поддержание этого портала у них уходит куча ресурсов. Если ты прикроешь этот портал, это должно изрядно их задержать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35162, 'ruRU', 'Сокровище: гнездо дубравного долгонога', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35166, 'ruRU', 'Обломки корабля', 'Соберите $1oa |4ящик:ящика:ящиков; вещей с боевого корабля.', 'Командир, у нас заканчиваются припасы.$b$bМожет быть, получится спасти что-нибудь с корабля, на котором мы прибыли?$b$bУчитывая, с какой скоростью народ прибывает из портала, еда у нас закончится еще до захода солнца... или луны?$b$bЯ все никак не привыкну к этому месту.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35167, 'ruRU', 'Затерянная в Награнде', 'Отыщите Ольгру, подругу Манкрика.', 'Эй, $gмистер:сударыня;, не поможешь мне?$B$BУ меня есть одна знакомая. Ее зовут Ольгра. Она с родителями вчера отправилась назад в Вор\'вар. Только до места они не добрались, и никто не знает, где они и что с ними.$B$BЕсли тебе не сложно, может, поищешь ее?$B$BОна, можно сказать, моя подруга.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35168, 'ruRU', 'Первый заказ для кузницы', 'Сделайте свой первый заказ для кузницы, затем заберите готовую продукцию.', 'Теперь у тебя есть кузница, и мы можем начать производство слитков истинной стали. Как только добудешь нужные материалы, поговори с моей помощницей, и мы начнем работу над первой партией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35169, 'ruRU', 'Правосудие для Тралла', 'Поговорите с воздаятельницей Ирель у Ворот Громмашара и возглавьте атаку на клан Песни Войны.', 'Сейчас самое время, командир. Тебе удалось разгромить всех союзников клана Песни Войны.$B$BУ ворот Громмашара стоят наши войска. Из надежных источников рангари получили сведения о том, что Гаррош находится в крепости клана Песни Войны.$B$BМы так долго шли к этому. Давай уничтожим Гарроша.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35170, 'ruRU', 'Одержимая возмездием', 'Убейте Воргошкура Дикого.', 'Они... они будто из воздуха появились. Вон оттуда.$B$B<Девочка, не переставая рыдать, указывает рукой куда-то на запад.>$B$BОни примчались на своих страшных волках.$B$BПожалуйста, командир... это же касается моей семьи. Ты отомстишь им за нас?', '', 'Отомстите этому орку из клана Песни Войны за то, что он сделал с семьей Ольгры.', 'Воргошкур Дикий', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35171, 'ruRU', 'Правосудие для Тралла', 'Поговорите с Дуротаном у Ворот Громмашара и возглавьте атаку на клан Песни Войны.', 'Сейчас самое время, командир. Тебе удалось разгромить всех ближайших союзников клана Песни Войны.$B$BУ ворот Громмашара сосредоточены наши войска. Темные охотники получили сведения из надежных источников о том, что Гаррош скрывается в крепости Песни Войны.$b$bМы долго шли к этому. Так покончим же с ним раз и навсегда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35174, 'ruRU', 'Бледный лунный свет', 'Убейте Острозуба Кровоискателя и $2oa |4бледнокожего пожирателя:бледнокожих пожирателей:бледнокожих пожирателей;.', 'Мы получили сообщение, что какие-то странные орки напали на поселение дренеев под названием \"Причал Вечерней Зари\".$b$bГоворят, эти орки не похожи на тех, с кем мы имели дело раньше.$b$bОни какие-то... болезненные, бледнее других.$b$bМестным нужна наша помощь, командир. Кроме того, это отличная возможность испытать, на что годится наш гарнизон.', '', '', 'Острозуб Кровоискатель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35176, 'ruRU', 'Все под контролем', 'Поговорите с Шелли, отыщите помощницу Яркий Камень и проверьте содержимое гарнизонного склада.', 'Столько дел, столько дел... Я даже не знаю, за что взяться сначала.$b$bПоддерживать работу всего гарнизона – дело непростое!$b$bШелли до сих пор не вернулась ко мне с докладом, моя помощница Яркий Камень и ее группа тоже как сквозь землю провалились, уф... Я совсем забегался, даже не успел проверить, остались ли ресурсы на складе.$b$bЖалко, что я не маг – а то бы сделал дюжину копий себя и разом со всеми делами управился.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35185, 'ruRU', 'Гарнизонная кампания: Саргераи', 'Поговорите с верховным магом Модерой на Плато Сокретара в долине Призрачной Луны.', 'Приветствую, $n.$B$BУ верховного мага Кадгара есть для тебя важное сообщение.$B$BДренеев постигло великое предательство – оказалось, что экзарх Отаар заодно с Легионом.$B$BВ холмах над долиной Призрачной Луны Отаар, который сейчас называет себя \"Сокретаром\", собирает новобранцев.$B$BЭтой операцией руководит верховный маг Модера, ей потребуется твоя помощь.$B$BВстреться с ней, и она введет тебя в курс дела.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35186, 'ruRU', 'Гарнизонная кампания: Саргераи', 'Поговорите с Броном Небесным Рогом, чтобы отправиться в долину Призрачной Луны.', 'Приветствую, $n.$B$BУ верховного мага Кадгара есть для тебя важное сообщение.$B$BДренеев постигло великое предательство – оказалось, что экзарх Отаар заодно с Легионом.$B$BВ холмах над долиной Призрачной Луны Отаар, который сейчас называет себя \"Сокретаром\", собирает новобранцев.$B$BЭтой операцией руководит верховный маг Модера, ей потребуется твоя помощь.$B$BВстреться с ней, и она введет тебя в курс дела.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35187, 'ruRU', 'Внедрение в ряды саргераев', 'Найдите саргерайское одеяние, саргерайский клобук и саргерайские туфли, чтобы замаскироваться под саргерайского послушника. Наденьте маскировку, после чего поговорите со стражницей душ Замайей, а затем с анахоретом Лаандой.', 'Один из моих агентов уже проник в ряды саргераев, но мне нужно, чтобы ты ему $gпомог:помогла;.$B$BЧтобы не раскрыть его, ты $gдолжен:должна; замаскироваться под врага.$B$BУбивай саргераев до тех пор, пока не найдешь клобук, одеяние и туфли – тогда у тебя будет отличная маскировка.$B$BНадень все это и скажи стражнице душ Замайе, что ты $Gновый ученик:новая ученица;, а потом шепни анахорету Лаанде: \"На Призрачную Луну пролился дождь\".$B$BЭто пароль, по которому станет ясно, что ты – друг.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35188, 'ruRU', 'Мерзкие стручлинги', 'Соберите 8 деревянных копий.$B$BЕсли вы утратите маскировку под саргерайского послушника, убивайте саргераев, чтобы добыть саргерайский клобук, саргерайское одеяние и саргерайские туфли и изготовить новую маскировку.', 'А, $Gновичок:новенькая;. $GГотов:Готова; выполнить свое первое задание?$B$BВ лесах к югу отсюда полно мерзких стручлингов. Они постоянно перекапывают поля на наших фермах, крадут припасы и нападают на неосторожных учеников.$B$BЭто мерзкие и жуткие существа, и их надо уничтожить.$B$B<Замайя скептически смотрит на вас.>$B$BВ доказательство принеси мне их копья.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35189, 'ruRU', 'Слово Сокретара', 'Прочтите \"Предназначение эредаров\", \"Цель единства\" и \"Обещание вечности\".', 'Саргераи – фанатичные последователи Сокретара. Насколько я понимаю, он сильный лидер и умеет убеждать.$B$BМногие послушники носят с собой его книги.$B$BПрочти их, а затем возвращайся и доложи мне. Нужно понять, что движет саргераями. Возможно, эти знания нам помогут.$B$BЯ видел книги у озера, на столе у фонтана и в доме, что неподалеку от садов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35190, 'ruRU', 'Древняя угроза', 'Убейте Старомоха.$B$BЕсли вы утратите маскировку под саргерайского послушника, убивайте саргераев, чтобы добыть саргерайский клобук, саргерайское одеяние и саргерайские туфли и изготовить новую маскировку.', 'В лесу на северо-востоке отсюда поселился древний.$B$BКто-то должен с ним разобраться.$B$BТы справишься. Это достаточно простое задание даже для $gпослушника:послушницы;.', '', '', 'Старомох', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35191, 'ruRU', 'Разбить врага', 'Уничтожьте 6 кристаллов Бури Скверны.', 'Пока ты делаешь вид, что подчиняешься приказам Замайи, мы устроим диверсию прямо у саргераев под носом.$B$BЗдесь повсюду можно отыскать кристаллы Бури Скверны. Противники используют их, чтобы приумножить свои силы.$B$BУничтожь эти кристаллы, чтобы выиграть время.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35192, 'ruRU', 'Подкрепление!', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35194, 'ruRU', 'Борьба с демонами', 'Победите Призванного и уничтожьте врата демонов.', 'Время на исходе, $n. Саргераи открыли портал призыва на холме, что к западу отсюда.$B$BПохоже, они собираются воспользоваться этим порталом, чтобы привести в долину Призрачной Луны армию демонов.$B$BМы должны помешать им любой ценой. Возьми эту чародейскую бомбу и уничтожь портал.$B$BДа, мы можем выдать себя, но сейчас уничтожение портала куда важнее, чем выполнение задания.', '', '', 'Призванный', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35195, 'ruRU', 'Ярость Сокретара', 'Бросьте вызов Сокретару, а затем заберите военные планы саргераев у стражницы душ Замайи.', '<Развернув свиток, вы обнаруживаете, что в нем – сообщение от анахорета Лаанды.>$B$B\"$n, пишу второпях. Меня разоблачили. Вызывают к Сокретару.$B$BНаказанием за преступление непременно будет смертная казнь, но не волнуйся. Ты $gдолжен:должна; воспользоваться этой возможностью, чтобы узнать как можно больше от самого Сокретара.$B$BСтражница душ Замайя по-прежнему тебе доверяет. Ты сможешь войти в главное здание.$B$BРаботать с тобой было честью для меня.\"', '', '', 'Стражница душ Замайя', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35196, 'ruRU', 'Продвижение вперед', 'Вернитесь к слуге Кадгара в свой гарнизон.', '<Голос анахорета Лаанды еле слышен.>$B$BДоложи... Кадгару.$B$BСокретар хочет захватить Шаттрат. Он будет и дальше... искать соратников...$B$BСпасибо... что $gпомог:помогла;... в мой последний час...$B$BОставь меня... Мне надо побыть одному...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35197, 'ruRU', 'Продвижение вперед', 'Вернитесь к слуге Кадгара в свой гарнизон на Хребте Ледяного Огня.', '<Голос анахорета Лаанды еле слышен.>$B$BДоложи... Кадгару.$B$BСокретар хочет захватить Шаттрат. Он будет и дальше... искать соратников...$B$BСпасибо... что $gпомог:помогла; мне... в мой последний час...$B$BОставь меня... Мне надо побыть одному...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35201, 'ruRU', 'Krixel', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35202, 'ruRU', 'Закни меня, ладно?', 'Добудьте $1oa |4панцирь горена:панциря горенов:панцирей горенов; с проглотов Костяного двора.', 'Волшебство Зака позволит тебе совершать великие дела, но сначала нужно подготовиться, чтобы духи даровали нам свою силу.$b$bЗаку нужно много панцирей этих мерзких горенов. Зак расскажет тебе, как их добыть.$b$bПодойди к их туннелям, и тогда горены хлынут толпой наружу. Тогда ты сможешь убить сразу много.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35204, 'ruRU', 'Сила пыльцы', 'Найдите $1oa |4щепотку:щепотки:щепоток; концентрированной пыльцы.', 'Цветы ботани опыляют огромные насекомоподобные создания.$b$bПыльца, которую переносят эти твари, обладает различными ценными свойствами и может пригодиться войскам твоего гарнизона.$b$bЕсли ты принесешь мне этой пыльцы, я переработаю ее во что-нибудь полезное.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35205, 'ruRU', 'Сжечь тела', 'Сожгите $1oa |4труп:трупа:трупов; для удобрения.', 'Ты не понимаешь. Все, что этим ходячим растениям не удается заразить, они откармливают и превращают в удобрения.$B$BПредлагаю отнять у них источник еды.$B$BЯ видел поблизости несколько трупов. Думаю, их надо сжечь.$B$BЗаодно проверим, смогут ли они заразить пепел.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35206, 'ruRU', 'Вырубка зарослей', 'Убейте $1oa |4ткача:ткачей:ткачей; цветения.', 'Мы продолжаем поиски подопечных Телина, но эти ботани... Они куда опаснее, чем мы думали.$B$BЗаражать свою жертву... бррр... ужасно.$B$BПожалуйста, командир, если ты окажешься в Ключах Вечного Рассвета к западу отсюда, убей как можно больше этих существ.$B$BПора положить конец их злодеяниям. Кто-то должен свершить правосудие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35207, 'ruRU', 'Месть Угледроба', 'Убейте $1oa |4хозяина росы:хозяев росы:хозяев росы;.', 'Я так объелся, что не смог бы даже топор поднять, будь он у меня под рукой.$b$bСлушай, а ведь мы можем помочь друг другу. Ты отомстишь за меня тем здоровенным ботани, что прячутся в самой глуши. А за это я расскажу, где эти зеленые переростки хранят свое секретное оружие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35208, 'ruRU', 'Невзгоды Черного Железа', 'Найдите Копения Угледроба в Ключах Вечного Рассвета.', 'Пока тебя не было, рангари нашли пару зацепок, по которым можно найти моих друзей.$b$bКопения Угледроба и Горелую Бровь.$b$bНо дело в том, что все следы ведут на запад – к Ключам Вечного Рассвета.$b$bПожалуйста, командир, очень прошу – пойди туда и спаси их.', '', '', '', '', '', 'Найдите Копения Угледроба в Ключах Вечного Рассвета.', 25549);
INSERT INTO `quest_template_locale` VALUES (35209, 'ruRU', 'Источник жизни', 'Наберите воду Утрофиса.', 'Пришли мы сюда, значит, за оружием, которое мы видели у ботани.$b$bГензель достал артефакт, а мы с Горелой Бровью должны были раздобыть особую воду, на которой эта штука работает.$b$bТолько мы не знали, что если в воде полным-полно жизненных сил, то из нее образуется элементаль.$b$bЗагляни в котел у основания того милого древнего артефакта в Ключах Вечного Рассвета – и найдешь это чудовище. Надо убить его и забрать его воду, она понадобится, когда мы достанем остальные части артефакта. ', '', 'Проявление живой воды.', 'Утрофис', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35210, 'ruRU', 'Великий побег', 'Расчистите туннель горенов и пройдите по нему, чтобы встретиться с Рексаром у Провала Ярости.', 'Туннель горенов!$b$bКак только путь наверх будет расчищен, вы сможете выбраться из этой забытой Светом ямы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35211, 'ruRU', 'Профилактика', 'Разместите $1oa |4огнебомбу:огнебомбы:огнебомб; на Мысе Паросвистов.', 'Нет, ты $Gвидел:видела;, сколько грибов выросло на домах на Мысе Паросвистов? Рано или поздно они понавыпускают столько спор, что заразят все живое на побережье!$B$BЗараженных на Мысе Паросвистов спасать уже поздно, чего уж тут говорить. Поэтому давай так – проявим сострадание и избавим несчастных от мучений, пока эпидемия не зашла слишком далеко.$B$BНа вот тебе несколько огнебомб – они сожгут грибы, но ты $Gдолжен:должна; будешь разместить их в подходящих местах, пока я ставлю детонаторы.$B$BНу, что скажешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35212, 'ruRU', 'Глубокорень', 'Встретьтесь с Телином Темной Наковальней в Глубокорне.', 'Теперь, когда тут все готово к расчистке от кустов и деревьев, я хочу попросить об одной услуге.$b$bМне нужно найти своих товарищей из клана Черного Железа, которые направлялись сюда. Так вышло, что мы разминулись.$b$bЯ пойду искать их к югу отсюда. Правда, юг так и кишит всякими ботани, стручлингами, гигантскими деревьями и прочими злобными растениями.$B$BВот материалы с лесопилки придутся как нельзя кстати. Если ты мне поможешь найти своих, то обещаю, что мы в долгу не останемся.', '', '', '', '', '', 'Встретьтесь с Телином Темной Наковальней в Глубокорне.', 25549);
INSERT INTO `quest_template_locale` VALUES (35213, 'ruRU', 'Терновое Цветение', 'Выясните, где находятся Лера Углепалец, Нори Копченый Ус и Гуляйбород.', 'Каайла считает, что напала на след. Похоже, несколько дворфов отправились на север к Терновому Цветению.$b$bНо есть одна проблемка – там куча траволюдей. А от меня в бою с ними никакой пользы. Не хочешь $gсам:сама; сходить и узнать, что там произошло?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35214, 'ruRU', 'Зараженные', 'Убейте $1oa |4зараженного:зараженных:зараженных;.', 'Д\'каан этого не сказал, но на самом деле ботани забрали куда больше рангари, чем ты $gнашел:нашла;.$B$BОн решил, что их убили. А я боюсь, что все куда хуже.$B$BЕсли нелегкая занесет тебя в Терновое Цветение, увидишь, что ботани делают со своими... \"пленниками\".$B$BОсвободи эти бедные души.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35215, 'ruRU', 'Глас Ию', 'Убейте Глас Ию.', 'Запись 25:$b$bУ ботани есть свой предводитель. Его зовут... Ее зовут... Это зовут Глас Ию.$b$bСудя по всему, ботани считают генезотавров богами, и лишь самые почтенные ботани имеют право говорить от их имени.$b$bКак только мы начали расспрашивать об артефакте, который нашли на базе, ботани разгневались, а Леру с Нори куда-то увели. С тех пор я их не видел.$b$bЧто-то у меня плохое предчувствие.', '', 'Он говорит от имени генезотавра.', 'Глас Ию', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35216, 'ruRU', 'Суперсемена', 'Соберите обогащенные семена.', 'Ботани заботливо защитили эти семена.$B$BЭти маленькие сосуды жизни излучают великую энергию.$B$BОни могут нам пригодиться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35218, 'ruRU', 'Приказы Железной Орды', 'Ищите приказы по вооружению в лагере Железной Орды в последнем приюте Клыколома.', 'Дух видел приказы Железной Орды в их лагере на утесе неподалеку. Должно быть, ты их тогда не $gзаметил:заметила;. Можешь сходить еще раз?', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35219, 'ruRU', 'Событие: Пылающий Фронт', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35220, 'ruRU', 'Событие: Харазос Победоносный', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35221, 'ruRU', 'Хранитель', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35225, 'ruRU', 'Ручища помощи', 'Найдите выживших дворфов из клана Черного Железа.', 'Копений сообщил нам координаты базы клана Черного Железа. Они назвали ее Бастионом Мойры.$b$bТолько вот достроить ее до конца так и не успели – к ним заявились горены.$b$bЕсли отправишься отсюда на юг, то рано или поздно выйдешь к этой базе. Ищи огромную пушку.$b$bМы двинемся следом – как только откопаем этот проклятый танк.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35226, 'ruRU', 'Прежде друзья, теперь враги', 'Бросьте вызов Оргриму Молоту Рока в деревне на Орунайском берегу.', 'Не могу поверить, что Оргрим по-прежнему служит Черноруку – даже после того, какое разорение он учинил.\n\nМы должны бросить ему вызов. Встретимся в деревне на Орунайском берегу и разыщем моего старинного друга.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35227, 'ruRU', 'Дипломатия огров', 'Убейте $1oa |4духа огров или питомцев:духов огров или питомцев:духов огров или питомцев; клана Анго\'рош в руинах Анго\'рош.', 'Огры есть огры. Духи они или нет, эти ангорошцы ничуть не отличаются от остальных.$B$BЧтобы заручиться их помощью, одних книг ритуалов недостаточно – ты $gдолжен:должна; показать себя в деле.$B$BЯ всю жизнь сражаюсь с ограми и знаю, что заслужить их уважение можно только одним способом.$B$BУбивая.$B$BЧем больше ангорошцев и их питомцев ты уничтожишь, тем выше будет твоя репутация.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35229, 'ruRU', 'Вниз, по горенской норе', 'Убейте $1oa |4горена:горенов:горенов; в Бастионе Мойры.', 'Эти твари так стремительно на нас напали, что у нас не было времени подготовиться к обороне. Они сразу бросились к нашим запасам металла, прогрызая по дороге стены.$b$bЕсли не убьем хотя бы часть из них как можно быстрее, они обрушат крепость.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35231, 'ruRU', 'Дела духовные', 'Поговорите с духами в Землях Предков.', 'Ошу\'гун давно притягивает к себе души умерших.$b$bСколько себя помню, эти леса всегда были переполнены призраками, бредущими к горе.$b$bОднако я чувствую, что в этих лесах поселилась какая-то тьма, нечто, призывающее сонмы призраков. Боюсь, то, что мы видим, не обычное паломничество.$b$bДоберись до Земель Предков и попроси у духов наставления.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35232, 'ruRU', 'Зов Ошу\'гуна', 'Отправьтесь в Леса Духов.', '$n, стихии сказали свое слово, и нам было видение.$b$bВместе мы отправимся к великой горе Ошу\'гун и там уничтожим источник тьмы.$b$bЕсли видение истинно, то нас ждут страшные испытания.$b$bЯ встречу тебя в Лесах Духов, у подножия Ошу\'гуна. Когда будешь $gготов:готова; отправиться в путь, поговори с Гиксмо Гонимани, и он отвезет тебя туда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35233, 'ruRU', 'На всякий случай', 'Собирайте по пути вниз роковые снаряды.', 'Когда мы тут обосновались, то первым делом соорудили пушку. Решили, что тут ей самое место.$b$bПотом стали возводить вокруг нее базу, и вдруг в один прекрасный день из-под земли вылезли эти плюющиеся кислотой паразиты.$b$bПлюс в том, что пушка уже готова, только не заряжена.$b$bНам все равно нужно спуститься на нижний этаж, так что по дороге можешь прихватить роковых снарядов, если они тебе попадутся.$b$bЛучше зря зарядить пушку, чем не зарядить, а потом об этом пожалеть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35234, 'ruRU', 'Воля генезотавра', 'Найдите Волю генезотавра.', 'Когда нас атаковали горены, мы отбивались как могли, но они все напирали и напирали.$b$bТогда наши парни отправились к ботани и стащили у них какой-то хитроумный артефакт.$b$bНо тут возникла новая проблема – мы не смогли его использовать. Артефакт сейчас находится на нижних ярусах бастиона. Чтобы его добыть, нужно пройти по туннелям, мимо всех этих горенов, а затем по самому крошечному туннелю, который ведет еще глубже.$b$bЕсли достанешь его, можешь забрать себе.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35235, 'ruRU', 'Ию', 'Победите Ию.', 'Слышишь?$b$bПохоже, генезотавр хочет получить свою \"волю\" обратно. Я же говорил – от этой штуки одни беды.$b$bСейчас заряжу пушку и попробую немного успокоить эту тварь. Но ты лучше сбегай и $gсам:сама; разберись с ней... ', '', 'Генезотавр уже здесь.', 'Ию', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35236, 'ruRU', 'Орунайский берег', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35237, 'ruRU', 'Лесозаготовки Мор\'грана', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35238, 'ruRU', 'Новый владелец', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35239, 'ruRU', 'Новый владелец', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35240, 'ruRU', 'До последней капли', 'Освободите рабов из двух клеток клана Кровавой Глазницы в Крови Сердца.', '<Дреней буквально выплевывает свои последние слова.>$b$bОни бросили нас в клетки. Они высасывают из нас кровь... для своих ритуалов...$b$b<Он заходится кашлем.>$b$b...осталось...$b$b...моих... собратьев...$b$b<Дреней умирает.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35241, 'ruRU', 'Месть за павших', 'Убейте 6 орков клана Кровавой Глазницы.', 'Слишком много моих сородичей было убито кланом Кровавой Глазницы. Такую жестокость простить нельзя.$b$b<Скорбящая орчиха останавливает взгляд на вас.>$b$bЗаставь их заплатить за это.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35242, 'ruRU', 'Месть за павших', 'Убейте 6 орков клана Кровавой Глазницы.', 'Слишком много моих сородичей убито кланом Кровавой Глазницы. Такую жестокость простить нельзя.$b$b<Скорбящая дренейка останавливает взгляд на вас.>$b$bЗаставь их заплатить за это.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35243, 'ruRU', 'Дар Темной госпожи', '', '', '', 'На\'Шра, только что получившая звание мастера клинка, – грозная воительница.', 'Мастер клинка На\'Шра', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35244, 'ruRU', 'Событие: Скэгг', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35245, 'ruRU', 'Памятная реликвия', 'Отнесите дар Литик Решаду в Гнездовье Терокк.', 'Веками браслет моего отца лежал здесь, пока самозванец Айкисс не украл его.$B$BЯ благодарна тебе за этот браслет, однако он мне не нужен. Прими его вместе с моим благословением.$B$BЕсли еще остались жрецы Когтя, верные истинному Королю воронов, отнеси его им. ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35247, 'ruRU', 'А нам по Заку', 'Поговорите с Костяным Заком и станьте свидетелем того, как он общается с Гро Изничтожителем.', 'Духи говорили со мной. Они полагают, что магнарон Гро Изничтожитель присоединится к нам и поведет своих последователей против Железной Орды.$b$bТакой чести не удостаивался ни один Веселый Череп – по крайней мере, в мое время.$b$bЯ поговорю с магнароном, и вместе мы уничтожим Железную Орду.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35248, 'ruRU', 'Суровое напоминание', 'Убейте $1oa |4обитателя:обитателей:обитателей; пустоши на Хребте Скорби.', '$gИноземец:Чужестранка;, добро пожаловать в место, где пустоши встречаются с джунглями.$B$BКогда враги начинают забывать о том, как свиреп может быть Веселый Череп, мы всегда рады освежить им память.$B$BЗдесь выживает только самый жестокий и беспощадный. В Горгронде по-другому никак.$B$BПрисоединяйся к нам! Посмотрим, долго ли ты протянешь в этих краях.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35249, 'ruRU', 'Усиление защиты', 'Найдите стражницу душ Туулани в Гробнице Света.', 'Приятно видеть, что в бой вступает защитник Орды.$B$BОборона Аукиндона рушится на глазах. Большинство аукенайских жрецов душ на передовой.$B$BCтражница душ Туулани отправилась в ближайшую Гробницу Света, чтобы добыть запасной пилон силы, но до сих пор не вернулась. Пожалуйста, найди ее и доставь сюда вместе с пилоном.', '', '', '', '', '', 'Найдите стражницу душ Туулани в Гробнице Света.', 25549);
INSERT INTO `quest_template_locale` VALUES (35251, 'ruRU', 'Награда Камнерогов', 'Возьмите свою долю добычи из сундука Дуротана.', 'Разграбление этой крепости – наша общая победа. Будет справедливо выделить тебе часть добычи.\n\nЯ прикажу подготовить для тебя сундук. Бери, что хочешь.', '', '', '', '', '', 'Поговорите с Дуротаном.', 19865);
INSERT INTO `quest_template_locale` VALUES (35252, 'ruRU', 'Сундук в награду – отслеживание задания', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35253, 'ruRU', 'ФЛАГ: Телин: событие завершено', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35254, 'ruRU', 'Воздаяние Света', 'Убейте $1oa |4демона:демонов:демонов; в Гул\'роке.', 'Шпионы тьмы окружают нас и всеми силами стараются захватить мир. Мы – последняя надежда Света на сохранение равновесия.$B$BТебе хватит сил, чтобы уничтожить демонов-слуг Терон\'крова раз и навсегда. Сокруши их и отправь в Круговерть Пустоты!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35255, 'ruRU', 'Мощь генезотавра', 'Поговорите с воздаятелем Мараадом на Верхнем Пути в Горгронде.', 'Командир, теперь у тебя есть \"Воля генезотавра\", а также воды сотворения и семена – то есть все, что нужно для создания армии. Не говоря уже о том, что тебе удалось спасти жизни дворфов.$b$bПо-моему, твое задание можно считать выполненным.$b$bЯ помогу дворфам собрать все, что можно спасти, и покинуть базу. А ты тем временем можешь отнести артефакт Марааду на аванпост.', '', '', '', '', '', 'Поговорите с воздаятелем Мараадом на Верхнем Пути в Горгронде.', 25549);
INSERT INTO `quest_template_locale` VALUES (35257, 'ruRU', 'Глубинная сила', 'Поговорите с темным провидцем Раастоком рядом с раскопками города апекситов.', 'Что за сила может испепелить целую деревню в мгновение ока? Приверженцы утверждают, что такую силу дает им воля Рухмар.$B$BОчевидно, что это ложь.$B$BОни ничем не заслужили такую силу – строго говоря, они обнаружили ее случайно.$B$BПриходи к месту раскопок, что к западу отсюда, – там мы и поговорим. Чтобы победить врага, надо раскрыть его тайны.', '', '', '', '', '', 'Поговорите с темным провидцем Раастоком рядом с раскопками города апекситов.', 25549);
INSERT INTO `quest_template_locale` VALUES (35258, 'ruRU', 'Наследие апекситов', 'Соберите $1oa |4солнечное ядро:солнечных ядра:солнечных ядер; со стражей апекситов.', 'Апекситы давно исчезли, но их наследие сохранилось в древних камерах под поверхностью Арака.$B$BЛегионы спящих конструктов, кристаллы, наполненные до краев солнечной энергией, давно забытые магические методы – после апекситов остались сокровищницы, в которых скрыта невероятная сила, и приверженцы Рухмар только приступили к их раскопкам.$B$BГолемы, которых выкопали Приверженцы, патрулируют площадку раскопок неподалеку. Принеси мне их сердечники, они полны мощи, они – ключ к разрушительной силе врага.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35259, 'ruRU', 'Солнечные сестры', 'Убейте солнечных ваятельниц Веорикс и Краксис.', 'Во время службы крылатым стражем в Небесном Пути я должен был охранять двух сестер, Веорикс и Краксис.$B$BОни были необычайно одаренными. В том возрасте, когда большинство послушников едва умели читать, сестры уже призывали фамилиаров из чистого солнечного света, чтобы те по ночам освещали страницы учебников.$B$BА теперь сестры разгадывают тайны технологии апекситов и уже прорубили вход в два древних покоя.$B$BВойди в эти покои и убей сестер, пока они не воспользовались ужасными плодами своего открытия.', '', 'Солнечные ваятельницы-близнецы.', 'Веорикс и Краксис', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35260, 'ruRU', 'Тяжелая работа', 'Используйте иллюзорные чучела, чтобы спасти $1oa |4порабощенного изгоя:порабощенных изгоев:порабощенных изгоев;.', 'Тех, кто не сгорел заживо в Гнездовье Акраз, заставляют раскапывать для Приверженцев оружие, чтобы потом использовать его против них же.$B$BВсех, кто пытается бежать, расстреливают из турели апекситов.$B$BНо если мы подсунем им чучела, о побеге не сразу догадаются. Просто поставь такое чучело рядом с каждым из этих бедняг – и она превратится в его идеального двойника! Заклинание даже замаскирует невольника, давая ему возможность ускользнуть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35261, 'ruRU', 'Управление огнем', 'Заберите пульт управления от турели апекситов у надзирателя Акрата.', '<По мере того как поток солнечной энергии проходит по спящим големам, вокруг вас эхом раздается гудение древних сервоприводов. Пытаться их выключить уже поздно.$B$BСнаружи выкрикивает команды араккоа-надсмотрщик, и на каждую его реплику отвечает гул турели апекситов, которая бурит породу.$B$BЭта турель быстро разберется с конструктами – если вы сможете ею управлять.>', '', '', 'Надзиратель Акрат', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35262, 'ruRU', 'Служба рангари Каайлы', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35264, 'ruRU', 'Горстка фрагментов артефакта', '', '', '', '', '', '', '', 'На этот раз ты $gсделал все, что мог:сделала все, что могла;, $n.', 19865);
INSERT INTO `quest_template_locale` VALUES (35265, 'ruRU', 'Ритуал единения', 'Поговорите с Каландриосом, чтобы начать ритуал единения.', 'Пришло время и тебе пройти ритуал единения, $n.$b$bЭтот древний шаманский ритуал проводился еще задолго до моего рождения. Быть избранным – большая честь.$b$bВо время ритуала у многих шаманов бывают видения, через связь со стихиями им открывается совсем иная картина мира.$b$bКак будешь $gготов:готова; к ритуалу, сообщи об этом Каландриосу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35266, 'ruRU', 'Усиленный персонаж', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35271, 'ruRU', 'Угроза Песни Войны', 'Украдите план нападения клана Песни Войны.', '<План наступления написан черными чернилами на пергаменте и завернут в необработанную кожу.>$b$bВсем аванпостам:$b$bВождь отдал приказ о подготовке наступления на захватчиков из Орды по всему фронту. Планы наступления доставлены на несколько удаленных аванпостов.$b$bВ кровавом бою мы добудем себе славу, втаптывая в землю захватчиков из Орды!$b$bПесня Войны грянет по приказу Вождя! Лок\'тар огар!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35272, 'ruRU', 'Своих не бросаем', 'Поговорите с темным ведуном Искаром и убедите его отпустить темного охотника Укамбе на волю.', 'Стоило пойти, глянуть, как тут что – и птицолюди сцапали меня.$B$BМы вон там над заставой для тебя работали, прям за горой, чтоб за тобой потом весь континент был.$B$BДела тут идут нехорошо.$B$BМне нужна будет твоя помощь, командир. Скажи им, что я вреда не хочу, хочу тебе заставу показать, а?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35273, 'ruRU', 'Место власть имущего', 'Воспользуйтесь креслом надзирателя, чтобы управлять турелью апекситов, и уничтожьте $1oa |4апекситовый разрушитель:апекситовых разрушителя:апекситовых разрушителей; и $2oa |4адепта:адептов:адептов; солнечных ваятелей.', '<Апекситовые разрушители выходят из своих комнат на тропу войны. Араккоа наверняка пошлют солнечных ваятелей, чтобы те поддерживали их.$B$BТурель и приборная доска негромко гудят друг другу в тон.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35274, 'ruRU', 'Своих не бросаем', 'Поговорите с темным ведуном Искаром и убедите его отпустить Джаспера Скверна на волю.', 'Эти проклятые твари сцапали меня во время осмотра местности. Теперь, когда ты здесь, командир, твоя помощь на базе очень пригодится.$B$BА, и еще – может, сумеешь убедить своих... друзей... дать мне уйти?$B$BОни, эм-м... не хотят меня отпускать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35275, 'ruRU', 'Смотр войск', 'Поговорите с темным охотником Укамбе в Павшем Топоре.', 'Павший Топор совсем близко.$B$BЯ его отмечу на твоей карте и там тебя подожду.', '', '', '', '', '', 'Поговорите с темным охотником Укамбе в Павшем Топоре.', 25549);
INSERT INTO `quest_template_locale` VALUES (35276, 'ruRU', 'Смотр войск', 'Поговорите с Джаспером Скверном в Южном порту.', 'Южный порт находится недалеко отсюда, к юго-западу.$B$BНет времени болтать. Встретимся прямо там, командир.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35277, 'ruRU', 'Какие будут приказы, командир?', 'Осмотрите чертежный стол и выберите, какую из построек следует возвести на аванпосте.', 'Командир, отчет о состоянии дел выглядит... прискорбно.$B$BЧерез несколько дней у нас закончатся припасы, и это если предположить, что у нас к тому времени еще будут войска.$B$BОставшихся материалов хватит либо на таверну, либо на торговую лавку.$B$BТаверна поможет разместить здесь свежие войска, зато торговая лавка позволит установить связи с изгоями поблизости и наладить возможные маршруты снабжения.$B$BПроекты Газлоу – на чертежном столе. Мы ждем твоего решения.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35279, 'ruRU', 'Сокровище: сокровища Призрачной Луны 01', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35280, 'ruRU', 'Сокровище: сокровища Призрачной Луны 02', '', '', '', '', '', '', '', '', 19865);
