INSERT INTO `quest_template_locale` VALUES (35284, 'ruRU', 'Торговая лавка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35285, 'ruRU', 'Вперед, за хотродом!', 'Найдите Кимзи Паросвист на Мысе Паросвистов.', 'Госпожа Кимзи – крепкий орешек, но оставаться одной на Мысе Паросвистов ей слишком опасно. Если наш босс вдруг заразится, то у всех просто опустятся руки.$b$bСлушай, сходи и проверь, как она там, а то мне надо отправить команду обратно в мастерскую.$b$bЕе дядя живет в башне по ту сторону нефтяных месторождений, думаю, ты можешь поискать ее там.', '', '', '', '', '', 'Поговорите с Кимзи Паросвист на Мысе Паросвистов.', 25549);
INSERT INTO `quest_template_locale` VALUES (35286, 'ruRU', 'Какие будут приказы, командир?', 'Осмотрите чертежный стол и выберите, какую из построек следует возвести на аванпосте.', 'Командир $n, это честь для нас.$B$BМы здесь едва держимся. Припасов у нас хватит самое большее на неделю, если предположить, что у нас к тому времени еще будут войска, которым эти припасы понадобятся.$B$BОставшихся материалов только-только хватит либо на таверну, либо на торговую лавку.$B$BТаверна поможет разместить здесь подкрепление, а торговый дом позволит установить связи с изгоями поблизости и наладить маршруты снабжения.$B$BДля постройки нам нужно твое одобрение, командир. Решение за тобой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35287, 'ruRU', 'Огненная Пропасть – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35288, 'ruRU', 'Тюрьма – награда', '', '', '', '', '', '', '', '', 25549);
