INSERT INTO `quest_template_locale` VALUES (35293, 'ruRU', 'Старые знакомые', 'Поговорите с Джаспером Скверном в гарнизоне адмирала Тейлора.', 'Адмирала Тейлора направили сюда строить гарнизон, а мы в это время обустраивались в Долине Призрачной Луны. Он обосновался совсем недалеко, к северу отсюда.$B$BЕсли мы с тобой вместе возьмемся за дело, то сумеем раздобыть немного припасов. Это позволит продержаться до следующей поставки.$B$BЧто скажешь, командир? Адмирал точно будет рад снова тебя увидеть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35294, 'ruRU', 'Джаспер действует', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35295, 'ruRU', 'Их припасы – наши припасы', 'Поговорите с темным охотником Укамбе в гарнизоне адмирала Тейлора.', 'Мне тут на разведке попалось кой-чего еще, босс.$B$BУ Альянса вон прям там гарнизон, и давно так ужо никто не внутрь, ни наружу не ходил.$B$BПервоклассный шанс их грабануть и набить твои сундуки, командир.$B$BЧего скажешь? Вместе пойдем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35297, 'ruRU', 'ФЛАГ: Армия выступила', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35298, 'ruRU', 'Ба-бах!', 'Используйте подрывную машинку с огнебомбами и залезьте в ветролет Кимзи.', 'Что ж, $n, скольких могли, мы спасли, но теперь надо проследить, чтобы зараза не разошлась дальше.$b$bОгнебомбы заряжены и готовы.$b$bКимзи только что закончила возиться с ветролетом, так что можно лететь обратно в мастерскую, когда закончим.$b$bТы $Gсделал:сделала; всю грязную работу – тебе и подрывать бомбы, я считаю.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35303, 'ruRU', 'Пещеры Стенаний – награда', '', '', '', '', '', '', '', '', 25549);
