INSERT INTO `quest_template_locale` VALUES (35305, 'ruRU', 'Награда за победу над бароном Сильверлейном', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35307, 'ruRU', 'Пещеры Стенаний – Дополнительная задача', '', '', '', '', '', '', '', '', 25549);
