INSERT INTO `quest_template_locale` VALUES (35316, 'ruRU', 'Врата Заходящего Солнца (награда)', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35317, 'ruRU', 'Темное сердце Ошу\'гуна', 'Войдите в Святилище наару.', '$n, внутренние покои уже близко. Скоро мы узнаем, в чем первопричина этого зла.$b$bЯ могу поместить в эти покои свою проекцию, чтобы направлять тебя, но бороться со злом придется тебе.$b$bПусть ветер Каландриоса придаст тебе сил, пусть мудрость Абориуса просветит тебя и пусть огонь Возжигателя подожжет твоих врагов.$b$bИ пусть память о Гордауге защитит тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35318, 'ruRU', 'Дворец Могу\'шан (награда)', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35319, 'ruRU', 'Монастырь Шадо-Пан (награда)', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35320, 'ruRU', 'Монастырь Шадо-Пан (награда)', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35321, 'ruRU', 'Дворец Могу\'шан (награда)', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35322, 'ruRU', 'Я вижу умерших людей', 'Заберите чертежи Брайана Финна у призрачных работников.', 'Здесь... все мертвы.$B$BИ дух архитектора чего-то не хочет с нами сражаться. Надо же, откинулся, а все туда же – только о работе думает. Надо ему мозги прочистить, может, тогда и поймем чего.$B$BТак, у кого-то из призрачных работников должен быть один из его чертежей. Дадим ему позырить, вот память и вернется.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35323, 'ruRU', 'Хмелеварня Буйных Портеров (награда)', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35324, 'ruRU', 'Хмелеварня Буйных Портеров (награда)', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35325, 'ruRU', 'Храм Нефритовой Змеи (награда)', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35327, 'ruRU', 'Храм Нефритовой Змеи (награда)', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35329, 'ruRU', 'Я вижу умерших людей', 'Заберите чертежи Брайана Финна у призрачных работников.', 'П-призраки! Они все стали призраками!$B$BБрайан был одним из моих лучших друзей. Что-то затуманило его разум, и мы должны как можно скорее привести его в чувство!$B$BОн всегда был без ума от своей работы. Если показать ему один из его чертежей, это может помочь. Наверняка такой чертеж есть у кого-то из призрачных работников.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35330, 'ruRU', 'Ритуал единения', 'Поговорите с Каландриосом, чтобы начать ритуал единения.', '$n, настало время тебе пройти ритуал единения.$b$bПоговори об этом с Каландриосом, а я подожду тебя здесь.$b$bВо время ритуала стихии одарят тебя видением. Когда ритуал закончится, возвращайся ко мне, и мы продолжим разговор.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35331, 'ruRU', 'Призыв к Трону', 'Поговорите с яростными духами у Трона Стихий.', 'Я был в Таладоре, когда меня позвал некий голос.$b$bЯ оглянулся, но рядом со мной никого не было. Голос раздался снова – словно со мной говорил ветер.$b$b\"Тебе нужно поспешить к трону\", – шепнул он.$b$bГолос назвал себя \"Каландриос\", он и привел меня сюда.$b$bМне еще никогда не приходилось бывать в этих краях, кроме того, я никогда раньше не встречался с Гневами – однако все здесь мне почему-то кажется знакомым.$b$bТеперь, когда ты тут, настало время поприветствовать Гневов и выслушать их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35332, 'ruRU', 'Весть от Нобундо', 'Поговорите с воздаятелем Нобундо у Трона Стихий.', '$n, тебя хотят видеть у Трона Стихий.$b$bВоздаятель Нобундо услышал в голосе ветра зов Гнева и отправился в путь, чтобы поговорить со стихиями.$b$bЯ не знаю, каковы намерения Гневов, но орки почитают их, как могущественных и благородных духов.', '', '', '', '', '', 'Поговорите с Нобундо.', 25549);
INSERT INTO `quest_template_locale` VALUES (35333, 'ruRU', 'Единое целое со стихиями', 'Станьте единым целым со стихиями с помощью четырех столпов стихий.', 'Даже сейчас голос Каландриоса говорит со мной.$b$b\"Герой Азерота должен прислушаться к стихиям плато\", – молвит он.$b$bНа Плато Стихий есть четыре высокие колонны, высеченные из живого камня. Положи руки на каменные колонны, и тогда твоя душа станет едина со стихиями.$b$bА я пока продолжу разговор с великими духами – возможно, мне удастся понять, чего именно они хотят.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35334, 'ruRU', 'Событие: яйцо Вараши', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35335, 'ruRU', 'Событие: Башиок', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35337, 'ruRU', 'От топота копыт', 'Добудьте $1oa |4пару:пары:пар; ушей твердошкурого копытня.', 'Командир. Мы с этой рангари обсуждали преимущества разных способов охоты.$B$BЯ уверяю ее, что ШРУ прекрасно подготовлено к любой ситуации, даже если приходится действовать вдали от цивилизации.$B$BНо она считает, что в \"ее землях\" мы беспомощны, как слепые котята.$B$BМы же не позволим ей так нас унижать, да? Давай добудем несколько копытней.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35338, 'ruRU', 'Наперегонки с ветром', 'Соберите $1oa |4рог:рога:рогов; талбука-ветробега.', 'У нас с Киа вышел жаркий спор о том, кто более эффективно убивает: ШРУ или рангари.$B$BНе хочешь поучаствовать в пари, командир?$B$BМы решили посоревноваться в охоте на талбуков – потому что они такие горделивые и яростные. Любой уроженец Дренора знает, что они – воплощение величия Награнда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35339, 'ruRU', 'Последняя просьба', 'Добудьте $1oa |4сущность привидения:сущности привидений:сущностей привидений; в гарнизоне и покажите их Элис Финн, чтобы помочь ей принять свою судьбу.', 'Понятия не имею, что случилось. Видимо, я вместе со своей бригадой погиб в числе первых.$B$BМне кажется, моя жена, хозяйка таверны, сейчас находится в таком же состоянии, что и я.$B$BПрошу тебя, упокой обитателей гарнизона и покажи их сущности моей жене. Это вырвет ее из объятий ледяной мглы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35340, 'ruRU', 'Что здесь произошло?', 'Найдите один из чертежей Брайана Финна.', 'Дух этого архитектора не хочет на нас нападать. Может, нам удастся разогнать туман, застилающий его разум, и узнать, что произошло.$B$BНаверняка у одного из этих воскресших крестьян есть один из его чертежей или еще что-нибудь, что вернет ему память.$B$BПопробовать стоит.', '', '', '', '', '', 'Поговорите с темным охотником Уджамбе в гарнизоне адмирала Тейлора.', 19865);
INSERT INTO `quest_template_locale` VALUES (35341, 'ruRU', 'Отступничество Рокаша', 'Примите клятву крови мастера клинка На\'Шры.', 'Ты мне очень $gпомог:помогла;. Теперь этот клинок принадлежит не только мне, но и тебе.$b$bЯ клянусь на крови служить тебе и использовать все свои знания о клинках и руде, чтобы помогать тебе.$b$bПримешь ли ты мою клятву?', '', 'На\'Шра, только что получившая звание мастера клинка, – грозная воительница.', 'Мастер клинка На\'Шра', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35342, 'ruRU', 'Бутыль с загадочной жидкостью', 'Поговорите с Аэниром в гарнизоне.', 'Жидкость, бурлящая в бутыли, очевидно, обладает мощными алхимическими свойствами, но ее природа вам неизвестна.$B$BВы слыхали, что один из беженцев Вечерней Зари в вашем гарнизоне знаком с дренорской алхимией. Может быть, он знает, что это за жидкость?', '', '', '', '', '', 'Поговорите с Аэниром в гарнизоне.', 25549);
INSERT INTO `quest_template_locale` VALUES (35343, 'ruRU', 'Юный алхимик', 'Найдите Абату у Зеленеющей топи.', 'Основам алхимии меня обучала моя тетушка. Но если ты хочешь углубить свои познания в алхимии, тебе следует обратиться к моей кузине Абате. Она училась у моей тетушки, пока та не умерла.$B$BАбата живет у Зеленеющей топи с сестрой и отцом.', '', '', '', '', '', 'Найдите Абату.', 25549);
INSERT INTO `quest_template_locale` VALUES (35344, 'ruRU', 'Пропавший отец', 'Отыщите Телоса в Зеленеющей топи.', 'Я рада бы была помочь тебе в твоих алхимических изысканиях, но сейчас я беспокоюсь об отце.$B$BОн уже давно ушел охотиться к реке, но домой так и не вернулся. Мне нужно присматривать за Лумиель. Прошу, разыщи его.', '', '', '', '', '', 'Отыщите Телоса.', 25549);
INSERT INTO `quest_template_locale` VALUES (35345, 'ruRU', 'Шокирующая помощь', 'Соберите 100 шоковых чешуек с искровых угрей.', 'После смерти жены мне непросто содержать семью, вот я и переоценил свои силы, взяв этот контракт на шоковую чешую.$b$bУвы, теперь мне ни за что не успеть наловить достаточно угрей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35347, 'ruRU', 'Сокровище: добыча огров 000', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35348, 'ruRU', 'Пещеры Черной горы – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35349, 'ruRU', 'Пещеры Черной горы – дополнительная награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35350, 'ruRU', 'Королева копытней', 'Добудьте рог Бантар.', 'Лаара сказала, что здесь Бантар! Точнее, что она еще жива. Хотя какая разница, кто что сказал?$B$BКомандир, это наш шанс. Если мы одолеем молодую Бантар, этим рангари придется признать нашу силу.$B$BПокажем Лааре, как действуют настоящие профессионалы.', '', 'Моложе и сильнее, чем ее двойник из Запределья. Добудьте ее рог.', 'Бантар, королева копытней', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35351, 'ruRU', 'Пещеры Черной горы – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35352, 'ruRU', 'Пещеры Черной горы – дополнительная награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35353, 'ruRU', 'Недостающее звено', 'Убейте ужасную аберрацию в подвале таверны.', 'Да, теперь я припоминаю. Командир стражи Брансон велел нам оставаться в таверне... Сказал, что там безопасно.$B$BА потом...$B$BПотом туда вломилась эта ТВАРЬ и всех перебила!$B$BИ она все еще там... в подвале.', '', '', 'Ужасная аберрация.', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35356, 'ruRU', 'Пропавшая стрела', 'Отнесите стрелу рангари Лааре на Телаарскую станцию.', '<Из бока талбука торчит стрела рангари. Возможно, ваша находка заинтересует рангари Лаару.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35357, 'ruRU', 'Вожак ветробегов', 'Добудьте хвост Щеголя.', 'Дай угадаю: ты $gнашел:нашла; ее в боку талбука?$B$B<Лаара на минуту задумывается.>$B$BЭта стрела предназначалась Щеголю, вожаку ветробегов. Другой талбук – тот, которого ты $gубил:убила; – заслонил его собой в самый последний момент.$B$BПопробуй выследить вожака. Когда я охотилась на него, он, кажется, любил гулять к югу отсюда, по берегу пруда в Одиноких водах.', '', 'Вожак всех талбуков Награнда.', 'Щеголь', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35358, 'ruRU', 'Конец Времен – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35363, 'ruRU', 'Трон Приливов – награда', '', '', '', '', '', '', '', '', 25549);
