INSERT INTO `quest_template_locale` VALUES (35372, 'ruRU', 'Зов Ошу\'гуна', 'Отправьтесь в Леса Духов.', '$n, стихии сказали свое слово, и нам было видение.$b$bВместе мы отправимся к великой горе Ошу\'гун и там уничтожим источник тьмы.$b$bЕсли видение истинно, то нас ждут страшные испытания.$b$bЯ встречу тебя в Лесах Духов, у подножия Ошу\'гуна. Когда будешь $gготов:готова; отправиться в путь, поговори с Гиксмо Гонимани, и он отвезет тебя туда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35373, 'ruRU', 'Сокровище: добыча огров 006', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35374, 'ruRU', 'От топота копыт', 'Добудьте $1oa |4пару:пары:пар; ушей твердошкурого копытня.', 'Командир! Мы с этой Северной Волчицей обсуждали преимущества разных способов охоты.$B$BЯ ее уверял, что темные охотники прекрасно подготовлены к любой неожиданности, даже если приходится действовать вдали от цивилизации.$B$BНо она считает, что в \"ее земле\" мы беспомощны, как слепые котята.$B$BМы же не позволим ей так нас унижать, да? Давай добудем несколько копытней.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35375, 'ruRU', 'Королева копытней', 'Добудьте рог Бантар.', 'Огка говорит, что Бантар здесь! Точнее, что она еще жива. Хотя какая разница, кто что сказал?$B$BКомандир, это наш шанс. Если мы одолеем молодую Бантар, то здорово насолим этим Северным Волкам.$B$BПокажем Огке, как действуют настоящие профессионалы!', '', 'Этот зверь моложе и сильнее чем его двойник из Запределья. Добудьте его рог.', 'Бантар, королева копытней', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35376, 'ruRU', 'Наперегонки с ветром', 'Соберите $1oa |4рог ветробега:рога ветробега:рогов талбука-ветробега;.', 'У нас с Тацем вышел жаркий спор о том, кто эффективнее убивает: темные охотники или Северные Волки.$B$BНе хочешь поучаствовать в пари, командир?$B$BМы в основном сосредоточились на талбуках – потому что они такие горделивые и яростные. Любой уроженец Дренора знает, что они – воплощение величия Награнда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35377, 'ruRU', 'Пропавший топор', 'Отнесите топор Северного Волка охотнице Огке в Вор\'вар.', '<Из бока талбука торчит топор Северных Волков. Возможно, ваша находка заинтересует охотницу Огку.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35378, 'ruRU', 'Вожак ветробегов', 'Добудьте хвост Щеголя.', 'Сейчас угадаю: ты $gнашел:нашла; его в боку талбука?$B$B<Огка на минуту задумывается.>$B$BЭтот топор предназначался для Щеголя, вожака ветробегов. Другой талбук – тот, которого ты $gубил:убила; – заслонил его собой в самый последний момент.$B$BМожешь попробовать выследить вожака. Когда я охотилась на него, он, кажется, любил гулять к югу отсюда, по берегу пруда в Одиноких водах.', '', 'Вожак всех талбуков Награнда.', 'Щеголь', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35379, 'ruRU', 'Охотничьи угодья Хеминга', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35380, 'ruRU', 'Заместитель командира', 'Поговорите с сэром Эдвардом в гарнизоне адмирала Тейлора.', 'Подожди... Я припоминаю кое-что еще...$B$BСэр Эдвард... кричал... искал кого-то.$B$BЯ... Не помню, кого именно. Все вокруг так кричали...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35381, 'ruRU', 'Сокровище: сокровища Призрачной Луны 05', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35382, 'ruRU', 'Сокровище: сокровища Призрачной Луны 06', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35383, 'ruRU', 'Сокровище: сокровища Призрачной Луны 07', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35384, 'ruRU', 'Сокровище: сокровища Призрачной Луны 08', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35385, 'ruRU', '[Удалено ] Сокровище: сокровища Призрачной Луны 07', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35386, 'ruRU', 'Угроза Песни Войны', 'Украдите план нападения клана Песни Войны.', '<План наступления написан черными чернилами на пергаменте и завернут в необработанную кожу.>$b$bВсем аванпостам:$b$bВождь отдал приказ о подготовке наступления на захватчиков из Альянса по всему фронту. Планы наступления доставлены на несколько удаленных аванпостов.$b$bВ кровавом бою мы добудем себе славу, втаптывая в землю захватчиков из Альянса!$b$bПесня Войны грянет по приказу Вождя! Лок\'тар огар!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35387, 'ruRU', 'Через Пустоту', 'Отправьтесь в Круговерть Пустоты.', 'Ритуалы остановлены, но темная энергия продолжает стекаться к маякам Пустоты. А это может означать только то, что они подпитываются из Круговерти Пустоты.$b$bЕдинственный способ остановить поток энергии – это отправиться в Круговерть Пустоты и остановить зло, которое засело там!$b$bЧтобы попасть туда, используй один из маяков. Как только окажешься там, воспользуйся камнем шаманов, который дали нам неистовства стихий, чтобы связаться со мной.$b$bДа пребудет с тобой Свет.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35388, 'ruRU', 'Марш Бездны', 'Убейте $oa |4чудовище:чудовищ:чудовищ; Бездны.', 'Легионы чудовищ Бездны приближаются к Ошу\'гуну и приносят себя в жертву Немощусу.$b$bИ по мере того как они умирают, он набирается сил, питаясь ими.$b$bМы должны помешать ему – ведь иначе он обретет такое могущество, что его уже нельзя будет одолеть.$b$bУбей как можно больше чудовищ Бездны. Я же пока поищу способ, который позволить нам сдержать Немощуса.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35389, 'ruRU', 'Прервать зов', 'Убейте шаманов Песни Войны, руководящих ритуалом.', 'Шаманы клана Песни Войны используют стихии, чтобы выкачивать темную энергию из Бездны.$b$bЯ не шаман, но даже я знаю, что большинство орков с отвращением относятся к подобным делам. Бездна является противоположностью Света, это источник хаоса и разрушения.$b$bТакие ритуалы разрушают завесу, отделяющую наш мир от Круговерти Пустоты. Если их не остановить, скоро эту землю захватят обитатели Круговерти Пустоты.$B$BУбей шамана, который руководит проведением ритуала, пока темная магия не уничтожила нас всех!', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35390, 'ruRU', 'Тень над Ошу\'гуном', 'Призовите и победите Немощуса.', 'Повелитель Бездны Немощус стоит на вершине Ошу\'гуна, поглощая души мертвых.$B$BДаже убитые тобой ужасы Бездны служили лишь тому, чтобы насытить это чудовище.$B$BЕсли мы промедлим, Немощус станет слишком силен, чтобы противостоять ему в одиночку.$B$BНа каждой ритуальной площадке в Круговерти Пустоты есть кристалл, наполненный силами Бездны. Уничтожь кристалл Бездны, и Немощус узнает о твоем присутствии.$B$BБудь настороже – он сразу же возжелает пожрать и твою душу.', '', '', '', '', '', 'I need text', 19865);
INSERT INTO `quest_template_locale` VALUES (35391, 'ruRU', 'Прервать ритуалы', 'Уничтожьте ритуальные тотемы.', 'Под горой Ошу\'гун выполняет свои темные ритуалы клан Песни Войны.$B$BШаманы клана хотят усилить своих сородичей, призвав в сердце Ошу\'гуна мощный источник энергии Бездны.$B$BЯ не знаю наверняка, откуда взялась эта сила, но боюсь, что тут может быть замешан умирающая наару К\'уре.$B$BРитуалы клана Песни Войны надо прекратить, иначе вуаль, отделяющая этот мир от Круговерти Пустоты, будет разорвана.$B$BНайди ритуальные тотемы, которые поддерживают энергетический поток во время ритуалов, и уничтожь их.', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35392, 'ruRU', 'Пустота подступает', 'Обрушьте $oa |4врата:врат:врат;. Бездны.', 'Открыв порталы, клан Песни Войны истончил вуаль, укрывающую наш мир от Круговерти Пустоты.$b$bПосмотри вокруг, и ты увидишь, что повсюду появляется бесконечное множество новых порталов – на этот раз сами обитатели Круговерти Пустоты пытаются установить связь с Дренором.$b$bЕсли эти порталы откроются, в Награнд хлынут самые разные демоны и монстры Бездны.$b$bИди и обрушь эти порталы, пока они не успели открыться!', '', '', '', '', '', 'I need text', 19865);
INSERT INTO `quest_template_locale` VALUES (35393, 'ruRU', 'Дела духовные', 'Поговорите с духами в Землях Предков.', 'Гора Ошу\'гун давно притягивает к себе души умерших.$b$bСколько себя помню, эти леса всегда были переполнены призраками, бредущими к горе. Мне кажется, их притягивает пустота в горе.$b$bДоберись до Земель Предков и попроси у духов наставления.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35395, 'ruRU', 'Судьба Гордауга', 'Добудьте Сердце Гнева.', 'Путь к внутренним покоям преграждает устрашающий дух земли, которого мы так жаждали вернуть на Трон Стихий.$b$bГордауг зачарован – он стал рабом Чо\'Галла. Мое сердце опечалено; мне тяжело видеть, что зло поработило это великое существо и лишило разума.$b$bНазад пути нет; ты $gдолжен:должна; одолеть Гордауга.$b$bМне больно это говорить, но Гордауга необходимо убить.$b$bКогда это будет сделано, мы вернем его сердце к Трону Стихий – туда, где оно и должно быть.', '', 'Смерть – единственный способ вырвать великую ярость из лап Чо\'Галла.', 'Гордауг', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35396, 'ruRU', 'Темное сердце Ошу\'гуна', 'Войдите в Святилище наару.', 'Под древними обломками \"Генедара\" находится вход во внутреннюю часть корабля. Кажется, энергия Бездны сосредоточена именно там.$b$bТебе нужно войти туда и сразиться с силами зла. Боюсь, что великого наару К\'уре постигла страшная участь, но в любом случае зло нужно истребить.$b$bДа не оставит тебя Свет, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35397, 'ruRU', 'Бледная угроза', 'Убейте Серого Провидца и $2oa |4бледнокожего орка:бледнокожих орков:бледнокожих орков;.', 'Если мы хотим остановить Чо\'Галла и защитить наару, то должны пробиться через Бледную Пещеру – темную, извилистую пещеру.$b$bВ ней обитают бледнокожие – орки, ненавидящие все доброе и святое. Чем дольше мы их игнорируем, тем более коварные планы они строят.$b$bДоберись до Бледной Пещеры и уничтожь этих мерзких тварей вместе с их предводителем – Серым Провидцем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35398, 'ruRU', 'Темные путы', 'Освободите $1oa |4духа:духов:духов; стихий.', 'В эту самую минуту бледнокожие в Ущелье Нависших Теней подчиняют стихии своей воле. Многие уже в их власти, но это только начало.$b$bОтправляйся в Ущелье Нависших Теней и освободи тех духов стихий, которых бледнокожие еще не успели поработить. Ну а порабощенным мы можем помочь лишь одним – освободить, даровав им быструю смерть.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35399, 'ruRU', 'Опасная трясина', 'Найдите Торга Собирателя Ушей, Меку Лицеедку и Чага Безносого в Терновом Цветении.', 'Твоя волчья королева не выпускает меня из виду.$b$bМожет быть, мою деревню и уничтожили дети магнарона, но мой народ забрали дети генезотавра.$b$bБотани и их прислужники утаскивают моих сородичей в Терновое Цветение, и если мы снова видим их, то они уже не такие, какими были при жизни.$b$BТы уже $gпомог:помогла; Черепам, так что я снова прошу твоей помощи.$b$bОтправляйся в Терновое Цветение и поищи там моих сородичей, которых недавно забрали.$b$bВозможно, они даже еще живы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35400, 'ruRU', 'Зараженные', 'Убейте $1oa |4зараженного орка:зараженных орков:зараженных орков;.', 'Я понимаю желание Каз спасти своих сородичей, но ее план безрассуден, и она многое недоговаривает.$b$bМне хотелось убедиться, что она ничего не замышляет против нас, а теперь я вижу это... этот... кошмар.$b$bЧто ботани сотворили с этими орками?$b$bЭтим зараженным душам нужно подарить покой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35401, 'ruRU', 'Вершина Смерча – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35402, 'ruRU', 'Глас Ию', 'Убейте Глас Ию.', 'Ботани со своими безобразными прислужниками все забирают, забирают, забирают.$b$bИм нужна еда – они забирают нашу землю. Им нужна армия – забирают наших сородичей.$b$bНеобходимо вселить страх в кустистые сердца этого зеленого народца.$b$BНайди их вождя, Глас Ию. Это ботани, который вещает от лица их повелителя-генезотавра.$b$bУбей этого драгоценного вождя в его драгоценном цветущем убежище.', '', 'Он говорит от имени генезотавра.', 'Глас Ию', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35403, 'ruRU', 'Вершина Смерча – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35404, 'ruRU', 'Грим Батол – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35405, 'ruRU', 'Грим Батол – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35406, 'ruRU', 'Суперсемена', 'Соберите обогащенные семена.', 'Ботани заботливо защищали эти семена.$B$BЭти маленькие сосуды жизни излучают великую энергию.$B$BОни могут нам пригодиться.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35407, 'ruRU', 'Полевой суд', 'Убейте $1oa |4предателя:предателей:предателей; из гарнизона.', 'Они предатели – все до одного!$b$bПеред тобой – последний оплот, все еще верный адмиралу Тейлору и Альянсу.$B$BИ будь я проклят, если позволю перебежчикам уйти безнаказанно.$B$BТы, похоже, $gготов:готова; действовать. Покажи им, как мы поступаем с такими, как они, в военное время.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35408, 'ruRU', 'Забить снаряды в пушку', 'Добудьте $1oa |4железное ядро:железных ядра:железных ядер; и $2oa |4пушку:пушки:пушек; арсенала.', 'Оружейную захватили предатели. Все, что у нас есть, – это пара пушек без боеприпасов.$B$BСолдат, тебе нужно добыть ядра, тогда мы сможем начать обстрел.$B$BИ, если честно, еще одно орудие нам тоже не помешает.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35411, 'ruRU', 'Зул\'Гуруб – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35412, 'ruRU', 'Зул\'Гуруб – Дополнительная задача', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35413, 'ruRU', 'Затерянный город Тол\'вир – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35414, 'ruRU', 'Затерянный город Тол\'вир – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35415, 'ruRU', 'Чертоги Созидания – награда', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35416, 'ruRU', 'Мощь генезотавра', 'Поговорите с Дуротаном на Звериной заставе в Горгронде.', 'Командир, теперь у тебя есть Воля генезотавра, а также воды сотворения и семена – то есть все, что нужно для создания армии. Это даже без учета спасенных тобой членов клана Веселого Черепа.$b$bПо-моему, задание можно считать успешно выполненным.$b$bЯ пройдусь по крепости и посмотрю, нет ли там еще каких-нибудь материалов, которые можно забрать.$b$bА ты тем временем можешь отнести добытые артефакты Дуротану на аванпост. Я догоню тебя, когда закончу здесь.', '', '', '', '', '', 'Поговорите с Дуротаном на Звериной заставе в Горгронде.', 25549);
INSERT INTO `quest_template_locale` VALUES (35420, 'ruRU', 'Чертоги Созидания – дополнительные награды', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35424, 'ruRU', 'Чертоги Созидания – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35426, 'ruRU', 'Чертоги Созидания – дополнительные награды', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35429, 'ruRU', 'Сила пыльцы', 'Найдите $1oa |4щепотку:щепотки:щепоток; концентрированной пыльцы.', 'Те из нас, кто вырос в Горгронде, давно научились парочке фокусов у ботани и теперь могут выращивать собственные растения.$B$BИменно поэтому Веселый Череп не знает, что такое голод.$B$BВсе дело в опустошителях.$B$BУ Ключей Вечного Рассвета можно найти великое множество разных опустошителей. Убей их и отними у них пыльцу, а я с ее помощью помогу тебе развести растения в твоем гарнизоне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35430, 'ruRU', 'Резатель', 'Найдите Резателя.', 'Ты $gнашел:нашла; много Веселых Черепов. Это были мои друзья и близкие. И все они погибли. Но ты не $gнашел:нашла; моего милого Резателя.$b$bКогда доберешься до Ключей Вечного Рассвета, поищи его там. $b$bСпаси его.$b$bОн хороший мальчик и не заслужил такой жуткой смерти как заражение.$b$bЯ загоню несколько опустошителей и нападу с воздуха. Если найдешь Резателя раньше меня, отыщи меня в Ключах Вечного Рассвета.', '', '', '', '', '', 'Найдите Резателя в Ключах Вечного Рассвета.', 25549);
INSERT INTO `quest_template_locale` VALUES (35432, 'ruRU', 'Вырубка зарослей', 'Убейте $1oa |4ткача:ткачей:ткачей; цветения.', 'Каз использует нас, я тебе говорю. Она одна из Веселых Черепов, а уж им точно не стоит доверять.$B$BЯ думаю, сейчас нам лучше разделиться и собрать побольше информации.$B$BКаз отправит тебя к Ключам Вечного Рассвета. Увидишь там ботани – убивай, не задумываясь.$B$BЧем их меньше, тем лучше для орков.$B$BА я останусь с Каз и буду за ней приглядывать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35433, 'ruRU', 'Вырезать под корень', 'Убейте $1oa |4хозяина росы:хозяев росы:хозяев росы;.', 'Они воруют детей? Детей?!$B$BЕсли бы ты не $gспас:спасла; дитя Каз, его бы уже давно превратили в удобрение, как и остальных.$B$BПора поговорить с ботани на том языке, который они понимают. Вырежи под корень их драгоценных собирателей росы. Разорви их на части.$B$BПусть знают, как забирать наших детей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35434, 'ruRU', 'Источник жизни', 'Добудьте воду Утрофиса.', 'Похоже, что эти твои \"дворфы\" улизнули с могущественным артефактом ботани.$B$BХорошо хоть у них не хватило ума сообразить, что для артефакта нужна особая вода.$B$BЕсли пойдешь к северу отсюда, к Утесу Вечного Рассвета, ты найдешь источник.$B$BРядом с ним увидишь стража, существо из воды, которое мы зовем Утрофисом.$B$BУбей его, извлеки сущность, и мы станем на один шаг ближе к победе над ботани и их генезотавром.', '', 'Текущая жизнь', 'Утрофис', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35435, 'ruRU', 'Источник Вечности – награда', '', '', '', '', '', '', '', '', 25549);
