INSERT INTO `quest_template_locale` VALUES (35437, 'ruRU', 'Кузня Душ – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35438, 'ruRU', 'Яма Сарона – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35439, 'ruRU', 'Время Сумерек – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35440, 'ruRU', 'Яма Сарона – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35441, 'ruRU', 'Залы Отражений – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35442, 'ruRU', 'Залы Отражений – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35443, 'ruRU', 'Зул\'Аман – награда', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35444, 'ruRU', 'Южные напасти', 'Поговорите с прелатом Рину в Дракории.', 'Сначала Железная Орда, затем орки Призрачной Луны, а теперь еще одна беда!$B$BМой брат – наездник на драконе – сейчас на юге, в Дракории.$B$BОн говорит, что на наши земли хлынули обитатели болот. Куда катится этот мир?$B$BНу так вот – ты же $gопытный искатель:опытная искательница; приключений, да? Если ты направляешься в ту сторону, может, разберешься с этой напастью?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35446, 'ruRU', 'Окулус – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35447, 'ruRU', 'Окулус – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35448, 'ruRU', 'Событие: темный магистр Го\'вид', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35449, 'ruRU', 'Вершина Утгард – награда', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35450, 'ruRU', 'Южные напасти', 'Поговорите с прелатом Рину в Дракории.', 'С юга, из Дракория, поступают тревожные вести.$B$BГород находится рядом с болотом, и в последнее время по его окраинам шастают опасные существа.$B$BА ты ведь, похоже, $gопытный искатель:опытная искательница; приключений. Если ты направляешься в ту сторону, может, заглянешь в город?$B$BМне будет гораздо спокойней, если я буду знать, что мои друзья в безопасности.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35453, 'ruRU', 'Вершина Утгард – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35456, 'ruRU', 'Чертоги Молний – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35458, 'ruRU', 'Чертоги Молний – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35459, 'ruRU', 'Южные напасти', 'Поговорите с прелатом Рину в Дракории.', 'Размещено: прелатом Рину$B$BБлагородные друзья Альянса, дренеи Дракория встречают вас с миром.$B$BНа наш город постоянно нападают враги, обитающие в местных болотах.$B$BНедавно здесь прошел караван из Азерота и, возможно, свернул на опасную территорию.$B$BЕсли какому-то искателю приключений удастся спасти караван, он будет щедро вознагражден.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35460, 'ruRU', 'Атака Железной Орды', 'Убейте $1oa |4рубаку:рубак:рубак; Железного Марша.', 'Нам сообщили, что непосредственно перед атакой Темный портал окрашивается в красный цвет. Нападающие называют себя Железной Ордой, но, похоже, никак не связаны с той Ордой, которую знаем мы.$B$BИх войско очень хорошо снаряжено, их бойцам несть числа.$B$BОни уже заняли крепость Стражей Пустоты. Нашим войскам на передовой не помешала бы твоя помощь, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35461, 'ruRU', 'Осада Нюцзао (награда)', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35462, 'ruRU', 'В осаде', 'Выведите из строя $1oa |4\"Железный разрушитель:\"Железных разрушителя\":\"Железных разрушителей\";.', 'Пушки Железной Орды наносят огромный урон нашим войскам. Не знаю даже, сколько мы еще против них продержимся. Наш фронт и так уже слишком растянут.$B$BДолжен быть какой-то способ остановить эти боевые машины.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35463, 'ruRU', 'Спрятавшиеся разведчики', 'Убейте $1oa |4разведчицу:разведчиц:разведчиц; Железной Орды.', 'Большая часть наших операций провалилась. За нами явно следят.$B$BУ Железной Орды здесь, в Выжженных землях, наверняка полно разведчиков. Победа ускользает от нас.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35464, 'ruRU', 'Отмена казни', 'Убейте $1oa |4палача:палачей:палачей; Железного Марша.', 'Мы прибыли сразу, как только смогли – но опоздали. Крепость Стражей Пустоты пала. Железная Орда взяла в плен ее защитников.$B$BБез сомнения, сейчас они стараются выведать у пленных важные сведения о наших войсках.$B$BБоюсь, что после допроса пленников сразу же казнят. Времени мало.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35465, 'ruRU', 'Чертоги Камня – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35468, 'ruRU', 'Чертоги Камня – награда', '', '', '', '', '', '', '', '', 25549);
