INSERT INTO `quest_template_locale` VALUES (35481, 'ruRU', 'Событие: Низзикс', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35482, 'ruRU', 'Адмирал Тейлор', 'Найдите адмирала Тейлора на ферме адмирала Тейлора.', 'Адмирал Тейлор выяснил, кто за всем этим стоит. Он велел нам спасти всех, кого сможем... и хотел разобраться в произошедшем самостоятельно.$B$BБольше мы его не видели, ведь у нас был приказ.$B$BПожалуйста... пожалуйста, найди его. Он отправился к ферме.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35483, 'ruRU', 'Крепость Драк\'Тарон – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35484, 'ruRU', 'Крепость Драк\'Тарон – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35486, 'ruRU', 'Безумные лейтенанты', 'Раздобудьте боевые планы Железной Орды.', 'Пора нам узнать о нашем враге побольше.$B$BРазведчики вычислили несколько офицеров Железной Орды. Нападения противника слишком хорошо организованы: это явно не хаотичные варварские набеги. Наверняка лейтенанты имеют доступ к секретным боевым планам.$B$BТы – единственный солдат, кому я могу доверить это задание, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35487, 'ruRU', 'Мертвецов – на костер', 'Сожгите $1oa |4труп:трупа:трупов;.', 'Я видел тут много трупов. Каз учит нас всегда их сжигать.$B$BТолько так их не смогут превратить в коварные растения.$B$BНам следует сделать, как говорит Каз.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35488, 'ruRU', 'Смерть Молоту Ужаса!', 'Убейте $1oa |4огра:огров:огров; из клана Молота Ужаса.', 'Тупость огров клана Молота Ужаса не перестает меня удивлять. Железная Орда наверняка использует их в своих мерзких целях.$B$BТем не менее, надо показать этим ограм, что бывает, когда выступаешь против Альянса. Думаю, сейчас самое время.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35489, 'ruRU', 'Ан\'кахет: Старое Королевство – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35490, 'ruRU', 'Ан\'кахет: Старое Королевство – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35491, 'ruRU', 'Флаг выслеживания - Событие \"Малый надзиратель Кровогрив\"', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35492, 'ruRU', 'За Стражей Пустоты!', 'Установите флаги Альянса в крепости Стражей Пустоты.', 'Железная Орда контролирует крепость Стражей Пустоты, но глупо было бы с их стороны думать, что мы не попытаемся отбить свое.$B$BМои лучшие войска с нетерпением ждут возможности пролить кровь этих дикарей, но чтобы возглавить атаку, нам нужен победоносный воитель вроде тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35493, 'ruRU', 'Дополнительная награда: Ан\'кахет: Старое Королевство', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35494, 'ruRU', 'Реликвии павших', 'Найдите меч Штрумнера, кружку Кери и щит Кролана.', 'Их было так много. Охрана не смогла их остановить... и никто не смог. Сколько хороших солдат погибло из-за этих дикарей!$B$BНельзя забывать тех, кто отдал свои жизни, защищая Крепость Стражей Пустоты. Прошу, если найдешь что-то напоминающее о павших, принеси это мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35495, 'ruRU', 'Зуболом Разрушитель', 'Убейте Зуболома Разрушителя.', 'Если верить найденным тобой планам, огры клана Молота Ужаса виноваты в этой разрухе ничуть не меньше Железной Орды. Пора нам преподать им урок.$B$BСудя по всему, в Железной Орде огров представляет великан по прозвищу Зуболом. Убей его – и планы чудовищ будут расстроены.', '', '', 'Зуболом Разрушитель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35496, 'ruRU', 'Месть Енохи', 'Отравите провизию огров клана Молота Ужаса.', 'Они... Они убили мою сестру. Эти чудовища прошли прямо сквозь главные ворота и... просто ужас!$B$BИм помогали огры клана Молота Ужаса. Все они будут страдать. Возьми этот яд и капни немного в их крысиное варево. Яд будет медленно разъедать их изнутри. Они умрут медленной и мучительной смертью, как и заслужили.$B$BПрошу тебя. Ради моей сестры.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35497, 'ruRU', 'Азжол-Неруб – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35498, 'ruRU', 'Азжол-Неруб – награда', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35500, 'ruRU', 'Гар\'мак Фехтовальщик', 'Убейте Гар\'мака Фехтовальщика.', 'Благодаря собранным тобой разведданным мы узнали, что штурм возглавляет орк Железной Орды по имени Гар\'мак Фехтовальщик. Он укрылся в форте Окрил\'лон.$B$BУбив его, войну мы не выиграем, но наверняка нарушим сообщение между боевыми подразделениями Железной Орды. Это даст нам драгоценное время на сбор новых сил и разработку планов по противодействию новой угрозе.', '', '', 'Гар\'мак Фехтовальщик', '', 'Гар\'мак Фехтовальщик', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35501, 'ruRU', 'Роковой снаряд', 'Добудьте $1oa |4роковой снаряд:роковых снаряда:роковых снарядов;.', 'Этот огромный снаряд, видимо, предназначен для пушки, вокруг которой построен Бастион.$b$bЗаряжающее устройство находится на самом нижнем этаже, но почему-то снаряд до него не донесли.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35502, 'ruRU', 'Крепость Утгард – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35503, 'ruRU', 'Чар Горящий', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35505, 'ruRU', 'Пропавший дровосек', 'Найдите Френну в Хитросплетении.', 'Моя подруга была тут со мной на буровой установке. Френна, она как всегда старалась по максимуму, записывала все свои наблюдения в дневник.$b$bПенни хочет, чтобы я сказал тебе, где она. Я точно-то не знаю, но она бежала прям за мной, да, кажись, не выбралась.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35506, 'ruRU', 'Стремительный рост', 'Соберите $1oa |4порцию:порции:порций; древнего сока ботани или древних в Хитросплетении.', 'Этот дворф Талдрен бежал из Хитросплетения, будто у него сапоги на ногах горели.\n\nГоворит, его буровая установка оказалась здесь, и сам он еле живым выбрался. А еще одна – по имени Френна, может, так до сих пор и там.\n\nКое-что полезное он, правда, сообщил: у тамошних обитателей есть сок, с помощью которого можно все растить супер-пупер быстро.\n\nКстати, я собираюсь поискать буровую установку Талдрена. Когда закончишь, найди меня в Хитросплетении.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35507, 'ruRU', 'Вниз, по горенской норе', 'Убейте $1oa |4горена:горенов:горенов; в Бастионе Мойры.', 'Какие глупые дворфы! Как можно не знать, что, если вовремя не перестать копать, обязательно нарвешься на горенов?$B$BКогда пойдешь в эту железную крепость, по пути расправься с горенами, иначе они прогрызут стены насквозь.$B$BИзвини, что переваливаю все на тебя, но я еще никак не отойду от фруктовой диеты ботани.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35508, 'ruRU', 'Глава I: посев', 'Уничтожьте $1oa |4опыленный стручок:опыленных стручка:опыленных стручков;.', 'В Хитросплетении есть такие странные светящиеся штуки, которые, похоже, опыляют разные жалящие твари.\n\nБотани иногда собирают то, что выделяют стручки. Не знаю точно, что это, но это может быть для нас опасно.\n\nФренна', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35509, 'ruRU', 'Воля генезотавра', 'Найдите Волю генезотавра.', 'Я уверен, что дворфы отнесли артефакт во-о-он в ту железную крепость.$B$BТы за ним пойдешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35510, 'ruRU', 'Ию', 'Победите Ию.', 'Генезотавр уже здесь!$b$bОн хочет вернуть себе артефакт!$B$BКаз и Дрека сейчас сражаются с ним на поверхности, и им нужна твоя помощь. Дрека сказала, что я могу пострелять из большой пушки. Так что я останусь здесь и займусь этим.', '', 'Начало изначальной жизни.', 'Ию', '', '', '', 25549);
