INSERT INTO `quest_template_locale` VALUES (35524, 'ruRU', 'Глава III: pитуал Обугленных', 'Убейте $1oa |4древнего:древних:древних;.', 'На моих глазах древние совершили какой-то странный ритуал. Они вошли в огонь, сжигая свои листья и опаляя кору.\n\nЯ называю этот ритуал \"Ритуалом Обугленных\". Если мы хотим ослабить древних, нужно избавиться от них, пока они не стали еще сильнее.\n\nФренна', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35525, 'ruRU', 'Ботаника – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35526, 'ruRU', 'Ботаника – награда', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35527, 'ruRU', 'Глава II: жатва', 'Убейте Онтогена Жнеца.', 'Я видела, как некое существо разжигало в юных саженцах древних ярость и ненависть ко всему, что отличается от них.\n\nПолагаю, именно этот ботани и виновен в необычно агрессивном поведении древних здесь в Хитросплетении.\n\nМожет, в наших интересах убить этого ботани? Боюсь, одной мне с ним нипочем не совладать.\n\nФренна', '', '', 'Онтоген Жнец', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35528, 'ruRU', 'Механар – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35529, 'ruRU', 'Механар – награда', '', '', '', '', '', '', '', '', 25549);
