INSERT INTO `quest_template_locale` VALUES (35535, 'ruRU', 'Аркатрац – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35536, 'ruRU', 'Секреты ботани', 'Сопроводите Резателя к Каз Визгунье – она ждет вас у компостной кучи.', 'Ботани, должно быть, привели того огромного огрона, чтобы защитить что-то ценное. А что это за существо, похожее на пень, которого он убил?$B$BБотани – гадкие создания, но игрушки у них забавные. Может, Каз знает, что это было.$B$BПойдем ее искать?$B$BУ холма к югу отсюда есть компостная куча. Если Каз меня ищет, бьюсь об заклад, она начнет поиски оттуда.', '', '', '', '', '', 'Поговорите с Каз Визгуньей у компостной кучи.', 25549);
INSERT INTO `quest_template_locale` VALUES (35537, 'ruRU', 'Новости с Пиков Арака', 'Поговорите с Рокханом в своем гарнизоне на Хребте Ледяного Огня.', 'Командир, разведчики, вернувшиеся с Пиков Арака в гарнизон, принесли новости. Они говорят, что там идет война между людьми-птицами и орками клана Изувеченной Длани.\n\nРокхан просит тебя зайти к нему, когда закончишь здесь с делами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35538, 'ruRU', 'Аркатрац – награда', '', '', '', '', '', '', '', '', 25549);
