INSERT INTO `quest_template_locale` VALUES (35548, 'ruRU', 'Дополнительная задача: Гробницы Маны', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35549, 'ruRU', 'Почести герою', 'Поговорите с лейтенантом Виллемом в Южном порту.', 'Во имя Света...$B$BЯ не могу поверить, что это произошло с Тейлором и его людьми, это ведь был целый гарнизон.$B$BНам потребуется собрать все свои силы, чтобы защитить твой аванпост, командир.$B$BНам надо уходить отсюда. Мы почтим память павших, когда доберемся до безопасного места.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35550, 'ruRU', 'Выживание в диких краях', 'Поговорите с бригадиром Горнеком в Павшем Топоре.', 'Может, они и из Альянса, но адмирал Тейлор и его воины сражались с честью.$B$BОни заслужили наше уважение, да услышат меня древние вожди.$B$BА если наш гарнизон падет под темной магией, то окажется, что все труды насмарку, а, командир?$B$BПора нам обратно на базу. Там безопасно.$B$BПо крайней мере, безопаснее, чем здесь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35552, 'ruRU', 'Доверять нельзя никому', 'Идите по следу Маладаара и выясните, действительно ли в Элодор проник предатель.', 'Здесь все изменилось. Все шепчутся – постоянно перешептываются. Мараад ничего не замечает, но здесь, в Элодоре, появились следы энергии скверны. Враг проник в наши ряды!$b$bМне нужно идти на Совет экзархов, но я хочу, чтобы ты $gрасследовал:расследовала; это дело. Иди по следу энергии скверны – я его подсвечу. Если среди нас действительно есть предатели, то у них должно быть какое-то убежище. Найди его! Мы с другим экзархами будем ждать тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35553, 'ruRU', 'Событие: Раи\'вош', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35554, 'ruRU', 'Новости с Пиков Арака', 'Поговорите с Боудриком Греем в своем гарнизоне в Долине Призрачной Луны.', 'В твое отсутствие тебя искал какой-то подозрительный человек. Он сказал, что работает на... какого-то Грея, что ли... и у него есть информация по Пикам Арака, которая должна тебя заинтересовать.\n\nОн просил тебе это передать. Что я, собственно, и сделала.\n\nДа, вот еще что – пока ты здесь, хочу сказать: спасибо за все то, что ты для нас $gсделал:сделала;. Ты и твоя армия вступились за нас, хотя могли этого и не делать. Мы этого не забудем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35555, 'ruRU', 'Событие: Темный Коготь', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35556, 'ruRU', 'Тайны Горгронда', 'Найдите Ирель в Диколесье в Горгронде. Чтобы отправиться к ней, поговорите с укротителем грифонов в своем гарнизоне.', 'Командир! Ирель и Мараад придумали тактический ход.$b$bОни советуют отправить небольшой отряд на север, в дикие земли Горгронда.$b$bВ сообщениях от их рангари предполагается, что в тех землях можно найти изначальные знания, которые помогут найти слабые места Железной Орды.$b$bЕсли согласишься туда отправиться, знай – я уже приготовил для тебя грифона.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35557, 'ruRU', 'Тайны Горгронда', 'Встретьтесь с Дуротаном в Горгронде.', 'Командир, Дуротану нужна помощь. Он ведет небольшой отряд в Горгронд, чтобы контратаковать расположенные там крепости Железной Орды. $b$bВ Горгронде базируется клан Черной горы, отвечающий за индустриальную мощь Железной Орды.$b$bТакже там живут одни из наиболее опасных гигантов и монстров на всем Дреноре.$b$bЕсли хочешь ответить на этот призыв, то отправляйся в Горгронд по восточной стороне Хребта Ледяного Огня, через Грозовой Перевал.', '', '', '', '', '', 'Встретьтесь с Дуротаном в Горгронде.', 25549);
