INSERT INTO `quest_template_locale` VALUES (35611, 'ruRU', 'Возвращение в Гнездовье Терокк', 'Поговорите с Решадом в Гнездовье Терокк.', '<К лапе калири привязана небольшая записка.>$B$B\"Перси должен принести тебе корзину – если, конечно, не сбросит ее где-нибудь по дороге. Прими ее в знак моей благодарности и прости за тот инцидент с разведчиком.$B$BПрошу тебя срочно вернуться в Гнездовье Терокк, чтобы мы закончили запланированные дела.$B$BРешад\"', '', '', '', '', '', 'Поговорите с Решадом в Гнездовье Терокк.', 25549);
