INSERT INTO `quest_template_locale` VALUES (35632, 'ruRU', 'Урок археологии', 'Достаньте загадочный артефакт.', 'Для археолога очень важно делать великие открытия и вносить свой вклад в науку. Почему? Потому что только так ты можешь сделать себе имя!$b$bДаже этот балбес Харрисон Джонс сумел стать более-менее известным. А уж если у него это получилось – у тебя и подавно получится!$b$bКлан Верховного Молота прячет в своей пещере что-то очень важное, и нам непременно нужно проникнуть туда и стащить это у них прямиком из-под носа!$b$bВот, возьми вот этот маячок телепортации и отправляйся вглубь пещеры. Как только найдешь реликвию, установи маяк, и моя группа обо всем позаботится!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35633, 'ruRU', 'Невеселая разведка', 'Соберите $1oa |4кошелек:кошелька:кошельков; рангари с мертвых рангари.', 'Моего отряда больше нет. Часть бойцов погибла, но это все, что мы знаем. Остальные же... они, должно быть, остались там.$b$bСтупай и отыщи тела погибших бойцов моего отряда. При каждом из них должен быть небольшой кошелек с дорогими сердцу безделушками. Мне бы хотелось вернуть эти вещи семьям погибших.$b$bЯ отправлюсь вперед. Встретимся на болоте.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35634, 'ruRU', 'Самое главное – это контроль', 'Принесите пульт управления от турели апекситов темному провидцу Раастоку в Гнездовье Терокк.', 'Апекситовые технологии поражают, правда? Механизмы, работающие на солнечной энергии. Энергии, самой по себе напитанной магией!$B$BПросто потрясающе!$B$BАх, но тут есть подвох. И, кажется, тебе удалось его найти.$B$BОтнеси пульт управления обратно в Гнездовье Терокк, хорошо? Я буду следом – только захвачу апекситовые стержни.$B$BЕсли моя теория верна, мы сможем повернуть оружие приверженцев против них самих!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35636, 'ruRU', 'Дань уважения', 'Добудьте перо Сита и \"Сказание о Терокке\".', 'Незадолго до атаки на Скеттис здесь побывала группа Приверженцев. Навыки маскировки меня не подвели: стоило прикинуться грибом, и эти разини меня не заметили.$B$BА вот моему соседу повезло меньше...$B$BЕсли не ошибаюсь, старина собрал у себя множество ценных текстов. Может, вы и найдете в его хижине что-нибудь ценное, если ты дашь Решаду немного времени.$B$BКстати, не $gмог:могла; бы ты прихватить какое-нибудь из его перьев и отнести его в святилище неподалеку от Гнездовья Терокк? Я знаю, он был бы безмерно этому рад.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35637, 'ruRU', 'Нападение на Земли Каменного Неистовства', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35638, 'ruRU', 'Несколько фрагментов артефакта', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35639, 'ruRU', 'КУЧА фрагментов артефакта', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35640, 'ruRU', 'Месть за павших', 'Убейте $1oa |4грибного разведчика:грибных разведчиков:грибных разведчиков;.', 'Мне... мне почти удалось выбраться. Почти все наши... погибли. Те, кто выжил... перестали быть сами собой.$b$bВиной тому эти споровые звери... Они пытались затащить нас вглубь болота... останови их.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35641, 'ruRU', 'Нападение на Земли Каменного Неистовства', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35642, 'ruRU', 'Таинственный стручок', 'Отнесите светящийся красный стручок Хаано в Багровую топь, что в Горгронде.', 'Этот стручок похож на все остальные стручки, растущие на трупах и возле них, только он как-то странно пульсирует.$b$bХаано определенно заинтересуется им.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35643, 'ruRU', 'Награнд – Сокровище 062 – Набор покорителя гор', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35644, 'ruRU', 'Жалость к выжившим', 'Убейте $1oa |4покрытого плесенью шаркуна:покрытых плесенью шаркунов:покрытых плесенью шаркунов;.', 'Теперь ты $gсам:сама; видишь, что тем, кто погиб, еще повезло. Выжившие теперь бесцельно блуждают по округе, нападая на всех, кто еще не заражен этими гнусными спорами.$b$bМне не хватает духу убить этих несчастных, но если ты проявишь милосердие к ним, я буду перед тобой в большом долгу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35645, 'ruRU', 'Секрет грибов', 'Соберите $1oa |4светящийся гриб:светящихся гриба:светящихся грибов;.', 'Я начинаю ощущать... сильную... связь между грибницей и существами, обитающими на ней. Некоторые из грибов обладают большей силой по сравнению с остальными.$b$bДумаю, если бы у меня были образцы таких грибов, я бы смог с их помощью вычислить источник заразы... и разобраться с ним.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35646, 'ruRU', 'Награнд – Клад 006 – Припасы Хитрой Шестеренки', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35647, 'ruRU', 'Жуткий урожай', 'Принесите Хаано $1oa |4споровый стручок:споровых стручка:споровых стручков; грибных топотунов.', 'Чем дальше мы углубляемся в болото, тем больше встречаем спор. Но мне кажется, что ключ к разгадке кроется в этих больших грибозверях.$b$bУбей их и принеси мне их мешочки со спорами. Они понадобятся мне, чтобы... сузить область поиска.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35648, 'ruRU', 'Награнд – Сокровище 005 – Припасы Хитрой Шестеренки', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35649, 'ruRU', 'Топь Терзаний', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35650, 'ruRU', 'Глава III: pитуал Обугленных', 'Убейте $1oa |4древнего:древних:древних;.', 'На моих глазах древние совершили какой-то странный ритуал. Они вошли в огонь, сжигая свои листья и опаляя кору.\n\nЯ называю этот ритуал \"Ритуалом Обугленных\". Если мы хотим ослабить древних, нужно избавиться от них, пока они не стали еще сильнее.\n\nФренна', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35651, 'ruRU', 'Глава II: жатва', 'Убейте Онтогена Жнеца.', 'Я видела, как некое существо разжигало в юных саженцах древних ярость и ненависть ко всему, что отличается от них.\n\nПолагаю, именно этот ботани и виновен в необычно агрессивном поведении древних здесь в Хитросплетении.\n\nМожет, в наших интересах убить этого ботани? Боюсь, одной мне с ним нипочем не совладать.\n\nФренна', '', '', 'Онтоген Жнец', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35652, 'ruRU', 'Растим лес', 'Соберите $1oa |4порцию:порции:порций; древнего сока ботани или древних.', 'Лесопилка уже построена – но нам нужно больше дерева!\n\nРангари говорят, что ботани приспособились очень быстро растить древних при помощи какой-то жидкости.\n\nПринеси мне несколько образцов этого... сока, и я пущу их в дело.\n\nЧто? О, Глиза? Нашел я ее недавно, и вот что скажу – она кое-что смыслит в рубке леса. Заберу ее потом с собой на аванпост.\n\nВстретимся в Хитросплетении, если я его найду, конечно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35654, 'ruRU', 'Глава I: посев', 'Уничтожьте $1oa |4опыленный стручок:опыленных стручка:опыленных стручков;.', 'В Хитросплетении есть такие странные светящиеся штуки, которые, похоже, опыляют разные жалящие твари.\n\nБотани иногда собирают то, что выделяют стручки. Не знаю точно, что это, но это может быть для нас опасно.\n\nФренна', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35656, 'ruRU', 'Поиск по зову сердца', 'Выясните, что происходит в Багровой топи.', 'Я чувствую присутствие на болоте какой-то мощной силы, $p. Это не так далеко отсюда.$b$bСходи посмотри, что это такое, а я пока закончу с этим. Я тебя догоню...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35659, 'ruRU', 'В самое сердце топи', 'Следуйте за Хаано вглубь Багровой топи и разберитесь с угрозой.', 'Меня словно молотом по голове колотят. Это невыносимо, но я должен выполнить свою миссию. Я съел достаточно спор, и теперь я точно знаю, куда идти и что делать.$b$bЯ найду источник и помогу распространить... нет! Уничтожить его! Я сделаю то, что должно быть сделано!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35660, 'ruRU', 'Награнд – Сокровище 052 – Заросший грибами сундук', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35661, 'ruRU', 'Награнд – Сокровище 054 – Цветок грез', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35662, 'ruRU', 'Награнд – Сокровище 053 – Припасы Хитрой Шестеренки', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35663, 'ruRU', 'Урок работы в команде', 'Раздобудьте $oa |4загадочный артефакт:загадочных артефакта:загадочных артефактов;.', 'Успех археологической экспедиции определяется тем, насколько эффективно налажена работа в команде. А ключ к эффективной работе в команде заключается в понимании того, когда нужно брать, а когда – отдавать.$b$bОгры клана Верховного Молота последнее время занялись раскопками в ущелье в поисках ценных артефактов. Я предлагаю тебе объединить усилия с ограми Верховного Молота во имя археологии!$b$bПомнишь, что я только что говорил о том, как брать и отдавать? Огры дали нам шанс сэкономить кучу сил и времени на раскопках – эту часть работы они сделали за нас. Теперь тебе остается только забрать у них найденные артефакты и принести их мне!$b$bПрекрасный пример командной работы!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35664, 'ruRU', 'Сеятели плохих новостей', 'Сожгите $1oa |4труп древнего-сеятеля:трупа древних-сеятелей:трупов древних-сеятелей;.', 'Убить сеятеля – дело нехитрое, но сами семена при этом выживают. Из них вырастают новые сеятели – и на это уходят вовсе не годы, а буквально считанные часы.$b$bЕсли не уничтожать останки, скоро их расплодится столько, что мы с ними уже не справимся.$b$bНо мы выяснили, что их можно сжечь, и тогда ничего такого не произойдет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35665, 'ruRU', 'Мы не одни', 'Осмотрите лагерь Железной Орды в Серной низине.', 'Командир, я засекла неподалеку солдат Железной Орды.$b$bДаже для них слишком смело углубляться так далеко на столь опасную территорию.$b$bЕсли мы не прогоним их сразу, наверняка они вскоре изрядно попортят нам нервы.$b$bМожешь помочь мне и осмотреть их лагерь, пока я получше разведаю каньоны?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35666, 'ruRU', 'Рангари в трясине', 'Отыщите Хаано возле Багровой топи в Горгронде.', 'Горгронд – очень опасная земля. Наши разведотряды отправились в ближайшие регионы.$b$bОдин из этих отрядов ушел на болото, которое мы называем Багровая топь, и как сквозь землю провалился. Прошу тебя, отыщи пропавших разведчиков или хотя бы принеси мне их отчет – если получится.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35667, 'ruRU', 'Собиратели Черепов в Багровой топи', 'Отыщите Грулкора у Багровой топи в Горгронде.', 'Отряд Грулкора часто пропадает целыми неделями и возвращается, только когда груда трофеев и припасов становится такой, что они уже не могут ее тащить. Но в этот раз его нет слишком долго.$b$bОн упомянул, что впервые отправляется на охоту в Багровую топь. Узнай, жив ли он еще.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35668, 'ruRU', 'Тайна Сита', 'Добудьте Глаз Анзу.', 'Наш покойный друг скрывал здесь не только свою любовь к старым свиткам и романы о любовных похождениях чародеев. У него было нечто поистине ценное.$B$BЕсли я правильно понял его заметки, он утверждает, будто бы нашел Глаз Анзу – хрустальный шар, которым Терокк пользовался уже после своего падения.$B$BНам нужен этот шар! Записки говорят, что Сит припрятал его в логове опустошителей вверх по дороге.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35669, 'ruRU', 'Разыскивается: Кихо', 'Добудьте отрубленную лапу Кихо, убив Кихо Дикаря.', 'Размещено: бригадиром Горнеком$B$BСаблерон по прозвищу Кихо стал настоящим бедствием для Павшего Топора.$B$BНедавно он напал на батраков, работающих в ночную смену, убил их, а трупы утащил к себе в логово.$B$BТот, кто уничтожит саблерона и в доказательство принесет его отрубленную лапу, будет щедро вознагражден.', '', '', 'Кихо Дикарь', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35670, 'ruRU', 'Разыскивается: Хребторез', 'Добудьте панцирь Хребтореза.', 'Размещено: Киллгой$B$BЯ щедро вознагражу любого, кто принесет мне панцирь Хребтореза.$B$BХочу соорудить себе славный доспех, но мне не хватит умения сладить с таким зверем.$B$BТолько поосторожнее, лишних дырок в нем не наделайте.', '', '', 'Хребторез', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35671, 'ruRU', 'Сбор теней', 'Войдите в Гнездовье Терокк с Решадом.', 'Гнездовье Терокк прямо перед нами.$B$BНадеюсь, остальные добрались сюда в целости.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35672, 'ruRU', 'Разыскивается: Ядошипа', 'Убейте Ядошипу.', 'Размещено: Хутоу Воздушным Пером$B$BДаже высшие араккоа трепещут перед Ядошипой – грозой небес Арака.$B$BНашим всадникам из-за нее не подобраться к Павшему Топору, и мы не получаем важных поставок.$B$BМне не надо доказательств ее смерти – просто сделай так, чтобы крик ее больше никогда не раздался среди наших пиков.$B$BЕе гнездо – над Воющим утесом к северо-востоку.', '', '', 'Ядошипа', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35673, 'ruRU', 'Награнд – Клад 014 – Захваченные припасы Песни Войны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35674, 'ruRU', 'Разыскивается: Кихо', 'Добудьте отрубленную лапу Кихо, убив Кихо Дикаря.', 'Размещено: лейтенантом Виллемом$B$BКихо, чудовищный саблерон, по ночам повадился нападать на Южный порт. Мы теряем людей десятками.$B$BЯ предлагаю солидный куш тому, кто выследит Кихо и принесет мне его отрубленную лапу.', '', '', 'Кихо Дикарь', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35675, 'ruRU', 'Разыскивается: Хребторез', 'Добудьте панцирь Хребтореза.', 'Размещено: интендантом Милагой$B$BУ нас не хватает материалов, чтобы чинить доспехи наших воинов.$B$BЯ предлагаю солидную сумму за панцирь опустошителя Хребтореза. Его хватит на многие недели.', '', '', 'Хребторез', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35676, 'ruRU', 'Разыскивается: Ядошипа', 'Убейте Ядошипу.', 'Размещено: Фалрогом$B$BЯдошипа мне всю жизнь отравляет. Орет как резаная, мешает спокойно пропустить стаканчик.$B$BКто-нибудь, убейте ее, наконец. Доказательств мне не нужно. Главное – тишина и покой.', '', '', 'Ядошипа', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35677, 'ruRU', 'Сокровище: Затонувшая рыбацкая лодка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35678, 'ruRU', 'Награнд – Сокровище 015 – Сейф Песни Войны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35679, 'ruRU', 'Гарнизонная кампания: Падение Шаттрата', 'Поговорите с экзархом Маладааром у Шпиля Света в Таладоре.', 'Здравствуй, $n. У меня еще одно сообщение от верховного мага Кадгара.$B$BМы больше не можем игнорировать присутствие Сокретара в Шаттрате, где он распространяет свое опасное учение, с каждым днем привлекая на свою сторону все больше дренеев.$B$BНастало время положить этому конец.$B$BЭкзарх Маладаар уже дожидается тебя у Шпиля Света в Таладоре. Удачи, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35680, 'ruRU', 'Гарнизонная кампания: Падение Шаттрата', 'Поговорите с леди Лиадрин у Шпиля Света в Таладоре.', 'Здравствуй, $n. У меня еще одно сообщение от верховного мага Кадгара.$B$BМы больше не можем игнорировать присутствие Сокретара в Шаттрате, где он распространяет свое опасное учение, с каждым днем привлекая на свою сторону все больше дренеев.$B$BНастало время положить этому конец.$B$BЛеди Лиадрин уже дожидается тебя у Шпиля Света в Таладоре. Удачи, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35682, 'ruRU', 'Награнд – Сокровище 016 – Копье Песни Войны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35683, 'ruRU', 'Освобождение города', 'Соберите $1oa |4саргерайский знак различия:саргерайских знака различия:саргерайских знаков различия;.', 'Наступление на Шаттрат идет полным ходом, но сам Сокретар до сих пор не показался на поле брани.$B$BНесмотря на все наши усилия, мы пока не смогли пробиться во внутренний Шаттрат. Оборона купола слишком сильна.$B$BНо мне кажется, что есть способ выманить Сокретара из его укрытия. Убей его офицеров и рядовых бойцов и собери их знаки различия.$B$BКогда мы предъявим ему доказательства гибели его приспешников, он наверняка придет в ярость и выйдет мстить за них.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35684, 'ruRU', 'Освобождение города', 'Соберите $1oa |4саргерайский знак различия:саргерайских знака различия:саргерайских знаков различия;.', 'Наступление на Шаттрат идет полным ходом, но сам Сокретар до сих пор не показался на поле брани.$B$BНесмотря на все наши усилия, мы пока не смогли пробиться в центральную часть города, где он укрылся.$B$BНо мне кажется, что мы сможем выманить его оттуда. Убей его офицеров и рядовых бойцов и собери их знаки различия.$B$BКогда мы предъявим ему доказательства гибели его приспешников, он наверняка придет в ярость и выйдет мстить за них.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35685, 'ruRU', 'Гибель Сокретара', 'Убейте Сокретара.', 'Я буду ждать тебя у входа под купол Шаттрата.$B$BТам мы бросим вызов саргерайскому командиру. Если он примет вызов, то там и встретит свою смерть.$B$BСущество, ныне именующее себя Сокретаром, когда-то было одним из нас. Хотелось бы мне надеяться, что в нем еще осталось хоть немного Света.', '', '', 'Сокретар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35686, 'ruRU', 'Ярость и мудрость', 'Поговорите с рангари Эрдани на Хребте Скорби.', 'Между обитателями восточных джунглей и зверями, населяющими западную пустошь, идет бесконечная война.$b$bЕсли в ней определится победитель, он вскорости приберет к рукам весь Дренор.$b$bРангари Эрдани по моему приказу отправилась в самое сердце битвы между враждующими сторонами. ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35687, 'ruRU', 'Гибель Сокретара', 'Убейте Сокретара.', 'Я буду ждать тебя у входа под купол Шаттрата.$B$BТам мы и бросим вызов саргерайскому командиру. Если он примет вызов, то встретит свою смерть.$B$BНе буду отрицать, что я давно уже жду этого, $n.', '', '', 'Сокретар', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35688, 'ruRU', 'Событие: Энавра Варанди', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35689, 'ruRU', 'Несколько фрагментов артефакта', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35690, 'ruRU', 'Горстка фрагментов артефакта', '', '', '', '', '', '', '', 'На этот раз ты $gсделал все, что мог:сделала все, что могла;, $n.', 19865);
INSERT INTO `quest_template_locale` VALUES (35691, 'ruRU', 'КУЧА фрагментов артефакта', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35692, 'ruRU', 'Награнд – Сокровище 010 – Пресноводный моллюск', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35693, 'ruRU', 'Суровое напоминание', 'Убейте $1oa |4обитателя:обитателей:обитателей; пустоши на Хребте Скорби.', 'Добро пожаловать на фронт, командир! Здесь в смертельной схватке сошлись дикие джунгли и бесплодные пустоши.$b$bБитва внизу идет полным ходом, и мне кажется, что одна из сторон начинает одерживать верх. Допустить этого ни в коем случае нельзя.$b$bМалые гронны уже теснят жителей восточных лесов, и их нужно остановить, пока они не стали явной угрозой для Верхнего Пути.$b$bТак что ты пока займись сокращением их численности, а я тем временем переберусь поближе к месту сражения. Когда закончишь, отыщи меня на Хребте Скорби.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35694, 'ruRU', 'Награнд – Сокровище 011 – Золотое яйцо калири – TSH', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35695, 'ruRU', 'Награнд – Сокровище 022 – Тайник Песни Войны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35696, 'ruRU', 'Награнд – Сокровище 048 – Тайник Пылающего Клинка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35697, 'ruRU', 'Мирное подношение', 'Доставьте ящик кактусового десерта темному ведуну Ириззару на Пики Арака.', 'Нам нужны союзники в этом горном краю, и побыстрее.$B$BКомандир, я полагаю, благоразумно будет поискать помощи.$B$BК юго-востоку отсюда, неподалеку от логова опустошителей, живет араккоа-изгой. Звери его не трогают. Полагаю, он располагает полезными сведениями о них.$B$BА у меня остался последний ящик кактусового десерта. Это – наш лучший вариант, $Gсэр:мэм;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35699, 'ruRU', 'Мирное подношение', 'Доставьте ящик североземского портвейна темному ведуну Ириззару.', 'Нам очень пригодились бы торговые партнеры, командир.$B$BК северо-востоку отсюда, почти в самом логове опустошителей, живет араккоа-изгой. Как думаешь, нам удастся с ним договориться? Должно быть, ему известен какой-то секрет, позволяющий отпугивать зверей.$B$BА у меня остался последний ящик североземского портвейна. Возможно, нам удастся убедить отшельника в наших добрых намерениях.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35701, 'ruRU', 'Отслеживание: Сокровища мельницы 1', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35702, 'ruRU', 'Железные цепи', 'Победите капитана Браку и найдите Сердце магнарона.', 'Артефакт почти у нас в руках.$b$bГотовься к битве. Если они действительно научились управлять гроннами, все может оказаться сложнее, чем мы ожидали.$b$bЯ помогу тебе сражаться, когда будешь на месте.', '', '', 'Капитан Брака', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35703, 'ruRU', 'Отслеживание: Преграда на пути к сокровищу мельницы 1', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35704, 'ruRU', 'Когда все сходится', 'Отправьтесь в полет на Ка\'алу и убейте $1oa |4приверженца:приверженцев:приверженцев;.', 'Говорящие с воронами послушники снаряжены пультами управления от турели апекситов, им нужно только подобраться достаточно близко.$B$BПойдем, пора подняться в небо и захватить Террасу Рассвета.$B$BКогда все будет готово, нам нужно будет развернуть ложные солнца друг против друга. Пики сгорят, словно факелы!$B$BЖду не дождусь, когда смогу вписать твои подвиги в историю.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35705, 'ruRU', 'Самые выгодные цены!', 'Поговорите с Микси Разор на Темноводном болоте.', 'Командир, две гоблинши-контрабандистки – Микси и Трикси Разор – недавно были здесь, а теперь ушли на восток, к болоту.$B$BУ них в грузе только буровые установки, а оружия нет.$B$BБьюсь об заклад, они добудут то сырье, которое нужно нам, а мы можем взамен обеспечить им защиту.$B$BПолагаю, было бы неплохо их разыскать, командир.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35706, 'ruRU', 'Грязное дело', 'Добудьте $1oa |4намокшую батарейку:намокшие батарейки:намокших батареек;.', 'Мы везли батарейки к месту раскопок, и я разбила свою проклятую колымагу!$B$BМоя сестрица даже не оглянулась. Ну подумаешь, в поворот не вписалась – бывает!$B$BНо дело в том, что батарейки разлетелись повсюду, а мне не с руки ползать и собирать их.$B$BНу что? Поможешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35707, 'ruRU', 'Хитросплетение', 'Поговорите с Пенни Поппинстук рядом с Хитросплетением.', 'Привет, душечка. Лесопилка уже готова, но нам надо придумать способ, как быстро заготавливать древесину.\n\nПомнится, в клане Веселого Черепа были разговоры о каком-то месте под названием Хитросплетение... так вот – там ботани все так выращивают – ну моментально быстро.\n\nЯ отправляюсь туда.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35708, 'ruRU', 'Хитросплетение', 'Поговорите с Глирином рядом с Хитросплетением.', 'Рангари тут уже давно, и они слышали рассказы клана Веселого Черепа о месте, которое называют Хитросплетением.\n\nПохоже, это родина весьма злобных древних, и ботани используют какие-то особые ростки, чтобы выращивать их побыстрее.\n\nДумаю, мы сможем использовать это на пользу аванпосту. Любое дерево сгодится, так ведь?\n\nВстретимся там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35709, 'ruRU', 'Сокровище: Тайник Веселого Черепа I', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35711, 'ruRU', 'Награнд – Сокровище 059 – Упорство Абу\'гара', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35712, 'ruRU', 'Награнд – Событие – Босс 012 – Краснокоготь Дикий', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35713, 'ruRU', 'Близнецы Портачи', 'Поговорите с Филбертом Портачом на Темноводном болоте.', 'Командир, пока тебя не было, здесь проходили два гнома-торговца, Филберт и Дилберт Портачи. Они ушли на восток, к болоту.$B$BУ них были только буровые установки, а оружия не было.$B$BКак насчет того, чтобы предложить им защиту в обмен на добытое сырье?$B$BЕсли ты собираешься на поиски, я сейчас отмечу на карте, куда они пошли.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35714, 'ruRU', 'Награнд – Событие – Босс 001 – Великое Перо', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35715, 'ruRU', 'Награнд – Событие – Босс 002 – Гар\'луа, Мать-волчица', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35716, 'ruRU', 'Грязное дело', 'Добудьте $1oa |4намокшую батарейку:намокшие батарейки:намокших батареек;.', 'Отряд араккоа выследил нас по дороге к месту раскопок и уничтожил наш караван. Мы с братом еле ноги унесли из этой преисподней.$B$BДа, Портачи – на все руки мастера!$B$BНо я не могу оставить здесь батарейки для бурильных установок. Они увязли в топи – никак не получается их вытащить.$B$BДостань их для меня, а?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35717, 'ruRU', 'Награнд – Событие – Босс 015 – Узлокопытень Бешеный', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35718, 'ruRU', 'Снова здорово', 'Поговорите с Трикси Разор в Гнездовье Зекк.', 'Да, я теперь у тебя в долгу. Но есть еще одна просьба...$B$BМожешь отправиться на место раскопок и сообщить моей сестрице, что я скоро буду? Я тут все обстряпаю и раздобуду новый драндулет, чтобы отбуксировать этот.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35719, 'ruRU', 'Снова здорово', 'Поговорите с Дилбертом Портачом в Гнездовье Зекк.', 'Теперь, когда батарейки выужены из топи, я могу вызвать гирокоптеры, чтобы их отвезли в лагерь.$B$BЯ подожду гирокоптеры тут, но тебе следует отправиться к моему брату Дилберту и рассказать о том, что случилось. Он, должно быть, места себе не находит!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35725, 'ruRU', 'Событие: Яркочар', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35730, 'ruRU', 'Прижигание ран', 'Добудьте горящую головню и прижгите раны Ниши.', 'Ты $gспас:спасла; Нишу, мою верную подругу. Я в огромном долгу перед тобой.$b$bЖелезная Орда разлучила меня с ней, но больше я на такой обман не поддамся.$b$bЖелезная Орда нанесла ей множество ран, но, боюсь, для полного излечения нам придется снова причинить ей боль.$b$bМожешь принести горящую головню из костра и прижечь раны? $b$bА я подержу ее, чтобы она не кусалась.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35731, 'ruRU', 'Событие: Ба\'руун', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35732, 'ruRU', 'Событие: Шинри', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35733, 'ruRU', 'Обряды жрецов Когтя', 'Положите молоток Терокка на чучело Терокка.', 'Этот молоток когда-то носил гордое имя \"Клюволом\". На закате своих дней, что уже были черны, как ночь, Терокк пускал его в ход, устраивая отвратительные жертвоприношения. \n\nОб этих временах лучше не вспоминать.\n\nТерокка заточили в глубокой темнице теней, чтобы он мог обрести покой и, возможно, исцелиться.\n\nЧтобы связаться с ним, нам потребуется приложить немало усилий – так что пока позволь мне поведать тебе о его куда более достойных деяниях. В те времена проклятие еще не довлело над ним.\n\nПожалуйста, положи молоток на чучело.', '', '', '', '', '', 'Положите молоток Терокка на чучело Терокка.', 25549);
INSERT INTO `quest_template_locale` VALUES (35734, 'ruRU', 'Король воронов', 'Воспользуйтесь чучелом Терокка, чтобы восстановить события боя с воинами Кровавой Гривы. Убейте $1oa |4мелкоклыка Кровавой Гривы:мелкоклыков Кровавой Гривы:мелкоклыков Кровавой Гривы;, $2oa |4взрослого саблерона Кровавой Гривы:взрослых саблеронов Кровавой Гривы:взрослых саблеронов Кровавой Гривы; и Вожака стаи Караша.', '<Слушая повествование Решада о славных деяниях Терокка, вы внезапно останавливаете взгляд на клинках, висящих у чучела на поясе.\n\nВ Скеттисе они выглядели совершенно непримечательными, но теперь буквально излучают энергию, словно пробужденные словами хранителя свитков.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35735, 'ruRU', 'Награнд – Событие Босс 021 – Крошшер-берсерк', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35736, 'ruRU', 'Письмена на снегу', 'Отнесите изорванную страницу из дневника Рокхану в гарнизон.', 'Это вырванная страница из дневника темной охотницы Бву\'и. Похоже, на ней нарисован вход в невольничьи шахты Кровавого Молота. Рокхан из гарнизона наверняка заинтересуется этим.', '', '', '', '', '', 'Вернитесь к Рокхану в свой гарнизон.', 19865);
INSERT INTO `quest_template_locale` VALUES (35737, 'ruRU', 'Письмена на снегу', 'Отнесите изорванную страницу из дневника Боудрику Грею в гарнизон.', 'Это вырванная страница из дневника Овинна Граддока. Похоже, на ней нарисован вход в невольничьи шахты Кровавого Молота. Боудрик Грей из гарнизона наверняка заинтересуется этим.', '', '', '', '', '', 'Вернитесь к Боудрику Грею в свой гарнизон.', 25549);
INSERT INTO `quest_template_locale` VALUES (35738, 'ruRU', 'Природное топливо', 'Соберите $1oa |4кусок:куска:кусков; свежего угля с Древних.', 'Так у вас там логово контрабандистов, да?$B$BЯ бы с удовольствием с вами торговала, детка, но моя лазерная пушка совсем не пашет.$B$BЗнаешь что? Видишь этих Древних? Араккоа отлично поджарили их своим оружием – теперь эти Древние просто ходячие глыбы угля.$B$BНаковыряй мне немного угля, чтобы раскочегарить пушку, и ударим по рукам.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35739, 'ruRU', 'Природное топливо', 'Соберите $1oa |4кусок:куска:кусков; свежего угля с Древних.', 'А, так у вас там торговая лавка?$B$BФантастика!$B$BПредлагаю сделку. Ты помогаешь мне зарядить мою лазерную пушку, а я меняю часть этого термо…ультра…обсидигласа на оружие.$B$BАраккоа поджарили местных Древних своим оружием – теперь они просто ходячие глыбы угля. Наковыряй мне угольков!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35744, 'ruRU', 'Положить конец казням', 'Убейте $1oa |4палача:палачей:палачей; Железного Марша.', 'Мы спешили изо всех сил... но не поспели. Железная Орда захватила в плен несколько наших воинов.$b$bТеперь они, поди, пытают их, заставляют все рассказать.$b$bБоюсь, они казнят пленных, как только закончат с допросом. Времени мало.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35745, 'ruRU', 'Наступление Железной Орды', 'Убейте $1oa |4рубаку:рубак:рубак; Железного Марша.', 'Нам сообщили, что непосредственно перед атакой Темный портал окрашивается в красный цвет. Нападающие называют себя Железной Ордой.$b$bИх армия превосходно вооружена, а воинам нет числа.$b$bОни уже захватили форт Окрил\'лон и крепость Стражей Пустоты. Нашим войскам на передовой очень кстати пришлась бы твоя помощь, |3-6($c).', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35746, 'ruRU', 'В осаде', 'Выведите из строя $1oa |4\"Железный разрушитель\":\"Железных разрушителя\":\"Железных разрушителей\";.', 'Пушки Железной Орды просто уничтожают наших бойцов. Не знаю, сколько нам еще удастся продержаться. У нас кончаются войска.$b$bДолжен же быть какой-то способ справиться с этими боевыми машинами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35747, 'ruRU', 'Подъем на танк', 'Поговорите с Телином Темной Наковальней, затем сопроводите его на верхнюю площадку \"Железного разрушителя миров\".', 'Мы не можем допустить повторной активации Темного портала. Самое время нанести решительный удар.$b$bТелин уже должен был разобраться, как заставить танк работать. Возьми Телина с собой и направь орудие танка на Темный портал. Мы последуем за тобой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35748, 'ruRU', 'Спрятавшиеся разведчицы', 'Убейте $1oa |4разведчицу:разведчиц:разведчиц; Железной Орды.', 'Большая часть наших операций провалилась. За нами явно следят.$B$BУ Железной Орды здесь, в Выжженных землях, наверняка полно разведчиц. Победа ускользает от нас.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35750, 'ruRU', 'Безумные лейтенанты', 'Раздобудьте боевые планы Железной Орды.', 'Нам нужно получше узнать нашего нового врага.$b$bНаши разведчики обнаружили несколько лейтенантов Железной Орды. Для дикарей они действуют слишком уж организованно. Думаю, у этих лейтенантов должны быть какие-то планы военных операций. $b$bНужно раздобыть их – и никто не справится с этим делом лучше тебя, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35751, 'ruRU', 'Штурм Крепости Стражей Пустоты', 'Водрузите знамена Орды над крепостью Стражей Пустоты.', 'Железная Орда смогла захватить крепость Стражей Пустоты, но если они полагают, что мы сдадим им такой стратегически важный объект, они сильно заблуждаются.$b$bМои лучшие воины давно уже готовы пролить кровь этих дикарей. Они рвутся в бой, и дело за малым – нужен командир, который возглавит атаку, и этим командиром станешь ты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35759, 'ruRU', 'Награнд – Сокровище 065 – Брошенный груз', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35760, 'ruRU', 'Зуболом Разрушитель', 'Убейте Зуболома Разрушителя', 'Если принесенные тобой планы верны, то выходит, что огры клана Молота Ужаса виновны в наших бедствиях не меньше самой Железной Орды. Думаю, пора показать этим ограм, что мы об этом думаем.$b$bПохоже, больше всех с Железной Ордой контактирует один здоровенный огр по имени Зуболом. Если мы убьем его, то у нас появится шанс расстроить их планы.', '', '', 'Зуболом Разрушитель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35761, 'ruRU', 'Поиски вещей в Крепости Стражей Пустоты', 'Найдите топор Айтокка, флакон яда Неки и щит надзирательницы Струк.', 'Когда Железная Орда захватила Крепость Стражей Пустоты, мы напали на нее. Уничтожили всех ее воинов в крепости, но через портал к ним прибыло подкрепление и захватило форт Окрил\'лон. Сколькие же лишились душ из-за этих дикарей!$B$BМы будем вечно помнить тех, кто отдал свои жизни, защищая Крепость Стражей Пустоты. Если тебе вдруг попадутся на глаза личные вещи павших героев, прошу тебя, принеси их мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35762, 'ruRU', 'Смерть Молоту Ужаса!', 'Убейте $1oa |4огра:огров:огров; из клана Молота Ужаса.', 'Глупость и близорукость огров клана Молота Ужаса просто поражает меня. Очевидно, что Железная Орда просто использует их в своих целях.$b$bНо в любом случае мы должны показать ограм, что бывает с теми, кто смеет бросить вызов истинной Орде. Нам нужно показать ограм клана Молота Ужаса, как мы поступаем с нашими врагами.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35763, 'ruRU', 'Гар\'мак Фехтовальщик', 'Убейте Гар\'мака Фехтовальщика', 'Благодаря собранным тобой разведданным мы узнали, что штурм возглавляет орк Железной Орды по имени Гар\'мак Фехтовальщик. Он укрылся в форте Окрил\'лон.$B$BУбив его, войну мы не выиграем, но наверняка нарушим сообщение между боевыми подразделениями Железной Орды. Это даст нам драгоценное время на сбор новых сил и разработку планов по противодействию новой угрозе.', '', '', 'Гар\'мак Фехтовальщик', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35764, 'ruRU', 'Месть Окриллы', 'Отравите съестные припасы огров клана Молота Ужаса.', 'Огры клана Молота Ужаса думают, что одержали победу? Как бы не так. Вот, возьми этот яд и подлей буквально пару капель в их крысиный гуляш.$b$bЯд постепенно разъест их внутренности. Всех их ждет медленная и мучительная смерть – а иной они и не заслужили.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35765, 'ruRU', 'Награнд – Сокровище 049 – Набор авантюриста', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35766, 'ruRU', 'Я вижу умерших араккоа', 'С помощью Призракографера-12000 найдите и уничтожьте дух жрицы Когтя Зекк.', 'У меня тут непростая проблемка, и я надеюсь на твою помощь. Не знаю, на кого еще мне рассчитывать.$B$BМои работники говорят, что видят призрак араккоа, которая тут всем заправляла.$B$BЯ знаю, это бред, но я хочу попросить тебя взять мой \"Призракографер-12000\" и проверить ее останки.$B$BЕсли там привидение, \"Призракографер\" его обнаружит. А если нет, то получится, что мои работники просто отлынивают.', '', '', 'Жрица Когтя Зекк', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35778, 'ruRU', 'Награнд – Событие – Босс 020 – Древний Мастер клинка – TSH', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35782, 'ruRU', 'Я вижу умерших араккоа', 'С помощью Призракографера-12000 найдите и уничтожьте дух жрицы Когтя Зекк.', 'Слушай, не поможешь мне решить одну серьезную проблему?$B$BМои работники говорят, что видят призрак араккоа, которая тут всем заправляла.$B$BЯ, разумеется, ни на секунду в это не поверю, и все же... возьми-ка мой \"Призракографер-12000\" и проверь ее останки.$B$BТак мы сможем убедиться, что у моих трудяг крыша еще не поехала.', '', '', 'Жрица Когтя Зекк', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35784, 'ruRU', 'Событие – босс', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35797, 'ruRU', 'Эбеновый охотник', 'Добудьте органический лазер, победив эбенового охотника.', 'Осталось только установить лазер, и можно будет приниматься за дело. Но мне пригодилась бы еще кое-какая помощь.$B$BК юго-востоку отсюда в устье реки живет и охотится споровое чудище. У него в голове есть орган, способный стрелять гораздо более мощным лучом, чем наш лазер.$B$BПринеси мне его.$B$BМы сможем ускорить добычу, если встроим его в наш механизм!', '', '', 'Эбеновый охотник', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35798, 'ruRU', 'Сокровище: светящийся пещерный цветок', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35807, 'ruRU', 'Почетный трофей: Эрозиан', 'Отнесите трофей Дуротану на Звериную заставу в Горгронде.', 'Вы победили Эрозиана и завоевали достойный восхищения трофей.$b$bОтнесите его Дуротану на Звериную заставу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35808, 'ruRU', 'Почетный трофей: Эрозиан', 'Отнесите трофей Марааду на Верхний Путь в Горгронде.', 'Вы победили Эрозиана и завоевали достойный восхищения трофей.$b$bОтнесите его Марааду на Верхний Путь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35809, 'ruRU', 'Почетный трофей: Иссушитель', 'Отнесите трофей Марааду на Верхний Путь в Горгронде.', 'Вы победили Иссушителя и завоевали достойный восхищения трофей.$b$bОтнесите его Марааду на Верхний Путь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35810, 'ruRU', 'Почетный трофей: Иссушитель', 'Отнесите трофей Дуротану на Звериную заставу в Горгронде.', 'Вы победили Иссушителя и завоевали достойный восхищения трофей.$b$bОтнесите его Дуротану на Звериную заставу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35811, 'ruRU', 'Почетный трофей: владыка кратера Игний', 'Отнесите трофей Дуротану на Звериную заставу в Горгронде.', 'Вы победили владыку кратера Игния и завоевали достойный восхищения трофей.$b$bОтнесите его Дуротану на Звериную заставу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35812, 'ruRU', 'Почетный трофей: владыка кратера Игний', 'Отнесите трофей Марааду на Верхний Путь в Горгронде.', 'Вы победили владыку кратера Игния и завоевали достойный восхищения трофей.$b$bОтнесите его Марааду на Верхний Путь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35813, 'ruRU', 'Почетный трофей: Грибной преторианец', 'Отнесите трофей Марааду на Верхний Путь в Горгронде.', 'Вы победили Грибного преторианца и завоевали достойный восхищения трофей.$b$bОтнесите его Марааду на Верхний Путь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35814, 'ruRU', 'Почетный трофей: Грибной преторианец', 'Отнесите трофей Дуротану на Звериную заставу в Горгронде.', 'Вы победили Грибного преторианца и завоевали достойный восхищения трофей.$b$bОтнесите его Дуротану на Звериную заставу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35815, 'ruRU', 'Почетный трофей: Чарл Смертекрылый', 'Отнесите трофей Дуротану на Звериную заставу в Горгронде.', 'Вы победили Чарла и завоевали достойный восхищения трофей.$b$bОтнесите его Дуротану на Звериную заставу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35816, 'ruRU', 'Почетный трофей: Чарл Смертекрылый', 'Отнесите трофей Марааду на Верхний Путь в Горгронде.', 'Вы победили Чарла и завоевали достойный восхищения трофей.$b$bОтнесите его Марааду на Верхний Путь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35817, 'ruRU', 'Почетный трофей: Ревудан Небесный Ужас', 'Отнесите трофей Марааду на Верхний Путь в Горгронде.', 'Вы победили Ревудана и завоевали достойный восхищения трофей.$b$bОтнесите его Марааду на Верхний Путь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35818, 'ruRU', 'Почетный трофей: Ревудан Небесный Ужас', 'Отнесите трофей Дуротану на Звериную заставу в Горгронде.', 'Вы победили Ревудана и завоевали достойный восхищения трофей.$b$bОтнесите его Дуротану на Звериную заставу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35819, 'ruRU', 'Почетный трофей: Каргакс Пожиратель', 'Отнесите трофей Дуротану на Звериную заставу в Горгронде.', 'Вы победили Каргакса и завоевали достойный восхищения трофей.$b$bОтнесите его Дуротану на Звериную заставу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35820, 'ruRU', 'Почетный трофей: Каргакс Пожиратель', 'Отнесите трофей Марааду на Верхний Путь в Горгронде.', 'Вы победили Каргакса и завоевали трофей, которым не стыдно похвалиться на своем аванпосте. $b$bОтнесите трофей Марааду – это прославит вас еще больше!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35828, 'ruRU', 'Я сорвал агро... культуру', 'Встретьтесь с Телином Темной Наковальней в Диколесье.', '$p? Как же я рад тебя видеть.$b$bЯ тут пытался отвязаться от генезотавра, но наткнулся на лагерь рангари.$b$bГлазом моргнуть не успел – земля задрожала, и из нее поперли злобные растения.$b$bЯ едва успел выбраться из танка, как проклятый генезотавр отшвырнул его, точно пустое ведро.$b$bЯ собираюсь вернуться на дорогу и поискать танк.$b$bУвидимся там, когда закончишь.', '', '', '', '', '', 'Встретьтесь с Телином Темной Наковальней в Диколесье.', 25549);
INSERT INTO `quest_template_locale` VALUES (35834, 'ruRU', 'След генезотавра', 'Уничтожьте $1oa |4агрессивное растение:агрессивных растения:агрессивных растений;.', 'Сначала в наш лагерь въехала здоровенная железная зверюга, а за ней следом примчался генезотавр и устроил тут дендрарий.$b$bОставленные генезотавром проявления необходимо истребить, чтобы мы смогли собрать свои пожитки перед бегством.$b$bЕсли хочешь помочь, убей как можно больше агрессивных растений, которые не дают нам покоя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35835, 'ruRU', 'Эбеновый охотник', 'Добудьте органический лазер, победив эбенового охотника.', 'Мы готовы установить лазер, но нам потребуется увеличить мощность, чтобы пробиться через породу.$B$BК юго-востоку отсюда в устье реки живет эбеновый охотник. У него в голове есть орган, способный стрелять гораздо более мощным лучом, чем наш лазер.$B$BНам нужна эта штуковина.$B$BПопробуй добыть ее, а мы пока подготовим лазер к работе.', '', '', 'Эбеновый охотник', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35836, 'ruRU', 'Награнд – босс события 008 – Ужас дна', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35837, 'ruRU', 'Гарнизонная кампания: В тылу врага', 'Найдите Джанин Амрелл в Тайном лагере в Награнде.', 'Джанин Амрелл, одна из моих лучших полевых агентов, находится в глубине территории Железной Орды на севере Награнда.$B$BОна докладывает, что вожди орочьих кланов планируют тайно собраться на сторожевом посту Мок\'гол.$B$BЭто отличная возможность разузнать об их планах.$B$BЯ хочу, чтобы ты немедленно $gвстретился:встретилась; с агентом Амрелл. Возможно, это наш шанс, $n!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35838, 'ruRU', 'Совет вождя', 'Узнайте, кто стоит за запиской.', 'При ближайшем рассмотрении вы находите кусочек пергамента, обернутый вокруг шеи погибшей.$B$BНа нем размашисто написано:$B$B\"ТАК БУДЕТ С КАЖДЫМ, КТО ПОЙДЕТ ПРОТИВ ЖЕЛЕЗНОЙ ОРДЫ!\"', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35839, 'ruRU', 'Военные планы', 'Найдите миниатюрную копию Горгорека, миниатюру боевой машины и карту Танаанских джунглей.', 'Мне удалось найти записи Джанин. Она упомянула несколько важных предметов поблизости, которые необходимо изучить поближе.$B$BК сожалению, ее скоропостижная гибель не позволила завершить начатое, но уж мы-то управимся.$B$BОбыщи лагерь, пока я отвлекаю орков.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35840, 'ruRU', 'Перехват приказов', 'Соберите приказы для воинов Хребта Ледяного Огня, Долины Призрачной Луны и Пиков Арака.', 'Разведка – ключ ко всему, $gмой друг:моя дорогая;. Чем больше мы узнаем о планах Адского Крика, тем легче будет их сорвать.$B$BОрки Мок\'Гола часто служат Адскому Крику курьерами, развозя его приказы отсюда по аванпостам всего Дренора.$B$BУбей этих наездников и забери у них все приказы, какие найдешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35841, 'ruRU', 'Стая без вожака', 'Убейте Вор\'гаша Вожака Стаи.', 'Управлять сторожевым постом Мок\'гол доверено могучему воину – Вор\'гашу Вожаку Стаи.$B$BЕсли мы убьем этого свирепого командира, то временно лишим противника связи.$B$BВор\'гаша ты найдешь на северо-востоке, он ходит там дозором.$B$BУбей его.', '', '', 'Вор\'гаш Вожак Стаи', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35842, 'ruRU', 'Стая без вожака', 'Убейте Вор\'гаша Вожака Стаи.', 'На сторожевом посту Мок\'гол командует Вор\'гаш Вожак Стаи.$B$BУбьем его – врагу придется худо.$B$BОн сейчас на северо-востоке, в дозор там ходит.$B$BУбей его.', '', '', 'Вор\'гаш Вожак Стаи', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35843, 'ruRU', 'Гарнизонная кампания: В тылу врага', 'Найдите темного охотника Засту в Тайном лагере в Награнде.', 'Ты $Gлегок:легка; на помине, командир.$B$BЯ тут отправил в тыл врага темного охотника.$B$BОн говорит, что вожди хотят тайно встретиться на сторожевом посту Мок\'гол.$B$BВот нам шансик-то и выпал – узнаем, чего задумал Адский Крик.$B$BСходи, поговори с Застой. Он скажет, что дальше делать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35844, 'ruRU', 'Совет вождя', 'Узнайте, кто стоит за запиской.', 'При ближайшем рассмотрении вы находите кусочек пергамента, обернутый вокруг шеи погибшего.$B$BНа нем размашисто написано:$B$B\"ТАК БУДЕТ С КАЖДЫМ, КТО ПОЙДЕТ ПРОТИВ ЖЕЛЕЗНОЙ ОРДЫ!\"', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35845, 'ruRU', 'Военные планы', 'Найдите миниатюрную копию Горгорека, миниатюру боевой машины и карту Танаанских джунглей.', 'Мне удалось найти записи Засты. Он видел, как лидеры клана Песни Войны устраивали встречи поблизости. Заста думает, что там можно найти информацию о планах Железной Орды.$B$BВсе что нам остается делать – следовать его указаниям.$B$BОбыщи их лагерь, вдруг что интересное найдешь, а я отвлеку орков.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35846, 'ruRU', 'Перехват приказов', 'Соберите приказы для воинов Хребта Ледяного Огня, Долины Призрачной Луны и Пиков Арака.', 'Командир, всем правит разведка. Чем больше мы знаем о планах Адского Крика, тем проще их порушить.$B$BОрки Мок\'Гола Гаррошу курьерами служат, развозят приказы отсюда и по всему Дренору.$B$BТы этих наездников убей, а приказы у них забери – все, что найдешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35847, 'ruRU', 'Событие: пророк Бездны Калург', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35861, 'ruRU', 'Гарнизонная кампания: Гнездовье Темного Прилива', 'Отправляйтесь в Гнездовье Темного прилива.', 'Нам сообщают, что боевые корабли Железной Орды пристают у маленького острова к югу от Долины Призрачной Луны.$B$BМы отправили туда разведчиков, но от них все нет вестей. Пожалуй, стоит посмотреть, что там да как.$B$BТебя ждет Дунгар Долгопив, командир, у него наготове грифон.', '', '', '', '', '', 'Отправляйтесь в Гнездовье Темного прилива к югу от Долины Призрачной Луны.', 25549);
INSERT INTO `quest_template_locale` VALUES (35865, 'ruRU', 'Награнд – босс события 018 – Миазмы Бездны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35867, 'ruRU', 'Несколько фрагментов артефакта', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35868, 'ruRU', 'Горстка фрагментов артефакта', '', '', '', '', '', '', '', 'Ты в этот раз просто $Gсам:сама; себя $Gпревзошел:превзошла;, $n.', 19865);
INSERT INTO `quest_template_locale` VALUES (35869, 'ruRU', 'КУЧА фрагментов артефакта', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35870, 'ruRU', 'Война с мертвыми василисками', 'Соберите $1oa |4кусок:куска:кусков; мяса камнелапого василиска или разлагающегося василиска.', 'Василиски – одно из любимых лакомств Ниши. Она на них охотится, и, вероятно, этим воспользовались ублюдки из Железной Орды, чтобы ее поймать.$B$BНе пойму, неужели они были готовы ко всем этим неприятностям только из-за нее? Возможно, мы получим ответ, когда будем наказывать орков за их злодеяния.$B$BНиша голодна. Пока я за ней ухаживаю, сможешь добыть для нее дичи?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35871, 'ruRU', 'Несколько фрагментов артефакта', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35872, 'ruRU', 'Горстка фрагментов артефакта', '', '', '', '', '', '', '', 'Ты в этот раз просто $Gсам:сама; себя $Gпревзошел:превзошла;, $n.', 19865);
INSERT INTO `quest_template_locale` VALUES (35873, 'ruRU', 'КУЧА фрагментов артефакта', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35874, 'ruRU', 'Устройство', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35875, 'ruRU', 'Награнд – босс события 024 – Опфис', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35876, 'ruRU', 'Гарнизонная кампания: Гнездовье Темного Прилива', 'Отправляйтесь в Гнездовье Темного прилива.', 'Нам сообщают, что боевые корабли Железной Орды пристают у маленького острова к югу от Долины Призрачной Луны.$B$BМы отправили туда разведчиков, но от них все нет вестей. Пожалуй, стоит посмотреть, что там да как.$B$BТебя ждет Брон Небесный Рог, командир, у него уже наготове риклак.', '', '', '', '', '', 'Отправляйтесь в Гнездовье Темного прилива к югу от Долины Призрачной Луны.', 25549);
INSERT INTO `quest_template_locale` VALUES (35877, 'ruRU', 'Награнд – босс события 005 – призыватель ветров Кораст', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35878, 'ruRU', 'Меры предосторожности', 'Убейте $1oa |4обитателя топи:обитателей топи:обитателей топи;.', 'Как оказалось, резонанс электромагнитного поля от батарей взбудоражил местную живность. Мне показалось, что... что один вепрь таращился на меня голодными глазами и облизывался.$B$BЯ тебя вознагражу, если ты просто уничтожишь там все живое. Неважно, какие существа тебе встретятся, просто убей их, ладно?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35879, 'ruRU', 'Меры предосторожности', 'Убейте $1oa |4обитателя топи:обитателей топи:обитателей топи;.', 'Батареи, которые я потеряла на болоте, очень плохо влияют на местных зверей. Кто знает, с какими существами тебе придется сразиться, чтобы вернуть их...$B$BЕсли ты не против, пожалуйста, \"позаботься\" о всех зверях, что встретятся на твоем пути. Не хотелось бы, чтобы за мной на раскопки притащилась какая-нибудь огромная тварь.$B$BДа и ты в накладе не останешься.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35880, 'ruRU', 'Ярость и мудрость', 'Поговорите с Костяным Заком на Хребте Скорби.', 'Обитатели западных пустошей ведут бесконечную войну с существами восточных джунглей.$B$BЕсли одна сторона одолеет другую, от победителей не будет житья всему Дренору.$B$BКлан Веселого Черепа жаждет отомстить за разрушенную деревню. Однако я направил их гнев на чудовищ, которые расположились угрожающе близко к нашей заставе.$B$BЕсли желаешь, присмотри за тем, как развивается битва. Я пока не могу доверять клану Веселого Черепа.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35881, 'ruRU', 'Руины первого бастиона', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35882, 'ruRU', 'Интерес Бруто', 'Примите клятву крови мастера клинка На\'Шры.', 'Ты мне очень $gпомог:помогла;. Теперь этот клинок принадлежит не только мне, но и тебе.$b$bЯ клянусь на крови служить тебе и использовать все свои знания о клинках и руде, чтобы помогать тебе.$b$bПримешь ли ты мою клятву?', '', 'На\'Шра, только что получившая звание мастера клинка, – грозная воительница.', 'Мастер клинка На\'Шра', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35883, 'ruRU', 'Кулаки Ваандаама', 'Примите клятву крови мастера клинка На\'Шры.', 'Ты мне очень $gпомог:помогла;. Теперь этот клинок принадлежит не только мне, но и тебе.$b$bЯ клянусь на крови служить тебе и использовать все свои знания о клинках и руде, чтобы помогать тебе.$b$bПримешь ли ты мою клятву?', '', 'На\'Шра, только что получившая звание мастера клинка, – грозная воительница.', 'Мастер клинка На\'Шра', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35884, 'ruRU', 'Финишная прямая', 'Проберитесь к причалу.', 'Уж если они не разозлились до этого, то теперь мы точно довели их до белого каления. Мы и минуты не протянем на этом танке!$b$bНам нужно объединиться с оставшимися и сваливать отсюда!', '', '', '', '', '', '', 25549);
