INSERT INTO `quest_template_locale` VALUES (35904, 'ruRU', 'Глубины Черной горы (Все) – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35905, 'ruRU', 'Сброс припасов', 'Поговорите с Баросом Алекстоном в своем гарнизоне в Долине Призрачной Луны.', 'Твои работники закончили собирать урожай и готовы подвозить припасы в гарнизон. За безопасность каравана в этот раз можно не беспокоиться – я отправлю отряд рангари, чтобы защитить его.$B$BЭкзархи всегда будут следить за тобой.$B$BКогда вернешься в гарнизон, твои припасы будут ждать тебя там. Удачи тебе в борьбе, $n!', '', '', '', '', '', 'Поговорите с Баросом Алекстоном в своем гарнизоне в Долине Призрачной Луны.', 25549);
INSERT INTO `quest_template_locale` VALUES (35906, 'ruRU', 'Событие: Сумасшедший \"Король\" Спореон', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35907, 'ruRU', 'Покушение на убийство', 'Поговорите с Хутоу Воздушным Пером, чтобы отправиться на Заставу Тени.', 'Командир, барменша Лунзул умирает. Ее отравили, срочно нужно противоядие.$b$bОдин из твоих разведчиков недавно видел тут орка из клана Изувеченной Длани. Вот у них может быть то, что нам нужно.$b$bК востоку отсюда находится небольшая обитель араккоа, возле которой расположен лагерь клана Изувеченной Длани. Думаю, стоит начать поиски там.$b$bРаспорядителю полетов уже известно, куда мы направимся, так что сможем сэкономить время.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35908, 'ruRU', 'Событие: праматерь Осколка Камня', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35909, 'ruRU', 'Событие: Инша\'тар', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35910, 'ruRU', 'Событие: Топотун Криго', '', '', '', '', '', '', '', '', 19865);
