INSERT INTO `quest_template_locale` VALUES (35913, 'ruRU', 'Каменные Недра (Героический) – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35914, 'ruRU', 'Internal: Default Invasion Reward', 'Отразите нападение горенов на гарнизон.$B$B(Чтобы начать, еще раз поговорите с сержантом Зловещей Утробой.)', 'У нас тут было землетрясение, гарнизон тряхануло пару раз. Да еще несколько разведчиков с задания не вернулось.', '', '', '', 'Зловещая Утроба, лучший легионер на Дреноре или вроде того.', 'Нападение разрушителей?', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35915, 'ruRU', 'Покушение на убийство', 'Поговорите с Фирном Быстрым Ветром, чтобы отправиться на Заставу Тени.', 'Колриг умирает, командир. Его отравили. Нужно противоядие, пока еще не поздно.$b$bОдин из твоих разведчиков недавно видел тут орка из клана Изувеченной Длани. Стоит нанести им визит.$b$bК востоку отсюда находится небольшая обитель араккоа, возле которой расположен лагерь клана Изувеченной Длани. Там и начнем поиски.$b$bРаспорядителю полетов уже известно, куда мы направимся, так что сможем сэкономить время. ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35919, 'ruRU', 'Сокровище: жертва', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35920, 'ruRU', 'Награнд – босс 019 – Тура\'ака', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35921, 'ruRU', 'Хлеб и зрелища', 'Поговорите с Дексилом Клинком Ужаса в Круге Испытаний.', 'Эй, $Gгосподин:госпожа;, этот недоумок меня не пропускает. Ты деньжат заработать не хочешь?$B$BМой босс устраивает бои в Круге Испытаний. А по тебе видно, что драться ты умеешь.$B$BСоветую принять участие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35922, 'ruRU', 'Хлеб и зрелища', 'Поговорите с Дексилом Клинком Ужаса в Круге Испытаний.', 'Эй, $Gгосподин:госпожа;, этот недоумок меня не пропускает. Ты деньжат заработать не хочешь?$B$BМой босс устраивает бои в Круге Испытаний. А по тебе видно, что драться ты умеешь.$B$BСоветую принять участие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35923, 'ruRU', 'Награнд – босс 006 – Охотник Чернозуб', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35924, 'ruRU', 'Знак убийцы', 'Осмотрите трупы изгоев, чтобы найти на них знак мастера.', 'Их яд куда сильнее, чем я думала. Надо найти орка, который его изготовил.$B$BМастера-убийцы всегда оставляют на жертвах свои метки. Это их визитные карточки, повод прославиться среди себе подобных.$B$BВот здесь явно такой и поработал.$B$BДавай разделимся и осмотрим трупы изгнанных – вдруг найдем какие-нибудь знаки, которые приведут нас к тому, кто их оставил. Встретимся у подножия холма, командир.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35925, 'ruRU', 'Операция \"Гронн\"', 'Покажите приказы по вооружению Рексару в Венце Разрушителя.', 'Раз!$b$bТебе поручено изловить еще 4 гроннов для вооружения.$b$bИз первой группы весь процесс пережил только один.$b$bОдин постоянно нападал на солдат, и его пришлось убить.$b$bВторой погиб от случайного выстрела, пока на него устанавливали орудие. Третий во сне перекатился на собственные пушки. Его ошметки мы до сих пор собираем.$b$bНе волнуйся, твои труды не пропадут.$b$bКапитан Брака', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35926, 'ruRU', 'Знак убийцы', 'Осмотрите трупы изгоев, чтобы найти на них знак мастера.', 'А яд-то не простой, совсем не простой. Надо разыскать орка, который его изготовил.$B$BМастера-убийцы на телах своих жертв всегда оставляют знак. Чтобы собратья по ремеслу уважали. И уж поверь, это работа мастера-убийцы.$B$BДавай-ка разделимся, да и глянем – может, найдем на трупах изгнанных то, что нас выведет на убийцу. Встретимся у подножия холма.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35928, 'ruRU', 'Мясобрюху нужны кости', '', '', '', '', '', '', '', '', 25549);
