INSERT INTO `quest_template_locale` VALUES (35930, 'ruRU', 'Непроглядная пучина (дополнительно) – награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35931, 'ruRU', 'Награнд – босс события 016 – разведчик клана Песни Войны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35932, 'ruRU', 'Награнд – босс события 026 – тактик клана Песни Войны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35933, 'ruRU', 'Последняя надежда Азерота', 'Заберите послание Железной Орды у одного из солдат Железной Орды на базе рядом с Темным порталом.', 'Ты $gсправлялся:справлялась; с разными напастями бессчетное количество раз, $gпобеждал:побеждала; невообразимое зло. И вот ты снова $gответил:ответила; на зов, $gприготовился:приготовилась; вновь рисковать своей жизнью – ради нашего мира.$B$BТы последняя надежда Азерота, $n.$B$BПеред нами стоят почти невыполнимые задачи, и нет никого другого, кому бы можно было доверить их разрешение, кроме тебя.$B$BУ врага может быть информация, необходимая нам для победы.$B$BИди же и добудь ее, $n! За Азерот!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35934, 'ruRU', 'За Нишу', 'Убейте $1oa |4гром\'карского рубаку:гром\'карских рубак:гром\'карских рубак;.', 'С тех пор как я в очередной раз ушел на охоту, Железная Орда подобралась еще ближе и закрепилась на позициях.$b$b<Лицо Рексара расплывается в улыбке.>$b$bСколько потенциальных целей...$b$bНо сейчас нужно лечить Нишу. Разберись с ними за меня. Заставь их страдать от боли и страха так же, как страдала она.$b$bПусть их вопли разлетятся по всему каньону!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35935, 'ruRU', 'Нападение Железной Орды!', 'Отбросьте войска Железной Орды.', 'На горизонте виднеется дым... Железная Орда уже совсем близко.', '', '', '', '', '', '', 25549);
