INSERT INTO `quest_template_locale` VALUES (35943, 'ruRU', 'Награнд – Событие босс 026 – Дурета', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35944, 'ruRU', 'Доказательство силы: зуб горена', 'Отнесите доказательство рангари Йонаа на Верхний Путь в Горгронде.', 'Этот зуб – доказательство твоего мастерства в охоте на горенов, твой друг гладиатор может это подтвердить.$b$bОтнеси этот зуб Йонаа, ты $gзаслужил:заслужила; награду.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35945, 'ruRU', 'Греблин Убыстрямс', 'Помогите Греблину Убыстрямсу спуститься.', 'Я тут сто лет уже торчу!$b$bСпокойно летел себе, вел разведку для Никсии, и вдруг... бац! Какой-то тупой огр швырнул в меня камень!$b$bПланер сломался, и вот я здесь... и как же тут неуютно!$b$bПоможешь спуститься? Я в долгу не останусь! ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35946, 'ruRU', 'Стукс Великолепный', 'Примите клятву крови мастера клинков На\'шры.', 'Ты мне очень $gпомог:помогла;. Теперь этот клинок принадлежит не только мне, но и тебе.$b$bЯ клянусь на крови служить тебе и использовать все свои знания о клинках и руде, чтобы помогать тебе.$b$bПримешь ли ты мою клятву?', '', '', 'Мастер клинков На\'Шра', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35947, 'ruRU', 'Сила яда', 'Допросите орков клана Изувеченной Длани в Ядовитых ямах, чтобы узнать, кто такой Г.Я.Н. и где его искать.', 'Г.Я.Н.? Нам бы имя и место, а не какие-то инициалы.$B$B<Велонара достает небольшой флакон.>$B$BЭто мой последний флакон терзающего яда. Мы его используем, чтобы разговорить пленных. Он... довольно мощный.$B$BСмажь им свое оружие и отправляйся в лагерь клана Изувеченной Длани, вон он – прямо перед тобой. Вступи, как обычно, в бой с врагами и потребуй ответов – об остальном позаботится яд. Довольно с меня орков и их глупости.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35948, 'ruRU', 'Доказательство силы: зуб горена', 'Отнесите доказательство Ногорвачу на Звериную заставу в Горгронде.', 'Этот зуб – доказательство твоего мастерства в охоте на горенов, твой друг гладиатор может это подтвердить.$b$bОтнеси этот зуб Ногорвачу, ты $gзаслужил:заслужила; награду.', '', '', '', '', '', '', 25549);
