INSERT INTO `quest_template_locale` VALUES (35959, 'ruRU', 'Сила яда', 'Допросите орков клана Изувеченной Длани в Ядовитых ямах, чтобы узнать, кто такой Г.Я.Н. и где его искать.', 'Г.Я.Н.? Нам бы имя и место!$B$BЯ знаю, как нам это выяснить.$B$B<Гульда достает небольшой флакон.>$B$BЭто мой последний флакон терзающего яда. Мы его используем, чтобы разговорить пленных.$B$BСмажь им свое оружие и отправляйся в лагерь клана Изувеченной Длани, вон он – прямо перед тобой. Вступи, как обычно, в бой с врагами и потребуй ответов – об остальном позаботится яд.', '', '', '', '', '', '', 25549);
