INSERT INTO `quest_template_locale` VALUES (35969, 'ruRU', 'Награнд – Сокровище 018 – набор путешественника', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35970, 'ruRU', 'Сохранение и капиталовложение', 'Найдите ожерелье с красным зубом, ожерелье с фиолетовым зубом и бюст огра.', 'Я ищу ценные артефакты. Те, которые помогут раскрыть величайшие тайны Дренора и принесут Археологическому обществу Хитрой Шестеренки кучу бабла. А ведь дамочки обожают бабло, смекаешь, о чем я?$b$bНу так вот, ты приносишь мне артефакты, мне они приносят любовь дамочек, а тебе... стоп, а что тебе было нужно?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35971, 'ruRU', 'Tracking: Mill Treasure 7', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35972, 'ruRU', 'Расправа над ограми', 'Убейте $1oa |4огра:огров:огров; и $2oa |4огрона:огронов:огронов; ', 'Эти огры мешают раскопкам Хитрой Шестеренки.$b$bГрубые, агрессивные, ужасно вонючие твари. И скажу тебе честно – я в ярости от того, что они поломали мой планер.$b$bОкажешь мне услугу, а? Сотри их с лица Дренора. Вот прям совсем.$b$bОт этого всем станет легче – ну, мне-то точно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35973, 'ruRU', 'Разборки с Ломало', 'Убейте Ломало.', 'Я тут уже почти все доделал, но не могу же я просто взять и уйти.$b$bВидал я тут огрона по имени Ломало, у него есть бесценное кольцо. Бесценное – в смысле безумно дорогое.$b$bИ уверен, Никси наконец даст мне повышение, если я верну его ей.', '', '', 'Ломало', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35974, 'ruRU', 'Атака на Гнездовье Темного Прилива', 'Одолейте войска Железной Орды и соберите разведданные о них.', 'В Железной Орде теперь служат гоблины? Уничтожь их!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (35975, 'ruRU', 'Tracking: Mill Treasure 8', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35976, 'ruRU', 'Награнд – Сокровище 020 – припасы Песни Войны', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (35977, 'ruRU', 'Атака на Гнездовье Темного Прилива', 'Одолейте войска Железной Орды и соберите разведданные о них.', 'В Железной Орде теперь служат гоблины? Уничтожь их!', '', '', '', '', '', '', 25549);
