INSERT INTO `quest_template_locale` VALUES (36047, 'ruRU', 'Теперь он попался', 'Добудьте тайную формулу Ядовитого Ножа и $2oa |4бочонок:бочонка:бочонков; с ядом.', 'Теперь Гардулу точно никуда не деться, командир.$b$bИ ты с ним быстрее справишься, чем я. Давай, убей его, возьми формулу и забери как можно больше бочонков с ядом.$b$bА я останусь охранять подступы и задержу подкрепление, если оно вдруг явится.', '', '', 'Гардул Ядовитый Нож', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36048, 'ruRU', 'Теперь он попался', 'Добудьте тайную формулу Ядовитого Ножа и $2oa |4бочонок:бочонка:бочонков; с ядом.', 'Ну что, командир, загнали мы Гардула в угол.$b$bТы посильнее меня будешь, поэтому и валить его тебе. Убей, формулу хапни и не забудь про бочонки с ядом – чем больше возьмешь, тем лучше.$b$bА я тут побуду, позырю, не сунется ли кто ему на помощь.', '', '', 'Гардул Ядовитый Нож', '', '', '', 25549);
