INSERT INTO `quest_template_locale` VALUES (36059, 'ruRU', 'Достойный преемник', 'Пробудите короля воронов.', 'Время пришло, $p.\n\nПробуди короля воронов. Призови его в этот мир, чтобы он сокрушил наших врагов!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36061, 'ruRU', '[Опротестовано]Босс Огрон', 'Найдите агента Резвошлепа.', 'Так, я сматываюсь. Что? Ой, теперь ты просишь меня о помощи? Ох, ну ладно.$b$bНедавно тут проходила гоблинша по имени Ганки. Она хотела мне помочь, но, к сожалению, ее низкорослость этому помешала. К тому же она очень спешила. Говорила, что нужно кого-то остановить. Азуки? Азука? Вот имя точно начиналось с Аз...$b$bВ общем, эта Ганки умчалась к Изломанному обрыву. И, по-моему, совсем не вовремя. Сейчас у огров и огронов что-то вроде гражданской войны. Кстати, и тебе поостеречься бы не мешало.', '', '', '', '', '', 'Вернитесь к Боудрику Грею в свой гарнизон в Долине Призрачной Луны.', 19865);
