INSERT INTO `quest_template_locale` VALUES (36079, 'ruRU', 'Теплый прием', 'Поговорите с предсказателем Дрек\'Таром в Ледниковой Бухте на Хребте Ледяного Огня.', 'Ты $gприбыл:прибыла; в Хребет Ледяного Огня. Дальше тебя направит предсказатель Дрек\'Тар.', '', '', '', '', '', '', 19865);
