INSERT INTO `quest_template_locale` VALUES (36085, 'ruRU', 'На черных крыльях', 'Убейте $2oa |4приверженца:приверженцев:приверженцев; и хранителя ветра Кореикса. Поговорите с Ка\'алу, чтобы добраться на террасу Дикого Ветра.', 'Пора атаковать приверженцев. Раасток уверен, что его новое изобретение позволит нам управлять оружием апекситов, но для этого нужно подобраться очень близко.$B$BКа\'алу и ее вороны доставят нас на террасу Дикого Ветра. Нам стоит укрепиться там, прежде чем выдвигаться на Террасу Рассвета.', '', '', 'Хранитель ветра Кореикс', '', '', '', 25549);
