INSERT INTO `quest_template_locale` VALUES (36095, 'ruRU', 'Азука Ярость Клинка', 'Вернитесь к Боудрику Грею в свой гарнизон в долине Призрачной Луны.', 'Агент Резвошлеп мертв. На его груди зияет огромная рана.$b$bПрочитав найденный рядом отчет агента, вам удается воссоздать целостную картину событий. Азука предала огров. Она убила Яркуга и забрала его силу.$b$bНеобходимо немедленно сообщить об этом Боудрику.', '', '', '', '', '', 'Вернитесь к Боудрику Грею в свой гарнизон в Долине Призрачной Луны.', 25549);
