INSERT INTO `quest_template_locale` VALUES (36117, 'ruRU', 'Гарнизонная кампания: Разбитый берег', 'Найдите Греблина Убыстрямса.', 'Э-хей! Ты в этой крепости командуешь, да? Я от Археологического общества Хитрой Шестеренки.$b$bМы тут пытались провести очень важные раскопки и двинуть в Награнд. Но у нас возникло недопонимание с ограми.$b$bОдин из лучших наших ребят пропал во время разведки местности. И он уже третий за неделю!$b$bДля спасательной операции мы плоховато подготовлены... так чего скажешь? Помочь нам не хочешь?', '', '', '', '', '', 'Поговорите с Греблином Убыстрямсом на Разбитом берегу в Награнде.', 25549);
