INSERT INTO `quest_template_locale` VALUES (36119, 'ruRU', 'Добро пожаловать на Ашран', 'Поговорите с командиром Анной Данворс в Преграде Ветров.', 'Приветствую! Добро пожаловать на Ашран! За всеми указаниями обращайся к командиру Анне Данворс в Преграде Ветров.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36123, 'ruRU', 'В диких условиях', 'Крис Кларки из Преграды Ветров хочет, чтобы вы убили бойца Орды в стороне от главной дороги и принесли обратно часть его доспехов.', 'Дорога Славы – не единственное поле брани на этих землях, $n. Нам необходимо отправиться в дикие земли, чтобы найти артефакты.$B$BПокажи мне, на что ты $gспособен:способна;. Ступай и убей бойца Орды на окраинах, а затем принеси мне часть его доспехов в качестве доказательства.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36124, 'ruRU', 'Jared\'s Test Quest', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36125, 'ruRU', 'Дорога Славы', 'Убейте 5 бойцов Орды на Дороге Славы по просьбе Криса Кларки из Преграды Ветров.', 'Орда намеревается вытеснить нас из Ашрана, $n. Их планы не должны осуществиться. Отправляйся на Дорогу Славы и сократи численность ордынцев хотя бы на 5 воинов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36127, 'ruRU', 'Дорогами Ашрана', 'Исследуйте на Ашране Дорогу Славы, Раскаленный карьер, Утес Громил, Амфитеатр Истребления и Некрополь Молота Ашрана по просьбе предсказательницы Киланды из Преграды Ветров.', 'Я предсказательница, $n, поэтому могу заглянуть в самые дальние уголки Ашрана, не покидая Преграды Ветров. Но ты обязательно $gдолжен:должна; увидеть все своими глазами. ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36128, 'ruRU', 'Земли саблеронов – босс события саблеронов', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36129, 'ruRU', 'Событие: Наз Данберлин', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36130, 'ruRU', 'Всегда готов!', 'Поговорите с Мизирин Пивохлеб, предсказательницей Киландой и Крисом Кларки.', 'Слушай сюда, $n! У меня времени нет, поговори с этими ребятами – они введут тебя в курс дела.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36131, 'ruRU', 'Доказательство силы', 'Докажите Мокугу Пиводуру свое умение, поймав 5 зангарских угрей на его наживку.', 'Ну то, что ты $gопытный воин:опытная воительница;, это понятно. А теперь посмотрим, какой из тебя рыбак. Я тут сообразил наживку из жал ледоспинных жальщиков, которые ты $gпринес:принесла;. Возьми ее да налови зангарских угрей в прибрежных водах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36132, 'ruRU', 'Гарнизонная рыбалка', 'Вернитесь к Мак\'джину с заметками рыбаков клана Северного Волка.', 'Что ж, ты $gпоказал:показала;, на что $gспособен:способна;. На, возьми эти заметки рыбаков клана Северного Волка, возвращайся в свой гарнизон и изучай на здоровье. Если осилишь, потом хоть кракена выловить сможешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36133, 'ruRU', 'Калейдоскоп фрагментов', 'Убивайте существ на окраинах Ашрана в стороне от главной дороги и принесите 5 фрагментов артефакта Экиламу по просьбе Мизирин Пивохлеб из Преграды Ветров.', 'Ну и дела! Похоже, фрагменты артефакта так и сыплются из каждого существа, обитающего на окраинах Ашрана. Добудь не менее пяти фрагментов и принеси их магу Экиламу к костру в Преграде Ветров.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36134, 'ruRU', 'Гарнизонная кампания: пробуждение', 'Поговорите с Тизали Вороной в Покое Горгорека, что в Горгронде.', 'Мы выследили, куда скрылась Ярость Клинка с украденным артефактом – она в соляных полях на западе Горгронда.$B$BТизали Ворона встретит тебя там с отрядом разведчиков.$B$BВесь гарнизон приведен в состояние повышенной боеготовности. Мы должны быть готовы перехватить врага, если потребуется.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36136, 'ruRU', 'Гарнизонная кампания: пробуждение', 'Поговорите с Чолуной в Покое Горгорека, что в Горгронде.', 'Мы выследили, куда скрылась Ярость Клинка с украденным артефактом – она на севере Горгронда.$B$BТам сейчас Чолуна со своими разведчиками.$B$BГарнизон тоже в полной боевой готовности. Ты иди, поговори с ней и перехвати врага, если надо будет.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36137, 'ruRU', 'Рубка леса для чайников', 'Найдите образец древесины небольшого дерева и принесите старшему лесозаготовщику Октрону.', 'Командир, нам потребуется много древесины, чтобы превратить этот гарнизон в надежную крепость. А значит, нам придется немного поработать.$b$bСамо собой, я не могу просить тебя заниматься физическим трудом, но все же необходимо, чтобы ты $gнашел:нашла; древесину для нашей лесопилки. Когда ты отметишь дерево, какой-нибудь бестолковый крепкий батрак срубит его и передаст тебе древесину.$b$bХребет Ледяного Огня не самое лучшее место для ее добычи, но я видел неподалеку подходящее небольшое дерево.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36138, 'ruRU', 'Золотое дерево', 'Соберите 10 связок древесины со всего Дренора и обеспечьте работой лесопилку своего гарнизона.', 'Теперь ты знаешь, как заставить батраков собирать древесину, так что перейдем к заказу для твоей лесопилки.$b$bНо сначала нам понадобится немного дерева для обработки!$b$bПо всему Дренору растут деревья, которые только и ждут, чтобы их срубили. Найди подходящую древесину для нашей лесопилки. Возвращайся, когда достаточно соберешь, и мы приступим к работе над заказом.$b$bКак обычно, тяжелую работу оставь батракам. Только защищай их, все-таки на Дреноре опасно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36141, 'ruRU', 'Ледоспинные жальщики', 'Докажите Мокугу Пиводуру свою силу, добыв 4 жала ледоспинного жальщика.', 'Я тебе помогу, только сначала докажи, что ты не только умелый рыбак, но и $gбесстрашный воин:бесстрашная воительница;.$b$bВ ущелье к северу отсюда полно ледоспинных жальщиков. Перебей жальщиков и принеси мне их жала. В этих водах они сойдут за наживку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36142, 'ruRU', 'Острее топоры – толще деревья', 'Найдите образцы древесины разных пород деревьев и принесите старшему лесозаготовщику Октрону.', 'Прекрасные новости, командир $n. Твой верный слуга (то есть я) заручился поддержкой дроворубов. Если ты не знаешь, кто такие дроворубы, давай я объясню: представь кровожадного, беспощадного маньяка, которому нравится только убивать. Вот дроворубы именно такие. Только они убивают не людей, а деревья!$b$bДля нас это хорошо тем, что теперь мы сможем заготавливать деревья среднего размера. Надо только сначала испытать наших дроворубов с полевых условиях, так сказать.$b$bТут рядом есть подходящее дерево. Удачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36157, 'ruRU', 'Пики предателя', 'Добудьте кольцо из чистого солия у высшего мудреца Вирикс в Небесном Пути.', 'Я о многом хочу попросить тебя, $n, но сначала мне надо убедиться, что ты полностью $gраскрыл:раскрыла; свой потенциал. Я могу помочь тебе.$b$bЯ хочу создать между нами связь, артефакт, который увеличит твою силу и позволит мне отслеживать твои успехи. Тебе нравятся амулеты? Нет? Тогда, может, кольцо? Отлично.$b$bМои информаторы из араккоа-изгоев рассказывали о кольце из чистейшего солия. Сейчас оно находится в лапах высшего мудреца Вирикс на вершинах Небесного Пути. Принеси мне это кольцо, $n. Мы найдем ему куда лучшее применение.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36158, 'ruRU', 'Волшебная сила Дренора', 'Соберите 4986 апекситовых кристаллов для верховного мага Кадгара. Кристаллы можно найти у созданий, обитающих в самых опасных уголках мира.', 'Раз мы с тобой теперь будем вместе работать, я бы хотел усовершенствовать твое кольцо. В этом нам поможет древняя магия: апекситовые кристаллы, оставшиеся после ранней цивилизации араккоа! Их можно найти у самых опасных созданий по всему миру.$b$bСобери 4986 кристаллов.$b$bНе надо на меня так смотреть. Я маг. Я все посчитал. Нужно ровно 4986 кристаллов. 4985 будет недостаточно. 4987, разумеется, чересчур.$b$bЧетыре тысячи девятьсот восемьдесят шесть. Вперед!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36159, 'ruRU', 'Награнд – Босс события 004 – Камнезуб ', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36160, 'ruRU', 'Гарнизонная кампания: Роз без шипов не бывает', 'Принесите Баросу розу для лейтенанта Торн.', 'Моя любовь слишком сильна. Я больше не могу скрывать свои чувства.$b$bЯ должен признаться Торн. Я должен сказать ей, что люблю ее.$b$bОна говорила, что любит розы. А я столько сидел за своей работой, что даже не знаю, где на Дреноре можно найти розу…', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36161, 'ruRU', 'Нет дыма без огня...', 'Убейте Раг\'слу Стукножа, Акату Огненную Вспышку и Дрека Призывателя Огня.', 'Убийцы из клана Пылающего Клинка проникли в гарнизон. Мы ни в коем случае не можем позволить им добраться до сердца Горгорека, командир.', '', '', '', '', '', 'Вернитесь к лейтенанту Торн в свой гарнизон.', 19865);
INSERT INTO `quest_template_locale` VALUES (36162, 'ruRU', 'Украденное сердце', 'Убейте Азуку Ярость Клинка.', 'Не дай Азуке завладеть сердцем, командир. Она не должна победить.', '', '', '', '', '', 'Поговорите с лейтенантом Торн в своем гарнизоне.', 19865);
INSERT INTO `quest_template_locale` VALUES (36163, 'ruRU', 'Гарнизонная кампания: Зов экзарха', 'Поговорите с Ирель в Элодоре в Долине Призрачной Луны.', 'Ага, ты-то мне и $gнужен:нужна;, дорогуша.$b$bИрель уже заходила в гарнизон, искала тебя. Такая милая девчушка! Все про мою семью расспрашивала, когда мне было грустно. Просто золотце. Так, о чем это я?$b$bАга! Она просила передать, чтобы ты $gвстретил:встретила; ее в Элодоре к востоку.$b$bСовет дренеев пригласил ее пройти испытания экзарха, что бы это ни значило.$b$bВ общем, давай, торопись!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36164, 'ruRU', 'Испытание храбрости', 'Убейте Вечногорящего.', 'Экзарх должен быть столпом силы, и нет силы большей, нежели мужество встретить опасность.$B$BДалеко к северо-западу, среди заснеженных утесов Хребта Ледяного Огня, живет изначальный Гнев по имени Вечногорящий.$B$BЛишь столкнувшись с одним из этих созданий лицом к лицу, познаешь ты пределы своей смелости.', '', '', 'Вечногорящий', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36165, 'ruRU', 'Времени в обрез', 'Отнесите бальзам вершин Колригу Стоктрону в Южный порт.', 'Нам повезло, командир. Противоядие совсем не трудно изготовить.$b$bВот, уже удалось сделать немного из того, что было при себе. Отнеси его Колригу, пока не поздно. Так он дождется, пока я сделаю еще.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36166, 'ruRU', 'Времени в обрез', 'Отнесите бальзам вершин Лунзул в Павший Топор.', 'Нам повезло, командир. Противоядие совсем не трудно изготовить.$b$bВот, уже удалось сделать немного из того, что было при себе. Отнеси его Лунзул, пока не поздно. Так она дождется, пока я сделаю еще.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36167, 'ruRU', 'Испытание сердца', 'Поговорите с Ирель в Лазурной лагуне, после чего найдите источник ядовитого тумана.', 'Испытание сердца – это проверка твоей готовности идти вперед и преодолевать любые трудности.$b$bДалеко на запад, в Лазурной лагуне расположен аванпост рангари.$b$bОттуда поступила просьба о помощи. Всех местных жителей поразила какая-то инфекция. Ситуация критическая.$b$bНайди рангари и помоги им выявить причину этого жуткого недуга.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36168, 'ruRU', 'Испытание веры', 'Поговорите со стражницей душ Туулани у входа в Аукиндон, а затем пройдите испытание веры.', 'Испытание экзарха включает в себя паломничество к священному месту – склепу наших павших героев.$B$BПрошу тебя, возьми прах воздаятеля Мараада и отнеси в священные покои Аукиндона.$B$BИменно там духи наших предков подвергнут Ирель самому трудному испытанию и узнают, сумеет ли она справиться со своей самой большой слабостью.$B$BУдачи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36169, 'ruRU', 'Испытание защитников', 'Пройдите испытание Совета экзархов.', 'С первыми тремя испытаниями ты $gсправился:справилась; превосходно.$B$BПоследнее же испытание ждет тебя на Совете экзархов.$B$BСкажи мне, когда будешь $gготов:готова;.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36170, 'ruRU', 'Сокровище: берцовая кость невероятности', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36171, 'ruRU', 'Нападение ботани!', 'Отбейте нападение ботани на ваш гарнизон.$b$b(Чтобы начать, еще раз поговорите с сержантом Краулером.)', 'Сегодня растения какие-то странные. Трава не стелется по ветру, а словно пытается ухватить меня за сапоги. Уже два раза за утро на меня с деревьев падали ветки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36174, 'ruRU', 'Nagrand - Treasure 081 - Bounty of the Elements', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36176, 'ruRU', 'Состязание охотников', 'Отнесите грязную записку Фанаре в деревню Эмбаари, чтобы принять участие в соревновании.', '<Записку едва удается разобрать, но, похоже, это приглашение на местное состязание охотников неподалеку от деревни Эмбаари.>$b$b\"Приглашаем всех желающих испытать свои навыки на товарищеский охотничий турнир\".', '', '', '', '', '', 'Отнесите записку Фанаре в деревню Эмбаари.', 25549);
INSERT INTO `quest_template_locale` VALUES (36177, 'ruRU', 'Товарищеский турнир', 'Соберите $1oa |4шкуру:шкуры:шкур; животных из долины Призрачной Луны и $2oa |4коготь:когтя:когтей; среброкрылых калири и вернитесь к Фанаре раньше других участников.', 'Хочешь принять участие в турнире, $n? Удачи тебе.$b$bНаполни сумку шкурами и когтями местной живности и принеси ее мне раньше других участников!$b$bПобедитель получит возможность стать учеником ремесленника Гараала.$b$bУдачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36178, 'ruRU', 'Событие: Мандракор Ночной Охотник', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36179, 'ruRU', 'Уничтожение вредителей', 'Убейте 10 споровиков-скитальцев или грибных исполинов на Туманной отмели.', 'Эти твари на отмелях по-прежнему ломают наши очистители быстрее, чем мы их чиним.$b$bЯ должен их истреблять, но моему бластеру пришел конец. Даже свечу им сейчас не зажечь!$b$bМожешь сделать одолжение и убить несколько вредителей, пока я занимаюсь ремонтом?$b$bТолько сообщи Газвитцу, что ты $gподменил:подменила; меня, тогда мне возместят стоимость починки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36182, 'ruRU', 'Древоцид', 'Получите образец древесины с большого дерева и принесите его старшему лесозаготовщику Октрону.', 'Командир, гоблины приготовили для тебя подарок. Они назвали его \"Древоубийца 9000\"$b$bЧто он делает? Судя по всему, убивает деревья, но самое главное, он позволит нам заготавливать большие деревья. Знаешь, сколько древесины содержится в большом дереве? Вот и я не знаю, но наверняка целая куча!$b$bТут как недалеко есть большое неубитое дерево. Не желаешь ли испытать агрегат? Принеси мне все материалы, которые удастся собрать, и я найду им хорошее применение.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36183, 'ruRU', 'Адмирал Тейлор', 'Найдите адмирала Тейлора на Ферме адмирала Тейлора.', 'Адмирал Тейлор выяснил, кто за всем этим стоит. Он велел нам спасти всех, кого сможем... хотел разобраться в произошедшем самостоятельно.$B$BБольше мы его не видели, ведь мы не можем ослушаться приказа.$B$BПожалуйста... пожалуйста, найди его. Он отправился к ферме.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36184, 'ruRU', 'Золотая жила', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36185, 'ruRU', 'Честная сделка', 'Гараал ждет вас.', 'Ну ладно. Держи.$b$bСкорее отнеси все Гараалу. Он любит мелкие детали и тонкую работу. Так что ты ему точно понравишься.', '', '', '', '', '', 'Отнесите товары Гараалу в деревню Эмбаари.', 25549);
INSERT INTO `quest_template_locale` VALUES (36186, 'ruRU', 'Событие: Грелдрок Коварный', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36189, 'ruRU', 'Рубка леса для чайников', 'Добудьте образец древесины из небольшого дерева и принесите его Джастину Тимберлорду.', 'Командир, нам потребуется много древесины, чтобы превратить этот гарнизон в надежную крепость. А значит, придется немного поработать.$b$bСамо собой, я не могу просить тебя заниматься физическим трудом, но все же необходимо, чтобы ты $Gнашел:нашла; древесину для нашей лесопилки. Когда ты отметишь дерево, какой-нибудь дровосек срубит его и передаст тебе древесину.$b$bДавай испытаем наших дровосеков. Тут неподалеку есть дерево.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36192, 'ruRU', 'Деревянный доход', 'Соберите 10 связок древесины со всего Дренора и обеспечьте работой лесопилку своего гарнизона.', 'Теперь ты знаешь, как заставить дровосеков собирать древесину, так что перейдем к созданию заказа для твоей лесопилки.$b$bНо сначала нам понадобится немного дерева для обработки!$b$bПо всему Дренору растут деревья, которые только и ждут, чтобы их срубили. Найди подходящую древесину для нашей лесопилки. Возвращайся, когда достаточно соберешь, и мы приступим к работе над заказом.$b$bКак обычно, тяжелую работу оставь дровосекам. Только защищай их, все-таки на Дреноре опасно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36193, 'ruRU', 'Доброе дело.', 'Используйте целебные мухоморы, чтобы вылечить отравленных рангари.', 'Я знаю, что вы с воздаятельницей Ирель прибыли по важному делу, но я должен попросить вас об услуге.$b$bОтряд рангари отправился на патрулирование незадолго до появления ядовитого тумана.$b$bЕсли их застали врасплох на болоте, им точно нужна помощь.$b$bНайди целебные мухоморы среди камышей и используй их, чтобы помочь всем отравленным рангари, которых встретишь.$b$bЕсли $gсам:сама; попадешь впросак, съешь один гриб, чтобы нейтрализовать яд.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36194, 'ruRU', 'Острее топоры – толще деревья', 'Добудьте образец древесины из дерева и принесите его Джастину Тимберлорду.', 'Прекрасные новости, командир $n. Ваш верный слуга заручился поддержкой боевых дровосеков. Если не знаешь, кто это, давай я объясню: это те же дровосеки, только они специализируются на убийствах. В основном это оставшиеся без работы наемники и убийцы.$b$bДля нас это хорошо тем, что теперь мы сможем заготавливать деревья среднего размера. Надо только сначала испытать наших новых союзников в полевых условиях, так сказать.$b$bТут рядом есть подходящее дерево. Удачи!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36195, 'ruRU', 'Древоцид', 'Добудьте образец древесины из большого дерева и принесите его Джастину Тимберлорду.', 'Командир, инженеры приготовили для тебя подарок. Они назвали его \"Изничтожитель древесины XXI 3-го поколения\".$b$bЧто он делает? Судя по всему, изничтожает деревья, но самое главное, он позволит нам заготавливать большие куски древесины. Знаешь, сколько ее в большом дереве? Вот и я не знаю, но наверняка целая куча!$b$bТут как недалеко есть большое неизничтоженное дерево. Не желаешь ли испытать агрегат? Принеси мне все материалы, которые удастся собрать, и я найду им хорошее применение.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36196, 'ruRU', 'Добро пожаловать на Ашран', 'Поговорите с генералом Ашет Волкодавом в Копье Войны.', 'Приветствую! Добро пожаловать на Ашран.$b$bОбратись к генералу Ашет Волкодаву в Копье Войны за указаниями.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36197, 'ruRU', 'Прибытие к месту службы', 'Поговорите с Саймре Сияющий Клинок, Марой Вольной Охотницей и Зургом.', 'Внимание, $n! Времени в обрез, поговори с теми ребятами, они все объяснят.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36198, 'ruRU', 'Поиск фрагментов артефакта', 'Саймре Сияющий Клинок в Копье Войны хочет, чтобы вы убили существ на окраинах Ашрана в стороне от главной дороги и принесли 5 фрагментов артефакта Фьюре.', 'Похоже, фрагменты артефакта выпадают из всех существ, которые водятся на окраинах Ашрана.$b$bДобудь не менее пяти фрагментов и принеси их магу Фьюре на заставу в Копье Войны.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36199, 'ruRU', 'Клешни луноспинного краба', 'Докажите Мадари свою силу, собрав 4 клешни луноспинного краба.', 'Я тебе помогу, только сначала докажи, что ты не только умелый рыбак, но и $gбесстрашный воин:бесстрашная воительница;.$b$bНа пляже к юго-востоку отсюда полно луноспинных ползунов. Перебей ползунов и принеси мне их клешни. В этих водах они сойдут за наживку.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36201, 'ruRU', 'Доказательство силы', 'Докажите Мадари свое умение, поймав 5 темных осетров при помощи предоставленной наживки.', 'Воинское умение ты $gподтвердил:подтвердила;, а теперь посмотрим, какой из тебя рыбак. Я тут сообразил наживку из клешней луноспинных крабов, которые ты $gпринес:принесла;. Возьми ее да налови темных осетров в прибрежных водах.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36202, 'ruRU', 'Рыбалка в нашем гарнизоне', 'Вернитесь к Рону Эштону с дневником рыбака Вечерней Зари.', 'Ты $gпоказал:показала;, на что $gспособен:способна;. Возвращайся с этим дневником рыбака Вечерней Зари в свой гарнизон и изучи его. После этого сможешь выловить хоть самого кракена.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36203, 'ruRU', 'Сокровище: яйцо горена', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36204, 'ruRU', 'Событие: Жракен Ненасытный', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36205, 'ruRU', 'Сломанный молот', 'Найдите предыдущего владельца молота на аванпосте Каменного Клыка.', 'Очевидно, что этот кузнечный молот знавал лучшие времена.$b$bВесь грязный и в трещинах, он похож на жалкое подобие самого себя.$b$bОдно можно сказать наверняка: его предыдущий владелец не принадлежал к ограм или Железной Орде.$b$bВозможно, кто-либо на аванпосте Каменного Клыка сможет что-то про него рассказать.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36206, 'ruRU', 'История о драконе', 'Идите по следу вверх по горе, пока не найдете Кайроздорму на Затерянной во времени поляне.', 'Похоже, Хроми напала на след. Нам кажется, что Гаррош проходил здесь, когда впервые прибыл на Дренор. Но что насчет Кайроза? Он должен быть рядом.$b$bХроми подсветит улики. Обращай внимание на все, что покажется тебе ненормальным. Иди по следу на восток и вверх по горе, пока не найдешь Кайроздорму… или его тело. Удачи!', '', '', '', '', '', 'Поговорите с верховным магом Кадгаром на Затерянной во времени поляне в Награнде.', 19865);
INSERT INTO `quest_template_locale` VALUES (36207, 'ruRU', 'Варук Хладобой', 'Отнеси молот Варука к его могиле.', 'Многие говорят, что мой отец был легендарным кузнецом. Его называли Варук Хладобой, слагали легенды о его могущественном оружии, выкованном всего лишь из стали и льда. Я называю его Варук Враль.$b$bОн обещал, что скоро вернется. Говорил: \"Я должен поддержать наши войска\".$b$bЗачем он ушел? Почему они его не защитили?$b$bОт поломанных инструментов мне проку не больше, чем от нарушенных обещаний. Его могила к востоку отсюда; можешь оставить это вместе с остальным его барахлом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36208, 'ruRU', 'Осколок кристалла', 'Добудьте $1oa |4кристалл:кристалла:кристаллов; горена с проглотов-длиннозубов.', 'Ты очень вовремя.$b$bУ орков из клана Веселого Черепа много странных обычаев, но один из них в нашей ситуации как раз может пригодиться.$b$bТы можешь собрать необходимые компоненты, пока я займусь прочими приготовлениями?$b$bВ первую очередь нам понадобятся кристаллы с трупов умерших горенов. Их тела ты найдешь в каньоне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36209, 'ruRU', 'Что там под землей?', 'Замаскируйтесь под горена для исследования местности в Горгронде.', 'Все готово.$B$BС этими чарами ты сможешь не только свободно ходить среди горенов, но и двигаться, как они.$B$BТеперь тебе будет легче проходить через каньон. Ты спокойно доберешься туда, куда раньше ни за что бы не $Gсмог:смогла;.$B$BВозможно, путешествие в эти тоннели поможет тебе найти новую информацию, которую можно будет использовать против Железной Орды.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36210, 'ruRU', 'Прочный панцирь', 'Добудьте $1oa |4панцирь горена:панциря горенов:панцирей горенов; с проглотов Костяного двора.', 'Мне уже удалось столько всего узнать благодаря наблюдениям за кланом Веселого Черепа.$b$bСчиталось, что по горенским туннелям нельзя пройти из-за кислоты, которую они оставляют за собой, но эти находчивые орки нашли обходной путь.$b$bНам понадобятся панцири горенов из каньона.$b$bЕсли увидишь их тоннельный кратер, который вот-вот рванет, подойди к нему, и горены сразу хлынут оттуда. Так ты сможешь убить за раз много горенов и быстрее собрать нужные панцири.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36211, 'ruRU', '6.0 Tanaan - Boots Bootstrap', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36212, 'ruRU', '6.0 Tanaan - Wrist Bootstrap', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36213, 'ruRU', '6.0 Tanaan - Ring Bootstrap', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36214, 'ruRU', '6.0 Tanaan - Hands Bootstrap', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36219, 'ruRU', 'Гарнизонная кампания: Кольцо Крови', 'Поговорите с Гаргтоком в Хранилище Гаргтока в Награнде.', 'Приветик!$B$BЯ тебя тут искал, да ты куда-то $gподевался:подевалась;. У меня тут дельце отличненькое наклюнулось в Кольце Крови в Награнде. Там толпы огров только и ждут новой крупной драки. Можно сорвать большой куш. Ну что, ты в деле?$B$BДа кого я обманываю, кто ж откажется от славы, деньжат и славной заварушки? Встретимся у меня в тайнике, чтобы перекинуться парой слов перед твоим громким дебютом.$B$B<Прилагается карта со значком доллара, нацарапанным на заброшенной орочьей башне.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36220, 'ruRU', 'Сила есть?', 'Убейте Луг\'дола и отдайте его голову Крогголу Стене у Горианской арены испытаний.', 'Могор проводит в Кольце Крови особое состязание за титул Чемпиона Крови, и ты, я думаю, самый подходящий кандидат!$B$BСлушай сюда. Эти огры уважают только одно – сорвиголов... ность. У них там стоит у дверей такой амбал, который пропускает на арену испытаний только самых суровых гладиаторов.$B$BЕсли ты в деле, то убей седого гладиатора Луг\'дола в башне прямо по дороге отсюда и отдай его голову Крогголу Стене. Это покажет им, из какого теста ты $gслеплен:слеплена;.', '', '', 'Луг\'дол', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36221, 'ruRU', 'Плата за вход', 'Добудьте $1oa |4камень:камня: камней; Крови и принесите их троллю-прислужнику Водину.', 'Хочешь в Кольцо Крови? Ха! Очень смешно. Не каждому дано там сражаться. Надо платить сбор: пятьдесят кровавых меток.$B$BКак их достать? Ох, малявка, ты меня просто убиваешь!$B$B<Кроггол отдает вам маленький камень, покрытый запекшейся кровью.>$B$BЭто – твоя первая метка. Убиваешь кого на арене испытаний – получаешь еще. Соберешь – неси Водину, троллю-прислужнику при Могоре.$B$BА с самим Могором даже заговаривать не вздумай. Могор тут босс, ему не до тебя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36222, 'ruRU', 'Чемпион Крови', 'Поговорите с Гаргтоком, чтобы принять участие в битве за титул Чемпиона Крови.', 'Ты $gпринес:принесла; камни Крови – доказательство того, что ты чего-то стоишь. Хм... Да, может быть, ты и станешь $gтем чемпионом, которого:той чемпионкой, которую; искал Могор.$B$BЕще один боец принес мне камни, кроме тебя. Вы двое и сразитесь за честь стать Чемпионом Крови.$B$BПоговори с Гаргтоком, и посмотрим, кто ты... настоящий боец или еще одно кровавое пятно на арене.', '', '', 'Кацуо', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36223, 'ruRU', 'Мы своих... бросаем', 'Найдите капрала Тукмара и заберите его бумаги.', 'В лапы огронам попало нечто, представляющее ценность для Железной Орды. Думаю, они этого даже не представляют. Скорее всего, им просто скучно, и они хотят кого-нибудь помучить.$b$bМожно, конечно, бросить их пленников на произвол судьбы, но, наверное, тут стоит копнуть поглубже. Если удача будет на нашей стороне, мы помешаем Железной Орде использовать в качестве оружия самых грозных обитателей Горгронда.$b$bПостарайся отыскать капрала Тукмара и его бумаги.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36226, 'ruRU', 'Исследование Ашрана', 'Предсказательница Мара Вольная Охотница в Копье Войны хочет, чтобы вы исследовали Дорогу Славы, Раскаленный карьер, Утес Громил, Амфитеатр Истребления и Некрополь Молота Ашрана на Ашране.', 'Будучи предсказательницей, я могу заглянуть в дальние уголки Ашрана, находясь здесь, в Копье Войны. Но ты $gдолжен:должна; пойти и увидеть все своими глазами, $n.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36227, 'ruRU', 'Дорога Славы', 'Зург в Копье Войны хочет, чтобы вы убили 5 игроков Альянса на дороге Славы.', 'АЛЬЯНС! <В гневе топает ногой> НУЖНО ВЫШВЫРНУТЬ ИХ ИЗ АШРАНА НЕМЕДЛЕННО! ОТПРАВЛЯЙСЯ НА ДОРОГУ СЛАВЫ И УБЕЙ ВСЕХ, КТО ПОПАДЕТСЯ ТЕБЕ НА ГЛАЗА!$b$bЖИВО!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36228, 'ruRU', 'В диких условиях', 'Зург в Копье Войны хочет, чтобы вы убили представителя Альянса в стороне от главной дороги и принесли кусок его доспеха в качестве подтверждения убийства.', 'ЧТО МОЖЕТ БЫТЬ ЛУЧШЕ, ЧЕМ УБИВАТЬ ПРИХВОСТНЕЙ АЛЬЯНСА НА ДОРОГЕ СЛАВЫ?$B$BУБИВАТЬ ИХ ВЕЗДЕ, ГДЕ ВСТРЕТИШЬ. <Хохочет>$B$BОТПРАВЛЯЙСЯ НА ОКРАИНЫ АШРАНА И УБЕЙ ЛЮБОГО АЛЬЯНСОВЦА НА СВОЕМ ПУТИ. И ПРИНЕСИ МНЕ В КАЧЕСТВЕ ДОКАЗАТЕЛЬСТВА ПОБЕДЫ КУСОК ЕГО ЖАЛКИХ ДОСПЕХОВ. ЧЕМ БОЛЬШЕ НА НЕМ БУДЕТ КРОВИ – ТЕМ ЛУЧШЕ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36229, 'ruRU', 'Награнд – Босс в событии – Мистер Пинчи старший', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36230, 'ruRU', 'Беспокойный дух', 'Убейте Кургтука Безжалостного и с помощью молота Варука превратите снаряжение орков из клана Громоборцев в металлолом.', 'Когда-то этот молот ковал чудеснейшее оружие для моих братьев и сестер из клана Северного Волка.$B$BНо когда Громоборцы взяли меня в плен, я отказался брать его в руки. Как мог я ковать оружие, которым будут убивать мой народ?$B$BМне грустно видеть, во что превратился мой молот от дурного обращения.$B$BМне хотелось когда-нибудь передать его Кугре, но сейчас она так зла, что даже не навещает мою могилу.$B$BПрошу тебя, $p, помоги мне починить молот и отомстить тем, кто в этом виноват!$B$BРади Кугры...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36236, 'ruRU', 'Таинственная портновская книга', 'Поговорите с Эруном в своем гарнизоне.', 'Разные разделы книги описывают способы кроя, которые кажутся очень странными по сравнению с традиционными.$b$bНи на одной из страниц не указано имя автора. Может быть, кому-нибудь в вашем гарнизоне больше известно об этой книге.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36238, 'ruRU', 'Как починить разбитое сердце', 'Встретьтесь с Варуком на Аванпосте Каменного Клыка.', 'Спасибо, что $Gотомстил:отомстила; за мою смерть, $p. Однако я хочу еще кое о чем тебя попросить.$B$BЕсли выполнишь мою просьбу, я навсегда буду у тебя в долгу.$B$BВозьми эти инструменты и отправляйся в кузню на аванпост Каменного Клыка. Встретимся там.$B$BЯ вселил в свои инструменты частичку своей сущности, но нам все равно потребуется посторонняя помощь, чтобы перековать молот.$B$BПора нам помириться с Кугрой и обоим наконец обрести мир в своих душах...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36239, 'ruRU', 'Таинственная сумка', 'Найдите владельца сумки.', 'Пустая сумка, окруженная древней магической аурой.$B$BОна выглядит довольно потрепанной, к подкладке прилипли остатки трав и грибов. Может, стоит обойти Тенетопь – вдруг вам удастся выяснить, что это такое.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36240, 'ruRU', 'Медленно, но верно', 'Соберите травы и вернитесь с ними к Ша\'ле.', 'Замечательно!$B$BКогда соберешь достаточно трав, возвращайся ко мне, и я сделаю из них чернила для мастера Ардула.$B$BДумаю нужные ты найдешь на спороскатах и великанах.$B$BИ помни: осторожность – прежде всего!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36241, 'ruRU', 'Сила сохранения', 'Доставьте чернила мастеру Ардулу.', 'Эти чернила очень важны для нашего народа. Они обладают способностью сохранять древние тексты.$B$BМастер Ардул объяснит тебе все подробнее. Он ждет внутри.', '', '', '', '', '', 'Вернитесь к мастеру Ардулу в Анклав рангари.', 25549);
INSERT INTO `quest_template_locale` VALUES (36242, 'ruRU', 'Нет дыма без огня...', 'Убейте Раг\'слу Стукножа, Акату Огненную Вспышку и Дрека Призывателя Огня.', 'На ваш гарнизон напал клан Пылающего Клинка!$b$bУбейте главарей клана Пылающего Клинка, руководящих атакой, и вернитесь к воеводе Зогу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36243, 'ruRU', 'Spires - Treasure 001 - Outcast\'s Basket', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36244, 'ruRU', 'Spires - Treasure 002 - Misplaced Scrolls', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36245, 'ruRU', 'Spires - Treasure 004 - Relics of the Outcasts', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36246, 'ruRU', 'Spires - Treasure 005 - Fractured Sunstone', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36247, 'ruRU', 'Spires - Treasure 007 - Lost Herb Satchel', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36248, 'ruRU', 'Украденное сердце', 'Сразите Азуку Ярость Клинка.', 'Целью этого нападения явно было захватить сердце Горгорека.$b$bНужно усилить охрану, пока еще не поздно.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36249, 'ruRU', 'Активный выбор: лесопилка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36250, 'ruRU', 'Активный выбор: лесопилка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36251, 'ruRU', 'Активный выбор: бойцовская арена', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36252, 'ruRU', 'Активный выбор: бойцовская арена', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36254, 'ruRU', 'Spires - Vignette Boss 002 - Tesska the Broken', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36255, 'ruRU', 'Зачарованный наруч клана Верховного Молота', 'Принесите наруч в свой гарнизон Ю\'рине Мистик.', 'От этих древних наручей клана Верховного Молота исходят мощные чары.\n\nМожет быть, Ю\'рина Мистик, гарнизонная поставщица товаров для наложения чар, расскажет тебе больше об этом наруче.', '', '', '', '', '', 'Поговорите с Ю\'риной Мистиком в вашем гарнизоне.', 25549);
INSERT INTO `quest_template_locale` VALUES (36256, 'ruRU', 'Араккоа-чародей', 'Найдите Делата на северном краю Растрескавшихся Равнин.', 'Араккоа говорил, что собирается исследовать аномалию Растрескавшихся равнин, возможно, связанную с другим предметом брони.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36257, 'ruRU', 'Ученик-неудачник', 'Найдите и освободите Торага из ледяной тюрьмы.', 'Ору\'кай был первым огром-магом, овладевшим искусством наложения чар. После его смерти артефакты рассеялись по всему Дренору. Я выяснил, что его скипетр – на поле, что раскинулось перед нами. \n\nКак видишь, наложенные на скипетр чары мешают взять его. Тораг Каменное Неистовство, желавший стать учеником, взял одно из колец Ору\'кая, чтобы развеять чары, но потерпел неудачу и застрял в ледяной ловушке. \n\nОсвободи Торага, возьми кольцо и закончи то, что он начал, и тогда я тебя вознагражу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36260, 'ruRU', 'Скипетр Ору\'кая', 'Достаньте скипетр Ору\'кая и принесите его Делату.', 'Знал бы я, что быть зачаровывателем так опасно, остался бы в Вор\'голе. \n\nВот кольцо, держи. Птицечеловек велел мне снять этим кольцом чары на скипетре.\n\nПринеси ему скипетр и, может быть, он научит тебя тому, чему обещал научить меня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36261, 'ruRU', 'Гарнизонная кампания: Пропавший рубака', 'Найдите Дул\'зака.', 'Пока сердце Горгорека хранится в нашем гарнизоне, нам нельзя терять бдительность. Клан Пылающего Клинка известен своими молниеносными и внезапными атаками.$b$bЯ послал нескольких рубак патрулировать окрестности. Один из новичков, Дул\'зак, уже должен был вернуться с докладом. ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36262, 'ruRU', 'Искусная ткачиха Амика', 'Поговорите с Амикой в Элодоре.', 'Амика написала эту книгу, чтобы сохранить нашу культуру и передать ее детям. Наверное, она потеряла ее во время странствий. Амика будет рада, если ты вернешь ей книгу.$b$bДругие жители деревни говорили, что видели ее по дороге в Элодор. Думаю, там ты ее и найдешь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36265, 'ruRU', 'Spires - Vignette Boss 001 - Stonespite', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36266, 'ruRU', 'В войне за ткань все средства хороши', 'Соберите 10 одеяний Призрачной Луны.', 'Раз уж ты так мне $Gпомог:помогла;, может, я могу попросить еще об одной услуге?$B$BМы у себя в деревне храним каждый лоскуток ткани, чтобы латать одежду и легкие доспехи. Правда, из-за недавних нападений почти весь мой запас пропал.$B$BЕсли ты лишишь сектантов Призрачной Луны их запасов, то в следующий раз они подумают дважды, прежде чем обокрасть нас.$B$BДобудь для меня несколько церемониальных одеяний Призрачной Луны, и я научу тебя своим любимым приемам портняжного мастерства.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36267, 'ruRU', 'Spires - Vignette 005 - Durkath Steelmaw', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36268, 'ruRU', 'Spires - Vignette Boss 007 - Kalos the Bloodbathed', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36269, 'ruRU', 'Волшебная ткань', 'Воспользуйтесь гноем из мухоловки Амики, чтобы создать образец волшебной ткани.', 'Теперь пора напитать ткань магией.$B$BЭтот процесс довольно прост. Нужно аккуратно погрузить шерстяную пряжу в гной из горгрондских мухоловок.$B$BОбычно его нужно собирать самостоятельно, но мне удалось забрать кое-что у клана Призрачной Луны во время их последнего набега.$B$BПользуйся на здоровье.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36271, 'ruRU', 'Игры с ловушками', 'Используйте железную ловушку, чтобы поймать элекка или талбука в Долине Призрачной Луны, а затем разместите заказ в своем хлеву.', 'Проходя через портал, мы не смогли взять с собой наших животных. Чтобы наладить производство шкур и меха, тебе нужно поймать и доставить сюда несколько местных зверей.$B$BЗдесь, в Долине Призрачной Луны, мы можем добывать шкуры с элекков или мех с талбуков.$B$BВозьми эту железную ловушку и поймай с ее помощью раненого взрослого талбука или элекка. Затем принеси ловушку обратно, и мы возьмемся за дело.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36272, 'ruRU', 'Накормить армию', 'Используйте улучшенную железную ловушку, чтобы поймать вепря или речное чудище в Горгронде, а затем разместите заказ в своем хлеву.', 'Мы уже довольно хорошо изучили этих животных и разработали для тебя новую ловушку. Она должна быть намного прочнее предыдущей!$B$BХочешь ее опробовать, командир? Улучшенная железная ловушка поможет тебе поймать в Горгронде живность помясистее, например больших вепрей или речных чудищ. Мы сможем приготовить из них весьма вкусные стейки.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36273, 'ruRU', 'Прополка', 'Уничтожьте $1oa |4стручлинга:стручлингов:стручлингов; Чащи злобнолистов.', 'Эти стручлинги из Чащи злобнолистов – настоящее бедствие, пора что-то предпринять!$b$bВместе с Хемингом Эрнестуэем я охотилась на самых больших и опасных зверей, которые тут водятся, но никогда еще в жизни не встречала настолько злобных, отвратительных и мстительных созданий, как стручлинги!$b$bЭти мерзкие маленькие твари быстро распространяются повсюду, точно сорняки; если немедленно что-то с этим не сделать, они расползутся по всему континенту!$b$bСтупай в Чащу злобнолистов и убей столько стручлингов, сколько сможешь!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36274, 'ruRU', 'Больше ловушка – крупнее награда', 'Поймайте в смертоносную железную ловушку самца железношкурого копытня, самца лютоклыка или болотного тяжелоступа.', 'Отличные новости, командир! При помощи собранных здесь материалов нам удалось сконструировать ловушку, из которой не вырвется даже самая сильная зверюга!$b$bПочему бы вам не отправиться в Награнд и не испытать ее? Говорят, на западных равнинах водится самая великолепная дичь по эту сторону Хрустального Озера.$b$bТолько сразу предупреждаю, эти твари так легко не сдадутся. Советую захватить друзей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36275, 'ruRU', 'Следуя за исследованием', 'Верните дневник исследователя, экспедиционные припасы и противогрибные ботинки доктору Хэдли Рикарду.', 'Мои заметки об исследованиях куда-то пропали!$b$bДолжно быть, они потерялись во время нападения стручлингов на исследовательскую станцию. Все результаты моих трудов сгинут без следа, если я не найду эти заметки!$b$bКстати, моя сумка с экспедиционными припасами тоже пропала... да и противогрибные ботинки куда-то подевались...$b$bКак я могу проводить биологические изыскания без данных и экипировки?!$b$bНет, так не пойдет.$b$bПрошу, отправляйся к Зангарском Берегу и отыщи мои пропавшие вещи, чтобы я и дальше мог исследовать грибы!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36276, 'ruRU', 'Spires - Vignette Boss 008 - Spawn of Sethe', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36277, 'ruRU', 'Полководцы – Максимальный уровень – Подземелье – Дополнительная награда', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36278, 'ruRU', 'Spires - Vignette Boss 009 - Talonbreaker', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36279, 'ruRU', 'Spires - Vignette 010 - Poisonmaster Bortusk', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36280, 'ruRU', 'Гарнизонная кампания: Кольцо Крови', 'Поговорите с Гаргтоком в Хранилище Гаргтока в Награнде.', 'Приветик!$B$BЯ тебя тут искал, да ты куда-то $gподевался:подевалась;. У меня тут дельце отличненькое наклюнулось в Кольце Крови в Награнде. Там толпы огров только и ждут новой крупной драки. Можно сорвать большой куш. Ну что, ты в деле?$B$BЭто же ты тогда $gпоказал:показала; всем в Круге Испытаний, что такое настоящая боль? Это – новая ступенька на твоем пути к славе! Тебе обязательно надо там быть.$B$BВстретимся у меня в тайнике, чтобы поговорить с глазу на глаз перед твоим громким дебютом.$B$B<Прилагается карта со значком доллара, нацарапанным на заброшенной огрской башне.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36281, 'ruRU', 'Гарнизонная кампания: Кольцо Крови', 'Поговорите с Гаргтоком в Хранилище Гаргтока в Награнде.', 'Приветик!$B$BЯ тебя тут искал, да ты куда-то $gподевался:подевалась;. У меня тут дельце отличненькое наклюнулось в Кольце Крови в Награнде. Там толпы огров только и ждут новой крупной драки. Можно сорвать большой куш. Ну что, ты в деле?$B$BПомнишь Арену Каменного Молота? Так вот, это намного, намного, просто неимоверно круче, так и знай.$B$BВстретимся у меня в тайнике, чтобы поговорить с глазу на глаз перед твоим громким дебютом.$B$B<Прилагается карта со значком доллара, нацарапанным на заброшенной огрской башне.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36282, 'ruRU', 'Гарнизонная кампания: Кольцо Крови', 'Поговорите с Гаргтоком в Хранилище Гаргтока в Награнде.', 'Приветик!$B$BЯ тебя тут искал, да ты куда-то $gподевался:подевалась;. О тебе, дорогуша, говорит вся арена! Круг Испытаний, ага? Арена Каменного Молота? Лечь и не встать!$B$BУ меня тут наклюнулось отличненькое дельце в Кольце Крови в Награнде. Толпы огров только и ждут новой крупной драки. Большой куш. Ты в деле?$B$BВстретимся у меня в тайнике, чтобы поговорить с глазу на глаз перед твоим громким дебютом.$B$B<Прилагается карта со значком доллара, нацарапанным на заброшенной огрской башне.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36283, 'ruRU', 'Spires - Vignette Boss 011 - Blightglow', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36284, 'ruRU', 'Занятный гриб', 'Соберите $1oa |4пригоршню:пригоршни:пригоршней; спор грибов.', 'На Зангарском Берегу встречается множество любопытных разновидностей грибов, многие из которых похожи на те, что растут в Азероте. И есть здесь один вид, который даже необычнее прочих!$b$bЯ называю его зангарским грибом, так как в экосистеме Дренора он занимает главенствующее положение среди прочих. Этот уникальный гриб обладает выдающимися адаптивными качествами, он растет на многих обитателях Зангарского Берега.$b$bПочему он существует? Какие у него свойства?$b$bЧтобы узнать это, мне нужны дополнительные образцы грибных спор.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36285, 'ruRU', 'Болотень', 'Убейте Болотня и извлеките грибной мозг.', 'Чтобы по-настоящему разобраться в устройстве и свойствах зангарских грибов, нужно подробно изучить образец со сложной структурой. Грибной мозг спорового великана прекрасно для этого подойдет. Впрочем, сгодится не любой великан: нам нужен по-настоящему огромный... злобный... дикий и первобытный представитель этого вида, одним словом, уникальный экземпляр!$b$bВ пещере, что находится глубоко под поверхностью земли, обитает древний споровый великан, которого называют Болотень. Убей чудовище и тщательно сохрани его мозг, он пригодится для исследований!', '', 'Мы должны добыть грибной мозг!', 'Болотень', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36286, 'ruRU', 'Передатчик 047-B', 'Верните передатчик Очкарику.', 'На обратной стороне передатчика выгравирована надпись:$B$B<СРОЧНО: пожалуйста, верните Очкарику в районе Элодора. Это чрезвычайно важно!>$B$B', '', '', '', '', '', 'Найдите Очкарика в районе Элодора.', 25549);
INSERT INTO `quest_template_locale` VALUES (36287, 'ruRU', 'Хватай-тащи', 'Поищите на берегу целые детали.', 'Мы извлекли все данные из восстановленного тобой передатчика и нанесли их на карту. Наш анализатор местности наконец-то готов!$B$BОсталось разобраться лишь с парой мелочей, и можно начинать настоящие испытания.$B$BОдин из моих пилотов упоминал, что видел корабль Железной Орды, севший на мель у берега. Если позаимствуешь оттуда несколько деталей, то мы сможем заставить эту штуку работать!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36288, 'ruRU', 'Spires - Vignette Boss 012 - Oskiira', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36289, 'ruRU', 'Под покровом теней', 'Поговорите с Боудриком Греем в своем гарнизоне.', 'И снова прими мои поздравления, $gЧемпион:Чемпионка; Крови. Ты $gсражался:сражалась; просто потрясающе.$B$BКстати – когда ты $gбыл:была; на арене, сюда пришел один из твоих дружков и попросил передать, чтобы ты $gвернулся:вернулась; на свою базу. Он назвался Боудриком Греем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36290, 'ruRU', 'Под покровом теней', 'Поговорите с Рокханом в своем гарнизоне.', 'И снова прими мои поздравления, $gЧемпион:Чемпионка; Крови. Ты $gсражался:сражалась; просто потрясающе.$B$BКстати – когда ты $gбыл:была; на арене, сюда пришел один из твоих дружков и попросил передать, чтобы ты $gвернулся:вернулась; на свою базу. Он назвался темным охотником.', '', '', '', '', '', 'Поговорите с Гаргтоком в Хранилище Гаргтока в Награнде.', 19865);
INSERT INTO `quest_template_locale` VALUES (36291, 'ruRU', 'Spires - Vignette Boss 014 -  Betsi Boombasket', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36292, 'ruRU', 'Подготовка вторжения', 'Встретьтесь с Траллом в тылу врага.', 'Я поведу небольшой отряд в тыл врага.$b$bВстретимся в землях клана Молота Ужаса, |3-6($c). Там решим, что делать дальше.', '', '', '', '', '', 'Поговорите с Траллом в Выжженных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (36294, 'ruRU', 'Phylarch the Evergreen A', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36295, 'ruRU', 'Phylarch the Evergreen B', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36296, 'ruRU', 'Филарх Вечнозеленый', 'Примите клятву крови мастера клинка На\'Шры.', '[PHYLARCH ACQUISITION TEXT GOES HERE]', '', '', 'Мастер клинка На\'Шра', '', '', '', 19865);
