INSERT INTO `quest_template_locale` VALUES (36298, 'ruRU', 'Шпили – Босс события 017 – Расколотый Шип', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36301, 'ruRU', 'Швейный набор Треги', 'Найдите Трегу в Вор\'голе.', 'Сумка полна выкроек и незнакомых швейных принадлежностей. На подкладке вышито имя \"Трега\".$b$bВы припоминаете, что видели ее в Вор\'голе. Возможно, она до сих пор еще там.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36303, 'ruRU', 'Spires - Vignette Boss 019 - Eyeless', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36304, 'ruRU', 'Spires - Vignette Boss 022 - Gochar', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36305, 'ruRU', 'Spires - Vignette Boss 023 - Gobblefin', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36306, 'ruRU', 'Spires - Vignette Boss 024 - Jiasska the Sporegorger', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36307, 'ruRU', 'Расследование вторжения', 'Встретьтесь с Мараадом в тылу врага.', 'Я проведу небольшой отряд в тыл врага.$b$bВстретимся в землях клана Молота Ужаса, |3-6($c). Там решим, что делать дальше.', '', '', '', '', '', 'Поговорите с Мараадом в Выжженных землях.', 25549);
INSERT INTO `quest_template_locale` VALUES (36308, 'ruRU', 'Зачарованный наруч клана Верховного Молота', 'Принесите наруч Элизе Темной Песне в гарнизон.', 'От этих древних наручей клана Верховного Молота так и веет мощной магией.\n\nВозможно, Элиза Темная Песня, гарнизонная поставщица товаров для наложения чар, может рассказать о них больше.', '', '', '', '', '', 'Поговорите с Элизой Темной Песней в вашем гарнизоне.', 25549);
INSERT INTO `quest_template_locale` VALUES (36309, 'ruRU', 'Сила железа', 'Отнесите сумку Гефесту.', 'По нашитой на сумку заплатке с именем вы с легкостью определяете владельца.$B$BВы вспоминаете, что слышали рассказы об отличном кузнеце, проживающем к северу от Эмбаари.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36310, 'ruRU', 'Араккоа-чародей', 'Найдите Делата на Забытом взморье на юге.', 'Араккоа сказал, что собирается исследовать аномалию на Забытом взморье, которая может быть как-то связана с другой частью доспеха.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36311, 'ruRU', 'Отец и сын', 'Найдите сына Гефеста.', 'Прошу, найди моего мальчика!$B$BПеред тем как пришли грабители, мы с ним были на холме к северо-востоку отсюда.$B$BИх было не так много, но я кузнец, а не воин!$B$BНеужели я так подставил своего единственного сына?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36312, 'ruRU', 'Spires - Vignette Boss 025 - Sun Sage Valarik', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36313, 'ruRU', 'Нерадивая ученица', 'Найдите и освободите Дииму из временной ловушки.', 'Ору\'кай был первым огром-магом во всем Дреноре, который овладел искусством наложения чар. После его смерти созданные им артефакты рассеялись по всему свету. Мне удалось выяснить, где находится его посох. Он там, на берегу прямо перед нами. \n\nКак видишь, наложенные на посох чары мешают его забрать. Ученица Диима взяла одно из колец Ору\'кая, чтобы развеять чары, но потерпела неудачу и тоже застряла в ловушке. \n\nНайди и освободи Дииму, забери кольцо и закончи то, что она начала. И не сомневайся, я тебя вознагражу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36314, 'ruRU', 'Замысловатая багровая подвеска', 'Спросите в гарнизоне, не узнает ли кто-нибудь подвеску.', 'Багровый самоцвет в этой подвеске не похож ни на один драгоценный камень, что вы видели в своей жизни, а оправа сделана столь искусно, что сразу ясно – такое украшение мог изготовить лишь настоящий мастер своего дела.$B$BОпределенно, вы могли бы многому у него научиться. Возможно, кто-нибудь в гарнизоне и узнает руку ювелира.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36315, 'ruRU', 'Посох Ору\'кая', 'Добудьте посох Ору\'кая и верните его Делату.', 'Если бы я знала, что быть чародеем так опасно – осталась бы в Шаттрате. \n\nВот, держи кольцо. Тот араккоа сказал, что с его помощью можно рассеять чары.\n\nВерни ему посох, может, он научит тебя тому, чему обещал научить меня.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36316, 'ruRU', 'Близкая победа', 'Убейте Ранжита, Аракната, Рухрана и высшего мудреца Вирикс в подземелье Небесного Пути.', 'Мы нанесли сокрушительный удар приверженцам, но бой еще не окончен.$B$BСобирай своих союзников, готовьтесь к окончательной осаде Небесного Пути!$b$b\"Тени сгущаются. Когда ворон проглотит солнце.$B$BПылающие небеса гаснут, когда крылья ворона медленно окутывают небосвод.$B$BОтдыхайте, дети мои, отдыхайте. Ведь даже солнце должно спать\".$B$BЭто колыбельная Рухмар, которую она пела самым первым араккоа. Боги, как же мы заплутали.', '', '', '', '', '', '', 25549);
