INSERT INTO `quest_template_locale` VALUES (36341, 'ruRU', 'Изначальное неистовство', 'Встретьтесь с Боудриком Греем у Врат Танаана в Таладоре, а затем победите Горгорека и вождя Азуку Ярость Клинка.', 'Похоже, время пришло, командир.$B$BМы должны остановить Железную Орду любой ценой. Я отправила буревестников в гарнизон и попросила Боудрика Грея перебросить твои войска к Вратам Танаана.$B$BК тому времени, как ты доберешься в северный Таладор, он будет ждать тебя там... Со всей армией.$B$BОткладывать больше нельзя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36342, 'ruRU', 'Изначальное неистовство', 'Поговорите с темным охотником Рокханом в северном Таладоре, затем одолейте Горгорека и Азуку Ярость Клинка.', 'Похоже, время пришло, командир.$B$BМы должны остановить Железную Орду любой ценой. Я отправила буревестников в твой гарнизон и попросила темного охотника Рокхана перебросить твои войска к Вратам Танаана.$B$BК тому времени, как ты доберешься в северный Таладор, он будет ждать тебя там... Со всей армией.$B$BОткладывать больше нельзя.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36344, 'ruRU', 'Накормить армию', 'Используйте улучшенную железную ловушку, чтобы поймать вепря или речное чудище в Горгронде, а затем разместите заказ в своем хлеву.', 'Мы уже довольно хорошо изучили этих животных и разработали для тебя новую ловушку. Она должна быть намного прочнее предыдущей.$B$BУлучшенная железная ловушка поможет тебе поймать на Дреноре зверей помясистее. Одним речным чудищем или вепрем из Горгронда можно накормить многих воинов.$B$BПоймай зверя и доставь его сюда, а мы приготовим потрясающий обед.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36345, 'ruRU', 'Игры с ловушками', 'Используйте железную ловушку, чтобы поймать копытня или волка на Хребте Ледяного Огня, а затем разместите заказ в своем хлеву.', 'Проходя через портал, мы не смогли взять с собой наших животных. Чтобы наладить производство шкур и меха, тебе нужно поймать и доставить сюда несколько местных зверей.$B$BНесмотря на то, что равнины замерзли, на Хребте Ледяного Огня предостаточно копытней и волков. С копытней можно получить шкуры, а с волков – мех.$B$BВозьми эту железную ловушку и поймай с ее помощью раненого взрослого зверя. Затем доставь пойманное животное сюда, и мы возьмемся за дело.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36346, 'ruRU', 'Больше ловушка – крупнее награда', 'Поймайте в смертоносную железную ловушку самца железношкурого копытня, самца лютоклыка или болотного тяжелоступа.', 'А, командир, рад снова видеть тебя. Благодаря собранным на Дреноре материалам, мы смогли соорудить ловушку, способную обездвижить даже самого крупного зверя.$B$BЭтих громадных созданий можно найти в западной части Награнда, на самых плодородных равнинах.$B$BНо предупреждаю: эти звери большие и сильные. Возможно, тебе стоит позвать на помощь товарищей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36347, 'ruRU', 'Атака на Плато Сокретара', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36348, 'ruRU', 'Атака на Плато Сокретара', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36352, 'ruRU', 'В поисках ювелира', 'Разыщите владельца медальона в Вор\'голе.', 'Ты точно $gуверен:уверена;, что не хочешь это продать? Я дам отличную цену!$B$BЛадно, ладно... раз ты настаиваешь на том, чтобы найти владельца, тебе стоит заглянуть в Вор\'гол.$B$BГоворят, там живет искусный мастер, занимающийся обработкой драгоценных металлов и камней. Возможно, он тебе и нужен.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36353, 'ruRU', 'По старой дружбе', '', '', '', '', '', '', '', '', 25549);
