INSERT INTO `quest_template_locale` VALUES (36366, 'ruRU', 'Spires – Treasure 046 – Goblin Rum', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36367, 'ruRU', 'Spires – Treasure 047 – Mayoral Campaign Contributions', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36368, 'ruRU', 'Пропавший дровосек', 'Найдите Френну в Хитросплетении.', 'Все эти буровые установки стали в Горгронде весьма и весьма нестабильными. Одна из них, говорят, даже сломалась здесь, в Хитросплетении.\n\nПоищи Френну. Она была на установке, которую мы запеленговали в этих краях. А я пойду искать буровую – может, еще удастся ее починить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36374, 'ruRU', 'Spiires – Treasure 036 – Statue of Anzu', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36375, 'ruRU', 'Spires – Treasure 026 – Sethekk Idol', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36376, 'ruRU', 'Нападение горенов!', 'Отразите нападение горенов.$B$B(Чтобы начать, еще раз поговорите с сержантом Краулером.)', 'У нас тут было землетрясение, гарнизон тряхануло пару раз. Да еще несколько разведчиков с задания не вернулось.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36377, 'ruRU', 'Spires – Treasure 049 – Rukhmar\'s Image', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36378, 'ruRU', 'Без труда не вытащишь и алмаз из слизнюка', 'Добудьте лавовые алмазы из лавовых слизнюков, населяющих Хребет Ледяного Огня.', 'Ты тоже хочешь постичь тайны наших алмазов, |3-6($r)? Что ж, в благодарность за возвращение моей подвески я тебе помогу.$B$BТолько сразу предупреждаю, что добыча необходимых материалов – дело очень хлопотное.$B$BК северу отсюда встречаются озера магмы, в которых из лавы рождаются живые существа. Внутри этих существ медленно кристаллизуются великолепные алмазы.$B$BПожалуйста, принеси мне несколько таких камней...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36379, 'ruRU', 'Взгляд сквозь портал', 'Найдите разведчицу Пазерп и воспользуйтесь ее телескопом.', 'Я отправил разведчицу Пазерп осмотреть портал. Она уже должна была вернуться с докладом. Что же могло ее задержать?$b$bОна одна из моих лучших агентов. Надеюсь, с ней все в порядке.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36380, 'ruRU', 'Бриллианты вечны', 'Подождите окончания работы над подвеской.', 'Из этого драгоценного камня я изготовлю для тебя прекрасную подвеску.$B$BА ты внимательно следи за моей работой да мотай на ус – глядишь, чему и научишься.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36381, 'ruRU', 'Spires – Shrine Treasure 01 – Gift of Anzu', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36382, 'ruRU', 'Взгляд сквозь портал', 'Найдите разведчика Пазастика и воспользуйтесь его телескопом.', 'Я отправил разведчика Пазастика поглядеть на портал. Пора бы ему уже вернуться, почему он не идет?$b$bВот что бывает, когда нанимаешь гоблинов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36384, 'ruRU', 'Полевые испытания', 'Отправляйтесь на Мыс Паросвистов и опробуйте действие непротестированной сыворотки на зараженном забияке или зараженном дровосеке. Затем вернитесь к Крикселю Паросвисту и доложите о результатах.', 'Слушай, я еще не говорил об этом Кимзи, потому что не хочу ее расстраивать, но я решил не уезжать с Мыса Паросвистов.$b$bПонимаешь, я работал над обеззараживающей сывороткой, но во время последних испытаний меня окружили, и я поранил ногу.$b$bЯ уверен, что нашел правильное решение, но мне нужно проверить действенность средства. Возьми эту склянку и испытай действие сыворотки на ком-нибудь из зараженных около моего дома.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36385, 'ruRU', 'Наследие древних', 'Достаньте сердце Курука, ствол Отука, ветвь Лорука и корни Ханука.', 'Открыв древний фолиант, вы обнаруживаете, что это на самом деле не книга, а ларец. В нем четыре пустых отделения.$B$BПрисмотревшись, вы видите, что над каждым отделением вырезан силуэт дренорского древнего, нанесены какие-то символы и прикреплен сосуд, в котором когда-то хранился образец ткани изображенного древнего. Кажется, там также указано, где этих древних можно найти: в Долине Призрачной Луны, в Горгронде, на Пиках Арака и в Награнде.$B$BЭто инструкции для убийцы. Деревья просят убить другие деревья.', '', '', '', '', '', '', 25549);
