INSERT INTO `quest_template_locale` VALUES (36403, 'ruRU', 'Spires – Treasure 010 – Offering to the Raven Mother 01', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36404, 'ruRU', 'Расчистка места для сада', 'Убейте 8 енотов Зашедшей Луны.', 'Эта поляна идеально подходит для выращивания трав на нужды нашего гарнизона. Есть только одна небольшая проблема. Проклятые еноты!$b$bНадо истребить их всех до одного – и тогда совсем скоро наш сад расцветет пышным цветом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36405, 'ruRU', 'Spires – Treasure 051 – Offering to the Raven Mother 02', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36406, 'ruRU', 'Spires – Treasure 052 – Offering to the Raven Mother 03', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36407, 'ruRU', 'Spires – Treasure 053 – Offering to the Raven Mother 04', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36408, 'ruRU', 'Утраченная сила', 'Найдите в деревне Эмбаари мастера, знающего толк в геммологии и магии.', '<Осколок ярко вспыхивает на свету, и в тот же миг его аура окончательно угасает.>$B$BПохоже, его сила полностью исчерпалась.$B$BВы припоминаете, что слышали о специалисте из деревни Эмбаари, который занимается магическим усилением самоцветов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36409, 'ruRU', 'Исцеление', 'Достаньте образец для механолога Балиры.', 'Как я уже говорил, наши крупные защитные кристаллы растеряли свою былую силу, вследствие чего в обороне возникли бреши. Тот кристалл, который ты мне $gпринес:принесла;, стал очередным напоминанием о всей серьезности нашего положения. Готов биться об заклад, что тут замешана магия орков клана Призрачной Луны.$B$BОдин из наших рагнари-разведчиков видел орка, спешившего на север в долину за деревней Бледной Луны. Догони этого орка и посмотри, нет ли у него при себе сосуда, в котором собрана похищенная энергия. Если он окажется у нас, я верну кристаллам их былую силу.', '', '', 'Морах Ледяной Шепот', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36410, 'ruRU', 'Spires – Treasure 054 – Offering to the Raven Mother 05', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36411, 'ruRU', 'Spires – Treasure 014 – A Lost Ring', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36412, 'ruRU', 'Нападение клана Призрачной Луны', 'Отразите нападение клана Призрачной Луны на ваш гарнизон.$B$B(Чтобы начать, еще раз поговорите с сержантом Краулером.)', 'Разведчики сообщают, что клан Призрачной Луны взбудоражен, как потревоженное осиное гнездо. Ну что, нам пора снова отрабатывать наше жалованье, командир?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36414, 'ruRU', 'Нападение клана Призрачной Луны!', 'Отразите нападение клана Призрачной Луны на ваш гарнизон.$B$B(Чтобы начать, еще раз поговорите с сержантом Зловещей Утробой.)', 'Разведчики говорят, что над нами снова нависает угроза Призрачной Луны. Некроманты там, все дела... Если я погибну и восстану из мертвых, ты уж, командир, пожалуйста, прикончи меня поскорее. Не хочу быть упырем.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36415, 'ruRU', 'Spires – Treasure 020 – Reagent Pouch', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36416, 'ruRU', 'Spires – Treasure 049 – Misplaced Scroll', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36417, 'ruRU', 'Из хладных рук...', 'Добудьте 10 кусков поврежденной волшебной ткани у огров из клана Камнерогов.', 'Огры забрали всю мою волшебную ткань!$b$bЯ надежно спрятала ее на самом дне моей сумки. Откуда они вообще узнали о том, что она такая ценная?$b$bЕсли они сумеют воспользоваться хотя бы малой толикой ее потенциала, нам всем грозят большие неприятности.$b$b$n, это проблема Северных Волков. Значит, и решать ее следует в духе Северных Волков.$b$bТы мне поможешь?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36418, 'ruRU', 'Spires – Treasure 013 – Dark Grimoire', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36419, 'ruRU', 'Пропитка пряжи', 'Окуните пряжу в сок мухоловки Треги, чтобы создать образец волшебной ткани.', 'В голове не укладывается, что они пытались вырвать магию из ткани в буквальном смысле этого слова!$b$bПохоже, мы зря волновались о том, что мои секреты могут попасть не в те руки, но лучше перестраховаться...$b$bВ благодарность за твою помощь я научу тебя зачаровывать ткань.$b$bСок мухоловки – большая редкость в этих краях, но у меня еще остались запасы. Возьми шерстяную пряжу, окуни ее в сок – и ты $gсам:сама; увидишь, из-за чего затевался весь этот сыр-бор.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36420, 'ruRU', 'Spires – Treasure 011 – Garrison Supplies', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36421, 'ruRU', 'Spires – Treasure 024 – Sun-Touched Cache', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36422, 'ruRU', 'Spires – Treasure 029 – Sun-Touched Cache', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36423, 'ruRU', 'Питомцы против паразитов', 'Победите трех вредителей в вашем гарнизоне.', 'Мне хотелось подготовить это место для твоих питомцев, но при строительстве гарнизона мы обнаружили множество опасных паразитов. Самостоятельно с ними справиться не удалось.$b$bВ саду сидит злая морковь, гигантская крыса пожирает наши припасы, а гнусная водяная тварь атакует рыбаков. Если можешь их уничтожить, у меня освободится время для завершения работ в зверинце.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36424, 'ruRU', 'Spires – Treasure 059 – Sun-Touched Cache', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36425, 'ruRU', 'Яйцебой', 'Разбейте $1oa |4яйцо:яйца:яиц; опустошителя в лагере Тернистого Шрама.', '<Влажное пульсирующее яйцо опустошителя, несомненно, содержащее зародыш.$B$BБыстрый удар ноги решит проблему.>', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36426, 'ruRU', 'Состязание сфер', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36427, 'ruRU', 'Расцвет и падение \"Баров Индастриз\": Алексий Баров', 'Примите клятву крови мастера клинка На\'Шры.', '[PHYLARCH ACQUISITION TEXT GOES HERE]', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36428, 'ruRU', 'Вылечим – насильно!', 'Излечите $1oa |4зараженного гоблина:зараженных гоблинов:зараженных гоблинов;.', 'Изучив результаты испытаний, могу с уверенностью утверждать, что мы на правильном пути.$b$bЯ внес несколько изменений в сыворотку. Теперь она должна стать намного мощнее, вот только для эффективного срабатывания требуется, чтобы в больном было не слишком много крови... иначе концентрации сыворотки не хватит.$b$bЗначит, тебе придется повыпускать кровь из этих бедолаг перед применением сыворотки.$b$bБолезнь прогрессирует и скоро станет неизлечимой, так что у нас есть только один шанс, чтобы спасти как можно больше жизней.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36429, 'ruRU', 'Расцвет и падение \"Баров Индастриз\": Вэлдон Баров', 'Примите клятву крови мастера клинка На\'Шры.', '[PHYLARCH ACQUISITION TEXT GOES HERE]', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36430, 'ruRU', 'Tracking: Mill Treasure 18', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36431, 'ruRU', 'Событие: Исказитель душ Торек', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36432, 'ruRU', 'В поисках разведчика', 'Найдите Альтаура в Погибели Дионора в Горгронде.', 'Мы все еще ищем наших разведчиков. Один из них, Альтаур, любит брать на себя самые опасные задания.$B$BНо от него пока нет никаких вестей, так что нам стоит проверить, не откусил ли он больше, чем мог проглотить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36433, 'ruRU', 'Шпили – Сокровище 008 – Контрабандные апекситовые артефакты', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36434, 'ruRU', 'Милашка Пенни', 'Поговорите с Пенни Поппинстук на Звериной заставе.', '<Дуротан с любопытством смотрит на вас.>\n\nЯ вижу, в вашем мире скрытность не приветствуется?\n\nИди вперед и встреть нашу новую союзницу. Мы присоединимся к тебе, как только будем готовы.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36435, 'ruRU', 'Загадочные разведданные', 'Поищите в Вор\'голе того, кто сможет перевести записи.', 'Записи прочесть невозможно, но опыт подсказывает мне, что это обычный орочий.$B$BВозможно, что здесь содержится важная информация, очень ценная для орков клана Северного Волка.$B$BДумаю, кто-нибудь в Вор\'голе сможет прочитать эти записи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36436, 'ruRU', 'Подрезка растений', 'Убейте $1oa |4защитника:защитников:защитников; в Погибели Дионора.', 'Там может быть еще больше этой поросли, но чтобы разобраться с ситуацией, нам придется все это расчистить, верно?$B$BПредлагаю в целях безопасности разделаться с самыми агрессивными защитниками.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36437, 'ruRU', 'Посол к древнему', 'Поговорите с Березусом в Погибели Дионора в Горгронде.', 'Похоже, недавно поблизости был убит генезотавр, и с тех пор началось... Монстры в окрестностях совсем обезумели, и теперь я переживаю за безопасность нашей заставы.$B$BЗдесь неподалеку есть странный, очень печальный древний. Кажется, он не представляет опасности. Разузнаешь его историю?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36438, 'ruRU', 'Рожебой против Валуна', 'Разбейте загораживающий проход валун, попросив об этом гладиатора Рожебоя.', 'Саблероны забрали свое сокровище на утес и забаррикадировались после атаки Березуса. Прорваться туда будет сложно, но я слышал, у тебя есть туз в рукаве.$B$BОдин из входов перекрыт огромным булыжником. Ни тебе, ни мне с этим ничего не поделать, а вот огру с большой дубиной это, может, и под силу. Думаю, ты $gпонял:поняла;, кого я имею ввиду...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36439, 'ruRU', 'Крошшер против саблеронов', 'Разрубите лозы с помощью крошшера.', 'Саблероны забрали свое сокровище на утес и забаррикадировались после атаки Березуса. Прорваться туда будет сложно, но я слышал, у тебя есть туз в рукаве.$B$BОдин из входов перекрыт густыми зарослями. Думаю, у нас есть идеальное решение проблемы. Крошшер подойдет как нельзя лучше. Ты знаешь, что делать...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36440, 'ruRU', 'Сокращение численности саблеронов', 'Убейте $1oa |4саблерона:саблеронов:саблеронов; на Парящем утесе.', 'Мы все ближе к нашей цели, но нашему продвижению мешают острозубые саблероны.$b$bЕсли мы хотим продвигаться дальше, самых агрессивных саблеронов придется убить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36441, 'ruRU', 'Возврат собственности', 'Отыщите $1oa |4пучок:пучка:пучков; благословенных трав в кладах саблеронов на Парящем утесе.', 'Ваше внимание привлекло тусклое зеленоватое свечение контейнера. Внутри находится светящийся пучок благословенных трав, очевидно, украденный из раскинувшихся внизу Буйных зарослей.$b$bБудет разумно забрать все травы, чтобы саблероны прекратили свои неумелые попытки овладеть магией растений, раздражающие местных магнаронов.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36442, 'ruRU', 'Добыть Цветок Смерти', 'Заберите Цветок Смерти у Владыки дыма Ррыка на Парящем утесе.', 'Твои усилия были не напрасны: ты $gузнал:узнала;, что в пещере неподалеку отсюда могущественный саблеронский шаман учится повелевать магией генезотавров при помощи Цветка Смерти, который мы ищем. Решение напрашивается само. Убей шамана, забери Цветок Смерти и возвращайся к Березусу. Это поможет укрепить защиту аванпоста.', '', 'Убейте Владыку дыма Ррыка и захватите Цветок Смерти.', 'Владыка дыма Ррык', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36443, 'ruRU', 'Упокоение Дионора', 'Наблюдайте за ритуалом Березуса.', 'Этот цветок – настоящий дар для меня. Теперь я смогу навсегда вернуть Дионора назад в Буйные заросли и покончить с этим кошмаром. Осталось лишь провести ритуал... Наблюдай. Больше ты никогда такого не увидишь.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36444, 'ruRU', 'Шпили – Сокровище 006 – Взрывчатка Железной Орды', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36445, 'ruRU', 'Шпили – Сокровище 015 – Копье Железной Орды', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36446, 'ruRU', 'Шпили – Сокровище 016 – Сума изгоя', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36447, 'ruRU', 'Шпили – Сокровище 020 – Корзинка изгоя', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36448, 'ruRU', 'Минус один', 'Раздобудьте голову Алексия Барова.', 'Каким же я был идиотом, что поверил ему после финансового краха семьи Баровых! Мне надо было убить его при первой же возможности.$B$BА теперь он решил, что станет единолично разрабатывать этот участок, а я останусь не при делах?!$B$BНет, дорогой братец, только не в этот раз. В \"Баров Индастриз\" может быть только один директор – и это буду я.$B$B$GМой друг-простолюдин:Моя добрая простолюдинка;, окажи мне услугу. Найди моего брата Алексия и вручи ему уведомление о расторжении!$B$BЕго ты скорее всего найдешь в пустошах, он добывает там древесину.', '', 'Бывший брат и подлый предатель.', 'Алексий Баров', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36449, 'ruRU', 'Минус один', 'Раздобудьте голову Вэлдона Барова.', 'Каким же я был идиотом, что поверил ему после финансового краха семьи Баровых! Мне надо было убить его при первой же возможности.$B$BА теперь он решил, что станет единолично разрабатывать этот участок, а я останусь не при делах?!$B$BНет, дорогой братец, только не в этот раз. В \"Баров Индастриз\" может быть только один директор – и это буду я.$B$B$GМой друг-простолюдин:Моя добрая простолюдинка;, окажи мне услугу. Найди моего брата Вэлдона и вручи ему уведомление о расторжении!$B$BЕго ты скорее всего найдешь в пустошах, он добывает там древесину.', '', 'Бывший брат и подлый предатель.', 'Вэлдон Баров', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36450, 'ruRU', 'Шпили – Сокровище 028 – Сетеккский ритуальный напиток', '', '', '', '', '', '', '', '', 19865);
