INSERT INTO `quest_template_locale` VALUES (36454, 'ruRU', 'Шпили – Сокровище 039 – Сушеные грибные шляпки', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36455, 'ruRU', 'Шпили – Сокровище 040 – Раскисшая сумка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36456, 'ruRU', 'Шпили – Сокровище 045 – Части крошшера', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36457, 'ruRU', 'В обход охраны', 'Проникните в Гром\'гар с помощью карты Роли.', 'О нет!$B$BЭто список пленных, их явно ждет перевод в другое место – или, чего доброго, казнь!$B$BТут есть и знакомое мне имя – имя моего наставника!$B$BЯ все ждал его возвращения, но он, похоже, попал в руки врага.$B$BЭто ужасно! Прошу тебя, $n, его надо спасти!$B$BЕсли верить записке, его забрали в Гром\'гар, это далеко на восток отсюда.$B$BМинутку... кажется, я знаю, как можно пробраться туда тайком...', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36458, 'ruRU', 'Шпили – Сокровище 055 – Брошенная кирка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36459, 'ruRU', 'Шпили – Сокровище 056 – Лезвие пилы', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36460, 'ruRU', 'Стена падет!', 'Используйте подрывную машинку Пенни, чтобы взорвать каменную стену.', 'Дело такое.\n\nПока я летела, я увидела местечко, которое легко оборонять.\n\nПрямо за этими камнями есть идеальная площадка, где можно окопаться. У меня даже готовы планы, как там все обустроить!\n\nНичего, что я бегу впереди паровоза?\n\nВ общем, как будешь $gготов:готова; – жми на поршень!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36461, 'ruRU', 'В поисках гранильщика', 'Поищите в Вор\'голе владельца подвески.', 'А ты точно не хочешь с ней расстаться? Я хорошо заплачу!$B$BЛадно, ладно. Раз ты так хочешь найти владельца, тебе надо в Вор\'гол.$B$BГоворят, там есть опытный мастер, умело обрабатывающий драгоценные металлы и камни.$B$BНо если вдруг передумаешь – ты знаешь, где меня искать...', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36462, 'ruRU', 'Шпили – Сокровище 012 – Сундук адмирала Тейлора', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36463, 'ruRU', 'Шпили – Сокровище 012 – Ключ от сундука Тейлора', '', '', '', '', '', '', '', '', 19865);
