INSERT INTO `quest_template_locale` VALUES (36469, 'ruRU', 'Питомцы против паразитов', 'Одолейте трех вредителей в своем гарнизоне.', 'Я готовила это место для твоих питомцев, но при строительстве гарнизона мы обнаружили множество опасных вредителей. Я хотела с ними сама разобраться, но мне они оказались не по зубам.$b$bВ саду сидит злая морковь, гигантская крыса пожирает наши припасы, а гнусная водяная тварь атакует рыбаков. Если сможешь их усмирить, у меня освободится время для завершения работ в зверинце.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36470, 'ruRU', 'Шпили – Босс события 006 – Гнилошляп', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36471, 'ruRU', 'Новый боец ярмарки Новолуния!', 'Одолейте Кристофа фон Физеля в битве питомцев.', 'Посмотри на меня, теперь на моего коня, теперь опять на меня – разве я не самый доблестный дрессировщик всех времен и народов?$B$BА посмотри вон на того моего товарища – сидит ли он на лошади? Конечно же, нет! Есть ли у него на шляпе фейерверки? Да ни в жисть! У меня все самое лучшее – от расцветки куртки до фамилии, которую я сам выдумал.$B$BОсмелишься ли ты бросить вызов Кристофу Уилликенсу Деннису Рагнаросу фон Физелю Первому?$B$BО, я уже вижу, как ты трепещешь!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36472, 'ruRU', 'Шпили – Босс события 028 – Древняя оса', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36473, 'ruRU', 'Хребет Скорби', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36474, 'ruRU', 'Терновое Цветение', 'Отыщите Дреку и Каз в Терновом Цветении.', 'Каз, шаманка клана Веселого Черепа, убежала, пока мы добирались сюда.$b$bОна сказала, что будет искать своих соплеменников в джунглях на юге.$b$bДрека пошла с ней – чтобы защищать ее, а также предупредить возможное предательство.$b$bКомандир, если Каз говорила правду, то ей с Дрекой понадобится серьезная помощь.$b$bМожет, ты присоединишься к ним? Они не могли уйти далеко.$b$bИ это может быть идеальным испытанием для твоего нового крошшера и возможностью заготовить древесину.', '', '', '', '', '', 'Поговорите с Дрекой в Терновом Цветении.', 25549);
INSERT INTO `quest_template_locale` VALUES (36475, 'ruRU', 'Кража декларации', 'Заберите содержимое сейфа главного осадного кузнеца Уратока.', 'Командир, вы с Роли проделали большую работу, разыскивая меня, но я именно там, где должен быть.$B$BС самого прибытия сюда мы без устали работаем над тем, чтобы расшифровать дренейские записи.$B$BЯ уже думал, что их смысл мне вот-вот откроется, но тут меня похитили!$B$BПожалуйста, помоги мне выбраться. На холме к востоку ты найдешь палатку главного осадного кузнеца.$B$BЕсли сможешь вытащить из его сундука документы и, по возможности, ключ, я наконец-то сумею перевести тексты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36476, 'ruRU', 'Южная часть Гронн-каньона', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36477, 'ruRU', 'Нарушенные обещания', 'Найдите кого-нибудь на ярмарке Новолуния, кого бы заинтересовало это кольцо.', 'Сильно поцарапанное кольцо, чуть запятнанное кровью.$B$BВозможно, кто-нибудь на ярмарке Новолуния знает об этой вещи больше.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36478, 'ruRU', 'Шпили – Событие 020 – Темноствол', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36479, 'ruRU', 'Шпили – Событие 021 – Ночной живоглот', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36480, 'ruRU', 'Долина Разрушений', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36481, 'ruRU', 'Вызов огнекрыла', 'Соберите в полете 15 колец.', 'Ты $Gготов:готова; взмыть в небеса и испытать \"Вызов огнекрыла\"? Это здорово!$B$BСобери 15 колец – и победишь! Как будешь $Gготов:готова; к взлету – скажи.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36482, 'ruRU', 'Зеленый огрон?', 'Убейте зараженного огрона.', 'Каз всегда говорила, что зеленые огроны плохие.$b$bУ этих ботани живет зеленый огрон, и это паршивая новость.$b$bОн оказался достаточно силен, чтобы раскидать весь охотничий отряд моего отца.$b$bСумеешь убить его?', '', 'Одно из наиболее опасных зараженных существ в арсенале ботани.', 'Зараженный огрон', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36483, 'ruRU', 'Битва с питомцами', 'Победите питомцев в боевой зоне.', 'У нас в боевом загоне посетители, они жаждут драки. Может, покажешь им лично, на что способен дрессировщик боевых питомцев?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36488, 'ruRU', 'Дворфы-воры', 'Отыщите Резателя на утесе Бастиона.', 'Резатель напал на след украденного дворфами артефакта. Когда речь идет об охоте в джунглях, у него нюх, как у волка.$b$bИди по каньонам на юг, пока не встретишься с ним.$b$bПохоже, нас с королевой волков здесь ждет еще одна драка напоследок.$b$BМы пойдем по следу со всей возможной скоростью.', '', '', '', '', '', 'Отыщите Резателя на утесе Бастиона.', 25549);
INSERT INTO `quest_template_locale` VALUES (36489, 'ruRU', 'Нападение на Яму', 'Уничтожьте тайник с оружием Железной Орды и убейте столько ее бойцов, сколько сможете.', 'Железная Орда складирует свое оружие и боеприпасы возле Литейной. Дренорская кампания истощила их запасы. Проберись туда и устрой там бучу, заодно используй какие-нибудь из хранящихся там боеприпасов против Железной Орды. Нечего бросать их где ни попадя!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36490, 'ruRU', 'Нападение на Cтолпы Судьбы', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36491, 'ruRU', 'Нападение на Cтолпы Судьбы', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36492, 'ruRU', 'Garrison Pet Battle', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36493, 'ruRU', 'Задание на поиск способа открыть дверь Отаара', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36494, 'ruRU', 'Вести из Таладора', 'Поговорите с Рокханом в своем гарнизоне на Хребте Ледяного Огня.', 'Рокхан прислал весточку – ты $gнужен:нужна; в Ледяных скалах. Железная Орда высадилась на берегах Таладора.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36495, 'ruRU', 'Вести из Таладора', 'Поговорите с Боудриком Греем в своем гарнизоне в Долине Призрачной Луны.', 'Боудрик Грей из твоего гарнизона доложил, что флот Железной Орды обнаружен у берегов Таладора.$b$bМы не можем позволить им уничтожить Шаттрат.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36498, 'ruRU', 'Нападение Железной Орды', 'Поговорите с воздаятелем Мараадом на Расколотом береговом плацдарме в Выжженных Землях.', 'По приказу его высочества короля Вариана Ринна, все способные держать в руках оружие граждане должны прибыть к воздаятелю Марааду на Расколотый береговой плацдарм в Выжженных землях.$B$BЧтобы попасть прямо на передовую, воспользуйтесь порталом в Башне магов в Штормграде.$B$BИмя новой угрозы – Железная Орда. Она захватила Темный портал и ее надо остановить.$B$BВо славу и за честь Альянса!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36499, 'ruRU', 'Нападение Железной Орды', 'Поговорите с Траллом в Расколотом лагере, что в Выжженных землях.', 'Всем способным держать в руках оружие приказывается немедленно прибыть к Траллу в Выжженные земли.$B$BЧтобы попасть прямо на передовую, воспользуйтесь порталом в Волоке в Оргриммаре.$B$BИмя новой угрозы – Железная Орда. Она захватила Темный портал и ее надо остановить.$B$BСудьба зовет!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36500, 'ruRU', 'Терновое Цветение', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36501, 'ruRU', 'Нападение Железной Орды', 'Стрелок Арефеон', 'По приказу его высочества короля Вариана Ринна, все способные держать в руках оружие граждане должны прибыть к воздаятелю Марааду на Расколотый береговой плацдарм в Выжженных землях.$B$BДобраться до пристани у крепости Северной Стражи можно, взяв в Пиратской бухте лодку до Кабестана и пройдя по побережью на юг.$B$BВо славу и за честь Альянса!', '', '', '', '', '', 'Поговорите с воздаятелем Мараадом в xxxx, что в Выжженных землях.', 19865);
INSERT INTO `quest_template_locale` VALUES (36502, 'ruRU', 'Почетный трофей: Биожор', 'Отнесите трофей Марааду на Верхний Путь в Горгронде.', 'Вы победили Биожора и завоевали трофей, которым не стыдно похвалиться в своем лагере. $b$bОтнесите трофей Марааду – это прославит вас еще больше!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36503, 'ruRU', 'Почетный трофей: Биожор', 'Отнесите трофей Дуротану на Звериную заставу в Горгронде.', 'Вы победили Биожора и завоевали трофей, которым не стыдно похвалиться в своем лагере. $b$bОтнесите трофей Дуротану на Звериную заставу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36504, 'ruRU', 'Ключи Вечного Рассвета', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36505, 'ruRU', 'Накидка воина', 'Найдите в Вор\'голе орка из клана Северного Волка, который сможет вам помочь.', 'Хоть этот плащ явно знавал лучшие времена, качество работы все равно впечатляет. Любой обычный плащ за это время давно бы истлел.$B$BВозможно, кто-нибудь из клана Северного Волка в Вор\'голе поможет вам его починить.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36506, 'ruRU', 'Сокровище: добыча сильнейшего орка-заклинателя', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36507, 'ruRU', 'Сокровище: скелет орка', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36508, 'ruRU', 'Это кто-то из твоих?', 'Поговорите с Рексаром и поручитесь за рангари Эрдани.', 'Она пряталась в кустах. Говорит, что твой союзник.$b$bЭто правда? Или мне зажарить ее на медленном огне?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36509, 'ruRU', 'Сокровище: груда сокровищ гидры', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36510, 'ruRU', 'Огненный аммонит', 'Добудьте 10 порций икры огненных аммонитов на Хребте Ледяного Огня по просьбе Рона Эштона.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Осмотри водоемы Хребта Ледяного Огня и выясни, где можно хорошо порыбачить. Каждой пойманной рыбине надо будет вспороть брюхо и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36511, 'ruRU', 'Безротый скрытиус', 'Рон Эштон хочет, чтобы вы собрали 10 порций икры безротого скрытиуса в Горгронде.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Осмотри водоемы Горгронда и выясни, где можно хорошо порыбачить. Каждой пойманной рыбине надо будет вспороть брюхо и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36512, 'ruRU', 'В единстве – наша сила!', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36513, 'ruRU', 'Толстопузик', 'Добудьте 10 порций икры толстопузиков в Награнде по просьбе Рона Эштона.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Осмотри водоемы Награнда и выясни, где можно хорошо порыбачить. Каждой пойманной рыбине надо будет вспороть брюхо и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36514, 'ruRU', 'Слепой озерный осетр', 'Добудьте 10 порций икры слепых озерных осетров в Долине Призрачной Луны по просьбе Рона Эштона.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Поищи в водоемах Долины Призрачной Луны рыбу, которая может нам пригодиться. Тебе придется распотрошить ее и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36515, 'ruRU', 'Хлыстохвост Черноводья', 'Принесите Рону Эштону 10 порций икры хлыстохвостов Черноводья, которые водятся в водоемах Таладора.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Осмотри водоемы Таладора и выясни, где можно хорошо порыбачить. Каждой пойманной рыбине надо будет вспороть брюхо и достать икру.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36516, 'ruRU', 'Режь под корень!', 'Добудьте материалы, необходимые для ремонта плаща.', 'После всего, что ты для нас $gсделал:сделала;, я с радостью тебе помогу. К сожалению, у меня нет необходимых материалов, чтобы выполнить ремонт как полагается.$B$BНужны будут шкуры копытней, обитающих у подножья, – я дам тебе свой нож, чтобы ты $gмог:могла; освежевать их. Еще понадобится жидкая смола из сажелиста, чтобы как следует выдубить эти шкуры.$B$BК сожалению, единственное известное мне место, где растет сажелист, облюбовали огры, так что тебе, скорее всего, придется добывать его с боем.$B$BВозвращайся ко мне со всем необходимым, и я с радостью помогу тебе починить твой плащ.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36517, 'ruRU', 'Глубинный угорь-мешкорот', 'Добудьте 10 порций икры глубинных угрей-мешкоротов с Пиков Арака по просьбе Рона Эштона.', 'Было бы неплохо начать разводить в гарнизонном пруду рыбу. Осмотри водоемы Пиков Арака и выясни, где можно хорошо порыбачить. Каждой пойманной рыбине надо будет вспороть брюхо и достать икру.', '', '', '', '', '', '', 25549);
