INSERT INTO `quest_template_locale` VALUES (36523, 'ruRU', 'Зеленый огрон?', 'Убейте зараженного огрона.', 'У этих ваших ботани откуда-то взялся зеленый огрон. Зеленый огрон!$b$bЯ не разбираюсь в этих ходячих растениях, но это явно не к добру.$b$bДумаешь, справишься с таким страшилищем?', '', 'Одно из наиболее опасных зараженных существ в арсенале ботани.', 'Зараженный огрон', '', '', '', 25549);
