INSERT INTO `quest_template_locale` VALUES (36725, 'ruRU', 'Безупречный топор Северного Волка с отметинами клыков', 'Выставите артефакт на обозрение.', 'Этот артефакт полностью отреставрирован и теперь находится в отличном состоянии. Его вполне можно выставить на всеобщее обозрение в вашем гарнизоне.', '', '', '', '', '', '', 25549);
