INSERT INTO `quest_template_locale` VALUES (36741, 'ruRU', 'Выдержанное зелье свободы действий', 'Принесите Гимлетте Наливайс 10 жемчужин клана Молота Ашрана.', 'Говорят, что против наших героев на передовой противник активно использует эффекты замедления, обездвижения и оглушения! К счастью, у меня есть зелье, позволяющее этому противостоять. Рецепт немного староват, но должен сработать.$b$bКлючевой компонент для этого зелья можно найти здесь в Ашране, на побережье возле башни огров.', '', '', '', '', '', 'Вернитесь к Гимлетте Наливайс в Крепость Преграды Ветров.', 19865);
INSERT INTO `quest_template_locale` VALUES (36742, 'ruRU', 'Выдержанное зелье свободы действий', 'Принесите Тире Серебряной Крови 10 жемчужин клана Молота Ашрана.', 'Альянс все активнее использует против нас в ближнем бою эффекты замедления, обездвижения и оглушения. К счастью, у меня есть зелье, позволяющее этому противостоять. Рецепт немного староват, но должен сработать.$b$bКлючевой компонент для этого зелья можно найти здесь в Ашране, на побережье возле башни огров.', '', '', '', '', '', 'Вернитесь к Тире Серебряной Крови на Аванпост Копья Войны.', 19865);
INSERT INTO `quest_template_locale` VALUES (36743, 'ruRU', 'Безупречный клык с семейной историей клана Северного Волка', 'Выставите артефакт на обозрение.', 'Этот артефакт полностью отреставрирован и теперь находится в отличном состоянии. Его вполне можно выставить на всеобщее обозрение в вашем гарнизоне.', '', '', '', '', '', '', 25549);
