INSERT INTO `quest_template_locale` VALUES (36790, 'ruRU', 'Отмщение посвященного', 'Убейте 18 саблеронов Кровавой Гривы.', 'Я... Мне конец. Совсем скоро дух мой отправится к Прародительнице воронов.$b$bУмоляю тебя, $gнезнакомец:незнакомка;, отомсти за меня! Перебей этих гнусных тварей.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36791, 'ruRU', 'Зелье призрачности', 'Принесите Гимлетте Наливайс 10 призрачных трюфелей.', 'В Ашране ты на каждом шагу рискуешь вляпаться в неприятности. Но не беспокойся, $n, у меня созрело идеальное решение. Это моя авторская разработка на базе популярного зелья невидимости. Но для его изготовления мне не хватает одного ингредиента: пещерных грибов. $B$BК счастью, здесь, в Ашране, они встречаются в изобилии.', '', '', '', '', '', 'Вернитесь к Гимлетте Наливайс в Крепость Преграды Ветров.', 19865);
