INSERT INTO `quest_template_locale` VALUES (36796, 'ruRU', 'Отмщение стаи', 'Убейте 18 саблеронов Кровавой Гривы.', 'Саблероны Кровавой Гривы напали на нас в Пристанище Воронов, когда мы проводили ритуал, и забрали с собой несколько наших посвященных. Они должны усвоить, что наша стая никогда не оставит столь гнусное деяние безнаказанным!$b$bЗа каждого нашего павшего сородича мы убьем одного из их племени!$b$bОтправляйся в их проклятое логово в Долине Кровавой Гривы и убей всех саблеронов, что попадутся тебе на глаза.', '', '', '', '', '', 'Вернитесь к Верховной Говорящей с воронами Крикке в Гнездо Говорящих с воронами.', 19865);
