INSERT INTO `quest_template_locale` VALUES (36830, 'ruRU', 'Нападение Совета Теней!', 'Отразите нападение Совета Теней на свой гарнизон.$B$B(Чтобы начать, поговорите еще раз с сержантом Краулером.)', 'Демоны наступают нам на пятки, командир. Молоко скисло. Старая ведьма на меня утром посмотрела как-то особенно злобно. И небо над головой какое-то... не такое.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36831, 'ruRU', 'Нападение Совета Теней!', 'Отразите нападение Совета Теней на свой гарнизон.$B$B(Чтобы начать, поговорите еще раз с сержантом Зловещей Утробой.)', 'Моя кровь словно медленно вскипает, командир. Как будто какой-то могучий чернокнижник стиснул мое сердце своей когтистой лапой. Я чую – Совет Теней приближается!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36832, 'ruRU', 'Зак с вами!', '', '', '', '', '', '', '', 'Поговорите с духом Костяного Зака в Гронн-каньоне, что в Горгронде.', 25549);
