INSERT INTO `quest_template_locale` VALUES (36843, 'ruRU', 'Они явились с неба', 'Найдите огранщика Барума рядом с Арууной в Таладоре.', 'Прошу тебя, помоги мне.$B$BМою родную Арууну разрушили араккоа. Они налетели со своих пиков и убили всех, кто пытался бежать. Моя семья... она не спаслась.$B$BМой брат Барум остался там, чтобы найти в царящей неразберихе свою дочь. Умоляю тебя, пожалуйста, отправляйся в Арууну и найди Барума.$B$BКроме него у меня совсем не осталось родных.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36846, 'ruRU', 'Награнд – Сокровище 082 – Дар духа', '', '', '', '', '', '', '', '', 19865);
