INSERT INTO `quest_template_locale` VALUES (36848, 'ruRU', 'Огрские путевые врата', 'Соберите 25 путевых камней огров и с их помощью активируйте огрские путевые врата на Дреноре.', 'На Дреноре есть шесть уникальных врат, которые огры-маги возвели в незапамятные времена. Мы обнаружили, что за все это время они ничуть не утратили своей волшебной силы.$b$bЕсли ты соберешь достаточно путевых камней огров, чтобы активировать любые из них, мы сможем создать односторонний портал, который перенесет тебя из гарнизона к этим вратам.', '', 'Некогда тут были древние торговые пути огров Дренора. Теперь путевые врата доступны и нам.', 'Огрские путевые врата', '', '', '', 25549);
