INSERT INTO `quest_template_locale` VALUES (36861, 'ruRU', 'Мастерская Паросвистов', 'Поговорите с Дунгаром Долгопивом, чтобы отправиться в Мастерскую Паросвистов.', 'Командир, сегодня утром прибыл курьер-гоблин.$B$BОн сказал, что явился из Мастерской Паросвистов – поселения на Пиках Арака. Там просят нашей помощи; говорят, у них там какая-то экологическая катастрофа.$B$BЗаручиться их доверием лишним не будет. Отправляйся туда и посмотри, какую помощь мы сможем предложить.$B$BЯ говорила с распорядителем полетов, он уже подготовил для тебя особый рейс.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36862, 'ruRU', 'Мастерская Паросвистов', 'Поговорите с Броном Небесным Рогом, чтобы отправиться в Мастерскую Паросвистов.', 'Командир, сегодня утром к нам прибыл курьер.$B$BОн сказал, что явился из Мастерской Паросвистов – гоблинского поселения на Пиках Арака. Там просят нашей помощи – курьер говорит, у них там какая-то экологическая катастрофа.$B$BНаши силы сейчас растянуты, но заручиться их доверием лишним не будет – так мы сможем получить ценного союзника.$B$BОтправляйся туда и посмотри, какую помощь мы можем предложить. Я говорила с распорядителем полетов, он уже подготовил для тебя особый рейс.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36863, 'ruRU', 'Сокровище: Боеприпасы Железной Орды', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36864, 'ruRU', 'По пояс в могиле', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36866, 'ruRU', 'Lower Blackrock Spires Reward Quest', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36867, 'ruRU', 'Lower Blackrock Spires Bonus Reward Quest', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36870, 'ruRU', 'Приманка для Ната', 'Поймайте чародейскую форель в Долине Призрачной Луны и принесите ее Сегуми.', 'Теперь, когда ты $gподнаторел:поднаторела; в рыбалке на Дреноре, нам, возможно, удастся уговорить присоединиться к нам самого Ната Пэгла.\n\nНо просто так он в такую даль не потащится. Нам нужно будет продемонстрировать ему, что здесь его ждут невероятные уловы. Отправляйся к местным водоемам в долине Призрачной Луны и налови чего-нибудь особенного. Не зря же ты столько времени $gпросидел:просидела; на Дреноре с удочкой.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36872, 'ruRU', 'Ошибка Остина', '', '', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36874, 'ruRU', 'Полководец Дренора', 'Убивайте игроков в режиме PvP, чтобы получить 20 переломанных костей, а затем поместите их на алтарь костей, чтобы получить трофей покорителя.', 'Дуротан...$B$B<Раза\'кул сплевывает.>$B$BОн прикрывается белым флагом мира, надеясь решить все конфликты с врагами словом.$b$bС теми, кто занял наши дома, а нас выгнал из земель наших предков.$B$BПокончить с дренеями и их новым альянсом трусов можно только одним способом – кровью.$B$BПрисоединяйся ко мне, и вместе мы покроем эти священные земли костями Альянса и заработаем награды, достойные полководца!$B$BВозвращайся, когда утолишь свою жажду крови.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36876, 'ruRU', 'Полководец Дренора', 'Убивайте игроков в режиме PvP, чтобы получить 20 переломанных костей, а затем поместите их на алтарь костей, чтобы получить трофей покорителя.', 'Экзархи не делают ничего по существу. Они заняты мелкими склоками, тогда как наши люди гибнут в своих домах от руки орочьего отродья. Если они не собираются опустить кулак неповиновения на головы наших врагов, я в стороне не останусь.$B$BЯ желаю вступить в Альянс и избавить мир от Орды. ВСЕЙ ОРДЫ. Будь то Орда Железная или какая другая.$B$BАлтарь костей, возле которого я стою, символизирует нашу честь в боях с Ордой. Сделай подношение и получи трофей покорителя, достойный твоей неутолимой жажды крови.$B$BУбей. Их. Всех.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36877, 'ruRU', 'Tracking Quest: Tormmok', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36878, 'ruRU', 'Сокровище: Свет Карабора', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36879, 'ruRU', 'Treasure: Dusty Lockbox', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36880, 'ruRU', 'Vignette: Sneevel', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36881, 'ruRU', 'Темный портал', 'Поговорите с верховным магом Кадгаром у подножия Темного портала в Выжженных землях.', '$n, ты ли это? Какая радость, что ты здесь. Уж мы-то найдем работу $gкаждому:каждой; |3-2($c), $gкоторый:которая; сюда заглядывает.$B$BЯ собираю самых сильных героев Азерота, чтобы пройти сквозь Темный портал и выступить против Железной Орды. Возможно, спасти Азерот удастся только так.$b$bНу, что? Ты с нами?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36882, 'ruRU', 'Возвращение великого рыбака', 'Вернитесь к Сегуми с доказательством встречи с Натом Пэглом.', 'Что за вид, ты говоришь? Чародейская форель? Я о такой рыбе даже не слышал, ясно дело, что и в руках не держал.\n\nЯ хочу разыскать побольше редких рыб, у меня к этому душа лежит! А если там, говоришь, клюет славно, я ни за какие шиши мимо не пройду. Держи страничку из моего дневника, чтобы тебе поверили, что ты меня $gнашел:нашла;, а позже встретимся в гарнизоне.', '', 'Редкие виды рыбы долины Призрачной Луны на Дреноре.', 'Чародейская форель', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (36884, 'ruRU', 'Морда воргена', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36885, 'ruRU', 'Ogre Waygate', '', '', '', '', '', '', '', '', 19865);
