INSERT INTO `quest_template_locale` VALUES (36887, 'ruRU', 'Spires - Vignette 029 - Hermit Palefur', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (36889, 'ruRU', 'Заклятый враг: охотник – или жертва?', 'Сожгите чучело злейшего врага в святилище гладиатора, а затем поговорите с Раза\'кулом.', 'Враги окружают нас и с каждым днем их численность возрастает. Пришло время нанести им сокрушительный удар.$B$BРядом со мной стоят чучела наших самых ненавистных противников. Ты принесешь им погибель, $n. Ты станешь их злейшим врагом, и они будут спасаться бегством, увидев тебя.$B$BВыбери на кого направить свой гнев и сожги чучело представителя расы, которую хочешь уничтожить. Поговори со мной, когда сделаешь свой выбор.', '', '', '', '', '', '', 25549);
