INSERT INTO `quest_template_locale` VALUES (37191, 'ruRU', 'Шанкецу, Пылающий клинок', 'Отнесите Пылающий клинок Шанкецу лейтенанту Торн в ваш гарнизон.', 'К оружию больно прикоснуться – оно обжигает. Драгоценный камень на рукояти как будто смотрит на вас в упор, словно бросая вам вызов.$B$BВозможно, кому-то из вашего гарнизона будет интересно взглянуть на это оружие.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37192, 'ruRU', 'Шанкецу, Пылающий клинок', 'Отнесите Пылающий клинок Шанкецу воеводе Зогу в ваш гарнизон.', 'К оружию больно прикоснуться – оно обжигает. Драгоценный камень на рукояти как будто смотрит на вас в упор, словно бросая вам вызов.$B$BВозможно, кому-то из вашего гарнизона будет интересно взглянуть на это оружие.', '', '', '', '', '', '', 25549);
