INSERT INTO `quest_template_locale` VALUES (37201, 'ruRU', 'Саймре Сияющий Клинок', 'Победите Саймре Сияющий Клинок в бою питомцев.', 'В ходе недавних раскопок были найдены любопытные артефакты, и мне бы хотелось испытать их. Я хочу узнать, как их применяли в древности. У тебя случайно нет кого-нибудь маленького и пушистого – такого, что может постоять за себя в бою?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37202, 'ruRU', 'Hemet Nesingwary Visitor Tracking Event', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (37203, 'ruRU', 'Эшли', 'Победите Эшли в бою питомцев.', 'Я не люблю, когда мои питомцы дерутся, но обожаю утешать их, когда все заканчивается.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37204, 'ruRU', 'Разжигая старый огонь', 'Доставьте сущность огня Фираге в Магнарок.', 'Я умираю. Мой огонь слабеет... скоро мой свет угаснет, растворится в пустоте.$b$bТы $gдолжен:должна; этому помешать. Принеси мне сущность огня. Дай мне прожить еще один день и тогда, клянусь, я превращу всех разрушителей в пепел.$b$bЯ отомщу за своих братьев и сестер. ', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37205, 'ruRU', 'Гаргра', 'Победите Гаргру в битве питомцев.', 'Мои волки должны тренироваться. Не желаешь бросить им вызов?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37206, 'ruRU', 'Тарр Ужасный', 'Победите Тарра Ужасного в битве питомцев.', 'Только Тарр – настоящий вождь! Приводи свою армию, тогда я тебе докажу.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37207, 'ruRU', 'Вешарр', 'Победите Вешарра в битве питомцев.', 'Мне было видение, что тот, кто выдрессировал своих питомцев, бросил мне вызов. Неужели сон станет явью?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37208, 'ruRU', 'Таралуна', 'Победите Таралуну в битве питомцев.', 'Я стараюсь обучать при помощи не смертельных поединков между питомцами. Хочешь ли ты учиться?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37209, 'ruRU', 'Холодная сталь, часть 2', 'Найдите железную автоматическую пушку в Депо Мрачных Путей.', 'Привет.$B$BЯ хотел поблагодарить тебя за все, что ты $gсделал:сделала; для меня. Эта пушка в моих руках – лучшее лекарство от всех невзгод. Но теперь...$B$B<Кишан смотрит вдаль, его лицо кривится.> У меня кончились боеприпасы.$B$BВидимо придется сидеть здесь и ждать, когда я сдохну.', '', '', '', '', '', '', 25549);
