INSERT INTO `quest_template_locale` VALUES (37296, 'ruRU', 'Дефицит ос', 'Убейте $1oa |4осу-вдову:осы-вдовы:ос-вдов;.', 'Жала! Эти проклятые осы жужжат круглые сутки, и их постоянная агрессия меня утомляет.$b$bЯ никак не отвечу на твое предложение, пока с этим неудобством не будет покончено.', '', '', '', '', '', '', 25549);
