INSERT INTO `quest_template_locale` VALUES (37318, 'ruRU', 'Мертвые не прощают...', 'Поместите 10 черепов древних рыколапов в котел гадателя на костях.', 'Много лет назад меня вместе с моей семьей убили на этом самом месте.$b$bСаблероны, которых ты видишь вокруг, – потомки племени, уничтожившего мою деревню. Долго же я ждал в этом забытом месте, чтобы увидеть, как саблеронов настигнет расплата за совершенные преступления.$b$bВождь рыколапов – гадатель на костях. С помощью останков мертвых он предсказывает будущее.$b$bСрази саблеронов на уступе Рыколапов и помести их черепа в котел гадателя на костях.$b$bИнтересно, предсказывал ли он им такое будущее?', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37319, 'ruRU', 'Особый заказ на работу ювелира: обручальные кольца', 'Изготовьте два блестящих кольца Черной Горы. Вторичные характеристики неважны.', 'Нас попросили изготовить пару обручальных колец. Клиенты настаивают на том, чтобы их $gсделал:сделала; именно ты.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37320, 'ruRU', 'Особый заказ на работу ювелира: качественное колье', 'Изготовьте шепчущее железное колье. Вторичные характеристики неважны.', 'Поступил заказ на изготовление качественного украшения. Клиентка хочет подарить его заклятому врагу, чтобы положить конец какому-то их конфликту. У нее нет особых пожеланий по поводу оформления, но, кажется, она что-то упоминала о колье.\n\nАх да, она попросила сделать украшение \"очень крепким\".', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37321, 'ruRU', 'Особый заказ на работу ювелира: желтый кристалл ярче золота', 'Изготовьте таладит критического удара.', 'Нам поручили изготовить золотой браслет, украшенный таладитовым кристаллом, \"который ярче золота\". Я справлюсь с работой по металлу, но не с кристаллом.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37322, 'ruRU', 'Последнее наставление пророка', 'Доставьте магический знак пророка к памятнику пророку Велену под Колизеем Света в Долине Призрачной Луны.', 'Этот скромный переливающийся кристалл содержит последние мысли великого пророка Велена. Он был создан незадолго до того, как пророк вступил в противостояние с Нер\'зулом.$b$bДоставь кристалл к памятнику пророку Велену под Колизеем Света около Карабора, чтобы услышать его последнее наставление.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37323, 'ruRU', 'Особый заказ на работу ювелира: голубой – цвет неба и моря', 'Изготовьте два таладита скорости.', 'Клиентка желает пару серебряных сережек, украшенных голубыми кристаллами под цвет ее глаз. Работа с металлом достаточно простая, но я не знаю, как сделать такой оттенок таладита.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37324, 'ruRU', 'Нет в наличии: руда Черной Горы', 'Соберите 20 кусков руды Черной Горы.', 'Браслеты, изготовленные по последним эскизам, продаются на ура, но у нас закончилась руда для их изготовления.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37325, 'ruRU', 'Нет в наличии: истинная железная руда', 'Соберите 20 кусков истинной железной руды.', 'Похоже, наша маленькая лавка обретает популярность. Для изготовления всех изделий мы используем исключительно истинную железную руду. Угадай, что произошло? Она закончилось!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37326, 'ruRU', 'Сдружиться с местными', 'Поговорите с темным ведуном Ириззаром около Гнездовья Терокк.', 'Если мы хотим дожить до завтра – нам необходимы союзники. Мы связались с одним араккоа-изгоем, но он отказался обсуждать союзы без предварительного разговора с тобой.$B$BОн представился темным ведуном Ириззаром. Тебе стоит поговорить с ним, командир.$B$BЕго можно найти к юго-западу от Гнездовья Терокк.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37327, 'ruRU', 'Сдружиться с местными', 'Поговорите с темным ведуном Ириззаром около Гнездовья Терокк.', 'Командир, я полагаю, что для безопасности этого аванпоста нужно заручиться поддержкой союзников. Мы связались с одним араккоа-изгоем, но он отказался что-либо обещать по поводу союза без предварительного разговора с тобой.$B$BОн представился темным ведуном Ириззаром. Можешь поговорить с ним, командир?$B$BЕго можно найти к юго-западу от Гнездовья Терокк.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37328, 'ruRU', 'Не здесь и не сейчас', 'Поговорите с бригадиром Горнеком в Павшем Топоре.', 'Скоро я отправлюсь к твоим соратникам, чтобы все подготовить.$B$BА сейчас убирайся. Оставь меня в покое.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37329, 'ruRU', 'Не здесь и не сейчас', 'Поговорите с лейтенантом Виллемом в Южном порту.', 'Скоро я отправлюсь к твоим соратникам, чтобы все подготовить.$B$BА сейчас убирайся. Оставь меня в покое.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37330, 'ruRU', 'Не здесь и не сейчас', 'Поговорите с бригадиром Горнеком в Павшем Топоре.', 'Скоро я отправлюсь к твоим соратникам, чтобы все подготовить.$B$BА сейчас убирайся. Оставь меня в покое.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37331, 'ruRU', 'Не здесь и не сейчас', 'Поговорите с лейтенантом Виллемом в Южном порту.', 'Скоро я отправлюсь к твоим соратникам, чтобы все подготовить.$B$BА сейчас убирайся. Оставь меня в покое.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37332, 'ruRU', 'Грибной сверток', 'Отнесите странный нарост рангари Шиире в Анклав рангари, что в Долине Призрачной Луны.', 'Тенеспоровый великан, который ты $gуничтожил:уничтожила;, казался неуязвимым для нестабильных спор. Возможно, странные наросты на его теле способствовали этой неуязвимости. Возьми с собой большой отвратительный нарост, чтобы передать его рангари для исследований.', '', '', '', '', '', '', 25549);
