INSERT INTO `quest_template_locale` VALUES (37511, 'ruRU', 'Диззи Искродвигс', 'Найдите Диззи Искродвигс.', 'Пока артефакты поступают, у меня все на мази.$b$bУ нас тут еще пара ребят из сообщества работает. Я бы сам их поискал, но здоровья мне это не прибавит.$b$bУ тебя вот, по виду, нет проблем с получением тумаков. Можешь найти Диззи?', '', '', '', '', '', 'Найдите Диззи Искродвигс на Разбитом берегу, что в Награнде.', 25549);
INSERT INTO `quest_template_locale` VALUES (37516, 'ruRU', 'Новости для Никси', 'Поговорите с Никси.', 'Похоже, Никси чертовски волнуют возможные потери прибыли от этих раскопок.$b$bКак увидишь ее, передай, что мы скоро вернемся.', '', '', '', '', '', 'Вернитесь к Никси в свой гарнизон на Хребте Ледяного Огня.', 25549);
INSERT INTO `quest_template_locale` VALUES (37517, 'ruRU', 'Новости для Никси', 'Поговорите с Никси', 'Похоже, Никси чертовски волнуют возможные потери прибыли от этих раскопок.$b$bКак увидишь ее, передай, что мы скоро вернемся.', '', '', '', '', '', 'Вернитесь к Никси в свой гарнизон в долине Призрачной Луны.', 25549);
