INSERT INTO `quest_template_locale` VALUES (37563, 'ruRU', 'Решимость Северных Волков', 'Выберите одного из соратников (Великую Мать Гейю, Кал\'гора Благородного или Локру), затем снова поговорите с Маккаром Камневязом.', 'Сегодня мы понесли тяжелую утрату, но слово Северного Волка тверже гранита, и наш договор остается в силе.$b$bНесколько бойцов моего клана вызвались присоединиться к твоему войску, чтобы вместе сражаться против общего врага.$b$bУвы, нас осталось очень мало, поэтому я могу отпустить лишь одного.$b$bКогда ты сделаешь свой выбор, сообщи мне.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37564, 'ruRU', 'Первый заказ для кузницы', 'Сделайте свой первый заказ для кузницы, затем заберите готовую продукцию.', 'Теперь у тебя есть кузница, и мы можем начать производство слитков истинной стали. Как только добудешь нужные материалы, поговори с моей помощницей, и мы начнем работу над первой партией.', '', '', '', '', '', 'Вернитесь к помощнику кузнеца.', 19865);
INSERT INTO `quest_template_locale` VALUES (37567, 'ruRU', 'Interact with Dudebro', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` VALUES (37568, 'ruRU', 'Первый заказ для алхимической лаборатории', 'Сделайте свой первый заказ для алхимической лаборатории, затем заберите готовую продукцию.', 'Теперь у тебя есть алхимическая лаборатория, и мы можем начать производство алхимических катализаторов. Как только добудешь нужные материалы, поговори с моей помощницей, и мы начнем работу над первой партией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37569, 'ruRU', 'Первый заказ для кузницы', 'Сделайте свой первый заказ для кузницы, затем заберите готовую продукцию.', 'Теперь у тебя есть кузница, и мы можем начать производство слитков истинной стали. Как только добудешь нужные материалы, поговори с моей помощницей, и мы начнем работу над первой партией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37570, 'ruRU', 'Первый заказ для павильона наложения чар', 'Сделайте свой первый заказ для павильона наложения чар, затем заберите готовую продукцию.', 'Теперь у тебя есть павильон наложения чар, и мы можем начать производство дренорской пыли. Как только добудешь нужные материалы, поговори с моей помощницей, и мы начнем работу над первой партией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37571, 'ruRU', 'Первый заказ для инженерной мастерской', 'Сделайте свой первый заказ для инженерной мастерской, затем заберите готовую продукцию.', 'Теперь у тебя есть инженерная мастерская, и мы можем начать производство частей механизмов. Как только добудешь нужные материалы, поговори с моей помощницей, и мы начнем работу над первой партией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37572, 'ruRU', 'Первый заказ для мастерской начертателя', 'Сделайте свой первый заказ для мастерской начертателя, затем заберите готовую продукцию.', 'Теперь у тебя есть мастерская начертателя, и мы можем начать производство красок сражений. Как только добудешь нужные материалы, поговори с моим помощником, и мы начнем работу над первой партией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37573, 'ruRU', 'Первый заказ для лавки самоцветов', 'Сделайте свой первый заказ для лавки самоцветов, затем заберите готовую продукцию.', 'Теперь у тебя есть лавка самоцветов, и мы можем начать производство таладитовых кристаллов. Как только добудешь нужные материалы, поговори с моим помощником, и мы начнем работу над первой партией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37574, 'ruRU', 'Первый заказ для кожевни', 'Сделайте свой первый заказ для кожевни, затем заберите готовую продукцию.', 'Теперь у тебя есть кожевня, и мы можем начать производство блестящей кожи. Как только добудешь нужные материалы, поговори с моей помощницей, и мы начнем работу над первой партией.', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37575, 'ruRU', 'Первый заказ для швейной лавки', 'Сделайте свой первый заказ для швейной лавки, затем заберите готовую продукцию.', 'Теперь у тебя есть швейная лавка, и мы можем начать производство волшебной ткани. Как только добудешь нужные материалы, поговори с моей помощницей, и мы начнем работу над первой партией.', '', '', '', '', '', '', 25549);
