INSERT INTO `quest_template_locale` VALUES (37627, 'ruRU', 'Атака на Разбитый берег', 'Убейте как можно больше орков из клана Призрачной Луны и их приспешников из Бездны.', '[PH]Командир! Ты совсем чуть-чуть $Gразминулся:разминулась; с группой рангари, принесшей дурные вести. У Крепости Страданий замечены орки из клана Призрачной Луны. Разведчики сообщают про странные ритуалы и порождения чистой тьмы. Должно быть, эти орки пытаются призвать себе новых приспешников из Бездны!$B$BЕсли мы не вмешаемся, то можем лишиться всего, что завоевали в Долине Призрачной Луны!', '', '', '', '', '', '', 25549);
INSERT INTO `quest_template_locale` VALUES (37628, 'ruRU', 'Атака на Разбитый берег', 'Убейте как можно больше орков из клана Призрачной Луны и их приспешников из Бездны.', '[PH]Командир! Ты совсем чуть-чуть $Gразминулся:разминулась; с группой рангари, принесшей дурные вести. У Крепости Страданий замечены орки из клана Призрачной Луны. Разведчики сообщают про странные ритуалы и порождения чистой тьмы. Должно быть, эти орки пытаются призвать себе новых приспешников из Бездны!$B$BЕсли мы не вмешаемся, то можем лишиться всего, что завоевали в Долине Призрачной Луны!', '', '', '', '', '', '', 25549);
